@import url('https://fonts.googleapis.com/css2?family=Source+Sans+3:ital,wght@0,500;1,500&display=swap');

body,
.mw-body h3,
.mw-body h1,
.mw-body .mw-heading1,
.mw-body-content h1,
.mw-body-content .mw-heading1,
.mw-body-content h2,
.mw-body-content h3,
.mw-body-content .mw-heading2 { font-family: "Source Sans 3", sans-serif !important}

html {
  -webkit-box-sizing: border-box;
       box-sizing: border-box;
}

*,
*::before,
*::after {
  -webkit-box-sizing: inherit;
      box-sizing: inherit;
}


.blackoutline {
	-webkit-text-stroke: 4px black;
    paint-order: stroke fill;
}

.gradient {
	background-clip: text !important;
    color: transparent !important;
}

.fakehref, .fakehref a, .fakehref:hover, .fakehref a:hover {
	color:white !important;
	text-decoration: none !important;
	padding: 0 0 0 0 !important;
	background-image: none !important;
	margin:0 0 0 0 !important;
}

.glass {
	backdrop-filter: blur(5px) saturate(2);
    background: #ffffff26;
    border: 1px solid #ffffff12;
}

.onhover {
	transition: all 0.1s ease;
}

.onhover:hover {
	transform: translateY(-2px);
    box-shadow: 0px 4px 4px 0px #00000087;
}

