.infobox img {
	object-fit: cover;
}

/* Wrap tabs instead of creating an endless horizontal scroll */
.tabber__tabs {
    flex-wrap: wrap;
}

/* Special tabber styles for infoboxes */
@media (max-width: 720px) {
	.mw-parser-output .infobox {
		width: calc(100% - 10px);
		float: none;
		margin-left: 0;
		margin-bottom: 1em;
	}
}

.infobox div:not(.infobox-img) > .tabber {
	margin: -7px;
	margin-top: 5px;

	.tabber__tabs {
		background-color: #0000004f;
		overflow: visible;
	}

	--tabber-border-color-base: #3d3e40;
}

.infobox .tabber__tab {
	flex-grow: 1;
}

/* Clear infobox before Change History section */
h2:has(#Change_History) {
	clear: right;
}

/* Custom frames */
.frame {
    padding: 0 15px 15px;
    border-radius: 10px;
    border: solid rgba(255, 255, 255, 0.05) 4px;
    margin-bottom: 15px;
}

.frame-noborder {
	padding: 1em;
	border-radius: 10px;
	border: 1px solid #2e2e35;
	box-shadow: 0 4px 6px rgba(0,0,0,0.2);
	margin: 1.1em 0 1.1em;
    background: var(--theme-page-background-color);

	.heading2 {
		background: rgba(0, 0, 0, 0.1);
		line-height: 1;
		margin: 0.5em -1em 0.7em;

		.main {
			display: inline-block;
			margin: 0 1.5em;
			padding: 0 0.5em;
			background: var(--theme-page-background-color)!important;
		}
	}

	h4 {
		font-weight:bold;
		font-size: 1.5em;
		margin:0;
	}

	.box {
		background: rgba(0, 0, 0, 0.1);
    	padding: 0.4em;
    	padding-left: 0.5em;
		margin: 1em 0;
		border-radius: 3px;

		.title {
			display: inline-block;
			font-weight: 500;
    		font-size: 1.1em;
    		margin-bottom: 0.5em
		}
	}

	.quote {
		background-image: linear-gradient(to right, rgba(0,0,0,0.1), rgba(0,0,0,0));
    	color: #E1E1E1;
    	font-style: italic;
    	padding: 0.3em;
    	padding-left: 0.5em;
		margin: 1em 0;
		border-radius: 3px;
	}
}

.frame .heading, 
.frame-noborder .heading {
	display: block;
	font-size:20px;
	font-weight: bold;
	text-align: center;
	background-color: rgba(0,0,0,0.2);
	padding: 3px; margin-bottom: 10px;
	border-radius: 2px;
}

.frame .heading {
	margin-left: -3px;
	margin-right: -3px;
}

.frame hr, .frame-noborder hr {
	border: 1px solid rgba(0, 0, 0, 0.2);
}
.frame h4, .frame h3 {
	margin: 0.6em 0 0.6em 0;
}

.infobox-img .tabber__header {
	margin-bottom: 5px;
}

.item-icon:has(a.new) {
	display: none;
}

