#mw-customcollapsible-ToggleSpoilers:not(.mw-collapsed) {
	animation: spoilerReveal .3s ease-out;
}

@keyframes spoilerReveal {
	from { opacity: 0; transform: translateY(-8px); }
	to   { opacity: 1; transform: translateY(0); }
}

#mw-customcollapsible-ToggleSpoilers {
	transition: opacity .3s ease, transform .3s ease, display .3s allow-discrete;
	opacity: 1;
}

#mw-customcollapsible-ToggleSpoilers.mw-collapsed {
	opacity: 0;
	transform: translateY(8px);
}

.spoiler-toggle {
	transition: filter .15s ease, transform .1s ease;
}

.spoiler-toggle:hover { filter: brightness(1.1); }
.spoiler-toggle:active { transform: scale(.97); }

