-- <pre>
--------------------------------------------------------------------------------
-- Allows wikis to locally override `/config` subpages of modules.
--
-- @script config
-- @alias p
-- @release experimental
-- @require [[Module:No globals]]
-- @require [[Module:TableTools]]
-- @author [[User:ExE Boss]]
-- @see [[Module:I18n]] - Inspired the way in which the @{Config} class works.
-- This module is licensed under CC-BY-SA.
--------------------------------------------------------------------------------

--require('Module:No globals');

local libraryUtil = require('libraryUtil');
local checkType = libraryUtil.checkType;
local checkTypeMulti = libraryUtil.checkTypeMulti;
local checkTypeForNamedArg = libraryUtil.checkTypeForNamedArg;

local tableTools = require('Module:TableTools');

local p = {};

--[[
-- @function p._substArgsInMsg
-- @param {string} msg
-- @param {table} args
--]]
local function substArgsInMsg(msg, args)
	checkType('substArgsInMsg', 1, msg, 'string');
	checkType('substArgsInMsg', 2, args, 'table');

	for i, value in tableTools.sparseIpairs(args) do
		msg = string.gsub(msg, '%$' .. tostring(i), tostring(value));
	end
	return msg;
end
p._substArgsInMsg = substArgsInMsg;

--[[
-- Configuration datastore class
-- @type Config
--]]
local Config = {};
Config.__index = Config;

--[[
-- Datastore option getter.
--
-- This method returns values from the datastore corresponding to a `key`.
--
-- If the value is a string, then these values may have `$n` parameters, which
-- can be replaced by optional argument strings supplied by the `getValue` call.
--
-- @function Config:getValue
-- @param {string|table} option Config query or string key to return from the datastore.
-- @param {string} option.key String key to return from the datastore.
-- @param[opt] {table} option.args Arguments to substitute into the value (`$n`).
-- @param[opt] {string} ... Arguments to substitute into the value (`$n`).
-- @return {nil|boolean|string|number|table}
--]]
function Config:getValue(option, ...)
	checkTypeMulti('Config:getValue', 1, option, { 'table', 'string' });

	local key;
	local args;

	if (type(option) == 'table') then
		key = option.key;
		checkTypeForNamedArg('Config:getValue', 'key', key, 'string');

		args = option.args;
		checkTypeForNamedArg('Config:getValue', 'args', args, 'table', true);
	else -- type(option) == 'string'
		key = option;
		args = select('#', ...) > 0 and { ... } or nil;
	end

	-- value fetching
	local value;
	for _, data in ipairs(self._data) do
		value = data[key];
		if (value ~= nil) then
			break;
		end
	end

	if (type(value) == 'string' and args) then
		value = substArgsInMsg(value, args);
	end

	return value;
end

--[[
-- Loads the configuration from the global `"Dev:" .. source .. "/config"` configuration page
-- with overrides from the local `"Module:" .. source .. "/config"` configuration page.
--
-- @function p.loadConfig
-- @param {string} source
-- @return {Config}
--]]
function p.loadConfig(source)
	if (source == '') then
		source = nil
	end
	checkType('loadConfig', 1, source, 'string');

	local cfg = {};
	cfg._data = {};
	setmetatable(cfg, Config);

	source = string.gsub(source, '^.', mw.ustring.upper);
	local hasNS = mw.ustring.find(source, ':');
	if (not hasNS) then
		source = source .. '/config';
		source = 'Module:' .. source;
	end

	cfg._data[#cfg._data + 1] = mw.loadData(source);
	return cfg;
end

--[[
-- Exports classes for testing
--
-- @function p._exportClasses
-- @private
-- @return {table}
--]]
function p._exportClasses()
	return {
		Config = Config,
	};
end

return p;
-- </pre>

.hatnote {
    border-left: 3px solid #008eff;
    padding: 3px 10px;
    border-radius: 3px;
    background: linear-gradient(145deg, rgba(0, 142, 255, 0.15) 0%, rgba(0, 142, 255, 0) 100%);
    margin: 5px 0;
}

.mbox.subjective-severity-2                                                   { --mbox-theme-color: rgba(255, 50, 50) }
.mbox.removed, .mbox.delete, .mbox.subjective-severity-4                                  { --mbox-theme-color: rgba(255, 50, 50) }
.mbox.community                                                                           { --mbox-theme-color: rgba(255, 214, 120) }
.mbox.stub																				  { --mbox-theme-color: rgba(255, 255, 119) }
.mbox.sandbox, .mbox.subjective-severity-0                                                { --mbox-theme-color: rgba(50, 225, 100) }
.mbox.cleanup, .mbox-underconstruction, .mbox.subjective-severity-3                       { --mbox-theme-color: rgba(255, 150, 50) }
.mbox.upcoming, .mbox.placeholderimage, .mbox.disambiguation, .mbox.subjective-severity-1 { --mbox-theme-color: rgba(50, 200, 255) }
.mbox.lua, .mbox.css                                                                      { --mbox-theme-color: rgba(40, 100, 200) }
.mbox.premium                                                                             { --mbox-theme-color: rgba(183, 162, 104) }

.mbox {
    display: flex;
    position: relative;
    border: 1px solid var(--mbox-theme-color);
/*     border-left-width: 8px; */
    border-left-color: var(--mbox-theme-color);
    border-radius: 3px;
    margin-bottom: 5px;
    min-height: 32px;
    border-width: 1px 1px 1px 3px;
	background-color: rgb(from var(--mbox-theme-color) r g b / 0.1);
}

.mbox.subjective {
    border-style: dashed;
    border-left-width: 1px;
    font-size: 14px;
}

body.mediawiki .mbox a:not(.new),
body.mediawiki .mbox a:not(.new):hover {
	color: var(--mbox-theme-color);
	background-image: none;
	padding-right: 0;
	font-weight: 600;
}

.mbox__content {
    display: table;
    box-sizing: border-box;
    width: 100%;
    padding: 8px 15px;
}

.mbox__content__wrapper {
    display: table-cell;
    vertical-align: middle;
}

.mbox__content__header {
    display: block;
    font-weight: bold;
}

.mbox__content__text {
    display: block;
	padding-right: 10px;
}

.mbox__close {
    position: absolute;
    right: 0;
    top: 0;
    padding: 2px 7px;
    font-weight: bold;
    font-size: 16px;
    color: #bbb;
    cursor: pointer;
    transition: all .15s ease-in;
}

.mbox__content__image {
    display: table-cell;
    width: 40px;
    height: 100%;
    text-align: center;
    vertical-align: middle;
    padding-right: 15px;
}

.mbox__content__text__comment {
    font-size: small;
}

