/* ===== Unknown rarity ===== */

.rarity-unknown {
  color: inherit;
}

.rarity {
  font-weight: bold;
}

/* ===== Normal RNG ===== */

.rarity-rng-common {
  color: #FFFFFF;
}

.rarity-rng-uncommon {
  color: #AEFF7C;
}

.rarity-rng-rare {
  color: #80F2FF;
}

.rarity-rng-epic {
  color: #E49EFF;
}

.rarity-rng-radical {
  color: #FF9AEC;
}

.rarity-rng-legendary {
  color: #FFC260;
}

.rarity-rng-mythic {
  color: #FF5465;
}

.rarity-rng-super {
  color: #65FF6A;
}

.rarity-rng-ultra {
  color: #F238FF;
}

.rarity-rng-lucky {
  color: #38C865;
}

.rarity-rng-binary {
  color: #00FF00;
}

.rarity-rng-rgb .rgb-r {
  color: #FF0000;
}

.rarity-rng-rgb .rgb-g {
  color: #00FF00;
}

.rarity-rng-rgb .rgb-b {
  color: #0000FF;
}

/* ===== Animated RNG ===== */

.rarity-rng-ethereal {
  animation: rarity-ethereal-text 2.5s linear infinite;
}

.rarity-rng-exotic {
  animation: rarity-exotic-text 2s linear infinite;
}

.rarity-rng-godlyplus {
  animation: rarity-godly-text 1.5s linear infinite;
}

@keyframes rarity-ethereal-text {
  0% {
    color: #555555;
  }

  25% {
    color: #AAAAAA;
  }

  50% {
    color: #FFFFFF;
  }

  75% {
    color: #808080;
  }

  100% {
    color: #555555;
  }
}

@keyframes rarity-exotic-text {
  0% {
    color: #80FFD9;
  }

  33% {
    color: #FFFFFF;
  }

  66% {
    color: #00FFAA;
  }

  100% {
    color: #80FFD9;
  }
}

@keyframes rarity-godly-text {
  0% {
    color: #FF1D1D;
  }

  16% {
    color: #FF9C23;
  }

  32% {
    color: #FFFF00;
  }

  48% {
    color: #65FF6A;
  }

  64% {
    color: #80F2FF;
  }

  80% {
    color: #F238FF;
  }

  100% {
    color: #FF1D1D;
  }
}

