}

.entry-card-name a {
  color: inherit;
}

.entry-name-rarity-common,
.entry-name-rarity-common a {
  animation: fish-common-name 2s ease-in-out infinite;
}

@keyframes fish-common-name {
  0% { color: #A8B1B6; }
  50% { color: #7F8C99; }
  100% { color: #A8B1B6; }
}

