  display: flex;
  flex-direction: column;
  gap: 18px;
}

.entry-side-pill {
  width: 170px;
  height: 135px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  text-align: center;
