.entry-content {
  position: relative;
  overflow: hidden;

  flex: 1;
  min-height: 430px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  padding: 24px;
  box-sizing: border-box;
}

.entry-content-title {
  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  margin-bottom: 20px;
}

.entries-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}
.entry-card {
  position: relative;

  width: 130px;
  height: 150px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 18px;

  text-align: center;
  box-sizing: border-box;
  padding: 10px;
  overflow: visible;
}

.entry-card:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-card img {
  max-width: 100px;
  max-height: 100px;
  width: auto;
  height: auto;
}

.entry-card-name {
  margin-top: -30px;
  font-size: 16px;
  font-weight: bold;
