/* ===== Responsive layout ===== */

.entry-ui {
  width: 100%;
  max-width: 1075px;
  box-sizing: border-box;
}

.entry-choice-box,
.entry-library {
  width: 100%;
  max-width: 1075px;
  box-sizing: border-box;
}

.entry-choice-box {
  height: auto;
  min-height: 500px;
  flex-wrap: wrap;
}

/* Laptop / tablet */
@media screen and (max-width: 900px) {
  .entry-choice-box {
    padding: 18px;
    gap: 18px;
  }

  .entry-choice-pill {
    width: 260px;
    height: 250px;
    flex: 0 0 260px;
  }

  .entry-choice-pill img {
    max-width: 170px;
    max-height: 170px;
  }

  .entry-choice-text {
    font-size: 38px;
  }

  .entry-library {
    flex-direction: column;
    padding: 18px;
    gap: 18px;
  }

  .entry-side {
    width: 100%;
    flex: none;
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: center;
  }

  .entry-side-pill {
    width: 150px;
    height: 115px;
    font-size: 20px;
  }

  .entry-content {
    width: 100%;
    min-height: 500px;
  }

  .entry-content-title {
    font-size: 36px;
    text-align: center;
  }

  .entries-grid {
    justify-content: center;
  }
}

/* Phone */
@media screen and (max-width: 600px) {
  .entry-choice-box {
    min-height: 0;
    padding: 12px;
    gap: 14px;
  }

  .entry-choice-pill {
    width: 100%;
    height: 190px;
    flex: 0 0 100%;
    border-radius: 18px;
  }

  .entry-choice-pill img {
    max-width: 120px;
    max-height: 120px;
  }

  .entry-choice-text {
    font-size: 32px;
  }

  .entry-library {
    padding: 12px;
    gap: 12px;
    border-radius: 18px;
  }

  .entry-side {
    gap: 10px;
  }

  .entry-side-pill {
    width: 31%;
    min-width: 90px;
    height: 90px;
    font-size: 14px;
    border-width: 3px;
    border-radius: 16px;
  }

  .entry-side-pill img {
    max-width: 48px;
    max-height: 48px;
  }

  .entry-content {
    padding: 14px;
    min-height: 560px;
    border-radius: 18px;
  }

  .entry-content-title {
    font-size: 30px;
    margin-bottom: 14px;
    text-align: center;
  }

  .entry-subtabs {
    justify-content: center;
    flex-wrap: wrap;
  }

  .entry-subtab {
    font-size: 18px;
    padding: 7px 14px;
  }

  .entry-card {
    width: 110px;
    height: 135px;
    padding: 8px;
  }

  .entry-card img {
    max-width: 82px;
    max-height: 82px;
  }

  .entry-card-name {
    margin-top: -15px;
    font-size: 14px;
  }

  .entry-detail-panel {
    padding: 14px;
    overflow: auto;
  }

  .entry-detail-top {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .entry-detail-image {
    text-align: center;
  }

  .entry-detail-image img {
    max-width: 110px;
    max-height: 110px;
  }

  .entry-detail-name {
    font-size: 30px;
  }

  .entry-detail-back {
    text-align: center;
  }

  .entry-detail-body {
    font-size: 16px;
    text-align: center;
  }
}

/* Very small phones */
@media screen and (max-width: 380px) {
  .entry-choice-pill {
    height: 165px;
  }

  .entry-choice-pill img {
    max-width: 95px;
    max-height: 95px;
  }

  .entry-choice-text {
    font-size: 26px;
  }

  .entry-side-pill {
    width: 100%;
    height: 75px;
    flex-direction: row;
    font-size: 16px;
  }

  .entry-side-pill img {
    max-width: 42px;
    max-height: 42px;
  }

  .entry-card {
    width: 95px;
    height: 125px;
  }

  .entry-card img {
    max-width: 72px;
    max-height: 72px;
  }

  .entry-card-name {
    font-size: 12px;
  }

  .entry-detail-name {
    font-size: 24px;
  }

  .entry-detail-body {
    font-size: 14px;
  }
}

.entry-choice-box {
  display: flex;
  flex-direction: row;
  flex-wrap: nowrap;
  justify-content: center;
  align-items: center;
  gap: 28px;

  width: 1075px;
  height: 500px;
  padding: 24px;

  background: #07122b;
