/* ===== Responsive layout ===== */

.entry-ui {
  width: 100%;
  max-width: 1075px;
  box-sizing: border-box;
}

.entry-choice-box,
.entry-library {
  width: 100%;
  max-width: 1075px;
  box-sizing: border-box;
}

.entry-choice-box {
  height: auto;
  min-height: 500px;
  flex-wrap: wrap;
}

/* Laptop / tablet */
@media screen and (max-width: 900px) {
  .entry-choice-box {
    padding: 18px;
    gap: 18px;
  }

  .entry-choice-pill {
    width: 260px;
    height: 250px;
    flex: 0 0 260px;
  }

  .entry-choice-pill img {
    max-width: 170px;
    max-height: 170px;
  }

  .entry-choice-text {
    font-size: 38px;
  }

  .entry-library {
    flex-direction: column;
    padding: 18px;
    gap: 18px;
  }

  .entry-side {
    width: 100%;
    flex: none;
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: center;
  }

  .entry-side-pill {
    width: 150px;
    height: 115px;
    font-size: 20px;
  }

  .entry-content {
    width: 100%;
    min-height: 500px;
  }

  .entry-content-title {
    font-size: 36px;
    text-align: center;
  }

  .entries-grid {
    justify-content: center;
  }
}

/* Phone */
@media screen and (max-width: 600px) {
  .entry-choice-box {
    min-height: 0;
    padding: 12px;
    gap: 14px;
  }

  .entry-choice-pill {
    width: 100%;
    height: 190px;
    flex: 0 0 100%;
    border-radius: 18px;
  }

  .entry-choice-pill img {
    max-width: 120px;
    max-height: 120px;
  }

  .entry-choice-text {
    font-size: 32px;
  }

  .entry-library {
    padding: 12px;
