#detail-white-bass:target ~ .entry-ui .entry-detail-white-bass,
#detail-clownfish:target ~ .entry-ui .entry-detail-clownfish,
#detail-pike:target ~ .entry-ui .entry-detail-pike,
#detail-red-emperor:target ~ .entry-ui .entry-detail-red-emperor,
#detail-swordfish:target ~ .entry-ui .entry-detail-swordfish,
#detail-zebrasoma-xanthurum:target ~ .entry-ui .entry-detail-zebrasoma-xanthurum,
#detail-ash:target ~ .entry-ui .entry-detail-ash,
#detail-ball:target ~ .entry-ui .entry-detail-ball,
#detail-parmesan:target ~ .entry-ui .entry-detail-parmesan,
#detail-teddy-bear:target ~ .entry-ui .entry-detail-teddy-bear,
#detail-dynamite:target ~ .entry-ui .entry-detail-dynamite,
#detail-worm:target ~ .entry-ui .entry-detail-worm,
#detail-moss:target ~ .entry-ui .entry-detail-moss {
  display: block;
}

#detail-fishing-rod:target ~ .entry-ui .entry-detail-fishing-rod,
#detail-advanced-fishing-rod:target ~ .entry-ui .entry-detail-advanced-fishing-rod,
#detail-momentum-fishing-rod:target ~ .entry-ui .entry-detail-momentum-fishing-rod,
#detail-pistol:target ~ .entry-ui .entry-detail-pistol {
  display: block;
}

#detail-strength:target ~ .entry-ui .entry-detail-strength,
#detail-strength-plus:target ~ .entry-ui .entry-detail-strength-plus,
#detail-momentum:target ~ .entry-ui .entry-detail-momentum,
#detail-momentum-plus:target ~ .entry-ui .entry-detail-momentum-plus,
#detail-ultra:target ~ .entry-ui .entry-detail-ultra,
#detail-fortune:target ~ .entry-ui .entry-detail-fortune,
#detail-less-backfire:target ~ .entry-ui .entry-detail-less-backfire,
#detail-sharpshooter:target ~ .entry-ui .entry-detail-sharpshooter {
  display: block;
}
/* ===== Responsive layout ===== */

.entry-ui {
  width: 100%;
  max-width: 1075px;
  box-sizing: border-box;
}

.entry-choice-box,
.entry-library {
  width: 100%;
  max-width: 1075px;
  box-sizing: border-box;
}

.entry-choice-box {
  height: auto;
  min-height: 500px;
  flex-wrap: wrap;
}

/* Laptop / tablet */
@media screen and (max-width: 900px) {
  .entry-choice-box {
    padding: 18px;
    gap: 18px;
  }

  .entry-choice-pill {
    width: 260px;
    height: 250px;
    flex: 0 0 260px;
  }

  .entry-choice-pill img {
    max-width: 170px;
    max-height: 170px;
  }

  .entry-choice-text {
    font-size: 38px;
  }

  .entry-library {
    flex-direction: column;
    padding: 18px;
    gap: 18px;
  }

  .entry-side {
    width: 100%;
    flex: none;
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: center;
  }

  .entry-side-pill {
    width: 150px;
    height: 115px;
    font-size: 20px;
  }

  .entry-content {
    width: 100%;
    min-height: 500px;
  }

  .entry-content-title {
    font-size: 36px;
    text-align: center;
  }

  .entries-grid {
    justify-content: center;
  }
}

/* Phone */
@media screen and (max-width: 600px) {
  .entry-choice-box {
    min-height: 0;
    padding: 12px;
    gap: 14px;
  }

  .entry-choice-pill {
    width: 100%;
    height: 190px;
    flex: 0 0 100%;
    border-radius: 18px;
  }

  .entry-choice-pill img {
    max-width: 120px;
    max-height: 120px;
  }

  .entry-choice-text {
    font-size: 32px;
  }

  .entry-library {
    padding: 12px;
    gap: 12px;
    border-radius: 18px;
  }

  .entry-side {
    gap: 10px;
  }

  .entry-side-pill {
    width: 31%;
    min-width: 90px;
    height: 90px;
    font-size: 14px;
    border-width: 3px;
    border-radius: 16px;
  }

  .entry-side-pill img {
    max-width: 48px;
    max-height: 48px;
  }

  .entry-content {
    padding: 14px;
    min-height: 560px;
    border-radius: 18px;
  }

  .entry-content-title {
    font-size: 30px;
    margin-bottom: 14px;
    text-align: center;
  }

  .entry-subtabs {
    justify-content: center;
    flex-wrap: wrap;
  }

  .entry-subtab {
    font-size: 18px;
    padding: 7px 14px;
  }

  .entry-card {
    width: 110px;
    height: 135px;
    padding: 8px;
  }

  .entry-card img {
    max-width: 82px;
    max-height: 82px;
  }

  .entry-card-name {
    margin-top: -15px;
    font-size: 14px;
  }

  .entry-detail-panel {
    padding: 14px;
    overflow: auto;
  }

  .entry-detail-top {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .entry-detail-image {
    text-align: center;
  }

  .entry-detail-image img {
    max-width: 110px;
    max-height: 110px;
  }

  .entry-detail-name {
    font-size: 30px;
  }

  .entry-detail-back {
    text-align: center;
  }

  .entry-detail-body {
    font-size: 16px;
    text-align: center;
  }
}

/* Very small phones */
@media screen and (max-width: 380px) {
  .entry-choice-pill {
    height: 165px;
  }

  .entry-choice-pill img {
    max-width: 95px;
    max-height: 95px;
  }

  .entry-choice-text {
    font-size: 26px;
  }

  .entry-side-pill {
    width: 100%;
    height: 75px;
    flex-direction: row;
    font-size: 16px;
  }

  .entry-side-pill img {
    max-width: 42px;
    max-height: 42px;
  }

  .entry-card {
    width: 95px;
    height: 125px;
  }

  .entry-card img {
    max-width: 72px;
    max-height: 72px;
  }

  .entry-card-name {
    font-size: 12px;
  }

  .entry-detail-name {
    font-size: 24px;
  }

  .entry-detail-body {
    font-size: 14px;
  }
}
.entry-side-pill.entry-active,
.entry-subtab.entry-active {
  background: #10275a;
  border-color: #5aaeff;
}
.js-entry-open {
  cursor: pointer;
}

.entry-side-pill.entry-active,
.entry-subtab.entry-active {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-ui {
  width: 100%;
  max-width: 1075px;
  box-sizing: border-box;
}

.entry-choice-box {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: 28px;

  width: 100%;
  max-width: 1075px;
  height: auto;
  min-height: 500px;
  padding: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;
  box-sizing: border-box;
}

.entry-choice-pill {
  width: 320px;
  height: 300px;
  flex: 0 0 320px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 26px;

  text-align: center;
  box-sizing: border-box;
}

.entry-choice-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-choice-pill img {
  max-width: 220px;
  max-height: 220px;
  width: auto;
  height: auto;
}

.entry-choice-text {
  display: block;
  font-size: 50px;
  line-height: 1;
  color: #4f8cff;
  white-space: nowrap;
}

.entry-library {
  display: none;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;
  gap: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;
  box-sizing: border-box;
}

.entry-side {
  width: 190px;
  flex: 0 0 190px;

  display: flex;
  flex-direction: column;
  gap: 18px;
}

.entry-side-pill {
  width: 170px;
  height: 135px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  text-align: center;
  box-sizing: border-box;
  color: #4f8cff;
  font-weight: bold;
  font-size: 24px;
  line-height: 1;
}

.entry-side-pill img {
  max-width: 80px;
  max-height: 80px;
  width: auto;
  height: auto;
}

.entry-side-pill div {
  margin-top: 0;
}

.entry-side-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-content {
  position: relative;
  overflow: hidden;

  flex: 1;
  min-height: 430px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  padding: 24px;
  box-sizing: border-box;
}

.entry-content-title {
  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  margin-bottom: 20px;
}

.entry-subtabs {
  display: flex;
  gap: 12px;
  margin-bottom: 20px;
}

.entry-subtab {
  padding: 8px 18px;
  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 999px;
  font-size: 22px;
  font-weight: bold;
  color: #4f8cff;
}

.entry-subtab:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-subcontent {
  display: none;
}

.entries-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.entry-card {
  position: relative;

  width: 130px;
  height: 150px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 18px;

  text-align: center;
  box-sizing: border-box;
  padding: 10px;
  overflow: visible;
}

.entry-card:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-card img {
  max-width: 100px;
  max-height: 100px;
  width: auto;
  height: auto;
}

.entry-card-name {
  margin-top: -30px;
  font-size: 16px;
  font-weight: bold;
  line-height: 1;
}

.entry-card-items {
  border-color: #5aaeff;
}

.entry-card-tools {
  border-color: #69e8f4;
}

.entry-card-enchants {
  border-color: #9666ff;
}

.entry-detail-panel {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  z-index: 50;

  background: #0b0f17;
  border-radius: 20px;
  padding: 24px;
  box-sizing: border-box;
}

.entry-detail-top {
  display: grid;
  grid-template-columns: 160px 1fr 120px;
  align-items: center;
  gap: 20px;
}

.entry-detail-image {
  text-align: left;
}

.entry-detail-image img {
  max-width: 140px;
  max-height: 140px;
  width: auto;
  height: auto;
}

.entry-detail-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
}

.entry-detail-name {
  text-align: center;
  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
}

.entry-detail-rarity {
  text-align: center;
}

.entry-rarity-pill {
  display: inline-block;
  padding: 8px 16px;
  background: #0b0f17;
  border: 2px solid #222831;
  border-radius: 999px;
  font-weight: bold;
  line-height: 1;
}

.entry-detail-back {
  justify-self: end;

  display: inline-block;
  padding: 8px 14px;

  border-radius: 12px;
  background: #10275a;
  border: 2px solid #5aaeff;

  color: #ffffff;
  text-decoration: none;
  font-weight: bold;
  cursor: pointer;
}

.entry-detail-back:hover {
  background: #1f4388;
}

.entry-detail-body {
  margin-top: 28px;
  color: #ffffff;
  font-size: 18px;
  line-height: 1.4;
}

.js-entry-open {
  cursor: pointer;
}

.entry-side-pill.entry-active,
.entry-subtab.entry-active {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Rarity name animations ===== */

.entry-name-rarity-common {
  animation: fish-common-name 2s ease-in-out infinite;
}

@keyframes fish-common-name {
  0% { color: #A8B1B6; }
  50% { color: #7F8C99; }
  100% { color: #A8B1B6; }
}

.entry-name-rarity-uncommon {
  animation: fish-uncommon-name 2s ease-in-out infinite;
}

@keyframes fish-uncommon-name {
  0% { color: #67EC88; }
  50% { color: #63C138; }
  100% { color: #67EC88; }
}

.entry-name-rarity-rare {
  animation: fish-rare-name 2s ease-in-out infinite;
}

@keyframes fish-rare-name {
  0% { color: #4AD8FF; }
  50% { color: #3D93FC; }
  100% { color: #4AD8FF; }
}

.entry-name-rarity-epic {
  animation: fish-epic-name 2s ease-in-out infinite;
}

@keyframes fish-epic-name {
  0% { color: #7843FF; }
  50% { color: #7246A7; }
  100% { color: #7843FF; }
}

.entry-name-rarity-legendary {
  animation: fish-legendary-name 2s ease-in-out infinite;
}

@keyframes fish-legendary-name {
  0% { color: #FFE669; }
  50% { color: #FC932A; }
  100% { color: #FFE669; }
}

/* ===== Rarity border animations ===== */

.entry-card-rarity-none {
  border-color: #5aaeff;
}

.entry-card-rarity-common {
  animation: fish-common-border 2s ease-in-out infinite;
}

@keyframes fish-common-border {
  0% {
    border-color: #A8B1B6;
    box-shadow: 0 0 6px #A8B1B6;
  }
  50% {
    border-color: #7F8C99;
    box-shadow: 0 0 10px #7F8C99;
  }
  100% {
    border-color: #A8B1B6;
    box-shadow: 0 0 6px #A8B1B6;
  }
}

.entry-card-rarity-uncommon {
  animation: fish-uncommon-border 2s ease-in-out infinite;
}

@keyframes fish-uncommon-border {
  0% {
    border-color: #67EC88;
    box-shadow: 0 0 6px #67EC88;
  }
  50% {
    border-color: #63C138;
    box-shadow: 0 0 10px #63C138;
  }
  100% {
    border-color: #67EC88;
    box-shadow: 0 0 6px #67EC88;
  }
}

.entry-card-rarity-rare {
  animation: fish-rare-border 2s ease-in-out infinite;
}

@keyframes fish-rare-border {
  0% {
    border-color: #4AD8FF;
    box-shadow: 0 0 6px #4AD8FF;
  }
  50% {
    border-color: #3D93FC;
    box-shadow: 0 0 10px #3D93FC;
  }
  100% {
    border-color: #4AD8FF;
    box-shadow: 0 0 6px #4AD8FF;
  }
}

.entry-card-rarity-epic {
  animation: fish-epic-border 2s ease-in-out infinite;
}

@keyframes fish-epic-border {
  0% {
    border-color: #7843FF;
    box-shadow: 0 0 6px #7843FF;
  }
  50% {
    border-color: #7246A7;
    box-shadow: 0 0 10px #7246A7;
  }
  100% {
    border-color: #7843FF;
    box-shadow: 0 0 6px #7843FF;
  }
}

.entry-card-rarity-legendary {
  animation: fish-legendary-border 2s ease-in-out infinite;
}

@keyframes fish-legendary-border {
  0% {
    border-color: #FFE669;
    box-shadow: 0 0 6px #FFE669;
  }
  50% {
    border-color: #FC932A;
    box-shadow: 0 0 10px #FC932A;
  }
  100% {
    border-color: #FFE669;
    box-shadow: 0 0 6px #FFE669;
  }
}

