.entries-grid {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-content: flex-start;
  gap: 12px;
}

.entry-ui {
  width: 100%;
  max-width: 1075px;
  box-sizing: border-box;
}

.entry-choice-box {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: 28px;

  width: 100%;
  max-width: 1075px;
  height: auto;
  min-height: 500px;
  padding: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;
  box-sizing: border-box;
}

.entry-choice-pill {
  width: 320px;
  height: 300px;
  flex: 0 0 320px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 26px;

  text-align: center;
  box-sizing: border-box;
}

.entry-choice-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-choice-pill img {
  max-width: 220px;
  max-height: 220px;
  width: auto;
  height: auto;
}

.entry-choice-text {
  display: block;
  font-size: 50px;
  line-height: 1;
  color: #4f8cff;
  white-space: nowrap;
}

.entry-library {
  display: none;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;
  gap: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;
  box-sizing: border-box;
}

.entry-side {
  width: 190px;
  flex: 0 0 190px;

  display: flex;
  flex-direction: column;
  gap: 18px;

  align-self: stretch;
}

.entry-side-pill {
  width: 170px;
  flex: 1;
  min-height: 135px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  text-align: center;
  box-sizing: border-box;
  color: #4f8cff;
  font-weight: bold;
  font-size: 24px;
  line-height: 1;
}
.entry-side-pill img {
  max-width: 80px;
  max-height: 80px;
  width: auto;
  height: auto;
}

.entry-side-pill div {
  margin-top: 0;
}

.entry-side-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-content {
  position: relative;
  overflow: hidden;

  flex: 1;
  min-height: 430px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  padding: 24px;
  box-sizing: border-box;
}

.entry-content-title {
  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  margin-bottom: 20px;
}

.entry-subtabs {
  display: flex;
  gap: 12px;
  margin-bottom: 20px;
}

.entry-subtab {
  padding: 8px 18px;
  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 999px;
  font-size: 22px;
  font-weight: bold;
  color: #4f8cff;
}

.entry-subtab:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-subcontent {
  display: none;
}

.entries-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.entry-card {
  position: relative;

  width: 130px;
  height: 150px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 18px;

  text-align: center;
  box-sizing: border-box;
  padding: 10px;
  overflow: visible;
}

.entry-card:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-card img {
  max-width: 100px;
  max-height: 100px;
  width: auto;
  height: auto;
}

.entry-card-name {
  margin-top: -30px;
  font-size: 16px;
  font-weight: bold;
  line-height: 1;
}

.entry-card-items {
  border-color: #5aaeff;
}

.entry-card-tools {
  border-color: #69e8f4;
}

.entry-card-enchants {
  border-color: #9666ff;
}

.entry-detail-panel {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  z-index: 50;

  background: #0b0f17;
  border-radius: 20px;
  padding: 24px;
  box-sizing: border-box;
}

.entry-detail-top {
  display: grid;
  grid-template-columns: 160px 1fr 120px;
  align-items: center;
  gap: 20px;
}

.entry-detail-image {
  text-align: left;
}

.entry-detail-image img {
  max-width: 140px;
  max-height: 140px;
  width: auto;
  height: auto;
}

.entry-detail-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
}

.entry-detail-name {
  text-align: center;
  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
}

.entry-detail-rarity {
  text-align: center;
}

.entry-rarity-pill {
  display: inline-block;
  padding: 8px 16px;
  background: #0b0f17;
  border: 2px solid #222831;
  border-radius: 999px;
  font-weight: bold;
  line-height: 1;
}

.entry-detail-back {
  justify-self: end;

