  }

  .entry-side-pill img {
    max-width: 48px;
    max-height: 48px;
  }

  .entry-content {
    padding: 14px;
    min-height: 560px;
    border-radius: 18px;
  }

  .entry-content-title {
    font-size: 30px;
    margin-bottom: 14px;
    text-align: center;
  }

  .entry-subtabs {
    justify-content: center;
    flex-wrap: wrap;
  }

  .entry-subtab {
    font-size: 18px;
    padding: 7px 14px;
  }

  /*
   * All fish groups remain on one horizontal row.
   * The normal browser scrollbar is used on small screens.
   */
  .fish-area-menu {
    justify-content: flex-start;

    overflow-x: auto;
    overflow-y: hidden;

    gap: 10px;
    padding: 2px 2px 10px;
  }

  .fish-area-icon {
    flex: 0 0 105px;
    min-width: 105px;
    height: 125px;
    padding: 8px;
  }

  .fish-area-icon img {
    max-width: 65px;
    max-height: 65px;
  }

  .fish-area-name {
    font-size: 13px;
  }

  .fish-group-heading {
    gap: 10px;
  }

  .fish-group-title {
    font-size: 22px;
  }

  .fish-group-back {
    padding: 7px 12px;
    font-size: 14px;
  }

  .entry-card {
    width: 110px;
    height: 135px;
    padding: 8px;
  }

  .entry-card img {
    max-width: 82px;
    max-height: 82px;
  }

  .entry-card-name {
    margin-top: -15px;
    font-size: 14px;
  }

  .entry-detail-panel {
    padding: 14px;
    overflow: auto;
  }

  .entry-detail-top {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .entry-detail-image {
    text-align: center;
  }

  .entry-detail-image img {
    max-width: 110px;
    max-height: 110px;
  }

  .entry-detail-name {
    font-size: 30px;
  }

  .entry-detail-back {
    justify-self: center;
    text-align: center;
  }

  .entry-detail-body {
    font-size: 16px;
    text-align: center;
  }
}

/* ===== Very small phone layout ===== */

@media screen and (max-width: 380px) {
  .entry-choice-pill {
    height: 165px;
  }

  .entry-choice-pill img {
    max-width: 95px;
