/* ===== Selected fish group ===== */

.fish-group {
  display: none;
}

.fish-group-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 18px;
}

.fish-group-title {
