  border-color: #5aaeff;
}

.entry-card-rarity-common {
  animation: fish-common-border 2s ease-in-out infinite;
}

@keyframes fish-common-border {
  0% {
    border-color: #a8b1b6;
    box-shadow: 0 0 6px #a8b1b6;
  }

  50% {
    border-color: #7f8c99;
    box-shadow: 0 0 10px #7f8c99;
  }

  100% {
    border-color: #a8b1b6;
    box-shadow: 0 0 6px #a8b1b6;
  }
}

.entry-card-rarity-uncommon {
  animation: fish-uncommon-border 2s ease-in-out infinite;
}

@keyframes fish-uncommon-border {
  0% {
    border-color: #67ec88;
    box-shadow: 0 0 6px #67ec88;
  }

  50% {
    border-color: #63c138;
    box-shadow: 0 0 10px #63c138;
  }

  100% {
    border-color: #67ec88;
    box-shadow: 0 0 6px #67ec88;
  }
}

.entry-card-rarity-rare {
  animation: fish-rare-border 2s ease-in-out infinite;
}

@keyframes fish-rare-border {
  0% {
    border-color: #4ad8ff;
    box-shadow: 0 0 6px #4ad8ff;
  }

  50% {
    border-color: #3d93fc;
    box-shadow: 0 0 10px #3d93fc;
  }

  100% {
    border-color: #4ad8ff;
    box-shadow: 0 0 6px #4ad8ff;
  }
}

.entry-card-rarity-epic {
  animation: fish-epic-border 2s ease-in-out infinite;
}

@keyframes fish-epic-border {
  0% {
    border-color: #7843ff;
    box-shadow: 0 0 6px #7843ff;
  }

  50% {
    border-color: #7246a7;
    box-shadow: 0 0 10px #7246a7;
  }

  100% {
    border-color: #7843ff;
    box-shadow: 0 0 6px #7843ff;
  }
}

.entry-card-rarity-legendary {
  animation: fish-legendary-border 2s ease-in-out infinite;
}

@keyframes fish-legendary-border {
  0% {
    border-color: #ffe669;
    box-shadow: 0 0 6px #ffe669;
  }

  50% {
    border-color: #fc932a;
    box-shadow: 0 0 10px #fc932a;
  }

  100% {
    border-color: #ffe669;
    box-shadow: 0 0 6px #ffe669;
  }
}

/* ===== Tablet layout ===== */

@media screen and (max-width: 900px) {
  .entry-choice-box {
    padding: 18px;
    gap: 18px;
  }

  .entry-choice-pill {
    width: 260px;
    height: 250px;
    flex: 0 0 260px;
  }

  .entry-choice-pill img {
    max-width: 170px;
    max-height: 170px;
  }

  .entry-choice-text {
    font-size: 38px;
  }

  .entry-library {
    flex-direction: column;
    padding: 18px;
    gap: 18px;
  }

  .entry-side {
    width: 100%;
    flex: none;
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: center;
  }

  .entry-side-pill {
    width: 150px;
    height: 115px;
    flex: 0 0 150px;
    font-size: 20px;
  }

  .entry-content {
    width: 100%;
    min-height: 500px;
  }

  .entry-content-title {
    font-size: 36px;
    text-align: center;
  }

  .entries-grid {
    justify-content: center;
  }

  .fish-area-menu {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 10px;
  }

  .fish-area-icon {
    height: 145px;
    padding: 8px;
  }

  .fish-area-icon img {
    max-width: 80px;
    max-height: 80px;
  }

  .fish-area-name {
    font-size: 15px;
  }
}

/* ===== Phone layout ===== */

@media screen and (max-width: 600px) {
  .entry-choice-box {
    min-height: 0;
    padding: 12px;
    gap: 14px;
  }

  .entry-choice-pill {
    width: 100%;
    height: 190px;
    flex: 0 0 100%;
    border-radius: 18px;
  }

  .entry-choice-pill img {
    max-width: 120px;
    max-height: 120px;
  }

  .entry-choice-text {
    font-size: 32px;
  }

  .entry-library {
    padding: 12px;
    gap: 12px;
    border-radius: 18px;
  }

  .entry-side {
    gap: 10px;
  }

  .entry-side-pill {
    width: 31%;
