    flex-wrap: wrap;
  }

  .entry-subtab {
    font-size: 18px;
    padding: 7px 14px;
  }

  /* Two fish-group icons per row */

  .fish-area-menu {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
    overflow: visible;
    padding: 0;
  }

  .fish-area-icon {
    min-width: 0;
    height: 135px;
    padding: 8px;
  }

  .fish-area-icon img {
    max-width: 75px;
    max-height: 75px;
  }

  .fish-area-name {
    font-size: 14px;
  }

  .fish-group-heading {
    gap: 10px;
  }

  .fish-group-title {
    font-size: 22px;
  }

  .fish-group-back {
    padding: 7px 12px;
    font-size: 14px;
  }

  .entry-card {
    width: 110px;
    height: 135px;
    padding: 8px;
  }

  .entry-card img {
    max-width: 82px;
