}

.entry-side-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Main content ===== */

.entry-content {
  position: relative;
  overflow: hidden;

  flex: 1;
  min-width: 0;
  min-height: 430px;

  padding: 24px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

.entry-content-title {
  margin-bottom: 20px;

  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
}

/* ===== Item subtabs ===== */

.entry-subtabs {
  display: flex;
  gap: 12px;

  margin-bottom: 20px;
}

.entry-subtab {
  padding: 8px 18px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 999px;

  color: #4f8cff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
}

.entry-subtab:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-subcontent {
  display: none;
}

/* ===== Six fish subicons ===== */

.fish-area-menu {
  display: none;

  width: 100%;

  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;

  margin: 0;
  padding: 0;

  box-sizing: border-box;
}

.fish-area-icon {
  min-width: 0;
  height: 155px;

  padding: 8px 10px 4px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 18px;

  text-align: center;

  box-sizing: border-box;
  cursor: pointer;
  overflow: hidden;
}

.fish-area-icon:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.fish-area-icon img {
  display: block;

  max-width: 95px;
  max-height: 95px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.fish-area-name {
  width: 100%;

  margin-top: -8px;
  padding: 0;

  color: #4f8cff;
  font-size: 17px;
  font-weight: bold;
  line-height: 1;

  text-align: center;
  white-space: normal;
  word-wrap: break-word;
}

/* ===== Selected fish group ===== */

.fish-group {
  display: none;
}

.fish-group-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;

  margin-bottom: 18px;
}

.fish-group-title {
  color: #4f8cff;
  font-size: 28px;
  font-weight: bold;
}

.fish-group-back {
  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;

  cursor: pointer;
}

.fish-group-back:hover {
  background: #1f4388;
}

/* ===== Entry cards ===== */

.entries-grid {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-content: flex-start;
  gap: 12px;
}

.entry-card {
  position: relative;

  width: 130px;
  height: 150px;

  padding: 10px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 18px;

  text-align: center;

  box-sizing: border-box;
  overflow: visible;
  cursor: pointer;
}

.entry-card:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-card img {
  max-width: 100px;
  max-height: 100px;
  width: auto;
  height: auto;
}

.entry-card-name {
  margin-top: -30px;

  font-size: 16px;
  font-weight: bold;
  line-height: 1;
}

.entry-card-items {
  border-color: #5aaeff;
}

.entry-card-tools {
  border-color: #69e8f4;
}

.entry-card-enchants {
  border-color: #9666ff;
}

/* ===== Entry detail page ===== */

.entry-detail-panel {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  z-index: 50;

  padding: 24px;

  background: #0b0f17;
  border-radius: 20px;

  box-sizing: border-box;
}

.entry-detail-top {
  display: grid;
  grid-template-columns: 160px 1fr 120px;
  align-items: center;
  gap: 20px;
}

.entry-detail-image {
  text-align: left;
}

.entry-detail-image img {
  max-width: 140px;
  max-height: 140px;
  width: auto;
  height: auto;
}

.entry-detail-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
}

.entry-detail-name {
  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  text-align: center;
}

.entry-detail-rarity {
  text-align: center;
}

.entry-rarity-pill {
  display: inline-block;

  padding: 8px 16px;

  background: #0b0f17;
  border: 2px solid #222831;
  border-radius: 999px;

  font-weight: bold;
  line-height: 1;
}

.entry-detail-back {
  justify-self: end;

  display: inline-block;

  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;
  text-decoration: none;

  cursor: pointer;
}

.entry-detail-back:hover {
  background: #1f4388;
}

.entry-detail-body {
  margin-top: 28px;

  color: #ffffff;
  font-size: 18px;
  line-height: 1.4;
}

/* ===== Active states ===== */

.js-entry-open {
  cursor: pointer;
}

.entry-side-pill.entry-active,
.entry-subtab.entry-active {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Rarity name animations ===== */

.entry-name-rarity-common {
  animation: fish-common-name 2s ease-in-out infinite;
}

@keyframes fish-common-name {
  0% {
    color: #a8b1b6;
  }

  50% {
    color: #7f8c99;
  }

  100% {
    color: #a8b1b6;
  }
}

.entry-name-rarity-uncommon {
  animation: fish-uncommon-name 2s ease-in-out infinite;
}

@keyframes fish-uncommon-name {
  0% {
    color: #67ec88;
  }

  50% {
    color: #63c138;
  }

  100% {
    color: #67ec88;
  }
}

.entry-name-rarity-rare {
  animation: fish-rare-name 2s ease-in-out infinite;
}

@keyframes fish-rare-name {
  0% {
    color: #4ad8ff;
  }

  50% {
    color: #3d93fc;
  }

  100% {
    color: #4ad8ff;
  }
}

.entry-name-rarity-epic {
  animation: fish-epic-name 2s ease-in-out infinite;
}

@keyframes fish-epic-name {
  0% {
    color: #7843ff;
  }

  50% {
    color: #7246a7;
  }

  100% {
    color: #7843ff;
  }
}

.entry-name-rarity-legendary {
  animation: fish-legendary-name 2s ease-in-out infinite;
}

@keyframes fish-legendary-name {
  0% {
    color: #ffe669;
  }

  50% {
    color: #fc932a;
  }

  100% {
    color: #ffe669;
  }
}

/* ===== Rarity border animations ===== */

.entry-card-rarity-none {
  border-color: #5aaeff;
}

.entry-card-rarity-common {
  animation: fish-common-border 2s ease-in-out infinite;
}

@keyframes fish-common-border {
  0% {
    border-color: #a8b1b6;
    box-shadow: 0 0 6px #a8b1b6;
  }

  50% {
    border-color: #7f8c99;
    box-shadow: 0 0 10px #7f8c99;
  }

  100% {
    border-color: #a8b1b6;
    box-shadow: 0 0 6px #a8b1b6;
  }
}

.entry-card-rarity-uncommon {
  animation: fish-uncommon-border 2s ease-in-out infinite;
}

@keyframes fish-uncommon-border {
  0% {
    border-color: #67ec88;
    box-shadow: 0 0 6px #67ec88;
  }

  50% {
    border-color: #63c138;
    box-shadow: 0 0 10px #63c138;
  }

  100% {
    border-color: #67ec88;
    box-shadow: 0 0 6px #67ec88;
  }
}

.entry-card-rarity-rare {
  animation: fish-rare-border 2s ease-in-out infinite;
}

@keyframes fish-rare-border {
  0% {
    border-color: #4ad8ff;
    box-shadow: 0 0 6px #4ad8ff;
  }

  50% {
    border-color: #3d93fc;
    box-shadow: 0 0 10px #3d93fc;
  }

  100% {
    border-color: #4ad8ff;
    box-shadow: 0 0 6px #4ad8ff;
  }
}

.entry-card-rarity-epic {
  animation: fish-epic-border 2s ease-in-out infinite;
}

@keyframes fish-epic-border {
  0% {
    border-color: #7843ff;
    box-shadow: 0 0 6px #7843ff;
  }

  50% {
    border-color: #7246a7;
    box-shadow: 0 0 10px #7246a7;
  }

  100% {
    border-color: #7843ff;
    box-shadow: 0 0 6px #7843ff;
  }
}

.entry-card-rarity-legendary {
  animation: fish-legendary-border 2s ease-in-out infinite;
}

@keyframes fish-legendary-border {
  0% {
    border-color: #ffe669;
    box-shadow: 0 0 6px #ffe669;
  }

  50% {
    border-color: #fc932a;
    box-shadow: 0 0 10px #fc932a;
  }

  100% {
    border-color: #ffe669;
    box-shadow: 0 0 6px #ffe669;
  }
}

/* ===== Tablet layout ===== */

@media screen and (max-width: 900px) {
  .entry-choice-box {
    padding: 18px;
    gap: 18px;
  }

  .entry-choice-pill {
    width: 260px;
    height: 250px;
    flex: 0 0 260px;
  }

  .entry-choice-pill img {
    max-width: 170px;
    max-height: 170px;
  }

  .entry-choice-text {
    font-size: 38px;
  }

  .entry-library {
    flex-direction: column;

    padding: 18px;
    gap: 18px;
  }

  .entry-side {
    width: 100%;
    flex: 0 0 auto;

    flex-direction: row;
    flex-wrap: wrap;
    justify-content: center;
  }

  .entry-side-pill {
    width: 150px;
    height: 115px;
    flex: 0 0 150px;

    font-size: 20px;
  }

  .entry-content {
    width: 100%;
    min-height: 500px;
  }

  .entry-content-title {
    font-size: 36px;
    text-align: center;
  }

  .entries-grid {
    justify-content: center;
  }

  .fish-area-menu {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 10px;
  }

  .fish-area-icon {
    height: 145px;
    padding: 7px 8px 3px;
  }

  .fish-area-icon img {
    max-width: 82px;
    max-height: 82px;
  }

  .fish-area-name {
    margin-top: -7px;
    font-size: 15px;
  }
}

/* ===== Phone layout ===== */

@media screen and (max-width: 600px) {
  .entry-choice-box {
    min-height: 0;

    padding: 12px;
    gap: 14px;
  }

  .entry-choice-pill {
    width: 100%;
    height: 190px;
    flex: 0 0 100%;

    border-radius: 18px;
  }

  .entry-choice-pill img {
    max-width: 120px;
    max-height: 120px;
  }

  .entry-choice-text {
    font-size: 32px;
  }

  .entry-library {
    padding: 12px;
    gap: 12px;

    border-radius: 18px;
  }

  .entry-side {
    gap: 10px;
  }

  .entry-side-pill {
    width: 31%;
    min-width: 90px;
    height: 90px;
    flex: 0 0 31%;

    font-size: 14px;

    border-width: 3px;
    border-radius: 16px;
  }

  .entry-side-pill img {
    max-width: 48px;
    max-height: 48px;
  }

  .entry-content {
    min-height: 560px;

    padding: 14px;

    border-radius: 18px;
  }

  .entry-content-title {
    margin-bottom: 14px;

    font-size: 30px;
    text-align: center;
  }

  .entry-subtabs {
    justify-content: center;
    flex-wrap: wrap;
  }

  .entry-subtab {
    padding: 7px 14px;

    font-size: 18px;
  }

  .fish-area-menu {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;

    margin: 0;
    padding: 0;
    overflow: visible;
  }

  .fish-area-icon {
    min-width: 0;
    height: 135px;

    padding: 6px 8px 3px;
  }

  .fish-area-icon img {
    max-width: 75px;
    max-height: 75px;
  }

  .fish-area-name {
    margin-top: -7px;

    font-size: 14px;
  }

  .fish-group-heading {
    gap: 10px;
  }

  .fish-group-title {
    font-size: 22px;
  }

  .fish-group-back {
    padding: 7px 12px;

    font-size: 14px;
  }

  .entry-card {
    width: 110px;
    height: 135px;

    padding: 8px;
  }

  .entry-card img {
    max-width: 82px;
    max-height: 82px;
  }

  .entry-card-name {
    margin-top: -15px;

    font-size: 14px;
  }

  .entry-detail-panel {
    padding: 14px;
    overflow: auto;
  }

  .entry-detail-top {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .entry-detail-image {
    text-align: center;
  }

  .entry-detail-image img {
    max-width: 110px;
    max-height: 110px;
  }

  .entry-detail-name {
    font-size: 30px;
  }

  .entry-detail-back {
    justify-self: center;
    text-align: center;
  }

  .entry-detail-body {
    font-size: 16px;
    text-align: center;
  }
}

/* ===== Very small phones ===== */

@media screen and (max-width: 380px) {
  .entry-choice-pill {
    height: 165px;
  }

  .entry-choice-pill img {
    max-width: 95px;
    max-height: 95px;
  }

  .entry-choice-text {
    font-size: 26px;
  }

  .entry-side-pill {
    width: 100%;
    height: 75px;
    flex: 0 0 100%;

    flex-direction: row;

    font-size: 16px;
  }

  .entry-side-pill img {
    max-width: 42px;
    max-height: 42px;
  }

  .fish-area-menu {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
  }

  .fish-area-icon {
    min-width: 0;
    height: 120px;

    padding: 5px 6px 2px;
  }

  .fish-area-icon img {
    max-width: 62px;
    max-height: 62px;
  }

  .fish-area-name {
    margin-top: -6px;

    font-size: 12px;
  }

  .fish-group-title {
    font-size: 19px;
  }

  .entry-card {
    width: 95px;
    height: 125px;
  }

  .entry-card img {
    max-width: 72px;
    max-height: 72px;
  }

  .entry-card-name {
    font-size: 12px;
  }

  .entry-detail-name {
    font-size: 24px;
  }

  .entry-detail-body {
    font-size: 14px;
  }
}

/* ===== Remove space beneath the six subicons ===== */

/*
 * These rules must stay at the very bottom.
 * They override the 430px, 500px and 560px minimum heights
 * only while the fish subicon menu is open.
 */

.entry-library-items.entry-fish-menu-open {
  min-height: 0;
  padding-bottom: 8px;
}

.entry-library-items.entry-fish-menu-open .entry-content {
  min-height: 0;
  padding-bottom: 8px;
}

