    border-width: 3px;
    border-radius: 16px;
  }

  .entry-side-pill img {
    max-width: 48px;
    max-height: 48px;
  }

  .entry-content {
    min-height: 560px;

    padding: 14px;

    border-radius: 18px;
  }

  .entry-content-title {
    margin-bottom: 14px;

    font-size: 30px;
    text-align: center;
  }

  .entry-subtabs {
    justify-content: center;
    flex-wrap: wrap;
  }

  .entry-subtab {
    padding: 7px 14px;

    font-size: 18px;
  }

  .fish-area-menu {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;

    margin: 0;
    padding: 0;
    overflow: visible;
  }

  .fish-area-icon {
    min-width: 0;
    height: 135px;

    padding: 6px 8px 3px;
  }

  .fish-area-icon img {
    max-width: 75px;
    max-height: 75px;
  }

  .fish-area-name {
    margin-top: -7px;

    font-size: 14px;
  }

  .fish-group-heading {
    gap: 10px;
  }

  .fish-group-title {
    font-size: 22px;
  }

  .fish-group-back {
    padding: 7px 12px;

    font-size: 14px;
  }

  .entry-card {
    width: 110px;
    height: 135px;

    padding: 8px;
  }

  .entry-card img {
    max-width: 82px;
    max-height: 82px;
  }

  .entry-card-name {
    margin-top: -15px;

    font-size: 14px;
  }

  .entry-detail-panel {
    padding: 14px;
    overflow: auto;
  }

  .entry-detail-top {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .entry-detail-image {
    text-align: center;
  }

  .entry-detail-image img {
    max-width: 110px;
    max-height: 110px;
  }

  .entry-detail-name {
    font-size: 30px;
  }

  .entry-detail-back {
    justify-self: center;
    text-align: center;
  }

  .entry-detail-body {
    font-size: 16px;
    text-align: center;
  }
}

/* ===== Very small phones ===== */

@media screen and (max-width: 380px) {
  .entry-choice-pill {
    height: 165px;
  }

  .entry-choice-pill img {
    max-width: 95px;
    max-height: 95px;
  }

  .entry-choice-text {
    font-size: 26px;
  }

  .entry-side-pill {
    width: 100%;
    height: 75px;
    flex: 0 0 100%;

    flex-direction: row;

