  }

  .fish-area-menu {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
  }

  .fish-area-icon {
    min-width: 0;
    height: 120px;

    padding: 5px 6px 2px;
  }

  .fish-area-icon img {
    max-width: 62px;
    max-height: 62px;
  }

  .fish-area-name {
    margin-top: -6px;

    font-size: 12px;
  }

  .fish-group-title {
    font-size: 19px;
  }

  .entry-card {
    width: 95px;
    height: 125px;
  }

  .entry-card img {
    max-width: 72px;
    max-height: 72px;
  }

  .entry-card-name {
    font-size: 12px;
  }

  .entry-detail-name {
