  }

  .fish-area-menu {
    grid-template-columns: repeat(3, 160px);
    justify-content: center;
    gap: 10px;
  }

  .fish-area-icon {
    width: 160px;
    height: 160px;
  }

  .fish-area-icon img {
    max-width: 100px;
    max-height: 100px;
  }

  .fish-area-name {
    top: -10px;

    margin-top: -5px;
    font-size: 16px;
  }
}

/* ===== Phone layout ===== */

@media screen and (max-width: 600px) {
  .entry-choice-box {
    min-height: 0;
    padding: 12px;
    gap: 14px;
  }

  .entry-choice-pill {
    width: 100%;
    height: 190px;
    flex: 0 0 100%;

