    padding: 5px;
    border-radius: 16px;
  }

  .fish-area-icon img {
    max-width: 70px;
    max-height: 70px;
  }

  .fish-area-name {
    top: -6px;

    margin-top: -4px;
    font-size: 12px;
  }

  .fish-group-title {
    font-size: 19px;
  }

  .entry-card {
    width: 95px;
    height: 125px;
  }

  .entry-card img {
    max-width: 72px;
    max-height: 72px;
  }

  .entry-card-name {
    font-size: 12px;
  }

  .entry-detail-name {
    font-size: 24px;
  }

  .entry-detail-body {
    font-size: 14px;
  }
}

/* ===== Compact fish-menu screen ===== */

.entry-library-items.entry-fish-menu-open {
  min-height: 0;
  align-items: flex-start;
  padding-bottom: 12px;
}

.entry-library-items.entry-fish-menu-open .entry-content {
  min-height: 0;
  height: auto;

  align-self: flex-start;
  padding-bottom: 12px;
}

.entry-library-items.entry-fish-menu-open .entry-side {
  align-self: flex-start;
}

.entry-library-items.entry-fish-menu-open .entry-side-pill {
  flex: 0 0 135px;
  min-height: 135px;
}

@media screen and (max-width: 900px) {
