  }

  .entries-grid {
    gap: 9px;
  }

  .entry-card {
    width: 112px;
    height: 134px;
    padding: 8px;

    border-radius: 15px;
  }

  .entry-card img {
    max-width: 86px;
    max-height: 86px;
  }

  .entry-card-name {
    margin-top: -24px;

    font-size: 14px;
  }

  .entry-detail-panel {
    padding: 16px;

    border-radius: 14px;
  }

  .entry-detail-top {
    grid-template-columns: 84px minmax(0, 1fr);
    gap: 12px;
  }

  .entry-detail-image img {
    max-width: 78px;
    max-height: 78px;
  }

  .entry-detail-header {
    align-items: flex-start;
  }

  .entry-detail-name {
    font-size: 27px;
    text-align: left;
  }

  .entry-detail-rarity {
    text-align: left;
  }

  .entry-rarity-pill {
    padding: 6px 10px;

    font-size: 13px;
  }

  .entry-detail-back {
    grid-column: 1 / -1;
    justify-self: stretch;

    text-align: center;
  }

  .entry-detail-stats {
    grid-template-columns: 1fr;
    gap: 9px;

    margin-top: 18px;
  }

  .entry-detail-stat {
    padding: 12px;
  }

  .entry-detail-stat-value {
