/* ===== Very small screens ===== */

@media (max-width: 360px) {
  .fish-area-menu {
    grid-template-columns: repeat(2, minmax(0, 118px));
  }

  .fish-area-icon,
  .fish-area-icon:nth-child(4),
  .fish-area-icon:nth-child(5) {
    width: 118px;
    height: 125px;
  }

  .fish-area-icon img {
    max-width: 72px;
    max-height: 72px;
  }

  .entry-card {
    width: 104px;
  }
}

.entry-ui {
  width: 100%;
  max-width: 1075px;
  margin: 0 auto;
  box-sizing: border-box;
}

/* ===== Main category selection ===== */

.entry-choice-box {
  display: flex;
  flex-flow: row wrap;
  justify-content: center;
  align-items: center;
  gap: 28px;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;
  box-sizing: border-box;
}

.entry-choice-pill {
  width: 320px;
  height: 300px;
  flex: 0 0 320px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 26px;

  text-align: center;
  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.entry-choice-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
  transform: translateY(-2px);
}

.entry-choice-pill img {
  display: block;

  max-width: 220px;
  max-height: 220px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.entry-choice-text {
  display: block;

  color: #4f8cff;
  font-size: 50px;
  font-weight: bold;
  line-height: 1;
  white-space: nowrap;
}

/* ===== Entry library ===== */

.entry-library {
  display: none;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;
  gap: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

/* ===== Left navigation ===== */

.entry-side {
  width: 190px;
  flex: 0 0 190px;

  display: flex;
  flex-direction: column;
  align-self: stretch;
  gap: 18px;
}

.entry-side-pill {
  width: 170px;
  min-height: 135px;
  flex: 1;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  color: #4f8cff;
  font-size: 24px;
  font-weight: bold;
  line-height: 1;
  text-align: center;

  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

.entry-side-pill img {
  display: block;

  max-width: 80px;
  max-height: 80px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.entry-side-pill div {
  margin-top: 0;
}

.entry-side-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Main content ===== */

.entry-content {
  position: relative;
  overflow: hidden;

  flex: 1;
  min-width: 0;
  min-height: 430px;
  padding: 24px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

.entry-content-title {
  margin-bottom: 20px;

  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  line-height: 1.1;
}

/* ===== Item subtabs ===== */

.entry-subtabs {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;

  margin-bottom: 20px;
}

.entry-subtab {
  padding: 8px 18px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 999px;

  color: #4f8cff;
  font-size: 22px;
  font-weight: bold;

  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

.entry-subtab:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-subcontent {
  display: none;
}

/* ===== Five fish-area buttons ===== */
/* Desktop layout: 3 on top and 2 centred below */

.fish-area-menu {
  display: none;

  width: 100%;

  grid-template-columns: repeat(6, 83px);
  justify-content: center;
  column-gap: 14px;
  row-gap: 14px;

  margin: 0;
  padding: 0;

  box-sizing: border-box;
}

.fish-area-icon {
  width: 180px;
  height: 180px;
  min-width: 0;
  grid-column: span 2;

  padding: 10px 8px 6px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 22px;

  text-align: center;
  box-sizing: border-box;
  cursor: pointer;
  overflow: hidden;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.fish-area-icon:nth-child(4) {
  grid-column: 2 / span 2;
}

.fish-area-icon:nth-child(5) {
  grid-column: 4 / span 2;
}

.fish-area-icon:hover {
  background: #10275a;
  border-color: #5aaeff;
  transform: translateY(-2px);
}

.fish-area-icon img {
  display: block;

  max-width: 115px;
  max-height: 115px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.fish-area-name {
  width: 100%;

  margin-top: -5px;
  padding: 0;

  color: #4f8cff;
  font-size: 18px;
  font-weight: bold;
  line-height: 1;

  text-align: center;
  white-space: normal;
  overflow-wrap: anywhere;
}

.fish-area-icon.entry-active {
  background: #17346b;
  border-color: #5aaeff;
}

/* ===== Selected fish group ===== */

.fish-group {
  display: none;
}

.fish-group-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;

  margin-bottom: 18px;
}

.fish-group-title {
  color: #4f8cff;
  font-size: 28px;
  font-weight: bold;
}

.fish-group-back {
  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;

  box-sizing: border-box;
  cursor: pointer;

  transition: background 0.15s ease;
}

.fish-group-back:hover {
  background: #1f4388;
}

/* ===== Entry cards ===== */

.entries-grid {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-content: flex-start;
  gap: 12px;
}

.entry-card {
  position: relative;

  width: 130px;
  height: 150px;
  padding: 10px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 18px;

  text-align: center;

  box-sizing: border-box;
  overflow: visible;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.entry-card:hover {
  background: #10275a;
  border-color: #5aaeff;
  transform: translateY(-2px);
}

.entry-card img {
  display: block;

  max-width: 100px;
  max-height: 100px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.entry-card-name {
  margin-top: -30px;

  font-size: 16px;
  font-weight: bold;
  line-height: 1;

  overflow-wrap: anywhere;
}

.entry-card-items {
  border-color: #5aaeff;
}

.entry-card-tools {
  border-color: #69e8f4;
}

.entry-card-enchants {
  border-color: #9666ff;
}

/* ===== Entry detail page ===== */

.entry-detail-panel {
  display: none;

  position: absolute;
  inset: 0;
  z-index: 50;

  padding: 24px;
  overflow-y: auto;

  background: #0b0f17;
  border-radius: 20px;

  box-sizing: border-box;
}

.entry-detail-layout {
  min-height: 100%;

  display: flex;
  flex-direction: column;

  box-sizing: border-box;
}

.entry-detail-top {
  display: grid;
  grid-template-columns: 160px minmax(0, 1fr) 120px;
  align-items: start;
  gap: 20px;
}

.entry-detail-image {
  text-align: left;
}

.entry-detail-image img {
  display: block;

  max-width: 140px;
  max-height: 140px;
  width: auto;
  height: auto;
}

.entry-detail-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 10px;

  min-width: 0;
}

.entry-detail-name {
  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  line-height: 1.05;
  text-align: center;

  overflow-wrap: anywhere;
}

.entry-detail-rarity {
  text-align: center;
}

.entry-rarity-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 6px;

  padding: 8px 16px;

  background: #0b0f17;
  border: 2px solid #222831;
  border-radius: 999px;

  color: #ffffff;
  font-weight: bold;
  line-height: 1;
}

.entry-rarity-stars {
  display: inline-block;
  letter-spacing: 1px;
}

/* ===== Catch chance beneath rarity ===== */

.entry-detail-chance {
  width: fit-content;
  max-width: 100%;

  margin-top: 2px;
  padding: 10px 16px;

  background: rgba(28, 68, 135, 0.35);
  border: 2px solid #5aaeff;
  border-radius: 12px;

  text-align: center;
  box-sizing: border-box;
}

.entry-detail-chance-label {
  margin-bottom: 5px;

  color: #86beff;
  font-size: 13px;
  font-weight: bold;
  line-height: 1;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.entry-detail-chance-value {
  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  line-height: 1.4;

  overflow-wrap: anywhere;
}

.entry-detail-back {
  justify-self: end;
  display: inline-block;

  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;
  text-decoration: none;

  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    transform 0.15s ease;
}

.entry-detail-back:hover {
  background: #1f4388;
  transform: translateY(-1px);
}

/* ===== Lore and effects ===== */

.entry-detail-body {
  margin-top: 24px;
  margin-bottom: 18px;
  padding: 16px;

  background: rgba(7, 18, 43, 0.55);
  border: 1px solid #222831;
  border-radius: 14px;

  color: #ffffff;
  font-size: 18px;
  line-height: 1.45;

  box-sizing: border-box;
  overflow-wrap: anywhere;
}

/* ===== Sell value at bottom-left ===== */

.entry-detail-sell {
  align-self: flex-start;

  min-width: 180px;
  max-width: 100%;

  margin-top: auto;
  padding: 12px 18px;

  background: rgba(20, 95, 80, 0.3);
  border: 2px solid #69e8c5;
  border-radius: 14px;

  box-sizing: border-box;
}

.entry-detail-sell-label {
  margin-bottom: 5px;

  color: #83f0d3;
  font-size: 13px;
  font-weight: bold;
  line-height: 1;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.entry-detail-sell-value {
  color: #ffffff;
  font-size: 21px;
  font-weight: bold;
  line-height: 1.2;

  overflow-wrap: anywhere;
}

/* ===== Entry detail tablet ===== */

@media (max-width: 900px) {
  .entry-detail-top {
    grid-template-columns: 130px minmax(0, 1fr) 90px;
    gap: 14px;
  }

  .entry-detail-image img {
    max-width: 115px;
    max-height: 115px;
  }

  .entry-detail-name {
    font-size: 34px;
  }

  .entry-detail-chance {
    padding: 9px 13px;
  }

  .entry-detail-chance-value {
    font-size: 15px;
  }
}

/* ===== Entry detail mobile ===== */

@media (max-width: 650px) {
  .entry-detail-panel {
    padding: 16px;
    border-radius: 14px;
  }

  .entry-detail-top {
    grid-template-columns: 84px minmax(0, 1fr);
    align-items: start;
    gap: 12px;
  }

  .entry-detail-image img {
    max-width: 78px;
    max-height: 78px;
  }

  .entry-detail-header {
    align-items: flex-start;
  }

  .entry-detail-name {
    font-size: 27px;
    text-align: left;
  }

  .entry-detail-rarity {
    text-align: left;
  }

  .entry-rarity-pill {
    padding: 6px 10px;
    font-size: 13px;
  }

  .entry-detail-chance {
    width: 100%;
    padding: 9px 11px;

    text-align: left;
  }

  .entry-detail-chance-label {
    font-size: 12px;
  }

  .entry-detail-chance-value {
    font-size: 14px;
  }

  .entry-detail-back {
    grid-column: 1 / -1;
    justify-self: stretch;

    text-align: center;
  }

  .entry-detail-body {
    margin-top: 18px;
    padding: 13px;

    font-size: 16px;
  }

  .entry-detail-sell {
    width: 100%;
    min-width: 0;

    padding: 11px 14px;
  }

  .entry-detail-sell-value {
    font-size: 18px;
  }
}
/* ===== Active states ===== */

.js-entry-open {
  cursor: pointer;
}

.entry-side-pill.entry-active,
.entry-subtab.entry-active {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Rarity name animations ===== */

.entry-name-rarity-common {
  animation: fish-common-name 2s ease-in-out infinite;
}

@keyframes fish-common-name {
  0%,
  100% {
    color: #a8b1b6;
  }

  50% {
    color: #7f8c99;
  }
}

.entry-name-rarity-uncommon {
  animation: fish-uncommon-name 2s ease-in-out infinite;
}

@keyframes fish-uncommon-name {
  0%,
  100% {
    color: #67ec88;
  }

  50% {
    color: #63c138;
  }
}

.entry-name-rarity-rare {
  animation: fish-rare-name 2s ease-in-out infinite;
}

@keyframes fish-rare-name {
  0%,
  100% {
    color: #4ad8ff;
  }

  50% {
    color: #3d93fc;
  }
}

.entry-name-rarity-epic {
  animation: fish-epic-name 2s ease-in-out infinite;
}

@keyframes fish-epic-name {
  0%,
  100% {
    color: #7843ff;
  }

  50% {
    color: #7246a7;
  }
}

.entry-name-rarity-legendary {
  animation: fish-legendary-name 2s ease-in-out infinite;
}

@keyframes fish-legendary-name {
  0%,
  100% {
    color: #ffe669;
  }

  50% {
    color: #fc932a;
  }
}

.entry-name-rarity-mythic {
  animation: fish-mythic-name 2s ease-in-out infinite;
}

@keyframes fish-mythic-name {
  0%,
  100% {
    color: #ff3045;
  }

  50% {
    color: #b11156;
  }
}

/* ===== Rarity border animations ===== */

.entry-card-rarity-none {
  border-color: #5aaeff;
}

.entry-card-rarity-common {
  animation: fish-common-border 2s ease-in-out infinite;
}

@keyframes fish-common-border {
  0%,
  100% {
    border-color: #a8b1b6;
    box-shadow: 0 0 6px #a8b1b6;
  }

  50% {
    border-color: #7f8c99;
    box-shadow: 0 0 10px #7f8c99;
  }
}

.entry-card-rarity-uncommon {
  animation: fish-uncommon-border 2s ease-in-out infinite;
}

@keyframes fish-uncommon-border {
  0%,
  100% {
    border-color: #67ec88;
    box-shadow: 0 0 6px #67ec88;
  }

  50% {
    border-color: #63c138;
    box-shadow: 0 0 10px #63c138;
  }
}

.entry-card-rarity-rare {
  animation: fish-rare-border 2s ease-in-out infinite;
}

@keyframes fish-rare-border {
  0%,
  100% {
    border-color: #4ad8ff;
    box-shadow: 0 0 6px #4ad8ff;
  }

  50% {
    border-color: #3d93fc;
    box-shadow: 0 0 10px #3d93fc;
  }
}

.entry-card-rarity-epic {
  animation: fish-epic-border 2s ease-in-out infinite;
}

@keyframes fish-epic-border {
  0%,
  100% {
    border-color: #7843ff;
    box-shadow: 0 0 6px #7843ff;
  }

  50% {
    border-color: #7246a7;
    box-shadow: 0 0 10px #7246a7;
  }
}

.entry-card-rarity-legendary {
  animation: fish-legendary-border 2s ease-in-out infinite;
}

@keyframes fish-legendary-border {
  0%,
  100% {
    border-color: #ffe669;
    box-shadow: 0 0 6px #ffe669;
  }

  50% {
    border-color: #fc932a;
    box-shadow: 0 0 10px #fc932a;
  }
}

.entry-card-rarity-mythic {
  animation: fish-mythic-border 2s ease-in-out infinite;
}

@keyframes fish-mythic-border {
  0%,
  100% {
    border-color: #ff3045;
    box-shadow: 0 0 6px #ff3045;
  }

  50% {
    border-color: #b11156;
    box-shadow: 0 0 12px #b11156;
  }
}

/* ===== Tablet ===== */

@media (max-width: 900px) {
  .entry-choice-box {
