    grid-template-columns: 84px minmax(0, 1fr);
    gap: 12px;
  }

  .entry-detail-image img {
    max-width: 78px;
    max-height: 78px;
  }

  .entry-detail-header {
    align-items: flex-start;
  }

  .entry-detail-name {
    font-size: 27px;
    text-align: left;
  }

  .entry-detail-rarity {
    text-align: left;
  }

  .entry-rarity-pill {
    padding: 6px 10px;

    font-size: 13px;
  }

  .entry-detail-back {
    grid-column: 1 / -1;
    justify-self: stretch;

    text-align: center;
  }

  .entry-detail-stats {
