/* ===== Very small screens ===== */

@media (max-width: 360px) {
  .fish-area-menu {
    grid-template-columns: repeat(2, minmax(0, 118px));
  }

  .fish-area-icon,
  .fish-area-icon:nth-child(4),
  .fish-area-icon:nth-child(5) {
    width: 118px;
    height: 125px;
  }

  .fish-area-icon img {
    max-width: 72px;
    max-height: 72px;
  }

  .entry-card {
    width: 104px;
  }
}

.entry-library-items.entry-fish-menu-open {
  min-height: 0;
  height: auto;

  align-items: flex-start;

  padding-bottom: 12px;
}

.entry-library-items.entry-fish-menu-open .entry-content {
  min-height: 0 !important;
  height: auto;

  align-self: flex-start;

  padding-bottom: 12px;
}

.entry-library-items.entry-fish-menu-open .entry-subcontent-fish {
  margin-bottom: 0;
  padding-bottom: 0;
}

.entry-library-items.entry-fish-menu-open .fish-area-menu {
  margin-bottom: 0;
  padding-bottom: 0;
}

/* ===== Tablet compact fish screen ===== */

@media screen and (max-width: 900px) {
  .entry-library-items.entry-fish-menu-open {
    min-height: 0;
    height: auto;

    padding-bottom: 10px;
  }

  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0 !important;
    height: auto;

    padding-bottom: 10px;
  }
}

/* ===== Mobile compact fish screen ===== */

@media screen and (max-width: 650px) {
  .entry-library-items.entry-fish-menu-open {
    min-height: 0;
    height: auto;

    padding-bottom: 8px;
  }

  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0 !important;
    height: auto;

    padding-bottom: 8px;
  }

  .entry-library-items.entry-fish-menu-open .entry-subcontent-fish,
  .entry-library-items.entry-fish-menu-open .fish-area-menu {
    margin-bottom: 0;
    padding-bottom: 0;
  }
}

.entry-ui {
  width: 100%;
  max-width: 1075px;
  margin: 0 auto;
  box-sizing: border-box;
}

/* ===== Main category selection ===== */

.entry-choice-box {
  display: flex;
  flex-flow: row wrap;
  justify-content: center;
  align-items: center;
  gap: 28px;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;
  box-sizing: border-box;
}

.entry-choice-pill {
  width: 320px;
  height: 300px;
  flex: 0 0 320px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 26px;

  text-align: center;
  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.entry-choice-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
  transform: translateY(-2px);
}

.entry-choice-pill img {
  display: block;

  max-width: 220px;
  max-height: 220px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.entry-choice-text {
  display: block;

  color: #4f8cff;
  font-size: 50px;
  font-weight: bold;
  line-height: 1;
  white-space: nowrap;
}

/* ===== Entry library ===== */

.entry-library {
  display: none;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;
  gap: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

/* ===== Left navigation ===== */

.entry-side {
  width: 190px;
  flex: 0 0 190px;

  display: flex;
  flex-direction: column;
  align-self: stretch;
  gap: 18px;
}

.entry-side-pill {
  width: 170px;
  min-height: 135px;
  flex: 1;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  color: #4f8cff;
  font-size: 24px;
  font-weight: bold;
  line-height: 1;
  text-align: center;

  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

.entry-side-pill img {
  display: block;

  max-width: 80px;
  max-height: 80px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.entry-side-pill div {
  margin-top: 0;
}

.entry-side-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Main content ===== */

.entry-content {
  position: relative;
  overflow: hidden;

  flex: 1;
  min-width: 0;
  min-height: 430px;
  padding: 24px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

.entry-content-title {
  margin-bottom: 20px;

  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  line-height: 1.1;
}

/* ===== Item subtabs ===== */

.entry-subtabs {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;

  margin-bottom: 20px;
}

.entry-subtab {
  padding: 8px 18px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 999px;

  color: #4f8cff;
  font-size: 22px;
  font-weight: bold;

  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

.entry-subtab:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-subcontent {
  display: none;
}

/* ===== Five fish-area buttons ===== */
/* Desktop layout: 3 on top and 2 centred below */

.fish-area-menu {
  display: none;

  width: 100%;

  grid-template-columns: repeat(6, 83px);
  justify-content: center;
  column-gap: 14px;
  row-gap: 14px;

  margin: 0;
  padding: 0;

  box-sizing: border-box;
}

.fish-area-icon {
  width: 180px;
  height: 180px;
  min-width: 0;
  grid-column: span 2;

  padding: 10px 8px 6px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 22px;

  text-align: center;
  box-sizing: border-box;
  cursor: pointer;
  overflow: hidden;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.fish-area-icon:nth-child(4) {
  grid-column: 2 / span 2;
}

.fish-area-icon:nth-child(5) {
  grid-column: 4 / span 2;
}

.fish-area-icon:hover {
  background: #10275a;
  border-color: #5aaeff;
  transform: translateY(-2px);
}

.fish-area-icon img {
  display: block;

  max-width: 115px;
  max-height: 115px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.fish-area-name {
  width: 100%;

  margin-top: -5px;
  padding: 0;

  color: #4f8cff;
  font-size: 18px;
  font-weight: bold;
  line-height: 1;

  text-align: center;
  white-space: normal;
  overflow-wrap: anywhere;
}

.fish-area-icon.entry-active {
  background: #17346b;
  border-color: #5aaeff;
}

/* ===== Selected fish group ===== */

.fish-group {
  display: none;
}

.fish-group-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;

  margin-bottom: 18px;
}

.fish-group-title {
  color: #4f8cff;
  font-size: 28px;
  font-weight: bold;
}

.fish-group-back {
  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;

  box-sizing: border-box;
  cursor: pointer;

  transition: background 0.15s ease;
}

.fish-group-back:hover {
  background: #1f4388;
}

/* ===== Entry cards ===== */

.entries-grid {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-content: flex-start;
  gap: 12px;
}

.entry-card {
  position: relative;

  width: 130px;
  height: 150px;
  padding: 10px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 18px;

  text-align: center;

  box-sizing: border-box;
  overflow: visible;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.entry-card:hover {
  background: #10275a;
  border-color: #5aaeff;
  transform: translateY(-2px);
}

.entry-card img {
  display: block;

  max-width: 100px;
  max-height: 100px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.entry-card-name {
  margin-top: -30px;

  font-size: 16px;
  font-weight: bold;
  line-height: 1;

  overflow-wrap: anywhere;
}

.entry-card-items {
  border-color: #5aaeff;
}

.entry-card-tools {
  border-color: #69e8f4;
}

.entry-card-enchants {
  border-color: #9666ff;
}

/* ===== Entry detail page ===== */

.entry-detail-panel {
  display: none;

  position: absolute;
  inset: 0;
  z-index: 50;

  padding: 24px;
  overflow-y: auto;

  background: #0b0f17;
  border-radius: 20px;

  box-sizing: border-box;
}

.entry-detail-top {
  display: grid;
  grid-template-columns: 160px minmax(0, 1fr) 120px;
  align-items: center;
  gap: 20px;
}

.entry-detail-image {
  text-align: left;
}

.entry-detail-image img {
  display: block;

  max-width: 140px;
  max-height: 140px;
  width: auto;
  height: auto;
}

.entry-detail-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  min-width: 0;
}

.entry-detail-name {
  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  line-height: 1.05;
  text-align: center;

  overflow-wrap: anywhere;
}

.entry-detail-rarity {
  text-align: center;
}

.entry-rarity-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 6px;

  padding: 8px 16px;

  background: #0b0f17;
  border: 2px solid #222831;
  border-radius: 999px;

  color: #ffffff;
  font-weight: bold;
  line-height: 1;
}

.entry-rarity-stars {
  display: inline-block;
  letter-spacing: 1px;
}

.entry-detail-back {
  justify-self: end;
  display: inline-block;

  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;
  text-decoration: none;

  box-sizing: border-box;
  cursor: pointer;

  transition: background 0.15s ease;
}

.entry-detail-back:hover {
  background: #1f4388;
}

/* ===== Chance and cost ===== */

.entry-detail-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;

  margin-top: 24px;
  margin-bottom: 18px;
}

.entry-detail-stat {
  min-width: 0;
  padding: 14px 16px;

  background: #07122b;
  border: 2px solid #263a63;
  border-radius: 14px;

  box-sizing: border-box;
}

.entry-detail-stat-label {
  margin-bottom: 6px;

  color: #7eb5ff;
  font-size: 14px;
  font-weight: bold;
  letter-spacing: 0.06em;
  line-height: 1;
  text-transform: uppercase;
}

.entry-detail-stat-value {
  color: #ffffff;
  font-size: 19px;
  font-weight: bold;
  line-height: 1.25;

  overflow-wrap: anywhere;
}

.entry-detail-stat-chance {
  border-color: #5aaeff;
}

.entry-detail-stat-cost {
  border-color: #69e8f4;
}

.entry-detail-body {
  margin-top: 18px;
  padding: 16px;

  background: rgba(7, 18, 43, 0.55);
  border: 1px solid #222831;
  border-radius: 14px;

  color: #ffffff;
  font-size: 18px;
  line-height: 1.45;

  box-sizing: border-box;
  overflow-wrap: anywhere;
}

/* ===== Active states ===== */

.js-entry-open {
  cursor: pointer;
}

.entry-side-pill.entry-active,
.entry-subtab.entry-active {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Rarity name animations ===== */

.entry-name-rarity-common {
  animation: fish-common-name 2s ease-in-out infinite;
}

@keyframes fish-common-name {
  0%,
  100% {
    color: #a8b1b6;
  }

  50% {
    color: #7f8c99;
  }
}

.entry-name-rarity-uncommon {
  animation: fish-uncommon-name 2s ease-in-out infinite;
}

@keyframes fish-uncommon-name {
  0%,
  100% {
    color: #67ec88;
  }

  50% {
    color: #63c138;
  }
}

.entry-name-rarity-rare {
  animation: fish-rare-name 2s ease-in-out infinite;
}

@keyframes fish-rare-name {
  0%,
  100% {
    color: #4ad8ff;
  }

  50% {
    color: #3d93fc;
  }
}

.entry-name-rarity-epic {
  animation: fish-epic-name 2s ease-in-out infinite;
}

@keyframes fish-epic-name {
  0%,
  100% {
    color: #7843ff;
  }

  50% {
    color: #7246a7;
  }
}

.entry-name-rarity-legendary {
  animation: fish-legendary-name 2s ease-in-out infinite;
}

@keyframes fish-legendary-name {
  0%,
  100% {
    color: #ffe669;
  }

  50% {
    color: #fc932a;
  }
}

.entry-name-rarity-mythic {
  animation: fish-mythic-name 2s ease-in-out infinite;
}

@keyframes fish-mythic-name {
  0%,
  100% {
    color: #ff3045;
  }

  50% {
    color: #b11156;
  }
}

/* ===== Rarity border animations ===== */

.entry-card-rarity-none {
  border-color: #5aaeff;
}

.entry-card-rarity-common {
  animation: fish-common-border 2s ease-in-out infinite;
}

@keyframes fish-common-border {
  0%,
  100% {
    border-color: #a8b1b6;
    box-shadow: 0 0 6px #a8b1b6;
  }

  50% {
    border-color: #7f8c99;
    box-shadow: 0 0 10px #7f8c99;
  }
}

.entry-card-rarity-uncommon {
  animation: fish-uncommon-border 2s ease-in-out infinite;
}

@keyframes fish-uncommon-border {
  0%,
  100% {
    border-color: #67ec88;
    box-shadow: 0 0 6px #67ec88;
  }

  50% {
    border-color: #63c138;
    box-shadow: 0 0 10px #63c138;
  }
}

.entry-card-rarity-rare {
  animation: fish-rare-border 2s ease-in-out infinite;
}

@keyframes fish-rare-border {
  0%,
  100% {
    border-color: #4ad8ff;
    box-shadow: 0 0 6px #4ad8ff;
  }

  50% {
    border-color: #3d93fc;
    box-shadow: 0 0 10px #3d93fc;
  }
}

.entry-card-rarity-epic {
  animation: fish-epic-border 2s ease-in-out infinite;
}

@keyframes fish-epic-border {
  0%,
  100% {
    border-color: #7843ff;
    box-shadow: 0 0 6px #7843ff;
  }

  50% {
    border-color: #7246a7;
    box-shadow: 0 0 10px #7246a7;
  }
}

.entry-card-rarity-legendary {
  animation: fish-legendary-border 2s ease-in-out infinite;
}

@keyframes fish-legendary-border {
  0%,
  100% {
    border-color: #ffe669;
    box-shadow: 0 0 6px #ffe669;
  }

  50% {
    border-color: #fc932a;
    box-shadow: 0 0 10px #fc932a;
  }
}

.entry-card-rarity-mythic {
  animation: fish-mythic-border 2s ease-in-out infinite;
}

@keyframes fish-mythic-border {
  0%,
  100% {
    border-color: #ff3045;
    box-shadow: 0 0 6px #ff3045;
  }

  50% {
    border-color: #b11156;
    box-shadow: 0 0 12px #b11156;
  }
}

/* ===== Tablet ===== */

@media (max-width: 900px) {
  .entry-choice-box {
    gap: 18px;
    padding: 18px;
  }

  .entry-choice-pill {
    width: 250px;
    height: 240px;
    flex-basis: 250px;
  }

  .entry-choice-pill img {
    max-width: 165px;
    max-height: 165px;
  }

  .entry-choice-text {
    font-size: 38px;
  }

  .entry-library {
    padding: 18px;
    gap: 18px;
  }

  .entry-side {
    width: 155px;
    flex-basis: 155px;
    gap: 14px;
  }

  .entry-side-pill {
    width: 145px;
    min-height: 120px;
    font-size: 20px;
  }

  .entry-side-pill img {
    max-width: 68px;
    max-height: 68px;
  }

  .entry-content {
    padding: 18px;
  }

  .entry-content-title {
    font-size: 36px;
  }

  .fish-area-menu {
    grid-template-columns: repeat(6, 75px);
    column-gap: 10px;
    row-gap: 12px;
  }

  .fish-area-icon {
    width: 160px;
    height: 160px;
  }

  .fish-area-icon img {
    max-width: 100px;
    max-height: 100px;
  }

  .entry-detail-top {
    grid-template-columns: 130px minmax(0, 1fr) 90px;
    gap: 14px;
  }

  .entry-detail-image img {
    max-width: 115px;
    max-height: 115px;
  }

  .entry-detail-name {
    font-size: 34px;
  }
}

/* ===== Mobile ===== */

@media (max-width: 650px) {
  .entry-ui {
    max-width: 100%;
  }

  .entry-choice-box {
    min-height: 0;
    padding: 14px;
    gap: 14px;
  }

  .entry-choice-pill {
    width: 100%;
    max-width: 290px;
    height: 220px;
    flex: 1 1 100%;
  }

  .entry-choice-pill img {
    max-width: 145px;
    max-height: 145px;
  }

  .entry-choice-text {
    font-size: 34px;
  }

  .entry-library {
    min-height: 0;
    padding: 12px;
    gap: 12px;

    flex-direction: column;
  }

  .entry-side {
    width: 100%;
    flex: 0 0 auto;

    flex-direction: row;
    align-self: auto;
    gap: 8px;
  }

  .entry-side-pill {
    width: auto;
    min-width: 0;
    min-height: 92px;
    flex: 1;

    padding: 8px 4px;

    border-width: 3px;
    border-radius: 16px;

    font-size: 14px;
  }

  .entry-side-pill img {
    max-width: 48px;
    max-height: 48px;
  }

  .entry-content {
    min-height: 500px;
    padding: 14px;

    border-radius: 18px;
  }

  .entry-content-title {
    margin-bottom: 14px;

    font-size: 30px;
  }

  .entry-subtabs {
    gap: 8px;
    margin-bottom: 14px;
  }

  .entry-subtab {
    padding: 7px 13px;

    border-width: 2px;
    font-size: 18px;
  }

  /* Mobile: 2 + 2 + 1 centred */

  .fish-area-menu {
    grid-template-columns: repeat(2, minmax(0, 135px));
    justify-content: center;
    column-gap: 10px;
    row-gap: 10px;
  }

  .fish-area-icon,
  .fish-area-icon:nth-child(4),
  .fish-area-icon:nth-child(5) {
    width: 135px;
    height: 135px;
    grid-column: auto;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 1 / -1;
    justify-self: center;
  }

  .fish-area-icon img {
    max-width: 82px;
    max-height: 82px;
  }

  .fish-area-name {
    margin-top: -2px;

    font-size: 15px;
  }

  .entries-grid {
    gap: 9px;
  }

  .entry-card {
    width: 112px;
    height: 134px;
    padding: 8px;

    border-radius: 15px;
  }

  .entry-card img {
    max-width: 86px;
    max-height: 86px;
  }

  .entry-card-name {
    margin-top: -24px;

    font-size: 14px;
  }

  .entry-detail-panel {
    padding: 16px;

    border-radius: 14px;
  }

  .entry-detail-top {
    grid-template-columns: 84px minmax(0, 1fr);
    gap: 12px;
  }

  .entry-detail-image img {
    max-width: 78px;
    max-height: 78px;
  }

  .entry-detail-header {
    align-items: flex-start;
  }

  .entry-detail-name {
    font-size: 27px;
    text-align: left;
  }

  .entry-detail-rarity {
    text-align: left;
  }

  .entry-rarity-pill {
    padding: 6px 10px;

    font-size: 13px;
  }

  .entry-detail-back {
    grid-column: 1 / -1;
    justify-self: stretch;

    text-align: center;
  }

  .entry-detail-stats {
    grid-template-columns: 1fr;
    gap: 9px;

    margin-top: 18px;
  }

  .entry-detail-stat {
    padding: 12px;
  }

  .entry-detail-stat-value {
    font-size: 17px;
  }

  .entry-detail-body {
    padding: 13px;

    font-size: 16px;
  }
}

/* ===== Very small screens ===== */

@media (max-width: 360px) {
  .fish-area-menu {
    grid-template-columns: repeat(2, minmax(0, 118px));
  }

  .fish-area-icon,
  .fish-area-icon:nth-child(4),
  .fish-area-icon:nth-child(5) {
    width: 118px;
    height: 125px;
  }

  .fish-area-icon img {
    max-width: 72px;
    max-height: 72px;
  }

  .entry-card {
    width: 104px;
  }
}

.entry-library-items.entry-fish-menu-open {
  min-height: 0;
  height: auto;

  align-items: flex-start;

  padding-bottom: 12px;
}

.entry-library-items.entry-fish-menu-open .entry-content {
  min-height: 0 !important;
  height: auto;

  align-self: flex-start;

  padding-bottom: 12px;
}

.entry-library-items.entry-fish-menu-open .entry-subcontent-fish {
  margin-bottom: 0;
  padding-bottom: 0;
}

.entry-library-items.entry-fish-menu-open .fish-area-menu {
  margin-bottom: 0;
  padding-bottom: 0;
}

/* ===== Tablet compact fish screen ===== */

@media screen and (max-width: 900px) {
  .entry-library-items.entry-fish-menu-open {
    min-height: 0;
    height: auto;

    padding-bottom: 10px;
  }

  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0 !important;
    height: auto;

    padding-bottom: 10px;
  }
}

/* ===== Mobile compact fish screen ===== */

@media screen and (max-width: 650px) {
  .entry-library-items.entry-fish-menu-open {
    min-height: 0;
    height: auto;

    padding-bottom: 8px;
  }

  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0 !important;
    height: auto;

    padding-bottom: 8px;
  }

  .entry-library-items.entry-fish-menu-open .entry-subcontent-fish,
  .entry-library-items.entry-fish-menu-open .fish-area-menu {
    margin-bottom: 0;
    padding-bottom: 0;
  }
}

.entry-ui {
  width: 100%;
  max-width: 1075px;
  margin: 0 auto;
  box-sizing: border-box;
}

/* ===== Main category selection ===== */

.entry-choice-box {
  display: flex;
  flex-flow: row wrap;
  justify-content: center;
  align-items: center;
  gap: 28px;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;
  box-sizing: border-box;
}

.entry-choice-pill {
  width: 320px;
  height: 300px;
  flex: 0 0 320px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 26px;

  text-align: center;
  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.entry-choice-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
  transform: translateY(-2px);
}

.entry-choice-pill img {
  display: block;

  max-width: 220px;
  max-height: 220px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.entry-choice-text {
  display: block;

  color: #4f8cff;
  font-size: 50px;
  font-weight: bold;
  line-height: 1;
  white-space: nowrap;
}

/* ===== Entry library ===== */

.entry-library {
  display: none;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;
  gap: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

/* ===== Left navigation ===== */

.entry-side {
  width: 190px;
  flex: 0 0 190px;

  display: flex;
  flex-direction: column;
  align-self: stretch;
  gap: 18px;
}

.entry-side-pill {
  width: 170px;
  min-height: 135px;
  flex: 1;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  color: #4f8cff;
  font-size: 24px;
  font-weight: bold;
  line-height: 1;
  text-align: center;

  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

.entry-side-pill img {
  display: block;

  max-width: 80px;
  max-height: 80px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.entry-side-pill div {
  margin-top: 0;
}

.entry-side-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Main content ===== */

.entry-content {
  position: relative;
  overflow: hidden;

  flex: 1;
  min-width: 0;
  min-height: 430px;
  padding: 24px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

.entry-content-title {
  margin-bottom: 20px;

  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  line-height: 1.1;
}

/* ===== Item subtabs ===== */

.entry-subtabs {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;

  margin-bottom: 20px;
}

.entry-subtab {
  padding: 8px 18px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 999px;

  color: #4f8cff;
  font-size: 22px;
  font-weight: bold;

  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

.entry-subtab:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-subcontent {
  display: none;
}

/* ===== Five fish-area buttons ===== */
/* Desktop layout: 3 on top and 2 centred below */

.fish-area-menu {
  display: none;

  width: 100%;

  grid-template-columns: repeat(6, 83px);
  justify-content: center;
  column-gap: 14px;
  row-gap: 14px;

  margin: 0;
  padding: 0;

  box-sizing: border-box;
}

.fish-area-icon {
  width: 180px;
  height: 180px;
  min-width: 0;
  grid-column: span 2;

  padding: 10px 8px 6px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 22px;

  text-align: center;
  box-sizing: border-box;
  cursor: pointer;
  overflow: hidden;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.fish-area-icon:nth-child(4) {
  grid-column: 2 / span 2;
}

.fish-area-icon:nth-child(5) {
  grid-column: 4 / span 2;
}

.fish-area-icon:hover {
  background: #10275a;
  border-color: #5aaeff;
  transform: translateY(-2px);
}

.fish-area-icon img {
  display: block;

  max-width: 115px;
  max-height: 115px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.fish-area-name {
  width: 100%;

  margin-top: -5px;
  padding: 0;

  color: #4f8cff;
  font-size: 18px;
  font-weight: bold;
  line-height: 1;

  text-align: center;
  white-space: normal;
  overflow-wrap: anywhere;
}

.fish-area-icon.entry-active {
  background: #17346b;
  border-color: #5aaeff;
}

/* ===== Selected fish group ===== */

.fish-group {
  display: none;
}

.fish-group-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;

  margin-bottom: 18px;
}

.fish-group-title {
  color: #4f8cff;
  font-size: 28px;
  font-weight: bold;
}

.fish-group-back {
  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;

  box-sizing: border-box;
  cursor: pointer;

  transition: background 0.15s ease;
}

.fish-group-back:hover {
  background: #1f4388;
}

/* ===== Entry cards ===== */

.entries-grid {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-content: flex-start;
  gap: 12px;
}

.entry-card {
  position: relative;

  width: 130px;
  height: 150px;
  padding: 10px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 18px;

  text-align: center;

  box-sizing: border-box;
  overflow: visible;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.entry-card:hover {
  background: #10275a;
  border-color: #5aaeff;
  transform: translateY(-2px);
}

.entry-card img {
  display: block;

  max-width: 100px;
  max-height: 100px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.entry-card-name {
  margin-top: -30px;

  font-size: 16px;
  font-weight: bold;
  line-height: 1;

  overflow-wrap: anywhere;
}

.entry-card-items {
  border-color: #5aaeff;
}

.entry-card-tools {
  border-color: #69e8f4;
}

.entry-card-enchants {
  border-color: #9666ff;
}

/* ===== Entry detail page ===== */

.entry-detail-panel {
  display: none;

  position: absolute;
  inset: 0;
  z-index: 50;

  padding: 24px;
  overflow-y: auto;

  background: #0b0f17;
  border-radius: 20px;

  box-sizing: border-box;
}

.entry-detail-top {
  display: grid;
  grid-template-columns: 160px minmax(0, 1fr) 120px;
  align-items: center;
  gap: 20px;
}

.entry-detail-image {
  text-align: left;
}

.entry-detail-image img {
  display: block;

  max-width: 140px;
  max-height: 140px;
  width: auto;
  height: auto;
}

.entry-detail-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  min-width: 0;
}

.entry-detail-name {
  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  line-height: 1.05;
  text-align: center;

  overflow-wrap: anywhere;
}

.entry-detail-rarity {
  text-align: center;
}

.entry-rarity-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 6px;

  padding: 8px 16px;

  background: #0b0f17;
  border: 2px solid #222831;
  border-radius: 999px;

  color: #ffffff;
  font-weight: bold;
  line-height: 1;
}

.entry-rarity-stars {
  display: inline-block;
  letter-spacing: 1px;
}

.entry-detail-back {
  justify-self: end;
  display: inline-block;

  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;
  text-decoration: none;

  box-sizing: border-box;
  cursor: pointer;

  transition: background 0.15s ease;
}

.entry-detail-back:hover {
  background: #1f4388;
}

/* ===== Chance and cost ===== */

.entry-detail-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;

  margin-top: 24px;
  margin-bottom: 18px;
}

.entry-detail-stat {
  min-width: 0;
  padding: 14px 16px;

  background: #07122b;
  border: 2px solid #263a63;
  border-radius: 14px;

  box-sizing: border-box;
}

.entry-detail-stat-label {
  margin-bottom: 6px;

  color: #7eb5ff;
  font-size: 14px;
  font-weight: bold;
  letter-spacing: 0.06em;
  line-height: 1;
  text-transform: uppercase;
}

.entry-detail-stat-value {
  color: #ffffff;
  font-size: 19px;
  font-weight: bold;
  line-height: 1.25;

  overflow-wrap: anywhere;
}

.entry-detail-stat-chance {
  border-color: #5aaeff;
}

.entry-detail-stat-cost {
  border-color: #69e8f4;
}

.entry-detail-body {
  margin-top: 18px;
  padding: 16px;

  background: rgba(7, 18, 43, 0.55);
  border: 1px solid #222831;
  border-radius: 14px;

  color: #ffffff;
  font-size: 18px;
  line-height: 1.45;

  box-sizing: border-box;
  overflow-wrap: anywhere;
}

/* ===== Active states ===== */

.js-entry-open {
  cursor: pointer;
}

.entry-side-pill.entry-active,
.entry-subtab.entry-active {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Rarity name animations ===== */

.entry-name-rarity-common {
  animation: fish-common-name 2s ease-in-out infinite;
}

@keyframes fish-common-name {
  0%,
  100% {
    color: #a8b1b6;
  }

  50% {
    color: #7f8c99;
  }
}

.entry-name-rarity-uncommon {
  animation: fish-uncommon-name 2s ease-in-out infinite;
}

@keyframes fish-uncommon-name {
  0%,
  100% {
    color: #67ec88;
  }

  50% {
    color: #63c138;
  }
}

.entry-name-rarity-rare {
  animation: fish-rare-name 2s ease-in-out infinite;
}

@keyframes fish-rare-name {
  0%,
  100% {
    color: #4ad8ff;
  }

  50% {
    color: #3d93fc;
  }
}

.entry-name-rarity-epic {
  animation: fish-epic-name 2s ease-in-out infinite;
}

@keyframes fish-epic-name {
  0%,
  100% {
    color: #7843ff;
  }

  50% {
    color: #7246a7;
  }
}

.entry-name-rarity-legendary {
  animation: fish-legendary-name 2s ease-in-out infinite;
}

@keyframes fish-legendary-name {
  0%,
  100% {
    color: #ffe669;
  }

  50% {
    color: #fc932a;
  }
}

.entry-name-rarity-mythic {
  animation: fish-mythic-name 2s ease-in-out infinite;
}

@keyframes fish-mythic-name {
  0%,
  100% {
    color: #ff3045;
  }

  50% {
    color: #b11156;
  }
}

/* ===== Rarity border animations ===== */

.entry-card-rarity-none {
  border-color: #5aaeff;
}

.entry-card-rarity-common {
  animation: fish-common-border 2s ease-in-out infinite;
}

@keyframes fish-common-border {
  0%,
  100% {
    border-color: #a8b1b6;
    box-shadow: 0 0 6px #a8b1b6;
  }

  50% {
    border-color: #7f8c99;
    box-shadow: 0 0 10px #7f8c99;
  }
}

.entry-card-rarity-uncommon {
  animation: fish-uncommon-border 2s ease-in-out infinite;
}

@keyframes fish-uncommon-border {
  0%,
  100% {
    border-color: #67ec88;
    box-shadow: 0 0 6px #67ec88;
  }

  50% {
    border-color: #63c138;
    box-shadow: 0 0 10px #63c138;
  }
}

.entry-card-rarity-rare {
  animation: fish-rare-border 2s ease-in-out infinite;
}

@keyframes fish-rare-border {
  0%,
  100% {
    border-color: #4ad8ff;
    box-shadow: 0 0 6px #4ad8ff;
  }

  50% {
    border-color: #3d93fc;
    box-shadow: 0 0 10px #3d93fc;
  }
}

.entry-card-rarity-epic {
  animation: fish-epic-border 2s ease-in-out infinite;
}

@keyframes fish-epic-border {
  0%,
  100% {
    border-color: #7843ff;
    box-shadow: 0 0 6px #7843ff;
  }

  50% {
    border-color: #7246a7;
    box-shadow: 0 0 10px #7246a7;
  }
}

.entry-card-rarity-legendary {
  animation: fish-legendary-border 2s ease-in-out infinite;
}

@keyframes fish-legendary-border {
  0%,
  100% {
    border-color: #ffe669;
    box-shadow: 0 0 6px #ffe669;
  }

  50% {
    border-color: #fc932a;
    box-shadow: 0 0 10px #fc932a;
  }
}

.entry-card-rarity-mythic {
  animation: fish-mythic-border 2s ease-in-out infinite;
}

@keyframes fish-mythic-border {
  0%,
  100% {
    border-color: #ff3045;
    box-shadow: 0 0 6px #ff3045;
  }

  50% {
    border-color: #b11156;
    box-shadow: 0 0 12px #b11156;
  }
}

/* ===== Tablet ===== */

@media (max-width: 900px) {
  .entry-choice-box {
    gap: 18px;
    padding: 18px;
  }

  .entry-choice-pill {
    width: 250px;
    height: 240px;
    flex-basis: 250px;
  }

  .entry-choice-pill img {
    max-width: 165px;
    max-height: 165px;
  }

  .entry-choice-text {
    font-size: 38px;
  }

  .entry-library {
    padding: 18px;
    gap: 18px;
  }

  .entry-side {
    width: 155px;
    flex-basis: 155px;
    gap: 14px;
  }

  .entry-side-pill {
    width: 145px;
    min-height: 120px;
    font-size: 20px;
  }

  .entry-side-pill img {
    max-width: 68px;
    max-height: 68px;
  }

  .entry-content {
    padding: 18px;
  }

  .entry-content-title {
    font-size: 36px;
  }

  .fish-area-menu {
    grid-template-columns: repeat(6, 75px);
    column-gap: 10px;
    row-gap: 12px;
  }

  .fish-area-icon {
    width: 160px;
    height: 160px;
  }

  .fish-area-icon img {
    max-width: 100px;
    max-height: 100px;
  }

  .entry-detail-top {
    grid-template-columns: 130px minmax(0, 1fr) 90px;
    gap: 14px;
  }

  .entry-detail-image img {
    max-width: 115px;
    max-height: 115px;
  }

  .entry-detail-name {
    font-size: 34px;
  }
}

/* ===== Mobile ===== */

@media (max-width: 650px) {
  .entry-ui {
    max-width: 100%;
  }

  .entry-choice-box {
    min-height: 0;
    padding: 14px;
    gap: 14px;
  }

  .entry-choice-pill {
    width: 100%;
    max-width: 290px;
    height: 220px;
    flex: 1 1 100%;
  }

  .entry-choice-pill img {
    max-width: 145px;
    max-height: 145px;
  }

  .entry-choice-text {
    font-size: 34px;
  }

  .entry-library {
    min-height: 0;
    padding: 12px;
    gap: 12px;

    flex-direction: column;
  }

  .entry-side {
    width: 100%;
    flex: 0 0 auto;

    flex-direction: row;
    align-self: auto;
    gap: 8px;
  }

  .entry-side-pill {
    width: auto;
    min-width: 0;
    min-height: 92px;
    flex: 1;

    padding: 8px 4px;

    border-width: 3px;
    border-radius: 16px;

    font-size: 14px;
  }

  .entry-side-pill img {
    max-width: 48px;
    max-height: 48px;
  }

  .entry-content {
    min-height: 500px;
    padding: 14px;

    border-radius: 18px;
  }

  .entry-content-title {
    margin-bottom: 14px;

    font-size: 30px;
  }

  .entry-subtabs {
    gap: 8px;
    margin-bottom: 14px;
  }

  .entry-subtab {
    padding: 7px 13px;

    border-width: 2px;
    font-size: 18px;
  }

  /* Mobile: 2 + 2 + 1 centred */

  .fish-area-menu {
    grid-template-columns: repeat(2, minmax(0, 135px));
    justify-content: center;
    column-gap: 10px;
    row-gap: 10px;
  }

  .fish-area-icon,
  .fish-area-icon:nth-child(4),
  .fish-area-icon:nth-child(5) {
    width: 135px;
    height: 135px;
    grid-column: auto;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 1 / -1;
    justify-self: center;
  }

  .fish-area-icon img {
    max-width: 82px;
    max-height: 82px;
  }

  .fish-area-name {
    margin-top: -2px;

    font-size: 15px;
  }

  .entries-grid {
    gap: 9px;
  }

  .entry-card {
    width: 112px;
    height: 134px;
    padding: 8px;

    border-radius: 15px;
  }

  .entry-card img {
    max-width: 86px;
    max-height: 86px;
  }

  .entry-card-name {
    margin-top: -24px;

    font-size: 14px;
  }

  .entry-detail-panel {
    padding: 16px;

    border-radius: 14px;
  }

  .entry-detail-top {
    grid-template-columns: 84px minmax(0, 1fr);
    gap: 12px;
  }

  .entry-detail-image img {
    max-width: 78px;
    max-height: 78px;
  }

  .entry-detail-header {
    align-items: flex-start;
  }

  .entry-detail-name {
    font-size: 27px;
    text-align: left;
  }

  .entry-detail-rarity {
    text-align: left;
  }

  .entry-rarity-pill {
    padding: 6px 10px;

    font-size: 13px;
  }

  .entry-detail-back {
    grid-column: 1 / -1;
    justify-self: stretch;

    text-align: center;
  }

  .entry-detail-stats {
    grid-template-columns: 1fr;
    gap: 9px;

    margin-top: 18px;
  }

  .entry-detail-stat {
    padding: 12px;
  }

  .entry-detail-stat-value {
    font-size: 17px;
  }

  .entry-detail-body {
    padding: 13px;

    font-size: 16px;
  }
}

/* ===== Very small screens ===== */

@media (max-width: 360px) {
  .fish-area-menu {
    grid-template-columns: repeat(2, minmax(0, 118px));
  }

  .fish-area-icon,
  .fish-area-icon:nth-child(4),
  .fish-area-icon:nth-child(5) {
    width: 118px;
    height: 125px;
  }

  .fish-area-icon img {
    max-width: 72px;
    max-height: 72px;
  }

  .entry-card {
    width: 104px;
  }
}

.entry-ui {
  width: 100%;
  max-width: 1075px;
  margin: 0 auto;
  box-sizing: border-box;
}

/* ===== Main category selection ===== */

.entry-choice-box {
  display: flex;
  flex-flow: row wrap;
  justify-content: center;
  align-items: center;
  gap: 28px;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;
  box-sizing: border-box;
}

.entry-choice-pill {
  width: 320px;
  height: 300px;
  flex: 0 0 320px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 26px;

  text-align: center;
  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.entry-choice-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
  transform: translateY(-2px);
}

.entry-choice-pill img {
  display: block;

  max-width: 220px;
  max-height: 220px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.entry-choice-text {
  display: block;

  color: #4f8cff;
  font-size: 50px;
  font-weight: bold;
  line-height: 1;
  white-space: nowrap;
}

/* ===== Entry library ===== */

.entry-library {
  display: none;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;
  gap: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

/* ===== Left navigation ===== */

.entry-side {
  width: 190px;
  flex: 0 0 190px;

  display: flex;
  flex-direction: column;
  align-self: stretch;
  gap: 18px;
}

.entry-side-pill {
  width: 170px;
  min-height: 135px;
  flex: 1;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  color: #4f8cff;
  font-size: 24px;
  font-weight: bold;
  line-height: 1;
  text-align: center;

  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

.entry-side-pill img {
  display: block;

  max-width: 80px;
  max-height: 80px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.entry-side-pill div {
  margin-top: 0;
}

.entry-side-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Main content ===== */

.entry-content {
  position: relative;
  overflow: hidden;

  flex: 1;
  min-width: 0;
  min-height: 430px;
  padding: 24px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

.entry-content-title {
  margin-bottom: 20px;

  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  line-height: 1.1;
}

/* ===== Item subtabs ===== */

.entry-subtabs {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;

  margin-bottom: 20px;
}

.entry-subtab {
  padding: 8px 18px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 999px;

  color: #4f8cff;
  font-size: 22px;
  font-weight: bold;

  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

.entry-subtab:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-subcontent {
  display: none;
}

/* ===== Five fish-area buttons ===== */
/* Desktop layout: 3 on top and 2 centred below */

.fish-area-menu {
  display: none;

  width: 100%;

  grid-template-columns: repeat(6, 83px);
  justify-content: center;
  column-gap: 14px;
  row-gap: 14px;

  margin: 0;
  padding: 0;

  box-sizing: border-box;
}

.fish-area-icon {
  width: 180px;
  height: 180px;
  min-width: 0;
  grid-column: span 2;

  padding: 10px 8px 6px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 22px;

  text-align: center;
  box-sizing: border-box;
  cursor: pointer;
  overflow: hidden;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.fish-area-icon:nth-child(4) {
  grid-column: 2 / span 2;
}

.fish-area-icon:nth-child(5) {
  grid-column: 4 / span 2;
}

.fish-area-icon:hover {
  background: #10275a;
  border-color: #5aaeff;
  transform: translateY(-2px);
}

.fish-area-icon img {
  display: block;

  max-width: 115px;
  max-height: 115px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.fish-area-name {
  width: 100%;

  margin-top: -5px;
  padding: 0;

  color: #4f8cff;
  font-size: 18px;
  font-weight: bold;
  line-height: 1;

  text-align: center;
  white-space: normal;
  overflow-wrap: anywhere;
}

.fish-area-icon.entry-active {
  background: #17346b;
  border-color: #5aaeff;
}

/* ===== Selected fish group ===== */

.fish-group {
  display: none;
}

.fish-group-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;

  margin-bottom: 18px;
}

.fish-group-title {
  color: #4f8cff;
  font-size: 28px;
  font-weight: bold;
}

.fish-group-back {
  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;

  box-sizing: border-box;
  cursor: pointer;

  transition: background 0.15s ease;
}

.fish-group-back:hover {
  background: #1f4388;
}

/* ===== Entry cards ===== */

.entries-grid {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-content: flex-start;
  gap: 12px;
}

.entry-card {
  position: relative;

  width: 130px;
  height: 150px;
  padding: 10px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 18px;

  text-align: center;

  box-sizing: border-box;
  overflow: visible;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.entry-card:hover {
  background: #10275a;
  border-color: #5aaeff;
  transform: translateY(-2px);
}

.entry-card img {
  display: block;

  max-width: 100px;
  max-height: 100px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.entry-card-name {
  margin-top: -30px;

  font-size: 16px;
  font-weight: bold;
  line-height: 1;

  overflow-wrap: anywhere;
}

.entry-card-items {
  border-color: #5aaeff;
}

.entry-card-tools {
  border-color: #69e8f4;
}

.entry-card-enchants {
  border-color: #9666ff;
}

/* ===== Entry detail page ===== */

.entry-detail-panel {
  display: none;

  position: absolute;
  inset: 0;
  z-index: 50;

  padding: 24px;
  overflow-y: auto;

  background: #0b0f17;
  border-radius: 20px;

  box-sizing: border-box;
}

.entry-detail-top {
  display: grid;
  grid-template-columns: 160px minmax(0, 1fr) 120px;
  align-items: center;
  gap: 20px;
}

.entry-detail-image {
  text-align: left;
}

.entry-detail-image img {
  display: block;

  max-width: 140px;
  max-height: 140px;
  width: auto;
  height: auto;
}

.entry-detail-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  min-width: 0;
}

.entry-detail-name {
  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  line-height: 1.05;
  text-align: center;

  overflow-wrap: anywhere;
}

.entry-detail-rarity {
  text-align: center;
}

.entry-rarity-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 6px;

  padding: 8px 16px;

  background: #0b0f17;
  border: 2px solid #222831;
  border-radius: 999px;

  color: #ffffff;
  font-weight: bold;
  line-height: 1;
}

.entry-rarity-stars {
  display: inline-block;
  letter-spacing: 1px;
}

.entry-detail-back {
  justify-self: end;
  display: inline-block;

  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;
  text-decoration: none;

  box-sizing: border-box;
  cursor: pointer;

  transition: background 0.15s ease;
}

.entry-detail-back:hover {
  background: #1f4388;
}

/* ===== Chance and cost ===== */

.entry-detail-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;

  margin-top: 24px;
  margin-bottom: 18px;
}

.entry-detail-stat {
  min-width: 0;
  padding: 14px 16px;

  background: #07122b;
  border: 2px solid #263a63;
  border-radius: 14px;

  box-sizing: border-box;
}

.entry-detail-stat-label {
  margin-bottom: 6px;

  color: #7eb5ff;
  font-size: 14px;
  font-weight: bold;
  letter-spacing: 0.06em;
  line-height: 1;
  text-transform: uppercase;
}

.entry-detail-stat-value {
  color: #ffffff;
  font-size: 19px;
  font-weight: bold;
  line-height: 1.25;

  overflow-wrap: anywhere;
}

.entry-detail-stat-chance {
  border-color: #5aaeff;
}

.entry-detail-stat-cost {
  border-color: #69e8f4;
}

.entry-detail-body {
  margin-top: 18px;
  padding: 16px;

  background: rgba(7, 18, 43, 0.55);
  border: 1px solid #222831;
  border-radius: 14px;

  color: #ffffff;
  font-size: 18px;
  line-height: 1.45;

  box-sizing: border-box;
  overflow-wrap: anywhere;
}

/* ===== Active states ===== */

.js-entry-open {
  cursor: pointer;
}

.entry-side-pill.entry-active,
.entry-subtab.entry-active {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Rarity name animations ===== */

.entry-name-rarity-common {
  animation: fish-common-name 2s ease-in-out infinite;
}

@keyframes fish-common-name {
  0%,
  100% {
    color: #a8b1b6;
  }

  50% {
    color: #7f8c99;
  }
}

.entry-name-rarity-uncommon {
  animation: fish-uncommon-name 2s ease-in-out infinite;
}

@keyframes fish-uncommon-name {
  0%,
  100% {
    color: #67ec88;
  }

  50% {
    color: #63c138;
  }
}

.entry-name-rarity-rare {
  animation: fish-rare-name 2s ease-in-out infinite;
}

@keyframes fish-rare-name {
  0%,
  100% {
    color: #4ad8ff;
  }

  50% {
    color: #3d93fc;
  }
}

.entry-name-rarity-epic {
  animation: fish-epic-name 2s ease-in-out infinite;
}

@keyframes fish-epic-name {
  0%,
  100% {
    color: #7843ff;
  }

  50% {
    color: #7246a7;
  }
}

.entry-name-rarity-legendary {
  animation: fish-legendary-name 2s ease-in-out infinite;
}

@keyframes fish-legendary-name {
  0%,
  100% {
    color: #ffe669;
  }

  50% {
    color: #fc932a;
  }
}

.entry-name-rarity-mythic {
  animation: fish-mythic-name 2s ease-in-out infinite;
}

@keyframes fish-mythic-name {
  0%,
  100% {
    color: #ff3045;
  }

  50% {
    color: #b11156;
  }
}

/* ===== Rarity border animations ===== */

.entry-card-rarity-none {
  border-color: #5aaeff;
}

.entry-card-rarity-common {
  animation: fish-common-border 2s ease-in-out infinite;
}

@keyframes fish-common-border {
  0%,
  100% {
    border-color: #a8b1b6;
    box-shadow: 0 0 6px #a8b1b6;
  }

  50% {
    border-color: #7f8c99;
    box-shadow: 0 0 10px #7f8c99;
  }
}

.entry-card-rarity-uncommon {
  animation: fish-uncommon-border 2s ease-in-out infinite;
}

@keyframes fish-uncommon-border {
  0%,
  100% {
    border-color: #67ec88;
    box-shadow: 0 0 6px #67ec88;
  }

  50% {
    border-color: #63c138;
    box-shadow: 0 0 10px #63c138;
  }
}

.entry-card-rarity-rare {
  animation: fish-rare-border 2s ease-in-out infinite;
}

@keyframes fish-rare-border {
  0%,
  100% {
    border-color: #4ad8ff;
    box-shadow: 0 0 6px #4ad8ff;
  }

  50% {
    border-color: #3d93fc;
    box-shadow: 0 0 10px #3d93fc;
  }
}

.entry-card-rarity-epic {
  animation: fish-epic-border 2s ease-in-out infinite;
}

@keyframes fish-epic-border {
  0%,
  100% {
    border-color: #7843ff;
    box-shadow: 0 0 6px #7843ff;
  }

  50% {
    border-color: #7246a7;
    box-shadow: 0 0 10px #7246a7;
  }
}

.entry-card-rarity-legendary {
  animation: fish-legendary-border 2s ease-in-out infinite;
}

@keyframes fish-legendary-border {
  0%,
  100% {
    border-color: #ffe669;
    box-shadow: 0 0 6px #ffe669;
  }

  50% {
    border-color: #fc932a;
    box-shadow: 0 0 10px #fc932a;
  }
}

.entry-card-rarity-mythic {
  animation: fish-mythic-border 2s ease-in-out infinite;
}

@keyframes fish-mythic-border {
  0%,
  100% {
    border-color: #ff3045;
    box-shadow: 0 0 6px #ff3045;
  }

  50% {
    border-color: #b11156;
    box-shadow: 0 0 12px #b11156;
  }
}

/* ===== Tablet ===== */

@media (max-width: 900px) {
  .entry-choice-box {
    gap: 18px;
    padding: 18px;
  }

  .entry-choice-pill {
    width: 250px;
    height: 240px;
    flex-basis: 250px;
  }

  .entry-choice-pill img {
    max-width: 165px;
    max-height: 165px;
  }

  .entry-choice-text {
    font-size: 38px;
  }

  .entry-library {
    padding: 18px;
    gap: 18px;
  }

  .entry-side {
    width: 155px;
    flex-basis: 155px;
    gap: 14px;
  }

  .entry-side-pill {
    width: 145px;
    min-height: 120px;
    font-size: 20px;
  }

  .entry-side-pill img {
    max-width: 68px;
    max-height: 68px;
  }

  .entry-content {
    padding: 18px;
  }

  .entry-content-title {
    font-size: 36px;
  }

  .fish-area-menu {
    grid-template-columns: repeat(6, 75px);
    column-gap: 10px;
    row-gap: 12px;
  }

  .fish-area-icon {
    width: 160px;
    height: 160px;
  }

  .fish-area-icon img {
    max-width: 100px;
    max-height: 100px;
  }

  .entry-detail-top {
    grid-template-columns: 130px minmax(0, 1fr) 90px;
    gap: 14px;
  }

  .entry-detail-image img {
    max-width: 115px;
    max-height: 115px;
  }

  .entry-detail-name {
    font-size: 34px;
  }
}

/* ===== Mobile ===== */

@media (max-width: 650px) {
  .entry-ui {
    max-width: 100%;
  }

  .entry-choice-box {
    min-height: 0;
    padding: 14px;
    gap: 14px;
  }

  .entry-choice-pill {
    width: 100%;
    max-width: 290px;
    height: 220px;
    flex: 1 1 100%;
  }

  .entry-choice-pill img {
    max-width: 145px;
    max-height: 145px;
  }

  .entry-choice-text {
    font-size: 34px;
  }

  .entry-library {
    min-height: 0;
    padding: 12px;
    gap: 12px;

    flex-direction: column;
  }

  .entry-side {
    width: 100%;
    flex: 0 0 auto;

    flex-direction: row;
    align-self: auto;
    gap: 8px;
  }

  .entry-side-pill {
    width: auto;
    min-width: 0;
    min-height: 92px;
    flex: 1;

    padding: 8px 4px;

    border-width: 3px;
    border-radius: 16px;

    font-size: 14px;
  }

  .entry-side-pill img {
    max-width: 48px;
    max-height: 48px;
  }

  .entry-content {
    min-height: 500px;
    padding: 14px;

    border-radius: 18px;
  }

  .entry-content-title {
    margin-bottom: 14px;

    font-size: 30px;
  }

  .entry-subtabs {
    gap: 8px;
    margin-bottom: 14px;
  }

  .entry-subtab {
    padding: 7px 13px;

    border-width: 2px;
    font-size: 18px;
  }

  /* Mobile: 2 + 2 + 1 centred */

  .fish-area-menu {
    grid-template-columns: repeat(2, minmax(0, 135px));
    justify-content: center;
    column-gap: 10px;
    row-gap: 10px;
  }

  .fish-area-icon,
  .fish-area-icon:nth-child(4),
  .fish-area-icon:nth-child(5) {
    width: 135px;
    height: 135px;
    grid-column: auto;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 1 / -1;
    justify-self: center;
  }

  .fish-area-icon img {
    max-width: 82px;
    max-height: 82px;
  }

  .fish-area-name {
    margin-top: -2px;

    font-size: 15px;
  }

  .entries-grid {
    gap: 9px;
  }

  .entry-card {
    width: 112px;
    height: 134px;
    padding: 8px;

    border-radius: 15px;
  }

  .entry-card img {
    max-width: 86px;
    max-height: 86px;
  }

  .entry-card-name {
    margin-top: -24px;

    font-size: 14px;
  }

  .entry-detail-panel {
    padding: 16px;

    border-radius: 14px;
  }

  .entry-detail-top {
    grid-template-columns: 84px minmax(0, 1fr);
    gap: 12px;
  }

  .entry-detail-image img {
    max-width: 78px;
    max-height: 78px;
  }

  .entry-detail-header {
    align-items: flex-start;
  }

  .entry-detail-name {
    font-size: 27px;
    text-align: left;
  }

  .entry-detail-rarity {
    text-align: left;
  }

  .entry-rarity-pill {
    padding: 6px 10px;

    font-size: 13px;
  }

  .entry-detail-back {
    grid-column: 1 / -1;
    justify-self: stretch;

    text-align: center;
  }

  .entry-detail-stats {
    grid-template-columns: 1fr;
    gap: 9px;

    margin-top: 18px;
  }

  .entry-detail-stat {
    padding: 12px;
  }

  .entry-detail-stat-value {
    font-size: 17px;
  }

  .entry-detail-body {
    padding: 13px;

    font-size: 16px;
  }
}

/* ===== Very small screens ===== */

@media (max-width: 360px) {
  .fish-area-menu {
    grid-template-columns: repeat(2, minmax(0, 118px));
  }

  .fish-area-icon,
  .fish-area-icon:nth-child(4),
  .fish-area-icon:nth-child(5) {
    width: 118px;
    height: 125px;
  }

  .fish-area-icon img {
    max-width: 72px;
    max-height: 72px;
  }

  .entry-card {
    width: 104px;
  }
}

/* ===== Remove empty space below fish subicons ===== */
/* Keep this section at the very bottom of the CSS. */

.entry-library-items.entry-fish-menu-open {
  min-height: 0;
  height: auto;
  align-items: flex-start;
  padding-bottom: 12px;
}

.entry-library-items.entry-fish-menu-open .entry-side {
  align-self: stretch;
}

.entry-library-items.entry-fish-menu-open .entry-content {
  min-height: 0 !important;
  height: auto;
  align-self: flex-start;
  padding-bottom: 12px;
}

.entry-library-items.entry-fish-menu-open .entry-subcontent-fish,
.entry-library-items.entry-fish-menu-open .fish-area-menu {
  margin-bottom: 0;
  padding-bottom: 0;
}

@media (max-width: 900px) {
  .entry-library-items.entry-fish-menu-open {
    min-height: 0;
    height: auto;
    padding-bottom: 10px;
  }

  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0 !important;
    height: auto;
    padding-bottom: 10px;
  }
}

@media (max-width: 650px) {
  .entry-library-items.entry-fish-menu-open {
    min-height: 0;
    height: auto;
    align-items: stretch;
    padding-bottom: 8px;
  }

  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0 !important;
    height: auto;
    align-self: auto;
    padding-bottom: 8px;
  }

  .entry-library-items.entry-fish-menu-open .entry-subcontent-fish,
  .entry-library-items.entry-fish-menu-open .fish-area-menu {
    margin-bottom: 0;
    padding-bottom: 0;
  }
}

.entry-ui {
  width: 100%;
  max-width: 1075px;
  margin: 0 auto;
  box-sizing: border-box;
}

/* ===== Main category selection ===== */

.entry-choice-box {
  display: flex;
  flex-flow: row wrap;
  justify-content: center;
  align-items: center;
  gap: 28px;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;
  box-sizing: border-box;
}

.entry-choice-pill {
  width: 320px;
  height: 300px;
  flex: 0 0 320px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 26px;

  text-align: center;
  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.entry-choice-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
  transform: translateY(-2px);
}

.entry-choice-pill img {
  display: block;

  max-width: 220px;
  max-height: 220px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.entry-choice-text {
  display: block;

  color: #4f8cff;
  font-size: 50px;
  font-weight: bold;
  line-height: 1;
  white-space: nowrap;
}

/* ===== Entry library ===== */

.entry-library {
  display: none;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;
  gap: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

/* ===== Left navigation ===== */

.entry-side {
  width: 190px;
  flex: 0 0 190px;

  display: flex;
  flex-direction: column;
  align-self: stretch;
  gap: 18px;
}

.entry-side-pill {
  width: 170px;
  min-height: 135px;
  flex: 1;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  color: #4f8cff;
  font-size: 24px;
  font-weight: bold;
  line-height: 1;
  text-align: center;

  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

.entry-side-pill img {
  display: block;

  max-width: 80px;
  max-height: 80px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.entry-side-pill div {
  margin-top: 0;
}

.entry-side-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Main content ===== */

.entry-content {
  position: relative;
  overflow: hidden;

  flex: 1;
  min-width: 0;
  min-height: 430px;
  padding: 24px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

.entry-content-title {
  margin-bottom: 20px;

  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  line-height: 1.1;
}

/* ===== Item subtabs ===== */

.entry-subtabs {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;

  margin-bottom: 20px;
}

.entry-subtab {
  padding: 8px 18px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 999px;

  color: #4f8cff;
  font-size: 22px;
  font-weight: bold;

  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

.entry-subtab:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-subcontent {
  display: none;
}

/* ===== Five fish-area buttons ===== */
/* Desktop layout: 3 on top and 2 centred below */

.fish-area-menu {
  display: none;

  width: 100%;

  grid-template-columns: repeat(6, 83px);
  justify-content: center;
  column-gap: 14px;
  row-gap: 14px;

  margin: 0;
  padding: 0;

  box-sizing: border-box;
}

.fish-area-icon {
  width: 180px;
  height: 180px;
  min-width: 0;
  grid-column: span 2;

  padding: 10px 8px 6px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 22px;

  text-align: center;
  box-sizing: border-box;
  cursor: pointer;
  overflow: hidden;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.fish-area-icon:nth-child(4) {
  grid-column: 2 / span 2;
}

.fish-area-icon:nth-child(5) {
  grid-column: 4 / span 2;
}

.fish-area-icon:hover {
  background: #10275a;
  border-color: #5aaeff;
  transform: translateY(-2px);
}

.fish-area-icon img {
  display: block;

  max-width: 115px;
  max-height: 115px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.fish-area-name {
  width: 100%;

  margin-top: -5px;
  padding: 0;

  color: #4f8cff;
  font-size: 18px;
  font-weight: bold;
  line-height: 1;

  text-align: center;
  white-space: normal;
  overflow-wrap: anywhere;
}

.fish-area-icon.entry-active {
  background: #17346b;
  border-color: #5aaeff;
}

/* ===== Selected fish group ===== */

.fish-group {
  display: none;
}

.fish-group-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;

  margin-bottom: 18px;
}

.fish-group-title {
  color: #4f8cff;
  font-size: 28px;
  font-weight: bold;
}

.fish-group-back {
  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;

  box-sizing: border-box;
  cursor: pointer;

  transition: background 0.15s ease;
}

.fish-group-back:hover {
  background: #1f4388;
}

/* ===== Entry cards ===== */

.entries-grid {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-content: flex-start;
  gap: 12px;
}

.entry-card {
  position: relative;

  width: 130px;
  height: 150px;
  padding: 10px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 18px;

  text-align: center;

  box-sizing: border-box;
  overflow: visible;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.entry-card:hover {
  background: #10275a;
  border-color: #5aaeff;
  transform: translateY(-2px);
}

.entry-card img {
  display: block;

  max-width: 100px;
  max-height: 100px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.entry-card-name {
  margin-top: -30px;

  font-size: 16px;
  font-weight: bold;
  line-height: 1;

  overflow-wrap: anywhere;
}

.entry-card-items {
  border-color: #5aaeff;
}

.entry-card-tools {
  border-color: #69e8f4;
}

.entry-card-enchants {
  border-color: #9666ff;
}

/* ===== Entry detail page ===== */

.entry-detail-panel {
  display: none;

  position: absolute;
  inset: 0;
  z-index: 50;

  padding: 24px;
  overflow-y: auto;

  background: #0b0f17;
  border-radius: 20px;

  box-sizing: border-box;
}

.entry-detail-top {
  display: grid;
  grid-template-columns: 160px minmax(0, 1fr) 120px;
  align-items: center;
  gap: 20px;
}

.entry-detail-image {
  text-align: left;
}

.entry-detail-image img {
  display: block;

  max-width: 140px;
  max-height: 140px;
  width: auto;
  height: auto;
}

.entry-detail-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  min-width: 0;
}

.entry-detail-name {
  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  line-height: 1.05;
  text-align: center;

  overflow-wrap: anywhere;
}

.entry-detail-rarity {
  text-align: center;
}

.entry-rarity-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 6px;

  padding: 8px 16px;

  background: #0b0f17;
  border: 2px solid #222831;
  border-radius: 999px;

  color: #ffffff;
  font-weight: bold;
  line-height: 1;
}

.entry-rarity-stars {
  display: inline-block;
  letter-spacing: 1px;
}

.entry-detail-back {
  justify-self: end;
  display: inline-block;

  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;
  text-decoration: none;

  box-sizing: border-box;
  cursor: pointer;

  transition: background 0.15s ease;
}

.entry-detail-back:hover {
  background: #1f4388;
}

/* ===== Chance and cost ===== */

.entry-detail-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;

  margin-top: 24px;
  margin-bottom: 18px;
}

.entry-detail-stat {
  min-width: 0;
  padding: 14px 16px;

  background: #07122b;
  border: 2px solid #263a63;
  border-radius: 14px;

  box-sizing: border-box;
}

.entry-detail-stat-label {
  margin-bottom: 6px;

  color: #7eb5ff;
  font-size: 14px;
  font-weight: bold;
  letter-spacing: 0.06em;
  line-height: 1;
  text-transform: uppercase;
}

.entry-detail-stat-value {
  color: #ffffff;
  font-size: 19px;
  font-weight: bold;
  line-height: 1.25;

  overflow-wrap: anywhere;
}

.entry-detail-stat-chance {
  border-color: #5aaeff;
}

.entry-detail-stat-cost {
  border-color: #69e8f4;
}

.entry-detail-body {
  margin-top: 18px;
  padding: 16px;

  background: rgba(7, 18, 43, 0.55);
  border: 1px solid #222831;
  border-radius: 14px;

  color: #ffffff;
  font-size: 18px;
  line-height: 1.45;

  box-sizing: border-box;
  overflow-wrap: anywhere;
}

/* ===== Active states ===== */

.js-entry-open {
  cursor: pointer;
}

.entry-side-pill.entry-active,
.entry-subtab.entry-active {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Rarity name animations ===== */

.entry-name-rarity-common {
  animation: fish-common-name 2s ease-in-out infinite;
}

@keyframes fish-common-name {
  0%,
  100% {
    color: #a8b1b6;
  }

  50% {
    color: #7f8c99;
  }
}

.entry-name-rarity-uncommon {
  animation: fish-uncommon-name 2s ease-in-out infinite;
}

@keyframes fish-uncommon-name {
  0%,
  100% {
    color: #67ec88;
  }

  50% {
    color: #63c138;
  }
}

.entry-name-rarity-rare {
  animation: fish-rare-name 2s ease-in-out infinite;
}

@keyframes fish-rare-name {
  0%,
  100% {
    color: #4ad8ff;
  }

  50% {
    color: #3d93fc;
  }
}

.entry-name-rarity-epic {
  animation: fish-epic-name 2s ease-in-out infinite;
}

@keyframes fish-epic-name {
  0%,
  100% {
    color: #7843ff;
  }

  50% {
    color: #7246a7;
  }
}

.entry-name-rarity-legendary {
  animation: fish-legendary-name 2s ease-in-out infinite;
}

@keyframes fish-legendary-name {
  0%,
  100% {
    color: #ffe669;
  }

  50% {
    color: #fc932a;
  }
}

.entry-name-rarity-mythic {
  animation: fish-mythic-name 2s ease-in-out infinite;
}

@keyframes fish-mythic-name {
  0%,
  100% {
    color: #ff3045;
  }

  50% {
    color: #b11156;
  }
}

/* ===== Rarity border animations ===== */

.entry-card-rarity-none {
  border-color: #5aaeff;
}

.entry-card-rarity-common {
  animation: fish-common-border 2s ease-in-out infinite;
}

@keyframes fish-common-border {
  0%,
  100% {
    border-color: #a8b1b6;
    box-shadow: 0 0 6px #a8b1b6;
  }

  50% {
    border-color: #7f8c99;
    box-shadow: 0 0 10px #7f8c99;
  }
}

.entry-card-rarity-uncommon {
  animation: fish-uncommon-border 2s ease-in-out infinite;
}

@keyframes fish-uncommon-border {
  0%,
  100% {
    border-color: #67ec88;
    box-shadow: 0 0 6px #67ec88;
  }

  50% {
    border-color: #63c138;
    box-shadow: 0 0 10px #63c138;
  }
}

.entry-card-rarity-rare {
  animation: fish-rare-border 2s ease-in-out infinite;
}

@keyframes fish-rare-border {
  0%,
  100% {
    border-color: #4ad8ff;
    box-shadow: 0 0 6px #4ad8ff;
  }

  50% {
    border-color: #3d93fc;
    box-shadow: 0 0 10px #3d93fc;
  }
}

.entry-card-rarity-epic {
  animation: fish-epic-border 2s ease-in-out infinite;
}

@keyframes fish-epic-border {
  0%,
  100% {
    border-color: #7843ff;
    box-shadow: 0 0 6px #7843ff;
  }

  50% {
    border-color: #7246a7;
    box-shadow: 0 0 10px #7246a7;
  }
}

.entry-card-rarity-legendary {
  animation: fish-legendary-border 2s ease-in-out infinite;
}

@keyframes fish-legendary-border {
  0%,
  100% {
    border-color: #ffe669;
    box-shadow: 0 0 6px #ffe669;
  }

  50% {
    border-color: #fc932a;
    box-shadow: 0 0 10px #fc932a;
  }
}

.entry-card-rarity-mythic {
  animation: fish-mythic-border 2s ease-in-out infinite;
}

@keyframes fish-mythic-border {
  0%,
  100% {
    border-color: #ff3045;
    box-shadow: 0 0 6px #ff3045;
  }

  50% {
    border-color: #b11156;
    box-shadow: 0 0 12px #b11156;
  }
}

/* ===== Tablet ===== */

@media (max-width: 900px) {
  .entry-choice-box {
    gap: 18px;
    padding: 18px;
  }

  .entry-choice-pill {
    width: 250px;
    height: 240px;
    flex-basis: 250px;
  }

  .entry-choice-pill img {
    max-width: 165px;
    max-height: 165px;
  }

  .entry-choice-text {
    font-size: 38px;
  }

  .entry-library {
    padding: 18px;
    gap: 18px;
  }

  .entry-side {
    width: 155px;
    flex-basis: 155px;
    gap: 14px;
  }

  .entry-side-pill {
    width: 145px;
    min-height: 120px;
    font-size: 20px;
  }

  .entry-side-pill img {
    max-width: 68px;
    max-height: 68px;
  }

  .entry-content {
    padding: 18px;
  }

  .entry-content-title {
    font-size: 36px;
  }

  .fish-area-menu {
    grid-template-columns: repeat(6, 75px);
    column-gap: 10px;
    row-gap: 12px;
  }

  .fish-area-icon {
    width: 160px;
    height: 160px;
  }

  .fish-area-icon img {
    max-width: 100px;
    max-height: 100px;
  }

  .entry-detail-top {
    grid-template-columns: 130px minmax(0, 1fr) 90px;
    gap: 14px;
  }

  .entry-detail-image img {
    max-width: 115px;
    max-height: 115px;
  }

  .entry-detail-name {
    font-size: 34px;
  }
}

/* ===== Mobile ===== */

@media (max-width: 650px) {
  .entry-ui {
    max-width: 100%;
  }

  .entry-choice-box {
    min-height: 0;
    padding: 14px;
    gap: 14px;
  }

  .entry-choice-pill {
    width: 100%;
    max-width: 290px;
    height: 220px;
    flex: 1 1 100%;
  }

  .entry-choice-pill img {
    max-width: 145px;
    max-height: 145px;
  }

  .entry-choice-text {
    font-size: 34px;
  }

  .entry-library {
    min-height: 0;
    padding: 12px;
    gap: 12px;

    flex-direction: column;
  }

  .entry-side {
    width: 100%;
    flex: 0 0 auto;

    flex-direction: row;
    align-self: auto;
    gap: 8px;
  }

  .entry-side-pill {
    width: auto;
    min-width: 0;
    min-height: 92px;
    flex: 1;

    padding: 8px 4px;

    border-width: 3px;
    border-radius: 16px;

    font-size: 14px;
  }

  .entry-side-pill img {
    max-width: 48px;
    max-height: 48px;
  }

  .entry-content {
    min-height: 500px;
    padding: 14px;

    border-radius: 18px;
  }

  .entry-content-title {
    margin-bottom: 14px;

    font-size: 30px;
  }

  .entry-subtabs {
    gap: 8px;
    margin-bottom: 14px;
  }

  .entry-subtab {
    padding: 7px 13px;

    border-width: 2px;
    font-size: 18px;
  }

  /* Mobile: 2 + 2 + 1 centred */

  .fish-area-menu {
    grid-template-columns: repeat(2, minmax(0, 135px));
    justify-content: center;
    column-gap: 10px;
    row-gap: 10px;
  }

  .fish-area-icon,
  .fish-area-icon:nth-child(4),
  .fish-area-icon:nth-child(5) {
    width: 135px;
    height: 135px;
    grid-column: auto;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 1 / -1;
    justify-self: center;
  }

  .fish-area-icon img {
    max-width: 82px;
    max-height: 82px;
  }

  .fish-area-name {
    margin-top: -2px;

    font-size: 15px;
  }

  .entries-grid {
    gap: 9px;
  }

  .entry-card {
    width: 112px;
    height: 134px;
    padding: 8px;

    border-radius: 15px;
  }

  .entry-card img {
    max-width: 86px;
    max-height: 86px;
  }

  .entry-card-name {
    margin-top: -24px;

    font-size: 14px;
  }

  .entry-detail-panel {
    padding: 16px;

    border-radius: 14px;
  }

  .entry-detail-top {
    grid-template-columns: 84px minmax(0, 1fr);
    gap: 12px;
  }

  .entry-detail-image img {
    max-width: 78px;
    max-height: 78px;
  }

  .entry-detail-header {
    align-items: flex-start;
  }

  .entry-detail-name {
    font-size: 27px;
    text-align: left;
  }

  .entry-detail-rarity {
    text-align: left;
  }

  .entry-rarity-pill {
    padding: 6px 10px;

    font-size: 13px;
  }

  .entry-detail-back {
    grid-column: 1 / -1;
    justify-self: stretch;

    text-align: center;
  }

  .entry-detail-stats {
    grid-template-columns: 1fr;
    gap: 9px;

    margin-top: 18px;
  }

  .entry-detail-stat {
    padding: 12px;
  }

  .entry-detail-stat-value {
    font-size: 17px;
  }

  .entry-detail-body {
    padding: 13px;

    font-size: 16px;
  }
}

/* ===== Very small screens ===== */

@media (max-width: 360px) {
  .fish-area-menu {
    grid-template-columns: repeat(2, minmax(0, 118px));
  }

  .fish-area-icon,
  .fish-area-icon:nth-child(4),
  .fish-area-icon:nth-child(5) {
    width: 118px;
    height: 125px;
  }

  .fish-area-icon img {
    max-width: 72px;
    max-height: 72px;
  }

  .entry-card {
    width: 104px;
  }
}

.entry-ui {
  width: 100%;
  max-width: 1075px;
  margin: 0 auto;
  box-sizing: border-box;
}

/* ===== Main category selection ===== */

.entry-choice-box {
  display: flex;
  flex-flow: row wrap;
  justify-content: center;
  align-items: center;
  gap: 28px;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;
  box-sizing: border-box;
}

.entry-choice-pill {
  width: 320px;
  height: 300px;
  flex: 0 0 320px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 26px;

  text-align: center;
  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.entry-choice-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
  transform: translateY(-2px);
}

.entry-choice-pill img {
  display: block;

  max-width: 220px;
  max-height: 220px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.entry-choice-text {
  display: block;

  color: #4f8cff;
  font-size: 50px;
  font-weight: bold;
  line-height: 1;
  white-space: nowrap;
}

/* ===== Entry library ===== */

.entry-library {
  display: none;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;
  gap: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

/* ===== Left navigation ===== */

.entry-side {
  width: 190px;
  flex: 0 0 190px;

  display: flex;
  flex-direction: column;
  align-self: stretch;
  gap: 18px;
}

.entry-side-pill {
  width: 170px;
  min-height: 135px;
  flex: 1;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  color: #4f8cff;
  font-size: 24px;
  font-weight: bold;
  line-height: 1;
  text-align: center;

  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

.entry-side-pill img {
  display: block;

  max-width: 80px;
  max-height: 80px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.entry-side-pill div {
  margin-top: 0;
}

.entry-side-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Main content ===== */

.entry-content {
  position: relative;
  overflow: hidden;

  flex: 1;
  min-width: 0;
  min-height: 430px;
  padding: 24px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

.entry-content-title {
  margin-bottom: 20px;

  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  line-height: 1.1;
}

/* ===== Item subtabs ===== */

.entry-subtabs {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;

  margin-bottom: 20px;
}

.entry-subtab {
  padding: 8px 18px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 999px;

  color: #4f8cff;
  font-size: 22px;
  font-weight: bold;

  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

.entry-subtab:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-subcontent {
  display: none;
}

/* ===== Five fish-area buttons ===== */
/* Desktop layout: 3 on top and 2 centred below */

.fish-area-menu {
  display: none;

  width: 100%;

  grid-template-columns: repeat(6, 83px);
  justify-content: center;
  column-gap: 14px;
  row-gap: 14px;

  margin: 0;
  padding: 0;

  box-sizing: border-box;
}

.fish-area-icon {
  width: 180px;
  height: 180px;
  min-width: 0;
  grid-column: span 2;

  padding: 10px 8px 6px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 22px;

  text-align: center;
  box-sizing: border-box;
  cursor: pointer;
  overflow: hidden;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.fish-area-icon:nth-child(4) {
  grid-column: 2 / span 2;
}

.fish-area-icon:nth-child(5) {
  grid-column: 4 / span 2;
}

.fish-area-icon:hover {
  background: #10275a;
  border-color: #5aaeff;
  transform: translateY(-2px);
}

.fish-area-icon img {
  display: block;

  max-width: 115px;
  max-height: 115px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.fish-area-name {
  width: 100%;

  margin-top: -5px;
  padding: 0;

  color: #4f8cff;
  font-size: 18px;
  font-weight: bold;
  line-height: 1;

  text-align: center;
  white-space: normal;
  overflow-wrap: anywhere;
}

.fish-area-icon.entry-active {
  background: #17346b;
  border-color: #5aaeff;
}

/* ===== Selected fish group ===== */

.fish-group {
  display: none;
}

.fish-group-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;

  margin-bottom: 18px;
}

.fish-group-title {
  color: #4f8cff;
  font-size: 28px;
  font-weight: bold;
}

.fish-group-back {
  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;

  box-sizing: border-box;
  cursor: pointer;

  transition: background 0.15s ease;
}

.fish-group-back:hover {
  background: #1f4388;
}

/* ===== Entry cards ===== */

.entries-grid {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-content: flex-start;
  gap: 12px;
}

.entry-card {
  position: relative;

  width: 130px;
  height: 150px;
  padding: 10px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 18px;

  text-align: center;

  box-sizing: border-box;
  overflow: visible;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.entry-card:hover {
  background: #10275a;
  border-color: #5aaeff;
  transform: translateY(-2px);
}

.entry-card img {
  display: block;

  max-width: 100px;
  max-height: 100px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.entry-card-name {
  margin-top: -30px;

  font-size: 16px;
  font-weight: bold;
  line-height: 1;

  overflow-wrap: anywhere;
}

.entry-card-items {
  border-color: #5aaeff;
}

.entry-card-tools {
  border-color: #69e8f4;
}

.entry-card-enchants {
  border-color: #9666ff;
}

/* ===== Entry detail page ===== */

.entry-detail-panel {
  display: none;

  position: absolute;
  inset: 0;
  z-index: 50;

  padding: 24px;
  overflow-y: auto;

  background: #0b0f17;
  border-radius: 20px;

  box-sizing: border-box;
}

.entry-detail-top {
  display: grid;
  grid-template-columns: 160px minmax(0, 1fr) 120px;
  align-items: center;
  gap: 20px;
}

.entry-detail-image {
  text-align: left;
}

.entry-detail-image img {
  display: block;

  max-width: 140px;
  max-height: 140px;
  width: auto;
  height: auto;
}

.entry-detail-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  min-width: 0;
}

.entry-detail-name {
  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  line-height: 1.05;
  text-align: center;

  overflow-wrap: anywhere;
}

.entry-detail-rarity {
  text-align: center;
}

.entry-rarity-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 6px;

  padding: 8px 16px;

  background: #0b0f17;
  border: 2px solid #222831;
  border-radius: 999px;

  color: #ffffff;
  font-weight: bold;
  line-height: 1;
}

.entry-rarity-stars {
  display: inline-block;
  letter-spacing: 1px;
}

.entry-detail-back {
  justify-self: end;
  display: inline-block;

  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;
  text-decoration: none;

  box-sizing: border-box;
  cursor: pointer;

  transition: background 0.15s ease;
}

.entry-detail-back:hover {
  background: #1f4388;
}

/* ===== Chance and cost ===== */

.entry-detail-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;

  margin-top: 24px;
  margin-bottom: 18px;
}

.entry-detail-stat {
  min-width: 0;
  padding: 14px 16px;

  background: #07122b;
  border: 2px solid #263a63;
  border-radius: 14px;

  box-sizing: border-box;
}

.entry-detail-stat-label {
  margin-bottom: 6px;

  color: #7eb5ff;
  font-size: 14px;
  font-weight: bold;
  letter-spacing: 0.06em;
  line-height: 1;
  text-transform: uppercase;
}

.entry-detail-stat-value {
  color: #ffffff;
  font-size: 19px;
  font-weight: bold;
  line-height: 1.25;

  overflow-wrap: anywhere;
}

.entry-detail-stat-chance {
  border-color: #5aaeff;
}

.entry-detail-stat-cost {
  border-color: #69e8f4;
}

.entry-detail-body {
  margin-top: 18px;
  padding: 16px;

  background: rgba(7, 18, 43, 0.55);
  border: 1px solid #222831;
  border-radius: 14px;

  color: #ffffff;
  font-size: 18px;
  line-height: 1.45;

  box-sizing: border-box;
  overflow-wrap: anywhere;
}

/* ===== Active states ===== */

.js-entry-open {
  cursor: pointer;
}

.entry-side-pill.entry-active,
.entry-subtab.entry-active {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Rarity name animations ===== */

.entry-name-rarity-common {
  animation: fish-common-name 2s ease-in-out infinite;
}

@keyframes fish-common-name {
  0%,
  100% {
    color: #a8b1b6;
  }

  50% {
    color: #7f8c99;
  }
}

.entry-name-rarity-uncommon {
  animation: fish-uncommon-name 2s ease-in-out infinite;
}

@keyframes fish-uncommon-name {
  0%,
  100% {
    color: #67ec88;
  }

  50% {
    color: #63c138;
  }
}

.entry-name-rarity-rare {
  animation: fish-rare-name 2s ease-in-out infinite;
}

@keyframes fish-rare-name {
  0%,
  100% {
    color: #4ad8ff;
  }

  50% {
    color: #3d93fc;
  }
}

.entry-name-rarity-epic {
  animation: fish-epic-name 2s ease-in-out infinite;
}

@keyframes fish-epic-name {
  0%,
  100% {
    color: #7843ff;
  }

  50% {
    color: #7246a7;
  }
}

.entry-name-rarity-legendary {
  animation: fish-legendary-name 2s ease-in-out infinite;
}

@keyframes fish-legendary-name {
  0%,
  100% {
    color: #ffe669;
  }

  50% {
    color: #fc932a;
  }
}

.entry-name-rarity-mythic {
  animation: fish-mythic-name 2s ease-in-out infinite;
}

@keyframes fish-mythic-name {
  0%,
  100% {
    color: #ff3045;
  }

  50% {
    color: #b11156;
  }
}

/* ===== Rarity border animations ===== */

.entry-card-rarity-none {
  border-color: #5aaeff;
}

.entry-card-rarity-common {
  animation: fish-common-border 2s ease-in-out infinite;
}

@keyframes fish-common-border {
  0%,
  100% {
    border-color: #a8b1b6;
    box-shadow: 0 0 6px #a8b1b6;
  }

  50% {
    border-color: #7f8c99;
    box-shadow: 0 0 10px #7f8c99;
  }
}

.entry-card-rarity-uncommon {
  animation: fish-uncommon-border 2s ease-in-out infinite;
}

@keyframes fish-uncommon-border {
  0%,
  100% {
    border-color: #67ec88;
    box-shadow: 0 0 6px #67ec88;
  }

  50% {
    border-color: #63c138;
    box-shadow: 0 0 10px #63c138;
  }
}

.entry-card-rarity-rare {
  animation: fish-rare-border 2s ease-in-out infinite;
}

@keyframes fish-rare-border {
  0%,
  100% {
    border-color: #4ad8ff;
    box-shadow: 0 0 6px #4ad8ff;
  }

  50% {
    border-color: #3d93fc;
    box-shadow: 0 0 10px #3d93fc;
  }
}

.entry-card-rarity-epic {
  animation: fish-epic-border 2s ease-in-out infinite;
}

@keyframes fish-epic-border {
  0%,
  100% {
    border-color: #7843ff;
    box-shadow: 0 0 6px #7843ff;
  }

  50% {
    border-color: #7246a7;
    box-shadow: 0 0 10px #7246a7;
  }
}

.entry-card-rarity-legendary {
  animation: fish-legendary-border 2s ease-in-out infinite;
}

@keyframes fish-legendary-border {
  0%,
  100% {
    border-color: #ffe669;
    box-shadow: 0 0 6px #ffe669;
  }

  50% {
    border-color: #fc932a;
    box-shadow: 0 0 10px #fc932a;
  }
}

.entry-card-rarity-mythic {
  animation: fish-mythic-border 2s ease-in-out infinite;
}

@keyframes fish-mythic-border {
  0%,
  100% {
    border-color: #ff3045;
    box-shadow: 0 0 6px #ff3045;
  }

  50% {
    border-color: #b11156;
    box-shadow: 0 0 12px #b11156;
  }
}

/* ===== Tablet ===== */

@media (max-width: 900px) {
  .entry-choice-box {
    gap: 18px;
    padding: 18px;
  }

  .entry-choice-pill {
    width: 250px;
    height: 240px;
    flex-basis: 250px;
  }

  .entry-choice-pill img {
    max-width: 165px;
    max-height: 165px;
  }

  .entry-choice-text {
    font-size: 38px;
  }

  .entry-library {
    padding: 18px;
    gap: 18px;
  }

  .entry-side {
    width: 155px;
    flex-basis: 155px;
    gap: 14px;
  }

  .entry-side-pill {
    width: 145px;
    min-height: 120px;
    font-size: 20px;
  }

  .entry-side-pill img {
    max-width: 68px;
    max-height: 68px;
  }

  .entry-content {
    padding: 18px;
  }

  .entry-content-title {
    font-size: 36px;
  }

  .fish-area-menu {
    grid-template-columns: repeat(6, 75px);
    column-gap: 10px;
    row-gap: 12px;
  }

  .fish-area-icon {
    width: 160px;
    height: 160px;
  }

  .fish-area-icon img {
    max-width: 100px;
    max-height: 100px;
  }

  .entry-detail-top {
    grid-template-columns: 130px minmax(0, 1fr) 90px;
    gap: 14px;
  }

  .entry-detail-image img {
    max-width: 115px;
    max-height: 115px;
  }

  .entry-detail-name {
    font-size: 34px;
  }
}

/* ===== Mobile ===== */

@media (max-width: 650px) {
  .entry-ui {
    max-width: 100%;
  }

  .entry-choice-box {
    min-height: 0;
    padding: 14px;
    gap: 14px;
  }

  .entry-choice-pill {
    width: 100%;
    max-width: 290px;
    height: 220px;
    flex: 1 1 100%;
  }

  .entry-choice-pill img {
    max-width: 145px;
    max-height: 145px;
  }

  .entry-choice-text {
    font-size: 34px;
  }

  .entry-library {
    min-height: 0;
    padding: 12px;
    gap: 12px;

    flex-direction: column;
  }

  .entry-side {
    width: 100%;
    flex: 0 0 auto;

    flex-direction: row;
    align-self: auto;
    gap: 8px;
  }

  .entry-side-pill {
    width: auto;
    min-width: 0;
    min-height: 92px;
    flex: 1;

    padding: 8px 4px;

    border-width: 3px;
    border-radius: 16px;

    font-size: 14px;
  }

  .entry-side-pill img {
    max-width: 48px;
    max-height: 48px;
  }

  .entry-content {
    min-height: 500px;
    padding: 14px;

    border-radius: 18px;
  }

  .entry-content-title {
    margin-bottom: 14px;

    font-size: 30px;
  }

  .entry-subtabs {
    gap: 8px;
    margin-bottom: 14px;
  }

  .entry-subtab {
    padding: 7px 13px;

    border-width: 2px;
    font-size: 18px;
  }

  /* Mobile: 2 + 2 + 1 centred */

  .fish-area-menu {
    grid-template-columns: repeat(2, minmax(0, 135px));
    justify-content: center;
    column-gap: 10px;
    row-gap: 10px;
  }

  .fish-area-icon,
  .fish-area-icon:nth-child(4),
  .fish-area-icon:nth-child(5) {
    width: 135px;
    height: 135px;
    grid-column: auto;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 1 / -1;
    justify-self: center;
  }

  .fish-area-icon img {
    max-width: 82px;
    max-height: 82px;
  }

  .fish-area-name {
    margin-top: -2px;

    font-size: 15px;
  }

  .entries-grid {
    gap: 9px;
  }

  .entry-card {
    width: 112px;
    height: 134px;
    padding: 8px;

    border-radius: 15px;
  }

  .entry-card img {
    max-width: 86px;
    max-height: 86px;
  }

  .entry-card-name {
    margin-top: -24px;

    font-size: 14px;
  }

  .entry-detail-panel {
    padding: 16px;

    border-radius: 14px;
  }

  .entry-detail-top {
    grid-template-columns: 84px minmax(0, 1fr);
    gap: 12px;
  }

  .entry-detail-image img {
    max-width: 78px;
    max-height: 78px;
  }

  .entry-detail-header {
    align-items: flex-start;
  }

  .entry-detail-name {
    font-size: 27px;
    text-align: left;
  }

  .entry-detail-rarity {
    text-align: left;
  }

  .entry-rarity-pill {
    padding: 6px 10px;

    font-size: 13px;
  }

  .entry-detail-back {
    grid-column: 1 / -1;
    justify-self: stretch;

    text-align: center;
  }

  .entry-detail-stats {
    grid-template-columns: 1fr;
    gap: 9px;

    margin-top: 18px;
  }

  .entry-detail-stat {
    padding: 12px;
  }

  .entry-detail-stat-value {
    font-size: 17px;
  }

  .entry-detail-body {
    padding: 13px;

    font-size: 16px;
  }
}

/* ===== Very small screens ===== */

@media (max-width: 360px) {
  .fish-area-menu {
    grid-template-columns: repeat(2, minmax(0, 118px));
  }

  .fish-area-icon,
  .fish-area-icon:nth-child(4),
  .fish-area-icon:nth-child(5) {
    width: 118px;
    height: 125px;
  }

  .fish-area-icon img {
    max-width: 72px;
    max-height: 72px;
  }

  .entry-card {
    width: 104px;
  }
}
/* ===== Compact fish-area menu ===== */

.entry-library-items.entry-fish-menu-open {
  min-height: 0 !important;
  height: auto !important;

  align-items: flex-start !important;

  padding-bottom: 12px !important;
}

.entry-library-items.entry-fish-menu-open .entry-side {
  align-self: flex-start !important;
  height: auto !important;
}

.entry-library-items.entry-fish-menu-open .entry-side-pill {
  flex: 0 0 135px !important;

  height: 135px !important;
  min-height: 135px !important;
}

.entry-library-items.entry-fish-menu-open .entry-content {
  min-height: 0 !important;
  height: auto !important;

  align-self: flex-start !important;

  padding-bottom: 12px !important;
}

.entry-library-items.entry-fish-menu-open .entry-subcontent-fish,
.entry-library-items.entry-fish-menu-open .fish-area-menu {
  margin-bottom: 0 !important;
  padding-bottom: 0 !important;
}

/* ===== Tablet ===== */

@media (max-width: 900px) {
  .entry-library-items.entry-fish-menu-open {
    padding-bottom: 10px !important;
  }

  .entry-library-items.entry-fish-menu-open .entry-side-pill {
    flex: 0 0 120px !important;

    height: 120px !important;
    min-height: 120px !important;
  }

  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0 !important;
    padding-bottom: 10px !important;
  }
}

/* ===== Mobile ===== */

@media (max-width: 650px) {
  .entry-library-items.entry-fish-menu-open {
    align-items: stretch !important;

    padding-bottom: 8px !important;
  }

  .entry-library-items.entry-fish-menu-open .entry-side {
    align-self: auto !important;
    height: auto !important;
  }

  .entry-library-items.entry-fish-menu-open .entry-side-pill {
    width: auto !important;
    min-width: 0 !important;

    flex: 1 1 0 !important;

    height: 92px !important;
    min-height: 92px !important;
  }

  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0 !important;
    height: auto !important;

    align-self: auto !important;

    padding-bottom: 8px !important;
  }
}

.entry-ui {
  width: 100%;
  max-width: 1075px;
  margin: 0 auto;
  box-sizing: border-box;
}

/* ===== Main category selection ===== */

.entry-choice-box {
  display: flex;
  flex-flow: row wrap;
  justify-content: center;
  align-items: center;
  gap: 28px;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;
  box-sizing: border-box;
}

.entry-choice-pill {
  width: 320px;
  height: 300px;
  flex: 0 0 320px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 26px;

  text-align: center;
  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.entry-choice-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
  transform: translateY(-2px);
}

.entry-choice-pill img {
  display: block;

  max-width: 220px;
  max-height: 220px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.entry-choice-text {
  display: block;

  color: #4f8cff;
  font-size: 50px;
  font-weight: bold;
  line-height: 1;
  white-space: nowrap;
}

/* ===== Entry library ===== */

.entry-library {
  display: none;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;
  gap: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

/* ===== Left navigation ===== */

.entry-side {
  width: 190px;
  flex: 0 0 190px;

  display: flex;
  flex-direction: column;
  align-self: stretch;
  gap: 18px;
}

.entry-side-pill {
  width: 170px;
  min-height: 135px;
  flex: 1;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  color: #4f8cff;
  font-size: 24px;
  font-weight: bold;
  line-height: 1;
  text-align: center;

  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

.entry-side-pill img {
  display: block;

  max-width: 80px;
  max-height: 80px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.entry-side-pill div {
  margin-top: 0;
}

.entry-side-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Main content ===== */

.entry-content {
  position: relative;
  overflow: hidden;

  flex: 1;
  min-width: 0;
  min-height: 430px;
  padding: 24px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

.entry-content-title {
  margin-bottom: 20px;

  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  line-height: 1.1;
}

/* ===== Item subtabs ===== */

.entry-subtabs {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;

  margin-bottom: 20px;
}

.entry-subtab {
  padding: 8px 18px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 999px;

  color: #4f8cff;
  font-size: 22px;
  font-weight: bold;

  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

.entry-subtab:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-subcontent {
  display: none;
}

/* ===== Five fish-area buttons ===== */
/* Desktop layout: 3 on top and 2 centred below */

.fish-area-menu {
  display: none;

  width: 100%;

  grid-template-columns: repeat(6, 83px);
  justify-content: center;
  column-gap: 14px;
  row-gap: 14px;

  margin: 0;
  padding: 0;

  box-sizing: border-box;
}

.fish-area-icon {
  width: 180px;
  height: 180px;
  min-width: 0;
  grid-column: span 2;

  padding: 10px 8px 6px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 22px;

  text-align: center;
  box-sizing: border-box;
  cursor: pointer;
  overflow: hidden;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.fish-area-icon:nth-child(4) {
  grid-column: 2 / span 2;
}

.fish-area-icon:nth-child(5) {
  grid-column: 4 / span 2;
}

.fish-area-icon:hover {
  background: #10275a;
  border-color: #5aaeff;
  transform: translateY(-2px);
}

.fish-area-icon img {
  display: block;

  max-width: 115px;
  max-height: 115px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.fish-area-name {
  width: 100%;

  margin-top: -5px;
  padding: 0;

  color: #4f8cff;
  font-size: 18px;
  font-weight: bold;
  line-height: 1;

  text-align: center;
  white-space: normal;
  overflow-wrap: anywhere;
}

.fish-area-icon.entry-active {
  background: #17346b;
  border-color: #5aaeff;
}

/* ===== Selected fish group ===== */

.fish-group {
  display: none;
}

.fish-group-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;

  margin-bottom: 18px;
}

.fish-group-title {
  color: #4f8cff;
  font-size: 28px;
  font-weight: bold;
}

.fish-group-back {
  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;

  box-sizing: border-box;
  cursor: pointer;

  transition: background 0.15s ease;
}

.fish-group-back:hover {
  background: #1f4388;
}

/* ===== Entry cards ===== */

.entries-grid {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-content: flex-start;
  gap: 12px;
}

.entry-card {
  position: relative;

  width: 130px;
  height: 150px;
  padding: 10px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 18px;

  text-align: center;

  box-sizing: border-box;
  overflow: visible;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.entry-card:hover {
  background: #10275a;
  border-color: #5aaeff;
  transform: translateY(-2px);
}

.entry-card img {
  display: block;

  max-width: 100px;
  max-height: 100px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.entry-card-name {
  margin-top: -30px;

  font-size: 16px;
  font-weight: bold;
  line-height: 1;

  overflow-wrap: anywhere;
}

.entry-card-items {
  border-color: #5aaeff;
}

.entry-card-tools {
  border-color: #69e8f4;
}

.entry-card-enchants {
  border-color: #9666ff;
}

/* ===== Entry detail page ===== */

.entry-detail-panel {
  display: none;

  position: absolute;
  inset: 0;
  z-index: 50;

  padding: 24px;
  overflow-y: auto;

  background: #0b0f17;
  border-radius: 20px;

  box-sizing: border-box;
}

.entry-detail-top {
  display: grid;
  grid-template-columns: 160px minmax(0, 1fr) 120px;
  align-items: center;
  gap: 20px;
}

.entry-detail-image {
  text-align: left;
}

.entry-detail-image img {
  display: block;

  max-width: 140px;
  max-height: 140px;
  width: auto;
  height: auto;
}

.entry-detail-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  min-width: 0;
}

.entry-detail-name {
  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  line-height: 1.05;
  text-align: center;

  overflow-wrap: anywhere;
}

.entry-detail-rarity {
  text-align: center;
}

.entry-rarity-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 6px;

  padding: 8px 16px;

  background: #0b0f17;
  border: 2px solid #222831;
  border-radius: 999px;

  color: #ffffff;
  font-weight: bold;
  line-height: 1;
}

.entry-rarity-stars {
  display: inline-block;
  letter-spacing: 1px;
}

.entry-detail-back {
  justify-self: end;
  display: inline-block;

  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;
  text-decoration: none;

  box-sizing: border-box;
  cursor: pointer;

  transition: background 0.15s ease;
}

.entry-detail-back:hover {
  background: #1f4388;
}

/* ===== Chance and cost ===== */

.entry-detail-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;

  margin-top: 24px;
  margin-bottom: 18px;
}

.entry-detail-stat {
  min-width: 0;
  padding: 14px 16px;

  background: #07122b;
  border: 2px solid #263a63;
  border-radius: 14px;

  box-sizing: border-box;
}

.entry-detail-stat-label {
  margin-bottom: 6px;

  color: #7eb5ff;
  font-size: 14px;
  font-weight: bold;
  letter-spacing: 0.06em;
  line-height: 1;
  text-transform: uppercase;
}

.entry-detail-stat-value {
  color: #ffffff;
  font-size: 19px;
  font-weight: bold;
  line-height: 1.25;

  overflow-wrap: anywhere;
}

.entry-detail-stat-chance {
  border-color: #5aaeff;
}

.entry-detail-stat-cost {
  border-color: #69e8f4;
}

.entry-detail-body {
  margin-top: 18px;
  padding: 16px;

  background: rgba(7, 18, 43, 0.55);
  border: 1px solid #222831;
  border-radius: 14px;

  color: #ffffff;
  font-size: 18px;
  line-height: 1.45;

  box-sizing: border-box;
  overflow-wrap: anywhere;
}

/* ===== Active states ===== */

.js-entry-open {
  cursor: pointer;
}

.entry-side-pill.entry-active,
.entry-subtab.entry-active {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Rarity name animations ===== */

.entry-name-rarity-common {
  animation: fish-common-name 2s ease-in-out infinite;
}

@keyframes fish-common-name {
  0%,
  100% {
    color: #a8b1b6;
  }

  50% {
    color: #7f8c99;
  }
}

.entry-name-rarity-uncommon {
  animation: fish-uncommon-name 2s ease-in-out infinite;
}

@keyframes fish-uncommon-name {
  0%,
  100% {
    color: #67ec88;
  }

  50% {
    color: #63c138;
  }
}

.entry-name-rarity-rare {
  animation: fish-rare-name 2s ease-in-out infinite;
}

@keyframes fish-rare-name {
  0%,
  100% {
    color: #4ad8ff;
  }

  50% {
    color: #3d93fc;
  }
}

.entry-name-rarity-epic {
  animation: fish-epic-name 2s ease-in-out infinite;
}

@keyframes fish-epic-name {
  0%,
  100% {
    color: #7843ff;
  }

  50% {
    color: #7246a7;
  }
}

.entry-name-rarity-legendary {
  animation: fish-legendary-name 2s ease-in-out infinite;
}

@keyframes fish-legendary-name {
  0%,
  100% {
    color: #ffe669;
  }

  50% {
    color: #fc932a;
  }
}

.entry-name-rarity-mythic {
  animation: fish-mythic-name 2s ease-in-out infinite;
}

@keyframes fish-mythic-name {
  0%,
  100% {
    color: #ff3045;
  }

  50% {
    color: #b11156;
  }
}

/* ===== Rarity border animations ===== */

.entry-card-rarity-none {
  border-color: #5aaeff;
}

.entry-card-rarity-common {
  animation: fish-common-border 2s ease-in-out infinite;
}

@keyframes fish-common-border {
  0%,
  100% {
    border-color: #a8b1b6;
    box-shadow: 0 0 6px #a8b1b6;
  }

  50% {
    border-color: #7f8c99;
    box-shadow: 0 0 10px #7f8c99;
  }
}

.entry-card-rarity-uncommon {
  animation: fish-uncommon-border 2s ease-in-out infinite;
}

@keyframes fish-uncommon-border {
  0%,
  100% {
    border-color: #67ec88;
    box-shadow: 0 0 6px #67ec88;
  }

  50% {
    border-color: #63c138;
    box-shadow: 0 0 10px #63c138;
  }
}

.entry-card-rarity-rare {
  animation: fish-rare-border 2s ease-in-out infinite;
}

@keyframes fish-rare-border {
  0%,
  100% {
    border-color: #4ad8ff;
    box-shadow: 0 0 6px #4ad8ff;
  }

  50% {
    border-color: #3d93fc;
    box-shadow: 0 0 10px #3d93fc;
  }
}

.entry-card-rarity-epic {
  animation: fish-epic-border 2s ease-in-out infinite;
}

@keyframes fish-epic-border {
  0%,
  100% {
    border-color: #7843ff;
    box-shadow: 0 0 6px #7843ff;
  }

  50% {
    border-color: #7246a7;
    box-shadow: 0 0 10px #7246a7;
  }
}

.entry-card-rarity-legendary {
  animation: fish-legendary-border 2s ease-in-out infinite;
}

@keyframes fish-legendary-border {
  0%,
  100% {
    border-color: #ffe669;
    box-shadow: 0 0 6px #ffe669;
  }

  50% {
    border-color: #fc932a;
    box-shadow: 0 0 10px #fc932a;
  }
}

.entry-card-rarity-mythic {
  animation: fish-mythic-border 2s ease-in-out infinite;
}

@keyframes fish-mythic-border {
  0%,
  100% {
    border-color: #ff3045;
    box-shadow: 0 0 6px #ff3045;
  }

  50% {
    border-color: #b11156;
    box-shadow: 0 0 12px #b11156;
  }
}

/* ===== Tablet ===== */

@media (max-width: 900px) {
  .entry-choice-box {
    gap: 18px;
    padding: 18px;
  }

  .entry-choice-pill {
    width: 250px;
    height: 240px;
    flex-basis: 250px;
  }

  .entry-choice-pill img {
    max-width: 165px;
    max-height: 165px;
  }

  .entry-choice-text {
    font-size: 38px;
  }

  .entry-library {
    padding: 18px;
    gap: 18px;
  }

  .entry-side {
    width: 155px;
    flex-basis: 155px;
    gap: 14px;
  }

  .entry-side-pill {
    width: 145px;
    min-height: 120px;
    font-size: 20px;
  }

  .entry-side-pill img {
    max-width: 68px;
    max-height: 68px;
  }

  .entry-content {
    padding: 18px;
  }

  .entry-content-title {
    font-size: 36px;
  }

  .fish-area-menu {
    grid-template-columns: repeat(6, 75px);
    column-gap: 10px;
    row-gap: 12px;
  }

  .fish-area-icon {
    width: 160px;
    height: 160px;
  }

  .fish-area-icon img {
    max-width: 100px;
    max-height: 100px;
  }

  .entry-detail-top {
    grid-template-columns: 130px minmax(0, 1fr) 90px;
    gap: 14px;
  }

  .entry-detail-image img {
    max-width: 115px;
    max-height: 115px;
  }

  .entry-detail-name {
    font-size: 34px;
  }
}

/* ===== Mobile ===== */

@media (max-width: 650px) {
  .entry-ui {
    max-width: 100%;
  }

  .entry-choice-box {
    min-height: 0;
    padding: 14px;
    gap: 14px;
  }

  .entry-choice-pill {
    width: 100%;
    max-width: 290px;
    height: 220px;
    flex: 1 1 100%;
  }

  .entry-choice-pill img {
    max-width: 145px;
    max-height: 145px;
  }

  .entry-choice-text {
    font-size: 34px;
  }

  .entry-library {
    min-height: 0;
    padding: 12px;
    gap: 12px;

    flex-direction: column;
  }

  .entry-side {
    width: 100%;
    flex: 0 0 auto;

    flex-direction: row;
    align-self: auto;
    gap: 8px;
  }

  .entry-side-pill {
    width: auto;
    min-width: 0;
    min-height: 92px;
    flex: 1;

    padding: 8px 4px;

    border-width: 3px;
    border-radius: 16px;

    font-size: 14px;
  }

  .entry-side-pill img {
    max-width: 48px;
    max-height: 48px;
  }

  .entry-content {
    min-height: 500px;
    padding: 14px;

    border-radius: 18px;
  }

  .entry-content-title {
    margin-bottom: 14px;

    font-size: 30px;
  }

  .entry-subtabs {
    gap: 8px;
    margin-bottom: 14px;
  }

  .entry-subtab {
    padding: 7px 13px;

    border-width: 2px;
    font-size: 18px;
  }

  /* Mobile: 2 + 2 + 1 centred */

  .fish-area-menu {
    grid-template-columns: repeat(2, minmax(0, 135px));
    justify-content: center;
    column-gap: 10px;
    row-gap: 10px;
  }

  .fish-area-icon,
  .fish-area-icon:nth-child(4),
  .fish-area-icon:nth-child(5) {
    width: 135px;
    height: 135px;
    grid-column: auto;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 1 / -1;
    justify-self: center;
  }

  .fish-area-icon img {
    max-width: 82px;
    max-height: 82px;
  }

  .fish-area-name {
    margin-top: -2px;

    font-size: 15px;
  }

  .entries-grid {
    gap: 9px;
  }

  .entry-card {
    width: 112px;
    height: 134px;
    padding: 8px;

    border-radius: 15px;
  }

  .entry-card img {
    max-width: 86px;
    max-height: 86px;
  }

  .entry-card-name {
    margin-top: -24px;

    font-size: 14px;
  }

  .entry-detail-panel {
    padding: 16px;

    border-radius: 14px;
  }

  .entry-detail-top {
    grid-template-columns: 84px minmax(0, 1fr);
    gap: 12px;
  }

  .entry-detail-image img {
    max-width: 78px;
    max-height: 78px;
  }

  .entry-detail-header {
    align-items: flex-start;
  }

  .entry-detail-name {
    font-size: 27px;
    text-align: left;
  }

  .entry-detail-rarity {
    text-align: left;
  }

  .entry-rarity-pill {
    padding: 6px 10px;

    font-size: 13px;
  }

  .entry-detail-back {
    grid-column: 1 / -1;
    justify-self: stretch;

    text-align: center;
  }

  .entry-detail-stats {
    grid-template-columns: 1fr;
    gap: 9px;

    margin-top: 18px;
  }

  .entry-detail-stat {
    padding: 12px;
  }

  .entry-detail-stat-value {
    font-size: 17px;
  }

  .entry-detail-body {
    padding: 13px;

    font-size: 16px;
  }
}

/* ===== Very small screens ===== */

@media (max-width: 360px) {
  .fish-area-menu {
    grid-template-columns: repeat(2, minmax(0, 118px));
  }

  .fish-area-icon,
  .fish-area-icon:nth-child(4),
  .fish-area-icon:nth-child(5) {
    width: 118px;
    height: 125px;
  }

  .fish-area-icon img {
    max-width: 72px;
    max-height: 72px;
  }

  .entry-card {
    width: 104px;
  }
}
/* ===== Compact fish-area menu ===== */
/* Keep this at the absolute bottom of the stylesheet. */

.entry-library-items.entry-fish-menu-open {
  min-height: 0 !important;
  height: fit-content !important;

  align-items: flex-start !important;

  padding-bottom: 12px !important;
}

.entry-library-items.entry-fish-menu-open .entry-side {
  align-self: flex-start !important;

  height: fit-content !important;
  min-height: 0 !important;
}

.entry-library-items.entry-fish-menu-open .entry-side-pill {
  flex: 0 0 135px !important;

  width: 170px !important;
  height: 135px !important;
  min-height: 135px !important;
}

.entry-library-items.entry-fish-menu-open .entry-content {
  flex: 1 1 0 !important;

  min-height: 0 !important;
  height: fit-content !important;

  align-self: flex-start !important;

  padding-bottom: 14px !important;
}

.entry-library-items.entry-fish-menu-open .entry-subcontent-fish {
  min-height: 0 !important;
  height: fit-content !important;

  margin: 0 !important;
  padding: 0 !important;
}

.entry-library-items.entry-fish-menu-open .fish-area-menu {
  min-height: 0 !important;
  height: fit-content !important;

  margin: 0 !important;
  padding: 0 !important;
}

/* ===== Tablet ===== */

@media (max-width: 900px) {
  .entry-library-items.entry-fish-menu-open {
    height: fit-content !important;
    padding-bottom: 10px !important;
  }

  .entry-library-items.entry-fish-menu-open .entry-side-pill {
    flex: 0 0 120px !important;

    width: 145px !important;
    height: 120px !important;
    min-height: 120px !important;
  }

  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0 !important;
    height: fit-content !important;

    padding-bottom: 12px !important;
  }
}

/* ===== Mobile ===== */

@media (max-width: 650px) {
  .entry-library-items.entry-fish-menu-open {
    height: fit-content !important;

    align-items: stretch !important;

    padding-bottom: 8px !important;
  }

  .entry-library-items.entry-fish-menu-open .entry-side {
    width: 100% !important;
    height: fit-content !important;

    align-self: auto !important;
  }

  .entry-library-items.entry-fish-menu-open .entry-side-pill {
    width: auto !important;
    min-width: 0 !important;

    flex: 1 1 0 !important;

    height: 92px !important;
    min-height: 92px !important;
  }

  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0 !important;
    height: fit-content !important;

    align-self: auto !important;

    padding-bottom: 10px !important;
  }
}

.entry-ui {
  width: 100%;
  max-width: 1075px;
  margin: 0 auto;
  box-sizing: border-box;
}

/* ===== Main category selection ===== */

.entry-choice-box {
  display: flex;
  flex-flow: row wrap;
  justify-content: center;
  align-items: center;
  gap: 28px;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;

  background: #07122b;
  border: 41px solid #222831;
  border-radius: 24px;
  box-sizing: border-box;
}

.entry-choice-pill {
  width: 320px;
  height: 300px;
  flex: 0 0 320px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 26px;

  text-align: center;
  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.entry-choice-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
  transform: translateY(-2px);
}

.entry-choice-pill img {
  display: block;

  max-width: 220px;
  max-height: 220px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.entry-choice-text {
  display: block;

  color: #4f8cff;
  font-size: 50px;
  font-weight: bold;
  line-height: 1;
  white-space: nowrap;
}

/* ===== Entry library ===== */

.entry-library {
  display: none;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;
  gap: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

/* ===== Left navigation ===== */

.entry-side {
  width: 190px;
  flex: 0 0 190px;

  display: flex;
  flex-direction: column;
  align-self: stretch;
  gap: 18px;
}

.entry-side-pill {
  width: 170px;
  min-height: 135px;
  flex: 1;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  color: #4f8cff;
  font-size: 24px;
  font-weight: bold;
  line-height: 1;
  text-align: center;

  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

.entry-side-pill img {
  display: block;

  max-width: 80px;
  max-height: 80px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.entry-side-pill div {
  margin-top: 0;
}

.entry-side-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Main content ===== */

.entry-content {
  position: relative;
  overflow: hidden;

  flex: 1;
  min-width: 0;
  min-height: 430px;
  padding: 24px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

.entry-content-title {
  margin-bottom: 20px;

  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  line-height: 1.1;
}

/* ===== Item subtabs ===== */

.entry-subtabs {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;

  margin-bottom: 20px;
}

.entry-subtab {
  padding: 8px 18px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 999px;

  color: #4f8cff;
  font-size: 22px;
  font-weight: bold;

  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

.entry-subtab:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-subcontent {
  display: none;
}

/* ===== Five fish-area buttons ===== */
/* Desktop layout: 3 on top and 2 centred below */

.fish-area-menu {
  display: none;

  width: 100%;

  grid-template-columns: repeat(6, 83px);
  justify-content: center;
  column-gap: 14px;
  row-gap: 14px;

  margin: 0;
  padding: 0;

  box-sizing: border-box;
}

.fish-area-icon {
  width: 180px;
  height: 180px;
  min-width: 0;
  grid-column: span 2;

  padding: 10px 8px 6px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 22px;

  text-align: center;
  box-sizing: border-box;
  cursor: pointer;
  overflow: hidden;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.fish-area-icon:nth-child(4) {
  grid-column: 2 / span 2;
}

.fish-area-icon:nth-child(5) {
  grid-column: 4 / span 2;
}

.fish-area-icon:hover {
  background: #10275a;
  border-color: #5aaeff;
  transform: translateY(-2px);
}

.fish-area-icon img {
  display: block;

  max-width: 115px;
  max-height: 115px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.fish-area-name {
  width: 100%;

  margin-top: -5px;
  padding: 0;

  color: #4f8cff;
  font-size: 18px;
  font-weight: bold;
  line-height: 1;

  text-align: center;
  white-space: normal;
  overflow-wrap: anywhere;
}

.fish-area-icon.entry-active {
  background: #17346b;
  border-color: #5aaeff;
}

/* ===== Selected fish group ===== */

.fish-group {
  display: none;
}

.fish-group-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;

  margin-bottom: 18px;
}

.fish-group-title {
  color: #4f8cff;
  font-size: 28px;
  font-weight: bold;
}

.fish-group-back {
  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;

  box-sizing: border-box;
  cursor: pointer;

  transition: background 0.15s ease;
}

.fish-group-back:hover {
  background: #1f4388;
}

/* ===== Entry cards ===== */

.entries-grid {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-content: flex-start;
  gap: 12px;
}

.entry-card {
  position: relative;

  width: 130px;
  height: 150px;
  padding: 10px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 18px;

  text-align: center;

  box-sizing: border-box;
  overflow: visible;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.entry-card:hover {
  background: #10275a;
  border-color: #5aaeff;
  transform: translateY(-2px);
}

.entry-card img {
  display: block;

  max-width: 100px;
  max-height: 100px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.entry-card-name {
  margin-top: -30px;

  font-size: 16px;
  font-weight: bold;
  line-height: 1;

  overflow-wrap: anywhere;
}

.entry-card-items {
  border-color: #5aaeff;
}

.entry-card-tools {
  border-color: #69e8f4;
}

.entry-card-enchants {
  border-color: #9666ff;
}

/* ===== Entry detail page ===== */

.entry-detail-panel {
  display: none;

  position: absolute;
  inset: 0;
  z-index: 50;

  padding: 24px;
  overflow-y: auto;

  background: #0b0f17;
  border-radius: 20px;

  box-sizing: border-box;
}

.entry-detail-top {
  display: grid;
  grid-template-columns: 160px minmax(0, 1fr) 120px;
  align-items: center;
  gap: 20px;
}

.entry-detail-image {
  text-align: left;
}

.entry-detail-image img {
  display: block;

  max-width: 140px;
  max-height: 140px;
  width: auto;
  height: auto;
}

.entry-detail-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  min-width: 0;
}

.entry-detail-name {
  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  line-height: 1.05;
  text-align: center;

  overflow-wrap: anywhere;
}

.entry-detail-rarity {
  text-align: center;
}

.entry-rarity-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 6px;

  padding: 8px 16px;

  background: #0b0f17;
  border: 2px solid #222831;
  border-radius: 999px;

  color: #ffffff;
  font-weight: bold;
  line-height: 1;
}

.entry-rarity-stars {
  display: inline-block;
  letter-spacing: 1px;
}

.entry-detail-back {
  justify-self: end;
  display: inline-block;

  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;
  text-decoration: none;

  box-sizing: border-box;
  cursor: pointer;

  transition: background 0.15s ease;
}

.entry-detail-back:hover {
  background: #1f4388;
}

/* ===== Chance and cost ===== */

.entry-detail-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;

  margin-top: 24px;
  margin-bottom: 18px;
}

.entry-detail-stat {
  min-width: 0;
  padding: 14px 16px;

  background: #07122b;
  border: 2px solid #263a63;
  border-radius: 14px;

  box-sizing: border-box;
}

.entry-detail-stat-label {
  margin-bottom: 6px;

  color: #7eb5ff;
  font-size: 14px;
  font-weight: bold;
  letter-spacing: 0.06em;
  line-height: 1;
  text-transform: uppercase;
}

.entry-detail-stat-value {
  color: #ffffff;
  font-size: 19px;
  font-weight: bold;
  line-height: 1.25;

  overflow-wrap: anywhere;
}

.entry-detail-stat-chance {
  border-color: #5aaeff;
}

.entry-detail-stat-cost {
  border-color: #69e8f4;
}

.entry-detail-body {
  margin-top: 18px;
  padding: 16px;

  background: rgba(7, 18, 43, 0.55);
  border: 1px solid #222831;
  border-radius: 14px;

  color: #ffffff;
  font-size: 18px;
  line-height: 1.45;

  box-sizing: border-box;
  overflow-wrap: anywhere;
}

/* ===== Active states ===== */

.js-entry-open {
  cursor: pointer;
}

.entry-side-pill.entry-active,
.entry-subtab.entry-active {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Rarity name animations ===== */

.entry-name-rarity-common {
  animation: fish-common-name 2s ease-in-out infinite;
}

@keyframes fish-common-name {
  0%,
  100% {
    color: #a8b1b6;
  }

  50% {
    color: #7f8c99;
  }
}

.entry-name-rarity-uncommon {
  animation: fish-uncommon-name 2s ease-in-out infinite;
}

@keyframes fish-uncommon-name {
  0%,
  100% {
    color: #67ec88;
  }

  50% {
    color: #63c138;
  }
}

.entry-name-rarity-rare {
  animation: fish-rare-name 2s ease-in-out infinite;
}

@keyframes fish-rare-name {
  0%,
  100% {
    color: #4ad8ff;
  }

  50% {
    color: #3d93fc;
  }
}

.entry-name-rarity-epic {
  animation: fish-epic-name 2s ease-in-out infinite;
}

@keyframes fish-epic-name {
  0%,
  100% {
    color: #7843ff;
  }

  50% {
    color: #7246a7;
  }
}

.entry-name-rarity-legendary {
  animation: fish-legendary-name 2s ease-in-out infinite;
}

@keyframes fish-legendary-name {
  0%,
  100% {
    color: #ffe669;
  }

  50% {
    color: #fc932a;
  }
}

.entry-name-rarity-mythic {
  animation: fish-mythic-name 2s ease-in-out infinite;
}

@keyframes fish-mythic-name {
  0%,
  100% {
    color: #ff3045;
  }

  50% {
    color: #b11156;
  }
}

/* ===== Rarity border animations ===== */

.entry-card-rarity-none {
  border-color: #5aaeff;
}

.entry-card-rarity-common {
  animation: fish-common-border 2s ease-in-out infinite;
}

@keyframes fish-common-border {
  0%,
  100% {
    border-color: #a8b1b6;
    box-shadow: 0 0 6px #a8b1b6;
  }

  50% {
    border-color: #7f8c99;
    box-shadow: 0 0 10px #7f8c99;
  }
}

.entry-card-rarity-uncommon {
  animation: fish-uncommon-border 2s ease-in-out infinite;
}

@keyframes fish-uncommon-border {
  0%,
  100% {
    border-color: #67ec88;
    box-shadow: 0 0 6px #67ec88;
  }

  50% {
    border-color: #63c138;
    box-shadow: 0 0 10px #63c138;
  }
}

.entry-card-rarity-rare {
  animation: fish-rare-border 2s ease-in-out infinite;
}

@keyframes fish-rare-border {
  0%,
  100% {
    border-color: #4ad8ff;
    box-shadow: 0 0 6px #4ad8ff;
  }

  50% {
    border-color: #3d93fc;
    box-shadow: 0 0 10px #3d93fc;
  }
}

.entry-card-rarity-epic {
  animation: fish-epic-border 2s ease-in-out infinite;
}

@keyframes fish-epic-border {
  0%,
  100% {
    border-color: #7843ff;
    box-shadow: 0 0 6px #7843ff;
  }

  50% {
    border-color: #7246a7;
    box-shadow: 0 0 10px #7246a7;
  }
}

.entry-card-rarity-legendary {
  animation: fish-legendary-border 2s ease-in-out infinite;
}

@keyframes fish-legendary-border {
  0%,
  100% {
    border-color: #ffe669;
    box-shadow: 0 0 6px #ffe669;
  }

  50% {
    border-color: #fc932a;
    box-shadow: 0 0 10px #fc932a;
  }
}

.entry-card-rarity-mythic {
  animation: fish-mythic-border 2s ease-in-out infinite;
}

@keyframes fish-mythic-border {
  0%,
  100% {
    border-color: #ff3045;
    box-shadow: 0 0 6px #ff3045;
  }

  50% {
    border-color: #b11156;
    box-shadow: 0 0 12px #b11156;
  }
}

/* ===== Tablet ===== */

@media (max-width: 900px) {
  .entry-choice-box {
    gap: 18px;
    padding: 18px;
  }

  .entry-choice-pill {
    width: 250px;
    height: 240px;
    flex-basis: 250px;
  }

  .entry-choice-pill img {
    max-width: 165px;
    max-height: 165px;
  }

  .entry-choice-text {
    font-size: 38px;
  }

  .entry-library {
    padding: 18px;
    gap: 18px;
  }

  .entry-side {
    width: 155px;
    flex-basis: 155px;
    gap: 14px;
  }

  .entry-side-pill {
    width: 145px;
    min-height: 120px;
    font-size: 20px;
  }

  .entry-side-pill img {
    max-width: 68px;
    max-height: 68px;
  }

  .entry-content {
    padding: 18px;
  }

  .entry-content-title {
    font-size: 36px;
  }

  .fish-area-menu {
    grid-template-columns: repeat(6, 75px);
    column-gap: 10px;
    row-gap: 12px;
  }

  .fish-area-icon {
    width: 160px;
    height: 160px;
  }

  .fish-area-icon img {
    max-width: 100px;
    max-height: 100px;
  }

  .entry-detail-top {
    grid-template-columns: 130px minmax(0, 1fr) 90px;
    gap: 14px;
  }

  .entry-detail-image img {
    max-width: 115px;
    max-height: 115px;
  }

  .entry-detail-name {
    font-size: 34px;
  }
}

/* ===== Mobile ===== */

@media (max-width: 650px) {
  .entry-ui {
    max-width: 100%;
  }

  .entry-choice-box {
    min-height: 0;
    padding: 14px;
    gap: 14px;
  }

  .entry-choice-pill {
    width: 100%;
    max-width: 290px;
    height: 220px;
    flex: 1 1 100%;
  }

  .entry-choice-pill img {
    max-width: 145px;
    max-height: 145px;
  }

  .entry-choice-text {
    font-size: 34px;
  }

  .entry-library {
    min-height: 0;
    padding: 12px;
    gap: 12px;

    flex-direction: column;
  }

  .entry-side {
    width: 100%;
    flex: 0 0 auto;

    flex-direction: row;
    align-self: auto;
    gap: 8px;
  }

  .entry-side-pill {
    width: auto;
    min-width: 0;
    min-height: 92px;
    flex: 1;

    padding: 8px 4px;

    border-width: 3px;
    border-radius: 16px;

    font-size: 14px;
  }

  .entry-side-pill img {
    max-width: 48px;
    max-height: 48px;
  }

  .entry-content {
    min-height: 500px;
    padding: 14px;

    border-radius: 18px;
  }

  .entry-content-title {
    margin-bottom: 14px;

    font-size: 30px;
  }

  .entry-subtabs {
    gap: 8px;
    margin-bottom: 14px;
  }

  .entry-subtab {
    padding: 7px 13px;

    border-width: 2px;
    font-size: 18px;
  }

  /* Mobile: 2 + 2 + 1 centred */

  .fish-area-menu {
    grid-template-columns: repeat(2, minmax(0, 135px));
    justify-content: center;
    column-gap: 10px;
    row-gap: 10px;
  }

  .fish-area-icon,
  .fish-area-icon:nth-child(4),
  .fish-area-icon:nth-child(5) {
    width: 135px;
    height: 135px;
    grid-column: auto;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 1 / -1;
    justify-self: center;
  }

  .fish-area-icon img {
    max-width: 82px;
    max-height: 82px;
  }

  .fish-area-name {
    margin-top: -2px;

    font-size: 15px;
  }

  .entries-grid {
    gap: 9px;
  }

  .entry-card {
    width: 112px;
    height: 134px;
    padding: 8px;

    border-radius: 15px;
  }

  .entry-card img {
    max-width: 86px;
    max-height: 86px;
  }

  .entry-card-name {
    margin-top: -24px;

    font-size: 14px;
  }

  .entry-detail-panel {
    padding: 16px;

    border-radius: 14px;
  }

  .entry-detail-top {
    grid-template-columns: 84px minmax(0, 1fr);
    gap: 12px;
  }

  .entry-detail-image img {
    max-width: 78px;
    max-height: 78px;
  }

  .entry-detail-header {
    align-items: flex-start;
  }

  .entry-detail-name {
    font-size: 27px;
    text-align: left;
  }

  .entry-detail-rarity {
    text-align: left;
  }

  .entry-rarity-pill {
    padding: 6px 10px;

    font-size: 13px;
  }

  .entry-detail-back {
    grid-column: 1 / -1;
    justify-self: stretch;

    text-align: center;
  }

  .entry-detail-stats {
    grid-template-columns: 1fr;
    gap: 9px;

    margin-top: 18px;
  }

  .entry-detail-stat {
    padding: 12px;
  }

  .entry-detail-stat-value {
    font-size: 17px;
  }

  .entry-detail-body {
    padding: 13px;

    font-size: 16px;
  }
}

/* ===== Very small screens ===== */

@media (max-width: 360px) {
  .fish-area-menu {
    grid-template-columns: repeat(2, minmax(0, 118px));
  }

  .fish-area-icon,
  .fish-area-icon:nth-child(4),
  .fish-area-icon:nth-child(5) {
    width: 118px;
    height: 125px;
  }

  .fish-area-icon img {
    max-width: 72px;
    max-height: 72px;
  }

  .entry-card {
    width: 104px;
  }
}
/* ===== Compact fish-area menu ===== */
/* Keep this at the absolute bottom of the stylesheet. */

.entry-library-items.entry-fish-menu-open {
  min-height: 0 !important;
  height: fit-content !important;

  align-items: flex-start !important;

  padding-bottom: 12px !important;
}

.entry-library-items.entry-fish-menu-open .entry-side {
  align-self: flex-start !important;

  height: fit-content !important;
  min-height: 0 !important;
}

.entry-library-items.entry-fish-menu-open .entry-side-pill {
  flex: 0 0 135px !important;

  width: 170px !important;
  height: 135px !important;
  min-height: 135px !important;
}

.entry-library-items.entry-fish-menu-open .entry-content {
  flex: 1 1 0 !important;

  min-height: 0 !important;
  height: fit-content !important;

  align-self: flex-start !important;

  padding-bottom: 14px !important;
}

.entry-library-items.entry-fish-menu-open .entry-subcontent-fish {
  min-height: 0 !important;
  height: fit-content !important;

  margin: 0 !important;
  padding: 0 !important;
}

.entry-library-items.entry-fish-menu-open .fish-area-menu {
  min-height: 0 !important;
  height: fit-content !important;

  margin: 0 !important;
  padding: 0 !important;
}

/* ===== Tablet ===== */

@media (max-width: 900px) {
  .entry-library-items.entry-fish-menu-open {
    height: fit-content !important;
    padding-bottom: 10px !important;
  }

  .entry-library-items.entry-fish-menu-open .entry-side-pill {
    flex: 0 0 120px !important;

    width: 145px !important;
    height: 120px !important;
    min-height: 120px !important;
  }

  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0 !important;
    height: fit-content !important;

    padding-bottom: 12px !important;
  }
}

/* ===== Mobile ===== */

@media (max-width: 650px) {
  .entry-library-items.entry-fish-menu-open {
    height: fit-content !important;

    align-items: stretch !important;

    padding-bottom: 8px !important;
  }

  .entry-library-items.entry-fish-menu-open .entry-side {
    width: 100% !important;
    height: fit-content !important;

    align-self: auto !important;
  }

  .entry-library-items.entry-fish-menu-open .entry-side-pill {
    width: auto !important;
    min-width: 0 !important;

    flex: 1 1 0 !important;

    height: 92px !important;
    min-height: 92px !important;
  }

  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0 !important;
    height: fit-content !important;

    align-self: auto !important;

    padding-bottom: 10px !important;
  }
}

.entry-ui {
  width: 100%;
  max-width: 1075px;
  margin: 0 auto;
  box-sizing: border-box;
}

/* ===== Main category selection ===== */

.entry-choice-box {
  display: flex;
  flex-flow: row wrap;
  justify-content: center;
  align-items: center;
  gap: 28px;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;

  background: #07122b;
  border: 1px solid #222831;
  border-radius: 24px;
  box-sizing: border-box;
}

.entry-choice-pill {
  width: 320px;
  height: 300px;
  flex: 0 0 320px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 26px;

  text-align: center;
  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.entry-choice-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
  transform: translateY(-2px);
}

.entry-choice-pill img {
  display: block;

  max-width: 220px;
  max-height: 220px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.entry-choice-text {
  display: block;

  color: #4f8cff;
  font-size: 50px;
  font-weight: bold;
  line-height: 1;
  white-space: nowrap;
}

/* ===== Entry library ===== */

.entry-library {
  display: none;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;
  gap: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

/* ===== Left navigation ===== */

.entry-side {
  width: 190px;
  flex: 0 0 190px;

  display: flex;
  flex-direction: column;
  align-self: stretch;
  gap: 18px;
}

.entry-side-pill {
  width: 170px;
  min-height: 135px;
  flex: 1;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  color: #4f8cff;
  font-size: 24px;
  font-weight: bold;
  line-height: 1;
  text-align: center;

  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

.entry-side-pill img {
  display: block;

  max-width: 80px;
  max-height: 80px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.entry-side-pill div {
  margin-top: 0;
}

.entry-side-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Main content ===== */

.entry-content {
  position: relative;
  overflow: hidden;

  flex: 1;
  min-width: 0;
  min-height: 430px;
  padding: 24px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

.entry-content-title {
  margin-bottom: 20px;

  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  line-height: 1.1;
}

/* ===== Item subtabs ===== */

.entry-subtabs {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;

  margin-bottom: 20px;
}

.entry-subtab {
  padding: 8px 18px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 999px;

  color: #4f8cff;
  font-size: 22px;
  font-weight: bold;

  box-sizing: border-box;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

.entry-subtab:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-subcontent {
  display: none;
}

/* ===== Five fish-area buttons ===== */
/* Desktop layout: 3 on top and 2 centred below */

.fish-area-menu {
  display: none;

  width: 100%;

  grid-template-columns: repeat(6, 83px);
  justify-content: center;
  column-gap: 14px;
  row-gap: 14px;

  margin: 0;
  padding: 0;

  box-sizing: border-box;
}

.fish-area-icon {
  width: 180px;
  height: 180px;
  min-width: 0;
  grid-column: span 2;

  padding: 10px 8px 6px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 22px;

  text-align: center;
  box-sizing: border-box;
  cursor: pointer;
  overflow: hidden;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.fish-area-icon:nth-child(4) {
  grid-column: 2 / span 2;
}

.fish-area-icon:nth-child(5) {
  grid-column: 4 / span 2;
}

.fish-area-icon:hover {
  background: #10275a;
  border-color: #5aaeff;
  transform: translateY(-2px);
}

.fish-area-icon img {
  display: block;

  max-width: 115px;
  max-height: 115px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.fish-area-name {
  width: 100%;

  margin-top: -5px;
  padding: 0;

  color: #4f8cff;
  font-size: 18px;
  font-weight: bold;
  line-height: 1;

  text-align: center;
  white-space: normal;
  overflow-wrap: anywhere;
}

.fish-area-icon.entry-active {
  background: #17346b;
  border-color: #5aaeff;
}

/* ===== Selected fish group ===== */

.fish-group {
  display: none;
}

.fish-group-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;

  margin-bottom: 18px;
}

.fish-group-title {
  color: #4f8cff;
  font-size: 28px;
  font-weight: bold;
}

.fish-group-back {
  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;

  box-sizing: border-box;
  cursor: pointer;

  transition: background 0.15s ease;
}

.fish-group-back:hover {
  background: #1f4388;
}

/* ===== Entry cards ===== */

.entries-grid {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-content: flex-start;
  gap: 12px;
}

.entry-card {
  position: relative;

  width: 130px;
  height: 150px;
  padding: 10px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 18px;

  text-align: center;

  box-sizing: border-box;
  overflow: visible;
  cursor: pointer;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.entry-card:hover {
  background: #10275a;
  border-color: #5aaeff;
  transform: translateY(-2px);
}

.entry-card img {
  display: block;

  max-width: 100px;
  max-height: 100px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.entry-card-name {
  margin-top: -30px;

  font-size: 16px;
  font-weight: bold;
  line-height: 1;

  overflow-wrap: anywhere;
}

.entry-card-items {
  border-color: #5aaeff;
}

.entry-card-tools {
  border-color: #69e8f4;
}

.entry-card-enchants {
  border-color: #9666ff;
}

/* ===== Entry detail page ===== */

.entry-detail-panel {
  display: none;

  position: absolute;
  inset: 0;
  z-index: 50;

  padding: 24px;
  overflow-y: auto;

  background: #0b0f17;
  border-radius: 20px;

  box-sizing: border-box;
}

.entry-detail-top {
  display: grid;
  grid-template-columns: 160px minmax(0, 1fr) 120px;
  align-items: center;
  gap: 20px;
}

.entry-detail-image {
  text-align: left;
}

.entry-detail-image img {
  display: block;

  max-width: 140px;
  max-height: 140px;
  width: auto;
  height: auto;
}

.entry-detail-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  min-width: 0;
}

.entry-detail-name {
  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  line-height: 1.05;
  text-align: center;

  overflow-wrap: anywhere;
}

.entry-detail-rarity {
  text-align: center;
}

.entry-rarity-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 6px;

  padding: 8px 16px;

  background: #0b0f17;
  border: 2px solid #222831;
  border-radius: 999px;

  color: #ffffff;
  font-weight: bold;
  line-height: 1;
}

.entry-rarity-stars {
  display: inline-block;
  letter-spacing: 1px;
}

.entry-detail-back {
  justify-self: end;
  display: inline-block;

  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;
  text-decoration: none;

  box-sizing: border-box;
  cursor: pointer;

  transition: background 0.15s ease;
}

.entry-detail-back:hover {
  background: #1f4388;
}

/* ===== Chance and cost ===== */

.entry-detail-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;

  margin-top: 24px;
  margin-bottom: 18px;
}

.entry-detail-stat {
  min-width: 0;
  padding: 14px 16px;

  background: #07122b;
  border: 2px solid #263a63;
  border-radius: 14px;

  box-sizing: border-box;
}

.entry-detail-stat-label {
  margin-bottom: 6px;

  color: #7eb5ff;
  font-size: 14px;
  font-weight: bold;
  letter-spacing: 0.06em;
  line-height: 1;
  text-transform: uppercase;
}

.entry-detail-stat-value {
  color: #ffffff;
  font-size: 19px;
  font-weight: bold;
  line-height: 1.25;

  overflow-wrap: anywhere;
}

.entry-detail-stat-chance {
  border-color: #5aaeff;
}

.entry-detail-stat-cost {
  border-color: #69e8f4;
}

.entry-detail-body {
  margin-top: 18px;
  padding: 16px;

  background: rgba(7, 18, 43, 0.55);
  border: 1px solid #222831;
  border-radius: 14px;

  color: #ffffff;
  font-size: 18px;
  line-height: 1.45;

  box-sizing: border-box;
  overflow-wrap: anywhere;
}

/* ===== Active states ===== */

.js-entry-open {
  cursor: pointer;
}

.entry-side-pill.entry-active,
.entry-subtab.entry-active {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Rarity name animations ===== */

.entry-name-rarity-common {
  animation: fish-common-name 2s ease-in-out infinite;
}

@keyframes fish-common-name {
  0%,
  100% {
    color: #a8b1b6;
  }

  50% {
    color: #7f8c99;
  }
}

.entry-name-rarity-uncommon {
  animation: fish-uncommon-name 2s ease-in-out infinite;
}

@keyframes fish-uncommon-name {
  0%,
  100% {
    color: #67ec88;
  }

  50% {
    color: #63c138;
  }
}

.entry-name-rarity-rare {
  animation: fish-rare-name 2s ease-in-out infinite;
}

@keyframes fish-rare-name {
  0%,
  100% {
    color: #4ad8ff;
  }

  50% {
    color: #3d93fc;
  }
}

.entry-name-rarity-epic {
  animation: fish-epic-name 2s ease-in-out infinite;
}

@keyframes fish-epic-name {
  0%,
  100% {
    color: #7843ff;
  }

  50% {
    color: #7246a7;
  }
}

.entry-name-rarity-legendary {
  animation: fish-legendary-name 2s ease-in-out infinite;
}

@keyframes fish-legendary-name {
  0%,
  100% {
    color: #ffe669;
  }

  50% {
    color: #fc932a;
  }
}

.entry-name-rarity-mythic {
  animation: fish-mythic-name 2s ease-in-out infinite;
}

@keyframes fish-mythic-name {
  0%,
  100% {
    color: #ff3045;
  }

  50% {
    color: #b11156;
  }
}

/* ===== Rarity border animations ===== */

.entry-card-rarity-none {
  border-color: #5aaeff;
}

.entry-card-rarity-common {
  animation: fish-common-border 2s ease-in-out infinite;
}

@keyframes fish-common-border {
  0%,
  100% {
    border-color: #a8b1b6;
    box-shadow: 0 0 6px #a8b1b6;
  }

  50% {
    border-color: #7f8c99;
    box-shadow: 0 0 10px #7f8c99;
  }
}

.entry-card-rarity-uncommon {
  animation: fish-uncommon-border 2s ease-in-out infinite;
}

@keyframes fish-uncommon-border {
  0%,
  100% {
    border-color: #67ec88;
    box-shadow: 0 0 6px #67ec88;
  }

  50% {
    border-color: #63c138;
    box-shadow: 0 0 10px #63c138;
  }
}

.entry-card-rarity-rare {
  animation: fish-rare-border 2s ease-in-out infinite;
}

@keyframes fish-rare-border {
  0%,
  100% {
    border-color: #4ad8ff;
    box-shadow: 0 0 6px #4ad8ff;
  }

  50% {
    border-color: #3d93fc;
    box-shadow: 0 0 10px #3d93fc;
  }
}

.entry-card-rarity-epic {
  animation: fish-epic-border 2s ease-in-out infinite;
}

@keyframes fish-epic-border {
  0%,
  100% {
    border-color: #7843ff;
    box-shadow: 0 0 6px #7843ff;
  }

  50% {
    border-color: #7246a7;
    box-shadow: 0 0 10px #7246a7;
  }
}

.entry-card-rarity-legendary {
  animation: fish-legendary-border 2s ease-in-out infinite;
}

@keyframes fish-legendary-border {
  0%,
  100% {
    border-color: #ffe669;
    box-shadow: 0 0 6px #ffe669;
  }

  50% {
    border-color: #fc932a;
    box-shadow: 0 0 10px #fc932a;
  }
}

.entry-card-rarity-mythic {
  animation: fish-mythic-border 2s ease-in-out infinite;
}

@keyframes fish-mythic-border {
  0%,
  100% {
    border-color: #ff3045;
    box-shadow: 0 0 6px #ff3045;
  }

  50% {
    border-color: #b11156;
    box-shadow: 0 0 12px #b11156;
  }
}

/* ===== Tablet ===== */

@media (max-width: 900px) {
  .entry-choice-box {
    gap: 18px;
    padding: 18px;
  }

  .entry-choice-pill {
    width: 250px;
    height: 240px;
    flex-basis: 250px;
  }

  .entry-choice-pill img {
    max-width: 165px;
    max-height: 165px;
  }

  .entry-choice-text {
    font-size: 38px;
  }

  .entry-library {
    padding: 18px;
    gap: 18px;
  }

  .entry-side {
    width: 155px;
    flex-basis: 155px;
    gap: 14px;
  }

  .entry-side-pill {
    width: 145px;
    min-height: 120px;
    font-size: 20px;
  }

  .entry-side-pill img {
    max-width: 68px;
    max-height: 68px;
  }

  .entry-content {
    padding: 18px;
  }

  .entry-content-title {
    font-size: 36px;
  }

  .fish-area-menu {
    grid-template-columns: repeat(6, 75px);
    column-gap: 10px;
    row-gap: 12px;
  }

  .fish-area-icon {
    width: 160px;
    height: 160px;
  }

  .fish-area-icon img {
    max-width: 100px;
    max-height: 100px;
  }

  .entry-detail-top {
    grid-template-columns: 130px minmax(0, 1fr) 90px;
    gap: 14px;
  }

  .entry-detail-image img {
    max-width: 115px;
    max-height: 115px;
  }

  .entry-detail-name {
    font-size: 34px;
  }
}

/* ===== Mobile ===== */

@media (max-width: 650px) {
  .entry-ui {
    max-width: 100%;
  }

  .entry-choice-box {
    min-height: 0;
    padding: 14px;
    gap: 14px;
  }

  .entry-choice-pill {
    width: 100%;
    max-width: 290px;
    height: 220px;
    flex: 1 1 100%;
  }

  .entry-choice-pill img {
    max-width: 145px;
    max-height: 145px;
  }

  .entry-choice-text {
    font-size: 34px;
  }

  .entry-library {
    min-height: 0;
    padding: 12px;
    gap: 12px;

    flex-direction: column;
  }

  .entry-side {
    width: 100%;
    flex: 0 0 auto;

    flex-direction: row;
    align-self: auto;
    gap: 8px;
  }

  .entry-side-pill {
    width: auto;
    min-width: 0;
    min-height: 92px;
    flex: 1;

    padding: 8px 4px;

    border-width: 3px;
    border-radius: 16px;

    font-size: 14px;
  }

  .entry-side-pill img {
    max-width: 48px;
    max-height: 48px;
  }

  .entry-content {
    min-height: 500px;
    padding: 14px;

    border-radius: 18px;
  }

  .entry-content-title {
    margin-bottom: 14px;

    font-size: 30px;
  }

  .entry-subtabs {
    gap: 8px;
    margin-bottom: 14px;
  }

  .entry-subtab {
    padding: 7px 13px;

    border-width: 2px;
    font-size: 18px;
  }

  /* Mobile: 2 + 2 + 1 centred */

  .fish-area-menu {
    grid-template-columns: repeat(2, minmax(0, 135px));
    justify-content: center;
    column-gap: 10px;
    row-gap: 10px;
  }

  .fish-area-icon,
  .fish-area-icon:nth-child(4),
  .fish-area-icon:nth-child(5) {
    width: 135px;
    height: 135px;
    grid-column: auto;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 1 / -1;
    justify-self: center;
  }

  .fish-area-icon img {
    max-width: 82px;
    max-height: 82px;
  }

  .fish-area-name {
    margin-top: -2px;

    font-size: 15px;
  }

  .entries-grid {
    gap: 9px;
  }

  .entry-card {
    width: 112px;
    height: 134px;
    padding: 8px;

    border-radius: 15px;
  }

  .entry-card img {
    max-width: 86px;
    max-height: 86px;
  }

  .entry-card-name {
    margin-top: -24px;

    font-size: 14px;
  }

  .entry-detail-panel {
    padding: 16px;

    border-radius: 14px;
  }

  .entry-detail-top {
    grid-template-columns: 84px minmax(0, 1fr);
    gap: 12px;
  }

  .entry-detail-image img {
    max-width: 78px;
    max-height: 78px;
  }

  .entry-detail-header {
    align-items: flex-start;
  }

  .entry-detail-name {
    font-size: 27px;
    text-align: left;
  }

  .entry-detail-rarity {
    text-align: left;
  }

  .entry-rarity-pill {
    padding: 6px 10px;

    font-size: 13px;
  }

  .entry-detail-back {
    grid-column: 1 / -1;
    justify-self: stretch;

    text-align: center;
  }

  .entry-detail-stats {
    grid-template-columns: 1fr;
    gap: 9px;

    margin-top: 18px;
  }

  .entry-detail-stat {
    padding: 12px;
  }

  .entry-detail-stat-value {
    font-size: 17px;
  }

  .entry-detail-body {
    padding: 13px;

    font-size: 16px;
  }
}

/* ===== Very small screens ===== */

@media (max-width: 360px) {
  .fish-area-menu {
    grid-template-columns: repeat(2, minmax(0, 118px));
  }

  .fish-area-icon,
  .fish-area-icon:nth-child(4),
  .fish-area-icon:nth-child(5) {
    width: 118px;
    height: 125px;
  }

  .fish-area-icon img {
    max-width: 72px;
    max-height: 72px;
  }

  .entry-card {
    width: 104px;
  }
}
/* ===== Compact fish-area menu ===== */
/* Keep this at the absolute bottom of the stylesheet. */

.entry-library-items.entry-fish-menu-open {
  min-height: 0 !important;
  height: fit-content !important;

  align-items: flex-start !important;

  padding-bottom: 12px !important;
}

.entry-library-items.entry-fish-menu-open .entry-side {
  align-self: flex-start !important;

  height: fit-content !important;
  min-height: 0 !important;
}

.entry-library-items.entry-fish-menu-open .entry-side-pill {
  flex: 0 0 135px !important;

  width: 170px !important;
  height: 135px !important;
  min-height: 135px !important;
}

.entry-library-items.entry-fish-menu-open .entry-content {
  flex: 1 1 0 !important;

  min-height: 0 !important;
  height: fit-content !important;

  align-self: flex-start !important;

  padding-bottom: 14px !important;
}

.entry-library-items.entry-fish-menu-open .entry-subcontent-fish {
  min-height: 0 !important;
  height: fit-content !important;

  margin: 0 !important;
  padding: 0 !important;
}

.entry-library-items.entry-fish-menu-open .fish-area-menu {
  min-height: 0 !important;
  height: fit-content !important;

  margin: 0 !important;
  padding: 0 !important;
}

/* ===== Tablet ===== */

@media (max-width: 900px) {
  .entry-library-items.entry-fish-menu-open {
    height: fit-content !important;
    padding-bottom: 10px !important;
  }

  .entry-library-items.entry-fish-menu-open .entry-side-pill {
    flex: 0 0 120px !important;

    width: 145px !important;
    height: 120px !important;
    min-height: 120px !important;
  }

  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0 !important;
    height: fit-content !important;

    padding-bottom: 12px !important;
  }
}

/* ===== Mobile ===== */

@media (max-width: 650px) {
  .entry-library-items.entry-fish-menu-open {
    height: fit-content !important;

    align-items: stretch !important;

    padding-bottom: 8px !important;
  }

  .entry-library-items.entry-fish-menu-open .entry-side {
    width: 100% !important;
    height: fit-content !important;

    align-self: auto !important;
  }

  .entry-library-items.entry-fish-menu-open .entry-side-pill {
    width: auto !important;
    min-width: 0 !important;

    flex: 1 1 0 !important;

    height: 92px !important;
    min-height: 92px !important;
  }

  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0 !important;
    height: fit-content !important;

    align-self: auto !important;

    padding-bottom: 10px !important;
  }
}

.entry-ui {
  width: 100%;
  max-width: 1075px;
  box-sizing: border-box;
}

/* ===== Main category selection ===== */

.entry-choice-box {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: 28px;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;
  box-sizing: border-box;
}

.entry-choice-pill {
  width: 320px;
  height: 300px;
  flex: 0 0 320px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 26px;

  text-align: center;
  box-sizing: border-box;
  cursor: pointer;
}

.entry-choice-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-choice-pill img {
  max-width: 220px;
  max-height: 220px;
  width: auto;
  height: auto;
}

.entry-choice-text {
  display: block;

  color: #4f8cff;
  font-size: 50px;
  line-height: 1;
  white-space: nowrap;
}

/* ===== Entry library ===== */

.entry-library {
  display: none;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;

  padding: 24px;
  gap: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

/* ===== Left navigation ===== */

.entry-side {
  width: 190px;
  flex: 0 0 190px;

  display: flex;
  flex-direction: column;
  gap: 18px;

  align-self: stretch;
}

.entry-side-pill {
  width: 170px;
  flex: 1;
  min-height: 135px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  color: #4f8cff;
  font-size: 24px;
  font-weight: bold;
  line-height: 1;
  text-align: center;

  box-sizing: border-box;
  cursor: pointer;
}

.entry-side-pill img {
  max-width: 80px;
  max-height: 80px;
  width: auto;
  height: auto;
}

.entry-side-pill div {
  margin-top: 0;
}

.entry-side-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Main content ===== */

.entry-content {
  position: relative;
  overflow: hidden;

  flex: 1;
  min-width: 0;
  min-height: 430px;

  padding: 24px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

.entry-content-title {
  margin-bottom: 20px;

  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
}

/* ===== Item subtabs ===== */

.entry-subtabs {
  display: flex;
  gap: 12px;
  margin-bottom: 8px;
}

.entry-subtab {
  padding: 8px 18px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 999px;

  color: #4f8cff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
}

.entry-subtab:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-subcontent {
  display: none;
}

/* Remove empty MediaWiki paragraphs */

.entry-subcontent-fish > p {
  display: none;
  margin: 0;
  padding: 0;
}

/* ===== Fish subicon menu ===== */

.fish-area-menu {
  display: none;

  width: 100%;

  /*
   * Each icon spans two 83px columns:
   * 83px + 14px gap + 83px = 180px.
   */
  grid-template-columns: repeat(6, 83px);
  justify-content: center;
  column-gap: 14px;
  row-gap: 14px;

  margin: 0;
  padding: 0;

  box-sizing: border-box;
}

.fish-area-icon {
  width: 180px;
  height: 180px;
  min-width: 0;

  grid-column: span 2;
  justify-self: center;

  padding: 10px 8px 6px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 22px;

  text-align: center;

  box-sizing: border-box;
  cursor: pointer;
  overflow: hidden;
}

.fish-area-icon:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.fish-area-icon img {
  display: block;

  max-width: 115px;
  max-height: 115px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.fish-area-name {
  position: relative;
  top: -12px;

  width: 100%;
  margin-top: -5px;
  padding: 0;

  color: #4f8cff;
  font-size: 18px;
  font-weight: bold;
  line-height: 1;

  text-align: center;
  white-space: normal;
  word-wrap: break-word;
}

/* Centre subicons 4 and 5 on the second row */

.fish-area-icon:nth-child(4) {
  grid-column: 2 / span 2;
}

.fish-area-icon:nth-child(5) {
  grid-column: 4 / span 2;
}

.fish-area-icon.entry-active {
  background: #17346b;
  border-color: #5aaeff;
}

/* ===== Selected fish group ===== */

.fish-group {
  display: none;
}

.fish-group-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;

  margin-bottom: 18px;
}

.fish-group-title {
  color: #4f8cff;
  font-size: 28px;
  font-weight: bold;
}

.fish-group-back {
  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;

  cursor: pointer;
}

.fish-group-back:hover {
  background: #1f4388;
}

/* ===== Entry cards ===== */

.entries-grid {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-content: flex-start;
  gap: 12px;
}

.entry-card {
  position: relative;

  width: 130px;
  height: 150px;
  padding: 10px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 18px;

  text-align: center;

  box-sizing: border-box;
  overflow: visible;
  cursor: pointer;
}

.entry-card:hover {
  background: #10275a;
}

.entry-card img {
  max-width: 100px;
  max-height: 100px;
  width: auto;
  height: auto;
}

.entry-card-name {
  margin-top: -30px;

  font-size: 16px;
  font-weight: bold;
  line-height: 1;
}

.entry-card-items {
  border-color: #5aaeff;
}

.entry-card-tools {
  border-color: #69e8f4;
}

.entry-card-enchants {
  border-color: #9666ff;
}

/* ===== Entry detail page ===== */

.entry-detail-panel {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  z-index: 50;

  padding: 24px;

  background: #0b0f17;
  border-radius: 20px;

  box-sizing: border-box;
}

.entry-detail-top {
  display: grid;
  grid-template-columns: 160px 1fr 120px;
  align-items: center;
  gap: 20px;
}

.entry-detail-image {
  text-align: left;
}

.entry-detail-image img {
  max-width: 140px;
  max-height: 140px;
  width: auto;
  height: auto;
}

.entry-detail-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
}

.entry-detail-name {
  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  text-align: center;
}

.entry-detail-rarity {
  text-align: center;
}

.entry-rarity-pill {
  display: inline-block;

  padding: 8px 16px;

  background: #0b0f17;
  border: 2px solid #222831;
  border-radius: 999px;

  font-weight: bold;
  line-height: 1;
}

.entry-detail-back {
  justify-self: end;
  display: inline-block;

  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;
  text-decoration: none;

  cursor: pointer;
}

.entry-detail-back:hover {
  background: #1f4388;
}

.entry-detail-body {
  margin-top: 28px;

  color: #ffffff;
  font-size: 18px;
  line-height: 1.4;
}

/* ===== Active states ===== */

.js-entry-open {
  cursor: pointer;
}

.entry-side-pill.entry-active,
.entry-subtab.entry-active {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Rarity name animations ===== */

.entry-name-rarity-common {
  animation: fish-common-name 2s ease-in-out infinite;
}

.entry-name-rarity-uncommon {
  animation: fish-uncommon-name 2s ease-in-out infinite;
}

.entry-name-rarity-rare {
  animation: fish-rare-name 2s ease-in-out infinite;
}

.entry-name-rarity-epic {
  animation: fish-epic-name 2s ease-in-out infinite;
}

.entry-name-rarity-legendary {
  animation: fish-legendary-name 2s ease-in-out infinite;
}

.entry-name-rarity-mythic {
  animation: fish-mythic-name 2s ease-in-out infinite;
}

@keyframes fish-common-name {
  0% {
    color: #a8b1b6;
  }

  50% {
    color: #7f8c99;
  }

  100% {
    color: #a8b1b6;
  }
}

@keyframes fish-uncommon-name {
  0% {
    color: #67ec88;
  }

  50% {
    color: #63c138;
  }

  100% {
    color: #67ec88;
  }
}

@keyframes fish-rare-name {
  0% {
    color: #4ad8ff;
  }

  50% {
    color: #3d93fc;
  }

  100% {
    color: #4ad8ff;
  }
}

@keyframes fish-epic-name {
  0% {
    color: #7843ff;
  }

  50% {
    color: #7246a7;
  }

  100% {
    color: #7843ff;
  }
}

@keyframes fish-legendary-name {
  0% {
    color: #ffe669;
  }

  50% {
    color: #fc932a;
  }

  100% {
    color: #ffe669;
  }
}

@keyframes fish-mythic-name {
  0% {
    color: #ff3045;
  }

  50% {
    color: #b11156;
  }

  100% {
    color: #ff3045;
  }
}

/* ===== Rarity border animations ===== */

.entry-card-rarity-none {
  border-color: #222831;
  box-shadow: none;
}

.entry-card-rarity-common {
  animation: fish-common-border 2s ease-in-out infinite;
}

.entry-card-rarity-uncommon {
  animation: fish-uncommon-border 2s ease-in-out infinite;
}

.entry-card-rarity-rare {
  animation: fish-rare-border 2s ease-in-out infinite;
}

.entry-card-rarity-epic {
  animation: fish-epic-border 2s ease-in-out infinite;
}

.entry-card-rarity-legendary {
  animation: fish-legendary-border 2s ease-in-out infinite;
}

.entry-card-rarity-mythic {
  animation: fish-mythic-border 2s ease-in-out infinite;
}

@keyframes fish-common-border {
  0% {
    border-color: #a8b1b6;
    box-shadow: 0 0 5px #a8b1b6;
  }

  50% {
    border-color: #7f8c99;
    box-shadow: 0 0 10px #7f8c99;
  }

  100% {
    border-color: #a8b1b6;
    box-shadow: 0 0 5px #a8b1b6;
  }
}

@keyframes fish-uncommon-border {
  0% {
    border-color: #67ec88;
    box-shadow: 0 0 5px #67ec88;
  }

  50% {
    border-color: #63c138;
    box-shadow: 0 0 10px #63c138;
  }

  100% {
    border-color: #67ec88;
    box-shadow: 0 0 5px #67ec88;
  }
}

@keyframes fish-rare-border {
  0% {
    border-color: #4ad8ff;
    box-shadow: 0 0 5px #4ad8ff;
  }

  50% {
    border-color: #3d93fc;
    box-shadow: 0 0 10px #3d93fc;
  }

  100% {
    border-color: #4ad8ff;
    box-shadow: 0 0 5px #4ad8ff;
  }
}

@keyframes fish-epic-border {
  0% {
    border-color: #7843ff;
    box-shadow: 0 0 5px #7843ff;
  }

  50% {
    border-color: #7246a7;
    box-shadow: 0 0 10px #7246a7;
  }

  100% {
    border-color: #7843ff;
    box-shadow: 0 0 5px #7843ff;
  }
}

@keyframes fish-legendary-border {
  0% {
    border-color: #ffe669;
    box-shadow: 0 0 5px #ffe669;
  }

  50% {
    border-color: #fc932a;
    box-shadow: 0 0 10px #fc932a;
  }

  100% {
    border-color: #ffe669;
    box-shadow: 0 0 5px #ffe669;
  }
}

@keyframes fish-mythic-border {
  0% {
    border-color: #ff3045;
    box-shadow: 0 0 6px #ff3045;
  }

  50% {
    border-color: #b11156;
    box-shadow: 0 0 12px #b11156;
  }

  100% {
    border-color: #ff3045;
    box-shadow: 0 0 6px #ff3045;
  }
}

/* ===== Tablet layout ===== */

@media screen and (max-width: 900px) {
  .entry-choice-box {
    padding: 18px;
    gap: 18px;
  }

  .entry-choice-pill {
    width: 260px;
    height: 250px;
    flex: 0 0 260px;
  }

  .entry-choice-pill img {
    max-width: 170px;
    max-height: 170px;
  }

  .entry-choice-text {
    font-size: 38px;
  }

  .entry-library {
    flex-direction: column;
    padding: 18px;
    gap: 18px;
  }

  .entry-side {
    width: 100%;
    flex: 0 0 auto;

    flex-direction: row;
    flex-wrap: wrap;
    justify-content: center;
  }

  .entry-side-pill {
    width: 150px;
    height: 115px;
    flex: 0 0 150px;

    font-size: 20px;
  }

  .entry-content {
    width: 100%;
    min-height: 500px;
  }

  .entry-content-title {
    font-size: 36px;
    text-align: center;
  }

  .entries-grid {
    justify-content: center;
  }

  .fish-area-menu {
    /*
     * 75px + 10px gap + 75px = 160px.
     */
    grid-template-columns: repeat(6, 75px);
    justify-content: center;
    column-gap: 10px;
    row-gap: 10px;
  }

  .fish-area-icon {
    width: 160px;
    height: 160px;

    grid-column: span 2;
    justify-self: center;
  }

  .fish-area-icon img {
    max-width: 100px;
    max-height: 100px;
  }

  .fish-area-name {
    top: -10px;
    margin-top: -5px;
    font-size: 16px;
  }

  .fish-area-icon:nth-child(4) {
    grid-column: 2 / span 2;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 4 / span 2;
  }
}

/* ===== Phone layout ===== */

@media screen and (max-width: 600px) {
  .entry-choice-box {
    min-height: 0;
    padding: 12px;
    gap: 14px;
  }

  .entry-choice-pill {
    width: 100%;
    height: 190px;
    flex: 0 0 100%;

    border-radius: 18px;
  }

  .entry-choice-pill img {
    max-width: 120px;
    max-height: 120px;
  }

  .entry-choice-text {
    font-size: 32px;
  }

  .entry-library {
    padding: 12px;
    gap: 12px;

    border-radius: 18px;
  }

  .entry-side {
    gap: 10px;
  }

  .entry-side-pill {
    width: 31%;
    min-width: 90px;
    height: 90px;
    flex: 0 0 31%;

    font-size: 14px;
    border-width: 3px;
    border-radius: 16px;
  }

  .entry-side-pill img {
    max-width: 48px;
    max-height: 48px;
  }

  .entry-content {
    min-height: 560px;
    padding: 14px;

    border-radius: 18px;
  }

  .entry-content-title {
    margin-bottom: 14px;

    font-size: 30px;
    text-align: center;
  }

  .entry-subtabs {
    justify-content: center;
    flex-wrap: wrap;
    margin-bottom: 8px;
  }

  .entry-subtab {
    padding: 7px 14px;
    font-size: 18px;
  }

  /* 2 + 2 + 1 centred */

  .fish-area-menu {
    grid-template-columns: repeat(2, 135px);
    justify-content: center;
    column-gap: 10px;
    row-gap: 10px;

    margin: 0;
    padding: 0;
  }

  .fish-area-icon {
    width: 135px;
    height: 135px;

    grid-column: auto;
    justify-self: center;

    padding: 6px;
    border-radius: 18px;
  }

  .fish-area-icon img {
    max-width: 82px;
    max-height: 82px;
  }

  .fish-area-name {
    top: -8px;
    margin-top: -5px;
    font-size: 14px;
  }

  .fish-area-icon:nth-child(4) {
    grid-column: auto;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 1 / -1;
    justify-self: center;
  }

  .fish-group-heading {
    gap: 10px;
  }

  .fish-group-title {
    font-size: 22px;
  }

  .fish-group-back {
    padding: 7px 12px;
    font-size: 14px;
  }

  .entry-card {
    width: 110px;
    height: 135px;
    padding: 8px;
  }

  .entry-card img {
    max-width: 82px;
    max-height: 82px;
  }

  .entry-card-name {
    margin-top: -15px;
    font-size: 14px;
  }

  .entry-detail-panel {
    padding: 14px;
    overflow: auto;
  }

  .entry-detail-top {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .entry-detail-image {
    text-align: center;
  }

  .entry-detail-image img {
    max-width: 110px;
    max-height: 110px;
  }

  .entry-detail-name {
    font-size: 30px;
  }

  .entry-detail-back {
    justify-self: center;
    text-align: center;
  }

  .entry-detail-body {
    font-size: 16px;
    text-align: center;
  }
}

/* ===== Very small phones ===== */

@media screen and (max-width: 380px) {
  .entry-choice-pill {
    height: 165px;
  }

  .entry-choice-pill img {
    max-width: 95px;
    max-height: 95px;
  }

  .entry-choice-text {
    font-size: 26px;
  }

  .entry-side-pill {
    width: 100%;
    height: 75px;
    flex: 0 0 100%;

    flex-direction: row;
    font-size: 16px;
  }

  .entry-side-pill img {
    max-width: 42px;
    max-height: 42px;
  }

  .fish-area-menu {
    grid-template-columns: repeat(2, 120px);
    justify-content: center;
    column-gap: 8px;
    row-gap: 8px;
  }

  .fish-area-icon {
    width: 120px;
    height: 120px;

    grid-column: auto;
    justify-self: center;

    padding: 5px;
    border-radius: 16px;
  }

  .fish-area-icon img {
    max-width: 70px;
    max-height: 70px;
  }

  .fish-area-name {
    top: -6px;
    margin-top: -4px;
    font-size: 12px;
  }

  .fish-area-icon:nth-child(4) {
    grid-column: auto;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 1 / -1;
    justify-self: center;
  }

  .fish-group-title {
    font-size: 19px;
  }

  .entry-card {
    width: 95px;
    height: 125px;
  }

  .entry-card img {
    max-width: 72px;
    max-height: 72px;
  }

  .entry-card-name {
    font-size: 12px;
  }

  .entry-detail-name {
    font-size: 24px;
  }

  .entry-detail-body {
    font-size: 14px;
  }
}

/* ===== Compact fish-menu screen ===== */

/*
 * The fish content panel becomes shorter.
 * Items, Tools and Enchants keep their original
 * equal sidebar spacing.
 */

.entry-library-items.entry-fish-menu-open {
  min-height: 0;
  padding-bottom: 12px;
}

.entry-library-items.entry-fish-menu-open .entry-content {
  min-height: 0;
  height: auto;

  align-self: flex-start;
  padding-bottom: 12px;
}

@media screen and (max-width: 900px) {
  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0;
  }
}

@media screen and (max-width: 600px) {
  .entry-library-items.entry-fish-menu-open {
    min-height: 0;
    padding-bottom: 8px;
  }

  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0;
    padding-bottom: 8px;
  }
}

/* ===== Hidden page image ===== */

.hidden-pageimage {
  position: absolute;

  width: 0;
  height: 0;

  overflow: hidden;
}

.hidden-pageimage img {
  width: 0;
  height: 0;
}

.entry-ui {
  width: 100%;
  max-width: 1075px;
  box-sizing: border-box;
}

/* ===== Main category selection ===== */

.entry-choice-box {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: 28px;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;
  box-sizing: border-box;
}

.entry-choice-pill {
  width: 320px;
  height: 300px;
  flex: 0 0 320px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 26px;

  text-align: center;
  box-sizing: border-box;
  cursor: pointer;
}

.entry-choice-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-choice-pill img {
  max-width: 220px;
  max-height: 220px;
  width: auto;
  height: auto;
}

.entry-choice-text {
  display: block;

  color: #4f8cff;
  font-size: 50px;
  line-height: 1;
  white-space: nowrap;
}

/* ===== Entry library ===== */

.entry-library {
  display: none;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;

  padding: 24px;
  gap: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

/* ===== Left navigation ===== */

.entry-side {
  width: 190px;
  flex: 0 0 190px;

  display: flex;
  flex-direction: column;
  gap: 18px;

  align-self: stretch;
}

.entry-side-pill {
  width: 170px;
  flex: 1;
  min-height: 135px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  color: #4f8cff;
  font-size: 24px;
  font-weight: bold;
  line-height: 1;
  text-align: center;

  box-sizing: border-box;
  cursor: pointer;
}

.entry-side-pill img {
  max-width: 80px;
  max-height: 80px;
  width: auto;
  height: auto;
}

.entry-side-pill div {
  margin-top: 0;
}

.entry-side-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Main content ===== */

.entry-content {
  position: relative;
  overflow: hidden;

  flex: 1;
  min-width: 0;
  min-height: 430px;

  padding: 24px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

.entry-content-title {
  margin-bottom: 20px;

  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
}

/* ===== Item subtabs ===== */

.entry-subtabs {
  display: flex;
  gap: 12px;
  margin-bottom: 8px;
}

.entry-subtab {
  padding: 8px 18px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 999px;

  color: #4f8cff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
}

.entry-subtab:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-subcontent {
  display: none;
}

/* Remove empty MediaWiki paragraphs */

.entry-subcontent-fish > p {
  display: none;
  margin: 0;
  padding: 0;
}

/* ===== Fish subicon menu ===== */

.fish-area-menu {
  display: none;

  width: 100%;

  /*
   * Each icon spans two 83px columns:
   * 83px + 14px gap + 83px = 180px.
   */
  grid-template-columns: repeat(6, 83px);
  justify-content: center;
  column-gap: 14px;
  row-gap: 14px;

  margin: 0;
  padding: 0;

  box-sizing: border-box;
}

.fish-area-icon {
  width: 180px;
  height: 180px;
  min-width: 0;

  grid-column: span 2;
  justify-self: center;

  padding: 10px 8px 6px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 22px;

  text-align: center;

  box-sizing: border-box;
  cursor: pointer;
  overflow: hidden;
}

.fish-area-icon:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.fish-area-icon img {
  display: block;

  max-width: 115px;
  max-height: 115px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.fish-area-name {
  position: relative;
  top: -12px;

  width: 100%;
  margin-top: -5px;
  padding: 0;

  color: #4f8cff;
  font-size: 18px;
  font-weight: bold;
  line-height: 1;

  text-align: center;
  white-space: normal;
  word-wrap: break-word;
}

/* Centre subicons 4 and 5 on the second row */

.fish-area-icon:nth-child(4) {
  grid-column: 2 / span 2;
}

.fish-area-icon:nth-child(5) {
  grid-column: 4 / span 2;
}

.fish-area-icon.entry-active {
  background: #17346b;
  border-color: #5aaeff;
}

/* ===== Selected fish group ===== */

.fish-group {
  display: none;
}

.fish-group-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;

  margin-bottom: 18px;
}

.fish-group-title {
  color: #4f8cff;
  font-size: 28px;
  font-weight: bold;
}

.fish-group-back {
  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;

  cursor: pointer;
}

.fish-group-back:hover {
  background: #1f4388;
}

/* ===== Entry cards ===== */

.entries-grid {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-content: flex-start;
  gap: 12px;
}

.entry-card {
  position: relative;

  width: 130px;
  height: 150px;
  padding: 10px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 18px;

  text-align: center;

  box-sizing: border-box;
  overflow: visible;
  cursor: pointer;
}

.entry-card:hover {
  background: #10275a;
}

.entry-card img {
  max-width: 100px;
  max-height: 100px;
  width: auto;
  height: auto;
}

.entry-card-name {
  margin-top: -30px;

  font-size: 16px;
  font-weight: bold;
  line-height: 1;
}

.entry-card-items {
  border-color: #5aaeff;
}

.entry-card-tools {
  border-color: #69e8f4;
}

.entry-card-enchants {
  border-color: #9666ff;
}

/* ===== Entry detail page ===== */

.entry-detail-panel {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  z-index: 50;

  padding: 24px;

  background: #0b0f17;
  border-radius: 20px;

  box-sizing: border-box;
}

.entry-detail-top {
  display: grid;
  grid-template-columns: 160px 1fr 120px;
  align-items: center;
  gap: 20px;
}

.entry-detail-image {
  text-align: left;
}

.entry-detail-image img {
  max-width: 140px;
  max-height: 140px;
  width: auto;
  height: auto;
}

.entry-detail-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
}

.entry-detail-name {
  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  text-align: center;
}

.entry-detail-rarity {
  text-align: center;
}

.entry-rarity-pill {
  display: inline-block;

  padding: 8px 16px;

  background: #0b0f17;
  border: 2px solid #222831;
  border-radius: 999px;

  font-weight: bold;
  line-height: 1;
}

.entry-detail-back {
  justify-self: end;
  display: inline-block;

  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;
  text-decoration: none;

  cursor: pointer;
}

.entry-detail-back:hover {
  background: #1f4388;
}

.entry-detail-body {
  margin-top: 28px;

  color: #ffffff;
  font-size: 18px;
  line-height: 1.4;
}

/* ===== Active states ===== */

.js-entry-open {
  cursor: pointer;
}

.entry-side-pill.entry-active,
.entry-subtab.entry-active {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Rarity name animations ===== */

.entry-name-rarity-common {
  animation: fish-common-name 2s ease-in-out infinite;
}

.entry-name-rarity-uncommon {
  animation: fish-uncommon-name 2s ease-in-out infinite;
}

.entry-name-rarity-rare {
  animation: fish-rare-name 2s ease-in-out infinite;
}

.entry-name-rarity-epic {
  animation: fish-epic-name 2s ease-in-out infinite;
}

.entry-name-rarity-legendary {
  animation: fish-legendary-name 2s ease-in-out infinite;
}

.entry-name-rarity-mythic {
  animation: fish-mythic-name 2s ease-in-out infinite;
}
.entry-name-rarity-secret {
  animation: fish-secret-name 2s ease-in-out infinite;
}
@keyframes fish-common-name {
  0% {
    color: #a8b1b6;
  }

  50% {
    color: #7f8c99;
  }

  100% {
    color: #a8b1b6;
  }
}

@keyframes fish-uncommon-name {
  0% {
    color: #67ec88;
  }

  50% {
    color: #63c138;
  }

  100% {
    color: #67ec88;
  }
}

@keyframes fish-rare-name {
  0% {
    color: #4ad8ff;
  }

  50% {
    color: #3d93fc;
  }

  100% {
    color: #4ad8ff;
  }
}

@keyframes fish-epic-name {
  0% {
    color: #7843ff;
  }

  50% {
    color: #7246a7;
  }

  100% {
    color: #7843ff;
  }
}

@keyframes fish-legendary-name {
  0% {
    color: #ffe669;
  }

  50% {
    color: #fc932a;
  }

  100% {
    color: #ffe669;
  }
}

@keyframes fish-mythic-name {
  0% {
    color: #ff3045;
  }

  50% {
    color: #b11156;
  }

  100% {
    color: #ff3045;
  }
}

@keyframes fish-secret-color {
  0% {
    color: #a617ff;
  }

  50% {
    color: #ff26fb;
  }

  100% {
    color: #a617ff;
  }
}
/* ===== Rarity border animations ===== */

.entry-card-rarity-none {
  border-color: #222831;
  box-shadow: none;
}

.entry-card-rarity-common {
  animation: fish-common-border 2s ease-in-out infinite;
}

.entry-card-rarity-uncommon {
  animation: fish-uncommon-border 2s ease-in-out infinite;
}

.entry-card-rarity-rare {
  animation: fish-rare-border 2s ease-in-out infinite;
}

.entry-card-rarity-epic {
  animation: fish-epic-border 2s ease-in-out infinite;
}

.entry-card-rarity-legendary {
  animation: fish-legendary-border 2s ease-in-out infinite;
}

.entry-card-rarity-mythic {
  animation: fish-mythic-border 2s ease-in-out infinite;
}

@keyframes fish-common-border {
  0% {
    border-color: #a8b1b6;
    box-shadow: 0 0 5px #a8b1b6;
  }

  50% {
    border-color: #7f8c99;
    box-shadow: 0 0 10px #7f8c99;
  }

  100% {
    border-color: #a8b1b6;
    box-shadow: 0 0 5px #a8b1b6;
  }
}

@keyframes fish-uncommon-border {
  0% {
    border-color: #67ec88;
    box-shadow: 0 0 5px #67ec88;
  }

  50% {
    border-color: #63c138;
    box-shadow: 0 0 10px #63c138;
  }

  100% {
    border-color: #67ec88;
    box-shadow: 0 0 5px #67ec88;
  }
}

@keyframes fish-rare-border {
  0% {
    border-color: #4ad8ff;
    box-shadow: 0 0 5px #4ad8ff;
  }

  50% {
    border-color: #3d93fc;
    box-shadow: 0 0 10px #3d93fc;
  }

  100% {
    border-color: #4ad8ff;
    box-shadow: 0 0 5px #4ad8ff;
  }
}

@keyframes fish-epic-border {
  0% {
    border-color: #7843ff;
    box-shadow: 0 0 5px #7843ff;
  }

  50% {
    border-color: #7246a7;
    box-shadow: 0 0 10px #7246a7;
  }

  100% {
    border-color: #7843ff;
    box-shadow: 0 0 5px #7843ff;
  }
}

@keyframes fish-legendary-border {
  0% {
    border-color: #ffe669;
    box-shadow: 0 0 5px #ffe669;
  }

  50% {
    border-color: #fc932a;
    box-shadow: 0 0 10px #fc932a;
  }

  100% {
    border-color: #ffe669;
    box-shadow: 0 0 5px #ffe669;
  }
}

@keyframes fish-mythic-border {
  0% {
    border-color: #ff3045;
    box-shadow: 0 0 6px #ff3045;
  }

  50% {
    border-color: #b11156;
    box-shadow: 0 0 12px #b11156;
  }

  100% {
    border-color: #ff3045;
    box-shadow: 0 0 6px #ff3045;
  }
}

/* ===== Tablet layout ===== */

@media screen and (max-width: 900px) {
  .entry-choice-box {
    padding: 18px;
    gap: 18px;
  }

  .entry-choice-pill {
    width: 260px;
    height: 250px;
    flex: 0 0 260px;
  }

  .entry-choice-pill img {
    max-width: 170px;
    max-height: 170px;
  }

  .entry-choice-text {
    font-size: 38px;
  }

  .entry-library {
    flex-direction: column;
    padding: 18px;
    gap: 18px;
  }

  .entry-side {
    width: 100%;
    flex: 0 0 auto;

    flex-direction: row;
    flex-wrap: wrap;
    justify-content: center;
  }

  .entry-side-pill {
    width: 150px;
    height: 115px;
    flex: 0 0 150px;

    font-size: 20px;
  }

  .entry-content {
    width: 100%;
    min-height: 500px;
  }

  .entry-content-title {
    font-size: 36px;
    text-align: center;
  }

  .entries-grid {
    justify-content: center;
  }

  .fish-area-menu {
    /*
     * 75px + 10px gap + 75px = 160px.
     */
    grid-template-columns: repeat(6, 75px);
    justify-content: center;
    column-gap: 10px;
    row-gap: 10px;
  }

  .fish-area-icon {
    width: 160px;
    height: 160px;

    grid-column: span 2;
    justify-self: center;
  }

  .fish-area-icon img {
    max-width: 100px;
    max-height: 100px;
  }

  .fish-area-name {
    top: -10px;
    margin-top: -5px;
    font-size: 16px;
  }

  .fish-area-icon:nth-child(4) {
    grid-column: 2 / span 2;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 4 / span 2;
  }
}

/* ===== Phone layout ===== */

@media screen and (max-width: 600px) {
  .entry-choice-box {
    min-height: 0;
    padding: 12px;
    gap: 14px;
  }

  .entry-choice-pill {
    width: 100%;
    height: 190px;
    flex: 0 0 100%;

    border-radius: 18px;
  }

  .entry-choice-pill img {
    max-width: 120px;
    max-height: 120px;
  }

  .entry-choice-text {
    font-size: 32px;
  }

  .entry-library {
    padding: 12px;
    gap: 12px;

    border-radius: 18px;
  }

  .entry-side {
    gap: 10px;
  }

  .entry-side-pill {
    width: 31%;
    min-width: 90px;
    height: 90px;
    flex: 0 0 31%;

    font-size: 14px;
    border-width: 3px;
    border-radius: 16px;
  }

  .entry-side-pill img {
    max-width: 48px;
    max-height: 48px;
  }

  .entry-content {
    min-height: 560px;
    padding: 14px;

    border-radius: 18px;
  }

  .entry-content-title {
    margin-bottom: 14px;

    font-size: 30px;
    text-align: center;
  }

  .entry-subtabs {
    justify-content: center;
    flex-wrap: wrap;
    margin-bottom: 8px;
  }

  .entry-subtab {
    padding: 7px 14px;
    font-size: 18px;
  }

  /* 2 + 2 + 1 centred */

  .fish-area-menu {
    grid-template-columns: repeat(2, 135px);
    justify-content: center;
    column-gap: 10px;
    row-gap: 10px;

    margin: 0;
    padding: 0;
  }

  .fish-area-icon {
    width: 135px;
    height: 135px;

    grid-column: auto;
    justify-self: center;

    padding: 6px;
    border-radius: 18px;
  }

  .fish-area-icon img {
    max-width: 82px;
    max-height: 82px;
  }

  .fish-area-name {
    top: -8px;
    margin-top: -5px;
    font-size: 14px;
  }

  .fish-area-icon:nth-child(4) {
    grid-column: auto;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 1 / -1;
    justify-self: center;
  }

  .fish-group-heading {
    gap: 10px;
  }

  .fish-group-title {
    font-size: 22px;
  }

  .fish-group-back {
    padding: 7px 12px;
    font-size: 14px;
  }

  .entry-card {
    width: 110px;
    height: 135px;
    padding: 8px;
  }

  .entry-card img {
    max-width: 82px;
    max-height: 82px;
  }

  .entry-card-name {
    margin-top: -15px;
    font-size: 14px;
  }

  .entry-detail-panel {
    padding: 14px;
    overflow: auto;
  }

  .entry-detail-top {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .entry-detail-image {
    text-align: center;
  }

  .entry-detail-image img {
    max-width: 110px;
    max-height: 110px;
  }

  .entry-detail-name {
    font-size: 30px;
  }

  .entry-detail-back {
    justify-self: center;
    text-align: center;
  }

  .entry-detail-body {
    font-size: 16px;
    text-align: center;
  }
}

/* ===== Very small phones ===== */

@media screen and (max-width: 380px) {
  .entry-choice-pill {
    height: 165px;
  }

  .entry-choice-pill img {
    max-width: 95px;
    max-height: 95px;
  }

  .entry-choice-text {
    font-size: 26px;
  }

  .entry-side-pill {
    width: 100%;
    height: 75px;
    flex: 0 0 100%;

    flex-direction: row;
    font-size: 16px;
  }

  .entry-side-pill img {
    max-width: 42px;
    max-height: 42px;
  }

  .fish-area-menu {
    grid-template-columns: repeat(2, 120px);
    justify-content: center;
    column-gap: 8px;
    row-gap: 8px;
  }

  .fish-area-icon {
    width: 120px;
    height: 120px;

    grid-column: auto;
    justify-self: center;

    padding: 5px;
    border-radius: 16px;
  }

  .fish-area-icon img {
    max-width: 70px;
    max-height: 70px;
  }

  .fish-area-name {
    top: -6px;
    margin-top: -4px;
    font-size: 12px;
  }

  .fish-area-icon:nth-child(4) {
    grid-column: auto;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 1 / -1;
    justify-self: center;
  }

  .fish-group-title {
    font-size: 19px;
  }

  .entry-card {
    width: 95px;
    height: 125px;
  }

  .entry-card img {
    max-width: 72px;
    max-height: 72px;
  }

  .entry-card-name {
    font-size: 12px;
  }

  .entry-detail-name {
    font-size: 24px;
  }

  .entry-detail-body {
    font-size: 14px;
  }
}

/* ===== Compact fish-menu screen ===== */

/*
 * The fish content panel becomes shorter.
 * Items, Tools and Enchants keep their original
 * equal sidebar spacing.
 */

.entry-library-items.entry-fish-menu-open {
  min-height: 0;
  padding-bottom: 12px;
}

.entry-library-items.entry-fish-menu-open .entry-content {
  min-height: 0;
  height: auto;

  align-self: flex-start;
  padding-bottom: 12px;
}

@media screen and (max-width: 900px) {
  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0;
  }
}

@media screen and (max-width: 600px) {
  .entry-library-items.entry-fish-menu-open {
    min-height: 0;
    padding-bottom: 8px;
  }

  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0;
    padding-bottom: 8px;
  }
}

/* ===== Hidden page image ===== */

.hidden-pageimage {
  position: absolute;

  width: 0;
  height: 0;

  overflow: hidden;
}

.hidden-pageimage img {
  width: 0;
  height: 0;
}

.entry-ui {
  width: 100%;
  max-width: 1075px;
  box-sizing: border-box;
}

/* ===== Main category selection ===== */

.entry-choice-box {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: 28px;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;
  box-sizing: border-box;
}

.entry-choice-pill {
  width: 320px;
  height: 300px;
  flex: 0 0 320px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 26px;

  text-align: center;
  box-sizing: border-box;
  cursor: pointer;
}

.entry-choice-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-choice-pill img {
  max-width: 220px;
  max-height: 220px;
  width: auto;
  height: auto;
}

.entry-choice-text {
  display: block;

  color: #4f8cff;
  font-size: 50px;
  line-height: 1;
  white-space: nowrap;
}

/* ===== Entry library ===== */

.entry-library {
  display: none;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;

  padding: 24px;
  gap: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

/* ===== Left navigation ===== */

.entry-side {
  width: 190px;
  flex: 0 0 190px;

  display: flex;
  flex-direction: column;
  gap: 18px;

  align-self: stretch;
}

.entry-side-pill {
  width: 170px;
  flex: 1;
  min-height: 135px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  color: #4f8cff;
  font-size: 24px;
  font-weight: bold;
  line-height: 1;
  text-align: center;

  box-sizing: border-box;
  cursor: pointer;
}

.entry-side-pill img {
  max-width: 80px;
  max-height: 80px;
  width: auto;
  height: auto;
}

.entry-side-pill div {
  margin-top: 0;
}

.entry-side-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Main content ===== */

.entry-content {
  position: relative;
  overflow: hidden;

  flex: 1;
  min-width: 0;
  min-height: 430px;

  padding: 24px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

.entry-content-title {
  margin-bottom: 20px;

  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
}

/* ===== Item subtabs ===== */

.entry-subtabs {
  display: flex;
  gap: 12px;
  margin-bottom: 8px;
}

.entry-subtab {
  padding: 8px 18px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 999px;

  color: #4f8cff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
}

.entry-subtab:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-subcontent {
  display: none;
}

/* Remove empty MediaWiki paragraphs */

.entry-subcontent-fish > p {
  display: none;
  margin: 0;
  padding: 0;
}

/* ===== Fish subicon menu ===== */

.fish-area-menu {
  display: none;

  width: 100%;

  /*
   * Each icon spans two 83px columns:
   * 83px + 14px gap + 83px = 180px.
   */
  grid-template-columns: repeat(6, 83px);
  justify-content: center;
  column-gap: 14px;
  row-gap: 14px;

  margin: 0;
  padding: 0;

  box-sizing: border-box;
}

.fish-area-icon {
  width: 180px;
  height: 180px;
  min-width: 0;

  grid-column: span 2;
  justify-self: center;

  padding: 10px 8px 6px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 22px;

  text-align: center;

  box-sizing: border-box;
  cursor: pointer;
  overflow: hidden;
}

.fish-area-icon:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.fish-area-icon img {
  display: block;

  max-width: 115px;
  max-height: 115px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.fish-area-name {
  position: relative;
  top: -12px;

  width: 100%;
  margin-top: -5px;
  padding: 0;

  color: #4f8cff;
  font-size: 18px;
  font-weight: bold;
  line-height: 1;

  text-align: center;
  white-space: normal;
  word-wrap: break-word;
}

/* Centre subicons 4 and 5 on the second row */

.fish-area-icon:nth-child(4) {
  grid-column: 2 / span 2;
}

.fish-area-icon:nth-child(5) {
  grid-column: 4 / span 2;
}

.fish-area-icon.entry-active {
  background: #17346b;
  border-color: #5aaeff;
}

/* ===== Selected fish group ===== */

.fish-group {
  display: none;
}

.fish-group-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;

  margin-bottom: 18px;
}

.fish-group-title {
  color: #4f8cff;
  font-size: 28px;
  font-weight: bold;
}

.fish-group-back {
  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;

  cursor: pointer;
}

.fish-group-back:hover {
  background: #1f4388;
}

/* ===== Entry cards ===== */

.entries-grid {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-content: flex-start;
  gap: 12px;
}

.entry-card {
  position: relative;

  width: 130px;
  height: 150px;
  padding: 10px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 18px;

  text-align: center;

  box-sizing: border-box;
  overflow: visible;
  cursor: pointer;
}

.entry-card:hover {
  background: #10275a;
}

.entry-card img {
  max-width: 100px;
  max-height: 100px;
  width: auto;
  height: auto;
}

.entry-card-name {
  margin-top: -30px;

  font-size: 16px;
  font-weight: bold;
  line-height: 1;
}

.entry-card-items {
  border-color: #5aaeff;
}

.entry-card-tools {
  border-color: #69e8f4;
}

.entry-card-enchants {
  border-color: #9666ff;
}

/* ===== Entry detail page ===== */

.entry-detail-panel {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  z-index: 50;

  padding: 24px;

  background: #0b0f17;
  border-radius: 20px;

  box-sizing: border-box;
}

.entry-detail-top {
  display: grid;
  grid-template-columns: 160px 1fr 120px;
  align-items: center;
  gap: 20px;
}

.entry-detail-image {
  text-align: left;
}

.entry-detail-image img {
  max-width: 140px;
  max-height: 140px;
  width: auto;
  height: auto;
}

.entry-detail-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
}

.entry-detail-name {
  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  text-align: center;
}

.entry-detail-rarity {
  text-align: center;
}

.entry-rarity-pill {
  display: inline-block;

  padding: 8px 16px;

  background: #0b0f17;
  border: 2px solid #222831;
  border-radius: 999px;

  font-weight: bold;
  line-height: 1;
}

.entry-detail-back {
  justify-self: end;
  display: inline-block;

  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;
  text-decoration: none;

  cursor: pointer;
}

.entry-detail-back:hover {
  background: #1f4388;
}

.entry-detail-body {
  margin-top: 28px;

  color: #ffffff;
  font-size: 18px;
  line-height: 1.4;
}

/* ===== Active states ===== */

.js-entry-open {
  cursor: pointer;
}

.entry-side-pill.entry-active,
.entry-subtab.entry-active {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Rarity name animations ===== */

.entry-name-rarity-common {
  animation: fish-common-name 2s ease-in-out infinite;
}

.entry-name-rarity-uncommon {
  animation: fish-uncommon-name 2s ease-in-out infinite;
}

.entry-name-rarity-rare {
  animation: fish-rare-name 2s ease-in-out infinite;
}

.entry-name-rarity-epic {
  animation: fish-epic-name 2s ease-in-out infinite;
}

.entry-name-rarity-legendary {
  animation: fish-legendary-name 2s ease-in-out infinite;
}

.entry-name-rarity-mythic {
  animation: fish-mythic-name 2s ease-in-out infinite;
}

.entry-name-rarity-secret {
  animation: fish-secret-name 2s ease-in-out infinite;
}
@keyframes fish-common-name {
  0% {
    color: #a8b1b6;
  }

  50% {
    color: #7f8c99;
  }

  100% {
    color: #a8b1b6;
  }
}

@keyframes fish-uncommon-name {
  0% {
    color: #67ec88;
  }

  50% {
    color: #63c138;
  }

  100% {
    color: #67ec88;
  }
}

@keyframes fish-rare-name {
  0% {
    color: #4ad8ff;
  }

  50% {
    color: #3d93fc;
  }

  100% {
    color: #4ad8ff;
  }
}

@keyframes fish-epic-name {
  0% {
    color: #7843ff;
  }

  50% {
    color: #7246a7;
  }

  100% {
    color: #7843ff;
  }
}

@keyframes fish-legendary-name {
  0% {
    color: #ffe669;
  }

  50% {
    color: #fc932a;
  }

  100% {
    color: #ffe669;
  }
}

@keyframes fish-mythic-name {
  0% {
    color: #ff3045;
  }

  50% {
    color: #b11156;
  }

  100% {
    color: #ff3045;
  }
}

@keyframes fish-secret-color {
  0% {
    color: #a617ff;
  }

  50% {
    color: #ff26fb;
  }

  100% {
    color: #a617ff;
  }
}
/* ===== Rarity border animations ===== */

.entry-card-rarity-none {
  border-color: #222831;
  box-shadow: none;
}

.entry-card-rarity-common {
  animation: fish-common-border 2s ease-in-out infinite;
}

.entry-card-rarity-uncommon {
  animation: fish-uncommon-border 2s ease-in-out infinite;
}

.entry-card-rarity-rare {
  animation: fish-rare-border 2s ease-in-out infinite;
}

.entry-card-rarity-epic {
  animation: fish-epic-border 2s ease-in-out infinite;
}

.entry-card-rarity-legendary {
  animation: fish-legendary-border 2s ease-in-out infinite;
}

.entry-card-rarity-mythic {
  animation: fish-mythic-border 2s ease-in-out infinite;
}
.entry-card-rarity-secret {
  animation: fish-secret-border 2s ease-in-out infinite;
}
@keyframes fish-common-border {
  0% {
    border-color: #a8b1b6;
    box-shadow: 0 0 5px #a8b1b6;
  }

  50% {
    border-color: #7f8c99;
    box-shadow: 0 0 10px #7f8c99;
  }

  100% {
    border-color: #a8b1b6;
    box-shadow: 0 0 5px #a8b1b6;
  }
}

@keyframes fish-uncommon-border {
  0% {
    border-color: #67ec88;
    box-shadow: 0 0 5px #67ec88;
  }

  50% {
    border-color: #63c138;
    box-shadow: 0 0 10px #63c138;
  }

  100% {
    border-color: #67ec88;
    box-shadow: 0 0 5px #67ec88;
  }
}

@keyframes fish-rare-border {
  0% {
    border-color: #4ad8ff;
    box-shadow: 0 0 5px #4ad8ff;
  }

  50% {
    border-color: #3d93fc;
    box-shadow: 0 0 10px #3d93fc;
  }

  100% {
    border-color: #4ad8ff;
    box-shadow: 0 0 5px #4ad8ff;
  }
}

@keyframes fish-epic-border {
  0% {
    border-color: #7843ff;
    box-shadow: 0 0 5px #7843ff;
  }

  50% {
    border-color: #7246a7;
    box-shadow: 0 0 10px #7246a7;
  }

  100% {
    border-color: #7843ff;
    box-shadow: 0 0 5px #7843ff;
  }
}

@keyframes fish-legendary-border {
  0% {
    border-color: #ffe669;
    box-shadow: 0 0 5px #ffe669;
  }

  50% {
    border-color: #fc932a;
    box-shadow: 0 0 10px #fc932a;
  }

  100% {
    border-color: #ffe669;
    box-shadow: 0 0 5px #ffe669;
  }
}

@keyframes fish-mythic-border {
  0% {
    border-color: #ff3045;
    box-shadow: 0 0 6px #ff3045;
  }

  50% {
    border-color: #b11156;
    box-shadow: 0 0 12px #b11156;
  }

  100% {
    border-color: #ff3045;
    box-shadow: 0 0 6px #ff3045;
  }
}
@keyframes fish-mythic-border {
  0% {
    border-color: #a617ff;
    box-shadow: 0 0 6px #a617ff;
  }

  50% {
    border-color: #ff26fb;
    box-shadow: 0 0 12px #ff26fb;
  }

  100% {
    border-color: #a617ff;
    box-shadow: 0 0 6px #a617ff;
  }
}
/* ===== Tablet layout ===== */

@media screen and (max-width: 900px) {
  .entry-choice-box {
    padding: 18px;
    gap: 18px;
  }

  .entry-choice-pill {
    width: 260px;
    height: 250px;
    flex: 0 0 260px;
  }

  .entry-choice-pill img {
    max-width: 170px;
    max-height: 170px;
  }

  .entry-choice-text {
    font-size: 38px;
  }

  .entry-library {
    flex-direction: column;
    padding: 18px;
    gap: 18px;
  }

  .entry-side {
    width: 100%;
    flex: 0 0 auto;

    flex-direction: row;
    flex-wrap: wrap;
    justify-content: center;
  }

  .entry-side-pill {
    width: 150px;
    height: 115px;
    flex: 0 0 150px;

    font-size: 20px;
  }

  .entry-content {
    width: 100%;
    min-height: 500px;
  }

  .entry-content-title {
    font-size: 36px;
    text-align: center;
  }

  .entries-grid {
    justify-content: center;
  }

  .fish-area-menu {
    /*
     * 75px + 10px gap + 75px = 160px.
     */
    grid-template-columns: repeat(6, 75px);
    justify-content: center;
    column-gap: 10px;
    row-gap: 10px;
  }

  .fish-area-icon {
    width: 160px;
    height: 160px;

    grid-column: span 2;
    justify-self: center;
  }

  .fish-area-icon img {
    max-width: 100px;
    max-height: 100px;
  }

  .fish-area-name {
    top: -10px;
    margin-top: -5px;
    font-size: 16px;
  }

  .fish-area-icon:nth-child(4) {
    grid-column: 2 / span 2;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 4 / span 2;
  }
}

/* ===== Phone layout ===== */

@media screen and (max-width: 600px) {
  .entry-choice-box {
    min-height: 0;
    padding: 12px;
    gap: 14px;
  }

  .entry-choice-pill {
    width: 100%;
    height: 190px;
    flex: 0 0 100%;

    border-radius: 18px;
  }

  .entry-choice-pill img {
    max-width: 120px;
    max-height: 120px;
  }

  .entry-choice-text {
    font-size: 32px;
  }

  .entry-library {
    padding: 12px;
    gap: 12px;

    border-radius: 18px;
  }

  .entry-side {
    gap: 10px;
  }

  .entry-side-pill {
    width: 31%;
    min-width: 90px;
    height: 90px;
    flex: 0 0 31%;

    font-size: 14px;
    border-width: 3px;
    border-radius: 16px;
  }

  .entry-side-pill img {
    max-width: 48px;
    max-height: 48px;
  }

  .entry-content {
    min-height: 560px;
    padding: 14px;

    border-radius: 18px;
  }

  .entry-content-title {
    margin-bottom: 14px;

    font-size: 30px;
    text-align: center;
  }

  .entry-subtabs {
    justify-content: center;
    flex-wrap: wrap;
    margin-bottom: 8px;
  }

  .entry-subtab {
    padding: 7px 14px;
    font-size: 18px;
  }

  /* 2 + 2 + 1 centred */

  .fish-area-menu {
    grid-template-columns: repeat(2, 135px);
    justify-content: center;
    column-gap: 10px;
    row-gap: 10px;

    margin: 0;
    padding: 0;
  }

  .fish-area-icon {
    width: 135px;
    height: 135px;

    grid-column: auto;
    justify-self: center;

    padding: 6px;
    border-radius: 18px;
  }

  .fish-area-icon img {
    max-width: 82px;
    max-height: 82px;
  }

  .fish-area-name {
    top: -8px;
    margin-top: -5px;
    font-size: 14px;
  }

  .fish-area-icon:nth-child(4) {
    grid-column: auto;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 1 / -1;
    justify-self: center;
  }

  .fish-group-heading {
    gap: 10px;
  }

  .fish-group-title {
    font-size: 22px;
  }

  .fish-group-back {
    padding: 7px 12px;
    font-size: 14px;
  }

  .entry-card {
    width: 110px;
    height: 135px;
    padding: 8px;
  }

  .entry-card img {
    max-width: 82px;
    max-height: 82px;
  }

  .entry-card-name {
    margin-top: -15px;
    font-size: 14px;
  }

  .entry-detail-panel {
    padding: 14px;
    overflow: auto;
  }

  .entry-detail-top {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .entry-detail-image {
    text-align: center;
  }

  .entry-detail-image img {
    max-width: 110px;
    max-height: 110px;
  }

  .entry-detail-name {
    font-size: 30px;
  }

  .entry-detail-back {
    justify-self: center;
    text-align: center;
  }

  .entry-detail-body {
    font-size: 16px;
    text-align: center;
  }
}

/* ===== Very small phones ===== */

@media screen and (max-width: 380px) {
  .entry-choice-pill {
    height: 165px;
  }

  .entry-choice-pill img {
    max-width: 95px;
    max-height: 95px;
  }

  .entry-choice-text {
    font-size: 26px;
  }

  .entry-side-pill {
    width: 100%;
    height: 75px;
    flex: 0 0 100%;

    flex-direction: row;
    font-size: 16px;
  }

  .entry-side-pill img {
    max-width: 42px;
    max-height: 42px;
  }

  .fish-area-menu {
    grid-template-columns: repeat(2, 120px);
    justify-content: center;
    column-gap: 8px;
    row-gap: 8px;
  }

  .fish-area-icon {
    width: 120px;
    height: 120px;

    grid-column: auto;
    justify-self: center;

    padding: 5px;
    border-radius: 16px;
  }

  .fish-area-icon img {
    max-width: 70px;
    max-height: 70px;
  }

  .fish-area-name {
    top: -6px;
    margin-top: -4px;
    font-size: 12px;
  }

  .fish-area-icon:nth-child(4) {
    grid-column: auto;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 1 / -1;
    justify-self: center;
  }

  .fish-group-title {
    font-size: 19px;
  }

  .entry-card {
    width: 95px;
    height: 125px;
  }

  .entry-card img {
    max-width: 72px;
    max-height: 72px;
  }

  .entry-card-name {
    font-size: 12px;
  }

  .entry-detail-name {
    font-size: 24px;
  }

  .entry-detail-body {
    font-size: 14px;
  }
}

/* ===== Compact fish-menu screen ===== */

/*
 * The fish content panel becomes shorter.
 * Items, Tools and Enchants keep their original
 * equal sidebar spacing.
 */

.entry-library-items.entry-fish-menu-open {
  min-height: 0;
  padding-bottom: 12px;
}

.entry-library-items.entry-fish-menu-open .entry-content {
  min-height: 0;
  height: auto;

  align-self: flex-start;
  padding-bottom: 12px;
}

@media screen and (max-width: 900px) {
  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0;
  }
}

@media screen and (max-width: 600px) {
  .entry-library-items.entry-fish-menu-open {
    min-height: 0;
    padding-bottom: 8px;
  }

  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0;
    padding-bottom: 8px;
  }
}

/* ===== Hidden page image ===== */

.hidden-pageimage {
  position: absolute;

  width: 0;
  height: 0;

  overflow: hidden;
}

.hidden-pageimage img {
  width: 0;
  height: 0;
}

.entry-ui {
  width: 100%;
  max-width: 1075px;
  box-sizing: border-box;
}

/* ===== Main category selection ===== */

.entry-choice-box {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: 28px;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;
  box-sizing: border-box;
}

.entry-choice-pill {
  width: 320px;
  height: 300px;
  flex: 0 0 320px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 26px;

  text-align: center;
  box-sizing: border-box;
  cursor: pointer;
}

.entry-choice-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-choice-pill img {
  max-width: 220px;
  max-height: 220px;
  width: auto;
  height: auto;
}

.entry-choice-text {
  display: block;

  color: #4f8cff;
  font-size: 50px;
  line-height: 1;
  white-space: nowrap;
}

/* ===== Entry library ===== */

.entry-library {
  display: none;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;

  padding: 24px;
  gap: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

/* ===== Left navigation ===== */

.entry-side {
  width: 190px;
  flex: 0 0 190px;

  display: flex;
  flex-direction: column;
  gap: 18px;

  align-self: stretch;
}

.entry-side-pill {
  width: 170px;
  flex: 1;
  min-height: 135px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  color: #4f8cff;
  font-size: 24px;
  font-weight: bold;
  line-height: 1;
  text-align: center;

  box-sizing: border-box;
  cursor: pointer;
}

.entry-side-pill img {
  max-width: 80px;
  max-height: 80px;
  width: auto;
  height: auto;
}

.entry-side-pill div {
  margin-top: 0;
}

.entry-side-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Main content ===== */

.entry-content {
  position: relative;
  overflow: hidden;

  flex: 1;
  min-width: 0;
  min-height: 430px;

  padding: 24px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

.entry-content-title {
  margin-bottom: 20px;

  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
}

/* ===== Item subtabs ===== */

.entry-subtabs {
  display: flex;
  gap: 12px;
  margin-bottom: 8px;
}

.entry-subtab {
  padding: 8px 18px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 999px;

  color: #4f8cff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
}

.entry-subtab:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-subcontent {
  display: none;
}

/* Remove empty MediaWiki paragraphs */

.entry-subcontent-fish > p {
  display: none;
  margin: 0;
  padding: 0;
}

/* ===== Fish subicon menu ===== */

.fish-area-menu {
  display: none;

  width: 100%;

  /*
   * Each icon spans two 83px columns:
   * 83px + 14px gap + 83px = 180px.
   */
  grid-template-columns: repeat(6, 83px);
  justify-content: center;
  column-gap: 14px;
  row-gap: 14px;

  margin: 0;
  padding: 0;

  box-sizing: border-box;
}

.fish-area-icon {
  width: 180px;
  height: 180px;
  min-width: 0;

  grid-column: span 2;
  justify-self: center;

  padding: 10px 8px 6px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 22px;

  text-align: center;

  box-sizing: border-box;
  cursor: pointer;
  overflow: hidden;
}

.fish-area-icon:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.fish-area-icon img {
  display: block;

  max-width: 115px;
  max-height: 115px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.fish-area-name {
  position: relative;
  top: -12px;

  width: 100%;
  margin-top: -5px;
  padding: 0;

  color: #4f8cff;
  font-size: 18px;
  font-weight: bold;
  line-height: 1;

  text-align: center;
  white-space: normal;
  word-wrap: break-word;
}

/* Centre subicons 4 and 5 on the second row */

.fish-area-icon:nth-child(4) {
  grid-column: 2 / span 2;
}

.fish-area-icon:nth-child(5) {
  grid-column: 4 / span 2;
}

.fish-area-icon.entry-active {
  background: #17346b;
  border-color: #5aaeff;
}

/* ===== Selected fish group ===== */

.fish-group {
  display: none;
}

.fish-group-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;

  margin-bottom: 18px;
}

.fish-group-title {
  color: #4f8cff;
  font-size: 28px;
  font-weight: bold;
}

.fish-group-back {
  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;

  cursor: pointer;
}

.fish-group-back:hover {
  background: #1f4388;
}

/* ===== Entry cards ===== */

.entries-grid {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-content: flex-start;
  gap: 12px;
}

.entry-card {
  position: relative;

  width: 130px;
  height: 150px;
  padding: 10px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 18px;

  text-align: center;

  box-sizing: border-box;
  overflow: visible;
  cursor: pointer;
}

.entry-card:hover {
  background: #10275a;
}

.entry-card img {
  max-width: 100px;
  max-height: 100px;
  width: auto;
  height: auto;
}

.entry-card-name {
  margin-top: -30px;

  font-size: 16px;
  font-weight: bold;
  line-height: 1;
}

.entry-card-items {
  border-color: #5aaeff;
}

.entry-card-tools {
  border-color: #69e8f4;
}

.entry-card-enchants {
  border-color: #9666ff;
}

/* ===== Entry detail page ===== */

.entry-detail-panel {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  z-index: 50;

  padding: 24px;

  background: #0b0f17;
  border-radius: 20px;

  box-sizing: border-box;
}

.entry-detail-top {
  display: grid;
  grid-template-columns: 160px 1fr 120px;
  align-items: center;
  gap: 20px;
}

.entry-detail-image {
  text-align: left;
}

.entry-detail-image img {
  max-width: 140px;
  max-height: 140px;
  width: auto;
  height: auto;
}

.entry-detail-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
}

.entry-detail-name {
  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  text-align: center;
}

.entry-detail-rarity {
  text-align: center;
}

.entry-rarity-pill {
  display: inline-block;

  padding: 8px 16px;

  background: #0b0f17;
  border: 2px solid #222831;
  border-radius: 999px;

  font-weight: bold;
  line-height: 1;
}

.entry-detail-back {
  justify-self: end;
  display: inline-block;

  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;
  text-decoration: none;

  cursor: pointer;
}

.entry-detail-back:hover {
  background: #1f4388;
}

.entry-detail-body {
  margin-top: 28px;

  color: #ffffff;
  font-size: 18px;
  line-height: 1.4;
}

/* ===== Active states ===== */

.js-entry-open {
  cursor: pointer;
}

.entry-side-pill.entry-active,
.entry-subtab.entry-active {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Rarity name animations ===== */

.entry-name-rarity-common {
  animation: fish-common-name 2s ease-in-out infinite;
}

.entry-name-rarity-uncommon {
  animation: fish-uncommon-name 2s ease-in-out infinite;
}

.entry-name-rarity-rare {
  animation: fish-rare-name 2s ease-in-out infinite;
}

.entry-name-rarity-epic {
  animation: fish-epic-name 2s ease-in-out infinite;
}

.entry-name-rarity-legendary {
  animation: fish-legendary-name 2s ease-in-out infinite;
}

.entry-name-rarity-mythic {
  animation: fish-mythic-name 2s ease-in-out infinite;
}

.entry-name-rarity-secret {
  animation: fish-secret-name 2s ease-in-out infinite;
}
@keyframes fish-common-name {
  0% {
    color: #a8b1b6;
  }

  50% {
    color: #7f8c99;
  }

  100% {
    color: #a8b1b6;
  }
}

@keyframes fish-uncommon-name {
  0% {
    color: #67ec88;
  }

  50% {
    color: #63c138;
  }

  100% {
    color: #67ec88;
  }
}

@keyframes fish-rare-name {
  0% {
    color: #4ad8ff;
  }

  50% {
    color: #3d93fc;
  }

  100% {
    color: #4ad8ff;
  }
}

@keyframes fish-epic-name {
  0% {
    color: #7843ff;
  }

  50% {
    color: #7246a7;
  }

  100% {
    color: #7843ff;
  }
}

@keyframes fish-legendary-name {
  0% {
    color: #ffe669;
  }

  50% {
    color: #fc932a;
  }

  100% {
    color: #ffe669;
  }
}

@keyframes fish-mythic-name {
  0% {
    color: #ff3045;
  }

  50% {
    color: #b11156;
  }

  100% {
    color: #ff3045;
  }
}

@keyframes fish-secret-name {
  0% {
    color: #a617ff;
  }

  50% {
    color: #ff26fb;
  }

  100% {
    color: #a617ff;
  }
}
/* ===== Rarity border animations ===== */

.entry-card-rarity-none {
  border-color: #222831;
  box-shadow: none;
}

.entry-card-rarity-common {
  animation: fish-common-border 2s ease-in-out infinite;
}

.entry-card-rarity-uncommon {
  animation: fish-uncommon-border 2s ease-in-out infinite;
}

.entry-card-rarity-rare {
  animation: fish-rare-border 2s ease-in-out infinite;
}

.entry-card-rarity-epic {
  animation: fish-epic-border 2s ease-in-out infinite;
}

.entry-card-rarity-legendary {
  animation: fish-legendary-border 2s ease-in-out infinite;
}

.entry-card-rarity-mythic {
  animation: fish-mythic-border 2s ease-in-out infinite;
}
.entry-card-rarity-secret {
  animation: fish-secret-border 2s ease-in-out infinite;
}
@keyframes fish-common-border {
  0% {
    border-color: #a8b1b6;
    box-shadow: 0 0 5px #a8b1b6;
  }

  50% {
    border-color: #7f8c99;
    box-shadow: 0 0 10px #7f8c99;
  }

  100% {
    border-color: #a8b1b6;
    box-shadow: 0 0 5px #a8b1b6;
  }
}

@keyframes fish-uncommon-border {
  0% {
    border-color: #67ec88;
    box-shadow: 0 0 5px #67ec88;
  }

  50% {
    border-color: #63c138;
    box-shadow: 0 0 10px #63c138;
  }

  100% {
    border-color: #67ec88;
    box-shadow: 0 0 5px #67ec88;
  }
}

@keyframes fish-rare-border {
  0% {
    border-color: #4ad8ff;
    box-shadow: 0 0 5px #4ad8ff;
  }

  50% {
    border-color: #3d93fc;
    box-shadow: 0 0 10px #3d93fc;
  }

  100% {
    border-color: #4ad8ff;
    box-shadow: 0 0 5px #4ad8ff;
  }
}

@keyframes fish-epic-border {
  0% {
    border-color: #7843ff;
    box-shadow: 0 0 5px #7843ff;
  }

  50% {
    border-color: #7246a7;
    box-shadow: 0 0 10px #7246a7;
  }

  100% {
    border-color: #7843ff;
    box-shadow: 0 0 5px #7843ff;
  }
}

@keyframes fish-legendary-border {
  0% {
    border-color: #ffe669;
    box-shadow: 0 0 5px #ffe669;
  }

  50% {
    border-color: #fc932a;
    box-shadow: 0 0 10px #fc932a;
  }

  100% {
    border-color: #ffe669;
    box-shadow: 0 0 5px #ffe669;
  }
}

@keyframes fish-mythic-border {
  0% {
    border-color: #ff3045;
    box-shadow: 0 0 6px #ff3045;
  }

  50% {
    border-color: #b11156;
    box-shadow: 0 0 12px #b11156;
  }

  100% {
    border-color: #ff3045;
    box-shadow: 0 0 6px #ff3045;
  }
}
@keyframes fish-mythic-border {
  0% {
    border-color: #a617ff;
    box-shadow: 0 0 6px #a617ff;
  }

  50% {
    border-color: #ff26fb;
    box-shadow: 0 0 12px #ff26fb;
  }

  100% {
    border-color: #a617ff;
    box-shadow: 0 0 6px #a617ff;
  }
}
/* ===== Tablet layout ===== */

@media screen and (max-width: 900px) {
  .entry-choice-box {
    padding: 18px;
    gap: 18px;
  }

  .entry-choice-pill {
    width: 260px;
    height: 250px;
    flex: 0 0 260px;
  }

  .entry-choice-pill img {
    max-width: 170px;
    max-height: 170px;
  }

  .entry-choice-text {
    font-size: 38px;
  }

  .entry-library {
    flex-direction: column;
    padding: 18px;
    gap: 18px;
  }

  .entry-side {
    width: 100%;
    flex: 0 0 auto;

    flex-direction: row;
    flex-wrap: wrap;
    justify-content: center;
  }

  .entry-side-pill {
    width: 150px;
    height: 115px;
    flex: 0 0 150px;

    font-size: 20px;
  }

  .entry-content {
    width: 100%;
    min-height: 500px;
  }

  .entry-content-title {
    font-size: 36px;
    text-align: center;
  }

  .entries-grid {
    justify-content: center;
  }

  .fish-area-menu {
    /*
     * 75px + 10px gap + 75px = 160px.
     */
    grid-template-columns: repeat(6, 75px);
    justify-content: center;
    column-gap: 10px;
    row-gap: 10px;
  }

  .fish-area-icon {
    width: 160px;
    height: 160px;

    grid-column: span 2;
    justify-self: center;
  }

  .fish-area-icon img {
    max-width: 100px;
    max-height: 100px;
  }

  .fish-area-name {
    top: -10px;
    margin-top: -5px;
    font-size: 16px;
  }

  .fish-area-icon:nth-child(4) {
    grid-column: 2 / span 2;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 4 / span 2;
  }
}

/* ===== Phone layout ===== */

@media screen and (max-width: 600px) {
  .entry-choice-box {
    min-height: 0;
    padding: 12px;
    gap: 14px;
  }

  .entry-choice-pill {
    width: 100%;
    height: 190px;
    flex: 0 0 100%;

    border-radius: 18px;
  }

  .entry-choice-pill img {
    max-width: 120px;
    max-height: 120px;
  }

  .entry-choice-text {
    font-size: 32px;
  }

  .entry-library {
    padding: 12px;
    gap: 12px;

    border-radius: 18px;
  }

  .entry-side {
    gap: 10px;
  }

  .entry-side-pill {
    width: 31%;
    min-width: 90px;
    height: 90px;
    flex: 0 0 31%;

    font-size: 14px;
    border-width: 3px;
    border-radius: 16px;
  }

  .entry-side-pill img {
    max-width: 48px;
    max-height: 48px;
  }

  .entry-content {
    min-height: 560px;
    padding: 14px;

    border-radius: 18px;
  }

  .entry-content-title {
    margin-bottom: 14px;

    font-size: 30px;
    text-align: center;
  }

  .entry-subtabs {
    justify-content: center;
    flex-wrap: wrap;
    margin-bottom: 8px;
  }

  .entry-subtab {
    padding: 7px 14px;
    font-size: 18px;
  }

  /* 2 + 2 + 1 centred */

  .fish-area-menu {
    grid-template-columns: repeat(2, 135px);
    justify-content: center;
    column-gap: 10px;
    row-gap: 10px;

    margin: 0;
    padding: 0;
  }

  .fish-area-icon {
    width: 135px;
    height: 135px;

    grid-column: auto;
    justify-self: center;

    padding: 6px;
    border-radius: 18px;
  }

  .fish-area-icon img {
    max-width: 82px;
    max-height: 82px;
  }

  .fish-area-name {
    top: -8px;
    margin-top: -5px;
    font-size: 14px;
  }

  .fish-area-icon:nth-child(4) {
    grid-column: auto;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 1 / -1;
    justify-self: center;
  }

  .fish-group-heading {
    gap: 10px;
  }

  .fish-group-title {
    font-size: 22px;
  }

  .fish-group-back {
    padding: 7px 12px;
    font-size: 14px;
  }

  .entry-card {
    width: 110px;
    height: 135px;
    padding: 8px;
  }

  .entry-card img {
    max-width: 82px;
    max-height: 82px;
  }

  .entry-card-name {
    margin-top: -15px;
    font-size: 14px;
  }

  .entry-detail-panel {
    padding: 14px;
    overflow: auto;
  }

  .entry-detail-top {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .entry-detail-image {
    text-align: center;
  }

  .entry-detail-image img {
    max-width: 110px;
    max-height: 110px;
  }

  .entry-detail-name {
    font-size: 30px;
  }

  .entry-detail-back {
    justify-self: center;
    text-align: center;
  }

  .entry-detail-body {
    font-size: 16px;
    text-align: center;
  }
}

/* ===== Very small phones ===== */

@media screen and (max-width: 380px) {
  .entry-choice-pill {
    height: 165px;
  }

  .entry-choice-pill img {
    max-width: 95px;
    max-height: 95px;
  }

  .entry-choice-text {
    font-size: 26px;
  }

  .entry-side-pill {
    width: 100%;
    height: 75px;
    flex: 0 0 100%;

    flex-direction: row;
    font-size: 16px;
  }

  .entry-side-pill img {
    max-width: 42px;
    max-height: 42px;
  }

  .fish-area-menu {
    grid-template-columns: repeat(2, 120px);
    justify-content: center;
    column-gap: 8px;
    row-gap: 8px;
  }

  .fish-area-icon {
    width: 120px;
    height: 120px;

    grid-column: auto;
    justify-self: center;

    padding: 5px;
    border-radius: 16px;
  }

  .fish-area-icon img {
    max-width: 70px;
    max-height: 70px;
  }

  .fish-area-name {
    top: -6px;
    margin-top: -4px;
    font-size: 12px;
  }

  .fish-area-icon:nth-child(4) {
    grid-column: auto;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 1 / -1;
    justify-self: center;
  }

  .fish-group-title {
    font-size: 19px;
  }

  .entry-card {
    width: 95px;
    height: 125px;
  }

  .entry-card img {
    max-width: 72px;
    max-height: 72px;
  }

  .entry-card-name {
    font-size: 12px;
  }

  .entry-detail-name {
    font-size: 24px;
  }

  .entry-detail-body {
    font-size: 14px;
  }
}

/* ===== Compact fish-menu screen ===== */

/*
 * The fish content panel becomes shorter.
 * Items, Tools and Enchants keep their original
 * equal sidebar spacing.
 */

.entry-library-items.entry-fish-menu-open {
  min-height: 0;
  padding-bottom: 12px;
}

.entry-library-items.entry-fish-menu-open .entry-content {
  min-height: 0;
  height: auto;

  align-self: flex-start;
  padding-bottom: 12px;
}

@media screen and (max-width: 900px) {
  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0;
  }
}

@media screen and (max-width: 600px) {
  .entry-library-items.entry-fish-menu-open {
    min-height: 0;
    padding-bottom: 8px;
  }

  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0;
    padding-bottom: 8px;
  }
}

/* ===== Hidden page image ===== */

.hidden-pageimage {
  position: absolute;

  width: 0;
  height: 0;

  overflow: hidden;
}

.hidden-pageimage img {
  width: 0;
  height: 0;
}

.entry-ui {
  width: 100%;
  max-width: 1075px;
  box-sizing: border-box;
}

/* ===== Main category selection ===== */

.entry-choice-box {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: 28px;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;
  box-sizing: border-box;
}

.entry-choice-pill {
  width: 320px;
  height: 300px;
  flex: 0 0 320px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 26px;

  text-align: center;
  box-sizing: border-box;
  cursor: pointer;
}

.entry-choice-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-choice-pill img {
  max-width: 220px;
  max-height: 220px;
  width: auto;
  height: auto;
}

.entry-choice-text {
  display: block;

  color: #4f8cff;
  font-size: 50px;
  line-height: 1;
  white-space: nowrap;
}

/* ===== Entry library ===== */

.entry-library {
  display: none;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;

  padding: 24px;
  gap: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

/* ===== Left navigation ===== */

.entry-side {
  width: 190px;
  flex: 0 0 190px;

  display: flex;
  flex-direction: column;
  gap: 18px;

  align-self: stretch;
}

.entry-side-pill {
  width: 170px;
  flex: 1;
  min-height: 135px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  color: #4f8cff;
  font-size: 24px;
  font-weight: bold;
  line-height: 1;
  text-align: center;

  box-sizing: border-box;
  cursor: pointer;
}

.entry-side-pill img {
  max-width: 80px;
  max-height: 80px;
  width: auto;
  height: auto;
}

.entry-side-pill div {
  margin-top: 0;
}

.entry-side-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Main content ===== */

.entry-content {
  position: relative;
  overflow: hidden;

  flex: 1;
  min-width: 0;
  min-height: 430px;

  padding: 24px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

.entry-content-title {
  margin-bottom: 20px;

  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
}

/* ===== Item subtabs ===== */

.entry-subtabs {
  display: flex;
  gap: 12px;
  margin-bottom: 8px;
}

.entry-subtab {
  padding: 8px 18px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 999px;

  color: #4f8cff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
}

.entry-subtab:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-subcontent {
  display: none;
}

/* Remove empty MediaWiki paragraphs */

.entry-subcontent-fish > p {
  display: none;
  margin: 0;
  padding: 0;
}

/* ===== Fish subicon menu ===== */

.fish-area-menu {
  display: none;

  width: 100%;

  /*
   * Each icon spans two 83px columns:
   * 83px + 14px gap + 83px = 180px.
   */
  grid-template-columns: repeat(6, 83px);
  justify-content: center;
  column-gap: 14px;
  row-gap: 14px;

  margin: 0;
  padding: 0;

  box-sizing: border-box;
}

.fish-area-icon {
  width: 180px;
  height: 180px;
  min-width: 0;

  grid-column: span 2;
  justify-self: center;

  padding: 10px 8px 6px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 22px;

  text-align: center;

  box-sizing: border-box;
  cursor: pointer;
  overflow: hidden;
}

.fish-area-icon:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.fish-area-icon img {
  display: block;

  max-width: 115px;
  max-height: 115px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.fish-area-name {
  position: relative;
  top: -12px;

  width: 100%;
  margin-top: -5px;
  padding: 0;

  color: #4f8cff;
  font-size: 18px;
  font-weight: bold;
  line-height: 1;

  text-align: center;
  white-space: normal;
  word-wrap: break-word;
}

/* Centre subicons 4 and 5 on the second row */

.fish-area-icon:nth-child(4) {
  grid-column: 2 / span 2;
}

.fish-area-icon:nth-child(5) {
  grid-column: 4 / span 2;
}

.fish-area-icon.entry-active {
  background: #17346b;
  border-color: #5aaeff;
}

/* ===== Selected fish group ===== */

.fish-group {
  display: none;
}

.fish-group-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;

  margin-bottom: 18px;
}

.fish-group-title {
  color: #4f8cff;
  font-size: 28px;
  font-weight: bold;
}

.fish-group-back {
  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;

  cursor: pointer;
}

.fish-group-back:hover {
  background: #1f4388;
}

/* ===== Entry cards ===== */

.entries-grid {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-content: flex-start;
  gap: 12px;
}

.entry-card {
  position: relative;

  width: 130px;
  height: 150px;
  padding: 10px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 18px;

  text-align: center;

  box-sizing: border-box;
  overflow: visible;
  cursor: pointer;
}

.entry-card:hover {
  background: #10275a;
}

.entry-card img {
  max-width: 100px;
  max-height: 100px;
  width: auto;
  height: auto;
}

.entry-card-name {
  margin-top: -30px;

  font-size: 16px;
  font-weight: bold;
  line-height: 1;
}

.entry-card-items {
  border-color: #5aaeff;
}

.entry-card-tools {
  border-color: #69e8f4;
}

.entry-card-enchants {
  border-color: #9666ff;
}

/* ===== Entry detail page ===== */

.entry-detail-panel {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  z-index: 50;

  padding: 24px;

  background: #0b0f17;
  border-radius: 20px;

  box-sizing: border-box;
}

.entry-detail-top {
  display: grid;
  grid-template-columns: 160px 1fr 120px;
  align-items: center;
  gap: 20px;
}

.entry-detail-image {
  text-align: left;
}

.entry-detail-image img {
  max-width: 140px;
  max-height: 140px;
  width: auto;
  height: auto;
}

.entry-detail-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
}

.entry-detail-name {
  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  text-align: center;
}

.entry-detail-rarity {
  text-align: center;
}

.entry-rarity-pill {
  display: inline-block;

  padding: 8px 16px;

  background: #0b0f17;
  border: 2px solid #222831;
  border-radius: 999px;

  font-weight: bold;
  line-height: 1;
}

.entry-detail-back {
  justify-self: end;
  display: inline-block;

  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;
  text-decoration: none;

  cursor: pointer;
}

.entry-detail-back:hover {
  background: #1f4388;
}

.entry-detail-body {
  margin-top: 28px;

  color: #ffffff;
  font-size: 18px;
  line-height: 1.4;
}

/* ===== Active states ===== */

.js-entry-open {
  cursor: pointer;
}

.entry-side-pill.entry-active,
.entry-subtab.entry-active {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Rarity name animations ===== */

.entry-name-rarity-common {
  animation: fish-common-name 2s ease-in-out infinite;
}

.entry-name-rarity-uncommon {
  animation: fish-uncommon-name 2s ease-in-out infinite;
}

.entry-name-rarity-rare {
  animation: fish-rare-name 2s ease-in-out infinite;
}

.entry-name-rarity-epic {
  animation: fish-epic-name 2s ease-in-out infinite;
}

.entry-name-rarity-legendary {
  animation: fish-legendary-name 2s ease-in-out infinite;
}

.entry-name-rarity-mythic {
  animation: fish-mythic-name 2s ease-in-out infinite;
}

.entry-name-rarity-secret {
  animation: fish-secret-name 2s ease-in-out infinite;
}
@keyframes fish-common-name {
  0% {
    color: #a8b1b6;
  }

  50% {
    color: #7f8c99;
  }

  100% {
    color: #a8b1b6;
  }
}

@keyframes fish-uncommon-name {
  0% {
    color: #67ec88;
  }

  50% {
    color: #63c138;
  }

  100% {
    color: #67ec88;
  }
}

@keyframes fish-rare-name {
  0% {
    color: #4ad8ff;
  }

  50% {
    color: #3d93fc;
  }

  100% {
    color: #4ad8ff;
  }
}

@keyframes fish-epic-name {
  0% {
    color: #7843ff;
  }

  50% {
    color: #7246a7;
  }

  100% {
    color: #7843ff;
  }
}

@keyframes fish-legendary-name {
  0% {
    color: #ffe669;
  }

  50% {
    color: #fc932a;
  }

  100% {
    color: #ffe669;
  }
}

@keyframes fish-mythic-name {
  0% {
    color: #ff3045;
  }

  50% {
    color: #b11156;
  }

  100% {
    color: #ff3045;
  }
}

@keyframes fish-secret-name {
  0% {
    color: #a617ff;
  }

  50% {
    color: #ff26fb;
  }

  100% {
    color: #a617ff;
  }
}
/* ===== Rarity border animations ===== */

.entry-card-rarity-none {
  border-color: #222831;
  box-shadow: none;
}

.entry-card-rarity-common {
  animation: fish-common-border 2s ease-in-out infinite;
}

.entry-card-rarity-uncommon {
  animation: fish-uncommon-border 2s ease-in-out infinite;
}

.entry-card-rarity-rare {
  animation: fish-rare-border 2s ease-in-out infinite;
}

.entry-card-rarity-epic {
  animation: fish-epic-border 2s ease-in-out infinite;
}

.entry-card-rarity-legendary {
  animation: fish-legendary-border 2s ease-in-out infinite;
}

.entry-card-rarity-mythic {
  animation: fish-mythic-border 2s ease-in-out infinite;
}
.entry-card-rarity-secret {
  animation: fish-secret-border 2s ease-in-out infinite;
}
@keyframes fish-common-border {
  0% {
    border-color: #a8b1b6;
    box-shadow: 0 0 5px #a8b1b6;
  }

  50% {
    border-color: #7f8c99;
    box-shadow: 0 0 10px #7f8c99;
  }

  100% {
    border-color: #a8b1b6;
    box-shadow: 0 0 5px #a8b1b6;
  }
}

@keyframes fish-uncommon-border {
  0% {
    border-color: #67ec88;
    box-shadow: 0 0 5px #67ec88;
  }

  50% {
    border-color: #63c138;
    box-shadow: 0 0 10px #63c138;
  }

  100% {
    border-color: #67ec88;
    box-shadow: 0 0 5px #67ec88;
  }
}

@keyframes fish-rare-border {
  0% {
    border-color: #4ad8ff;
    box-shadow: 0 0 5px #4ad8ff;
  }

  50% {
    border-color: #3d93fc;
    box-shadow: 0 0 10px #3d93fc;
  }

  100% {
    border-color: #4ad8ff;
    box-shadow: 0 0 5px #4ad8ff;
  }
}

@keyframes fish-epic-border {
  0% {
    border-color: #7843ff;
    box-shadow: 0 0 5px #7843ff;
  }

  50% {
    border-color: #7246a7;
    box-shadow: 0 0 10px #7246a7;
  }

  100% {
    border-color: #7843ff;
    box-shadow: 0 0 5px #7843ff;
  }
}

@keyframes fish-legendary-border {
  0% {
    border-color: #ffe669;
    box-shadow: 0 0 5px #ffe669;
  }

  50% {
    border-color: #fc932a;
    box-shadow: 0 0 10px #fc932a;
  }

  100% {
    border-color: #ffe669;
    box-shadow: 0 0 5px #ffe669;
  }
}

@keyframes fish-mythic-border {
  0% {
    border-color: #ff3045;
    box-shadow: 0 0 6px #ff3045;
  }

  50% {
    border-color: #b11156;
    box-shadow: 0 0 12px #b11156;
  }

  100% {
    border-color: #ff3045;
    box-shadow: 0 0 6px #ff3045;
  }
}
@keyframes fish-secret-border {
  0% {
    border-color: #a617ff;
    box-shadow: 0 0 6px #a617ff;
  }

  50% {
    border-color: #ff26fb;
    box-shadow: 0 0 12px #ff26fb;
  }

  100% {
    border-color: #a617ff;
    box-shadow: 0 0 6px #a617ff;
  }
}
/* ===== Tablet layout ===== */

@media screen and (max-width: 900px) {
  .entry-choice-box {
    padding: 18px;
    gap: 18px;
  }

  .entry-choice-pill {
    width: 260px;
    height: 250px;
    flex: 0 0 260px;
  }

  .entry-choice-pill img {
    max-width: 170px;
    max-height: 170px;
  }

  .entry-choice-text {
    font-size: 38px;
  }

  .entry-library {
    flex-direction: column;
    padding: 18px;
    gap: 18px;
  }

  .entry-side {
    width: 100%;
    flex: 0 0 auto;

    flex-direction: row;
    flex-wrap: wrap;
    justify-content: center;
  }

  .entry-side-pill {
    width: 150px;
    height: 115px;
    flex: 0 0 150px;

    font-size: 20px;
  }

  .entry-content {
    width: 100%;
    min-height: 500px;
  }

  .entry-content-title {
    font-size: 36px;
    text-align: center;
  }

  .entries-grid {
    justify-content: center;
  }

  .fish-area-menu {
    /*
     * 75px + 10px gap + 75px = 160px.
     */
    grid-template-columns: repeat(6, 75px);
    justify-content: center;
    column-gap: 10px;
    row-gap: 10px;
  }

  .fish-area-icon {
    width: 160px;
    height: 160px;

    grid-column: span 2;
    justify-self: center;
  }

  .fish-area-icon img {
    max-width: 100px;
    max-height: 100px;
  }

  .fish-area-name {
    top: -10px;
    margin-top: -5px;
    font-size: 16px;
  }

  .fish-area-icon:nth-child(4) {
    grid-column: 2 / span 2;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 4 / span 2;
  }
}

/* ===== Phone layout ===== */

@media screen and (max-width: 600px) {
  .entry-choice-box {
    min-height: 0;
    padding: 12px;
    gap: 14px;
  }

  .entry-choice-pill {
    width: 100%;
    height: 190px;
    flex: 0 0 100%;

    border-radius: 18px;
  }

  .entry-choice-pill img {
    max-width: 120px;
    max-height: 120px;
  }

  .entry-choice-text {
    font-size: 32px;
  }

  .entry-library {
    padding: 12px;
    gap: 12px;

    border-radius: 18px;
  }

  .entry-side {
    gap: 10px;
  }

  .entry-side-pill {
    width: 31%;
    min-width: 90px;
    height: 90px;
    flex: 0 0 31%;

    font-size: 14px;
    border-width: 3px;
    border-radius: 16px;
  }

  .entry-side-pill img {
    max-width: 48px;
    max-height: 48px;
  }

  .entry-content {
    min-height: 560px;
    padding: 14px;

    border-radius: 18px;
  }

  .entry-content-title {
    margin-bottom: 14px;

    font-size: 30px;
    text-align: center;
  }

  .entry-subtabs {
    justify-content: center;
    flex-wrap: wrap;
    margin-bottom: 8px;
  }

  .entry-subtab {
    padding: 7px 14px;
    font-size: 18px;
  }

  /* 2 + 2 + 1 centred */

  .fish-area-menu {
    grid-template-columns: repeat(2, 135px);
    justify-content: center;
    column-gap: 10px;
    row-gap: 10px;

    margin: 0;
    padding: 0;
  }

  .fish-area-icon {
    width: 135px;
    height: 135px;

    grid-column: auto;
    justify-self: center;

    padding: 6px;
    border-radius: 18px;
  }

  .fish-area-icon img {
    max-width: 82px;
    max-height: 82px;
  }

  .fish-area-name {
    top: -8px;
    margin-top: -5px;
    font-size: 14px;
  }

  .fish-area-icon:nth-child(4) {
    grid-column: auto;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 1 / -1;
    justify-self: center;
  }

  .fish-group-heading {
    gap: 10px;
  }

  .fish-group-title {
    font-size: 22px;
  }

  .fish-group-back {
    padding: 7px 12px;
    font-size: 14px;
  }

  .entry-card {
    width: 110px;
    height: 135px;
    padding: 8px;
  }

  .entry-card img {
    max-width: 82px;
    max-height: 82px;
  }

  .entry-card-name {
    margin-top: -15px;
    font-size: 14px;
  }

  .entry-detail-panel {
    padding: 14px;
    overflow: auto;
  }

  .entry-detail-top {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .entry-detail-image {
    text-align: center;
  }

  .entry-detail-image img {
    max-width: 110px;
    max-height: 110px;
  }

  .entry-detail-name {
    font-size: 30px;
  }

  .entry-detail-back {
    justify-self: center;
    text-align: center;
  }

  .entry-detail-body {
    font-size: 16px;
    text-align: center;
  }
}

/* ===== Very small phones ===== */

@media screen and (max-width: 380px) {
  .entry-choice-pill {
    height: 165px;
  }

  .entry-choice-pill img {
    max-width: 95px;
    max-height: 95px;
  }

  .entry-choice-text {
    font-size: 26px;
  }

  .entry-side-pill {
    width: 100%;
    height: 75px;
    flex: 0 0 100%;

    flex-direction: row;
    font-size: 16px;
  }

  .entry-side-pill img {
    max-width: 42px;
    max-height: 42px;
  }

  .fish-area-menu {
    grid-template-columns: repeat(2, 120px);
    justify-content: center;
    column-gap: 8px;
    row-gap: 8px;
  }

  .fish-area-icon {
    width: 120px;
    height: 120px;

    grid-column: auto;
    justify-self: center;

    padding: 5px;
    border-radius: 16px;
  }

  .fish-area-icon img {
    max-width: 70px;
    max-height: 70px;
  }

  .fish-area-name {
    top: -6px;
    margin-top: -4px;
    font-size: 12px;
  }

  .fish-area-icon:nth-child(4) {
    grid-column: auto;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 1 / -1;
    justify-self: center;
  }

  .fish-group-title {
    font-size: 19px;
  }

  .entry-card {
    width: 95px;
    height: 125px;
  }

  .entry-card img {
    max-width: 72px;
    max-height: 72px;
  }

  .entry-card-name {
    font-size: 12px;
  }

  .entry-detail-name {
    font-size: 24px;
  }

  .entry-detail-body {
    font-size: 14px;
  }
}

/* ===== Compact fish-menu screen ===== */

/*
 * The fish content panel becomes shorter.
 * Items, Tools and Enchants keep their original
 * equal sidebar spacing.
 */

.entry-library-items.entry-fish-menu-open {
  min-height: 0;
  padding-bottom: 12px;
}

.entry-library-items.entry-fish-menu-open .entry-content {
  min-height: 0;
  height: auto;

  align-self: flex-start;
  padding-bottom: 12px;
}

@media screen and (max-width: 900px) {
  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0;
  }
}

@media screen and (max-width: 600px) {
  .entry-library-items.entry-fish-menu-open {
    min-height: 0;
    padding-bottom: 8px;
  }

  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0;
    padding-bottom: 8px;
  }
}

/* ===== Hidden page image ===== */

.hidden-pageimage {
  position: absolute;

  width: 0;
  height: 0;

  overflow: hidden;
}

.hidden-pageimage img {
  width: 0;
  height: 0;
}

