mw.loader.using('mediawiki.util').then(() => {
    if (mw.config.get('wgPageName') !== 'Your_Page_Name') {
        return;
    }

    const quotes = [
	    "Idk - mobogreat",
	    "idk again - mobogreat"
	];

	document.getElementById("newQuote").onclick = () => {
	    document.getElementById("quote").textContent =
	        quotes[Math.floor(Math.random() * quotes.length)];
	};
});

if (mw.config.get("wgPageName") === "Jerry") {
    const quotes = [
        "buff momentum - tin",
        "nerf momentum - tin",
        "we are still not affiliated with upgradex.com.au - Veemo10 (@PacificInTheSeaWing)",
        "what if the real upgradex was the friends we made along the way - Veemo10 (@PacificInTheSeaWing)",
        "First we upgradex, then we wiki, let's upgradex wiki!! - Veemo10 (@PacificInTheSeaWing)",
        "Pretty please dont steal assets - Signal-Noise",
        "remember to touch gra- oh your pointing a gun at me nevermind - Probable"
    ];

    const container = document.getElementById("quote-widget");

    if (!container) {
        return;
    }

    const quote = document.createElement("div");
    const button = document.createElement("button");

    button.textContent = "New Quote";

    let lastQuote = -1;

    function randomQuote() {
        let newQuote;

        do {
            newQuote = Math.floor(Math.random() * quotes.length);
        } while (newQuote === lastQuote && quotes.length > 1);

        lastQuote = newQuote;
        quote.textContent = quotes[newQuote];
    }

    button.addEventListener("click", randomQuote);

    randomQuote();

    container.appendChild(quote);
    container.appendChild(document.createElement("br"));
    container.appendChild(button);
}

