    ];

    const container = document.getElementById("quote-widget");

    if (!container) {
    	console.log("Container not available")
    }

    console.log("Container Exists")

    const quote = document.createElement("div");
    const button = document.createElement("button");

    button.textContent = "New Quote";

    let lastQuote = -1;

    function randomQuote() {
        let newQuote;

        do {
            newQuote = Math.floor(Math.random() * quotes.length);
        } while (newQuote === lastQuote && quotes.length > 1);

        lastQuote = newQuote;
        quote.textContent = quotes[newQuote];
    }

    button.addEventListener("click", randomQuote);

    randomQuote();

    container.appendChild(quote);
    container.appendChild(document.createElement("br"));
    container.appendChild(button);
}

