    		{ name: 'Less Backfire', file: 'less_backfire.png', levelMult: 0.7, colorClass: 'enchant-bg-less-backfire' },
    		{ name: 'Sharpshooter', file: 'Sharpshooter.png', levelMult: 0.5, colorClass: 'enchant-bg-sharpshooter' }
		];
	} else {
		enchants = [
    		{ name: 'Strength', file: 'strength.png', levelMult: 0.8, colorClass: 'enchant-bg-strength' },
    		{ name: 'Strength+', file: 'Strength+.png', levelMult: 0.5, colorClass: 'enchant-bg-strength-plus' },
    		{ name: 'Momentum', file: 'Momentum.png', levelMult: 0.7, colorClass: 'enchant-bg-momentum' },
    		{ name: 'Momentum+', file: 'Momentum+.png', levelMult: 0.4, colorClass: 'enchant-bg-momentum-plus' },
    		{ name: 'Fortune', file: 'Fortune.png', levelMult: 0.6, colorClass: 'enchant-bg-fortune' },
    		{ name: 'Ultra', file: 'Ultra.png', levelMult: 0.3, colorClass: 'enchant-bg-ultra' }
		];
	}

    grid.empty();

    enchants.forEach(function (enchant) {
      var levelRange = calculateEnchantLevelRange(fishPoints, enchant.levelMult);
      var imgUrl = mw.util.getUrl('Special:Redirect/file/' + enchant.file);

      var card = $('<div>')
		.addClass('enchant-result-card')
		.addClass(enchant.colorClass);

      $('<img>')
        .attr('src', imgUrl)
        .attr('alt', enchant.name)
        .appendTo(card);

      $('<div>')
        .addClass('enchant-result-name')
        .text(enchant.name)
        .appendTo(card);

      $('<div>')
        .addClass('enchant-result-level')
        .text('Level ' + levelRange.min + ' - ' + levelRange.max)
        .appendTo(card);

      grid.append(card);
    });

    infoText.hide();
    grid.css('display', 'grid');
  }

  $('.enchant-ui').each(function () {
    var ui = $(this);
    var box = ui.find('.enchant-cost-box');
    var display = ui.find('.enchant-fish-points-display');

    ui.find('.enchant-open-picker').on('click', function () {
      ui.addClass('rod-picker-open');
    });

    ui.find('.rod-card-normal').on('click', function () {
      ui.removeClass('rod-picker-open rod-advanced rod-momentum rod-pistol')
        .addClass('rod-normal');
      updateEnchantDisplay(ui);
    });

    ui.find('.rod-card-advanced').on('click', function () {
      ui.removeClass('rod-picker-open rod-normal rod-momentum rod-pistol')
        .addClass('rod-advanced');
      updateEnchantDisplay(ui);
    });

    ui.find('.rod-card-momentum').on('click', function () {
      ui.removeClass('rod-picker-open rod-normal rod-advanced rod-pistol')
        .addClass('rod-momentum');
      updateEnchantDisplay(ui);
    });

    ui.find('.rod-card-pistol').on('click', function () {
      ui.removeClass('rod-picker-open rod-normal rod-advanced rod-momentum')
        .addClass('rod-pistol');
      updateEnchantDisplay(ui);
    });

    box.on('click', function () {
      if (box.find('input').length) {
        return;
      }

      var currentText = display.text().trim();

      if (
        currentText === 'Fish Points' ||
        currentText.indexOf('Input a real number') !== -1
      ) {
        currentText = '';
      } else {
        currentText = currentText.replace(/ fish points?/i, '').trim();
      }

      var input = $('<input>')
        .addClass('enchant-points-input')
        .attr('type', 'text')
        .attr('placeholder', 'Example: 1, 2k, 3m, 1e6')
        .val(currentText);

      display.hide();
      box.removeClass('fish-points-error');
      box.append(input);
      input.focus();

      function saveValue() {
        var raw = input.val().trim();
        var parsed = parseFishNumber(raw);

        if (parsed === null) {
          box.removeAttr('data-fish-points');
          box.addClass('fish-points-error');
          display.text('Input a real number in this format: 1, 2k, 3m, 1e6');

          input.remove();
          display.show();

          updateEnchantDisplay(ui);
          return;
        }

        box.attr('data-fish-points', parsed);
        box.removeClass('fish-points-error');
        display.text(raw + ' Fish Points');

        input.remove();
        display.show();

        updateEnchantDisplay(ui);
      }

      input.on('keydown', function (event) {
        if (event.key === 'Enter') {
          saveValue();
        }

        if (event.key === 'Escape') {
          input.remove();
          display.show();
        }
      });

      input.on('blur', saveValue);
    });

    updateEnchantDisplay(ui);
  });
});
(function () {
  function resetEntryUI(ui) {
    ui.querySelectorAll('.entry-choice-box').forEach(function (el) {
      el.style.display = 'none';
    });

    ui.querySelectorAll('.entry-library').forEach(function (el) {
      el.style.display = 'none';
    });

    ui.querySelectorAll('.entry-subcontent').forEach(function (el) {
      el.style.display = 'none';
    });

    ui.querySelectorAll('.entry-detail-panel').forEach(function (el) {
      el.style.display = 'none';
    });

    ui.querySelectorAll('.entry-side-pill').forEach(function (el) {
      el.classList.remove('entry-active');
    });

    ui.querySelectorAll('.entry-subtab').forEach(function (el) {
      el.classList.remove('entry-active');
    });
  }

  function showItems(ui, tab) {
    resetEntryUI(ui);

    var library = ui.querySelector('.entry-library-items');
    var side = ui.querySelector('.side-items');

    if (library) {
      library.style.display = 'flex';
    }

    if (side) {
      side.classList.add('entry-active');
    }

    if (tab === 'bait') {
      var bait = ui.querySelector('.entry-subcontent-bait');
      var baitTab = ui.querySelector('.entry-subtab-bait');

      if (bait) {
        bait.style.display = 'block';
      }

      if (baitTab) {
        baitTab.classList.add('entry-active');
      }
    } else {
      var fish = ui.querySelector('.entry-subcontent-fish');
      var fishTab = ui.querySelector('.entry-subtab-fish');

      if (fish) {
        fish.style.display = 'block';
      }

      if (fishTab) {
        fishTab.classList.add('entry-active');
      }
    }
  }

  function showTools(ui) {
    resetEntryUI(ui);

    var library = ui.querySelector('.entry-library-tools');
    var side = ui.querySelector('.side-tools');

    if (library) {
      library.style.display = 'flex';
    }

    if (side) {
      side.classList.add('entry-active');
    }
  }

  function showEnchants(ui) {
    resetEntryUI(ui);

    var library = ui.querySelector('.entry-library-enchants');
    var side = ui.querySelector('.side-enchants');

    if (library) {
      library.style.display = 'flex';
    }

    if (side) {
      side.classList.add('entry-active');
    }
  }

  function showDetail(ui, id) {
    var key = id.replace('detail-', '');
    var detail = ui.querySelector('.entry-detail-' + key);

    if (!detail) {
      return;
    }

    resetEntryUI(ui);

    var library = detail.closest('.entry-library');

    if (library) {
      library.style.display = 'flex';
    }

    detail.style.display = 'block';

    if (library && library.classList.contains('entry-library-items')) {
      var items = ui.querySelector('.side-items');
      if (items) {
        items.classList.add('entry-active');
      }
    }

    if (library && library.classList.contains('entry-library-tools')) {
      var tools = ui.querySelector('.side-tools');
      if (tools) {
        tools.classList.add('entry-active');
      }
    }

    if (library && library.classList.contains('entry-library-enchants')) {
      var enchants = ui.querySelector('.side-enchants');
      if (enchants) {
        enchants.classList.add('entry-active');
      }
    }
  }

  function openEntryTarget(ui, id) {
    if (id === 'entry-items') {
      showItems(ui, 'fish');
      return;
    }

    if (id === 'items-fish') {
      showItems(ui, 'fish');
      return;
    }

    if (id === 'items-bait') {
      showItems(ui, 'bait');
      return;
    }

    if (id === 'entry-tools') {
      showTools(ui);
      return;
    }

    if (id === 'entry-enchants') {
      showEnchants(ui);
      return;
    }

    if (id.indexOf('detail-') === 0) {
      showDetail(ui, id);
    }
  }

  document.addEventListener('click', function (event) {
    var button = event.target.closest('.js-entry-open');

    if (!button) {
      return;
    }

    var ui = button.closest('.entry-ui');

    if (!ui) {
      return;
    }

    var target = button.getAttribute('data-entry-target');

    if (!target) {
      return;
    }

    event.preventDefault();
    event.stopPropagation();

    openEntryTarget(ui, target);
  });
})();

