$(function () {
  function parseFishNumber(text) {
    var input = String(text).trim().toLowerCase().replace(/,/g, '');

    var match = input.match(/^([0-9]*\.?[0-9]+(?:e[+-]?[0-9]+)?)(k|m|b|t|qd|qn|sx|sp|oc|no|dc)?$/i);

    if (!match) {
      return null;
    }

    var number = Number(match[1]);
    var suffix = match[2] || '';

    var multipliers = {
      k: 1e3,
      m: 1e6,
      b: 1e9,
      t: 1e12,
      qd: 1e15,
      qn: 1e18,
      sx: 1e21,
      sp: 1e24,
      oc: 1e27,
      no: 1e30,
      dc: 1e33
    };

    if (!isFinite(number)) {
      return null;
    }

    if (suffix) {
      number *= multipliers[suffix];
    }

    if (number < 1) {
      return null;
    }

    return number;
  }
  function formatFishNumber(number) {
	number = Number(number);
	if (!isFinite(number)) {
    return String(number);
  }
  if (Math.abs(number) < 1e6) {
    return Math.floor(number).toLocaleString();
  }
  return number.toExponential(2).replace('+', '').replace(/\.00e/, 'e');
}
  function calculateEnchantLevelRange(fishpointinput, rodLevelMult) {
	var baseLevel = Math.pow(Math.pow(fishpointinput, 0.5) * rodLevelMult, 0.45);

	var minLevel = Math.max(1, Math.floor(baseLevel - 3));
	var maxLevel = Math.max(1, Math.floor(baseLevel + 3));

	return {
    	min: minLevel,
    	max: maxLevel
	};
}

