      ) {
        output.text('Select a rod first.');
        return;
      }

      if (ui.hasClass('rod-pistol')) {
        output.text('Pistol can roll Less Backfire or Sharpshooter. Both are 50% chance.');
        return;
      }

      output.text('Normal rods can roll Strength, Strength+, Momentum, Momentum+, Fortune, or Ultra. Each is 16.67% chance.');
    });

    ui.find('.enchant-menu-set-notation').on('click', function (event) {
      event.preventDefault();
