// Formula Graph
(() => {
  'use strict';

  const DEFAULT_MAX_LEVEL = 10;
  const TOOLTIP_ID = 'cost-formula-tooltip';
  const STYLE_ID = 'cost-formula-tooltip-style';
  const CHART_JS = 'https://cdn.jsdelivr.net/npm/chart.js@4.4.3/dist/chart.umd.min.js';
  let activeFormulaElement = null;
  let activeMousePosition = { x: 0, y: 0 };

  const FUNCTIONS = {
    abs: Math.abs,
    ceil: Math.ceil,
    cos: Math.cos,
    exp: Math.exp,
    floor: Math.floor,
    ln: Math.log,
    log: Math.log,
    log10: (x) => Math.log10 ? Math.log10(x) : Math.log(x) / Math.LN10,
    max: (...args) => Math.max(...args),
    min: (...args) => Math.min(...args),
    pow: Math.pow,
    round: Math.round,
    sin: Math.sin,
    sqrt: Math.sqrt,
    tan: Math.tan,
  };

  function injectStyles() {
    if (document.getElementById(STYLE_ID)) return;

    const style = document.createElement('style');
    style.id = STYLE_ID;
    style.textContent = `
      #${TOOLTIP_ID} {
        position: fixed;
        z-index: 99999;
        display: none;
        width: 520px;
        max-width: calc(100vw - 24px);
        padding: 12px;
        border: 1px solid rgba(255,255,255,.12);
        border-radius: 16px;
		background: var(--cf-bg);
		color: var(--cf-text);
        box-shadow: 0 12px 30px rgba(0,0,0,.35);
        pointer-events: none;
        font: 12px/1.35 system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
        backdrop-filter: blur(10px);
        -webkit-backdrop-filter: blur(10px);
      }

      #${TOOLTIP_ID} .cf-title {
        font-weight: 700;
        margin-bottom: 8px;
        word-break: break-word;
      }

      #${TOOLTIP_ID} .cf-chart-box {
        position: relative;
        width: 100%;
        height: 280px;
        margin-bottom: 10px;
      }

      #${TOOLTIP_ID} canvas {
        width: 100% !important;
        height: 100% !important;
        display: block;
      }

      #${TOOLTIP_ID} .cf-values {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 4px 10px;
        max-height: 180px;
        overflow: hidden;
      }

      #${TOOLTIP_ID} .cf-row {
        display: flex;
        justify-content: space-between;
        gap: 8px;
        font-variant-numeric: tabular-nums;
      }

     #${TOOLTIP_ID} .cf-lv {
	  color: var(--cf-muted);
	}

      #${TOOLTIP_ID} .cf-val {
        font-weight: 600;
      }

      #${TOOLTIP_ID} .cf-meta {
        display: flex;
        justify-content: space-between;
        gap: 8px;
        margin-bottom: 8px;
        opacity: .78;
      }

      #${TOOLTIP_ID} .cf-note {
        margin-top: 8px;
        font-size: 11px;
        opacity: .65;
      }

      #cost-formula-tooltip {
	  --cf-bg: rgba(20,20,24,.96);
	  --cf-text: white;
	  --cf-muted: rgba(255,255,255,.72);
	}

	html.skin-citizen-light #cost-formula-tooltip {
	  --cf-bg: rgba(255,255,255,.96);
	  --cf-text: black;
	  --cf-muted: rgba(0,0,0,.65);
	}

	html.skin-citizen-dark #cost-formula-tooltip {
	  --cf-bg: rgba(20,20,24,.96);
	  --cf-text: white;
	  --cf-muted: rgba(255,255,255,.72);
	}
    `;
    document.head.appendChild(style);
  }

  function ensureTooltip() {
    let el = document.getElementById(TOOLTIP_ID);
    if (el) return el;

    el = document.createElement('div');
    el.id = TOOLTIP_ID;
    document.body.appendChild(el);
    return el;
  }

  function normalizeFormula(text) {
    return String(text || '')
      .replace(/\u00A0/g, ' ')
      .replace(/[€$£¥₽₹]/g, '')
      .trim();
  }

  function isFormulaLike(text) {
    return /[+\-*/^(),]|\b(?:lvl|level|pi|e|sqrt|log10?|ln|abs|floor|ceil|round|min|max|pow|sin|cos|tan)\b/i.test(text);
  }

  function tokenize(input) {
    const tokens = [];
    let i = 0;

    const isDigit = (c) => c >= '0' && c <= '9';
    const isAlpha = (c) => (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c === '_';

    while (i < input.length) {
      const c = input[i];

      if (/\s/.test(c)) {
        i += 1;
        continue;
      }

      if ('()+-*/%^,'.includes(c)) {
        tokens.push({ type: c, value: c });
        i += 1;
        continue;
      }

      if (isDigit(c) || (c === '.' && isDigit(input[i + 1]))) {
        let j = i + 1;
        while (j < input.length && /[0-9.]/.test(input[j])) j += 1;
        if (input[j] === 'e' || input[j] === 'E') {
          let k = j + 1;
          if (input[k] === '+' || input[k] === '-') k += 1;
          while (k < input.length && isDigit(input[k])) k += 1;
          j = k;
        }
        tokens.push({ type: 'number', value: input.slice(i, j) });
        i = j;
        continue;
      }

      if (isAlpha(c)) {
        let j = i + 1;
        while (j < input.length && /[A-Za-z0-9_]/.test(input[j])) j += 1;
        tokens.push({ type: 'ident', value: input.slice(i, j).toLowerCase() });
        i = j;
        continue;
      }

      i += 1;
    }

    return tokens;
  }

  const PRECEDENCE = { 'u+': 5, 'u-': 5, '^': 4, '*': 3, '/': 3, '%': 3, '+': 2, '-': 2 };
  const RIGHT_ASSOC = new Set(['^', 'u+', 'u-']);

  function toRpn(tokens) {
    const output = [];
    const stack = [];
    const argCountStack = [];
    let prev = null;

    for (let i = 0; i < tokens.length; i += 1) {
      const t = tokens[i];

      if (t.type === 'number') {
        output.push({ type: 'number', value: parseFloat(t.value) });
        prev = t;
        continue;
      }

      if (t.type === 'ident') {
        const next = tokens[i + 1];
        if (next && next.type === '(') {
          stack.push({ type: 'func', value: t.value });
          argCountStack.push(1);
        } else {
          output.push({ type: 'var', value: t.value });
        }
        prev = t;
        continue;
      }

      if (t.type === ',') {
        while (stack.length && stack[stack.length - 1].type !== '(') output.push(stack.pop());
        if (!argCountStack.length) throw new Error('Unexpected comma');
        argCountStack[argCountStack.length - 1] += 1;
        prev = t;
        continue;
      }

      if (t.type === '(') {
        stack.push({ type: '(' });
        prev = t;
        continue;
      }

      if (t.type === ')') {
        while (stack.length && stack[stack.length - 1].type !== '(') output.push(stack.pop());
        if (!stack.length) throw new Error('Mismatched parentheses');
        stack.pop();

        if (stack.length && stack[stack.length - 1].type === 'func') {
          const fn = stack.pop();
          fn.argCount = argCountStack.pop() || 1;
          output.push(fn);
        }

        prev = t;
        continue;
      }

      if ('+-*/%^'.includes(t.type)) {
        let op = t.type;
        const unary = !prev || prev.type === '(' || prev.type === ',' || '+-*/%^'.includes(prev.type);
        if (unary && (op === '+' || op === '-')) op = op === '+' ? 'u+' : 'u-';

        while (stack.length) {
          const top = stack[stack.length - 1];
          if (top.type !== 'op') break;

          const p1 = PRECEDENCE[op];
          const p2 = PRECEDENCE[top.value];

          if ((RIGHT_ASSOC.has(op) && p1 < p2) || (!RIGHT_ASSOC.has(op) && p1 <= p2)) {
            output.push(stack.pop());
          } else {
            break;
          }
        }

        stack.push({ type: 'op', value: op });
        prev = t;
      }
    }

    while (stack.length) {
      const x = stack.pop();
      if (x.type === '(') throw new Error('Mismatched parentheses');
      output.push(x);
    }

    return output;
  }

  function evaluateRpn(rpn, vars) {
    const stack = [];

    for (const t of rpn) {
      if (t.type === 'number') {
        stack.push(t.value);
        continue;
      }

      if (t.type === 'var') {
        if (t.value === 'pi') stack.push(Math.PI);
        else if (t.value === 'e') stack.push(Math.E);
        else if (Object.prototype.hasOwnProperty.call(vars, t.value)) stack.push(vars[t.value]);
        else throw new Error(`Unknown variable: ${t.value}`);
        continue;
      }

      if (t.type === 'op') {
        if (t.value === 'u+') {
          stack.push(+stack.pop());
          continue;
        }

        if (t.value === 'u-') {
          stack.push(-stack.pop());
          continue;
        }

        const b = stack.pop();
        const a = stack.pop();

        if (t.value === '+') stack.push(a + b);
        else if (t.value === '-') stack.push(a - b);
        else if (t.value === '*') stack.push(a * b);
        else if (t.value === '/') stack.push(a / b);
        else if (t.value === '%') stack.push(a % b);
        else if (t.value === '^') stack.push(Math.pow(a, b));
        else throw new Error(`Unknown operator: ${t.value}`);
        continue;
      }

      if (t.type === 'func') {
        const args = [];
        for (let i = 0; i < (t.argCount || 1); i += 1) args.unshift(stack.pop());
        const fn = FUNCTIONS[t.value];
        if (!fn) throw new Error(`Unknown function: ${t.value}`);
        stack.push(fn(...args));
      }
    }

    if (stack.length !== 1) throw new Error('Invalid expression');
    return stack[0];
  }

  const RPN_CACHE = new Map();

  function compile(expr) {
    const normalized = normalizeFormula(expr);
    if (RPN_CACHE.has(normalized)) return RPN_CACHE.get(normalized);
    const rpn = toRpn(tokenize(normalized));
    RPN_CACHE.set(normalized, rpn);
    return rpn;
  }

  function evaluate(expr, lvl) {
    return evaluateRpn(compile(expr), { lvl, level: lvl });
  }

  function formatValue(n) {
    if (!Number.isFinite(n)) return String(n);
    const abs = Math.abs(n);
    if (abs >= 1e15 || (abs > 0 && abs < 1e-6)) {
      return n.toExponential(4).replace(/\.0+e/, 'e').replace(/\.?0+e/, 'e');
    }
    return new Intl.NumberFormat(undefined, { maximumFractionDigits: 6 }).format(n);
  }

  function compactNumber(n) {
    if (!Number.isFinite(n)) return String(n);
    const abs = Math.abs(n);
    const units = [
      { v: 1e15, s: 'Q' },
      { v: 1e12, s: 'T' },
      { v: 1e9, s: 'B' },
      { v: 1e6, s: 'M' },
      { v: 1e3, s: 'K' },
    ];
    for (const u of units) {
      if (abs >= u.v) return (n / u.v).toFixed(2).replace(/\.?0+$/, '') + u.s;
    }
    return formatValue(n);
  }

  function loadChartJs() {
    if (window.Chart) return Promise.resolve();
    if (window.__costFormulaChartJsPromise) return window.__costFormulaChartJsPromise;

    window.__costFormulaChartJsPromise = new Promise((resolve, reject) => {
      const existing = document.querySelector(`script[src="${CHART_JS}"]`);
      if (existing) {
        existing.addEventListener('load', resolve, { once: true });
        existing.addEventListener('error', reject, { once: true });
        return;
      }

      const s = document.createElement('script');
      s.src = CHART_JS;
      s.async = true;
      s.onload = () => resolve();
      s.onerror = () => reject(new Error('Failed to load Chart.js'));
      document.head.appendChild(s);
    });

    return window.__costFormulaChartJsPromise;
  }

	function pointsFor(expr, maxLevel) {
	  const points = [];

	  for (let lvl = 1; lvl <= maxLevel; lvl += 1) {
	    points.push({ lvl, value: evaluate(expr, lvl) });
	  }

	  return points;
	}

  function buildContent(expr, points, currency) {
    const rows = points.map((p) => `
      <div class="cf-row">
        <span class="cf-lv">Level ${p.lvl}</span>
        <span class="cf-val">${formatValue(p.value)}${currency}</span>
      </div>
    `).join('');

    const values = points.map((p) => p.value).filter(Number.isFinite);
    const ratioText = values.length >= 2 && values[0] !== 0
      ? `x${formatValue(values[values.length - 1] / values[0])} from Level 1 to Level ${values.length}`
      : `Level 1 to Level ${points.length}`;

    return `
      <div class="cf-title">${expr}</div>
      <div class="cf-chart-box"><canvas></canvas></div>
      <div class="cf-meta"><span>${ratioText}</span><span>${values.length !== points.length ? 'Invalid value' : ''}</span></div>
      <div class="cf-values">${rows}</div>
    `;
  }

  function positionTooltip(tooltip, x, y) {
    const offsetX = 18;
    const offsetY = 18;
    const margin = 12;

    tooltip.style.left = '0px';
    tooltip.style.top = '0px';
    tooltip.style.display = 'block';
    tooltip.style.visibility = 'hidden';

    const rect = tooltip.getBoundingClientRect();
    let left = x + offsetX;
    let top = y + offsetY;

    if (left + rect.width > window.innerWidth - margin) left = x - rect.width - offsetX;
    if (top + rect.height > window.innerHeight - margin) top = y - rect.height - offsetY;

    tooltip.style.left = `${Math.max(margin, left)}px`;
    tooltip.style.top = `${Math.max(margin, top)}px`;
    tooltip.style.visibility = 'visible';
  }

  function getThemeColors() {
	  const dark = document.documentElement.classList.contains('skin-citizen-dark');

	  return {
	    text: dark ? 'rgba(255,255,255,.85)' : 'rgba(0,0,0,.85)',
	    mutedText: dark ? 'rgba(255,255,255,.72)' : 'rgba(0,0,0,.65)',
	    grid: dark ? 'rgba(255,255,255,.08)' : 'rgba(0,0,0,.12)',
	    label: dark ? 'rgba(255,255,255,.95)' : 'rgba(0,0,0,.9)',
	    background: dark ? 'rgba(20,20,24,.96)' : 'rgba(255,255,255,.96)'
	  };
	}

  function makeChart(canvas, expr, points, currency) {
  	const colors = getThemeColors();
    const labels = points.map((p) => String(p.lvl));
    const data = points.map((p) => p.value);
    const ctx = canvas.getContext('2d');

    if (canvas._cfChart) {
      canvas._cfChart.destroy();
      canvas._cfChart = null;
    }

	const pointLabelPlugin = {
	  id: 'cfPointLabels',
	  afterDatasetsDraw(chart) {
	    const { ctx, chartArea } = chart;
	    const meta = chart.getDatasetMeta(0);

	    ctx.save();
	    ctx.fillStyle = colors.label;
	    ctx.font = 'bold 10px system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif';

	    const pad = 6;
	    const safeMargin = 4;
	    const lineHeight = 10;

	    meta.data.forEach((pt, i) => {
	      const value = data[i];
	      const label = `${compactNumber(value)}${currency}`;
	      const textWidth = ctx.measureText(label).width;

	      let x = pt.x - pad;
	      let y = pt.y - pad;
	      let align = 'right';
	      let baseline = 'bottom';

	      const fitsAbove = pt.y - lineHeight - pad >= chartArea.top + safeMargin;
	      const fitsLeft = pt.x - textWidth - pad >= chartArea.left + safeMargin;
	      const fitsRight = pt.x + textWidth + pad <= chartArea.right - safeMargin;

	      if (!fitsAbove) {
	        y = pt.y + pad + lineHeight;
	        baseline = 'top';
	      }

	      if (!fitsLeft && fitsRight) {
	        x = pt.x + pad;
	        align = 'left';
	      } else if (!fitsLeft && !fitsRight) {
	        x = Math.max(chartArea.left + safeMargin, Math.min(pt.x, chartArea.right - textWidth - safeMargin));
	        align = 'center';
	      }

	      ctx.textAlign = align;
	      ctx.textBaseline = baseline;
	      ctx.fillText(label, x, y);
	    });

	    ctx.restore();
	  },
	};

    canvas._cfChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: expr,
          data,
          borderWidth: 2.5,
          pointRadius: 4,
          pointHoverRadius: 5,
          tension: 0.25,
          fill: false,
        }],
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: { duration: 220 },
        plugins: {
          legend: { display: false },
          tooltip: {
            callbacks: {
              title(items) {
                return `Level ${items[0].label}`;
              },
              label(item) {
                return `Cost: ${formatValue(item.raw)}${currency}`;
              },
            },
          },
        },
        layout: {
          padding: { top: 16, right: 10, bottom: 32, left: 8 },
        },
        scales: {
          x: {
            title: { display: true, text: 'Level', color: colors.text, font: { weight: '700' } },
            ticks: { color: colors.mutedText },
            grid: { color: colors.grid },
          },
		y: {
		  title: {
		    display: true,
		    text: 'Cost',
		    color: colors.text,
		    font: { weight: '700' }
		  },
		  ticks: {
		    color: colors.mutedText,
              callback(value) {
                return compactNumber(value) + currency;
              },
            },
            grid: { color: colors.grid },
          },
        },
      },
      plugins: [pointLabelPlugin],
    });
  }

  function bindElement(el, tooltip) {
    if (el.dataset.costFormulaBound === '1') return;
    el.dataset.costFormulaBound = '1';

    let visible = false;
    let hideTimer = null;
    let lastMouse = { x: 0, y: 0 };
    let rafPending = false;

    function getMaxLevel() {
	  const cap = Number(el.dataset.cap || el.getAttribute('data-cap'));

	  if (Number.isFinite(cap) && cap > 0) {
	    return Math.floor(cap);
	  }

	  return DEFAULT_MAX_LEVEL;
	}

    function getExpr() {
      return normalizeFormula(el.dataset.formula || el.getAttribute('data-formula') || el.textContent || '');
    }

    function getCurrency() {
      return el.dataset.currency || el.getAttribute('data-currency') || '€';
    }

    async function show() {
      const expr = getExpr();
      if (!expr || !isFormulaLike(expr)) return;

      try {
        await loadChartJs();
        const points = pointsFor(expr, getMaxLevel());

        tooltip.innerHTML = buildContent(expr, points, getCurrency());

        const canvas = tooltip.querySelector('canvas');
        makeChart(canvas, expr, points, getCurrency());

        tooltip.style.display = 'block';
        visible = true;

        positionTooltip(tooltip, lastMouse.x, lastMouse.y);
      } catch (e) {
        tooltip.style.display = 'none';
        visible = false;
      }
    }

    function hide() {
      tooltip.style.display = 'none';
      visible = false;

      const canvas = tooltip.querySelector('canvas');
      if (canvas && canvas._cfChart) {
        canvas._cfChart.destroy();
        canvas._cfChart = null;
      }
    }

	el.addEventListener('mouseenter', (e) => {
	  activeFormulaElement = el;

	  clearTimeout(hideTimer);
	  lastMouse.x = e.clientX;
	  lastMouse.y = e.clientY;
	  show();
	});

	el.addEventListener('mousemove', (e) => {
	  lastMouse.x = e.clientX;
	  lastMouse.y = e.clientY;

	  activeMousePosition.x = e.clientX;
	  activeMousePosition.y = e.clientY;
      if (!visible) return;
      if (rafPending) return;

      rafPending = true;
      requestAnimationFrame(() => {
        rafPending = false;
        if (tooltip.style.display !== 'none') {
          positionTooltip(tooltip, lastMouse.x, lastMouse.y);
        }
      });
    });

    el.addEventListener('mouseleave', () => {
      clearTimeout(hideTimer);
      hideTimer = setTimeout(hide, 20);
    });
  }

  function init() {
  	if (!window.__costFormulaThemeObserver) {
		window.__costFormulaThemeObserver = new MutationObserver(() => {
		  if (activeFormulaElement) {
			activeFormulaElement.dispatchEvent(new MouseEvent('mouseenter', {
			  clientX: activeMousePosition.x,
			  clientY: activeMousePosition.y
			}));
		  }
		});

	  window.__costFormulaThemeObserver.observe(document.documentElement, {
	    attributes: true,
	    attributeFilter: ['class']
	  });
	}

    injectStyles();
    const tooltip = ensureTooltip();

    document.querySelectorAll('.cost-formula').forEach((el) => bindElement(el, tooltip));

    if (!window.__costFormulaObserver && window.MutationObserver) {
      window.__costFormulaObserver = new MutationObserver(() => {
        document.querySelectorAll('.cost-formula').forEach((el) => bindElement(el, tooltip));
      });

      window.__costFormulaObserver.observe(document.body, { childList: true, subtree: true });
    }
  }

  if (window.mw && mw.hook) {
    mw.hook('wikipage.content').add(init);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
// Formula Graph Ends

