// Fish Island Stuff
$(function () {
  function parseFishNumber(text) {
    var input = String(text).trim().toLowerCase().replace(/,/g, '');

    var multipliers = {
      k: 1e3,
      m: 1e6,
      b: 1e9,
      t: 1e12,
      qd: 1e15,
      qn: 1e18,
      sx: 1e21,
      sp: 1e24,
      oc: 1e27,
      no: 1e30,
      dc: 1e33
    };

    var number;

    var suffixMatch = input.match(/^([0-9]*\.?[0-9]+)(k|m|b|t|qd|qn|sx|sp|oc|no|dc)$/i);

    if (suffixMatch) {
      number = Number(suffixMatch[1]) * multipliers[suffixMatch[2]];
    } else {
      var scientificMatch = input.match(/^([0-9]*\.?[0-9]+(?:e[+-]?[0-9]+)?)$/i);

      if (!scientificMatch) {
        return null;
      }

      number = Number(scientificMatch[1]);
    }

    if (!isFinite(number) || number < 1) {
      return null;
    }

    return number;
  }

  function calculateEnchantLevelRange(fishpointinput, rodLevelMult) {
    var baseLevel = Math.pow(Math.pow(fishpointinput, 0.5) * rodLevelMult, 0.45);

    var minLevel = Math.max(1, Math.round(baseLevel - 3));
    var maxLevel = Math.max(1, Math.round(baseLevel + 3));

    return {
      min: minLevel,
      max: maxLevel
    };
  }

  var currentNotation = localStorage.getItem('fishIslandNotation') || 'suffix';

if (currentNotation !== 'suffix' && currentNotation !== 'scientific') {
  currentNotation = 'suffix';
}

function formatFishNumber(number) {
  number = Number(number);

  if (!isFinite(number)) {
    return 'Too big';
  }

  if (currentNotation === 'scientific') {
    return number.toExponential(2).replace('+', '').replace(/\.00e/, 'e');
  }

  return formatFishSuffix(number);
}

  function formatFishSuffix(number) {
    var abs = Math.abs(number);

    if (abs < 1000) {
      return Math.floor(number).toLocaleString();
    }

    var suffixes = [
      { value: 1e33, symbol: 'dc' },
      { value: 1e30, symbol: 'no' },
      { value: 1e27, symbol: 'oc' },
      { value: 1e24, symbol: 'sp' },
      { value: 1e21, symbol: 'sx' },
      { value: 1e18, symbol: 'qn' },
      { value: 1e15, symbol: 'qd' },
      { value: 1e12, symbol: 't' },
      { value: 1e9, symbol: 'b' },
      { value: 1e6, symbol: 'm' },
      { value: 1e3, symbol: 'k' }
    ];

    for (var i = 0; i < suffixes.length; i++) {
      if (abs >= suffixes[i].value) {
        var shortNumber = number / suffixes[i].value;
        var text;

        if (Math.abs(shortNumber) >= 100) {
          text = shortNumber.toFixed(0);
        } else if (Math.abs(shortNumber) >= 10) {
          text = shortNumber.toFixed(1);
        } else {
          text = shortNumber.toFixed(2);
        }

        text = text.replace(/\.0+$/, '').replace(/(\.\d*[1-9])0+$/, '$1');

        return text + suffixes[i].symbol;
      }
    }

    return number.toExponential(2).replace('+', '').replace(/\.00e/, 'e');
  }

  function updateEnchantDisplay(ui) {
    var fishPoints = Number(ui.find('.enchant-cost-box').attr('data-fish-points'));
    var infoText = ui.find('.enchant-info-text');
    var grid = ui.find('.enchant-result-grid');

    var hasRod =
      ui.hasClass('rod-normal') ||
      ui.hasClass('rod-advanced') ||
      ui.hasClass('rod-momentum') ||
      ui.hasClass('rod-pistol');

    if (!hasRod && (!fishPoints || fishPoints < 1)) {
      grid.hide().empty();
      infoText.show().text('Select a rod and input Fish Points');
      return;
    }

    if (!hasRod) {
      grid.hide().empty();
      infoText.show().text('Select a rod first');
      return;
    }

    if (!fishPoints || fishPoints < 1) {
      grid.hide().empty();
      infoText.show().text('Input Fish Points');
      return;
    }

    var enchants;

    if (ui.hasClass('rod-pistol')) {
      enchants = [
        { name: 'Less Backfire', file: 'less_backfire.png', levelMult: 0.7, colorClass: 'enchant-bg-less-backfire' },
        { name: 'Sharpshooter', file: 'Sharpshooter.png', levelMult: 0.5, colorClass: 'enchant-bg-sharpshooter' }
      ];
    } else {
      enchants = [
        { name: 'Strength', file: 'strength.png', levelMult: 0.8, colorClass: 'enchant-bg-strength' },
        { name: 'Strength+', file: 'Strength+.png', levelMult: 0.5, colorClass: 'enchant-bg-strength-plus' },
        { name: 'Momentum', file: 'Momentum.png', levelMult: 0.7, colorClass: 'enchant-bg-momentum' },
        { name: 'Momentum+', file: 'Momentum+.png', levelMult: 0.4, colorClass: 'enchant-bg-momentum-plus' },
        { name: 'Fortune', file: 'Fortune.png', levelMult: 0.6, colorClass: 'enchant-bg-fortune' },
        { name: 'Ultra', file: 'Ultra.png', levelMult: 0.3, colorClass: 'enchant-bg-ultra' }
      ];
    }

    grid.empty();

    enchants.forEach(function (enchant) {
      var levelRange = calculateEnchantLevelRange(fishPoints, enchant.levelMult);
      var imgUrl = mw.util.getUrl('Special:Redirect/file/' + enchant.file);

      var card = $('<div>')
        .addClass('enchant-result-card')
        .addClass(enchant.colorClass);

      $('<img>')
        .attr('src', imgUrl)
        .attr('alt', enchant.name)
        .appendTo(card);

      $('<div>')
        .addClass('enchant-result-name')
        .text(enchant.name)
        .appendTo(card);

      $('<div>')
        .addClass('enchant-result-level')
        .text('Level ' + formatFishNumber(levelRange.min) + ' - ' + formatFishNumber(levelRange.max))
        .appendTo(card);

      grid.append(card);
    });

    infoText.hide();
    grid.css('display', 'grid');
  }

  $('.enchant-ui').each(function () {
    var ui = $(this);
    var box = ui.find('.enchant-cost-box');
    var display = ui.find('.enchant-fish-points-display');

    var suffixChoice = ui.find('.enchant-notation-choice[data-notation="suffix"]');
    var scientificChoice = ui.find('.enchant-notation-choice[data-notation="scientific"]');

    if (suffixChoice.length && scientificChoice.length) {
      suffixChoice.insertBefore(scientificChoice);
    }

    function setNotation(notation) {
  if (notation !== 'suffix' && notation !== 'scientific') {
    notation = 'suffix';
  }

  currentNotation = notation;
  localStorage.setItem('fishIslandNotation', notation);
  ui.attr('data-notation', notation);

  ui.find('.enchant-notation-choice').removeClass('notation-active');
  ui.find('.enchant-notation-choice[data-notation="' + notation + '"]').addClass('notation-active');

  var fishPoints = box.attr('data-fish-points');

  if (fishPoints && !isNaN(Number(fishPoints)) && Number(fishPoints) >= 1) {
    display.text(formatFishNumber(fishPoints) + ' Fish Points');
  }

  updateEnchantDisplay(ui);
}

    var savedNotation = localStorage.getItem('fishIslandNotation') || 'suffix';
    setNotation(savedNotation);

    ui.on('click', '.enchant-menu-button', function (event) {
      event.preventDefault();
      event.stopPropagation();

      ui.removeClass('rod-picker-open');
      ui.toggleClass('enchant-menu-open');
    });

    ui.on('click', '.enchant-menu-close', function (event) {
      event.preventDefault();
      event.stopPropagation();

      ui.removeClass('enchant-menu-open');
    });

    ui.on('click', '.enchant-open-picker', function (event) {
      event.preventDefault();
      event.stopPropagation();

      ui.removeClass('enchant-menu-open');
      ui.addClass('rod-picker-open');
    });

    ui.find('.enchant-menu-fish-advisor').on('click', function (event) {
      event.preventDefault();
      event.stopPropagation();

      var panel = ui.find('.enchant-menu-panel');
      var output = ui.find('.enchant-advisor-output');
      var fishPoints = Number(box.attr('data-fish-points'));

      panel.removeClass('show-notation').addClass('show-fish');

      if (!fishPoints || fishPoints < 1) {
        output.text('Input Fish Points first.');
        return;
      }

      if (
        !ui.hasClass('rod-normal') &&
        !ui.hasClass('rod-advanced') &&
        !ui.hasClass('rod-momentum') &&
        !ui.hasClass('rod-pistol')
      ) {
        output.text('Select a rod first.');
        return;
      }

      if (ui.hasClass('rod-pistol')) {
        output.text('Pistol can roll Less Backfire or Sharpshooter. Both are 50% chance.');
        return;
      }

      output.text('Normal rods can roll Strength, Strength+, Momentum, Momentum+, Fortune, or Ultra. Each is 16.67% chance.');
    });

    ui.find('.enchant-menu-set-notation').on('click', function (event) {
      event.preventDefault();
      event.stopPropagation();

      ui.find('.enchant-menu-panel')
        .removeClass('show-fish')
        .addClass('show-notation');
    });

    ui.find('.enchant-menu-back').on('click', function (event) {
      event.preventDefault();
      event.stopPropagation();

      ui.find('.enchant-menu-panel').removeClass('show-fish show-notation');
    });

    ui.find('.enchant-notation-choice').on('click', function (event) {
      event.preventDefault();
      event.stopPropagation();

      setNotation($(this).attr('data-notation'));
    });

    ui.find('.rod-card-normal').on('click', function () {
      ui.removeClass('rod-picker-open rod-advanced rod-momentum rod-pistol')
        .addClass('rod-normal');

      updateEnchantDisplay(ui);
    });

    ui.find('.rod-card-advanced').on('click', function () {
      ui.removeClass('rod-picker-open rod-normal rod-momentum rod-pistol')
        .addClass('rod-advanced');

      updateEnchantDisplay(ui);
    });

    ui.find('.rod-card-momentum').on('click', function () {
      ui.removeClass('rod-picker-open rod-normal rod-advanced rod-pistol')
        .addClass('rod-momentum');

      updateEnchantDisplay(ui);
    });

    ui.find('.rod-card-pistol').on('click', function () {
      ui.removeClass('rod-picker-open rod-normal rod-advanced rod-momentum')
        .addClass('rod-pistol');

      updateEnchantDisplay(ui);
    });

    box.on('click', function () {
      if (box.find('input').length) {
        return;
      }

      var currentText = display.text().trim();

      if (
        currentText === 'Fish Points' ||
        currentText.indexOf('Input a real number') !== -1
      ) {
        currentText = '';
      } else {
        currentText = currentText.replace(/ fish points?/i, '').trim();
      }

      var input = $('<input>')
        .addClass('enchant-points-input')
        .attr('type', 'text')
        .attr('placeholder', 'Example: 1, 2k, 3m, 1e6')
        .val(currentText);

      display.hide();
      box.removeClass('fish-points-error');
      box.append(input);
      input.focus();

      var didSave = false;

      function saveValue() {
        if (didSave) {
          return;
        }

        didSave = true;

        var raw = input.val().trim();
        var parsed = parseFishNumber(raw);

        if (parsed === null) {
          box.removeAttr('data-fish-points');
          box.addClass('fish-points-error');
          display.text('Input a real number in this format: 1, 2k, 3m, 1e6');

          input.remove();
          display.show();

          updateEnchantDisplay(ui);
          return;
        }

        box.attr('data-fish-points', parsed);
        box.removeClass('fish-points-error');
        display.text(formatFishNumber(parsed) + ' Fish Points');

        input.remove();
        display.show();

        updateEnchantDisplay(ui);
      }

      input.on('keydown', function (event) {
        if (event.key === 'Enter') {
          saveValue();
        }

        if (event.key === 'Escape') {
          didSave = true;
          input.remove();
          display.show();
        }
      });

      input.on('blur', saveValue);
    });

    updateEnchantDisplay(ui);
  });
});

/* ===== entries ===== */
(function () {
  function resetEntryUI(ui) {
    ui.querySelectorAll('.entry-choice-box').forEach(function (el) {
      el.style.display = 'none';
    });

    ui.querySelectorAll('.entry-library').forEach(function (el) {
      el.style.display = 'none';
    });

    ui.querySelectorAll('.entry-subcontent').forEach(function (el) {
      el.style.display = 'none';
    });

    ui.querySelectorAll('.entry-detail-panel').forEach(function (el) {
      el.style.display = 'none';
    });

    ui.querySelectorAll('.entry-side-pill').forEach(function (el) {
      el.classList.remove('entry-active');
    });

    ui.querySelectorAll('.entry-subtab').forEach(function (el) {
      el.classList.remove('entry-active');
    });
  }

  function showItems(ui, tab) {
    resetEntryUI(ui);

    var library = ui.querySelector('.entry-library-items');
    var side = ui.querySelector('.side-items');

    if (library) {
      library.style.display = 'flex';
    }

    if (side) {
      side.classList.add('entry-active');
    }

    if (tab === 'bait') {
      var bait = ui.querySelector('.entry-subcontent-bait');
      var baitTab = ui.querySelector('.entry-subtab-bait');

      if (bait) {
        bait.style.display = 'block';
      }

      if (baitTab) {
        baitTab.classList.add('entry-active');
      }
    } else {
      var fish = ui.querySelector('.entry-subcontent-fish');
      var fishTab = ui.querySelector('.entry-subtab-fish');

      if (fish) {
        fish.style.display = 'block';
      }

      if (fishTab) {
        fishTab.classList.add('entry-active');
      }
    }
  }

  function showTools(ui) {
    resetEntryUI(ui);

    var library = ui.querySelector('.entry-library-tools');
    var side = ui.querySelector('.side-tools');

    if (library) {
      library.style.display = 'flex';
    }

    if (side) {
      side.classList.add('entry-active');
    }
  }

  function showEnchants(ui) {
    resetEntryUI(ui);

    var library = ui.querySelector('.entry-library-enchants');
    var side = ui.querySelector('.side-enchants');

    if (library) {
      library.style.display = 'flex';
    }

    if (side) {
      side.classList.add('entry-active');
    }
  }

  function showDetail(ui, id) {
    var key = id.replace('detail-', '');
    var detail = ui.querySelector('.entry-detail-' + key);

    if (!detail) {
      return;
    }

    resetEntryUI(ui);

    var library = detail.closest('.entry-library');

    if (library) {
      library.style.display = 'flex';
    }

    detail.style.display = 'block';

    if (library && library.classList.contains('entry-library-items')) {
      var items = ui.querySelector('.side-items');

      if (items) {
        items.classList.add('entry-active');
      }
    }

    if (library && library.classList.contains('entry-library-tools')) {
      var tools = ui.querySelector('.side-tools');

      if (tools) {
        tools.classList.add('entry-active');
      }
    }

    if (library && library.classList.contains('entry-library-enchants')) {
      var enchants = ui.querySelector('.side-enchants');

      if (enchants) {
        enchants.classList.add('entry-active');
      }
    }
  }

  function openEntryTarget(ui, id) {
    if (id === 'entry-items') {
      showItems(ui, 'fish');
      return;
    }

    if (id === 'items-fish') {
      showItems(ui, 'fish');
      return;
    }

    if (id === 'items-bait') {
      showItems(ui, 'bait');
      return;
    }

    if (id === 'entry-tools') {
      showTools(ui);
      return;
    }

    if (id === 'entry-enchants') {
      showEnchants(ui);
      return;
    }

    if (id.indexOf('detail-') === 0) {
      showDetail(ui, id);
    }
  }

  document.addEventListener('click', function (event) {
    var button = event.target.closest('.js-entry-open');

    if (!button) {
      return;
    }

    var ui = button.closest('.entry-ui');

    if (!ui) {
      return;
    }

    var target = button.getAttribute('data-entry-target');

    if (!target) {
      return;
    }

    event.preventDefault();
    event.stopPropagation();

    openEntryTarget(ui, target);
  });
})();

