/* ===== Fish Island ===== */
window.FishNumber = (function () {
  var suffixes = [
    '',
    'k', 'm', 'b', 't', 'qd', 'qn', 'sx', 'sp', 'oc', 'no',

    'de', 'ude', 'dde', 'tde', 'qdde', 'qnde', 'sxde', 'spde', 'ocde', 'node',

    'vt', 'uvt', 'dvt', 'tvt', 'qdvt', 'qnvt', 'sxvt', 'spvt', 'ocvt', 'novt',

    'tg', 'utg', 'dtg', 'ttg', 'qdtg', 'qntg', 'sxtg', 'sptg', 'octg', 'notg',

    'qg', 'uqg', 'dqg', 'tqg', 'qdqg', 'qnqg', 'sxqg', 'spqg', 'ocqg', 'noqg',

    'qag', 'uqag', 'dqag', 'tqag', 'qdqag', 'qnqag', 'sxqag', 'spqag', 'ocqag', 'noqag',

    'sg', 'usg', 'dsg', 'tsg', 'qdsg', 'qnsg', 'sxsg', 'spsg', 'ocsg', 'nosg',

    'spg', 'uspg', 'dspg', 'tspg', 'qdspg', 'qnspg', 'sxspg', 'spspg', 'ocspg', 'nospg',

    'og', 'uog', 'dog', 'tog', 'qdog', 'qnog', 'sxog', 'spog', 'ocog', 'noog',

    'ng', 'ung', 'dng', 'tng', 'qdng', 'qnng', 'sxng', 'spng', 'ocng', 'nong',

    'ce'
  ];

  var multipliers = {};

  suffixes.forEach(function (suffix, index) {
    multipliers[suffix.toLowerCase()] = Math.pow(1000, index);
  });

  function parse(text) {
    var input = String(text || '').trim().toLowerCase().replace(/,/g, '');

    if (input === '') {
      return null;
    }

    var suffixMatch = input.match(/^([0-9]*\.?[0-9]+)([a-z]+)$/i);

    if (suffixMatch) {
      var baseNumber = Number(suffixMatch[1]);
      var suffix = suffixMatch[2].toLowerCase();

      if (!multipliers.hasOwnProperty(suffix)) {
        return null;
      }

      var suffixNumber = baseNumber * multipliers[suffix];

      if (!isFinite(suffixNumber) || suffixNumber < 1) {
        return null;
      }

      return suffixNumber;
    }

    var scientificMatch = input.match(/^([0-9]*\.?[0-9]+(?:e[+-]?[0-9]+)?)$/i);

    if (!scientificMatch) {
      return null;
    }

    var number = Number(scientificMatch[1]);

    if (!isFinite(number) || number < 1) {
      return null;
    }

    return number;
  }

  function formatSuffix(number) {
    number = Number(number);

    if (!isFinite(number)) {
      return 'Too big';
    }

    var abs = Math.abs(number);

    if (abs < 1000) {
      return Math.floor(number).toLocaleString();
    }

    for (var i = suffixes.length - 1; i >= 1; i--) {
      var suffix = suffixes[i];
      var value = multipliers[suffix];

      if (abs >= value) {
        var shortNumber = number / value;
        var text;

        if (Math.abs(shortNumber) >= 100) {
          text = shortNumber.toFixed(0);
        } else if (Math.abs(shortNumber) >= 10) {
          text = shortNumber.toFixed(1);
        } else {
          text = shortNumber.toFixed(2);
        }

        text = text.replace(/\.0+$/, '').replace(/(\.\d*[1-9])0+$/, '$1');

        return text + suffix;
      }
    }

    return number.toString();
  }

  function formatScientific(number) {
    number = Number(number);

    if (!isFinite(number)) {
      return 'Too big';
    }

    return number.toExponential(2).replace('+', '').replace(/\.00e/, 'e');
  }

  function format(number, notation) {
    if (notation === 'scientific') {
      return formatScientific(number);
    }

    return formatSuffix(number);
  }

  return {
    parse: parse,
    format: format,
    formatSuffix: formatSuffix,
    formatScientific: formatScientific
  };
})();

/* ===== enchanting ===== */
$(function () {
  localStorage.removeItem('fishIslandFishPoints');

  $(document).off('click.fishEnchantMenuButton').on('click.fishEnchantMenuButton', '.enchant-menu-button', function (event) {
    event.preventDefault();
    event.stopPropagation();

    var ui = $(this).closest('.enchant-ui');

    if (!ui.length) {
      ui = $('.enchant-ui').first();
    }

    ui.removeClass('rod-picker-open');
    ui.toggleClass('enchant-menu-open');
  });

  $(document).off('click.fishEnchantMenuClose').on('click.fishEnchantMenuClose', '.enchant-menu-close', function (event) {
    event.preventDefault();
    event.stopPropagation();

    var ui = $(this).closest('.enchant-ui');

    if (!ui.length) {
      ui = $('.enchant-ui').first();
    }

    ui.removeClass('enchant-menu-open');
  });

  function parseFishNumber(text) {
    return window.FishNumber.parse(text);
  }

  function calculateEnchantLevelRange(fishpointinput, rodLevelMult) {
    var baseLevel = Math.pow(Math.pow(fishpointinput, 0.5) * rodLevelMult, 0.45);

    var minLevel = Math.max(1, Math.round(baseLevel - 3));
    var maxLevel = Math.max(1, Math.round(baseLevel + 3));

    return {
      min: minLevel,
      max: maxLevel
    };
  }

  function getNotation(ui) {
    var activeNotation = ui.find('.enchant-notation-choice.notation-active').attr('data-notation');

    if (activeNotation === 'suffix' || activeNotation === 'scientific') {
      return activeNotation;
    }

    var savedNotation = localStorage.getItem('fishIslandNotation');

    if (savedNotation === 'suffix' || savedNotation === 'scientific') {
      return savedNotation;
    }

    return 'suffix';
  }

  function formatFishNumberWithNotation(number, notation) {
    return window.FishNumber.format(number, notation);
  }

  function formatFishNumber(number, ui) {
    return formatFishNumberWithNotation(number, getNotation(ui));
  }

  function getEnchantListForRodName(rodName) {
    if (rodName === 'pistol') {
      return [
        { name: 'Less Backfire', file: 'less_backfire.png', levelMult: 0.7, colorClass: 'enchant-bg-less-backfire' },
        { name: 'Sharpshooter', file: 'Sharpshooter.png', levelMult: 0.5, colorClass: 'enchant-bg-sharpshooter' }
      ];
    }

    return [
      { name: 'Strength', file: 'strength.png', levelMult: 0.8, colorClass: 'enchant-bg-strength' },
      { name: 'Strength+', file: 'Strength+.png', levelMult: 0.5, colorClass: 'enchant-bg-strength-plus' },
      { name: 'Momentum', file: 'Momentum.png', levelMult: 0.7, colorClass: 'enchant-bg-momentum' },
      { name: 'Momentum+', file: 'Momentum+.png', levelMult: 0.4, colorClass: 'enchant-bg-momentum-plus' },
      { name: 'Fortune', file: 'Fortune.png', levelMult: 0.6, colorClass: 'enchant-bg-fortune' },
      { name: 'Ultra', file: 'Ultra.png', levelMult: 0.3, colorClass: 'enchant-bg-ultra' }
    ];
  }

  function getEnchantListForUi(ui) {
    if (ui.hasClass('rod-pistol')) {
      return getEnchantListForRodName('pistol');
    }

    return getEnchantListForRodName('normal');
  }

  function getMainRodName(ui) {
    if (ui.hasClass('rod-pistol')) {
      return 'pistol';
    }

    if (ui.hasClass('rod-advanced')) {
      return 'advanced';
    }

    if (ui.hasClass('rod-momentum')) {
      return 'momentum';
    }

    if (ui.hasClass('rod-normal')) {
      return 'normal';
    }

    return 'normal';
  }

  function getRodDisplayName(rodName) {
    if (rodName === 'advanced') {
      return 'Advanced Rod';
    }

    if (rodName === 'momentum') {
      return 'Momentum Rod';
    }

    if (rodName === 'pistol') {
      return 'Pistol';
    }

    return 'Fishing Rod';
  }

  function minimumFishToGuaranteeLevel(targetLevel, levelMult) {
    var low = 1;
    var high = 1;

    while (calculateEnchantLevelRange(high, levelMult).min < targetLevel) {
      high *= 2;

      if (high > 1e300) {
        return null;
      }
    }

    while (low < high) {
      var mid = Math.floor((low + high) / 2);

      if (calculateEnchantLevelRange(mid, levelMult).min >= targetLevel) {
        high = mid;
      } else {
        low = mid + 1;
      }
    }

    return low;
  }

  function getLevelChanceAtSpend(fishPoints, levelMult, targetLevel) {
    var baseLevel = Math.pow(Math.pow(fishPoints, 0.5) * levelMult, 0.45);

    var success = 0;
    var total = 7;

    for (var offset = -3; offset <= 3; offset++) {
      var rolledLevel = Math.max(1, Math.round(baseLevel + offset));

      if (rolledLevel >= targetLevel) {
        success++;
      }
    }

    return {
      success: success,
      total: total,
      chance: success / total
    };
  }

  function getCombination(n, k) {
    if (k < 0 || k > n) {
      return 0;
    }

    if (k === 0 || k === n) {
      return 1;
    }

    k = Math.min(k, n - k);

    var result = 1;

    for (var i = 1; i <= k; i++) {
      result = result * (n - k + i) / i;
    }

    return result;
  }

  function getComboEstimateNoDupes(allEnchantCount, selectedEnchants, fishPoints, targetLevel) {
    var selectedCount = selectedEnchants.length;
    var maxSlots = Math.min(4, allEnchantCount);

    if (selectedCount < 1) {
      return null;
    }

    if (selectedCount > maxSlots) {
      return null;
    }

    var totalPossibleCombos = getCombination(allEnchantCount, maxSlots);
    var successfulCombos = getCombination(allEnchantCount - selectedCount, maxSlots - selectedCount);
    var comboChance = successfulCombos / totalPossibleCombos;

    var levelChanceProduct = 1;
    var chances = [];

    selectedEnchants.forEach(function (enchant) {
      var chanceInfo = getLevelChanceAtSpend(fishPoints, enchant.levelMult, targetLevel);

      levelChanceProduct *= chanceInfo.chance;

      chances.push({
        enchant: enchant,
        levelChance: chanceInfo.chance,
        levelSuccess: chanceInfo.success,
        levelTotal: chanceInfo.total
      });
    });

    var successChancePerRoll = comboChance * levelChanceProduct;

    return {
      selectedCount: selectedCount,
      maxSlots: maxSlots,
      totalPossibleCombos: totalPossibleCombos,
      successfulCombos: successfulCombos,
      comboChance: comboChance,
      levelChanceProduct: levelChanceProduct,
      successChancePerRoll: successChancePerRoll,
      expectedRolls: 1 / successChancePerRoll,
      chances: chances
    };
  }

  function hasSelectedItem(ui) {
    return (
      ui.hasClass('rod-normal') ||
      ui.hasClass('rod-advanced') ||
      ui.hasClass('rod-momentum') ||
      ui.hasClass('rod-pistol')
    );
  }

  function setAdvisorRod(ui, rodName) {
    if (
      rodName !== 'normal' &&
      rodName !== 'advanced' &&
      rodName !== 'momentum' &&
      rodName !== 'pistol'
    ) {
      rodName = 'normal';
    }

    ui.attr('data-advisor-rod', rodName);

    ui.find('.enchant-advisor-rod').removeClass('advisor-rod-active');
    ui.find('.enchant-advisor-rod[data-advisor-rod="' + rodName + '"]').addClass('advisor-rod-active');

    renderAdvisorComboList(ui);
  }

  function getAdvisorRod(ui) {
    var rodName = ui.attr('data-advisor-rod');

    if (
      rodName === 'normal' ||
      rodName === 'advanced' ||
      rodName === 'momentum' ||
      rodName === 'pistol'
    ) {
      return rodName;
    }

    return getMainRodName(ui);
  }

  function renderAdvisorComboList(ui) {
    var rodName = getAdvisorRod(ui);
    var enchants = getEnchantListForRodName(rodName);
    var comboList = ui.find('.enchant-advisor-combo-list');

    comboList.empty();

    enchants.forEach(function (enchant) {
      $('<div>')
        .addClass('enchant-advisor-combo-button')
        .attr('data-enchant-name', enchant.name)
        .text(enchant.name)
        .appendTo(comboList);
    });

    ui.find('.enchant-advisor-output').text('Select enchant option(s), then input target level.');
  }

  function getSelectedAdvisorEnchants(ui) {
    var rodName = getAdvisorRod(ui);
    var enchants = getEnchantListForRodName(rodName);
    var selectedNames = [];

    ui.find('.enchant-advisor-combo-button.combo-active').each(function () {
      selectedNames.push($(this).attr('data-enchant-name'));
    });

    return enchants.filter(function (enchant) {
      return selectedNames.indexOf(enchant.name) !== -1;
    });
  }

  function updateEnchantDisplay(ui) {
    var fishPoints = Number(ui.find('.enchant-cost-box').attr('data-fish-points'));
    var infoText = ui.find('.enchant-info-text');
    var grid = ui.find('.enchant-result-grid');

    var hasRod = hasSelectedItem(ui);

    if (!hasRod && (!fishPoints || fishPoints < 1)) {
      grid.hide().empty();
      infoText.show().text('Select a rod and input Fish Points');
      return;
    }

    if (!hasRod) {
      grid.hide().empty();
      infoText.show().text('Select a rod first');
      return;
    }

    if (!fishPoints || fishPoints < 1) {
      grid.hide().empty();
      infoText.show().text('Input Fish Points');
      return;
    }

    var enchants = getEnchantListForUi(ui);

    grid.empty();

    enchants.forEach(function (enchant) {
      var levelRange = calculateEnchantLevelRange(fishPoints, enchant.levelMult);
      var imgUrl = mw.util.getUrl('Special:Redirect/file/' + enchant.file);

      var card = $('<div>')
        .addClass('enchant-result-card')
        .addClass(enchant.colorClass);

      $('<img>')
        .attr('src', imgUrl)
        .attr('alt', enchant.name)
        .appendTo(card);

      $('<div>')
        .addClass('enchant-result-name')
        .text(enchant.name)
        .appendTo(card);

      $('<div>')
        .addClass('enchant-result-level')
        .text('Level ' + formatFishNumber(levelRange.min, ui) + ' - ' + formatFishNumber(levelRange.max, ui))
        .appendTo(card);

      grid.append(card);
    });

    infoText.hide();
    grid.css('display', 'grid');
  }

  function runFishAdvisor(ui) {
    var output = ui.find('.enchant-advisor-output');
    var rawLevel = ui.find('.enchant-advisor-level-box').attr('data-target-level');
    var targetLevelNumber = parseFishNumber(rawLevel);
    var rodName = getAdvisorRod(ui);
    var allEnchants = getEnchantListForRodName(rodName);
    var selectedEnchants = getSelectedAdvisorEnchants(ui);

    output.empty();

    if (selectedEnchants.length === 0) {
      output.text('Select at least one enchant option.');
      return;
    }

    if (selectedEnchants.length > 4) {
      output.text('You can only select up to 4 enchants.');
      return;
    }

    if (targetLevelNumber === null) {
      output.text('Input a target level first.\nExample: 10, 50, 100');
      return;
    }

    var targetLevel = Math.max(1, Math.floor(targetLevelNumber));

    var highestSingleCost = 1;

    selectedEnchants.forEach(function (enchant) {
      var needed = minimumFishToGuaranteeLevel(targetLevel, enchant.levelMult);

      if (needed !== null && needed > highestSingleCost) {
        highestSingleCost = needed;
      }
    });

    var estimate = getComboEstimateNoDupes(
      allEnchants.length,
      selectedEnchants,
      highestSingleCost,
      targetLevel
    );

    if (estimate === null) {
      output.text('Invalid combo. Maximum is 4 enchants.');
      return;
    }

    var estimatedComboCost = highestSingleCost * estimate.expectedRolls;

    $('<div>')
      .addClass('advisor-result-title')
      .text(getRodDisplayName(rodName) + ' - Estimated combo cost')
      .appendTo(output);

    var summary = $('<div>')
      .addClass('advisor-result-row advisor-best')
      .appendTo(output);

    var summaryInfo = $('<div>')
      .addClass('advisor-result-info')
      .appendTo(summary);

    $('<div>')
      .addClass('advisor-result-name')
      .text('Estimated total Fish Points')
      .appendTo(summaryInfo);

    $('<div>')
      .addClass('advisor-result-level')
      .text(formatFishNumber(estimatedComboCost, ui) + ' Fish Points')
      .appendTo(summaryInfo);

    $('<div>')
      .addClass('advisor-result-min')
      .text(
        'About ' +
        estimate.expectedRolls.toFixed(2) +
        ' rolls at ' +
        formatFishNumber(highestSingleCost, ui) +
        ' Fish Points each.'
      )
      .appendTo(summaryInfo);

    $('<div>')
      .addClass('advisor-result-min')
      .text(
        'Combo chance per roll: ' +
        estimate.successfulCombos +
        '/' +
        estimate.totalPossibleCombos +
        ' = ' +
        (estimate.comboChance * 100).toFixed(2) +
        '%'
      )
      .appendTo(summaryInfo);

    $('<div>')
      .addClass('advisor-result-min')
      .text(
        'Chance including Level ' +
        formatFishNumber(targetLevel, ui) +
        '+: ' +
        (estimate.successChancePerRoll * 100).toFixed(2) +
        '%'
      )
      .appendTo(summaryInfo);

    $('<div>')
      .addClass('advisor-result-min')
      .text('Selected enchant breakdown:')
      .appendTo(summaryInfo);

    selectedEnchants.forEach(function (enchant) {
      var needed = minimumFishToGuaranteeLevel(targetLevel, enchant.levelMult);
      var chanceInfo = getLevelChanceAtSpend(highestSingleCost, enchant.levelMult, targetLevel);

      $('<div>')
        .addClass('advisor-result-min')
        .text(
          enchant.name +
          ': ' +
          formatFishNumber(needed, ui) +
          ' Fish Points minimum, level chance ' +
          chanceInfo.success +
          '/' +
          chanceInfo.total +
          ' = ' +
          (chanceInfo.chance * 100).toFixed(2) +
          '%'
        )
        .appendTo(summaryInfo);
    });

    selectedEnchants.forEach(function (enchant) {
      var range = calculateEnchantLevelRange(highestSingleCost, enchant.levelMult);
      var needed = minimumFishToGuaranteeLevel(targetLevel, enchant.levelMult);
      var chanceInfo = getLevelChanceAtSpend(highestSingleCost, enchant.levelMult, targetLevel);
      var imgUrl = mw.util.getUrl('Special:Redirect/file/' + enchant.file);

      var row = $('<div>')
        .addClass('advisor-result-row')
        .addClass(enchant.colorClass);

      $('<img>')
        .attr('src', imgUrl)
        .attr('alt', enchant.name)
        .appendTo(row);

      var info = $('<div>')
        .addClass('advisor-result-info')
        .appendTo(row);

      $('<div>')
        .addClass('advisor-result-name')
        .text(enchant.name)
        .appendTo(info);

      $('<div>')
        .addClass('advisor-result-level')
        .text('At combo spend: Level ' + formatFishNumber(range.min, ui) + ' - ' + formatFishNumber(range.max, ui))
        .appendTo(info);

      $('<div>')
        .addClass('advisor-result-min')
        .text('Own minimum cost: ' + formatFishNumber(needed, ui) + ' Fish Points')
        .appendTo(info);

      $('<div>')
        .addClass('advisor-result-min')
        .text('Level chance: ' + chanceInfo.success + '/' + chanceInfo.total + ' = ' + (chanceInfo.chance * 100).toFixed(2) + '%')
        .appendTo(info);

      output.append(row);
    });
  }

  $(document)
    .off('click.fishAdvisorComboButton')
    .on('click.fishAdvisorComboButton', '.enchant-advisor-combo-button', function (event) {
      event.preventDefault();
      event.stopPropagation();

      var button = $(this);
      var ui = button.closest('.enchant-ui');

      if (!ui.length) {
        return;
      }

      if (!button.hasClass('combo-active')) {
        var activeCount = ui.find('.enchant-advisor-combo-button.combo-active').length;

        if (activeCount >= 4) {
          ui.find('.enchant-advisor-output').text('You can only select up to 4 enchants.');
          return;
        }
      }

      button.toggleClass('combo-active');

      if (ui.find('.enchant-advisor-level-box').attr('data-target-level')) {
        runFishAdvisor(ui);
      }
    });

  $('.enchant-ui').each(function () {
    var ui = $(this);
    var box = ui.find('.enchant-cost-box');
    var display = ui.find('.enchant-fish-points-display');

    var suffixChoice = ui.find('.enchant-notation-choice[data-notation="suffix"]');
    var scientificChoice = ui.find('.enchant-notation-choice[data-notation="scientific"]');

    if (suffixChoice.length && scientificChoice.length) {
      suffixChoice.insertBefore(scientificChoice);
    }

    function setNotation(notation) {
      if (notation !== 'suffix' && notation !== 'scientific') {
        notation = 'suffix';
      }

      localStorage.setItem('fishIslandNotation', notation);
      ui.attr('data-notation', notation);

      ui.find('.enchant-notation-choice').removeClass('notation-active');
      ui.find('.enchant-notation-choice[data-notation="' + notation + '"]').addClass('notation-active');

      var fishPoints = box.attr('data-fish-points');

      if (fishPoints && !isNaN(Number(fishPoints)) && Number(fishPoints) >= 1) {
        display.text(formatFishNumberWithNotation(fishPoints, notation) + ' Fish Points');
      }

      updateEnchantDisplay(ui);

      if (ui.find('.enchant-advisor-level-box').attr('data-target-level')) {
        runFishAdvisor(ui);
      }
    }

    var savedNotation = localStorage.getItem('fishIslandNotation') || 'suffix';
    setNotation(savedNotation);
    setAdvisorRod(ui, getMainRodName(ui));

    ui.on('click', '.enchant-open-picker', function (event) {
      event.preventDefault();
      event.stopPropagation();

      ui.removeClass('enchant-menu-open');
      ui.addClass('rod-picker-open');
    });

    ui.find('.enchant-menu-fish-advisor').on('click', function (event) {
      event.preventDefault();
      event.stopPropagation();

      ui.find('.enchant-menu-panel')
        .removeClass('show-notation')
        .addClass('show-fish');

      setAdvisorRod(ui, getAdvisorRod(ui));
    });

    ui.find('.enchant-advisor-rod').on('click', function (event) {
      event.preventDefault();
      event.stopPropagation();

      setAdvisorRod(ui, $(this).attr('data-advisor-rod'));
    });

    ui.find('.enchant-advisor-level-box').on('click', function () {
      var levelBox = $(this);

      if (levelBox.find('input').length) {
        return;
      }

      var displaySpan = levelBox.find('.enchant-advisor-level-display');
      var displayText = displaySpan.text().trim();

      if (displayText === 'Click to input target level') {
        displayText = '';
      } else {
        displayText = displayText.replace(/^Level\s+/i, '').trim();
      }

      var input = $('<input>')
        .addClass('enchant-advisor-level-input')
        .attr('type', 'text')
        .attr('placeholder', 'Example: 10, 50, 100')
        .val(displayText);

      displaySpan.hide();
      levelBox.append(input);
      input.focus();

      function saveTargetLevel() {
        var raw = input.val().trim();

        if (raw === '') {
          levelBox.removeAttr('data-target-level');
          displaySpan.text('Click to input target level');
        } else {
          levelBox.attr('data-target-level', raw);
          displaySpan.text('Level ' + raw);
        }

        input.remove();
        displaySpan.show();
      }

      input.on('keydown', function (event) {
        if (event.key === 'Enter') {
          event.preventDefault();
          saveTargetLevel();
          runFishAdvisor(ui);
        }

        if (event.key === 'Escape') {
          input.remove();
          displaySpan.show();
        }
      });

      input.on('blur', saveTargetLevel);
    });

    ui.find('.enchant-advisor-check').on('click', function (event) {
      event.preventDefault();
      event.stopPropagation();

      var activeInput = ui.find('.enchant-advisor-level-box input');

      if (activeInput.length) {
        activeInput.blur();
      }

      runFishAdvisor(ui);
    });

    ui.find('.enchant-menu-set-notation').on('click', function (event) {
      event.preventDefault();
      event.stopPropagation();

      ui.find('.enchant-menu-panel')
        .removeClass('show-fish')
        .addClass('show-notation');
    });

    ui.find('.enchant-menu-back').on('click', function (event) {
      event.preventDefault();
      event.stopPropagation();

      ui.find('.enchant-menu-panel').removeClass('show-fish show-notation');
    });

    ui.find('.enchant-notation-choice').on('click', function (event) {
      event.preventDefault();
      event.stopPropagation();

      setNotation($(this).attr('data-notation'));
    });

    ui.find('.rod-card-normal').on('click', function () {
      ui.removeClass('rod-picker-open rod-advanced rod-momentum rod-pistol')
        .addClass('rod-normal');

      updateEnchantDisplay(ui);
    });

    ui.find('.rod-card-advanced').on('click', function () {
      ui.removeClass('rod-picker-open rod-normal rod-momentum rod-pistol')
        .addClass('rod-advanced');

      updateEnchantDisplay(ui);
    });

    ui.find('.rod-card-momentum').on('click', function () {
      ui.removeClass('rod-picker-open rod-normal rod-advanced rod-pistol')
        .addClass('rod-momentum');

      updateEnchantDisplay(ui);
    });

    ui.find('.rod-card-pistol').on('click', function () {
      ui.removeClass('rod-picker-open rod-normal rod-advanced rod-momentum')
        .addClass('rod-pistol');

      updateEnchantDisplay(ui);
    });

    box.on('click', function () {
      if (box.find('input').length) {
        return;
      }

      var currentText = display.text().trim();

      if (
        currentText === 'Fish Points' ||
        currentText.indexOf('Input a real number') !== -1
      ) {
        currentText = '';
      } else {
        currentText = currentText.replace(/ fish points?/i, '').trim();
      }

      var input = $('<input>')
        .addClass('enchant-points-input')
        .attr('type', 'text')
        .attr('placeholder', 'Example: 1, 2k, 3m, 1e6')
        .val(currentText);

      display.hide();
      box.removeClass('fish-points-error');
      box.append(input);
      input.focus();

      var didSave = false;

      function saveValue() {
        if (didSave) {
          return;
        }

        didSave = true;

        var raw = input.val().trim();
        var parsed = parseFishNumber(raw);

        if (parsed === null) {
          box.removeAttr('data-fish-points');
          box.addClass('fish-points-error');
          display.text('Input a real number in this format: 1, 2k, 3m, 1e6');

          input.remove();
          display.show();

          updateEnchantDisplay(ui);
          return;
        }

        box.attr('data-fish-points', parsed);
        box.removeClass('fish-points-error');

        var notation = getNotation(ui);
        display.text(formatFishNumberWithNotation(parsed, notation) + ' Fish Points');

        input.remove();
        display.show();

        updateEnchantDisplay(ui);
      }

      input.on('keydown', function (event) {
        if (event.key === 'Enter') {
          saveValue();
        }

        if (event.key === 'Escape') {
          didSave = true;
          input.remove();
          display.show();
        }
      });

      input.on('blur', saveValue);
    });

    updateEnchantDisplay(ui);
  });
});

/* ===== entries ===== */
(function () {
  function resetEntryUI(ui) {
    ui.querySelectorAll('.entry-choice-box').forEach(function (el) {
      el.style.display = 'none';
    });

    ui.querySelectorAll('.entry-library').forEach(function (el) {
      el.style.display = 'none';
    });

    ui.querySelectorAll('.entry-subcontent').forEach(function (el) {
      el.style.display = 'none';
    });

    ui.querySelectorAll('.entry-detail-panel').forEach(function (el) {
      el.style.display = 'none';
    });

    ui.querySelectorAll('.entry-side-pill').forEach(function (el) {
      el.classList.remove('entry-active');
    });

    ui.querySelectorAll('.entry-subtab').forEach(function (el) {
      el.classList.remove('entry-active');
    });
  }

  function showItems(ui, tab) {
    resetEntryUI(ui);

    var library = ui.querySelector('.entry-library-items');
    var side = ui.querySelector('.side-items');

    if (library) {
      library.style.display = 'flex';
    }

    if (side) {
      side.classList.add('entry-active');
    }

    if (tab === 'bait') {
      var bait = ui.querySelector('.entry-subcontent-bait');
      var baitTab = ui.querySelector('.entry-subtab-bait');

      if (bait) {
        bait.style.display = 'block';
      }

      if (baitTab) {
        baitTab.classList.add('entry-active');
      }
    } else {
      var fish = ui.querySelector('.entry-subcontent-fish');
      var fishTab = ui.querySelector('.entry-subtab-fish');

      if (fish) {
        fish.style.display = 'block';
      }

      if (fishTab) {
        fishTab.classList.add('entry-active');
      }
    }
  }

  function showTools(ui) {
    resetEntryUI(ui);

    var library = ui.querySelector('.entry-library-tools');
    var side = ui.querySelector('.side-tools');

    if (library) {
      library.style.display = 'flex';
    }

    if (side) {
      side.classList.add('entry-active');
    }
  }

  function showEnchants(ui) {
    resetEntryUI(ui);

    var library = ui.querySelector('.entry-library-enchants');
    var side = ui.querySelector('.side-enchants');

    if (library) {
      library.style.display = 'flex';
    }

    if (side) {
      side.classList.add('entry-active');
    }
  }

  function showDetail(ui, id) {
    var key = id.replace('detail-', '');
    var detail = ui.querySelector('.entry-detail-' + key);

    if (!detail) {
      return;
    }

    resetEntryUI(ui);

    var library = detail.closest('.entry-library');

    if (library) {
      library.style.display = 'flex';
    }

    detail.style.display = 'block';

    if (library && library.classList.contains('entry-library-items')) {
      var items = ui.querySelector('.side-items');

      if (items) {
        items.classList.add('entry-active');
      }
    }

    if (library && library.classList.contains('entry-library-tools')) {
      var tools = ui.querySelector('.side-tools');

      if (tools) {
        tools.classList.add('entry-active');
      }
    }

    if (library && library.classList.contains('entry-library-enchants')) {
      var enchants = ui.querySelector('.side-enchants');

      if (enchants) {
        enchants.classList.add('entry-active');
      }
    }
  }

  function openEntryTarget(ui, id) {
    if (id === 'entry-items') {
      showItems(ui, 'fish');
      return;
    }

    if (id === 'items-fish') {
      showItems(ui, 'fish');
      return;
    }

    if (id === 'items-bait') {
      showItems(ui, 'bait');
      return;
    }

    if (id === 'entry-tools') {
      showTools(ui);
      return;
    }

    if (id === 'entry-enchants') {
      showEnchants(ui);
      return;
    }

    if (id.indexOf('detail-') === 0) {
      showDetail(ui, id);
    }
  }

  document.addEventListener('click', function (event) {
    var button = event.target.closest('.js-entry-open');

    if (!button) {
      return;
    }

    var ui = button.closest('.entry-ui');

    if (!ui) {
      return;
    }

    var target = button.getAttribute('data-entry-target');

    if (!target) {
      return;
    }

    event.preventDefault();
    event.stopPropagation();

    openEntryTarget(ui, target);
  });
})();

/* ===== masteries ===== */
$(function () {
  $('.mastery-panel').each(function () {
    var panel = $(this);
    var popup = panel.find('.mastery-popup');
    var popupFormula = panel.find('.mastery-popup-formula');

    panel.find('.mastery-show').on('click', function () {
      var row = $(this).closest('.mastery-row');
      var number = row.find('.mastery-num').text().trim();
      var formula = row.find('.mastery-formula').text().trim();

      panel.find('.mastery-popup-title').text('Mastery ' + number + ' Formula');
      popupFormula.text(formula);
      popup.addClass('mastery-popup-open');
    });

    panel.find('.mastery-popup-close').on('click', function () {
      popup.removeClass('mastery-popup-open');
    });

    popup.on('click', function (event) {
      if (event.target === this) {
        popup.removeClass('mastery-popup-open');
      }
    });
  });
});
// Fish Island Ends

// Formula Graph
(() => {
  'use strict';

  const DEFAULT_MAX_LEVEL = 10;
  const TOOLTIP_ID = 'cost-formula-tooltip';
  const STYLE_ID = 'cost-formula-tooltip-style';
  const CHART_JS = 'https://cdn.jsdelivr.net/npm/chart.js@4.4.3/dist/chart.umd.min.js';

  const FUNCTIONS = {
    abs: Math.abs,
    ceil: Math.ceil,
    cos: Math.cos,
    exp: Math.exp,
    floor: Math.floor,
    ln: Math.log,
    log: Math.log,
    log10: (x) => Math.log10 ? Math.log10(x) : Math.log(x) / Math.LN10,
    max: (...args) => Math.max(...args),
    min: (...args) => Math.min(...args),
    pow: Math.pow,
    round: Math.round,
    sin: Math.sin,
    sqrt: Math.sqrt,
    tan: Math.tan,
  };

  function injectStyles() {
    if (document.getElementById(STYLE_ID)) return;

    const style = document.createElement('style');
    style.id = STYLE_ID;
    style.textContent = `
      #${TOOLTIP_ID} {
        position: fixed;
        z-index: 99999;
        display: none;
        width: 520px;
        max-width: calc(100vw - 24px);
        padding: 12px;
        border: 1px solid rgba(255,255,255,.12);
        border-radius: 16px;
        background: rgba(20, 20, 24, 0.96);
        color: #fff;
        box-shadow: 0 12px 30px rgba(0,0,0,.35);
        pointer-events: none;
        font: 12px/1.35 system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
        backdrop-filter: blur(10px);
        -webkit-backdrop-filter: blur(10px);
      }

      #${TOOLTIP_ID} .cf-title {
        font-weight: 700;
        margin-bottom: 8px;
        word-break: break-word;
      }

      #${TOOLTIP_ID} .cf-chart-box {
        position: relative;
        width: 100%;
        height: 280px;
        margin-bottom: 10px;
      }

      #${TOOLTIP_ID} canvas {
        width: 100% !important;
        height: 100% !important;
        display: block;
      }

      #${TOOLTIP_ID} .cf-values {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 4px 10px;
        max-height: 180px;
        overflow: hidden;
      }

      #${TOOLTIP_ID} .cf-row {
        display: flex;
        justify-content: space-between;
        gap: 8px;
        font-variant-numeric: tabular-nums;
      }

      #${TOOLTIP_ID} .cf-lv {
        color: rgba(255,255,255,.72);
      }

      #${TOOLTIP_ID} .cf-val {
        font-weight: 600;
      }

      #${TOOLTIP_ID} .cf-meta {
        display: flex;
        justify-content: space-between;
        gap: 8px;
        margin-bottom: 8px;
        opacity: .78;
      }

      #${TOOLTIP_ID} .cf-note {
        margin-top: 8px;
        font-size: 11px;
        opacity: .65;
      }
    `;
    document.head.appendChild(style);
  }

  function ensureTooltip() {
    let el = document.getElementById(TOOLTIP_ID);
    if (el) return el;

    el = document.createElement('div');
    el.id = TOOLTIP_ID;
    document.body.appendChild(el);
    return el;
  }

  function normalizeFormula(text) {
    return String(text || '')
      .replace(/\u00A0/g, ' ')
      .replace(/[€$£¥₽₹]/g, '')
      .trim();
  }

  function isFormulaLike(text) {
    return /[+\-*/^(),]|\b(?:lvl|level|pi|e|sqrt|log10?|ln|abs|floor|ceil|round|min|max|pow|sin|cos|tan)\b/i.test(text);
  }

  function tokenize(input) {
    const tokens = [];
    let i = 0;

    const isDigit = (c) => c >= '0' && c <= '9';
    const isAlpha = (c) => (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c === '_';

    while (i < input.length) {
      const c = input[i];

      if (/\s/.test(c)) {
        i += 1;
        continue;
      }

      if ('()+-*/%^,'.includes(c)) {
        tokens.push({ type: c, value: c });
        i += 1;
        continue;
      }

      if (isDigit(c) || (c === '.' && isDigit(input[i + 1]))) {
        let j = i + 1;
        while (j < input.length && /[0-9.]/.test(input[j])) j += 1;
        if (input[j] === 'e' || input[j] === 'E') {
          let k = j + 1;
          if (input[k] === '+' || input[k] === '-') k += 1;
          while (k < input.length && isDigit(input[k])) k += 1;
          j = k;
        }
        tokens.push({ type: 'number', value: input.slice(i, j) });
        i = j;
        continue;
      }

      if (isAlpha(c)) {
        let j = i + 1;
        while (j < input.length && /[A-Za-z0-9_]/.test(input[j])) j += 1;
        tokens.push({ type: 'ident', value: input.slice(i, j).toLowerCase() });
        i = j;
        continue;
      }

      i += 1;
    }

    return tokens;
  }

  const PRECEDENCE = { 'u+': 5, 'u-': 5, '^': 4, '*': 3, '/': 3, '%': 3, '+': 2, '-': 2 };
  const RIGHT_ASSOC = new Set(['^', 'u+', 'u-']);

  function toRpn(tokens) {
    const output = [];
    const stack = [];
    const argCountStack = [];
    let prev = null;

    for (let i = 0; i < tokens.length; i += 1) {
      const t = tokens[i];

      if (t.type === 'number') {
        output.push({ type: 'number', value: parseFloat(t.value) });
        prev = t;
        continue;
      }

      if (t.type === 'ident') {
        const next = tokens[i + 1];
        if (next && next.type === '(') {
          stack.push({ type: 'func', value: t.value });
          argCountStack.push(1);
        } else {
          output.push({ type: 'var', value: t.value });
        }
        prev = t;
        continue;
      }

      if (t.type === ',') {
        while (stack.length && stack[stack.length - 1].type !== '(') output.push(stack.pop());
        if (!argCountStack.length) throw new Error('Unexpected comma');
        argCountStack[argCountStack.length - 1] += 1;
        prev = t;
        continue;
      }

      if (t.type === '(') {
        stack.push({ type: '(' });
        prev = t;
        continue;
      }

      if (t.type === ')') {
        while (stack.length && stack[stack.length - 1].type !== '(') output.push(stack.pop());
        if (!stack.length) throw new Error('Mismatched parentheses');
        stack.pop();

        if (stack.length && stack[stack.length - 1].type === 'func') {
          const fn = stack.pop();
          fn.argCount = argCountStack.pop() || 1;
          output.push(fn);
        }

        prev = t;
        continue;
      }

      if ('+-*/%^'.includes(t.type)) {
        let op = t.type;
        const unary = !prev || prev.type === '(' || prev.type === ',' || '+-*/%^'.includes(prev.type);
        if (unary && (op === '+' || op === '-')) op = op === '+' ? 'u+' : 'u-';

        while (stack.length) {
          const top = stack[stack.length - 1];
          if (top.type !== 'op') break;

          const p1 = PRECEDENCE[op];
          const p2 = PRECEDENCE[top.value];

          if ((RIGHT_ASSOC.has(op) && p1 < p2) || (!RIGHT_ASSOC.has(op) && p1 <= p2)) {
            output.push(stack.pop());
          } else {
            break;
          }
        }

        stack.push({ type: 'op', value: op });
        prev = t;
      }
    }

    while (stack.length) {
      const x = stack.pop();
      if (x.type === '(') throw new Error('Mismatched parentheses');
      output.push(x);
    }

    return output;
  }

  function evaluateRpn(rpn, vars) {
    const stack = [];

    for (const t of rpn) {
      if (t.type === 'number') {
        stack.push(t.value);
        continue;
      }

      if (t.type === 'var') {
        if (t.value === 'pi') stack.push(Math.PI);
        else if (t.value === 'e') stack.push(Math.E);
        else if (Object.prototype.hasOwnProperty.call(vars, t.value)) stack.push(vars[t.value]);
        else throw new Error(`Unknown variable: ${t.value}`);
        continue;
      }

      if (t.type === 'op') {
        if (t.value === 'u+') {
          stack.push(+stack.pop());
          continue;
        }

        if (t.value === 'u-') {
          stack.push(-stack.pop());
          continue;
        }

        const b = stack.pop();
        const a = stack.pop();

        if (t.value === '+') stack.push(a + b);
        else if (t.value === '-') stack.push(a - b);
        else if (t.value === '*') stack.push(a * b);
        else if (t.value === '/') stack.push(a / b);
        else if (t.value === '%') stack.push(a % b);
        else if (t.value === '^') stack.push(Math.pow(a, b));
        else throw new Error(`Unknown operator: ${t.value}`);
        continue;
      }

      if (t.type === 'func') {
        const args = [];
        for (let i = 0; i < (t.argCount || 1); i += 1) args.unshift(stack.pop());
        const fn = FUNCTIONS[t.value];
        if (!fn) throw new Error(`Unknown function: ${t.value}`);
        stack.push(fn(...args));
      }
    }

    if (stack.length !== 1) throw new Error('Invalid expression');
    return stack[0];
  }

  const RPN_CACHE = new Map();

  function compile(expr) {
    const normalized = normalizeFormula(expr);
    if (RPN_CACHE.has(normalized)) return RPN_CACHE.get(normalized);
    const rpn = toRpn(tokenize(normalized));
    RPN_CACHE.set(normalized, rpn);
    return rpn;
  }

  function evaluate(expr, lvl) {
    return evaluateRpn(compile(expr), { lvl, level: lvl });
  }

  function formatValue(n) {
    if (!Number.isFinite(n)) return String(n);
    const abs = Math.abs(n);
    if (abs >= 1e15 || (abs > 0 && abs < 1e-6)) {
      return n.toExponential(4).replace(/\.0+e/, 'e').replace(/\.?0+e/, 'e');
    }
    return new Intl.NumberFormat(undefined, { maximumFractionDigits: 6 }).format(n);
  }

  function compactNumber(n) {
    if (!Number.isFinite(n)) return String(n);
    const abs = Math.abs(n);
    const units = [
      { v: 1e15, s: 'Q' },
      { v: 1e12, s: 'T' },
      { v: 1e9, s: 'B' },
      { v: 1e6, s: 'M' },
      { v: 1e3, s: 'K' },
    ];
    for (const u of units) {
      if (abs >= u.v) return (n / u.v).toFixed(2).replace(/\.?0+$/, '') + u.s;
    }
    return formatValue(n);
  }

  function loadChartJs() {
    if (window.Chart) return Promise.resolve();
    if (window.__costFormulaChartJsPromise) return window.__costFormulaChartJsPromise;

    window.__costFormulaChartJsPromise = new Promise((resolve, reject) => {
      const existing = document.querySelector(`script[src="${CHART_JS}"]`);
      if (existing) {
        existing.addEventListener('load', resolve, { once: true });
        existing.addEventListener('error', reject, { once: true });
        return;
      }

      const s = document.createElement('script');
      s.src = CHART_JS;
      s.async = true;
      s.onload = () => resolve();
      s.onerror = () => reject(new Error('Failed to load Chart.js'));
      document.head.appendChild(s);
    });

    return window.__costFormulaChartJsPromise;
  }

	function pointsFor(expr, maxLevel) {
	  const points = [];

	  for (let lvl = 1; lvl <= maxLevel; lvl += 1) {
	    points.push({ lvl, value: evaluate(expr, lvl) });
	  }

	  return points;
	}

  function buildContent(expr, points, currency) {
    const rows = points.map((p) => `
      <div class="cf-row">
        <span class="cf-lv">Level ${p.lvl}</span>
        <span class="cf-val">${formatValue(p.value)}${currency}</span>
      </div>
    `).join('');

    const values = points.map((p) => p.value).filter(Number.isFinite);
    const ratioText = values.length >= 2 && values[0] !== 0
      ? `x${formatValue(values[values.length - 1] / values[0])} from Level 1 to Level ${values.length}`
      : `Level 1 to Level ${points.length}`;

    return `
      <div class="cf-title">${expr}</div>
      <div class="cf-chart-box"><canvas></canvas></div>
      <div class="cf-meta"><span>${ratioText}</span><span>${values.length !== points.length ? 'Invalid value' : ''}</span></div>
      <div class="cf-values">${rows}</div>
    `;
  }

  function positionTooltip(tooltip, x, y) {
    const offsetX = 18;
    const offsetY = 18;
    const margin = 12;

    tooltip.style.left = '0px';
    tooltip.style.top = '0px';
    tooltip.style.display = 'block';
    tooltip.style.visibility = 'hidden';

    const rect = tooltip.getBoundingClientRect();
    let left = x + offsetX;
    let top = y + offsetY;

    if (left + rect.width > window.innerWidth - margin) left = x - rect.width - offsetX;
    if (top + rect.height > window.innerHeight - margin) top = y - rect.height - offsetY;

    tooltip.style.left = `${Math.max(margin, left)}px`;
    tooltip.style.top = `${Math.max(margin, top)}px`;
    tooltip.style.visibility = 'visible';
  }

  function makeChart(canvas, expr, points, currency) {
    const labels = points.map((p) => String(p.lvl));
    const data = points.map((p) => p.value);
    const ctx = canvas.getContext('2d');

    if (canvas._cfChart) {
      canvas._cfChart.destroy();
      canvas._cfChart = null;
    }

	const pointLabelPlugin = {
	  id: 'cfPointLabels',
	  afterDatasetsDraw(chart) {
	    const { ctx, chartArea } = chart;
	    const meta = chart.getDatasetMeta(0);

	    ctx.save();
	    ctx.fillStyle = 'rgba(255,255,255,.95)';
	    ctx.font = 'bold 10px system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif';

	    const pad = 6;
	    const safeMargin = 4;
	    const lineHeight = 10;

	    meta.data.forEach((pt, i) => {
	      const value = data[i];
	      const label = `${compactNumber(value)}${currency}`;
	      const textWidth = ctx.measureText(label).width;

	      let x = pt.x - pad;
	      let y = pt.y - pad;
	      let align = 'right';
	      let baseline = 'bottom';

	      const fitsAbove = pt.y - lineHeight - pad >= chartArea.top + safeMargin;
	      const fitsLeft = pt.x - textWidth - pad >= chartArea.left + safeMargin;
	      const fitsRight = pt.x + textWidth + pad <= chartArea.right - safeMargin;

	      if (!fitsAbove) {
	        y = pt.y + pad + lineHeight;
	        baseline = 'top';
	      }

	      if (!fitsLeft && fitsRight) {
	        x = pt.x + pad;
	        align = 'left';
	      } else if (!fitsLeft && !fitsRight) {
	        x = Math.max(chartArea.left + safeMargin, Math.min(pt.x, chartArea.right - textWidth - safeMargin));
	        align = 'center';
	      }

	      ctx.textAlign = align;
	      ctx.textBaseline = baseline;
	      ctx.fillText(label, x, y);
	    });

	    ctx.restore();
	  },
	};

    canvas._cfChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: expr,
          data,
          borderWidth: 2.5,
          pointRadius: 4,
          pointHoverRadius: 5,
          tension: 0.25,
          fill: false,
        }],
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: { duration: 220 },
        plugins: {
		  legend: {
		    display: false,
		  },
		  tooltip: {
		    enabled: true,
		    backgroundColor: "rgba(20,20,24,0.96)",
		    titleColor: "#ffffff",
		    bodyColor: "#ffffff",
		    borderColor: "rgba(255,255,255,0.15)",
		    borderWidth: 1,
		    displayColors: false,
		    callbacks: {
		      title(items) {
		        return `Level ${items[0].label}`;
		      },
		      label(item) {
		        return `Cost: ${formatValue(item.raw)}${currency}`;
		      },
		    },
		  },
		},
        layout: {
          padding: { top: 16, right: 10, bottom: 32, left: 8 },
        },
        scales: {
		  x: {
		    title: {
		      display: true,
		      text: 'Level',
		      color: 'rgba(255,255,255,.85)',
		      font: { weight: '700' },
		    },
		    ticks: {
		      color: 'rgba(255,255,255,.72)',
		    },
		    grid: {
		      color: 'rgba(255,255,255,.05)',
		    },
		    border: {
		      color: 'rgba(255,255,255,.2)',
		    },
		  },
		  y: {
		    title: {
		      display: true,
		      text: 'Cost',
		      color: 'rgba(255,255,255,.85)',
		      font: { weight: '700' },
		    },
		    ticks: {
		      color: 'rgba(255,255,255,.72)',
		      callback(value) {
		        return compactNumber(value) + currency;
		      },
		    },
		    grid: {
		      color: 'rgba(255,255,255,.08)',
		    },
		    border: {
		      color: 'rgba(255,255,255,.2)',
		    },
		  },
		},
       },
      plugins: [pointLabelPlugin],
    });
  }

  function bindElement(el, tooltip) {
    if (el.dataset.costFormulaBound === '1') return;
    el.dataset.costFormulaBound = '1';

    let visible = false;
    let hideTimer = null;
    let lastMouse = { x: 0, y: 0 };
    let rafPending = false;

    function getMaxLevel() {
	  const cap = Number(el.dataset.cap || el.getAttribute('data-cap'));

	  if (Number.isFinite(cap) && cap > 0) {
	    return Math.floor(cap);
	  }

	  return DEFAULT_MAX_LEVEL;
	}

    function getExpr() {
      return normalizeFormula(el.dataset.formula || el.getAttribute('data-formula') || el.textContent || '');
    }

    function getCurrency() {
      return el.dataset.currency || el.getAttribute('data-currency') || '€';
    }

    async function show() {
      const expr = getExpr();
      if (!expr || !isFormulaLike(expr)) return;

      try {
        await loadChartJs();
        const points = pointsFor(expr, getMaxLevel());

        tooltip.innerHTML = buildContent(expr, points, getCurrency());

        const canvas = tooltip.querySelector('canvas');
        makeChart(canvas, expr, points, getCurrency());

        tooltip.style.display = 'block';
        visible = true;

        positionTooltip(tooltip, lastMouse.x, lastMouse.y);
      } catch (e) {
        tooltip.style.display = 'none';
        visible = false;
      }
    }

    function hide() {
      tooltip.style.display = 'none';
      visible = false;

      const canvas = tooltip.querySelector('canvas');
      if (canvas && canvas._cfChart) {
        canvas._cfChart.destroy();
        canvas._cfChart = null;
      }
    }

    el.addEventListener('mouseenter', (e) => {
      clearTimeout(hideTimer);
      lastMouse.x = e.clientX;
      lastMouse.y = e.clientY;
      show();
    });

    el.addEventListener('mousemove', (e) => {
      lastMouse.x = e.clientX;
      lastMouse.y = e.clientY;
      if (!visible) return;
      if (rafPending) return;

      rafPending = true;
      requestAnimationFrame(() => {
        rafPending = false;
        if (tooltip.style.display !== 'none') {
          positionTooltip(tooltip, lastMouse.x, lastMouse.y);
        }
      });
    });

    el.addEventListener('mouseleave', () => {
      clearTimeout(hideTimer);
      hideTimer = setTimeout(hide, 20);
    });
  }

  function init() {
    injectStyles();
    const tooltip = ensureTooltip();

    document.querySelectorAll('.cost-formula').forEach((el) => bindElement(el, tooltip));

    if (!window.__costFormulaObserver && window.MutationObserver) {
      window.__costFormulaObserver = new MutationObserver(() => {
        document.querySelectorAll('.cost-formula').forEach((el) => bindElement(el, tooltip));
      });

      window.__costFormulaObserver.observe(document.body, { childList: true, subtree: true });
    }
  }

  if (window.mw && mw.hook) {
    mw.hook('wikipage.content').add(init);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
// Formula Graph Ends

