(function () {

    function forceSectionsOpen() {

        document
            .querySelectorAll(
                '#mw-content-text section.collapsible-block'
            )
            .forEach(function (section) {

                if (
                    section.hasAttribute(
                        'hidden'
                    )
                ) {
                    section.removeAttribute(
                        'hidden'
                    );
                }

                if (
                    section.classList.contains(
                        'collapsible-block-js'
                    )
                ) {
                    section.classList.remove(
                        'collapsible-block-js'
                    );
                }

            });

        document
            .querySelectorAll(
                '#mw-content-text .collapsible-heading, ' +
                '#mw-content-text [data-no-section-collapse="true"]'
            )
            .forEach(function (heading) {

                heading.setAttribute(
                    'data-no-section-collapse',
                    'true'
                );

                heading.classList.remove(
                    'collapsible-heading'
                );

                heading.removeAttribute(
                    'role'
                );

                heading.removeAttribute(
                    'tabindex'
                );

                heading.removeAttribute(
                    'aria-controls'
                );

                heading.removeAttribute(
                    'aria-expanded'
                );

                heading
                    .querySelectorAll(
                        '.indicator'
                    )
                    .forEach(function (arrow) {

                        arrow.remove();

                    });

            });

        document
            .querySelectorAll(
                '#mw-content-text .citizen-section-toggle'
            )
            .forEach(function (button) {

                button.remove();

            });

    }


    function stopSectionClick(event) {

        var heading =
            event.target.closest(
                '[data-no-section-collapse="true"]'
            );

        if (!heading) {
            return;
        }

        event.preventDefault();
        event.stopImmediatePropagation();

        forceSectionsOpen();

    }

    function start() {

        forceSectionsOpen();

        document.addEventListener(
            'click',
            stopSectionClick,
            true
        );

        var content =
            document.getElementById(
                'mw-content-text'
            );

        if (!content) {
            return;
        }

        var observer =
            new MutationObserver(
                function () {

                    forceSectionsOpen();

                }
            );

        observer.observe(
            content,
            {
                childList: true,
                subtree: true,
                attributes: true,
                attributeFilter: [
                    'hidden',
                    'class',
                    'aria-expanded'
                ]
            }
        );

        setTimeout(
            forceSectionsOpen,
            100
        );

        setTimeout(
            forceSectionsOpen,
            500
        );

        setTimeout(
            forceSectionsOpen,
            1500
        );

    }


    if (
        document.readyState ===
        'loading'
    ) {

        document.addEventListener(
            'DOMContentLoaded',
            start
        );

    } else {

        start();

    }

}());

