#quote-widget {
    background: var(--background-color-base, #fff);
    border: 1px solid var(--border-color-base, #eaecf0);
    border-radius: 12px;
    padding: 16px 20px;
    max-width: 500px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
    margin: 1em 0;
}

#quote-widget > div {
    font-size: 1.25rem;
    line-height: 1.5;
    color: var(--color-base, #202122);
    margin-bottom: 12px;
}

#quote-widget > button {
    background: var(--background-color-interactive, #36c);
    color: white;
    border: none;
    border-radius: 8px;
    padding: 8px 16px;
    font-size: 0.95rem;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.15s ease, transform 0.1s ease;
}

#quote-widget > button:hover {
    background: #2a4b8d;
}

#quote-widget > button:active {
    transform: scale(0.97);
}

.gradient {
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
    color: transparent;
}

