.dialogue-player-wrapper {
    display: flex;
	background: linear-gradient(90deg, rgb(0 0 0 / 24%) 50%, rgba(0, 0, 0, 0) 100%);
    padding: 3px 8px;
    gap: 10px;
}

.dialogue-player-icon {
	width: 20px;
}

.dialogue-npc-wrapper {
    display: flex;
    flex-direction: row;
}

.dialogue-npc, .dialogue-npc-text {
	padding: 3px 6px;
}

.dialogue-player-wrapper,
.dialogue-npc-wrapper {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    margin: 8px 0;
}

.dialogue-player-wrapper {
    justify-content: flex-end;
}

.dialogue-player-icon {
    width: 32px;
    height: 32px;
    flex-shrink: 0;

    background: var(--theme-accent, #777);
    border-radius: 50%;
}

.dialogue-player-text {
    max-width: 70%;
    padding: 8px 12px;

    background: rgba(255,255,255,.08);
    border: 1px solid rgba(255,255,255,.15);
    border-radius: 12px;

    line-height: 1.5;
}

.dialogue-npc-wrapper {
    justify-content: flex-start;
}

.dialogue-npc {
    padding: 4px 10px;

    color: #fff;
    font-weight: 600;
    border-radius: 6px;

    white-space: nowrap;
    align-self: flex-start;
}

.dialogue-npc-text {
    max-width: 70%;
    padding: 8px 12px;

    color: #fff;
    border-radius: 12px;

    line-height: 1.5;
}

.dialogue-player-wrapper + .dialogue-npc-wrapper,
.dialogue-npc-wrapper + .dialogue-player-wrapper {
    margin-top: 12px;
}

