.enchant-ui {
  width: 100%;
  max-width: 866px;
  min-height: 575px;

  background: #130b25;
  border: 2px solid #8f5cff;
  box-sizing: border-box;

  font-family: Arial, sans-serif;
  color: #ffffff;

  background-image:
    linear-gradient(135deg, rgba(140, 80, 255, 0.12) 0%, rgba(140, 80, 255, 0.12) 18%, transparent 18%, transparent 38%, rgba(140, 80, 255, 0.08) 38%, rgba(140, 80, 255, 0.08) 55%, transparent 55%);
}

.enchant-topbar {
  height: 32px;
  background: #935cff;

  display: flex;
  align-items: center;

  padding-left: 10px;
  box-sizing: border-box;

  font-size: 18px;
  font-weight: bold;
  letter-spacing: 1px;
}

.enchant-title-icon {
  margin-right: 8px;
}

.enchant-main {
  display: flex;
  gap: 14px;

  padding: 8px 16px 20px 12px;
  box-sizing: border-box;
}

.enchant-left {
  width: 215px;
  flex: 0 0 215px;
}

.enchant-item-slot {
  width: 213px;
  height: 213px;

  border: 1px solid #9b6cff;
  background: rgba(55, 30, 90, 0.35);

  box-sizing: border-box;
}

.enchant-right {
  flex: 1;
  min-width: 0;
}

.enchant-heading {
  font-size: 50px;
  font-weight: bold;
  line-height: 1;

  margin: 18px 0 26px 0;
}

.enchant-display-box {
  width: 100%;
  height: 190px;

  background: rgba(82, 45, 120, 0.55);
  box-sizing: border-box;
}

.enchant-line {
  width: 100%;
  height: 1px;

  background: #8f5cff;
  margin: 26px 0;
}

.enchant-cost-box {
  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 48px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
}

.enchant-button {
  width: 355px;
  height: 70px;

  margin: 22px auto 0 auto;

  background: #4b347a;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #130b25;
  font-size: 34px;
  font-weight: bold;

  box-sizing: border-box;
}

.enchant-ui {
  width: 100%;
  max-width: 1000px;
  min-height: 575px;
  margin: 0 auto;

  background: #130b25;
  border: 2px solid #8f5cff;
  box-sizing: border-box;

  font-family: Arial, sans-serif;
  color: #ffffff;

  background-image:
    linear-gradient(
      135deg,
      rgba(140, 80, 255, 0.12) 0%,
      rgba(140, 80, 255, 0.12) 18%,
      transparent 18%,
      transparent 38%,
      rgba(140, 80, 255, 0.08) 38%,
      rgba(140, 80, 255, 0.08) 55%,
      transparent 55%
    );
}

.enchant-topbar {
  height: 32px;
  background: #935cff;

  display: flex;
  align-items: center;

  padding-left: 10px;
  box-sizing: border-box;

  font-size: 18px;
  font-weight: bold;
  letter-spacing: 1px;
}

.enchant-title-icon {
  margin-right: 8px;
}

.enchant-main {
  display: flex;
  gap: 18px;

  padding: 10px 18px 22px 14px;
  box-sizing: border-box;
}

.enchant-left {
  width: 25%;
  max-width: 230px;
  min-width: 170px;
  flex: 0 0 25%;
}

.enchant-item-slot {
  width: 100%;
  height: 0;
  padding-bottom: 100%;

  border: 1px solid #9b6cff;
  background: rgba(55, 30, 90, 0.35);

  box-sizing: border-box;
}

.enchant-right {
  flex: 1;
  min-width: 0;
}

.enchant-heading {
  font-size: 50px;
  font-weight: bold;
  line-height: 1;

  margin: 18px 0 26px 0;
}

.enchant-display-box {
  width: 100%;
  height: 190px;

  background: rgba(82, 45, 120, 0.55);
  box-sizing: border-box;
}

.enchant-line {
  width: 100%;
  height: 1px;

  background: #8f5cff;
  margin: 26px 0;
}

.enchant-cost-box {
  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 48px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
}

.enchant-button {
  width: 55%;
  max-width: 355px;
  min-width: 230px;
  height: 70px;

  margin: 22px auto 0 auto;

  background: #4b347a;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #130b25;
  font-size: 34px;
  font-weight: bold;

  box-sizing: border-box;
}

/* Laptop / smaller monitor */
@media screen and (max-width: 900px) {
  .enchant-ui {
    max-width: 850px;
    min-height: 520px;
  }

  .enchant-main {
    gap: 16px;
    padding: 10px 16px 20px 12px;
  }

  .enchant-left {
    min-width: 155px;
  }

  .enchant-heading {
    font-size: 42px;
    margin: 16px 0 22px 0;
  }

  .enchant-display-box {
    height: 165px;
  }

  .enchant-cost-box {
    height: 80px;
    font-size: 40px;
  }

  .enchant-button {
    height: 62px;
    font-size: 30px;
  }
}

/* Tablet / big phone */
@media screen and (max-width: 650px) {
  .enchant-ui {
    min-height: 0;
  }

  .enchant-main {
    flex-direction: column;
    align-items: center;

    padding: 12px;
    gap: 14px;
  }

  .enchant-left {
    width: 45%;
    max-width: 210px;
    min-width: 140px;
    flex: none;
  }

  .enchant-right {
    width: 100%;
  }

  .enchant-heading {
    text-align: center;
    font-size: 36px;
    margin: 8px 0 18px 0;
  }

  .enchant-display-box {
    height: 145px;
  }

  .enchant-line {
    margin: 20px 0;
  }

  .enchant-cost-box {
    height: 75px;
    font-size: 34px;
  }

  .enchant-button {
    width: 80%;
    min-width: 0;
    height: 58px;
    font-size: 28px;
  }
}

/* Small phones */
