#rod-momentum:target ~ .enchant-ui .enchant-heading-default,
#rod-pistol:target ~ .enchant-ui .enchant-heading-default {
  display: none;
}
#rod-normal:target ~ .enchant-ui .enchant-heading-normal {
  display: block;
}

#rod-advanced:target ~ .enchant-ui .enchant-heading-advanced {
  display: block;
}

#rod-momentum:target ~ .enchant-ui .enchant-heading-momentum {
  display: block;
}

#rod-pistol:target ~ .enchant-ui .enchant-heading-pistol {
  display: block;
}

.enchant-ui {
  width: 100%;
  max-width: 1000px;
  min-height: 575px;
  margin: 0 auto;
  position: relative;

  background: #130b25;
  border: 2px solid #8f5cff;
  box-sizing: border-box;

  font-family: Arial, sans-serif;
  color: #ffffff;

  background-image:
    linear-gradient(
      135deg,
      rgba(140, 80, 255, 0.12) 0%,
      rgba(140, 80, 255, 0.12) 18%,
      transparent 18%,
      transparent 38%,
      rgba(140, 80, 255, 0.08) 38%,
      rgba(140, 80, 255, 0.08) 55%,
      transparent 55%
    );
}

.enchant-topbar {
  height: 32px;
  background: #935cff;

  display: flex;
  align-items: center;

  padding-left: 10px;
  box-sizing: border-box;

  font-size: 18px;
  font-weight: bold;
  letter-spacing: 1px;
}

.enchant-title-icon {
  margin-right: 8px;
}

.enchant-main {
  display: flex;
  gap: 18px;

  padding: 10px 18px 22px 14px;
  box-sizing: border-box;
}

.enchant-left {
  width: 25%;
  max-width: 230px;
  min-width: 170px;
  flex: 0 0 25%;
}

.enchant-item-slot {
  position: relative;
  overflow: hidden;

  width: 100%;
  height: 0;
  padding-bottom: 100%;

  border: 1px solid #9b6cff;
  background: rgba(55, 30, 90, 0.35);

  box-sizing: border-box;
}

.enchant-right {
  flex: 1;
  min-width: 0;
}

.enchant-heading {
  font-size: 50px;
  font-weight: bold;
  line-height: 1;

  margin: 18px 0 26px 0;
}

.enchant-display-box {
  width: 100%;
  height: 190px;

  background: rgba(82, 45, 120, 0.55);
  box-sizing: border-box;
}

.enchant-line {
  width: 100%;
  height: 1px;

  background: #8f5cff;
  margin: 26px 0;
}

.enchant-cost-box {
  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 48px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
}

.enchant-button {
  width: 55%;
  max-width: 355px;
  min-width: 230px;
  height: 70px;

  margin: 22px auto 0 auto;

  background: #4b347a;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #130b25;
  font-size: 34px;
  font-weight: bold;

  box-sizing: border-box;
}

@media screen and (max-width: 900px) {
  .enchant-ui {
    max-width: 850px;
    min-height: 520px;
  }

  .enchant-main {
    gap: 16px;
    padding: 10px 16px 20px 12px;
  }

  .enchant-left {
    min-width: 155px;
  }

  .enchant-heading {
    font-size: 42px;
    margin: 16px 0 22px 0;
  }

  .enchant-display-box {
    height: 165px;
  }

  .enchant-cost-box {
    height: 80px;
    font-size: 40px;
  }

  .enchant-button {
    height: 62px;
    font-size: 30px;
  }
}
@media screen and (max-width: 650px) {
  .enchant-ui {
    min-height: 0;
  }

  .enchant-main {
    flex-direction: column;
    align-items: center;

    padding: 12px;
    gap: 14px;
  }

  .enchant-left {
    width: 45%;
    max-width: 210px;
    min-width: 140px;
    flex: none;
  }

  .enchant-right {
    width: 100%;
  }

  .enchant-heading {
    text-align: center;
    font-size: 36px;
    margin: 8px 0 18px 0;
  }

  .enchant-display-box {
    height: 145px;
  }

  .enchant-line {
    margin: 20px 0;
  }

  .enchant-cost-box {
    height: 75px;
    font-size: 34px;
  }

  .enchant-button {
    width: 80%;
    min-width: 0;
    height: 58px;
    font-size: 28px;
  }
}

@media screen and (max-width: 420px) {
  .enchant-topbar {
    height: 28px;
    font-size: 15px;
  }

  .enchant-main {
    padding: 10px;
  }

  .enchant-left {
    width: 55%;
    min-width: 120px;
  }

  .enchant-heading {
    font-size: 30px;
  }

  .enchant-display-box {
    height: 120px;
  }

  .enchant-cost-box {
    height: 62px;
    font-size: 28px;
  }

  .enchant-button {
    width: 100%;
    height: 52px;
    font-size: 24px;
  }
}

@media screen and (max-width: 340px) {
  .enchant-heading {
    font-size: 26px;
  }

  .enchant-cost-box {
    font-size: 24px;
  }

  .enchant-button {
    font-size: 21px;
  }
}
.enchant-target {
  position: absolute;
  top: 0;
  left: 0;

  width: 0;
  height: 0;

  overflow: hidden;
  pointer-events: none;
}
.enchant-button a {
  width: 100%;
  height: 100%;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #130b25;
  text-decoration: none;
}

.enchant-selected-img {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  align-items: center;
  justify-content: center;
}

.enchant-selected-img img {
  max-width: 75%;
  max-height: 75%;
  width: auto;
  height: auto;
  transform: translateX(20px);
}
#rod-normal:target ~ .enchant-main .selected-normal {
  display: flex;
}

#rod-advanced:target ~ .enchant-main .selected-advanced {
  display: flex;
}

#rod-momentum:target ~ .enchant-main .selected-momentum {
  display: flex;
}

#rod-pistol:target ~ .enchant-main .selected-pistol {
  display: flex;
}

.rod-popup {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 32px;
  bottom: 0;

  z-index: 100;

  align-items: center;
  justify-content: center;

  background: rgba(8, 4, 20, 0.72);
  box-sizing: border-box;
  padding: 24px;
}
#rod-picker:target ~ .rod-popup {
  display: flex;
}

.rod-popup-panel {
  width: 90%;
  max-width: 760px;

  background: #170d2f;
  border: 2px solid #8f5cff;
  box-shadow: 0 0 24px rgba(143, 92, 255, 0.35);

  padding: 24px;
  box-sizing: border-box;
}

.rod-popup-title {
  text-align: center;
  font-size: 36px;
  font-weight: bold;
  margin-bottom: 22px;
  color: #ffffff;
}

.rod-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}

.rod-card {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  min-height: 190px;
  padding: 14px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  text-align: center;
  box-sizing: border-box;
}

.rod-card:hover {
  background: #26124d;
  border-color: #9b6cff;
}

.rod-card img {
  max-width: 120px;
  max-height: 120px;
  width: auto;
  height: auto;
}

.rod-card a {
  color: #ffffff;
  text-decoration: none;
  font-weight: bold;
}
@media screen and (max-width: 650px) {
  .rod-popup {
    padding: 14px;
  }

  .rod-popup-panel {
    width: 100%;
    padding: 16px;
  }

  .rod-popup-title {
    font-size: 28px;
  }

  .rod-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .rod-card {
    min-height: 155px;
    padding: 10px;
  }

  .rod-card img {
    max-width: 85px;
    max-height: 85px;
  }
}

@media screen and (max-width: 360px) {
  .rod-popup-title {
    font-size: 24px;
  }

  .rod-card {
    min-height: 135px;
    font-size: 13px;
  }

  .rod-card img {
    max-width: 70px;
    max-height: 70px;
  }
}

.enchant-heading-normal,
.enchant-heading-advanced,
.enchant-heading-momentum,
.enchant-heading-pistol {
  display: none;
}
#rod-normal:target ~ .enchant-main .enchant-heading-default,
#rod-advanced:target ~ .enchant-main .enchant-heading-default,
#rod-momentum:target ~ .enchant-main .enchant-heading-default,
#rod-pistol:target ~ .enchant-main .enchant-heading-default {
