  font-size: 50px;
  font-weight: bold;
  line-height: 1;

  margin: 18px 0 26px 0;
}
.enchant-line {
  width: 100%;
  height: 1px;

  background: #8f5cff;
  margin: 26px 0;
}

.enchant-cost-box {
  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 48px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
}

.enchant-button {
  width: 55%;
  max-width: 355px;
  min-width: 230px;
  height: 70px;

  margin: 22px auto 0 auto;

  background: #4b347a;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #130b25;
  font-size: 34px;
  font-weight: bold;

  box-sizing: border-box;
}

