.enchant-ui {
  width: 100%;
  max-width: 1000px;
  min-height: 575px;
  margin: 0 auto;
  position: relative;

  background: #130b25;
  border: 2px solid #8f5cff;
  box-sizing: border-box;

  font-family: Arial, sans-serif;
  color: #ffffff;

  background-image:
    linear-gradient(
      135deg,
      rgba(140, 80, 255, 0.12) 0%,
      rgba(140, 80, 255, 0.12) 18%,
      transparent 18%,
      transparent 38%,
      rgba(140, 80, 255, 0.08) 38%,
      rgba(140, 80, 255, 0.08) 55%,
      transparent 55%
    );
}

.enchant-topbar {
  height: 32px;
  background: #935cff;

  display: flex;
  align-items: center;

  padding-left: 10px;
  box-sizing: border-box;

  font-size: 18px;
  font-weight: bold;
  letter-spacing: 1px;
}

.enchant-title-icon {
  margin-right: 8px;
}

.enchant-main {
  display: flex;
  gap: 18px;

  padding: 10px 18px 22px 14px;
  box-sizing: border-box;
}

.enchant-left {
  width: 25%;
  max-width: 230px;
  min-width: 170px;
  flex: 0 0 25%;
}

.enchant-item-slot {
  position: relative;
  overflow: hidden;

  width: 100%;
  height: 0;
  padding-bottom: 100%;

  border: 1px solid #9b6cff;
  background: rgba(55, 30, 90, 0.35);

  box-sizing: border-box;
}

.enchant-right {
  flex: 1;
  min-width: 0;
}

.enchant-heading {
  font-size: 50px;
  font-weight: bold;
  line-height: 1;

  margin: 18px 0 26px 0;
}
.enchant-line {
  width: 100%;
  height: 1px;

  background: #8f5cff;
  margin: 26px 0;
}

.enchant-cost-box {
  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 48px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
}

.enchant-button {
  width: 55%;
  max-width: 355px;
  min-width: 230px;
  height: 70px;

  margin: 22px auto 0 auto;

  background: #4b347a;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #130b25;
  font-size: 34px;
  font-weight: bold;

  box-sizing: border-box;
}

