}

.enchant-selected-img img {
  max-width: 75%;
  max-height: 75%;
  width: auto;
  height: auto;
  transform: translateX(20px);
}
.rod-popup {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 32px;
  bottom: 0;

  z-index: 100;

  align-items: center;
  justify-content: center;

  background: rgba(8, 4, 20, 0.72);
  box-sizing: border-box;
  padding: 24px;
}
.rod-popup-panel {
  width: 90%;
  max-width: 760px;

  background: #170d2f;
  border: 2px solid #8f5cff;
  box-shadow: 0 0 24px rgba(143, 92, 255, 0.35);

  padding: 24px;
  box-sizing: border-box;
}

.rod-popup-title {
  text-align: center;
  font-size: 36px;
  font-weight: bold;
  margin-bottom: 22px;
  color: #ffffff;
}

.rod-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}

.rod-card {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  min-height: 190px;
  padding: 14px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  text-align: center;
  box-sizing: border-box;
}

.rod-card:hover {
  background: #26124d;
  border-color: #9b6cff;
}

.rod-card img {
  max-width: 120px;
  max-height: 120px;
  width: auto;
  height: auto;
}

@media screen and (max-width: 650px) {
  .rod-popup {
    padding: 14px;
  }

