    width: 100%;
    padding: 16px;
  }

  .rod-popup-title {
    font-size: 28px;
  }

  .rod-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .rod-card {
    min-height: 155px;
    padding: 10px;
  }

  .rod-card img {
    max-width: 85px;
    max-height: 85px;
  }
}

