.enchant-menu-button {
  display: flex;
  align-items: center;
  justify-content: center;

  color: #ffffff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
  background: none;
  border: none;
  border-radius: 0;
}

.enchant-menu-button:hover {
  color: #d8c8ff;
}

.enchant-menu-popup {
  display: none;

  position: absolute;
  right: 12px;
  top: 44px;

  z-index: 150;

  width: 320px;
  max-width: calc(100% - 24px);

  background: rgba(8, 4, 20, 0.9);
  border: 2px solid #8f5cff;
  border-radius: 14px;

  box-shadow: 0 0 24px rgba(143, 92, 255, 0.45);

  padding: 14px;
  box-sizing: border-box;
}

.enchant-ui.enchant-menu-open .enchant-menu-popup {
  display: block;
}

.enchant-menu-panel {
  color: #ffffff;
}

.enchant-menu-title {
  color: #ffffff;
  font-size: 24px;
  font-weight: bold;
  text-align: center;

  margin-bottom: 14px;
}

.enchant-menu-section {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 10px;
