}

.enchant-menu-text {
  color: #ffffff;
  font-size: 14px;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.enchant-menu-close {
  display: block;

  width: fit-content;
  margin: 12px auto 0 auto;
  padding: 8px 16px;

  background: #4b347a;
  border-radius: 10px;

  color: #ffffff;
  font-weight: bold;
  cursor: pointer;
}

.enchant-menu-close:hover {
  background: #6d4ab0;
}

