.enchant-menu-button {
  position: relative;
  z-index: 1001;
  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-width: 32px;
  min-height: 28px;

  cursor: pointer;
  pointer-events: auto;
  user-select: none;
}

.enchant-menu-popup {
  z-index: 1200;
  pointer-events: auto;
}

.enchant-menu-option,
.enchant-menu-option a,
.enchant-menu-close {
  pointer-events: auto;
