  user-select: none;
}

.enchant-menu-close:hover,
.enchant-menu-back:hover {
  background: #6d4ab0;
}

/* responsive */

@media screen and (max-width: 900px) {
  .enchant-ui {
    max-width: 850px;
    min-height: 520px;
  }

  .enchant-main {
    gap: 16px;
    padding: 10px 16px 20px 12px;
  }

  .enchant-left {
    min-width: 155px;
  }

  .enchant-heading {
    font-size: 42px;
    margin: 16px 0 22px 0;
  }

