  }

  .enchant-button {
    width: 80%;
    min-width: 0;
    height: 58px;
    font-size: 28px;
  }

  .rod-popup {
    padding: 14px;
  }

  .rod-popup-panel {
    width: 100%;
    padding: 16px;
  }

  .rod-popup-title {
    font-size: 28px;
  }

  .rod-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .rod-card {
    min-height: 155px;
    padding: 10px;
  }

  .rod-card img {
    max-width: 85px;
    max-height: 85px;
  }
}

@media screen and (max-width: 420px) {
  .enchant-topbar {
    height: 28px;
