  }

  .enchant-left {
    width: 55%;
    min-width: 120px;
  }

  .enchant-heading {
    font-size: 30px;
  }

  .enchant-display-box {
    height: 120px;
  }

  .enchant-info-text {
    font-size: 22px;
  }

  .enchant-cost-box {
    height: 62px;
