  .enchant-result-card {
    min-height: 115px;
  }

  .enchant-result-card img {
    max-width: 46px;
    max-height: 46px;
  }

  .enchant-result-level {
    font-size: 16px;
  }

  .enchant-menu-popup {
    top: 42px;
    right: 8px;
    bottom: 14px;

    width: calc(100% - 16px);
    max-width: none;
  }

  .enchant-menu-title {
    font-size: 20px;
  }

  .enchant-menu-option {
    font-size: 16px;
    padding: 14px;
  }

  .enchant-menu-text {
    font-size: 13px;
  }
}

@media screen and (max-width: 360px) {
  .rod-popup-title {
    font-size: 24px;
  }

  .rod-card {
    min-height: 135px;
    font-size: 13px;
  }

  .rod-card img {
    max-width: 70px;
    max-height: 70px;
  }
}

@media screen and (max-width: 340px) {
  .enchant-heading {
