.enchant-menu-popup .enchant-menu-panel .enchant-menu-back,
.enchant-menu-popup .enchant-menu-panel .enchant-menu-close {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 110px;
  min-width: 110px;

  margin-left: auto;
  margin-right: auto;

  padding: 8px 18px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 999px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-popup .enchant-menu-panel .enchant-menu-back {
  margin-top: 18px;
}

.enchant-menu-popup .enchant-menu-panel .enchant-menu-close {
  margin-top: 28px;
}

.enchant-ui {
  width: 100%;
  max-width: 1000px;
  min-height: 575px;
  margin: 0 auto;
  position: relative;

  background: #130b25;
  border: 2px solid #8f5cff;
  box-sizing: border-box;

  font-family: Arial, sans-serif;
  color: #ffffff;

  background-image:
    linear-gradient(
      135deg,
      rgba(140, 80, 255, 0.12) 0%,
      rgba(140, 80, 255, 0.12) 18%,
      transparent 18%,
      transparent 38%,
      rgba(140, 80, 255, 0.08) 38%,
      rgba(140, 80, 255, 0.08) 55%,
      transparent 55%
    );
}

.enchant-topbar {
  position: relative;
  z-index: 1000;

  height: 32px;
  background: #935cff;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 10px;
  box-sizing: border-box;

  font-size: 18px;
  font-weight: bold;
  letter-spacing: 1px;
}

.enchant-topbar-title {
  display: flex;
  align-items: center;
}

.enchant-title-icon {
  margin-right: 8px;
}

.enchant-main {
  display: flex;
  gap: 18px;

  padding: 10px 18px 22px 14px;
  box-sizing: border-box;
}

.enchant-left {
  width: 25%;
  max-width: 230px;
  min-width: 170px;
  flex: 0 0 25%;
}

.enchant-item-slot {
  position: relative;
  overflow: hidden;

  width: 100%;
  height: 0;
  padding-bottom: 100%;

  border: 1px solid #9b6cff;
  background: rgba(55, 30, 90, 0.35);

  box-sizing: border-box;
}

.enchant-right {
  flex: 1;
  min-width: 0;
}

.enchant-heading {
  font-size: 50px;
  font-weight: bold;
  line-height: 1;

  margin: 18px 0 26px 0;
}

.enchant-line {
  width: 100%;
  height: 1px;

  background: #8f5cff;
  margin: 26px 0;
}

.enchant-cost-box {
  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 48px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-fish-points-display {
  max-width: 100%;
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-button {
  width: 55%;
  max-width: 355px;
  min-width: 230px;
  height: 70px;

  margin: 22px auto 0 auto;

  background: #4b347a;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #130b25;
  font-size: 34px;
  font-weight: bold;

  box-sizing: border-box;
}

.enchant-open-picker {
  cursor: pointer;
}

.enchant-item-slot:hover,
.enchant-button:hover {
  outline: 2px solid #9b6cff;
}

/* selected rod image */

.enchant-selected-img {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  align-items: center;
  justify-content: center;
}

.enchant-selected-img img {
  max-width: 75%;
  max-height: 75%;
  width: auto;
  height: auto;
  transform: translateX(20px);
}

.enchant-ui.rod-normal .selected-normal,
.enchant-ui.rod-advanced .selected-advanced,
.enchant-ui.rod-momentum .selected-momentum,
.enchant-ui.rod-pistol .selected-pistol {
  display: flex;
}

/* headings */

.enchant-heading-normal,
.enchant-heading-advanced,
.enchant-heading-momentum,
.enchant-heading-pistol {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-default,
.enchant-ui.rod-advanced .enchant-heading-default,
.enchant-ui.rod-momentum .enchant-heading-default,
.enchant-ui.rod-pistol .enchant-heading-default {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-normal,
.enchant-ui.rod-advanced .enchant-heading-advanced,
.enchant-ui.rod-momentum .enchant-heading-momentum,
.enchant-ui.rod-pistol .enchant-heading-pistol {
  display: block;
}

/* rod popup */

.rod-popup {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 32px;
  bottom: 0;

  z-index: 100;

  align-items: center;
  justify-content: center;

  background: rgba(8, 4, 20, 0.72);
  box-sizing: border-box;
  padding: 24px;
}

.enchant-ui.rod-picker-open .rod-popup {
  display: flex;
}

.rod-popup-panel {
  width: 90%;
  max-width: 760px;

  background: #170d2f;
  border: 2px solid #8f5cff;
  box-shadow: 0 0 24px rgba(143, 92, 255, 0.35);

  padding: 24px;
  box-sizing: border-box;
}

.rod-popup-title {
  text-align: center;
  font-size: 36px;
  font-weight: bold;
  margin-bottom: 22px;
  color: #ffffff;
}

.rod-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}

.rod-card {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  min-height: 190px;
  padding: 14px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  text-align: center;
  box-sizing: border-box;

  cursor: pointer;
}

.rod-card:hover {
  background: #26124d;
  border-color: #9b6cff;
}

.rod-card img {
  max-width: 120px;
  max-height: 120px;
  width: auto;
  height: auto;
}

/* fish points input */

.enchant-points-input {
  width: 90%;
  background: transparent;
  border: none;
  outline: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;
}

.enchant-points-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.fish-points-error {
  border-color: #ff6666;
}

.fish-points-error .enchant-fish-points-display {
  color: #ff8888;
  font-size: 24px;
  font-style: normal;
}

/* enchant result display */

.enchant-display-box {
  width: 100%;
  height: 190px;

  background: rgba(82, 45, 120, 0.55);
  box-sizing: border-box;

  display: block;

  padding: 12px;

  overflow-y: auto;
  overflow-x: hidden;
}

.enchant-info-text {
  min-height: 100%;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #bda2ff;
  font-size: 30px;
  font-weight: bold;
  text-align: center;
}

.enchant-result-grid {
  display: none;
  width: 100%;

  grid-template-columns: repeat(auto-fit, minmax(90px, 1fr));
  gap: 10px;
}

.enchant-result-card {
  min-height: 130px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;

  text-align: center;
  box-sizing: border-box;
  padding: 8px;
}

.enchant-result-card img {
  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;
}

.enchant-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
  line-height: 1;
}

.enchant-result-level {
  color: #bda2ff;
  font-size: 18px;
  font-weight: bold;
}

/* enchant colors */

.enchant-bg-strength {
  background: #8c4368;
}

.enchant-bg-strength-plus {
  background: #871d50;
}

.enchant-bg-momentum {
  background: #5d8084;
}

.enchant-bg-momentum-plus {
  background: #387e73;
}

.enchant-bg-fortune {
  background: #406a98;
}

.enchant-bg-ultra {
  background: #8b4a43;
}

.enchant-bg-less-backfire {
  background: #463b53;
}

.enchant-bg-sharpshooter {
  background: #7f1397;
}

/* menu */

.enchant-menu-button {
  position: relative;
  z-index: 1001;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-width: 32px;
  min-height: 28px;

  color: #ffffff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
  user-select: none;
  pointer-events: auto;

  background: none;
  border: none;
  border-radius: 0;
}

.enchant-menu-button:hover {
  color: #d8c8ff;
}

.enchant-menu-popup {
  display: none;

  position: absolute;
  top: 46px;
  right: 12px;
  bottom: 18px;

  width: 320px;
  max-width: calc(100% - 24px);

  z-index: 1200;

  background: rgba(8, 4, 20, 0.96);
  border: 2px solid #8f5cff;
  border-radius: 16px;

  box-shadow: -8px 0 24px rgba(143, 92, 255, 0.35);

  padding: 18px;
  box-sizing: border-box;

  overflow-y: auto;
  pointer-events: auto;
}

.enchant-ui.enchant-menu-open .enchant-menu-popup {
  display: block;
}

.enchant-menu-panel {
  min-height: 100%;

  display: flex;
  flex-direction: column;

  color: #ffffff;
}

.enchant-menu-title {
  color: #ffffff;
  font-size: 24px;
  font-weight: bold;

  margin-bottom: 12px;
}

.enchant-menu-main,
.enchant-menu-options {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-menu-option {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 18px 16px;

  color: #ffffff;
  font-size: 18px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-option:hover {
  background: #21103f;
  border-color: #8f5cff;
}

.enchant-menu-page {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-main,
.enchant-menu-panel.show-notation .enchant-menu-main {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-page-fish,
.enchant-menu-panel.show-notation .enchant-menu-page-notation {
  display: block;
}

.enchant-menu-text {
  color: #ffffff;
  font-size: 14px;
  line-height: 1.35;
  overflow-wrap: anywhere;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px;
  box-sizing: border-box;
}

.enchant-notation-choice {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px 16px;
  margin-bottom: 10px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-notation-choice:hover {
  background: #140a24;
  border-color: #5b347f;
}

.enchant-notation-choice.notation-active {
  background: #21103f;
  border-color: #8f5cff;
  box-shadow: 0 0 12px rgba(143, 92, 255, 0.45);
}

.enchant-menu-back {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  width: fit-content;
  margin: 12px auto 0 auto;
  padding: 8px 18px;

  background: #2d1b52;
  border: 2px solid #5d3a91;
  border-radius: 999px;

  color: #ffffff;
  font-weight: bold;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  align-self: center;

  width: auto;
  min-width: 90px;

  margin: 22px auto 0 auto;
  padding: 8px 22px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 999px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-close:hover,
.enchant-menu-back:hover {
  background: #6d4ab0;
}

