.enchant-advisor-box {
  width: 100%;
  margin-top: 12px;
  padding: 12px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;

  box-sizing: border-box;
  cursor: text;
}

.enchant-advisor-display {
  display: block;
  color: #ffffff;
}

.enchant-advisor-input {
  width: 100%;

  background: transparent;
  border: none;
  outline: none;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  font-family: inherit;

  box-sizing: border-box;
}

.enchant-advisor-input::placeholder {
