/* ===== Fish Advisor rod list cleanup ===== */

/* shrink the whole menu a bit */
.enchant-menu-popup {
  width: 470px;
  max-width: calc(100% - 20px);
}

/* make the advisor area a bit tighter too */
.enchant-advisor-layout {
  grid-template-columns: 95px 1fr;
  gap: 12px;
}

.enchant-advisor-rods {
  width: 95px;
}

/* outer pill only */
.enchant-advisor-rod {
  width: 95px;
  min-height: 92px;

  padding: 8px 6px 6px;
  box-sizing: border-box;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;

  gap: 4px;
  overflow: hidden;
}

/* remove any extra box/background around the image */
.enchant-advisor-rod a,
.enchant-advisor-rod .image {
  display: block;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;
  line-height: 0;
}

/* image itself */
.enchant-advisor-rod img,
.enchant-advisor-rod .mw-file-element {
  display: block;
  max-width: 38px;
  max-height: 38px;
  width: auto;
  height: auto;
  margin: 0 auto;
}

/* move name higher and keep it directly under image */
.enchant-advisor-rod span {
  display: block;
  margin-top: 2px;
  line-height: 1.1;
  font-size: 11px;
  text-align: center;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* make right side fit the smaller menu */
.enchant-advisor-right {
  gap: 12px;
}

/* mobile */
@media screen and (max-width: 520px) {
  .enchant-menu-popup {
    width: calc(100% - 16px);
  }

  .enchant-advisor-layout {
    grid-template-columns: 82px 1fr;
    gap: 10px;
  }

  .enchant-advisor-rods {
    width: 82px;
  }

  .enchant-advisor-rod {
    width: 82px;
    min-height: 84px;
    padding: 7px 5px 5px;
  }

  .enchant-advisor-rod img,
  .enchant-advisor-rod .mw-file-element {
    max-width: 32px;
    max-height: 32px;
  }

  .enchant-advisor-rod span {
    font-size: 10px;
  }
}
.enchant-advisor-right {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-advisor-output {
  order: 1;
}

.enchant-advisor-box {
  order: 2;
}

.enchant-advisor-check {
  order: 3;
}

.enchant-ui {
  width: 100%;
  max-width: 1000px;
  min-height: 575px;
  margin: 0 auto;
  position: relative;

  background: #130b25;
  border: 2px solid #8f5cff;
  box-sizing: border-box;

  font-family: Arial, sans-serif;
  color: #ffffff;

  background-image:
    linear-gradient(
      135deg,
      rgba(140, 80, 255, 0.12) 0%,
      rgba(140, 80, 255, 0.12) 18%,
      transparent 18%,
      transparent 38%,
      rgba(140, 80, 255, 0.08) 38%,
      rgba(140, 80, 255, 0.08) 55%,
      transparent 55%
    );
}

.enchant-topbar {
  position: relative;
  z-index: 1000;

  height: 32px;
  background: #935cff;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 10px;
  box-sizing: border-box;

  font-size: 18px;
  font-weight: bold;
  letter-spacing: 1px;
}

.enchant-topbar-title {
  display: flex;
  align-items: center;
}

.enchant-title-icon {
  margin-right: 8px;
}

.enchant-main {
  display: flex;
  gap: 18px;

  padding: 10px 18px 22px 14px;
  box-sizing: border-box;
}

.enchant-left {
  width: 25%;
  max-width: 230px;
  min-width: 170px;
  flex: 0 0 25%;
}

.enchant-item-slot {
  position: relative;
  overflow: hidden;

  width: 100%;
  height: 0;
  padding-bottom: 100%;

  border: 1px solid #9b6cff;
  background: rgba(55, 30, 90, 0.35);

  box-sizing: border-box;
}

.enchant-right {
  flex: 1;
  min-width: 0;
}

.enchant-heading {
  font-size: 50px;
  font-weight: bold;
  line-height: 1;

  margin: 18px 0 26px 0;
}

.enchant-line {
  width: 100%;
  height: 1px;

  background: #8f5cff;
  margin: 26px 0;
}

.enchant-cost-box {
  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 48px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-fish-points-display {
  max-width: 100%;
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-button {
  width: 55%;
  max-width: 355px;
  min-width: 230px;
  height: 70px;

  margin: 22px auto 0 auto;

  background: #4b347a;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #130b25;
  font-size: 34px;
  font-weight: bold;

  box-sizing: border-box;
}

.enchant-open-picker {
  cursor: pointer;
}

.enchant-item-slot:hover,
.enchant-button:hover {
  outline: 2px solid #9b6cff;
}

/* selected rod image */

.enchant-selected-img {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  align-items: center;
  justify-content: center;
}

.enchant-selected-img img {
  max-width: 75%;
  max-height: 75%;
  width: auto;
  height: auto;
  transform: translateX(20px);
}

.enchant-ui.rod-normal .selected-normal,
.enchant-ui.rod-advanced .selected-advanced,
.enchant-ui.rod-momentum .selected-momentum,
.enchant-ui.rod-pistol .selected-pistol {
  display: flex;
}

/* headings */

.enchant-heading-normal,
.enchant-heading-advanced,
.enchant-heading-momentum,
.enchant-heading-pistol {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-default,
.enchant-ui.rod-advanced .enchant-heading-default,
.enchant-ui.rod-momentum .enchant-heading-default,
.enchant-ui.rod-pistol .enchant-heading-default {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-normal,
.enchant-ui.rod-advanced .enchant-heading-advanced,
.enchant-ui.rod-momentum .enchant-heading-momentum,
.enchant-ui.rod-pistol .enchant-heading-pistol {
  display: block;
}

/* rod popup */

.rod-popup {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 32px;
  bottom: 0;

  z-index: 100;

  align-items: center;
  justify-content: center;

  background: rgba(8, 4, 20, 0.72);
  box-sizing: border-box;
  padding: 24px;
}

.enchant-ui.rod-picker-open .rod-popup {
  display: flex;
}

.rod-popup-panel {
  width: 90%;
  max-width: 760px;

  background: #170d2f;
  border: 2px solid #8f5cff;
  box-shadow: 0 0 24px rgba(143, 92, 255, 0.35);

  padding: 24px;
  box-sizing: border-box;
}

.rod-popup-title {
  text-align: center;
  font-size: 36px;
  font-weight: bold;
  margin-bottom: 22px;
  color: #ffffff;
}

.rod-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}

.rod-card {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  min-height: 190px;
  padding: 14px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  text-align: center;
  box-sizing: border-box;

  cursor: pointer;
}

.rod-card:hover {
  background: #26124d;
  border-color: #9b6cff;
}

.rod-card img {
  max-width: 120px;
  max-height: 120px;
  width: auto;
  height: auto;
}

/* fish points input */

.enchant-points-input {
  width: 90%;
  background: transparent;
  border: none;
  outline: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;
}

.enchant-points-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.fish-points-error {
  border-color: #ff6666;
}

.fish-points-error .enchant-fish-points-display {
  color: #ff8888;
  font-size: 24px;
  font-style: normal;
}

/* enchant result display */

.enchant-display-box {
  width: 100%;
  height: 190px;

  background: rgba(82, 45, 120, 0.55);
  box-sizing: border-box;

  display: block;

  padding: 12px;

  overflow-y: auto;
  overflow-x: hidden;
}

.enchant-info-text {
  min-height: 100%;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #bda2ff;
  font-size: 30px;
  font-weight: bold;
  text-align: center;
}

.enchant-result-grid {
  display: none;
  width: 100%;

  grid-template-columns: repeat(auto-fit, minmax(90px, 1fr));
  gap: 10px;
}

.enchant-result-card {
  min-height: 130px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;

  text-align: center;
  box-sizing: border-box;
  padding: 8px;
}

.enchant-result-card img {
  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;
}

.enchant-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
  line-height: 1;
}

.enchant-result-level {
  color: #bda2ff;
  font-size: 18px;
  font-weight: bold;
}

