  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;

  line-height: 0;
}

.enchant-advisor-rod img,
.enchant-advisor-rod .mw-file-element {
  display: block;

  max-width: 34px;
  max-height: 34px;
  width: auto;
  height: auto;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;

  margin: 0 auto;
}

.enchant-advisor-rod span {
  display: block;
  max-width: 100%;

  margin-top: 2px;

  line-height: 1.1;
  font-size: 10px;
  text-align: center;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-advisor-right {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-advisor-output {
  order: 1;

  width: 100%;
  min-height: 190px;
  max-height: 260px;

  margin-top: 0;
  padding: 14px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  color: #ffffff;
  font-size: 14px;
  line-height: 1.45;

  overflow-y: auto;
  overflow-x: hidden;

  box-sizing: border-box;
  white-space: normal;
}

.enchant-advisor-box {
  order: 2;

  width: 100%;
  min-height: 74px;

  padding: 12px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;

  box-sizing: border-box;
  cursor: text;

  display: flex;
  align-items: center;

  overflow: hidden;
}

.enchant-advisor-display {
  display: block;
  width: 100%;

  color: #ffffff;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-advisor-input {
  width: 100%;

  background: transparent;
  border: none;
  outline: none;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  font-family: inherit;

  box-sizing: border-box;
}

.enchant-advisor-input::placeholder {
  color: #8f7bbd;
}

.enchant-advisor-check {
  order: 3;

  width: 100%;
  margin-top: 0;
  padding: 12px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 12px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;

  box-sizing: border-box;
}

.enchant-advisor-check:hover {
  background: #6d4ab0;
}

.advisor-result-title {
  font-size: 15px;
  font-weight: bold;
  color: #ffffff;
  margin-bottom: 10px;
}

.advisor-result-row {
  background: #130b25;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 10px;
  margin-bottom: 8px;

  display: flex;
  gap: 8px;
  align-items: center;

  box-sizing: border-box;
}

.advisor-result-row.advisor-best {
  border-color: #8f5cff;
  box-shadow: 0 0 10px rgba(143, 92, 255, 0.35);
}

.advisor-result-row img {
  width: 34px;
  height: 34px;
  object-fit: contain;
  flex: 0 0 34px;
}

.advisor-result-info {
  flex: 1;
  min-width: 0;
}

.advisor-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-level {
  color: #bda2ff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-min {
  color: #8f7bbd;
  font-size: 11px;
  margin-top: 2px;
}

/* responsive */

@media screen and (max-width: 900px) {
  .enchant-ui {
    max-width: 850px;
    min-height: 520px;
  }

  .enchant-main {
    gap: 16px;
    padding: 10px 16px 20px 12px;
  }

  .enchant-left {
    min-width: 155px;
  }

  .enchant-heading {
    font-size: 42px;
    margin: 16px 0 22px 0;
  }

  .enchant-display-box {
    height: 165px;
  }

  .enchant-cost-box {
    height: 80px;
    font-size: 40px;
  }

  .enchant-button {
    height: 62px;
    font-size: 30px;
  }
}

@media screen and (max-width: 650px) {
  .enchant-ui {
    min-height: 0;
  }

  .enchant-main {
    flex-direction: column;
    align-items: center;

    padding: 12px;
    gap: 14px;
  }

  .enchant-left {
    width: 45%;
    max-width: 210px;
    min-width: 140px;
    flex: none;
  }

  .enchant-right {
    width: 100%;
  }

  .enchant-heading {
    text-align: center;
    font-size: 36px;
    margin: 8px 0 18px 0;
  }

  .enchant-display-box {
    height: 145px;
  }

  .enchant-line {
    margin: 20px 0;
  }

  .enchant-cost-box {
    height: 75px;
    font-size: 34px;
  }

  .enchant-button {
    width: 80%;
    min-width: 0;
    height: 58px;
    font-size: 28px;
  }

  .rod-popup {
    padding: 14px;
  }

  .rod-popup-panel {
    width: 100%;
    padding: 16px;
  }

  .rod-popup-title {
    font-size: 28px;
  }

  .rod-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .rod-card {
    min-height: 155px;
    padding: 10px;
  }

  .rod-card img {
    max-width: 85px;
    max-height: 85px;
  }
}

@media screen and (max-width: 520px) {
  .enchant-menu-popup {
    width: calc(100% - 16px);
  }

  .enchant-advisor-layout {
    grid-template-columns: 76px 1fr;
    gap: 10px;
  }

  .enchant-advisor-rods {
    width: 76px;
  }

  .enchant-advisor-rod {
    width: 76px;
    min-height: 82px;
    font-size: 9px;
  }

  .enchant-advisor-rod img,
  .enchant-advisor-rod .mw-file-element {
    max-width: 30px;
    max-height: 30px;
  }

  .enchant-advisor-rod span {
    font-size: 9px;
  }
}

@media screen and (max-width: 420px) {
  .enchant-topbar {
    height: 28px;
    font-size: 15px;
  }

  .enchant-main {
    padding: 10px;
  }

  .enchant-left {
    width: 55%;
    min-width: 120px;
  }

  .enchant-heading {
    font-size: 30px;
  }

  .enchant-display-box {
    height: 120px;
  }

  .enchant-info-text {
    font-size: 22px;
  }

  .enchant-cost-box {
    height: 62px;
    font-size: 28px;
  }

  .enchant-button {
    width: 100%;
    height: 52px;
    font-size: 24px;
  }

  .enchant-result-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .enchant-result-card {
    min-height: 115px;
  }

  .enchant-result-card img {
    max-width: 46px;
    max-height: 46px;
  }

  .enchant-result-level {
    font-size: 16px;
  }

  .enchant-menu-popup {
    top: 42px;
    right: 8px;
    bottom: 14px;

    width: calc(100% - 16px);
    max-width: none;
  }

  .enchant-menu-title {
    font-size: 20px;
  }

  .enchant-menu-option {
    font-size: 16px;
    padding: 14px;
  }

  .enchant-menu-text {
    font-size: 13px;
  }
}

@media screen and (max-width: 360px) {
  .rod-popup-title {
    font-size: 24px;
  }

  .rod-card {
    min-height: 135px;
    font-size: 13px;
  }

  .rod-card img {
    max-width: 70px;
    max-height: 70px;
  }
}

@media screen and (max-width: 340px) {
  .enchant-heading {
    font-size: 26px;
  }

  .enchant-cost-box {
    font-size: 24px;
  }

  .enchant-button {
    font-size: 21px;
  }
}

.enchant-ui {
  width: 100%;
  max-width: 1000px;
  min-height: 575px;
  margin: 0 auto;
  position: relative;

  background: #130b25;
  border: 2px solid #8f5cff;
  box-sizing: border-box;

  font-family: Arial, sans-serif;
  color: #ffffff;

  background-image:
    linear-gradient(
      135deg,
      rgba(140, 80, 255, 0.12) 0%,
      rgba(140, 80, 255, 0.12) 18%,
      transparent 18%,
      transparent 38%,
      rgba(140, 80, 255, 0.08) 38%,
      rgba(140, 80, 255, 0.08) 55%,
      transparent 55%
    );
}

.enchant-topbar {
  position: relative;
  z-index: 1000;

  height: 32px;
  background: #935cff;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 10px;
  box-sizing: border-box;

  font-size: 18px;
  font-weight: bold;
  letter-spacing: 1px;
}

.enchant-topbar-title {
  display: flex;
  align-items: center;
}

.enchant-title-icon {
  margin-right: 8px;
}

.enchant-main {
  display: flex;
  gap: 18px;

  padding: 10px 18px 22px 14px;
  box-sizing: border-box;
}

.enchant-left {
  width: 25%;
  max-width: 230px;
  min-width: 170px;
  flex: 0 0 25%;
}

.enchant-item-slot {
  position: relative;
  overflow: hidden;

  width: 100%;
  height: 0;
  padding-bottom: 100%;

  border: 1px solid #9b6cff;
  background: rgba(55, 30, 90, 0.35);

  box-sizing: border-box;
}

.enchant-right {
  flex: 1;
  min-width: 0;
}

.enchant-heading {
  font-size: 50px;
  font-weight: bold;
  line-height: 1;

  margin: 18px 0 26px 0;
}

.enchant-line {
  width: 100%;
  height: 1px;

  background: #8f5cff;
  margin: 26px 0;
}

.enchant-cost-box {
  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 48px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-fish-points-display {
  max-width: 100%;
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-button {
  width: 55%;
  max-width: 355px;
  min-width: 230px;
  height: 70px;

  margin: 22px auto 0 auto;

  background: #4b347a;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #130b25;
  font-size: 34px;
  font-weight: bold;

  box-sizing: border-box;
}

.enchant-open-picker {
  cursor: pointer;
}

.enchant-item-slot:hover,
.enchant-button:hover {
  outline: 2px solid #9b6cff;
}

/* selected rod image */

.enchant-selected-img {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  align-items: center;
  justify-content: center;
}

.enchant-selected-img img {
  max-width: 75%;
  max-height: 75%;
  width: auto;
  height: auto;
  transform: translateX(20px);
}

.enchant-ui.rod-normal .selected-normal,
.enchant-ui.rod-advanced .selected-advanced,
.enchant-ui.rod-momentum .selected-momentum,
.enchant-ui.rod-pistol .selected-pistol {
  display: flex;
}

/* headings */

.enchant-heading-normal,
.enchant-heading-advanced,
.enchant-heading-momentum,
.enchant-heading-pistol {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-default,
.enchant-ui.rod-advanced .enchant-heading-default,
.enchant-ui.rod-momentum .enchant-heading-default,
.enchant-ui.rod-pistol .enchant-heading-default {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-normal,
.enchant-ui.rod-advanced .enchant-heading-advanced,
.enchant-ui.rod-momentum .enchant-heading-momentum,
.enchant-ui.rod-pistol .enchant-heading-pistol {
  display: block;
}

/* rod popup */

.rod-popup {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 32px;
  bottom: 0;

  z-index: 100;

  align-items: center;
  justify-content: center;

  background: rgba(8, 4, 20, 0.72);
  box-sizing: border-box;
  padding: 24px;
}

.enchant-ui.rod-picker-open .rod-popup {
  display: flex;
}

.rod-popup-panel {
  width: 90%;
  max-width: 760px;

  background: #170d2f;
  border: 2px solid #8f5cff;
  box-shadow: 0 0 24px rgba(143, 92, 255, 0.35);

  padding: 24px;
  box-sizing: border-box;
}

.rod-popup-title {
  text-align: center;
  font-size: 36px;
  font-weight: bold;
  margin-bottom: 22px;
  color: #ffffff;
}

.rod-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}

.rod-card {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  min-height: 190px;
  padding: 14px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  text-align: center;
  box-sizing: border-box;

  cursor: pointer;
}

.rod-card:hover {
  background: #26124d;
  border-color: #9b6cff;
}

.rod-card img {
  max-width: 120px;
  max-height: 120px;
  width: auto;
  height: auto;
}

/* fish points input */

.enchant-points-input {
  width: 90%;
  background: transparent;
  border: none;
  outline: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;
}

.enchant-points-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.fish-points-error {
  border-color: #ff6666;
}

.fish-points-error .enchant-fish-points-display {
  color: #ff8888;
  font-size: 24px;
  font-style: normal;
}

/* enchant result display */

.enchant-display-box {
  width: 100%;
  height: 190px;

  background: rgba(82, 45, 120, 0.55);
  box-sizing: border-box;

  display: block;

  padding: 12px;

  overflow-y: auto;
  overflow-x: hidden;
}

.enchant-info-text {
  min-height: 100%;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #bda2ff;
  font-size: 30px;
  font-weight: bold;
  text-align: center;
}

.enchant-result-grid {
  display: none;
  width: 100%;

  grid-template-columns: repeat(auto-fit, minmax(90px, 1fr));
  gap: 10px;
}

.enchant-result-card {
  min-height: 130px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;

  text-align: center;
  box-sizing: border-box;
  padding: 8px;
}

.enchant-result-card img {
  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;
}

.enchant-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
  line-height: 1;
}

.enchant-result-level {
  color: #bda2ff;
  font-size: 18px;
  font-weight: bold;
}

/* enchant colors */

.enchant-bg-strength {
  background: #8c4368;
}

.enchant-bg-strength-plus {
  background: #871d50;
}

.enchant-bg-momentum {
  background: #5d8084;
}

.enchant-bg-momentum-plus {
  background: #387e73;
}

.enchant-bg-fortune {
  background: #406a98;
}

.enchant-bg-ultra {
  background: #8b4a43;
}

.enchant-bg-less-backfire {
  background: #463b53;
}

.enchant-bg-sharpshooter {
  background: #7f1397;
}

/* menu */

.enchant-menu-button {
  position: relative;
  z-index: 1001;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-width: 32px;
  min-height: 28px;

  color: #ffffff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
  user-select: none;
  pointer-events: auto;

  background: none;
  border: none;
  border-radius: 0;
}

.enchant-menu-button:hover {
  color: #d8c8ff;
}

.enchant-menu-popup {
  display: none;

  position: absolute;
  top: 46px;
  right: 12px;
  bottom: 18px;

  width: 440px;
  max-width: calc(100% - 20px);

  z-index: 1200;

  background: rgba(8, 4, 20, 0.96);
  border: 2px solid #8f5cff;
  border-radius: 16px;

  box-shadow: -8px 0 24px rgba(143, 92, 255, 0.35);

  padding: 18px;
  box-sizing: border-box;

  overflow-y: auto;
  pointer-events: auto;
}

.enchant-ui.enchant-menu-open .enchant-menu-popup {
  display: block;
}

.enchant-menu-panel {
  min-height: 100%;

  display: flex;
  flex-direction: column;

  color: #ffffff;
}

.enchant-menu-title {
  color: #ffffff;
  font-size: 24px;
  font-weight: bold;

  margin-bottom: 12px;
}

.enchant-menu-main,
.enchant-menu-options {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-menu-option {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 18px 16px;

  color: #ffffff;
  font-size: 18px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-option:hover {
  background: #21103f;
  border-color: #8f5cff;
}

.enchant-menu-page {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-main,
.enchant-menu-panel.show-notation .enchant-menu-main {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-page-fish,
.enchant-menu-panel.show-notation .enchant-menu-page-notation {
  display: block;
}

.enchant-menu-text {
  color: #ffffff;
  font-size: 14px;
  line-height: 1.35;
  overflow-wrap: anywhere;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px;
  box-sizing: border-box;
}

.enchant-notation-choice {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px 16px;
  margin-bottom: 10px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-notation-choice:hover {
  background: #140a24;
  border-color: #5b347f;
}

.enchant-notation-choice.notation-active {
  background: #21103f;
  border-color: #8f5cff;
  box-shadow: 0 0 12px rgba(143, 92, 255, 0.45);
}

.enchant-menu-back,
.enchant-menu-close {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 110px;
  min-width: 110px;

  margin-left: auto;
  margin-right: auto;

  padding: 8px 18px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 999px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-back {
  margin-top: 18px;
}

.enchant-menu-close {
  margin-top: 28px;
}

.enchant-menu-close:hover,
.enchant-menu-back:hover {
  background: #6d4ab0;
}

/* fish advisor */

.enchant-advisor-layout {
  display: grid;
  grid-template-columns: 82px 1fr;
  gap: 12px;
  align-items: start;
}

.enchant-advisor-rods {
  width: 82px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.enchant-advisor-rod {
  width: 82px;
  min-height: 88px;

  background: #24113f;
  border: 2px solid #3b245f;
  border-radius: 12px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 4px;

  color: #ffffff;
  font-size: 10px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;

  box-sizing: border-box;
  padding: 8px 5px 5px;
  overflow: hidden;
}

.enchant-advisor-rod:hover,
.enchant-advisor-rod.advisor-rod-active {
  background: #21103f;
  border-color: #8f5cff;
  box-shadow: 0 0 12px rgba(143, 92, 255, 0.45);
}

.enchant-advisor-rod a,
.enchant-advisor-rod .image {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 100%;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;

  line-height: 0;
}

.enchant-advisor-rod img,
.enchant-advisor-rod .mw-file-element {
  display: block;

  max-width: 34px;
  max-height: 34px;
  width: auto;
  height: auto;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;

  margin: 0 auto;
}

.enchant-advisor-rod span {
  display: block;
  max-width: 100%;

  margin-top: 2px;

  line-height: 1.1;
  font-size: 10px;
  text-align: center;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-advisor-right {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-advisor-output {
  order: 1;

  width: 100%;
  min-height: 190px;
  max-height: 260px;

  margin-top: 0;
  padding: 14px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  color: #ffffff;
  font-size: 14px;
  line-height: 1.45;

  overflow-y: auto;
  overflow-x: hidden;

  box-sizing: border-box;
  white-space: normal;
}

.enchant-advisor-box {
  order: 2;

  width: 100%;
  min-height: 74px;

  padding: 12px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;

  box-sizing: border-box;
  cursor: text;

  display: flex;
  align-items: center;

  overflow: hidden;
}

.enchant-advisor-display {
  display: block;
  width: 100%;

  color: #ffffff;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-advisor-input {
  width: 100%;

  background: transparent;
  border: none;
  outline: none;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  font-family: inherit;

  box-sizing: border-box;
}

.enchant-advisor-input::placeholder {
  color: #8f7bbd;
}

.enchant-advisor-check {
  order: 3;

  width: 100%;
  margin-top: 0;
  padding: 12px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 12px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;

  box-sizing: border-box;
}

.enchant-advisor-check:hover {
  background: #6d4ab0;
}

.advisor-result-title {
  font-size: 15px;
  font-weight: bold;
  color: #ffffff;
  margin-bottom: 10px;
}

.advisor-result-row {
  background: #130b25;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 10px;
  margin-bottom: 8px;

  display: flex;
  gap: 8px;
  align-items: center;

  box-sizing: border-box;
}

.advisor-result-row.advisor-best {
  border-color: #8f5cff;
  box-shadow: 0 0 10px rgba(143, 92, 255, 0.35);
}

.advisor-result-row img {
  width: 34px;
  height: 34px;
  object-fit: contain;
  flex: 0 0 34px;
}

.advisor-result-info {
  flex: 1;
  min-width: 0;
}

.advisor-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-level {
  color: #bda2ff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-min {
  color: #8f7bbd;
  font-size: 11px;
  margin-top: 2px;
}

/* responsive */

@media screen and (max-width: 900px) {
  .enchant-ui {
    max-width: 850px;
    min-height: 520px;
  }

  .enchant-main {
    gap: 16px;
    padding: 10px 16px 20px 12px;
  }

  .enchant-left {
    min-width: 155px;
  }

  .enchant-heading {
    font-size: 42px;
    margin: 16px 0 22px 0;
  }

  .enchant-display-box {
    height: 165px;
  }

  .enchant-cost-box {
    height: 80px;
    font-size: 40px;
  }

  .enchant-button {
    height: 62px;
    font-size: 30px;
  }
}

@media screen and (max-width: 650px) {
  .enchant-ui {
    min-height: 0;
  }

  .enchant-main {
    flex-direction: column;
    align-items: center;

    padding: 12px;
    gap: 14px;
  }

  .enchant-left {
    width: 45%;
    max-width: 210px;
    min-width: 140px;
    flex: none;
  }

  .enchant-right {
    width: 100%;
  }

  .enchant-heading {
    text-align: center;
    font-size: 36px;
    margin: 8px 0 18px 0;
  }

  .enchant-display-box {
    height: 145px;
  }

  .enchant-line {
    margin: 20px 0;
  }

  .enchant-cost-box {
    height: 75px;
    font-size: 34px;
  }

  .enchant-button {
    width: 80%;
    min-width: 0;
    height: 58px;
    font-size: 28px;
  }

  .rod-popup {
    padding: 14px;
  }

  .rod-popup-panel {
    width: 100%;
    padding: 16px;
  }

  .rod-popup-title {
    font-size: 28px;
  }

  .rod-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .rod-card {
    min-height: 155px;
    padding: 10px;
  }

  .rod-card img {
    max-width: 85px;
    max-height: 85px;
  }
}

@media screen and (max-width: 520px) {
  .enchant-menu-popup {
    width: calc(100% - 16px);
  }

  .enchant-advisor-layout {
    grid-template-columns: 76px 1fr;
    gap: 10px;
  }

  .enchant-advisor-rods {
    width: 76px;
  }

  .enchant-advisor-rod {
    width: 76px;
    min-height: 82px;
    font-size: 9px;
  }

  .enchant-advisor-rod img,
  .enchant-advisor-rod .mw-file-element {
    max-width: 30px;
    max-height: 30px;
  }

  .enchant-advisor-rod span {
    font-size: 9px;
  }
}

@media screen and (max-width: 420px) {
  .enchant-topbar {
    height: 28px;
    font-size: 15px;
  }

  .enchant-main {
    padding: 10px;
  }

  .enchant-left {
    width: 55%;
    min-width: 120px;
  }

  .enchant-heading {
    font-size: 30px;
  }

  .enchant-display-box {
    height: 120px;
  }

  .enchant-info-text {
    font-size: 22px;
  }

  .enchant-cost-box {
    height: 62px;
    font-size: 28px;
  }

  .enchant-button {
    width: 100%;
    height: 52px;
    font-size: 24px;
  }

  .enchant-result-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .enchant-result-card {
    min-height: 115px;
  }

  .enchant-result-card img {
    max-width: 46px;
    max-height: 46px;
  }

  .enchant-result-level {
    font-size: 16px;
  }

  .enchant-menu-popup {
    top: 42px;
    right: 8px;
    bottom: 14px;

    width: calc(100% - 16px);
    max-width: none;
  }

  .enchant-menu-title {
    font-size: 20px;
  }

  .enchant-menu-option {
    font-size: 16px;
    padding: 14px;
  }

  .enchant-menu-text {
    font-size: 13px;
  }
}

@media screen and (max-width: 360px) {
  .rod-popup-title {
    font-size: 24px;
  }

  .rod-card {
    min-height: 135px;
    font-size: 13px;
  }

  .rod-card img {
    max-width: 70px;
    max-height: 70px;
  }
}

@media screen and (max-width: 340px) {
  .enchant-heading {
    font-size: 26px;
  }

  .enchant-cost-box {
    font-size: 24px;
  }

  .enchant-button {
    font-size: 21px;
  }
}
/* remove image wrapper background */
.enchant-advisor-rod a,
.enchant-advisor-rod .image,
.enchant-advisor-rod span,
.enchant-advisor-rod .mw-file-element,
.enchant-advisor-rod img {
  background: transparent;
  border: none;
  box-shadow: none;
  padding: 0;
}

.enchant-ui {
  width: 100%;
  max-width: 1000px;
  min-height: 575px;
  margin: 0 auto;
  position: relative;

  background: #130b25;
  border: 2px solid #8f5cff;
  box-sizing: border-box;

  font-family: Arial, sans-serif;
  color: #ffffff;

  background-image:
    linear-gradient(
      135deg,
      rgba(140, 80, 255, 0.12) 0%,
      rgba(140, 80, 255, 0.12) 18%,
      transparent 18%,
      transparent 38%,
      rgba(140, 80, 255, 0.08) 38%,
      rgba(140, 80, 255, 0.08) 55%,
      transparent 55%
    );
}

.enchant-topbar {
  position: relative;
  z-index: 1000;

  height: 32px;
  background: #935cff;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 10px;
  box-sizing: border-box;

  font-size: 18px;
  font-weight: bold;
  letter-spacing: 1px;
}

.enchant-topbar-title {
  display: flex;
  align-items: center;
}

.enchant-title-icon {
  margin-right: 8px;
}

.enchant-main {
  display: flex;
  gap: 18px;

  padding: 10px 18px 22px 14px;
  box-sizing: border-box;
}

.enchant-left {
  width: 25%;
  max-width: 230px;
  min-width: 170px;
  flex: 0 0 25%;
}

.enchant-item-slot {
  position: relative;
  overflow: hidden;

  width: 100%;
  height: 0;
  padding-bottom: 100%;

  border: 1px solid #9b6cff;
  background: rgba(55, 30, 90, 0.35);

  box-sizing: border-box;
}

.enchant-right {
  flex: 1;
  min-width: 0;
}

.enchant-heading {
  font-size: 50px;
  font-weight: bold;
  line-height: 1;

  margin: 18px 0 26px 0;
}

.enchant-line {
  width: 100%;
  height: 1px;

  background: #8f5cff;
  margin: 26px 0;
}

.enchant-cost-box {
  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 48px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-fish-points-display {
  max-width: 100%;
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-button {
  width: 55%;
  max-width: 355px;
  min-width: 230px;
  height: 70px;

  margin: 22px auto 0 auto;

  background: #4b347a;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #130b25;
  font-size: 34px;
  font-weight: bold;

  box-sizing: border-box;
}

.enchant-open-picker {
  cursor: pointer;
}

.enchant-item-slot:hover,
.enchant-button:hover {
  outline: 2px solid #9b6cff;
}

/* selected rod image */

.enchant-selected-img {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  align-items: center;
  justify-content: center;
}

.enchant-selected-img img {
  max-width: 75%;
  max-height: 75%;
  width: auto;
  height: auto;
  transform: translateX(20px);
}

.enchant-ui.rod-normal .selected-normal,
.enchant-ui.rod-advanced .selected-advanced,
.enchant-ui.rod-momentum .selected-momentum,
.enchant-ui.rod-pistol .selected-pistol {
  display: flex;
}

/* headings */

.enchant-heading-normal,
.enchant-heading-advanced,
.enchant-heading-momentum,
.enchant-heading-pistol {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-default,
.enchant-ui.rod-advanced .enchant-heading-default,
.enchant-ui.rod-momentum .enchant-heading-default,
.enchant-ui.rod-pistol .enchant-heading-default {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-normal,
.enchant-ui.rod-advanced .enchant-heading-advanced,
.enchant-ui.rod-momentum .enchant-heading-momentum,
.enchant-ui.rod-pistol .enchant-heading-pistol {
  display: block;
}

/* rod popup */

.rod-popup {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 32px;
  bottom: 0;

  z-index: 100;

  align-items: center;
  justify-content: center;

  background: rgba(8, 4, 20, 0.72);
  box-sizing: border-box;
  padding: 24px;
}

.enchant-ui.rod-picker-open .rod-popup {
  display: flex;
}

.rod-popup-panel {
  width: 90%;
  max-width: 760px;

  background: #170d2f;
  border: 2px solid #8f5cff;
  box-shadow: 0 0 24px rgba(143, 92, 255, 0.35);

  padding: 24px;
  box-sizing: border-box;
}

.rod-popup-title {
  text-align: center;
  font-size: 36px;
  font-weight: bold;
  margin-bottom: 22px;
  color: #ffffff;
}

.rod-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}

.rod-card {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  min-height: 190px;
  padding: 14px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  text-align: center;
  box-sizing: border-box;

  cursor: pointer;
}

.rod-card:hover {
  background: #26124d;
  border-color: #9b6cff;
}

.rod-card img {
  max-width: 120px;
  max-height: 120px;
  width: auto;
  height: auto;
}

/* fish points input */

.enchant-points-input {
  width: 90%;
  background: transparent;
  border: none;
  outline: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;
}

.enchant-points-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.fish-points-error {
  border-color: #ff6666;
}

.fish-points-error .enchant-fish-points-display {
  color: #ff8888;
  font-size: 24px;
  font-style: normal;
}

/* enchant result display */

.enchant-display-box {
  width: 100%;
  height: 190px;

  background: rgba(82, 45, 120, 0.55);
  box-sizing: border-box;

  display: block;

  padding: 12px;

  overflow-y: auto;
  overflow-x: hidden;
}

.enchant-info-text {
  min-height: 100%;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #bda2ff;
  font-size: 30px;
  font-weight: bold;
  text-align: center;
}

.enchant-result-grid {
  display: none;
  width: 100%;

  grid-template-columns: repeat(auto-fit, minmax(90px, 1fr));
  gap: 10px;
}

.enchant-result-card {
  min-height: 130px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;

  text-align: center;
  box-sizing: border-box;
  padding: 8px;
}

.enchant-result-card img {
  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;
}

.enchant-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
  line-height: 1;
}

.enchant-result-level {
  color: #bda2ff;
  font-size: 18px;
  font-weight: bold;
}

/* enchant colors */

.enchant-bg-strength {
  background: #8c4368;
}

.enchant-bg-strength-plus {
  background: #871d50;
}

.enchant-bg-momentum {
  background: #5d8084;
}

.enchant-bg-momentum-plus {
  background: #387e73;
}

.enchant-bg-fortune {
  background: #406a98;
}

.enchant-bg-ultra {
  background: #8b4a43;
}

.enchant-bg-less-backfire {
  background: #463b53;
}

.enchant-bg-sharpshooter {
  background: #7f1397;
}

/* menu */

.enchant-menu-button {
  position: relative;
  z-index: 1001;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-width: 32px;
  min-height: 28px;

  color: #ffffff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
  user-select: none;
  pointer-events: auto;

  background: none;
  border: none;
  border-radius: 0;
}

.enchant-menu-button:hover {
  color: #d8c8ff;
}

.enchant-menu-popup {
  display: none;

  position: absolute;
  top: 46px;
  right: 12px;
  bottom: 18px;

  width: 440px;
  max-width: calc(100% - 20px);

  z-index: 1200;

  background: rgba(8, 4, 20, 0.96);
  border: 2px solid #8f5cff;
  border-radius: 16px;

  box-shadow: -8px 0 24px rgba(143, 92, 255, 0.35);

  padding: 18px;
  box-sizing: border-box;

  overflow-y: auto;
  pointer-events: auto;
}

.enchant-ui.enchant-menu-open .enchant-menu-popup {
  display: block;
}

.enchant-menu-panel {
  min-height: 100%;

  display: flex;
  flex-direction: column;

  color: #ffffff;
}

.enchant-menu-title {
  color: #ffffff;
  font-size: 24px;
  font-weight: bold;

  margin-bottom: 12px;
}

.enchant-menu-main,
.enchant-menu-options {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-menu-option {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 18px 16px;

  color: #ffffff;
  font-size: 18px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-option:hover {
  background: #21103f;
  border-color: #8f5cff;
}

.enchant-menu-page {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-main,
.enchant-menu-panel.show-notation .enchant-menu-main {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-page-fish,
.enchant-menu-panel.show-notation .enchant-menu-page-notation {
  display: block;
}

.enchant-menu-text {
  color: #ffffff;
  font-size: 14px;
  line-height: 1.35;
  overflow-wrap: anywhere;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px;
  box-sizing: border-box;
}

.enchant-notation-choice {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px 16px;
  margin-bottom: 10px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-notation-choice:hover {
  background: #140a24;
  border-color: #5b347f;
}

.enchant-notation-choice.notation-active {
  background: #21103f;
  border-color: #8f5cff;
  box-shadow: 0 0 12px rgba(143, 92, 255, 0.45);
}

.enchant-menu-back,
.enchant-menu-close {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 110px;
  min-width: 110px;

  margin-left: auto;
  margin-right: auto;

  padding: 8px 18px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 999px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-back {
  margin-top: 18px;
}

.enchant-menu-close {
  margin-top: 28px;
}

.enchant-menu-close:hover,
.enchant-menu-back:hover {
  background: #6d4ab0;
}

/* fish advisor */

.enchant-advisor-layout {
  display: grid;
  grid-template-columns: 82px 1fr;
  gap: 12px;
  align-items: start;
}

.enchant-advisor-rods {
  width: 82px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.enchant-advisor-rod {
  width: 82px;
  min-height: 88px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 4px;

  color: #ffffff;
  font-size: 10px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;

  box-sizing: border-box;
  padding: 8px 5px 5px;
  overflow: hidden;
}

.enchant-advisor-rod:hover,
.enchant-advisor-rod.advisor-rod-active {
  background: #0b0618;
  border-color: #8f5cff;
  box-shadow: 0 0 12px rgba(143, 92, 255, 0.45);
}

.enchant-advisor-rod a,
.enchant-advisor-rod .image {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 100%;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;

  line-height: 0;
}

.enchant-advisor-rod img,
.enchant-advisor-rod .mw-file-element {
  display: block;

  max-width: 34px;
  max-height: 34px;
  width: auto;
  height: auto;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;

  margin: 0 auto;
}

.enchant-advisor-rod span {
  display: block;
  max-width: 100%;

  margin-top: 2px;

  line-height: 1.1;
  font-size: 10px;
  text-align: center;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-advisor-right {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-advisor-output {
  order: 1;

  width: 100%;
  min-height: 190px;
  max-height: 260px;

  margin-top: 0;
  padding: 14px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  color: #ffffff;
  font-size: 14px;
  line-height: 1.45;

  overflow-y: auto;
  overflow-x: hidden;

  box-sizing: border-box;
  white-space: normal;
}

.enchant-advisor-box {
  order: 2;

  width: 100%;
  min-height: 74px;

  padding: 12px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;

  box-sizing: border-box;
  cursor: text;

  display: flex;
  align-items: center;

  overflow: hidden;
}

.enchant-advisor-display {
  display: block;
  width: 100%;

  color: #ffffff;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-advisor-input {
  width: 100%;

  background: transparent;
  border: none;
  outline: none;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  font-family: inherit;

  box-sizing: border-box;
}

.enchant-advisor-input::placeholder {
  color: #8f7bbd;
}

.enchant-advisor-check {
  order: 3;

  width: 100%;
  margin-top: 0;
  padding: 12px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 12px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;

  box-sizing: border-box;
}

.enchant-advisor-check:hover {
  background: #6d4ab0;
}

.advisor-result-title {
  font-size: 15px;
  font-weight: bold;
  color: #ffffff;
  margin-bottom: 10px;
}

.advisor-result-row {
  background: #130b25;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 10px;
  margin-bottom: 8px;

  display: flex;
  gap: 8px;
  align-items: center;

  box-sizing: border-box;
}

.advisor-result-row.advisor-best {
  border-color: #8f5cff;
  box-shadow: 0 0 10px rgba(143, 92, 255, 0.35);
}

.advisor-result-row img {
  width: 34px;
  height: 34px;
  object-fit: contain;
  flex: 0 0 34px;
}

.advisor-result-info {
  flex: 1;
  min-width: 0;
}

.advisor-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-level {
  color: #bda2ff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-min {
  color: #8f7bbd;
  font-size: 11px;
  margin-top: 2px;
}

/* responsive */

@media screen and (max-width: 900px) {
  .enchant-ui {
    max-width: 850px;
    min-height: 520px;
  }

  .enchant-main {
    gap: 16px;
    padding: 10px 16px 20px 12px;
  }

  .enchant-left {
    min-width: 155px;
  }

  .enchant-heading {
    font-size: 42px;
    margin: 16px 0 22px 0;
  }

  .enchant-display-box {
    height: 165px;
  }

  .enchant-cost-box {
    height: 80px;
    font-size: 40px;
  }

  .enchant-button {
    height: 62px;
    font-size: 30px;
  }
}

@media screen and (max-width: 650px) {
  .enchant-ui {
    min-height: 0;
  }

  .enchant-main {
    flex-direction: column;
    align-items: center;

    padding: 12px;
    gap: 14px;
  }

  .enchant-left {
    width: 45%;
    max-width: 210px;
    min-width: 140px;
    flex: none;
  }

  .enchant-right {
    width: 100%;
  }

  .enchant-heading {
    text-align: center;
    font-size: 36px;
    margin: 8px 0 18px 0;
  }

  .enchant-display-box {
    height: 145px;
  }

  .enchant-line {
    margin: 20px 0;
  }

  .enchant-cost-box {
    height: 75px;
    font-size: 34px;
  }

  .enchant-button {
    width: 80%;
    min-width: 0;
    height: 58px;
    font-size: 28px;
  }

  .rod-popup {
    padding: 14px;
  }

  .rod-popup-panel {
    width: 100%;
    padding: 16px;
  }

  .rod-popup-title {
    font-size: 28px;
  }

  .rod-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .rod-card {
    min-height: 155px;
    padding: 10px;
  }

  .rod-card img {
    max-width: 85px;
    max-height: 85px;
  }
}

@media screen and (max-width: 520px) {
  .enchant-menu-popup {
    width: calc(100% - 16px);
  }

  .enchant-advisor-layout {
    grid-template-columns: 76px 1fr;
    gap: 10px;
  }

  .enchant-advisor-rods {
    width: 76px;
  }

  .enchant-advisor-rod {
    width: 76px;
    min-height: 82px;
    font-size: 9px;
  }

  .enchant-advisor-rod img,
  .enchant-advisor-rod .mw-file-element {
    max-width: 30px;
    max-height: 30px;
  }

  .enchant-advisor-rod span {
    font-size: 9px;
  }
}

@media screen and (max-width: 420px) {
  .enchant-topbar {
    height: 28px;
    font-size: 15px;
  }

  .enchant-main {
    padding: 10px;
  }

  .enchant-left {
    width: 55%;
    min-width: 120px;
  }

  .enchant-heading {
    font-size: 30px;
  }

  .enchant-display-box {
    height: 120px;
  }

  .enchant-info-text {
    font-size: 22px;
  }

  .enchant-cost-box {
    height: 62px;
    font-size: 28px;
  }

  .enchant-button {
    width: 100%;
    height: 52px;
    font-size: 24px;
  }

  .enchant-result-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .enchant-result-card {
    min-height: 115px;
  }

  .enchant-result-card img {
    max-width: 46px;
    max-height: 46px;
  }

  .enchant-result-level {
    font-size: 16px;
  }

  .enchant-menu-popup {
    top: 42px;
    right: 8px;
    bottom: 14px;

    width: calc(100% - 16px);
    max-width: none;
  }

  .enchant-menu-title {
    font-size: 20px;
  }

  .enchant-menu-option {
    font-size: 16px;
    padding: 14px;
  }

  .enchant-menu-text {
    font-size: 13px;
  }
}

@media screen and (max-width: 360px) {
  .rod-popup-title {
    font-size: 24px;
  }

  .rod-card {
    min-height: 135px;
    font-size: 13px;
  }

  .rod-card img {
    max-width: 70px;
    max-height: 70px;
  }
}

@media screen and (max-width: 340px) {
  .enchant-heading {
    font-size: 26px;
  }

  .enchant-cost-box {
    font-size: 24px;
  }

  .enchant-button {
    font-size: 21px;
  }
}

.enchant-ui {
  width: 100%;
  max-width: 1000px;
  min-height: 575px;
  margin: 0 auto;
  position: relative;

  background: #130b25;
  border: 2px solid #8f5cff;
  box-sizing: border-box;

  font-family: Arial, sans-serif;
  color: #ffffff;

  background-image:
    linear-gradient(
      135deg,
      rgba(140, 80, 255, 0.12) 0%,
      rgba(140, 80, 255, 0.12) 18%,
      transparent 18%,
      transparent 38%,
      rgba(140, 80, 255, 0.08) 38%,
      rgba(140, 80, 255, 0.08) 55%,
      transparent 55%
    );
}

.enchant-topbar {
  position: relative;
  z-index: 1000;

  height: 32px;
  background: #935cff;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 10px;
  box-sizing: border-box;

  font-size: 18px;
  font-weight: bold;
  letter-spacing: 1px;
}

.enchant-topbar-title {
  display: flex;
  align-items: center;
}

.enchant-title-icon {
  margin-right: 8px;
}

.enchant-main {
  display: flex;
  gap: 18px;

  padding: 10px 18px 22px 14px;
  box-sizing: border-box;
}

.enchant-left {
  width: 25%;
  max-width: 230px;
  min-width: 170px;
  flex: 0 0 25%;
}

.enchant-item-slot {
  position: relative;
  overflow: hidden;

  width: 100%;
  height: 0;
  padding-bottom: 100%;

  border: 1px solid #9b6cff;
  background: rgba(55, 30, 90, 0.35);

  box-sizing: border-box;
}

.enchant-right {
  flex: 1;
  min-width: 0;
}

.enchant-heading {
  font-size: 50px;
  font-weight: bold;
  line-height: 1;

  margin: 18px 0 26px 0;
}

.enchant-line {
  width: 100%;
  height: 1px;

  background: #8f5cff;
  margin: 26px 0;
}

.enchant-cost-box {
  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 48px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-fish-points-display {
  max-width: 100%;
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-button {
  width: 55%;
  max-width: 355px;
  min-width: 230px;
  height: 70px;

  margin: 22px auto 0 auto;

  background: #4b347a;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #130b25;
  font-size: 34px;
  font-weight: bold;

  box-sizing: border-box;
}

.enchant-open-picker {
  cursor: pointer;
}

.enchant-item-slot:hover,
.enchant-button:hover {
  outline: 2px solid #9b6cff;
}

/* selected rod image */

.enchant-selected-img {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  align-items: center;
  justify-content: center;
}

.enchant-selected-img img {
  max-width: 75%;
  max-height: 75%;
  width: auto;
  height: auto;
  transform: translateX(20px);
}

.enchant-ui.rod-normal .selected-normal,
.enchant-ui.rod-advanced .selected-advanced,
.enchant-ui.rod-momentum .selected-momentum,
.enchant-ui.rod-pistol .selected-pistol {
  display: flex;
}

/* headings */

.enchant-heading-normal,
.enchant-heading-advanced,
.enchant-heading-momentum,
.enchant-heading-pistol {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-default,
.enchant-ui.rod-advanced .enchant-heading-default,
.enchant-ui.rod-momentum .enchant-heading-default,
.enchant-ui.rod-pistol .enchant-heading-default {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-normal,
.enchant-ui.rod-advanced .enchant-heading-advanced,
.enchant-ui.rod-momentum .enchant-heading-momentum,
.enchant-ui.rod-pistol .enchant-heading-pistol {
  display: block;
}

/* rod popup */

.rod-popup {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 32px;
  bottom: 0;

  z-index: 100;

  align-items: center;
  justify-content: center;

  background: rgba(8, 4, 20, 0.72);
  box-sizing: border-box;
  padding: 24px;
}

.enchant-ui.rod-picker-open .rod-popup {
  display: flex;
}

.rod-popup-panel {
  width: 90%;
  max-width: 760px;

  background: #170d2f;
  border: 2px solid #8f5cff;
  box-shadow: 0 0 24px rgba(143, 92, 255, 0.35);

  padding: 24px;
  box-sizing: border-box;
}

.rod-popup-title {
  text-align: center;
  font-size: 36px;
  font-weight: bold;
  margin-bottom: 22px;
  color: #ffffff;
}

.rod-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}

.rod-card {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  min-height: 190px;
  padding: 14px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  text-align: center;
  box-sizing: border-box;

  cursor: pointer;
}

.rod-card:hover {
  background: #26124d;
  border-color: #9b6cff;
}

.rod-card img {
  max-width: 120px;
  max-height: 120px;
  width: auto;
  height: auto;
}

/* fish points input */

.enchant-points-input {
  width: 90%;
  background: transparent;
  border: none;
  outline: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;
}

.enchant-points-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.fish-points-error {
  border-color: #ff6666;
}

.fish-points-error .enchant-fish-points-display {
  color: #ff8888;
  font-size: 24px;
  font-style: normal;
}

/* enchant result display */

.enchant-display-box {
  width: 100%;
  height: 190px;

  background: rgba(82, 45, 120, 0.55);
  box-sizing: border-box;

  display: block;

  padding: 12px;

  overflow-y: auto;
  overflow-x: hidden;
}

.enchant-info-text {
  min-height: 100%;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #bda2ff;
  font-size: 30px;
  font-weight: bold;
  text-align: center;
}

.enchant-result-grid {
  display: none;
  width: 100%;

  grid-template-columns: repeat(auto-fit, minmax(90px, 1fr));
  gap: 10px;
}

.enchant-result-card {
  min-height: 130px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;

  text-align: center;
  box-sizing: border-box;
  padding: 8px;
}

.enchant-result-card img {
  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;
}

.enchant-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
  line-height: 1;
}

.enchant-result-level {
  color: #bda2ff;
  font-size: 18px;
  font-weight: bold;
}

/* enchant colors */

.enchant-bg-strength {
  background: #8c4368;
}

.enchant-bg-strength-plus {
  background: #871d50;
}

.enchant-bg-momentum {
  background: #5d8084;
}

.enchant-bg-momentum-plus {
  background: #387e73;
}

.enchant-bg-fortune {
  background: #406a98;
}

.enchant-bg-ultra {
  background: #8b4a43;
}

.enchant-bg-less-backfire {
  background: #463b53;
}

.enchant-bg-sharpshooter {
  background: #7f1397;
}

/* menu */

.enchant-menu-button {
  position: relative;
  z-index: 1001;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-width: 32px;
  min-height: 28px;

  color: #ffffff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
  user-select: none;
  pointer-events: auto;

  background: none;
  border: none;
  border-radius: 0;
}

.enchant-menu-button:hover {
  color: #d8c8ff;
}

.enchant-menu-popup {
  display: none;

  position: absolute;
  top: 46px;
  right: 12px;
  bottom: 18px;

  width: 440px;
  max-width: calc(100% - 20px);

  z-index: 1200;

  background: rgba(8, 4, 20, 0.96);
  border: 2px solid #8f5cff;
  border-radius: 16px;

  box-shadow: -8px 0 24px rgba(143, 92, 255, 0.35);

  padding: 18px;
  box-sizing: border-box;

  overflow-y: auto;
  pointer-events: auto;
}

.enchant-ui.enchant-menu-open .enchant-menu-popup {
  display: block;
}

.enchant-menu-panel {
  min-height: 100%;

  display: flex;
  flex-direction: column;

  color: #ffffff;
}

.enchant-menu-title {
  color: #ffffff;
  font-size: 24px;
  font-weight: bold;

  margin-bottom: 12px;
}

.enchant-menu-main,
.enchant-menu-options {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-menu-option {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 18px 16px;

  color: #ffffff;
  font-size: 18px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-option:hover {
  background: #21103f;
  border-color: #8f5cff;
}

.enchant-menu-page {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-main,
.enchant-menu-panel.show-notation .enchant-menu-main {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-page-fish,
.enchant-menu-panel.show-notation .enchant-menu-page-notation {
  display: block;
}

.enchant-menu-text {
  color: #ffffff;
  font-size: 14px;
  line-height: 1.35;
  overflow-wrap: anywhere;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px;
  box-sizing: border-box;
}

.enchant-notation-choice {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px 16px;
  margin-bottom: 10px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-notation-choice:hover {
  background: #140a24;
  border-color: #5b347f;
}

.enchant-notation-choice.notation-active {
  background: #21103f;
  border-color: #8f5cff;
  box-shadow: 0 0 12px rgba(143, 92, 255, 0.45);
}

.enchant-menu-back,
.enchant-menu-close {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 110px;
  min-width: 110px;

  margin-left: auto;
  margin-right: auto;

  padding: 8px 18px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 999px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-back {
  margin-top: 18px;
}

.enchant-menu-close {
  margin-top: 28px;
}

.enchant-menu-close:hover,
.enchant-menu-back:hover {
  background: #6d4ab0;
}

/* fish advisor */

.enchant-advisor-layout {
  display: grid;
  grid-template-columns: 82px 1fr;
  gap: 12px;
  align-items: start;
}

.enchant-advisor-rods {
  width: 82px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.enchant-advisor-rod {
  width: 82px;
  min-height: 88px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 4px;

  color: #ffffff;
  font-size: 10px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;

  box-sizing: border-box;
  padding: 8px 5px 5px;
  overflow: hidden;
}

.enchant-advisor-rod:hover,
.enchant-advisor-rod.advisor-rod-active {
  background: #0b0618;
  border-color: #8f5cff;
  box-shadow: 0 0 12px rgba(143, 92, 255, 0.45);
}

.enchant-advisor-rod a,
.enchant-advisor-rod .image {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 100%;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;

  line-height: 0;
}

.enchant-advisor-rod img,
.enchant-advisor-rod .mw-file-element {
  display: block;

  max-width: 34px;
  max-height: 34px;
  width: auto;
  height: auto;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;

  margin: 0 auto;
}

.enchant-advisor-rod span {
  display: block;
  max-width: 100%;

  margin-top: 2px;

  line-height: 1.1;
  font-size: 10px;
  text-align: center;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-advisor-right {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-advisor-output {
  order: 1;

  width: 100%;
  min-height: 190px;
  max-height: 260px;

  margin-top: 0;
  padding: 14px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  color: #ffffff;
  font-size: 14px;
  line-height: 1.45;

  overflow-y: auto;
  overflow-x: hidden;

  box-sizing: border-box;
  white-space: normal;
}

.enchant-advisor-box {
  order: 2;

  width: 100%;
  min-height: 74px;

  padding: 12px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;

  box-sizing: border-box;
  cursor: text;

  display: flex;
  align-items: center;

  overflow: hidden;
}

.enchant-advisor-display {
  display: block;
  width: 100%;

  color: #ffffff;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-advisor-input {
  width: 100%;

  background: transparent;
  border: none;
  outline: none;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  font-family: inherit;

  box-sizing: border-box;
}

.enchant-advisor-input::placeholder {
  color: #8f7bbd;
}

.enchant-advisor-check {
  order: 3;

  width: 100%;
  margin-top: 0;
  padding: 12px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 12px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;

  box-sizing: border-box;
}

.enchant-advisor-check:hover {
  background: #6d4ab0;
}

.advisor-result-title {
  font-size: 15px;
  font-weight: bold;
  color: #ffffff;
  margin-bottom: 10px;
}

.advisor-result-row {
  background: #130b25;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 10px;
  margin-bottom: 8px;

  display: flex;
  gap: 8px;
  align-items: center;

  box-sizing: border-box;
}

.advisor-result-row.advisor-best {
  border-color: #8f5cff;
  box-shadow: 0 0 10px rgba(143, 92, 255, 0.35);
}

.advisor-result-row img {
  width: 34px;
  height: 34px;
  object-fit: contain;
  flex: 0 0 34px;
}

.advisor-result-info {
  flex: 1;
  min-width: 0;
}

.advisor-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-level {
  color: #bda2ff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-min {
  color: #8f7bbd;
  font-size: 11px;
  margin-top: 2px;
}

/* responsive */

@media screen and (max-width: 900px) {
  .enchant-ui {
    max-width: 850px;
    min-height: 520px;
  }

  .enchant-main {
    gap: 16px;
    padding: 10px 16px 20px 12px;
  }

  .enchant-left {
    min-width: 155px;
  }

  .enchant-heading {
    font-size: 42px;
    margin: 16px 0 22px 0;
  }

  .enchant-display-box {
    height: 165px;
  }

  .enchant-cost-box {
    height: 80px;
    font-size: 40px;
  }

  .enchant-button {
    height: 62px;
    font-size: 30px;
  }
}

@media screen and (max-width: 650px) {
  .enchant-ui {
    min-height: 0;
  }

  .enchant-main {
    flex-direction: column;
    align-items: center;

    padding: 12px;
    gap: 14px;
  }

  .enchant-left {
    width: 45%;
    max-width: 210px;
    min-width: 140px;
    flex: none;
  }

  .enchant-right {
    width: 100%;
  }

  .enchant-heading {
    text-align: center;
    font-size: 36px;
    margin: 8px 0 18px 0;
  }

  .enchant-display-box {
    height: 145px;
  }

  .enchant-line {
    margin: 20px 0;
  }

  .enchant-cost-box {
    height: 75px;
    font-size: 34px;
  }

  .enchant-button {
    width: 80%;
    min-width: 0;
    height: 58px;
    font-size: 28px;
  }

  .rod-popup {
    padding: 14px;
  }

  .rod-popup-panel {
    width: 100%;
    padding: 16px;
  }

  .rod-popup-title {
    font-size: 28px;
  }

  .rod-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .rod-card {
    min-height: 155px;
    padding: 10px;
  }

  .rod-card img {
    max-width: 85px;
    max-height: 85px;
  }
}

@media screen and (max-width: 520px) {
  .enchant-menu-popup {
    width: calc(100% - 16px);
  }

  .enchant-advisor-layout {
    grid-template-columns: 76px 1fr;
    gap: 10px;
  }

  .enchant-advisor-rods {
    width: 76px;
  }

  .enchant-advisor-rod {
    width: 76px;
    min-height: 82px;
    font-size: 9px;
  }

  .enchant-advisor-rod img,
  .enchant-advisor-rod .mw-file-element {
    max-width: 30px;
    max-height: 30px;
  }

  .enchant-advisor-rod span {
    font-size: 9px;
  }
}

@media screen and (max-width: 420px) {
  .enchant-topbar {
    height: 28px;
    font-size: 15px;
  }

  .enchant-main {
    padding: 10px;
  }

  .enchant-left {
    width: 55%;
    min-width: 120px;
  }

  .enchant-heading {
    font-size: 30px;
  }

  .enchant-display-box {
    height: 120px;
  }

  .enchant-info-text {
    font-size: 22px;
  }

  .enchant-cost-box {
    height: 62px;
    font-size: 28px;
  }

  .enchant-button {
    width: 100%;
    height: 52px;
    font-size: 24px;
  }

  .enchant-result-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .enchant-result-card {
    min-height: 115px;
  }

  .enchant-result-card img {
    max-width: 46px;
    max-height: 46px;
  }

  .enchant-result-level {
    font-size: 16px;
  }

  .enchant-menu-popup {
    top: 42px;
    right: 8px;
    bottom: 14px;

    width: calc(100% - 16px);
    max-width: none;
  }

  .enchant-menu-title {
    font-size: 20px;
  }

  .enchant-menu-option {
    font-size: 16px;
    padding: 14px;
  }

  .enchant-menu-text {
    font-size: 13px;
  }
}

@media screen and (max-width: 360px) {
  .rod-popup-title {
    font-size: 24px;
  }

  .rod-card {
    min-height: 135px;
    font-size: 13px;
  }

  .rod-card img {
    max-width: 70px;
    max-height: 70px;
  }
}

@media screen and (max-width: 340px) {
  .enchant-heading {
    font-size: 26px;
  }

  .enchant-cost-box {
    font-size: 24px;
  }

  .enchant-button {
    font-size: 21px;
  }
}
.enchant-advisor-rod a,
.enchant-advisor-rod .image,
.enchant-advisor-rod .mw-file-description,
.enchant-advisor-rod .mw-default-size,
.enchant-advisor-rod .mw-file-element,
.enchant-advisor-rod img {
  background: transparent;
  border: 0;
  outline: 0;
  box-shadow: none;
  padding: 0;
}

.enchant-ui {
  width: 100%;
  max-width: 1000px;
  min-height: 575px;
  margin: 0 auto;
  position: relative;

  background: #130b25;
  border: 2px solid #8f5cff;
  box-sizing: border-box;

  font-family: Arial, sans-serif;
  color: #ffffff;

  background-image:
    linear-gradient(
      135deg,
      rgba(140, 80, 255, 0.12) 0%,
      rgba(140, 80, 255, 0.12) 18%,
      transparent 18%,
      transparent 38%,
      rgba(140, 80, 255, 0.08) 38%,
      rgba(140, 80, 255, 0.08) 55%,
      transparent 55%
    );
}

.enchant-topbar {
  position: relative;
  z-index: 1000;

  height: 32px;
  background: #935cff;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 10px;
  box-sizing: border-box;

  font-size: 18px;
  font-weight: bold;
  letter-spacing: 1px;
}

.enchant-topbar-title {
  display: flex;
  align-items: center;
}

.enchant-title-icon {
  margin-right: 8px;
}

.enchant-main {
  display: flex;
  gap: 18px;

  padding: 10px 18px 22px 14px;
  box-sizing: border-box;
}

.enchant-left {
  width: 25%;
  max-width: 230px;
  min-width: 170px;
  flex: 0 0 25%;
}

.enchant-item-slot {
  position: relative;
  overflow: hidden;

  width: 100%;
  height: 0;
  padding-bottom: 100%;

  border: 1px solid #9b6cff;
  background: rgba(55, 30, 90, 0.35);

  box-sizing: border-box;
}

.enchant-right {
  flex: 1;
  min-width: 0;
}

.enchant-heading {
  font-size: 50px;
  font-weight: bold;
  line-height: 1;

  margin: 18px 0 26px 0;
}

.enchant-line {
  width: 100%;
  height: 1px;

  background: #8f5cff;
  margin: 26px 0;
}

.enchant-cost-box {
  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 48px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-fish-points-display {
  max-width: 100%;
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-button {
  width: 55%;
  max-width: 355px;
  min-width: 230px;
  height: 70px;

  margin: 22px auto 0 auto;

  background: #4b347a;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #130b25;
  font-size: 34px;
  font-weight: bold;

  box-sizing: border-box;
}

.enchant-open-picker {
  cursor: pointer;
}

.enchant-item-slot:hover,
.enchant-button:hover {
  outline: 2px solid #9b6cff;
}

/* selected rod image */

.enchant-selected-img {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  align-items: center;
  justify-content: center;
}

.enchant-selected-img img {
  max-width: 75%;
  max-height: 75%;
  width: auto;
  height: auto;
  transform: translateX(20px);
}

.enchant-ui.rod-normal .selected-normal,
.enchant-ui.rod-advanced .selected-advanced,
.enchant-ui.rod-momentum .selected-momentum,
.enchant-ui.rod-pistol .selected-pistol {
  display: flex;
}

/* headings */

.enchant-heading-normal,
.enchant-heading-advanced,
.enchant-heading-momentum,
.enchant-heading-pistol {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-default,
.enchant-ui.rod-advanced .enchant-heading-default,
.enchant-ui.rod-momentum .enchant-heading-default,
.enchant-ui.rod-pistol .enchant-heading-default {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-normal,
.enchant-ui.rod-advanced .enchant-heading-advanced,
.enchant-ui.rod-momentum .enchant-heading-momentum,
.enchant-ui.rod-pistol .enchant-heading-pistol {
  display: block;
}

/* rod popup */

.rod-popup {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 32px;
  bottom: 0;

  z-index: 100;

  align-items: center;
  justify-content: center;

  background: rgba(8, 4, 20, 0.72);
  box-sizing: border-box;
  padding: 24px;
}

.enchant-ui.rod-picker-open .rod-popup {
  display: flex;
}

.rod-popup-panel {
  width: 90%;
  max-width: 760px;

  background: #170d2f;
  border: 2px solid #8f5cff;
  box-shadow: 0 0 24px rgba(143, 92, 255, 0.35);

  padding: 24px;
  box-sizing: border-box;
}

.rod-popup-title {
  text-align: center;
  font-size: 36px;
  font-weight: bold;
  margin-bottom: 22px;
  color: #ffffff;
}

.rod-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}

.rod-card {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  min-height: 190px;
  padding: 14px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  text-align: center;
  box-sizing: border-box;

  cursor: pointer;
}

.rod-card:hover {
  background: #26124d;
  border-color: #9b6cff;
}

.rod-card img {
  max-width: 120px;
  max-height: 120px;
  width: auto;
  height: auto;
}

/* fish points input */

.enchant-points-input {
  width: 90%;
  background: transparent;
  border: none;
  outline: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;
}

.enchant-points-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.fish-points-error {
  border-color: #ff6666;
}

.fish-points-error .enchant-fish-points-display {
  color: #ff8888;
  font-size: 24px;
  font-style: normal;
}

/* enchant result display */

.enchant-display-box {
  width: 100%;
  height: 190px;

  background: rgba(82, 45, 120, 0.55);
  box-sizing: border-box;

  display: block;

  padding: 12px;

  overflow-y: auto;
  overflow-x: hidden;
}

.enchant-info-text {
  min-height: 100%;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #bda2ff;
  font-size: 30px;
  font-weight: bold;
  text-align: center;
}

.enchant-result-grid {
  display: none;
  width: 100%;

  grid-template-columns: repeat(auto-fit, minmax(90px, 1fr));
  gap: 10px;
}

.enchant-result-card {
  min-height: 130px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;

  text-align: center;
  box-sizing: border-box;
  padding: 8px;
}

.enchant-result-card img {
  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;
}

.enchant-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
  line-height: 1;
}

.enchant-result-level {
  color: #bda2ff;
  font-size: 18px;
  font-weight: bold;
}

/* enchant colors */

.enchant-bg-strength {
  background: #8c4368;
}

.enchant-bg-strength-plus {
  background: #871d50;
}

.enchant-bg-momentum {
  background: #5d8084;
}

.enchant-bg-momentum-plus {
  background: #387e73;
}

.enchant-bg-fortune {
  background: #406a98;
}

.enchant-bg-ultra {
  background: #8b4a43;
}

.enchant-bg-less-backfire {
  background: #463b53;
}

.enchant-bg-sharpshooter {
  background: #7f1397;
}

/* menu */

.enchant-menu-button {
  position: relative;
  z-index: 1001;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-width: 32px;
  min-height: 28px;

  color: #ffffff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
  user-select: none;
  pointer-events: auto;

  background: none;
  border: none;
  border-radius: 0;
}

.enchant-menu-button:hover {
  color: #d8c8ff;
}

.enchant-menu-popup {
  display: none;

  position: absolute;
  top: 46px;
  right: 12px;
  bottom: 18px;

  width: 440px;
  max-width: calc(100% - 20px);

  z-index: 1200;

  background: rgba(8, 4, 20, 0.96);
  border: 2px solid #8f5cff;
  border-radius: 16px;

  box-shadow: -8px 0 24px rgba(143, 92, 255, 0.35);

  padding: 18px;
  box-sizing: border-box;

  overflow-y: auto;
  pointer-events: auto;
}

.enchant-ui.enchant-menu-open .enchant-menu-popup {
  display: block;
}

.enchant-menu-panel {
  min-height: 100%;

  display: flex;
  flex-direction: column;

  color: #ffffff;
}

.enchant-menu-title {
  color: #ffffff;
  font-size: 24px;
  font-weight: bold;

  margin-bottom: 12px;
}

.enchant-menu-main,
.enchant-menu-options {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-menu-option {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 18px 16px;

  color: #ffffff;
  font-size: 18px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-option:hover {
  background: #21103f;
  border-color: #8f5cff;
}

.enchant-menu-page {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-main,
.enchant-menu-panel.show-notation .enchant-menu-main {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-page-fish,
.enchant-menu-panel.show-notation .enchant-menu-page-notation {
  display: block;
}

.enchant-menu-text {
  color: #ffffff;
  font-size: 14px;
  line-height: 1.35;
  overflow-wrap: anywhere;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px;
  box-sizing: border-box;
}

.enchant-notation-choice {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px 16px;
  margin-bottom: 10px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-notation-choice:hover {
  background: #140a24;
  border-color: #5b347f;
}

.enchant-notation-choice.notation-active {
  background: #21103f;
  border-color: #8f5cff;
  box-shadow: 0 0 12px rgba(143, 92, 255, 0.45);
}

.enchant-menu-back,
.enchant-menu-close {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 110px;
  min-width: 110px;

  margin-left: auto;
  margin-right: auto;

  padding: 8px 18px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 999px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-back {
  margin-top: 18px;
}

.enchant-menu-close {
  margin-top: 28px;
}

.enchant-menu-close:hover,
.enchant-menu-back:hover {
  background: #6d4ab0;
}

/* fish advisor */

.enchant-advisor-layout {
  display: grid;
  grid-template-columns: 82px 1fr;
  gap: 12px;
  align-items: start;
}

.enchant-advisor-rods {
  width: 82px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.enchant-advisor-rod {
  width: 82px;
  min-height: 88px;

  background: transparent;
  border: 2px solid #3b245f;
  border-radius: 12px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 4px;

  color: #ffffff;
  font-size: 10px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;

  box-sizing: border-box;
  padding: 8px 5px 5px;
  overflow: hidden;
}

.enchant-advisor-rod:hover,
.enchant-advisor-rod.advisor-rod-active {
  background: rgba(143, 92, 255, 0.12);
  border-color: #8f5cff;
  box-shadow: 0 0 12px rgba(143, 92, 255, 0.45);
}

.enchant-advisor-rod a,
.enchant-advisor-rod .image {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 100%;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;

  line-height: 0;
}

.enchant-advisor-rod img,
.enchant-advisor-rod .mw-file-element {
  display: block;

  max-width: 34px;
  max-height: 34px;
  width: auto;
  height: auto;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;

  margin: 0 auto;
}

.enchant-advisor-rod span {
  display: block;
  max-width: 100%;

  margin-top: 2px;

  line-height: 1.1;
  font-size: 10px;
  text-align: center;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-advisor-right {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-advisor-output {
  order: 1;

  width: 100%;
  min-height: 190px;
  max-height: 260px;

  margin-top: 0;
  padding: 14px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  color: #ffffff;
  font-size: 14px;
  line-height: 1.45;

  overflow-y: auto;
  overflow-x: hidden;

  box-sizing: border-box;
  white-space: normal;
}

.enchant-advisor-box {
  order: 2;

  width: 100%;
  min-height: 74px;

  padding: 12px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;

  box-sizing: border-box;
  cursor: text;

  display: flex;
  align-items: center;

  overflow: hidden;
}

.enchant-advisor-display {
  display: block;
  width: 100%;

  color: #ffffff;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-advisor-input {
  width: 100%;

  background: transparent;
  border: none;
  outline: none;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  font-family: inherit;

  box-sizing: border-box;
}

.enchant-advisor-input::placeholder {
  color: #8f7bbd;
}

.enchant-advisor-check {
  order: 3;

  width: 100%;
  margin-top: 0;
  padding: 12px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 12px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;

  box-sizing: border-box;
}

.enchant-advisor-check:hover {
  background: #6d4ab0;
}

.advisor-result-title {
  font-size: 15px;
  font-weight: bold;
  color: #ffffff;
  margin-bottom: 10px;
}

.advisor-result-row {
  background: #130b25;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 10px;
  margin-bottom: 8px;

  display: flex;
  gap: 8px;
  align-items: center;

  box-sizing: border-box;
}

.advisor-result-row.advisor-best {
  border-color: #8f5cff;
  box-shadow: 0 0 10px rgba(143, 92, 255, 0.35);
}

.advisor-result-row img {
  width: 34px;
  height: 34px;
  object-fit: contain;
  flex: 0 0 34px;
}

.advisor-result-info {
  flex: 1;
  min-width: 0;
}

.advisor-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-level {
  color: #bda2ff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-min {
  color: #8f7bbd;
  font-size: 11px;
  margin-top: 2px;
}

/* responsive */

@media screen and (max-width: 900px) {
  .enchant-ui {
    max-width: 850px;
    min-height: 520px;
  }

  .enchant-main {
    gap: 16px;
    padding: 10px 16px 20px 12px;
  }

  .enchant-left {
    min-width: 155px;
  }

  .enchant-heading {
    font-size: 42px;
    margin: 16px 0 22px 0;
  }

  .enchant-display-box {
    height: 165px;
  }

  .enchant-cost-box {
    height: 80px;
    font-size: 40px;
  }

  .enchant-button {
    height: 62px;
    font-size: 30px;
  }
}

@media screen and (max-width: 650px) {
  .enchant-ui {
    min-height: 0;
  }

  .enchant-main {
    flex-direction: column;
    align-items: center;

    padding: 12px;
    gap: 14px;
  }

  .enchant-left {
    width: 45%;
    max-width: 210px;
    min-width: 140px;
    flex: none;
  }

  .enchant-right {
    width: 100%;
  }

  .enchant-heading {
    text-align: center;
    font-size: 36px;
    margin: 8px 0 18px 0;
  }

  .enchant-display-box {
    height: 145px;
  }

  .enchant-line {
    margin: 20px 0;
  }

  .enchant-cost-box {
    height: 75px;
    font-size: 34px;
  }

  .enchant-button {
    width: 80%;
    min-width: 0;
    height: 58px;
    font-size: 28px;
  }

  .rod-popup {
    padding: 14px;
  }

  .rod-popup-panel {
    width: 100%;
    padding: 16px;
  }

  .rod-popup-title {
    font-size: 28px;
  }

  .rod-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .rod-card {
    min-height: 155px;
    padding: 10px;
  }

  .rod-card img {
    max-width: 85px;
    max-height: 85px;
  }
}

@media screen and (max-width: 520px) {
  .enchant-menu-popup {
    width: calc(100% - 16px);
  }

  .enchant-advisor-layout {
    grid-template-columns: 76px 1fr;
    gap: 10px;
  }

  .enchant-advisor-rods {
    width: 76px;
  }

  .enchant-advisor-rod {
    width: 76px;
    min-height: 82px;
    font-size: 9px;
  }

  .enchant-advisor-rod img,
  .enchant-advisor-rod .mw-file-element {
    max-width: 30px;
    max-height: 30px;
  }

  .enchant-advisor-rod span {
    font-size: 9px;
  }
}

@media screen and (max-width: 420px) {
  .enchant-topbar {
    height: 28px;
    font-size: 15px;
  }

  .enchant-main {
    padding: 10px;
  }

  .enchant-left {
    width: 55%;
    min-width: 120px;
  }

  .enchant-heading {
    font-size: 30px;
  }

  .enchant-display-box {
    height: 120px;
  }

  .enchant-info-text {
    font-size: 22px;
  }

  .enchant-cost-box {
    height: 62px;
    font-size: 28px;
  }

  .enchant-button {
    width: 100%;
    height: 52px;
    font-size: 24px;
  }

  .enchant-result-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .enchant-result-card {
    min-height: 115px;
  }

  .enchant-result-card img {
    max-width: 46px;
    max-height: 46px;
  }

  .enchant-result-level {
    font-size: 16px;
  }

  .enchant-menu-popup {
    top: 42px;
    right: 8px;
    bottom: 14px;

    width: calc(100% - 16px);
    max-width: none;
  }

  .enchant-menu-title {
    font-size: 20px;
  }

  .enchant-menu-option {
    font-size: 16px;
    padding: 14px;
  }

  .enchant-menu-text {
    font-size: 13px;
  }
}

@media screen and (max-width: 360px) {
  .rod-popup-title {
    font-size: 24px;
  }

  .rod-card {
    min-height: 135px;
    font-size: 13px;
  }

  .rod-card img {
    max-width: 70px;
    max-height: 70px;
  }
}

@media screen and (max-width: 340px) {
  .enchant-heading {
    font-size: 26px;
  }

  .enchant-cost-box {
    font-size: 24px;
  }

  .enchant-button {
    font-size: 21px;
  }
}

.enchant-ui {
  width: 100%;
  max-width: 1000px;
  min-height: 575px;
  margin: 0 auto;
  position: relative;

  background: #130b25;
  border: 2px solid #8f5cff;
  box-sizing: border-box;

  font-family: Arial, sans-serif;
  color: #ffffff;

  background-image:
    linear-gradient(
      135deg,
      rgba(140, 80, 255, 0.12) 0%,
      rgba(140, 80, 255, 0.12) 18%,
      transparent 18%,
      transparent 38%,
      rgba(140, 80, 255, 0.08) 38%,
      rgba(140, 80, 255, 0.08) 55%,
      transparent 55%
    );
}

.enchant-topbar {
  position: relative;
  z-index: 1000;

  height: 32px;
  background: #935cff;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 10px;
  box-sizing: border-box;

  font-size: 18px;
  font-weight: bold;
  letter-spacing: 1px;
}

.enchant-topbar-title {
  display: flex;
  align-items: center;
}

.enchant-title-icon {
  margin-right: 8px;
}

.enchant-main {
  display: flex;
  gap: 18px;

  padding: 10px 18px 22px 14px;
  box-sizing: border-box;
}

.enchant-left {
  width: 25%;
  max-width: 230px;
  min-width: 170px;
  flex: 0 0 25%;
}

.enchant-item-slot {
  position: relative;
  overflow: hidden;

  width: 100%;
  height: 0;
  padding-bottom: 100%;

  border: 1px solid #9b6cff;
  background: rgba(55, 30, 90, 0.35);

  box-sizing: border-box;
}

.enchant-right {
  flex: 1;
  min-width: 0;
}

.enchant-heading {
  font-size: 50px;
  font-weight: bold;
  line-height: 1;

  margin: 18px 0 26px 0;
}

.enchant-line {
  width: 100%;
  height: 1px;

  background: #8f5cff;
  margin: 26px 0;
}

.enchant-cost-box {
  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 48px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-fish-points-display {
  max-width: 100%;
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-button {
  width: 55%;
  max-width: 355px;
  min-width: 230px;
  height: 70px;

  margin: 22px auto 0 auto;

  background: #4b347a;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #130b25;
  font-size: 34px;
  font-weight: bold;

  box-sizing: border-box;
}

.enchant-open-picker {
  cursor: pointer;
}

.enchant-item-slot:hover,
.enchant-button:hover {
  outline: 2px solid #9b6cff;
}

/* selected rod image */

.enchant-selected-img {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  align-items: center;
  justify-content: center;
}

.enchant-selected-img img {
  max-width: 75%;
  max-height: 75%;
  width: auto;
  height: auto;
  transform: translateX(20px);
}

.enchant-ui.rod-normal .selected-normal,
.enchant-ui.rod-advanced .selected-advanced,
.enchant-ui.rod-momentum .selected-momentum,
.enchant-ui.rod-pistol .selected-pistol {
  display: flex;
}

/* headings */

.enchant-heading-normal,
.enchant-heading-advanced,
.enchant-heading-momentum,
.enchant-heading-pistol {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-default,
.enchant-ui.rod-advanced .enchant-heading-default,
.enchant-ui.rod-momentum .enchant-heading-default,
.enchant-ui.rod-pistol .enchant-heading-default {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-normal,
.enchant-ui.rod-advanced .enchant-heading-advanced,
.enchant-ui.rod-momentum .enchant-heading-momentum,
.enchant-ui.rod-pistol .enchant-heading-pistol {
  display: block;
}

/* rod popup */

.rod-popup {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 32px;
  bottom: 0;

  z-index: 100;

  align-items: center;
  justify-content: center;

  background: rgba(8, 4, 20, 0.72);
  box-sizing: border-box;
  padding: 24px;
}

.enchant-ui.rod-picker-open .rod-popup {
  display: flex;
}

.rod-popup-panel {
  width: 90%;
  max-width: 760px;

  background: #170d2f;
  border: 2px solid #8f5cff;
  box-shadow: 0 0 24px rgba(143, 92, 255, 0.35);

  padding: 24px;
  box-sizing: border-box;
}

.rod-popup-title {
  text-align: center;
  font-size: 36px;
  font-weight: bold;
  margin-bottom: 22px;
  color: #ffffff;
}

.rod-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}

.rod-card {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  min-height: 190px;
  padding: 14px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  text-align: center;
  box-sizing: border-box;

  cursor: pointer;
}

.rod-card:hover {
  background: #26124d;
  border-color: #9b6cff;
}

.rod-card img {
  max-width: 120px;
  max-height: 120px;
  width: auto;
  height: auto;
}

/* fish points input */

.enchant-points-input {
  width: 90%;
  background: transparent;
  border: none;
  outline: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;
}

.enchant-points-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.fish-points-error {
  border-color: #ff6666;
}

.fish-points-error .enchant-fish-points-display {
  color: #ff8888;
  font-size: 24px;
  font-style: normal;
}

/* enchant result display */

.enchant-display-box {
  width: 100%;
  height: 190px;

  background: rgba(82, 45, 120, 0.55);
  box-sizing: border-box;

  display: block;

  padding: 12px;

  overflow-y: auto;
  overflow-x: hidden;
}

.enchant-info-text {
  min-height: 100%;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #bda2ff;
  font-size: 30px;
  font-weight: bold;
  text-align: center;
}

.enchant-result-grid {
  display: none;
  width: 100%;

  grid-template-columns: repeat(auto-fit, minmax(90px, 1fr));
  gap: 10px;
}

.enchant-result-card {
  min-height: 130px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;

  text-align: center;
  box-sizing: border-box;
  padding: 8px;
}

.enchant-result-card img {
  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;
}

.enchant-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
  line-height: 1;
}

.enchant-result-level {
  color: #bda2ff;
  font-size: 18px;
  font-weight: bold;
}

/* enchant colors */

.enchant-bg-strength {
  background: #8c4368;
}

.enchant-bg-strength-plus {
  background: #871d50;
}

.enchant-bg-momentum {
  background: #5d8084;
}

.enchant-bg-momentum-plus {
  background: #387e73;
}

.enchant-bg-fortune {
  background: #406a98;
}

.enchant-bg-ultra {
  background: #8b4a43;
}

.enchant-bg-less-backfire {
  background: #463b53;
}

.enchant-bg-sharpshooter {
  background: #7f1397;
}

/* menu */

.enchant-menu-button {
  position: relative;
  z-index: 1001;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-width: 32px;
  min-height: 28px;

  color: #ffffff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
  user-select: none;
  pointer-events: auto;

  background: none;
  border: none;
  border-radius: 0;
}

.enchant-menu-button:hover {
  color: #d8c8ff;
}

.enchant-menu-popup {
  display: none;

  position: absolute;
  top: 46px;
  right: 12px;
  bottom: 18px;

  width: 440px;
  max-width: calc(100% - 20px);

  z-index: 1200;

  background: rgba(8, 4, 20, 0.96);
  border: 2px solid #8f5cff;
  border-radius: 16px;

  box-shadow: -8px 0 24px rgba(143, 92, 255, 0.35);

  padding: 18px;
  box-sizing: border-box;

  overflow-y: auto;
  pointer-events: auto;
}

.enchant-ui.enchant-menu-open .enchant-menu-popup {
  display: block;
}

.enchant-menu-panel {
  min-height: 100%;

  display: flex;
  flex-direction: column;

  color: #ffffff;
}

.enchant-menu-title {
  color: #ffffff;
  font-size: 24px;
  font-weight: bold;

  margin-bottom: 12px;
}

.enchant-menu-main,
.enchant-menu-options {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-menu-option {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 18px 16px;

  color: #ffffff;
  font-size: 18px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-option:hover {
  background: #21103f;
  border-color: #8f5cff;
}

.enchant-menu-page {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-main,
.enchant-menu-panel.show-notation .enchant-menu-main {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-page-fish,
.enchant-menu-panel.show-notation .enchant-menu-page-notation {
  display: block;
}

.enchant-menu-text {
  color: #ffffff;
  font-size: 14px;
  line-height: 1.35;
  overflow-wrap: anywhere;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px;
  box-sizing: border-box;
}

.enchant-notation-choice {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px 16px;
  margin-bottom: 10px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-notation-choice:hover {
  background: #140a24;
  border-color: #5b347f;
}

.enchant-notation-choice.notation-active {
  background: #21103f;
  border-color: #8f5cff;
  box-shadow: 0 0 12px rgba(143, 92, 255, 0.45);
}

.enchant-menu-back,
.enchant-menu-close {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 110px;
  min-width: 110px;

  margin-left: auto;
  margin-right: auto;

  padding: 8px 18px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 999px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-back {
  margin-top: 18px;
}

.enchant-menu-close {
  margin-top: 28px;
}

.enchant-menu-close:hover,
.enchant-menu-back:hover {
  background: #6d4ab0;
}

/* fish advisor */

.enchant-advisor-layout {
  display: grid;
  grid-template-columns: 82px 1fr;
  gap: 12px;
  align-items: start;
}

.enchant-advisor-rods {
  width: 82px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.enchant-advisor-rod {
  width: 82px;
  min-height: 88px;

  background: transparent;
  border: 2px solid #3b245f;
  border-radius: 12px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 4px;

  color: #ffffff;
  font-size: 10px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;

  box-sizing: border-box;
  padding: 8px 5px 5px;
  overflow: hidden;
}

.enchant-advisor-rod:hover,
.enchant-advisor-rod.advisor-rod-active {
  background: rgba(143, 92, 255, 0.12);
  border-color: #8f5cff;
  box-shadow: 0 0 12px rgba(143, 92, 255, 0.45);
}

.enchant-advisor-rod a,
.enchant-advisor-rod .image {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 100%;

  background: transparent;
  border: none;
  box-shadow: none;
  padding: 0;
  margin: 0;

  line-height: 0;
}

.enchant-advisor-rod img,
.enchant-advisor-rod .mw-file-element {
  display: block;

  max-width: 34px;
  max-height: 34px;
  width: auto;
  height: auto;

  background: transparent;
  border: none;
  box-shadow: none;

  margin: 0 auto;
}

.enchant-advisor-rod span {
  display: block;
  max-width: 100%;

  margin-top: 2px;

  line-height: 1.1;
  font-size: 10px;
  text-align: center;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-advisor-right {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-advisor-output {
  order: 1;

  width: 100%;
  min-height: 190px;
  max-height: 260px;

  margin-top: 0;
  padding: 14px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  color: #ffffff;
  font-size: 14px;
  line-height: 1.45;

  overflow-y: auto;
  overflow-x: hidden;

  box-sizing: border-box;
  white-space: normal;
}

.enchant-advisor-box {
  order: 2;

  width: 100%;
  min-height: 74px;

  padding: 12px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;

  box-sizing: border-box;
  cursor: text;

  display: flex;
  align-items: center;

  overflow: hidden;
}

.enchant-advisor-display {
  display: block;
  width: 100%;

  color: #ffffff;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-advisor-input {
  display: block;

  width: 100%;
  height: 40px;

  margin: 0;
  padding: 0;

  background: transparent;
  border: 0;
  outline: 0;
  box-shadow: none;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  font-family: Arial, sans-serif;

  line-height: 40px;

  overflow: hidden;
  resize: none;

  box-sizing: border-box;
}

.enchant-advisor-input::placeholder {
  color: #8f7bbd;
  opacity: 1;
}

.enchant-advisor-check {
  order: 3;

  width: 100%;
  margin-top: 0;
  padding: 12px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 12px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;

  box-sizing: border-box;
}

.enchant-advisor-check:hover {
  background: #6d4ab0;
}

.advisor-result-title {
  font-size: 15px;
  font-weight: bold;
  color: #ffffff;
  margin-bottom: 10px;
}

.advisor-result-row {
  background: #130b25;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 10px;
  margin-bottom: 8px;

  display: flex;
  gap: 8px;
  align-items: center;

  box-sizing: border-box;
}

.advisor-result-row.advisor-best {
  border-color: #8f5cff;
  box-shadow: 0 0 10px rgba(143, 92, 255, 0.35);
}

.advisor-result-row img {
  width: 34px;
  height: 34px;
  object-fit: contain;
  flex: 0 0 34px;
}

.advisor-result-info {
  flex: 1;
  min-width: 0;
}

.advisor-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-level {
  color: #bda2ff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-min {
  color: #8f7bbd;
  font-size: 11px;
  margin-top: 2px;
}

/* responsive */

@media screen and (max-width: 900px) {
  .enchant-ui {
    max-width: 850px;
    min-height: 520px;
  }

  .enchant-main {
    gap: 16px;
    padding: 10px 16px 20px 12px;
  }

  .enchant-left {
    min-width: 155px;
  }

  .enchant-heading {
    font-size: 42px;
    margin: 16px 0 22px 0;
  }

  .enchant-display-box {
    height: 165px;
  }

  .enchant-cost-box {
    height: 80px;
    font-size: 40px;
  }

  .enchant-button {
    height: 62px;
    font-size: 30px;
  }
}

@media screen and (max-width: 650px) {
  .enchant-ui {
    min-height: 0;
  }

  .enchant-main {
    flex-direction: column;
    align-items: center;

    padding: 12px;
    gap: 14px;
  }

  .enchant-left {
    width: 45%;
    max-width: 210px;
    min-width: 140px;
    flex: none;
  }

  .enchant-right {
    width: 100%;
  }

  .enchant-heading {
    text-align: center;
    font-size: 36px;
    margin: 8px 0 18px 0;
  }

  .enchant-display-box {
    height: 145px;
  }

  .enchant-line {
    margin: 20px 0;
  }

  .enchant-cost-box {
    height: 75px;
    font-size: 34px;
  }

  .enchant-button {
    width: 80%;
    min-width: 0;
    height: 58px;
    font-size: 28px;
  }

  .rod-popup {
    padding: 14px;
  }

  .rod-popup-panel {
    width: 100%;
    padding: 16px;
  }

  .rod-popup-title {
    font-size: 28px;
  }

  .rod-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .rod-card {
    min-height: 155px;
    padding: 10px;
  }

  .rod-card img {
    max-width: 85px;
    max-height: 85px;
  }
}

@media screen and (max-width: 520px) {
  .enchant-menu-popup {
    width: calc(100% - 16px);
  }

  .enchant-advisor-layout {
    grid-template-columns: 76px 1fr;
    gap: 10px;
  }

  .enchant-advisor-rods {
    width: 76px;
  }

  .enchant-advisor-rod {
    width: 76px;
    min-height: 82px;
    font-size: 9px;
  }

  .enchant-advisor-rod img,
  .enchant-advisor-rod .mw-file-element {
    max-width: 30px;
    max-height: 30px;
  }

  .enchant-advisor-rod span {
    font-size: 9px;
  }
}

@media screen and (max-width: 420px) {
  .enchant-topbar {
    height: 28px;
    font-size: 15px;
  }

  .enchant-main {
    padding: 10px;
  }

  .enchant-left {
    width: 55%;
    min-width: 120px;
  }

  .enchant-heading {
    font-size: 30px;
  }

  .enchant-display-box {
    height: 120px;
  }

  .enchant-info-text {
    font-size: 22px;
  }

  .enchant-cost-box {
    height: 62px;
    font-size: 28px;
  }

  .enchant-button {
    width: 100%;
    height: 52px;
    font-size: 24px;
  }

  .enchant-result-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .enchant-result-card {
    min-height: 115px;
  }

  .enchant-result-card img {
    max-width: 46px;
    max-height: 46px;
  }

  .enchant-result-level {
    font-size: 16px;
  }

  .enchant-menu-popup {
    top: 42px;
    right: 8px;
    bottom: 14px;

    width: calc(100% - 16px);
    max-width: none;
  }

  .enchant-menu-title {
    font-size: 20px;
  }

  .enchant-menu-option {
    font-size: 16px;
    padding: 14px;
  }

  .enchant-menu-text {
    font-size: 13px;
  }
}

@media screen and (max-width: 360px) {
  .rod-popup-title {
    font-size: 24px;
  }

  .rod-card {
    min-height: 135px;
    font-size: 13px;
  }

  .rod-card img {
    max-width: 70px;
    max-height: 70px;
  }
}

@media screen and (max-width: 340px) {
  .enchant-heading {
    font-size: 26px;
  }

  .enchant-cost-box {
    font-size: 24px;
  }

  .enchant-button {
    font-size: 21px;
  }
}

.enchant-ui {
  width: 100%;
  max-width: 1000px;
  min-height: 575px;
  margin: 0 auto;
  position: relative;

  background: #130b25;
  border: 2px solid #8f5cff;
  box-sizing: border-box;

  font-family: Arial, sans-serif;
  color: #ffffff;

  background-image:
    linear-gradient(
      135deg,
      rgba(140, 80, 255, 0.12) 0%,
      rgba(140, 80, 255, 0.12) 18%,
      transparent 18%,
      transparent 38%,
      rgba(140, 80, 255, 0.08) 38%,
      rgba(140, 80, 255, 0.08) 55%,
      transparent 55%
    );
}

.enchant-topbar {
  position: relative;
  z-index: 1000;

  height: 32px;
  background: #935cff;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 10px;
  box-sizing: border-box;

  font-size: 18px;
  font-weight: bold;
  letter-spacing: 1px;
}

.enchant-topbar-title {
  display: flex;
  align-items: center;
}

.enchant-title-icon {
  margin-right: 8px;
}

.enchant-main {
  display: flex;
  gap: 18px;

  padding: 10px 18px 22px 14px;
  box-sizing: border-box;
}

.enchant-left {
  width: 25%;
  max-width: 230px;
  min-width: 170px;
  flex: 0 0 25%;
}

.enchant-item-slot {
  position: relative;
  overflow: hidden;

  width: 100%;
  height: 0;
  padding-bottom: 100%;

  border: 1px solid #9b6cff;
  background: rgba(55, 30, 90, 0.35);

  box-sizing: border-box;
}

.enchant-right {
  flex: 1;
  min-width: 0;
}

.enchant-heading {
  font-size: 50px;
  font-weight: bold;
  line-height: 1;

  margin: 18px 0 26px 0;
}

.enchant-line {
  width: 100%;
  height: 1px;

  background: #8f5cff;
  margin: 26px 0;
}

.enchant-cost-box {
  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 48px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-fish-points-display {
  max-width: 100%;
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-button {
  width: 55%;
  max-width: 355px;
  min-width: 230px;
  height: 70px;

  margin: 22px auto 0 auto;

  background: #4b347a;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #130b25;
  font-size: 34px;
  font-weight: bold;

  box-sizing: border-box;
}

.enchant-open-picker {
  cursor: pointer;
}

.enchant-item-slot:hover,
.enchant-button:hover {
  outline: 2px solid #9b6cff;
}

/* selected rod image */

.enchant-selected-img {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  align-items: center;
  justify-content: center;
}

.enchant-selected-img img {
  max-width: 75%;
  max-height: 75%;
  width: auto;
  height: auto;
  transform: translateX(20px);
}

.enchant-ui.rod-normal .selected-normal,
.enchant-ui.rod-advanced .selected-advanced,
.enchant-ui.rod-momentum .selected-momentum,
.enchant-ui.rod-pistol .selected-pistol {
  display: flex;
}

/* headings */

.enchant-heading-normal,
.enchant-heading-advanced,
.enchant-heading-momentum,
.enchant-heading-pistol {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-default,
.enchant-ui.rod-advanced .enchant-heading-default,
.enchant-ui.rod-momentum .enchant-heading-default,
.enchant-ui.rod-pistol .enchant-heading-default {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-normal,
.enchant-ui.rod-advanced .enchant-heading-advanced,
.enchant-ui.rod-momentum .enchant-heading-momentum,
.enchant-ui.rod-pistol .enchant-heading-pistol {
  display: block;
}

/* rod popup */

.rod-popup {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 32px;
  bottom: 0;

  z-index: 100;

  align-items: center;
  justify-content: center;

  background: rgba(8, 4, 20, 0.72);
  box-sizing: border-box;
  padding: 24px;
}

.enchant-ui.rod-picker-open .rod-popup {
  display: flex;
}

.rod-popup-panel {
  width: 90%;
  max-width: 760px;

  background: #170d2f;
  border: 2px solid #8f5cff;
  box-shadow: 0 0 24px rgba(143, 92, 255, 0.35);

  padding: 24px;
  box-sizing: border-box;
}

.rod-popup-title {
  text-align: center;
  font-size: 36px;
  font-weight: bold;
  margin-bottom: 22px;
  color: #ffffff;
}

.rod-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}

.rod-card {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  min-height: 190px;
  padding: 14px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  text-align: center;
  box-sizing: border-box;

  cursor: pointer;
}

.rod-card:hover {
  background: #26124d;
  border-color: #9b6cff;
}

.rod-card img {
  max-width: 120px;
  max-height: 120px;
  width: auto;
  height: auto;
}

/* fish points input */

.enchant-points-input {
  width: 90%;
  background: transparent;
  border: none;
  outline: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;
}

.enchant-points-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.fish-points-error {
  border-color: #ff6666;
}

.fish-points-error .enchant-fish-points-display {
  color: #ff8888;
  font-size: 24px;
  font-style: normal;
}

/* enchant result display */

.enchant-display-box {
  width: 100%;
  height: 190px;

  background: rgba(82, 45, 120, 0.55);
  box-sizing: border-box;

  display: block;

  padding: 12px;

  overflow-y: auto;
  overflow-x: hidden;
}

.enchant-info-text {
  min-height: 100%;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #bda2ff;
  font-size: 30px;
  font-weight: bold;
  text-align: center;
}

.enchant-result-grid {
  display: none;
  width: 100%;

  grid-template-columns: repeat(auto-fit, minmax(90px, 1fr));
  gap: 10px;
}

.enchant-result-card {
  min-height: 130px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;

  text-align: center;
  box-sizing: border-box;
  padding: 8px;
}

.enchant-result-card img {
  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;
}

.enchant-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
  line-height: 1;
}

.enchant-result-level {
  color: #bda2ff;
  font-size: 18px;
  font-weight: bold;
}

/* enchant colors */

.enchant-bg-strength {
  background: #8c4368;
}

.enchant-bg-strength-plus {
  background: #871d50;
}

.enchant-bg-momentum {
  background: #5d8084;
}

.enchant-bg-momentum-plus {
  background: #387e73;
}

.enchant-bg-fortune {
  background: #406a98;
}

.enchant-bg-ultra {
  background: #8b4a43;
}

.enchant-bg-less-backfire {
  background: #463b53;
}

.enchant-bg-sharpshooter {
  background: #7f1397;
}

/* menu */

.enchant-menu-button {
  position: relative;
  z-index: 1001;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-width: 32px;
  min-height: 28px;

  color: #ffffff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
  user-select: none;
  pointer-events: auto;

  background: none;
  border: none;
  border-radius: 0;
}

.enchant-menu-button:hover {
  color: #d8c8ff;
}

.enchant-menu-popup {
  display: none;

  position: absolute;
  top: 46px;
  right: 12px;
  bottom: 18px;

  width: 520px;
  max-width: calc(100% - 20px);

  z-index: 1200;

  background: rgba(8, 4, 20, 0.96);
  border: 2px solid #8f5cff;
  border-radius: 16px;

  box-shadow: -8px 0 24px rgba(143, 92, 255, 0.35);

  padding: 18px;
  box-sizing: border-box;

  overflow-y: auto;
  pointer-events: auto;
}

.enchant-ui.enchant-menu-open .enchant-menu-popup {
  display: block;
}

.enchant-menu-panel {
  min-height: 100%;

  display: flex;
  flex-direction: column;

  color: #ffffff;
}

.enchant-menu-title {
  color: #ffffff;
  font-size: 24px;
  font-weight: bold;

  margin-bottom: 12px;
}

.enchant-menu-main,
.enchant-menu-options {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-menu-option {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 18px 16px;

  color: #ffffff;
  font-size: 18px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-option:hover {
  background: #21103f;
  border-color: #8f5cff;
}

.enchant-menu-page {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-main,
.enchant-menu-panel.show-notation .enchant-menu-main {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-page-fish,
.enchant-menu-panel.show-notation .enchant-menu-page-notation {
  display: block;
}

.enchant-menu-text {
  color: #ffffff;
  font-size: 14px;
  line-height: 1.35;
  overflow-wrap: anywhere;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px;
  box-sizing: border-box;
}

.enchant-notation-choice {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px 16px;
  margin-bottom: 10px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-notation-choice:hover {
  background: #140a24;
  border-color: #5b347f;
}

.enchant-notation-choice.notation-active {
  background: #21103f;
  border-color: #8f5cff;
  box-shadow: 0 0 12px rgba(143, 92, 255, 0.45);
}

.enchant-menu-back,
.enchant-menu-close {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 110px;
  min-width: 110px;

  margin-left: auto;
  margin-right: auto;

  padding: 8px 18px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 999px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-back {
  margin-top: 18px;
}

.enchant-menu-close {
  margin-top: 28px;
}

.enchant-menu-close:hover,
.enchant-menu-back:hover {
  background: #6d4ab0;
}

/* fish advisor */

.enchant-advisor-layout {
  display: grid;
  grid-template-columns: 120px 1fr;
  gap: 14px;
  align-items: start;
}

.enchant-advisor-rods {
  width: 120px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.enchant-advisor-rod {
  width: 120px;
  min-height: 150px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  padding: 10px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;

  color: #ffffff;
  font-size: 12px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
  box-sizing: border-box;
}

.enchant-advisor-rod:hover,
.enchant-advisor-rod.advisor-rod-active {
  background: #26124d;
  border-color: #9b6cff;
}

.enchant-advisor-rod a,
.enchant-advisor-rod .image {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 100%;

  background: transparent;
  border: none;
  box-shadow: none;
  padding: 0;
  margin: 0;

  line-height: 0;
}

.enchant-advisor-rod img,
.enchant-advisor-rod .mw-file-element {
  max-width: 70px;
  max-height: 70px;
  width: auto;
  height: auto;

  background: transparent;
  border: none;
  box-shadow: none;
}

.enchant-advisor-rod span {
  display: block;
  font-size: 12px;
  line-height: 1.1;
  text-align: center;
}

.enchant-advisor-right {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 14px;
}

.enchant-advisor-output {
  order: 1;

  width: 100%;
  min-height: 190px;
  max-height: 260px;

  margin-top: 0;
  padding: 14px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  color: #ffffff;
  font-size: 14px;
  line-height: 1.45;

  overflow-y: auto;
  overflow-x: hidden;

  box-sizing: border-box;
  white-space: normal;
}

.enchant-advisor-box {
  order: 2;

  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 28px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-advisor-display {
  max-width: 100%;
  display: block;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;

  color: #6f4bb5;
}

.enchant-advisor-input {
  width: 90%;

  background: transparent;
  border: none;
  outline: none;
  box-shadow: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;

  margin: 0;
  padding: 0;

  overflow: hidden;
  box-sizing: border-box;
}

.enchant-advisor-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.enchant-advisor-check {
  order: 3;

  width: 100%;
  margin-top: 0;
  padding: 12px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 12px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;

  box-sizing: border-box;
}

.enchant-advisor-check:hover {
  background: #6d4ab0;
}

/* fish advisor result rows */

.advisor-result-title {
  font-size: 15px;
  font-weight: bold;
  color: #ffffff;
  margin-bottom: 10px;
}

.advisor-result-row {
  background: #130b25;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 10px;
  margin-bottom: 8px;

  display: flex;
  gap: 8px;
  align-items: center;

  box-sizing: border-box;
}

.advisor-result-row.advisor-best {
  border-color: #8f5cff;
  box-shadow: 0 0 10px rgba(143, 92, 255, 0.35);
}

.advisor-result-row img {
  width: 34px;
  height: 34px;
  object-fit: contain;
  flex: 0 0 34px;
}

.advisor-result-info {
  flex: 1;
  min-width: 0;
}

.advisor-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-level {
  color: #bda2ff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-min {
  color: #8f7bbd;
  font-size: 11px;
  margin-top: 2px;
}

/* responsive */

@media screen and (max-width: 900px) {
  .enchant-ui {
    max-width: 850px;
    min-height: 520px;
  }

  .enchant-main {
    gap: 16px;
    padding: 10px 16px 20px 12px;
  }

  .enchant-left {
    min-width: 155px;
  }

  .enchant-heading {
    font-size: 42px;
    margin: 16px 0 22px 0;
  }

  .enchant-display-box {
    height: 165px;
  }

  .enchant-cost-box {
    height: 80px;
    font-size: 40px;
  }

  .enchant-button {
    height: 62px;
    font-size: 30px;
  }
}

@media screen and (max-width: 650px) {
  .enchant-ui {
    min-height: 0;
  }

  .enchant-main {
    flex-direction: column;
    align-items: center;

    padding: 12px;
    gap: 14px;
  }

  .enchant-left {
    width: 45%;
    max-width: 210px;
    min-width: 140px;
    flex: none;
  }

  .enchant-right {
    width: 100%;
  }

  .enchant-heading {
    text-align: center;
    font-size: 36px;
    margin: 8px 0 18px 0;
  }

  .enchant-display-box {
    height: 145px;
  }

  .enchant-line {
    margin: 20px 0;
  }

  .enchant-cost-box {
    height: 75px;
    font-size: 34px;
  }

  .enchant-button {
    width: 80%;
    min-width: 0;
    height: 58px;
    font-size: 28px;
  }

  .rod-popup {
    padding: 14px;
  }

  .rod-popup-panel {
    width: 100%;
    padding: 16px;
  }

  .rod-popup-title {
    font-size: 28px;
  }

  .rod-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .rod-card {
    min-height: 155px;
    padding: 10px;
  }

  .rod-card img {
    max-width: 85px;
    max-height: 85px;
  }
}

@media screen and (max-width: 520px) {
  .enchant-menu-popup {
    width: calc(100% - 16px);
  }

  .enchant-advisor-layout {
    grid-template-columns: 100px 1fr;
    gap: 10px;
  }

  .enchant-advisor-rods {
    width: 100px;
  }

  .enchant-advisor-rod {
    width: 100px;
    min-height: 130px;
    font-size: 11px;
  }

  .enchant-advisor-rod img,
  .enchant-advisor-rod .mw-file-element {
    max-width: 55px;
    max-height: 55px;
  }

  .enchant-advisor-box {
    height: 75px;
    font-size: 20px;
  }
}

@media screen and (max-width: 420px) {
  .enchant-topbar {
    height: 28px;
    font-size: 15px;
  }

  .enchant-main {
    padding: 10px;
  }

  .enchant-left {
    width: 55%;
    min-width: 120px;
  }

  .enchant-heading {
    font-size: 30px;
  }

  .enchant-display-box {
    height: 120px;
  }

  .enchant-info-text {
    font-size: 22px;
  }

  .enchant-cost-box {
    height: 62px;
    font-size: 28px;
  }

  .enchant-button {
    width: 100%;
    height: 52px;
    font-size: 24px;
  }

  .enchant-result-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .enchant-result-card {
    min-height: 115px;
  }

  .enchant-result-card img {
    max-width: 46px;
    max-height: 46px;
  }

  .enchant-result-level {
    font-size: 16px;
  }

  .enchant-menu-popup {
    top: 42px;
    right: 8px;
    bottom: 14px;

    width: calc(100% - 16px);
    max-width: none;
  }

  .enchant-menu-title {
    font-size: 20px;
  }

  .enchant-menu-option {
    font-size: 16px;
    padding: 14px;
  }

  .enchant-menu-text {
    font-size: 13px;
  }
}

@media screen and (max-width: 360px) {
  .rod-popup-title {
    font-size: 24px;
  }

  .rod-card {
    min-height: 135px;
    font-size: 13px;
  }

  .rod-card img {
    max-width: 70px;
    max-height: 70px;
  }
}

@media screen and (max-width: 340px) {
  .enchant-heading {
    font-size: 26px;
  }

  .enchant-cost-box {
    font-size: 24px;
  }

  .enchant-button {
    font-size: 21px;
  }
}

.enchant-ui {
  width: 100%;
  max-width: 1000px;
  min-height: 575px;
  margin: 0 auto;
  position: relative;

  background: #130b25;
  border: 2px solid #8f5cff;
  box-sizing: border-box;

  font-family: Arial, sans-serif;
  color: #ffffff;

  background-image:
    linear-gradient(
      135deg,
      rgba(140, 80, 255, 0.12) 0%,
      rgba(140, 80, 255, 0.12) 18%,
      transparent 18%,
      transparent 38%,
      rgba(140, 80, 255, 0.08) 38%,
      rgba(140, 80, 255, 0.08) 55%,
      transparent 55%
    );
}

.enchant-topbar {
  position: relative;
  z-index: 1000;

  height: 32px;
  background: #935cff;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 10px;
  box-sizing: border-box;

  font-size: 18px;
  font-weight: bold;
  letter-spacing: 1px;
}

.enchant-topbar-title {
  display: flex;
  align-items: center;
}

.enchant-title-icon {
  margin-right: 8px;
}

.enchant-main {
  display: flex;
  gap: 18px;

  padding: 10px 18px 22px 14px;
  box-sizing: border-box;
}

.enchant-left {
  width: 25%;
  max-width: 230px;
  min-width: 170px;
  flex: 0 0 25%;
}

.enchant-item-slot {
  position: relative;
  overflow: hidden;

  width: 100%;
  height: 0;
  padding-bottom: 100%;

  border: 1px solid #9b6cff;
  background: rgba(55, 30, 90, 0.35);

  box-sizing: border-box;
}

.enchant-right {
  flex: 1;
  min-width: 0;
}

.enchant-heading {
  font-size: 50px;
  font-weight: bold;
  line-height: 1;

  margin: 18px 0 26px 0;
}

.enchant-line {
  width: 100%;
  height: 1px;

  background: #8f5cff;
  margin: 26px 0;
}

.enchant-cost-box {
  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 48px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-fish-points-display {
  max-width: 100%;
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-button {
  width: 55%;
  max-width: 355px;
  min-width: 230px;
  height: 70px;

  margin: 22px auto 0 auto;

  background: #4b347a;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #130b25;
  font-size: 34px;
  font-weight: bold;

  box-sizing: border-box;
}

.enchant-open-picker {
  cursor: pointer;
}

.enchant-item-slot:hover,
.enchant-button:hover {
  outline: 2px solid #9b6cff;
}

/* selected rod image */

.enchant-selected-img {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  align-items: center;
  justify-content: center;
}

.enchant-selected-img img {
  max-width: 75%;
  max-height: 75%;
  width: auto;
  height: auto;
  transform: translateX(20px);
}

.enchant-ui.rod-normal .selected-normal,
.enchant-ui.rod-advanced .selected-advanced,
.enchant-ui.rod-momentum .selected-momentum,
.enchant-ui.rod-pistol .selected-pistol {
  display: flex;
}

/* headings */

.enchant-heading-normal,
.enchant-heading-advanced,
.enchant-heading-momentum,
.enchant-heading-pistol {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-default,
.enchant-ui.rod-advanced .enchant-heading-default,
.enchant-ui.rod-momentum .enchant-heading-default,
.enchant-ui.rod-pistol .enchant-heading-default {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-normal,
.enchant-ui.rod-advanced .enchant-heading-advanced,
.enchant-ui.rod-momentum .enchant-heading-momentum,
.enchant-ui.rod-pistol .enchant-heading-pistol {
  display: block;
}

/* rod popup */

.rod-popup {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 32px;
  bottom: 0;

  z-index: 100;

  align-items: center;
  justify-content: center;

  background: rgba(8, 4, 20, 0.72);
  box-sizing: border-box;
  padding: 24px;
}

.enchant-ui.rod-picker-open .rod-popup {
  display: flex;
}

.rod-popup-panel {
  width: 90%;
  max-width: 760px;

  background: #170d2f;
  border: 2px solid #8f5cff;
  box-shadow: 0 0 24px rgba(143, 92, 255, 0.35);

  padding: 24px;
  box-sizing: border-box;
}

.rod-popup-title {
  text-align: center;
  font-size: 36px;
  font-weight: bold;
  margin-bottom: 22px;
  color: #ffffff;
}

.rod-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}

.rod-card {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  min-height: 190px;
  padding: 14px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  text-align: center;
  box-sizing: border-box;

  cursor: pointer;
}

.rod-card:hover {
  background: #26124d;
  border-color: #9b6cff;
}

.rod-card img {
  max-width: 120px;
  max-height: 120px;
  width: auto;
  height: auto;
}

/* fish points input */

.enchant-points-input {
  width: 90%;
  background: transparent;
  border: none;
  outline: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;
}

.enchant-points-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.fish-points-error {
  border-color: #ff6666;
}

.fish-points-error .enchant-fish-points-display {
  color: #ff8888;
  font-size: 24px;
  font-style: normal;
}

/* enchant result display */

.enchant-display-box {
  width: 100%;
  height: 190px;

  background: rgba(82, 45, 120, 0.55);
  box-sizing: border-box;

  display: block;

  padding: 12px;

  overflow-y: auto;
  overflow-x: hidden;
}

.enchant-info-text {
  min-height: 100%;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #bda2ff;
  font-size: 30px;
  font-weight: bold;
  text-align: center;
}

.enchant-result-grid {
  display: none;
  width: 100%;

  grid-template-columns: repeat(auto-fit, minmax(90px, 1fr));
  gap: 10px;
}

.enchant-result-card {
  min-height: 130px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;

  text-align: center;
  box-sizing: border-box;
  padding: 8px;
}

.enchant-result-card img {
  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;
}

.enchant-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
  line-height: 1;
}

.enchant-result-level {
  color: #bda2ff;
  font-size: 18px;
  font-weight: bold;
}

/* enchant colors */

.enchant-bg-strength {
  background: #8c4368;
}

.enchant-bg-strength-plus {
  background: #871d50;
}

.enchant-bg-momentum {
  background: #5d8084;
}

.enchant-bg-momentum-plus {
  background: #387e73;
}

.enchant-bg-fortune {
  background: #406a98;
}

.enchant-bg-ultra {
  background: #8b4a43;
}

.enchant-bg-less-backfire {
  background: #463b53;
}

.enchant-bg-sharpshooter {
  background: #7f1397;
}

/* menu */

.enchant-menu-button {
  position: relative;
  z-index: 1001;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-width: 32px;
  min-height: 28px;

  color: #ffffff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
  user-select: none;
  pointer-events: auto;

  background: none;
  border: none;
  border-radius: 0;
}

.enchant-menu-button:hover {
  color: #d8c8ff;
}

.enchant-menu-popup {
  display: none;

  position: absolute;
  top: 46px;
  right: 12px;
  bottom: 18px;

  width: 520px;
  max-width: calc(100% - 20px);

  z-index: 1200;

  background: rgba(8, 4, 20, 0.96);
  border: 2px solid #8f5cff;
  border-radius: 16px;

  box-shadow: -8px 0 24px rgba(143, 92, 255, 0.35);

  padding: 18px;
  box-sizing: border-box;

  overflow-y: auto;
  pointer-events: auto;
}

.enchant-ui.enchant-menu-open .enchant-menu-popup {
  display: block;
}

.enchant-menu-panel {
  min-height: 100%;

  display: flex;
  flex-direction: column;

  color: #ffffff;
}

.enchant-menu-title {
  color: #ffffff;
  font-size: 24px;
  font-weight: bold;

  margin-bottom: 12px;
}

.enchant-menu-main,
.enchant-menu-options {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-menu-option {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 18px 16px;

  color: #ffffff;
  font-size: 18px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-option:hover {
  background: #21103f;
  border-color: #8f5cff;
}

.enchant-menu-page {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-main,
.enchant-menu-panel.show-notation .enchant-menu-main {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-page-fish,
.enchant-menu-panel.show-notation .enchant-menu-page-notation {
  display: block;
}

.enchant-menu-text {
  color: #ffffff;
  font-size: 14px;
  line-height: 1.35;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px;
  box-sizing: border-box;
}

.enchant-notation-choice {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px 16px;
  margin-bottom: 10px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-notation-choice:hover {
  background: #140a24;
  border-color: #5b347f;
}

.enchant-notation-choice.notation-active {
  background: #21103f;
  border-color: #8f5cff;
  box-shadow: 0 0 12px rgba(143, 92, 255, 0.45);
}

.enchant-menu-back,
.enchant-menu-close {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 110px;
  min-width: 110px;

  margin-left: auto;
  margin-right: auto;

  padding: 8px 18px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 999px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-back {
  margin-top: 18px;
}

.enchant-menu-close {
  margin-top: 28px;
}

.enchant-menu-close:hover,
.enchant-menu-back:hover {
  background: #6d4ab0;
}

/* fish advisor */

.enchant-advisor-layout {
  display: grid;
  grid-template-columns: 110px 1fr;
  gap: 14px;
  align-items: start;
}

.enchant-advisor-rods {
  width: 110px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-advisor-rod {
  width: 110px;
  height: 110px;
  min-height: 110px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  padding: 8px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  color: #ffffff;
  font-size: 11px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
  box-sizing: border-box;
}

.enchant-advisor-rod:hover,
.enchant-advisor-rod.advisor-rod-active {
  background: #26124d;
  border-color: #9b6cff;
}

.enchant-advisor-rod a,
.enchant-advisor-rod .image {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 100%;

  background: transparent;
  border: none;
  box-shadow: none;
  padding: 0;
  margin: 0;

  line-height: 0;
}

.enchant-advisor-rod img,
.enchant-advisor-rod .mw-file-element {
  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;

  background: transparent;
  border: none;
  box-shadow: none;
}

.enchant-advisor-rod span {
  display: block;

  margin-top: 0;

  font-size: 11px;
  line-height: 1.1;
  text-align: center;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-advisor-right {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 14px;
}

.enchant-advisor-output {
  order: 1;

  width: 100%;
  min-height: 190px;
  max-height: 260px;

  margin-top: 0;
  padding: 14px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  color: #ffffff;
  font-size: 14px;
  line-height: 1.45;

  overflow-y: auto;
  overflow-x: hidden;

  box-sizing: border-box;
  white-space: normal;
}

.enchant-advisor-box {
  order: 2;

  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 28px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-advisor-display {
  max-width: 100%;
  display: block;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;

  color: #6f4bb5;
}

.enchant-advisor-input {
  width: 90%;

  background: transparent;
  border: none;
  outline: none;
  box-shadow: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;

  margin: 0;
  padding: 0;

  overflow: hidden;
  box-sizing: border-box;
}

.enchant-advisor-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.enchant-advisor-check {
  order: 3;

  width: 100%;
  margin-top: 0;
  padding: 12px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 12px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;

  box-sizing: border-box;
}

.enchant-advisor-check:hover {
  background: #6d4ab0;
}

/* fish advisor result rows */

.advisor-result-title {
  font-size: 15px;
  font-weight: bold;
  color: #ffffff;
  margin-bottom: 10px;
}

.advisor-result-row {
  background: #130b25;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 10px;
  margin-bottom: 8px;

  display: flex;
  gap: 8px;
  align-items: center;

  box-sizing: border-box;
}

.advisor-result-row.advisor-best {
  border-color: #8f5cff;
  box-shadow: 0 0 10px rgba(143, 92, 255, 0.35);
}

.advisor-result-row img {
  width: 34px;
  height: 34px;
  object-fit: contain;
  flex: 0 0 34px;
}

.advisor-result-info {
  flex: 1;
  min-width: 0;
}

.advisor-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-level {
  color: #bda2ff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-min {
  color: #8f7bbd;
  font-size: 11px;
  margin-top: 2px;
}

/* responsive */

@media screen and (max-width: 900px) {
  .enchant-ui {
    max-width: 850px;
    min-height: 520px;
  }

  .enchant-main {
    gap: 16px;
    padding: 10px 16px 20px 12px;
  }

  .enchant-left {
    min-width: 155px;
  }

  .enchant-heading {
    font-size: 42px;
    margin: 16px 0 22px 0;
  }

  .enchant-display-box {
    height: 165px;
  }

  .enchant-cost-box {
    height: 80px;
    font-size: 40px;
  }

  .enchant-button {
    height: 62px;
    font-size: 30px;
  }
}

@media screen and (max-width: 650px) {
  .enchant-ui {
    min-height: 0;
  }

  .enchant-main {
    flex-direction: column;
    align-items: center;

    padding: 12px;
    gap: 14px;
  }

  .enchant-left {
    width: 45%;
    max-width: 210px;
    min-width: 140px;
    flex: none;
  }

  .enchant-right {
    width: 100%;
  }

  .enchant-heading {
    text-align: center;
    font-size: 36px;
    margin: 8px 0 18px 0;
  }

  .enchant-display-box {
    height: 145px;
  }

  .enchant-line {
    margin: 20px 0;
  }

  .enchant-cost-box {
    height: 75px;
    font-size: 34px;
  }

  .enchant-button {
    width: 80%;
    min-width: 0;
    height: 58px;
    font-size: 28px;
  }

  .rod-popup {
    padding: 14px;
  }

  .rod-popup-panel {
    width: 100%;
    padding: 16px;
  }

  .rod-popup-title {
    font-size: 28px;
  }

  .rod-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .rod-card {
    min-height: 155px;
    padding: 10px;
  }

  .rod-card img {
    max-width: 85px;
    max-height: 85px;
  }
}

@media screen and (max-width: 520px) {
  .enchant-menu-popup {
    width: calc(100% - 16px);
  }

  .enchant-advisor-layout {
    grid-template-columns: 88px 1fr;
    gap: 10px;
  }

  .enchant-advisor-rods {
    width: 88px;
  }

  .enchant-advisor-rod {
    width: 88px;
    height: 88px;
    min-height: 88px;
    font-size: 10px;
    padding: 6px;
  }

  .enchant-advisor-rod img,
  .enchant-advisor-rod .mw-file-element {
    max-width: 46px;
    max-height: 46px;
  }

  .enchant-advisor-rod span {
    font-size: 10px;
  }

  .enchant-advisor-box {
    height: 75px;
    font-size: 20px;
  }
}

@media screen and (max-width: 420px) {
  .enchant-topbar {
    height: 28px;
    font-size: 15px;
  }

  .enchant-main {
    padding: 10px;
  }

  .enchant-left {
    width: 55%;
    min-width: 120px;
  }

  .enchant-heading {
    font-size: 30px;
  }

  .enchant-display-box {
    height: 120px;
  }

  .enchant-info-text {
    font-size: 22px;
  }

  .enchant-cost-box {
    height: 62px;
    font-size: 28px;
  }

  .enchant-button {
    width: 100%;
    height: 52px;
    font-size: 24px;
  }

  .enchant-result-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .enchant-result-card {
    min-height: 115px;
  }

  .enchant-result-card img {
    max-width: 46px;
    max-height: 46px;
  }

  .enchant-result-level {
    font-size: 16px;
  }

  .enchant-menu-popup {
    top: 42px;
    right: 8px;
    bottom: 14px;

    width: calc(100% - 16px);
    max-width: none;
  }

  .enchant-menu-title {
    font-size: 20px;
  }

  .enchant-menu-option {
    font-size: 16px;
    padding: 14px;
  }

  .enchant-menu-text {
    font-size: 13px;
  }
}

@media screen and (max-width: 360px) {
  .rod-popup-title {
    font-size: 24px;
  }

  .rod-card {
    min-height: 135px;
    font-size: 13px;
  }

  .rod-card img {
    max-width: 70px;
    max-height: 70px;
  }
}

@media screen and (max-width: 340px) {
  .enchant-heading {
    font-size: 26px;
  }

  .enchant-cost-box {
    font-size: 24px;
  }

  .enchant-button {
    font-size: 21px;
  }
}

.enchant-ui {
  width: 100%;
  max-width: 1000px;
  min-height: 575px;
  margin: 0 auto;
  position: relative;

  background: #130b25;
  border: 2px solid #8f5cff;
  box-sizing: border-box;

  font-family: Arial, sans-serif;
  color: #ffffff;

  background-image:
    linear-gradient(
      135deg,
      rgba(140, 80, 255, 0.12) 0%,
      rgba(140, 80, 255, 0.12) 18%,
      transparent 18%,
      transparent 38%,
      rgba(140, 80, 255, 0.08) 38%,
      rgba(140, 80, 255, 0.08) 55%,
      transparent 55%
    );
}

.enchant-topbar {
  position: relative;
  z-index: 1000;

  height: 32px;
  background: #935cff;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 10px;
  box-sizing: border-box;

  font-size: 18px;
  font-weight: bold;
  letter-spacing: 1px;
}

.enchant-topbar-title {
  display: flex;
  align-items: center;
}

.enchant-title-icon {
  margin-right: 8px;
}

.enchant-main {
  display: flex;
  gap: 18px;

  padding: 10px 18px 22px 14px;
  box-sizing: border-box;
}

.enchant-left {
  width: 25%;
  max-width: 230px;
  min-width: 170px;
  flex: 0 0 25%;
}

.enchant-item-slot {
  position: relative;
  overflow: hidden;

  width: 100%;
  height: 0;
  padding-bottom: 100%;

  border: 1px solid #9b6cff;
  background: rgba(55, 30, 90, 0.35);

  box-sizing: border-box;
}

.enchant-right {
  flex: 1;
  min-width: 0;
}

.enchant-heading {
  font-size: 50px;
  font-weight: bold;
  line-height: 1;

  margin: 18px 0 26px 0;
}

.enchant-line {
  width: 100%;
  height: 1px;

  background: #8f5cff;
  margin: 26px 0;
}

.enchant-cost-box {
  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 48px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-fish-points-display {
  max-width: 100%;
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-button {
  width: 55%;
  max-width: 355px;
  min-width: 230px;
  height: 70px;

  margin: 22px auto 0 auto;

  background: #4b347a;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #130b25;
  font-size: 34px;
  font-weight: bold;

  box-sizing: border-box;
}

.enchant-open-picker {
  cursor: pointer;
}

.enchant-item-slot:hover,
.enchant-button:hover {
  outline: 2px solid #9b6cff;
}

/* selected rod image */

.enchant-selected-img {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  align-items: center;
  justify-content: center;
}

.enchant-selected-img img {
  max-width: 75%;
  max-height: 75%;
  width: auto;
  height: auto;
  transform: translateX(20px);
}

.enchant-ui.rod-normal .selected-normal,
.enchant-ui.rod-advanced .selected-advanced,
.enchant-ui.rod-momentum .selected-momentum,
.enchant-ui.rod-pistol .selected-pistol {
  display: flex;
}

/* headings */

.enchant-heading-normal,
.enchant-heading-advanced,
.enchant-heading-momentum,
.enchant-heading-pistol {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-default,
.enchant-ui.rod-advanced .enchant-heading-default,
.enchant-ui.rod-momentum .enchant-heading-default,
.enchant-ui.rod-pistol .enchant-heading-default {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-normal,
.enchant-ui.rod-advanced .enchant-heading-advanced,
.enchant-ui.rod-momentum .enchant-heading-momentum,
.enchant-ui.rod-pistol .enchant-heading-pistol {
  display: block;
}

/* rod popup */

.rod-popup {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 32px;
  bottom: 0;

  z-index: 100;

  align-items: center;
  justify-content: center;

  background: rgba(8, 4, 20, 0.72);
  box-sizing: border-box;
  padding: 24px;
}

.enchant-ui.rod-picker-open .rod-popup {
  display: flex;
}

.rod-popup-panel {
  width: 90%;
  max-width: 760px;

  background: #170d2f;
  border: 2px solid #8f5cff;
  box-shadow: 0 0 24px rgba(143, 92, 255, 0.35);

  padding: 24px;
  box-sizing: border-box;
}

.rod-popup-title {
  text-align: center;
  font-size: 36px;
  font-weight: bold;
  margin-bottom: 22px;
  color: #ffffff;
}

.rod-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}

.rod-card {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  min-height: 190px;
  padding: 14px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  text-align: center;
  box-sizing: border-box;

  cursor: pointer;
}

.rod-card:hover {
  background: #26124d;
  border-color: #9b6cff;
}

.rod-card img {
  max-width: 120px;
  max-height: 120px;
  width: auto;
  height: auto;
}

/* fish points input */

.enchant-points-input {
  width: 90%;
  background: transparent;
  border: none;
  outline: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;
}

.enchant-points-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.fish-points-error {
  border-color: #ff6666;
}

.fish-points-error .enchant-fish-points-display {
  color: #ff8888;
  font-size: 24px;
  font-style: normal;
}

/* enchant result display */

.enchant-display-box {
  width: 100%;
  height: 190px;

  background: rgba(82, 45, 120, 0.55);
  box-sizing: border-box;

  display: block;

  padding: 12px;

  overflow-y: auto;
  overflow-x: hidden;
}

.enchant-info-text {
  min-height: 100%;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #bda2ff;
  font-size: 30px;
  font-weight: bold;
  text-align: center;
}

.enchant-result-grid {
  display: none;
  width: 100%;

  grid-template-columns: repeat(auto-fit, minmax(90px, 1fr));
  gap: 10px;
}

.enchant-result-card {
  min-height: 130px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;

  text-align: center;
  box-sizing: border-box;
  padding: 8px;
}

.enchant-result-card img {
  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;
}

.enchant-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
  line-height: 1;
}

.enchant-result-level {
  color: #bda2ff;
  font-size: 18px;
  font-weight: bold;
}

/* enchant colors */

.enchant-bg-strength {
  background: #8c4368;
}

.enchant-bg-strength-plus {
  background: #871d50;
}

.enchant-bg-momentum {
  background: #5d8084;
}

.enchant-bg-momentum-plus {
  background: #387e73;
}

.enchant-bg-fortune {
  background: #406a98;
}

.enchant-bg-ultra {
  background: #8b4a43;
}

.enchant-bg-less-backfire {
  background: #463b53;
}

.enchant-bg-sharpshooter {
  background: #7f1397;
}

/* menu */

.enchant-menu-button {
  position: relative;
  z-index: 1001;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-width: 32px;
  min-height: 28px;

  color: #ffffff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
  user-select: none;
  pointer-events: auto;

  background: none;
  border: none;
  border-radius: 0;
}

.enchant-menu-button:hover {
  color: #d8c8ff;
}

.enchant-menu-popup {
  display: none;

  position: absolute;
  top: 46px;
  right: 12px;
  bottom: 18px;

  width: 520px;
  max-width: calc(100% - 20px);

  z-index: 1200;

  background: rgba(8, 4, 20, 0.96);
  border: 2px solid #8f5cff;
  border-radius: 16px;

  box-shadow: -8px 0 24px rgba(143, 92, 255, 0.35);

  padding: 18px;
  box-sizing: border-box;

  overflow-y: auto;
  pointer-events: auto;
}

.enchant-ui.enchant-menu-open .enchant-menu-popup {
  display: block;
}

.enchant-menu-panel {
  min-height: 100%;

  display: flex;
  flex-direction: column;

  color: #ffffff;
}

.enchant-menu-title {
  color: #ffffff;
  font-size: 24px;
  font-weight: bold;

  margin-bottom: 12px;
}

.enchant-menu-main,
.enchant-menu-options {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-menu-option {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 18px 16px;

  color: #ffffff;
  font-size: 18px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-option:hover {
  background: #21103f;
  border-color: #8f5cff;
}

.enchant-menu-page {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-main,
.enchant-menu-panel.show-notation .enchant-menu-main {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-page-fish,
.enchant-menu-panel.show-notation .enchant-menu-page-notation {
  display: block;
}

.enchant-menu-text {
  color: #ffffff;
  font-size: 14px;
  line-height: 1.35;
  overflow-wrap: anywhere;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px;
  box-sizing: border-box;
}

.enchant-notation-choice {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px 16px;
  margin-bottom: 10px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-notation-choice:hover {
  background: #140a24;
  border-color: #5b347f;
}

.enchant-notation-choice.notation-active {
  background: #21103f;
  border-color: #8f5cff;
  box-shadow: 0 0 12px rgba(143, 92, 255, 0.45);
}

.enchant-menu-back,
.enchant-menu-close {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 110px;
  min-width: 110px;

  margin-left: auto;
  margin-right: auto;

  padding: 8px 18px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 999px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-back {
  margin-top: 18px;
}

.enchant-menu-close {
  margin-top: 28px;
}

.enchant-menu-close:hover,
.enchant-menu-back:hover {
  background: #6d4ab0;
}

/* fish advisor */

.enchant-advisor-layout {
  display: grid;
  grid-template-columns: 110px 1fr;
  gap: 14px;
  align-items: start;
}

.enchant-advisor-rods {
  width: 110px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-advisor-rod {
  width: 110px;
  height: 110px;
  min-height: 110px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  padding: 8px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  color: #ffffff;
  font-size: 11px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
  box-sizing: border-box;

  overflow: hidden;
}

.enchant-advisor-rod:hover,
.enchant-advisor-rod.advisor-rod-active {
  background: #26124d;
  border-color: #9b6cff;
}

.enchant-advisor-rod a,
.enchant-advisor-rod .image,
.enchant-advisor-rod .mw-file-description,
.enchant-advisor-rod .mw-default-size {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 100%;
  max-width: 100%;

  background: transparent;
  border: none;
  box-shadow: none;
  padding: 0;
  margin: 0;

  line-height: 0;
  overflow: visible;
}

.enchant-advisor-rod img,
.enchant-advisor-rod .mw-file-element {
  display: block;

  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;

  background: transparent;
  border: none;
  box-shadow: none;

  margin: 0 auto;
}

.advisor-rod-name {
  display: block;
  width: 100%;

  margin-top: 0;

  color: #ffffff;
  font-size: 11px;
  line-height: 1.1;
  text-align: center;
  font-weight: bold;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-advisor-right {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 14px;
}

.enchant-advisor-output {
  order: 1;

  width: 100%;
  min-height: 190px;
  max-height: 260px;

  margin-top: 0;
  padding: 14px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  color: #ffffff;
  font-size: 14px;
  line-height: 1.45;

  overflow-y: auto;
  overflow-x: hidden;

  box-sizing: border-box;
  white-space: normal;
}

.enchant-advisor-box {
  order: 2;

  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 28px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-advisor-display {
  max-width: 100%;
  display: block;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;

  color: #6f4bb5;
}

.enchant-advisor-input {
  width: 90%;

  background: transparent;
  border: none;
  outline: none;
  box-shadow: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;

  margin: 0;
  padding: 0;

  overflow: hidden;
  box-sizing: border-box;
}

.enchant-advisor-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.enchant-advisor-check {
  order: 3;

  width: 100%;
  margin-top: 0;
  padding: 12px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 12px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;

  box-sizing: border-box;
}

.enchant-advisor-check:hover {
  background: #6d4ab0;
}

/* fish advisor result rows */

.advisor-result-title {
  font-size: 15px;
  font-weight: bold;
  color: #ffffff;
  margin-bottom: 10px;
}

.advisor-result-row {
  background: #130b25;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 10px;
  margin-bottom: 8px;

  display: flex;
  gap: 8px;
  align-items: center;

  box-sizing: border-box;
}

.advisor-result-row.advisor-best {
  border-color: #8f5cff;
  box-shadow: 0 0 10px rgba(143, 92, 255, 0.35);
}

.advisor-result-row img {
  width: 34px;
  height: 34px;
  object-fit: contain;
  flex: 0 0 34px;
}

.advisor-result-info {
  flex: 1;
  min-width: 0;
}

.advisor-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-level {
  color: #bda2ff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-min {
  color: #8f7bbd;
  font-size: 11px;
  margin-top: 2px;
}

/* responsive */

@media screen and (max-width: 900px) {
  .enchant-ui {
    max-width: 850px;
    min-height: 520px;
  }

  .enchant-main {
    gap: 16px;
    padding: 10px 16px 20px 12px;
  }

  .enchant-left {
    min-width: 155px;
  }

  .enchant-heading {
    font-size: 42px;
    margin: 16px 0 22px 0;
  }

  .enchant-display-box {
    height: 165px;
  }

  .enchant-cost-box {
    height: 80px;
    font-size: 40px;
  }

  .enchant-button {
    height: 62px;
    font-size: 30px;
  }
}

@media screen and (max-width: 650px) {
  .enchant-ui {
    min-height: 0;
  }

  .enchant-main {
    flex-direction: column;
    align-items: center;

    padding: 12px;
    gap: 14px;
  }

  .enchant-left {
    width: 45%;
    max-width: 210px;
    min-width: 140px;
    flex: none;
  }

  .enchant-right {
    width: 100%;
  }

  .enchant-heading {
    text-align: center;
    font-size: 36px;
    margin: 8px 0 18px 0;
  }

  .enchant-display-box {
    height: 145px;
  }

  .enchant-line {
    margin: 20px 0;
  }

  .enchant-cost-box {
    height: 75px;
    font-size: 34px;
  }

  .enchant-button {
    width: 80%;
    min-width: 0;
    height: 58px;
    font-size: 28px;
  }

  .rod-popup {
    padding: 14px;
  }

  .rod-popup-panel {
    width: 100%;
    padding: 16px;
  }

  .rod-popup-title {
    font-size: 28px;
  }

  .rod-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .rod-card {
    min-height: 155px;
    padding: 10px;
  }

  .rod-card img {
    max-width: 85px;
    max-height: 85px;
  }
}

@media screen and (max-width: 520px) {
  .enchant-menu-popup {
    width: calc(100% - 16px);
  }

  .enchant-advisor-layout {
    grid-template-columns: 88px 1fr;
    gap: 10px;
  }

  .enchant-advisor-rods {
    width: 88px;
  }

  .enchant-advisor-rod {
    width: 88px;
    height: 88px;
    min-height: 88px;
    font-size: 10px;
    padding: 6px;
  }

  .enchant-advisor-rod img,
  .enchant-advisor-rod .mw-file-element {
    max-width: 46px;
    max-height: 46px;
  }

  .advisor-rod-name {
    font-size: 10px;
  }

  .enchant-advisor-box {
    height: 75px;
    font-size: 20px;
  }
}

@media screen and (max-width: 420px) {
  .enchant-topbar {
    height: 28px;
    font-size: 15px;
  }

  .enchant-main {
    padding: 10px;
  }

  .enchant-left {
    width: 55%;
    min-width: 120px;
  }

  .enchant-heading {
    font-size: 30px;
  }

  .enchant-display-box {
    height: 120px;
  }

  .enchant-info-text {
    font-size: 22px;
  }

  .enchant-cost-box {
    height: 62px;
    font-size: 28px;
  }

  .enchant-button {
    width: 100%;
    height: 52px;
    font-size: 24px;
  }

  .enchant-result-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .enchant-result-card {
    min-height: 115px;
  }

  .enchant-result-card img {
    max-width: 46px;
    max-height: 46px;
  }

  .enchant-result-level {
    font-size: 16px;
  }

  .enchant-menu-popup {
    top: 42px;
    right: 8px;
    bottom: 14px;

    width: calc(100% - 16px);
    max-width: none;
  }

  .enchant-menu-title {
    font-size: 20px;
  }

  .enchant-menu-option {
    font-size: 16px;
    padding: 14px;
  }

  .enchant-menu-text {
    font-size: 13px;
  }
}

@media screen and (max-width: 360px) {
  .rod-popup-title {
    font-size: 24px;
  }

  .rod-card {
    min-height: 135px;
    font-size: 13px;
  }

  .rod-card img {
    max-width: 70px;
    max-height: 70px;
  }
}

@media screen and (max-width: 340px) {
  .enchant-heading {
    font-size: 26px;
  }

  .enchant-cost-box {
    font-size: 24px;
  }

  .enchant-button {
    font-size: 21px;
  }
}

.enchant-ui {
  width: 100%;
  max-width: 1000px;
  min-height: 575px;
  margin: 0 auto;
  position: relative;

  background: #130b25;
  border: 2px solid #8f5cff;
  box-sizing: border-box;

  font-family: Arial, sans-serif;
  color: #ffffff;

  background-image:
    linear-gradient(
      135deg,
      rgba(140, 80, 255, 0.12) 0%,
      rgba(140, 80, 255, 0.12) 18%,
      transparent 18%,
      transparent 38%,
      rgba(140, 80, 255, 0.08) 38%,
      rgba(140, 80, 255, 0.08) 55%,
      transparent 55%
    );
}

.enchant-topbar {
  position: relative;
  z-index: 1000;

  height: 32px;
  background: #935cff;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 10px;
  box-sizing: border-box;

  font-size: 18px;
  font-weight: bold;
  letter-spacing: 1px;
}

.enchant-topbar-title {
  display: flex;
  align-items: center;
}

.enchant-title-icon {
  margin-right: 8px;
}

.enchant-main {
  display: flex;
  gap: 18px;

  padding: 10px 18px 22px 14px;
  box-sizing: border-box;
}

.enchant-left {
  width: 25%;
  max-width: 230px;
  min-width: 170px;
  flex: 0 0 25%;
}

.enchant-item-slot {
  position: relative;
  overflow: hidden;

  width: 100%;
  height: 0;
  padding-bottom: 100%;

  border: 1px solid #9b6cff;
  background: rgba(55, 30, 90, 0.35);

  box-sizing: border-box;
}

.enchant-right {
  flex: 1;
  min-width: 0;
}

.enchant-heading {
  font-size: 50px;
  font-weight: bold;
  line-height: 1;

  margin: 18px 0 26px 0;
}

.enchant-line {
  width: 100%;
  height: 1px;

  background: #8f5cff;
  margin: 26px 0;
}

.enchant-cost-box {
  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 48px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-fish-points-display {
  max-width: 100%;
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-button {
  width: 55%;
  max-width: 355px;
  min-width: 230px;
  height: 70px;

  margin: 22px auto 0 auto;

  background: #4b347a;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #130b25;
  font-size: 34px;
  font-weight: bold;

  box-sizing: border-box;
}

.enchant-open-picker {
  cursor: pointer;
}

.enchant-item-slot:hover,
.enchant-button:hover {
  outline: 2px solid #9b6cff;
}

/* selected rod image */

.enchant-selected-img {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  align-items: center;
  justify-content: center;
}

.enchant-selected-img img {
  max-width: 75%;
  max-height: 75%;
  width: auto;
  height: auto;
  transform: translateX(20px);
}

.enchant-ui.rod-normal .selected-normal,
.enchant-ui.rod-advanced .selected-advanced,
.enchant-ui.rod-momentum .selected-momentum,
.enchant-ui.rod-pistol .selected-pistol {
  display: flex;
}

/* headings */

.enchant-heading-normal,
.enchant-heading-advanced,
.enchant-heading-momentum,
.enchant-heading-pistol {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-default,
.enchant-ui.rod-advanced .enchant-heading-default,
.enchant-ui.rod-momentum .enchant-heading-default,
.enchant-ui.rod-pistol .enchant-heading-default {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-normal,
.enchant-ui.rod-advanced .enchant-heading-advanced,
.enchant-ui.rod-momentum .enchant-heading-momentum,
.enchant-ui.rod-pistol .enchant-heading-pistol {
  display: block;
}

/* rod popup */

.rod-popup {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 32px;
  bottom: 0;

  z-index: 100;

  align-items: center;
  justify-content: center;

  background: rgba(8, 4, 20, 0.72);
  box-sizing: border-box;
  padding: 24px;
}

.enchant-ui.rod-picker-open .rod-popup {
  display: flex;
}

.rod-popup-panel {
  width: 90%;
  max-width: 760px;

  background: #170d2f;
  border: 2px solid #8f5cff;
  box-shadow: 0 0 24px rgba(143, 92, 255, 0.35);

  padding: 24px;
  box-sizing: border-box;
}

.rod-popup-title {
  text-align: center;
  font-size: 36px;
  font-weight: bold;
  margin-bottom: 22px;
  color: #ffffff;
}

.rod-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}

.rod-card {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  min-height: 190px;
  padding: 14px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  text-align: center;
  box-sizing: border-box;

  cursor: pointer;
}

.rod-card:hover {
  background: #26124d;
  border-color: #9b6cff;
}

.rod-card img {
  max-width: 120px;
  max-height: 120px;
  width: auto;
  height: auto;
}

/* fish points input */

.enchant-points-input {
  width: 90%;
  background: transparent;
  border: none;
  outline: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;
}

.enchant-points-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.fish-points-error {
  border-color: #ff6666;
}

.fish-points-error .enchant-fish-points-display {
  color: #ff8888;
  font-size: 24px;
  font-style: normal;
}

/* enchant result display */

.enchant-display-box {
  width: 100%;
  height: 190px;

  background: rgba(82, 45, 120, 0.55);
  box-sizing: border-box;

  display: block;

  padding: 12px;

  overflow-y: auto;
  overflow-x: hidden;
}

.enchant-info-text {
  min-height: 100%;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #bda2ff;
  font-size: 30px;
  font-weight: bold;
  text-align: center;
}

.enchant-result-grid {
  display: none;
  width: 100%;

  grid-template-columns: repeat(auto-fit, minmax(90px, 1fr));
  gap: 10px;
}

.enchant-result-card {
  min-height: 130px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;

  text-align: center;
  box-sizing: border-box;
  padding: 8px;
}

.enchant-result-card img {
  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;
}

.enchant-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
  line-height: 1;
}

.enchant-result-level {
  color: #bda2ff;
  font-size: 18px;
  font-weight: bold;
}

/* enchant colors */

.enchant-bg-strength {
  background: #8c4368;
}

.enchant-bg-strength-plus {
  background: #871d50;
}

.enchant-bg-momentum {
  background: #5d8084;
}

.enchant-bg-momentum-plus {
  background: #387e73;
}

.enchant-bg-fortune {
  background: #406a98;
}

.enchant-bg-ultra {
  background: #8b4a43;
}

.enchant-bg-less-backfire {
  background: #463b53;
}

.enchant-bg-sharpshooter {
  background: #7f1397;
}

/* menu */

.enchant-menu-button {
  position: relative;
  z-index: 1001;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-width: 32px;
  min-height: 28px;

  color: #ffffff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
  user-select: none;
  pointer-events: auto;

  background: none;
  border: none;
  border-radius: 0;
}

.enchant-menu-button:hover {
  color: #d8c8ff;
}

.enchant-menu-popup {
  display: none;

  position: absolute;
  top: 46px;
  right: 12px;
  bottom: 18px;

  width: 520px;
  max-width: calc(100% - 20px);

  z-index: 1200;

  background: rgba(8, 4, 20, 0.96);
  border: 2px solid #8f5cff;
  border-radius: 16px;

  box-shadow: -8px 0 24px rgba(143, 92, 255, 0.35);

  padding: 18px;
  box-sizing: border-box;

  overflow-y: auto;
  pointer-events: auto;
}

.enchant-ui.enchant-menu-open .enchant-menu-popup {
  display: block;
}

.enchant-menu-panel {
  min-height: 100%;

  display: flex;
  flex-direction: column;

  color: #ffffff;
}

.enchant-menu-title {
  color: #ffffff;
  font-size: 24px;
  font-weight: bold;

  margin-bottom: 12px;
}

.enchant-menu-main,
.enchant-menu-options {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-menu-option {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 18px 16px;

  color: #ffffff;
  font-size: 18px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-option:hover {
  background: #21103f;
  border-color: #8f5cff;
}

.enchant-menu-page {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-main,
.enchant-menu-panel.show-notation .enchant-menu-main {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-page-fish,
.enchant-menu-panel.show-notation .enchant-menu-page-notation {
  display: block;
}

.enchant-menu-text {
  color: #ffffff;
  font-size: 14px;
  line-height: 1.35;
  overflow-wrap: anywhere;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px;
  box-sizing: border-box;
}

.enchant-notation-choice {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px 16px;
  margin-bottom: 10px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-notation-choice:hover {
  background: #140a24;
  border-color: #5b347f;
}

.enchant-notation-choice.notation-active {
  background: #21103f;
  border-color: #8f5cff;
  box-shadow: 0 0 12px rgba(143, 92, 255, 0.45);
}

.enchant-menu-back,
.enchant-menu-close {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 110px;
  min-width: 110px;

  margin-left: auto;
  margin-right: auto;

  padding: 8px 18px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 999px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-back {
  margin-top: 18px;
}

.enchant-menu-close {
  margin-top: 28px;
}

.enchant-menu-close:hover,
.enchant-menu-back:hover {
  background: #6d4ab0;
}

/* fish advisor */

.enchant-advisor-layout {
  display: grid;
  grid-template-columns: 110px 1fr;
  gap: 14px;
  align-items: start;
}

.enchant-advisor-rods {
  width: 110px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-advisor-rod {
  width: 110px;
  height: 110px;
  min-height: 110px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  padding: 8px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  color: #ffffff;
  font-size: 11px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
  box-sizing: border-box;

  overflow: hidden;
}

.enchant-advisor-rod:hover,
.enchant-advisor-rod.advisor-rod-active {
  background: #26124d;
  border-color: #9b6cff;
}

.enchant-advisor-rod a,
.enchant-advisor-rod .image,
.enchant-advisor-rod .mw-file-description,
.enchant-advisor-rod .mw-default-size {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 100%;
  max-width: 100%;

  background: transparent;
  border: none;
  box-shadow: none;
  padding: 0;
  margin: 0;

  line-height: 0;
  overflow: visible;
}

.enchant-advisor-rod img,
.enchant-advisor-rod .mw-file-element {
  display: block;

  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;

  background: transparent;
  border: none;
  box-shadow: none;

  margin: 0 auto;
}

.advisor-rod-name {
  display: block;
  width: 100%;

  margin-top: 0;

  color: #ffffff;
  font-size: 11px;
  line-height: 1.1;
  text-align: center;
  font-weight: bold;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-advisor-right {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 14px;
}

.enchant-advisor-output {
  order: 1;

  width: 100%;
  min-height: 190px;
  max-height: 260px;

  margin-top: 0;
  padding: 14px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  color: #ffffff;
  font-size: 14px;
  line-height: 1.45;

  overflow-y: auto;
  overflow-x: hidden;

  box-sizing: border-box;
  white-space: normal;
}

.enchant-advisor-box {
  order: 2;

  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 28px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-advisor-display {
  max-width: 100%;
  display: block;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;

  color: #6f4bb5;
}

.enchant-advisor-input {
  width: 90%;

  background: transparent;
  border: none;
  outline: none;
  box-shadow: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;

  margin: 0;
  padding: 0;

  overflow: hidden;
  box-sizing: border-box;
}

.enchant-advisor-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.enchant-advisor-check {
  order: 3;

  width: 100%;
  margin-top: 0;
  padding: 12px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 12px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;

  box-sizing: border-box;
}

.enchant-advisor-check:hover {
  background: #6d4ab0;
}

/* fish advisor result rows */

.advisor-result-title {
  font-size: 15px;
  font-weight: bold;
  color: #ffffff;
  margin-bottom: 10px;
}

.advisor-result-row {
  background: #130b25;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 10px;
  margin-bottom: 8px;

  display: flex;
  gap: 8px;
  align-items: center;

  box-sizing: border-box;
}

.advisor-result-row.advisor-best {
  border-color: #8f5cff;
  box-shadow: 0 0 10px rgba(143, 92, 255, 0.35);
}

.advisor-result-row img {
  width: 34px;
  height: 34px;
  object-fit: contain;
  flex: 0 0 34px;
}

.advisor-result-info {
  flex: 1;
  min-width: 0;
}

.advisor-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-level {
  color: #bda2ff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-min {
  color: #8f7bbd;
  font-size: 11px;
  margin-top: 2px;
}

/* responsive */

@media screen and (max-width: 900px) {
  .enchant-ui {
    max-width: 850px;
    min-height: 520px;
  }

  .enchant-main {
    gap: 16px;
    padding: 10px 16px 20px 12px;
  }

  .enchant-left {
    min-width: 155px;
  }

  .enchant-heading {
    font-size: 42px;
    margin: 16px 0 22px 0;
  }

  .enchant-display-box {
    height: 165px;
  }

  .enchant-cost-box {
    height: 80px;
    font-size: 40px;
  }

  .enchant-button {
    height: 62px;
    font-size: 30px;
  }
}

@media screen and (max-width: 650px) {
  .enchant-ui {
    min-height: 0;
  }

  .enchant-main {
    flex-direction: column;
    align-items: center;

    padding: 12px;
    gap: 14px;
  }

  .enchant-left {
    width: 45%;
    max-width: 210px;
    min-width: 140px;
    flex: none;
  }

  .enchant-right {
    width: 100%;
  }

  .enchant-heading {
    text-align: center;
    font-size: 36px;
    margin: 8px 0 18px 0;
  }

  .enchant-display-box {
    height: 145px;
  }

  .enchant-line {
    margin: 20px 0;
  }

  .enchant-cost-box {
    height: 75px;
    font-size: 34px;
  }

  .enchant-button {
    width: 80%;
    min-width: 0;
    height: 58px;
    font-size: 28px;
  }

  .rod-popup {
    padding: 14px;
  }

  .rod-popup-panel {
    width: 100%;
    padding: 16px;
  }

  .rod-popup-title {
    font-size: 28px;
  }

  .rod-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .rod-card {
    min-height: 155px;
    padding: 10px;
  }

  .rod-card img {
    max-width: 85px;
    max-height: 85px;
  }
}

@media screen and (max-width: 520px) {
  .enchant-menu-popup {
    width: calc(100% - 16px);
  }

  .enchant-advisor-layout {
    grid-template-columns: 88px 1fr;
    gap: 10px;
  }

  .enchant-advisor-rods {
    width: 88px;
  }

  .enchant-advisor-rod {
    width: 88px;
    height: 88px;
    min-height: 88px;
    font-size: 10px;
    padding: 6px;
  }

  .enchant-advisor-rod img,
  .enchant-advisor-rod .mw-file-element {
    max-width: 46px;
    max-height: 46px;
  }

  .advisor-rod-name {
    font-size: 10px;
  }

  .enchant-advisor-box {
    height: 75px;
    font-size: 20px;
  }
}

@media screen and (max-width: 420px) {
  .enchant-topbar {
    height: 28px;
    font-size: 15px;
  }

  .enchant-main {
    padding: 10px;
  }

  .enchant-left {
    width: 55%;
    min-width: 120px;
  }

  .enchant-heading {
    font-size: 30px;
  }

  .enchant-display-box {
    height: 120px;
  }

  .enchant-info-text {
    font-size: 22px;
  }

  .enchant-cost-box {
    height: 62px;
    font-size: 28px;
  }

  .enchant-button {
    width: 100%;
    height: 52px;
    font-size: 24px;
  }

  .enchant-result-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .enchant-result-card {
    min-height: 115px;
  }

  .enchant-result-card img {
    max-width: 46px;
    max-height: 46px;
  }

  .enchant-result-level {
    font-size: 16px;
  }

  .enchant-menu-popup {
    top: 42px;
    right: 8px;
    bottom: 14px;

    width: calc(100% - 16px);
    max-width: none;
  }

  .enchant-menu-title {
    font-size: 20px;
  }

  .enchant-menu-option {
    font-size: 16px;
    padding: 14px;
  }

  .enchant-menu-text {
    font-size: 13px;
  }
}

@media screen and (max-width: 360px) {
  .rod-popup-title {
    font-size: 24px;
  }

  .rod-card {
    min-height: 135px;
    font-size: 13px;
  }

  .rod-card img {
    max-width: 70px;
    max-height: 70px;
  }
}

@media screen and (max-width: 340px) {
  .enchant-heading {
    font-size: 26px;
  }

  .enchant-cost-box {
    font-size: 24px;
  }

  .enchant-button {
    font-size: 21px;
  }
}
.enchant-advisor-layout {
  display: grid;
  grid-template-columns: 110px 1fr;
  gap: 14px;
  align-items: start;
}

.enchant-advisor-rods {
  width: 110px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-advisor-rod {
  width: 110px;
  height: 110px;
  min-height: 110px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  padding: 8px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  color: #ffffff;
  text-align: center;

  cursor: pointer;
  user-select: none;
  box-sizing: border-box;

  overflow: hidden;
}

.enchant-advisor-rod:hover,
.enchant-advisor-rod.advisor-rod-active {
  background: #26124d;
  border-color: #9b6cff;
}

.advisor-rod-image {
  width: 64px;
  height: 64px;

  display: flex;
  align-items: center;
  justify-content: center;

  overflow: hidden;
  background: transparent;
  border: none;
  box-shadow: none;
}

.advisor-rod-image a,
.advisor-rod-image span,
.advisor-rod-image figure,
.advisor-rod-image .image,
.advisor-rod-image .mw-file-description,
.advisor-rod-image .mw-default-size {
  display: flex;
  align-items: center;
  justify-content: center;

  width: auto;
  height: auto;
  max-width: 64px;
  max-height: 64px;

  overflow: hidden !important;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;

  line-height: 0;
}

.advisor-rod-image img,
.advisor-rod-image .mw-file-element {
  display: block;

  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;

  margin: 0 auto;
}

.advisor-rod-name {
  width: 100%;

  color: #ffffff;
  font-size: 11px;
  line-height: 1.1;
  text-align: center;
  font-weight: bold;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-ui {
  width: 100%;
  max-width: 1000px;
  min-height: 575px;
  margin: 0 auto;
  position: relative;

  background: #130b25;
  border: 2px solid #8f5cff;
  box-sizing: border-box;

  font-family: Arial, sans-serif;
  color: #ffffff;

  background-image:
    linear-gradient(
      135deg,
      rgba(140, 80, 255, 0.12) 0%,
      rgba(140, 80, 255, 0.12) 18%,
      transparent 18%,
      transparent 38%,
      rgba(140, 80, 255, 0.08) 38%,
      rgba(140, 80, 255, 0.08) 55%,
      transparent 55%
    );
}

.enchant-topbar {
  position: relative;
  z-index: 1000;

  height: 32px;
  background: #935cff;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 10px;
  box-sizing: border-box;

  font-size: 18px;
  font-weight: bold;
  letter-spacing: 1px;
}

.enchant-topbar-title {
  display: flex;
  align-items: center;
}

.enchant-title-icon {
  margin-right: 8px;
}

.enchant-main {
  display: flex;
  gap: 18px;

  padding: 10px 18px 22px 14px;
  box-sizing: border-box;
}

.enchant-left {
  width: 25%;
  max-width: 230px;
  min-width: 170px;
  flex: 0 0 25%;
}

.enchant-item-slot {
  position: relative;
  overflow: hidden;

  width: 100%;
  height: 0;
  padding-bottom: 100%;

  border: 1px solid #9b6cff;
  background: rgba(55, 30, 90, 0.35);

  box-sizing: border-box;
}

.enchant-right {
  flex: 1;
  min-width: 0;
}

.enchant-heading {
  font-size: 50px;
  font-weight: bold;
  line-height: 1;

  margin: 18px 0 26px 0;
}

.enchant-line {
  width: 100%;
  height: 1px;

  background: #8f5cff;
  margin: 26px 0;
}

.enchant-cost-box {
  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 48px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-fish-points-display {
  max-width: 100%;
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-button {
  width: 55%;
  max-width: 355px;
  min-width: 230px;
  height: 70px;

  margin: 22px auto 0 auto;

  background: #4b347a;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #130b25;
  font-size: 34px;
  font-weight: bold;

  box-sizing: border-box;
}

.enchant-open-picker {
  cursor: pointer;
}

.enchant-item-slot:hover,
.enchant-button:hover {
  outline: 2px solid #9b6cff;
}

/* selected rod image */

.enchant-selected-img {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  align-items: center;
  justify-content: center;
}

.enchant-selected-img img {
  max-width: 75%;
  max-height: 75%;
  width: auto;
  height: auto;
  transform: translateX(20px);
}

.enchant-ui.rod-normal .selected-normal,
.enchant-ui.rod-advanced .selected-advanced,
.enchant-ui.rod-momentum .selected-momentum,
.enchant-ui.rod-pistol .selected-pistol {
  display: flex;
}

/* headings */

.enchant-heading-normal,
.enchant-heading-advanced,
.enchant-heading-momentum,
.enchant-heading-pistol {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-default,
.enchant-ui.rod-advanced .enchant-heading-default,
.enchant-ui.rod-momentum .enchant-heading-default,
.enchant-ui.rod-pistol .enchant-heading-default {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-normal,
.enchant-ui.rod-advanced .enchant-heading-advanced,
.enchant-ui.rod-momentum .enchant-heading-momentum,
.enchant-ui.rod-pistol .enchant-heading-pistol {
  display: block;
}

/* rod popup */

.rod-popup {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 32px;
  bottom: 0;

  z-index: 100;

  align-items: center;
  justify-content: center;

  background: rgba(8, 4, 20, 0.72);
  box-sizing: border-box;
  padding: 24px;
}

.enchant-ui.rod-picker-open .rod-popup {
  display: flex;
}

.rod-popup-panel {
  width: 90%;
  max-width: 760px;

  background: #170d2f;
  border: 2px solid #8f5cff;
  box-shadow: 0 0 24px rgba(143, 92, 255, 0.35);

  padding: 24px;
  box-sizing: border-box;
}

.rod-popup-title {
  text-align: center;
  font-size: 36px;
  font-weight: bold;
  margin-bottom: 22px;
  color: #ffffff;
}

.rod-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}

.rod-card {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  min-height: 190px;
  padding: 14px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  text-align: center;
  box-sizing: border-box;

  cursor: pointer;
}

.rod-card:hover {
  background: #26124d;
  border-color: #9b6cff;
}

.rod-card img {
  max-width: 120px;
  max-height: 120px;
  width: auto;
  height: auto;
}

/* fish points input */

.enchant-points-input {
  width: 90%;
  background: transparent;
  border: none;
  outline: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;
}

.enchant-points-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.fish-points-error {
  border-color: #ff6666;
}

.fish-points-error .enchant-fish-points-display {
  color: #ff8888;
  font-size: 24px;
  font-style: normal;
}

/* enchant result display */

.enchant-display-box {
  width: 100%;
  height: 190px;

  background: rgba(82, 45, 120, 0.55);
  box-sizing: border-box;

  display: block;

  padding: 12px;

  overflow-y: auto;
  overflow-x: hidden;
}

.enchant-info-text {
  min-height: 100%;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #bda2ff;
  font-size: 30px;
  font-weight: bold;
  text-align: center;
}

.enchant-result-grid {
  display: none;
  width: 100%;

  grid-template-columns: repeat(auto-fit, minmax(90px, 1fr));
  gap: 10px;
}

.enchant-result-card {
  min-height: 130px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;

  text-align: center;
  box-sizing: border-box;
  padding: 8px;
}

.enchant-result-card img {
  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;
}

.enchant-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
  line-height: 1;
}

.enchant-result-level {
  color: #bda2ff;
  font-size: 18px;
  font-weight: bold;
}

/* enchant colors */

.enchant-bg-strength {
  background: #8c4368;
}

.enchant-bg-strength-plus {
  background: #871d50;
}

.enchant-bg-momentum {
  background: #5d8084;
}

.enchant-bg-momentum-plus {
  background: #387e73;
}

.enchant-bg-fortune {
  background: #406a98;
}

.enchant-bg-ultra {
  background: #8b4a43;
}

.enchant-bg-less-backfire {
  background: #463b53;
}

.enchant-bg-sharpshooter {
  background: #7f1397;
}

/* menu */

.enchant-menu-button {
  position: relative;
  z-index: 1001;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-width: 32px;
  min-height: 28px;

  color: #ffffff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
  user-select: none;
  pointer-events: auto;

  background: none;
  border: none;
  border-radius: 0;
}

.enchant-menu-button:hover {
  color: #d8c8ff;
}

.enchant-menu-popup {
  display: none;

  position: absolute;
  top: 46px;
  right: 12px;
  bottom: 18px;

  width: 520px;
  max-width: calc(100% - 20px);

  z-index: 1200;

  background: rgba(8, 4, 20, 0.96);
  border: 2px solid #8f5cff;
  border-radius: 16px;

  box-shadow: -8px 0 24px rgba(143, 92, 255, 0.35);

  padding: 14px 18px 18px 18px;
  box-sizing: border-box;

  overflow-y: auto;
  pointer-events: auto;
}

.enchant-ui.enchant-menu-open .enchant-menu-popup {
  display: block;
}

.enchant-menu-panel {
  min-height: 100%;

  display: flex;
  flex-direction: column;

  color: #ffffff;
}

.enchant-menu-title {
  color: #ffffff;
  font-size: 24px;
  font-weight: bold;

  margin-bottom: 10px;
}

.enchant-main-title {
  margin-bottom: 14px;
}

.menu-title-fish,
.menu-title-notation {
  display: none;
}

.enchant-menu-panel.show-fish .menu-title-fish {
  display: inline;
}

.enchant-menu-panel.show-notation .menu-title-notation {
  display: inline;
}

.enchant-menu-main,
.enchant-menu-options {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-menu-option {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 18px 16px;

  color: #ffffff;
  font-size: 18px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-option:hover {
  background: #21103f;
  border-color: #8f5cff;
}

.enchant-menu-page {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-main,
.enchant-menu-panel.show-notation .enchant-menu-main {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-page-fish,
.enchant-menu-panel.show-notation .enchant-menu-page-notation {
  display: block;
}

.enchant-menu-text {
  color: #ffffff;
  font-size: 14px;
  line-height: 1.35;
  overflow-wrap: anywhere;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px;
  box-sizing: border-box;
}

.enchant-notation-choice {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px 16px;
  margin-bottom: 10px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-notation-choice:hover {
  background: #140a24;
  border-color: #5b347f;
}

.enchant-notation-choice.notation-active {
  background: #21103f;
  border-color: #8f5cff;
  box-shadow: 0 0 12px rgba(143, 92, 255, 0.45);
}

.enchant-menu-back,
.enchant-menu-close {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 110px;
  min-width: 110px;

  margin-left: auto;
  margin-right: auto;

  padding: 8px 18px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 999px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-back {
  margin-top: 14px;
}

.enchant-menu-close {
  margin-top: 24px;
}

.enchant-menu-close:hover,
.enchant-menu-back:hover {
  background: #6d4ab0;
}

/* fish advisor */

.enchant-menu-page-fish {
  margin-top: 0;
}

.enchant-advisor-layout {
  display: grid;
  grid-template-columns: 110px 1fr;
  gap: 14px;
  align-items: start;

  margin-top: 0;
}

.enchant-advisor-rods {
  width: 110px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-advisor-rod {
  width: 110px;
  height: 110px;
  min-height: 110px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  padding: 8px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  color: #ffffff;
  font-size: 11px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
  box-sizing: border-box;

  overflow: hidden;
}

.enchant-advisor-rod:hover,
.enchant-advisor-rod.advisor-rod-active {
  background: #26124d;
  border-color: #9b6cff;
}

.advisor-rod-image {
  width: 64px;
  height: 64px;

  display: flex;
  align-items: center;
  justify-content: center;

  overflow: hidden;
  background: transparent;
  border: none;
  box-shadow: none;
}

.advisor-rod-image a,
.advisor-rod-image span,
.advisor-rod-image figure,
.advisor-rod-image .image,
.advisor-rod-image .mw-file-description,
.advisor-rod-image .mw-default-size {
  display: flex;
  align-items: center;
  justify-content: center;

  width: auto;
  height: auto;
  max-width: 64px;
  max-height: 64px;

  overflow: hidden !important;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;

  line-height: 0;
}

.advisor-rod-image img,
.advisor-rod-image .mw-file-element {
  display: block;

  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;

  margin: 0 auto;
}

.advisor-rod-name {
  width: 100%;

  color: #ffffff;
  font-size: 11px;
  line-height: 1.1;
  text-align: center;
  font-weight: bold;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-advisor-right {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-advisor-output {
  order: 1;

  width: 100%;
  min-height: 170px;
  max-height: 230px;

  margin-top: 0;
  padding: 14px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  color: #ffffff;
  font-size: 14px;
  line-height: 1.45;

  overflow-y: auto;
  overflow-x: hidden;

  box-sizing: border-box;
  white-space: normal;
}

.enchant-advisor-box {
  order: 2;

  width: 100%;
  height: 78px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 24px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-advisor-display {
  max-width: 100%;
  display: block;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;

  color: #6f4bb5;
}

.enchant-advisor-input {
  width: 90%;

  background: transparent;
  border: none;
  outline: none;
  box-shadow: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;

  margin: 0;
  padding: 0;

  overflow: hidden;
  box-sizing: border-box;
}

.enchant-advisor-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.enchant-advisor-check {
  order: 3;

  width: 100%;
  margin-top: 0;
  padding: 10px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 12px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;

  box-sizing: border-box;
}

.enchant-advisor-check:hover {
  background: #6d4ab0;
}

/* fish advisor result rows */

.advisor-result-title {
  font-size: 15px;
  font-weight: bold;
  color: #ffffff;
  margin-bottom: 10px;
}

.advisor-result-row {
  background: #130b25;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 10px;
  margin-bottom: 8px;

  display: flex;
  gap: 8px;
  align-items: center;

  box-sizing: border-box;
}

.advisor-result-row.advisor-best {
  border-color: #8f5cff;
  box-shadow: 0 0 10px rgba(143, 92, 255, 0.35);
}

.advisor-result-row img {
  width: 34px;
  height: 34px;
  object-fit: contain;
  flex: 0 0 34px;
}

.advisor-result-info {
  flex: 1;
  min-width: 0;
}

.advisor-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-level {
  color: #bda2ff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-min {
  color: #8f7bbd;
  font-size: 11px;
  margin-top: 2px;
}

/* responsive */

@media screen and (max-width: 900px) {
  .enchant-ui {
    max-width: 850px;
    min-height: 520px;
  }

  .enchant-main {
    gap: 16px;
    padding: 10px 16px 20px 12px;
  }

  .enchant-left {
    min-width: 155px;
  }

  .enchant-heading {
    font-size: 42px;
    margin: 16px 0 22px 0;
  }

  .enchant-display-box {
    height: 165px;
  }

  .enchant-cost-box {
    height: 80px;
    font-size: 40px;
  }

  .enchant-button {
    height: 62px;
    font-size: 30px;
  }
}

@media screen and (max-width: 650px) {
  .enchant-ui {
    min-height: 0;
  }

  .enchant-main {
    flex-direction: column;
    align-items: center;

    padding: 12px;
    gap: 14px;
  }

  .enchant-left {
    width: 45%;
    max-width: 210px;
    min-width: 140px;
    flex: none;
  }

  .enchant-right {
    width: 100%;
  }

  .enchant-heading {
    text-align: center;
    font-size: 36px;
    margin: 8px 0 18px 0;
  }

  .enchant-display-box {
    height: 145px;
  }

  .enchant-line {
    margin: 20px 0;
  }

  .enchant-cost-box {
    height: 75px;
    font-size: 34px;
  }

  .enchant-button {
    width: 80%;
    min-width: 0;
    height: 58px;
    font-size: 28px;
  }

  .rod-popup {
    padding: 14px;
  }

  .rod-popup-panel {
    width: 100%;
    padding: 16px;
  }

  .rod-popup-title {
    font-size: 28px;
  }

  .rod-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .rod-card {
    min-height: 155px;
    padding: 10px;
  }

  .rod-card img {
    max-width: 85px;
    max-height: 85px;
  }
}

@media screen and (max-width: 520px) {
  .enchant-menu-popup {
    width: calc(100% - 16px);
  }

  .enchant-advisor-layout {
    grid-template-columns: 88px 1fr;
    gap: 10px;
  }

  .enchant-advisor-rods {
    width: 88px;
  }

  .enchant-advisor-rod {
    width: 88px;
    height: 88px;
    min-height: 88px;
    font-size: 10px;
    padding: 6px;
  }

  .advisor-rod-image {
    width: 48px;
    height: 48px;
  }

  .advisor-rod-image img,
  .advisor-rod-image .mw-file-element {
    max-width: 46px;
    max-height: 46px;
  }

  .advisor-rod-name {
    font-size: 10px;
  }

  .enchant-advisor-box {
    height: 68px;
    font-size: 20px;
  }
}

@media screen and (max-width: 420px) {
  .enchant-topbar {
    height: 28px;
    font-size: 15px;
  }

  .enchant-main {
    padding: 10px;
  }

  .enchant-left {
    width: 55%;
    min-width: 120px;
  }

  .enchant-heading {
    font-size: 30px;
  }

  .enchant-display-box {
    height: 120px;
  }

  .enchant-info-text {
    font-size: 22px;
  }

  .enchant-cost-box {
    height: 62px;
    font-size: 28px;
  }

  .enchant-button {
    width: 100%;
    height: 52px;
    font-size: 24px;
  }

  .enchant-result-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .enchant-result-card {
    min-height: 115px;
  }

  .enchant-result-card img {
    max-width: 46px;
    max-height: 46px;
  }

  .enchant-result-level {
    font-size: 16px;
  }

  .enchant-menu-popup {
    top: 42px;
    right: 8px;
    bottom: 14px;

    width: calc(100% - 16px);
    max-width: none;
  }

  .enchant-menu-title {
    font-size: 20px;
  }

  .enchant-menu-option {
    font-size: 16px;
    padding: 14px;
  }

  .enchant-menu-text {
    font-size: 13px;
  }
}

@media screen and (max-width: 360px) {
  .rod-popup-title {
    font-size: 24px;
  }

  .rod-card {
    min-height: 135px;
    font-size: 13px;
  }

  .rod-card img {
    max-width: 70px;
    max-height: 70px;
  }
}

@media screen and (max-width: 340px) {
  .enchant-heading {
    font-size: 26px;
  }

  .enchant-cost-box {
    font-size: 24px;
  }

  .enchant-button {
    font-size: 21px;
  }
}

.enchant-ui {
  width: 100%;
  max-width: 1000px;
  min-height: 575px;
  margin: 0 auto;
  position: relative;

  background: #130b25;
  border: 2px solid #8f5cff;
  box-sizing: border-box;

  font-family: Arial, sans-serif;
  color: #ffffff;

  background-image:
    linear-gradient(
      135deg,
      rgba(140, 80, 255, 0.12) 0%,
      rgba(140, 80, 255, 0.12) 18%,
      transparent 18%,
      transparent 38%,
      rgba(140, 80, 255, 0.08) 38%,
      rgba(140, 80, 255, 0.08) 55%,
      transparent 55%
    );
}

.enchant-topbar {
  position: relative;
  z-index: 1000;

  height: 32px;
  background: #935cff;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 10px;
  box-sizing: border-box;

  font-size: 18px;
  font-weight: bold;
  letter-spacing: 1px;
}

.enchant-topbar-title {
  display: flex;
  align-items: center;
}

.enchant-title-icon {
  margin-right: 8px;
}

.enchant-main {
  display: flex;
  gap: 18px;

  padding: 10px 18px 22px 14px;
  box-sizing: border-box;
}

.enchant-left {
  width: 25%;
  max-width: 230px;
  min-width: 170px;
  flex: 0 0 25%;
}

.enchant-item-slot {
  position: relative;
  overflow: hidden;

  width: 100%;
  height: 0;
  padding-bottom: 100%;

  border: 1px solid #9b6cff;
  background: rgba(55, 30, 90, 0.35);

  box-sizing: border-box;
}

.enchant-right {
  flex: 1;
  min-width: 0;
}

.enchant-heading {
  font-size: 50px;
  font-weight: bold;
  line-height: 1;

  margin: 18px 0 26px 0;
}

.enchant-line {
  width: 100%;
  height: 1px;

  background: #8f5cff;
  margin: 26px 0;
}

.enchant-cost-box {
  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 48px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-fish-points-display {
  max-width: 100%;
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-button {
  width: 55%;
  max-width: 355px;
  min-width: 230px;
  height: 70px;

  margin: 22px auto 0 auto;

  background: #4b347a;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #130b25;
  font-size: 34px;
  font-weight: bold;

  box-sizing: border-box;
}

.enchant-open-picker {
  cursor: pointer;
}

.enchant-item-slot:hover,
.enchant-button:hover {
  outline: 2px solid #9b6cff;
}

/* selected rod image */

.enchant-selected-img {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  align-items: center;
  justify-content: center;
}

.enchant-selected-img img {
  max-width: 75%;
  max-height: 75%;
  width: auto;
  height: auto;
  transform: translateX(20px);
}

.enchant-ui.rod-normal .selected-normal,
.enchant-ui.rod-advanced .selected-advanced,
.enchant-ui.rod-momentum .selected-momentum,
.enchant-ui.rod-pistol .selected-pistol {
  display: flex;
}

/* headings */

.enchant-heading-normal,
.enchant-heading-advanced,
.enchant-heading-momentum,
.enchant-heading-pistol {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-default,
.enchant-ui.rod-advanced .enchant-heading-default,
.enchant-ui.rod-momentum .enchant-heading-default,
.enchant-ui.rod-pistol .enchant-heading-default {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-normal,
.enchant-ui.rod-advanced .enchant-heading-advanced,
.enchant-ui.rod-momentum .enchant-heading-momentum,
.enchant-ui.rod-pistol .enchant-heading-pistol {
  display: block;
}

/* rod popup */

.rod-popup {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 32px;
  bottom: 0;

  z-index: 100;

  align-items: center;
  justify-content: center;

  background: rgba(8, 4, 20, 0.72);
  box-sizing: border-box;
  padding: 24px;
}

.enchant-ui.rod-picker-open .rod-popup {
  display: flex;
}

.rod-popup-panel {
  width: 90%;
  max-width: 760px;

  background: #170d2f;
  border: 2px solid #8f5cff;
  box-shadow: 0 0 24px rgba(143, 92, 255, 0.35);

  padding: 24px;
  box-sizing: border-box;
}

.rod-popup-title {
  text-align: center;
  font-size: 36px;
  font-weight: bold;
  margin-bottom: 22px;
  color: #ffffff;
}

.rod-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}

.rod-card {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  min-height: 190px;
  padding: 14px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  text-align: center;
  box-sizing: border-box;

  cursor: pointer;
}

.rod-card:hover {
  background: #26124d;
  border-color: #9b6cff;
}

.rod-card img {
  max-width: 120px;
  max-height: 120px;
  width: auto;
  height: auto;
}

/* fish points input */

.enchant-points-input {
  width: 90%;
  background: transparent;
  border: none;
  outline: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;
}

.enchant-points-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.fish-points-error {
  border-color: #ff6666;
}

.fish-points-error .enchant-fish-points-display {
  color: #ff8888;
  font-size: 24px;
  font-style: normal;
}

/* enchant result display */

.enchant-display-box {
  width: 100%;
  height: 190px;

  background: rgba(82, 45, 120, 0.55);
  box-sizing: border-box;

  display: block;

  padding: 12px;

  overflow-y: auto;
  overflow-x: hidden;
}

.enchant-info-text {
  min-height: 100%;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #bda2ff;
  font-size: 30px;
  font-weight: bold;
  text-align: center;
}

.enchant-result-grid {
  display: none;
  width: 100%;

  grid-template-columns: repeat(auto-fit, minmax(90px, 1fr));
  gap: 10px;
}

.enchant-result-card {
  min-height: 130px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;

  text-align: center;
  box-sizing: border-box;
  padding: 8px;
}

.enchant-result-card img {
  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;
}

.enchant-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
  line-height: 1;
}

.enchant-result-level {
  color: #bda2ff;
  font-size: 18px;
  font-weight: bold;
}

/* enchant colors */

.enchant-bg-strength {
  background: #8c4368;
}

.enchant-bg-strength-plus {
  background: #871d50;
}

.enchant-bg-momentum {
  background: #5d8084;
}

.enchant-bg-momentum-plus {
  background: #387e73;
}

.enchant-bg-fortune {
  background: #406a98;
}

.enchant-bg-ultra {
  background: #8b4a43;
}

.enchant-bg-less-backfire {
  background: #463b53;
}

.enchant-bg-sharpshooter {
  background: #7f1397;
}

/* menu */

.enchant-menu-button {
  position: relative;
  z-index: 1001;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-width: 32px;
  min-height: 28px;

  color: #ffffff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
  user-select: none;
  pointer-events: auto;

  background: none;
  border: none;
  border-radius: 0;
}

.enchant-menu-button:hover {
  color: #d8c8ff;
}

.enchant-menu-popup {
  display: none;

  position: absolute;
  top: 46px;
  right: 12px;
  bottom: 18px;

  width: 520px;
  max-width: calc(100% - 20px);

  z-index: 1200;

  background: rgba(8, 4, 20, 0.96);
  border: 2px solid #8f5cff;
  border-radius: 16px;

  box-shadow: -8px 0 24px rgba(143, 92, 255, 0.35);

  padding: 14px 18px 18px 18px;
  box-sizing: border-box;

  overflow-y: auto;
  pointer-events: auto;
}

.enchant-ui.enchant-menu-open .enchant-menu-popup {
  display: block;
}

.enchant-menu-panel {
  min-height: 100%;

  display: flex;
  flex-direction: column;

  color: #ffffff;
}

.enchant-menu-title {
  color: #ffffff;
  font-size: 24px;
  font-weight: bold;

  margin-bottom: 10px;
}

.enchant-main-title {
  margin-bottom: 14px;
}

.menu-title-fish,
.menu-title-notation {
  display: none;
}

.enchant-menu-panel.show-fish .menu-title-fish {
  display: inline;
}

.enchant-menu-panel.show-notation .menu-title-notation {
  display: inline;
}

.enchant-menu-main,
.enchant-menu-options {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-menu-option {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 18px 16px;

  color: #ffffff;
  font-size: 18px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-option:hover {
  background: #21103f;
  border-color: #8f5cff;
}

.enchant-menu-page {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-main,
.enchant-menu-panel.show-notation .enchant-menu-main {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-page-fish,
.enchant-menu-panel.show-notation .enchant-menu-page-notation {
  display: block;
}

.enchant-menu-text {
  color: #ffffff;
  font-size: 14px;
  line-height: 1.35;
  overflow-wrap: anywhere;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px;
  box-sizing: border-box;
}

.enchant-notation-choice {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px 16px;
  margin-bottom: 10px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-notation-choice:hover {
  background: #140a24;
  border-color: #5b347f;
}

.enchant-notation-choice.notation-active {
  background: #21103f;
  border-color: #8f5cff;
  box-shadow: 0 0 12px rgba(143, 92, 255, 0.45);
}

.enchant-menu-back,
.enchant-menu-close {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 110px;
  min-width: 110px;

  margin-left: auto;
  margin-right: auto;

  padding: 8px 18px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 999px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-back {
  margin-top: 14px;
}

.enchant-menu-close {
  margin-top: 24px;
}

.enchant-menu-close:hover,
.enchant-menu-back:hover {
  background: #6d4ab0;
}

/* fish advisor */

.enchant-menu-page-fish {
  margin-top: 0;
}

.enchant-advisor-layout {
  display: grid;
  grid-template-columns: 110px 1fr;
  gap: 14px;
  align-items: start;

  margin-top: 0;
}

.enchant-advisor-rods {
  width: 110px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-advisor-rod {
  width: 110px;
  height: 110px;
  min-height: 110px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  padding: 8px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  color: #ffffff;
  font-size: 11px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
  box-sizing: border-box;

  overflow: hidden;
}

.enchant-advisor-rod:hover,
.enchant-advisor-rod.advisor-rod-active {
  background: #26124d;
  border-color: #9b6cff;
}

.advisor-rod-image {
  width: 64px;
  height: 64px;

  display: flex;
  align-items: center;
  justify-content: center;

  overflow: hidden;
  background: transparent;
  border: none;
  box-shadow: none;
}

.advisor-rod-image a,
.advisor-rod-image span,
.advisor-rod-image figure,
.advisor-rod-image .image,
.advisor-rod-image .mw-file-description,
.advisor-rod-image .mw-default-size {
  display: flex;
  align-items: center;
  justify-content: center;

  width: auto;
  height: auto;
  max-width: 64px;
  max-height: 64px;

  overflow: hidden !important;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;

  line-height: 0;
}

.advisor-rod-image img,
.advisor-rod-image .mw-file-element {
  display: block;

  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;

  margin: 0 auto;
}

.advisor-rod-name {
  width: 100%;

  color: #ffffff;
  font-size: 11px;
  line-height: 1.1;
  text-align: center;
  font-weight: bold;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-advisor-right {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-advisor-output {
  order: 1;

  width: 100%;
  min-height: 170px;
  max-height: 230px;

  margin-top: 0;
  padding: 14px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  color: #ffffff;
  font-size: 14px;
  line-height: 1.45;

  overflow-y: auto;
  overflow-x: hidden;

  box-sizing: border-box;
  white-space: normal;
}

.enchant-advisor-box {
  order: 2;

  width: 100%;
  height: 78px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 24px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-advisor-display {
  max-width: 100%;
  display: block;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;

  color: #6f4bb5;
}

.enchant-advisor-input {
  width: 90%;

  background: transparent;
  border: none;
  outline: none;
  box-shadow: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;

  margin: 0;
  padding: 0;

  overflow: hidden;
  box-sizing: border-box;
}

.enchant-advisor-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.enchant-advisor-check {
  order: 3;

  width: 100%;
  margin-top: 0;
  padding: 10px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 12px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;

  box-sizing: border-box;
}

.enchant-advisor-check:hover {
  background: #6d4ab0;
}

/* fish advisor result rows */

.advisor-result-title {
  font-size: 15px;
  font-weight: bold;
  color: #ffffff;
  margin-bottom: 10px;
}

.advisor-result-row {
  background: #130b25;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 10px;
  margin-bottom: 8px;

  display: flex;
  gap: 8px;
  align-items: center;

  box-sizing: border-box;
}

.advisor-result-row.advisor-best {
  border-color: #8f5cff;
  box-shadow: 0 0 10px rgba(143, 92, 255, 0.35);
}

.advisor-result-row img {
  width: 34px;
  height: 34px;
  object-fit: contain;
  flex: 0 0 34px;
}

.advisor-result-info {
  flex: 1;
  min-width: 0;
}

.advisor-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-level {
  color: #bda2ff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-min {
  color: #8f7bbd;
  font-size: 11px;
  margin-top: 2px;
}

/* responsive */

@media screen and (max-width: 900px) {
  .enchant-ui {
    max-width: 850px;
    min-height: 520px;
  }

  .enchant-main {
    gap: 16px;
    padding: 10px 16px 20px 12px;
  }

  .enchant-left {
    min-width: 155px;
  }

  .enchant-heading {
    font-size: 42px;
    margin: 16px 0 22px 0;
  }

  .enchant-display-box {
    height: 165px;
  }

  .enchant-cost-box {
    height: 80px;
    font-size: 40px;
  }

  .enchant-button {
    height: 62px;
    font-size: 30px;
  }
}

@media screen and (max-width: 650px) {
  .enchant-ui {
    min-height: 0;
  }

  .enchant-main {
    flex-direction: column;
    align-items: center;

    padding: 12px;
    gap: 14px;
  }

  .enchant-left {
    width: 45%;
    max-width: 210px;
    min-width: 140px;
    flex: none;
  }

  .enchant-right {
    width: 100%;
  }

  .enchant-heading {
    text-align: center;
    font-size: 36px;
    margin: 8px 0 18px 0;
  }

  .enchant-display-box {
    height: 145px;
  }

  .enchant-line {
    margin: 20px 0;
  }

  .enchant-cost-box {
    height: 75px;
    font-size: 34px;
  }

  .enchant-button {
    width: 80%;
    min-width: 0;
    height: 58px;
    font-size: 28px;
  }

  .rod-popup {
    padding: 14px;
  }

  .rod-popup-panel {
    width: 100%;
    padding: 16px;
  }

  .rod-popup-title {
    font-size: 28px;
  }

  .rod-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .rod-card {
    min-height: 155px;
    padding: 10px;
  }

  .rod-card img {
    max-width: 85px;
    max-height: 85px;
  }
}

@media screen and (max-width: 520px) {
  .enchant-menu-popup {
    width: calc(100% - 16px);
  }

  .enchant-advisor-layout {
    grid-template-columns: 88px 1fr;
    gap: 10px;
  }

  .enchant-advisor-rods {
    width: 88px;
  }

  .enchant-advisor-rod {
    width: 88px;
    height: 88px;
    min-height: 88px;
    font-size: 10px;
    padding: 6px;
  }

  .advisor-rod-image {
    width: 48px;
    height: 48px;
  }

  .advisor-rod-image img,
  .advisor-rod-image .mw-file-element {
    max-width: 46px;
    max-height: 46px;
  }

  .advisor-rod-name {
    font-size: 10px;
  }

  .enchant-advisor-box {
    height: 68px;
    font-size: 20px;
  }
}

@media screen and (max-width: 420px) {
  .enchant-topbar {
    height: 28px;
    font-size: 15px;
  }

  .enchant-main {
    padding: 10px;
  }

  .enchant-left {
    width: 55%;
    min-width: 120px;
  }

  .enchant-heading {
    font-size: 30px;
  }

  .enchant-display-box {
    height: 120px;
  }

  .enchant-info-text {
    font-size: 22px;
  }

  .enchant-cost-box {
    height: 62px;
    font-size: 28px;
  }

  .enchant-button {
    width: 100%;
    height: 52px;
    font-size: 24px;
  }

  .enchant-result-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .enchant-result-card {
    min-height: 115px;
  }

  .enchant-result-card img {
    max-width: 46px;
    max-height: 46px;
  }

  .enchant-result-level {
    font-size: 16px;
  }

  .enchant-menu-popup {
    top: 42px;
    right: 8px;
    bottom: 14px;

    width: calc(100% - 16px);
    max-width: none;
  }

  .enchant-menu-title {
    font-size: 20px;
  }

  .enchant-menu-option {
    font-size: 16px;
    padding: 14px;
  }

  .enchant-menu-text {
    font-size: 13px;
  }
}

@media screen and (max-width: 360px) {
  .rod-popup-title {
    font-size: 24px;
  }

  .rod-card {
    min-height: 135px;
    font-size: 13px;
  }

  .rod-card img {
    max-width: 70px;
    max-height: 70px;
  }
}

@media screen and (max-width: 340px) {
  .enchant-heading {
    font-size: 26px;
  }

  .enchant-cost-box {
    font-size: 24px;
  }

  .enchant-button {
    font-size: 21px;
  }
}
.enchant-advisor-combo-list {
  order: 2;

  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;

  width: 100%;
}

.enchant-advisor-combo-button {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 10px 8px;

  color: #ffffff;
  font-size: 12px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;

  box-sizing: border-box;
}

.enchant-advisor-combo-button:hover,
.enchant-advisor-combo-button.combo-active {
  background: #26124d;
  border-color: #9b6cff;
  box-shadow: 0 0 8px rgba(143, 92, 255, 0.35);
}

.enchant-advisor-level-box {
  order: 3;

  width: 100%;
  height: 78px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 24px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-advisor-level-display {
  max-width: 100%;
  display: block;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;

  color: #6f4bb5;
}

.enchant-advisor-level-input {
  width: 90%;

  background: transparent;
  border: none;
  outline: none;
  box-shadow: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;

  margin: 0;
  padding: 0;

  overflow: hidden;
  box-sizing: border-box;
}

.enchant-advisor-level-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.enchant-advisor-check {
  order: 4;
}

.enchant-ui {
  width: 100%;
  max-width: 1000px;
  min-height: 575px;
  margin: 0 auto;
  position: relative;
  background: #130b25;
  border: 2px solid #8f5cff;
  box-sizing: border-box;
  font-family: Arial, sans-serif;
  color: #ffffff;

  background-image:
    linear-gradient(
      135deg,
      rgba(140, 80, 255, 0.12) 0%,
      rgba(140, 80, 255, 0.12) 18%,
      transparent 18%,
      transparent 38%,
      rgba(140, 80, 255, 0.08) 38%,
      rgba(140, 80, 255, 0.08) 55%,
      transparent 55%
    );
}

/* top bar */

.enchant-topbar {
  position: relative;
  z-index: 1000;
  height: 32px;
  background: #935cff;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 10px;
  box-sizing: border-box;

  font-size: 18px;
  font-weight: bold;
  letter-spacing: 1px;
}

.enchant-topbar-title {
  display: flex;
  align-items: center;
}

.enchant-title-icon {
  margin-right: 8px;
}

/* main layout */

.enchant-main {
  display: flex;
  gap: 18px;
  padding: 10px 18px 22px 14px;
  box-sizing: border-box;
}

.enchant-left {
  width: 25%;
  max-width: 230px;
  min-width: 170px;
  flex: 0 0 25%;
}

.enchant-right {
  flex: 1;
  min-width: 0;
}

.enchant-item-slot {
  position: relative;
  overflow: hidden;
  width: 100%;
  height: 0;
  padding-bottom: 100%;
  border: 1px solid #9b6cff;
  background: rgba(55, 30, 90, 0.35);
  box-sizing: border-box;
}

.enchant-item-slot:hover,
.enchant-button:hover {
  outline: 2px solid #9b6cff;
}

/* selected rod image */

.enchant-selected-img {
  display: none;
  position: absolute;
  inset: 0;
  align-items: center;
  justify-content: center;
}

.enchant-selected-img img {
  max-width: 75%;
  max-height: 75%;
  width: auto;
  height: auto;
  transform: translateX(20px);
}

.enchant-ui.rod-normal .selected-normal,
.enchant-ui.rod-advanced .selected-advanced,
.enchant-ui.rod-momentum .selected-momentum,
.enchant-ui.rod-pistol .selected-pistol {
  display: flex;
}

/* headings */

.enchant-heading {
  font-size: 50px;
  font-weight: bold;
  line-height: 1;
  margin: 18px 0 26px 0;
}

.enchant-heading-normal,
.enchant-heading-advanced,
.enchant-heading-momentum,
.enchant-heading-pistol {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-default,
.enchant-ui.rod-advanced .enchant-heading-default,
.enchant-ui.rod-momentum .enchant-heading-default,
.enchant-ui.rod-pistol .enchant-heading-default {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-normal,
.enchant-ui.rod-advanced .enchant-heading-advanced,
.enchant-ui.rod-momentum .enchant-heading-momentum,
.enchant-ui.rod-pistol .enchant-heading-pistol {
  display: block;
}

/* main enchant display */

.enchant-display-box {
  width: 100%;
  height: 190px;
  background: rgba(82, 45, 120, 0.55);
  box-sizing: border-box;
  display: block;
  padding: 12px;
  overflow-y: auto;
  overflow-x: hidden;
}

.enchant-info-text {
  min-height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #bda2ff;
  font-size: 30px;
  font-weight: bold;
  text-align: center;
}

.enchant-result-grid {
  display: none;
  width: 100%;
  grid-template-columns: repeat(auto-fit, minmax(90px, 1fr));
  gap: 10px;
}

.enchant-result-card {
  min-height: 130px;
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;

  text-align: center;
  box-sizing: border-box;
  padding: 8px;
}

.enchant-result-card img {
  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;
}

.enchant-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
  line-height: 1;
}

.enchant-result-level {
  color: #bda2ff;
  font-size: 18px;
  font-weight: bold;
}

/* fish point input */

.enchant-line {
  width: 100%;
  height: 1px;
  background: #8f5cff;
  margin: 26px 0;
}

.enchant-cost-box {
  width: 100%;
  height: 90px;
  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 48px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;
  cursor: text;
}

.enchant-fish-points-display {
  max-width: 100%;
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-points-input {
  width: 90%;
  background: transparent;
  border: none;
  outline: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;
  font-family: inherit;
}

.enchant-points-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.fish-points-error {
  border-color: #ff6666;
}

.fish-points-error .enchant-fish-points-display {
  color: #ff8888;
  font-size: 24px;
  font-style: normal;
}

.enchant-button {
  width: 55%;
  max-width: 355px;
  min-width: 230px;
  height: 70px;
  margin: 22px auto 0 auto;
  background: #4b347a;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #130b25;
  font-size: 34px;
  font-weight: bold;
  box-sizing: border-box;
}

.enchant-open-picker {
  cursor: pointer;
}

/* enchant colors */

.enchant-bg-strength {
  background: #8c4368;
}

.enchant-bg-strength-plus {
  background: #871d50;
}

.enchant-bg-momentum {
  background: #5d8084;
}

.enchant-bg-momentum-plus {
  background: #387e73;
}

.enchant-bg-fortune {
  background: #406a98;
}

.enchant-bg-ultra {
  background: #8b4a43;
}

.enchant-bg-less-backfire {
  background: #463b53;
}

.enchant-bg-sharpshooter {
  background: #7f1397;
}

/* rod popup */

.rod-popup {
  display: none;
  position: absolute;
  left: 0;
  right: 0;
  top: 32px;
  bottom: 0;
  z-index: 100;

  align-items: center;
  justify-content: center;

  background: rgba(8, 4, 20, 0.72);
  box-sizing: border-box;
  padding: 24px;
}

.enchant-ui.rod-picker-open .rod-popup {
  display: flex;
}

.rod-popup-panel {
  width: 90%;
  max-width: 760px;
  background: #170d2f;
  border: 2px solid #8f5cff;
  box-shadow: 0 0 24px rgba(143, 92, 255, 0.35);
  padding: 24px;
  box-sizing: border-box;
}

.rod-popup-title {
  text-align: center;
  font-size: 36px;
  font-weight: bold;
  margin-bottom: 22px;
  color: #ffffff;
}

.rod-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}

.rod-card {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;
  min-height: 190px;
  padding: 14px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  text-align: center;
  box-sizing: border-box;
  cursor: pointer;
}

.rod-card:hover {
  background: #26124d;
  border-color: #9b6cff;
}

.rod-card img {
  max-width: 120px;
  max-height: 120px;
  width: auto;
  height: auto;
}

/* menu */

.enchant-menu-button {
  position: relative;
  z-index: 1001;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-width: 32px;
  min-height: 28px;

  color: #ffffff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
  user-select: none;
  pointer-events: auto;

  background: none;
  border: none;
  border-radius: 0;
}

.enchant-menu-button:hover {
  color: #d8c8ff;
}

.enchant-menu-popup {
  display: none;
  position: absolute;
  top: 46px;
  right: 12px;
  bottom: 18px;

  width: 520px;
  max-width: calc(100% - 20px);

  z-index: 1200;

  background: rgba(8, 4, 20, 0.96);
  border: 2px solid #8f5cff;
  border-radius: 16px;
  box-shadow: -8px 0 24px rgba(143, 92, 255, 0.35);

  padding: 14px 18px 18px 18px;
  box-sizing: border-box;

  overflow-y: auto;
  pointer-events: auto;
}

.enchant-ui.enchant-menu-open .enchant-menu-popup {
  display: block;
}

.enchant-menu-panel {
  min-height: 100%;
  display: flex;
  flex-direction: column;
  color: #ffffff;
}

.enchant-menu-title {
  color: #ffffff;
  font-size: 24px;
  font-weight: bold;
  margin-bottom: 10px;
}

.enchant-main-title {
  margin-bottom: 14px;
}

.menu-title-fish,
.menu-title-notation {
  display: none;
}

.enchant-menu-panel.show-fish .menu-title-fish,
.enchant-menu-panel.show-notation .menu-title-notation {
  display: inline;
}

.enchant-menu-main {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-menu-option {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 18px 16px;

  color: #ffffff;
  font-size: 18px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-option:hover {
  background: #21103f;
  border-color: #8f5cff;
}

.enchant-menu-page {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-main,
.enchant-menu-panel.show-notation .enchant-menu-main {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-page-fish,
.enchant-menu-panel.show-notation .enchant-menu-page-notation {
  display: block;
}

.enchant-notation-choice {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px 16px;
  margin-bottom: 10px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-notation-choice:hover {
  background: #140a24;
  border-color: #5b347f;
}

.enchant-notation-choice.notation-active {
  background: #21103f;
  border-color: #8f5cff;
  box-shadow: 0 0 12px rgba(143, 92, 255, 0.45);
}

.enchant-menu-back,
.enchant-menu-close {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 110px;
  min-width: 110px;

  margin-left: auto;
  margin-right: auto;

  padding: 8px 18px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 999px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-back {
  margin-top: 14px;
}

.enchant-menu-close {
  margin-top: 24px;
}

.enchant-menu-close:hover,
.enchant-menu-back:hover {
  background: #6d4ab0;
}

/* fish advisor */

.enchant-menu-page-fish {
  margin-top: 0;
}

.enchant-advisor-layout {
  display: grid;
  grid-template-columns: 110px 1fr;
  gap: 14px;
  align-items: start;
  margin-top: 0;
}

.enchant-advisor-rods {
  width: 110px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-advisor-rod {
  width: 110px;
  height: 110px;
  min-height: 110px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  padding: 8px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  color: #ffffff;
  font-size: 11px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
  box-sizing: border-box;
  overflow: hidden;
}

.enchant-advisor-rod:hover,
.enchant-advisor-rod.advisor-rod-active {
  background: #26124d;
  border-color: #9b6cff;
}

.advisor-rod-image {
  width: 64px;
  height: 64px;

  display: flex;
  align-items: center;
  justify-content: center;

  overflow: hidden;
  background: transparent;
  border: none;
  box-shadow: none;
}

.advisor-rod-image a,
.advisor-rod-image span,
.advisor-rod-image figure,
.advisor-rod-image .image,
.advisor-rod-image .mw-file-description,
.advisor-rod-image .mw-default-size {
  display: flex;
  align-items: center;
  justify-content: center;

  width: auto;
  height: auto;
  max-width: 64px;
  max-height: 64px;

  overflow: hidden !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;

  line-height: 0;
}

.advisor-rod-image img,
.advisor-rod-image .mw-file-element {
  display: block;

  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;

  margin: 0 auto;
}

.advisor-rod-name {
  width: 100%;

  color: #ffffff;
  font-size: 11px;
  line-height: 1.1;
  text-align: center;
  font-weight: bold;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-advisor-right {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-advisor-output {
  order: 1;

  width: 100%;
  min-height: 170px;
  max-height: 230px;

  margin-top: 0;
  padding: 14px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  color: #ffffff;
  font-size: 14px;
  line-height: 1.45;

  overflow-y: auto;
  overflow-x: hidden;

  box-sizing: border-box;
  white-space: normal;
}

.enchant-advisor-combo-list {
  order: 2;

  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;

  width: 100%;
}

.enchant-advisor-combo-button {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 10px 8px;

  color: #ffffff;
  font-size: 12px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
  box-sizing: border-box;
}

.enchant-advisor-combo-button:hover,
.enchant-advisor-combo-button.combo-active {
  background: #26124d;
  border-color: #9b6cff;
  box-shadow: 0 0 8px rgba(143, 92, 255, 0.35);
}

.enchant-advisor-level-box {
  order: 3;

  width: 100%;
  height: 78px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 24px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-advisor-level-display {
  max-width: 100%;
  display: block;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;

  color: #6f4bb5;
}

.enchant-advisor-level-input {
  width: 90%;

  background: transparent;
  border: none;
  outline: none;
  box-shadow: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;

  margin: 0;
  padding: 0;

  overflow: hidden;
  box-sizing: border-box;
}

.enchant-advisor-level-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.enchant-advisor-check {
  order: 4;

  width: 100%;
  margin-top: 0;
  padding: 10px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 12px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
  box-sizing: border-box;
}

.enchant-advisor-check:hover {
  background: #6d4ab0;
}

/* fish advisor result rows */

.advisor-result-title {
  font-size: 15px;
  font-weight: bold;
  color: #ffffff;
  margin-bottom: 10px;
}

.advisor-result-row {
  background: #130b25;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 10px;
  margin-bottom: 8px;

  display: flex;
  gap: 8px;
  align-items: center;

  box-sizing: border-box;
}

.advisor-result-row.advisor-best {
  border-color: #8f5cff;
  box-shadow: 0 0 10px rgba(143, 92, 255, 0.35);
}

.advisor-result-row img {
  width: 34px;
  height: 34px;
  object-fit: contain;
  flex: 0 0 34px;
}

.advisor-result-info {
  flex: 1;
  min-width: 0;
}

.advisor-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-level {
  color: #bda2ff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-min {
  color: #8f7bbd;
  font-size: 11px;
  margin-top: 2px;
}

/* responsive */

@media screen and (max-width: 900px) {
  .enchant-ui {
    max-width: 850px;
    min-height: 520px;
  }

  .enchant-main {
    gap: 16px;
    padding: 10px 16px 20px 12px;
  }

  .enchant-left {
    min-width: 155px;
  }

  .enchant-heading {
    font-size: 42px;
    margin: 16px 0 22px 0;
  }

  .enchant-display-box {
    height: 165px;
  }

  .enchant-cost-box {
    height: 80px;
    font-size: 40px;
  }

  .enchant-button {
    height: 62px;
    font-size: 30px;
  }
}

@media screen and (max-width: 650px) {
  .enchant-ui {
    min-height: 0;
  }

  .enchant-main {
    flex-direction: column;
    align-items: center;
    padding: 12px;
    gap: 14px;
  }

  .enchant-left {
    width: 45%;
    max-width: 210px;
    min-width: 140px;
    flex: none;
  }

  .enchant-right {
    width: 100%;
  }

  .enchant-heading {
    text-align: center;
    font-size: 36px;
    margin: 8px 0 18px 0;
  }

  .enchant-display-box {
    height: 145px;
  }

  .enchant-line {
    margin: 20px 0;
  }

  .enchant-cost-box {
    height: 75px;
    font-size: 34px;
  }

  .enchant-button {
    width: 80%;
    min-width: 0;
    height: 58px;
    font-size: 28px;
  }

  .rod-popup {
    padding: 14px;
  }

  .rod-popup-panel {
    width: 100%;
    padding: 16px;
  }

  .rod-popup-title {
    font-size: 28px;
  }

  .rod-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .rod-card {
    min-height: 155px;
    padding: 10px;
  }

  .rod-card img {
    max-width: 85px;
    max-height: 85px;
  }
}

@media screen and (max-width: 520px) {
  .enchant-menu-popup {
    width: calc(100% - 16px);
  }

  .enchant-advisor-layout {
    grid-template-columns: 88px 1fr;
    gap: 10px;
  }

  .enchant-advisor-rods {
    width: 88px;
  }

  .enchant-advisor-rod {
    width: 88px;
    height: 88px;
    min-height: 88px;
    font-size: 10px;
    padding: 6px;
  }

  .advisor-rod-image {
    width: 48px;
    height: 48px;
  }

  .advisor-rod-image img,
  .advisor-rod-image .mw-file-element {
    max-width: 46px;
    max-height: 46px;
  }

  .advisor-rod-name {
    font-size: 10px;
  }

  .enchant-advisor-level-box {
    height: 68px;
    font-size: 20px;
  }
}

@media screen and (max-width: 420px) {
  .enchant-topbar {
    height: 28px;
    font-size: 15px;
  }

  .enchant-main {
    padding: 10px;
  }

  .enchant-left {
    width: 55%;
    min-width: 120px;
  }

  .enchant-heading {
    font-size: 30px;
  }

  .enchant-display-box {
    height: 120px;
  }

  .enchant-info-text {
    font-size: 22px;
  }

  .enchant-cost-box {
    height: 62px;
    font-size: 28px;
  }

  .enchant-button {
    width: 100%;
    height: 52px;
    font-size: 24px;
  }

  .enchant-result-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .enchant-result-card {
    min-height: 115px;
  }

  .enchant-result-card img {
    max-width: 46px;
    max-height: 46px;
  }

  .enchant-result-level {
    font-size: 16px;
  }

  .enchant-menu-popup {
    top: 42px;
    right: 8px;
    bottom: 14px;
    width: calc(100% - 16px);
    max-width: none;
  }

  .enchant-menu-title {
    font-size: 20px;
  }

  .enchant-menu-option {
    font-size: 16px;
    padding: 14px;
  }
}

@media screen and (max-width: 360px) {
  .rod-popup-title {
    font-size: 24px;
  }

  .rod-card {
    min-height: 135px;
    font-size: 13px;
  }

  .rod-card img {
    max-width: 70px;
    max-height: 70px;
  }
}

@media screen and (max-width: 340px) {
  .enchant-heading {
    font-size: 26px;
  }

  .enchant-cost-box {
    font-size: 24px;
  }

  .enchant-button {
    font-size: 21px;
  }
}

.enchant-ui {
  width: 100%;
  max-width: 1000px;
  min-height: 575px;
  margin: 0 auto;
  position: relative;

  background: #130b25;
  border: 2px solid #8f5cff;
  box-sizing: border-box;

  font-family: Arial, sans-serif;
  color: #ffffff;

  background-image:
    linear-gradient(
      135deg,
      rgba(140, 80, 255, 0.12) 0%,
      rgba(140, 80, 255, 0.12) 18%,
      transparent 18%,
      transparent 38%,
      rgba(140, 80, 255, 0.08) 38%,
      rgba(140, 80, 255, 0.08) 55%,
      transparent 55%
    );
}

.enchant-topbar {
  position: relative;
  z-index: 1000;

  height: 32px;
  background: #935cff;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 10px;
  box-sizing: border-box;

  font-size: 18px;
  font-weight: bold;
  letter-spacing: 1px;
}

.enchant-topbar-title {
  display: flex;
  align-items: center;
}

.enchant-title-icon {
  margin-right: 8px;
}

.enchant-main {
  display: flex;
  gap: 18px;

  padding: 10px 18px 22px 14px;
  box-sizing: border-box;
}

.enchant-left {
  width: 25%;
  max-width: 230px;
  min-width: 170px;
  flex: 0 0 25%;
}

.enchant-item-slot {
  position: relative;
  overflow: hidden;

  width: 100%;
  height: 0;
  padding-bottom: 100%;

  border: 1px solid #9b6cff;
  background: rgba(55, 30, 90, 0.35);

  box-sizing: border-box;
}

.enchant-right {
  flex: 1;
  min-width: 0;
}

.enchant-heading {
  font-size: 50px;
  font-weight: bold;
  line-height: 1;

  margin: 18px 0 26px 0;
}

.enchant-line {
  width: 100%;
  height: 1px;

  background: #8f5cff;
  margin: 26px 0;
}

.enchant-cost-box {
  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 48px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-fish-points-display {
  max-width: 100%;
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-button {
  width: 55%;
  max-width: 355px;
  min-width: 230px;
  height: 70px;

  margin: 22px auto 0 auto;

  background: #4b347a;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #130b25;
  font-size: 34px;
  font-weight: bold;

  box-sizing: border-box;
}

.enchant-open-picker {
  cursor: pointer;
}

.enchant-item-slot:hover,
.enchant-button:hover {
  outline: 2px solid #9b6cff;
}

/* selected rod image */

.enchant-selected-img {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  align-items: center;
  justify-content: center;
}

.enchant-selected-img img {
  max-width: 75%;
  max-height: 75%;
  width: auto;
  height: auto;
  transform: translateX(20px);
}

.enchant-ui.rod-normal .selected-normal,
.enchant-ui.rod-advanced .selected-advanced,
.enchant-ui.rod-momentum .selected-momentum,
.enchant-ui.rod-pistol .selected-pistol {
  display: flex;
}

/* headings */

.enchant-heading-normal,
.enchant-heading-advanced,
.enchant-heading-momentum,
.enchant-heading-pistol {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-default,
.enchant-ui.rod-advanced .enchant-heading-default,
.enchant-ui.rod-momentum .enchant-heading-default,
.enchant-ui.rod-pistol .enchant-heading-default {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-normal,
.enchant-ui.rod-advanced .enchant-heading-advanced,
.enchant-ui.rod-momentum .enchant-heading-momentum,
.enchant-ui.rod-pistol .enchant-heading-pistol {
  display: block;
}

/* rod popup */

.rod-popup {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 32px;
  bottom: 0;

  z-index: 100;

  align-items: center;
  justify-content: center;

  background: rgba(8, 4, 20, 0.72);
  box-sizing: border-box;
  padding: 24px;
}

.enchant-ui.rod-picker-open .rod-popup {
  display: flex;
}

.rod-popup-panel {
  width: 90%;
  max-width: 760px;

  background: #170d2f;
  border: 2px solid #8f5cff;
  box-shadow: 0 0 24px rgba(143, 92, 255, 0.35);

  padding: 24px;
  box-sizing: border-box;
}

.rod-popup-title {
  text-align: center;
  font-size: 36px;
  font-weight: bold;
  margin-bottom: 22px;
  color: #ffffff;
}

.rod-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}

.rod-card {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  min-height: 190px;
  padding: 14px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  text-align: center;
  box-sizing: border-box;

  cursor: pointer;
}

.rod-card:hover {
  background: #26124d;
  border-color: #9b6cff;
}

.rod-card img {
  max-width: 120px;
  max-height: 120px;
  width: auto;
  height: auto;
}

/* fish points input */

.enchant-points-input {
  width: 90%;
  background: transparent;
  border: none;
  outline: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;
}

.enchant-points-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.fish-points-error {
  border-color: #ff6666;
}

.fish-points-error .enchant-fish-points-display {
  color: #ff8888;
  font-size: 24px;
  font-style: normal;
}

/* enchant result display */

.enchant-display-box {
  width: 100%;
  height: 190px;

  background: rgba(82, 45, 120, 0.55);
  box-sizing: border-box;

  display: block;

  padding: 12px;

  overflow-y: auto;
  overflow-x: hidden;
}

.enchant-info-text {
  min-height: 100%;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #bda2ff;
  font-size: 30px;
  font-weight: bold;
  text-align: center;
}

.enchant-result-grid {
  display: none;
  width: 100%;

  grid-template-columns: repeat(auto-fit, minmax(90px, 1fr));
  gap: 10px;
}

.enchant-result-card {
  min-height: 130px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;

  text-align: center;
  box-sizing: border-box;
  padding: 8px;
}

.enchant-result-card img {
  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;
}

.enchant-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
  line-height: 1;
}

.enchant-result-level {
  color: #bda2ff;
  font-size: 18px;
  font-weight: bold;
}

/* enchant colors */

.enchant-bg-strength {
  background: #8c4368;
}

.enchant-bg-strength-plus {
  background: #871d50;
}

.enchant-bg-momentum {
  background: #5d8084;
}

.enchant-bg-momentum-plus {
  background: #387e73;
}

.enchant-bg-fortune {
  background: #406a98;
}

.enchant-bg-ultra {
  background: #8b4a43;
}

.enchant-bg-less-backfire {
  background: #463b53;
}

.enchant-bg-sharpshooter {
  background: #7f1397;
}

/* menu */

.enchant-menu-button {
  position: relative;
  z-index: 1001;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-width: 32px;
  min-height: 28px;

  color: #ffffff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
  user-select: none;
  pointer-events: auto;

  background: none;
  border: none;
  border-radius: 0;
}

.enchant-menu-button:hover {
  color: #d8c8ff;
}

.enchant-menu-popup {
  display: none;

  position: absolute;
  top: 46px;
  right: 12px;
  bottom: 18px;

  width: 520px;
  max-width: calc(100% - 20px);

  z-index: 1200;

  background: rgba(8, 4, 20, 0.96);
  border: 2px solid #8f5cff;
  border-radius: 16px;

  box-shadow: -8px 0 24px rgba(143, 92, 255, 0.35);

  padding: 14px 18px 18px 18px;
  box-sizing: border-box;

  overflow-y: auto;
  pointer-events: auto;
}

.enchant-ui.enchant-menu-open .enchant-menu-popup {
  display: block;
}

.enchant-menu-panel {
  min-height: 100%;

  display: flex;
  flex-direction: column;

  color: #ffffff;
}

.enchant-menu-title {
  color: #ffffff;
  font-size: 24px;
  font-weight: bold;

  margin-bottom: 10px;
}

.enchant-main-title {
  margin-bottom: 14px;
}

.menu-title-fish,
.menu-title-notation {
  display: none;
}

.enchant-menu-panel.show-fish .menu-title-fish {
  display: inline;
}

.enchant-menu-panel.show-notation .menu-title-notation {
  display: inline;
}

.enchant-menu-main,
.enchant-menu-options {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-menu-option {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 18px 16px;

  color: #ffffff;
  font-size: 18px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-option:hover {
  background: #21103f;
  border-color: #8f5cff;
}

.enchant-menu-page {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-main,
.enchant-menu-panel.show-notation .enchant-menu-main {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-page-fish,
.enchant-menu-panel.show-notation .enchant-menu-page-notation {
  display: block;
}

.enchant-menu-text {
  color: #ffffff;
  font-size: 14px;
  line-height: 1.35;
  overflow-wrap: anywhere;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px;
  box-sizing: border-box;
}

.enchant-notation-choice {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px 16px;
  margin-bottom: 10px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-notation-choice:hover {
  background: #140a24;
  border-color: #5b347f;
}

.enchant-notation-choice.notation-active {
  background: #21103f;
  border-color: #8f5cff;
  box-shadow: 0 0 12px rgba(143, 92, 255, 0.45);
}

.enchant-menu-back,
.enchant-menu-close {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 110px;
  min-width: 110px;

  margin-left: auto;
  margin-right: auto;

  padding: 8px 18px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 999px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-back {
  margin-top: 14px;
}

.enchant-menu-close {
  margin-top: 24px;
}

.enchant-menu-close:hover,
.enchant-menu-back:hover {
  background: #6d4ab0;
}

/* fish advisor */

.enchant-menu-page-fish {
  margin-top: 0;
}

.enchant-advisor-layout {
  display: grid;
  grid-template-columns: 110px 1fr;
  gap: 14px;
  align-items: start;

  margin-top: 0;
}

.enchant-advisor-rods {
  width: 110px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-advisor-rod {
  width: 110px;
  height: 110px;
  min-height: 110px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  padding: 8px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  color: #ffffff;
  font-size: 11px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
  box-sizing: border-box;

  overflow: hidden;
}

.enchant-advisor-rod:hover,
.enchant-advisor-rod.advisor-rod-active {
  background: #26124d;
  border-color: #9b6cff;
}

.advisor-rod-image {
  width: 64px;
  height: 64px;

  display: flex;
  align-items: center;
  justify-content: center;

  overflow: hidden;
  background: transparent;
  border: none;
  box-shadow: none;
}

.advisor-rod-image a,
.advisor-rod-image span,
.advisor-rod-image figure,
.advisor-rod-image .image,
.advisor-rod-image .mw-file-description,
.advisor-rod-image .mw-default-size {
  display: flex;
  align-items: center;
  justify-content: center;

  width: auto;
  height: auto;
  max-width: 64px;
  max-height: 64px;

  overflow: hidden !important;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;

  line-height: 0;
}

.advisor-rod-image img,
.advisor-rod-image .mw-file-element {
  display: block;

  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;

  margin: 0 auto;
}

.advisor-rod-name {
  width: 100%;

  color: #ffffff;
  font-size: 11px;
  line-height: 1.1;
  text-align: center;
  font-weight: bold;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-advisor-right {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-advisor-output {
  order: 1;

  width: 100%;
  min-height: 170px;
  max-height: 230px;

  margin-top: 0;
  padding: 14px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  color: #ffffff;
  font-size: 14px;
  line-height: 1.45;

  overflow-y: auto;
  overflow-x: hidden;

  box-sizing: border-box;
  white-space: normal;
}

.enchant-advisor-box {
  order: 2;

  width: 100%;
  height: 78px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 24px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-advisor-display {
  max-width: 100%;
  display: block;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;

  color: #6f4bb5;
}

.enchant-advisor-input {
  width: 90%;

  background: transparent;
  border: none;
  outline: none;
  box-shadow: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;

  margin: 0;
  padding: 0;

  overflow: hidden;
  box-sizing: border-box;
}

.enchant-advisor-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.enchant-advisor-check {
  order: 3;

  width: 100%;
  margin-top: 0;
  padding: 10px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 12px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;

  box-sizing: border-box;
}

.enchant-advisor-check:hover {
  background: #6d4ab0;
}

/* fish advisor result rows */

.advisor-result-title {
  font-size: 15px;
  font-weight: bold;
  color: #ffffff;
  margin-bottom: 10px;
}

.advisor-result-row {
  background: #130b25;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 10px;
  margin-bottom: 8px;

  display: flex;
  gap: 8px;
  align-items: center;

  box-sizing: border-box;
}

.advisor-result-row.advisor-best {
  border-color: #8f5cff;
  box-shadow: 0 0 10px rgba(143, 92, 255, 0.35);
}

.advisor-result-row img {
  width: 34px;
  height: 34px;
  object-fit: contain;
  flex: 0 0 34px;
}

.advisor-result-info {
  flex: 1;
  min-width: 0;
}

.advisor-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-level {
  color: #bda2ff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-min {
  color: #8f7bbd;
  font-size: 11px;
  margin-top: 2px;
}

/* responsive */

@media screen and (max-width: 900px) {
  .enchant-ui {
    max-width: 850px;
    min-height: 520px;
  }

  .enchant-main {
    gap: 16px;
    padding: 10px 16px 20px 12px;
  }

  .enchant-left {
    min-width: 155px;
  }

  .enchant-heading {
    font-size: 42px;
    margin: 16px 0 22px 0;
  }

  .enchant-display-box {
    height: 165px;
  }

  .enchant-cost-box {
    height: 80px;
    font-size: 40px;
  }

  .enchant-button {
    height: 62px;
    font-size: 30px;
  }
}

@media screen and (max-width: 650px) {
  .enchant-ui {
    min-height: 0;
  }

  .enchant-main {
    flex-direction: column;
    align-items: center;

    padding: 12px;
    gap: 14px;
  }

  .enchant-left {
    width: 45%;
    max-width: 210px;
    min-width: 140px;
    flex: none;
  }

  .enchant-right {
    width: 100%;
  }

  .enchant-heading {
    text-align: center;
    font-size: 36px;
    margin: 8px 0 18px 0;
  }

  .enchant-display-box {
    height: 145px;
  }

  .enchant-line {
    margin: 20px 0;
  }

  .enchant-cost-box {
    height: 75px;
    font-size: 34px;
  }

  .enchant-button {
    width: 80%;
    min-width: 0;
    height: 58px;
    font-size: 28px;
  }

  .rod-popup {
    padding: 14px;
  }

  .rod-popup-panel {
    width: 100%;
    padding: 16px;
  }

  .rod-popup-title {
    font-size: 28px;
  }

  .rod-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .rod-card {
    min-height: 155px;
    padding: 10px;
  }

  .rod-card img {
    max-width: 85px;
    max-height: 85px;
  }
}

@media screen and (max-width: 520px) {
  .enchant-menu-popup {
    width: calc(100% - 16px);
  }

  .enchant-advisor-layout {
    grid-template-columns: 88px 1fr;
    gap: 10px;
  }

  .enchant-advisor-rods {
    width: 88px;
  }

  .enchant-advisor-rod {
    width: 88px;
    height: 88px;
    min-height: 88px;
    font-size: 10px;
    padding: 6px;
  }

  .advisor-rod-image {
    width: 48px;
    height: 48px;
  }

  .advisor-rod-image img,
  .advisor-rod-image .mw-file-element {
    max-width: 46px;
    max-height: 46px;
  }

  .advisor-rod-name {
    font-size: 10px;
  }

  .enchant-advisor-box {
    height: 68px;
    font-size: 20px;
  }
}

@media screen and (max-width: 420px) {
  .enchant-topbar {
    height: 28px;
    font-size: 15px;
  }

  .enchant-main {
    padding: 10px;
  }

  .enchant-left {
    width: 55%;
    min-width: 120px;
  }

  .enchant-heading {
    font-size: 30px;
  }

  .enchant-display-box {
    height: 120px;
  }

  .enchant-info-text {
    font-size: 22px;
  }

  .enchant-cost-box {
    height: 62px;
    font-size: 28px;
  }

  .enchant-button {
    width: 100%;
    height: 52px;
    font-size: 24px;
  }

  .enchant-result-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .enchant-result-card {
    min-height: 115px;
  }

  .enchant-result-card img {
    max-width: 46px;
    max-height: 46px;
  }

  .enchant-result-level {
    font-size: 16px;
  }

  .enchant-menu-popup {
    top: 42px;
    right: 8px;
    bottom: 14px;

    width: calc(100% - 16px);
    max-width: none;
  }

  .enchant-menu-title {
    font-size: 20px;
  }

  .enchant-menu-option {
    font-size: 16px;
    padding: 14px;
  }

  .enchant-menu-text {
    font-size: 13px;
  }
}

@media screen and (max-width: 360px) {
  .rod-popup-title {
    font-size: 24px;
  }

  .rod-card {
    min-height: 135px;
    font-size: 13px;
  }

  .rod-card img {
    max-width: 70px;
    max-height: 70px;
  }
}

@media screen and (max-width: 340px) {
  .enchant-heading {
    font-size: 26px;
  }

  .enchant-cost-box {
    font-size: 24px;
  }

  .enchant-button {
    font-size: 21px;
  }
}
.enchant-advisor-combo-list {
  order: 2;

  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;

  width: 100%;
}

.enchant-advisor-combo-button {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 10px 8px;

  color: #ffffff;
  font-size: 12px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;

  box-sizing: border-box;
}

.enchant-advisor-combo-button:hover,
.enchant-advisor-combo-button.combo-active {
  background: #26124d;
  border-color: #9b6cff;
  box-shadow: 0 0 8px rgba(143, 92, 255, 0.35);
}

.enchant-advisor-level-box {
  order: 3;

  width: 100%;
  height: 78px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 24px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-advisor-level-display {
  max-width: 100%;
  display: block;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;

  color: #6f4bb5;
}

.enchant-advisor-level-input {
  width: 90%;

  background: transparent;
  border: none;
  outline: none;
  box-shadow: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;

  margin: 0;
  padding: 0;

  overflow: hidden;
  box-sizing: border-box;
}

.enchant-advisor-level-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.enchant-advisor-check {
  order: 4;
}

.enchant-ui {
  width: 100%;
  max-width: 1000px;
  min-height: 575px;
  margin: 0 auto;
  position: relative;

  background: #130b25;
  border: 2px solid #8f5cff;
  box-sizing: border-box;

  font-family: Arial, sans-serif;
  color: #ffffff;

  background-image:
    linear-gradient(
      135deg,
      rgba(140, 80, 255, 0.12) 0%,
      rgba(140, 80, 255, 0.12) 18%,
      transparent 18%,
      transparent 38%,
      rgba(140, 80, 255, 0.08) 38%,
      rgba(140, 80, 255, 0.08) 55%,
      transparent 55%
    );
}

.enchant-topbar {
  position: relative;
  z-index: 1000;

  height: 32px;
  background: #935cff;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 10px;
  box-sizing: border-box;

  font-size: 18px;
  font-weight: bold;
  letter-spacing: 1px;
}

.enchant-topbar-title {
  display: flex;
  align-items: center;
}

.enchant-title-icon {
  margin-right: 8px;
}

.enchant-main {
  display: flex;
  gap: 18px;

  padding: 10px 18px 22px 14px;
  box-sizing: border-box;
}

.enchant-left {
  width: 25%;
  max-width: 230px;
  min-width: 170px;
  flex: 0 0 25%;
}

.enchant-item-slot {
  position: relative;
  overflow: hidden;

  width: 100%;
  height: 0;
  padding-bottom: 100%;

  border: 1px solid #9b6cff;
  background: rgba(55, 30, 90, 0.35);

  box-sizing: border-box;
}

.enchant-right {
  flex: 1;
  min-width: 0;
}

.enchant-heading {
  font-size: 50px;
  font-weight: bold;
  line-height: 1;

  margin: 18px 0 26px 0;
}

.enchant-line {
  width: 100%;
  height: 1px;

  background: #8f5cff;
  margin: 26px 0;
}

.enchant-cost-box {
  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 48px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-fish-points-display {
  max-width: 100%;
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-button {
  width: 55%;
  max-width: 355px;
  min-width: 230px;
  height: 70px;

  margin: 22px auto 0 auto;

  background: #4b347a;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #130b25;
  font-size: 34px;
  font-weight: bold;

  box-sizing: border-box;
}

.enchant-open-picker {
  cursor: pointer;
}

.enchant-item-slot:hover,
.enchant-button:hover {
  outline: 2px solid #9b6cff;
}

/* selected rod image */

.enchant-selected-img {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  align-items: center;
  justify-content: center;
}

.enchant-selected-img img {
  max-width: 75%;
  max-height: 75%;
  width: auto;
  height: auto;
  transform: translateX(20px);
}

.enchant-ui.rod-normal .selected-normal,
.enchant-ui.rod-advanced .selected-advanced,
.enchant-ui.rod-momentum .selected-momentum,
.enchant-ui.rod-pistol .selected-pistol {
  display: flex;
}

/* headings */

.enchant-heading-normal,
.enchant-heading-advanced,
.enchant-heading-momentum,
.enchant-heading-pistol {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-default,
.enchant-ui.rod-advanced .enchant-heading-default,
.enchant-ui.rod-momentum .enchant-heading-default,
.enchant-ui.rod-pistol .enchant-heading-default {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-normal,
.enchant-ui.rod-advanced .enchant-heading-advanced,
.enchant-ui.rod-momentum .enchant-heading-momentum,
.enchant-ui.rod-pistol .enchant-heading-pistol {
  display: block;
}

/* rod popup */

.rod-popup {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 32px;
  bottom: 0;

  z-index: 100;

  align-items: center;
  justify-content: center;

  background: rgba(8, 4, 20, 0.72);
  box-sizing: border-box;
  padding: 24px;
}

.enchant-ui.rod-picker-open .rod-popup {
  display: flex;
}

.rod-popup-panel {
  width: 90%;
  max-width: 760px;

  background: #170d2f;
  border: 2px solid #8f5cff;
  box-shadow: 0 0 24px rgba(143, 92, 255, 0.35);

  padding: 24px;
  box-sizing: border-box;
}

.rod-popup-title {
  text-align: center;
  font-size: 36px;
  font-weight: bold;
  margin-bottom: 22px;
  color: #ffffff;
}

.rod-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}

.rod-card {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  min-height: 190px;
  padding: 14px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  text-align: center;
  box-sizing: border-box;

  cursor: pointer;
}

.rod-card:hover {
  background: #26124d;
  border-color: #9b6cff;
}

.rod-card img {
  max-width: 120px;
  max-height: 120px;
  width: auto;
  height: auto;
}

/* fish points input */

.enchant-points-input {
  width: 90%;
  background: transparent;
  border: none;
  outline: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;
}

.enchant-points-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.fish-points-error {
  border-color: #ff6666;
}

.fish-points-error .enchant-fish-points-display {
  color: #ff8888;
  font-size: 24px;
  font-style: normal;
}

/* enchant result display */

.enchant-display-box {
  width: 100%;
  height: 190px;

  background: rgba(82, 45, 120, 0.55);
  box-sizing: border-box;

  display: block;

  padding: 12px;

  overflow-y: auto;
  overflow-x: hidden;
}

.enchant-info-text {
  min-height: 100%;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #bda2ff;
  font-size: 30px;
  font-weight: bold;
  text-align: center;
}

.enchant-result-grid {
  display: none;
  width: 100%;

  grid-template-columns: repeat(auto-fit, minmax(90px, 1fr));
  gap: 10px;
}

.enchant-result-card {
  min-height: 130px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;

  text-align: center;
  box-sizing: border-box;
  padding: 8px;
}

.enchant-result-card img {
  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;
}

.enchant-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
  line-height: 1;
}

.enchant-result-level {
  color: #bda2ff;
  font-size: 18px;
  font-weight: bold;
}

/* enchant colors */

.enchant-bg-strength {
  background: #8c4368;
}

.enchant-bg-strength-plus {
  background: #871d50;
}

.enchant-bg-momentum {
  background: #5d8084;
}

.enchant-bg-momentum-plus {
  background: #387e73;
}

.enchant-bg-fortune {
  background: #406a98;
}

.enchant-bg-ultra {
  background: #8b4a43;
}

.enchant-bg-less-backfire {
  background: #463b53;
}

.enchant-bg-sharpshooter {
  background: #7f1397;
}

/* menu */

.enchant-menu-button {
  position: relative;
  z-index: 1001;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-width: 32px;
  min-height: 28px;

  color: #ffffff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
  user-select: none;
  pointer-events: auto;

  background: none;
  border: none;
  border-radius: 0;
}

.enchant-menu-button:hover {
  color: #d8c8ff;
}

.enchant-menu-popup {
  display: none;

  position: absolute;
  top: 46px;
  right: 12px;
  bottom: 18px;

  width: 520px;
  max-width: calc(100% - 20px);

  z-index: 1200;

  background: rgba(8, 4, 20, 0.96);
  border: 2px solid #8f5cff;
  border-radius: 16px;

  box-shadow: -8px 0 24px rgba(143, 92, 255, 0.35);

  padding: 14px 18px 18px 18px;
  box-sizing: border-box;

  overflow-y: auto;
  pointer-events: auto;
}

.enchant-ui.enchant-menu-open .enchant-menu-popup {
  display: block;
}

.enchant-menu-panel {
  min-height: 100%;

  display: flex;
  flex-direction: column;

  color: #ffffff;
}

.enchant-menu-title {
  color: #ffffff;
  font-size: 24px;
  font-weight: bold;

  margin-bottom: 10px;
}

.enchant-main-title {
  margin-bottom: 14px;
}

.menu-title-fish,
.menu-title-notation {
  display: none;
}

.enchant-menu-panel.show-fish .menu-title-fish {
  display: inline;
}

.enchant-menu-panel.show-notation .menu-title-notation {
  display: inline;
}

.enchant-menu-main,
.enchant-menu-options {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-menu-option {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 18px 16px;

  color: #ffffff;
  font-size: 18px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-option:hover {
  background: #21103f;
  border-color: #8f5cff;
}

.enchant-menu-page {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-main,
.enchant-menu-panel.show-notation .enchant-menu-main {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-page-fish,
.enchant-menu-panel.show-notation .enchant-menu-page-notation {
  display: block;
}

.enchant-menu-text {
  color: #ffffff;
  font-size: 14px;
  line-height: 1.35;
  overflow-wrap: anywhere;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px;
  box-sizing: border-box;
}

.enchant-notation-choice {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px 16px;
  margin-bottom: 10px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-notation-choice:hover {
  background: #140a24;
  border-color: #5b347f;
}

.enchant-notation-choice.notation-active {
  background: #21103f;
  border-color: #8f5cff;
  box-shadow: 0 0 12px rgba(143, 92, 255, 0.45);
}

.enchant-menu-back,
.enchant-menu-close {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 110px;
  min-width: 110px;

  margin-left: auto;
  margin-right: auto;

  padding: 8px 18px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 999px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-back {
  margin-top: 14px;
}

.enchant-menu-close {
  margin-top: 24px;
}

.enchant-menu-close:hover,
.enchant-menu-back:hover {
  background: #6d4ab0;
}

/* fish advisor */

.enchant-menu-page-fish {
  margin-top: 0;
}

.enchant-advisor-layout {
  display: grid;
  grid-template-columns: 110px 1fr;
  gap: 14px;
  align-items: start;

  margin-top: 0;
}

.enchant-advisor-rods {
  width: 110px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-advisor-rod {
  width: 110px;
  height: 110px;
  min-height: 110px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  padding: 8px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  color: #ffffff;
  font-size: 11px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
  box-sizing: border-box;

  overflow: hidden;
}

.enchant-advisor-rod:hover,
.enchant-advisor-rod.advisor-rod-active {
  background: #26124d;
  border-color: #9b6cff;
}

.advisor-rod-image {
  width: 64px;
  height: 64px;

  display: flex;
  align-items: center;
  justify-content: center;

  overflow: hidden;
  background: transparent;
  border: none;
  box-shadow: none;
}

.advisor-rod-image a,
.advisor-rod-image span,
.advisor-rod-image figure,
.advisor-rod-image .image,
.advisor-rod-image .mw-file-description,
.advisor-rod-image .mw-default-size {
  display: flex;
  align-items: center;
  justify-content: center;

  width: auto;
  height: auto;
  max-width: 64px;
  max-height: 64px;

  overflow: hidden !important;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;

  line-height: 0;
}

.advisor-rod-image img,
.advisor-rod-image .mw-file-element {
  display: block;

  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;

  margin: 0 auto;
}

.advisor-rod-name {
  width: 100%;

  color: #ffffff;
  font-size: 11px;
  line-height: 1.1;
  text-align: center;
  font-weight: bold;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-advisor-right {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-advisor-output {
  order: 1;

  width: 100%;
  min-height: 170px;
  max-height: 230px;

  margin-top: 0;
  padding: 14px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  color: #ffffff;
  font-size: 14px;
  line-height: 1.45;

  overflow-y: auto;
  overflow-x: hidden;

  box-sizing: border-box;
  white-space: normal;
}

.enchant-advisor-box {
  order: 2;

  width: 100%;
  height: 78px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 24px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-advisor-display {
  max-width: 100%;
  display: block;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;

  color: #6f4bb5;
}

.enchant-advisor-input {
  width: 90%;

  background: transparent;
  border: none;
  outline: none;
  box-shadow: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;

  margin: 0;
  padding: 0;

  overflow: hidden;
  box-sizing: border-box;
}

.enchant-advisor-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.enchant-advisor-check {
  order: 3;

  width: 100%;
  margin-top: 0;
  padding: 10px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 12px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;

  box-sizing: border-box;
}

.enchant-advisor-check:hover {
  background: #6d4ab0;
}

/* fish advisor result rows */

.advisor-result-title {
  font-size: 15px;
  font-weight: bold;
  color: #ffffff;
  margin-bottom: 10px;
}

.advisor-result-row {
  background: #130b25;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 10px;
  margin-bottom: 8px;

  display: flex;
  gap: 8px;
  align-items: center;

  box-sizing: border-box;
}

.advisor-result-row.advisor-best {
  border-color: #8f5cff;
  box-shadow: 0 0 10px rgba(143, 92, 255, 0.35);
}

.advisor-result-row img {
  width: 34px;
  height: 34px;
  object-fit: contain;
  flex: 0 0 34px;
}

.advisor-result-info {
  flex: 1;
  min-width: 0;
}

.advisor-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-level {
  color: #bda2ff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-min {
  color: #8f7bbd;
  font-size: 11px;
  margin-top: 2px;
}

/* responsive */

@media screen and (max-width: 900px) {
  .enchant-ui {
    max-width: 850px;
    min-height: 520px;
  }

  .enchant-main {
    gap: 16px;
    padding: 10px 16px 20px 12px;
  }

  .enchant-left {
    min-width: 155px;
  }

  .enchant-heading {
    font-size: 42px;
    margin: 16px 0 22px 0;
  }

  .enchant-display-box {
    height: 165px;
  }

  .enchant-cost-box {
    height: 80px;
    font-size: 40px;
  }

  .enchant-button {
    height: 62px;
    font-size: 30px;
  }
}

@media screen and (max-width: 650px) {
  .enchant-ui {
    min-height: 0;
  }

  .enchant-main {
    flex-direction: column;
    align-items: center;

    padding: 12px;
    gap: 14px;
  }

  .enchant-left {
    width: 45%;
    max-width: 210px;
    min-width: 140px;
    flex: none;
  }

  .enchant-right {
    width: 100%;
  }

  .enchant-heading {
    text-align: center;
    font-size: 36px;
    margin: 8px 0 18px 0;
  }

  .enchant-display-box {
    height: 145px;
  }

  .enchant-line {
    margin: 20px 0;
  }

  .enchant-cost-box {
    height: 75px;
    font-size: 34px;
  }

  .enchant-button {
    width: 80%;
    min-width: 0;
    height: 58px;
    font-size: 28px;
  }

  .rod-popup {
    padding: 14px;
  }

  .rod-popup-panel {
    width: 100%;
    padding: 16px;
  }

  .rod-popup-title {
    font-size: 28px;
  }

  .rod-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .rod-card {
    min-height: 155px;
    padding: 10px;
  }

  .rod-card img {
    max-width: 85px;
    max-height: 85px;
  }
}

@media screen and (max-width: 520px) {
  .enchant-menu-popup {
    width: calc(100% - 16px);
  }

  .enchant-advisor-layout {
    grid-template-columns: 88px 1fr;
    gap: 10px;
  }

  .enchant-advisor-rods {
    width: 88px;
  }

  .enchant-advisor-rod {
    width: 88px;
    height: 88px;
    min-height: 88px;
    font-size: 10px;
    padding: 6px;
  }

  .advisor-rod-image {
    width: 48px;
    height: 48px;
  }

  .advisor-rod-image img,
  .advisor-rod-image .mw-file-element {
    max-width: 46px;
    max-height: 46px;
  }

  .advisor-rod-name {
    font-size: 10px;
  }

  .enchant-advisor-box {
    height: 68px;
    font-size: 20px;
  }
}

@media screen and (max-width: 420px) {
  .enchant-topbar {
    height: 28px;
    font-size: 15px;
  }

  .enchant-main {
    padding: 10px;
  }

  .enchant-left {
    width: 55%;
    min-width: 120px;
  }

  .enchant-heading {
    font-size: 30px;
  }

  .enchant-display-box {
    height: 120px;
  }

  .enchant-info-text {
    font-size: 22px;
  }

  .enchant-cost-box {
    height: 62px;
    font-size: 28px;
  }

  .enchant-button {
    width: 100%;
    height: 52px;
    font-size: 24px;
  }

  .enchant-result-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .enchant-result-card {
    min-height: 115px;
  }

  .enchant-result-card img {
    max-width: 46px;
    max-height: 46px;
  }

  .enchant-result-level {
    font-size: 16px;
  }

  .enchant-menu-popup {
    top: 42px;
    right: 8px;
    bottom: 14px;

    width: calc(100% - 16px);
    max-width: none;
  }

  .enchant-menu-title {
    font-size: 20px;
  }

  .enchant-menu-option {
    font-size: 16px;
    padding: 14px;
  }

  .enchant-menu-text {
    font-size: 13px;
  }
}

@media screen and (max-width: 360px) {
  .rod-popup-title {
    font-size: 24px;
  }

  .rod-card {
    min-height: 135px;
    font-size: 13px;
  }

  .rod-card img {
    max-width: 70px;
    max-height: 70px;
  }
}

@media screen and (max-width: 340px) {
  .enchant-heading {
    font-size: 26px;
  }

  .enchant-cost-box {
    font-size: 24px;
  }

  .enchant-button {
    font-size: 21px;
  }
}
.enchant-advisor-combo-list {
  order: 2;

  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;

  width: 100%;
}

.enchant-advisor-combo-button {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 10px 8px;

  color: #ffffff;
  font-size: 12px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;

  box-sizing: border-box;
}

.enchant-advisor-combo-button:hover,
.enchant-advisor-combo-button.combo-active {
  background: #26124d;
  border-color: #9b6cff;
  box-shadow: 0 0 8px rgba(143, 92, 255, 0.35);
}

.enchant-advisor-level-box {
  order: 3;

  width: 100%;
  height: 78px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 24px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-advisor-level-display {
  max-width: 100%;
  display: block;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;

  color: #6f4bb5;
}

.enchant-advisor-level-input {
  width: 90%;

  background: transparent;
  border: none;
  outline: none;
  box-shadow: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;

  margin: 0;
  padding: 0;

  overflow: hidden;
  box-sizing: border-box;
}

.enchant-advisor-level-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.enchant-advisor-check {
  order: 4;
}
.enchant-menu-main,
.enchant-menu-options {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-menu-panel.show-fish .enchant-menu-main,
.enchant-menu-panel.show-fish .enchant-menu-options,
.enchant-menu-panel.show-notation .enchant-menu-main,
.enchant-menu-panel.show-notation .enchant-menu-options {
  display: none;
}

.enchant-menu-option,
.enchant-notation-choice,
.enchant-advisor-rod,
.enchant-advisor-combo-button,
.enchant-advisor-check,
.enchant-menu-back,
.enchant-menu-close {
  pointer-events: auto;
  cursor: pointer;
}

.enchant-menu-popup {
  pointer-events: auto;
}

.enchant-selected-img {
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;
}

.enchant-ui {
  width: 100%;
  max-width: 1000px;
  min-height: 575px;
  margin: 0 auto;
  position: relative;

  background: #130b25;
  border: 2px solid #8f5cff;
  box-sizing: border-box;

  font-family: Arial, sans-serif;
  color: #ffffff;

  background-image:
    linear-gradient(
      135deg,
      rgba(140, 80, 255, 0.12) 0%,
      rgba(140, 80, 255, 0.12) 18%,
      transparent 18%,
      transparent 38%,
      rgba(140, 80, 255, 0.08) 38%,
      rgba(140, 80, 255, 0.08) 55%,
      transparent 55%
    );
}

.enchant-topbar {
  position: relative;
  z-index: 1000;

  height: 32px;
  background: #935cff;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 10px;
  box-sizing: border-box;

  font-size: 18px;
  font-weight: bold;
  letter-spacing: 1px;
}

.enchant-topbar-title {
  display: flex;
  align-items: center;
}

.enchant-title-icon {
  margin-right: 8px;
}

.enchant-main {
  display: flex;
  gap: 18px;

  padding: 10px 18px 22px 14px;
  box-sizing: border-box;
}

.enchant-left {
  width: 25%;
  max-width: 230px;
  min-width: 170px;
  flex: 0 0 25%;
}

.enchant-item-slot {
  position: relative;
  overflow: hidden;

  width: 100%;
  height: 0;
  padding-bottom: 100%;

  border: 1px solid #9b6cff;
  background: rgba(55, 30, 90, 0.35);

  box-sizing: border-box;
}

.enchant-right {
  flex: 1;
  min-width: 0;
}

.enchant-heading {
  font-size: 50px;
  font-weight: bold;
  line-height: 1;

  margin: 18px 0 26px 0;
}

.enchant-line {
  width: 100%;
  height: 1px;

  background: #8f5cff;
  margin: 26px 0;
}

.enchant-cost-box {
  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 48px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-fish-points-display {
  max-width: 100%;
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-button {
  width: 55%;
  max-width: 355px;
  min-width: 230px;
  height: 70px;

  margin: 22px auto 0 auto;

  background: #4b347a;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #130b25;
  font-size: 34px;
  font-weight: bold;

  box-sizing: border-box;
}

.enchant-open-picker {
  cursor: pointer;
}

.enchant-item-slot:hover,
.enchant-button:hover {
  outline: 2px solid #9b6cff;
}

/* selected rod image */

.enchant-selected-img {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  align-items: center;
  justify-content: center;
}

.enchant-selected-img img {
  max-width: 75%;
  max-height: 75%;
  width: auto;
  height: auto;
  transform: translateX(20px);
}

.enchant-ui.rod-normal .selected-normal,
.enchant-ui.rod-advanced .selected-advanced,
.enchant-ui.rod-momentum .selected-momentum,
.enchant-ui.rod-pistol .selected-pistol {
  display: flex;
}

/* headings */

.enchant-heading-normal,
.enchant-heading-advanced,
.enchant-heading-momentum,
.enchant-heading-pistol {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-default,
.enchant-ui.rod-advanced .enchant-heading-default,
.enchant-ui.rod-momentum .enchant-heading-default,
.enchant-ui.rod-pistol .enchant-heading-default {
  display: none;
}

.enchant-ui.rod-normal .enchant-heading-normal,
.enchant-ui.rod-advanced .enchant-heading-advanced,
.enchant-ui.rod-momentum .enchant-heading-momentum,
.enchant-ui.rod-pistol .enchant-heading-pistol {
  display: block;
}

/* rod popup */

.rod-popup {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 32px;
  bottom: 0;

  z-index: 100;

  align-items: center;
  justify-content: center;

  background: rgba(8, 4, 20, 0.72);
  box-sizing: border-box;
  padding: 24px;
}

.enchant-ui.rod-picker-open .rod-popup {
  display: flex;
}

.rod-popup-panel {
  width: 90%;
  max-width: 760px;

  background: #170d2f;
  border: 2px solid #8f5cff;
  box-shadow: 0 0 24px rgba(143, 92, 255, 0.35);

  padding: 24px;
  box-sizing: border-box;
}

.rod-popup-title {
  text-align: center;
  font-size: 36px;
  font-weight: bold;
  margin-bottom: 22px;
  color: #ffffff;
}

.rod-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}

.rod-card {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  min-height: 190px;
  padding: 14px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  text-align: center;
  box-sizing: border-box;

  cursor: pointer;
}

.rod-card:hover {
  background: #26124d;
  border-color: #9b6cff;
}

.rod-card img {
  max-width: 120px;
  max-height: 120px;
  width: auto;
  height: auto;
}

/* fish points input */

.enchant-points-input {
  width: 90%;
  background: transparent;
  border: none;
  outline: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;
}

.enchant-points-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.fish-points-error {
  border-color: #ff6666;
}

.fish-points-error .enchant-fish-points-display {
  color: #ff8888;
  font-size: 24px;
  font-style: normal;
}

/* enchant result display */

.enchant-display-box {
  width: 100%;
  height: 190px;

  background: rgba(82, 45, 120, 0.55);
  box-sizing: border-box;

  display: block;

  padding: 12px;

  overflow-y: auto;
  overflow-x: hidden;
}

.enchant-info-text {
  min-height: 100%;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #bda2ff;
  font-size: 30px;
  font-weight: bold;
  text-align: center;
}

.enchant-result-grid {
  display: none;
  width: 100%;

  grid-template-columns: repeat(auto-fit, minmax(90px, 1fr));
  gap: 10px;
}

.enchant-result-card {
  min-height: 130px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;

  text-align: center;
  box-sizing: border-box;
  padding: 8px;
}

.enchant-result-card img {
  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;
}

.enchant-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
  line-height: 1;
}

.enchant-result-level {
  color: #bda2ff;
  font-size: 18px;
  font-weight: bold;
}

/* enchant colors */

.enchant-bg-strength {
  background: #8c4368;
}

.enchant-bg-strength-plus {
  background: #871d50;
}

.enchant-bg-momentum {
  background: #5d8084;
}

.enchant-bg-momentum-plus {
  background: #387e73;
}

.enchant-bg-fortune {
  background: #406a98;
}

.enchant-bg-ultra {
  background: #8b4a43;
}

.enchant-bg-less-backfire {
  background: #463b53;
}

.enchant-bg-sharpshooter {
  background: #7f1397;
}

/* menu */

.enchant-menu-button {
  position: relative;
  z-index: 1001;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-width: 32px;
  min-height: 28px;

  color: #ffffff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
  user-select: none;
  pointer-events: auto;

  background: none;
  border: none;
  border-radius: 0;
}

.enchant-menu-button:hover {
  color: #d8c8ff;
}

.enchant-menu-popup {
  display: none;

  position: absolute;
  top: 46px;
  right: 12px;
  bottom: 18px;

  width: 520px;
  max-width: calc(100% - 20px);

  z-index: 1200;

  background: rgba(8, 4, 20, 0.96);
  border: 2px solid #8f5cff;
  border-radius: 16px;

  box-shadow: -8px 0 24px rgba(143, 92, 255, 0.35);

  padding: 14px 18px 18px 18px;
  box-sizing: border-box;

  overflow-y: auto;
  pointer-events: auto;
}

.enchant-ui.enchant-menu-open .enchant-menu-popup {
  display: block;
}

.enchant-menu-panel {
  min-height: 100%;

  display: flex;
  flex-direction: column;

  color: #ffffff;
}

.enchant-menu-title {
  color: #ffffff;
  font-size: 24px;
  font-weight: bold;

  margin-bottom: 10px;
}

.enchant-main-title {
  margin-bottom: 14px;
}

.menu-title-fish,
.menu-title-notation {
  display: none;
}

.enchant-menu-panel.show-fish .menu-title-fish {
  display: inline;
}

.enchant-menu-panel.show-notation .menu-title-notation {
  display: inline;
}

.enchant-menu-main,
.enchant-menu-options {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-menu-option {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 18px 16px;

  color: #ffffff;
  font-size: 18px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-option:hover {
  background: #21103f;
  border-color: #8f5cff;
}

.enchant-menu-page {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-main,
.enchant-menu-panel.show-notation .enchant-menu-main {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-page-fish,
.enchant-menu-panel.show-notation .enchant-menu-page-notation {
  display: block;
}

.enchant-menu-text {
  color: #ffffff;
  font-size: 14px;
  line-height: 1.35;
  overflow-wrap: anywhere;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px;
  box-sizing: border-box;
}

.enchant-notation-choice {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px 16px;
  margin-bottom: 10px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-notation-choice:hover {
  background: #140a24;
  border-color: #5b347f;
}

.enchant-notation-choice.notation-active {
  background: #21103f;
  border-color: #8f5cff;
  box-shadow: 0 0 12px rgba(143, 92, 255, 0.45);
}

.enchant-menu-back,
.enchant-menu-close {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 110px;
  min-width: 110px;

  margin-left: auto;
  margin-right: auto;

  padding: 8px 18px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 999px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-back {
  margin-top: 14px;
}

.enchant-menu-close {
  margin-top: 24px;
}

.enchant-menu-close:hover,
.enchant-menu-back:hover {
  background: #6d4ab0;
}

/* fish advisor */

.enchant-menu-page-fish {
  margin-top: 0;
}

.enchant-advisor-layout {
  display: grid;
  grid-template-columns: 110px 1fr;
  gap: 14px;
  align-items: start;

  margin-top: 0;
}

.enchant-advisor-rods {
  width: 110px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-advisor-rod {
  width: 110px;
  height: 110px;
  min-height: 110px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  padding: 8px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  color: #ffffff;
  font-size: 11px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
  box-sizing: border-box;

  overflow: hidden;
}

.enchant-advisor-rod:hover,
.enchant-advisor-rod.advisor-rod-active {
  background: #26124d;
  border-color: #9b6cff;
}

.advisor-rod-image {
  width: 64px;
  height: 64px;

  display: flex;
  align-items: center;
  justify-content: center;

  overflow: hidden;
  background: transparent;
  border: none;
  box-shadow: none;
}

.advisor-rod-image a,
.advisor-rod-image span,
.advisor-rod-image figure,
.advisor-rod-image .image,
.advisor-rod-image .mw-file-description,
.advisor-rod-image .mw-default-size {
  display: flex;
  align-items: center;
  justify-content: center;

  width: auto;
  height: auto;
  max-width: 64px;
  max-height: 64px;

  overflow: hidden !important;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;

  line-height: 0;
}

.advisor-rod-image img,
.advisor-rod-image .mw-file-element {
  display: block;

  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;

  margin: 0 auto;
}

.advisor-rod-name {
  width: 100%;

  color: #ffffff;
  font-size: 11px;
  line-height: 1.1;
  text-align: center;
  font-weight: bold;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-advisor-right {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-advisor-output {
  order: 1;

  width: 100%;
  min-height: 170px;
  max-height: 230px;

  margin-top: 0;
  padding: 14px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  color: #ffffff;
  font-size: 14px;
  line-height: 1.45;

  overflow-y: auto;
  overflow-x: hidden;

  box-sizing: border-box;
  white-space: normal;
}

.enchant-advisor-box {
  order: 2;

  width: 100%;
  height: 78px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 24px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-advisor-display {
  max-width: 100%;
  display: block;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;

  color: #6f4bb5;
}

.enchant-advisor-input {
  width: 90%;

  background: transparent;
  border: none;
  outline: none;
  box-shadow: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;

  margin: 0;
  padding: 0;

  overflow: hidden;
  box-sizing: border-box;
}

.enchant-advisor-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.enchant-advisor-check {
  order: 3;

  width: 100%;
  margin-top: 0;
  padding: 10px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 12px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;

  box-sizing: border-box;
}

.enchant-advisor-check:hover {
  background: #6d4ab0;
}

/* fish advisor result rows */

.advisor-result-title {
  font-size: 15px;
  font-weight: bold;
  color: #ffffff;
  margin-bottom: 10px;
}

.advisor-result-row {
  background: #130b25;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 10px;
  margin-bottom: 8px;

  display: flex;
  gap: 8px;
  align-items: center;

  box-sizing: border-box;
}

.advisor-result-row.advisor-best {
  border-color: #8f5cff;
  box-shadow: 0 0 10px rgba(143, 92, 255, 0.35);
}

.advisor-result-row img {
  width: 34px;
  height: 34px;
  object-fit: contain;
  flex: 0 0 34px;
}

.advisor-result-info {
  flex: 1;
  min-width: 0;
}

.advisor-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-level {
  color: #bda2ff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-min {
  color: #8f7bbd;
  font-size: 11px;
  margin-top: 2px;
}

/* responsive */

@media screen and (max-width: 900px) {
  .enchant-ui {
    max-width: 850px;
    min-height: 520px;
  }

  .enchant-main {
    gap: 16px;
    padding: 10px 16px 20px 12px;
  }

  .enchant-left {
    min-width: 155px;
  }

  .enchant-heading {
    font-size: 42px;
    margin: 16px 0 22px 0;
  }

  .enchant-display-box {
    height: 165px;
  }

  .enchant-cost-box {
    height: 80px;
    font-size: 40px;
  }

  .enchant-button {
    height: 62px;
    font-size: 30px;
  }
}

@media screen and (max-width: 650px) {
  .enchant-ui {
    min-height: 0;
  }

  .enchant-main {
    flex-direction: column;
    align-items: center;

    padding: 12px;
    gap: 14px;
  }

  .enchant-left {
    width: 45%;
    max-width: 210px;
    min-width: 140px;
    flex: none;
  }

  .enchant-right {
    width: 100%;
  }

  .enchant-heading {
    text-align: center;
    font-size: 36px;
    margin: 8px 0 18px 0;
  }

  .enchant-display-box {
    height: 145px;
  }

  .enchant-line {
    margin: 20px 0;
  }

  .enchant-cost-box {
    height: 75px;
    font-size: 34px;
  }

  .enchant-button {
    width: 80%;
    min-width: 0;
    height: 58px;
    font-size: 28px;
  }

  .rod-popup {
    padding: 14px;
  }

  .rod-popup-panel {
    width: 100%;
    padding: 16px;
  }

  .rod-popup-title {
    font-size: 28px;
  }

  .rod-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .rod-card {
    min-height: 155px;
    padding: 10px;
  }

  .rod-card img {
    max-width: 85px;
    max-height: 85px;
  }
}

@media screen and (max-width: 520px) {
  .enchant-menu-popup {
    width: calc(100% - 16px);
  }

  .enchant-advisor-layout {
    grid-template-columns: 88px 1fr;
    gap: 10px;
  }

  .enchant-advisor-rods {
    width: 88px;
  }

  .enchant-advisor-rod {
    width: 88px;
    height: 88px;
    min-height: 88px;
    font-size: 10px;
    padding: 6px;
  }

  .advisor-rod-image {
    width: 48px;
    height: 48px;
  }

  .advisor-rod-image img,
  .advisor-rod-image .mw-file-element {
    max-width: 46px;
    max-height: 46px;
  }

  .advisor-rod-name {
    font-size: 10px;
  }

  .enchant-advisor-box {
    height: 68px;
    font-size: 20px;
  }
}

@media screen and (max-width: 420px) {
  .enchant-topbar {
    height: 28px;
    font-size: 15px;
  }

  .enchant-main {
    padding: 10px;
  }

  .enchant-left {
    width: 55%;
    min-width: 120px;
  }

  .enchant-heading {
    font-size: 30px;
  }

  .enchant-display-box {
    height: 120px;
  }

  .enchant-info-text {
    font-size: 22px;
  }

  .enchant-cost-box {
    height: 62px;
    font-size: 28px;
  }

  .enchant-button {
    width: 100%;
    height: 52px;
    font-size: 24px;
  }

  .enchant-result-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .enchant-result-card {
    min-height: 115px;
  }

  .enchant-result-card img {
    max-width: 46px;
    max-height: 46px;
  }

  .enchant-result-level {
    font-size: 16px;
  }

  .enchant-menu-popup {
    top: 42px;
    right: 8px;
    bottom: 14px;

    width: calc(100% - 16px);
    max-width: none;
  }

  .enchant-menu-title {
    font-size: 20px;
  }

  .enchant-menu-option {
    font-size: 16px;
    padding: 14px;
  }

  .enchant-menu-text {
    font-size: 13px;
  }
}

@media screen and (max-width: 360px) {
  .rod-popup-title {
    font-size: 24px;
  }

  .rod-card {
    min-height: 135px;
    font-size: 13px;
  }

  .rod-card img {
    max-width: 70px;
    max-height: 70px;
  }
}

@media screen and (max-width: 340px) {
  .enchant-heading {
    font-size: 26px;
  }

  .enchant-cost-box {
    font-size: 24px;
  }

  .enchant-button {
    font-size: 21px;
  }
}
.enchant-advisor-combo-list {
  order: 2;

  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;

  width: 100%;
}

.enchant-advisor-combo-button {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 10px 8px;

  color: #ffffff;
  font-size: 12px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;

  box-sizing: border-box;
}

.enchant-advisor-combo-button:hover,
.enchant-advisor-combo-button.combo-active {
  background: #26124d;
  border-color: #9b6cff;
  box-shadow: 0 0 8px rgba(143, 92, 255, 0.35);
}

.enchant-advisor-level-box {
  order: 3;

  width: 100%;
  height: 78px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 24px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-advisor-level-display {
  max-width: 100%;
  display: block;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;

  color: #6f4bb5;
}

.enchant-advisor-level-input {
  width: 90%;

  background: transparent;
  border: none;
  outline: none;
  box-shadow: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;

  margin: 0;
  padding: 0;

  overflow: hidden;
  box-sizing: border-box;
}

.enchant-advisor-level-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.enchant-advisor-check {
  order: 4;
}

.enchant-ui {
  width: 100%;
  max-width: 1000px;
  min-height: 575px;
  margin: 0 auto;
  position: relative;

  background: #130b25;
  border: 2px solid #8f5cff;
  box-sizing: border-box;

  font-family: Arial, sans-serif;
  color: #ffffff;

  background-image:
    linear-gradient(
      135deg,
      rgba(140, 80, 255, 0.12) 0%,
      rgba(140, 80, 255, 0.12) 18%,
      transparent 18%,
      transparent 38%,
      rgba(140, 80, 255, 0.08) 38%,
      rgba(140, 80, 255, 0.08) 55%,
      transparent 55%
    );
}

.enchant-topbar {
  position: relative;
  z-index: 1000;

  height: 32px;
  background: #935cff;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 10px;
  box-sizing: border-box;

  font-size: 18px;
  font-weight: bold;
  letter-spacing: 1px;
}

.enchant-topbar-title {
  display: flex;
  align-items: center;
}

.enchant-title-icon {
  margin-right: 8px;
}

.enchant-main {
  display: flex;
  gap: 18px;

  padding: 10px 18px 22px 14px;
  box-sizing: border-box;
}

.enchant-left {
  width: 25%;
  max-width: 230px;
  min-width: 170px;
  flex: 0 0 25%;
}

.enchant-item-slot {
  position: relative;
  overflow: hidden;

  width: 100%;
  height: 0;
  padding-bottom: 100%;

  border: 1px solid #9b6cff;
  background: rgba(55, 30, 90, 0.35);

  box-sizing: border-box;
}

.enchant-right {
  flex: 1;
  min-width: 0;
}

.enchant-heading {
  font-size: 50px;
  font-weight: bold;
  line-height: 1;

  margin: 18px 0 26px 0;
}

.enchant-line {
  width: 100%;
  height: 1px;

  background: #8f5cff;
  margin: 26px 0;
}

.enchant-cost-box {
  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 48px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-fish-points-display {
  max-width: 100%;
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-button {
  width: 55%;
  max-width: 355px;
  min-width: 230px;
  height: 70px;

  margin: 22px auto 0 auto;

  background: #4b347a;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #130b25;
  font-size: 34px;
  font-weight: bold;

  box-sizing: border-box;
}

.enchant-open-picker {
  cursor: pointer;
}

.enchant-item-slot:hover,
.enchant-button:hover {
  outline: 2px solid #9b6cff;
}



.enchant-selected-img {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  align-items: center;
  justify-content: center;
}

.enchant-selected-img img {
  max-width: 75%;
  max-height: 75%;
  width: auto;
  height: auto;
  transform: translateX(20px);
}

.enchant-selected-img.enchant-selected-active {
  display: flex;
}

.rod-popup {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 32px;
  bottom: 0;

  z-index: 100;

  align-items: center;
  justify-content: center;

  background: rgba(8, 4, 20, 0.72);
  box-sizing: border-box;
  padding: 24px;
}

.enchant-ui.rod-picker-open .rod-popup {
  display: flex;
}

.rod-popup-panel {
  width: 90%;
  max-width: 760px;

  background: #170d2f;
  border: 2px solid #8f5cff;
  box-shadow: 0 0 24px rgba(143, 92, 255, 0.35);

  padding: 24px;
  box-sizing: border-box;
}

.rod-popup-title {
  text-align: center;
  font-size: 36px;
  font-weight: bold;
  margin-bottom: 22px;
  color: #ffffff;
}

.rod-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 14px;
}

.rod-picker-message {
  grid-column: 1 / -1;
  padding: 24px;
  text-align: center;
  color: #bda2ff;
  font-size: 18px;
}

.rod-card {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  min-height: 190px;
  padding: 14px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  text-align: center;
  box-sizing: border-box;

  cursor: pointer;
}

.rod-card:hover {
  background: #26124d;
  border-color: #9b6cff;
}

.rod-card img {
  max-width: 120px;
  max-height: 120px;
  width: auto;
  height: auto;
}



.enchant-points-input {
  width: 90%;
  background: transparent;
  border: none;
  outline: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;
}

.enchant-points-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.fish-points-error {
  border-color: #ff6666;
}

.fish-points-error .enchant-fish-points-display {
  color: #ff8888;
  font-size: 24px;
  font-style: normal;
}



.enchant-display-box {
  width: 100%;
  height: 190px;

  background: rgba(82, 45, 120, 0.55);
  box-sizing: border-box;

  display: block;

  padding: 12px;

  overflow-y: auto;
  overflow-x: hidden;
}

.enchant-info-text {
  min-height: 100%;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #bda2ff;
  font-size: 30px;
  font-weight: bold;
  text-align: center;
}

.enchant-result-grid {
  display: none;
  width: 100%;

  grid-template-columns: repeat(auto-fit, minmax(90px, 1fr));
  gap: 10px;
}

.enchant-result-card {
  min-height: 130px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;

  text-align: center;
  box-sizing: border-box;
  padding: 8px;
}

.enchant-result-card img {
  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;
}

.enchant-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
  line-height: 1;
}

.enchant-result-level {
  color: #bda2ff;
  font-size: 18px;
  font-weight: bold;
}



.enchant-bg-strength {
  background: #8c4368;
}

.enchant-bg-strength-plus {
  background: #871d50;
}

.enchant-bg-momentum {
  background: #5d8084;
}

.enchant-bg-momentum-plus {
  background: #387e73;
}

.enchant-bg-fortune {
  background: #406a98;
}

.enchant-bg-ultra {
  background: #8b4a43;
}

.enchant-bg-less-backfire {
  background: #463b53;
}

.enchant-bg-sharpshooter {
  background: #7f1397;
}



.enchant-menu-button {
  position: relative;
  z-index: 1001;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-width: 32px;
  min-height: 28px;

  color: #ffffff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
  user-select: none;
  pointer-events: auto;

  background: none;
  border: none;
  border-radius: 0;
}

.enchant-menu-button:hover {
  color: #d8c8ff;
}

.enchant-menu-popup {
  display: none;

  position: absolute;
  top: 46px;
  right: 12px;
  bottom: 18px;

  width: 520px;
  max-width: calc(100% - 20px);

  z-index: 1200;

  background: rgba(8, 4, 20, 0.96);
  border: 2px solid #8f5cff;
  border-radius: 16px;

  box-shadow: -8px 0 24px rgba(143, 92, 255, 0.35);

  padding: 14px 18px 18px 18px;
  box-sizing: border-box;

  overflow-y: auto;
  pointer-events: auto;
}

.enchant-ui.enchant-menu-open .enchant-menu-popup {
  display: block;
}

.enchant-menu-panel {
  min-height: 100%;

  display: flex;
  flex-direction: column;

  color: #ffffff;
}

.enchant-menu-title {
  color: #ffffff;
  font-size: 24px;
  font-weight: bold;

  margin-bottom: 10px;
}

.enchant-main-title {
  margin-bottom: 14px;
}

.menu-title-fish,
.menu-title-notation {
  display: none;
}

.enchant-menu-panel.show-fish .menu-title-fish {
  display: inline;
}

.enchant-menu-panel.show-notation .menu-title-notation {
  display: inline;
}

.enchant-menu-main,
.enchant-menu-options {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-menu-option {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 18px 16px;

  color: #ffffff;
  font-size: 18px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-option:hover {
  background: #21103f;
  border-color: #8f5cff;
}

.enchant-menu-page {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-main,
.enchant-menu-panel.show-notation .enchant-menu-main {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-page-fish,
.enchant-menu-panel.show-notation .enchant-menu-page-notation {
  display: block;
}

.enchant-menu-text {
  color: #ffffff;
  font-size: 14px;
  line-height: 1.35;
  overflow-wrap: anywhere;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px;
  box-sizing: border-box;
}

.enchant-notation-choice {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px 16px;
  margin-bottom: 10px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-notation-choice:hover {
  background: #140a24;
  border-color: #5b347f;
}

.enchant-notation-choice.notation-active {
  background: #21103f;
  border-color: #8f5cff;
  box-shadow: 0 0 12px rgba(143, 92, 255, 0.45);
}

.enchant-menu-back,
.enchant-menu-close {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 110px;
  min-width: 110px;

  margin-left: auto;
  margin-right: auto;

  padding: 8px 18px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 999px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-back {
  margin-top: 14px;
}

.enchant-menu-close {
  margin-top: 24px;
}

.enchant-menu-close:hover,
.enchant-menu-back:hover {
  background: #6d4ab0;
}



.enchant-menu-page-fish {
  margin-top: 0;
}

.enchant-advisor-layout {
  display: grid;
  grid-template-columns: 110px 1fr;
  gap: 14px;
  align-items: start;

  margin-top: 0;
}

.enchant-advisor-rods {
  width: 110px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-advisor-rod {
  width: 110px;
  height: 110px;
  min-height: 110px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  padding: 8px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  color: #ffffff;
  font-size: 11px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
  box-sizing: border-box;

  overflow: hidden;
}

.enchant-advisor-rod:hover,
.enchant-advisor-rod.advisor-rod-active {
  background: #26124d;
  border-color: #9b6cff;
}

.advisor-rod-image {
  width: 64px;
  height: 64px;

  display: flex;
  align-items: center;
  justify-content: center;

  overflow: hidden;
  background: transparent;
  border: none;
  box-shadow: none;
}

.advisor-rod-image a,
.advisor-rod-image span,
.advisor-rod-image figure,
.advisor-rod-image .image,
.advisor-rod-image .mw-file-description,
.advisor-rod-image .mw-default-size {
  display: flex;
  align-items: center;
  justify-content: center;

  width: auto;
  height: auto;
  max-width: 64px;
  max-height: 64px;

  overflow: hidden !important;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;

  line-height: 0;
}

.advisor-rod-image img,
.advisor-rod-image .mw-file-element {
  display: block;

  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;

  margin: 0 auto;
}

.advisor-rod-name {
  width: 100%;

  color: #ffffff;
  font-size: 11px;
  line-height: 1.1;
  text-align: center;
  font-weight: bold;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-advisor-right {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-advisor-output {
  order: 1;

  width: 100%;
  min-height: 170px;
  max-height: 230px;

  margin-top: 0;
  padding: 14px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  color: #ffffff;
  font-size: 14px;
  line-height: 1.45;

  overflow-y: auto;
  overflow-x: hidden;

  box-sizing: border-box;
  white-space: normal;
}

.enchant-advisor-box {
  order: 2;

  width: 100%;
  height: 78px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 24px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-advisor-display {
  max-width: 100%;
  display: block;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;

  color: #6f4bb5;
}

.enchant-advisor-input {
  width: 90%;

  background: transparent;
  border: none;
  outline: none;
  box-shadow: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;

  margin: 0;
  padding: 0;

  overflow: hidden;
  box-sizing: border-box;
}

.enchant-advisor-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.enchant-advisor-check {
  order: 3;

  width: 100%;
  margin-top: 0;
  padding: 10px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 12px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;

  box-sizing: border-box;
}

.enchant-advisor-check:hover {
  background: #6d4ab0;
}



.advisor-result-title {
  font-size: 15px;
  font-weight: bold;
  color: #ffffff;
  margin-bottom: 10px;
}

.advisor-result-row {
  background: #130b25;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 10px;
  margin-bottom: 8px;

  display: flex;
  gap: 8px;
  align-items: center;

  box-sizing: border-box;
}

.advisor-result-row.advisor-best {
  border-color: #8f5cff;
  box-shadow: 0 0 10px rgba(143, 92, 255, 0.35);
}

.advisor-result-row img {
  width: 34px;
  height: 34px;
  object-fit: contain;
  flex: 0 0 34px;
}

.advisor-result-info {
  flex: 1;
  min-width: 0;
}

.advisor-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-level {
  color: #bda2ff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-min {
  color: #8f7bbd;
  font-size: 11px;
  margin-top: 2px;
}



@media screen and (max-width: 900px) {
  .enchant-ui {
    max-width: 850px;
    min-height: 520px;
  }

  .enchant-main {
    gap: 16px;
    padding: 10px 16px 20px 12px;
  }

  .enchant-left {
    min-width: 155px;
  }

  .enchant-heading {
    font-size: 42px;
    margin: 16px 0 22px 0;
  }

  .enchant-display-box {
    height: 165px;
  }

  .enchant-cost-box {
    height: 80px;
    font-size: 40px;
  }

  .enchant-button {
    height: 62px;
    font-size: 30px;
  }
}

@media screen and (max-width: 650px) {
  .enchant-ui {
    min-height: 0;
  }

  .enchant-main {
    flex-direction: column;
    align-items: center;

    padding: 12px;
    gap: 14px;
  }

  .enchant-left {
    width: 45%;
    max-width: 210px;
    min-width: 140px;
    flex: none;
  }

  .enchant-right {
    width: 100%;
  }

  .enchant-heading {
    text-align: center;
    font-size: 36px;
    margin: 8px 0 18px 0;
  }

  .enchant-display-box {
    height: 145px;
  }

  .enchant-line {
    margin: 20px 0;
  }

  .enchant-cost-box {
    height: 75px;
    font-size: 34px;
  }

  .enchant-button {
    width: 80%;
    min-width: 0;
    height: 58px;
    font-size: 28px;
  }

  .rod-popup {
    padding: 14px;
  }

  .rod-popup-panel {
    width: 100%;
    padding: 16px;
  }

  .rod-popup-title {
    font-size: 28px;
  }

  .rod-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .rod-card {
    min-height: 155px;
    padding: 10px;
  }

  .rod-card img {
    max-width: 85px;
    max-height: 85px;
  }
}

@media screen and (max-width: 520px) {
  .enchant-menu-popup {
    width: calc(100% - 16px);
  }

  .enchant-advisor-layout {
    grid-template-columns: 88px 1fr;
    gap: 10px;
  }

  .enchant-advisor-rods {
    width: 88px;
  }

  .enchant-advisor-rod {
    width: 88px;
    height: 88px;
    min-height: 88px;
    font-size: 10px;
    padding: 6px;
  }

  .advisor-rod-image {
    width: 48px;
    height: 48px;
  }

  .advisor-rod-image img,
  .advisor-rod-image .mw-file-element {
    max-width: 46px;
    max-height: 46px;
  }

  .advisor-rod-name {
    font-size: 10px;
  }

  .enchant-advisor-box {
    height: 68px;
    font-size: 20px;
  }
}

@media screen and (max-width: 420px) {
  .enchant-topbar {
    height: 28px;
    font-size: 15px;
  }

  .enchant-main {
    padding: 10px;
  }

  .enchant-left {
    width: 55%;
    min-width: 120px;
  }

  .enchant-heading {
    font-size: 30px;
  }

  .enchant-display-box {
    height: 120px;
  }

  .enchant-info-text {
    font-size: 22px;
  }

  .enchant-cost-box {
    height: 62px;
    font-size: 28px;
  }

  .enchant-button {
    width: 100%;
    height: 52px;
    font-size: 24px;
  }

  .enchant-result-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .enchant-result-card {
    min-height: 115px;
  }

  .enchant-result-card img {
    max-width: 46px;
    max-height: 46px;
  }

  .enchant-result-level {
    font-size: 16px;
  }

  .enchant-menu-popup {
    top: 42px;
    right: 8px;
    bottom: 14px;

    width: calc(100% - 16px);
    max-width: none;
  }

  .enchant-menu-title {
    font-size: 20px;
  }

  .enchant-menu-option {
    font-size: 16px;
    padding: 14px;
  }

  .enchant-menu-text {
    font-size: 13px;
