.enchant-ui {
  width: 100%;
  max-width: 1000px;
  min-height: 575px;
  margin: 0 auto;
  position: relative;

  background: #130b25;
  border: 2px solid #8f5cff;
  box-sizing: border-box;

  font-family: Arial, sans-serif;
  color: #ffffff;

  background-image:
    linear-gradient(
      135deg,
      rgba(140, 80, 255, 0.12) 0%,
      rgba(140, 80, 255, 0.12) 18%,
      transparent 18%,
      transparent 38%,
      rgba(140, 80, 255, 0.08) 38%,
      rgba(140, 80, 255, 0.08) 55%,
      transparent 55%
    );
}

.enchant-topbar {
  position: relative;
  z-index: 1000;

  height: 32px;
  background: #935cff;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 10px;
  box-sizing: border-box;

  font-size: 18px;
  font-weight: bold;
  letter-spacing: 1px;
}

.enchant-topbar-title {
  display: flex;
  align-items: center;
}

.enchant-title-icon {
  margin-right: 8px;
}

.enchant-main {
  display: flex;
  gap: 18px;

  padding: 10px 18px 22px 14px;
  box-sizing: border-box;
}

.enchant-left {
  width: 25%;
  max-width: 230px;
  min-width: 170px;
  flex: 0 0 25%;
}

.enchant-item-slot {
  position: relative;
  overflow: hidden;

  width: 100%;
  height: 0;
  padding-bottom: 100%;

  border: 1px solid #9b6cff;
  background: rgba(55, 30, 90, 0.35);

  box-sizing: border-box;
}

.enchant-right {
  flex: 1;
  min-width: 0;
}

.enchant-heading {
  font-size: 50px;
  font-weight: bold;
  line-height: 1;

  margin: 18px 0 26px 0;
}

.enchant-line {
  width: 100%;
  height: 1px;

  background: #8f5cff;
  margin: 26px 0;
}

.enchant-cost-box {
  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 48px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-fish-points-display {
  max-width: 100%;
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-button {
  width: 55%;
  max-width: 355px;
  min-width: 230px;
  height: 70px;

  margin: 22px auto 0 auto;

  background: #4b347a;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #130b25;
  font-size: 34px;
  font-weight: bold;

  box-sizing: border-box;
}

.enchant-open-picker {
  cursor: pointer;
}

.enchant-item-slot:hover,
.enchant-button:hover {
  outline: 2px solid #9b6cff;
}



.enchant-selected-img {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  align-items: center;
  justify-content: center;
}

.enchant-selected-img img {
  max-width: 75%;
  max-height: 75%;
  width: auto;
  height: auto;
  transform: translateX(20px);
}

.enchant-selected-img.enchant-selected-active {
  display: flex;
}

.rod-popup {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 32px;
  bottom: 0;

  z-index: 100;

  align-items: center;
  justify-content: center;

  background: rgba(8, 4, 20, 0.72);
  box-sizing: border-box;
  padding: 24px;
}

.enchant-ui.rod-picker-open .rod-popup {
  display: flex;
}

.rod-popup-panel {
  width: 90%;
  max-width: 760px;

  background: #170d2f;
  border: 2px solid #8f5cff;
  box-shadow: 0 0 24px rgba(143, 92, 255, 0.35);

