  cursor: pointer;
}

.rod-card:hover {
  background: #26124d;
  border-color: #9b6cff;
}

.rod-card img {
  max-width: 120px;
  max-height: 120px;
  width: auto;
  height: auto;
}



.enchant-points-input {
  width: 90%;
  background: transparent;
  border: none;
  outline: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;
}

