.enchant-menu-button {
  position: relative;
  z-index: 1001;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-width: 32px;
  min-height: 28px;

  color: #ffffff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
  user-select: none;
  pointer-events: auto;

  background: none;
  border: none;
  border-radius: 0;
}

.enchant-menu-button:hover {
  color: #d8c8ff;
}

.enchant-menu-popup {
  display: none;

  position: absolute;
  top: 46px;
  right: 12px;
  bottom: 18px;

  width: 520px;
  max-width: calc(100% - 20px);

  z-index: 1200;

  background: rgba(8, 4, 20, 0.96);
  border: 2px solid #8f5cff;
  border-radius: 16px;

  box-shadow: -8px 0 24px rgba(143, 92, 255, 0.35);

  padding: 14px 18px 18px 18px;
  box-sizing: border-box;

  overflow-y: auto;
  pointer-events: auto;
}

.enchant-ui.enchant-menu-open .enchant-menu-popup {
  display: block;
}

.enchant-menu-panel {
  min-height: 100%;

  display: flex;
  flex-direction: column;

  color: #ffffff;
}

.enchant-menu-title {
  color: #ffffff;
  font-size: 24px;
  font-weight: bold;

  margin-bottom: 10px;
}

.enchant-main-title {
  margin-bottom: 14px;
}

.menu-title-fish,
.menu-title-notation {
  display: none;
}

.enchant-menu-panel.show-fish .menu-title-fish {
  display: inline;
}

.enchant-menu-panel.show-notation .menu-title-notation {
  display: inline;
}

.enchant-menu-main,
.enchant-menu-options {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-menu-option {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 18px 16px;

  color: #ffffff;
  font-size: 18px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-option:hover {
  background: #21103f;
  border-color: #8f5cff;
}

.enchant-menu-page {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-main,
.enchant-menu-panel.show-notation .enchant-menu-main {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-page-fish,
.enchant-menu-panel.show-notation .enchant-menu-page-notation {
  display: block;
}

.enchant-menu-text {
  color: #ffffff;
  font-size: 14px;
  line-height: 1.35;
  overflow-wrap: anywhere;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px;
  box-sizing: border-box;
}

.enchant-notation-choice {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px 16px;
  margin-bottom: 10px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-notation-choice:hover {
