  border-color: #5b347f;
}

.enchant-notation-choice.notation-active {
  background: #21103f;
  border-color: #8f5cff;
  box-shadow: 0 0 12px rgba(143, 92, 255, 0.45);
}

.enchant-menu-back,
.enchant-menu-close {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 110px;
  min-width: 110px;

  margin-left: auto;
  margin-right: auto;

  padding: 8px 18px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 999px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-back {
  margin-top: 14px;
}

.enchant-menu-close {
  margin-top: 24px;
}

.enchant-menu-close:hover,
.enchant-menu-back:hover {
