    width: calc(100% - 16px);
  }

  .enchant-advisor-layout {
    grid-template-columns: 88px 1fr;
    gap: 10px;
  }

  .enchant-advisor-rods {
    width: 88px;
  }

  .enchant-advisor-rod {
    width: 88px;
    height: 88px;
    min-height: 88px;
    font-size: 10px;
    padding: 6px;
  }

  .advisor-rod-image {
    width: 48px;
    height: 48px;
  }

  .advisor-rod-image img,
  .advisor-rod-image .mw-file-element {
    max-width: 46px;
    max-height: 46px;
  }

  .advisor-rod-name {
    font-size: 10px;
  }

  .enchant-advisor-box {
    height: 68px;
    font-size: 20px;
  }
}

@media screen and (max-width: 420px) {
  .enchant-topbar {
    height: 28px;
    font-size: 15px;
  }

  .enchant-main {
    padding: 10px;
  }

  .enchant-left {
    width: 55%;
    min-width: 120px;
  }

  .enchant-heading {
    font-size: 30px;
  }

  .enchant-display-box {
    height: 120px;
  }

  .enchant-info-text {
    font-size: 22px;
  }

  .enchant-cost-box {
    height: 62px;
    font-size: 28px;
  }

  .enchant-button {
    width: 100%;
    height: 52px;
    font-size: 24px;
  }

  .enchant-result-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .enchant-result-card {
    min-height: 115px;
  }

  .enchant-result-card img {
    max-width: 46px;
    max-height: 46px;
  }

  .enchant-result-level {
    font-size: 16px;
  }

  .enchant-menu-popup {
    top: 42px;
    right: 8px;
    bottom: 14px;

    width: calc(100% - 16px);
    max-width: none;
  }

  .enchant-menu-title {
    font-size: 20px;
  }

  .enchant-menu-option {
    font-size: 16px;
    padding: 14px;
  }

  .enchant-menu-text {
    font-size: 13px;
  }
}

@media screen and (max-width: 360px) {
  .rod-popup-title {
    font-size: 24px;
  }

  .rod-card {
    min-height: 135px;
    font-size: 13px;
  }

  .rod-card img {
    max-width: 70px;
    max-height: 70px;
  }
}

@media screen and (max-width: 340px) {
  .enchant-heading {
    font-size: 26px;
  }

  .enchant-cost-box {
    font-size: 24px;
  }

  .enchant-button {
    font-size: 21px;
  }
}
.enchant-advisor-combo-list {
  order: 2;

  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;

  width: 100%;
}

.enchant-advisor-combo-button {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 10px 8px;

  color: #ffffff;
  font-size: 12px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;

  box-sizing: border-box;
}

.enchant-advisor-combo-button:hover,
.enchant-advisor-combo-button.combo-active {
  background: #26124d;
  border-color: #9b6cff;
  box-shadow: 0 0 8px rgba(143, 92, 255, 0.35);
}

.enchant-advisor-level-box {
  order: 3;

  width: 100%;
  height: 78px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 24px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-advisor-level-display {
  max-width: 100%;
  display: block;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;

  color: #6f4bb5;
}

.enchant-advisor-level-input {
  width: 90%;

  background: transparent;
  border: none;
  outline: none;
  box-shadow: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;

  margin: 0;
  padding: 0;

  overflow: hidden;
  box-sizing: border-box;
}

.enchant-advisor-level-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.enchant-advisor-check {
  order: 4;
}

.enchant-ui {
  width: 100%;
  max-width: 1000px;
  min-height: 575px;
  margin: 0 auto;
  position: relative;

  background: #130b25;
  border: 2px solid #8f5cff;
  box-sizing: border-box;

  font-family: Arial, sans-serif;
  color: #ffffff;

  background-image:
    linear-gradient(
      135deg,
      rgba(140, 80, 255, 0.12) 0%,
      rgba(140, 80, 255, 0.12) 18%,
      transparent 18%,
      transparent 38%,
      rgba(140, 80, 255, 0.08) 38%,
      rgba(140, 80, 255, 0.08) 55%,
      transparent 55%
    );
}

.enchant-topbar {
  position: relative;
  z-index: 1000;

  height: 32px;
  background: #935cff;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 10px;
  box-sizing: border-box;

  font-size: 18px;
  font-weight: bold;
  letter-spacing: 1px;
}

.enchant-topbar-title {
  display: flex;
  align-items: center;
}

.enchant-title-icon {
  margin-right: 8px;
}

.enchant-main {
  display: flex;
  gap: 18px;

  padding: 10px 18px 22px 14px;
  box-sizing: border-box;
}

.enchant-left {
  width: 25%;
  max-width: 230px;
  min-width: 170px;
  flex: 0 0 25%;
}

.enchant-item-slot {
  position: relative;
  overflow: hidden;

  width: 100%;
  height: 0;
  padding-bottom: 100%;

  border: 1px solid #9b6cff;
  background: rgba(55, 30, 90, 0.35);

  box-sizing: border-box;
}

.enchant-right {
  flex: 1;
  min-width: 0;
}

.enchant-heading {
  font-size: 50px;
  font-weight: bold;
  line-height: 1;

  margin: 18px 0 26px 0;
}

.enchant-line {
  width: 100%;
  height: 1px;

  background: #8f5cff;
  margin: 26px 0;
}

.enchant-cost-box {
  width: 100%;
  height: 90px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 48px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-fish-points-display {
  max-width: 100%;
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-button {
  width: 55%;
  max-width: 355px;
  min-width: 230px;
  height: 70px;

  margin: 22px auto 0 auto;

  background: #4b347a;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #130b25;
  font-size: 34px;
  font-weight: bold;

  box-sizing: border-box;
}

.enchant-open-picker {
  cursor: pointer;
}

.enchant-item-slot:hover,
.enchant-button:hover {
  outline: 2px solid #9b6cff;
}



.enchant-selected-img {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  align-items: center;
  justify-content: center;
}

.enchant-selected-img img {
  max-width: 75%;
  max-height: 75%;
  width: auto;
  height: auto;
  transform: translateX(20px);
}

.enchant-selected-img.enchant-selected-active {
  display: flex;
}

.rod-popup {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 32px;
  bottom: 0;

  z-index: 100;

  align-items: center;
  justify-content: center;

  background: rgba(8, 4, 20, 0.72);
  box-sizing: border-box;
  padding: 24px;
}

.enchant-ui.rod-picker-open .rod-popup {
  display: flex;
}

.rod-popup-panel {
  width: 90%;
  max-width: 760px;

  background: #170d2f;
  border: 2px solid #8f5cff;
  box-shadow: 0 0 24px rgba(143, 92, 255, 0.35);

  padding: 24px;
  box-sizing: border-box;
}

.rod-popup-title {
  text-align: center;
  font-size: 36px;
  font-weight: bold;
  margin-bottom: 22px;
  color: #ffffff;
}

.rod-grid {
  display: grid;
