  padding: 24px;
  text-align: center;
  color: #bda2ff;
  font-size: 18px;
}

.rod-card {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  min-height: 190px;
  padding: 14px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  text-align: center;
  box-sizing: border-box;

  cursor: pointer;
}

.rod-card:hover {
  background: #26124d;
  border-color: #9b6cff;
}

.rod-card img {
  max-width: 120px;
  max-height: 120px;
  width: auto;
  height: auto;
}



.enchant-points-input {
  width: 90%;
  background: transparent;
  border: none;
  outline: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;
}

.enchant-points-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

