  display: block;

  padding: 12px;

  overflow-y: auto;
  overflow-x: hidden;
}

.enchant-info-text {
  min-height: 100%;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #bda2ff;
  font-size: 30px;
  font-weight: bold;
  text-align: center;
}

.enchant-result-grid {
  display: none;
  width: 100%;

  grid-template-columns: repeat(auto-fit, minmax(90px, 1fr));
  gap: 10px;
}

.enchant-result-card {
  min-height: 130px;

  background: #0b0618;
  border: 2px solid #3b245f;
