  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;

  text-align: center;
  box-sizing: border-box;
  padding: 8px;
}

.enchant-result-card img {
  max-width: 58px;
  max-height: 58px;
