}



.enchant-menu-button {
  position: relative;
  z-index: 1001;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-width: 32px;
  min-height: 28px;

  color: #ffffff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
  user-select: none;
  pointer-events: auto;

  background: none;
  border: none;
  border-radius: 0;
}

.enchant-menu-button:hover {
  color: #d8c8ff;
}

.enchant-menu-popup {
  display: none;

  position: absolute;
  top: 46px;
  right: 12px;
  bottom: 18px;

  width: 520px;
  max-width: calc(100% - 20px);

  z-index: 1200;

  background: rgba(8, 4, 20, 0.96);
  border: 2px solid #8f5cff;
  border-radius: 16px;

  box-shadow: -8px 0 24px rgba(143, 92, 255, 0.35);

  padding: 14px 18px 18px 18px;
  box-sizing: border-box;

  overflow-y: auto;
  pointer-events: auto;
}

.enchant-ui.enchant-menu-open .enchant-menu-popup {
  display: block;
}

.enchant-menu-panel {
  min-height: 100%;

  display: flex;
  flex-direction: column;

  color: #ffffff;
}

.enchant-menu-title {
  color: #ffffff;
  font-size: 24px;
  font-weight: bold;

  margin-bottom: 10px;
}

.enchant-main-title {
  margin-bottom: 14px;
}

.menu-title-fish,
.menu-title-planner,
.menu-title-notation {
  display: none;
}

.enchant-menu-panel.show-fish .menu-title-fish {
  display: inline;
}

.enchant-menu-panel.show-notation .menu-title-notation {
  display: inline;
}

.enchant-menu-panel.show-planner .menu-title-planner {
  display: inline;
}

.enchant-menu-main,
.enchant-menu-options {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-menu-option {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 18px 16px;

  color: #ffffff;
  font-size: 18px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-option:hover {
  background: #21103f;
  border-color: #8f5cff;
}

.enchant-menu-page {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-main,
.enchant-menu-panel.show-planner .enchant-menu-main,
.enchant-menu-panel.show-notation .enchant-menu-main {
  display: none;
}

.enchant-menu-panel.show-fish .enchant-menu-page-fish,
.enchant-menu-panel.show-planner .enchant-menu-page-planner,
.enchant-menu-panel.show-notation .enchant-menu-page-notation {
  display: block;
}

.enchant-planner-enchants {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));
  gap: 10px;
  max-height: 210px;
  overflow-y: auto;
  margin-bottom: 14px;
}

.enchant-planner-choice {
  min-height: 105px;
  padding: 10px;
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 10px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 7px;
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
  text-align: center;
  cursor: pointer;
  box-sizing: border-box;
}

.enchant-planner-choice:hover,
.enchant-planner-choice.planner-active {
  background: #26124d;
  border-color: #9b6cff;
}

.enchant-planner-choice img {
  max-width: 55px;
  max-height: 55px;
  width: auto;
  height: auto;
}

.enchant-planner-loading,
.enchant-planner-selected,
.enchant-planner-output {
  padding: 12px;
  color: #d8c8ff;
  text-align: center;
}

.enchant-planner-loading {
  grid-column: 1 / -1;
}

.enchant-planner-selected {
  margin-bottom: 10px;
  background: rgba(75, 52, 122, 0.45);
  border: 1px solid #6f4bb5;
  border-radius: 8px;
  font-weight: bold;
}

.enchant-planner-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 10px;
  color: #ffffff;
  font-size: 14px;
  font-weight: bold;
}

.enchant-planner-field input {
  width: 100%;
  box-sizing: border-box;
  padding: 10px;
  color: #ffffff;
  font-size: 16px;
  text-align: center;
  background: #130b25;
  border: 1px solid #9b6cff;
  border-radius: 7px;
  outline: none;
}

.enchant-planner-calculate {
  padding: 12px 16px;
  margin: 12px 0;
  color: #ffffff;
  font-size: 17px;
  font-weight: bold;
  text-align: center;
  background: #6d43c4;
  border: 2px solid #9b6cff;
  border-radius: 9px;
  cursor: pointer;
}

.enchant-planner-calculate:hover {
