}

.enchant-planner-output {
  margin-bottom: 10px;
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 10px;
  font-size: 17px;
  font-weight: bold;
}

.enchant-menu-text {
  color: #ffffff;
  font-size: 14px;
  line-height: 1.35;
  overflow-wrap: anywhere;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px;
  box-sizing: border-box;
}

.enchant-notation-choice {
  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 14px 16px;
  margin-bottom: 10px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-notation-choice:hover {
  background: #140a24;
  border-color: #5b347f;
}

.enchant-notation-choice.notation-active {
  background: #21103f;
  border-color: #8f5cff;
  box-shadow: 0 0 12px rgba(143, 92, 255, 0.45);
}

.enchant-menu-back,
.enchant-menu-close {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 110px;
  min-width: 110px;

  margin-left: auto;
  margin-right: auto;

  padding: 8px 18px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 999px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
}

.enchant-menu-back {
  margin-top: 14px;
}

.enchant-menu-close {
  margin-top: 24px;
}

.enchant-menu-close:hover,
.enchant-menu-back:hover {
  background: #6d4ab0;
}



.enchant-menu-page-fish {
  margin-top: 0;
}

.enchant-advisor-layout {
  display: grid;
  grid-template-columns: 110px 1fr;
  gap: 14px;
  align-items: start;

  margin-top: 0;
}

.enchant-advisor-rods {
  width: 110px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-advisor-rod {
  width: 110px;
  height: 110px;
  min-height: 110px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  padding: 8px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  color: #ffffff;
  font-size: 11px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;
  box-sizing: border-box;

  overflow: hidden;
}

.enchant-advisor-rod:hover,
.enchant-advisor-rod.advisor-rod-active {
  background: #26124d;
  border-color: #9b6cff;
}

.advisor-rod-image {
  width: 64px;
  height: 64px;

  display: flex;
  align-items: center;
  justify-content: center;

  overflow: hidden;
  background: transparent;
  border: none;
  box-shadow: none;
}

.advisor-rod-image a,
.advisor-rod-image span,
.advisor-rod-image figure,
.advisor-rod-image .image,
.advisor-rod-image .mw-file-description,
.advisor-rod-image .mw-default-size {
  display: flex;
  align-items: center;
  justify-content: center;

  width: auto;
  height: auto;
  max-width: 64px;
  max-height: 64px;

  overflow: hidden !important;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;

  line-height: 0;
}

.advisor-rod-image img,
.advisor-rod-image .mw-file-element {
  display: block;

  max-width: 58px;
  max-height: 58px;
  width: auto;
  height: auto;

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;

  margin: 0 auto;
}

.advisor-rod-name {
  width: 100%;

  color: #ffffff;
  font-size: 11px;
  line-height: 1.1;
  text-align: center;
  font-weight: bold;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.enchant-advisor-right {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 12px;
}

.enchant-advisor-output {
  order: 1;

  width: 100%;
  min-height: 170px;
  max-height: 230px;

  margin-top: 0;
  padding: 14px;

  background: #0b0618;
  border: 2px solid #3b245f;
  border-radius: 14px;

  color: #ffffff;
  font-size: 14px;
  line-height: 1.45;

  overflow-y: auto;
  overflow-x: hidden;

  box-sizing: border-box;
  white-space: normal;
}

.enchant-advisor-box {
  order: 2;

  width: 100%;
  height: 78px;

  border: 1px solid #3b245f;
  background: rgba(10, 7, 20, 0.45);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #6f4bb5;
  font-size: 24px;
  font-weight: bold;
  font-style: italic;

  box-sizing: border-box;
  overflow: hidden;
  padding: 8px;

  cursor: text;
}

.enchant-advisor-display {
  max-width: 100%;
  display: block;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;

  color: #6f4bb5;
}

.enchant-advisor-input {
  width: 90%;

  background: transparent;
  border: none;
  outline: none;
  box-shadow: none;

  color: #6f4bb5;
  font-size: inherit;
  font-weight: bold;
  font-style: italic;
  text-align: center;

  font-family: inherit;

  margin: 0;
  padding: 0;

  overflow: hidden;
  box-sizing: border-box;
}

.enchant-advisor-input::placeholder {
  color: #6f4bb5;
  opacity: 0.65;
}

.enchant-advisor-check {
  order: 3;

  width: 100%;
  margin-top: 0;
  padding: 10px;

  background: #4b347a;
  border: 2px solid #8f5cff;
  border-radius: 12px;

  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  text-align: center;

  cursor: pointer;
  user-select: none;

  box-sizing: border-box;
}

.enchant-advisor-check:hover {
  background: #6d4ab0;
}



.advisor-result-title {
  font-size: 15px;
  font-weight: bold;
  color: #ffffff;
  margin-bottom: 10px;
}

.advisor-result-row {
  background: #130b25;
  border: 2px solid #3b245f;
  border-radius: 12px;

  padding: 10px;
  margin-bottom: 8px;

  display: flex;
  gap: 8px;
  align-items: center;

  box-sizing: border-box;
}

.advisor-result-row.advisor-best {
  border-color: #8f5cff;
  box-shadow: 0 0 10px rgba(143, 92, 255, 0.35);
}

.advisor-result-row img {
  width: 34px;
  height: 34px;
  object-fit: contain;
  flex: 0 0 34px;
}

.advisor-result-info {
  flex: 1;
  min-width: 0;
}

.advisor-result-name {
  color: #ffffff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-level {
  color: #bda2ff;
  font-size: 13px;
  font-weight: bold;
}

.advisor-result-min {
  color: #8f7bbd;
  font-size: 11px;
  margin-top: 2px;
}



@media screen and (max-width: 900px) {
  .enchant-ui {
    max-width: 850px;
    min-height: 520px;
  }

  .enchant-main {
    gap: 16px;
    padding: 10px 16px 20px 12px;
  }

  .enchant-left {
    min-width: 155px;
  }

  .enchant-heading {
    font-size: 42px;
    margin: 16px 0 22px 0;
  }

  .enchant-display-box {
    height: 165px;
  }

  .enchant-cost-box {
    height: 80px;
    font-size: 40px;
  }

  .enchant-button {
    height: 62px;
    font-size: 30px;
  }
}

@media screen and (max-width: 650px) {
  .enchant-ui {
    min-height: 0;
  }

  .enchant-main {
    flex-direction: column;
    align-items: center;

    padding: 12px;
    gap: 14px;
  }

  .enchant-left {
    width: 45%;
    max-width: 210px;
    min-width: 140px;
    flex: none;
  }

  .enchant-right {
    width: 100%;
  }

  .enchant-heading {
    text-align: center;
    font-size: 36px;
    margin: 8px 0 18px 0;
  }

  .enchant-display-box {
    height: 145px;
  }

  .enchant-line {
    margin: 20px 0;
  }

  .enchant-cost-box {
    height: 75px;
    font-size: 34px;
  }

  .enchant-button {
    width: 80%;
    min-width: 0;
    height: 58px;
    font-size: 28px;
  }

  .rod-popup {
    padding: 14px;
  }

  .rod-popup-panel {
    width: 100%;
    padding: 16px;
  }

  .rod-popup-title {
    font-size: 28px;
  }

  .rod-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .rod-card {
