@media screen and (max-width: 520px) {
  .enchant-menu-popup {
    width: calc(100% - 16px);
  }

  .enchant-advisor-layout {
    grid-template-columns: 88px 1fr;
    gap: 10px;
  }

  .enchant-advisor-rods {
    width: 88px;
