  }

  .enchant-heading {
    font-size: 30px;
  }

  .enchant-display-box {
    height: 120px;
  }

  .enchant-info-text {
    font-size: 22px;
  }

  .enchant-cost-box {
    height: 62px;
    font-size: 28px;
  }

  .enchant-button {
    width: 100%;
