.mastery-show {
  display: none;
}

.mastery-popup {
  display: none;

  position: fixed;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  z-index: 9999;

  background: rgba(0, 0, 0, 0.7);

  align-items: center;
  justify-content: center;
  padding: 18px;
  box-sizing: border-box;
}

.mastery-popup.mastery-popup-open {
  display: flex;
}

.mastery-popup-box {
  width: 100%;
  max-width: 420px;

  background: #07122b;
  border: 3px solid #5aaeff;
  border-radius: 18px;

  padding: 20px;
  box-sizing: border-box;

  text-align: center;
}

.mastery-popup-title {
  color: #5aaeff;
  font-size: 24px;
  font-weight: bold;
  margin-bottom: 14px;
}

.mastery-popup-formula {
  color: #ffffff;
  font-size: 18px;
  font-weight: bold;

  overflow-wrap: anywhere;
  word-break: break-word;

  background: #0b0f17;
  border: 2px solid #222831;
  border-radius: 14px;

  padding: 14px;
  margin-bottom: 16px;
}

.mastery-popup-close,
.mastery-show {
  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;

  padding: 8px 14px;
  cursor: pointer;
}

