    --cf-shadow: 0 16px 40px rgba(0, 0, 0, 0.16), 0 2px 8px rgba(0, 0, 0, 0.08);
    --cf-accent: #3366cc;
    --cf-accent-2: #7b5cff;
    --cf-grid: rgba(0, 0, 0, 0.07);
    --cf-axis: rgba(0, 0, 0, 0.30);
    --cf-fill-top: rgba(51, 102, 204, 0.28);
    --cf-fill-bottom: rgba(51, 102, 204, 0);
