  const DARK_VARS = `
    --cf-bg: rgba(28, 29, 33, 0.97);
    --cf-fg: #eaecf0;
    --cf-fg-muted: #b7bcc3;
    --cf-fg-faint: #8a9099;
    --cf-border: rgba(255, 255, 255, 0.10);
    --cf-divider: rgba(255, 255, 255, 0.08);
    --cf-row-bg: rgba(255, 255, 255, 0.045);
    --cf-shadow: 0 16px 40px rgba(0, 0, 0, 0.60), 0 2px 8px rgba(0, 0, 0, 0.40);
    --cf-accent: #7aa7ff;
    --cf-accent-2: #b39dff;
    --cf-grid: rgba(255, 255, 255, 0.07);
    --cf-axis: rgba(255, 255, 255, 0.30);
    --cf-fill-top: rgba(122, 167, 255, 0.32);
    --cf-fill-bottom: rgba(122, 167, 255, 0);
  `;

  function injectStyles() {
    if (document.getElementById(STYLE_ID)) return;

    const style = document.createElement('style');
    style.id = STYLE_ID;
