    style.textContent = `
      #${TOOLTIP_ID} {
        ${LIGHT_VARS}
        position: fixed;
        z-index: 99999;
        display: none;
        width: 560px;
        max-width: calc(100vw - 24px);
        padding: 14px 16px 12px;
        border: 1px solid var(--cf-border);
