        ${DARK_VARS}
      }

      @media (prefers-color-scheme: dark) {
        html.skin-theme-clientpref-os #${TOOLTIP_ID},
        body.skin-theme-clientpref-os #${TOOLTIP_ID} {
          ${DARK_VARS}
        }
      }

      #${TOOLTIP_ID} .cf-title {
        margin: 0 0 10px;
