      }
    `;
    document.head.appendChild(style);
  }

  function ensureTooltip() {
    let el = document.getElementById(TOOLTIP_ID);
    if (el) return el;

    el = document.createElement('div');
    el.id = TOOLTIP_ID;
    document.body.appendChild(el);
    return el;
  }

  function readTheme(el) {
    const cs = getComputedStyle(el);
    const get = (name, fallback) => cs.getPropertyValue(name).trim() || fallback;
    return {
      bg: get('--cf-bg', 'rgba(255,255,255,0.97)'),
      fg: get('--cf-fg', '#1c1c1e'),
      muted: get('--cf-fg-muted', '#55585c'),
      grid: get('--cf-grid', 'rgba(0,0,0,0.07)'),
      axis: get('--cf-axis', 'rgba(0,0,0,0.30)'),
      accent: get('--cf-accent', '#3366cc'),
      accent2: get('--cf-accent-2', '#7b5cff'),
      fillTop: get('--cf-fill-top', 'rgba(51,102,204,0.28)'),
      fillBottom: get('--cf-fill-bottom', 'rgba(51,102,204,0)'),
    };
  }

  /* ---------------------------------------------------------------------
   * Formula parsing
   * ------------------------------------------------------------------ */

  function normalizeFormula(text) {
    return String(text || '')
      .replace(/\u00A0/g, ' ')
      .replace(/[€$£¥₽₹]/g, '')
      .replace(/(\d{1,3}(?:,\d{3})+)/g, (m) => m.replace(/,/g, ''))
      .trim();
  }

  function isFormulaLike(text) {
    return /[+\-*/^(),]|\b(?:lvl|level|pi|e|sqrt|log10?|ln|abs|floor|ceil|round|min|max|pow|sin|cos|tan)\b/i.test(
      text
    );
  }

  function tokenize(input) {
    const tokens = [];
    let i = 0;

    const isDigit = (c) => c >= '0' && c <= '9';
    const isAlpha = (c) =>
      (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c === '_';

    while (i < input.length) {
      const c = input[i];

      if (/\s/.test(c)) {
        i += 1;
        continue;
      }

      if ('()+-*/%^,'.includes(c)) {
        tokens.push({ type: c, value: c });
        i += 1;
        continue;
      }

      if (isDigit(c) || (c === '.' && isDigit(input[i + 1]))) {
        let j = i + 1;
        while (j < input.length && /[0-9.]/.test(input[j])) j++;

        if (input[j] === 'e' || input[j] === 'E') {
          let k = j + 1;
          if (input[k] === '+' || input[k] === '-') k++;
          if (isDigit(input[k])) {
            while (k < input.length && isDigit(input[k])) k++;
            j = k;
          }
        }

        let num = parseFloat(input.slice(i, j));
        let s = j;
        while (s < input.length && /[A-Za-z]/.test(input[s])) s++;

        if (s > j) {
          const suffix = input.slice(j, s).toLowerCase();
          if (Object.prototype.hasOwnProperty.call(SUFFIX_MAP, suffix)) {
            num *= SUFFIX_MAP[suffix];
            j = s;
          }
        }

        tokens.push({ type: 'number', value: String(num) });
        i = j;
        continue;
      }

      if (isAlpha(c)) {
        let j = i + 1;
        while (j < input.length && /[A-Za-z0-9_]/.test(input[j])) j += 1;
        tokens.push({ type: 'ident', value: input.slice(i, j).toLowerCase() });
        i = j;
        continue;
      }

      i += 1;
    }

    return tokens;
  }

  const PRECEDENCE = {
    'u+': 5, 'u-': 5,
    '^': 4,
    '*': 3, '/': 3, '%': 3,
    '+': 2, '-': 2,
  };
  const RIGHT_ASSOC = new Set(['^', 'u+', 'u-']);

  function toRpn(tokens) {
    const output = [];
    const stack = [];
    const argCountStack = [];
    let prev = null;

    for (let i = 0; i < tokens.length; i += 1) {
      const t = tokens[i];

      if (t.type === 'number') {
        output.push({ type: 'number', value: parseFloat(t.value) });
        prev = t;
        continue;
      }

      if (t.type === 'ident') {
        const next = tokens[i + 1];
        if (next && next.type === '(') {
          stack.push({ type: 'func', value: t.value });
          argCountStack.push(1);
        } else {
          output.push({ type: 'var', value: t.value });
        }
        prev = t;
        continue;
      }

      if (t.type === ',') {
        while (stack.length && stack[stack.length - 1].type !== '(') output.push(stack.pop());
        if (!argCountStack.length) throw new Error('Unexpected comma');
        argCountStack[argCountStack.length - 1] += 1;
        prev = t;
        continue;
      }

      if (t.type === '(') {
        stack.push({ type: '(' });
        prev = t;
        continue;
      }

      if (t.type === ')') {
        while (stack.length && stack[stack.length - 1].type !== '(') output.push(stack.pop());
        if (!stack.length) throw new Error('Mismatched parentheses');
        stack.pop();

        if (stack.length && stack[stack.length - 1].type === 'func') {
          const fn = stack.pop();
          fn.argCount = argCountStack.pop() || 1;
          output.push(fn);
        }

        prev = t;
        continue;
      }

      if ('+-*/%^'.includes(t.type)) {
        let op = t.type;
        const unary =
          !prev || prev.type === '(' || prev.type === ',' || '+-*/%^'.includes(prev.type);
        if (unary && (op === '+' || op === '-')) op = op === '+' ? 'u+' : 'u-';

        while (stack.length) {
          const top = stack[stack.length - 1];
          if (top.type !== 'op') break;

          const p1 = PRECEDENCE[op];
          const p2 = PRECEDENCE[top.value];

          if (
            (RIGHT_ASSOC.has(op) && p1 < p2) ||
            (!RIGHT_ASSOC.has(op) && p1 <= p2)
          ) {
            output.push(stack.pop());
          } else {
            break;
          }
        }

        stack.push({ type: 'op', value: op });
        prev = t;
      }
    }

    while (stack.length) {
      const x = stack.pop();
      if (x.type === '(') throw new Error('Mismatched parentheses');
      output.push(x);
    }

    return output;
  }

  function evaluateRpn(rpn, vars) {
    const stack = [];

    for (const t of rpn) {
      if (t.type === 'number') {
        stack.push(t.value);
        continue;
      }

      if (t.type === 'var') {
        if (t.value === 'pi') stack.push(Math.PI);
        else if (t.value === 'e') stack.push(Math.E);
        else if (Object.prototype.hasOwnProperty.call(vars, t.value)) stack.push(vars[t.value]);
        else throw new Error('Unknown variable: ' + t.value);
        continue;
      }

      if (t.type === 'op') {
        if (t.value === 'u+') { stack.push(+stack.pop()); continue; }
        if (t.value === 'u-') { stack.push(-stack.pop()); continue; }

        const b = stack.pop();
        const a = stack.pop();

        if (t.value === '+') stack.push(a + b);
        else if (t.value === '-') stack.push(a - b);
        else if (t.value === '*') stack.push(a * b);
        else if (t.value === '/') stack.push(a / b);
        else if (t.value === '%') stack.push(a % b);
        else if (t.value === '^') stack.push(Math.pow(a, b));
        else throw new Error('Unknown operator: ' + t.value);
        continue;
      }

      if (t.type === 'func') {
        const args = [];
        for (let i = 0; i < (t.argCount || 1); i += 1) args.unshift(stack.pop());
        const fn = FUNCTIONS[t.value];
        if (!fn) throw new Error('Unknown function: ' + t.value);
        stack.push(fn.apply(null, args));
      }
    }

    if (stack.length !== 1) throw new Error('Invalid expression');
    return stack[0];
  }

  const RPN_CACHE = new Map();

  function compile(expr) {
    const normalized = normalizeFormula(expr);
    if (RPN_CACHE.has(normalized)) return RPN_CACHE.get(normalized);
    const rpn = toRpn(tokenize(normalized));
    RPN_CACHE.set(normalized, rpn);
    return rpn;
  }

  function evaluate(expr, lvl) {
    return evaluateRpn(compile(expr), { lvl, level: lvl });
  }

  function pointsFor(expr, maxLevel) {
    const points = [];
    for (let lvl = 1; lvl <= maxLevel; lvl += 1) {
      let value;
      try {
        value = evaluate(expr, lvl);
      } catch (e) {
        value = NaN;
      }
      points.push({ lvl, value });
    }
    return points;
  }

  /* ---------------------------------------------------------------------
   * Chart.js loading
   * ------------------------------------------------------------------ */

  function loadChartJs() {
    if (window.Chart) return Promise.resolve();
    if (window.__costFormulaChartJsPromise) return window.__costFormulaChartJsPromise;

    window.__costFormulaChartJsPromise = new Promise((resolve, reject) => {
      const existing = document.querySelector('script[src="' + CHART_JS + '"]');
      if (existing) {
        existing.addEventListener('load', resolve, { once: true });
        existing.addEventListener('error', reject, { once: true });
        return;
      }

      const s = document.createElement('script');
      s.src = CHART_JS;
      s.async = true;
      s.onload = () => resolve();
      s.onerror = () => reject(new Error('Failed to load Chart.js'));
      document.head.appendChild(s);
    });

    return window.__costFormulaChartJsPromise;
  }

  /* ---------------------------------------------------------------------
   * Tooltip content
   * ------------------------------------------------------------------ */

  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, (c) => ({
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      '"': '&quot;',
      "'": '&#39;',
    }[c]));
  }

  function buildContent(expr, points, currency) {
    let displayPoints = points;
    let ellipsisHtml = '';

    // If there are too many levels, only show the first 6 and last 6
    if (points.length > 12) {
      const firstHalf = points.slice(0, 6);
      const lastHalf = points.slice(-6);
      displayPoints = firstHalf.concat(lastHalf);

      ellipsisHtml = `
        <div class="cf-row cf-ellipsis">
          ... ${points.length - 12} more levels ...
        </div>`;
    }

    const rows = displayPoints.map((p, i) => {
      const rowHtml = `
        <div class="cf-row">
          <span class="cf-lv">Lv ${p.lvl}</span>
          <span class="cf-val">${escapeHtml(formatShort(p.value, 3) + currency)}</span>
        </div>`;

      // Insert ellipsis after the 6th item
      if (ellipsisHtml && i === 5) {
        return rowHtml + ellipsisHtml;
      }
      return rowHtml;
    }).join('');

    const values = points.map((p) => p.value).filter(Number.isFinite);
    const valid = values.length === points.length && values[0] !== 0;

    const ratioText = valid
      ? `×${formatShort(values[values.length - 1] / values[0], 2)} from Lv 1 → Lv ${points.length}`
      : `Levels 1 – ${points.length}`;

    const warn = values.length !== points.length ? '<span class="cf-warn">⚠ invalid value</span>' : '';

    return `
      <div class="cf-title">${escapeHtml(expr)}</div>
      <div class="cf-chart-box"><canvas></canvas></div>
      <div class="cf-meta"><span>${ratioText}</span>${warn}</div>
      <div class="cf-values">${rows}</div>
    `;
  }

  function positionTooltip(tooltip, x, y) {
    const offsetX = 18;
    const offsetY = 18;
    const margin = 12;

    tooltip.style.left = '0px';
    tooltip.style.top = '0px';
    tooltip.style.display = 'block';
    tooltip.style.visibility = 'hidden';

    const rect = tooltip.getBoundingClientRect();
    let left = x + offsetX;
    let top = y + offsetY;

    if (left + rect.width > window.innerWidth - margin) left = x - rect.width - offsetX;
    if (top + rect.height > window.innerHeight - margin) top = y - rect.height - offsetY;

    tooltip.style.left = Math.max(margin, left) + 'px';
    tooltip.style.top = Math.max(margin, top) + 'px';
    tooltip.style.visibility = 'visible';
  }

  /* ---------------------------------------------------------------------
   * Chart
   * ------------------------------------------------------------------ */

  function rectsOverlap(a, b) {
    return !(a.x2 <= b.x1 || a.x1 >= b.x2 || a.y2 <= b.y1 || a.y1 >= b.y2);
  }

  function makeChart(canvas, expr, points, currency, theme, useLog) {
    const labels = points.map((p) => String(p.lvl));
    const data = points.map((p) => p.value);
    const ctx = canvas.getContext('2d');

    if (canvas._cfChart) {
      canvas._cfChart.destroy();
      canvas._cfChart = null;
    }

    // Point labels with collision avoidance + halo for readability
    const pointLabelPlugin = {
      id: 'cfPointLabels',
      afterDatasetsDraw(chart) {
        // If there are too many points, hide the labels entirely to avoid clutter
        if (data.length > 12) return;

        const { ctx, chartArea } = chart;
        const meta = chart.getDatasetMeta(0);
        if (!meta || !meta.data || !chartArea) return;

        ctx.save();
        ctx.font =
          '600 10px system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif';
        ctx.lineJoin = 'round';

        const placed = [];
        const pad = 6;
        const lh = 11;
        const margin = 4;

        meta.data.forEach((pt, i) => {
          const value = data[i];
          if (!Number.isFinite(value)) return;

          const label = formatShort(value, 2) + currency;
          const w = ctx.measureText(label).width + 2;

          const candidates = [
            { x1: pt.x - pad - w, y1: pt.y - pad - lh, x2: pt.x - pad, y2: pt.y - pad, align: 'right' },
            { x1: pt.x + pad,     y1: pt.y - pad - lh, x2: pt.x + pad + w, y2: pt.y - pad, align: 'left' },
            { x1: pt.x - pad - w, y1: pt.y + pad,      x2: pt.x - pad, y2: pt.y + pad + lh, align: 'right' },
            { x1: pt.x + pad,     y1: pt.y + pad,      x2: pt.x + pad + w, y2: pt.y + pad + lh, align: 'left' },
          ];

          let chosen = null;
          for (const c of candidates) {
            if (c.x1 < chartArea.left + margin) continue;
            if (c.x2 > chartArea.right - margin) continue;
            if (c.y1 < chartArea.top + margin) continue;
            if (c.y2 > chartArea.bottom - margin) continue;
            if (placed.some((r) => rectsOverlap(r, c))) continue;
            chosen = c;
            break;
          }

          if (!chosen) {
            const base = candidates[0];
            const x1 = Math.max(
              chartArea.left + margin,
              Math.min(base.x1, chartArea.right - margin - w)
            );
            const y1 = Math.max(
              chartArea.top + margin,
              Math.min(base.y1, chartArea.bottom - margin - lh)
            );
            chosen = { x1, y1, x2: x1 + w, y2: y1 + lh, align: 'left' };
          }

          placed.push(chosen);

          const tx = chosen.align === 'right' ? chosen.x2 : chosen.x1;
          const ty = (chosen.y1 + chosen.y2) / 2;

          ctx.textAlign = chosen.align;
          ctx.textBaseline = 'middle';

          ctx.lineWidth = 3;
          ctx.strokeStyle = theme.bg;
          ctx.strokeText(label, tx, ty);

          ctx.fillStyle = theme.fg;
          ctx.fillText(label, tx, ty);
        });

        ctx.restore();
      },
    };

    canvas._cfChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [
          {
            label: expr,
            data,
            borderColor: theme.accent,
            borderWidth: 2.5,
            pointRadius: 3.5,
            pointHoverRadius: 6,
            pointBackgroundColor: theme.accent,
            pointBorderColor: theme.bg,
            pointBorderWidth: 1.5,
            pointHoverBackgroundColor: theme.accent2,
            pointHoverBorderColor: theme.bg,
            tension: 0.25,
            fill: true,
            backgroundColor: (context) => {
              const chart = context.chart;
              const { ctx: c, chartArea: ca } = chart;
              if (!ca) return theme.fillTop;
              const g = c.createLinearGradient(0, ca.top, 0, ca.bottom);
              g.addColorStop(0, theme.fillTop);
              g.addColorStop(1, theme.fillBottom);
              return g;
            },
          },
        ],
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: { duration: 220 },
        interaction: {
          mode: 'nearest',
          intersect: false,
        },
        plugins: {
          legend: { display: false },
          tooltip: {
            enabled: true,
            backgroundColor: theme.bg,
            titleColor: theme.fg,
            bodyColor: theme.fg,
            borderColor: theme.axis,
            borderWidth: 1,
            padding: 10,
            displayColors: false,
            cornerRadius: 8,
            titleFont: { weight: '700' },
            callbacks: {
              title(items) {
                return 'Level ' + items[0].label;
              },
              label(item) {
                return 'Cost: ' + formatShort(item.raw, 3) + currency;
              },
            },
          },
        },
        layout: {
          padding: { top: 20, right: 14, bottom: 6, left: 4 },
        },
        scales: {
          x: {
            title: {
              display: true,
              text: 'Level',
              color: theme.muted,
              font: { weight: '700', size: 11 },
            },
            ticks: {
              color: theme.muted,
              font: { size: 10 },
              maxTicksLimit: 10, // Keeps X axis from getting too dense
            },
            grid: {
              color: theme.grid,
              drawTicks: false,
            },
            border: { color: theme.axis },
          },
          y: {
            type: useLog ? 'logarithmic' : 'linear',
            title: {
              display: true,
              text: useLog ? 'Cost (log scale)' : 'Cost',
              color: theme.muted,
              font: { weight: '700', size: 11 },
            },
            ticks: {
              color: theme.muted,
              font: { size: 10 },
              maxTicksLimit: 8, // <--- THIS FIXES THE CRAMPED Y AXIS
              callback(value) {
                return formatShort(value, 1) + currency;
              },
            },
            grid: {
              color: theme.grid,
              drawTicks: false,
            },
            border: { color: theme.axis },
          },
        },
      },
      plugins: [pointLabelPlugin],
    });
  }

  /* ---------------------------------------------------------------------
   * Binding
   * ------------------------------------------------------------------ */

  function bindElement(el, tooltip) {
    if (el.dataset.costFormulaBound === '1') return;
    el.dataset.costFormulaBound = '1';

    let visible = false;
    let hideTimer = null;
    let lastMouse = { x: 0, y: 0 };
    let rafPending = false;

    function getMaxLevel() {
      const cap = Number(el.dataset.cap || el.getAttribute('data-cap'));
      if (Number.isFinite(cap) && cap > 0) return Math.floor(cap);
      return DEFAULT_MAX_LEVEL;
    }

    function getExpr() {
      return normalizeFormula(
        el.dataset.formula || el.getAttribute('data-formula') || el.textContent || ''
      );
    }

    function getCurrency() {
      return el.dataset.currency || el.getAttribute('data-currency') || '€';
    }

    async function show() {
      const expr = getExpr();
      if (!expr || !isFormulaLike(expr)) return;

      try {
        await loadChartJs();

        const points = pointsFor(expr, getMaxLevel());

        tooltip.style.display = 'block';
        tooltip.style.visibility = 'hidden';
        tooltip.innerHTML = buildContent(expr, points, getCurrency());

        const theme = readTheme(tooltip);

        const positive = points.map((p) => p.value).filter((v) => Number.isFinite(v) && v > 0);
        let useLog = false;
        if (positive.length === points.length && positive.length > 1) {
          const min = Math.min.apply(null, positive);
          const max = Math.max.apply(null, positive);
          useLog = min > 0 && max / min >= 5;
        }

        const canvas = tooltip.querySelector('canvas');
        makeChart(canvas, expr, points, getCurrency(), theme, useLog);

        visible = true;
        positionTooltip(tooltip, lastMouse.x, lastMouse.y);
      } catch (e) {
        tooltip.style.display = 'none';
        visible = false;
      }
    }

    function hide() {
      tooltip.style.display = 'none';
      visible = false;

      const canvas = tooltip.querySelector('canvas');
      if (canvas && canvas._cfChart) {
        canvas._cfChart.destroy();
        canvas._cfChart = null;
      }
    }

    el.addEventListener('mouseenter', (e) => {
      clearTimeout(hideTimer);
      lastMouse.x = e.clientX;
      lastMouse.y = e.clientY;
      show();
    });

    el.addEventListener('mousemove', (e) => {
      lastMouse.x = e.clientX;
      lastMouse.y = e.clientY;
      if (!visible) return;
      if (rafPending) return;

      rafPending = true;
      requestAnimationFrame(() => {
        rafPending = false;
        if (tooltip.style.display !== 'none') {
          positionTooltip(tooltip, lastMouse.x, lastMouse.y);
        }
      });
    });

    el.addEventListener('mouseleave', () => {
      clearTimeout(hideTimer);
      hideTimer = setTimeout(hide, 20);
    });
  }

  function init() {
    injectStyles();
    const tooltip = ensureTooltip();

    document.querySelectorAll('.cost-formula').forEach((el) => bindElement(el, tooltip));

    if (!window.__costFormulaObserver && window.MutationObserver) {
      window.__costFormulaObserver = new MutationObserver(() => {
        document
          .querySelectorAll('.cost-formula')
          .forEach((el) => bindElement(el, tooltip));
      });

      window.__costFormulaObserver.observe(document.body, {
        childList: true,
        subtree: true,
      });
    }
  }

  if (window.mw && mw.hook) {
    mw.hook('wikipage.content').add(init);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
});

/* ===== Enchanting ===== */

window.FishNumber = (function () {
  var suffixes = [
    '',
    'k', 'm', 'b', 't', 'qd', 'qn', 'sx', 'sp', 'oc', 'no',
    'de', 'ude', 'dde', 'tde', 'qdde', 'qnde', 'sxde', 'spde', 'ocde', 'node',
    'vt', 'uvt', 'dvt', 'tvt', 'qdvt', 'qnvt', 'sxvt', 'spvt', 'ocvt', 'novt',
    'tg', 'utg', 'dtg', 'ttg', 'qdtg', 'qntg', 'sxtg', 'sptg', 'octg', 'notg',
    'qg', 'uqg', 'dqg', 'tqg', 'qdqg', 'qnqg', 'sxqg', 'spqg', 'ocqg', 'noqg',
    'qag', 'uqag', 'dqag', 'tqag', 'qdqag', 'qnqag', 'sxqag', 'spqag', 'ocqag', 'noqag',
    'sg', 'usg', 'dsg', 'tsg', 'qdsg', 'qnsg', 'sxsg', 'spsg', 'ocsg', 'nosg',
    'spg', 'uspg', 'dspg', 'tspg', 'qdspg', 'qnspg', 'sxspg', 'spspg', 'ocspg', 'nospg',
    'og', 'uog', 'dog', 'tog', 'qdog', 'qnog', 'sxog', 'spog', 'ocog', 'noog',
    'ng', 'ung', 'dng', 'tng', 'qdng', 'qnng', 'sxng', 'spng', 'ocng', 'nong',
    'ce'
  ];

  var multipliers = {};

  suffixes.forEach(function (suffix, index) {
    multipliers[suffix.toLowerCase()] = Math.pow(1000, index);
  });

  function parse(text) {
    var input = String(text || '')
      .trim()
      .toLowerCase()
      .replace(/,/g, '');

    if (input === '') {
      return null;
    }

    var suffixMatch = input.match(/^([0-9]*\.?[0-9]+)([a-z]+)$/i);

    if (suffixMatch) {
      var baseNumber = Number(suffixMatch[1]);
      var suffix = suffixMatch[2].toLowerCase();

      if (!Object.prototype.hasOwnProperty.call(multipliers, suffix)) {
        return null;
      }

      var suffixNumber = baseNumber * multipliers[suffix];

      if (!isFinite(suffixNumber) || suffixNumber < 1) {
        return null;
      }

      return suffixNumber;
    }

    var scientificMatch = input.match(
      /^([0-9]*\.?[0-9]+(?:e[+-]?[0-9]+)?)$/i
    );

    if (!scientificMatch) {
      return null;
    }

    var number = Number(scientificMatch[1]);

    if (!isFinite(number) || number < 1) {
      return null;
    }

    return number;
  }

  function formatSuffix(number) {
    number = Number(number);

    if (!isFinite(number)) {
      return 'Too big';
    }

    var absolute = Math.abs(number);

    if (absolute < 1000) {
      return Math.floor(number).toLocaleString();
    }

    for (var i = suffixes.length - 1; i >= 1; i--) {
      var suffix = suffixes[i];
      var value = multipliers[suffix];

      if (absolute >= value) {
        var shortNumber = number / value;
        var text;

        if (Math.abs(shortNumber) >= 100) {
          text = shortNumber.toFixed(0);
        } else if (Math.abs(shortNumber) >= 10) {
          text = shortNumber.toFixed(1);
        } else {
          text = shortNumber.toFixed(2);
        }

        text = text
          .replace(/\.0+$/, '')
          .replace(/(\.\d*[1-9])0+$/, '$1');

        return text + suffix;
      }
    }

    return String(number);
  }

  function formatScientific(number) {
    number = Number(number);

    if (!isFinite(number)) {
      return 'Too big';
    }

    return number
      .toExponential(2)
      .replace('+', '')
      .replace(/\.00e/, 'e');
  }

  function format(number, notation) {
    if (notation === 'scientific') {
      return formatScientific(number);
    }

    return formatSuffix(number);
  }

  return {
    parse: parse,
    format: format,
    formatSuffix: formatSuffix,
    formatScientific: formatScientific
  };
})();

/* ===== Real Module:EN formatter ===== */
/*
 * JavaScript cannot require a Scribunto module directly.
 * This calls the real Module:EN through MediaWiki's
 * expandtemplates API:
 *
 * {{#invoke:EN|toSuffix|VALUE|2}}
 * {{#invoke:EN|toScientific|VALUE|2}}
 */

window.FishEN = (function () {
  var cache = Object.create(null);
  var requestCounter = 0;

  function normaliseNotation(notation) {
    return notation === 'scientific' ? 'scientific' : 'suffix';
  }

  function normaliseDigits(digits) {
    digits = Math.floor(Number(digits));

    if (!isFinite(digits) || digits < 0) {
      return 2;
    }

    return digits;
  }

  function getFunctionName(notation) {
    return notation === 'scientific'
      ? 'toScientific'
      : 'toSuffix';
  }

  function valueToModuleText(value) {
    var number = Number(value);

    if (!isFinite(number)) {
      return null;
    }

    return String(number);
  }

  function fallback(value, notation) {
    return window.FishNumber.format(value, notation);
  }

  function formatMany(values, notation, digits) {
    notation = normaliseNotation(notation);
    digits = normaliseDigits(digits);

    var results = new Array(values.length);
    var missingValues = [];
    var missingKeys = [];
    var missingKeyPositions = Object.create(null);

    values.forEach(function (value, index) {
      var valueText = valueToModuleText(value);

      if (valueText === null) {
        results[index] = fallback(value, notation);
        return;
      }

      var key = [
        notation,
        digits,
        valueText
      ].join('|');

      if (
        Object.prototype.hasOwnProperty.call(
          cache,
          key
        )
      ) {
        results[index] = cache[key];
        return;
      }

      if (
        !Object.prototype.hasOwnProperty.call(
          missingKeyPositions,
          key
        )
      ) {
        missingKeyPositions[key] = [];
        missingKeys.push(key);
        missingValues.push(valueText);
      }

      missingKeyPositions[key].push(index);
    });

    if (missingValues.length === 0) {
      return Promise.resolve(results);
    }

    requestCounter += 1;

    var separator =
      '@@FISH_EN_SPLIT_' +
      requestCounter +
      '_' +
      Date.now() +
      '@@';

    var functionName =
      getFunctionName(notation);

    var invokeText = missingValues
      .map(function (valueText) {
        return (
          '{{#invoke:EN|' +
          functionName +
          '|' +
          valueText +
          '|' +
          digits +
          '}}'
        );
      })
      .join(separator);

    return mw.loader
      .using('mediawiki.api')
      .then(function () {
        var api = new mw.Api();

        return api.post({
          action: 'expandtemplates',
          text: invokeText,
          prop: 'wikitext',
          title: mw.config.get('wgPageName'),
          formatversion: 2
        });
      })
      .then(function (data) {
        var expanded =
          data &&
          data.expandtemplates &&
          data.expandtemplates.wikitext !== undefined
            ? String(
                data.expandtemplates.wikitext
              )
            : '';

        var parts =
          expanded.split(separator);

        missingValues.forEach(
          function (valueText, missingIndex) {
            var key =
              missingKeys[missingIndex];

            var result = String(
              parts[missingIndex] || ''
            ).trim();

            if (!result) {
              result = fallback(
                Number(valueText),
                notation
              );
            }

            cache[key] = result;

            missingKeyPositions[key].forEach(
              function (position) {
                results[position] = result;
              }
            );
          }
        );

        return results;
      })
      .catch(function (error) {
        console.error(
          'Module:EN formatting failed:',
          error
        );

        values.forEach(
          function (value, index) {
            if (
              results[index] === undefined
            ) {
              results[index] = fallback(
                value,
                notation
              );
            }
          }
        );

        return results;
      });
  }

  function format(
    value,
    notation,
    digits
  ) {
    return formatMany(
      [value],
      notation,
      digits
    ).then(function (results) {
      return results[0];
    });
  }

  function clearCache() {
    cache = Object.create(null);
  }

  return {
    format: format,
    formatMany: formatMany,
    clearCache: clearCache
  };
})();

/* ===== Enchanting calculator ===== */

$(function () {
  localStorage.removeItem(
    'fishIslandFishPoints'
  );

  $(document)
    .off('click.fishEnchantMenuButton')
    .on(
      'click.fishEnchantMenuButton',
      '.enchant-menu-button',
      function (event) {
        event.preventDefault();
        event.stopPropagation();

        var ui = $(this).closest(
          '.enchant-ui'
        );

        if (!ui.length) {
          ui = $('.enchant-ui').first();
        }

        ui.removeClass(
          'rod-picker-open'
        );

        ui.toggleClass(
          'enchant-menu-open'
        );
      }
    );

  $(document)
    .off('click.fishEnchantMenuClose')
    .on(
      'click.fishEnchantMenuClose',
      '.enchant-menu-close',
      function (event) {
        event.preventDefault();
        event.stopPropagation();

        var ui = $(this).closest(
          '.enchant-ui'
        );

        if (!ui.length) {
          ui = $('.enchant-ui').first();
        }

        ui.removeClass(
          'enchant-menu-open'
        );
      }
    );

  function parseFishNumber(text) {
    return window.FishNumber.parse(text);
  }

  function clampUpgradeLevel(value) {
    value = Math.floor(
      Number(value)
    );

    if (!isFinite(value)) {
      value = 0;
    }

    return Math.max(
      0,
      Math.min(25, value)
    );
  }

  function getUpgradeLevel(ui) {
    var upgradeBox = ui.find(
      '.enchant-upgrade-box'
    );

    if (!upgradeBox.length) {
      return 0;
    }

    return clampUpgradeLevel(
      upgradeBox.attr(
        'data-upgrade-level'
      )
    );
  }

  function calculateEnchantBaseLevel(
    fishPoints,
    levelMult,
    upgradeLevel
  ) {
    fishPoints = Number(fishPoints);
    levelMult = Number(levelMult);

    upgradeLevel =
      clampUpgradeLevel(upgradeLevel);

    if (
      !isFinite(fishPoints) ||
      fishPoints < 1 ||
      !isFinite(levelMult) ||
      levelMult <= 0
    ) {
      return null;
    }

    return (
      Math.pow(
        fishPoints *
          Math.pow(
            1.2,
            upgradeLevel
          ),
        0.2
      ) *
      levelMult
    );
  }

  function applyLevelCap(
    level,
    levelCap
  ) {
    if (
      levelCap === undefined ||
      levelCap === null
    ) {
      return level;
    }

    levelCap = Number(levelCap);

    if (!isFinite(levelCap)) {
      return level;
    }

    return Math.min(
      level,
      levelCap
    );
  }

  function calculateEnchantLevelRange(
    fishPoints,
    levelMult,
    upgradeLevel,
    levelCap
  ) {
    var baseLevel =
      calculateEnchantBaseLevel(
        fishPoints,
        levelMult,
        upgradeLevel
      );

    if (baseLevel === null) {
      return {
        min: 1,
        max: 1
      };
    }

    var minLevel = Math.max(
      1,
      Math.ceil(
        baseLevel * 0.9
      )
    );

    var maxLevel = Math.max(
      1,
      Math.ceil(
        baseLevel * 1.1
      )
    );

    minLevel = applyLevelCap(
      minLevel,
      levelCap
    );

    maxLevel = applyLevelCap(
      maxLevel,
      levelCap
    );

    return {
      min: minLevel,
      max: maxLevel
    };
  }

  function getNotation(ui) {
    var activeNotation = ui
      .find(
        '.enchant-notation-choice.notation-active'
      )
      .attr(
        'data-notation'
      );

    if (
      activeNotation === 'suffix' ||
      activeNotation === 'scientific'
    ) {
      return activeNotation;
    }

    var savedNotation =
      localStorage.getItem(
        'fishIslandNotation'
      );

    if (
      savedNotation === 'suffix' ||
      savedNotation === 'scientific'
    ) {
      return savedNotation;
    }

    return 'suffix';
  }

  function formatFishNumber(
    number,
    ui
  ) {
    return window.FishNumber.format(
      number,
      getNotation(ui)
    );
  }

  function formatWithModule(
    values,
    ui
  ) {
    return window.FishEN.formatMany(
      values,
      getNotation(ui),
      2
    );
  }

  function updateSingleFormattedText(
    ui,
    element,
    value,
    suffixText
  ) {
    var notation =
      getNotation(ui);

    var requestId =
      Number(
        element.data(
          'fishEnRequest'
        ) || 0
      ) + 1;

    element.data(
      'fishEnRequest',
      requestId
    );

    element.text(
      window.FishNumber.format(
        value,
        notation
      ) +
        (suffixText || '')
    );

    window.FishEN
      .format(
        value,
        notation,
        2
      )
      .then(function (formatted) {
        if (
          Number(
            element.data(
              'fishEnRequest'
            )
          ) !== requestId
        ) {
          return;
        }

        element.text(
          formatted +
            (suffixText || '')
        );
      });
  }

  function getEnchantListForRodName(
    rodName
  ) {
    if (rodName === 'pistol') {
      return [
        {
          name: 'Less Backfire',
          file: 'less_backfire.png',
          levelMult: 0.75,
          colorClass:
            'enchant-bg-less-backfire'
        },
        {
          name: 'Sharpshooter',
          file: 'Sharpshooter.png',
          levelMult: 0.75,
          colorClass:
            'enchant-bg-sharpshooter'
        }
      ];
    }

    return [
      {
        name: 'Strength',
        file: 'strength.png',
        levelMult: 1,
        colorClass:
          'enchant-bg-strength'
      },
      {
        name: 'Strength+',
        file: 'Strength+.png',
        levelMult: 0.8,
        colorClass:
          'enchant-bg-strength-plus'
      },
      {
        name: 'Momentum',
        file: 'Momentum.png',
        levelMult: 0.65,
        colorClass:
          'enchant-bg-momentum'
      },
      {
        name: 'Momentum+',
        file: 'Momentum+.png',
        levelMult: 0.5,
        colorClass:
          'enchant-bg-momentum-plus'
      },
      {
        name: 'Fortune',
        file: 'Fortune.png',
        levelMult: 0.5,
        colorClass:
          'enchant-bg-fortune'
      },
      {
        name: 'Ultra',
        file: 'Ultra.png',
        levelMult: 0.5,
        colorClass:
          'enchant-bg-ultra'
      }
    ];
  }

  function getEnchantListForUi(ui) {
    if (
      ui.hasClass(
        'rod-pistol'
      )
    ) {
      return getEnchantListForRodName(
        'pistol'
      );
    }

    return getEnchantListForRodName(
      'normal'
    );
  }

  function hasSelectedItem(ui) {
    return (
      ui.hasClass('rod-normal') ||
      ui.hasClass('rod-advanced') ||
      ui.hasClass('rod-momentum') ||
      ui.hasClass('rod-pistol')
    );
  }

  function updateEnchantDisplay(ui) {
    var fishPoints = Number(
      ui
        .find('.enchant-cost-box')
        .attr(
          'data-fish-points'
        )
    );

    var infoText = ui.find(
      '.enchant-info-text'
    );

    var grid = ui.find(
      '.enchant-result-grid'
    );

    var hasRod =
      hasSelectedItem(ui);

    if (
      !hasRod &&
      (
        !fishPoints ||
        fishPoints < 1
      )
    ) {
      grid.hide().empty();

      infoText
        .show()
        .text(
          'Select a rod and input Fish Points'
        );

      return;
    }

    if (!hasRod) {
      grid.hide().empty();

      infoText
        .show()
        .text(
          'Select a rod first'
        );

      return;
    }

    if (
      !fishPoints ||
      fishPoints < 1
    ) {
      grid.hide().empty();

      infoText
        .show()
        .text(
          'Input Fish Points'
        );

      return;
    }

    var enchants =
      getEnchantListForUi(ui);

    var upgradeLevel =
      getUpgradeLevel(ui);

    var valuesToFormat = [];
    var levelElements = [];

    var renderId =
      Number(
        ui.data(
          'enchantDisplayRenderId'
        ) || 0
      ) + 1;

    ui.data(
      'enchantDisplayRenderId',
      renderId
    );

    grid.empty();

    enchants.forEach(
      function (enchant) {
        var levelRange =
          calculateEnchantLevelRange(
            fishPoints,
            enchant.levelMult,
            upgradeLevel,
            enchant.levelCap
          );

        var imgUrl =
          mw.util.getUrl(
            'Special:Redirect/file/' +
              enchant.file
          );

        var card = $('<div>')
          .addClass(
            'enchant-result-card'
          )
          .addClass(
            enchant.colorClass
          );

        $('<img>')
          .attr(
            'src',
            imgUrl
          )
          .attr(
            'alt',
            enchant.name
          )
          .appendTo(card);

        $('<div>')
          .addClass(
            'enchant-result-name'
          )
          .text(
            enchant.name
          )
          .appendTo(card);

        var levelElement =
          $('<div>')
            .addClass(
              'enchant-result-level'
            )
            .text(
              'Level ' +
                formatFishNumber(
                  levelRange.min,
                  ui
                ) +
                ' - ' +
                formatFishNumber(
                  levelRange.max,
                  ui
                )
            )
            .appendTo(card);

        valuesToFormat.push(
          levelRange.min
        );

        valuesToFormat.push(
          levelRange.max
        );

        levelElements.push(
          levelElement
        );

        grid.append(card);
      }
    );

    infoText.hide();

    grid.css(
      'display',
      'grid'
    );

    formatWithModule(
      valuesToFormat,
      ui
    ).then(
      function (formattedValues) {
        if (
          Number(
            ui.data(
              'enchantDisplayRenderId'
            )
          ) !== renderId
        ) {
          return;
        }

        levelElements.forEach(
          function (element, index) {
            element.text(
              'Level ' +
                formattedValues[
                  index * 2
                ] +
                ' - ' +
                formattedValues[
                  index * 2 + 1
                ]
            );
          }
        );
      }
    );
  }

  $('.enchant-ui').each(
    function () {
      var ui = $(this);

      var box = ui.find(
        '.enchant-cost-box'
      );

      var display = ui.find(
        '.enchant-fish-points-display'
      );

      /*
       * Remove the old Fish Advisor controls
       * from the current template HTML.
       */

      ui.find(
        '.enchant-menu-fish-advisor, ' +
        '.enchant-advisor-panel, ' +
        '.enchant-fish-advisor, ' +
        '[class*="enchant-advisor-"]'
      ).remove();

      ui.find(
        '.enchant-menu-panel'
      ).removeClass(
        'show-fish'
      );

      /* ===== Create the 3FH input ===== */

      var upgradeBox = ui.find(
        '.enchant-upgrade-box'
      );

      if (!upgradeBox.length) {
        var enchantLeft = ui
          .find(
            '.enchant-left'
          )
          .first();

        var itemSlot = enchantLeft
          .find(
            '.enchant-item-slot'
          )
          .first();

        upgradeBox = $('<div>')
          .addClass(
            'enchant-upgrade-box'
          )
          .attr(
            'data-upgrade-level',
            '0'
          )
          .css({
            width: '100%',
            minHeight: '86px',
            marginTop: '16px',
            padding: '10px',
            boxSizing: 'border-box',

            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            gap: '6px',

            background:
              'rgba(10, 7, 20, 0.45)',

            border:
              '1px solid #3b245f',

            color: '#bda2ff',
            fontWeight: 'bold',
            textAlign: 'center',
            cursor: 'text'
          });

        $('<div>')
          .addClass(
            'enchant-upgrade-label'
          )
          .text(
            '3FH Upgrade'
          )
          .css({
            fontSize: '15px',
            lineHeight: '1.1'
          })
          .appendTo(
            upgradeBox
          );

        $('<div>')
          .addClass(
            'enchant-upgrade-display'
          )
          .text(
            'Level 0 / 25'
          )
          .css({
            fontSize: '21px',
            lineHeight: '1.1'
          })
          .appendTo(
            upgradeBox
          );

        if (itemSlot.length) {
          itemSlot.after(
            upgradeBox
          );
        } else if (
          enchantLeft.length
        ) {
          enchantLeft.append(
            upgradeBox
          );
        }
      }

      var upgradeDisplay =
        upgradeBox.find(
          '.enchant-upgrade-display'
        );

      if (
        !upgradeDisplay.length
      ) {
        upgradeDisplay =
          $('<div>')
            .addClass(
              'enchant-upgrade-display'
            )
            .appendTo(
              upgradeBox
            );
      }

      var storedUpgradeLevel =
        localStorage.getItem(
          'fishIsland3FHLevel'
        );

      var existingUpgradeLevel =
        upgradeBox.attr(
          'data-upgrade-level'
        );

      var savedUpgradeLevel;

      if (
        storedUpgradeLevel !== null &&
        storedUpgradeLevel !== ''
      ) {
        savedUpgradeLevel =
          clampUpgradeLevel(
            storedUpgradeLevel
          );
      } else {
        savedUpgradeLevel =
          clampUpgradeLevel(
            existingUpgradeLevel
          );
      }

      upgradeBox.attr(
        'data-upgrade-level',
        savedUpgradeLevel
      );

      upgradeDisplay.text(
        'Level ' +
          savedUpgradeLevel +
          ' / 25'
      );

      upgradeBox
        .off(
          'click.fish3FHUpgrade'
        )
        .on(
          'click.fish3FHUpgrade',
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            if (
              upgradeBox.find(
                'input'
              ).length
            ) {
              return;
            }

            var currentLevel =
              getUpgradeLevel(ui);

            var input = $('<input>')
              .addClass(
                'enchant-upgrade-input'
              )
              .attr(
                'type',
                'number'
              )
              .attr(
                'min',
                '0'
              )
              .attr(
                'max',
                '25'
              )
              .attr(
                'step',
                '1'
              )
              .attr(
                'placeholder',
                '0 - 25'
              )
              .val(
                currentLevel
              )
              .css({
                width: '85%',
                height: '34px',
                padding: '4px 8px',
                boxSizing:
                  'border-box',

                background:
                  '#130b25',

                border:
                  '1px solid #9b6cff',

                color: '#ffffff',
                fontSize: '18px',
                fontWeight: 'bold',
                textAlign: 'center',
                outline: 'none'
              });

            upgradeDisplay.hide();

            upgradeBox.append(
              input
            );

            input.focus();
            input.select();

            var didSave = false;

            function saveUpgradeLevel() {
              if (didSave) {
                return;
              }

              didSave = true;

              var upgradeLevel =
                clampUpgradeLevel(
                  input.val()
                );

              upgradeBox.attr(
                'data-upgrade-level',
                upgradeLevel
              );

              localStorage.setItem(
                'fishIsland3FHLevel',
                upgradeLevel
              );

              upgradeDisplay.text(
                'Level ' +
                  upgradeLevel +
                  ' / 25'
              );

              input.remove();

              upgradeDisplay.show();

              updateEnchantDisplay(
                ui
              );
            }

            input.on(
              'keydown',
              function (keyEvent) {
                if (
                  keyEvent.key ===
                  'Enter'
                ) {
                  keyEvent.preventDefault();

                  saveUpgradeLevel();
                }

                if (
                  keyEvent.key ===
                  'Escape'
                ) {
                  didSave = true;

                  input.remove();

                  upgradeDisplay.show();
                }
              }
            );

            input.on(
              'blur',
              saveUpgradeLevel
            );
          }
        );

      var suffixChoice =
        ui.find(
          '.enchant-notation-choice[data-notation="suffix"]'
        );

      var scientificChoice =
        ui.find(
          '.enchant-notation-choice[data-notation="scientific"]'
        );

      if (
        suffixChoice.length &&
        scientificChoice.length
      ) {
        suffixChoice.insertBefore(
          scientificChoice
        );
      }

      function setNotation(
        notation
      ) {
        if (
          notation !== 'suffix' &&
          notation !== 'scientific'
        ) {
          notation = 'suffix';
        }

        localStorage.setItem(
          'fishIslandNotation',
          notation
        );

        ui.attr(
          'data-notation',
          notation
        );

        ui.find(
          '.enchant-notation-choice'
        ).removeClass(
          'notation-active'
        );

        ui.find(
          '.enchant-notation-choice[data-notation="' +
            notation +
            '"]'
        ).addClass(
          'notation-active'
        );

        var fishPoints =
          box.attr(
            'data-fish-points'
          );

        if (
          fishPoints &&
          !isNaN(
            Number(fishPoints)
          ) &&
          Number(fishPoints) >= 1
        ) {
          updateSingleFormattedText(
            ui,
            display,
            Number(fishPoints),
            ' Fish Points'
          );
        }

        updateEnchantDisplay(
          ui
        );
      }

      var savedNotation =
        localStorage.getItem(
          'fishIslandNotation'
        ) || 'suffix';

      setNotation(
        savedNotation
      );

      ui
        .off(
          'click.fishEnchantPicker',
          '.enchant-open-picker'
        )
        .on(
          'click.fishEnchantPicker',
          '.enchant-open-picker',
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            ui.removeClass(
              'enchant-menu-open'
            );

            ui.addClass(
              'rod-picker-open'
            );
          }
        );

      ui.find(
        '.enchant-menu-set-notation'
      )
        .off(
          'click.fishEnchantNotationMenu'
        )
        .on(
          'click.fishEnchantNotationMenu',
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            ui.find(
              '.enchant-menu-panel'
            ).addClass(
              'show-notation'
            );
          }
        );

      ui.find(
        '.enchant-menu-back'
      )
        .off(
          'click.fishEnchantMenuBack'
        )
        .on(
          'click.fishEnchantMenuBack',
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            ui.find(
              '.enchant-menu-panel'
            ).removeClass(
              'show-notation'
            );
          }
        );

      ui.find(
        '.enchant-notation-choice'
      )
        .off(
          'click.fishEnchantNotationChoice'
        )
        .on(
          'click.fishEnchantNotationChoice',
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            setNotation(
              $(this).attr(
                'data-notation'
              )
            );
          }
        );

      ui.find(
        '.rod-card-normal'
      )
        .off(
          'click.fishEnchantRodNormal'
        )
        .on(
          'click.fishEnchantRodNormal',
          function () {
            ui.removeClass(
              'rod-picker-open rod-advanced rod-momentum rod-pistol'
            ).addClass(
              'rod-normal'
            );

            updateEnchantDisplay(
              ui
            );
          }
        );

      ui.find(
        '.rod-card-advanced'
      )
        .off(
          'click.fishEnchantRodAdvanced'
        )
        .on(
          'click.fishEnchantRodAdvanced',
          function () {
            ui.removeClass(
              'rod-picker-open rod-normal rod-momentum rod-pistol'
            ).addClass(
              'rod-advanced'
            );

            updateEnchantDisplay(
              ui
            );
          }
        );

      ui.find(
        '.rod-card-momentum'
      )
        .off(
          'click.fishEnchantRodMomentum'
        )
        .on(
          'click.fishEnchantRodMomentum',
          function () {
            ui.removeClass(
              'rod-picker-open rod-normal rod-advanced rod-pistol'
            ).addClass(
              'rod-momentum'
            );

            updateEnchantDisplay(
              ui
            );
          }
        );

      ui.find(
        '.rod-card-pistol'
      )
        .off(
          'click.fishEnchantRodPistol'
        )
        .on(
          'click.fishEnchantRodPistol',
          function () {
            ui.removeClass(
              'rod-picker-open rod-normal rod-advanced rod-momentum'
            ).addClass(
              'rod-pistol'
            );

            updateEnchantDisplay(
              ui
            );
          }
        );

      box
        .off(
          'click.fishEnchantPoints'
        )
        .on(
          'click.fishEnchantPoints',
          function () {
            if (
              box.find(
                'input'
              ).length
            ) {
              return;
            }

            var currentText =
              display
                .text()
                .trim();

            if (
              currentText ===
                'Fish Points' ||
              currentText.indexOf(
                'Input a real number'
              ) !== -1
            ) {
              currentText = '';
            } else {
              currentText =
                currentText
                  .replace(
                    / fish points?/i,
                    ''
                  )
                  .trim();
            }

            var input = $('<input>')
              .addClass(
                'enchant-points-input'
              )
              .attr(
                'type',
                'text'
              )
              .attr(
                'placeholder',
                'Example: 1, 2k, 3m, 1e6'
              )
              .val(
                currentText
              );

            display.hide();

            box.removeClass(
              'fish-points-error'
            );

            box.append(
              input
            );

            input.focus();

            var didSave = false;

            function saveValue() {
              if (didSave) {
                return;
              }

              didSave = true;

              var raw =
                input
                  .val()
                  .trim();

              var parsed =
                parseFishNumber(
                  raw
                );

              if (
                parsed === null
              ) {
                box.removeAttr(
                  'data-fish-points'
                );

                box.addClass(
                  'fish-points-error'
                );

                display.text(
                  'Input a real number in this format: 1, 2k, 3m, 1e6'
                );

                input.remove();

                display.show();

                updateEnchantDisplay(
                  ui
                );

                return;
              }

              box.attr(
                'data-fish-points',
                parsed
              );

              box.removeClass(
                'fish-points-error'
              );

              input.remove();

              display.show();

              updateSingleFormattedText(
                ui,
                display,
                parsed,
                ' Fish Points'
              );

              updateEnchantDisplay(
                ui
              );
            }

            input.on(
              'keydown',
              function (event) {
                if (
                  event.key ===
                  'Enter'
                ) {
                  event.preventDefault();

                  saveValue();
                }

                if (
                  event.key ===
                  'Escape'
                ) {
                  didSave = true;

                  input.remove();

                  display.show();
                }
              }
            );

            input.on(
              'blur',
              saveValue
            );
          }
        );

      updateEnchantDisplay(
        ui
      );
    }
  );
});

window.FishNumber = (function () {
  var suffixes = [
    '',
    'k', 'm', 'b', 't', 'qd', 'qn', 'sx', 'sp', 'oc', 'no',
    'de', 'ude', 'dde', 'tde', 'qdde', 'qnde', 'sxde', 'spde', 'ocde', 'node',
    'vt', 'uvt', 'dvt', 'tvt', 'qdvt', 'qnvt', 'sxvt', 'spvt', 'ocvt', 'novt',
    'tg', 'utg', 'dtg', 'ttg', 'qdtg', 'qntg', 'sxtg', 'sptg', 'octg', 'notg',
    'qg', 'uqg', 'dqg', 'tqg', 'qdqg', 'qnqg', 'sxqg', 'spqg', 'ocqg', 'noqg',
    'qag', 'uqag', 'dqag', 'tqag', 'qdqag', 'qnqag', 'sxqag', 'spqag', 'ocqag', 'noqag',
    'sg', 'usg', 'dsg', 'tsg', 'qdsg', 'qnsg', 'sxsg', 'spsg', 'ocsg', 'nosg',
    'spg', 'uspg', 'dspg', 'tspg', 'qdspg', 'qnspg', 'sxspg', 'spspg', 'ocspg', 'nospg',
    'og', 'uog', 'dog', 'tog', 'qdog', 'qnog', 'sxog', 'spog', 'ocog', 'noog',
    'ng', 'ung', 'dng', 'tng', 'qdng', 'qnng', 'sxng', 'spng', 'ocng', 'nong',
    'ce'
  ];

  var multipliers = {};

  suffixes.forEach(function (suffix, index) {
    multipliers[suffix.toLowerCase()] = Math.pow(1000, index);
  });

  function parse(text) {
    var input = String(text || '')
      .trim()
      .toLowerCase()
      .replace(/,/g, '');

    if (input === '') {
      return null;
    }

    var suffixMatch = input.match(/^([0-9]*\.?[0-9]+)([a-z]+)$/i);

    if (suffixMatch) {
      var baseNumber = Number(suffixMatch[1]);
      var suffix = suffixMatch[2].toLowerCase();

      if (!Object.prototype.hasOwnProperty.call(multipliers, suffix)) {
        return null;
      }

      var suffixNumber = baseNumber * multipliers[suffix];

      if (!isFinite(suffixNumber) || suffixNumber < 1) {
        return null;
      }

      return suffixNumber;
    }

    var scientificMatch = input.match(
      /^([0-9]*\.?[0-9]+(?:e[+-]?[0-9]+)?)$/i
    );

    if (!scientificMatch) {
      return null;
    }

    var number = Number(scientificMatch[1]);

    if (!isFinite(number) || number < 1) {
      return null;
    }

    return number;
  }

  function formatSuffix(number) {
    number = Number(number);

    if (!isFinite(number)) {
      return 'Too big';
    }

    var absolute = Math.abs(number);

    if (absolute < 1000) {
      return Math.floor(number).toLocaleString();
    }

    for (var i = suffixes.length - 1; i >= 1; i--) {
      var suffix = suffixes[i];
      var value = multipliers[suffix];

      if (absolute >= value) {
        var shortNumber = number / value;
        var text;

        if (Math.abs(shortNumber) >= 100) {
          text = shortNumber.toFixed(0);
        } else if (Math.abs(shortNumber) >= 10) {
          text = shortNumber.toFixed(1);
        } else {
          text = shortNumber.toFixed(2);
        }

        text = text
          .replace(/\.0+$/, '')
          .replace(/(\.\d*[1-9])0+$/, '$1');

        return text + suffix;
      }
    }

    return String(number);
  }

  function formatScientific(number) {
    number = Number(number);

    if (!isFinite(number)) {
      return 'Too big';
    }

    return number
      .toExponential(2)
      .replace('+', '')
      .replace(/\.00e/, 'e');
  }

  function format(number, notation) {
    if (notation === 'scientific') {
      return formatScientific(number);
    }

    return formatSuffix(number);
  }

  return {
    parse: parse,
    format: format,
    formatSuffix: formatSuffix,
    formatScientific: formatScientific
  };
})();




window.FishEN = (function () {
  var cache = Object.create(null);
  var requestCounter = 0;

  function normaliseNotation(notation) {
    return notation === 'scientific' ? 'scientific' : 'suffix';
  }

  function normaliseDigits(digits) {
    digits = Math.floor(Number(digits));

    if (!isFinite(digits) || digits < 0) {
      return 2;
    }

    return digits;
  }

  function getFunctionName(notation) {
    return notation === 'scientific'
      ? 'toScientific'
      : 'toSuffix';
  }

  function valueToModuleText(value) {
    var number = Number(value);

    if (!isFinite(number)) {
      return null;
    }

    return String(number);
  }

  function fallback(value, notation) {
    return window.FishNumber.format(value, notation);
  }

  function formatMany(values, notation, digits) {
    notation = normaliseNotation(notation);
    digits = normaliseDigits(digits);

    var results = new Array(values.length);
    var missingValues = [];
    var missingKeys = [];
    var missingKeyPositions = Object.create(null);

    values.forEach(function (value, index) {
      var valueText = valueToModuleText(value);

      if (valueText === null) {
        results[index] = fallback(value, notation);
        return;
      }

      var key = [
        notation,
        digits,
        valueText
      ].join('|');

      if (
        Object.prototype.hasOwnProperty.call(
          cache,
          key
        )
      ) {
        results[index] = cache[key];
        return;
      }

      if (
        !Object.prototype.hasOwnProperty.call(
          missingKeyPositions,
          key
        )
      ) {
        missingKeyPositions[key] = [];
        missingKeys.push(key);
        missingValues.push(valueText);
      }

      missingKeyPositions[key].push(index);
    });

    if (missingValues.length === 0) {
      return Promise.resolve(results);
    }

    requestCounter += 1;

    var separator =
      '@@FISH_EN_SPLIT_' +
      requestCounter +
      '_' +
      Date.now() +
      '@@';

    var functionName =
      getFunctionName(notation);

    var invokeText = missingValues
      .map(function (valueText) {
        return (
          '{{#invoke:EN|' +
          functionName +
          '|' +
          valueText +
          '|' +
          digits +
          '}}'
        );
      })
      .join(separator);

    return mw.loader
      .using('mediawiki.api')
      .then(function () {
        var api = new mw.Api();

        return api.post({
          action: 'expandtemplates',
          text: invokeText,
          prop: 'wikitext',
          title: mw.config.get('wgPageName'),
          formatversion: 2
        });
      })
      .then(function (data) {
        var expanded =
          data &&
          data.expandtemplates &&
          data.expandtemplates.wikitext !== undefined
            ? String(
                data.expandtemplates.wikitext
              )
            : '';

        var parts =
          expanded.split(separator);

        missingValues.forEach(
          function (valueText, missingIndex) {
            var key =
              missingKeys[missingIndex];

            var result = String(
              parts[missingIndex] || ''
            ).trim();

            if (!result) {
              result = fallback(
                Number(valueText),
                notation
              );
            }

            cache[key] = result;

            missingKeyPositions[key].forEach(
              function (position) {
                results[position] = result;
              }
            );
          }
        );

        return results;
      })
      .catch(function (error) {
        console.error(
          'Module:EN formatting failed:',
          error
        );

        values.forEach(
          function (value, index) {
            if (
              results[index] === undefined
            ) {
              results[index] = fallback(
                value,
                notation
              );
            }
          }
        );

        return results;
      });
  }

  function format(
    value,
    notation,
    digits
  ) {
    return formatMany(
      [value],
      notation,
      digits
    ).then(function (results) {
      return results[0];
    });
  }

  function clearCache() {
    cache = Object.create(null);
  }

  return {
    format: format,
    formatMany: formatMany,
    clearCache: clearCache
  };
})();



$(function () {
  var entriesData =
    window.FishEntriesData || {
      tools: [],
      enchants: []
    };

  localStorage.removeItem(
    'fishIslandFishPoints'
  );

  $(document)
    .off('click.fishEnchantMenuButton')
    .on(
      'click.fishEnchantMenuButton',
      '.enchant-menu-button',
      function (event) {
        event.preventDefault();
        event.stopPropagation();

        var ui = $(this).closest(
          '.enchant-ui'
        );

        if (!ui.length) {
          ui = $('.enchant-ui').first();
        }

        ui.removeClass(
          'rod-picker-open'
        );

        ui.toggleClass(
          'enchant-menu-open'
        );
      }
    );

  $(document)
    .off('click.fishEnchantMenuClose')
    .on(
      'click.fishEnchantMenuClose',
      '.enchant-menu-close',
      function (event) {
        event.preventDefault();
        event.stopPropagation();

        var ui = $(this).closest(
          '.enchant-ui'
        );

        if (!ui.length) {
          ui = $('.enchant-ui').first();
        }

        ui.removeClass(
          'enchant-menu-open'
        );
      }
    );

  function parseFishNumber(text) {
    return window.FishNumber.parse(text);
  }

  function clampUpgradeLevel(value) {
    value = Math.floor(
      Number(value)
    );

    if (!isFinite(value)) {
      value = 0;
    }

    return Math.max(
      0,
      Math.min(25, value)
    );
  }

  function getUpgradeLevel(ui) {
    var upgradeBox = ui.find(
      '.enchant-upgrade-box'
    );

    if (!upgradeBox.length) {
      return 0;
    }

    return clampUpgradeLevel(
      upgradeBox.attr(
        'data-upgrade-level'
      )
    );
  }

  function calculateEnchantBaseLevel(
    fishPoints,
    levelMult,
    upgradeLevel
  ) {
    fishPoints = Number(fishPoints);
    levelMult = Number(levelMult);

    upgradeLevel =
      clampUpgradeLevel(upgradeLevel);

    if (
      !isFinite(fishPoints) ||
      fishPoints < 1 ||
      !isFinite(levelMult) ||
      levelMult <= 0
    ) {
      return null;
    }

    return (
      Math.pow(
        fishPoints *
          Math.pow(
            1.2,
            upgradeLevel
          ),
        0.2
      ) *
      levelMult
    );
  }

  function applyLevelCap(
    level,
    levelCap
  ) {
    if (
      levelCap === undefined ||
      levelCap === null
    ) {
      return level;
    }

    levelCap = Number(levelCap);

    if (!isFinite(levelCap)) {
      return level;
    }

    return Math.min(
      level,
      levelCap
    );
  }

  function calculateEnchantLevelRange(
    fishPoints,
    levelMult,
    upgradeLevel,
    levelCap
  ) {
    var baseLevel =
      calculateEnchantBaseLevel(
        fishPoints,
        levelMult,
        upgradeLevel
      );

    if (baseLevel === null) {
      return {
        min: 1,
        max: 1
      };
    }

    var minLevel = Math.max(
      1,
      Math.ceil(
        baseLevel * 0.9
      )
    );

    var maxLevel = Math.max(
      1,
      Math.ceil(
        baseLevel * 1.1
      )
    );

    minLevel = applyLevelCap(
      minLevel,
      levelCap
    );

    maxLevel = applyLevelCap(
      maxLevel,
      levelCap
    );

    return {
      min: minLevel,
      max: maxLevel
    };
  }

  function getNotation(ui) {
    var activeNotation = ui
      .find(
        '.enchant-notation-choice.notation-active'
      )
      .attr(
        'data-notation'
      );

    if (
      activeNotation === 'suffix' ||
      activeNotation === 'scientific'
    ) {
      return activeNotation;
    }

    var savedNotation =
      localStorage.getItem(
        'fishIslandNotation'
      );

    if (
      savedNotation === 'suffix' ||
      savedNotation === 'scientific'
    ) {
      return savedNotation;
    }

    return 'suffix';
  }

  function formatFishNumber(
    number,
    ui
  ) {
    return window.FishNumber.format(
      number,
      getNotation(ui)
    );
  }

  function formatWithModule(
    values,
    ui
  ) {
    return window.FishEN.formatMany(
      values,
      getNotation(ui),
      2
    );
  }

  function updateSingleFormattedText(
    ui,
    element,
    value,
    suffixText
  ) {
    var notation =
      getNotation(ui);

    var requestId =
      Number(
        element.data(
          'fishEnRequest'
        ) || 0
      ) + 1;

    element.data(
      'fishEnRequest',
      requestId
    );

    element.text(
      window.FishNumber.format(
        value,
        notation
      ) +
        (suffixText || '')
    );

    window.FishEN
      .format(
        value,
        notation,
        2
      )
      .then(function (formatted) {
        if (
          Number(
            element.data(
              'fishEnRequest'
            )
          ) !== requestId
        ) {
          return;
        }

        element.text(
          formatted +
            (suffixText || '')
        );
      });
  }

  function normaliseRodType(value) {
    return String(value || '')
      .trim()
      .toLowerCase();
  }

  function normaliseEnchantName(value) {
    return String(value || '')
      .trim()
      .toLowerCase();
  }

  function getEnchantLevelMult(name) {
    var multipliers = {
      strength: 1,
      'strength+': 0.8,
      momentum: 0.65,
      'momentum+': 0.5,
      fortune: 0.5,
      ultra: 0.5,
      'less backfire': 0.75,
      sharpshooter: 0.75
    };

    var key =
      normaliseEnchantName(name);

    return Object.prototype.hasOwnProperty.call(
      multipliers,
      key
    )
      ? multipliers[key]
      : 1;
  }

  function getEnchantColorClass(name) {
    return (
      'enchant-bg-' +
      normaliseEnchantName(name)
        .replace(/\+/g, '-plus')
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '')
    );
  }

  function getEnchantListForUi(ui) {
    var selectedTool =
      ui.data('selectedTool');

    if (!selectedTool) {
      return [];
    }

    var selectedRodType =
      normaliseRodType(
        selectedTool.rodType
      );

    return (entriesData.enchants || [])
      .filter(function (enchant) {
        return (
          normaliseRodType(
            enchant.rodType
          ) === selectedRodType
        );
      })
      .map(function (enchant) {
        return {
          name: enchant.name,
          file: enchant.image,
          levelMult:
            getEnchantLevelMult(
              enchant.name
            ),
          colorClass:
            getEnchantColorClass(
              enchant.name
            )
        };
      });
  }

  function hasSelectedItem(ui) {
    return Boolean(
      ui.data('selectedTool')
    );
  }

  function updateEnchantDisplay(ui) {
    var fishPoints = Number(
      ui
        .find('.enchant-cost-box')
        .attr(
          'data-fish-points'
        )
    );

    var infoText = ui.find(
      '.enchant-info-text'
    );

    var grid = ui.find(
      '.enchant-result-grid'
    );

    var hasRod =
      hasSelectedItem(ui);

    if (
      !hasRod &&
      (
        !fishPoints ||
        fishPoints < 1
      )
    ) {
      grid.hide().empty();

      infoText
        .show()
        .text(
          'Select a rod and input Fish Points'
        );

      return;
    }

    if (!hasRod) {
      grid.hide().empty();

      infoText
        .show()
        .text(
          'Select a rod first'
        );

      return;
    }

    if (
      !fishPoints ||
      fishPoints < 1
    ) {
      grid.hide().empty();

      infoText
        .show()
        .text(
          'Input Fish Points'
        );

      return;
    }

    var enchants =
      getEnchantListForUi(ui);

    if (!enchants.length) {
      grid.hide().empty();

      infoText
        .show()
        .text(
          'No enchants match this tool type'
        );

      return;
    }

    var upgradeLevel =
      getUpgradeLevel(ui);

    var valuesToFormat = [];
    var levelElements = [];

    var renderId =
      Number(
        ui.data(
          'enchantDisplayRenderId'
        ) || 0
      ) + 1;

    ui.data(
      'enchantDisplayRenderId',
      renderId
    );

    grid.empty();

    enchants.forEach(
      function (enchant) {
        var levelRange =
          calculateEnchantLevelRange(
            fishPoints,
            enchant.levelMult,
            upgradeLevel,
            enchant.levelCap
          );

        var imgUrl =
          mw.util.getUrl(
            'Special:Redirect/file/' +
              enchant.file
          );

        var card = $('<div>')
          .addClass(
            'enchant-result-card'
          )
          .addClass(
            enchant.colorClass
          );

        $('<img>')
          .attr(
            'src',
            imgUrl
          )
          .attr(
            'alt',
            enchant.name
          )
          .appendTo(card);

        $('<div>')
          .addClass(
            'enchant-result-name'
          )
          .text(
            enchant.name
          )
          .appendTo(card);

        var levelElement =
          $('<div>')
            .addClass(
              'enchant-result-level'
            )
            .text(
              'Level ' +
                formatFishNumber(
                  levelRange.min,
                  ui
                ) +
                ' - ' +
                formatFishNumber(
                  levelRange.max,
                  ui
                )
            )
            .appendTo(card);

        valuesToFormat.push(
          levelRange.min
        );

        valuesToFormat.push(
          levelRange.max
        );

        levelElements.push(
          levelElement
        );

        grid.append(card);
      }
    );

    infoText.hide();

    grid.css(
      'display',
      'grid'
    );

    formatWithModule(
      valuesToFormat,
      ui
    ).then(
      function (formattedValues) {
        if (
          Number(
            ui.data(
              'enchantDisplayRenderId'
            )
          ) !== renderId
        ) {
          return;
        }

        levelElements.forEach(
          function (element, index) {
            element.text(
              'Level ' +
                formattedValues[
                  index * 2
                ] +
                ' - ' +
                formattedValues[
                  index * 2 + 1
                ]
            );
          }
        );
      }
    );
  }

  function getFileUrl(fileName) {
    if (!fileName) {
      return '';
    }

    return mw.util.getUrl(
      'Special:Redirect/file/' +
        fileName
    );
  }

  function selectTool(ui, tool) {
    ui.data(
      'selectedTool',
      tool
    );

    ui.removeClass(
      'rod-picker-open'
    );

    var itemSlot = ui.find(
      '.enchant-item-slot'
    );

    itemSlot.empty();

    var selectedImage = $('<div>')
      .addClass(
        'enchant-selected-img enchant-selected-active'
      )
      .appendTo(itemSlot);

    if (tool.image) {
      $('<img>')
        .attr(
          'src',
          getFileUrl(tool.image)
        )
        .attr(
          'alt',
          tool.name
        )
        .appendTo(selectedImage);
    }

    ui.find(
      '.enchant-heading-wrap'
    )
      .empty()
      .append(
        $('<div>')
          .addClass(
            'enchant-heading'
          )
          .text(
            tool.name
          )
      );

    updateEnchantDisplay(ui);
  }

  function buildRodPicker(ui) {
    var grid = ui.find(
      '.rod-grid'
    );

    if (!grid.length) {
      return;
    }

    grid.empty();

    var tools =
      entriesData.tools || [];

    if (!tools.length) {
      $('<div>')
        .addClass(
          'rod-picker-message'
        )
        .text(
          'Loading tools...'
        )
        .appendTo(grid);

      return;
    }

    tools.forEach(function (tool) {
      var card = $('<div>')
        .addClass('rod-card')
        .attr('role', 'button')
        .attr('tabindex', '0')
        .data('toolEntry', tool);

      if (tool.image) {
        $('<img>')
          .attr(
            'src',
            getFileUrl(tool.image)
          )
          .attr(
            'alt',
            tool.name
          )
          .appendTo(card);
      }

      $('<div>')
        .text(tool.name)
        .appendTo(card);

      card.appendTo(grid);
    });
  }

  function applyEntriesData(data) {
    if (!data) {
      return;
    }

    entriesData = {
      tools: Array.isArray(data.tools)
        ? data.tools
        : [],
      enchants: Array.isArray(data.enchants)
        ? data.enchants
        : []
    };

    $('.enchant-ui').each(function () {
      var ui = $(this);
