          )
          .css({
            fontSize: '15px',
            lineHeight: '1.1'
          })
          .appendTo(
            upgradeBox
          );

        $('<div>')
          .addClass(
            'enchant-upgrade-display'
          )
          .text(
            'Level 0 / 25'
          )
          .css({
            fontSize: '21px',
            lineHeight: '1.1'
          })
          .appendTo(
            upgradeBox
          );

        if (itemSlot.length) {
          itemSlot.after(
            upgradeBox
          );
        } else if (
