              'enchant-upgrade-display'
            )
            .appendTo(
              upgradeBox
            );
      }

      var storedUpgradeLevel =
        localStorage.getItem(
          'fishIsland3FHLevel'
        );

      var existingUpgradeLevel =
        upgradeBox.attr(
          'data-upgrade-level'
        );

      var savedUpgradeLevel;

      if (
        storedUpgradeLevel !== null &&
        storedUpgradeLevel !== ''
      ) {
        savedUpgradeLevel =
          clampUpgradeLevel(
            storedUpgradeLevel
          );
      } else {
        savedUpgradeLevel =
          clampUpgradeLevel(
            existingUpgradeLevel
          );
      }

      upgradeBox.attr(
        'data-upgrade-level',
        savedUpgradeLevel
      );

      upgradeDisplay.text(
        'Level ' +
          savedUpgradeLevel +
