      upgradeBox
        .off(
          'click.fish3FHUpgrade'
        )
        .on(
          'click.fish3FHUpgrade',
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            if (
              upgradeBox.find(
                'input'
              ).length
            ) {
              return;
            }

            var currentLevel =
              getUpgradeLevel(ui);

            var input = $('<input>')
              .addClass(
                'enchant-upgrade-input'
              )
              .attr(
                'type',
                'number'
              )
              .attr(
                'min',
                '0'
              )
              .attr(
                'max',
                '25'
              )
              .attr(
                'step',
                '1'
              )
              .attr(
                'placeholder',
                '0 - 25'
              )
              .val(
                currentLevel
              )
              .css({
                width: '85%',
                height: '34px',
                padding: '4px 8px',
                boxSizing:
                  'border-box',

                background:
                  '#130b25',

                border:
                  '1px solid #9b6cff',

                color: '#ffffff',
                fontSize: '18px',
                fontWeight: 'bold',
                textAlign: 'center',
                outline: 'none'
              });

            upgradeDisplay.hide();

            upgradeBox.append(
              input
            );

            input.focus();
            input.select();

            var didSave = false;

            function saveUpgradeLevel() {
              if (didSave) {
                return;
              }

              didSave = true;

              var upgradeLevel =
                clampUpgradeLevel(
                  input.val()
                );

              upgradeBox.attr(
                'data-upgrade-level',
                upgradeLevel
              );

              localStorage.setItem(
                'fishIsland3FHLevel',
