            event.preventDefault();
            event.stopPropagation();

            ui.find(
              '.enchant-menu-panel'
            ).addClass(
              'show-notation'
            );
          }
        );

      ui.find(
        '.enchant-menu-back'
      )
        .off(
          'click.fishEnchantMenuBack'
        )
        .on(
          'click.fishEnchantMenuBack',
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            ui.find(
              '.enchant-menu-panel'
            ).removeClass(
              'show-notation'
            );
          }
        );

      ui.find(
        '.enchant-notation-choice'
      )
        .off(
          'click.fishEnchantNotationChoice'
        )
        .on(
          'click.fishEnchantNotationChoice',
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            setNotation(
              $(this).attr(
                'data-notation'
              )
            );
          }
        );

      ui
        .off(
          'click.fishEnchantDynamicRod',
          '.rod-card'
        )
        .on(
          'click.fishEnchantDynamicRod',
          '.rod-card',
          function () {
            var tool =
              $(this).data(
                'toolEntry'
              );

            if (tool) {
              selectTool(
                ui,
                tool
              );
            }
          }
        );

      ui
        .off(
          'keydown.fishEnchantDynamicRod',
          '.rod-card'
        )
        .on(
          'keydown.fishEnchantDynamicRod',
          '.rod-card',
          function (event) {
            if (
              event.key !== 'Enter' &&
              event.key !== ' '
            ) {
              return;
            }

            event.preventDefault();

            var tool =
              $(this).data(
                'toolEntry'
              );

            if (tool) {
              selectTool(
                ui,
                tool
              );
            }
          }
        );

      buildRodPicker(ui);

      box
        .off(
          'click.fishEnchantPoints'
        )
        .on(
          'click.fishEnchantPoints',
          function () {
            if (
              box.find(
                'input'
              ).length
            ) {
              return;
            }

            var currentText =
              display
                .text()
                .trim();

            if (
              currentText ===
                'Fish Points' ||
              currentText.indexOf(
                'Input a real number'
              ) !== -1
            ) {
              currentText = '';
            } else {
              currentText =
                currentText
                  .replace(
                    / fish points?/i,
                    ''
                  )
                  .trim();
            }

            var input = $('<input>')
              .addClass(
                'enchant-points-input'
              )
              .attr(
                'type',
                'text'
              )
              .attr(
                'placeholder',
                'Example: 1, 2k, 3m, 1e6'
              )
              .val(
                currentText
              );

            display.hide();

            box.removeClass(
              'fish-points-error'
            );

            box.append(
              input
            );

            input.focus();

            var didSave = false;

            function saveValue() {
              if (didSave) {
                return;
              }

              didSave = true;

              var raw =
                input
                  .val()
                  .trim();

              var parsed =
                parseFishNumber(
                  raw
                );

              if (
                parsed === null
              ) {
                box.removeAttr(
                  'data-fish-points'
                );

                box.addClass(
                  'fish-points-error'
                );

                display.text(
                  'Input a real number in this format: 1, 2k, 3m, 1e6'
                );

                input.remove();

                display.show();

                updateEnchantDisplay(
                  ui
                );

                return;
              }

              box.attr(
                'data-fish-points',
                parsed
              );

              box.removeClass(
                'fish-points-error'
              );

              input.remove();

              display.show();

              updateSingleFormattedText(
                ui,
                display,
                parsed,
                ' Fish Points'
              );

              updateEnchantDisplay(
                ui
              );
            }

            input.on(
              'keydown',
              function (event) {
                if (
                  event.key ===
                  'Enter'
                ) {
                  event.preventDefault();

                  saveValue();
                }

                if (
                  event.key ===
                  'Escape'
                ) {
                  didSave = true;

                  input.remove();

                  display.show();
                }
              }
            );

            input.on(
              'blur',
              saveValue
            );
          }
        );

      updateEnchantDisplay(
        ui
      );
    }
  );

  document.addEventListener(
    'fishEntriesDataReady',
    function (event) {
      applyEntriesData(
        event.detail
      );
    }
  );

  if (window.FishEntriesData) {
    applyEntriesData(
      window.FishEntriesData
    );
  }
});

window.FishNumber = (function () {
  var suffixes = [
    '',
    'k', 'm', 'b', 't', 'qd', 'qn', 'sx', 'sp', 'oc', 'no',
    'de', 'ude', 'dde', 'tde', 'qdde', 'qnde', 'sxde', 'spde', 'ocde', 'node',
    'vt', 'uvt', 'dvt', 'tvt', 'qdvt', 'qnvt', 'sxvt', 'spvt', 'ocvt', 'novt',
    'tg', 'utg', 'dtg', 'ttg', 'qdtg', 'qntg', 'sxtg', 'sptg', 'octg', 'notg',
    'qg', 'uqg', 'dqg', 'tqg', 'qdqg', 'qnqg', 'sxqg', 'spqg', 'ocqg', 'noqg',
    'qag', 'uqag', 'dqag', 'tqag', 'qdqag', 'qnqag', 'sxqag', 'spqag', 'ocqag', 'noqag',
    'sg', 'usg', 'dsg', 'tsg', 'qdsg', 'qnsg', 'sxsg', 'spsg', 'ocsg', 'nosg',
    'spg', 'uspg', 'dspg', 'tspg', 'qdspg', 'qnspg', 'sxspg', 'spspg', 'ocspg', 'nospg',
    'og', 'uog', 'dog', 'tog', 'qdog', 'qnog', 'sxog', 'spog', 'ocog', 'noog',
    'ng', 'ung', 'dng', 'tng', 'qdng', 'qnng', 'sxng', 'spng', 'ocng', 'nong',
    'ce'
  ];

  var multipliers = {};

  suffixes.forEach(function (suffix, index) {
    multipliers[suffix.toLowerCase()] = Math.pow(1000, index);
  });

  function parse(text) {
    var input = String(text || '')
      .trim()
      .toLowerCase()
      .replace(/,/g, '');

    if (input === '') {
      return null;
    }

    var suffixMatch = input.match(/^([0-9]*\.?[0-9]+)([a-z]+)$/i);

    if (suffixMatch) {
      var baseNumber = Number(suffixMatch[1]);
      var suffix = suffixMatch[2].toLowerCase();

      if (!Object.prototype.hasOwnProperty.call(multipliers, suffix)) {
        return null;
      }

      var suffixNumber = baseNumber * multipliers[suffix];

      if (!isFinite(suffixNumber) || suffixNumber < 1) {
        return null;
      }

      return suffixNumber;
    }

    var scientificMatch = input.match(
      /^([0-9]*\.?[0-9]+(?:e[+-]?[0-9]+)?)$/i
    );

    if (!scientificMatch) {
      return null;
    }

    var number = Number(scientificMatch[1]);

    if (!isFinite(number) || number < 1) {
      return null;
    }

    return number;
  }

  function formatSuffix(number) {
    number = Number(number);

    if (!isFinite(number)) {
      return 'Too big';
    }

    var absolute = Math.abs(number);

    if (absolute < 1000) {
      return Math.floor(number).toLocaleString();
    }

    for (var i = suffixes.length - 1; i >= 1; i--) {
      var suffix = suffixes[i];
      var value = multipliers[suffix];

      if (absolute >= value) {
        var shortNumber = number / value;
        var text;

        if (Math.abs(shortNumber) >= 100) {
          text = shortNumber.toFixed(0);
        } else if (Math.abs(shortNumber) >= 10) {
          text = shortNumber.toFixed(1);
        } else {
          text = shortNumber.toFixed(2);
        }

        text = text
          .replace(/\.0+$/, '')
          .replace(/(\.\d*[1-9])0+$/, '$1');

        return text + suffix;
      }
    }

    return String(number);
  }

  function formatScientific(number) {
    number = Number(number);

    if (!isFinite(number)) {
      return 'Too big';
    }

    return number
      .toExponential(2)
      .replace('+', '')
      .replace(/\.00e/, 'e');
  }

  function format(number, notation) {
    if (notation === 'scientific') {
      return formatScientific(number);
    }

    return formatSuffix(number);
  }

  return {
    parse: parse,
    format: format,
    formatSuffix: formatSuffix,
    formatScientific: formatScientific
  };
})();




window.FishEN = (function () {
  var cache = Object.create(null);
  var requestCounter = 0;

  function normaliseNotation(notation) {
    return notation === 'scientific' ? 'scientific' : 'suffix';
  }

  function normaliseDigits(digits) {
    digits = Math.floor(Number(digits));

    if (!isFinite(digits) || digits < 0) {
      return 2;
    }

    return digits;
  }

  function getFunctionName(notation) {
    return notation === 'scientific'
      ? 'toScientific'
      : 'toSuffix';
  }

  function valueToModuleText(value) {
    var number = Number(value);

    if (!isFinite(number)) {
      return null;
    }

    return String(number);
  }

  function fallback(value, notation) {
    return window.FishNumber.format(value, notation);
  }

  function formatMany(values, notation, digits) {
    notation = normaliseNotation(notation);
    digits = normaliseDigits(digits);

    var results = new Array(values.length);
    var missingValues = [];
    var missingKeys = [];
    var missingKeyPositions = Object.create(null);

    values.forEach(function (value, index) {
      var valueText = valueToModuleText(value);

      if (valueText === null) {
        results[index] = fallback(value, notation);
        return;
      }

      var key = [
        notation,
        digits,
        valueText
      ].join('|');

      if (
        Object.prototype.hasOwnProperty.call(
          cache,
          key
        )
      ) {
        results[index] = cache[key];
        return;
      }

      if (
        !Object.prototype.hasOwnProperty.call(
          missingKeyPositions,
          key
        )
      ) {
        missingKeyPositions[key] = [];
        missingKeys.push(key);
        missingValues.push(valueText);
      }

      missingKeyPositions[key].push(index);
    });

    if (missingValues.length === 0) {
      return Promise.resolve(results);
    }

    requestCounter += 1;

    var separator =
      '@@FISH_EN_SPLIT_' +
      requestCounter +
      '_' +
      Date.now() +
      '@@';

    var functionName =
      getFunctionName(notation);

    var invokeText = missingValues
      .map(function (valueText) {
        return (
          '{{#invoke:EN|' +
          functionName +
          '|' +
          valueText +
          '|' +
          digits +
          '}}'
        );
      })
      .join(separator);

    return mw.loader
      .using('mediawiki.api')
      .then(function () {
        var api = new mw.Api();

        return api.post({
          action: 'expandtemplates',
          text: invokeText,
          prop: 'wikitext',
          title: mw.config.get('wgPageName'),
          formatversion: 2
        });
      })
      .then(function (data) {
        var expanded =
          data &&
          data.expandtemplates &&
          data.expandtemplates.wikitext !== undefined
            ? String(
                data.expandtemplates.wikitext
              )
            : '';

        var parts =
          expanded.split(separator);

        missingValues.forEach(
          function (valueText, missingIndex) {
            var key =
              missingKeys[missingIndex];

            var result = String(
              parts[missingIndex] || ''
            ).trim();

            if (!result) {
              result = fallback(
                Number(valueText),
                notation
              );
            }

            cache[key] = result;

            missingKeyPositions[key].forEach(
              function (position) {
                results[position] = result;
              }
            );
          }
        );

        return results;
      })
      .catch(function (error) {
        console.error(
          'Module:EN formatting failed:',
          error
        );

        values.forEach(
          function (value, index) {
            if (
              results[index] === undefined
            ) {
              results[index] = fallback(
                value,
                notation
              );
            }
          }
        );

        return results;
      });
  }

  function format(
    value,
    notation,
    digits
  ) {
    return formatMany(
      [value],
      notation,
      digits
    ).then(function (results) {
      return results[0];
    });
  }

  function clearCache() {
    cache = Object.create(null);
  }

  return {
    format: format,
    formatMany: formatMany,
    clearCache: clearCache
  };
})();



$(function () {
  var entriesData =
    window.FishEntriesData || {
      tools: [],
      enchants: []
    };

  localStorage.removeItem(
    'fishIslandFishPoints'
  );

  $(document)
    .off('click.fishEnchantMenuButton')
    .on(
      'click.fishEnchantMenuButton',
      '.enchant-menu-button',
      function (event) {
        event.preventDefault();
        event.stopPropagation();

        var ui = $(this).closest(
          '.enchant-ui'
        );

        if (!ui.length) {
          ui = $('.enchant-ui').first();
        }

        ui.removeClass(
          'rod-picker-open'
        );

        ui.toggleClass(
          'enchant-menu-open'
        );
      }
    );

  $(document)
    .off('click.fishEnchantMenuClose')
    .on(
      'click.fishEnchantMenuClose',
      '.enchant-menu-close',
      function (event) {
        event.preventDefault();
        event.stopPropagation();

        var ui = $(this).closest(
          '.enchant-ui'
        );

        if (!ui.length) {
          ui = $('.enchant-ui').first();
        }

        ui.removeClass(
          'enchant-menu-open'
        );
      }
    );

  function parseFishNumber(text) {
    return window.FishNumber.parse(text);
  }

  function clampUpgradeLevel(value) {
    value = Math.floor(
      Number(value)
    );

    if (!isFinite(value)) {
      value = 0;
    }

    return Math.max(
      0,
      Math.min(25, value)
    );
  }

  function getUpgradeLevel(ui) {
    var upgradeBox = ui.find(
      '.enchant-upgrade-box'
    );

    if (!upgradeBox.length) {
      return 0;
    }

    return clampUpgradeLevel(
      upgradeBox.attr(
        'data-upgrade-level'
      )
    );
  }

  function calculateEnchantBaseLevel(
    fishPoints,
    levelMult,
    upgradeLevel
  ) {
    fishPoints = Number(fishPoints);
    levelMult = Number(levelMult);

    upgradeLevel =
      clampUpgradeLevel(upgradeLevel);

    if (
      !isFinite(fishPoints) ||
      fishPoints < 1 ||
      !isFinite(levelMult) ||
      levelMult <= 0
    ) {
      return null;
    }

    return (
      Math.pow(
        fishPoints *
          Math.pow(
            1.2,
            upgradeLevel
          ),
        0.2
      ) *
      levelMult
    );
  }

  function applyLevelCap(
    level,
    levelCap
  ) {
    if (
      levelCap === undefined ||
      levelCap === null
    ) {
      return level;
    }

    levelCap = Number(levelCap);

    if (!isFinite(levelCap)) {
      return level;
    }

    return Math.min(
      level,
      levelCap
    );
  }

  function calculateEnchantLevelRange(
    fishPoints,
    levelMult,
    upgradeLevel,
    levelCap
  ) {
    var baseLevel =
      calculateEnchantBaseLevel(
        fishPoints,
        levelMult,
        upgradeLevel
      );

    if (baseLevel === null) {
      return {
        min: 1,
        max: 1
      };
    }

    var minLevel = Math.max(
      1,
      Math.ceil(
        baseLevel * 0.9
      )
    );

    var maxLevel = Math.max(
      1,
      Math.ceil(
        baseLevel * 1.1
      )
    );

    minLevel = applyLevelCap(
      minLevel,
      levelCap
    );

    maxLevel = applyLevelCap(
      maxLevel,
      levelCap
    );

    return {
      min: minLevel,
      max: maxLevel
    };
  }

  function getNotation(ui) {
    var activeNotation = ui
      .find(
        '.enchant-notation-choice.notation-active'
      )
      .attr(
        'data-notation'
      );

    if (
      activeNotation === 'suffix' ||
      activeNotation === 'scientific'
    ) {
      return activeNotation;
    }

    var savedNotation =
      localStorage.getItem(
        'fishIslandNotation'
      );

    if (
      savedNotation === 'suffix' ||
      savedNotation === 'scientific'
    ) {
      return savedNotation;
    }

    return 'suffix';
  }

  function formatFishNumber(
    number,
    ui
  ) {
    return window.FishNumber.format(
      number,
      getNotation(ui)
    );
  }

  function formatWithModule(
    values,
    ui
  ) {
    return window.FishEN.formatMany(
      values,
      getNotation(ui),
      2
    );
  }

  function updateSingleFormattedText(
    ui,
    element,
    value,
    suffixText
  ) {
    var notation =
      getNotation(ui);

    var requestId =
      Number(
        element.data(
          'fishEnRequest'
        ) || 0
      ) + 1;

    element.data(
      'fishEnRequest',
      requestId
    );

    element.text(
      window.FishNumber.format(
        value,
        notation
      ) +
        (suffixText || '')
    );

    window.FishEN
      .format(
        value,
        notation,
        2
      )
      .then(function (formatted) {
        if (
          Number(
            element.data(
              'fishEnRequest'
            )
          ) !== requestId
        ) {
          return;
        }

        element.text(
          formatted +
            (suffixText || '')
        );
      });
  }

  function normaliseRodType(value) {
    return String(value || '')
      .trim()
      .toLowerCase();
  }

  function normaliseEnchantName(value) {
    return String(value || '')
      .trim()
      .toLowerCase();
  }

  function getEnchantLevelMult(name) {
    var multipliers = {
      strength: 1,
      'strength+': 0.8,
      momentum: 0.65,
      'momentum+': 0.5,
      fortune: 0.5,
      ultra: 0.5,
      'less backfire': 0.75,
      sharpshooter: 0.75
    };

    var key =
      normaliseEnchantName(name);

    return Object.prototype.hasOwnProperty.call(
      multipliers,
      key
    )
      ? multipliers[key]
      : 1;
  }

  function getEnchantColorClass(name) {
    return (
      'enchant-bg-' +
      normaliseEnchantName(name)
        .replace(/\+/g, '-plus')
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '')
    );
  }

  function getEnchantListForUi(ui) {
    var selectedTool =
      ui.data('selectedTool');

    if (!selectedTool) {
      return [];
    }

    var selectedRodType =
      normaliseRodType(
        selectedTool.rodType
      );

    return (entriesData.enchants || [])
      .filter(function (enchant) {
        return (
          normaliseRodType(
            enchant.rodType
          ) === selectedRodType
        );
      })
      .map(function (enchant) {
        return {
          name: enchant.name,
          file: enchant.image,
          levelMult:
            getEnchantLevelMult(
              enchant.name
            ),
          colorClass:
            getEnchantColorClass(
              enchant.name
            )
        };
      });
  }

  function hasSelectedItem(ui) {
    return Boolean(
      ui.data('selectedTool')
    );
  }

  function updateEnchantDisplay(ui) {
    var fishPoints = Number(
      ui
        .find('.enchant-cost-box')
        .attr(
          'data-fish-points'
        )
    );

    var infoText = ui.find(
      '.enchant-info-text'
    );

    var grid = ui.find(
      '.enchant-result-grid'
    );

    var hasRod =
      hasSelectedItem(ui);

    if (
      !hasRod &&
      (
        !fishPoints ||
        fishPoints < 1
      )
    ) {
      grid.hide().empty();

      infoText
        .show()
        .text(
          'Select a rod and input Fish Points'
        );

      return;
    }

    if (!hasRod) {
      grid.hide().empty();

      infoText
        .show()
        .text(
          'Select a rod first'
        );

      return;
    }

    if (
      !fishPoints ||
      fishPoints < 1
    ) {
      grid.hide().empty();

      infoText
        .show()
        .text(
          'Input Fish Points'
        );

      return;
    }

    var enchants =
      getEnchantListForUi(ui);

    if (!enchants.length) {
      grid.hide().empty();

      infoText
        .show()
        .text(
          'No enchants match this tool type'
        );

      return;
    }

    var upgradeLevel =
      getUpgradeLevel(ui);

    var valuesToFormat = [];
    var levelElements = [];

    var renderId =
      Number(
        ui.data(
          'enchantDisplayRenderId'
        ) || 0
      ) + 1;

    ui.data(
      'enchantDisplayRenderId',
      renderId
    );

    grid.empty();

    enchants.forEach(
      function (enchant) {
        var levelRange =
          calculateEnchantLevelRange(
            fishPoints,
            enchant.levelMult,
            upgradeLevel,
            enchant.levelCap
          );

        var imgUrl =
          mw.util.getUrl(
            'Special:Redirect/file/' +
              enchant.file
          );

        var card = $('<div>')
          .addClass(
            'enchant-result-card'
          )
          .addClass(
            enchant.colorClass
          );

        $('<img>')
          .attr(
            'src',
            imgUrl
          )
          .attr(
            'alt',
            enchant.name
          )
          .appendTo(card);

        $('<div>')
          .addClass(
            'enchant-result-name'
          )
          .text(
            enchant.name
          )
          .appendTo(card);

        var levelElement =
          $('<div>')
            .addClass(
              'enchant-result-level'
            )
            .text(
              'Level ' +
                formatFishNumber(
                  levelRange.min,
                  ui
                ) +
                ' - ' +
                formatFishNumber(
                  levelRange.max,
                  ui
                )
            )
            .appendTo(card);

        valuesToFormat.push(
          levelRange.min
        );

        valuesToFormat.push(
          levelRange.max
        );

        levelElements.push(
          levelElement
        );

        grid.append(card);
      }
    );

    infoText.hide();

    grid.css(
      'display',
      'grid'
    );

    formatWithModule(
      valuesToFormat,
      ui
    ).then(
      function (formattedValues) {
        if (
          Number(
            ui.data(
              'enchantDisplayRenderId'
            )
          ) !== renderId
        ) {
          return;
        }

        levelElements.forEach(
          function (element, index) {
            element.text(
              'Level ' +
                formattedValues[
                  index * 2
                ] +
                ' - ' +
                formattedValues[
                  index * 2 + 1
                ]
            );
          }
        );
      }
    );
  }

  function getFileUrl(fileName) {
    if (!fileName) {
      return '';
    }

    return mw.util.getUrl(
      'Special:Redirect/file/' +
        fileName
    );
  }

  function selectTool(ui, tool) {
    ui.data(
      'selectedTool',
      tool
    );

    ui.removeClass(
      'rod-picker-open'
    );

    var itemSlot = ui.find(
      '.enchant-item-slot'
    );

    itemSlot.empty();

    var selectedImage = $('<div>')
      .addClass(
        'enchant-selected-img enchant-selected-active'
      )
      .appendTo(itemSlot);

    if (tool.image) {
      $('<img>')
        .attr(
          'src',
          getFileUrl(tool.image)
        )
        .attr(
          'alt',
          tool.name
        )
        .appendTo(selectedImage);
    }

    ui.find(
      '.enchant-heading-wrap'
    )
      .empty()
      .append(
        $('<div>')
          .addClass(
            'enchant-heading'
          )
          .text(
            tool.name
          )
      );

    updateEnchantDisplay(ui);
  }

  function buildRodPicker(ui) {
    var grid = ui.find(
      '.rod-grid'
    );

    if (!grid.length) {
      return;
    }

    grid.empty();

    var tools =
      entriesData.tools || [];

    if (!tools.length) {
      $('<div>')
        .addClass(
          'rod-picker-message'
        )
        .text(
          'Loading tools...'
        )
        .appendTo(grid);

      return;
    }

    tools.forEach(function (tool) {
      var card = $('<div>')
        .addClass('rod-card')
        .attr('role', 'button')
        .attr('tabindex', '0')
        .data('toolEntry', tool);

      if (tool.image) {
        $('<img>')
          .attr(
            'src',
            getFileUrl(tool.image)
          )
          .attr(
            'alt',
            tool.name
          )
          .appendTo(card);
      }

      $('<div>')
        .text(tool.name)
        .appendTo(card);

      card.appendTo(grid);
    });
  }

  function applyEntriesData(data) {
    if (!data) {
      return;
    }

    entriesData = {
      tools: Array.isArray(data.tools)
        ? data.tools
        : [],
      enchants: Array.isArray(data.enchants)
        ? data.enchants
        : []
    };

    $('.enchant-ui').each(function () {
      var ui = $(this);
      buildRodPicker(ui);

      if (hasSelectedItem(ui)) {
        updateEnchantDisplay(ui);
      }
    });
  }

  $('.enchant-ui').each(
    function () {
      var ui = $(this);

      var box = ui.find(
        '.enchant-cost-box'
      );

      var display = ui.find(
        '.enchant-fish-points-display'
      );



      ui.find(
        '.enchant-menu-fish-advisor, ' +
        '.enchant-advisor-panel, ' +
        '.enchant-fish-advisor, ' +
        '[class*="enchant-advisor-"]'
      ).remove();

      ui.find(
        '.enchant-menu-panel'
      ).removeClass(
        'show-fish'
      );



      var upgradeBox = ui.find(
        '.enchant-upgrade-box'
      );

      if (!upgradeBox.length) {
        var enchantLeft = ui
          .find(
            '.enchant-left'
          )
          .first();

        var itemSlot = enchantLeft
          .find(
            '.enchant-item-slot'
          )
          .first();

        upgradeBox = $('<div>')
          .addClass(
            'enchant-upgrade-box'
          )
          .attr(
            'data-upgrade-level',
            '0'
          )
          .css({
            width: '100%',
            minHeight: '86px',
            marginTop: '16px',
            padding: '10px',
            boxSizing: 'border-box',

            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            gap: '6px',

            background:
              'rgba(10, 7, 20, 0.45)',

            border:
              '1px solid #3b245f',

            color: '#bda2ff',
            fontWeight: 'bold',
            textAlign: 'center',
            cursor: 'text'
          });

        $('<div>')
          .addClass(
            'enchant-upgrade-label'
          )
          .text(
            '3FH Upgrade'
          )
          .css({
            fontSize: '15px',
            lineHeight: '1.1'
          })
          .appendTo(
            upgradeBox
          );

        $('<div>')
          .addClass(
            'enchant-upgrade-display'
          )
          .text(
            'Level 0 / 25'
          )
          .css({
            fontSize: '21px',
            lineHeight: '1.1'
          })
          .appendTo(
            upgradeBox
          );

        if (itemSlot.length) {
          itemSlot.after(
            upgradeBox
          );
        } else if (
          enchantLeft.length
        ) {
          enchantLeft.append(
            upgradeBox
          );
        }
      }

      var upgradeDisplay =
        upgradeBox.find(
          '.enchant-upgrade-display'
        );

      if (
        !upgradeDisplay.length
      ) {
        upgradeDisplay =
          $('<div>')
            .addClass(
              'enchant-upgrade-display'
            )
            .appendTo(
              upgradeBox
            );
      }

      var storedUpgradeLevel =
        localStorage.getItem(
          'fishIsland3FHLevel'
        );

      var existingUpgradeLevel =
        upgradeBox.attr(
          'data-upgrade-level'
        );

      var savedUpgradeLevel;

      if (
        storedUpgradeLevel !== null &&
        storedUpgradeLevel !== ''
      ) {
        savedUpgradeLevel =
          clampUpgradeLevel(
            storedUpgradeLevel
          );
      } else {
        savedUpgradeLevel =
          clampUpgradeLevel(
            existingUpgradeLevel
          );
      }

      upgradeBox.attr(
        'data-upgrade-level',
        savedUpgradeLevel
      );

      upgradeDisplay.text(
        'Level ' +
          savedUpgradeLevel +
          ' / 25'
      );

      upgradeBox
        .off(
          'click.fish3FHUpgrade'
        )
        .on(
          'click.fish3FHUpgrade',
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            if (
              upgradeBox.find(
                'input'
              ).length
            ) {
              return;
            }

            var currentLevel =
              getUpgradeLevel(ui);

            var input = $('<input>')
              .addClass(
                'enchant-upgrade-input'
              )
              .attr(
                'type',
                'number'
              )
              .attr(
                'min',
                '0'
              )
              .attr(
                'max',
                '25'
              )
              .attr(
                'step',
                '1'
              )
              .attr(
                'placeholder',
                '0 - 25'
              )
              .val(
                currentLevel
              )
              .css({
                width: '85%',
                height: '34px',
                padding: '4px 8px',
                boxSizing:
                  'border-box',

                background:
                  '#130b25',

                border:
                  '1px solid #9b6cff',

                color: '#ffffff',
                fontSize: '18px',
                fontWeight: 'bold',
                textAlign: 'center',
                outline: 'none'
              });

            upgradeDisplay.hide();

            upgradeBox.append(
              input
            );

            input.focus();
            input.select();

            var didSave = false;

            function saveUpgradeLevel() {
              if (didSave) {
                return;
              }

              didSave = true;

              var upgradeLevel =
                clampUpgradeLevel(
                  input.val()
                );

              upgradeBox.attr(
                'data-upgrade-level',
                upgradeLevel
              );

              localStorage.setItem(
                'fishIsland3FHLevel',
                upgradeLevel
              );

              upgradeDisplay.text(
                'Level ' +
                  upgradeLevel +
                  ' / 25'
              );

              input.remove();

              upgradeDisplay.show();

              updateEnchantDisplay(
                ui
              );
            }

            input.on(
              'keydown',
              function (keyEvent) {
                if (
                  keyEvent.key ===
                  'Enter'
                ) {
                  keyEvent.preventDefault();

                  saveUpgradeLevel();
                }

                if (
                  keyEvent.key ===
                  'Escape'
                ) {
                  didSave = true;

                  input.remove();

                  upgradeDisplay.show();
                }
              }
            );

            input.on(
              'blur',
              saveUpgradeLevel
            );
          }
        );

      var suffixChoice =
        ui.find(
          '.enchant-notation-choice[data-notation="suffix"]'
        );

      var scientificChoice =
        ui.find(
          '.enchant-notation-choice[data-notation="scientific"]'
        );

      if (
        suffixChoice.length &&
        scientificChoice.length
      ) {
        suffixChoice.insertBefore(
          scientificChoice
        );
      }

      function setNotation(
        notation
      ) {
        if (
          notation !== 'suffix' &&
          notation !== 'scientific'
        ) {
          notation = 'suffix';
        }

        localStorage.setItem(
          'fishIslandNotation',
          notation
        );

        ui.attr(
          'data-notation',
          notation
        );

        ui.find(
          '.enchant-notation-choice'
        ).removeClass(
          'notation-active'
        );

        ui.find(
          '.enchant-notation-choice[data-notation="' +
            notation +
            '"]'
        ).addClass(
          'notation-active'
        );

        var fishPoints =
          box.attr(
            'data-fish-points'
          );

        if (
          fishPoints &&
          !isNaN(
            Number(fishPoints)
          ) &&
          Number(fishPoints) >= 1
        ) {
          updateSingleFormattedText(
            ui,
            display,
            Number(fishPoints),
            ' Fish Points'
          );
        }

        updateEnchantDisplay(
          ui
        );
      }

      var savedNotation =
        localStorage.getItem(
          'fishIslandNotation'
        ) || 'suffix';

      setNotation(
        savedNotation
      );

      ui
        .off(
          'click.fishEnchantPicker',
          '.enchant-open-picker'
        )
        .on(
          'click.fishEnchantPicker',
          '.enchant-open-picker',
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            ui.removeClass(
              'enchant-menu-open'
            );

            ui.addClass(
              'rod-picker-open'
            );
          }
        );

      ui.find(
        '.enchant-menu-set-notation'
      )
        .off(
          'click.fishEnchantNotationMenu'
        )
        .on(
          'click.fishEnchantNotationMenu',
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            ui.find(
              '.enchant-menu-panel'
            ).addClass(
              'show-notation'
            );
          }
        );

      ui.find(
        '.enchant-menu-back'
      )
        .off(
          'click.fishEnchantMenuBack'
        )
        .on(
          'click.fishEnchantMenuBack',
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            ui.find(
              '.enchant-menu-panel'
            ).removeClass(
              'show-notation'
            );
          }
        );

      ui.find(
        '.enchant-notation-choice'
      )
        .off(
          'click.fishEnchantNotationChoice'
        )
        .on(
          'click.fishEnchantNotationChoice',
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            setNotation(
              $(this).attr(
                'data-notation'
              )
            );
          }
        );

      ui
        .off(
          'click.fishEnchantDynamicRod',
          '.rod-card'
        )
        .on(
          'click.fishEnchantDynamicRod',
          '.rod-card',
          function () {
            var tool =
              $(this).data(
                'toolEntry'
              );

            if (tool) {
              selectTool(
                ui,
                tool
              );
            }
          }
        );

      ui
        .off(
          'keydown.fishEnchantDynamicRod',
          '.rod-card'
        )
        .on(
          'keydown.fishEnchantDynamicRod',
          '.rod-card',
          function (event) {
            if (
              event.key !== 'Enter' &&
              event.key !== ' '
            ) {
              return;
            }

            event.preventDefault();

            var tool =
              $(this).data(
                'toolEntry'
              );

            if (tool) {
              selectTool(
                ui,
                tool
              );
            }
          }
        );

      buildRodPicker(ui);

      box
        .off(
          'click.fishEnchantPoints'
        )
        .on(
          'click.fishEnchantPoints',
          function () {
            if (
              box.find(
                'input'
              ).length
            ) {
              return;
            }

            var currentText =
              display
                .text()
                .trim();

            if (
              currentText ===
                'Fish Points' ||
              currentText.indexOf(
                'Input a real number'
              ) !== -1
            ) {
              currentText = '';
            } else {
              currentText =
                currentText
                  .replace(
                    / fish points?/i,
                    ''
                  )
                  .trim();
            }

            var input = $('<input>')
              .addClass(
                'enchant-points-input'
              )
              .attr(
                'type',
                'text'
              )
              .attr(
                'placeholder',
                'Example: 1, 2k, 3m, 1e6'
              )
              .val(
                currentText
              );

            display.hide();

            box.removeClass(
              'fish-points-error'
            );

            box.append(
              input
            );

            input.focus();

            var didSave = false;

            function saveValue() {
              if (didSave) {
                return;
              }

              didSave = true;

              var raw =
                input
                  .val()
                  .trim();

              var parsed =
                parseFishNumber(
                  raw
                );

              if (
                parsed === null
              ) {
                box.removeAttr(
                  'data-fish-points'
                );

                box.addClass(
                  'fish-points-error'
                );

                display.text(
                  'Input a real number in this format: 1, 2k, 3m, 1e6'
                );

                input.remove();

                display.show();

                updateEnchantDisplay(
                  ui
                );

                return;
              }

              box.attr(
                'data-fish-points',
                parsed
              );

              box.removeClass(
                'fish-points-error'
              );

              input.remove();

              display.show();

              updateSingleFormattedText(
                ui,
                display,
                parsed,
                ' Fish Points'
              );

              updateEnchantDisplay(
                ui
              );
            }

            input.on(
              'keydown',
              function (event) {
                if (
                  event.key ===
                  'Enter'
                ) {
                  event.preventDefault();

                  saveValue();
                }

                if (
                  event.key ===
                  'Escape'
                ) {
                  didSave = true;

                  input.remove();

                  display.show();
                }
              }
            );

            input.on(
              'blur',
              saveValue
            );
          }
        );

      updateEnchantDisplay(
        ui
      );
    }
  );

  document.addEventListener(
    'fishEntriesDataReady',
    function (event) {
      applyEntriesData(
        event.detail
      );
    }
  );

  if (window.FishEntriesData) {
    applyEntriesData(
      window.FishEntriesData
    );
  }
});

window.FishNumber = (function () {
  var suffixes = [
    '',
    'k', 'm', 'b', 't', 'qd', 'qn', 'sx', 'sp', 'oc', 'no',
    'de', 'ude', 'dde', 'tde', 'qdde', 'qnde', 'sxde', 'spde', 'ocde', 'node',
    'vt', 'uvt', 'dvt', 'tvt', 'qdvt', 'qnvt', 'sxvt', 'spvt', 'ocvt', 'novt',
    'tg', 'utg', 'dtg', 'ttg', 'qdtg', 'qntg', 'sxtg', 'sptg', 'octg', 'notg',
    'qg', 'uqg', 'dqg', 'tqg', 'qdqg', 'qnqg', 'sxqg', 'spqg', 'ocqg', 'noqg',
    'qag', 'uqag', 'dqag', 'tqag', 'qdqag', 'qnqag', 'sxqag', 'spqag', 'ocqag', 'noqag',
    'sg', 'usg', 'dsg', 'tsg', 'qdsg', 'qnsg', 'sxsg', 'spsg', 'ocsg', 'nosg',
    'spg', 'uspg', 'dspg', 'tspg', 'qdspg', 'qnspg', 'sxspg', 'spspg', 'ocspg', 'nospg',
    'og', 'uog', 'dog', 'tog', 'qdog', 'qnog', 'sxog', 'spog', 'ocog', 'noog',
    'ng', 'ung', 'dng', 'tng', 'qdng', 'qnng', 'sxng', 'spng', 'ocng', 'nong',
    'ce'
  ];

  var multipliers = {};

  suffixes.forEach(function (suffix, index) {
    multipliers[suffix.toLowerCase()] = Math.pow(1000, index);
  });

  function parse(text) {
    var input = String(text || '')
      .trim()
      .toLowerCase()
      .replace(/,/g, '');

    if (input === '') {
      return null;
    }

    var suffixMatch = input.match(/^([0-9]*\.?[0-9]+)([a-z]+)$/i);

    if (suffixMatch) {
      var baseNumber = Number(suffixMatch[1]);
      var suffix = suffixMatch[2].toLowerCase();

      if (!Object.prototype.hasOwnProperty.call(multipliers, suffix)) {
        return null;
      }

      var suffixNumber = baseNumber * multipliers[suffix];

      if (!isFinite(suffixNumber) || suffixNumber < 1) {
        return null;
      }

      return suffixNumber;
    }

    var scientificMatch = input.match(
      /^([0-9]*\.?[0-9]+(?:e[+-]?[0-9]+)?)$/i
    );

    if (!scientificMatch) {
      return null;
    }

    var number = Number(scientificMatch[1]);

    if (!isFinite(number) || number < 1) {
      return null;
    }

    return number;
  }

  function formatSuffix(number) {
    number = Number(number);

    if (!isFinite(number)) {
      return 'Too big';
    }

    var absolute = Math.abs(number);

    if (absolute < 1000) {
      return Math.floor(number).toLocaleString();
    }

    for (var i = suffixes.length - 1; i >= 1; i--) {
      var suffix = suffixes[i];
      var value = multipliers[suffix];

      if (absolute >= value) {
        var shortNumber = number / value;
        var text;

        if (Math.abs(shortNumber) >= 100) {
          text = shortNumber.toFixed(0);
        } else if (Math.abs(shortNumber) >= 10) {
          text = shortNumber.toFixed(1);
        } else {
          text = shortNumber.toFixed(2);
        }

        text = text
          .replace(/\.0+$/, '')
          .replace(/(\.\d*[1-9])0+$/, '$1');

        return text + suffix;
      }
    }

    return String(number);
  }

  function formatScientific(number) {
    number = Number(number);

    if (!isFinite(number)) {
      return 'Too big';
    }

    return number
      .toExponential(2)
      .replace('+', '')
      .replace(/\.00e/, 'e');
  }

  function format(number, notation) {
    if (notation === 'scientific') {
      return formatScientific(number);
    }

    return formatSuffix(number);
  }

  return {
    parse: parse,
    format: format,
    formatSuffix: formatSuffix,
    formatScientific: formatScientific
  };
})();




window.FishEN = (function () {
  var cache = Object.create(null);
  var requestCounter = 0;

  function normaliseNotation(notation) {
    return notation === 'scientific' ? 'scientific' : 'suffix';
  }

  function normaliseDigits(digits) {
    digits = Math.floor(Number(digits));

    if (!isFinite(digits) || digits < 0) {
      return 2;
    }

    return digits;
  }

  function getFunctionName(notation) {
    return notation === 'scientific'
      ? 'toScientific'
      : 'toSuffix';
  }

  function valueToModuleText(value) {
    var number = Number(value);

    if (!isFinite(number)) {
      return null;
    }

    return String(number);
  }

  function fallback(value, notation) {
    return window.FishNumber.format(value, notation);
  }

  function formatMany(values, notation, digits) {
    notation = normaliseNotation(notation);
    digits = normaliseDigits(digits);

    var results = new Array(values.length);
    var missingValues = [];
    var missingKeys = [];
    var missingKeyPositions = Object.create(null);

    values.forEach(function (value, index) {
      var valueText = valueToModuleText(value);

      if (valueText === null) {
        results[index] = fallback(value, notation);
        return;
      }

      var key = [
        notation,
        digits,
        valueText
      ].join('|');

      if (
        Object.prototype.hasOwnProperty.call(
          cache,
          key
        )
      ) {
        results[index] = cache[key];
        return;
      }

      if (
        !Object.prototype.hasOwnProperty.call(
          missingKeyPositions,
          key
        )
      ) {
        missingKeyPositions[key] = [];
        missingKeys.push(key);
        missingValues.push(valueText);
      }

      missingKeyPositions[key].push(index);
    });

    if (missingValues.length === 0) {
      return Promise.resolve(results);
    }

    requestCounter += 1;

    var separator =
      '@@FISH_EN_SPLIT_' +
      requestCounter +
      '_' +
      Date.now() +
      '@@';

    var functionName =
      getFunctionName(notation);

    var invokeText = missingValues
      .map(function (valueText) {
        return (
          '{{#invoke:EN|' +
          functionName +
          '|' +
          valueText +
          '|' +
          digits +
          '}}'
        );
      })
      .join(separator);

    return mw.loader
      .using('mediawiki.api')
      .then(function () {
        var api = new mw.Api();

        return api.post({
          action: 'expandtemplates',
          text: invokeText,
          prop: 'wikitext',
          title: mw.config.get('wgPageName'),
          formatversion: 2
        });
      })
      .then(function (data) {
        var expanded =
          data &&
          data.expandtemplates &&
          data.expandtemplates.wikitext !== undefined
            ? String(
                data.expandtemplates.wikitext
              )
            : '';

        var parts =
          expanded.split(separator);

        missingValues.forEach(
          function (valueText, missingIndex) {
            var key =
              missingKeys[missingIndex];

            var result = String(
              parts[missingIndex] || ''
            ).trim();

            if (!result) {
              result = fallback(
                Number(valueText),
                notation
              );
            }

            cache[key] = result;

            missingKeyPositions[key].forEach(
              function (position) {
                results[position] = result;
              }
            );
          }
        );

        return results;
      })
      .catch(function (error) {
        console.error(
          'Module:EN formatting failed:',
          error
        );

        values.forEach(
          function (value, index) {
            if (
              results[index] === undefined
            ) {
              results[index] = fallback(
                value,
                notation
              );
            }
          }
        );

        return results;
      });
  }

  function format(
    value,
    notation,
    digits
  ) {
    return formatMany(
      [value],
      notation,
      digits
    ).then(function (results) {
      return results[0];
    });
  }

  function clearCache() {
    cache = Object.create(null);
  }

  return {
    format: format,
    formatMany: formatMany,
    clearCache: clearCache
  };
})();



$(function () {
  var entriesData =
    window.FishEntriesData || {
      tools: [],
      enchants: []
    };

  localStorage.removeItem(
    'fishIslandFishPoints'
  );

  $(document)
    .off('click.fishEnchantMenuButton')
    .on(
      'click.fishEnchantMenuButton',
      '.enchant-menu-button',
      function (event) {
        event.preventDefault();
        event.stopPropagation();

        var ui = $(this).closest(
          '.enchant-ui'
        );

        if (!ui.length) {
          ui = $('.enchant-ui').first();
        }

        ui.removeClass(
          'rod-picker-open'
        );

        ui.toggleClass(
          'enchant-menu-open'
        );
      }
    );

  $(document)
    .off('click.fishEnchantMenuClose')
    .on(
      'click.fishEnchantMenuClose',
      '.enchant-menu-close',
      function (event) {
        event.preventDefault();
        event.stopPropagation();

        var ui = $(this).closest(
          '.enchant-ui'
        );

        if (!ui.length) {
          ui = $('.enchant-ui').first();
        }

        ui.removeClass(
          'enchant-menu-open'
        );
      }
    );

  function parseFishNumber(text) {
    return window.FishNumber.parse(text);
  }

  function clampUpgradeLevel(value) {
    value = Math.floor(
      Number(value)
    );

    if (!isFinite(value)) {
      value = 0;
    }

    return Math.max(
      0,
      Math.min(25, value)
    );
  }

  function getUpgradeLevel(ui) {
    var upgradeBox = ui.find(
      '.enchant-upgrade-box'
    );

    if (!upgradeBox.length) {
      return 0;
    }

    return clampUpgradeLevel(
      upgradeBox.attr(
        'data-upgrade-level'
      )
    );
  }

  function calculateEnchantBaseLevel(
    fishPoints,
    levelMult,
    upgradeLevel
  ) {
    fishPoints = Number(fishPoints);
    levelMult = Number(levelMult);

    upgradeLevel =
      clampUpgradeLevel(upgradeLevel);

    if (
      !isFinite(fishPoints) ||
      fishPoints < 1 ||
      !isFinite(levelMult) ||
      levelMult <= 0
    ) {
      return null;
    }

    return (
      Math.pow(
        fishPoints *
          Math.pow(
            1.2,
            upgradeLevel
          ),
        0.2
      ) *
      levelMult
    );
  }

  function applyLevelCap(
    level,
    levelCap
  ) {
    if (
      levelCap === undefined ||
      levelCap === null
    ) {
      return level;
    }

    levelCap = Number(levelCap);

    if (!isFinite(levelCap)) {
      return level;
    }

    return Math.min(
      level,
      levelCap
    );
  }

  function calculateEnchantLevelRange(
    fishPoints,
    levelMult,
    upgradeLevel,
    levelCap
  ) {
    var baseLevel =
      calculateEnchantBaseLevel(
        fishPoints,
        levelMult,
        upgradeLevel
      );

    if (baseLevel === null) {
      return {
        min: 1,
        max: 1
      };
    }

    var minLevel = Math.max(
      1,
      Math.ceil(
        baseLevel * 0.9
      )
    );

    var maxLevel = Math.max(
      1,
      Math.ceil(
        baseLevel * 1.1
      )
    );

    minLevel = applyLevelCap(
      minLevel,
      levelCap
    );

    maxLevel = applyLevelCap(
      maxLevel,
      levelCap
    );

    return {
      min: minLevel,
      max: maxLevel
    };
  }

  function getNotation(ui) {
    var activeNotation = ui
      .find(
        '.enchant-notation-choice.notation-active'
      )
      .attr(
        'data-notation'
      );

    if (
      activeNotation === 'suffix' ||
      activeNotation === 'scientific'
    ) {
      return activeNotation;
    }

    var savedNotation =
      localStorage.getItem(
        'fishIslandNotation'
      );

    if (
      savedNotation === 'suffix' ||
      savedNotation === 'scientific'
    ) {
      return savedNotation;
    }

    return 'suffix';
  }

  function formatFishNumber(
    number,
    ui
  ) {
    return window.FishNumber.format(
      number,
      getNotation(ui)
    );
  }

  function formatWithModule(
    values,
    ui
  ) {
    return window.FishEN.formatMany(
      values,
      getNotation(ui),
      2
    );
  }

  function updateSingleFormattedText(
    ui,
    element,
    value,
    suffixText
  ) {
    var notation =
      getNotation(ui);

    var requestId =
      Number(
        element.data(
          'fishEnRequest'
        ) || 0
      ) + 1;

    element.data(
      'fishEnRequest',
      requestId
    );

    element.text(
      window.FishNumber.format(
        value,
        notation
      ) +
        (suffixText || '')
    );

    window.FishEN
      .format(
        value,
        notation,
        2
      )
      .then(function (formatted) {
        if (
          Number(
            element.data(
              'fishEnRequest'
            )
          ) !== requestId
        ) {
          return;
        }

        element.text(
          formatted +
            (suffixText || '')
        );
      });
  }

  function normaliseRodType(value) {
    return String(value || '')
      .trim()
      .toLowerCase();
  }

  function normaliseEnchantName(value) {
    return String(value || '')
      .trim()
      .toLowerCase();
  }

  function getEnchantLevelMult(name) {
    var multipliers = {
      strength: 1,
      'strength+': 0.8,
      momentum: 0.65,
      'momentum+': 0.5,
      fortune: 0.5,
      ultra: 0.5,
      'less backfire': 0.75,
      sharpshooter: 0.75
    };

    var key =
      normaliseEnchantName(name);

    return Object.prototype.hasOwnProperty.call(
      multipliers,
      key
    )
      ? multipliers[key]
      : 1;
  }

  function getEnchantColorClass(name) {
    return (
      'enchant-bg-' +
      normaliseEnchantName(name)
        .replace(/\+/g, '-plus')
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '')
    );
  }

  function getEnchantListForUi(ui) {
    var selectedTool =
      ui.data('selectedTool');

    if (!selectedTool) {
      return [];
    }

    var selectedRodType =
      normaliseRodType(
        selectedTool.rodType
      );

    return (entriesData.enchants || [])
      .filter(function (enchant) {
        return (
          normaliseRodType(
            enchant.rodType
          ) === selectedRodType
        );
      })
      .map(function (enchant) {
        return {
          name: enchant.name,
          file: enchant.image,
          levelMult:
            getEnchantLevelMult(
              enchant.name
            ),
          colorClass:
            getEnchantColorClass(
              enchant.name
            )
        };
      });
  }

  function hasSelectedItem(ui) {
    return Boolean(
      ui.data('selectedTool')
    );
  }

  function updateEnchantDisplay(ui) {
    var fishPoints = Number(
      ui
        .find('.enchant-cost-box')
        .attr(
          'data-fish-points'
        )
    );

    var infoText = ui.find(
      '.enchant-info-text'
    );

    var grid = ui.find(
      '.enchant-result-grid'
    );

    var hasRod =
      hasSelectedItem(ui);

    if (
      !hasRod &&
      (
        !fishPoints ||
        fishPoints < 1
      )
    ) {
      grid.hide().empty();

      infoText
        .show()
        .text(
          'Select a rod and input Fish Points'
        );

      return;
    }

    if (!hasRod) {
      grid.hide().empty();

      infoText
        .show()
        .text(
          'Select a rod first'
        );

      return;
    }

    if (
      !fishPoints ||
      fishPoints < 1
    ) {
      grid.hide().empty();

      infoText
        .show()
        .text(
          'Input Fish Points'
        );

      return;
    }

    var enchants =
      getEnchantListForUi(ui);

    if (!enchants.length) {
      grid.hide().empty();

      infoText
        .show()
        .text(
          'No enchants match this tool type'
        );

      return;
    }

    var upgradeLevel =
      getUpgradeLevel(ui);

    var valuesToFormat = [];
    var levelElements = [];

    var renderId =
      Number(
        ui.data(
          'enchantDisplayRenderId'
        ) || 0
      ) + 1;

    ui.data(
      'enchantDisplayRenderId',
      renderId
    );

    grid.empty();

    enchants.forEach(
      function (enchant) {
        var levelRange =
          calculateEnchantLevelRange(
            fishPoints,
            enchant.levelMult,
            upgradeLevel,
            enchant.levelCap
          );

        var imgUrl =
          mw.util.getUrl(
            'Special:Redirect/file/' +
              enchant.file
          );

        var card = $('<div>')
          .addClass(
            'enchant-result-card'
          )
          .addClass(
            enchant.colorClass
          );

        $('<img>')
          .attr(
            'src',
            imgUrl
          )
          .attr(
            'alt',
            enchant.name
          )
          .appendTo(card);

        $('<div>')
          .addClass(
            'enchant-result-name'
          )
          .text(
            enchant.name
          )
          .appendTo(card);

        var levelElement =
          $('<div>')
            .addClass(
              'enchant-result-level'
            )
            .text(
              'Level ' +
                formatFishNumber(
                  levelRange.min,
                  ui
                ) +
                ' - ' +
                formatFishNumber(
                  levelRange.max,
                  ui
                )
            )
            .appendTo(card);

        valuesToFormat.push(
          levelRange.min
        );

        valuesToFormat.push(
          levelRange.max
        );

        levelElements.push(
          levelElement
        );

        grid.append(card);
      }
    );

    infoText.hide();

    grid.css(
      'display',
      'grid'
    );

    formatWithModule(
      valuesToFormat,
      ui
    ).then(
      function (formattedValues) {
        if (
          Number(
            ui.data(
              'enchantDisplayRenderId'
            )
          ) !== renderId
        ) {
          return;
        }

        levelElements.forEach(
          function (element, index) {
            element.text(
              'Level ' +
                formattedValues[
                  index * 2
                ] +
                ' - ' +
                formattedValues[
                  index * 2 + 1
                ]
            );
          }
        );
      }
    );
  }

  function getFileUrl(fileName) {
    if (!fileName) {
      return '';
    }

    return mw.util.getUrl(
      'Special:Redirect/file/' +
        fileName
    );
  }

  function selectTool(ui, tool) {
    ui.data(
      'selectedTool',
      tool
    );

    ui.removeClass(
      'rod-picker-open'
    );

    var itemSlot = ui.find(
      '.enchant-item-slot'
    );

    itemSlot.empty();

    var selectedImage = $('<div>')
      .addClass(
        'enchant-selected-img enchant-selected-active'
      )
      .appendTo(itemSlot);

    if (tool.image) {
      $('<img>')
        .attr(
          'src',
          getFileUrl(tool.image)
        )
        .attr(
          'alt',
          tool.name
        )
        .appendTo(selectedImage);
    }

    ui.find(
      '.enchant-heading-wrap'
    )
      .empty()
      .append(
        $('<div>')
          .addClass(
            'enchant-heading'
          )
          .text(
            tool.name
          )
      );

    updateEnchantDisplay(ui);
  }

  function buildRodPicker(ui) {
    var grid = ui.find(
      '.rod-grid'
    );

    if (!grid.length) {
      return;
    }

    grid.empty();

    var tools =
      entriesData.tools || [];

    if (!tools.length) {
      $('<div>')
        .addClass(
          'rod-picker-message'
        )
        .text(
          'Loading tools...'
        )
        .appendTo(grid);

      return;
    }

    tools.forEach(function (tool) {
      var card = $('<div>')
        .addClass('rod-card')
        .attr('role', 'button')
        .attr('tabindex', '0')
        .data('toolEntry', tool);

      if (tool.image) {
        $('<img>')
          .attr(
            'src',
            getFileUrl(tool.image)
          )
          .attr(
            'alt',
            tool.name
          )
          .appendTo(card);
      }

      $('<div>')
        .text(tool.name)
        .appendTo(card);

      card.appendTo(grid);
    });
  }

  function applyEntriesData(data) {
    if (!data) {
      return;
    }

    entriesData = {
      tools: Array.isArray(data.tools)
        ? data.tools
        : [],
      enchants: Array.isArray(data.enchants)
        ? data.enchants
        : []
    };

    $('.enchant-ui').each(function () {
      var ui = $(this);
      buildRodPicker(ui);

      if (hasSelectedItem(ui)) {
        updateEnchantDisplay(ui);
      }
    });
  }

  $('.enchant-ui').each(
    function () {
      var ui = $(this);

      var box = ui.find(
        '.enchant-cost-box'
      );

      var display = ui.find(
        '.enchant-fish-points-display'
      );



      ui.find(
        '.enchant-menu-fish-advisor, ' +
        '.enchant-advisor-panel, ' +
        '.enchant-fish-advisor, ' +
        '[class*="enchant-advisor-"]'
      ).remove();

      ui.find(
        '.enchant-menu-panel'
      ).removeClass(
        'show-fish'
      );



      var upgradeBox = ui.find(
        '.enchant-upgrade-box'
      );

      if (!upgradeBox.length) {
        var enchantLeft = ui
          .find(
            '.enchant-left'
          )
          .first();

        var itemSlot = enchantLeft
          .find(
            '.enchant-item-slot'
          )
          .first();

        upgradeBox = $('<div>')
          .addClass(
            'enchant-upgrade-box'
          )
          .attr(
            'data-upgrade-level',
            '0'
          )
          .css({
            width: '100%',
            minHeight: '86px',
            marginTop: '16px',
            padding: '10px',
            boxSizing: 'border-box',

            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            gap: '6px',

            background:
              'rgba(10, 7, 20, 0.45)',

            border:
              '1px solid #3b245f',

            color: '#bda2ff',
            fontWeight: 'bold',
            textAlign: 'center',
            cursor: 'text'
          });

        $('<div>')
          .addClass(
            'enchant-upgrade-label'
          )
          .text(
            '3FH Upgrade'
          )
          .css({
            fontSize: '15px',
            lineHeight: '1.1'
          })
          .appendTo(
            upgradeBox
          );

        $('<div>')
          .addClass(
            'enchant-upgrade-display'
          )
          .text(
            'Level 0 / 25'
          )
          .css({
            fontSize: '21px',
            lineHeight: '1.1'
          })
          .appendTo(
            upgradeBox
          );

        if (itemSlot.length) {
          itemSlot.after(
            upgradeBox
          );
        } else if (
          enchantLeft.length
        ) {
          enchantLeft.append(
            upgradeBox
          );
        }
      }

      var upgradeDisplay =
        upgradeBox.find(
          '.enchant-upgrade-display'
        );

      if (
        !upgradeDisplay.length
      ) {
        upgradeDisplay =
          $('<div>')
            .addClass(
              'enchant-upgrade-display'
            )
            .appendTo(
              upgradeBox
            );
      }

      var storedUpgradeLevel =
        localStorage.getItem(
          'fishIsland3FHLevel'
        );

      var existingUpgradeLevel =
        upgradeBox.attr(
          'data-upgrade-level'
        );

      var savedUpgradeLevel;

      if (
        storedUpgradeLevel !== null &&
        storedUpgradeLevel !== ''
      ) {
        savedUpgradeLevel =
          clampUpgradeLevel(
            storedUpgradeLevel
          );
      } else {
        savedUpgradeLevel =
          clampUpgradeLevel(
            existingUpgradeLevel
          );
      }

      upgradeBox.attr(
        'data-upgrade-level',
        savedUpgradeLevel
      );

      upgradeDisplay.text(
        'Level ' +
          savedUpgradeLevel +
          ' / 25'
      );

      upgradeBox
        .off(
          'click.fish3FHUpgrade'
        )
        .on(
          'click.fish3FHUpgrade',
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            if (
              upgradeBox.find(
                'input'
              ).length
            ) {
              return;
            }

            var currentLevel =
              getUpgradeLevel(ui);

            var input = $('<input>')
              .addClass(
                'enchant-upgrade-input'
              )
              .attr(
                'type',
                'number'
              )
              .attr(
                'min',
                '0'
              )
              .attr(
                'max',
                '25'
              )
              .attr(
                'step',
                '1'
              )
              .attr(
                'placeholder',
                '0 - 25'
              )
              .val(
                currentLevel
              )
              .css({
                width: '85%',
                height: '34px',
                padding: '4px 8px',
                boxSizing:
                  'border-box',

                background:
                  '#130b25',

                border:
                  '1px solid #9b6cff',

                color: '#ffffff',
                fontSize: '18px',
                fontWeight: 'bold',
                textAlign: 'center',
                outline: 'none'
              });

            upgradeDisplay.hide();

            upgradeBox.append(
              input
            );

            input.focus();
            input.select();

            var didSave = false;

            function saveUpgradeLevel() {
              if (didSave) {
                return;
              }

              didSave = true;

              var upgradeLevel =
                clampUpgradeLevel(
                  input.val()
                );

              upgradeBox.attr(
                'data-upgrade-level',
                upgradeLevel
              );

              localStorage.setItem(
                'fishIsland3FHLevel',
                upgradeLevel
              );

              upgradeDisplay.text(
                'Level ' +
                  upgradeLevel +
                  ' / 25'
              );

              input.remove();

              upgradeDisplay.show();

              updateEnchantDisplay(
                ui
              );
            }

            input.on(
              'keydown',
              function (keyEvent) {
                if (
                  keyEvent.key ===
                  'Enter'
                ) {
                  keyEvent.preventDefault();

                  saveUpgradeLevel();
                }

                if (
                  keyEvent.key ===
                  'Escape'
                ) {
                  didSave = true;

                  input.remove();

                  upgradeDisplay.show();
                }
              }
            );

            input.on(
              'blur',
              saveUpgradeLevel
            );
          }
        );

      var suffixChoice =
        ui.find(
          '.enchant-notation-choice[data-notation="suffix"]'
        );

      var scientificChoice =
        ui.find(
          '.enchant-notation-choice[data-notation="scientific"]'
        );

      if (
        suffixChoice.length &&
        scientificChoice.length
      ) {
        suffixChoice.insertBefore(
          scientificChoice
        );
      }

      function setNotation(
        notation
      ) {
        if (
          notation !== 'suffix' &&
          notation !== 'scientific'
        ) {
          notation = 'suffix';
        }

        localStorage.setItem(
          'fishIslandNotation',
          notation
        );

        ui.attr(
          'data-notation',
          notation
        );

        ui.find(
          '.enchant-notation-choice'
        ).removeClass(
          'notation-active'
        );

        ui.find(
          '.enchant-notation-choice[data-notation="' +
            notation +
            '"]'
        ).addClass(
          'notation-active'
        );

        var fishPoints =
          box.attr(
            'data-fish-points'
          );

        if (
          fishPoints &&
          !isNaN(
            Number(fishPoints)
          ) &&
          Number(fishPoints) >= 1
        ) {
          updateSingleFormattedText(
            ui,
            display,
            Number(fishPoints),
            ' Fish Points'
          );
        }

        updateEnchantDisplay(
          ui
        );
      }

      var savedNotation =
        localStorage.getItem(
          'fishIslandNotation'
        ) || 'suffix';

      setNotation(
        savedNotation
      );

      ui
        .off(
          'click.fishEnchantPicker',
          '.enchant-open-picker'
        )
        .on(
          'click.fishEnchantPicker',
          '.enchant-open-picker',
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            ui.removeClass(
              'enchant-menu-open'
            );

            ui.addClass(
              'rod-picker-open'
            );
          }
        );

      ui.find(
        '.enchant-menu-set-notation'
      )
        .off(
          'click.fishEnchantNotationMenu'
        )
        .on(
          'click.fishEnchantNotationMenu',
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            ui.find(
              '.enchant-menu-panel'
            ).addClass(
              'show-notation'
            );
          }
        );

      ui.find(
        '.enchant-menu-back'
      )
        .off(
          'click.fishEnchantMenuBack'
        )
        .on(
          'click.fishEnchantMenuBack',
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            ui.find(
              '.enchant-menu-panel'
            ).removeClass(
              'show-notation'
            );
          }
        );

      ui.find(
        '.enchant-notation-choice'
      )
        .off(
          'click.fishEnchantNotationChoice'
        )
        .on(
          'click.fishEnchantNotationChoice',
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            setNotation(
              $(this).attr(
                'data-notation'
              )
            );
          }
        );

      ui
        .off(
          'click.fishEnchantDynamicRod',
          '.rod-card'
        )
        .on(
          'click.fishEnchantDynamicRod',
          '.rod-card',
          function () {
            var tool =
              $(this).data(
                'toolEntry'
              );

            if (tool) {
              selectTool(
                ui,
                tool
              );
            }
          }
        );

      ui
        .off(
          'keydown.fishEnchantDynamicRod',
          '.rod-card'
        )
        .on(
          'keydown.fishEnchantDynamicRod',
          '.rod-card',
          function (event) {
            if (
              event.key !== 'Enter' &&
              event.key !== ' '
            ) {
              return;
            }

            event.preventDefault();

            var tool =
              $(this).data(
                'toolEntry'
              );

            if (tool) {
              selectTool(
                ui,
                tool
              );
            }
          }
        );

      buildRodPicker(ui);

      box
        .off(
          'click.fishEnchantPoints'
        )
        .on(
          'click.fishEnchantPoints',
          function () {
            if (
              box.find(
                'input'
              ).length
            ) {
              return;
            }

            var currentText =
              display
                .text()
                .trim();

            if (
              currentText ===
                'Fish Points' ||
              currentText.indexOf(
                'Input a real number'
              ) !== -1
            ) {
              currentText = '';
            } else {
              currentText =
                currentText
                  .replace(
                    / fish points?/i,
                    ''
                  )
                  .trim();
            }

            var input = $('<input>')
              .addClass(
                'enchant-points-input'
              )
              .attr(
                'type',
                'text'
              )
              .attr(
                'placeholder',
                'Example: 1, 2k, 3m, 1e6'
              )
              .val(
                currentText
              );

            display.hide();

            box.removeClass(
              'fish-points-error'
            );

            box.append(
              input
            );

            input.focus();

            var didSave = false;

            function saveValue() {
              if (didSave) {
                return;
              }

              didSave = true;

              var raw =
                input
                  .val()
                  .trim();

              var parsed =
                parseFishNumber(
                  raw
                );

              if (
                parsed === null
              ) {
                box.removeAttr(
                  'data-fish-points'
                );

                box.addClass(
                  'fish-points-error'
                );

                display.text(
                  'Input a real number in this format: 1, 2k, 3m, 1e6'
                );

                input.remove();

                display.show();

                updateEnchantDisplay(
                  ui
                );

                return;
              }

              box.attr(
                'data-fish-points',
                parsed
              );

              box.removeClass(
                'fish-points-error'
              );

              input.remove();

              display.show();

              updateSingleFormattedText(
                ui,
                display,
                parsed,
                ' Fish Points'
              );

              updateEnchantDisplay(
                ui
              );
            }

            input.on(
              'keydown',
              function (event) {
                if (
                  event.key ===
                  'Enter'
                ) {
                  event.preventDefault();

                  saveValue();
                }

                if (
                  event.key ===
                  'Escape'
                ) {
                  didSave = true;

                  input.remove();

                  display.show();
                }
              }
            );

            input.on(
              'blur',
              saveValue
            );
          }
        );

      updateEnchantDisplay(
        ui
      );
    }
  );

  document.addEventListener(
    'fishEntriesDataReady',
    function (event) {
      applyEntriesData(
        event.detail
      );
    }
  );

  if (window.FishEntriesData) {
    applyEntriesData(
      window.FishEntriesData
    );
  }
});

window.FishNumber = (function () {
  var suffixes = [
    '',
    'k', 'm', 'b', 't', 'qd', 'qn', 'sx', 'sp', 'oc', 'no',
    'de', 'ude', 'dde', 'tde', 'qdde', 'qnde', 'sxde', 'spde', 'ocde', 'node',
    'vt', 'uvt', 'dvt', 'tvt', 'qdvt', 'qnvt', 'sxvt', 'spvt', 'ocvt', 'novt',
    'tg', 'utg', 'dtg', 'ttg', 'qdtg', 'qntg', 'sxtg', 'sptg', 'octg', 'notg',
    'qg', 'uqg', 'dqg', 'tqg', 'qdqg', 'qnqg', 'sxqg', 'spqg', 'ocqg', 'noqg',
    'qag', 'uqag', 'dqag', 'tqag', 'qdqag', 'qnqag', 'sxqag', 'spqag', 'ocqag', 'noqag',
    'sg', 'usg', 'dsg', 'tsg', 'qdsg', 'qnsg', 'sxsg', 'spsg', 'ocsg', 'nosg',
    'spg', 'uspg', 'dspg', 'tspg', 'qdspg', 'qnspg', 'sxspg', 'spspg', 'ocspg', 'nospg',
    'og', 'uog', 'dog', 'tog', 'qdog', 'qnog', 'sxog', 'spog', 'ocog', 'noog',
    'ng', 'ung', 'dng', 'tng', 'qdng', 'qnng', 'sxng', 'spng', 'ocng', 'nong',
    'ce'
  ];

  var multipliers = {};

  suffixes.forEach(function (suffix, index) {
    multipliers[suffix.toLowerCase()] = Math.pow(1000, index);
  });

  function parse(text) {
    var input = String(text || '')
      .trim()
      .toLowerCase()
      .replace(/,/g, '');

    if (input === '') {
      return null;
    }

    var suffixMatch = input.match(/^([0-9]*\.?[0-9]+)([a-z]+)$/i);

    if (suffixMatch) {
      var baseNumber = Number(suffixMatch[1]);
      var suffix = suffixMatch[2].toLowerCase();

      if (!Object.prototype.hasOwnProperty.call(multipliers, suffix)) {
        return null;
      }

      var suffixNumber = baseNumber * multipliers[suffix];

      if (!isFinite(suffixNumber) || suffixNumber < 1) {
        return null;
      }

      return suffixNumber;
    }

    var scientificMatch = input.match(
      /^([0-9]*\.?[0-9]+(?:e[+-]?[0-9]+)?)$/i
    );

    if (!scientificMatch) {
      return null;
    }

    var number = Number(scientificMatch[1]);

    if (!isFinite(number) || number < 1) {
      return null;
    }

    return number;
  }

  function formatSuffix(number) {
    number = Number(number);

    if (!isFinite(number)) {
      return 'Too big';
    }

    var absolute = Math.abs(number);

    if (absolute < 1000) {
      return Math.floor(number).toLocaleString();
    }

    for (var i = suffixes.length - 1; i >= 1; i--) {
      var suffix = suffixes[i];
      var value = multipliers[suffix];

      if (absolute >= value) {
        var shortNumber = number / value;
        var text;

        if (Math.abs(shortNumber) >= 100) {
          text = shortNumber.toFixed(0);
        } else if (Math.abs(shortNumber) >= 10) {
          text = shortNumber.toFixed(1);
        } else {
          text = shortNumber.toFixed(2);
        }

        text = text
          .replace(/\.0+$/, '')
          .replace(/(\.\d*[1-9])0+$/, '$1');

        return text + suffix;
      }
    }

    return String(number);
  }

  function formatScientific(number) {
    number = Number(number);

    if (!isFinite(number)) {
      return 'Too big';
    }

    return number
      .toExponential(2)
      .replace('+', '')
      .replace(/\.00e/, 'e');
  }

  function format(number, notation) {
    if (notation === 'scientific') {
      return formatScientific(number);
    }

    return formatSuffix(number);
  }

  return {
    parse: parse,
    format: format,
    formatSuffix: formatSuffix,
    formatScientific: formatScientific
  };
})();




window.FishEN = (function () {
  var cache = Object.create(null);
  var requestCounter = 0;

  function normaliseNotation(notation) {
    return notation === 'scientific' ? 'scientific' : 'suffix';
  }

  function normaliseDigits(digits) {
    digits = Math.floor(Number(digits));

    if (!isFinite(digits) || digits < 0) {
      return 2;
    }

    return digits;
  }

  function getFunctionName(notation) {
    return notation === 'scientific'
      ? 'toScientific'
      : 'toSuffix';
  }

  function valueToModuleText(value) {
    var number = Number(value);

    if (!isFinite(number)) {
      return null;
    }

    return String(number);
  }

  function fallback(value, notation) {
    return window.FishNumber.format(value, notation);
  }

  function formatMany(values, notation, digits) {
    notation = normaliseNotation(notation);
    digits = normaliseDigits(digits);

    var results = new Array(values.length);
    var missingValues = [];
    var missingKeys = [];
    var missingKeyPositions = Object.create(null);

    values.forEach(function (value, index) {
      var valueText = valueToModuleText(value);

      if (valueText === null) {
        results[index] = fallback(value, notation);
        return;
      }

      var key = [
        notation,
        digits,
        valueText
      ].join('|');

      if (
        Object.prototype.hasOwnProperty.call(
          cache,
          key
        )
      ) {
        results[index] = cache[key];
        return;
      }

      if (
        !Object.prototype.hasOwnProperty.call(
          missingKeyPositions,
          key
        )
      ) {
        missingKeyPositions[key] = [];
        missingKeys.push(key);
        missingValues.push(valueText);
      }

      missingKeyPositions[key].push(index);
    });

    if (missingValues.length === 0) {
      return Promise.resolve(results);
    }

    requestCounter += 1;

    var separator =
      '@@FISH_EN_SPLIT_' +
      requestCounter +
      '_' +
      Date.now() +
      '@@';

    var functionName =
      getFunctionName(notation);

    var invokeText = missingValues
      .map(function (valueText) {
        return (
          '{{#invoke:EN|' +
          functionName +
          '|' +
          valueText +
          '|' +
          digits +
          '}}'
        );
      })
      .join(separator);

    return mw.loader
      .using('mediawiki.api')
      .then(function () {
        var api = new mw.Api();

        return api.post({
          action: 'expandtemplates',
          text: invokeText,
          prop: 'wikitext',
          title: mw.config.get('wgPageName'),
          formatversion: 2
        });
      })
      .then(function (data) {
        var expanded =
          data &&
          data.expandtemplates &&
          data.expandtemplates.wikitext !== undefined
            ? String(
                data.expandtemplates.wikitext
              )
            : '';

        var parts =
          expanded.split(separator);

        missingValues.forEach(
          function (valueText, missingIndex) {
            var key =
              missingKeys[missingIndex];

            var result = String(
              parts[missingIndex] || ''
            ).trim();

            if (!result) {
              result = fallback(
                Number(valueText),
                notation
              );
            }

            cache[key] = result;

            missingKeyPositions[key].forEach(
              function (position) {
                results[position] = result;
              }
            );
          }
        );

        return results;
      })
      .catch(function (error) {
        console.error(
          'Module:EN formatting failed:',
          error
        );

        values.forEach(
          function (value, index) {
            if (
              results[index] === undefined
            ) {
              results[index] = fallback(
                value,
                notation
              );
            }
          }
        );

        return results;
      });
  }

  function format(
    value,
    notation,
    digits
  ) {
    return formatMany(
      [value],
      notation,
      digits
    ).then(function (results) {
      return results[0];
    });
  }

  function clearCache() {
    cache = Object.create(null);
  }

  return {
    format: format,
    formatMany: formatMany,
    clearCache: clearCache
  };
})();



$(function () {
  var entriesData =
    window.FishEntriesData || {
      tools: [],
      enchants: []
    };

  localStorage.removeItem(
    'fishIslandFishPoints'
  );

  $(document)
    .off('click.fishEnchantMenuButton')
    .on(
      'click.fishEnchantMenuButton',
      '.enchant-menu-button',
      function (event) {
        event.preventDefault();
        event.stopPropagation();

        var ui = $(this).closest(
          '.enchant-ui'
        );

        if (!ui.length) {
          ui = $('.enchant-ui').first();
        }

        ui.removeClass(
          'rod-picker-open'
        );

        ui.toggleClass(
          'enchant-menu-open'
        );
      }
    );

  $(document)
    .off('click.fishEnchantMenuClose')
    .on(
      'click.fishEnchantMenuClose',
      '.enchant-menu-close',
      function (event) {
        event.preventDefault();
        event.stopPropagation();

        var ui = $(this).closest(
          '.enchant-ui'
        );

        if (!ui.length) {
          ui = $('.enchant-ui').first();
        }

        ui.removeClass(
          'enchant-menu-open'
        );
      }
    );

  function parseFishNumber(text) {
    return window.FishNumber.parse(text);
  }

  function clampUpgradeLevel(value) {
    value = Math.floor(
      Number(value)
    );

    if (!isFinite(value)) {
      value = 0;
    }

    return Math.max(
      0,
      Math.min(25, value)
    );
  }

  function getUpgradeLevel(ui) {
    var upgradeBox = ui.find(
      '.enchant-upgrade-box'
    );

    if (!upgradeBox.length) {
      return 0;
    }

    return clampUpgradeLevel(
      upgradeBox.attr(
        'data-upgrade-level'
      )
    );
  }

  function calculateEnchantBaseLevel(
    fishPoints,
    levelMult,
    upgradeLevel
  ) {
    fishPoints = Number(fishPoints);
    levelMult = Number(levelMult);

    upgradeLevel =
      clampUpgradeLevel(upgradeLevel);

    if (
      !isFinite(fishPoints) ||
      fishPoints < 1 ||
      !isFinite(levelMult) ||
      levelMult <= 0
    ) {
      return null;
    }

    return (
      Math.pow(
        fishPoints *
          Math.pow(
            1.2,
            upgradeLevel
          ),
        0.2
      ) *
      levelMult
    );
  }

  function applyLevelCap(
    level,
    levelCap
  ) {
    if (
      levelCap === undefined ||
      levelCap === null
    ) {
      return level;
    }

    levelCap = Number(levelCap);

    if (!isFinite(levelCap)) {
      return level;
    }

    return Math.min(
      level,
      levelCap
    );
  }

  function calculateEnchantLevelRange(
    fishPoints,
    levelMult,
    upgradeLevel,
    levelCap
  ) {
    var baseLevel =
      calculateEnchantBaseLevel(
        fishPoints,
        levelMult,
        upgradeLevel
      );

    if (baseLevel === null) {
      return {
        min: 1,
        max: 1
      };
    }

    var minLevel = Math.max(
      1,
      Math.ceil(
        baseLevel * 0.9
      )
    );

    var maxLevel = Math.max(
      1,
      Math.ceil(
        baseLevel * 1.1
      )
    );

    minLevel = applyLevelCap(
      minLevel,
      levelCap
    );

    maxLevel = applyLevelCap(
      maxLevel,
      levelCap
    );

    return {
      min: minLevel,
      max: maxLevel
    };
  }

  function getNotation(ui) {
    var activeNotation = ui
      .find(
        '.enchant-notation-choice.notation-active'
      )
      .attr(
        'data-notation'
      );

    if (
      activeNotation === 'suffix' ||
      activeNotation === 'scientific'
    ) {
      return activeNotation;
    }

    var savedNotation =
      localStorage.getItem(
        'fishIslandNotation'
      );

    if (
      savedNotation === 'suffix' ||
      savedNotation === 'scientific'
    ) {
      return savedNotation;
    }

    return 'suffix';
  }

  function formatFishNumber(
    number,
    ui
  ) {
    return window.FishNumber.format(
      number,
      getNotation(ui)
    );
  }

  function formatWithModule(
    values,
    ui
  ) {
    return window.FishEN.formatMany(
      values,
      getNotation(ui),
      2
    );
  }

  function updateSingleFormattedText(
    ui,
    element,
    value,
    suffixText
  ) {
    var notation =
      getNotation(ui);

    var requestId =
      Number(
        element.data(
          'fishEnRequest'
        ) || 0
      ) + 1;

    element.data(
      'fishEnRequest',
      requestId
    );

    element.text(
      window.FishNumber.format(
        value,
        notation
      ) +
        (suffixText || '')
    );

    window.FishEN
      .format(
        value,
        notation,
        2
      )
      .then(function (formatted) {
        if (
          Number(
            element.data(
              'fishEnRequest'
            )
          ) !== requestId
        ) {
          return;
        }

        element.text(
          formatted +
            (suffixText || '')
        );
      });
  }

  function normaliseRodType(value) {
    return String(value || '')
      .trim()
      .toLowerCase();
  }

  function normaliseEnchantName(value) {
    return String(value || '')
      .trim()
      .toLowerCase();
  }

  function getEnchantLevelMult(name) {
    var multipliers = {
      strength: 1,
      'strength+': 0.8,
      momentum: 0.65,
      'momentum+': 0.5,
      fortune: 0.5,
      ultra: 0.5,
      'less backfire': 0.75,
      sharpshooter: 0.75
    };

    var key =
      normaliseEnchantName(name);

    return Object.prototype.hasOwnProperty.call(
      multipliers,
      key
    )
      ? multipliers[key]
      : 1;
  }

  function getEnchantColorClass(name) {
    return (
      'enchant-bg-' +
      normaliseEnchantName(name)
        .replace(/\+/g, '-plus')
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '')
    );
  }

  function getEnchantListForUi(ui) {
    var selectedTool =
      ui.data('selectedTool');

    if (!selectedTool) {
      return [];
    }

    var selectedRodType =
      normaliseRodType(
        selectedTool.rodType
      );

    return (entriesData.enchants || [])
      .filter(function (enchant) {
        return (
          normaliseRodType(
            enchant.rodType
          ) === selectedRodType
        );
      })
      .map(function (enchant) {
        return {
          name: enchant.name,
          file: enchant.image,
          levelMult:
            getEnchantLevelMult(
              enchant.name
            ),
          colorClass:
            getEnchantColorClass(
              enchant.name
            )
        };
      });
  }

  function hasSelectedItem(ui) {
    return Boolean(
      ui.data('selectedTool')
    );
  }

  function updateEnchantDisplay(ui) {
    var fishPoints = Number(
      ui
        .find('.enchant-cost-box')
        .attr(
          'data-fish-points'
        )
    );

    var infoText = ui.find(
      '.enchant-info-text'
    );

    var grid = ui.find(
      '.enchant-result-grid'
    );

    var hasRod =
      hasSelectedItem(ui);

    if (
      !hasRod &&
      (
        !fishPoints ||
        fishPoints < 1
      )
    ) {
      grid.hide().empty();

      infoText
        .show()
        .text(
          'Select a rod and input Fish Points'
        );

      return;
    }

    if (!hasRod) {
      grid.hide().empty();

      infoText
        .show()
        .text(
          'Select a rod first'
        );

      return;
    }

    if (
      !fishPoints ||
      fishPoints < 1
    ) {
      grid.hide().empty();

      infoText
        .show()
        .text(
          'Input Fish Points'
        );

      return;
    }

    var enchants =
      getEnchantListForUi(ui);

    if (!enchants.length) {
      grid.hide().empty();

      infoText
        .show()
        .text(
          'No enchants match this tool type'
        );

      return;
    }

    var upgradeLevel =
      getUpgradeLevel(ui);

    var valuesToFormat = [];
    var levelElements = [];

    var renderId =
      Number(
        ui.data(
          'enchantDisplayRenderId'
        ) || 0
      ) + 1;

    ui.data(
      'enchantDisplayRenderId',
      renderId
    );

    grid.empty();

    enchants.forEach(
      function (enchant) {
        var levelRange =
          calculateEnchantLevelRange(
            fishPoints,
            enchant.levelMult,
            upgradeLevel,
            enchant.levelCap
          );

        var imgUrl =
          mw.util.getUrl(
            'Special:Redirect/file/' +
              enchant.file
          );

        var card = $('<div>')
          .addClass(
            'enchant-result-card'
          )
          .addClass(
            enchant.colorClass
          );

        $('<img>')
          .attr(
            'src',
            imgUrl
          )
          .attr(
            'alt',
            enchant.name
          )
          .appendTo(card);

        $('<div>')
          .addClass(
            'enchant-result-name'
          )
          .text(
            enchant.name
          )
          .appendTo(card);

        var levelElement =
          $('<div>')
            .addClass(
              'enchant-result-level'
            )
            .text(
              'Level ' +
                formatFishNumber(
                  levelRange.min,
                  ui
                ) +
                ' - ' +
                formatFishNumber(
                  levelRange.max,
                  ui
                )
            )
            .appendTo(card);

        valuesToFormat.push(
          levelRange.min
        );

        valuesToFormat.push(
          levelRange.max
        );

        levelElements.push(
          levelElement
        );

        grid.append(card);
      }
    );

    infoText.hide();

    grid.css(
      'display',
      'grid'
    );

    formatWithModule(
      valuesToFormat,
      ui
    ).then(
      function (formattedValues) {
        if (
          Number(
            ui.data(
              'enchantDisplayRenderId'
            )
          ) !== renderId
        ) {
          return;
        }

        levelElements.forEach(
          function (element, index) {
            element.text(
              'Level ' +
                formattedValues[
                  index * 2
                ] +
                ' - ' +
                formattedValues[
                  index * 2 + 1
                ]
            );
          }
        );
      }
    );
  }

  function getFileUrl(fileName) {
    if (!fileName) {
      return '';
    }

    return mw.util.getUrl(
      'Special:Redirect/file/' +
        fileName
    );
  }

  function selectTool(ui, tool) {
    ui.data(
      'selectedTool',
      tool
    );

    ui.removeClass(
      'rod-picker-open'
    );

    var itemSlot = ui.find(
      '.enchant-item-slot'
    );

    itemSlot.empty();

    var selectedImage = $('<div>')
      .addClass(
        'enchant-selected-img enchant-selected-active'
      )
      .appendTo(itemSlot);

    if (tool.image) {
      $('<img>')
        .attr(
          'src',
          getFileUrl(tool.image)
        )
        .attr(
          'alt',
          tool.name
        )
        .appendTo(selectedImage);
    }

    ui.find(
      '.enchant-heading-wrap'
    )
      .empty()
      .append(
        $('<div>')
          .addClass(
            'enchant-heading'
          )
          .text(
            tool.name
          )
      );

    updateEnchantDisplay(ui);
  }

  function buildRodPicker(ui) {
    var grid = ui.find(
      '.rod-grid'
    );

    if (!grid.length) {
      return;
    }

    grid.empty();

    var tools =
      entriesData.tools || [];

    if (!tools.length) {
      $('<div>')
        .addClass(
          'rod-picker-message'
        )
        .text(
          'Loading tools...'
        )
        .appendTo(grid);

      return;
    }

    tools.forEach(function (tool) {
      var card = $('<div>')
        .addClass('rod-card')
        .attr('role', 'button')
        .attr('tabindex', '0')
        .data('toolEntry', tool);

      if (tool.image) {
        $('<img>')
          .attr(
            'src',
            getFileUrl(tool.image)
          )
          .attr(
            'alt',
            tool.name
          )
          .appendTo(card);
      }

      $('<div>')
        .text(tool.name)
        .appendTo(card);

      card.appendTo(grid);
    });
  }

  function applyEntriesData(data) {
    if (!data) {
      return;
    }

    entriesData = {
      tools: Array.isArray(data.tools)
        ? data.tools
        : [],
      enchants: Array.isArray(data.enchants)
        ? data.enchants
        : []
    };

    $('.enchant-ui').each(function () {
      var ui = $(this);
      buildRodPicker(ui);

      if (hasSelectedItem(ui)) {
        updateEnchantDisplay(ui);
      }
    });
  }

  $('.enchant-ui').each(
    function () {
      var ui = $(this);

      var box = ui.find(
        '.enchant-cost-box'
      );

      var display = ui.find(
        '.enchant-fish-points-display'
      );



      ui.find(
        '.enchant-menu-fish-advisor, ' +
        '.enchant-advisor-panel, ' +
        '.enchant-fish-advisor, ' +
        '[class*="enchant-advisor-"]'
      ).remove();

      ui.find(
        '.enchant-menu-panel'
      ).removeClass(
        'show-fish'
      );



      var upgradeBox = ui.find(
        '.enchant-upgrade-box'
      );

      if (!upgradeBox.length) {
        var enchantLeft = ui
          .find(
            '.enchant-left'
          )
          .first();

        var itemSlot = enchantLeft
          .find(
            '.enchant-item-slot'
          )
          .first();

        upgradeBox = $('<div>')
          .addClass(
            'enchant-upgrade-box'
          )
          .attr(
            'data-upgrade-level',
            '0'
          )
          .css({
            width: '100%',
            minHeight: '86px',
            marginTop: '16px',
            padding: '10px',
            boxSizing: 'border-box',

            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            gap: '6px',

            background:
              'rgba(10, 7, 20, 0.45)',

            border:
              '1px solid #3b245f',

            color: '#bda2ff',
            fontWeight: 'bold',
            textAlign: 'center',
            cursor: 'text'
          });

        $('<div>')
          .addClass(
            'enchant-upgrade-label'
          )
          .text(
            '3FH Upgrade'
          )
          .css({
            fontSize: '15px',
            lineHeight: '1.1'
          })
          .appendTo(
            upgradeBox
          );

        $('<div>')
          .addClass(
            'enchant-upgrade-display'
          )
          .text(
            'Level 0 / 25'
          )
          .css({
            fontSize: '21px',
            lineHeight: '1.1'
          })
          .appendTo(
            upgradeBox
          );

        if (itemSlot.length) {
          itemSlot.after(
            upgradeBox
          );
        } else if (
          enchantLeft.length
        ) {
          enchantLeft.append(
            upgradeBox
          );
        }
      }

      var upgradeDisplay =
        upgradeBox.find(
          '.enchant-upgrade-display'
        );

      if (
        !upgradeDisplay.length
      ) {
        upgradeDisplay =
          $('<div>')
            .addClass(
              'enchant-upgrade-display'
            )
            .appendTo(
              upgradeBox
            );
      }

      var storedUpgradeLevel =
        localStorage.getItem(
          'fishIsland3FHLevel'
        );

      var existingUpgradeLevel =
        upgradeBox.attr(
          'data-upgrade-level'
        );

      var savedUpgradeLevel;

      if (
        storedUpgradeLevel !== null &&
        storedUpgradeLevel !== ''
      ) {
        savedUpgradeLevel =
          clampUpgradeLevel(
            storedUpgradeLevel
          );
      } else {
        savedUpgradeLevel =
          clampUpgradeLevel(
            existingUpgradeLevel
          );
      }

      upgradeBox.attr(
        'data-upgrade-level',
        savedUpgradeLevel
      );

      upgradeDisplay.text(
        'Level ' +
          savedUpgradeLevel +
          ' / 25'
      );

      upgradeBox
        .off(
          'click.fish3FHUpgrade'
        )
        .on(
          'click.fish3FHUpgrade',
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            if (
              upgradeBox.find(
                'input'
              ).length
            ) {
              return;
            }

            var currentLevel =
              getUpgradeLevel(ui);

            var input = $('<input>')
              .addClass(
                'enchant-upgrade-input'
              )
              .attr(
                'type',
                'number'
              )
              .attr(
                'min',
                '0'
              )
              .attr(
                'max',
                '25'
              )
              .attr(
                'step',
                '1'
              )
              .attr(
                'placeholder',
                '0 - 25'
              )
              .val(
                currentLevel
              )
              .css({
                width: '85%',
                height: '34px',
                padding: '4px 8px',
                boxSizing:
                  'border-box',

                background:
                  '#130b25',

                border:
                  '1px solid #9b6cff',

                color: '#ffffff',
                fontSize: '18px',
                fontWeight: 'bold',
                textAlign: 'center',
                outline: 'none'
              });

            upgradeDisplay.hide();

            upgradeBox.append(
              input
            );

            input.focus();
            input.select();

            var didSave = false;

            function saveUpgradeLevel() {
              if (didSave) {
                return;
              }

              didSave = true;

              var upgradeLevel =
                clampUpgradeLevel(
                  input.val()
                );

              upgradeBox.attr(
                'data-upgrade-level',
                upgradeLevel
              );

              localStorage.setItem(
                'fishIsland3FHLevel',
                upgradeLevel
              );

              upgradeDisplay.text(
                'Level ' +
                  upgradeLevel +
                  ' / 25'
              );

              input.remove();

              upgradeDisplay.show();

              updateEnchantDisplay(
                ui
              );
            }

            input.on(
              'keydown',
              function (keyEvent) {
                if (
                  keyEvent.key ===
                  'Enter'
                ) {
                  keyEvent.preventDefault();

                  saveUpgradeLevel();
                }

                if (
                  keyEvent.key ===
                  'Escape'
                ) {
                  didSave = true;

                  input.remove();

                  upgradeDisplay.show();
                }
              }
            );

            input.on(
              'blur',
              saveUpgradeLevel
            );
          }
        );

      var suffixChoice =
        ui.find(
          '.enchant-notation-choice[data-notation="suffix"]'
        );

      var scientificChoice =
        ui.find(
          '.enchant-notation-choice[data-notation="scientific"]'
        );

      if (
        suffixChoice.length &&
        scientificChoice.length
      ) {
        suffixChoice.insertBefore(
          scientificChoice
        );
      }

      function setNotation(
        notation
      ) {
        if (
          notation !== 'suffix' &&
          notation !== 'scientific'
        ) {
          notation = 'suffix';
        }

        localStorage.setItem(
          'fishIslandNotation',
          notation
        );

        ui.attr(
          'data-notation',
          notation
        );

        ui.find(
          '.enchant-notation-choice'
        ).removeClass(
          'notation-active'
        );

        ui.find(
          '.enchant-notation-choice[data-notation="' +
            notation +
            '"]'
        ).addClass(
          'notation-active'
        );

        var fishPoints =
          box.attr(
            'data-fish-points'
          );

        if (
          fishPoints &&
          !isNaN(
            Number(fishPoints)
          ) &&
          Number(fishPoints) >= 1
        ) {
          updateSingleFormattedText(
            ui,
            display,
            Number(fishPoints),
            ' Fish Points'
          );
        }

        updateEnchantDisplay(
          ui
        );
      }

      var savedNotation =
        localStorage.getItem(
          'fishIslandNotation'
        ) || 'suffix';

      setNotation(
        savedNotation
      );

      ui
        .off(
          'click.fishEnchantPicker',
          '.enchant-open-picker'
        )
        .on(
          'click.fishEnchantPicker',
          '.enchant-open-picker',
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            ui.removeClass(
              'enchant-menu-open'
            );

            ui.addClass(
              'rod-picker-open'
            );
          }
        );

      ui.find(
        '.enchant-menu-set-notation'
      )
        .off(
          'click.fishEnchantNotationMenu'
        )
        .on(
          'click.fishEnchantNotationMenu',
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            ui.find(
              '.enchant-menu-panel'
            ).addClass(
              'show-notation'
            );
          }
        );

      ui.find(
        '.enchant-menu-back'
      )
        .off(
          'click.fishEnchantMenuBack'
        )
        .on(
          'click.fishEnchantMenuBack',
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            ui.find(
              '.enchant-menu-panel'
            ).removeClass(
              'show-notation'
            );
          }
        );

      ui.find(
        '.enchant-notation-choice'
      )
        .off(
          'click.fishEnchantNotationChoice'
        )
        .on(
          'click.fishEnchantNotationChoice',
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            setNotation(
              $(this).attr(
                'data-notation'
              )
            );
          }
        );

      ui
        .off(
          'click.fishEnchantDynamicRod',
          '.rod-card'
        )
        .on(
          'click.fishEnchantDynamicRod',
          '.rod-card',
          function () {
            var tool =
              $(this).data(
                'toolEntry'
              );

            if (tool) {
              selectTool(
                ui,
                tool
              );
            }
          }
        );

      ui
        .off(
          'keydown.fishEnchantDynamicRod',
          '.rod-card'
        )
        .on(
          'keydown.fishEnchantDynamicRod',
          '.rod-card',
          function (event) {
            if (
              event.key !== 'Enter' &&
              event.key !== ' '
            ) {
              return;
            }

            event.preventDefault();

            var tool =
              $(this).data(
                'toolEntry'
              );

            if (tool) {
              selectTool(
                ui,
                tool
              );
            }
          }
        );

      buildRodPicker(ui);

      box
        .off(
          'click.fishEnchantPoints'
        )
        .on(
          'click.fishEnchantPoints',
          function () {
            if (
              box.find(
                'input'
              ).length
            ) {
              return;
            }

            var currentText =
              display
                .text()
                .trim();

            if (
              currentText ===
                'Fish Points' ||
              currentText.indexOf(
                'Input a real number'
              ) !== -1
            ) {
              currentText = '';
            } else {
              currentText =
                currentText
                  .replace(
                    / fish points?/i,
                    ''
                  )
                  .trim();
            }

            var input = $('<input>')
              .addClass(
                'enchant-points-input'
              )
              .attr(
                'type',
                'text'
              )
              .attr(
                'placeholder',
                'Example: 1, 2k, 3m, 1e6'
              )
              .val(
                currentText
              );

            display.hide();

            box.removeClass(
              'fish-points-error'
            );

            box.append(
              input
            );

            input.focus();

            var didSave = false;

            function saveValue() {
              if (didSave) {
                return;
              }

              didSave = true;

              var raw =
                input
                  .val()
                  .trim();

              var parsed =
                parseFishNumber(
                  raw
                );

              if (
                parsed === null
              ) {
                box.removeAttr(
                  'data-fish-points'
                );

                box.addClass(
                  'fish-points-error'
                );

                display.text(
                  'Input a real number in this format: 1, 2k, 3m, 1e6'
                );

                input.remove();

                display.show();

                updateEnchantDisplay(
                  ui
                );

                return;
              }

              box.attr(
                'data-fish-points',
                parsed
              );

              box.removeClass(
                'fish-points-error'
              );

              input.remove();

              display.show();

              updateSingleFormattedText(
                ui,
                display,
                parsed,
                ' Fish Points'
              );

              updateEnchantDisplay(
                ui
              );
            }

            input.on(
              'keydown',
              function (event) {
                if (
                  event.key ===
                  'Enter'
                ) {
                  event.preventDefault();

                  saveValue();
                }

                if (
                  event.key ===
                  'Escape'
                ) {
                  didSave = true;

                  input.remove();

                  display.show();
                }
              }
            );

            input.on(
              'blur',
              saveValue
            );
          }
        );

      updateEnchantDisplay(
        ui
      );
    }
  );

  document.addEventListener(
    'fishEntriesDataReady',
    function (event) {
      applyEntriesData(
        event.detail
      );
    }
  );

  if (window.FishEntriesData) {
    applyEntriesData(
      window.FishEntriesData
    );
  }
});

window.FishNumber = (function () {
  var suffixes = [
    '',
    'k', 'm', 'b', 't', 'qd', 'qn', 'sx', 'sp', 'oc', 'no',
    'de', 'ude', 'dde', 'tde', 'qdde', 'qnde', 'sxde', 'spde', 'ocde', 'node',
    'vt', 'uvt', 'dvt', 'tvt', 'qdvt', 'qnvt', 'sxvt', 'spvt', 'ocvt', 'novt',
    'tg', 'utg', 'dtg', 'ttg', 'qdtg', 'qntg', 'sxtg', 'sptg', 'octg', 'notg',
    'qg', 'uqg', 'dqg', 'tqg', 'qdqg', 'qnqg', 'sxqg', 'spqg', 'ocqg', 'noqg',
    'qag', 'uqag', 'dqag', 'tqag', 'qdqag', 'qnqag', 'sxqag', 'spqag', 'ocqag', 'noqag',
    'sg', 'usg', 'dsg', 'tsg', 'qdsg', 'qnsg', 'sxsg', 'spsg', 'ocsg', 'nosg',
    'spg', 'uspg', 'dspg', 'tspg', 'qdspg', 'qnspg', 'sxspg', 'spspg', 'ocspg', 'nospg',
    'og', 'uog', 'dog', 'tog', 'qdog', 'qnog', 'sxog', 'spog', 'ocog', 'noog',
    'ng', 'ung', 'dng', 'tng', 'qdng', 'qnng', 'sxng', 'spng', 'ocng', 'nong',
    'ce'
  ];

  var multipliers = {};

  suffixes.forEach(function (suffix, index) {
    multipliers[suffix.toLowerCase()] = Math.pow(1000, index);
  });

  function parse(text) {
    var input = String(text || '')
      .trim()
      .toLowerCase()
      .replace(/,/g, '');

    if (input === '') {
      return null;
    }

    var suffixMatch = input.match(/^([0-9]*\.?[0-9]+)([a-z]+)$/i);

    if (suffixMatch) {
      var baseNumber = Number(suffixMatch[1]);
      var suffix = suffixMatch[2].toLowerCase();

      if (!Object.prototype.hasOwnProperty.call(multipliers, suffix)) {
        return null;
      }

      var suffixNumber = baseNumber * multipliers[suffix];

      if (!isFinite(suffixNumber) || suffixNumber < 1) {
        return null;
      }

      return suffixNumber;
    }

    var scientificMatch = input.match(
      /^([0-9]*\.?[0-9]+(?:e[+-]?[0-9]+)?)$/i
    );

    if (!scientificMatch) {
      return null;
    }

    var number = Number(scientificMatch[1]);

    if (!isFinite(number) || number < 1) {
      return null;
    }

    return number;
  }

  function formatSuffix(number) {
    number = Number(number);

    if (!isFinite(number)) {
      return 'Too big';
    }

    var absolute = Math.abs(number);

    if (absolute < 1000) {
      return Math.floor(number).toLocaleString();
    }

    for (var i = suffixes.length - 1; i >= 1; i--) {
      var suffix = suffixes[i];
      var value = multipliers[suffix];

      if (absolute >= value) {
        var shortNumber = number / value;
        var text;

        if (Math.abs(shortNumber) >= 100) {
          text = shortNumber.toFixed(0);
        } else if (Math.abs(shortNumber) >= 10) {
          text = shortNumber.toFixed(1);
        } else {
          text = shortNumber.toFixed(2);
        }

        text = text
          .replace(/\.0+$/, '')
          .replace(/(\.\d*[1-9])0+$/, '$1');

        return text + suffix;
      }
    }

    return String(number);
  }

  function formatScientific(number) {
    number = Number(number);

    if (!isFinite(number)) {
      return 'Too big';
    }

    return number
      .toExponential(2)
      .replace('+', '')
      .replace(/\.00e/, 'e');
  }

  function format(number, notation) {
    if (notation === 'scientific') {
      return formatScientific(number);
    }

    return formatSuffix(number);
  }

  return {
    parse: parse,
    format: format,
    formatSuffix: formatSuffix,
    formatScientific: formatScientific
  };
})();




window.FishEN = (function () {
  var cache = Object.create(null);
  var requestCounter = 0;

  function normaliseNotation(notation) {
    return notation === 'scientific' ? 'scientific' : 'suffix';
  }

  function normaliseDigits(digits) {
    digits = Math.floor(Number(digits));

    if (!isFinite(digits) || digits < 0) {
      return 2;
    }

    return digits;
  }

  function getFunctionName(notation) {
    return notation === 'scientific'
      ? 'toScientific'
      : 'toSuffix';
  }

  function valueToModuleText(value) {
    var number = Number(value);

    if (!isFinite(number)) {
      return null;
    }

    return String(number);
  }

  function fallback(value, notation) {
    return window.FishNumber.format(value, notation);
  }

  function formatMany(values, notation, digits) {
    notation = normaliseNotation(notation);
    digits = normaliseDigits(digits);

    var results = new Array(values.length);
    var missingValues = [];
    var missingKeys = [];
    var missingKeyPositions = Object.create(null);

    values.forEach(function (value, index) {
      var valueText = valueToModuleText(value);

      if (valueText === null) {
        results[index] = fallback(value, notation);
        return;
      }

      var key = [
        notation,
        digits,
        valueText
      ].join('|');

      if (
        Object.prototype.hasOwnProperty.call(
          cache,
          key
        )
      ) {
        results[index] = cache[key];
        return;
      }

      if (
        !Object.prototype.hasOwnProperty.call(
          missingKeyPositions,
          key
        )
      ) {
        missingKeyPositions[key] = [];
        missingKeys.push(key);
        missingValues.push(valueText);
      }

      missingKeyPositions[key].push(index);
    });

    if (missingValues.length === 0) {
      return Promise.resolve(results);
    }

    requestCounter += 1;

    var separator =
      '@@FISH_EN_SPLIT_' +
      requestCounter +
      '_' +
      Date.now() +
      '@@';

    var functionName =
      getFunctionName(notation);

    var invokeText = missingValues
      .map(function (valueText) {
        return (
          '{{#invoke:EN|' +
          functionName +
          '|' +
          valueText +
          '|' +
          digits +
          '}}'
        );
      })
      .join(separator);

    return mw.loader
      .using('mediawiki.api')
      .then(function () {
        var api = new mw.Api();

        return api.post({
          action: 'expandtemplates',
          text: invokeText,
          prop: 'wikitext',
          title: mw.config.get('wgPageName'),
          formatversion: 2
        });
      })
      .then(function (data) {
        var expanded =
          data &&
          data.expandtemplates &&
          data.expandtemplates.wikitext !== undefined
            ? String(
                data.expandtemplates.wikitext
              )
            : '';

        var parts =
          expanded.split(separator);

        missingValues.forEach(
          function (valueText, missingIndex) {
            var key =
              missingKeys[missingIndex];

            var result = String(
              parts[missingIndex] || ''
            ).trim();

            if (!result) {
              result = fallback(
                Number(valueText),
                notation
              );
            }

            cache[key] = result;

            missingKeyPositions[key].forEach(
              function (position) {
                results[position] = result;
              }
            );
          }
        );

        return results;
      })
      .catch(function (error) {
        console.error(
          'Module:EN formatting failed:',
          error
        );

        values.forEach(
          function (value, index) {
            if (
              results[index] === undefined
            ) {
              results[index] = fallback(
                value,
                notation
              );
            }
          }
        );

        return results;
      });
  }

  function format(
    value,
    notation,
    digits
  ) {
    return formatMany(
      [value],
      notation,
      digits
    ).then(function (results) {
      return results[0];
    });
  }

  function clearCache() {
    cache = Object.create(null);
  }

  return {
    format: format,
    formatMany: formatMany,
    clearCache: clearCache
  };
})();



