                    .append(
                      $('<div>')
                        .addClass('enchant-menu-back')
                        .text('Back')
                    )
                )
                .append(
                  $('<span>')
                    .addClass('enchant-menu-close')
                    .text('Close')
                )
            )
        )
        .append(
          $('<div>')
            .addClass('rod-popup')
            .append(
              $('<div>')
                .addClass('rod-popup-panel')
                .append(
                  $('<div>')
                    .addClass('rod-popup-title')
                    .text('Choose a rod')
                )
                .append(
                  $('<div>')
                    .addClass('rod-grid')
                    .append(
                      $('<div>')
                        .addClass('rod-picker-message')
                        .text('Loading tools...')
                    )
                )
            )
        )
    );
  }

  createEnchantingTemplate();

  var entriesData =
    window.FishEntriesData || {
      tools: [],
      enchants: []
    };

  localStorage.removeItem(
    'fishIslandFishPoints'
  );

  $(document)
    .off('click.fishEnchantMenuButton')
    .on(
      'click.fishEnchantMenuButton',
      '.enchant-menu-button',
      function (event) {
        event.preventDefault();
        event.stopPropagation();

        var ui = $(this).closest(
          '.enchant-ui'
        );

        if (!ui.length) {
          ui = $('.enchant-ui').first();
        }

        ui.removeClass(
          'rod-picker-open'
        );

        ui.toggleClass(
          'enchant-menu-open'
        );
      }
    );

  $(document)
    .off('click.fishEnchantMenuClose')
    .on(
      'click.fishEnchantMenuClose',
      '.enchant-menu-close',
      function (event) {
        event.preventDefault();
        event.stopPropagation();

        var ui = $(this).closest(
          '.enchant-ui'
        );

        if (!ui.length) {
          ui = $('.enchant-ui').first();
        }

        ui.removeClass(
          'enchant-menu-open'
        );
      }
    );

  function parseFishNumber(text) {
    return window.FishNumber.parse(text);
  }

  function clampUpgradeLevel(value) {
    value = Math.floor(
      Number(value)
    );

    if (!isFinite(value)) {
      value = 0;
    }

    return Math.max(
      0,
      Math.min(25, value)
    );
  }

  function getUpgradeLevel(ui) {
    var upgradeBox = ui.find(
      '.enchant-upgrade-box'
    );

    if (!upgradeBox.length) {
      return 0;
    }

    return clampUpgradeLevel(
      upgradeBox.attr(
        'data-upgrade-level'
      )
    );
  }

  function calculateEnchantBaseLevel(
    fishPoints,
    levelMult,
    upgradeLevel
  ) {
    fishPoints = Number(fishPoints);
    levelMult = Number(levelMult);

    upgradeLevel =
      clampUpgradeLevel(upgradeLevel);

    if (
      !isFinite(fishPoints) ||
      fishPoints < 1 ||
      !isFinite(levelMult) ||
      levelMult <= 0
    ) {
      return null;
    }

    return (
      Math.pow(
        fishPoints *
          Math.pow(
            1.2,
            upgradeLevel
          ),
        0.2
      ) *
      levelMult
    );
  }

  function applyLevelCap(
    level,
    levelCap
  ) {
    if (
      levelCap === undefined ||
      levelCap === null
    ) {
      return level;
    }

    levelCap = Number(levelCap);

    if (!isFinite(levelCap)) {
      return level;
    }

    return Math.min(
      level,
      levelCap
    );
  }

  function calculateEnchantLevelRange(
    fishPoints,
    levelMult,
    upgradeLevel,
    levelCap
  ) {
    var baseLevel =
      calculateEnchantBaseLevel(
        fishPoints,
        levelMult,
        upgradeLevel
      );

    if (baseLevel === null) {
      return {
        min: 1,
        max: 1
      };
    }

    var minLevel = Math.max(
      1,
      Math.ceil(
        baseLevel * 0.9
      )
    );

    var maxLevel = Math.max(
      1,
      Math.ceil(
        baseLevel * 1.1
      )
    );

    minLevel = applyLevelCap(
      minLevel,
      levelCap
    );

    maxLevel = applyLevelCap(
      maxLevel,
      levelCap
    );

    return {
      min: minLevel,
      max: maxLevel
    };
  }

  function getNotation(ui) {
    var activeNotation = ui
      .find(
        '.enchant-notation-choice.notation-active'
      )
      .attr(
        'data-notation'
      );

    if (
      activeNotation === 'suffix' ||
      activeNotation === 'scientific'
    ) {
      return activeNotation;
    }

    var savedNotation =
      localStorage.getItem(
        'fishIslandNotation'
      );

    if (
      savedNotation === 'suffix' ||
      savedNotation === 'scientific'
    ) {
      return savedNotation;
    }

    return 'suffix';
  }

  function formatFishNumber(
    number,
    ui
  ) {
    return window.FishNumber.format(
      number,
      getNotation(ui)
    );
  }

  function formatWithModule(
    values,
    ui
  ) {
    return window.FishEN.formatMany(
      values,
      getNotation(ui),
      2
    );
  }

  function updateSingleFormattedText(
    ui,
    element,
    value,
    suffixText
  ) {
    var notation =
      getNotation(ui);

    var requestId =
      Number(
        element.data(
          'fishEnRequest'
        ) || 0
      ) + 1;

    element.data(
      'fishEnRequest',
      requestId
    );

    element.text(
      window.FishNumber.format(
        value,
        notation
      ) +
        (suffixText || '')
    );

    window.FishEN
      .format(
        value,
        notation,
        2
      )
      .then(function (formatted) {
        if (
          Number(
            element.data(
              'fishEnRequest'
            )
          ) !== requestId
        ) {
          return;
        }

        element.text(
          formatted +
            (suffixText || '')
        );
      });
  }

  function normaliseRodType(value) {
    return String(value || '')
      .trim()
      .toLowerCase();
  }

  function normaliseEnchantName(value) {
    return String(value || '')
      .trim()
      .toLowerCase();
  }

  function getEnchantLevelMult(enchant) {
    var levelingWeight = Number(
      enchant && enchant.levelingWeight
    );

    return Number.isFinite(levelingWeight) &&
      levelingWeight > 0
      ? levelingWeight
      : 1;
  }

  function getEnchantColorClass(name) {
    return (
      'enchant-bg-' +
      normaliseEnchantName(name)
        .replace(/\+/g, '-plus')
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '')
    );
  }

  function getEnchantListForUi(ui) {
    var selectedTool =
      ui.data('selectedTool');

    if (!selectedTool) {
      return [];
    }

    var selectedRodType =
      normaliseRodType(
        selectedTool.rodType
      );

    return (entriesData.enchants || [])
      .filter(function (enchant) {
        return (
          normaliseRodType(
            enchant.rodType
          ) === selectedRodType
        );
      })
      .map(function (enchant) {
        return {
          name: enchant.name,
          file: enchant.image,
          levelMult:
            getEnchantLevelMult(
              enchant
            ),
          colorClass:
            getEnchantColorClass(
              enchant.name
            )
        };
      });
  }

  function hasSelectedItem(ui) {
    return Boolean(
      ui.data('selectedTool')
    );
  }

  function updateEnchantDisplay(ui) {
    var fishPoints = Number(
      ui
        .find('.enchant-cost-box')
        .attr(
          'data-fish-points'
        )
    );

    var infoText = ui.find(
      '.enchant-info-text'
    );

    var grid = ui.find(
      '.enchant-result-grid'
    );

    var hasRod =
      hasSelectedItem(ui);

    if (
      !hasRod &&
      (
        !fishPoints ||
        fishPoints < 1
      )
    ) {
      grid.hide().empty();

      infoText
        .show()
        .text(
          'Select a rod and input Fish Points'
        );

      return;
    }

    if (!hasRod) {
      grid.hide().empty();

      infoText
        .show()
        .text(
          'Select a rod first'
        );

      return;
    }

    if (
      !fishPoints ||
      fishPoints < 1
    ) {
      grid.hide().empty();

      infoText
        .show()
        .text(
          'Input Fish Points'
        );

      return;
    }

    var enchants =
      getEnchantListForUi(ui);

    if (!enchants.length) {
      grid.hide().empty();

      infoText
        .show()
        .text(
          'No enchants match this tool type'
        );

      return;
    }

    var upgradeLevel =
      getUpgradeLevel(ui);

    var valuesToFormat = [];
    var levelElements = [];

    var renderId =
      Number(
        ui.data(
          'enchantDisplayRenderId'
        ) || 0
      ) + 1;

    ui.data(
      'enchantDisplayRenderId',
      renderId
    );

    grid.empty();

    enchants.forEach(
      function (enchant) {
        var levelRange =
          calculateEnchantLevelRange(
            fishPoints,
            enchant.levelMult,
            upgradeLevel,
            enchant.levelCap
          );

        var imgUrl =
          mw.util.getUrl(
            'Special:Redirect/file/' +
              enchant.file
          );

        var card = $('<div>')
          .addClass(
            'enchant-result-card'
          )
          .addClass(
            enchant.colorClass
          );

        $('<img>')
          .attr(
            'src',
            imgUrl
          )
          .attr(
            'alt',
            enchant.name
          )
          .appendTo(card);

        $('<div>')
          .addClass(
            'enchant-result-name'
          )
          .text(
            enchant.name
          )
          .appendTo(card);

        var levelElement =
          $('<div>')
            .addClass(
              'enchant-result-level'
            )
            .text(
              'Level ' +
                formatFishNumber(
                  levelRange.min,
                  ui
                ) +
                ' - ' +
                formatFishNumber(
                  levelRange.max,
                  ui
                )
            )
            .appendTo(card);

        valuesToFormat.push(
          levelRange.min
        );

        valuesToFormat.push(
          levelRange.max
        );

        levelElements.push(
          levelElement
        );

        grid.append(card);
      }
    );

    infoText.hide();

    grid.css(
      'display',
      'grid'
    );

    formatWithModule(
      valuesToFormat,
      ui
    ).then(
      function (formattedValues) {
        if (
          Number(
            ui.data(
              'enchantDisplayRenderId'
            )
          ) !== renderId
        ) {
          return;
        }

        levelElements.forEach(
          function (element, index) {
            element.text(
              'Level ' +
                formattedValues[
                  index * 2
                ] +
                ' - ' +
                formattedValues[
                  index * 2 + 1
                ]
            );
          }
        );
      }
    );
  }

  function getFileUrl(fileName) {
    if (!fileName) {
      return '';
    }

    return mw.util.getUrl(
      'Special:Redirect/file/' +
        fileName
    );
  }

  function selectTool(ui, tool) {
    ui.data(
      'selectedTool',
      tool
    );

    ui.removeClass(
      'rod-picker-open'
    );

    var itemSlot = ui.find(
      '.enchant-item-slot'
    );

    itemSlot.empty();

    var selectedImage = $('<div>')
      .addClass(
        'enchant-selected-img enchant-selected-active'
      )
      .appendTo(itemSlot);

    if (tool.image) {
      $('<img>')
        .attr(
          'src',
          getFileUrl(tool.image)
        )
        .attr(
          'alt',
          tool.name
        )
        .appendTo(selectedImage);
    }

    ui.find(
      '.enchant-heading-wrap'
    )
      .empty()
      .append(
        $('<div>')
          .addClass(
            'enchant-heading'
          )
          .text(
            tool.name
          )
      );

    updateEnchantDisplay(ui);
  }

  function buildRodPicker(ui) {
    var grid = ui.find(
      '.rod-grid'
    );

    if (!grid.length) {
      return;
    }

    grid.empty();

    var tools =
      entriesData.tools || [];

    if (!tools.length) {
      $('<div>')
        .addClass(
          'rod-picker-message'
        )
        .text(
          'Loading tools...'
        )
        .appendTo(grid);

      return;
    }

    tools.forEach(function (tool) {
      var card = $('<div>')
        .addClass('rod-card')
        .attr('role', 'button')
        .attr('tabindex', '0')
        .data('toolEntry', tool);

      if (tool.image) {
        $('<img>')
          .attr(
            'src',
            getFileUrl(tool.image)
          )
          .attr(
            'alt',
            tool.name
          )
          .appendTo(card);
      }

      $('<div>')
        .text(tool.name)
        .appendTo(card);

      card.appendTo(grid);
    });
  }

  function buildEnchantPlanner(ui) {
    var container = ui.find(
      '.enchant-planner-enchants'
    );

    if (!container.length) {
      return;
    }

    container.empty();

    var seen = {};
    var enchants = [];

    (entriesData.enchants || []).forEach(
      function (enchant) {
        var key =
          normaliseEnchantName(
            enchant.name
          );

        if (!key || seen[key]) {
          return;
        }

        seen[key] = true;
        enchants.push(enchant);
      }
    );

    if (!enchants.length) {
      $('<div>')
        .addClass('enchant-planner-loading')
        .text('Loading enchants...')
        .appendTo(container);

      return;
    }

    enchants.forEach(function (enchant) {
      var choice = $('<div>')
        .addClass('enchant-planner-choice')
        .attr('role', 'button')
        .attr('tabindex', '0')
        .data('enchantEntry', enchant);

      if (enchant.image) {
        $('<img>')
          .attr(
            'src',
            getFileUrl(enchant.image)
          )
          .attr(
            'alt',
            enchant.name
          )
          .appendTo(choice);
      }

      $('<span>')
        .text(enchant.name)
        .appendTo(choice);

      choice.appendTo(container);
    });
  }

  function calculateGuaranteedFishPoints(
    targetLevel,
    levelMult,
    upgradeLevel
  ) {
    var minimumRawLevel =
      targetLevel - 1;

    if (minimumRawLevel <= 0) {
      return 1;
    }

    var requiredBaseLevel =
      minimumRawLevel / 0.9;

    var fishPoints =
      Math.pow(
        requiredBaseLevel /
          levelMult,
        5
      ) /
      Math.pow(
        1.2,
        upgradeLevel
      );

    return Math.floor(fishPoints) + 1;
  }

  function calculatePlannerResult(ui) {
    var selectedEnchant =
      ui.data('plannerEnchant');

    var output = ui.find(
      '.enchant-planner-output'
    );

    if (!selectedEnchant) {
      output.text('Select an enchant first.');
      return;
    }

    var upgradeLevel = Number(
      ui.find('.enchant-planner-3fh').val()
    );

    var targetLevel = Number(
      ui.find('.enchant-planner-target').val()
    );

    if (
      !Number.isInteger(upgradeLevel) ||
      upgradeLevel < 0 ||
      upgradeLevel > 25
    ) {
      output.text(
        'Enter a 3FH level from 0 to 25.'
      );
      return;
    }

    if (
      !Number.isInteger(targetLevel) ||
      targetLevel < 1
    ) {
      output.text(
        'Enter a target enchant level of 1 or higher.'
      );
      return;
    }

    var levelMult =
      getEnchantLevelMult(
        selectedEnchant
      );

    var fishPoints =
      calculateGuaranteedFishPoints(
        targetLevel,
        levelMult,
        upgradeLevel
      );

    if (!Number.isFinite(fishPoints)) {
      output.text(
        'That target is too large to calculate.'
      );
      return;
    }

    output.text(
      'Calculating guaranteed Fish Points...'
    );

    updateSingleFormattedText(
      ui,
      output,
      fishPoints,
      ' Fish Points guaranteed'
    );
  }

  function applyEntriesData(data) {
    if (!data) {
      return;
    }

    entriesData = {
      tools: Array.isArray(data.tools)
        ? data.tools
        : [],
      enchants: Array.isArray(data.enchants)
        ? data.enchants
        : []
    };

    $('.enchant-ui').each(function () {
      var ui = $(this);
      buildRodPicker(ui);
      buildEnchantPlanner(ui);

      if (hasSelectedItem(ui)) {
        updateEnchantDisplay(ui);
      }
    });
  }

  $('.enchant-ui').each(
    function () {
      var ui = $(this);

      var box = ui.find(
        '.enchant-cost-box'
      );

      var display = ui.find(
        '.enchant-fish-points-display'
      );



      ui.find(
        '.enchant-menu-fish-advisor, ' +
        '.enchant-advisor-panel, ' +
        '.enchant-fish-advisor, ' +
        '[class*="enchant-advisor-"]'
      ).remove();

      ui.find(
        '.enchant-menu-panel'
      ).removeClass(
        'show-fish'
      );



      var upgradeBox = ui.find(
        '.enchant-upgrade-box'
      );

      if (!upgradeBox.length) {
        var enchantLeft = ui
          .find(
            '.enchant-left'
          )
          .first();

        var itemSlot = enchantLeft
          .find(
            '.enchant-item-slot'
          )
          .first();

        upgradeBox = $('<div>')
          .addClass(
            'enchant-upgrade-box'
          )
          .attr(
            'data-upgrade-level',
            '0'
          )
          .css({
            width: '100%',
            minHeight: '86px',
            marginTop: '16px',
            padding: '10px',
            boxSizing: 'border-box',

            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            gap: '6px',

            background:
              'rgba(10, 7, 20, 0.45)',

            border:
              '1px solid #3b245f',

            color: '#bda2ff',
            fontWeight: 'bold',
            textAlign: 'center',
            cursor: 'text'
          });

        $('<div>')
          .addClass(
            'enchant-upgrade-label'
          )
          .text(
            '3FH Upgrade'
          )
          .css({
            fontSize: '15px',
            lineHeight: '1.1'
          })
          .appendTo(
            upgradeBox
          );

        $('<div>')
          .addClass(
            'enchant-upgrade-display'
          )
          .text(
            'Level 0 / 25'
          )
          .css({
            fontSize: '21px',
            lineHeight: '1.1'
          })
          .appendTo(
            upgradeBox
          );

        if (itemSlot.length) {
          itemSlot.after(
            upgradeBox
          );
        } else if (
          enchantLeft.length
        ) {
          enchantLeft.append(
            upgradeBox
          );
        }
      }

      var upgradeDisplay =
        upgradeBox.find(
          '.enchant-upgrade-display'
        );

      if (
        !upgradeDisplay.length
      ) {
        upgradeDisplay =
          $('<div>')
            .addClass(
              'enchant-upgrade-display'
            )
            .appendTo(
              upgradeBox
            );
      }

      var storedUpgradeLevel =
        localStorage.getItem(
          'fishIsland3FHLevel'
        );

      var existingUpgradeLevel =
        upgradeBox.attr(
          'data-upgrade-level'
        );

      var savedUpgradeLevel;

      if (
        storedUpgradeLevel !== null &&
        storedUpgradeLevel !== ''
      ) {
        savedUpgradeLevel =
          clampUpgradeLevel(
            storedUpgradeLevel
          );
      } else {
        savedUpgradeLevel =
          clampUpgradeLevel(
            existingUpgradeLevel
          );
      }

      upgradeBox.attr(
        'data-upgrade-level',
        savedUpgradeLevel
      );

      upgradeDisplay.text(
        'Level ' +
          savedUpgradeLevel +
          ' / 25'
      );

      upgradeBox
        .off(
          'click.fish3FHUpgrade'
        )
        .on(
          'click.fish3FHUpgrade',
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            if (
              upgradeBox.find(
                'input'
              ).length
            ) {
              return;
            }

            var currentLevel =
              getUpgradeLevel(ui);

            var input = $('<input>')
              .addClass(
                'enchant-upgrade-input'
              )
              .attr(
                'type',
                'number'
              )
              .attr(
                'min',
                '0'
              )
              .attr(
                'max',
                '25'
              )
              .attr(
                'step',
                '1'
              )
              .attr(
                'placeholder',
                '0 - 25'
              )
              .val(
                currentLevel
              )
              .css({
                width: '85%',
                height: '34px',
                padding: '4px 8px',
                boxSizing:
                  'border-box',

                background:
                  '#130b25',

                border:
                  '1px solid #9b6cff',

                color: '#ffffff',
                fontSize: '18px',
                fontWeight: 'bold',
                textAlign: 'center',
                outline: 'none'
              });

            upgradeDisplay.hide();

            upgradeBox.append(
              input
            );

            input.focus();
            input.select();

            var didSave = false;

            function saveUpgradeLevel() {
              if (didSave) {
                return;
              }

              didSave = true;

              var upgradeLevel =
                clampUpgradeLevel(
                  input.val()
                );

              upgradeBox.attr(
                'data-upgrade-level',
                upgradeLevel
              );

              localStorage.setItem(
                'fishIsland3FHLevel',
                upgradeLevel
              );

              upgradeDisplay.text(
                'Level ' +
                  upgradeLevel +
                  ' / 25'
              );

              input.remove();

              upgradeDisplay.show();

              updateEnchantDisplay(
                ui
              );
            }

            input.on(
              'keydown',
              function (keyEvent) {
                if (
                  keyEvent.key ===
                  'Enter'
                ) {
                  keyEvent.preventDefault();

                  saveUpgradeLevel();
                }

                if (
                  keyEvent.key ===
                  'Escape'
                ) {
                  didSave = true;

                  input.remove();

                  upgradeDisplay.show();
                }
              }
            );

            input.on(
              'blur',
              saveUpgradeLevel
            );
          }
        );

      var suffixChoice =
        ui.find(
          '.enchant-notation-choice[data-notation="suffix"]'
        );

      var scientificChoice =
        ui.find(
          '.enchant-notation-choice[data-notation="scientific"]'
        );

      if (
        suffixChoice.length &&
        scientificChoice.length
      ) {
        suffixChoice.insertBefore(
          scientificChoice
        );
      }

      function setNotation(
        notation
      ) {
        if (
          notation !== 'suffix' &&
          notation !== 'scientific'
        ) {
          notation = 'suffix';
        }

        localStorage.setItem(
          'fishIslandNotation',
          notation
        );

        ui.attr(
          'data-notation',
          notation
        );

        ui.find(
          '.enchant-notation-choice'
        ).removeClass(
          'notation-active'
        );

        ui.find(
          '.enchant-notation-choice[data-notation="' +
            notation +
            '"]'
        ).addClass(
          'notation-active'
        );

        var fishPoints =
          box.attr(
            'data-fish-points'
          );

        if (
          fishPoints &&
          !isNaN(
            Number(fishPoints)
          ) &&
          Number(fishPoints) >= 1
        ) {
          updateSingleFormattedText(
            ui,
            display,
            Number(fishPoints),
            ' Fish Points'
          );
        }

        updateEnchantDisplay(
          ui
        );
      }

      var savedNotation =
        localStorage.getItem(
          'fishIslandNotation'
        ) || 'suffix';

      setNotation(
        savedNotation
      );

      ui
        .off(
          'click.fishEnchantPicker',
