            event.preventDefault();
            event.stopPropagation();

            ui.find(
              '.enchant-menu-panel'
            )
              .removeClass(
                'show-notation'
              )
              .addClass(
                'show-planner'
              );

            buildEnchantPlanner(ui);
          }
        );

      ui.find(
        '.enchant-menu-set-notation'
      )
        .off(
          'click.fishEnchantNotationMenu'
        )
        .on(
          'click.fishEnchantNotationMenu',
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            ui.find(
              '.enchant-menu-panel'
            )
              .removeClass(
                'show-planner'
              )
              .addClass(
                'show-notation'
              );
          }
        );

      ui.find(
        '.enchant-menu-back'
      )
        .off(
          'click.fishEnchantMenuBack'
        )
        .on(
          'click.fishEnchantMenuBack',
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            ui.find(
              '.enchant-menu-panel'
            ).removeClass(
              'show-notation show-planner'
            );
          }
        );

      ui.find(
        '.enchant-notation-choice'
      )
        .off(
          'click.fishEnchantNotationChoice'
        )
        .on(
          'click.fishEnchantNotationChoice',
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            setNotation(
              $(this).attr(
                'data-notation'
              )
            );
          }
        );

      ui
        .off(
          'click.fishEnchantDynamicRod',
          '.rod-card'
        )
        .on(
          'click.fishEnchantDynamicRod',
          '.rod-card',
          function () {
            var tool =
              $(this).data(
                'toolEntry'
              );

            if (tool) {
              selectTool(
                ui,
                tool
              );
            }
          }
        );

      ui
        .off(
          'click.fishEnchantPlannerChoice',
          '.enchant-planner-choice'
        )
        .on(
          'click.fishEnchantPlannerChoice',
          '.enchant-planner-choice',
          function () {
            var enchant =
              $(this).data(
                'enchantEntry'
              );

            if (!enchant) {
              return;
            }

            ui.data(
              'plannerEnchant',
              enchant
            );

            ui.find(
              '.enchant-planner-choice'
            ).removeClass(
              'planner-active'
            );

            $(this).addClass(
              'planner-active'
            );

            ui.find(
