(function () {

    var CREATOR_PAGE = 'Fish_page:sandbox';
    var FISH_PAGE_PREFIX = 'Fish_page:';

    function initFishEntryCreator() {

        if (mw.config.get('wgPageName') !== CREATOR_PAGE) {
            return;
        }

        var container =
            document.getElementById('fish-entry-creator');

        if (!container) {
            return;
        }

        if (container.dataset.loaded === 'true') {
            return;
        }

        container.dataset.loaded = 'true';

        container.innerHTML = `
            <div class="fish-creator">

                <h2>Fish Entry Creator</h2>

                <div class="fish-creator-row">
                    <label for="fishCreatorName">
                        Fish Name
                    </label>

                    <input
                        type="text"
                        id="fishCreatorName"
                        placeholder="Example: Cod"
                    >
                </div>


                <div class="fish-creator-row">
                    <label for="fishCreatorImage">
                        Image File
                    </label>

                    <input
                        type="text"
                        id="fishCreatorImage"
                        placeholder="Example: Cod.png"
                    >
                </div>


                <div class="fish-creator-row">
                    <label for="fishCreatorGroup">
                        Group
                    </label>

                    <select id="fishCreatorGroup">

                        <option value="Default">
                            Default
                        </option>

                        <option value="Bonus">
                            Bonus
                        </option>

                        <option value="Main">
                            Main
                        </option>

                        <option value="Research">
                            Research
                        </option>

                        <option value="Prestige">
                            Prestige
                        </option>

                        <option value="Ascension">
                            Ascension
                        </option>

                    </select>
                </div>


                <div class="fish-creator-row">
                    <label for="fishCreatorWeight">
                        Weight
                    </label>

                    <input
                        type="number"
                        id="fishCreatorWeight"
                        placeholder="Example: 4500"
                    >
                </div>


                <div class="fish-creator-row">
                    <label for="fishCreatorSpawn">
                        Spawn Chance
                    </label>

                    <input
                        type="text"
                        id="fishCreatorSpawn"
                        placeholder="Example: 125"
                    >
                </div>


                <div class="fish-creator-row">
                    <label for="fishCreatorDescription">
                        Description
                    </label>

                    <textarea
                        id="fishCreatorDescription"
                        placeholder="Enter a description..."
                    ></textarea>
                </div>


                <button
                    type="button"
                    id="fishCreatorButton"
                >
                    Create Fish Entry
                </button>


                <div id="fishCreatorStatus"></div>

            </div>
        `;

        document
            .getElementById('fishCreatorButton')
            .addEventListener(
                'click',
                createFishEntry
            );
    }
    function createFishEntry() {

        var name =
            document
                .getElementById('fishCreatorName')
                .value
                .trim();

        var image =
            document
                .getElementById('fishCreatorImage')
                .value
                .trim();

        var group =
            document
                .getElementById('fishCreatorGroup')
                .value;

        var weight =
            document
                .getElementById('fishCreatorWeight')
                .value
                .trim();

        var spawn =
            document
                .getElementById('fishCreatorSpawn')
                .value
                .trim();

        var description =
            document
                .getElementById('fishCreatorDescription')
                .value
                .trim();

        var button =
            document.getElementById(
                'fishCreatorButton'
            );

        var status =
            document.getElementById(
                'fishCreatorStatus'
            );
        if (!name) {

            status.textContent =
                'Please enter a fish name.';

            return;
        }
        if (!image) {

            image =
                name.replace(/\s+/g, '_') +
                '.png';
        }
        var pageName =
            FISH_PAGE_PREFIX + name;
        var pageText =
            '{{FishEntry\n' +

            '|name=' +
            name +
            '\n' +

            '|image=' +
            image +
            '\n' +

            '|group=' +
            group +
            '\n' +

            '|weight=' +
            weight +
            '\n' +

            '|spawnchance=' +
            spawn +
            '\n' +

            '|description=' +
            description +
            '\n' +

            '}}\n\n' +

            '[[Category:Fish]]\n' +

            '[[Category:' +
            group +
            ' Fish]]';
        button.disabled = true;

        status.textContent =
            'Creating ' +
            pageName +
            '...';
        mw.loader
            .using([
                'mediawiki.api',
                'mediawiki.util'
            ])

            .then(function () {

                var api =
                    new mw.Api();

                return api.postWithToken(
                    'csrf',
                    {
                        action: 'edit',

                        title:
                            pageName,

                        text:
                            pageText,

                        summary:
                            'Created fish entry for ' +
                            name,

                        createonly:
                            true,

                        format:
                            'json'
                    }
                );
            })
            .then(function () {

                button.disabled =
                    false;

                var link =
                    mw.util.getUrl(
                        pageName
                    );

                status.innerHTML =
                    '✅ Fish created successfully!<br>' +
                    '<a href="' +
                    link +
                    '">' +
                    pageName +
                    '</a>';
            })
            .catch(function (error) {

                button.disabled =
                    false;

                console.error(
                    'Fish Entry Creator Error:',
                    error
                );

                var errorCode =
                    '';

                if (
                    Array.isArray(error)
                ) {
                    errorCode =
                        error[0];
                }


                if (
                    errorCode ===
                        'articleexists' ||

                    String(error)
                        .indexOf(
                            'articleexists'
                        ) !== -1
                ) {

                    status.textContent =
                        '❌ ' +
                        pageName +
                        ' already exists.';

                } else {

                    status.textContent =
                        '❌ Could not create the fish entry. ' +
                        'Check the browser console for the error.';
                }

            });
    }
    $(initFishEntryCreator);

})();

(function () {

    var CREATOR_PAGE = 'Fish_page:sandbox';

    var PAGE_PREFIXES = {
        Fish: 'Fish_page:',
        Bait: 'Bait_page:',
        Tool: 'Tool_page:',
        Enchant: 'Enchant_page:'
    };

    var RARITIES = [
        'Common',
        'Uncommon',
        'Rare',
        'Epic',
        'Legendary',
        'Mythic'
    ];

    var FISH_GROUPS = [
        'Default',
        'Bonus',
        'Main',
        'Research',
        'Prestige',
        'Ascension'
    ];

    $(function () {

        if (
            mw.config.get('wgPageName') !==
            CREATOR_PAGE
        ) {
            return;
        }

        var container =
            document.getElementById(
                'entry-creator'
            ) ||
            document.getElementById(
                'fish-entry-creator'
            );

        if (!container) {
            return;
        }

        if (
            container.dataset.loaded ===
            'true'
        ) {
            return;
        }

        container.dataset.loaded =
            'true';

        buildCreator(
            container
        );

    });

    function buildCreator(container) {

        var rarityOptions =
            RARITIES.map(
                function (rarity) {

                    return (
                        '<option value="' +
                        escapeAttribute(rarity) +
                        '">' +
                        escapeHtml(rarity) +
                        '</option>'
                    );

                }
            ).join('');

        var weightInputs =
            FISH_GROUPS.map(
                function (group) {

                    return (
                        '<div class="entry-creator-weight">' +

                            '<label>' +
                                escapeHtml(group) +
                            '</label>' +

                            '<input ' +
                                'type="number" ' +
                                'min="0" ' +
                                'step="any" ' +
                                'class="entry-creator-weight-input" ' +
                                'data-fish-group="' +
                                escapeAttribute(group) +
                                '" ' +
                                'placeholder="Not in group"' +
                            '>' +

                        '</div>'
                    );

                }
            ).join('');

        container.innerHTML = `

            <div class="entry-creator">

                <div class="entry-creator-title">
                    Entry Creator
                </div>

                <div class="entry-creator-row">

                    <label for="entryCreatorType">
                        Entry Type
                    </label>

                    <select id="entryCreatorType">

                        <option value="Fish">
                            Fish
                        </option>

                        <option value="Bait">
                            Bait
                        </option>

                        <option value="Tool">
                            Tool
                        </option>

                        <option value="Enchant">
                            Enchant
                        </option>

                    </select>

                </div>

                <div class="entry-creator-row">

                    <label for="entryCreatorName">
                        Name
                    </label>

                    <input
                        type="text"
                        id="entryCreatorName"
                        placeholder="Example: Cod"
                    >

                </div>

                <div class="entry-creator-row">

                    <label for="entryCreatorRarity">
                        Rarity
                    </label>

                    <select id="entryCreatorRarity">
                        ${rarityOptions}
                    </select>

                </div>

                <div class="entry-creator-row">

                    <label for="entryCreatorImage">
                        PNG Image
                    </label>

                    <input
                        type="file"
                        id="entryCreatorImage"
                        accept="image/png,.png"
                    >

                    <div class="entry-creator-file-note">
                        PNG files only.
                    </div>

                </div>

                <div
                    class="entry-creator-preview"
                    id="entryCreatorPreview"
                >
                </div>

                <div class="entry-creator-row">

                    <label for="entryCreatorDescription">
                        Description / Lore
                    </label>

                    <textarea
                        id="entryCreatorDescription"
                        placeholder="Enter the description..."
                    ></textarea>

                </div>

                <div
                    class="entry-creator-type-section"
                    id="entryCreatorFishSection"
                >

                    <div class="entry-creator-section-title">
                        Fish Weights
                    </div>

                    <div class="entry-creator-help">
                        Leave a group blank if the fish
                        cannot be caught there.
                    </div>

                    <div class="entry-creator-weights">
                        ${weightInputs}
                    </div>

                </div>

                <div
                    class="entry-creator-type-section"
                    id="entryCreatorGeneralSection"
                >

                    <div class="entry-creator-row">

                        <label for="entryCreatorChance">
                            Chance / Obtain Method
                        </label>

                        <textarea
                            id="entryCreatorChance"
                            placeholder="Example: 5% drop chance, shop, quest, etc."
                        ></textarea>

                    </div>

                    <div class="entry-creator-row">

                        <label for="entryCreatorCost">
                            Cost
                        </label>

                        <input
                            type="text"
                            id="entryCreatorCost"
                            placeholder="Example: 500 Fish Points"
                        >

                    </div>

                </div>

                <button
                    type="button"
                    id="entryCreatorSubmit"
                >
                    Submit Entry
                </button>

                <div
                    id="entryCreatorStatus"
                    class="entry-creator-status"
                >
                </div>

            </div>

        `;

        document
            .getElementById(
                'entryCreatorType'
            )
            .addEventListener(
                'change',
                updateEntryType
            );

        document
            .getElementById(
                'entryCreatorImage'
            )
            .addEventListener(
                'change',
                updateImagePreview
            );

        document
            .getElementById(
                'entryCreatorSubmit'
            )
            .addEventListener(
                'click',
                submitEntry
            );

        updateEntryType();
        updateSubmitButton();

    }

    function updateEntryType() {

        var type =
            document.getElementById(
                'entryCreatorType'
            ).value;

        var fishSection =
            document.getElementById(
                'entryCreatorFishSection'
            );

        var generalSection =
            document.getElementById(
                'entryCreatorGeneralSection'
            );

        if (type === 'Fish') {

            fishSection.style.display =
                'block';

            generalSection.style.display =
                'none';

        } else {

            fishSection.style.display =
                'none';

            generalSection.style.display =
                'block';

        }

    }

    function isAdmin() {

        var groups =
            mw.config.get(
                'wgUserGroups'
            ) || [];

        return (
            groups.indexOf('sysop') !== -1
        );

    }

    function updateSubmitButton() {

        var button =
            document.getElementById(
                'entryCreatorSubmit'
            );

        if (!button) {
            return;
        }

        if (isAdmin()) {

            button.textContent =
                'Publish Entry';

        } else {

            button.textContent =
                'Submit for Review';

        }

    }

    function updateImagePreview() {

        var input =
            document.getElementById(
                'entryCreatorImage'
            );

        var preview =
            document.getElementById(
                'entryCreatorPreview'
            );

        preview.innerHTML = '';

        if (
            !input.files ||
            !input.files.length
        ) {
            return;
        }

        var file =
            input.files[0];

        if (!isPNG(file)) {

            preview.innerHTML =
                '<div class="entry-creator-error">' +
                'PNG files only.' +
                '</div>';

            return;
        }

        var image =
            document.createElement(
                'img'
            );

        image.src =
            URL.createObjectURL(
                file
            );

        image.onload =
            function () {

                URL.revokeObjectURL(
                    image.src
                );

            };

        preview.appendChild(
            image
        );

    }

    function submitEntry() {

        var status =
            document.getElementById(
                'entryCreatorStatus'
            );

        var button =
            document.getElementById(
                'entryCreatorSubmit'
            );

        status.className =
            'entry-creator-status';

        status.textContent =
            '';

        if (
            !mw.config.get('wgUserName')
        ) {

            showError(
                'You must be logged in to submit an entry.'
            );

            return;
        }

        var data =
            collectFormData();

        if (!data) {
            return;
        }

        button.disabled =
            true;

        status.textContent =
            'Uploading PNG...';

        mw.loader
            .using([
                'mediawiki.api',
                'mediawiki.util'
            ])

            .then(function () {

                var api =
                    new mw.Api();

                return uploadEntryImage(
                    api,
                    data
                )

                .then(function (filename) {

                    data.image =
                        filename;

                    status.textContent =
                        isAdmin()
                            ?
                        'Publishing entry...'
                            :
                        'Creating pending submission...';

                    return createEntryPage(
                        api,
                        data
                    );

                });

            })

            .then(function (result) {

                button.disabled =
                    false;

                showSuccess(
                    result.message,
                    result.page
                );

            })

            .catch(function (error) {

                button.disabled =
                    false;

                console.error(
                    'Entry Creator Error:',
                    error
                );

                showError(
                    getErrorMessage(
                        error
                    )
                );

            });

    }

    function collectFormData() {

        var type =
            document.getElementById(
                'entryCreatorType'
            ).value;

        var name =
            document.getElementById(
                'entryCreatorName'
            ).value.trim();

        var rarity =
            document.getElementById(
                'entryCreatorRarity'
            ).value;

        var description =
            document.getElementById(
                'entryCreatorDescription'
            ).value.trim();

        var imageInput =
            document.getElementById(
                'entryCreatorImage'
            );

        if (!name) {

            showError(
                'Please enter a name.'
            );

            return null;
        }

        if (
            name.indexOf(':') !== -1 ||
            name.indexOf('#') !== -1 ||
            name.indexOf('[') !== -1 ||
            name.indexOf(']') !== -1
        ) {

            showError(
                'The entry name contains characters that cannot be used.'
            );

            return null;
        }

        if (
            !imageInput.files ||
            !imageInput.files.length
        ) {

            showError(
                'Please upload a PNG image.'
            );

            return null;
        }

        var file =
            imageInput.files[0];

        if (!isPNG(file)) {

            showError(
                'The image must be a PNG file.'
            );

            return null;
        }

        var data = {

            type:
                type,

            name:
                name,

            rarity:
                rarity,

            description:
                description ||
                'No description has been added yet.',

            fileInput:
                imageInput,

            weights:
                {},

            chance:
                '',

            cost:
                ''

        };

        if (type === 'Fish') {

            var hasWeight =
                false;

            document
                .querySelectorAll(
                    '.entry-creator-weight-input'
                )
                .forEach(
                    function (input) {

                        var group =
                            input.getAttribute(
                                'data-fish-group'
                            );

                        var value =
                            input.value.trim();

                        if (!value) {
                            return;
                        }

                        var weight =
                            Number(value);

                        if (
                            !isFinite(weight) ||
                            weight <= 0
                        ) {
                            return;
                        }

                        data.weights[group] =
                            weight;

                        hasWeight =
                            true;

                    }
                );

            if (!hasWeight) {

                showError(
                    'A fish needs a weight in at least one group.'
                );

                return null;
            }

        } else {

            data.chance =
                document
                    .getElementById(
                        'entryCreatorChance'
                    )
                    .value
                    .trim() ||
                'TBD';

            data.cost =
                document
                    .getElementById(
                        'entryCreatorCost'
                    )
                    .value
                    .trim() ||
                'TBD';

        }

        return data;

    }

    function isPNG(file) {

        if (!file) {
            return false;
        }

        var name =
            file.name.toLowerCase();

        var validExtension =
            name.slice(-4) === '.png';

        var validMime =
            (
                !file.type ||
                file.type === 'image/png'
            );

        return (
            validExtension &&
            validMime
        );

    }

    function uploadEntryImage(
        api,
        data
    ) {

        var filename =
            makeImageFilename(
                data.type,
                data.name
            );

        var parameters = {

            filename:
                filename,

            comment:
                'Image uploaded for ' +
                data.type +
                ' entry: ' +
                data.name,

            format:
                'json',

            ignorewarnings:
                0

        };

        return new Promise(
            function (
                resolve,
                reject
            ) {

                api.upload(
                    data.fileInput,
                    parameters
                )

                .done(
                    function (response) {

                        if (
                            !response.upload
                        ) {

                            reject(
                                'The image upload returned no result.'
                            );

                            return;
                        }

                        if (
                            response.upload.result ===
                            'Warning'
                        ) {

                            console.warn(
                                'Upload warning:',
                                response.upload.warnings
                            );

                            reject(
                                'That PNG could not be uploaded because MediaWiki returned an upload warning. The file may already exist.'
                            );

                            return;
                        }

                        if (
                            response.upload.result !==
                            'Success'
                        ) {

                            reject(
                                'The PNG upload did not complete.'
                            );

                            return;
                        }

                        resolve(
                            response.upload.filename ||
                            filename
                        );

                    }
                )

                .fail(
                    function (error) {

                        reject(
                            error
                        );

                    }
                );

            }
        );

    }

    function makeImageFilename(
        type,
        name
    ) {

        var safeName =
            name
                .replace(
                    /[\/\\:#<>\[\]|{}]/g,
                    ''
                )
                .replace(
                    /\s+/g,
                    '_'
                )
                .trim();

        return (
            type +
            '_' +
            safeName +
            '.png'
        );

    }

    function createEntryPage(
        api,
        data
    ) {

        var admin =
            isAdmin();

        var pageName;

        if (admin) {

            pageName =
                PAGE_PREFIXES[
                    data.type
                ] +
                data.name;

        } else {

            pageName =
                'Entry_submission:' +
                data.type +
                '/' +
                data.name;

        }

        var pageText =
            buildEntryWikitext(
                data,
                admin
            );

        return api
            .postWithToken(
                'csrf',
                {

                    action:
                        'edit',

                    title:
                        pageName,

                    text:
                        pageText,

                    summary:
                        admin
                            ?
                        'Published ' +
                        data.type +
                        ' entry: ' +
                        data.name
                            :
                        'Submitted ' +
                        data.type +
                        ' entry for review: ' +
                        data.name,

                    createonly:
                        true,

                    format:
                        'json'

                }
            )

            .then(
                function () {

                    return {

                        page:
                            pageName,

                        message:
                            admin
                                ?
                            'Entry published successfully!'
                                :
                            'Entry submitted successfully and is waiting for approval.'

                    };

                }
            );

    }

    function buildEntryWikitext(
        data,
        live
    ) {

        var text =
            '{{EntryData\n' +

            '|type=' +
            safeTemplateValue(
                data.type
            ) +
            '\n' +

            '|name=' +
            safeTemplateValue(
                data.name
            ) +
            '\n' +

            '|image=' +
            safeTemplateValue(
                data.image
            ) +
            '\n' +

            '|rarity=' +
            safeTemplateValue(
                data.rarity
            ) +
            '\n' +

            '|description=' +
            safeTemplateValue(
                data.description
            ) +
            '\n';

        if (
            data.type ===
            'Fish'
        ) {

            FISH_GROUPS.forEach(
                function (group) {

                    var key =
                        group
                            .toLowerCase()
                            .replace(
                                /\s+/g,
                                '_'
                            );

                    var weight =
                        data.weights[
                            group
                        ] || '';

                    text +=
                        '|' +
                        key +
                        '_weight=' +
                        weight +
                        '\n';

                }
            );

        } else {

            text +=
                '|chance=' +
                safeTemplateValue(
                    data.chance
                ) +
                '\n';

            text +=
                '|cost=' +
                safeTemplateValue(
                    data.cost
                ) +
                '\n';

        }

        text +=
            '|status=' +
            (
                live
                    ?
                'Published'
                    :
                'Pending'
            ) +
            '\n';

        text +=
            '}}\n\n';

        if (live) {

            text +=
                '[[Category:' +
                data.type +
                ' Entries]]\n';

            if (
                data.type ===
                'Fish'
            ) {

                Object.keys(
                    data.weights
                )
                .forEach(
                    function (group) {

                        text +=
                            '[[Category:' +
                            group +
                            ' Fish]]\n';

                    }
                );

            }

        } else {

            text +=
                '[[Category:Pending Entry Submissions]]\n';

            text +=
                '[[Category:Pending ' +
                data.type +
                ' Submissions]]\n';

        }

        return text;

    }

    function safeTemplateValue(
        value
    ) {

        return String(
            value || ''
        )

        .replace(
            /\|/g,
            '&#124;'
        )

        .replace(
            /\}\}/g,
            '}&#125;'
        );

    }

    function showError(message) {

        var status =
            document.getElementById(
                'entryCreatorStatus'
            );

        status.className =
            'entry-creator-status ' +
            'entry-creator-status-error';

        status.textContent =
            message;

    }

    function showSuccess(
        message,
        pageName
    ) {

        var status =
            document.getElementById(
                'entryCreatorStatus'
            );

        status.className =
            'entry-creator-status ' +
            'entry-creator-status-success';

        var url =
            mw.util.getUrl(
                pageName
            );

        status.innerHTML =

            '✅ ' +
            escapeHtml(message) +

            '<br>' +

            '<a href="' +
            escapeAttribute(url) +
            '">' +

            escapeHtml(pageName) +

            '</a>';

    }

    function getErrorMessage(
        error
    ) {

        var text =
            String(error);

        if (
            text.indexOf(
                'articleexists'
            ) !== -1
        ) {

            return (
                'An entry with that name already exists.'
            );

        }

        if (
            text.indexOf(
                'permissiondenied'
            ) !== -1 ||

            text.indexOf(
                'badaccess'
            ) !== -1
        ) {

            return (
                'Your account does not have permission to perform this action.'
            );

        }

        return (
            'The entry could not be submitted. Check the browser console for the full error.'
        );

    }

    function escapeHtml(value) {

        return String(value)

            .replace(
                /&/g,
                '&amp;'
            )

            .replace(
                /</g,
                '&lt;'
            )

            .replace(
                />/g,
                '&gt;'
            )

            .replace(
                /"/g,
                '&quot;'
            )

            .replace(
                /'/g,
                '&#039;'
            );

    }

    function escapeAttribute(
        value
    ) {

        return escapeHtml(
            value
        );

    }

})();

(function () {

    var CREATOR_PAGE = 'Fish_page:sandbox';

    var PAGE_PREFIXES = {
        Fish: 'Fish_page:',
        Bait: 'Bait_page:',
        Tool: 'Tool_page:',
        Enchant: 'Enchant_page:'
    };

    var RARITIES = [
        'Common',
        'Uncommon',
        'Rare',
        'Epic',
        'Legendary',
        'Mythic'
    ];

    var FISH_GROUPS = [
        'Default',
        'Bonus',
        'Main',
        'Research',
        'Prestige',
        'Ascension'
    ];

    var loadedEdit = null;

    $(function () {

        if (
            mw.config.get('wgPageName') !==
            CREATOR_PAGE
        ) {
            return;
        }

        var container =
            document.getElementById('entry-creator') ||
            document.getElementById('fish-entry-creator');

        if (!container) {
