                            Enchant
                        </option>

                        <option value="Edit">
                            Edit Existing Entry
                        </option>

                    </select>

                </div>

                <div
                    class="entry-creator-type-section"
                    id="entryCreatorEditSection"
                >

                    <div class="entry-creator-section-title">
                        Edit Existing Entry
                    </div>

                    <div class="entry-creator-row">

                        <label for="entryCreatorEditType">
                            Existing Entry Type
                        </label>

                        <select id="entryCreatorEditType">

                            <option value="Fish">
                                Fish
                            </option>

                            <option value="Bait">
                                Bait
                            </option>

                            <option value="Tool">
                                Tool
                            </option>

                            <option value="Enchant">
                                Enchant
                            </option>

                        </select>

                    </div>

                    <div class="entry-creator-row">

                        <label for="entryCreatorEditName">
                            Existing Entry Name
                        </label>

                        <input
                            type="text"
                            id="entryCreatorEditName"
                            placeholder="Example: Cod"
                        >

                    </div>

                    <button
