                        id="entryCreatorLoad"
                    >
                        Load Entry
                    </button>

                    <div
                        id="entryCreatorLoadStatus"
                        class="entry-creator-status"
                    ></div>

                </div>

                <div
                    id="entryCreatorFormFields"
                >

                    <div class="entry-creator-row">

                        <label for="entryCreatorName">
                            Name
                        </label>

                        <input
                            type="text"
                            id="entryCreatorName"
                            placeholder="Example: Cod"
                        >

                    </div>

                    <div class="entry-creator-row">

                        <label for="entryCreatorRarity">
                            Rarity
                        </label>

                        <select id="entryCreatorRarity">
                            ${rarityOptions}
                        </select>

                    </div>

                    <div class="entry-creator-row">

                        <label for="entryCreatorImage">
                            PNG Image
                        </label>

                        <input
                            type="file"
                            id="entryCreatorImage"
                            accept="image/png,.png"
                        >

                        <div
                            class="entry-creator-file-note"
                            id="entryCreatorImageNote"
                        >
                            PNG files only.
                        </div>

                    </div>

                    <div
                        class="entry-creator-preview"
                        id="entryCreatorPreview"
                    ></div>

                    <div class="entry-creator-row">

                        <label for="entryCreatorDescription">
                            Description / Lore
                        </label>

                        <textarea
                            id="entryCreatorDescription"
                            placeholder="Enter the description..."
                        ></textarea>

                    </div>

                    <div
                        class="entry-creator-type-section"
                        id="entryCreatorFishSection"
                    >

                        <div class="entry-creator-row">

                            <label for="entryCreatorFishSellPrice">
                                Sell Price
                            </label>

                            <input
                                type="number"
                                id="entryCreatorFishSellPrice"
                                min="0"
                                step="any"
                                placeholder="Example: 5"
                            >

                        </div>

                        <div class="entry-creator-section-title">
                            Fish Weights
                        </div>

