                        </div>

                    </div>

                    <div
                        class="entry-creator-type-section"
                        id="entryCreatorBaitSection"
                    >

                        <div class="entry-creator-row">

                            <label for="entryCreatorBaitSellPrice">
                                Sell Price
                            </label>

                            <input
                                type="number"
                                id="entryCreatorBaitSellPrice"
                                min="0"
                                step="any"
                                placeholder="Example: 10"
                            >

                        </div>

                    </div>

                    <div
                        class="entry-creator-type-section"
                        id="entryCreatorToolSection"
                    >

                        <div class="entry-creator-row">

                            <label for="entryCreatorToolBaseCost">
                                Base Cost
                            </label>

                            <input
                                type="number"
                                id="entryCreatorToolBaseCost"
                                min="0"
                                step="any"
                                placeholder="Example: 500"
                            >

                        </div>

                    </div>

                    <div
                        class="entry-creator-type-section"
                        id="entryCreatorEnchantSection"
                    >

                        <div class="entry-creator-row">

                            <label for="entryCreatorEnchantWeight">
                                Weight
                            </label>

                            <input
                                type="number"
                                id="entryCreatorEnchantWeight"
                                min="0"
                                step="any"
                                placeholder="Example: 100"
                            >

                        </div>

                    </div>

                    <button
                        type="button"
                        id="entryCreatorSubmit"
                    >
                        Submit Entry
                    </button>

                    <div
                        id="entryCreatorStatus"
