                    ></div>

                </div>

            </div>

        `;

        document
            .getElementById('entryCreatorType')
            .addEventListener(
                'change',
                function () {

                    loadedEdit =
                        null;

                    clearForm();

                    updateEntryType();
                    updateSubmitButton();

                }
            );

        document
            .getElementById('entryCreatorImage')
            .addEventListener(
                'change',
                updateImagePreview
            );

        document
            .getElementById('entryCreatorLoad')
            .addEventListener(
                'click',
                loadExistingEntry
            );

        document
            .getElementById('entryCreatorSubmit')
            .addEventListener(
                'click',
                submitEntry
            );

        updateEntryType();
        updateSubmitButton();

    }

    function getCurrentDataType() {

        var creatorType =
            document.getElementById(
                'entryCreatorType'
            ).value;

        if (
            creatorType ===
            'Edit'
        ) {

            return document
                .getElementById(
                    'entryCreatorEditType'
                )
                .value;

        }

        return creatorType;

    }

    function updateEntryType() {

        var creatorType =
            document.getElementById(
                'entryCreatorType'
            ).value;

        var editSection =
            document.getElementById(
                'entryCreatorEditSection'
            );

        var formFields =
            document.getElementById(
                'entryCreatorFormFields'
            );

        if (
            creatorType ===
            'Edit'
        ) {

            editSection.style.display =
                'block';

            formFields.style.display =
                loadedEdit
                    ? 'block'
                    : 'none';

        } else {

            editSection.style.display =
                'none';

            formFields.style.display =
                'block';

        }

        updateSpecificSections();

    }

    function updateSpecificSections() {

        var creatorType =
            document.getElementById(
                'entryCreatorType'
            ).value;

        if (
            creatorType === 'Edit' &&
            !loadedEdit
        ) {

            hideSpecificSections();
            return;

        }

        var type =
            getCurrentDataType();

        document
            .getElementById(
                'entryCreatorFishSection'
            )
            .style.display =
                type === 'Fish'
                    ? 'block'
                    : 'none';

        document
            .getElementById(
                'entryCreatorBaitSection'
            )
            .style.display =
                type === 'Bait'
                    ? 'block'
                    : 'none';

        document
            .getElementById(
                'entryCreatorToolSection'
            )
            .style.display =
                type === 'Tool'
                    ? 'block'
                    : 'none';

        document
            .getElementById(
                'entryCreatorEnchantSection'
            )
            .style.display =
                type === 'Enchant'
                    ? 'block'
                    : 'none';

    }

    function hideSpecificSections() {

        document
            .getElementById(
                'entryCreatorFishSection'
            )
            .style.display =
                'none';

        document
            .getElementById(
                'entryCreatorBaitSection'
            )
            .style.display =
                'none';

        document
            .getElementById(
                'entryCreatorToolSection'
            )
            .style.display =
                'none';

        document
            .getElementById(
                'entryCreatorEnchantSection'
            )
            .style.display =
                'none';

    }

    function loadExistingEntry() {

        var type =
            document.getElementById(
                'entryCreatorEditType'
            ).value;

        var name =
            document.getElementById(
                'entryCreatorEditName'
            ).value.trim();

        var status =
            document.getElementById(
                'entryCreatorLoadStatus'
            );

        if (!name) {

            status.textContent =
                'Please enter the entry name.';

            return;

        }

        var pageName =
            PAGE_PREFIXES[type] +
            name;

        status.textContent =
            'Loading ' +
            pageName +
            '...';

        mw.loader
            .using([
                'mediawiki.api',
                'mediawiki.util'
            ])

            .then(function () {

                var api =
                    new mw.Api();

                return api.get({

                    action:
                        'query',

                    prop:
                        'revisions',

                    titles:
                        pageName,

                    rvprop:
                        'content',

                    rvslots:
                        'main',

                    format:
                        'json',

                    formatversion:
                        2

                });

            })

            .then(function (response) {

                if (
                    !response.query ||
                    !response.query.pages ||
                    !response.query.pages.length
                ) {

                    throw new Error(
                        'Entry not found.'
                    );

                }

                var page =
                    response.query.pages[0];

                if (
                    page.missing
                ) {

                    throw new Error(
                        'Entry not found.'
                    );

                }

                if (
                    !page.revisions ||
                    !page.revisions.length
                ) {

                    throw new Error(
                        'Could not read the entry.'
                    );

                }

                var revision =
                    page.revisions[0];

                var text =
                    '';

                if (
                    revision.slots &&
                    revision.slots.main
                ) {

                    text =
                        revision.slots.main.content ||
                        revision.slots.main['*'] ||
                        '';

                } else {

                    text =
                        revision.content ||
                        revision['*'] ||
                        '';

                }

                var data =
                    parseEntryData(
                        text
                    );

                if (!data) {

                    throw new Error(
                        'This page does not contain an EntryData template.'
                    );

                }

                loadedEdit = {

                    page:
                        pageName,

                    originalName:
                        data.name || name,

                    type:
                        type,

                    image:
                        data.image || '',

                    originalText:
                        text

                };

                populateForm(
                    type,
                    data
                );

                status.textContent =
                    'Entry loaded successfully.';

                document
                    .getElementById(
                        'entryCreatorFormFields'
                    )
                    .style.display =
                        'block';

                updateSpecificSections();
                updateSubmitButton();

            })

            .catch(function (error) {

                loadedEdit =
                    null;

                document
                    .getElementById(
                        'entryCreatorFormFields'
                    )
                    .style.display =
                        'none';

                console.error(
                    'Entry Load Error:',
                    error
                );

                status.textContent =
                    'Could not load that entry.';

            });

    }

    function parseEntryData(text) {

        var match =
            text.match(
                /\{\{\s*EntryData\b([\s\S]*?)\n?\}\}/i
            );

        if (!match) {
            return null;
        }

        var data =
            {};

        var lines =
            match[1].split(
                /\r?\n/
            );

        var currentKey =
            null;

        lines.forEach(function (line) {

            var parameter =
                line.match(
                    /^\s*\|\s*([^=]+?)\s*=\s*(.*)$/
                );

            if (parameter) {

                currentKey =
                    parameter[1]
                        .trim()
                        .toLowerCase();

                data[currentKey] =
                    decodeTemplateValue(
                        parameter[2].trim()
                    );

                return;

            }

            if (
                currentKey &&
                line.trim()
            ) {

                data[currentKey] +=
                    '\n' +
                    line.trim();

            }

        });

        return data;

    }

    function populateForm(
        type,
        data
    ) {

        clearForm();

        document
            .getElementById(
                'entryCreatorName'
            ).value =
                data.name || '';

        document
            .getElementById(
                'entryCreatorRarity'
            ).value =
                RARITIES.indexOf(
                    data.rarity
                ) !== -1
                    ? data.rarity
                    : 'Common';

        document
            .getElementById(
                'entryCreatorDescription'
            ).value =
                data.description || '';

        document
            .getElementById(
                'entryCreatorEditType'
            ).value =
                type;

        var imageNote =
            document.getElementById(
                'entryCreatorImageNote'
            );

        imageNote.textContent =
            data.image
                ? 'Current image: ' +
                  data.image +
                  '. Choose a new PNG only if you want to replace it.'
                : 'No current PNG. Choose a PNG to add one.';

        showExistingImage(
            data.image || ''
        );

        if (
            type === 'Fish'
        ) {

            document
                .getElementById(
                    'entryCreatorFishSellPrice'
                ).value =
                    data.sell_price || '';

            FISH_GROUPS.forEach(
                function (group) {

                    var key =
                        group
                            .toLowerCase()
                            .replace(
                                /\s+/g,
                                '_'
                            ) +
                        '_weight';

                    var input =
                        document.querySelector(
                            '.entry-creator-weight-input[data-fish-group="' +
                            group +
                            '"]'
                        );

                    if (input) {

                        input.value =
                            data[key] || '';

                    }

                }
            );

        }

        if (
            type === 'Bait'
        ) {

            document
                .getElementById(
                    'entryCreatorBaitSellPrice'
                ).value =
                    data.sell_price || '';

        }

        if (
            type === 'Tool'
        ) {

            document
                .getElementById(
                    'entryCreatorToolBaseCost'
                ).value =
                    data.base_cost || '';

        }

        if (
            type === 'Enchant'
        ) {

            document
                .getElementById(
                    'entryCreatorEnchantWeight'
                ).value =
                    data.weight || '';

        }

    }

    function showExistingImage(
        filename
    ) {

        var preview =
            document.getElementById(
                'entryCreatorPreview'
            );

        preview.innerHTML =
            '';

        if (!filename) {
            return;
        }

        var image =
            document.createElement(
                'img'
            );

        image.src =
            mw.util.getUrl(
                'Special:Redirect/file/' +
                filename
            );

        preview.appendChild(
            image
        );

    }

    function clearForm() {

        var ids = [
            'entryCreatorName',
            'entryCreatorDescription',
            'entryCreatorFishSellPrice',
            'entryCreatorBaitSellPrice',
            'entryCreatorToolBaseCost',
            'entryCreatorEnchantWeight'
        ];

        ids.forEach(
            function (id) {

                var element =
                    document.getElementById(
                        id
                    );

                if (element) {

                    element.value =
                        '';

                }

            }
        );

        var rarity =
            document.getElementById(
                'entryCreatorRarity'
            );

        if (rarity) {

            rarity.value =
                'Common';

        }

        document
            .querySelectorAll(
                '.entry-creator-weight-input'
            )
            .forEach(
                function (input) {

                    input.value =
                        '';

                }
            );

        var imageInput =
            document.getElementById(
                'entryCreatorImage'
            );

        if (imageInput) {

            imageInput.value =
                '';

        }

        var preview =
            document.getElementById(
                'entryCreatorPreview'
            );

        if (preview) {

            preview.innerHTML =
                '';

        }

        var status =
            document.getElementById(
                'entryCreatorStatus'
            );

        if (status) {

            status.textContent =
                '';

            status.className =
                'entry-creator-status';

        }

        var imageNote =
            document.getElementById(
                'entryCreatorImageNote'
            );

        if (imageNote) {

            imageNote.textContent =
                'PNG files only.';

        }

    }

    function isAdmin() {

        var groups =
            mw.config.get(
                'wgUserGroups'
            ) || [];

        return (
            groups.indexOf(
                'sysop'
            ) !== -1
        );

    }

    function updateSubmitButton() {

        var button =
            document.getElementById(
                'entryCreatorSubmit'
            );

        if (!button) {
            return;
        }

        var mode =
            document.getElementById(
                'entryCreatorType'
            ).value;

        if (
            mode === 'Edit'
        ) {

            button.textContent =
                isAdmin()
                    ? 'Save Changes'
                    : 'Submit Edit for Review';

        } else {

            button.textContent =
                isAdmin()
                    ? 'Publish Entry'
                    : 'Submit for Review';

        }

    }

    function updateImagePreview() {

        var input =
            document.getElementById(
                'entryCreatorImage'
            );

        var preview =
            document.getElementById(
                'entryCreatorPreview'
            );

        preview.innerHTML =
            '';

        if (
            !input.files ||
            !input.files.length
        ) {

            if (
                loadedEdit &&
                loadedEdit.image
            ) {

                showExistingImage(
                    loadedEdit.image
                );

            }

            return;

        }

        var file =
            input.files[0];

        if (!isPNG(file)) {

            preview.innerHTML =
                '<div class="entry-creator-error">' +
                'PNG files only.' +
                '</div>';

            return;

        }

        var image =
            document.createElement(
                'img'
            );

        var imageUrl =
            URL.createObjectURL(
                file
            );

        image.src =
            imageUrl;

        image.onload =
            function () {

                URL.revokeObjectURL(
                    imageUrl
                );

            };

        preview.appendChild(
            image
        );

    }

    function submitEntry() {

        var status =
            document.getElementById(
                'entryCreatorStatus'
            );

        var button =
            document.getElementById(
                'entryCreatorSubmit'
            );

        status.className =
            'entry-creator-status';

        status.textContent =
            '';

        if (
            !mw.config.get(
                'wgUserName'
            )
        ) {

            showError(
                'You must be logged in to submit an entry.'
            );

            return;

        }

        var mode =
            document.getElementById(
                'entryCreatorType'
            ).value;

        if (
            mode === 'Edit' &&
            !loadedEdit
        ) {

            showError(
                'Load an existing entry first.'
            );

            return;

        }

        var data =
            collectFormData();

        if (!data) {
            return;
        }

        button.disabled =
            true;

        mw.loader
            .using([
                'mediawiki.api',
                'mediawiki.util'
            ])

            .then(function () {

                var api =
                    new mw.Api();

                if (
                    data.file
                ) {

                    status.textContent =
                        'Uploading PNG...';

                    return uploadEntryImage(
                        api,
                        data
                    )

                    .then(
                        function (filename) {

                            data.image =
                                filename;

                            return api;

                        }
                    );

                }

                data.image =
                    loadedEdit
                        ? loadedEdit.image
                        : '';

                return api;

            })

            .then(function (api) {

                status.textContent =
                    mode === 'Edit'
                        ? (
                            isAdmin()
                                ? 'Saving changes...'
                                : 'Creating edit submission...'
                        )
                        : (
                            isAdmin()
                                ? 'Publishing entry...'
                                : 'Creating pending submission...'
                        );

                return saveEntry(
                    api,
                    data,
                    mode
                );

            })

            .then(function (result) {

                button.disabled =
                    false;

                showSuccess(
                    result.message,
                    result.page
                );

            })

            .catch(function (error) {

                button.disabled =
                    false;

                console.error(
                    'Entry Creator Error:',
                    error
                );

                showError(
                    getErrorMessage(
                        error
                    )
                );

            });

    }

    function collectFormData() {

        var mode =
            document.getElementById(
                'entryCreatorType'
            ).value;

        var type =
            getCurrentDataType();

        var name =
            document.getElementById(
                'entryCreatorName'
            ).value.trim();

        var rarity =
            document.getElementById(
                'entryCreatorRarity'
            ).value;

        var description =
            document.getElementById(
                'entryCreatorDescription'
            ).value.trim();

        var imageInput =
            document.getElementById(
                'entryCreatorImage'
            );

        if (!name) {

            showError(
                'Please enter a name.'
            );

            return null;

        }

        if (
            name.indexOf(':') !== -1 ||
            name.indexOf('#') !== -1 ||
            name.indexOf('[') !== -1 ||
            name.indexOf(']') !== -1
        ) {

            showError(
                'The entry name contains characters that cannot be used.'
            );

            return null;

        }

        var file =
            null;

        if (
            imageInput.files &&
            imageInput.files.length
        ) {

            file =
                imageInput.files[0];

            if (!isPNG(file)) {

                showError(
                    'The image must be a PNG file.'
                );

                return null;

            }

        }

        if (
            mode !== 'Edit' &&
            !file
        ) {

            showError(
                'Please upload a PNG image.'
            );

            return null;

        }

        var data = {

            type:
                type,

            name:
                name,

            rarity:
                rarity,

            description:
                description ||
                'No description has been added yet.',

            file:
                file,

            image:
                '',

            weights:
                {},

            sellPrice:
                '',

            baseCost:
                '',

            enchantWeight:
                ''

        };

        if (
            type === 'Fish'
        ) {

            var sellPrice =
                document
                    .getElementById(
                        'entryCreatorFishSellPrice'
                    )
                    .value
                    .trim();

            if (!sellPrice) {

                showError(
                    'Please enter the fish sell price.'
                );

                return null;

            }

            var hasWeight =
                false;

            var invalidWeight =
                false;

            document
                .querySelectorAll(
                    '.entry-creator-weight-input'
                )
                .forEach(
                    function (input) {

                        var group =
                            input.getAttribute(
                                'data-fish-group'
                            );

                        var value =
                            input.value.trim();

                        if (!value) {
                            return;
                        }

                        var weight =
                            Number(value);

                        if (
                            !isFinite(weight) ||
                            weight <= 0
                        ) {

                            invalidWeight =
                                true;

                            return;

                        }

                        data.weights[group] =
                            weight;

                        hasWeight =
                            true;

                    }
                );

            if (invalidWeight) {

                showError(
                    'Fish weights must be greater than 0.'
                );

                return null;

            }

            if (!hasWeight) {

                showError(
                    'A fish needs a weight in at least one group.'
                );

                return null;

            }

            data.sellPrice =
                sellPrice;

        }

        if (
            type === 'Bait'
        ) {

            var baitSellPrice =
                document
                    .getElementById(
                        'entryCreatorBaitSellPrice'
                    )
                    .value
                    .trim();

            if (!baitSellPrice) {

                showError(
                    'Please enter the bait sell price.'
                );

                return null;

            }

            data.sellPrice =
                baitSellPrice;

        }

        if (
            type === 'Tool'
        ) {

            var toolBaseCost =
                document
                    .getElementById(
                        'entryCreatorToolBaseCost'
                    )
                    .value
                    .trim();

            if (!toolBaseCost) {

                showError(
                    'Please enter the tool base cost.'
                );

                return null;

            }

            data.baseCost =
                toolBaseCost;

        }

        if (
            type === 'Enchant'
        ) {

            var enchantWeight =
                document
                    .getElementById(
                        'entryCreatorEnchantWeight'
                    )
                    .value
                    .trim();

            if (!enchantWeight) {

                showError(
                    'Please enter the enchant weight.'
                );

                return null;

            }

            var parsedEnchantWeight =
                Number(
                    enchantWeight
                );

            if (
                !isFinite(
                    parsedEnchantWeight
                ) ||
                parsedEnchantWeight <= 0
            ) {

                showError(
                    'Enchant weight must be greater than 0.'
                );

                return null;

            }

            data.enchantWeight =
                parsedEnchantWeight;

        }

        return data;

    }

    function isPNG(file) {

        if (!file) {
            return false;
        }

        var name =
            file.name.toLowerCase();

        var validExtension =
            name.slice(-4) ===
            '.png';

        var validMime =
            (
                !file.type ||
                file.type ===
                'image/png'
            );

        return (
            validExtension &&
            validMime
        );

    }

    function uploadEntryImage(
        api,
        data
    ) {

        var filename =
            makeImageFilename(
                data.type,
                data.name
            );

        if (
            loadedEdit &&
            loadedEdit.image
        ) {

            filename =
                loadedEdit.image;

        }

        var parameters = {

            filename:
                filename,

            comment:
                'Image uploaded for ' +
                data.type +
                ' entry: ' +
                data.name,

            format:
                'json',

            ignorewarnings:
                loadedEdit
                    ? 1
                    : 0

        };

        return new Promise(
            function (
                resolve,
                reject
            ) {

                api.upload(
                    data.file,
                    parameters
                )

                .done(function (response) {

                    if (
                        !response.upload
                    ) {

                        reject(
                            'The image upload returned no result.'
                        );

                        return;

                    }

                    if (
                        response.upload.result ===
                        'Warning'
                    ) {

                        reject(
                            'The PNG could not be uploaded.'
                        );

                        return;

                    }

                    if (
                        response.upload.result !==
                        'Success'
                    ) {

                        reject(
                            'The PNG upload did not complete.'
                        );

                        return;

                    }

                    resolve(
                        response.upload.filename ||
                        filename
                    );

                })

                .fail(function (error) {

                    reject(
                        error
                    );

                });

            }
        );

    }

    function makeImageFilename(
        type,
        name
    ) {

        var safeName =
            name
                .replace(
                    /[\/\\:#<>\[\]|{}]/g,
                    ''
                )
                .replace(
                    /\s+/g,
                    '_'
                )
                .trim();

        return (
            type +
            '_' +
            safeName +
            '.png'
        );

    }

    function saveEntry(
        api,
        data,
        mode
    ) {

        var admin =
            isAdmin();

        var pageName;

        if (
            mode === 'Edit'
        ) {

            if (admin) {

                pageName =
                    loadedEdit.page;

            } else {

                pageName =
                    'Entry_submission:Edit/' +
                    data.type +
                    '/' +
                    data.name;

            }

        } else {

            if (admin) {

                pageName =
                    PAGE_PREFIXES[
                        data.type
                    ] +
                    data.name;

            } else {

                pageName =
                    'Entry_submission:' +
                    data.type +
                    '/' +
                    data.name;

            }

        }

        var pageText =
            buildEntryWikitext(
                data,
                admin,
                mode
            );

        var params = {

            action:
                'edit',

            title:
                pageName,

            text:
                pageText,

            format:
                'json'

        };

        if (
            mode === 'Edit' &&
            admin
        ) {

            params.summary =
                'Updated ' +
                data.type +
                ' entry: ' +
                data.name;

            params.nocreate =
                true;

        } else {

            params.summary =
                mode === 'Edit'
                    ? (
                        'Submitted edit for ' +
                        data.type +
                        ' entry: ' +
                        data.name
                    )
                    : (
                        admin
                            ? 'Published ' +
                              data.type +
                              ' entry: ' +
                              data.name
                            : 'Submitted ' +
                              data.type +
                              ' entry for review: ' +
                              data.name
                    );

            params.createonly =
                true;

        }

        return api
            .postWithToken(
                'csrf',
                params
            )

            .then(function () {

                var message;

                if (
                    mode === 'Edit'
                ) {

                    message =
                        admin
                            ? 'Entry updated successfully!'
                            : 'Your edit was submitted for review.';

                } else {

                    message =
                        admin
                            ? 'Entry published successfully!'
                            : 'Entry submitted successfully and is waiting for approval.';

                }

                return {

                    page:
                        pageName,

                    message:
                        message

                };

            });

    }

    function buildEntryWikitext(
        data,
        live,
        mode
    ) {

        var text =
            '{{EntryData\n' +

            '|type=' +
            safeTemplateValue(
                data.type
            ) +
            '\n' +

            '|name=' +
            safeTemplateValue(
                data.name
            ) +
            '\n' +

            '|image=' +
            safeTemplateValue(
                data.image
            ) +
            '\n' +

            '|rarity=' +
            safeTemplateValue(
                data.rarity
            ) +
            '\n' +

            '|description=' +
            safeTemplateValue(
                data.description
            ) +
            '\n';

        if (
            data.type ===
            'Fish'
        ) {

            text +=
                '|sell_price=' +
                safeTemplateValue(
                    data.sellPrice
                ) +
                '\n';

            FISH_GROUPS.forEach(
                function (group) {

                    var key =
                        group
                            .toLowerCase()
                            .replace(
                                /\s+/g,
                                '_'
                            );

                    text +=
                        '|' +
                        key +
                        '_weight=' +
                        (
                            data.weights[
                                group
                            ] || ''
                        ) +
                        '\n';

                }
            );

        }

        if (
            data.type ===
            'Bait'
        ) {

            text +=
                '|sell_price=' +
                safeTemplateValue(
                    data.sellPrice
                ) +
                '\n';

        }

        if (
            data.type ===
            'Tool'
        ) {

            text +=
                '|base_cost=' +
                safeTemplateValue(
                    data.baseCost
                ) +
                '\n';

        }

        if (
            data.type ===
            'Enchant'
        ) {

            text +=
                '|weight=' +
                safeTemplateValue(
                    data.enchantWeight
                ) +
                '\n';

        }

        if (
            mode === 'Edit' &&
            !live &&
            loadedEdit
        ) {

            text +=
                '|edit_target=' +
                safeTemplateValue(
                    loadedEdit.page
                ) +
                '\n';

        }

        text +=
            '|status=' +
            (
                live
                    ? 'Published'
                    : 'Pending'
            ) +
            '\n';

        text +=
            '}}\n\n';

        if (live) {

            text +=
                '[[Category:' +
                data.type +
                ' Entries]]\n';

            if (
                data.type ===
                'Fish'
            ) {

                Object
                    .keys(
                        data.weights
                    )
                    .forEach(
                        function (group) {

                            text +=
                                '[[Category:' +
                                group +
                                ' Fish]]\n';

                        }
                    );

            }

        } else {

            text +=
                '[[Category:Pending Entry Submissions]]\n';

            if (
                mode === 'Edit'
            ) {

                text +=
                    '[[Category:Pending Entry Edits]]\n';

                text +=
                    '[[Category:Pending ' +
                    data.type +
                    ' Edits]]\n';

            } else {

                text +=
                    '[[Category:Pending ' +
                    data.type +
                    ' Submissions]]\n';

            }

        }

        return text;

    }

    function decodeTemplateValue(
        value
    ) {

        return String(
            value || ''
        )

            .replace(
                /&#124;/g,
                '|'
            )

            .replace(
                /\}&#125;/g,
                '}}'
            );

    }

    function safeTemplateValue(
        value
    ) {

        return String(
            value || ''
        )

            .replace(
                /\|/g,
                '&#124;'
            )

            .replace(
                /\}\}/g,
                '}&#125;'
            );

    }

    function showError(message) {

        var status =
            document.getElementById(
                'entryCreatorStatus'
            );

        status.className =
            'entry-creator-status ' +
            'entry-creator-status-error';

        status.textContent =
            message;

    }

    function showSuccess(
        message,
        pageName
    ) {

        var status =
            document.getElementById(
                'entryCreatorStatus'
            );

        status.className =
            'entry-creator-status ' +
            'entry-creator-status-success';

        var url =
            mw.util.getUrl(
                pageName
            );

        status.innerHTML =
            '✅ ' +
            escapeHtml(message) +
            '<br>' +
            '<a href="' +
            escapeAttribute(url) +
            '">' +
            escapeHtml(pageName) +
            '</a>';

    }

    function getErrorMessage(
        error
    ) {

        var text =
            String(error);

        if (
            text.indexOf(
                'articleexists'
            ) !== -1
        ) {

            return (
                'A submission with that name already exists.'
            );

        }

        if (
            text.indexOf(
                'permissiondenied'
            ) !== -1 ||
            text.indexOf(
                'badaccess'
            ) !== -1
        ) {

            return (
                'Your account does not have permission to perform this action.'
            );

        }

        return (
            'The entry could not be saved. Check the browser console for the full error.'
        );

    }

    function escapeHtml(value) {

        return String(value)

            .replace(
                /&/g,
                '&amp;'
            )

            .replace(
                /</g,
                '&lt;'
            )

            .replace(
                />/g,
                '&gt;'
            )

            .replace(
                /"/g,
                '&quot;'
            )

            .replace(
                /'/g,
                '&#039;'
            );

    }

    function escapeAttribute(
        value
    ) {

        return escapeHtml(
            value
        );

    }

})();

(function () {

    var CREATOR_PAGE = 'Fish_page:sandbox';

    var PAGE_PREFIXES = {
        Fish: 'Fish_page:',
        Bait: 'Bait_page:',
        Tool: 'Tool_page:',
        Enchant: 'Enchant_page:'
    };

    var RARITIES = [
        'Common',
        'Uncommon',
        'Rare',
        'Epic',
        'Legendary',
        'Mythic'
    ];

    var FISH_GROUPS = [
        'Default',
        'Bonus',
        'Main',
        'Research',
        'Prestige',
        'Ascension'
    ];

    var loadedEdit = null;

    $(function () {

        if (
            mw.config.get('wgPageName') !==
            CREATOR_PAGE
        ) {
            return;
        }

        var container =
            document.getElementById('entry-creator') ||
            document.getElementById('fish-entry-creator');

        if (!container) {
            return;
        }

        if (
            container.dataset.loaded ===
            'true'
        ) {
            return;
        }

        container.dataset.loaded =
            'true';

        buildCreator(container);

    });

    function buildCreator(container) {

        var rarityOptions =
            RARITIES.map(function (rarity) {

                return (
                    '<option value="' +
                    escapeAttribute(rarity) +
                    '">' +
                    escapeHtml(rarity) +
                    '</option>'
                );

            }).join('');

        var weightInputs =
            FISH_GROUPS.map(function (group) {

                return (
                    '<div class="entry-creator-weight">' +

                        '<label>' +
                            escapeHtml(group) +
                        '</label>' +

                        '<input ' +
                            'type="number" ' +
                            'min="0" ' +
                            'step="any" ' +
                            'class="entry-creator-weight-input" ' +
                            'data-fish-group="' +
                            escapeAttribute(group) +
                            '" ' +
                            'placeholder="Not in group"' +
                        '>' +

                    '</div>'
                );

            }).join('');

        container.innerHTML = `

            <div class="entry-creator">

                <div class="entry-creator-title">
                    Entry Creator
                </div>

                <div class="entry-creator-row">

                    <label for="entryCreatorType">
                        Entry Type
                    </label>

                    <select id="entryCreatorType">

                        <option value="Fish">
                            Fish
                        </option>

                        <option value="Bait">
                            Bait
                        </option>

                        <option value="Tool">
                            Tool
                        </option>

                        <option value="Enchant">
                            Enchant
                        </option>

                        <option value="Edit">
                            Edit Existing Entry
                        </option>

                    </select>

                </div>

                <div
                    class="entry-creator-type-section"
                    id="entryCreatorEditSection"
                >

                    <div class="entry-creator-section-title">
                        Edit Existing Entry
                    </div>

                    <div class="entry-creator-row">

                        <label for="entryCreatorEditType">
                            Existing Entry Type
                        </label>

                        <select id="entryCreatorEditType">

                            <option value="Fish">
                                Fish
                            </option>

                            <option value="Bait">
                                Bait
                            </option>

                            <option value="Tool">
                                Tool
                            </option>

                            <option value="Enchant">
                                Enchant
                            </option>

                        </select>

                    </div>

                    <div class="entry-creator-row">

                        <label for="entryCreatorEditName">
                            Existing Entry Name
                        </label>

                        <input
                            type="text"
                            id="entryCreatorEditName"
                            placeholder="Example: Cod"
                        >

                    </div>

                    <button
                        type="button"
                        id="entryCreatorLoad"
                    >
                        Load Entry
                    </button>

                    <div
                        id="entryCreatorLoadStatus"
                        class="entry-creator-status"
                    ></div>

                </div>

                <div
                    id="entryCreatorFormFields"
                >

                    <div class="entry-creator-row">

                        <label for="entryCreatorName">
                            Name
                        </label>

                        <input
                            type="text"
                            id="entryCreatorName"
                            placeholder="Example: Cod"
                        >

                    </div>

                    <div class="entry-creator-row">

                        <label for="entryCreatorRarity">
                            Rarity
                        </label>

                        <select id="entryCreatorRarity">
                            ${rarityOptions}
                        </select>

                    </div>

                    <div class="entry-creator-row">

                        <label for="entryCreatorImage">
                            PNG Image
                        </label>

                        <input
                            type="file"
                            id="entryCreatorImage"
                            accept="image/png,.png"
                        >

                    </div>

                    <div
                        class="entry-creator-preview"
                        id="entryCreatorPreview"
                    ></div>

                    <div class="entry-creator-row">

                        <label for="entryCreatorDescription">
                            Description / Lore
                        </label>

                        <textarea
                            id="entryCreatorDescription"
                            placeholder="Enter the description..."
                        ></textarea>

                    </div>

                    <div
                        class="entry-creator-type-section"
                        id="entryCreatorFishSection"
                    >

                        <div class="entry-creator-row">

                            <label for="entryCreatorFishSellPrice">
                                Sell Price
                            </label>

                            <input
                                type="number"
                                id="entryCreatorFishSellPrice"
                                min="0"
                                step="any"
                                placeholder="Example: 5"
                            >

                        </div>

                        <div class="entry-creator-section-title">
                            Fish Weights
                        </div>

                        <div class="entry-creator-help">
                            Leave a group blank if the fish cannot be caught there.
                        </div>

                        <div class="entry-creator-weights">
                            ${weightInputs}
                        </div>

                    </div>

                    <div
                        class="entry-creator-type-section"
                        id="entryCreatorBaitSection"
                    >

                        <div class="entry-creator-row">

                            <label for="entryCreatorBaitSellPrice">
                                Sell Price
                            </label>

                            <input
                                type="number"
                                id="entryCreatorBaitSellPrice"
                                min="0"
                                step="any"
                                placeholder="Example: 10"
                            >

                        </div>

                    </div>

                    <div
                        class="entry-creator-type-section"
                        id="entryCreatorToolSection"
                    >

                        <div class="entry-creator-row">

                            <label for="entryCreatorToolBaseCost">
                                Base Cost
                            </label>

                            <input
                                type="number"
                                id="entryCreatorToolBaseCost"
                                min="0"
                                step="any"
                                placeholder="Example: 500"
                            >

                        </div>

                    </div>

                    <div
                        class="entry-creator-type-section"
                        id="entryCreatorEnchantSection"
                    >

                        <div class="entry-creator-row">

                            <label for="entryCreatorEnchantWeight">
                                Weight
                            </label>

                            <input
                                type="number"
                                id="entryCreatorEnchantWeight"
                                min="0"
                                step="any"
                                placeholder="Example: 100"
                            >

                        </div>

                    </div>

                    <button
                        type="button"
                        id="entryCreatorSubmit"
                    >
                        Submit Entry
                    </button>

                    <div
                        id="entryCreatorStatus"
                        class="entry-creator-status"
                    ></div>

                </div>

            </div>

        `;

        document
            .getElementById('entryCreatorType')
            .addEventListener(
                'change',
                function () {

                    loadedEdit =
                        null;

                    clearForm();

                    updateEntryType();
                    updateSubmitButton();

                }
            );

        document
            .getElementById('entryCreatorImage')
            .addEventListener(
                'change',
                updateImagePreview
            );

        document
            .getElementById('entryCreatorLoad')
            .addEventListener(
                'click',
                loadExistingEntry
            );

        document
            .getElementById('entryCreatorSubmit')
            .addEventListener(
                'click',
                submitEntry
            );

        updateEntryType();
        updateSubmitButton();

    }

    function getCurrentDataType() {

        var creatorType =
            document.getElementById(
                'entryCreatorType'
            ).value;

        if (
            creatorType ===
            'Edit'
        ) {

            return document
                .getElementById(
                    'entryCreatorEditType'
                )
                .value;

        }

        return creatorType;

    }

    function updateEntryType() {

        var creatorType =
            document.getElementById(
                'entryCreatorType'
            ).value;

        var editSection =
            document.getElementById(
                'entryCreatorEditSection'
            );

        var formFields =
            document.getElementById(
                'entryCreatorFormFields'
            );

        if (
            creatorType ===
            'Edit'
        ) {

            editSection.style.display =
                'block';

            formFields.style.display =
                loadedEdit
                    ? 'block'
                    : 'none';

        } else {

            editSection.style.display =
                'none';

            formFields.style.display =
                'block';

        }

        updateSpecificSections();

    }

    function updateSpecificSections() {

        var creatorType =
            document.getElementById(
                'entryCreatorType'
            ).value;

        if (
            creatorType === 'Edit' &&
            !loadedEdit
        ) {

            hideSpecificSections();
            return;

        }

        var type =
            getCurrentDataType();

        document
            .getElementById(
                'entryCreatorFishSection'
            )
            .style.display =
                type === 'Fish'
                    ? 'block'
                    : 'none';

        document
            .getElementById(
                'entryCreatorBaitSection'
            )
            .style.display =
                type === 'Bait'
                    ? 'block'
                    : 'none';

        document
            .getElementById(
                'entryCreatorToolSection'
            )
            .style.display =
                type === 'Tool'
                    ? 'block'
                    : 'none';

        document
            .getElementById(
                'entryCreatorEnchantSection'
            )
            .style.display =
                type === 'Enchant'
                    ? 'block'
                    : 'none';

    }

    function hideSpecificSections() {

        document
            .getElementById(
                'entryCreatorFishSection'
            )
            .style.display =
                'none';

        document
            .getElementById(
                'entryCreatorBaitSection'
            )
            .style.display =
                'none';

        document
            .getElementById(
                'entryCreatorToolSection'
            )
            .style.display =
                'none';

        document
            .getElementById(
                'entryCreatorEnchantSection'
            )
            .style.display =
                'none';

    }

    function loadExistingEntry() {

        var type =
            document.getElementById(
                'entryCreatorEditType'
            ).value;

        var name =
            document.getElementById(
                'entryCreatorEditName'
            ).value.trim();

        var status =
            document.getElementById(
                'entryCreatorLoadStatus'
            );

        if (!name) {

            status.textContent =
                'Please enter the entry name.';

            return;

        }

        var pageName =
            PAGE_PREFIXES[type] +
            name;

        status.textContent =
            'Loading ' +
            pageName +
            '...';

        mw.loader
            .using([
                'mediawiki.api',
                'mediawiki.util'
            ])

            .then(function () {

                var api =
                    new mw.Api();

                return api.get({

                    action:
                        'query',

                    prop:
                        'revisions',

                    titles:
                        pageName,

                    rvprop:
                        'content',

                    rvslots:
                        'main',

                    format:
                        'json',

                    formatversion:
                        2

                });

            })

            .then(function (response) {

                if (
                    !response.query ||
                    !response.query.pages ||
                    !response.query.pages.length
                ) {

                    throw new Error(
                        'Entry not found.'
                    );

                }

                var page =
                    response.query.pages[0];

                if (
                    page.missing
                ) {

                    throw new Error(
                        'Entry not found.'
                    );

                }

                if (
                    !page.revisions ||
                    !page.revisions.length
                ) {

                    throw new Error(
                        'Could not read the entry.'
                    );

                }

                var revision =
                    page.revisions[0];

                var text =
                    '';

                if (
                    revision.slots &&
                    revision.slots.main
                ) {

                    text =
                        revision.slots.main.content ||
                        revision.slots.main['*'] ||
                        '';

                } else {

                    text =
                        revision.content ||
                        revision['*'] ||
                        '';

                }

                var data =
                    parseEntryData(
                        text
                    );

                if (!data) {

                    throw new Error(
                        'This page does not contain an EntryData template.'
                    );

                }

                loadedEdit = {

                    page:
                        pageName,

                    originalName:
                        data.name || name,

                    type:
                        type,

                    image:
                        data.image || '',

                    originalText:
                        text

                };

                populateForm(
                    type,
                    data
                );

                status.textContent =
                    'Entry loaded successfully.';

                document
                    .getElementById(
                        'entryCreatorFormFields'
                    )
                    .style.display =
                        'block';

                updateSpecificSections();
                updateSubmitButton();

            })

            .catch(function (error) {

                loadedEdit =
                    null;

                document
                    .getElementById(
                        'entryCreatorFormFields'
                    )
                    .style.display =
                        'none';

                console.error(
                    'Entry Load Error:',
                    error
                );

                status.textContent =
                    'Could not load that entry.';

            });

    }

    function parseEntryData(text) {

        var match =
            text.match(
                /\{\{\s*EntryData\b([\s\S]*?)\n?\}\}/i
            );

        if (!match) {
            return null;
        }

        var data =
            {};

        var lines =
            match[1].split(
                /\r?\n/
            );

        var currentKey =
            null;

        lines.forEach(function (line) {

            var parameter =
                line.match(
                    /^\s*\|\s*([^=]+?)\s*=\s*(.*)$/
                );

            if (parameter) {

                currentKey =
                    parameter[1]
                        .trim()
                        .toLowerCase();

                data[currentKey] =
                    decodeTemplateValue(
                        parameter[2].trim()
                    );

                return;

            }

            if (
                currentKey &&
                line.trim()
            ) {

                data[currentKey] +=
                    '\n' +
                    line.trim();

            }

        });

        return data;

    }

    function populateForm(
        type,
        data
    ) {

        clearForm();

        document
            .getElementById(
                'entryCreatorName'
            ).value =
                data.name || '';

        document
            .getElementById(
                'entryCreatorRarity'
            ).value =
                RARITIES.indexOf(
                    data.rarity
                ) !== -1
                    ? data.rarity
                    : 'Common';

        document
            .getElementById(
                'entryCreatorDescription'
            ).value =
                data.description || '';

        document
            .getElementById(
                'entryCreatorEditType'
            ).value =
                type;

        var imageNote =
            document.getElementById(
                'entryCreatorImageNote'
            );

        imageNote.textContent =
            data.image
                ? 'Current image: ' +
                  data.image +
                  '. Choose a new PNG only if you want to replace it.'
                : 'No current PNG. Choose a PNG to add one.';

        showExistingImage(
            data.image || ''
        );

        if (
            type === 'Fish'
        ) {

            document
                .getElementById(
                    'entryCreatorFishSellPrice'
                ).value =
                    data.sell_price || '';

            FISH_GROUPS.forEach(
                function (group) {

                    var key =
                        group
                            .toLowerCase()
                            .replace(
                                /\s+/g,
                                '_'
                            ) +
                        '_weight';

                    var input =
                        document.querySelector(
                            '.entry-creator-weight-input[data-fish-group="' +
                            group +
                            '"]'
                        );

                    if (input) {

                        input.value =
                            data[key] || '';

                    }

                }
            );

        }

        if (
            type === 'Bait'
        ) {

            document
                .getElementById(
                    'entryCreatorBaitSellPrice'
                ).value =
                    data.sell_price || '';

        }

        if (
            type === 'Tool'
        ) {

            document
                .getElementById(
                    'entryCreatorToolBaseCost'
                ).value =
                    data.base_cost || '';

        }

        if (
            type === 'Enchant'
        ) {

            document
                .getElementById(
                    'entryCreatorEnchantWeight'
                ).value =
                    data.weight || '';

        }

    }

    function showExistingImage(
        filename
    ) {

        var preview =
            document.getElementById(
                'entryCreatorPreview'
            );

        preview.innerHTML =
            '';

        if (!filename) {
            return;
        }

        var image =
            document.createElement(
                'img'
            );

        image.src =
            mw.util.getUrl(
                'Special:Redirect/file/' +
                filename
            );

        preview.appendChild(
            image
        );

    }

    function clearForm() {

        var ids = [
            'entryCreatorName',
            'entryCreatorDescription',
            'entryCreatorFishSellPrice',
            'entryCreatorBaitSellPrice',
            'entryCreatorToolBaseCost',
            'entryCreatorEnchantWeight'
        ];

        ids.forEach(
            function (id) {

                var element =
                    document.getElementById(
                        id
                    );

                if (element) {

                    element.value =
                        '';

                }

            }
        );

        var rarity =
            document.getElementById(
                'entryCreatorRarity'
            );

        if (rarity) {

            rarity.value =
                'Common';

        }

        document
            .querySelectorAll(
                '.entry-creator-weight-input'
            )
            .forEach(
                function (input) {

                    input.value =
                        '';

                }
            );

        var imageInput =
            document.getElementById(
                'entryCreatorImage'
            );

        if (imageInput) {

            imageInput.value =
                '';

        }

        var preview =
            document.getElementById(
                'entryCreatorPreview'
            );

        if (preview) {

            preview.innerHTML =
                '';

        }

        var status =
            document.getElementById(
                'entryCreatorStatus'
            );

        if (status) {

            status.textContent =
                '';

            status.className =
                'entry-creator-status';

        }

        var imageNote =
            document.getElementById(
                'entryCreatorImageNote'
            );

        if (imageNote) {

            imageNote.textContent =
                'PNG files only.';

        }

    }

    function isAdmin() {

        var groups =
            mw.config.get(
                'wgUserGroups'
            ) || [];

        return (
            groups.indexOf(
                'sysop'
            ) !== -1
        );

    }

    function updateSubmitButton() {

        var button =
            document.getElementById(
                'entryCreatorSubmit'
            );

        if (!button) {
            return;
        }

        var mode =
            document.getElementById(
                'entryCreatorType'
            ).value;

        if (
            mode === 'Edit'
        ) {

            button.textContent =
                isAdmin()
                    ? 'Save Changes'
                    : 'Submit Edit for Review';

        } else {

            button.textContent =
                isAdmin()
                    ? 'Publish Entry'
                    : 'Submit for Review';

        }

    }

    function updateImagePreview() {

        var input =
            document.getElementById(
                'entryCreatorImage'
            );

        var preview =
            document.getElementById(
                'entryCreatorPreview'
            );

        preview.innerHTML =
            '';

        if (
            !input.files ||
            !input.files.length
        ) {

            if (
                loadedEdit &&
                loadedEdit.image
            ) {

                showExistingImage(
                    loadedEdit.image
                );

            }

            return;

        }

        var file =
            input.files[0];

        if (!isPNG(file)) {

            preview.innerHTML =
                '<div class="entry-creator-error">' +
                'PNG files only.' +
                '</div>';

            return;

        }

        var image =
            document.createElement(
                'img'
            );

        var imageUrl =
            URL.createObjectURL(
                file
            );

        image.src =
            imageUrl;

        image.onload =
            function () {

                URL.revokeObjectURL(
                    imageUrl
                );

            };

        preview.appendChild(
            image
        );

    }

    function submitEntry() {

        var status =
            document.getElementById(
                'entryCreatorStatus'
            );

        var button =
            document.getElementById(
                'entryCreatorSubmit'
            );

        status.className =
            'entry-creator-status';

        status.textContent =
            '';

        if (
            !mw.config.get(
                'wgUserName'
            )
        ) {

            showError(
                'You must be logged in to submit an entry.'
            );

            return;

        }

        var mode =
            document.getElementById(
                'entryCreatorType'
            ).value;

        if (
            mode === 'Edit' &&
            !loadedEdit
        ) {

            showError(
                'Load an existing entry first.'
            );

            return;

        }

        var data =
            collectFormData();

        if (!data) {
            return;
        }

        button.disabled =
            true;

        mw.loader
            .using([
                'mediawiki.api',
                'mediawiki.util'
            ])

            .then(function () {

                var api =
                    new mw.Api();

                if (
                    data.file
                ) {

                    status.textContent =
                        'Uploading PNG...';

                    return uploadEntryImage(
                        api,
                        data
                    )

                    .then(
                        function (filename) {

                            data.image =
                                filename;

                            return api;

                        }
                    );

                }

                data.image =
                    loadedEdit
                        ? loadedEdit.image
                        : '';

                return api;

            })

            .then(function (api) {

                status.textContent =
                    mode === 'Edit'
                        ? (
                            isAdmin()
                                ? 'Saving changes...'
                                : 'Creating edit submission...'
                        )
                        : (
                            isAdmin()
                                ? 'Publishing entry...'
                                : 'Creating pending submission...'
                        );

                return saveEntry(
                    api,
                    data,
                    mode
                );

            })

            .then(function (result) {

                button.disabled =
                    false;

                showSuccess(
                    result.message,
                    result.page
                );

            })

            .catch(function (error) {

                button.disabled =
                    false;

                console.error(
                    'Entry Creator Error:',
                    error
                );

                showError(
                    getErrorMessage(
                        error
                    )
                );

            });

    }

    function collectFormData() {

        var mode =
            document.getElementById(
                'entryCreatorType'
            ).value;

        var type =
            getCurrentDataType();

        var name =
            document.getElementById(
                'entryCreatorName'
            ).value.trim();

        var rarity =
            document.getElementById(
                'entryCreatorRarity'
            ).value;

        var description =
            document.getElementById(
                'entryCreatorDescription'
            ).value.trim();

        var imageInput =
            document.getElementById(
                'entryCreatorImage'
            );

        if (!name) {

            showError(
                'Please enter a name.'
            );

            return null;

        }

        if (
            name.indexOf(':') !== -1 ||
            name.indexOf('#') !== -1 ||
            name.indexOf('[') !== -1 ||
            name.indexOf(']') !== -1
        ) {

            showError(
                'The entry name contains characters that cannot be used.'
            );

            return null;

        }

        var file =
            null;

        if (
            imageInput.files &&
            imageInput.files.length
        ) {

            file =
                imageInput.files[0];

            if (!isPNG(file)) {

                showError(
                    'The image must be a PNG file.'
                );

                return null;

            }

        }

        if (
            mode !== 'Edit' &&
            !file
        ) {

            showError(
                'Please upload a PNG image.'
            );

            return null;

        }

        var data = {

            type:
                type,

            name:
                name,

            rarity:
                rarity,

            description:
                description ||
                'No description has been added yet.',

            file:
                file,

            image:
                '',

            weights:
                {},

            sellPrice:
                '',

            baseCost:
                '',

            enchantWeight:
                ''

        };

        if (
            type === 'Fish'
        ) {

            var sellPrice =
                document
                    .getElementById(
                        'entryCreatorFishSellPrice'
                    )
                    .value
                    .trim();

            if (!sellPrice) {

                showError(
                    'Please enter the fish sell price.'
                );

                return null;

            }

            var hasWeight =
                false;

            var invalidWeight =
                false;

            document
                .querySelectorAll(
                    '.entry-creator-weight-input'
                )
                .forEach(
                    function (input) {

                        var group =
                            input.getAttribute(
                                'data-fish-group'
                            );

                        var value =
                            input.value.trim();

                        if (!value) {
                            return;
                        }

                        var weight =
                            Number(value);

                        if (
                            !isFinite(weight) ||
                            weight <= 0
                        ) {

                            invalidWeight =
                                true;

                            return;

                        }

                        data.weights[group] =
                            weight;

                        hasWeight =
                            true;

                    }
                );

            if (invalidWeight) {

                showError(
                    'Fish weights must be greater than 0.'
                );

                return null;

            }

            if (!hasWeight) {

                showError(
                    'A fish needs a weight in at least one group.'
                );

                return null;

            }

            data.sellPrice =
                sellPrice;

        }

        if (
            type === 'Bait'
        ) {

            var baitSellPrice =
                document
                    .getElementById(
                        'entryCreatorBaitSellPrice'
                    )
                    .value
                    .trim();

            if (!baitSellPrice) {

                showError(
                    'Please enter the bait sell price.'
                );

                return null;

            }

            data.sellPrice =
                baitSellPrice;

        }

        if (
            type === 'Tool'
        ) {

            var toolBaseCost =
                document
                    .getElementById(
                        'entryCreatorToolBaseCost'
                    )
                    .value
                    .trim();

            if (!toolBaseCost) {

                showError(
                    'Please enter the tool base cost.'
                );

                return null;

            }

            data.baseCost =
                toolBaseCost;

        }

        if (
            type === 'Enchant'
        ) {

            var enchantWeight =
                document
                    .getElementById(
                        'entryCreatorEnchantWeight'
                    )
                    .value
                    .trim();

            if (!enchantWeight) {

                showError(
                    'Please enter the enchant weight.'
                );

                return null;

            }

            var parsedEnchantWeight =
                Number(
                    enchantWeight
                );

            if (
                !isFinite(
                    parsedEnchantWeight
                ) ||
                parsedEnchantWeight <= 0
            ) {

                showError(
                    'Enchant weight must be greater than 0.'
                );

                return null;

            }

            data.enchantWeight =
                parsedEnchantWeight;

        }

        return data;

    }

    function isPNG(file) {

        if (!file) {
            return false;
        }

        var name =
            file.name.toLowerCase();

        var validExtension =
            name.slice(-4) ===
            '.png';

        var validMime =
            (
                !file.type ||
                file.type ===
                'image/png'
            );

        return (
            validExtension &&
            validMime
        );

    }

    function uploadEntryImage(
        api,
        data
    ) {

        var filename =
            makeImageFilename(
                data.type,
                data.name
            );

        if (
            loadedEdit &&
            loadedEdit.image
        ) {

            filename =
                loadedEdit.image;

        }

        var parameters = {

            filename:
                filename,

            comment:
                'Image uploaded for ' +
                data.type +
                ' entry: ' +
                data.name,

            format:
                'json',

            ignorewarnings:
                loadedEdit
                    ? 1
                    : 0

        };

        return new Promise(
            function (
                resolve,
                reject
            ) {

                api.upload(
                    data.file,
                    parameters
                )

                .done(function (response) {

                    if (
                        !response.upload
                    ) {

                        reject(
                            'The image upload returned no result.'
                        );

                        return;

                    }

                    if (
                        response.upload.result ===
                        'Warning'
                    ) {

                        reject(
                            'The PNG could not be uploaded.'
                        );

                        return;

                    }

                    if (
                        response.upload.result !==
                        'Success'
                    ) {

                        reject(
                            'The PNG upload did not complete.'
                        );

                        return;

                    }

                    resolve(
                        response.upload.filename ||
                        filename
                    );

                })

                .fail(function (error) {

                    reject(
                        error
                    );

                });

            }
        );

    }

    function makeImageFilename(
        type,
        name
    ) {

        var safeName =
            name
                .replace(
                    /[\/\\:#<>\[\]|{}]/g,
                    ''
                )
                .replace(
                    /\s+/g,
                    '_'
                )
                .trim();

        return (
            type +
            '_' +
            safeName +
            '.png'
        );

    }

    function saveEntry(
        api,
        data,
        mode
    ) {

        var admin =
            isAdmin();

        var pageName;

        if (
            mode === 'Edit'
        ) {

            if (admin) {

                pageName =
                    loadedEdit.page;

            } else {

                pageName =
                    'Entry_submission:Edit/' +
                    data.type +
                    '/' +
                    data.name;

            }

        } else {

            if (admin) {

                pageName =
                    PAGE_PREFIXES[
                        data.type
                    ] +
                    data.name;

            } else {

                pageName =
                    'Entry_submission:' +
                    data.type +
                    '/' +
                    data.name;

            }

        }

        var pageText =
            buildEntryWikitext(
                data,
                admin,
                mode
            );

        var params = {

            action:
                'edit',

            title:
                pageName,

            text:
                pageText,

            format:
                'json'

        };

        if (
            mode === 'Edit' &&
            admin
        ) {

            params.summary =
                'Updated ' +
                data.type +
                ' entry: ' +
                data.name;

            params.nocreate =
                true;

        } else {

            params.summary =
                mode === 'Edit'
                    ? (
                        'Submitted edit for ' +
                        data.type +
                        ' entry: ' +
                        data.name
                    )
                    : (
                        admin
                            ? 'Published ' +
                              data.type +
                              ' entry: ' +
                              data.name
                            : 'Submitted ' +
                              data.type +
                              ' entry for review: ' +
                              data.name
                    );

            params.createonly =
                true;

        }

        return api
            .postWithToken(
                'csrf',
                params
            )

            .then(function () {

                var message;

                if (
                    mode === 'Edit'
                ) {

                    message =
                        admin
                            ? 'Entry updated successfully!'
                            : 'Your edit was submitted for review.';

                } else {

                    message =
                        admin
                            ? 'Entry published successfully!'
                            : 'Entry submitted successfully and is waiting for approval.';

                }

                return {

                    page:
                        pageName,

                    message:
                        message

                };

            });

    }

    function buildEntryWikitext(
        data,
        live,
        mode
    ) {

        var text =
            '{{EntryData\n' +

            '|type=' +
            safeTemplateValue(
                data.type
            ) +
            '\n' +

            '|name=' +
            safeTemplateValue(
                data.name
            ) +
            '\n' +

            '|image=' +
            safeTemplateValue(
                data.image
            ) +
            '\n' +

            '|rarity=' +
            safeTemplateValue(
                data.rarity
            ) +
            '\n' +

            '|description=' +
            safeTemplateValue(
                data.description
            ) +
            '\n';

        if (
            data.type ===
            'Fish'
        ) {

            text +=
                '|sell_price=' +
                safeTemplateValue(
                    data.sellPrice
                ) +
                '\n';

            FISH_GROUPS.forEach(
                function (group) {

                    var key =
                        group
                            .toLowerCase()
                            .replace(
                                /\s+/g,
                                '_'
                            );

                    text +=
                        '|' +
                        key +
                        '_weight=' +
                        (
                            data.weights[
                                group
                            ] || ''
                        ) +
                        '\n';

                }
            );

        }

        if (
            data.type ===
            'Bait'
        ) {

            text +=
                '|sell_price=' +
                safeTemplateValue(
                    data.sellPrice
                ) +
                '\n';

        }

        if (
            data.type ===
            'Tool'
        ) {

            text +=
                '|base_cost=' +
                safeTemplateValue(
                    data.baseCost
                ) +
                '\n';

        }

        if (
            data.type ===
            'Enchant'
        ) {

            text +=
                '|weight=' +
                safeTemplateValue(
                    data.enchantWeight
                ) +
                '\n';

        }

        if (
            mode === 'Edit' &&
            !live &&
            loadedEdit
        ) {

            text +=
                '|edit_target=' +
                safeTemplateValue(
                    loadedEdit.page
                ) +
                '\n';

        }

        text +=
            '|status=' +
            (
                live
                    ? 'Published'
                    : 'Pending'
            ) +
            '\n';

        text +=
            '}}\n\n';

        if (live) {

            text +=
                '[[Category:' +
                data.type +
                ' Entries]]\n';

            if (
                data.type ===
                'Fish'
            ) {

                Object
                    .keys(
                        data.weights
                    )
                    .forEach(
                        function (group) {

                            text +=
                                '[[Category:' +
                                group +
                                ' Fish]]\n';

                        }
                    );

            }

        } else {

            text +=
                '[[Category:Pending Entry Submissions]]\n';

            if (
                mode === 'Edit'
            ) {

                text +=
                    '[[Category:Pending Entry Edits]]\n';

                text +=
                    '[[Category:Pending ' +
                    data.type +
                    ' Edits]]\n';

            } else {

                text +=
                    '[[Category:Pending ' +
                    data.type +
                    ' Submissions]]\n';

            }

        }

        return text;

    }

    function decodeTemplateValue(
        value
    ) {

        return String(
            value || ''
        )

            .replace(
                /&#124;/g,
                '|'
            )

            .replace(
                /\}&#125;/g,
                '}}'
            );

    }

    function safeTemplateValue(
        value
    ) {

        return String(
            value || ''
        )

            .replace(
                /\|/g,
                '&#124;'
            )

            .replace(
                /\}\}/g,
                '}&#125;'
            );

    }

    function showError(message) {

        var status =
            document.getElementById(
                'entryCreatorStatus'
            );

        status.className =
            'entry-creator-status ' +
            'entry-creator-status-error';

        status.textContent =
            message;

    }

    function showSuccess(
        message,
        pageName
    ) {

        var status =
            document.getElementById(
                'entryCreatorStatus'
            );

        status.className =
            'entry-creator-status ' +
            'entry-creator-status-success';

        var url =
            mw.util.getUrl(
                pageName
            );

        status.innerHTML =
            '✅ ' +
            escapeHtml(message) +
            '<br>' +
            '<a href="' +
            escapeAttribute(url) +
            '">' +
            escapeHtml(pageName) +
            '</a>';

    }

    function getErrorMessage(
        error
    ) {

        var text =
            String(error);

        if (
            text.indexOf(
                'articleexists'
            ) !== -1
        ) {

            return (
                'A submission with that name already exists.'
            );

        }

        if (
            text.indexOf(
                'permissiondenied'
            ) !== -1 ||
            text.indexOf(
                'badaccess'
            ) !== -1
        ) {

            return (
                'Your account does not have permission to perform this action.'
            );

        }

        return (
            'The entry could not be saved. Check the browser console for the full error.'
        );

    }

    function escapeHtml(value) {

        return String(value)

            .replace(
                /&/g,
                '&amp;'
            )

            .replace(
                /</g,
                '&lt;'
            )

            .replace(
                />/g,
                '&gt;'
            )

            .replace(
                /"/g,
                '&quot;'
            )

            .replace(
                /'/g,
                '&#039;'
            );

    }

    function escapeAttribute(
        value
    ) {

        return escapeHtml(
            value
        );

    }

})();

(function () {

    var CREATOR_PAGE = 'Fish_page:sandbox';

    var PAGE_PREFIXES = {
        Fish: 'Fish_page:',
        Bait: 'Bait_page:',
        Tool: 'Tool_page:',
        Enchant: 'Enchant_page:',
        Location: 'Location_page:'
    };

    var RARITIES = [
        'Common',
        'Uncommon',
        'Rare',
        'Epic',
        'Legendary',
        'Mythic'
    ];

    var DEFAULT_LOCATIONS = [
        'Default',
        'Bonus',
        'Main',
        'Prestige',
        'Ascension'
    ];

    var currentLocations =
        DEFAULT_LOCATIONS.slice();

    var loadedEdit =
        null;

    $(function () {

        if (
            mw.config.get('wgPageName') !==
