                                Bait
                            </option>

                            <option value="Tool">
                                Tool
                            </option>

                            <option value="Enchant">
                                Enchant
                            </option>

                            <option value="Location">
                                Location
                            </option>

                        </select>

                    </div>

                    <div class="entry-creator-row">

                        <label for="entryCreatorEditName">
