        document
            .getElementById(
                'entryCreatorType'
            )
            .addEventListener(
                'change',
                function () {

                    loadedEdit =
                        null;

                    clearForm();

                    updateEntryType();

                    updateSubmitButton();

                    if (
                        document
                            .getElementById(
                                'entryCreatorType'
                            )
                            .value ===
                        'Fish'
                    ) {

                        refreshLocations();

                    }

