        `;

        renderLocationInputs(
            currentLocations
        );

        document
            .getElementById(
                'entryCreatorType'
            )
            .addEventListener(
                'change',
                function () {

                    loadedEdit =
                        null;

                    clearForm();

                    updateEntryType();

                    updateSubmitButton();

                    if (
                        document
                            .getElementById(
                                'entryCreatorType'
                            )
                            .value ===
                        'Fish'
                    ) {

                        refreshLocations();

                    }

                }
            );

        document
            .getElementById(
                'entryCreatorEditType'
            )
            .addEventListener(
                'change',
                function () {

                    loadedEdit =
                        null;

                    document
                        .getElementById(
                            'entryCreatorFormFields'
                        )
                        .style.display =
                            'none';

                    document
                        .getElementById(
                            'entryCreatorLoadStatus'
                        )
                        .textContent =
                            '';

                }
            );

        document
            .getElementById(
                'entryCreatorImage'
            )
            .addEventListener(
