                updateImagePreview
            );

        document
            .getElementById(
                'entryCreatorLoad'
            )
            .addEventListener(
                'click',
                loadExistingEntry
            );

        document
            .getElementById(
                'entryCreatorSubmit'
            )
            .addEventListener(
                'click',
                submitEntry
            );

        updateEntryType();
        updateSubmitButton();

    }

    function refreshLocations() {

        return mw.loader
            .using([
                'mediawiki.api'
            ])
            .then(function () {

                var api =
                    new mw.Api();

                return getAllCategoryMembers(
                    api,
                    'Category:Fish Locations'
                );

            })
            .then(function (titles) {

                var locations =
                    [];

                titles.forEach(
                    function (title) {

                        if (
                            title.indexOf(
                                'Location_page:'
                            ) !== 0
                        ) {
                            return;
                        }

                        var name =
                            title
                                .replace(
                                    /^Location_page:/,
                                    ''
                                )
                                .trim();

                        if (!name) {
                            return;
                        }

                        addUniqueLocation(
                            locations,
                            name
                        );

                    }
                );

                currentLocations =
                    locations;

                renderLocationInputs(
                    currentLocations
                );

                return currentLocations;

            })
            .catch(function (error) {

                console.error(
                    'Location Loader Error:',
                    error
                );

                currentLocations =
                    [];

                renderLocationInputs(
                    currentLocations
                );

                return currentLocations;

            });

    }

    function getAllCategoryMembers(
        api,
        category,
        cmcontinue
    ) {

        var params = {

            action:
                'query',

            list:
                'categorymembers',

            cmtitle:
                category,

            cmlimit:
                'max',

            format:
                'json',

            formatversion:
                2

        };

        if (cmcontinue) {

            params.cmcontinue =
                cmcontinue;

        }

        return api
            .get(params)
            .then(function (response) {

                var titles =
                    [];

                if (
                    response.query &&
                    response.query.categorymembers
                ) {

                    titles =
                        response.query.categorymembers
                            .map(
                                function (page) {

                                    return page.title;

                                }
                            );

                }

                if (
                    response.continue &&
                    response.continue.cmcontinue
                ) {

                    return getAllCategoryMembers(
                        api,
                        category,
                        response.continue.cmcontinue
                    )
                    .then(
                        function (moreTitles) {

                            return titles.concat(
                                moreTitles
                            );

                        }
                    );

                }

                return titles;

            });

    }

    function addUniqueLocation(
        locations,
        name
    ) {

        var exists =
            locations.some(
                function (location) {

                    return (
                        location.toLowerCase() ===
                        name.toLowerCase()
                    );

                }
            );

        if (!exists) {

            locations.push(
                name
            );

        }

    }

    function renderLocationInputs(
        locations
    ) {

        var container =
            document.getElementById(
                'entryCreatorLocationWeights'
            );

        if (!container) {
            return;
        }

        var oldValues =
            {};

        container
            .querySelectorAll(
                '.entry-creator-location-weight'
            )
            .forEach(
                function (input) {

                    var location =
                        input.getAttribute(
                            'data-location-name'
                        );

                    oldValues[
                        location
                    ] =
                        input.value;

                }
            );

        container.innerHTML =
            '';

        if (!locations.length) {

            var empty =
                document.createElement(
                    'div'
                );

            empty.className =
                'entry-creator-help';

            empty.textContent =
                'No locations have been created yet.';

            container.appendChild(
                empty
            );

            return;

        }

        locations.forEach(
            function (location) {

                var wrapper =
                    document.createElement(
                        'div'
                    );

                wrapper.className =
                    'entry-creator-weight';

                var label =
                    document.createElement(
                        'label'
                    );

                label.textContent =
                    location;

                var input =
                    document.createElement(
                        'input'
                    );

                input.type =
                    'number';

                input.min =
                    '0';

                input.step =
                    'any';

                input.placeholder =
                    'Not in location';

                input.className =
                    'entry-creator-location-weight';

                input.setAttribute(
                    'data-location-name',
                    location
                );

                if (
                    Object.prototype
                        .hasOwnProperty.call(
                            oldValues,
                            location
                        )
                ) {

                    input.value =
                        oldValues[
                            location
                        ];

                }

                wrapper.appendChild(
                    label
                );

                wrapper.appendChild(
                    input
                );

                container.appendChild(
                    wrapper
                );

            }
        );

    }

    function getCurrentDataType() {

        var mode =
            document.getElementById(
                'entryCreatorType'
            ).value;

        if (
            mode ===
            'Edit'
        ) {

            return document
                .getElementById(
                    'entryCreatorEditType'
                )
                .value;

        }

        return mode;

    }

    function updateEntryType() {

        var mode =
            document.getElementById(
                'entryCreatorType'
            ).value;

        var editSection =
            document.getElementById(
                'entryCreatorEditSection'
            );

        var formFields =
            document.getElementById(
                'entryCreatorFormFields'
            );

        if (
            mode ===
            'Edit'
        ) {

            editSection.style.display =
                'block';

            formFields.style.display =
                loadedEdit
                    ? 'block'
                    : 'none';

        } else {

            editSection.style.display =
                'none';

            formFields.style.display =
                'block';

        }

        updateSpecificSections();

    }

    function updateSpecificSections() {

        var mode =
            document.getElementById(
                'entryCreatorType'
            ).value;

        if (
            mode === 'Edit' &&
            !loadedEdit
        ) {

            hideSpecificSections();

            return;

        }

        var type =
            getCurrentDataType();

        document
            .getElementById(
                'entryCreatorRarityRow'
            )
            .style.display =
                (
                    type === 'Fish' ||
                    type === 'Bait'
                )
                    ? 'flex'
                    : 'none';

        document
            .getElementById(
                'entryCreatorDescriptionRow'
            )
            .style.display =
                type === 'Location'
                    ? 'none'
                    : 'flex';

        document
            .getElementById(
                'entryCreatorFishSection'
            )
            .style.display =
                type === 'Fish'
                    ? 'block'
                    : 'none';

        document
            .getElementById(
                'entryCreatorToolSection'
            )
            .style.display =
                type === 'Tool'
                    ? 'block'
                    : 'none';

        document
            .getElementById(
                'entryCreatorEnchantSection'
            )
            .style.display =
                type === 'Enchant'
                    ? 'block'
                    : 'none';

    }

    function hideSpecificSections() {

        [
            'entryCreatorFishSection',
            'entryCreatorToolSection',
            'entryCreatorEnchantSection'
        ].forEach(
            function (id) {

                document
                    .getElementById(
                        id
                    )
                    .style.display =
                        'none';

            }
        );

    }

    function loadExistingEntry() {

        var type =
            document.getElementById(
                'entryCreatorEditType'
            ).value;

        var name =
            document.getElementById(
                'entryCreatorEditName'
            ).value.trim();

        var status =
            document.getElementById(
                'entryCreatorLoadStatus'
            );

        if (!name) {

            status.textContent =
                'Please enter the entry name.';

            return;

        }

        var pageName =
            PAGE_PREFIXES[
                type
            ] +
            name;

        status.textContent =
            'Loading ' +
            pageName +
            '...';

        mw.loader
            .using([
                'mediawiki.api',
                'mediawiki.util'
            ])
            .then(function () {

                var api =
                    new mw.Api();

                return api.get({

                    action:
                        'query',

                    prop:
                        'revisions',

                    titles:
                        pageName,

                    rvprop:
                        'content',

                    rvslots:
                        'main',

                    format:
                        'json',

                    formatversion:
                        2

                });

            })
            .then(function (response) {

                if (
                    !response.query ||
                    !response.query.pages ||
                    !response.query.pages.length
                ) {

                    throw new Error(
                        'Entry not found.'
                    );

                }

                var page =
                    response.query.pages[0];

                if (
                    page.missing
                ) {

                    throw new Error(
                        'Entry not found.'
                    );

                }

                if (
                    !page.revisions ||
                    !page.revisions.length
                ) {

                    throw new Error(
                        'Could not read entry.'
                    );

                }

                var revision =
                    page.revisions[0];

                var text =
                    '';

                if (
                    revision.slots &&
                    revision.slots.main
                ) {

                    text =
                        revision.slots.main.content ||
                        revision.slots.main['*'] ||
                        '';

                } else {

                    text =
                        revision.content ||
                        revision['*'] ||
                        '';

                }

                var data =
                    parseEntryData(
                        text
                    );

                if (!data) {

                    throw new Error(
                        'EntryData not found.'
                    );

                }

                loadedEdit = {

                    page:
                        pageName,

                    originalName:
                        data.name ||
                        name,

                    type:
                        type,

                    image:
                        data.image ||
                        ''

                };

                if (
                    type ===
                    'Fish'
                ) {

                    return refreshLocations()
                        .then(
                            function () {

                                populateForm(
                                    type,
                                    data
                                );

                            }
                        );

                }

                populateForm(
                    type,
                    data
                );

            })
            .then(function () {

                if (!loadedEdit) {
                    return;
                }

                status.textContent =
                    'Entry loaded successfully.';

                document
                    .getElementById(
                        'entryCreatorFormFields'
                    )
                    .style.display =
                        'block';

                document
                    .getElementById(
                        'entryCreatorName'
                    )
                    .readOnly =
                        true;

                updateSpecificSections();

                updateSubmitButton();

            })
            .catch(function (error) {

                loadedEdit =
                    null;

                console.error(
                    'Entry Load Error:',
                    error
                );

                status.textContent =
                    'Could not load that entry.';

                document
                    .getElementById(
                        'entryCreatorFormFields'
                    )
                    .style.display =
                        'none';

            });

    }

    function parseEntryData(text) {

        var match =
            text.match(
                /\{\{\s*EntryData\b([\s\S]*?)\n?\}\}/i
            );

        if (!match) {
            return null;
        }

        var data =
            {};

        var currentKey =
            null;

        match[1]
            .split(
                /\r?\n/
            )
            .forEach(
                function (line) {

                    var parameter =
                        line.match(
                            /^\s*\|\s*([^=]+?)\s*=\s*(.*)$/
                        );

                    if (parameter) {

                        currentKey =
                            parameter[1]
                                .trim()
                                .toLowerCase();

                        data[
                            currentKey
                        ] =
                            decodeTemplateValue(
                                parameter[2]
                                    .trim()
                            );

                        return;

                    }

                    if (
                        currentKey &&
                        line.trim()
                    ) {

                        data[
                            currentKey
                        ] +=
                            '\n' +
                            line.trim();

                    }

                }
            );

        return data;

    }

    function parseLocationWeights(
        data
    ) {

        var weights =
            {};

        if (
            data.location_weights
        ) {

            data.location_weights
                .split(';')
                .forEach(
                    function (entry) {

                        entry =
                            entry.trim();

                        if (!entry) {
                            return;
                        }

                        var separator =
                            entry.lastIndexOf(
                                ':'
                            );

                        if (
                            separator ===
                            -1
                        ) {
                            return;
                        }

                        var location =
                            entry
                                .slice(
                                    0,
                                    separator
                                )
                                .trim();

                        var weight =
                            entry
                                .slice(
                                    separator + 1
                                )
                                .trim();

                        if (
                            location &&
                            weight
                        ) {

                            weights[
                                location
                            ] =
                                weight;

                            addUniqueLocation(
                                currentLocations,
                                location
                            );

                        }

                    }
                );

        }

        return weights;

    }

    function populateForm(
        type,
        data
    ) {

        clearForm();

        document
            .getElementById(
                'entryCreatorName'
            )
            .value =
                data.name ||
                '';

        if (
            type === 'Fish' ||
            type === 'Bait'
        ) {

            document
                .getElementById(
                    'entryCreatorRarity'
                )
                .value =
                    RARITIES.indexOf(
                        data.rarity
                    ) !== -1
                        ? data.rarity
                        : 'Common';

        }

        if (
            type !==
            'Location'
        ) {

            document
                .getElementById(
                    'entryCreatorDescription'
                )
                .value =
                    data.description ||
                    '';

        }

        var imageNote =
            document.getElementById(
                'entryCreatorImageNote'
            );

        imageNote.textContent =
            data.image
                ?
            (
                'Current image: ' +
                data.image +
                '. Choose a new PNG only if you want to replace it.'
            )
                :
            'No current PNG. Choose a PNG to add one.';

        showExistingImage(
            data.image ||
            ''
        );

        if (
            type ===
            'Fish'
        ) {

            document
                .getElementById(
                    'entryCreatorFishBaseSellPrice'
                )
                .value =
                    data.base_sell_price ||
                    '';

            var weights =
                parseLocationWeights(
                    data
                );

            renderLocationInputs(
                currentLocations
            );

            Object.keys(
                weights
            ).forEach(
                function (location) {

                    var input =
                        findLocationInput(
                            location
                        );

                    if (input) {

                        input.value =
                            weights[
                                location
                            ];

                    }

                }
            );

        }

        if (
            type ===
            'Tool'
        ) {

            document
                .getElementById(
                    'entryCreatorToolBaseCost'
                )
                .value =
                    data.base_cost ||
                    '';

        }

        if (
            type ===
            'Enchant'
        ) {

            document
                .getElementById(
                    'entryCreatorEnchantWeight'
                )
                .value =
                    data.weight ||
                    '';

        }

    }

    function findLocationInput(
        location
    ) {

        var inputs =
            document.querySelectorAll(
                '.entry-creator-location-weight'
            );

        for (
            var i = 0;
            i < inputs.length;
            i++
        ) {

            if (
                inputs[
                    i
                ]
                    .getAttribute(
                        'data-location-name'
                    )
                    .toLowerCase() ===
                location.toLowerCase()
            ) {

                return inputs[
                    i
                ];

            }

        }

        return null;

    }

    function showExistingImage(
        filename
    ) {

        var preview =
            document.getElementById(
                'entryCreatorPreview'
            );

        preview.innerHTML =
            '';

        if (!filename) {
            return;
        }

        var image =
            document.createElement(
                'img'
            );

        image.src =
            mw.util.getUrl(
                'Special:Redirect/file/' +
                filename
            );

        preview.appendChild(
            image
        );

    }

    function clearForm() {

        [
            'entryCreatorName',
            'entryCreatorDescription',
            'entryCreatorFishBaseSellPrice',
            'entryCreatorToolBaseCost',
            'entryCreatorEnchantWeight'
        ].forEach(
            function (id) {

                var element =
                    document.getElementById(
                        id
                    );

                if (element) {

                    element.value =
                        '';

                }

            }
        );

        document
            .querySelectorAll(
                '.entry-creator-location-weight'
            )
            .forEach(
                function (input) {

                    input.value =
                        '';

                }
            );

        var nameInput =
            document.getElementById(
                'entryCreatorName'
            );

        if (nameInput) {

            nameInput.readOnly =
                false;

        }

        var rarity =
            document.getElementById(
                'entryCreatorRarity'
            );

        if (rarity) {

            rarity.value =
                'Common';

        }

        var imageInput =
            document.getElementById(
                'entryCreatorImage'
            );

        if (imageInput) {

            imageInput.value =
                '';

        }

        var preview =
            document.getElementById(
                'entryCreatorPreview'
            );

        if (preview) {

            preview.innerHTML =
                '';

        }

        var imageNote =
            document.getElementById(
                'entryCreatorImageNote'
            );

        if (imageNote) {

            imageNote.textContent =
                'PNG files only.';

        }

        var status =
            document.getElementById(
                'entryCreatorStatus'
            );

        if (status) {

            status.textContent =
                '';

            status.className =
                'entry-creator-status';

        }

    }

    function isAdmin() {

        var groups =
            mw.config.get(
                'wgUserGroups'
            ) || [];

        return (
            groups.indexOf(
                'sysop'
            ) !== -1
        );

    }

    function updateSubmitButton() {

        var button =
            document.getElementById(
                'entryCreatorSubmit'
            );

        if (!button) {
            return;
        }

        var mode =
            document.getElementById(
                'entryCreatorType'
            ).value;

        if (
            mode ===
            'Edit'
        ) {

            button.textContent =
                isAdmin()
                    ? 'Save Changes'
                    : 'Submit Edit for Review';

        } else {

            button.textContent =
                isAdmin()
                    ? 'Publish Entry'
                    : 'Submit for Review';

        }

    }

    function updateImagePreview() {

        var input =
            document.getElementById(
                'entryCreatorImage'
            );

        var preview =
            document.getElementById(
                'entryCreatorPreview'
            );

        preview.innerHTML =
            '';

        if (
            !input.files ||
            !input.files.length
        ) {

            if (
                loadedEdit &&
                loadedEdit.image
            ) {

                showExistingImage(
                    loadedEdit.image
                );

            }

            return;

        }

        var file =
            input.files[0];

        if (!isPNG(file)) {

            preview.innerHTML =
                '<div class="entry-creator-error">' +
                'PNG files only.' +
                '</div>';

            return;

        }

        var image =
            document.createElement(
                'img'
            );

        var imageUrl =
            URL.createObjectURL(
                file
            );

        image.src =
            imageUrl;

        image.onload =
            function () {

                URL.revokeObjectURL(
                    imageUrl
                );

            };

        preview.appendChild(
            image
        );

    }

    function submitEntry() {

        var status =
            document.getElementById(
                'entryCreatorStatus'
            );

        var button =
            document.getElementById(
                'entryCreatorSubmit'
            );

        status.className =
            'entry-creator-status';

        status.textContent =
            '';

        if (
            !mw.config.get(
                'wgUserName'
            )
        ) {

            showError(
                'You must be logged in to submit an entry.'
            );

            return;

        }

        var mode =
            document.getElementById(
                'entryCreatorType'
            ).value;

        if (
            mode === 'Edit' &&
            !loadedEdit
        ) {

            showError(
                'Load an existing entry first.'
            );

            return;

        }

        var data =
            collectFormData();

        if (!data) {
            return;
        }

        button.disabled =
            true;

        mw.loader
            .using([
                'mediawiki.api',
                'mediawiki.util'
            ])
            .then(function () {

                var api =
                    new mw.Api();

                if (
                    data.file
                ) {

                    status.textContent =
                        'Uploading PNG...';

                    return uploadEntryImage(
                        api,
                        data,
                        mode
                    )
                    .then(
                        function (filename) {

                            data.image =
                                filename;

                            return api;

                        }
                    );

                }

                data.image =
                    loadedEdit
                        ? loadedEdit.image
                        : '';

                return api;

            })
            .then(function (api) {

                status.textContent =
                    mode ===
                    'Edit'
                        ?
                    (
                        isAdmin()
                            ? 'Saving changes...'
                            : 'Creating edit submission...'
                    )
                        :
                    (
                        isAdmin()
                            ? 'Publishing entry...'
                            : 'Creating pending submission...'
                    );

                return saveEntry(
                    api,
                    data,
                    mode
                );

            })
            .then(function (result) {

                button.disabled =
                    false;

                showSuccess(
                    result.message,
                    result.page
                );

                if (
                    data.type ===
                    'Location' &&
                    isAdmin()
                ) {

                    refreshLocations();

                }

            })
            .catch(function (error) {

                button.disabled =
                    false;

                console.error(
                    'Entry Creator Error:',
                    error
                );

                showError(
                    getErrorMessage(
                        error
                    )
                );

            });

    }

    function collectFormData() {

        var mode =
            document.getElementById(
                'entryCreatorType'
            ).value;

        var type =
            getCurrentDataType();

        var name =
            document.getElementById(
                'entryCreatorName'
            ).value.trim();

        var description =
            document.getElementById(
                'entryCreatorDescription'
            ).value.trim();

        var imageInput =
            document.getElementById(
                'entryCreatorImage'
            );

        if (!name) {

            showError(
                'Please enter a name.'
            );

            return null;

        }

        if (
            name.indexOf(':') !== -1 ||
            name.indexOf('#') !== -1 ||
            name.indexOf('[') !== -1 ||
            name.indexOf(']') !== -1 ||
            name.indexOf('|') !== -1 ||
            name.indexOf('{') !== -1 ||
            name.indexOf('}') !== -1 ||
            name.indexOf(';') !== -1
        ) {

            showError(
                'The entry name contains characters that cannot be used.'
            );

            return null;

        }

        var file =
            null;

        if (
            imageInput.files &&
            imageInput.files.length
        ) {

            file =
                imageInput.files[0];

            if (!isPNG(file)) {

                showError(
                    'The image must be a PNG file.'
                );

                return null;

            }

        }

        if (
            mode !==
            'Edit' &&
            !file
        ) {

            showError(
                'Please upload a PNG image.'
            );

            return null;

        }

        var data = {

            type:
                type,

            name:
                name,

            rarity:
                (
                    type === 'Fish' ||
                    type === 'Bait'
                )
                    ?
                document
                    .getElementById(
                        'entryCreatorRarity'
                    )
                    .value
                    :
                '',

            description:
                type ===
                'Location'
                    ?
                ''
                    :
                (
                    description ||
                    'No description has been added yet.'
                ),

            file:
                file,

            image:
                '',

            weights:
                {},

            baseSellPrice:
                '',

            baseCost:
                '',

            enchantWeight:
                ''

        };

        if (
            type ===
            'Fish'
        ) {

            var baseSellPrice =
                document
                    .getElementById(
                        'entryCreatorFishBaseSellPrice'
                    )
                    .value
                    .trim();

            if (!baseSellPrice) {

                showError(
                    'Please enter the fish base sell price.'
                );

                return null;

            }

            var parsedBaseSellPrice =
                Number(
                    baseSellPrice
                );

            if (
                !isFinite(
                    parsedBaseSellPrice
                ) ||
                parsedBaseSellPrice < 0
            ) {

                showError(
                    'Base sell price must be 0 or greater.'
                );

                return null;

            }

            if (
                !currentLocations.length
            ) {

                showError(
                    'No fish locations have been created yet.'
                );

                return null;

            }

            var hasWeight =
                false;

            var invalidWeight =
                false;

            document
                .querySelectorAll(
                    '.entry-creator-location-weight'
                )
                .forEach(
                    function (input) {

                        var location =
                            input.getAttribute(
                                'data-location-name'
                            );

                        var value =
                            input.value.trim();

                        if (!value) {
                            return;
                        }

                        var weight =
                            Number(
                                value
                            );

                        if (
                            !isFinite(
                                weight
                            ) ||
                            weight <= 0
                        ) {

                            invalidWeight =
                                true;

                            return;

                        }

                        data.weights[
                            location
                        ] =
                            weight;

                        hasWeight =
                            true;

                    }
                );

            if (
                invalidWeight
            ) {

                showError(
                    'Fish weights must be greater than 0.'
                );

                return null;

            }

            if (
                !hasWeight
            ) {

                showError(
                    'A fish needs a weight in at least one location.'
                );

                return null;

            }

            data.baseSellPrice =
                parsedBaseSellPrice;

        }

        if (
            type ===
            'Tool'
        ) {

            var toolBaseCost =
                document
                    .getElementById(
                        'entryCreatorToolBaseCost'
                    )
                    .value
                    .trim();

            if (!toolBaseCost) {

                showError(
                    'Please enter the tool base cost.'
                );

                return null;

            }

            var parsedBaseCost =
                Number(
                    toolBaseCost
                );

            if (
                !isFinite(
                    parsedBaseCost
                ) ||
                parsedBaseCost < 0
            ) {

                showError(
                    'Base cost must be 0 or greater.'
                );

                return null;

            }

            data.baseCost =
                parsedBaseCost;

        }

        if (
            type ===
            'Enchant'
        ) {

            var enchantWeight =
                document
                    .getElementById(
                        'entryCreatorEnchantWeight'
                    )
                    .value
                    .trim();

            if (!enchantWeight) {

                showError(
                    'Please enter the enchant weight.'
                );

                return null;

            }

            var parsedEnchantWeight =
                Number(
                    enchantWeight
                );

            if (
                !isFinite(
                    parsedEnchantWeight
                ) ||
                parsedEnchantWeight <= 0
            ) {

                showError(
                    'Enchant weight must be greater than 0.'
                );

                return null;

            }

            data.enchantWeight =
                parsedEnchantWeight;

        }

        return data;

    }

    function isPNG(file) {

        if (!file) {
            return false;
        }

        var name =
            file.name.toLowerCase();

        var validExtension =
            name.slice(
                -4
            ) ===
            '.png';

        var validMime =
            (
                !file.type ||
                file.type ===
                'image/png'
            );

        return (
            validExtension &&
            validMime
        );

    }

    function uploadEntryImage(
        api,
        data,
        mode
    ) {

        var filename;

        var admin =
            isAdmin();

        if (
            mode === 'Edit' &&
            !admin
        ) {

            filename =
                'Pending_Edit_' +

                cleanFilenamePart(
                    mw.config.get(
                        'wgUserName'
                    ) ||
                    'User'
                ) +

                '_' +

                cleanFilenamePart(
                    data.type
                ) +

                '_' +

                cleanFilenamePart(
                    data.name
                ) +

                '_' +

                Date.now() +

                '.png';

        } else if (
            mode === 'Edit' &&
            admin &&
            loadedEdit &&
            loadedEdit.image
        ) {

            filename =
                loadedEdit.image;

        } else if (
            !admin
        ) {

            filename =
                'Pending_' +

                cleanFilenamePart(
                    data.type
                ) +

                '_' +

                cleanFilenamePart(
                    data.name
                ) +

                '_' +

                cleanFilenamePart(
                    mw.config.get(
                        'wgUserName'
                    ) ||
                    'User'
                ) +

                '_' +

                Date.now() +

                '.png';

        } else {

            filename =
                makeImageFilename(
                    data.type,
                    data.name
                );

        }

        var parameters = {

            filename:
                filename,

            comment:
                'Image uploaded for ' +
                data.type +
                ' entry: ' +
                data.name,

            format:
                'json',

            ignorewarnings:
                (
                    mode === 'Edit' &&
                    admin
                )
                    ? 1
                    : 0

        };

        return new Promise(
            function (
                resolve,
                reject
            ) {

                api.upload(
                    data.file,
                    parameters
                )

                .done(
                    function (response) {

                        if (
                            !response.upload
                        ) {

                            reject(
                                'The image upload returned no result.'
                            );

                            return;

                        }

                        if (
                            response.upload.result ===
                            'Warning'
                        ) {

                            console.warn(
                                'Upload warning:',
                                response.upload.warnings
                            );

                            reject(
                                'That PNG could not be uploaded. The file may already exist.'
                            );

                            return;

                        }

                        if (
                            response.upload.result !==
                            'Success'
                        ) {

                            reject(
                                'The PNG upload did not complete.'
                            );

                            return;

                        }

                        resolve(
                            response.upload.filename ||
                            filename
                        );

                    }
                )

                .fail(
                    function (error) {

                        reject(
                            error
                        );

                    }
                );

            }
        );

    }

    function cleanFilenamePart(
        value
    ) {

        return String(
            value
        )
            .replace(
                /[\/\\:#<>\[\]|{}]/g,
                ''
            )
            .replace(
                /\s+/g,
                '_'
            )
            .trim();

    }

    function makeImageFilename(
        type,
        name
    ) {

        return (
            cleanFilenamePart(
                type
            ) +
            '_' +
            cleanFilenamePart(
                name
            ) +
            '.png'
        );

    }

    function saveEntry(
        api,
        data,
        mode
    ) {

        var admin =
            isAdmin();

        var pageName;

        if (
            mode ===
            'Edit'
        ) {

            if (
                admin
            ) {

                pageName =
                    loadedEdit.page;

            } else {

                pageName =
                    'Entry_submission:Edit/' +
                    data.type +
                    '/' +
                    data.name;

            }

        } else {

            if (
                admin
            ) {

                pageName =
                    PAGE_PREFIXES[
                        data.type
                    ] +
                    data.name;

            } else {

                pageName =
                    'Entry_submission:' +
                    data.type +
                    '/' +
                    data.name;

            }

        }

        var pageText =
            buildEntryWikitext(
                data,
                admin,
                mode
            );

        var params = {

            action:
                'edit',

            title:
                pageName,

            text:
                pageText,

            format:
                'json'

        };

        if (
            mode === 'Edit' &&
            admin
        ) {

            params.summary =
                'Updated ' +
                data.type +
                ' entry: ' +
                data.name;

            params.nocreate =
                true;

        } else {

            params.summary =
                mode ===
                'Edit'
                    ?
                (
                    'Submitted edit for ' +
                    data.type +
                    ' entry: ' +
                    data.name
                )
                    :
                (
                    admin
                        ?
                    (
                        'Published ' +
                        data.type +
                        ' entry: ' +
                        data.name
                    )
                        :
                    (
                        'Submitted ' +
                        data.type +
                        ' entry for review: ' +
                        data.name
                    )
                );

            params.createonly =
                true;

        }

        return api
            .postWithToken(
                'csrf',
                params
            )
            .then(
                function () {

                    return {

                        page:
                            pageName,

                        message:
                            mode ===
                            'Edit'
                                ?
                            (
                                admin
                                    ?
                                'Entry updated successfully!'
                                    :
                                'Your edit was submitted for review.'
                            )
                                :
                            (
                                admin
                                    ?
                                'Entry published successfully!'
                                    :
                                'Entry submitted successfully and is waiting for approval.'
                            )

                    };

                }
            );

    }

    function buildLocationWeightsString(
        weights
    ) {

        return Object.keys(
            weights
        )
            .map(
                function (location) {

                    return (
                        location +
                        ':' +
                        weights[
                            location
                        ]
                    );

                }
            )
            .join(
                ';'
            );

    }

    function buildEntryWikitext(
        data,
        live,
        mode
    ) {

        var text =
            '{{EntryData\n' +

            '|type=' +
            safeTemplateValue(
                data.type
            ) +
            '\n' +

            '|name=' +
            safeTemplateValue(
                data.name
            ) +
            '\n' +

            '|image=' +
            safeTemplateValue(
                data.image
            ) +
            '\n';

        if (
            data.type === 'Fish' ||
            data.type === 'Bait'
        ) {

            text +=
                '|rarity=' +
                safeTemplateValue(
                    data.rarity
                ) +
                '\n';

        }

        if (
            data.type !==
            'Location'
        ) {

            text +=
                '|description=' +
                safeTemplateValue(
                    data.description
                ) +
                '\n';

        }

        if (
            data.type ===
            'Fish'
        ) {

            text +=
                '|base_sell_price=' +
                safeTemplateValue(
                    data.baseSellPrice
                ) +
                '\n';

            text +=
                '|location_weights=' +
                safeTemplateValue(
                    buildLocationWeightsString(
                        data.weights
                    )
                ) +
                '\n';

        }

        if (
            data.type ===
            'Tool'
        ) {

            text +=
                '|base_cost=' +
                safeTemplateValue(
                    data.baseCost
                ) +
                '\n';

        }

        if (
            data.type ===
            'Enchant'
        ) {

            text +=
                '|weight=' +
                safeTemplateValue(
                    data.enchantWeight
                ) +
                '\n';

        }

        if (
            mode === 'Edit' &&
            !live &&
            loadedEdit
        ) {

            text +=
                '|edit_target=' +
                safeTemplateValue(
                    loadedEdit.page
                ) +
                '\n';

        }

        text +=
            '|status=' +
            (
                live
                    ?
                'Published'
                    :
                'Pending'
            ) +
            '\n';

        text +=
            '}}\n\n';

        if (
            live
        ) {

            text +=
                '[[Category:' +
                data.type +
                ' Entries]]\n';

            if (
                data.type ===
                'Fish'
            ) {

                Object.keys(
                    data.weights
                )
                .forEach(
                    function (
                        location
                    ) {

                        text +=
                            '[[Category:' +
                            safeCategoryName(
                                location
                            ) +
                            ' Fish]]\n';

                    }
                );

            }

            if (
                data.type ===
                'Location'
            ) {

                text +=
                    '[[Category:Fish Locations]]\n';

            }

        } else {

            text +=
                '[[Category:Pending Entry Submissions]]\n';

            if (
                mode ===
                'Edit'
            ) {

                text +=
                    '[[Category:Pending Entry Edits]]\n';

                text +=
                    '[[Category:Pending ' +
                    data.type +
                    ' Edits]]\n';

            } else {

                text +=
                    '[[Category:Pending ' +
                    data.type +
                    ' Submissions]]\n';

            }

        }

        return text;

    }

    function safeCategoryName(
        value
    ) {

        return String(
            value ||
            ''
        )
            .replace(
                /[\[\]{}|<>#]/g,
                ''
            )
            .trim();

    }

    function decodeTemplateValue(
        value
    ) {

        return String(
            value ||
            ''
        )
            .replace(
                /&#124;/g,
                '|'
            )
            .replace(
                /\}&#125;/g,
                '}}'
            );

    }

    function safeTemplateValue(
        value
    ) {

        return String(
            value ||
            ''
        )
            .replace(
                /\|/g,
                '&#124;'
            )
            .replace(
                /\}\}/g,
                '}&#125;'
            );

    }

    function showError(
        message
    ) {

        var status =
            document.getElementById(
                'entryCreatorStatus'
            );

        status.className =
            'entry-creator-status ' +
            'entry-creator-status-error';

        status.textContent =
            message;

    }

    function showSuccess(
        message,
        pageName
    ) {

        var status =
            document.getElementById(
                'entryCreatorStatus'
            );

        status.className =
            'entry-creator-status ' +
            'entry-creator-status-success';

        var url =
            mw.util.getUrl(
                pageName
            );

        status.innerHTML =
            '✅ ' +
            escapeHtml(
                message
            ) +
            '<br>' +
            '<a href="' +
            escapeAttribute(
                url
            ) +
            '">' +
            escapeHtml(
                pageName
            ) +
            '</a>';

    }

    function getErrorMessage(
        error
    ) {

        var text =
            String(
                error
            );

        if (
            text.indexOf(
                'articleexists'
            ) !==
            -1
        ) {

            return (
                'A submission or entry with that name already exists.'
            );

        }

        if (
            text.indexOf(
                'permissiondenied'
            ) !==
            -1 ||
            text.indexOf(
                'badaccess'
            ) !==
            -1
        ) {

            return (
                'Your account does not have permission to perform this action.'
            );

        }

        return (
            'The entry could not be saved. Check the browser console for the full error.'
        );

    }

    function escapeHtml(
        value
    ) {

        return String(
            value
        )
            .replace(
                /&/g,
                '&amp;'
            )
            .replace(
                /</g,
                '&lt;'
            )
            .replace(
                />/g,
                '&gt;'
            )
            .replace(
                /"/g,
                '&quot;'
            )
            .replace(
                /'/g,
                '&#039;'
            );

    }

    function escapeAttribute(
        value
    ) {

        return escapeHtml(
            value
        );

    }

})();

(function () {

