    function normalizePageName(
        value
    ) {

        return String(
            value ||
            ''
        )
            .replace(
                /_/g,
                ' '
            )
            .trim()
            .toLowerCase();

    }

    function getEntryNameFromTitle(
        type,
        title
    ) {

        var cleanTitle =
            String(
                title ||
                ''
            ).replace(
                /_/g,
                ' '
            );

        var prefix =
            String(
                PAGE_PREFIXES[
                    type
                ] ||
                ''
            ).replace(
                /_/g,
                ' '
            );

        if (
            cleanTitle
                .toLowerCase()
                .indexOf(
                    prefix.toLowerCase()
                ) !==
            0
        ) {

            return '';

        }

        return cleanTitle
            .slice(
                prefix.length
            )
            .trim();

    }

    function resetEditSelection() {

        currentEditEntries =
            [];

        var search =
            document.getElementById(
                'entryCreatorEditSearch'
            );

        var name =
            document.getElementById(
                'entryCreatorEditName'
            );

        var page =
            document.getElementById(
                'entryCreatorEditPage'
            );

        var selected =
            document.getElementById(
                'entryCreatorEditSelected'
            );

        if (
            search
        ) {

            search.value =
                '';

        }

        if (
            name
        ) {

            name.value =
                '';

        }

        if (
            page
        ) {

            page.value =
                '';

        }

        if (
            selected
        ) {

            selected.textContent =
                '';

        }

    }

    function refreshEditEntries() {

        var type =
            document
                .getElementById(
                    'entryCreatorEditType'
                )
                .value;

        var list =
            document
                .getElementById(
                    'entryCreatorEditList'
                );

        currentEditEntries =
            [];

        list.innerHTML =
            '<div class="entry-creator-help">' +
            'Loading entries...' +
            '</div>';

        return loadMediaWikiModules()
            .then(
                function () {

                    var api =
                        new mw.Api();

                    return getAllCategoryMembers(
                        api,
                        ENTRY_CATEGORIES[
                            type
                        ]
                    );

                }
            )
            .then(
                function (titles) {

                    currentEditEntries =
                        [];

                    titles.forEach(
                        function (title) {

                            var name =
                                getEntryNameFromTitle(
                                    type,
                                    title
                                );

                            if (
                                !name
                            ) {
                                return;
                            }

                            currentEditEntries.push({

                                name:
                                    name,

                                title:
                                    title

                            });

                        }
                    );

                    currentEditEntries.sort(
                        function (
                            a,
                            b
                        ) {

                            return a.name.localeCompare(
                                b.name,
                                undefined,
                                {
                                    sensitivity:
                                        'base'
                                }
                            );

                        }
                    );

                    renderEditEntryList(
                        ''
                    );

                }
            )
            .catch(
                function (error) {

                    console.error(
                        'Edit Entry List Error:',
                        error
                    );

                    list.innerHTML =
                        '<div class="entry-creator-error">' +
                        escapeHtml(
                            formatError(
                                error
                            )
                        ) +
                        '</div>';

                }
            );

    }

    function renderEditEntryList(
        search
    ) {

        var list =
            document.getElementById(
                'entryCreatorEditList'
            );

        if (
            !list
        ) {
            return;
        }

        var selectedPage =
            document
                .getElementById(
                    'entryCreatorEditPage'
                )
                .value;

        search =
            String(
                search ||
                ''
            )
                .trim()
                .toLowerCase();

        var filtered =
            currentEditEntries.filter(
                function (entry) {

                    if (
                        !search
                    ) {
                        return true;
                    }

                    return (
                        entry.name
                            .toLowerCase()
                            .indexOf(
                                search
                            ) !==
                        -1
                    );

                }
            );

        list.innerHTML =
            '';

        if (
            !currentEditEntries.length
        ) {

            var empty =
                document.createElement(
                    'div'
                );

            empty.className =
                'entry-creator-help';

            empty.textContent =
                'No published entries were found for this type.';

            list.appendChild(
                empty
            );

            return;

        }

        if (
            !filtered.length
        ) {

            var noResults =
                document.createElement(
                    'div'
                );

            noResults.className =
                'entry-creator-help';

            noResults.textContent =
                'No matching entries.';

            list.appendChild(
                noResults
            );

            return;

        }

        filtered.forEach(
            function (entry) {

                var item =
                    document.createElement(
                        'button'
                    );

                item.type =
                    'button';

                item.className =
                    'entry-creator-edit-item';

                item.textContent =
                    entry.name;

                item.setAttribute(
                    'data-entry-page',
                    entry.title
                );

                if (
                    normalizePageName(
                        selectedPage
                    ) ===
                    normalizePageName(
                        entry.title
                    )
                ) {

                    item.classList.add(
                        'entry-active'
                    );

                }

                item.addEventListener(
                    'click',
                    function () {

                        selectEditEntry(
                            entry
                        );

                    }
                );

                list.appendChild(
                    item
                );

            }
        );

    }

    function selectEditEntry(
        entry
    ) {

        document
            .getElementById(
                'entryCreatorEditName'
            )
            .value =
                entry.name;

        document
            .getElementById(
                'entryCreatorEditPage'
            )
            .value =
                entry.title;

        document
            .getElementById(
                'entryCreatorEditSelected'
            )
            .textContent =
                'Selected: ' +
                entry.name;

        document
            .getElementById(
                'entryCreatorLoadStatus'
            )
            .textContent =
                '';

        renderEditEntryList(
            document
                .getElementById(
                    'entryCreatorEditSearch'
                )
                .value
        );

    }

    function refreshLocations() {

        return loadMediaWikiModules()
            .then(
                function () {

                    var api =
                        new mw.Api();

                    return getAllCategoryMembers(
                        api,
                        'Category:Fish Locations'
                    );

                }
            )
            .then(
                function (titles) {

                    var locations =
                        [];

                    titles.forEach(
                        function (title) {

                            var name =
                                getEntryNameFromTitle(
                                    'Location',
                                    title
                                );

                            if (
                                !name
                            ) {
                                return;
                            }

                            addUniqueLocation(
                                locations,
                                name
                            );

                        }
                    );

                    currentLocations =
                        locations;

                    renderLocationInputs(
                        currentLocations
                    );

                    return locations;

                }
            )
            .catch(
                function (error) {

                    console.error(
                        'Location Loader Error:',
                        error
                    );

                    currentLocations =
                        [];

                    renderLocationInputs(
                        currentLocations
                    );

                    return [];

                }
            );

    }

    function loadMediaWikiModules() {

        return mw.loader.using([
            'mediawiki.api',
            'mediawiki.util'
        ]);

    }

    function getAllCategoryMembers(
        api,
        category,
        cmcontinue
    ) {

        var params = {

            action:
                'query',

            list:
                'categorymembers',

            cmtitle:
                category,

            cmnamespace:
                0,

            cmlimit:
                'max',

            format:
                'json',

            formatversion:
                2

        };

        if (
            cmcontinue
        ) {

            params.cmcontinue =
                cmcontinue;

        }

        return apiRequest(
            api,
            params
        )
            .then(
                function (response) {

                    var titles =
                        [];

                    if (
                        response.query &&
                        response.query.categorymembers
                    ) {

                        titles =
                            response.query
                                .categorymembers
                                .map(
                                    function (
                                        page
                                    ) {

                                        return page.title;

                                    }
                                );

                    }

                    if (
                        response.continue &&
                        response.continue.cmcontinue
                    ) {

                        return getAllCategoryMembers(
                            api,
                            category,
                            response.continue.cmcontinue
                        )
                            .then(
                                function (
                                    more
                                ) {

                                    return titles.concat(
                                        more
                                    );

                                }
                            );

                    }

                    return titles;

                }
            );

    }

    function apiRequest(
        api,
        params
    ) {

        return new Promise(
            function (
                resolve,
                reject
            ) {

                api.get(
                    params
                )
                    .done(
                        function (
                            response
                        ) {

                            resolve(
                                response
                            );

                        }
                    )
                    .fail(
                        function (
                            code,
                            details
                        ) {

                            reject(
                                normalizeApiError(
                                    code,
                                    details
                                )
                            );

                        }
                    );

            }
        );

    }

    function apiEdit(
        api,
        params
    ) {

        return new Promise(
            function (
                resolve,
                reject
            ) {

                api.postWithToken(
                    'csrf',
                    params
                )
                    .done(
                        function (
                            response
                        ) {

                            resolve(
                                response
                            );

                        }
                    )
                    .fail(
                        function (
                            code,
                            details
                        ) {

                            reject(
                                normalizeApiError(
                                    code,
                                    details
                                )
                            );

                        }
                    );

            }
        );

    }

    function apiMove(
        api,
        fromPage,
        toPage
    ) {

        return new Promise(
            function (
                resolve,
                reject
            ) {

                api.postWithToken(
                    'csrf',
                    {

                        action:
                            'move',

                        from:
                            fromPage,

                        to:
                            toPage,

                        reason:
                            'Renamed entry',

                        movetalk:
                            1,

                        noredirect:
                            0,

                        format:
                            'json'

                    }
                )
                    .done(
                        function (
                            response
                        ) {

                            resolve(
                                response
                            );

                        }
                    )
                    .fail(
                        function (
                            code,
                            details
                        ) {

                            reject(
                                normalizeApiError(
                                    code,
                                    details
                                )
                            );

                        }
                    );

            }
        );

    }

    function addUniqueLocation(
        locations,
        name
    ) {

        var exists =
            locations.some(
                function (
                    location
                ) {

                    return (
                        location
                            .toLowerCase() ===
                        name
                            .toLowerCase()
                    );

                }
            );

        if (
            !exists
        ) {

            locations.push(
                name
            );

        }

    }

    function renderLocationInputs(
        locations
    ) {

        var container =
            document.getElementById(
                'entryCreatorLocationWeights'
            );

        if (
            !container
        ) {
            return;
        }

        var oldValues =
            {};

        container
            .querySelectorAll(
                '.entry-creator-location-weight'
            )
            .forEach(
                function (
                    input
                ) {

                    var location =
                        input.getAttribute(
                            'data-location-name'
                        );

                    oldValues[
                        location
                    ] =
                        input.value;

                }
            );

        container.innerHTML =
            '';

        if (
            !locations.length
        ) {

            var empty =
                document.createElement(
                    'div'
                );

            empty.className =
                'entry-creator-help';

            empty.textContent =
                'No locations have been created yet.';

            container.appendChild(
                empty
            );

            return;

        }

        locations.forEach(
            function (
                location
            ) {

                var wrapper =
                    document.createElement(
                        'div'
                    );

                wrapper.className =
                    'entry-creator-weight';

                var label =
                    document.createElement(
                        'label'
                    );

                label.textContent =
                    location;

                var input =
                    document.createElement(
                        'input'
                    );

                input.type =
                    'number';

                input.min =
                    '0';

                input.step =
                    'any';

                input.placeholder =
                    'Not in location';

                input.className =
                    'entry-creator-location-weight';

                input.setAttribute(
                    'data-location-name',
                    location
                );

                if (
                    Object.prototype
                        .hasOwnProperty.call(
                            oldValues,
                            location
                        )
                ) {

                    input.value =
                        oldValues[
                            location
                        ];

                }

                wrapper.appendChild(
                    label
                );

                wrapper.appendChild(
                    input
                );

                container.appendChild(
                    wrapper
                );

            }
        );

    }

    function getCurrentDataType() {

        var mode =
            document.getElementById(
                'entryCreatorType'
            ).value;

        if (
            mode ===
            'Edit'
        ) {

            return document
                .getElementById(
                    'entryCreatorEditType'
                )
                .value;

        }

        return mode;

    }

    function updateEntryType() {

        var mode =
            document.getElementById(
                'entryCreatorType'
            ).value;

        var editSection =
            document.getElementById(
                'entryCreatorEditSection'
            );

        var formFields =
            document.getElementById(
                'entryCreatorFormFields'
            );

        if (
            mode ===
            'Edit'
        ) {

            editSection.style.display =
                'block';

            formFields.style.display =
                loadedEdit
                    ? 'block'
                    : 'none';

        } else {

            editSection.style.display =
                'none';

            formFields.style.display =
                'block';

        }

        updateSpecificSections();

    }

    function updateSpecificSections() {

        var mode =
            document.getElementById(
                'entryCreatorType'
            ).value;

        if (
            mode ===
            'Edit' &&
            !loadedEdit
        ) {

            hideSpecificSections();

            return;

        }

        var type =
            getCurrentDataType();

        document
            .getElementById(
                'entryCreatorRarityRow'
            )
            .style.display =
                (
                    type ===
                    'Fish' ||
                    type ===
                    'Bait'
                )
                    ? 'flex'
                    : 'none';

        document
            .getElementById(
                'entryCreatorDescriptionRow'
            )
            .style.display =
                type ===
                'Location'
                    ? 'none'
                    : 'flex';

        document
            .getElementById(
                'entryCreatorFishSection'
            )
            .style.display =
                type ===
                'Fish'
                    ? 'block'
                    : 'none';

        document
            .getElementById(
                'entryCreatorToolSection'
            )
            .style.display =
                type ===
                'Tool'
                    ? 'block'
                    : 'none';

        document
            .getElementById(
                'entryCreatorEnchantSection'
            )
            .style.display =
                type ===
                'Enchant'
                    ? 'block'
                    : 'none';

    }

    function hideSpecificSections() {

        [
            'entryCreatorFishSection',
            'entryCreatorToolSection',
            'entryCreatorEnchantSection'
        ]
            .forEach(
                function (
                    id
                ) {

                    var section =
                        document.getElementById(
                            id
                        );

                    if (
                        section
                    ) {

                        section.style.display =
                            'none';

                    }

                }
            );

    }

    function getImageMode() {

        var selected =
            document.querySelector(
                'input[name="entryCreatorImageMode"]:checked'
            );

        return selected
            ? selected.value
            : 'upload';

    }

    function updateImageMode() {

        var mode =
            getImageMode();

        var uploadRow =
            document.getElementById(
                'entryCreatorUploadImageRow'
            );

        var existingRow =
            document.getElementById(
                'entryCreatorExistingImageRow'
            );

        uploadRow.style.display =
            mode ===
            'upload'
                ? 'flex'
                : 'none';

        existingRow.style.display =
            mode ===
            'existing'
                ? 'flex'
                : 'none';

        if (
            mode ===
            'keep'
        ) {

            if (
                loadedEdit &&
                loadedEdit.image
            ) {

                showExistingImage(
                    loadedEdit.image
                );

            } else {

                clearImagePreview();

            }

            return;

        }

        if (
            mode ===
            'upload'
        ) {

            updateUploadedImagePreview();

            return;

        }

        var existing =
            normalizeExistingFilename(
                document
                    .getElementById(
                        'entryCreatorExistingImage'
                    )
                    .value
            );

        if (
            existing
        ) {

            showExistingImage(
                existing
            );

        } else {

            clearImagePreview();

        }

    }

    function updateUploadedImagePreview() {

        if (
            getImageMode() !==
            'upload'
        ) {
            return;
        }

        var input =
            document.getElementById(
                'entryCreatorImage'
            );

        clearImagePreview();

        if (
            !input.files ||
            !input.files.length
        ) {
            return;
        }

        var file =
            input.files[
                0
            ];

        if (
            !isPNG(
                file
            )
        ) {

            showError(
                'The image must be a PNG file.'
            );

            return;

        }

        var image =
            document.createElement(
                'img'
            );

        var url =
            URL.createObjectURL(
                file
            );

        image.src =
            url;

        image.onload =
            function () {

                URL.revokeObjectURL(
                    url
                );

            };

        document
            .getElementById(
                'entryCreatorPreview'
            )
            .appendChild(
                image
            );

    }

    function previewExistingImage() {

        var input =
            document.getElementById(
                'entryCreatorExistingImage'
            );

        var filename =
            normalizeExistingFilename(
                input.value
            );

        if (
            !filename
        ) {

            showError(
                'Enter an existing wiki image filename first.'
            );

            return;

        }

        loadMediaWikiModules()
            .then(
                function () {

                    var api =
                        new mw.Api();

                    return verifyExistingImage(
                        api,
                        filename
                    );

                }
            )
            .then(
                function (
                    realFilename
                ) {

                    input.value =
                        realFilename;

                    showExistingImage(
                        realFilename
                    );

                    clearError();

                }
            )
            .catch(
                function (
                    error
                ) {

                    console.error(
                        'Existing Image Error:',
                        error
                    );

                    clearImagePreview();

                    showError(
                        formatError(
                            error
                        )
                    );

                }
            );

    }

    function verifyExistingImage(
        api,
        filename
    ) {

        filename =
            normalizeExistingFilename(
                filename
            );

        if (
            !filename
        ) {

            return Promise.reject({
                code:
                    'no-image',

                info:
                    'No existing image filename was entered.'
            });

        }

        return apiRequest(
            api,
            {

                action:
                    'query',

                prop:
                    'imageinfo',

                titles:
                    'File:' +
                    filename,

                iiprop:
                    'url',

                format:
                    'json',

                formatversion:
                    2

            }
        )
            .then(
                function (
                    response
                ) {

                    if (
                        !response.query ||
                        !response.query.pages ||
                        !response.query.pages.length
                    ) {

                        throw {
                            code:
                                'image-not-found',

                            info:
                                'The image could not be found on the wiki.'
                        };

                    }

                    var page =
                        response.query.pages[
                            0
                        ];

                    if (
                        page.missing
                    ) {

                        throw {
                            code:
                                'image-not-found',

                            info:
                                'File:' +
                                filename +
                                ' does not exist.'
                        };

                    }

                    if (
                        !page.imageinfo ||
                        !page.imageinfo.length
                    ) {

                        throw {
                            code:
                                'image-not-found',

                            info:
                                'The file page exists but no uploaded image was found.'
                        };

                    }

                    return String(
                        page.title ||
                        ''
                    ).replace(
                        /^File:/i,
                        ''
                    );

                }
            );

    }

    function normalizeExistingFilename(
        value
    ) {

        return String(
            value ||
            ''
        )
            .trim()
            .replace(
                /^File:/i,
                ''
            )
            .trim();

    }

    function clearImagePreview() {

        var preview =
            document.getElementById(
                'entryCreatorPreview'
            );

        if (
            preview
        ) {

            preview.innerHTML =
                '';

        }

    }

    function loadExistingEntry() {

        var type =
            document.getElementById(
                'entryCreatorEditType'
            ).value;

        var selectedName =
            document.getElementById(
                'entryCreatorEditName'
            ).value.trim();

        var pageName =
            document.getElementById(
                'entryCreatorEditPage'
            ).value.trim();

        var status =
            document.getElementById(
                'entryCreatorLoadStatus'
            );

        if (
            !selectedName ||
            !pageName
        ) {

            status.textContent =
                'Select an entry first.';

            return;

        }

        status.textContent =
            'Loading ' +
            pageName +
            '...';

        loadMediaWikiModules()
            .then(
                function () {

                    var api =
                        new mw.Api();

                    return apiRequest(
                        api,
                        {

                            action:
                                'query',

                            prop:
                                'revisions',

                            titles:
                                pageName,

                            rvprop:
                                'content',

                            rvslots:
                                'main',

                            redirects:
                                1,

                            format:
                                'json',

                            formatversion:
                                2

                        }
                    );

                }
            )
            .then(
                function (
                    response
                ) {

                    if (
                        !response.query ||
                        !response.query.pages ||
                        !response.query.pages.length
                    ) {

                        throw {
                            code:
                                'entry-not-found',

                            info:
                                pageName +
                                ' could not be found.'
                        };

                    }

                    var page =
                        response.query.pages[
                            0
                        ];

                    if (
                        page.missing
                    ) {

                        throw {
                            code:
                                'entry-not-found',

                            info:
                                pageName +
                                ' does not exist.'
                        };

                    }

                    if (
                        !page.revisions ||
                        !page.revisions.length
                    ) {

                        throw {
                            code:
                                'entry-read-error',

                            info:
                                'The page exists but its content could not be read.'
                        };

                    }

                    var revision =
                        page.revisions[
                            0
                        ];

                    var text =
                        '';

                    if (
                        revision.slots &&
                        revision.slots.main
                    ) {

                        text =
                            revision.slots.main.content ||
                            revision.slots.main['*'] ||
                            '';

                    } else {

                        text =
                            revision.content ||
                            revision['*'] ||
                            '';

                    }

                    var data =
                        parseEntryData(
                            text
                        );

                    if (
                        !data
                    ) {

                        throw {
                            code:
                                'entrydata-not-found',

                            info:
                                'The selected page exists, but it does not contain {{EntryData}}.'
                        };

                    }

                    var actualPageTitle =
                        page.title ||
                        pageName;

                    loadedEdit = {

                        page:
                            actualPageTitle,

                        originalName:
                            data.name ||
                            selectedName,

                        type:
                            type,

                        image:
                            data.image ||
                            ''

                    };

                    if (
                        type ===
                        'Fish'
                    ) {

                        return refreshLocations()
                            .then(
                                function () {

                                    populateForm(
                                        type,
                                        data
                                    );

                                }
                            );

                    }

                    populateForm(
                        type,
                        data
                    );

                }
            )
            .then(
                function () {

                    if (
                        !loadedEdit
                    ) {
                        return;
                    }

                    status.textContent =
                        'Entry loaded successfully.';

                    document
                        .getElementById(
                            'entryCreatorFormFields'
                        )
                        .style.display =
                            'block';

                    document
                        .getElementById(
                            'entryCreatorName'
                        )
                        .readOnly =
                            false;

                    var keepOption =
                        document.getElementById(
                            'entryCreatorKeepImageOption'
                        );

                    var keepRadio =
                        document.getElementById(
                            'entryCreatorImageModeKeep'
                        );

                    if (
                        loadedEdit.image
                    ) {

                        keepOption.style.display =
                            'block';

                        keepRadio.checked =
                            true;

                    } else {

                        keepOption.style.display =
                            'none';

                        document
                            .getElementById(
                                'entryCreatorImageModeUpload'
                            )
                            .checked =
                                true;

                    }

                    updateSpecificSections();
                    updateSubmitButton();
                    updateImageMode();

                }
            )
            .catch(
                function (
                    error
                ) {

                    loadedEdit =
                        null;

                    console.error(
                        'Entry Load Error:',
                        error
                    );

                    status.textContent =
                        formatError(
                            error
                        );

                    document
                        .getElementById(
                            'entryCreatorFormFields'
                        )
                        .style.display =
                            'none';

                }
            );

    }

    function parseEntryData(
        text
    ) {

        var match =
            text.match(
                /\{\{\s*EntryData\b([\s\S]*?)\n?\}\}/i
            );

        if (
            !match
        ) {
            return null;
        }

        var data =
            {};

        var currentKey =
            null;

        match[
            1
        ]
            .split(
                /\r?\n/
            )
            .forEach(
                function (
                    line
                ) {

                    var parameter =
                        line.match(
                            /^\s*\|\s*([^=]+?)\s*=\s*(.*)$/
                        );

                    if (
                        parameter
                    ) {

                        currentKey =
                            parameter[
                                1
                            ]
                                .trim()
                                .toLowerCase();

                        data[
                            currentKey
                        ] =
                            decodeTemplateValue(
                                parameter[
                                    2
                                ]
                                    .trim()
                            );

                        return;

                    }

                    if (
                        currentKey &&
                        line.trim()
                    ) {

                        data[
                            currentKey
                        ] +=
                            '\n' +
                            line.trim();

                    }

                }
            );

        return data;

    }

    function parseLocationWeights(
        data
    ) {

        var weights =
            {};

        if (
            !data.location_weights
        ) {

            return weights;

        }

        data.location_weights
            .split(
                ';'
            )
            .forEach(
                function (
                    entry
                ) {

                    entry =
                        entry.trim();

                    if (
                        !entry
                    ) {
                        return;
                    }

                    var separator =
                        entry.lastIndexOf(
                            ':'
                        );

                    if (
                        separator ===
                        -1
                    ) {
                        return;
                    }

                    var location =
                        entry
                            .slice(
                                0,
                                separator
                            )
                            .trim();

                    var weight =
                        entry
                            .slice(
                                separator +
                                1
                            )
                            .trim();

                    if (
                        location &&
                        weight
                    ) {

                        weights[
                            location
                        ] =
                            weight;

                        addUniqueLocation(
                            currentLocations,
                            location
                        );

                    }

                }
            );

        return weights;

    }

    function populateForm(
        type,
        data
    ) {

        clearForm();

        document
            .getElementById(
                'entryCreatorName'
            )
            .value =
                data.name ||
                '';

        document
            .getElementById(
                'entryCreatorName'
            )
            .readOnly =
                false;

        if (
            type ===
            'Fish' ||
            type ===
            'Bait'
        ) {

            document
                .getElementById(
                    'entryCreatorRarity'
                )
                .value =
                    RARITIES.indexOf(
                        data.rarity
                    ) !==
                    -1
                        ? data.rarity
                        : 'Common';

        }

        if (
            type !==
            'Location'
        ) {

            document
                .getElementById(
                    'entryCreatorDescription'
                )
                .value =
                    data.description ||
                    '';

        }

        if (
            type ===
            'Fish'
        ) {

            document
                .getElementById(
                    'entryCreatorFishBaseSellPrice'
                )
                .value =
                    data.base_sell_price ||
                    '';

            var weights =
                parseLocationWeights(
                    data
                );

            renderLocationInputs(
                currentLocations
            );

            Object.keys(
                weights
            )
                .forEach(
                    function (
                        location
                    ) {

                        var input =
                            findLocationInput(
                                location
                            );

                        if (
                            input
                        ) {

                            input.value =
                                weights[
                                    location
                                ];

                        }

                    }
                );

        }

        if (
            type ===
            'Tool'
        ) {

            document
                .getElementById(
                    'entryCreatorToolBaseCost'
                )
                .value =
                    data.base_cost ||
                    '';

        }

        if (
            type ===
            'Enchant'
        ) {

            document
                .getElementById(
                    'entryCreatorEnchantWeight'
                )
                .value =
                    data.weight ||
                    '';

        }

        if (
            data.image
        ) {

            document
                .getElementById(
                    'entryCreatorImageNote'
                )
                .textContent =
                    'Current image: ' +
                    data.image;

        }

    }

    function findLocationInput(
        location
    ) {

        var inputs =
            document.querySelectorAll(
                '.entry-creator-location-weight'
            );

        for (
            var i =
                0;
            i <
                inputs.length;
            i++
        ) {

            var inputLocation =
                inputs[
                    i
                ]
                    .getAttribute(
                        'data-location-name'
                    );

            if (
                inputLocation &&
                inputLocation
                    .toLowerCase() ===
                location
                    .toLowerCase()
            ) {

                return inputs[
                    i
                ];

            }

        }

        return null;

    }

    function showExistingImage(
        filename
    ) {

        clearImagePreview();

        if (
            !filename
        ) {
            return;
        }

        var image =
            document.createElement(
                'img'
            );

        image.src =
            mw.util.getUrl(
                'Special:Redirect/file/' +
                filename
            );

        document
            .getElementById(
                'entryCreatorPreview'
            )
            .appendChild(
                image
            );

    }

    function clearForm() {

        [
            'entryCreatorName',
            'entryCreatorDescription',
            'entryCreatorFishBaseSellPrice',
            'entryCreatorToolBaseCost',
            'entryCreatorEnchantWeight',
            'entryCreatorExistingImage'
        ]
            .forEach(
                function (
                    id
                ) {

                    var element =
                        document.getElementById(
                            id
                        );

                    if (
                        element
                    ) {

                        element.value =
                            '';

                    }

                }
            );

        document
            .querySelectorAll(
                '.entry-creator-location-weight'
            )
            .forEach(
                function (
                    input
                ) {

                    input.value =
                        '';

                }
            );

        var nameInput =
            document.getElementById(
                'entryCreatorName'
            );

        if (
            nameInput
        ) {

            nameInput.readOnly =
                false;

        }

        var rarity =
            document.getElementById(
                'entryCreatorRarity'
            );

        if (
            rarity
        ) {

            rarity.value =
                'Common';

        }

        var imageInput =
            document.getElementById(
                'entryCreatorImage'
            );

        if (
            imageInput
        ) {

            imageInput.value =
                '';

        }

        var uploadRadio =
            document.getElementById(
                'entryCreatorImageModeUpload'
            );

        if (
            uploadRadio
        ) {

            uploadRadio.checked =
                true;

        }

        var keepOption =
            document.getElementById(
                'entryCreatorKeepImageOption'
            );

        if (
            keepOption
        ) {

            keepOption.style.display =
                'none';

        }

        clearImagePreview();
        clearError();

        var imageNote =
            document.getElementById(
                'entryCreatorImageNote'
            );

        if (
            imageNote
        ) {

            imageNote.textContent =
                'PNG files only.';

        }

        updateImageMode();

    }

    function isAdmin() {

        var groups =
            mw.config.get(
                'wgUserGroups'
            ) ||
            [];

        return (
            groups.indexOf(
                'sysop'
            ) !==
            -1 ||
            groups.indexOf(
                'automod'
            ) !==
            -1
        );

    }

    function updateSubmitButton() {

        var button =
            document.getElementById(
                'entryCreatorSubmit'
            );

        if (
            !button
        ) {
            return;
        }

        var mode =
            document.getElementById(
                'entryCreatorType'
            ).value;

        if (
            mode ===
            'Edit'
        ) {

            button.textContent =
                isAdmin()
                    ? 'Save Changes'
                    : 'Submit Edit for Review';

        } else {

            button.textContent =
                isAdmin()
                    ? 'Publish Entry'
                    : 'Submit for Review';

        }

    }

    function submitEntry() {

        clearError();

        var button =
            document.getElementById(
                'entryCreatorSubmit'
            );

        var status =
            document.getElementById(
                'entryCreatorStatus'
            );

        if (
            !mw.config.get(
                'wgUserName'
            )
        ) {

            showError(
                'You must be logged in to submit an entry.'
            );

            return;

        }

        var mode =
            document.getElementById(
                'entryCreatorType'
            ).value;

        if (
            mode ===
            'Edit' &&
            !loadedEdit
        ) {

            showError(
                'Load an existing entry first.'
            );

            return;

        }

        var data =
            collectFormData();

        if (
            !data
        ) {
            return;
        }

        button.disabled =
            true;

        loadMediaWikiModules()
            .then(
                function () {

                    var api =
                        new mw.Api();

                    status.textContent =
                        'Checking image...';

                    return resolveEntryImage(
                        api,
                        data,
                        mode
                    )
                        .then(
                            function (
                                filename
                            ) {

                                data.image =
                                    filename;

                                return api;

                            }
                        );

                }
            )
            .then(
                function (
                    api
                ) {

                    status.textContent =
                        mode ===
                        'Edit'
                            ?
                        (
                            isAdmin()
                                ? 'Saving changes...'
                                : 'Submitting edit for review...'
                        )
                            :
                        (
                            isAdmin()
                                ? 'Publishing entry...'
                                : 'Submitting entry for review...'
                        );

                    return saveEntry(
                        api,
                        data,
                        mode
                    );

                }
            )
            .then(
                function (
                    result
                ) {

                    button.disabled =
                        false;

                    showSuccess(
                        result.message,
                        result.page
                    );

                    if (
                        data.type ===
                        'Location' &&
                        isAdmin()
                    ) {

                        refreshLocations();

                    }

                    if (
                        document
                            .getElementById(
                                'entryCreatorType'
                            )
                            .value ===
                        'Edit'
                    ) {

                        refreshEditEntries();

                    }

                }
            )
            .catch(
                function (
                    error
                ) {

                    button.disabled =
                        false;

                    console.error(
                        'FULL ENTRY CREATOR ERROR:',
                        error
                    );

                    console.error(
                        'ERROR CODE:',
                        error &&
                        error.code
                    );

                    console.error(
                        'ERROR INFO:',
                        error &&
                        error.info
                    );

                    console.error(
                        'ERROR DETAILS:',
                        error &&
                        error.details
                    );

                    showError(
                        formatError(
                            error
                        )
                    );

                }
            );

    }

    function resolveEntryImage(
        api,
        data,
        mode
    ) {

        if (
            data.imageMode ===
            'keep'
        ) {

            if (
                !loadedEdit ||
                !loadedEdit.image
            ) {

                return Promise.reject({
                    code:
                        'no-current-image',

                    info:
                        'There is no current image to keep.'
                });

            }

            return Promise.resolve(
                loadedEdit.image
            );

        }

        if (
            data.imageMode ===
            'existing'
        ) {

            return verifyExistingImage(
                api,
                data.existingImage
            );

        }

        if (
            data.imageMode ===
            'upload'
        ) {

            return uploadEntryImage(
                api,
                data,
                mode
            );

        }

        return Promise.reject({
            code:
                'image-mode-error',

            info:
                'No image option was selected.'
        });

    }

    function collectFormData() {

        var mode =
            document.getElementById(
                'entryCreatorType'
            ).value;

        var type =
            getCurrentDataType();

        var name =
            document.getElementById(
                'entryCreatorName'
            ).value.trim();

        var description =
            document.getElementById(
                'entryCreatorDescription'
            ).value.trim();

        var imageMode =
            getImageMode();

        if (
            !name
        ) {

            showError(
                'Please enter a name.'
            );

            return null;

        }

        if (
            /[:#\[\]|{};]/.test(
                name
            )
        ) {

            showError(
                'The entry name contains characters that cannot be used.'
            );

            return null;

        }

        var file =
            null;

        var existingImage =
            '';

        if (
            imageMode ===
            'upload'
        ) {

            var imageInput =
                document.getElementById(
                    'entryCreatorImage'
                );

            if (
                imageInput.files &&
                imageInput.files.length
            ) {

                file =
                    imageInput.files[
                        0
                    ];

            }

            if (
                !file
            ) {

                showError(
                    'Please choose a PNG image.'
                );

                return null;

            }

            if (
                !isPNG(
                    file
                )
            ) {

                showError(
                    'The image must be a PNG file.'
                );

                return null;

            }

        }

        if (
            imageMode ===
            'existing'
        ) {

            existingImage =
                normalizeExistingFilename(
                    document
                        .getElementById(
                            'entryCreatorExistingImage'
                        )
                        .value
                );

            if (
                !existingImage
            ) {

                showError(
                    'Please enter an existing wiki image.'
                );

                return null;

            }

        }

        if (
            imageMode ===
            'keep'
        ) {

            if (
                mode !==
                'Edit' ||
                !loadedEdit ||
                !loadedEdit.image
            ) {

                showError(
                    'There is no current image to keep.'
                );

                return null;

            }

        }

        var data = {

            type:
                type,

            name:
                name,

            rarity:
                (
                    type ===
                    'Fish' ||
                    type ===
                    'Bait'
                )
                    ? document
                        .getElementById(
                            'entryCreatorRarity'
                        )
                        .value
                    : '',

            description:
                type ===
                'Location'
                    ? ''
                    : (
                        description ||
                        'No description has been added yet.'
                    ),

            imageMode:
                imageMode,

            file:
                file,

            existingImage:
                existingImage,

            image:
                '',

            weights:
                {},

            baseSellPrice:
                '',

            baseCost:
                '',

            enchantWeight:
                ''

        };

        if (
            type ===
            'Fish'
        ) {

            var baseSellPrice =
                document
                    .getElementById(
                        'entryCreatorFishBaseSellPrice'
                    )
                    .value
                    .trim();

            if (
                baseSellPrice ===
                ''
            ) {

                showError(
                    'Please enter the fish base sell price.'
                );

                return null;

            }

            var parsedBaseSellPrice =
                Number(
                    baseSellPrice
                );

            if (
                !isFinite(
                    parsedBaseSellPrice
                ) ||
                parsedBaseSellPrice <
                0
            ) {

                showError(
                    'Base sell price must be 0 or greater.'
                );

                return null;

            }

            if (
                !currentLocations.length
            ) {

                showError(
                    'No fish locations have been created yet.'
                );

                return null;

            }

            var hasWeight =
                false;

            var invalidWeight =
                false;

            document
                .querySelectorAll(
                    '.entry-creator-location-weight'
                )
                .forEach(
                    function (
                        input
                    ) {

                        var location =
                            input.getAttribute(
                                'data-location-name'
                            );

                        var value =
                            input.value.trim();

                        if (
                            !value
                        ) {
                            return;
                        }

                        var weight =
                            Number(
                                value
                            );

                        if (
                            !isFinite(
                                weight
                            ) ||
                            weight <=
                            0
                        ) {

                            invalidWeight =
                                true;

                            return;

                        }

                        data.weights[
                            location
                        ] =
                            weight;

                        hasWeight =
                            true;

                    }
                );

            if (
                invalidWeight
            ) {

                showError(
                    'Fish weights must be greater than 0.'
                );

                return null;

            }

            if (
                !hasWeight
            ) {

                showError(
                    'A fish needs a weight in at least one location.'
                );

                return null;

            }

            data.baseSellPrice =
                parsedBaseSellPrice;

        }

        if (
            type ===
            'Tool'
        ) {

            var baseCost =
                document
                    .getElementById(
                        'entryCreatorToolBaseCost'
                    )
                    .value
                    .trim();

            if (
                baseCost ===
                ''
            ) {

                showError(
                    'Please enter the tool base cost.'
                );

                return null;

            }

            var parsedBaseCost =
                Number(
                    baseCost
                );

            if (
                !isFinite(
                    parsedBaseCost
                ) ||
                parsedBaseCost <
                0
            ) {

                showError(
                    'Base cost must be 0 or greater.'
                );

                return null;

            }

            data.baseCost =
                parsedBaseCost;

        }

        if (
            type ===
            'Enchant'
        ) {

            var enchantWeight =
                document
                    .getElementById(
                        'entryCreatorEnchantWeight'
                    )
                    .value
                    .trim();

            if (
                enchantWeight ===
                ''
            ) {

                showError(
                    'Please enter the enchant weight.'
                );

                return null;

            }

            var parsedEnchantWeight =
                Number(
                    enchantWeight
                );

            if (
                !isFinite(
                    parsedEnchantWeight
                ) ||
                parsedEnchantWeight <=
                0
            ) {

                showError(
                    'Enchant weight must be greater than 0.'
                );

                return null;

            }

            data.enchantWeight =
                parsedEnchantWeight;

        }

        return data;

    }

    function isPNG(
        file
    ) {

        if (
            !file
        ) {
            return false;
        }

        var filename =
            String(
                file.name ||
                ''
            ).toLowerCase();

        if (
            filename.slice(
                -4
            ) !==
            '.png'
        ) {

            return false;

        }

        if (
            file.type &&
            file.type !==
            'image/png'
        ) {

            return false;

        }

        return true;

    }

    function uploadEntryImage(
        api,
        data,
        mode
    ) {

        var filename;

        if (
            mode ===
            'Edit'
        ) {

            filename =
                cleanFilenamePart(
                    data.type
                ) +
                '_' +
                cleanFilenamePart(
                    data.name
                ) +
                '_Edit_' +
                Date.now() +
                '.png';

        } else if (
            !isAdmin()
        ) {

            filename =
                'Pending_' +
                cleanFilenamePart(
                    data.type
                ) +
                '_' +
                cleanFilenamePart(
                    data.name
                ) +
                '_' +
                Date.now() +
                '.png';

        } else {

            filename =
                makeImageFilename(
                    data.type,
                    data.name
                );

        }

        var parameters = {

            filename:
                filename,

            comment:
                'Image for ' +
                data.type +
                ' entry ' +
                data.name,

            ignorewarnings:
                0

        };

        return new Promise(
            function (
                resolve,
                reject
            ) {

                var upload;

                try {

                    upload =
                        api.upload(
                            data.file,
                            parameters
                        );

                } catch (
                    error
                ) {

                    reject({
                        code:
                            'upload-error',

                        info:
                            error &&
                            error.message
                                ? error.message
                                : String(
                                    error
                                )
                    });

                    return;

                }

                upload
                    .done(
                        function (
                            response
                        ) {

                            if (
                                !response ||
                                !response.upload
                            ) {

                                reject({
                                    code:
                                        'upload-no-response',

                                    info:
                                        'MediaWiki returned no upload information.'
                                });

                                return;

                            }

                            if (
                                response.upload.result ===
                                'Warning'
                            ) {

                                reject({
                                    code:
                                        'upload-warning',

                                    info:
                                        getUploadWarningText(
                                            response.upload.warnings
                                        ),

                                    details:
                                        response.upload.warnings
                                });

                                return;

                            }

                            if (
                                response.upload.result !==
                                'Success'
                            ) {

                                reject({
                                    code:
                                        'upload-failed',

                                    info:
                                        'MediaWiki returned upload result: ' +
                                        String(
                                            response.upload.result
                                        )
                                });

                                return;

                            }

                            resolve(
                                response.upload.filename ||
                                filename
                            );

                        }
                    )
                    .fail(
                        function (
                            code,
                            details
                        ) {

                            reject(
                                normalizeApiError(
                                    code,
                                    details
                                )
                            );

                        }
                    );

            }
        );

    }

    function getUploadWarningText(
        warnings
    ) {

        if (
            !warnings
        ) {

            return (
                'MediaWiki returned an upload warning.'
            );

        }

        if (
            typeof warnings ===
            'string'
        ) {

            return warnings;

        }

        var parts =
            [];

        Object.keys(
            warnings
        )
            .forEach(
                function (
                    key
                ) {

                    var value =
                        warnings[
                            key
                        ];

                    if (
                        typeof value ===
                        'string'
                    ) {

                        parts.push(
                            key +
                            ': ' +
                            value
                        );

                    } else {

                        try {

                            parts.push(
                                key +
                                ': ' +
                                JSON.stringify(
                                    value
                                )
                            );

                        } catch (
                            error
                        ) {

                            parts.push(
                                key
                            );

                        }

                    }

                }
            );

        return parts.length
            ? parts.join(
                ' | '
            )
            : 'MediaWiki returned an upload warning.';

    }

    function cleanFilenamePart(
        value
    ) {

        return String(
            value ||
            ''
        )
            .replace(
                /[\/\\:#<>\[\]|{}]/g,
                ''
            )
            .replace(
                /\s+/g,
                '_'
            )
            .trim();

    }

    function makeImageFilename(
        type,
        name
    ) {

        return (
            cleanFilenamePart(
                type
            ) +
            '_' +
            cleanFilenamePart(
                name
            ) +
            '.png'
        );

    }

    function saveEntry(
        api,
        data,
        mode
    ) {

        var admin =
            isAdmin();

        if (
            mode ===
            'Edit' &&
            admin
        ) {

            var oldPage =
                loadedEdit.page;

            var newPage =
                PAGE_PREFIXES[
                    data.type
                ] +
                data.name;

            var renameNeeded =
                normalizePageName(
                    oldPage
                ) !==
                normalizePageName(
                    newPage
                );

            var renamePromise =
                renameNeeded
                    ? apiMove(
                        api,
                        oldPage,
                        newPage
                    )
                    : Promise.resolve();

            return renamePromise
                .then(
                    function () {

                        var finalPage =
                            renameNeeded
                                ? newPage
                                : oldPage;

                        var pageText =
                            buildEntryWikitext(
                                data,
                                true,
                                mode
                            );

                        return apiEdit(
                            api,
                            {

                                action:
                                    'edit',

                                title:
                                    finalPage,

                                text:
                                    pageText,

                                summary:
                                    renameNeeded
                                        ?
                                    (
                                        'Renamed and updated ' +
                                        data.type +
                                        ' entry from ' +
                                        loadedEdit.originalName +
                                        ' to ' +
                                        data.name
                                    )
                                        :
                                    (
                                        'Updated ' +
                                        data.type +
                                        ' entry: ' +
                                        data.name
                                    ),

                                nocreate:
                                    true,

                                format:
                                    'json'

                            }
                        )
                            .then(
                                function () {

                                    return finalPage;

                                }
                            );

                    }
                )
                .then(
                    function (
                        finalPage
                    ) {

                        loadedEdit.page =
                            finalPage;

                        loadedEdit.originalName =
                            data.name;

                        loadedEdit.image =
                            data.image;

                        return {

                            page:
                                finalPage,

                            message:
                                renameNeeded
                                    ?
                                'Entry renamed and updated successfully!'
                                    :
                                'Entry updated successfully!'

                        };

                    }
                );

        }

        var pageName;

        if (
            mode ===
            'Edit'
        ) {

            pageName =
                'Entry submission:Edit/' +
                data.type +
                '/' +
                loadedEdit.originalName;

        } else if (
            admin
        ) {

            pageName =
                PAGE_PREFIXES[
                    data.type
                ] +
                data.name;

        } else {

            pageName =
                'Entry submission:' +
                data.type +
                '/' +
                data.name;

        }

        var pageText =
            buildEntryWikitext(
                data,
                admin,
                mode
            );

        return apiEdit(
            api,
            {

                action:
                    'edit',

                title:
                    pageName,

                text:
                    pageText,

                summary:
                    buildEditSummary(
                        data,
                        mode,
                        admin
                    ),

                createonly:
                    true,

                format:
                    'json'

            }
        )
            .then(
                function () {

                    return {

                        page:
                            pageName,

                        message:
                            mode ===
                            'Edit'
                                ?
                            'Your edit was submitted for review.'
                                :
                            (
                                admin
                                    ?
                                'Entry published successfully!'
                                    :
                                'Entry submitted successfully and is waiting for approval.'
                            )

                    };

                }
            );

    }

    function buildEditSummary(
        data,
        mode,
        admin
    ) {

        if (
            mode ===
            'Edit'
        ) {

            if (
                admin
            ) {

                if (
                    loadedEdit &&
                    loadedEdit.originalName !==
                    data.name
                ) {

                    return (
                        'Renamed ' +
                        data.type +
                        ' entry from ' +
                        loadedEdit.originalName +
                        ' to ' +
                        data.name
                    );

                }

                return (
                    'Updated ' +
                    data.type +
                    ' entry: ' +
                    data.name
                );

            }

            return (
                'Submitted edit for ' +
                data.type +
                ' entry: ' +
                data.name
            );

        }

        if (
            admin
        ) {

            return (
                'Published ' +
                data.type +
                ' entry: ' +
                data.name
            );

        }

        return (
            'Submitted ' +
            data.type +
            ' entry for review: ' +
            data.name
        );

    }

    function buildLocationWeightsString(
        weights
    ) {

        return Object.keys(
            weights
        )
            .map(
                function (
                    location
                ) {

                    return (
                        location +
                        ':' +
                        weights[
                            location
                        ]
                    );

                }
            )
            .join(
                ';'
            );

    }

    function buildEntryWikitext(
        data,
        live,
        mode
    ) {

        var text =
            '{{EntryData\n' +

            '|type=' +
            safeTemplateValue(
                data.type
            ) +
            '\n' +

            '|name=' +
            safeTemplateValue(
                data.name
            ) +
            '\n' +

            '|image=' +
            safeTemplateValue(
                data.image
            ) +
            '\n';

        if (
            data.type ===
            'Fish' ||
            data.type ===
            'Bait'
        ) {

            text +=
                '|rarity=' +
                safeTemplateValue(
                    data.rarity
                ) +
                '\n';

        }

        if (
            data.type !==
            'Location'
        ) {

            text +=
                '|description=' +
                safeTemplateValue(
                    data.description
                ) +
                '\n';

        }

        if (
            data.type ===
            'Fish'
        ) {

            text +=
                '|base_sell_price=' +
                safeTemplateValue(
                    data.baseSellPrice
                ) +
                '\n';

            text +=
                '|location_weights=' +
                safeTemplateValue(
                    buildLocationWeightsString(
                        data.weights
                    )
                ) +
                '\n';

        }

        if (
            data.type ===
            'Tool'
        ) {

            text +=
                '|base_cost=' +
                safeTemplateValue(
                    data.baseCost
                ) +
                '\n';

        }

        if (
            data.type ===
            'Enchant'
        ) {

            text +=
                '|weight=' +
                safeTemplateValue(
                    data.enchantWeight
                ) +
                '\n';

        }

        if (
            mode ===
            'Edit' &&
            !live &&
            loadedEdit
        ) {

            text +=
                '|edit_target=' +
                safeTemplateValue(
                    loadedEdit.page
                ) +
                '\n';

            text +=
                '|original_name=' +
                safeTemplateValue(
                    loadedEdit.originalName
                ) +
                '\n';

            text +=
                '|requested_name=' +
                safeTemplateValue(
                    data.name
                ) +
                '\n';

        }

        text +=
            '|status=' +
            (
                live
                    ? 'Published'
                    : 'Pending'
            ) +
            '\n';

        text +=
            '}}\n\n';

        if (
            live
        ) {

            text +=
                '[[Category:' +
                data.type +
                ' Entries]]\n';

            if (
                data.type ===
                'Fish'
            ) {

                Object.keys(
                    data.weights
                )
                    .forEach(
                        function (
                            location
                        ) {

                            text +=
                                '[[Category:' +
                                safeCategoryName(
                                    location
                                ) +
                                ' Fish]]\n';

                        }
                    );

            }

            if (
                data.type ===
                'Location'
            ) {

                text +=
                    '[[Category:Fish Locations]]\n';

            }

        } else {

            text +=
                '[[Category:Pending Entry Submissions]]\n';

            if (
                mode ===
                'Edit'
            ) {

                text +=
                    '[[Category:Pending Entry Edits]]\n';

                text +=
                    '[[Category:Pending ' +
                    data.type +
                    ' Edits]]\n';

            } else {

                text +=
                    '[[Category:Pending ' +
                    data.type +
                    ' Submissions]]\n';

            }

        }

        return text;

    }

    function safeCategoryName(
        value
    ) {

        return String(
            value ||
            ''
        )
            .replace(
                /[\[\]{}|<>#]/g,
                ''
            )
            .trim();

    }

    function decodeTemplateValue(
        value
    ) {

        return String(
            value ||
            ''
        )
            .replace(
                /&#124;/g,
                '|'
            )
            .replace(
                /\}&#125;/g,
                '}}'
            );

    }

    function safeTemplateValue(
        value
    ) {

        return String(
            value ||
            ''
        )
            .replace(
                /\|/g,
                '&#124;'
            )
            .replace(
                /\}\}/g,
                '}&#125;'
            );

    }

    function normalizeApiError(
        code,
        details
    ) {

        var error = {

            code:
                code ||
                'api-error',

            info:
                '',

            details:
                details ||
                null

        };

        if (
            details &&
            details.error
        ) {

            if (
                details.error.code
            ) {

                error.code =
                    details.error.code;

            }

            if (
                details.error.info
            ) {

                error.info =
                    details.error.info;

            }

        }

        if (
            !error.info &&
            details &&
            details.info
        ) {

            error.info =
                details.info;

        }

        if (
            !error.info &&
            details &&
            details.exception
        ) {

            error.info =
                details.exception;

        }

        if (
            !error.info &&
            typeof details ===
            'string'
        ) {

            error.info =
                details;

        }

        if (
            !error.info
        ) {

            error.info =
                'MediaWiki returned an API error.';

        }

        return error;

    }

    function formatError(
        error
    ) {

        if (
            !error
        ) {

            return (
                'Unknown error.'
            );

        }

        if (
            typeof error ===
            'string'
        ) {

            return error;

        }

        var code =
            error.code ||
            '';

        var info =
            error.info ||
            error.message ||
            '';

        if (
            code &&
            info
        ) {

            return (
                code +
                ': ' +
                info
            );

        }

        if (
            info
        ) {

            return info;

        }

        if (
            code
        ) {

            return code;

        }

        try {

            return JSON.stringify(
                error
            );

        } catch (
            error2
        ) {

            return (
                'Unknown error. Check the browser console.'
            );

        }

    }

    function clearError() {

        var status =
            document.getElementById(
                'entryCreatorStatus'
            );

        if (
            !status
        ) {
            return;
        }

        status.className =
            'entry-creator-status';

        status.textContent =
            '';

    }

    function showError(
        message
    ) {

        var status =
            document.getElementById(
                'entryCreatorStatus'
            );

        if (
            !status
        ) {
            return;
        }

        status.className =
            'entry-creator-status ' +
            'entry-creator-status-error';

        status.textContent =
            message;

    }

    function showSuccess(
        message,
        pageName
    ) {

        var status =
            document.getElementById(
                'entryCreatorStatus'
            );

        status.className =
            'entry-creator-status ' +
            'entry-creator-status-success';

        var url =
            mw.util.getUrl(
                pageName
            );

        status.innerHTML =
            '✅ ' +
            escapeHtml(
                message
            ) +
            '<br>' +
            '<a href="' +
            escapeAttribute(
                url
            ) +
            '">' +
            escapeHtml(
                pageName
            ) +
            '</a>';

    }

    function escapeHtml(
        value
    ) {

        return String(
            value ||
            ''
        )
            .replace(
                /&/g,
                '&amp;'
            )
            .replace(
                /</g,
                '&lt;'
            )
            .replace(
                />/g,
                '&gt;'
            )
            .replace(
                /"/g,
                '&quot;'
            )
            .replace(
                /'/g,
                '&#039;'
            );

    }

    function escapeAttribute(
        value
    ) {

        return escapeHtml(
            value
        );

    }

})();

