(function () {

    var ENTRIES_PAGE = 'Fish_entries:sandbox';

    var CATEGORIES = {
        Fish: 'Category:Fish Entries',
        Bait: 'Category:Bait Entries',
        Tool: 'Category:Tool Entries',
        Enchant: 'Category:Enchant Entries',
        Location: 'Category:Fish Locations',
        Rarity: 'Category:Rarity Entries'
    };

    var SIDE_ICONS = {
        Items: 'Ball.png',
        Tools: 'Fishing_Rod.png',
        Enchants: 'strength.png'
    };

    var locations = [];
    var fishEntries = [];
    var baitEntries = [];
    var toolEntries = [];
    var enchantEntries = [];
    var rarityEntries = {};

    var currentSection = 'Items';
    var currentItemTab = 'Fish';
    var currentLocation = null;

    $(function () {

        if (
            normalizePageName(
                mw.config.get('wgPageName')
            ) !==
            normalizePageName(
                ENTRIES_PAGE
            )
        ) {
            return;
        }

        var container =
            document.getElementById(
                'fish-entries-app'
            );

        if (!container) {
            return;
        }

        if (
            container.dataset.loaded ===
            'true'
        ) {
            return;
        }

        container.dataset.loaded =
            'true';

        container.innerHTML =
            '<div class="entries-app-loading">Loading entries...</div>';

        loadMediaWikiModules()
            .then(function () {

                return Promise.all([
                    loadLocations(),
                    loadFish(),
                    loadBaits(),
                    loadTools(),
                    loadEnchants(),
                    loadRarities()
                ]);

            })
            .then(function () {

                injectRarityStyles();

                buildEntriesApp(
                    container
                );

            })
            .catch(function (error) {

                console.error(
                    'Fish Entries App Error:',
                    error
                );

                container.innerHTML =
                    '<div class="entries-app-error">' +
                    escapeHtml(
                        formatError(
                            error
                        )
                    ) +
                    '</div>';

            });

    });

    function normalizePageName(value) {

        return String(
            value ||
            ''
        )
            .replace(
                /_/g,
                ' '
            )
            .replace(
                /\s+/g,
                ' '
            )
            .trim()
            .toLowerCase();

    }

    function loadMediaWikiModules() {

        return mw.loader.using([
            'mediawiki.api',
            'mediawiki.util'
        ]);

    }

    function loadLocations() {

        var api =
            new mw.Api();

        return getCategoryEntryPages(
            api,
            CATEGORIES.Location,
            'Location'
        )
            .then(function (entries) {

                locations =
                    entries.map(
                        function (entry) {

                            return {
                                page:
                                    entry.page,

                                name:
                                    entry.data.name ||
                                    getNameFromPage(
                                        entry.page
                                    ),

                                image:
                                    entry.data.image ||
                                    ''
                            };

                        }
                    );

                locations.sort(
                    sortByName
                );

            });

    }

    function loadFish() {

        var api =
            new mw.Api();

        return getCategoryEntryPages(
            api,
            CATEGORIES.Fish,
            'Fish'
        )
            .then(function (entries) {

                fishEntries =
                    entries.map(
                        function (entry) {

                            return {
                                page:
                                    entry.page,

                                name:
                                    entry.data.name ||
                                    getNameFromPage(
                                        entry.page
                                    ),

                                image:
                                    entry.data.image ||
                                    '',

                                rarity:
                                    entry.data.rarity ||
                                    '',

                                description:
                                    entry.data.description ||
                                    '',

                                baseSellPrice:
                                    entry.data.base_sell_price ||
                                    '',

                                weights:
                                    parseLocationWeights(
                                        entry.data.location_weights
                                    )
                            };

                        }
                    );

                fishEntries.sort(
                    sortByName
                );

            });

    }

    function loadBaits() {

        var api =
            new mw.Api();

        return getCategoryEntryPages(
            api,
            CATEGORIES.Bait,
            'Bait'
        )
            .then(function (entries) {

                baitEntries =
                    entries.map(
                        function (entry) {

                            return {
                                page:
                                    entry.page,

                                name:
                                    entry.data.name ||
                                    getNameFromPage(
                                        entry.page
                                    ),

                                image:
                                    entry.data.image ||
                                    '',

                                rarity:
                                    entry.data.rarity ||
                                    '',

                                description:
                                    entry.data.description ||
                                    ''
                            };

                        }
                    );

                baitEntries.sort(
                    sortByName
                );

            });

    }

    function loadTools() {

        var api =
            new mw.Api();

        return getCategoryEntryPages(
            api,
            CATEGORIES.Tool,
            'Tool'
        )
            .then(function (entries) {

                toolEntries =
                    entries.map(
                        function (entry) {

                            return {
                                page:
                                    entry.page,

                                name:
                                    entry.data.name ||
                                    getNameFromPage(
                                        entry.page
                                    ),

                                image:
                                    entry.data.image ||
                                    '',

                                description:
                                    entry.data.description ||
                                    '',

                                baseCost:
                                    entry.data.base_cost ||
                                    ''
                            };

                        }
                    );

                toolEntries.sort(
                    sortByName
                );

            });

    }

    function loadEnchants() {

        var api =
            new mw.Api();

        return getCategoryEntryPages(
            api,
            CATEGORIES.Enchant,
            'Enchant'
        )
            .then(function (entries) {

                enchantEntries =
                    entries.map(
                        function (entry) {

                            return {
                                page:
                                    entry.page,

                                name:
                                    entry.data.name ||
                                    getNameFromPage(
                                        entry.page
                                    ),

                                image:
                                    entry.data.image ||
                                    '',

                                description:
                                    entry.data.description ||
                                    '',

                                weight:
                                    Number(
                                        entry.data.weight ||
                                        0
                                    )
                            };

                        }
                    );

                enchantEntries.sort(
                    sortByName
                );

            });

    }

    function loadRarities() {

        var api =
            new mw.Api();

        return getCategoryEntryPages(
            api,
            CATEGORIES.Rarity,
            'Rarity'
        )
            .then(function (entries) {

                rarityEntries =
                    {};

                entries.forEach(
                    function (entry) {

                        var name =
                            String(
                                entry.data.name ||
                                getNameFromPage(
                                    entry.page
                                )
                            ).trim();

                        if (!name) {
                            return;
                        }

                        rarityEntries[
                            name.toLowerCase()
                        ] = {
                            name:
                                name,

                            color0:
                                normalizeHexColor(
                                    entry.data.color_0
                                ) ||
                                '#ffffff',

                            color50:
                                normalizeHexColor(
                                    entry.data.color_50
                                ) ||
                                '#ffffff',

                            color100:
                                normalizeHexColor(
                                    entry.data.color_100
                                ) ||
                                '#ffffff'
                        };

                    }
                );

            });

    }

    function getCategoryEntryPages(
        api,
        category,
        expectedType
    ) {

        return getAllCategoryMembers(
            api,
            category
        )
            .then(function (titles) {

                if (!titles.length) {
                    return [];
                }

                return getPagesContents(
                    api,
                    titles
                );

            })
            .then(function (pages) {

                if (!pages) {
                    return [];
                }

                var result =
                    [];

                pages.forEach(
                    function (page) {

                        var data =
                            parseEntryData(
                                page.text
                            );

                        if (!data) {
                            return;
                        }

                        if (
                            expectedType &&
                            String(
                                data.type ||
                                ''
                            ).toLowerCase() !==
                            expectedType.toLowerCase()
                        ) {
                            return;
                        }

                        result.push({
                            page:
                                page.title,

                            data:
                                data
                        });

                    }
                );

                return result;

            });

    }

    function getAllCategoryMembers(
        api,
        category,
        cmcontinue
    ) {

        var params = {
            action:
                'query',

            list:
                'categorymembers',

            cmtitle:
                category,

            cmlimit:
                'max',

            cmtype:
                'page',

            format:
                'json',

            formatversion:
                2
        };

        if (
            cmcontinue
        ) {

            params.cmcontinue =
                cmcontinue;

        }

        return apiRequest(
            api,
            params
        )
            .then(function (response) {

                var titles =
                    [];

                if (
                    response.query &&
                    response.query.categorymembers
                ) {

                    titles =
                        response.query
                            .categorymembers
                            .map(
                                function (page) {

                                    return page.title;

                                }
                            );

                }

                if (
                    response.continue &&
                    response.continue.cmcontinue
                ) {

                    return getAllCategoryMembers(
                        api,
                        category,
                        response.continue.cmcontinue
                    )
                        .then(function (more) {

                            return titles.concat(
                                more
                            );

                        });

                }

                return titles;

            });

    }

    function getPagesContents(
        api,
        titles
    ) {

        var chunks =
            [];

        for (
            var i = 0;
            i < titles.length;
            i += 50
        ) {

            chunks.push(
                titles.slice(
                    i,
                    i + 50
                )
            );

        }

        return Promise.all(
            chunks.map(
                function (chunk) {

                    return apiRequest(
                        api,
                        {
                            action:
                                'query',

                            prop:
                                'revisions',

                            titles:
                                chunk.join(
                                    '|'
                                ),

                            rvprop:
                                'content',

                            rvslots:
                                'main',

                            redirects:
                                1,

                            format:
                                'json',

                            formatversion:
                                2
                        }
                    );

                }
            )
        )
            .then(function (responses) {

                var result =
                    [];

                responses.forEach(
                    function (response) {

                        if (
                            !response.query ||
                            !response.query.pages
                        ) {
                            return;
                        }

                        response.query.pages
                            .forEach(
                                function (page) {

                                    if (
                                        page.missing ||
                                        !page.revisions ||
                                        !page.revisions.length
                                    ) {
                                        return;
                                    }

                                    var revision =
                                        page.revisions[
                                            0
                                        ];

                                    var text =
                                        '';

                                    if (
                                        revision.slots &&
                                        revision.slots.main
                                    ) {

                                        text =
                                            revision
                                                .slots
                                                .main
                                                .content ||
                                            revision
                                                .slots
                                                .main[
                                                    '*'
                                                ] ||
                                            '';

                                    } else {

                                        text =
                                            revision.content ||
                                            revision['*'] ||
                                            '';

                                    }

                                    result.push({
                                        title:
                                            page.title,

                                        text:
                                            text
                                    });

                                }
                            );

                    }
                );

                return result;

            });

    }

    function apiRequest(
        api,
        params
    ) {

        return new Promise(
            function (
                resolve,
                reject
            ) {

                api.get(
                    params
                )
                    .done(
                        function (response) {

                            resolve(
                                response
                            );

                        }
                    )
                    .fail(
                        function (
                            code,
                            details
                        ) {

                            reject(
                                normalizeApiError(
                                    code,
                                    details
                                )
                            );

                        }
                    );

            }
        );

    }

    function parseEntryData(
        text
    ) {

        var match =
            String(
                text ||
                ''
            ).match(
                /\{\{\s*EntryData\b([\s\S]*?)\n?\}\}/i
            );

        if (!match) {
            return null;
        }

        var data =
            {};

        var currentKey =
            null;

        match[1]
            .split(
                /\r?\n/
            )
            .forEach(
                function (line) {

                    var parameter =
                        line.match(
                            /^\s*\|\s*([^=]+?)\s*=\s*(.*)$/
                        );

                    if (
                        parameter
                    ) {

                        currentKey =
                            parameter[1]
                                .trim()
                                .toLowerCase();

                        data[
                            currentKey
                        ] =
                            decodeTemplateValue(
                                parameter[2]
                                    .trim()
                            );

                        return;

                    }

                    if (
                        currentKey &&
                        line.trim()
                    ) {

                        data[
                            currentKey
                        ] +=
                            '\n' +
                            line.trim();

                    }

                }
            );

        return data;

    }

    function parseLocationWeights(
        value
    ) {

        var result =
            [];

        String(
            value ||
            ''
        )
            .split(
                ';'
            )
            .forEach(
                function (part) {

                    part =
                        part.trim();

                    if (
                        !part
                    ) {
                        return;
                    }

                    var separator =
                        part.lastIndexOf(
                            ':'
                        );

                    if (
                        separator ===
                        -1
                    ) {
                        return;
                    }

                    var location =
                        part
                            .slice(
                                0,
                                separator
                            )
                            .trim();

                    var weight =
                        Number(
                            part
                                .slice(
                                    separator +
                                    1
                                )
                                .trim()
                        );

                    if (
                        !location ||
                        !isFinite(
                            weight
                        ) ||
                        weight <= 0
                    ) {
                        return;
                    }

                    result.push({
                        location:
                            location,

                        weight:
                            weight
                    });

                }
            );

        return result;

    }

    function getFishWeightForLocation(
        fish,
        locationName
    ) {

        var target =
            String(
                locationName ||
                ''
            )
                .trim()
                .toLowerCase();

        for (
            var i = 0;
            i < fish.weights.length;
            i++
        ) {

            if (
                String(
                    fish.weights[i]
                        .location
                )
                    .trim()
                    .toLowerCase() ===
                target
            ) {

                return Number(
                    fish.weights[i]
                        .weight
                ) || 0;

            }

        }

        return 0;

    }

    function getFishForLocation(
        locationName
    ) {

        var result =
            [];

        var totalWeight =
            0;

        fishEntries.forEach(
            function (fish) {

                var weight =
                    getFishWeightForLocation(
                        fish,
                        locationName
                    );

                if (
                    weight <=
                    0
                ) {
                    return;
                }

                totalWeight +=
                    weight;

                result.push({
                    fish:
                        fish,

                    weight:
                        weight,

                    chance:
                        0
                });

            }
        );

        result.forEach(
            function (entry) {

                entry.chance =
                    totalWeight > 0
                        ? (
                            entry.weight /
                            totalWeight
                        ) * 100
                        : 0;

            }
        );

        result.sort(
            function (
                a,
                b
            ) {

                if (
                    b.chance !==
                    a.chance
                ) {

                    return (
                        b.chance -
                        a.chance
                    );

                }

                return a.fish.name
                    .localeCompare(
                        b.fish.name,
                        undefined,
                        {
                            sensitivity:
                                'base'
                        }
                    );

            }
        );

        return {
            entries:
                result,

            totalWeight:
                totalWeight
        };

    }

    function buildEntriesApp(
        container
    ) {

        container.innerHTML =
            '';

        var shell =
            document.createElement(
                'div'
            );

        shell.className =
            'wiki-entries-shell';

        var sidebar =
            document.createElement(
                'div'
            );

        sidebar.className =
            'wiki-entries-sidebar';

        var content =
            document.createElement(
                'div'
            );

        content.className =
            'wiki-entries-content';

        shell.appendChild(
            sidebar
        );

        shell.appendChild(
            content
        );

        container.appendChild(
            shell
        );

        createSideButton(
            sidebar,
            'Items',
            SIDE_ICONS.Items
        );

        createSideButton(
            sidebar,
            'Tools',
            SIDE_ICONS.Tools
        );

        createSideButton(
            sidebar,
            'Enchants',
            SIDE_ICONS.Enchants
        );

        renderCurrentSection();

    }

    function createSideButton(
        container,
        section,
        imageName
    ) {

        var button =
            document.createElement(
                'button'
            );

        button.type =
            'button';

        button.className =
            'wiki-entry-side-pill';

        button.setAttribute(
            'data-entry-section',
            section
        );

        var image =
            document.createElement(
                'img'
            );

        image.src =
            getWikiImageUrl(
                imageName
            );

        image.alt =
            section;

        var label =
            document.createElement(
                'div'
            );

        label.textContent =
            section;

        button.appendChild(
            image
        );

        button.appendChild(
            label
        );

        button.addEventListener(
            'click',
            function () {

                currentSection =
                    section;

                currentLocation =
                    null;

                updateSideButtons();

                renderCurrentSection();

            }
        );

        container.appendChild(
            button
        );

    }

    function updateSideButtons() {

        document
            .querySelectorAll(
                '#fish-entries-app .wiki-entry-side-pill'
            )
            .forEach(
                function (button) {

                    var section =
                        button.getAttribute(
                            'data-entry-section'
                        );

                    button.classList.toggle(
                        'entry-active',
                        section ===
                        currentSection
                    );

                }
            );

    }

    function renderCurrentSection() {

        updateSideButtons();

        var content =
            document.querySelector(
                '#fish-entries-app .wiki-entries-content'
            );

        if (!content) {
            return;
        }

        content.innerHTML =
            '';

        if (
            currentSection ===
            'Items'
        ) {

            renderItemsSection(
                content
            );

            return;

        }

        if (
            currentSection ===
            'Tools'
        ) {

            renderToolsSection(
                content
            );

            return;

        }

        if (
            currentSection ===
            'Enchants'
        ) {

            renderEnchantsSection(
                content
            );

        }

    }

    function createSectionTitle(
        container,
        text
    ) {

        var title =
            document.createElement(
                'div'
            );

        title.className =
            'wiki-entry-content-title';

        title.textContent =
            text;

        container.appendChild(
            title
        );

    }

    function renderItemsSection(
        content
    ) {

        createSectionTitle(
            content,
            'Items'
        );

        var tabs =
            document.createElement(
                'div'
            );

        tabs.className =
            'wiki-entry-subtabs';

        var fishButton =
            createSubtabButton(
                'Fish'
            );

        var baitButton =
            createSubtabButton(
                'Baits'
            );

        tabs.appendChild(
            fishButton
        );

        tabs.appendChild(
            baitButton
        );

        content.appendChild(
            tabs
        );

        var body =
            document.createElement(
                'div'
            );

        body.className =
            'wiki-entry-items-body';

        content.appendChild(
            body
        );

        fishButton.addEventListener(
            'click',
            function () {

                currentItemTab =
                    'Fish';

                currentLocation =
                    null;

                updateItemTabs(
                    fishButton,
                    baitButton
                );

                renderFishLocations(
                    body
                );

            }
        );

        baitButton.addEventListener(
            'click',
            function () {

                currentItemTab =
                    'Baits';

                currentLocation =
                    null;

                updateItemTabs(
                    fishButton,
                    baitButton
                );

                renderBaits(
                    body
                );

            }
        );

        updateItemTabs(
            fishButton,
            baitButton
        );

        if (
            currentItemTab ===
            'Baits'
        ) {

            renderBaits(
                body
            );

        } else {

            renderFishLocations(
                body
            );

        }

    }

    function createSubtabButton(
        text
    ) {

        var button =
            document.createElement(
                'button'
            );

        button.type =
            'button';

        button.className =
            'wiki-entry-subtab';

        button.textContent =
            text;

        return button;

    }

    function updateItemTabs(
        fishButton,
        baitButton
    ) {

        fishButton.classList.toggle(
            'entry-active',
            currentItemTab ===
            'Fish'
        );

        baitButton.classList.toggle(
            'entry-active',
            currentItemTab ===
            'Baits'
        );

    }

    function renderFishLocations(
        body
    ) {

        body.innerHTML =
            '';

        if (
            currentLocation
        ) {

            renderLocationFish(
                body,
                currentLocation
            );

            return;

        }

        if (
            !locations.length
        ) {

            body.appendChild(
                createEmptyMessage(
                    'No locations have been published yet.'
                )
            );

            return;

        }

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-location-grid';

        locations.forEach(
            function (location) {

                var button =
                    document.createElement(
                        'button'
                    );

                button.type =
                    'button';

                button.className =
                    'wiki-location-pill';

                if (
                    location.image
                ) {

                    var image =
                        document.createElement(
                            'img'
                        );

                    image.src =
                        getWikiImageUrl(
                            location.image
                        );

                    image.alt =
                        location.name;

                    button.appendChild(
                        image
                    );

                }

                var name =
                    document.createElement(
                        'div'
                    );

                name.className =
                    'wiki-location-name';

                name.textContent =
                    location.name;

                button.appendChild(
                    name
                );

                button.addEventListener(
                    'click',
                    function () {

                        currentLocation =
                            location;

                        renderFishLocations(
                            body
                        );

                    }
                );

                grid.appendChild(
                    button
                );

            }
        );

        body.appendChild(
            grid
        );

    }

    function renderLocationFish(
        body,
        location
    ) {

        body.innerHTML =
            '';

        var header =
            document.createElement(
                'div'
            );

        header.className =
            'wiki-location-header';

        var titleArea =
            document.createElement(
                'div'
            );

        titleArea.className =
            'wiki-location-header-title';

        if (
            location.image
        ) {

            var icon =
                document.createElement(
                    'img'
                );

            icon.src =
                getWikiImageUrl(
                    location.image
                );

            icon.alt =
                location.name;

            titleArea.appendChild(
                icon
            );

        }

        var title =
            document.createElement(
                'div'
            );

        title.textContent =
            location.name;

        titleArea.appendChild(
            title
        );

        var back =
            document.createElement(
                'button'
            );

        back.type =
            'button';

        back.className =
            'wiki-entry-back';

        back.textContent =
            'Back';

        back.addEventListener(
            'click',
            function () {

                currentLocation =
                    null;

                renderFishLocations(
                    body
                );

            }
        );

        header.appendChild(
            titleArea
        );

        header.appendChild(
            back
        );

        body.appendChild(
            header
        );

        var calculated =
            getFishForLocation(
                location.name
            );

        if (
            !calculated.entries.length
        ) {

            body.appendChild(
                createEmptyMessage(
                    'No fish can currently be caught in this location.'
                )
            );

            return;

        }

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-fish-grid';

        calculated.entries
            .forEach(
                function (entry) {

                    grid.appendChild(
                        createFishCard(
                            entry.fish,
                            location,
                            entry.weight,
                            entry.chance,
                            calculated.totalWeight
                        )
                    );

                }
            );

        body.appendChild(
            grid
        );

    }

