        name.textContent =
            fish.name;

        applyRarityClass(
            name,
            fish.rarity
        );

        detail.appendChild(
            name
        );

        if (
            fish.rarity
        ) {

            var rarity =
                document.createElement(
                    'div'
                );

            rarity.className =
                'wiki-entry-detail-rarity';

            rarity.textContent =
                fish.rarity;

            applyRarityClass(
                rarity,
