        stats.className =
            'wiki-entry-stat-grid';

        stats.appendChild(
            createStat(
                'Location',
                location.name
            )
        );

        stats.appendChild(
            createStat(
                'Spawn Chance',
                formatPercent(
                    chance
                )
            )
        );

        stats.appendChild(
            createStat(
                'Weight',
                formatNumber(
                    weight
                )
            )
        );

        stats.appendChild(
            createStat(
                'Total Location Weight',
                formatNumber(
                    totalWeight
                )
            )
        );

        if (
            fish.baseSellPrice !==
            ''
        ) {

            stats.appendChild(
                createStat(
                    'Base Sell Price',
                    fish.baseSellPrice
                )
            );

        }

        detail.appendChild(
            stats
        );

        var calculation =
            document.createElement(
                'div'
            );

        calculation.className =
            'wiki-entry-calculation';

        calculation.textContent =
            formatNumber(
                weight
            ) +
            ' ÷ ' +
            formatNumber(
                totalWeight
            ) +
            ' × 100 = ' +
            formatPercent(
                chance
            );

        detail.appendChild(
            calculation
        );

        if (
            fish.description
        ) {

            var description =
                document.createElement(
                    'div'
                );

            description.className =
                'wiki-entry-description';

            description.textContent =
                fish.description;

            detail.appendChild(
                description
            );

        }

        detail.appendChild(
            createPageLink(
                fish.page
            )
        );

        body.appendChild(
            detail
        );

    }

    function renderBaits(
