        );

        card.addEventListener(
            'click',
            function () {

                var body =
                    document.querySelector(
                        '#fish-entries-app .wiki-entry-items-body'
                    );

                if (!body) {
                    return;
                }

                renderFishDetail(
                    body,
                    fish,
                    location,
                    weight,
                    chance,
                    totalWeight
