                );

            image.className =
                'wiki-fish-card-image';

            image.src =
                getWikiImageUrl(
                    fish.image
                );

            image.alt =
                fish.name;

            card.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'div'
            );

        name.className =
            'wiki-fish-card-name';

        name.textContent =
            fish.name;

        applyRarityClass(
            name,
            fish.rarity
        );

        card.appendChild(
            name
        );

        if (
            fish.rarity
        ) {

            var rarity =
                document.createElement(
                    'div'
                );

            rarity.className =
                'wiki-fish-card-rarity';

            rarity.textContent =
                fish.rarity;

            applyRarityClass(
                rarity,
                fish.rarity
            );

            card.appendChild(
                rarity
            );

        }

        var chanceText =
            document.createElement(
                'div'
            );

        chanceText.className =
            'wiki-fish-card-chance';

        chanceText.textContent =
            formatPercent(
                chance
            );

        card.appendChild(
