            detail.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'div'
            );

        name.className =
            'wiki-entry-detail-name';

        name.textContent =
            fish.name;

        applyRarityClass(
            name,
            fish.rarity
        );

        detail.appendChild(
            name
        );

        if (
            fish.rarity
        ) {

            var rarity =
                document.createElement(
                    'div'
                );

            rarity.className =
