            );

        name.className =
            'wiki-fish-card-name';

        name.textContent =
            fish.name;

        applyRarityClass(
            name,
            fish.rarity
        );

        card.appendChild(
            name
        );

        if (fish.rarity) {

            var rarity =
                document.createElement(
                    'div'
                );

            rarity.className =
