    function renderBaits(body) {

        body.innerHTML = '';

        if (!baitEntries.length) {

            body.appendChild(
                createEmptyMessage(
                    'No Bait entries have been published yet.'
                )
            );

            return;

        }

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-standard-entry-grid';

        baitEntries.forEach(function (bait) {

            grid.appendChild(
                createStandardCard(
                    bait,
                    function () {

                        renderStandardDetail(
                            body,
                            bait,
                            'Bait'
                        );

                    }
                )
            );

        });

        body.appendChild(
            grid
        );

    }

    function renderToolsSection(content) {

        createSectionTitle(
            content,
            'Tools'
        );

        if (!toolEntries.length) {

            content.appendChild(
                createEmptyMessage(
                    'No Tool entries have been published yet.'
                )
            );

            return;

        }

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-standard-entry-grid';

        toolEntries.forEach(function (tool) {

            grid.appendChild(
                createStandardCard(
                    tool,
                    function () {

                        renderToolDetail(
                            content,
                            tool
                        );

                    }
                )
            );

        });

        content.appendChild(
            grid
        );

    }

    function renderEnchantsSection(content) {

        createSectionTitle(
            content,
            'Enchants'
        );

        if (!enchantEntries.length) {

            content.appendChild(
                createEmptyMessage(
                    'No Enchant entries have been published yet.'
                )
            );

            return;

        }

        var totalWeight =
            enchantEntries.reduce(
                function (
                    total,
                    enchant
                ) {

                    return (
                        total +
                        (
                            Number(
                                enchant.weight
                            ) ||
                            0
                        )
                    );

                },
                0
            );

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-standard-entry-grid';

        enchantEntries.forEach(
            function (enchant) {

                var chance =
                    totalWeight > 0
                        ? (
                            enchant.weight /
                            totalWeight
                        ) * 100
                        : 0;

                var card =
                    createStandardCard(
                        enchant,
                        function () {

                            renderEnchantDetail(
                                content,
                                enchant,
                                chance,
                                totalWeight
                            );

                        }
                    );

                var chanceLabel =
                    document.createElement(
                        'div'
                    );

                chanceLabel.className =
                    'wiki-standard-card-extra';

                chanceLabel.textContent =
                    formatPercent(
                        chance
                    );

                card.appendChild(
                    chanceLabel
                );

                grid.appendChild(
                    card
                );

            }
        );

        content.appendChild(
            grid
        );

    }

