                getWikiImageUrl(
                    entry.image
                );

            image.alt =
                entry.name;

            card.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'div'
            );

        name.className =
            'wiki-standard-entry-name';

        name.textContent =
            entry.name;

        if (entry.rarity) {

            applyRarityClass(
                name,
                entry.rarity
            );

        }

        card.appendChild(
            name
        );

        if (entry.rarity) {

            var rarity =
                document.createElement(
