                );

            image.className =
                'wiki-fish-card-image';

            image.src =
                getWikiImageUrl(
                    fish.image
                );

            image.alt =
                fish.name;

            card.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'div'
            );

        name.className =
            'wiki-fish-card-name';

        name.textContent =
            fish.name;

        applyRarityClass(
            name,
            fish.rarity
        );

        card.appendChild(
            name
        );

        if (
            fish.rarity
        ) {

            var rarity =
                createRarityDisplay(
                    fish.rarity,
                    'wiki-fish-card-rarity'
                );

            if (
                rarity
            ) {

                card.appendChild(
                    rarity
                );

            }

        }

        var chanceText =
            document.createElement(
                'div'
            );

        chanceText.className =
            'wiki-fish-card-chance';

        chanceText.textContent =
            formatPercent(
                chance
            );

        card.appendChild(
            chanceText
        );

        card.addEventListener(
            'click',
            function () {

                var body =
                    document.querySelector(
                        '#fish-entries-app .wiki-entry-items-body'
                    );

                if (
                    !body
                ) {
                    return;
                }

                renderFishDetail(
                    body,
                    fish,
                    location,
                    weight,
                    chance,
                    totalWeight
                );

            }
        );

        return card;

    }

