                    chance
                )
            )
        );

        stats.appendChild(
            createStat(
                'Weight',
                formatNumber(
                    weight
                )
            )
        );

        if (
            fish.baseSellPrice !==
            ''
        ) {

            stats.appendChild(
                createStat(
                    'Base Sell',
