                );

            image.alt =
                fish.name;

            card.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'div'
            );

        name.className =
            'wiki-fish-card-name';

        name.textContent =
            fish.name;

        applyRarityClass(
            name,
            fish.rarity
        );

        card.appendChild(
