    function renderEnchantsSection(
        content
    ) {

        createSectionTitle(
            content,
            'Enchants'
        );

        if (
            !enchantEntries.length
        ) {

            content.appendChild(
                createEmptyMessage(
                    'No Enchant entries have been published yet.'
                )
            );

            return;

        }

        var totalWeight =
            enchantEntries.reduce(
                function (
                    total,
                    enchant
                ) {

                    return (
                        total +
                        (
                            Number(
                                enchant.weight
                            ) ||
                            0
                        )
                    );

                },
                0
            );

        var sortedEnchants =
            enchantEntries
                .slice()
                .sort(function (
                    a,
                    b
                ) {

                    if (
                        b.weight !==
                        a.weight
                    ) {

                        return (
                            b.weight -
                            a.weight
                        );

                    }

                    return sortByName(
                        a,
                        b
                    );

                });

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-standard-entry-grid';

        sortedEnchants.forEach(
            function (enchant) {

                var chance =
                    totalWeight > 0
                        ? (
                            enchant.weight /
                            totalWeight
                        ) * 100
                        : 0;

                var card =
                    createStandardCard(
                        enchant,
                        function () {

                            renderEnchantDetail(
                                content,
                                enchant,
                                chance,
                                totalWeight
                            );

                        }
                    );

                var chanceLabel =
                    document.createElement(
                        'div'
                    );

                chanceLabel.className =
                    'wiki-standard-card-extra';

                chanceLabel.textContent =
                    formatPercent(
                        chance
                    );

                card.appendChild(
                    chanceLabel
                );

                grid.appendChild(
                    card
                );

            }
        );

        content.appendChild(
            grid
        );

    }

    function createStandardCard(
        entry,
        onClick
    ) {

        var card =
            document.createElement(
                'button'
            );

        card.type =
            'button';

        card.className =
            'wiki-standard-entry-card';

        if (
            entry.image
        ) {

            var image =
                document.createElement(
                    'img'
                );

            image.src =
                getWikiImageUrl(
                    entry.image
                );

            image.alt =
                entry.name;

            card.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'div'
            );

        name.className =
            'wiki-standard-entry-name';

        name.textContent =
            entry.name;

        if (
            entry.rarity
        ) {

            applyRarityClass(
                name,
                entry.rarity
            );

        }

        card.appendChild(
            name
        );

        if (
            entry.rarity
        ) {

            var rarity =
                createRarityDisplay(
                    entry.rarity,
                    'wiki-standard-entry-rarity'
                );

            if (
                rarity
            ) {

                card.appendChild(
                    rarity
                );

            }

        }

        card.addEventListener(
            'click',
            onClick
        );

        return card;

    }

    function renderStandardDetail(
        body,
        entry,
        type
    ) {

        body.innerHTML =
            '';

        var detail =
            document.createElement(
                'div'
            );

        detail.className =
            'wiki-entry-detail';

        detail.appendChild(
            createBackButton(
                function () {

                    if (
                        type ===
                        'Bait'
                    ) {

                        renderBaits(
                            body
                        );

                    }

                }
            )
        );

        appendDetailBasicInfo(
            detail,
            entry
        );

        body.appendChild(
            detail
        );

    }

