    function renderEnchantsSection(
        content
    ) {

        createSectionTitle(
            content,
            'Enchants'
        );

        if (
            !enchantEntries.length
        ) {

            content.appendChild(
                createEmptyMessage(
                    'No Enchant entries have been published yet.'
                )
            );

            return;

        }

        var totalWeight =
            enchantEntries.reduce(
                function (
                    total,
                    enchant
                ) {

                    return (
                        total +
                        (
                            Number(
                                enchant.weight
                            ) ||
                            0
                        )
                    );

                },
                0
            );

        var sortedEnchants =
            enchantEntries
                .slice()
                .sort(function (
                    a,
                    b
                ) {

                    if (
                        a.weight !==
                        b.weight
                    ) {

                        return (
                            a.weight -
                            b.weight
                        );

                    }

                    return sortByName(
                        a,
                        b
                    );

                });

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-standard-entry-grid';

        sortedEnchants.forEach(
            function (enchant) {

                var chance =
                    totalWeight > 0
                        ? (
                            enchant.weight /
                            totalWeight
                        ) * 100
                        : 0;

                var card =
                    createStandardCard(
                        enchant,
                        function () {

                            renderEnchantDetail(
                                content,
                                enchant,
                                chance,
                                totalWeight
                            );

                        }
                    );

                var chanceLabel =
                    document.createElement(
                        'div'
                    );

                chanceLabel.className =
                    'wiki-standard-card-extra';

                chanceLabel.textContent =
                    formatPercent(
                        chance
                    );

                card.appendChild(
                    chanceLabel
                );

                grid.appendChild(
                    card
                );

            }
        );

        content.appendChild(
            grid
        );

    }

