    function injectRarityStyles() {

        var old =
            document.getElementById(
                'wiki-dynamic-rarity-styles'
            );

        if (
            old
        ) {
            old.remove();
        }

        var css = '';

        Object.keys(
            rarityEntries
        )
            .forEach(function (key) {

                var rarity =
                    rarityEntries[
                        key
                    ];

                var slug =
                    makeSlug(
                        rarity.name
                    );

                var animation =
                    'wiki-rarity-' +
                    slug;

                css +=
                    '@keyframes ' +
                    animation +
                    '{' +
                    '0%{color:' +
                    rarity.color0 +
                    ';}' +
                    '50%{color:' +
                    rarity.color50 +
                    ';}' +
                    '100%{color:' +
                    rarity.color100 +
                    ';}' +
                    '}';

                css +=
                    '.wiki-dynamic-rarity-' +
                    slug +
                    '{animation:' +
                    animation +
                    ' 3s ease-in-out infinite !important;}';

            });

        var style =
            document.createElement(
                'style'
            );

        style.id =
            'wiki-dynamic-rarity-styles';

        style.textContent =
            css;

        document.head.appendChild(
            style
        );

    }

    function applyRarityClass(
        element,
        rarity
    ) {

        rarity =
            String(
                rarity || ''
            ).trim();

        if (
            !rarity
        ) {
            return;
        }

        var slug =
            makeSlug(
                rarity
            );

        element.classList.add(
            'entry-name-rarity-' +
            slug
        );

        if (
            rarityEntries[
                rarity.toLowerCase()
            ]
        ) {

            element.classList.add(
                'wiki-dynamic-rarity-' +
                slug
            );

        }

    }

    function applyRarityBorderClass(
        element,
        rarity
    ) {

        rarity =
            String(
                rarity || ''
            ).trim();

        if (
            !rarity
        ) {
            return;
        }

        var rarityData =
            rarityEntries[
                rarity.toLowerCase()
            ];

        if (
            !rarityData
        ) {
            return;
        }

        element.classList.add(
            'wiki-rarity-animated-border'
        );

        element.style.setProperty(
            '--rarity-border-color-0',
            rarityData.color0
        );

        element.style.setProperty(
            '--rarity-border-color-50',
            rarityData.color50
        );

    }

    function makeSlug(
        value
    ) {

        return String(
            value || ''
        )
            .toLowerCase()
            .trim()
            .replace(
                /[^a-z0-9]+/g,
                '-'
            )
            .replace(
                /^-+|-+$/g,
                ''
            );

    }

    function normalizeHexColor(
        value
    ) {

        value =
            String(
                value || ''
            )
                .trim()
                .toLowerCase();

        if (
            /^[0-9a-f]{6}$/i.test(
                value
            )
        ) {

            value =
                '#' +
                value;

        }

        if (
            /^#[0-9a-f]{6}$/i.test(
                value
            )
        ) {

            return value;

        }

        return '';

    }

    function getWikiImageUrl(
        filename
    ) {

        filename =
            String(
                filename || ''
            )
                .replace(
                    /^File:/i,
                    ''
                )
                .trim();

        return mw.util.getUrl(
            'Special:Redirect/file/' +
            filename
        );

    }

    function getNameFromPage(
        page
    ) {

        page =
            String(
                page || ''
            );

        var separator =
            page.indexOf(
                ':'
            );

        if (
            separator !==
            -1
        ) {

            return page
                .slice(
                    separator + 1
                )
                .trim();

        }

        return page.trim();

    }

    function sortByName(
        a,
        b
    ) {

        return String(
            a.name || ''
        ).localeCompare(
            String(
                b.name || ''
            ),
            undefined,
            {
                sensitivity:
                    'base'
            }
        );

    }

    function formatPercent(
        value
    ) {

        value =
            Number(
                value
            );

        if (
            !isFinite(
                value
            )
        ) {

            return '0%';

        }

        if (
            value >= 10
        ) {

            return (
                value
                    .toFixed(2)
                    .replace(
                        /\.?0+$/,
                        ''
                    ) +
                '%'
            );

        }

        if (
            value >= 1
        ) {

            return (
                value
                    .toFixed(3)
                    .replace(
                        /\.?0+$/,
                        ''
                    ) +
                '%'
            );

        }

        return (
            value
                .toFixed(6)
                .replace(
                    /\.?0+$/,
                    ''
                ) +
            '%'
        );

    }

    function formatNumber(
        value
    ) {

        value =
            Number(
                value
            );

        if (
            !isFinite(
                value
            )
        ) {

            return '0';

        }

        return value.toLocaleString();

    }

    function decodeTemplateValue(
        value
    ) {

        return String(
            value || ''
        )
            .replace(
                /&#124;/g,
                '|'
            )
            .replace(
                /&#123;&#123;/g,
                '{{'
            )
            .replace(
                /&#125;&#125;/g,
                '}}'
            )
            .replace(
                /\}&#125;/g,
                '}}'
            );

    }

    function normalizeApiError(
        code,
        details
    ) {

        var error = {
            code:
                code ||
                'api-error',

            info:
                '',

            details:
                details ||
                null
        };

        if (
            details &&
            details.error
        ) {

            if (
                details.error.code
            ) {

                error.code =
                    details.error.code;

            }

            if (
                details.error.info
            ) {

                error.info =
                    details.error.info;

            }

        }

        if (
            !error.info &&
            details &&
            details.info
        ) {

            error.info =
                details.info;

        }

        if (
            !error.info &&
            typeof details ===
            'string'
        ) {

            error.info =
                details;

        }

        if (
            !error.info
        ) {

            error.info =
                'MediaWiki returned an API error.';

        }

        return error;

    }

    function formatError(
        error
    ) {

        if (
            !error
        ) {

            return 'Unknown error.';

        }

        if (
            typeof error ===
            'string'
        ) {

            return error;

        }

        if (
            error.code &&
            error.info
        ) {

            return (
                error.code +
                ': ' +
                error.info
            );

        }

        return (
            error.info ||
            error.code ||
            error.message ||
            'Unknown error.'
        );

    }

    function escapeHtml(
        value
    ) {

        return String(
            value || ''
        )
            .replace(
                /&/g,
                '&amp;'
            )
            .replace(
                /</g,
                '&lt;'
            )
            .replace(
                />/g,
                '&gt;'
            )
            .replace(
                /"/g,
                '&quot;'
            )
            .replace(
                /'/g,
                '&#039;'
            );

    }

})();

(function () {
    var ENTRIES_PAGE = 'Fish_entries:sandbox';

    var CATEGORIES = {
        Fish: 'Category:Fish Entries',
        Bait: 'Category:Bait Entries',
        Tool: 'Category:Tool Entries',
        Enchant: 'Category:Enchant Entries',
        Location: 'Category:Fish Locations',
        Rarity: 'Category:Rarity Entries'
    };

    var SIDE_ICONS = {
        Items: 'Ball.png',
        Tools: 'Fishing_Rod.png',
        Enchants: 'strength.png'
    };

    var locations = [];
    var fishEntries = [];
    var baitEntries = [];
    var toolEntries = [];
    var enchantEntries = [];
    var rarityEntries = {};

    var currentSection = null;
    var currentItemTab = 'Fish';
    var currentLocation = null;

    var CHANCE_DISPLAY_STORAGE_KEY =
        'fishIslandEntriesChanceDisplay';

    var chanceDisplayMode =
        localStorage.getItem(
            CHANCE_DISPLAY_STORAGE_KEY
        ) || 'percent';

    if (
        chanceDisplayMode !== 'percent' &&
        chanceDisplayMode !== 'fraction'
    ) {
        chanceDisplayMode = 'percent';
    }

    $(function () {
        if (
            normalizePageName(
                mw.config.get('wgPageName')
            ) !==
            normalizePageName(
                ENTRIES_PAGE
            )
        ) {
            return;
        }

        var container =
            document.getElementById(
                'fish-entries-app'
            );

        if (!container) {
            return;
        }

        if (
            container.dataset.loaded ===
            'true'
        ) {
            return;
        }

        container.dataset.loaded =
            'true';

        container.innerHTML =
            '<div class="entries-app-loading">Loading entries...</div>';

        loadMediaWikiModules()
            .then(function () {
                return Promise.all([
                    loadLocations(),
                    loadFish(),
                    loadBaits(),
                    loadTools(),
                    loadEnchants(),
                    loadRarities()
                ]);
            })
            .then(function () {
                injectRarityStyles();
                buildEntriesApp(
                    container
                );
            })
            .catch(function (error) {
                console.error(
                    'Fish Entries App Error:',
                    error
                );

                container.innerHTML =
                    '<div class="entries-app-error">' +
                    escapeHtml(
                        formatError(
                            error
                        )
                    ) +
                    '</div>';
            });
    });

    function normalizePageName(value) {
        return String(
            value || ''
        )
            .replace(
                /_/g,
                ' '
            )
            .replace(
                /\s+/g,
                ' '
            )
            .trim()
            .toLowerCase();
    }

    function loadMediaWikiModules() {
        return mw.loader.using([
            'mediawiki.api',
            'mediawiki.util'
        ]);
    }

    function loadLocations() {
        var api =
            new mw.Api();

        return getCategoryEntryPages(
            api,
            CATEGORIES.Location,
            'Location'
        ).then(function (entries) {
            locations =
                entries.map(
                    function (entry) {
                        return {
                            page:
                                entry.page,

                            name:
                                entry.data.name ||
                                getNameFromPage(
                                    entry.page
                                ),

                            image:
                                entry.data.image ||
                                ''
                        };
                    }
                );

            locations.sort(
                sortByName
            );
        });
    }

    function loadFish() {
        var api =
