    z-index: 2000;

    width: 280px;
    max-width: calc(100% - 20px);

    padding: 16px;

    background: rgba(7, 18, 43, 0.98);
    border: 2px solid #5aaeff;
    border-radius: 16px;

    box-shadow: 0 10px 30px rgba(0,0,0,.45);

    box-sizing: border-box;
}

#fish-entries-app .wiki-entries-settings-menu.menu-open {
    display: block;
}

#fish-entries-app .wiki-entries-settings-title {
    margin-bottom: 16px;

    color: #ffffff;
    font-size: 22px;
    font-weight: bold;
    text-align: center;
}

#fish-entries-app .wiki-entries-settings-label {
    margin-bottom: 9px;

    color: #7eb5ff;

    font-size: 13px;
    font-weight: bold;

    letter-spacing: 0.04em;
    text-transform: uppercase;
}

#fish-entries-app .wiki-chance-display-options {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

#fish-entries-app .wiki-chance-display-option {
    width: 100%;

    padding: 11px 14px;

    background: #0b0f17;

    border: 2px solid #222831;
    border-radius: 10px;

    color: #ffffff;

    font-size: 16px;
