    function applyRarityClass(
        element,
        rarity
    ) {
        rarity =
            String(
                rarity || ''
            ).trim();

        if (!rarity) {
            return;
        }

        var slug =
            makeSlug(
                rarity
            );

        element.classList.add(
            'entry-name-rarity-' +
            slug
        );

        if (
            rarityEntries[
                rarity.toLowerCase()
            ]
        ) {
            element.classList.add(
                'wiki-dynamic-rarity-' +
                slug
            );
        }
    }

    function makeSlug(
        value
    ) {
        return String(
            value || ''
        )
            .toLowerCase()
            .trim()
            .replace(
                /[^a-z0-9]+/g,
                '-'
            )
            .replace(
                /^-+|-+$/g,
                ''
            );
    }

    function normalizeHexColor(
        value
    ) {
        value =
            String(
                value || ''
            )
                .trim()
                .toLowerCase();

        if (
            /^[0-9a-f]{6}$/i.test(
                value
            )
        ) {
            value =
                '#' +
                value;
        }

        if (
            /^#[0-9a-f]{6}$/i.test(
                value
            )
        ) {
            return value;
        }

        return '';
    }

    function getWikiImageUrl(
        filename
    ) {
        filename =
            String(
                filename || ''
            )
                .replace(
                    /^File:/i,
                    ''
                )
                .trim();

        return mw.util.getUrl(
            'Special:Redirect/file/' +
            filename
        );
    }

    function getNameFromPage(
        page
    ) {
        page =
            String(
                page || ''
            );

        var separator =
            page.indexOf(':');

        if (
            separator !==
            -1
        ) {
            return page
                .slice(
                    separator + 1
                )
                .trim();
        }

        return page.trim();
    }

    function sortByName(
        a,
        b
    ) {
        return String(
            a.name || ''
        ).localeCompare(
            String(
                b.name || ''
            ),
            undefined,
            {
                sensitivity:
                    'base'
            }
        );
    }

    function formatChance(
        value
    ) {
        if (
            chanceDisplayMode ===
            'fraction'
        ) {
            return formatOneInChance(
                value
            );
        }

        return formatPercent(
            value
        );
    }

    function formatPercent(
        value
    ) {
        value =
            Number(
                value
            );

        if (
            !isFinite(
                value
            )
        ) {
            return '0%';
        }

        if (
            value >= 10
        ) {
            return (
                value
                    .toFixed(2)
                    .replace(
                        /\.?0+$/,
                        ''
                    ) +
                '%'
            );
        }

        if (
            value >= 1
        ) {
            return (
                value
                    .toFixed(3)
                    .replace(
                        /\.?0+$/,
                        ''
                    ) +
                '%'
            );
        }

        return (
            value
                .toFixed(6)
                .replace(
                    /\.?0+$/,
                    ''
                ) +
            '%'
        );
    }

    function formatOneInChance(
        chancePercent
    ) {
        chancePercent =
            Number(
                chancePercent
            );

        if (
            !isFinite(
                chancePercent
            ) ||
            chancePercent <= 0
        ) {
            return '1/∞';
        }

        var oneIn =
            100 /
            chancePercent;

        var nearestInteger =
            Math.round(
                oneIn
            );

        if (
            Math.abs(
                oneIn -
                nearestInteger
            ) <
            0.000001
        ) {
            return (
                '1/' +
                nearestInteger.toLocaleString()
            );
        }

        return (
            '1/' +
            oneIn.toLocaleString(
                undefined,
                {
                    minimumFractionDigits:
                        0,

                    maximumFractionDigits:
                        2
                }
            )
        );
    }

    function formatNumber(
        value
    ) {
        value =
            Number(
                value
            );

        if (
            !isFinite(
                value
            )
        ) {
            return '0';
        }

        return value.toLocaleString();
    }

    function decodeTemplateValue(
        value
    ) {
        return String(
            value || ''
        )
            .replace(
                /&#124;/g,
                '|'
            )
            .replace(
                /&#123;&#123;/g,
                '{{'
            )
            .replace(
                /&#125;&#125;/g,
                '}}'
            )
            .replace(
                /\}&#125;/g,
                '}}'
            );
    }

    function normalizeApiError(
        code,
        details
    ) {
        var error = {
            code:
                code ||
                'api-error',

            info:
                '',

            details:
                details ||
                null
        };

        if (
            details &&
            details.error
        ) {
            if (
                details.error.code
            ) {
                error.code =
                    details.error.code;
            }

            if (
                details.error.info
            ) {
                error.info =
                    details.error.info;
            }
        }

        if (
            !error.info &&
            details &&
            details.info
        ) {
            error.info =
                details.info;
        }

        if (
            !error.info &&
            typeof details ===
            'string'
        ) {
            error.info =
                details;
        }

        if (
            !error.info
        ) {
            error.info =
                'MediaWiki returned an API error.';
        }

        return error;
    }

    function formatError(
        error
    ) {
        if (!error) {
            return 'Unknown error.';
        }

        if (
            typeof error ===
            'string'
        ) {
            return error;
        }

        if (
            error.code &&
            error.info
        ) {
            return (
                error.code +
                ': ' +
                error.info
            );
        }

        return (
            error.info ||
            error.code ||
            error.message ||
            'Unknown error.'
        );
    }

    function escapeHtml(
        value
    ) {
        return String(
            value || ''
        )
            .replace(
                /&/g,
                '&amp;'
            )
            .replace(
                /</g,
                '&lt;'
            )
            .replace(
                />/g,
                '&gt;'
            )
            .replace(
                /"/g,
                '&quot;'
            )
            .replace(
                /'/g,
                '&#039;'
            );
    }
})();

(function () {
    var ENTRIES_PAGE = 'Fish_entries:sandbox';

    var CATEGORIES = {
