    $(function () {
        if (
            normalizePageName(
                mw.config.get('wgPageName')
            ) !==
            normalizePageName(
                ENTRIES_PAGE
            )
        ) {
            return;
        }

        var container =
            document.getElementById(
                'fish-entries-app'
            );

        if (!container) {
            return;
        }

        if (
            container.dataset.loaded ===
            'true'
        ) {
            return;
        }

        container.dataset.loaded =
            'true';

        container.innerHTML =
            '<div class="entries-app-loading">Loading entries...</div>';

        loadMediaWikiModules()
            .then(function () {
                return Promise.all([
                    loadLocations(),
                    loadFish(),
                    loadBaits(),
                    loadTools(),
                    loadEnchants(),
                    loadRarities()
                ]);
            })
            .then(function () {
                injectRarityStyles();
                buildEntriesApp(
                    container
                );
            })
            .catch(function (error) {
                console.error(
                    'Fish Entries App Error:',
                    error
                );

                container.innerHTML =
                    '<div class="entries-app-error">' +
                    escapeHtml(
                        formatError(
                            error
                        )
                    ) +
                    '</div>';
            });
    });

    function normalizePageName(value) {
        return String(
            value || ''
        )
            .replace(
                /_/g,
                ' '
            )
            .replace(
                /\s+/g,
                ' '
            )
            .trim()
            .toLowerCase();
    }

    function loadMediaWikiModules() {
        return mw.loader.using([
            'mediawiki.api',
            'mediawiki.util'
        ]);
    }

    function loadLocations() {
        var api =
            new mw.Api();

        return getCategoryEntryPages(
            api,
            CATEGORIES.Location,
            'Location'
        ).then(function (entries) {
            locations =
                entries.map(
                    function (entry) {
                        return {
                            page:
                                entry.page,

                            name:
                                entry.data.name ||
                                getNameFromPage(
                                    entry.page
                                ),

                            image:
                                entry.data.image ||
                                ''
                        };
                    }
                );

            locations.sort(
                sortByName
            );
        });
    }

    function loadFish() {
        var api =
            new mw.Api();

        return getCategoryEntryPages(
            api,
            CATEGORIES.Fish,
            'Fish'
        ).then(function (entries) {
            fishEntries =
                entries.map(
                    function (entry) {
                        return {
                            page:
                                entry.page,

                            name:
                                entry.data.name ||
                                getNameFromPage(
                                    entry.page
                                ),

                            image:
                                entry.data.image ||
                                '',

                            rarity:
                                entry.data.rarity ||
                                '',

                            description:
                                entry.data.description ||
                                '',

                            baseSellPrice:
                                entry.data.base_sell_price ||
                                '',

                            weights:
                                parseLocationWeights(
                                    entry.data.location_weights
                                )
                        };
                    }
                );

            fishEntries.sort(
                sortByName
            );
        });
    }

    function loadBaits() {
