    function loadEnchants() {
        var api =
            new mw.Api();

        return getCategoryEntryPages(
            api,
            CATEGORIES.Enchant,
            'Enchant'
        ).then(function (entries) {
            enchantEntries =
                entries.map(
                    function (entry) {
                        return {
                            page:
                                entry.page,

                            name:
                                entry.data.name ||
                                getNameFromPage(
                                    entry.page
                                ),

                            image:
                                entry.data.image ||
