                            ).trim();

                        if (!name) {
                            return;
                        }

                        rarityEntries[
                            name.toLowerCase()
                        ] = {
                            name:
                                name,

                            color0:
                                normalizeHexColor(
                                    entry.data.color_0
                                ) ||
                                '#ffffff',

                            color50:
                                normalizeHexColor(
                                    entry.data.color_50
