    function getCategoryEntryPages(
        api,
        category,
        expectedType
    ) {
        return getAllCategoryMembers(
            api,
            category
        )
            .then(function (titles) {
                if (!titles.length) {
                    return [];
                }

                return getPagesContents(
                    api,
                    titles
                );
            })
            .then(function (pages) {
                if (!pages) {
                    return [];
                }

                var result = [];

                pages.forEach(
                    function (page) {
                        var data =
                            parseEntryData(
                                page.text
                            );

                        if (!data) {
                            return;
                        }

                        if (
                            expectedType &&
                            String(
                                data.type || ''
                            ).toLowerCase() !==
                            expectedType.toLowerCase()
                        ) {
                            return;
                        }

                        result.push({
                            page:
                                page.title,

                            data:
                                data
                        });
                    }
                );

                return result;
            });
    }

    function getAllCategoryMembers(
        api,
        category,
        cmcontinue
    ) {
        var params = {
            action:
                'query',

            list:
                'categorymembers',

            cmtitle:
                category,

            cmlimit:
                'max',

            cmtype:
                'page',

            format:
                'json',

            formatversion:
                2
        };

        if (
            cmcontinue
        ) {
            params.cmcontinue =
                cmcontinue;
        }

        return apiRequest(
            api,
            params
        )
            .then(function (response) {
                var titles = [];

                if (
                    response.query &&
                    response.query.categorymembers
                ) {
                    titles =
                        response.query
                            .categorymembers
                            .map(
                                function (page) {
                                    return page.title;
                                }
                            );
                }

                if (
                    response.continue &&
                    response.continue.cmcontinue
                ) {
                    return getAllCategoryMembers(
                        api,
                        category,
                        response.continue.cmcontinue
                    )
                        .then(function (more) {
                            return titles.concat(
                                more
                            );
                        });
                }

                return titles;
            });
    }

    function getPagesContents(
        api,
        titles
    ) {
        var chunks = [];

        for (
            var i = 0;
            i < titles.length;
            i += 50
        ) {
            chunks.push(
                titles.slice(
                    i,
                    i + 50
                )
            );
        }

        return Promise.all(
            chunks.map(
                function (chunk) {
                    return apiRequest(
                        api,
                        {
                            action:
                                'query',

                            prop:
                                'revisions',

                            titles:
                                chunk.join('|'),

                            rvprop:
                                'content',

                            rvslots:
                                'main',

                            redirects:
                                1,

                            format:
                                'json',

                            formatversion:
                                2
                        }
                    );
                }
            )
        )
            .then(function (responses) {
                var result = [];

                responses.forEach(
                    function (response) {
                        if (
                            !response.query ||
                            !response.query.pages
                        ) {
                            return;
                        }

                        response.query.pages
                            .forEach(
                                function (page) {
                                    if (
                                        page.missing ||
                                        !page.revisions ||
                                        !page.revisions.length
                                    ) {
                                        return;
                                    }

                                    var revision =
                                        page.revisions[0];

                                    var text = '';

                                    if (
                                        revision.slots &&
                                        revision.slots.main
                                    ) {
                                        text =
                                            revision.slots.main.content ||
                                            revision.slots.main['*'] ||
                                            '';
                                    } else {
                                        text =
                                            revision.content ||
                                            revision['*'] ||
                                            '';
                                    }

                                    result.push({
                                        title:
                                            page.title,

                                        text:
                                            text
                                    });
                                }
                            );
                    }
                );

                return result;
            });
    }

    function apiRequest(
        api,
        params
    ) {
        return new Promise(
            function (
                resolve,
                reject
            ) {
                api.get(
                    params
                )
                    .done(
                        function (response) {
                            resolve(
                                response
                            );
                        }
                    )
                    .fail(
                        function (
                            code,
                            details
                        ) {
                            reject(
                                normalizeApiError(
                                    code,
                                    details
                                )
                            );
                        }
                    );
            }
        );
    }

    function parseEntryData(
        text
    ) {
        var match =
            String(
                text || ''
            ).match(
                /\{\{\s*EntryData\b([\s\S]*?)\n?\}\}/i
            );

        if (!match) {
            return null;
        }

        var data = {};
        var currentKey = null;

        match[1]
            .split(
                /\r?\n/
            )
            .forEach(
                function (line) {
                    var parameter =
                        line.match(
                            /^\s*\|\s*([^=]+?)\s*=\s*(.*)$/
                        );

                    if (
                        parameter
                    ) {
                        currentKey =
                            parameter[1]
                                .trim()
                                .toLowerCase();

                        data[
                            currentKey
                        ] =
                            decodeTemplateValue(
                                parameter[2]
                                    .trim()
                            );

                        return;
                    }

                    if (
                        currentKey &&
                        line.trim()
                    ) {
                        data[
                            currentKey
                        ] +=
                            '\n' +
                            line.trim();
                    }
                }
            );

        return data;
    }

    function parseLocationWeights(
        value
    ) {
        var result = [];

        String(
            value || ''
        )
            .split(';')
            .forEach(
                function (part) {
                    part =
                        part.trim();

                    if (!part) {
                        return;
                    }

                    var separator =
                        part.lastIndexOf(':');

                    if (
                        separator ===
                        -1
                    ) {
                        return;
                    }

                    var location =
                        part
                            .slice(
                                0,
                                separator
                            )
                            .trim();

                    var weight =
                        Number(
                            part
                                .slice(
                                    separator +
                                    1
                                )
                                .trim()
                        );

                    if (
                        !location ||
                        !isFinite(
                            weight
                        ) ||
                        weight <= 0
                    ) {
                        return;
                    }

                    result.push({
                        location:
                            location,

                        weight:
                            weight
                    });
                }
            );

        return result;
    }

    function getFishWeightForLocation(
        fish,
        locationName
    ) {
        var target =
            String(
                locationName || ''
            )
                .trim()
                .toLowerCase();

        for (
            var i = 0;
            i < fish.weights.length;
            i++
        ) {
            if (
                String(
                    fish.weights[i].location
                )
                    .trim()
                    .toLowerCase() ===
                target
            ) {
                return Number(
                    fish.weights[i].weight
                ) || 0;
            }
        }

        return 0;
    }

    function getFishForLocation(
        locationName
    ) {
        var result = [];
        var totalWeight = 0;

        fishEntries.forEach(
            function (fish) {
                var weight =
                    getFishWeightForLocation(
                        fish,
                        locationName
                    );

                if (
                    weight <= 0
                ) {
                    return;
                }

                totalWeight +=
                    weight;

                result.push({
                    fish:
                        fish,

                    weight:
                        weight,

                    chance:
                        0
                });
            }
        );

        result.forEach(
            function (entry) {
                entry.chance =
                    totalWeight > 0
                        ? (
                            entry.weight /
                            totalWeight
                        ) * 100
                        : 0;
            }
        );

        result.sort(
            function (
                a,
                b
            ) {
                if (
                    b.chance !==
                    a.chance
                ) {
                    return (
                        b.chance -
                        a.chance
                    );
                }

                return a.fish.name
                    .localeCompare(
                        b.fish.name,
                        undefined,
                        {
                            sensitivity:
                                'base'
                        }
                    );
            }
        );

        return {
            entries:
                result,

            totalWeight:
                totalWeight
        };
    }

    function buildEntriesApp(
        container
    ) {
        container.innerHTML =
            '';

        var shell =
            document.createElement(
                'div'
            );

        shell.className =
            'wiki-entries-shell wiki-entries-start';

        var nav =
            document.createElement(
                'div'
            );

        nav.className =
            'wiki-entries-nav';

        var content =
            document.createElement(
                'div'
            );

        content.className =
            'wiki-entries-content';

        content.style.display =
            'none';

        shell.appendChild(
            nav
        );

        shell.appendChild(
            content
        );

        container.appendChild(
            shell
        );

        createSettingsMenu(
            shell
        );

        createNavButton(
            nav,
            'Items',
            SIDE_ICONS.Items
        );

        createNavButton(
            nav,
            'Tools',
            SIDE_ICONS.Tools
        );

        createNavButton(
            nav,
            'Enchants',
            SIDE_ICONS.Enchants
        );
    }

    function createSettingsMenu(
        shell
    ) {
        var menuButton =
            document.createElement(
                'button'
            );

        menuButton.type =
            'button';

        menuButton.className =
            'wiki-entries-menu-button';

        menuButton.textContent =
            '☰';

        menuButton.title =
            'Settings';

        menuButton.setAttribute(
            'aria-label',
            'Open settings'
        );

        var menu =
            document.createElement(
                'div'
            );

        menu.className =
            'wiki-entries-settings-menu';

        var title =
            document.createElement(
                'div'
            );

        title.className =
            'wiki-entries-settings-title';

        title.textContent =
            'Settings';

        menu.appendChild(
            title
        );

        var chanceTitle =
            document.createElement(
                'div'
            );

        chanceTitle.className =
            'wiki-entries-settings-label';

        chanceTitle.textContent =
            'Chance Display';

        menu.appendChild(
            chanceTitle
        );

        var options =
            document.createElement(
                'div'
            );

        options.className =
            'wiki-chance-display-options';

        options.appendChild(
            createChanceOption(
                'percent',
                'Percentage'
            )
        );

        options.appendChild(
            createChanceOption(
                'fraction',
                '1/x'
            )
        );

        menu.appendChild(
            options
        );

        var help =
            document.createElement(
                'div'
            );

        help.className =
            'wiki-entries-settings-help';

        help.textContent =
            'This only changes how chances are displayed. Weights are not changed.';

        menu.appendChild(
            help
        );

        shell.appendChild(
            menuButton
        );

        shell.appendChild(
            menu
        );

        menuButton.addEventListener(
            'click',
            function (event) {
                event.preventDefault();
                event.stopPropagation();

                menu.classList.toggle(
                    'menu-open'
                );
            }
        );

        menu.addEventListener(
            'click',
            function (event) {
                event.stopPropagation();
            }
        );

        document.addEventListener(
            'click',
            function () {
                menu.classList.remove(
                    'menu-open'
                );
            }
        );

        updateChanceButtons();
    }

    function createChanceOption(
        mode,
        text
    ) {
        var button =
            document.createElement(
                'button'
            );

        button.type =
            'button';

        button.className =
            'wiki-chance-display-option';

        button.setAttribute(
            'data-chance-mode',
            mode
        );

        var radio =
            document.createElement(
                'span'
            );

        radio.className =
            'wiki-chance-radio';

        var label =
            document.createElement(
                'span'
            );

        label.textContent =
            text;

        button.appendChild(
            radio
        );

        button.appendChild(
            label
        );

        button.addEventListener(
            'click',
            function () {
                setChanceDisplayMode(
                    mode
                );
            }
        );

        return button;
    }

    function setChanceDisplayMode(
        mode
    ) {
        if (
            mode !== 'percent' &&
            mode !== 'fraction'
        ) {
            return;
        }

        chanceDisplayMode =
            mode;

        localStorage.setItem(
            CHANCE_DISPLAY_STORAGE_KEY,
            mode
        );

        updateChanceButtons();
        refreshChanceDisplays();
    }

    function updateChanceButtons() {
        document
            .querySelectorAll(
                '#fish-entries-app .wiki-chance-display-option'
            )
            .forEach(
                function (button) {
                    button.classList.toggle(
                        'chance-active',
                        button.getAttribute(
                            'data-chance-mode'
                        ) ===
                        chanceDisplayMode
                    );
                }
            );
    }

    function refreshChanceDisplays() {
        document
            .querySelectorAll(
                '#fish-entries-app [data-chance-percent]'
            )
            .forEach(
                function (element) {
                    var chance =
                        Number(
                            element.getAttribute(
                                'data-chance-percent'
                            )
                        );

                    if (
                        !isFinite(
                            chance
                        )
                    ) {
                        return;
                    }

                    element.textContent =
                        formatChance(
                            chance
                        );
                }
            );
    }

    function createNavButton(
        container,
        section,
        imageName
    ) {
        var button =
            document.createElement(
                'button'
            );

        button.type =
            'button';

        button.className =
            'wiki-entry-nav-pill';

        button.setAttribute(
            'data-entry-section',
            section
        );

        var image =
            document.createElement(
                'img'
            );

        image.src =
            getWikiImageUrl(
                imageName
            );

        image.alt =
            section;

        var label =
            document.createElement(
                'span'
            );

        label.textContent =
            section;

        button.appendChild(
            image
        );

        button.appendChild(
            label
        );

        button.addEventListener(
            'click',
            function () {
                currentSection =
                    section;

                currentLocation =
                    null;

                var shell =
                    document.querySelector(
                        '#fish-entries-app .wiki-entries-shell'
                    );

                var content =
                    document.querySelector(
                        '#fish-entries-app .wiki-entries-content'
                    );

                if (
                    shell
                ) {
                    shell.classList.remove(
                        'wiki-entries-start'
                    );

                    shell.classList.add(
                        'wiki-entries-open'
                    );
                }

                if (
                    content
                ) {
                    content.style.display =
                        'block';
                }

                updateNavButtons();
                renderCurrentSection();
            }
        );
    }

    function updateNavButtons() {
        document
            .querySelectorAll(
                '#fish-entries-app .wiki-entry-nav-pill'
            )
            .forEach(
                function (button) {
                    var section =
                        button.getAttribute(
                            'data-entry-section'
                        );

                    button.classList.toggle(
                        'entry-active',
                        section ===
                        currentSection
                    );
                }
            );
    }

    function renderCurrentSection() {
        updateNavButtons();

        var content =
            document.querySelector(
                '#fish-entries-app .wiki-entries-content'
            );

        if (
            !content
        ) {
            return;
        }

        content.innerHTML =
            '';

        if (
            currentSection ===
            'Items'
        ) {
            renderItemsSection(
                content
            );

            return;
        }

        if (
            currentSection ===
            'Tools'
        ) {
            renderToolsSection(
                content
            );

            return;
        }

        if (
            currentSection ===
            'Enchants'
        ) {
            renderEnchantsSection(
                content
            );
        }
    }

    function createSectionTitle(
        container,
        text
    ) {
        var title =
            document.createElement(
                'div'
            );

        title.className =
            'wiki-entry-content-title';

        title.textContent =
            text;

        container.appendChild(
            title
        );
    }

    function renderItemsSection(
        content
    ) {
        createSectionTitle(
            content,
            'Items'
        );

        var tabs =
            document.createElement(
                'div'
            );

        tabs.className =
            'wiki-entry-subtabs';

        var fishButton =
            createSubtabButton(
                'Fish'
            );

        var baitButton =
            createSubtabButton(
                'Baits'
            );

        tabs.appendChild(
            fishButton
        );

        tabs.appendChild(
            baitButton
        );

        content.appendChild(
            tabs
        );

        var body =
            document.createElement(
                'div'
            );

        body.className =
            'wiki-entry-items-body';

        content.appendChild(
            body
        );

        fishButton.addEventListener(
            'click',
            function () {
                currentItemTab =
                    'Fish';

                currentLocation =
                    null;

                updateItemTabs(
                    fishButton,
                    baitButton
                );

                renderFishLocations(
                    body
                );
            }
        );

        baitButton.addEventListener(
            'click',
            function () {
                currentItemTab =
                    'Baits';

                currentLocation =
                    null;

                updateItemTabs(
                    fishButton,
                    baitButton
                );

                renderBaits(
                    body
                );
            }
        );

        updateItemTabs(
            fishButton,
            baitButton
        );

        if (
            currentItemTab ===
            'Baits'
        ) {
            renderBaits(
                body
            );
        } else {
            renderFishLocations(
                body
            );
        }
    }

    function createSubtabButton(
        text
    ) {
        var button =
            document.createElement(
                'button'
            );

        button.type =
            'button';

        button.className =
            'wiki-entry-subtab';

        button.textContent =
            text;

        return button;
    }

    function updateItemTabs(
        fishButton,
        baitButton
    ) {
        fishButton.classList.toggle(
            'entry-active',
            currentItemTab ===
            'Fish'
        );

        baitButton.classList.toggle(
            'entry-active',
            currentItemTab ===
            'Baits'
        );
    }

    function renderFishLocations(
        body
    ) {
        body.innerHTML =
            '';

        if (
            currentLocation
        ) {
            renderLocationFish(
                body,
                currentLocation
            );

            return;
        }

        if (
            !locations.length
        ) {
            body.appendChild(
                createEmptyMessage(
                    'No locations have been published yet.'
                )
            );

            return;
        }

        var title =
            document.createElement(
                'div'
            );

        title.className =
            'wiki-location-label';

        title.textContent =
            'Locations';

        body.appendChild(
            title
        );

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-location-grid';

        locations.forEach(
            function (location) {
                var button =
                    document.createElement(
                        'button'
                    );

                button.type =
                    'button';

                button.className =
                    'wiki-location-pill';

                if (
                    location.image
                ) {
                    var image =
                        document.createElement(
                            'img'
                        );

                    image.src =
                        getWikiImageUrl(
                            location.image
                        );

                    image.alt =
                        location.name;

                    button.appendChild(
                        image
                    );
                }

                var name =
                    document.createElement(
                        'div'
                    );

                name.className =
                    'wiki-location-name';

                name.textContent =
                    location.name;

                button.appendChild(
                    name
                );

                button.addEventListener(
                    'click',
                    function () {
                        currentLocation =
                            location;

                        renderFishLocations(
                            body
                        );
                    }
                );

                grid.appendChild(
                    button
                );
            }
        );

        body.appendChild(
            grid
        );
    }

    function renderLocationFish(
        body,
        location
    ) {
        body.innerHTML =
            '';

        var header =
            document.createElement(
                'div'
            );

        header.className =
            'wiki-location-header';

        var title =
            document.createElement(
                'div'
            );

        title.className =
            'wiki-location-header-title';

        if (
            location.image
        ) {
            var image =
                document.createElement(
                    'img'
                );

            image.src =
                getWikiImageUrl(
                    location.image
                );

            image.alt =
                location.name;

            title.appendChild(
                image
            );
        }

        var name =
            document.createElement(
                'span'
            );

        name.textContent =
            location.name;

        title.appendChild(
            name
        );

        var back =
            document.createElement(
                'button'
            );

        back.type =
            'button';

        back.className =
            'wiki-entry-back';

        back.textContent =
            'Back';

        back.addEventListener(
            'click',
            function () {
                currentLocation =
                    null;

                renderFishLocations(
                    body
                );
            }
        );

        header.appendChild(
            title
        );

        header.appendChild(
            back
        );

        body.appendChild(
            header
        );

        var calculated =
            getFishForLocation(
                location.name
            );

        if (
            !calculated.entries.length
        ) {
            body.appendChild(
                createEmptyMessage(
                    'No fish can currently be caught here.'
                )
            );

            return;
        }

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-fish-grid';

        calculated.entries
            .forEach(
                function (entry) {
                    grid.appendChild(
                        createFishCard(
                            entry.fish,
                            location,
                            entry.weight,
                            entry.chance,
                            calculated.totalWeight
                        )
                    );
                }
            );

        body.appendChild(
            grid
        );
    }

    function createFishCard(
        fish,
        location,
        weight,
        chance,
        totalWeight
    ) {
        var card =
            document.createElement(
                'button'
            );

        card.type =
            'button';

        card.className =
            'wiki-fish-card';

        if (
            fish.image
        ) {
            var image =
                document.createElement(
                    'img'
                );

            image.className =
                'wiki-fish-card-image';

            image.src =
                getWikiImageUrl(
                    fish.image
                );

            image.alt =
                fish.name;

            card.appendChild(
                image
            );
        }

        var name =
            document.createElement(
                'div'
            );

        name.className =
            'wiki-fish-card-name';

        name.textContent =
            fish.name;

        applyRarityClass(
            name,
            fish.rarity
        );

        card.appendChild(
            name
        );

        if (
            fish.rarity
        ) {
            var rarity =
                document.createElement(
                    'div'
                );

            rarity.className =
                'wiki-fish-card-rarity';

            rarity.textContent =
                fish.rarity;

            applyRarityClass(
                rarity,
                fish.rarity
            );

            card.appendChild(
                rarity
            );
        }

        var chanceText =
            document.createElement(
                'div'
            );

        chanceText.className =
            'wiki-fish-card-chance';

        chanceText.setAttribute(
            'data-chance-percent',
            String(
                chance
            )
        );

        chanceText.textContent =
            formatChance(
                chance
            );

        card.appendChild(
            chanceText
        );

        card.addEventListener(
            'click',
            function () {
                var body =
                    document.querySelector(
                        '#fish-entries-app .wiki-entry-items-body'
                    );

                if (
                    !body
                ) {
                    return;
                }

                renderFishDetail(
                    body,
                    fish,
                    location,
                    weight,
                    chance,
                    totalWeight
                );
            }
        );

        return card;
    }

    function renderFishDetail(
        body,
