        );

        if (
            !toolEntries.length
        ) {
            content.appendChild(
                createEmptyMessage(
                    'No Tool entries have been published yet.'
                )
            );

            return;
        }

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-standard-entry-grid';

        toolEntries.forEach(
            function (tool) {
                grid.appendChild(
                    createStandardCard(
                        tool,
                        function () {
                            renderToolDetail(
                                content,
                                tool
                            );
                        }
                    )
                );
            }
