    function renderEnchantsSection(
        content
    ) {
        createSectionTitle(
            content,
            'Enchants'
        );

        if (
            !enchantEntries.length
        ) {
            content.appendChild(
                createEmptyMessage(
                    'No Enchant entries have been published yet.'
                )
            );

            return;
        }

        var totalWeight =
            enchantEntries.reduce(
                function (
                    total,
                    enchant
                ) {
                    return (
                        total +
                        (
                            Number(
                                enchant.weight
                            ) ||
                            0
                        )
                    );
                },
                0
            );

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-standard-entry-grid';

        enchantEntries.forEach(
            function (enchant) {
                var chance =
                    totalWeight > 0
                        ? (
                            enchant.weight /
                            totalWeight
                        ) * 100
                        : 0;

                var card =
                    createStandardCard(
                        enchant,
                        function () {
                            renderEnchantDetail(
                                content,
                                enchant,
                                chance
                            );
                        }
                    );

                var chanceLabel =
                    document.createElement(
                        'div'
                    );

                chanceLabel.className =
                    'wiki-standard-card-extra';

                chanceLabel.setAttribute(
                    'data-chance-percent',
                    String(
                        chance
                    )
                );

                chanceLabel.textContent =
                    formatChance(
                        chance
                    );

                card.appendChild(
                    chanceLabel
                );

                grid.appendChild(
                    card
                );
            }
        );

        content.appendChild(
            grid
        );
    }

