                        function (entry) {
                            return {
                                page:
                                    entry.page,

                                name:
                                    entry.data.name ||
                                    getNameFromPage(
                                        entry.page
                                    ),

                                image:
                                    entry.data.image ||
                                    '',

                                rarity:
                                    entry.data.rarity ||
