                );

            image.alt =
                entry.name;

            card.appendChild(
                image
            );
        }

        var name =
            document.createElement(
                'div'
            );

        name.className =
            'wiki-standard-entry-name';

        name.textContent =
            entry.name;

        if (
            entry.rarity
        ) {
            applyRarityClass(
                name,
                entry.rarity
            );
        }

        card.appendChild(
            name
        );

        if (
            entry.rarity
        ) {
            var rarity =
                document.createElement(
                    'div'
                );

            rarity.className =
                'wiki-standard-entry-rarity';

            rarity.textContent =
                entry.rarity;

            applyRarityClass(
                rarity,
                entry.rarity
            );

            card.appendChild(
                rarity
            );
