            '';

        createSectionTitle(
            content,
            'Tools'
        );

        var detail =
            document.createElement(
                'div'
            );

        detail.className =
            'wiki-entry-detail';

        detail.appendChild(
            createBackButton(
                function () {
                    renderCurrentSection();
                }
            )
        );

        appendDetailBasicInfo(
            detail,
            tool
        );

        if (
            tool.baseCost !==
            ''
        ) {
            var stats =
                document.createElement(
