                );

            stats.className =
                'wiki-entry-stat-grid';

            stats.appendChild(
                createStat(
                    'Base Cost',
                    tool.baseCost
                )
            );

            detail.appendChild(
                stats
            );
        }

        appendDescription(
            detail,
            tool.description
        );

        content.appendChild(
            detail
        );
    }

    function renderEnchantDetail(
        content,
        enchant,
        chance
    ) {
        content.innerHTML =
            '';

        createSectionTitle(
            content,
            'Enchants'
        );

        var detail =
            document.createElement(
                'div'
            );

        detail.className =
            'wiki-entry-detail';

        detail.appendChild(
            createBackButton(
                function () {
                    renderCurrentSection();
                }
            )
        );

        appendDetailBasicInfo(
            detail,
            enchant
        );

