    function appendDetailBasicInfo(
        detail,
        entry
    ) {
        if (
            entry.image
        ) {
            var image =
                document.createElement(
                    'img'
                );

            image.className =
                'wiki-entry-detail-image';

            image.src =
                getWikiImageUrl(
                    entry.image
                );

            image.alt =
                entry.name;

            detail.appendChild(
                image
            );
        }

        var name =
            document.createElement(
                'div'
            );

        name.className =
            'wiki-entry-detail-name';

        name.textContent =
            entry.name;

        if (
            entry.rarity
        ) {
            applyRarityClass(
                name,
                entry.rarity
            );
        }

        detail.appendChild(
            name
        );

        if (
            entry.rarity
        ) {
            var rarity =
                document.createElement(
                    'div'
                );

            rarity.className =
                'wiki-entry-detail-rarity';

            rarity.textContent =
                entry.rarity;

            applyRarityClass(
                rarity,
                entry.rarity
            );

            detail.appendChild(
                rarity
            );
        }
    }

    function appendDescription(
        detail,
        text
    ) {
        if (
            !text
        ) {
            return;
        }

        var description =
            document.createElement(
                'div'
            );

        description.className =
