        detail.appendChild(
            description
        );
    }

    function createBackButton(
        onClick
    ) {
        var wrapper =
            document.createElement(
                'div'
            );

        wrapper.className =
            'wiki-detail-back-row';

        var button =
            document.createElement(
                'button'
            );

        button.type =
            'button';

        button.className =
            'wiki-entry-back';

        button.textContent =
            'Back';

        button.addEventListener(
            'click',
