            );

        name.className =
            'wiki-entry-detail-name';

        name.textContent =
            tool.name;

        detail.appendChild(
            name
        );

        if (
            tool.baseCost !==
            ''
        ) {

            var stats =
                document.createElement(
                    'div'
                );

            stats.className =
                'wiki-entry-stat-grid wiki-tool-base-cost';

            stats.appendChild(
                createStat(
                    'Base Cost',
                    tool.baseCost
                )
            );

            detail.appendChild(
                stats
            );

        }

        if (
            tool.description
        ) {

            var description =
                document.createElement(
