                );

            description.className =
                'wiki-entry-description';

            renderLoreText(
                description,
                tool.description
            );

            detail.appendChild(
                description
            );

        }

        content.appendChild(
            detail
        );

    }

    function renderEnchantDetail(
        content,
        enchant,
        chance,
        totalWeight
    ) {

        content.innerHTML =
            '';

        createSectionTitle(
            content,
            'Enchants'
        );

        var detail =
            document.createElement(
                'div'
            );

        detail.className =
            'wiki-entry-detail';

        detail.appendChild(
            createBackButton(
                function () {

                    renderCurrentSection();

                }
            )
        );

        appendDetailBasicInfo(
            detail,
            enchant
        );

        var stats =
            document.createElement(
                'div'
            );

        stats.className =
            'wiki-entry-stat-grid';

        stats.appendChild(
            createStat(
                'Weight',
                formatNumber(
                    enchant.weight
                )
            )
        );

        stats.appendChild(
            createStat(
                'Chance',
                formatPercent(
                    chance
                )
            )
        );

        detail.appendChild(
            stats
        );

        content.appendChild(
