        grid.className =
            'wiki-standard-entry-grid';

        baitEntries.forEach(function (bait) {

            grid.appendChild(
                createStandardCard(
                    bait,
                    function () {

                        renderStandardDetail(
                            body,
                            bait,
                            'Bait'
                        );

                    }
                )
            );

        });

        body.appendChild(
            grid
        );

