        updateToolSettings();
        shell.appendChild(
            nav
        );

        shell.appendChild(
            content
        );

        var frame =
            document.createElement(
                'div'
        );

        frame.className =
            'wiki-entries-frame';

        frame.appendChild(
            menuBar
        );
        frame.appendChild(
            sideMenu
        );

        frame.appendChild(
            shell
        );

        container.appendChild(
            frame
        );

        menuButton.addEventListener(
            'click',
            function () {

                sideMenu.classList.toggle(
                    'wiki-side-menu-open'
                );

            }
        );

        createNavButton(
            nav,
            'Items',
            SIDE_ICONS.Items
        );

        createNavButton(
            nav,
            'Tools',
            SIDE_ICONS.Tools
        );

        createNavButton(
            nav,
            'Enchants',
            SIDE_ICONS.Enchants
        );

    }

    function createNavButton(
        container,
        section,
        imageName
    ) {

        var button =
            document.createElement(
                'button'
            );

        button.type =
            'button';

        button.className =
            'wiki-entry-nav-pill';

        button.setAttribute(
            'data-entry-section',
            section
        );

        var image =
            document.createElement(
                'img'
            );

        image.src =
            getWikiImageUrl(
                imageName
            );

        image.alt =
            section;

        var label =
            document.createElement(
                'span'
            );

        label.textContent =
            section;

        button.appendChild(
            image
        );

        button.appendChild(
            label
        );

        button.addEventListener(
            'click',
            function () {

                currentSection =
                    section;

                currentLocation =
                    null;

                var shell =
                    document.querySelector(
                        '#fish-entries-app .wiki-entries-shell'
                    );

                var content =
                    document.querySelector(
                        '#fish-entries-app .wiki-entries-content'
                    );

                if (
                    shell
                ) {

                    shell.classList.remove(
                        'wiki-entries-start'
                    );

                    shell.classList.add(
                        'wiki-entries-open'
                    );

                }

                if (
                    content
                ) {

                    content.style.display =
                        'block';

                }

                updateNavButtons();
                renderCurrentSection();

            }
        );

        container.appendChild(
            button
        );

    }

    function updateNavButtons() {

        document
            .querySelectorAll(
                '#fish-entries-app .wiki-entry-nav-pill'
            )
            .forEach(function (button) {

                var section =
                    button.getAttribute(
                        'data-entry-section'
                    );

                button.classList.toggle(
                    'entry-active',
                    section ===
                    currentSection
                );

            });

    }

    function renderCurrentSection() {

        updateNavButtons();

        var content =
            document.querySelector(
                '#fish-entries-app .wiki-entries-content'
            );

        if (
            !content
        ) {
            return;
        }

        content.innerHTML =
            '';

        if (
            currentSection ===
            'Items'
        ) {

            renderItemsSection(
                content
            );

            return;

        }

        if (
            currentSection ===
            'Tools'
        ) {

            renderToolsSection(
                content
            );

            return;

        }

        if (
            currentSection ===
            'Enchants'
        ) {

            renderEnchantsSection(
                content
            );

        }

    }

    function createSectionTitle(
        container,
        text
    ) {

        var title =
            document.createElement(
                'div'
            );

        title.className =
            'wiki-entry-content-title';

        title.textContent =
            text;

        container.appendChild(
            title
        );

    }

    function renderItemsSection(
        content
    ) {

        createSectionTitle(
            content,
            'Items'
        );

        var tabs =
            document.createElement(
                'div'
            );

        tabs.className =
            'wiki-entry-subtabs';

        var fishButton =
            createSubtabButton(
                'Fish'
            );

        var baitButton =
            createSubtabButton(
                'Baits'
            );

        tabs.appendChild(
            fishButton
        );

        tabs.appendChild(
            baitButton
        );

        content.appendChild(
            tabs
        );

        var body =
            document.createElement(
                'div'
            );

        body.className =
            'wiki-entry-items-body';

        content.appendChild(
            body
        );

        fishButton.addEventListener(
            'click',
            function () {

                currentItemTab =
                    'Fish';

                currentLocation =
                    null;

                updateItemTabs(
                    fishButton,
                    baitButton
                );

                renderFishLocations(
                    body
                );

            }
        );

        baitButton.addEventListener(
            'click',
            function () {

                currentItemTab =
                    'Baits';

                currentLocation =
                    null;

                updateItemTabs(
                    fishButton,
                    baitButton
                );

                renderBaits(
                    body
                );

            }
        );

        updateItemTabs(
            fishButton,
            baitButton
        );

        if (
            currentItemTab ===
            'Baits'
        ) {

            renderBaits(
                body
            );

        } else {

            renderFishLocations(
                body
            );

        }

    }

    function createSubtabButton(
        text
    ) {

        var button =
            document.createElement(
                'button'
            );

        button.type =
            'button';

        button.className =
            'wiki-entry-subtab';

        button.textContent =
            text;

        return button;

    }

    function updateItemTabs(
        fishButton,
        baitButton
    ) {

        fishButton.classList.toggle(
            'entry-active',
            currentItemTab ===
            'Fish'
        );

        baitButton.classList.toggle(
            'entry-active',
            currentItemTab ===
            'Baits'
        );

    }

    function renderFishLocations(
        body
    ) {

        body.innerHTML = '';

        if (
            currentLocation
        ) {

            renderLocationFish(
                body,
                currentLocation
            );

            return;

        }

        if (
            !locations.length
        ) {

            body.appendChild(
                createEmptyMessage(
                    'No locations have been published yet.'
                )
            );

            return;

        }

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-location-grid';

        locations.forEach(function (location) {

            var button =
                document.createElement(
                    'button'
                );

            button.type =
                'button';

            button.className =
                'wiki-location-pill';

            if (
                location.image
            ) {

                var image =
                    document.createElement(
                        'img'
                    );

                image.src =
                    getWikiImageUrl(
                        location.image
                    );

                image.alt =
                    location.name;

                button.appendChild(
                    image
                );

            }

            var name =
                document.createElement(
                    'div'
                );

            name.className =
                'wiki-location-name';

            name.textContent =
                location.name;

            button.appendChild(
                name
            );

            button.addEventListener(
                'click',
                function () {

                    currentLocation =
                        location;

                    renderFishLocations(
                        body
                    );

                }
            );

            grid.appendChild(
                button
            );

        });

        body.appendChild(
            grid
        );

    }

    function renderLocationFish(
        body,
        location
    ) {

        body.innerHTML =
            '';

        var header =
            document.createElement(
                'div'
            );

        header.className =
            'wiki-location-header';

        var title =
            document.createElement(
                'div'
            );

        title.className =
            'wiki-location-header-title';

        if (
            location.image
        ) {

            var image =
                document.createElement(
                    'img'
                );

            image.src =
                getWikiImageUrl(
                    location.image
                );

            image.alt =
                location.name;

            title.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'span'
            );

        name.textContent =
            location.name;

        title.appendChild(
            name
        );

        var back =
            document.createElement(
                'button'
            );

        back.type =
            'button';

        back.className =
            'wiki-entry-back';

        back.textContent =
            'Back';

        back.addEventListener(
            'click',
            function () {

                currentLocation =
                    null;

                renderFishLocations(
                    body
                );

            }
        );

        header.appendChild(
            title
        );

        header.appendChild(
            back
        );

        body.appendChild(
            header
        );

        var calculated =
            getFishForLocation(
                location.name
            );

        if (
            !calculated.entries.length
        ) {

            body.appendChild(
                createEmptyMessage(
                    'No fish can currently be caught here.'
                )
            );

            return;

        }

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-fish-grid';

        calculated.entries
            .forEach(function (entry) {

                grid.appendChild(
                    createFishCard(
                        entry.fish,
                        location,
                        entry.weight,
                        entry.chance,
                        calculated.totalWeight
                    )
                );

            });

        body.appendChild(
            grid
        );

    }

