    function renderBaits(
        body
    ) {

        body.innerHTML =
            '';

        if (
            !baitEntries.length
        ) {

            body.appendChild(
                createEmptyMessage(
                    'No Bait entries have been published yet.'
                )
            );

            return;

        }

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-standard-entry-grid';

        baitEntries.forEach(function (bait) {

            grid.appendChild(
                createStandardCard(
                    bait,
                    function () {

                        renderStandardDetail(
                            body,
                            bait,
                            'Bait'
                        );

                    }
                )
            );

        });

        body.appendChild(
            grid
        );

    }

    function renderToolsSection(
        content
    ) {

        createSectionTitle(
            content,
            'Tools'
        );

        if (
            !toolEntries.length
        ) {

            content.appendChild(
                createEmptyMessage(
                    'No Tool entries have been published yet.'
                )
            );

            return;

        }

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-standard-entry-grid';

        toolEntries.forEach(function (tool) {

            grid.appendChild(
                createStandardCard(
                    tool,
                    function () {

                        renderToolDetail(
                            content,
                            tool
                        );

                    }
                )
            );

        });

