    function renderLoreText(
        element,
        text
    ) {

        text =
            String(
                text || ''
            );

        var regex =
            /\[blue\]([\s\S]*?)\[\/blue\]/gi;

        var lastIndex = 0;
        var match;

        while (
            (
                match =
                    regex.exec(
                        text
                    )
            ) !==
            null
        ) {

            if (
                match.index >
                lastIndex
            ) {

                element.appendChild(
                    document.createTextNode(
                        text.slice(
                            lastIndex,
                            match.index
                        )
                    )
                );

            }

            var blue =
                document.createElement(
                    'span'
                );

            blue.className =
                'wiki-lore-blue';

            blue.textContent =
                match[1];

            element.appendChild(
                blue
            );

            lastIndex =
                regex.lastIndex;

        }

        if (
            lastIndex <
            text.length
        ) {

            element.appendChild(
                document.createTextNode(
                    text.slice(
                        lastIndex
                    )
                )
            );

        }

    }

    function createRarityDisplay(
        rarityName,
        className
    ) {

        rarityName =
            String(
                rarityName || ''
            ).trim();

        if (
            !rarityName
        ) {
            return null;
        }

        var wrapper =
            document.createElement(
                'div'
            );

        wrapper.className =
            className;

        var rarityText =
            document.createElement(
                'span'
            );

        rarityText.textContent =
            capitalizeFirst(
                rarityName
            );

        applyRarityClass(
            rarityText,
            rarityName
        );

        wrapper.appendChild(
            rarityText
        );

        var rarity =
            rarityEntries[
                rarityName.toLowerCase()
            ];

        if (
            rarity &&
            rarity.stars > 0
        ) {

            var stars =
                document.createElement(
                    'span'
                );

            stars.className =
                'wiki-rarity-stars-inline';

            stars.textContent =
                '★'.repeat(
                    rarity.stars
                );

            applyRarityClass(
                stars,
                rarityName
            );

            wrapper.appendChild(
                stars
            );

        }

        return wrapper;

    }

