    function renderToolsSection(
        content
    ) {

        createSectionTitle(
            content,
            'Tools'
        );

        if (
            !toolEntries.length
        ) {

            content.appendChild(
                createEmptyMessage(
                    'No Tool entries have been published yet.'
                )
            );

            return;

        }

        var toolGroups = {};
        var rodTypeOrder = [];

        toolEntries.forEach(
            function (tool) {

                var rodType =
                    String(
                        tool.rodType ||
                        'Unassigned'
                    ).trim() ||
                    'Unassigned';

                var rodTypeKey =
                    rodType.toLowerCase();

                if (
                    !toolGroups[
                        rodTypeKey
                    ]
                ) {

                    toolGroups[
                        rodTypeKey
                    ] = {
                        name:
                            rodType,

                        tools:
                            []
                    };

                    rodTypeOrder.push(
                        rodTypeKey
                    );

                }

                toolGroups[
                    rodTypeKey
                ]
                    .tools
                    .push(
                        tool
                    );

            }
        );

        rodTypeOrder.forEach(
            function (rodTypeKey) {

                var toolGroup =
                    toolGroups[
                        rodTypeKey
                    ];

                var group =
                    document.createElement(
                        'div'
                    );

                group.className =
                    'wiki-tool-type-group';

                var pill =
                    document.createElement(
                        'div'
                    );

                pill.className =
                    'wiki-tool-type-pill';

                pill.textContent =
                    toolGroup.name;

                group.appendChild(
                    pill
                );

                var grid =
                    document.createElement(
                        'div'
                    );

                grid.className =
                    'wiki-standard-entry-grid';

                toolGroup.tools.forEach(
                    function (tool) {

                        grid.appendChild(
                            createStandardCard(
                                tool,
                                function () {

                                    renderToolDetail(
                                        content,
                                        tool
                                    );

                                }
                            )
                        );

                    }
                );

                group.appendChild(
                    grid
                );

                content.appendChild(
                    group
                );

            }
        );

    }

    function renderEnchantsSection(
        content
    ) {

        createSectionTitle(
            content,
            'Enchants'
        );

        if (
            !enchantEntries.length
        ) {

            content.appendChild(
                createEmptyMessage(
                    'No Enchant entries have been published yet.'
                )
            );

            return;

        }

        var totalWeight =
            enchantEntries.reduce(
                function (
                    total,
                    enchant
                ) {

                    return (
                        total +
                        (
                            Number(
                                enchant.weight
                            ) ||
                            0
                        )
                    );

                },
                0
            );

        var sortedEnchants =
            enchantEntries
                .slice()
                .sort(function (
                    a,
                    b
                ) {

                    if (
                        a.weight !==
                        b.weight
                    ) {

                        return (
                            a.weight -
                            b.weight
                        );

                    }

                    return sortByName(
                        a,
                        b
                    );

                });

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-standard-entry-grid';

        sortedEnchants.forEach(
            function (enchant) {

                var chance =
                    totalWeight > 0
                        ? (
                            enchant.weight /
                            totalWeight
                        ) * 100
                        : 0;

                var card =
                    createStandardCard(
                        enchant,
                        function () {

                            renderEnchantDetail(
                                content,
                                enchant,
                                chance,
                                totalWeight
                            );

                        }
                    );

                var chanceLabel =
                    document.createElement(
                        'div'
                    );

                chanceLabel.className =
                    'wiki-standard-card-extra';

                chanceLabel.textContent =
                    formatChance(
                        chance
                    );

                card.appendChild(
                    chanceLabel
                );

                grid.appendChild(
                    card
                );

            }
        );

        content.appendChild(
            grid
        );

    }

