    function injectRarityStyles() {

        var old =
            document.getElementById(
                'wiki-dynamic-rarity-styles'
            );

        if (
            old
        ) {
            old.remove();
        }

        var css = '';

        Object.keys(
            rarityEntries
        )
            .forEach(function (key) {

                var rarity =
                    rarityEntries[
                        key
                    ];

                var slug =
                    makeSlug(
                        rarity.name
                    );

                var animation =
                    'wiki-rarity-' +
                    slug;

                css +=
                    '@keyframes ' +
                    animation +
                    '{' +
                    '0%{color:' +
                    rarity.color0 +
                    ';}' +
                    '50%{color:' +
                    rarity.color50 +
                    ';}' +
                    '100%{color:' +
                    rarity.color100 +
                    ';}' +
                    '}';

                css +=
                    '.wiki-dynamic-rarity-' +
                    slug +
                    '{animation:' +
                    animation +
                    ' 3s ease-in-out infinite !important;}';

            });

        var style =
            document.createElement(
                'style'
            );

        style.id =
            'wiki-dynamic-rarity-styles';

        style.textContent =
            css;

        document.head.appendChild(
            style
        );

    }

    function applyRarityClass(
        element,
        rarity
    ) {

        rarity =
            String(
                rarity || ''
            ).trim();

        if (
            !rarity
        ) {
            return;
        }

        var slug =
            makeSlug(
                rarity
            );

        element.classList.add(
            'entry-name-rarity-' +
            slug
        );

        if (
            rarityEntries[
                rarity.toLowerCase()
            ]
        ) {

            element.classList.add(
                'wiki-dynamic-rarity-' +
                slug
            );

        }

    }

    function applyRarityBorderClass(
        element,
        rarity
    ) {

        rarity =
            String(
                rarity || ''
            ).trim();

        if (
            !rarity
        ) {
            return;
        }

        var rarityData =
            rarityEntries[
                rarity.toLowerCase()
            ];

        if (
            !rarityData
        ) {
            return;
        }

        element.classList.add(
            'wiki-rarity-animated-border'
        );

        element.style.setProperty(
            '--rarity-border-color-0',
            rarityData.color0
        );

        element.style.setProperty(
            '--rarity-border-color-50',
            rarityData.color50
        );

    }

    function makeSlug(
        value
    ) {

        return String(
            value || ''
        )
            .toLowerCase()
            .trim()
            .replace(
                /[^a-z0-9]+/g,
                '-'
            )
            .replace(
                /^-+|-+$/g,
                ''
            );

    }

    function normalizeHexColor(
        value
    ) {

        value =
            String(
                value || ''
            )
                .trim()
                .toLowerCase();

        if (
            /^[0-9a-f]{6}$/i.test(
                value
            )
        ) {

            value =
                '#' +
                value;

        }

        if (
            /^#[0-9a-f]{6}$/i.test(
                value
            )
        ) {

            return value;

        }

        return '';

    }

    function getWikiImageUrl(
        filename
    ) {

        filename =
            String(
                filename || ''
            )
                .replace(
                    /^File:/i,
                    ''
                )
                .trim();

        return mw.util.getUrl(
            'Special:Redirect/file/' +
            filename
        );

    }

    function getNameFromPage(
        page
    ) {

        page =
            String(
                page || ''
            );

        var separator =
            page.indexOf(
                ':'
            );

        if (
            separator !==
            -1
        ) {

            return page
                .slice(
                    separator + 1
                )
                .trim();

        }

        return page.trim();

    }

    function sortByName(
        a,
        b
    ) {

        return String(
            a.name || ''
        ).localeCompare(
            String(
                b.name || ''
            ),
            undefined,
            {
                sensitivity:
                    'base'
            }
        );

    }

    function formatChance(
        value
    ) {

        value =
            Number(
                value
            );

        if (
            currentDisplayMode ===
            'percentage'
        ) {

            return formatPercent(
                value
            );

        }

        if (
            !isFinite(
                value
            ) ||
            value <= 0
        ) {

            return '1/∞';

        }


        var denominator =
            100 / value;

        if (
            Math.abs(
                denominator -
                Math.round(
                    denominator
                )
            ) < 0.000001
        ) {

            denominator =
                Math.round(
                    denominator
                );

        } else {

            denominator =
                denominator
                    .toFixed(
                        3
                    )
                    .replace(
                        /\.?0+$/,
                        ''
                    );

        }


        return (
            '1/' +
            denominator
        );

    }

    function formatPercent(
        value
    ) {

        value =
            Number(
                value
            );

        if (
            !isFinite(
                value
            )
        ) {

            return '0%';

        }

        if (
            value >= 10
        ) {

            return (
                value
                    .toFixed(2)
                    .replace(
                        /\.?0+$/,
                        ''
                    ) +
                '%'
            );

        }

        if (
            value >= 1
        ) {

            return (
                value
                    .toFixed(3)
                    .replace(
                        /\.?0+$/,
                        ''
                    ) +
                '%'
            );

        }

        return (
            value
                .toFixed(6)
                .replace(
                    /\.?0+$/,
                    ''
                ) +
            '%'
        );

    }

    function formatNumber(
        value
    ) {

        value =
            Number(
                value
            );

        if (
            !isFinite(
                value
            )
        ) {

            return '0';

        }

        return value.toLocaleString();

    }

    function decodeTemplateValue(
        value
    ) {

        return String(
            value || ''
        )
            .replace(
                /&#124;/g,
                '|'
            )
            .replace(
                /&#123;&#123;/g,
                '{{'
            )
            .replace(
                /&#125;&#125;/g,
                '}}'
            )
            .replace(
                /\}&#125;/g,
                '}}'
            );

    }

    function normalizeApiError(
        code,
        details
    ) {

        var error = {
            code:
                code ||
                'api-error',

            info:
                '',

            details:
                details ||
                null
        };

        if (
            details &&
            details.error
        ) {

            if (
                details.error.code
            ) {

                error.code =
                    details.error.code;

            }

            if (
                details.error.info
            ) {

                error.info =
                    details.error.info;

            }

        }

        if (
            !error.info &&
            details &&
            details.info
        ) {

            error.info =
                details.info;

        }

        if (
            !error.info &&
            typeof details ===
            'string'
        ) {

            error.info =
                details;

        }

        if (
            !error.info
        ) {

            error.info =
                'MediaWiki returned an API error.';

        }

        return error;

    }

    function formatError(
        error
    ) {

        if (
            !error
        ) {

            return 'Unknown error.';

        }

        if (
            typeof error ===
            'string'
        ) {

            return error;

        }

        if (
            error.code &&
            error.info
        ) {

            return (
                error.code +
                ': ' +
                error.info
            );

        }

        return (
            error.info ||
            error.code ||
            error.message ||
            'Unknown error.'
        );

    }

    function escapeHtml(
        value
    ) {

        return String(
            value || ''
        )
            .replace(
                /&/g,
                '&amp;'
            )
            .replace(
                /</g,
                '&lt;'
            )
            .replace(
                />/g,
                '&gt;'
            )
            .replace(
                /"/g,
                '&quot;'
            )
            .replace(
                /'/g,
                '&#039;'
            );

    }

})();

(function () {

    var ENTRIES_PAGE = 'Fish_entries:sandbox';

    var CATEGORIES = {
        Fish: 'Category:Fish Entries',
        Bait: 'Category:Bait Entries',
        Tool: 'Category:Tool Entries',
        Enchant: 'Category:Enchant Entries',
        Location: 'Category:Fish Locations',
        Rarity: 'Category:Rarity Entries'
    };

    var SIDE_ICONS = {
        Items: 'Ball.png',
        Tools: 'Fishing_Rod.png',
        Enchants: 'strength.png'
    };

    var locations = [];
    var fishEntries = [];
    var baitEntries = [];
    var toolEntries = [];
    var enchantEntries = [];
    var rarityEntries = {};

    var currentSection = null;
    var currentItemTab = 'Fish';
    var currentLocation = null;
    var currentDisplayMode ='percentage';

    $(function () {

        if (
            normalizePageName(
                mw.config.get('wgPageName')
            ) !==
            normalizePageName(
                ENTRIES_PAGE
            )
        ) {
            return;
        }

        var container =
            document.getElementById(
                'fish-entries-app'
            );

        if (!container) {
            return;
        }

        if (
            container.dataset.loaded ===
            'true'
        ) {
            return;
        }

        container.dataset.loaded =
            'true';

        container.innerHTML =
            '<div class="entries-app-loading">Loading entries...</div>';

        loadMediaWikiModules()
            .then(function () {

                return Promise.all([
                    loadLocations(),
                    loadFish(),
                    loadBaits(),
                    loadTools(),
                    loadEnchants(),
                    loadRarities()
                ]);

            })
            .then(function () {

                fishEntries.sort(
                    sortByRarity
                );

                baitEntries.sort(
                    sortByRarity
                );

                injectRarityStyles();

                buildEntriesApp(
                    container
                );

            })
            .catch(function (error) {

                console.error(
                    'Fish Entries App Error:',
                    error
                );

                container.innerHTML =
                    '<div class="entries-app-error">' +
                    escapeHtml(
                        formatError(
                            error
                        )
                    ) +
                    '</div>';

            });

    });

    function normalizePageName(value) {

        return String(
            value || ''
        )
            .replace(/_/g, ' ')
            .replace(/\s+/g, ' ')
            .trim()
            .toLowerCase();

    }

    function capitalizeFirst(value) {

        value =
            String(
                value || ''
            ).trim();

        if (!value) {
            return '';
        }

        return (
            value.charAt(0).toUpperCase() +
            value.slice(1).toLowerCase()
        );

    }

    function loadMediaWikiModules() {

        return mw.loader.using([
            'mediawiki.api',
            'mediawiki.util'
        ]);

    }

    function loadLocations() {

        var api =
            new mw.Api();

        return getCategoryEntryPages(
            api,
            CATEGORIES.Location,
            'Location'
        )
            .then(function (entries) {

                locations =
                    entries.map(function (entry) {

                        return {
                            page:
                                entry.page,

                            name:
                                entry.data.name ||
                                getNameFromPage(
                                    entry.page
                                ),

                            image:
                                entry.data.image ||
                                ''
                        };

                    });

                locations.sort(
                    sortByName
                );

            });

    }

    function loadFish() {

        var api =
            new mw.Api();

        return getCategoryEntryPages(
            api,
            CATEGORIES.Fish,
            'Fish'
        )
            .then(function (entries) {

                fishEntries =
                    entries.map(function (entry) {

                        return {
                            page:
                                entry.page,

                            name:
                                entry.data.name ||
                                getNameFromPage(
                                    entry.page
                                ),

                            image:
                                entry.data.image ||
                                '',

                            rarity:
                                entry.data.rarity ||
                                '',

                            description:
                                entry.data.description ||
                                '',

                            baseSellPrice:
                                entry.data.base_sell_price ||
                                '',

                            weights:
                                parseLocationWeights(
                                    entry.data.location_weights
                                )
                        };

                    });

            });

    }

    function loadBaits() {

        var api =
            new mw.Api();

        return getCategoryEntryPages(
            api,
            CATEGORIES.Bait,
            'Bait'
        )
            .then(function (entries) {

                baitEntries =
                    entries.map(function (entry) {

                        return {
                            page:
                                entry.page,

                            name:
                                entry.data.name ||
                                getNameFromPage(
                                    entry.page
                                ),

                            image:
                                entry.data.image ||
                                '',

                            rarity:
                                entry.data.rarity ||
                                '',

                            description:
                                entry.data.description ||
                                ''
                        };

                    });

            });

    }

    function loadTools() {

        var api =
            new mw.Api();

        return getCategoryEntryPages(
            api,
            CATEGORIES.Tool,
            'Tool'
        )
            .then(function (entries) {

                toolEntries =
                    entries.map(function (entry) {

                        return {
                            page:
                                entry.page,

                            name:
                                entry.data.name ||
                                getNameFromPage(
                                    entry.page
                                ),

                            image:
                                entry.data.image ||
                                '',

                            description:
                                entry.data.description ||
                                '',

                            baseCost:
                                entry.data.base_cost ||
                                '',
                            rodType:
                                String(
                                    entry.data.rod_type ||
                                    'Unassigned'
                                ).trim() ||
                                'Unassigned',
                            luck:
                                entry.data.luck !==
                                undefined
                                    ? Number(
                                        entry.data.luck
                                    )
                                    : 0
                        };

                    });

                toolEntries.sort(function (
                    a,
                    b
                ) {

                    var aCost =
                        Number(
                            a.baseCost
                        );

                    var bCost =
                        Number(
                            b.baseCost
                        );

                    if (
                        !Number.isFinite(
                            aCost
                        )
                    ) {
                        aCost = Infinity;
                    }

                    if (
                        !Number.isFinite(
                            bCost
                        )
                    ) {
                        bCost = Infinity;
                    }

                    if (
                        aCost !==
                        bCost
                    ) {

                        return (
                            aCost -
                            bCost
                        );

                    }

                    return sortByName(
                        a,
                        b
                    );

                });

            });

    }

    function loadEnchants() {

        var api =
            new mw.Api();

        return getCategoryEntryPages(
            api,
            CATEGORIES.Enchant,
            'Enchant'
        )
            .then(function (entries) {

                enchantEntries =
                    entries.map(function (entry) {

                        return {
                            page:
                                entry.page,

                            name:
                                entry.data.name ||
                                getNameFromPage(
                                    entry.page
                                ),

                            image:
                                entry.data.image ||
                                '',

                            description:
                                entry.data.description ||
                                '',
                            rodType:
                                String(
                                    entry.data.rod_type ||
                                    'Unassigned'
                                ).trim() ||
                                'Unassigned',
                            weight:
                                Number(
                                    entry.data.weight ||
                                    0
                                )
                        };

                    });

                enchantEntries.sort(function (
                    a,
                    b
                ) {

                    if (
                        a.weight !==
                        b.weight
                    ) {

                        return (
                            a.weight -
                            b.weight
                        );

                    }

                    return sortByName(
                        a,
                        b
                    );

                });

            });

    }

    function loadRarities() {

        var api =
            new mw.Api();

        return getCategoryEntryPages(
            api,
            CATEGORIES.Rarity,
            'Rarity'
        )
            .then(function (entries) {

                rarityEntries = {};

                entries.forEach(function (entry) {

                    var name =
                        String(
                            entry.data.name ||
                            getNameFromPage(
                                entry.page
                            )
                        ).trim();

                    if (!name) {
                        return;
                    }

                    var stars =
                        Number(
                            entry.data.stars
                        );

                    if (
                        !Number.isInteger(
                            stars
                        ) ||
                        stars < 0
                    ) {
                        stars = 0;
                    }

                    rarityEntries[
                        name.toLowerCase()
                    ] = {
                        name:
                            name,

                        stars:
                            stars,

                        color0:
                            normalizeHexColor(
                                entry.data.color_0
                            ) ||
                            '#ffffff',

                        color50:
                            normalizeHexColor(
                                entry.data.color_50
                            ) ||
                            '#ffffff',

                        color100:
                            normalizeHexColor(
                                entry.data.color_100
                            ) ||
                            '#ffffff'
                    };

                });

            });

    }

    function getRarityStars(
        rarityName
    ) {

        var rarity =
            rarityEntries[
                String(
                    rarityName || ''
                )
                    .trim()
                    .toLowerCase()
            ];

        if (!rarity) {
            return 999999;
        }

        var stars =
            Number(
                rarity.stars
            );

        if (
            !Number.isFinite(
                stars
            )
        ) {
            return 999999;
        }

        return stars;

    }

    function sortByRarity(
        a,
        b
    ) {

        var aStars =
            getRarityStars(
                a.rarity
            );

        var bStars =
            getRarityStars(
                b.rarity
            );

        if (
            aStars !==
            bStars
        ) {

            return (
                aStars -
                bStars
            );

        }

        return sortByName(
            a,
            b
        );

    }

    function getCategoryEntryPages(
        api,
        category,
        expectedType
    ) {

        return getAllCategoryMembers(
            api,
            category
        )
            .then(function (titles) {

                if (!titles.length) {
                    return [];
                }

                return getPagesContents(
                    api,
                    titles
                );

            })
            .then(function (pages) {

                if (!pages) {
                    return [];
                }

                var result = [];

                pages.forEach(function (page) {

                    var data =
                        parseEntryData(
                            page.text
                        );

                    if (!data) {
                        return;
                    }

                    if (
                        expectedType &&
                        String(
                            data.type || ''
                        ).toLowerCase() !==
                        expectedType.toLowerCase()
                    ) {
                        return;
                    }

                    result.push({
                        page:
                            page.title,

                        data:
                            data
                    });

                });

                return result;

            });

    }

    function getAllCategoryMembers(
        api,
        category,
        cmcontinue
    ) {

        var params = {
            action:
                'query',

            list:
                'categorymembers',

            cmtitle:
                category,

            cmlimit:
                'max',

            cmtype:
                'page',

            format:
                'json',

            formatversion:
                2
        };

        if (
            cmcontinue
        ) {

            params.cmcontinue =
                cmcontinue;

        }

        return apiRequest(
            api,
            params
        )
            .then(function (response) {

                var titles = [];

                if (
                    response.query &&
                    response.query.categorymembers
                ) {

                    titles =
                        response.query
                            .categorymembers
                            .map(function (page) {

                                return page.title;

                            });

                }

                if (
                    response.continue &&
                    response.continue.cmcontinue
                ) {

                    return getAllCategoryMembers(
                        api,
                        category,
                        response.continue.cmcontinue
                    )
                        .then(function (more) {

                            return titles.concat(
                                more
                            );

                        });

                }

                return titles;

            });

    }

    function getPagesContents(
        api,
        titles
    ) {

        var chunks = [];

        for (
            var i = 0;
            i < titles.length;
            i += 50
        ) {

            chunks.push(
                titles.slice(
                    i,
                    i + 50
                )
            );

        }

        return Promise.all(
            chunks.map(function (chunk) {

                return apiRequest(
                    api,
                    {
                        action:
                            'query',

                        prop:
                            'revisions',

                        titles:
                            chunk.join('|'),

                        rvprop:
                            'content',

                        rvslots:
                            'main',

                        redirects:
                            1,

                        format:
                            'json',

                        formatversion:
                            2
                    }
                );

            })
        )
            .then(function (responses) {

                var result = [];

                responses.forEach(function (response) {

                    if (
                        !response.query ||
                        !response.query.pages
                    ) {
                        return;
                    }

                    response.query.pages
                        .forEach(function (page) {

                            if (
                                page.missing ||
                                !page.revisions ||
                                !page.revisions.length
                            ) {
                                return;
                            }

                            var revision =
                                page.revisions[0];

                            var text = '';

                            if (
                                revision.slots &&
                                revision.slots.main
                            ) {

                                text =
                                    revision
                                        .slots
                                        .main
                                        .content ||
                                    revision
                                        .slots
                                        .main['*'] ||
                                    '';

                            } else {

                                text =
                                    revision.content ||
                                    revision['*'] ||
                                    '';

                            }

                            result.push({
                                title:
                                    page.title,

                                text:
                                    text
                            });

                        });

                });

                return result;

            });

    }

    function apiRequest(
        api,
        params
    ) {

        return new Promise(
            function (
                resolve,
                reject
            ) {

                api.get(
                    params
                )
                    .done(
                        resolve
                    )
                    .fail(function (
                        code,
                        details
                    ) {

                        reject(
                            normalizeApiError(
                                code,
                                details
                            )
                        );

                    });

            }
        );

    }

    function parseEntryData(text) {

        var match =
            String(
                text || ''
            ).match(
                /\{\{\s*EntryData\b([\s\S]*?)\n?\}\}/i
            );

        if (!match) {
            return null;
        }

        var data = {};
        var currentKey = null;

        match[1]
            .split(/\r?\n/)
            .forEach(function (line) {

                var parameter =
                    line.match(
                        /^\s*\|\s*([^=]+?)\s*=\s*(.*)$/
                    );

                if (
                    parameter
                ) {

                    currentKey =
                        parameter[1]
                            .trim()
                            .toLowerCase();

                    data[
                        currentKey
                    ] =
                        decodeTemplateValue(
                            parameter[2]
                                .trim()
                        );

                    return;

                }

                if (
                    currentKey &&
                    line.trim()
                ) {

                    data[
                        currentKey
                    ] +=
                        '\n' +
                        line.trim();

                }

            });

        return data;

    }

    function parseLocationWeights(
        value
    ) {

        var result = [];

        String(
            value || ''
        )
            .split(';')
            .forEach(function (part) {

                part =
                    part.trim();

                if (!part) {
                    return;
                }

                var separator =
                    part.lastIndexOf(
                        ':'
                    );

                if (
                    separator ===
                    -1
                ) {
                    return;
                }

                var location =
                    part
                        .slice(
                            0,
                            separator
                        )
                        .trim();

                var weight =
                    Number(
                        part
                            .slice(
                                separator + 1
                            )
                            .trim()
                    );

                if (
                    !location ||
                    !isFinite(
                        weight
                    ) ||
                    weight <= 0
                ) {
                    return;
                }

                result.push({
                    location:
                        location,

                    weight:
                        weight
                });

            });

        return result;

    }

    function getFishWeightForLocation(
        fish,
        locationName
    ) {

        var target =
            String(
                locationName || ''
            )
                .trim()
                .toLowerCase();

        for (
            var i = 0;
            i < fish.weights.length;
            i++
        ) {

            if (
                String(
                    fish.weights[i]
                        .location
                )
                    .trim()
                    .toLowerCase() ===
                target
            ) {

                return Number(
                    fish.weights[i]
                        .weight
                ) || 0;

            }

        }

        return 0;

    }

    function getFishForLocation(
        locationName
    ) {

        var result = [];
        var totalWeight = 0;

        fishEntries.forEach(function (fish) {

            var weight =
                getFishWeightForLocation(
                    fish,
                    locationName
                );

            if (
                weight <= 0
            ) {
                return;
            }

            totalWeight +=
                weight;

            result.push({
                fish:
                    fish,

                weight:
                    weight,

                chance:
                    0
            });

        });

        result.forEach(function (entry) {

            entry.chance =
                totalWeight > 0
                    ? (
                        entry.weight /
                        totalWeight
                    ) * 100
                    : 0;

        });

        result.sort(function (
            a,
            b
        ) {

            var aStars =
                getRarityStars(
                    a.fish.rarity
                );

            var bStars =
                getRarityStars(
                    b.fish.rarity
                );

            if (
                aStars !==
                bStars
            ) {

                return (
                    aStars -
                    bStars
                );

            }

            if (
                b.chance !==
                a.chance
            ) {

                return (
                    b.chance -
                    a.chance
                );

            }

            if (
                b.weight !==
                a.weight
            ) {

                return (
                    b.weight -
                    a.weight
                );

            }

            return String(
                a.fish.name || ''
            ).localeCompare(
                String(
                    b.fish.name || ''
                ),
                undefined,
                {
                    sensitivity:
                        'base'
                }
            );

        });

        return {
            entries:
                result,

            totalWeight:
                totalWeight
        };

    }

    function buildEntriesApp(
        container
    ) {

        container.innerHTML = '';

        var shell =
            document.createElement(
                'div'
            );

        shell.className =
            'wiki-entries-shell wiki-entries-start';

        var nav =
            document.createElement(
                'div'
            );

        nav.className =
            'wiki-entries-nav';

        var content =
            document.createElement(
                'div'
            );

        content.className =
            'wiki-entries-content';

        content.style.display =
            'none';

        var menuBar =
            document.createElement(
                'div'
            );

        menuBar.className =
            'wiki-entries-menu-bar';

        var menuButton =
            document.createElement(
                'button'
            );

        menuButton.type =
            'button';

        menuButton.className =
            'wiki-entries-menu-button';

        menuButton.innerHTML =
            '<span></span><span></span><span></span>';

        var displayStatus =
            document.createElement(
                'div'
            );

        displayStatus.className =
            'wiki-display-status';

        displayStatus.textContent =
            'Displaying: Percentage';

        menuBar.appendChild(
            menuButton
        );

        menuBar.appendChild(
            displayStatus
        );

        var sideMenu =
            document.createElement(
                'div'
            );

        sideMenu.className =
            'wiki-entries-side-menu';

        var displaySetting =
            document.createElement(
                'div'
            );

        displaySetting.className =
            'wiki-side-menu-setting';

        var displayLabel =
            document.createElement(
                'div'
            );

        displayLabel.className =
            'wiki-side-menu-label';

        displayLabel.textContent =
            'Display:';


        var displayToggle =
            document.createElement(
                'button'
            );

        displayToggle.type =
            'button';

        displayToggle.className =
            'wiki-display-toggle';

        displayToggle.textContent =
            'Percentage';


        displayToggle.addEventListener(
            'click',
            function () {

                if (
                    currentDisplayMode ===
                    'percentage'
                ) {

                    currentDisplayMode =
                        'fraction';

                    displayToggle.textContent =
                        'Fraction';

                    displayStatus.textContent =
                        'Displaying: Fraction';

                } else {

                    currentDisplayMode =
                        'percentage';

                    displayToggle.textContent =
                        'Percentage';

                    displayStatus.textContent =
                        'Displaying: Percentage';

                }

                if (
                    currentSection
                ) {

                    renderCurrentSection();

                }

            }
        );


        displaySetting.appendChild(
            displayLabel
        );

        displaySetting.appendChild(
            displayToggle
        );

        sideMenu.appendChild(
            displaySetting
        );

        var luckSetting =
            document.createElement(
                'div'
            );

        luckSetting.className =
            'wiki-side-menu-setting wiki-fish-luck-setting';

        var luckTitle =
            document.createElement(
                'div'
            );

        luckTitle.className =
            'wiki-side-menu-label';

        luckTitle.textContent =
            'Fish Luck Modifier';

        luckSetting.appendChild(
            luckTitle
        );

        var toolField =
            document.createElement(
                'label'
            );

        toolField.className =
            'wiki-setting-field';

        var toolText =
            document.createElement(
                'span'
            );

        toolText.textContent =
            'Select your tool:';

        var toolSelect =
            document.createElement(
                'select'
            );

        toolSelect.className =
            'wiki-setting-select';

        toolSelect.innerHTML =
            '';

        toolEntries.forEach(
            function (
                tool,
                index
            ) {

                var option =
                    document.createElement(
                        'option'
                    );

                option.value =
                    String(
                        index
                    );

                option.textContent =
                    tool.name;

                option.setAttribute(
                    'data-luck',
                    tool.luck
                );

                toolSelect.appendChild(
                    option
                );

            }
        );

        toolField.appendChild(
            toolText
        );

        toolField.appendChild(
            toolSelect
        );

        luckSetting.appendChild(
            toolField
        );

        var enchantField =
            document.createElement(
                'label'
            );

        enchantField.className =
            'wiki-setting-field';

        var enchantText =
            document.createElement(
                'span'
            );

        enchantText.textContent =
            'Fortune Enchant:';

        var enchantInput =
            document.createElement(
                'input'
            );

        enchantInput.type =
            'number';

        enchantInput.min =
            '0';

        enchantInput.step =
            '1';

        enchantInput.value =
            '0';

        enchantInput.className =
            'wiki-setting-select';

        enchantField.appendChild(
            enchantText
        );

        enchantField.appendChild(
            enchantInput
        );

        luckSetting.appendChild(
            enchantField
        );

        var upgradeField =
            document.createElement(
                'label'
            );

        upgradeField.className =
            'wiki-setting-field';

        var upgradeText =
            document.createElement(
                'span'
            );

        upgradeText.textContent =
            'Fish Upgrade: Fortune';

        var upgradeSelect =
            document.createElement(
                'select'
            );

        upgradeSelect.className =
            'wiki-setting-select';

        for (
            var upgradeLevel = 0;
            upgradeLevel <= 20;
            upgradeLevel++
        ) {

            var upgradeOption =
                document.createElement(
                    'option'
                );

            upgradeOption.value =
                upgradeLevel;

            upgradeOption.textContent =
                'Level ' + upgradeLevel;

            upgradeSelect.appendChild(
                upgradeOption
            );

        }

        upgradeField.appendChild(
            upgradeText
        );

        upgradeField.appendChild(
            upgradeSelect
        );

        luckSetting.appendChild(
            upgradeField
        );

        var baitField =
            document.createElement(
                'label'
            );

        baitField.className =
            'wiki-setting-field';

        var baitText =
            document.createElement(
                'span'
            );

        baitText.textContent =
            'Bait:';

        var baitSelect =
            document.createElement(
                'select'
            );

        baitSelect.className =
            'wiki-setting-select';

        baitSelect.innerHTML =
            '<option value="parmesan">Parmesan</option>' +
            '<option value="fusion-coil">Fusion Coil</option>';

        baitField.appendChild(
            baitText
        );

        baitField.appendChild(
            baitSelect
        );

        luckSetting.appendChild(
            baitField
        );

        sideMenu.appendChild(
            luckSetting
        );
        function updateToolSettings() {

            if (
                toolSelect.value ===
                'gun'
            ) {

                enchantText.textContent =
                    'Sharpshooter Enchant:';

                baitField.style.display =
                    'none';

            } else {

                enchantText.textContent =
                    'Fortune Enchant:';

                baitField.style.display =
                    'flex';

            }

        }

        toolSelect.addEventListener(
            'change',
            updateToolSettings
        );

        updateToolSettings();
        shell.appendChild(
            nav
        );

        shell.appendChild(
            content
        );

        var frame =
            document.createElement(
                'div'
        );

        frame.className =
            'wiki-entries-frame';

        frame.appendChild(
            menuBar
        );
        frame.appendChild(
            sideMenu
        );

        frame.appendChild(
            shell
        );

        container.appendChild(
            frame
        );

        menuButton.addEventListener(
            'click',
            function () {

                sideMenu.classList.toggle(
                    'wiki-side-menu-open'
                );

            }
        );

        createNavButton(
            nav,
            'Items',
            SIDE_ICONS.Items
        );

        createNavButton(
            nav,
            'Tools',
            SIDE_ICONS.Tools
        );

        createNavButton(
            nav,
            'Enchants',
            SIDE_ICONS.Enchants
        );

    }

    function createNavButton(
        container,
        section,
        imageName
    ) {

        var button =
            document.createElement(
                'button'
            );

        button.type =
            'button';

        button.className =
            'wiki-entry-nav-pill';

        button.setAttribute(
            'data-entry-section',
            section
        );

        var image =
            document.createElement(
                'img'
            );

        image.src =
            getWikiImageUrl(
                imageName
            );

        image.alt =
            section;

        var label =
            document.createElement(
                'span'
            );

        label.textContent =
            section;

        button.appendChild(
            image
        );

        button.appendChild(
            label
        );

        button.addEventListener(
            'click',
            function () {

                currentSection =
                    section;

                currentLocation =
                    null;

                var shell =
                    document.querySelector(
                        '#fish-entries-app .wiki-entries-shell'
                    );

                var content =
                    document.querySelector(
                        '#fish-entries-app .wiki-entries-content'
                    );

                if (
                    shell
                ) {

                    shell.classList.remove(
                        'wiki-entries-start'
                    );

                    shell.classList.add(
                        'wiki-entries-open'
                    );

                }

                if (
                    content
                ) {

                    content.style.display =
                        'block';

                }

                updateNavButtons();
                renderCurrentSection();

            }
        );

        container.appendChild(
            button
        );

    }

    function updateNavButtons() {

        document
            .querySelectorAll(
                '#fish-entries-app .wiki-entry-nav-pill'
            )
            .forEach(function (button) {

                var section =
                    button.getAttribute(
                        'data-entry-section'
                    );

                button.classList.toggle(
                    'entry-active',
                    section ===
                    currentSection
                );

            });

    }

    function renderCurrentSection() {

        updateNavButtons();

        var content =
            document.querySelector(
                '#fish-entries-app .wiki-entries-content'
            );

        if (
            !content
        ) {
            return;
        }

        content.innerHTML =
            '';

        if (
            currentSection ===
            'Items'
        ) {

            renderItemsSection(
                content
            );

            return;

        }

        if (
            currentSection ===
            'Tools'
        ) {

            renderToolsSection(
                content
            );

            return;

        }

        if (
            currentSection ===
            'Enchants'
        ) {

            renderEnchantsSection(
                content
            );

        }

    }

    function createSectionTitle(
        container,
        text
    ) {

        var title =
            document.createElement(
                'div'
            );

        title.className =
            'wiki-entry-content-title';

        title.textContent =
            text;

        container.appendChild(
            title
        );

    }

    function renderItemsSection(
        content
    ) {

        createSectionTitle(
            content,
            'Items'
        );

        var tabs =
            document.createElement(
                'div'
            );

        tabs.className =
            'wiki-entry-subtabs';

        var fishButton =
            createSubtabButton(
                'Fish'
            );

        var baitButton =
            createSubtabButton(
                'Baits'
            );

        tabs.appendChild(
            fishButton
        );

        tabs.appendChild(
            baitButton
        );

        content.appendChild(
            tabs
        );

        var body =
            document.createElement(
                'div'
            );

        body.className =
            'wiki-entry-items-body';

        content.appendChild(
            body
        );

        fishButton.addEventListener(
            'click',
            function () {

                currentItemTab =
                    'Fish';

                currentLocation =
                    null;

                updateItemTabs(
                    fishButton,
                    baitButton
                );

                renderFishLocations(
                    body
                );

            }
        );

        baitButton.addEventListener(
            'click',
            function () {

                currentItemTab =
                    'Baits';

                currentLocation =
                    null;

                updateItemTabs(
                    fishButton,
                    baitButton
                );

                renderBaits(
                    body
                );

            }
        );

        updateItemTabs(
            fishButton,
            baitButton
        );

        if (
            currentItemTab ===
            'Baits'
        ) {

            renderBaits(
                body
            );

        } else {

            renderFishLocations(
                body
            );

        }

    }

    function createSubtabButton(
        text
    ) {

        var button =
            document.createElement(
                'button'
            );

        button.type =
            'button';

        button.className =
            'wiki-entry-subtab';

        button.textContent =
            text;

        return button;

    }

    function updateItemTabs(
        fishButton,
        baitButton
    ) {

        fishButton.classList.toggle(
            'entry-active',
            currentItemTab ===
            'Fish'
        );

        baitButton.classList.toggle(
            'entry-active',
            currentItemTab ===
            'Baits'
        );

    }

    function renderFishLocations(
        body
    ) {

        body.innerHTML = '';

        if (
            currentLocation
        ) {

            renderLocationFish(
                body,
                currentLocation
            );

            return;

        }

        if (
            !locations.length
        ) {

            body.appendChild(
                createEmptyMessage(
                    'No locations have been published yet.'
                )
            );

            return;

        }

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-location-grid';

        locations.forEach(function (location) {

            var button =
                document.createElement(
                    'button'
                );

            button.type =
                'button';

            button.className =
                'wiki-location-pill';

            if (
                location.image
            ) {

                var image =
                    document.createElement(
                        'img'
                    );

                image.src =
                    getWikiImageUrl(
                        location.image
                    );

                image.alt =
                    location.name;

                button.appendChild(
                    image
                );

            }

            var name =
                document.createElement(
                    'div'
                );

            name.className =
                'wiki-location-name';

            name.textContent =
                location.name;

            button.appendChild(
                name
            );

            button.addEventListener(
                'click',
                function () {

                    currentLocation =
                        location;

                    renderFishLocations(
                        body
                    );

                }
            );

            grid.appendChild(
                button
            );

        });

        body.appendChild(
            grid
        );

    }

    function renderLocationFish(
        body,
        location
    ) {

        body.innerHTML =
            '';

        var header =
            document.createElement(
                'div'
            );

        header.className =
            'wiki-location-header';

        var title =
            document.createElement(
                'div'
            );

        title.className =
            'wiki-location-header-title';

        if (
            location.image
        ) {

            var image =
                document.createElement(
                    'img'
                );

            image.src =
                getWikiImageUrl(
                    location.image
                );

            image.alt =
                location.name;

            title.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'span'
            );

        name.textContent =
            location.name;

        title.appendChild(
            name
        );

        var back =
            document.createElement(
                'button'
            );

        back.type =
            'button';

        back.className =
            'wiki-entry-back';

        back.textContent =
            'Back';

        back.addEventListener(
            'click',
            function () {

                currentLocation =
                    null;

                renderFishLocations(
                    body
                );

            }
        );

        header.appendChild(
            title
        );

        header.appendChild(
            back
        );

        body.appendChild(
            header
        );

        var calculated =
            getFishForLocation(
                location.name
            );

        if (
            !calculated.entries.length
        ) {

            body.appendChild(
                createEmptyMessage(
                    'No fish can currently be caught here.'
                )
            );

            return;

        }

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-fish-grid';

        calculated.entries
            .forEach(function (entry) {

                grid.appendChild(
                    createFishCard(
                        entry.fish,
                        location,
                        entry.weight,
                        entry.chance,
                        calculated.totalWeight
                    )
                );

            });

        body.appendChild(
            grid
        );

    }

    function createFishCard(
        fish,
        location,
        weight,
        chance,
        totalWeight
    ) {

        var card =
            document.createElement(
                'button'
            );

        card.type =
            'button';

        card.className =
            'wiki-fish-card';

        applyRarityBorderClass(
            card,
            fish.rarity
        );

        if (
            fish.image
        ) {

            var image =
                document.createElement(
                    'img'
                );

            image.className =
                'wiki-fish-card-image';

            image.src =
                getWikiImageUrl(
                    fish.image
                );

            image.alt =
                fish.name;

            card.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'div'
            );

        name.className =
            'wiki-fish-card-name';

        name.textContent =
            fish.name;

        applyRarityClass(
            name,
            fish.rarity
        );

        card.appendChild(
            name
        );

        if (
            fish.rarity
        ) {

            var rarity =
                createRarityDisplay(
                    fish.rarity,
                    'wiki-fish-card-rarity'
                );

            if (
                rarity
            ) {
                card.appendChild(
                    rarity
                );
            }

        }

        var chanceText =
            document.createElement(
                'div'
            );

        chanceText.className =
            'wiki-fish-card-chance';

        chanceText.textContent =
            formatChance(
                chance
            );

        card.appendChild(
            chanceText
        );

        card.addEventListener(
            'click',
            function () {

                var body =
                    document.querySelector(
                        '#fish-entries-app .wiki-entry-items-body'
                    );

                if (
                    !body
                ) {
                    return;
                }

                renderFishDetail(
                    body,
                    fish,
                    location,
                    weight,
                    chance,
                    totalWeight
                );

            }
        );

        return card;

    }

    function renderFishDetail(
        body,
        fish,
        location,
        weight,
        chance,
        totalWeight
    ) {

        body.innerHTML =
            '';

        var detail =
            document.createElement(
                'div'
            );

        detail.className =
            'wiki-entry-detail';

        detail.appendChild(
            createBackButton(
                function () {

                    renderLocationFish(
                        body,
                        location
                    );

                }
            )
        );

        if (
            fish.image
        ) {

            var image =
                document.createElement(
                    'img'
                );

            image.className =
                'wiki-entry-detail-image';

            image.src =
                getWikiImageUrl(
                    fish.image
                );

            image.alt =
                fish.name;

            detail.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'div'
            );

        name.className =
            'wiki-entry-detail-name';

        name.textContent =
            fish.name;

        applyRarityClass(
            name,
            fish.rarity
        );

        detail.appendChild(
            name
        );

        if (
            fish.rarity
        ) {

            var rarity =
                createRarityDisplay(
                    fish.rarity,
                    'wiki-entry-detail-rarity'
                );

            if (
                rarity
            ) {
                detail.appendChild(
                    rarity
                );
            }

        }

        var stats =
            document.createElement(
                'div'
            );

        stats.className =
            'wiki-entry-stat-grid';

        stats.appendChild(
            createStat(
                'Chance',
                formatChance(
                    chance
                )
            )
        );

        stats.appendChild(
            createStat(
                'Weight',
                formatNumber(
                    weight
                )
            )
        );

        if (
            fish.baseSellPrice !==
            ''
        ) {

            stats.appendChild(
                createStat(
                    'Base Sell',
                    fish.baseSellPrice
                )
            );

        }

        detail.appendChild(
            stats
        );

        if (
            fish.description
        ) {

            var description =
                document.createElement(
                    'div'
                );

            description.className =
                'wiki-entry-description';

            renderLoreText(
                description,
                fish.description
            );

            detail.appendChild(
                description
            );

        }

        body.appendChild(
            detail
        );

    }

    function renderBaits(
        body
    ) {

        body.innerHTML =
            '';

        if (
            !baitEntries.length
        ) {

            body.appendChild(
                createEmptyMessage(
                    'No Bait entries have been published yet.'
                )
            );

            return;

        }

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-standard-entry-grid';

        baitEntries.forEach(function (bait) {

            grid.appendChild(
                createStandardCard(
                    bait,
                    function () {

                        renderStandardDetail(
                            body,
                            bait,
                            'Bait'
                        );

                    }
                )
            );

        });

        body.appendChild(
            grid
        );

    }

    function renderToolsSection(
        content
    ) {

        createSectionTitle(
            content,
            'Tools'
        );

        if (
            !toolEntries.length
        ) {

            content.appendChild(
                createEmptyMessage(
                    'No Tool entries have been published yet.'
                )
            );

            return;

        }

        var toolGroups = {};
        var rodTypeOrder = [];

        toolEntries.forEach(
            function (tool) {

                var rodType =
                    String(
                        tool.rodType ||
                        'Unassigned'
                    ).trim() ||
                    'Unassigned';

                var rodTypeKey =
                    rodType.toLowerCase();

                if (
                    !toolGroups[
                        rodTypeKey
                    ]
                ) {

                    toolGroups[
                        rodTypeKey
                    ] = {
                        name:
                            rodType,

                        tools:
                            []
                    };

                    rodTypeOrder.push(
                        rodTypeKey
                    );

                }

                toolGroups[
                    rodTypeKey
                ]
                    .tools
                    .push(
                        tool
                    );

            }
        );

        rodTypeOrder.forEach(
            function (rodTypeKey) {

                var toolGroup =
                    toolGroups[
                        rodTypeKey
                    ];

                var group =
                    document.createElement(
                        'div'
                    );

                group.className =
                    'wiki-tool-type-group';

                var pill =
                    document.createElement(
                        'div'
                    );

                pill.className =
                    'wiki-tool-type-pill';

                pill.textContent =
                    toolGroup.name;

                group.appendChild(
                    pill
                );

                var grid =
                    document.createElement(
                        'div'
                    );

                grid.className =
                    'wiki-standard-entry-grid';

                toolGroup.tools.forEach(
                    function (tool) {

                        grid.appendChild(
                            createStandardCard(
                                tool,
                                function () {

                                    renderToolDetail(
                                        content,
                                        tool
                                    );

                                }
                            )
                        );

                    }
                );

                group.appendChild(
                    grid
                );

                content.appendChild(
                    group
                );

            }
        );

    }

    function renderEnchantsSection(
        content
    ) {

        createSectionTitle(
            content,
            'Enchants'
        );

        if (
            !enchantEntries.length
        ) {

            content.appendChild(
                createEmptyMessage(
                    'No Enchant entries have been published yet.'
                )
            );

            return;

        }

        var enchantGroups = {};
        var rodTypeOrder = [];

        enchantEntries.forEach(
            function (enchant) {

                var rodType =
                    String(
                        enchant.rodType ||
                        'Unassigned'
                    ).trim() ||
                    'Unassigned';

                var rodTypeKey =
                    rodType.toLowerCase();

                if (
                    !enchantGroups[
                        rodTypeKey
                    ]
                ) {

                    enchantGroups[
                        rodTypeKey
                    ] = {
                        name:
                            rodType,

                        enchants:
                            []
                    };

                    rodTypeOrder.push(
                        rodTypeKey
                    );

                }

                enchantGroups[
                    rodTypeKey
                ]
                    .enchants
                    .push(
                        enchant
                    );

            }
        );

        rodTypeOrder.forEach(
            function (rodTypeKey) {

                var enchantGroup =
                    enchantGroups[
                        rodTypeKey
                    ];

                var totalWeight =
                    enchantGroup.enchants.reduce(
                        function (
                            total,
                            enchant
                        ) {

                            return (
                                total +
                                (
                                    Number(
                                        enchant.weight
                                    ) ||
                                    0
                                )
                            );

                        },
                        0
                    );

                enchantGroup.enchants.sort(
                    function (
                        a,
                        b
                    ) {

                        if (
                            a.weight !==
                            b.weight
                        ) {

                            return (
                                a.weight -
                                b.weight
                            );

                        }

                        return sortByName(
                            a,
                            b
                        );

                    }
                );

                var group =
                    document.createElement(
                        'div'
                    );

                group.className =
                    'wiki-tool-type-group';

                var pill =
                    document.createElement(
                        'div'
                    );

                pill.className =
                    'wiki-tool-type-pill';

                pill.textContent =
                    enchantGroup.name;

                group.appendChild(
                    pill
                );

                var grid =
                    document.createElement(
                        'div'
                    );

                grid.className =
                    'wiki-standard-entry-grid';

                enchantGroup.enchants.forEach(
                    function (enchant) {

                        var chance =
                            totalWeight > 0
                                ? (
                                    enchant.weight /
                                    totalWeight
                                ) * 100
                                : 0;

                        var card =
                            createStandardCard(
                                enchant,
                                function () {

                                    renderEnchantDetail(
                                        content,
                                        enchant,
                                        chance,
                                        totalWeight
                                    );

                                }
                            );

                        var chanceLabel =
                            document.createElement(
                                'div'
                            );

                        chanceLabel.className =
                            'wiki-standard-card-extra';

                        chanceLabel.textContent =
                            formatChance(
                                chance
                            );

                        card.appendChild(
                            chanceLabel
                        );

                        grid.appendChild(
                            card
                        );

                    }
                );

                group.appendChild(
                    grid
                );

                content.appendChild(
                    group
                );

            }
        );

    }

