            entry.name;

        if (
            entry.rarity
        ) {

            applyRarityClass(
                name,
                entry.rarity
            );

        }

        detail.appendChild(
            name
        );

        if (
            entry.rarity
        ) {

            var rarity =
                createRarityDisplay(
                    entry.rarity,
                    'wiki-entry-detail-rarity'
                );

            if (
