            );

        button.type =
            'button';

        button.className =
            'wiki-entry-back';

        button.textContent =
            'Back';

        button.addEventListener(
            'click',
            onClick
        );

        wrapper.appendChild(
            button
        );

        return wrapper;

    }

    function createStat(
        labelText,
        valueText
    ) {

        var stat =
            document.createElement(
                'div'
            );

        stat.className =
            'wiki-entry-stat';

        var label =
