                    };

                    rodTypeOrder.push(
                        rodTypeKey
                    );

                }

                toolGroups[
                    rodTypeKey
                ]
                    .tools
                    .push(
                        tool
                    );

            }
        );

        rodTypeOrder.forEach(
            function (rodTypeKey) {

                var toolGroup =
