            'wiki-entry-detail';

        detail.appendChild(
            createBackButton(
                function () {

                    if (
                        type ===
                        'Bait'
                    ) {

                        renderBaits(
                            body
                        );

                    }

                }
            )
        );

        appendDetailBasicInfo(
            detail,
            entry
        );

        body.appendChild(
