    function renderEnchantDetail(
        content,
        enchant,
        chance,
        totalWeight
    ) {

        content.innerHTML =
            '';

        createSectionTitle(
            content,
            'Enchants'
        );

        var detail =
            document.createElement(
                'div'
            );

        detail.className =
            'wiki-entry-detail';

        detail.appendChild(
            createBackButton(
                function () {

