    function appendDetailBasicInfo(
        detail,
        entry
    ) {

        if (
            entry.image
        ) {

            var image =
                document.createElement(
                    'img'
                );

            image.className =
                'wiki-entry-detail-image';

            image.src =
                getWikiImageUrl(
                    entry.image
                );

            image.alt =
                entry.name;

            detail.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'div'
            );

        name.className =
            'wiki-entry-detail-name';

        name.textContent =
            entry.name;

        if (
            entry.rarity
        ) {

            applyRarityClass(
                name,
                entry.rarity
            );

        }

        detail.appendChild(
            name
        );

        if (
            entry.rarity
        ) {

            var rarity =
                createRarityDisplay(
                    entry.rarity,
                    'wiki-entry-detail-rarity'
                );

            if (
                rarity
            ) {
                detail.appendChild(
                    rarity
                );
            }

        }

        if (
            entry.description
        ) {

            var description =
                document.createElement(
                    'div'
                );

            description.className =
                'wiki-entry-description';

            renderLoreText(
                description,
                entry.description
            );

            detail.appendChild(
                description
            );

        }

    }

    function renderLoreText(
        element,
        text
    ) {

        text =
            String(
                text || ''
            );

        var regex =
            /\[(blue|formula)\]([\s\S]*?)\[\/\1\]/gi;

        var lastIndex = 0;
        var match;

        while (
            (
                match =
                    regex.exec(
                        text
                    )
            ) !==
            null
        ) {

            if (
                match.index >
                lastIndex
            ) {

                element.appendChild(
                    document.createTextNode(
                        text.slice(
                            lastIndex,
                            match.index
                        )
                    )
                );

            }


            var styledText =
                document.createElement(
                    'span'
                );


            if (
                match[1].toLowerCase() ===
                'blue'
            ) {

                styledText.className =
                    'wiki-lore-blue';

            } else if (
                match[1].toLowerCase() ===
                'formula'
            ) {

                styledText.className =
                    'wiki-lore-formula';

            }


            styledText.textContent =
                match[2];


            element.appendChild(
                styledText
            );


            lastIndex =
                regex.lastIndex;

        }


        if (
            lastIndex <
            text.length
        ) {

            element.appendChild(
                document.createTextNode(
                    text.slice(
                        lastIndex
                    )
                )
            );

        }

    }

    function createRarityDisplay(
        rarityName,
        className
    ) {

        rarityName =
            String(
                rarityName || ''
            ).trim();

        if (
            !rarityName
        ) {
            return null;
        }

        var wrapper =
            document.createElement(
                'div'
            );

        wrapper.className =
            className;

        var rarityText =
            document.createElement(
                'span'
            );

        rarityText.textContent =
            capitalizeFirst(
                rarityName
            );

        applyRarityClass(
            rarityText,
            rarityName
        );

        wrapper.appendChild(
            rarityText
        );

        var rarity =
            rarityEntries[
                rarityName.toLowerCase()
            ];

        if (
            rarity &&
            rarity.stars > 0
        ) {

            var stars =
                document.createElement(
                    'span'
                );

            stars.className =
                'wiki-rarity-stars-inline';

            stars.textContent =
                '★'.repeat(
                    rarity.stars
                );

            applyRarityClass(
                stars,
                rarityName
            );

            wrapper.appendChild(
                stars
            );

        }

        return wrapper;

    }

    function createBackButton(
        onClick
    ) {

        var wrapper =
            document.createElement(
                'div'
            );

        wrapper.className =
            'wiki-detail-back-row';

        var button =
            document.createElement(
                'button'
            );

        button.type =
            'button';

        button.className =
            'wiki-entry-back';

        button.textContent =
            'Back';

        button.addEventListener(
            'click',
            onClick
        );

        wrapper.appendChild(
            button
        );

        return wrapper;

    }

    function createStat(
        labelText,
        valueText
    ) {

        var stat =
            document.createElement(
                'div'
            );

        stat.className =
            'wiki-entry-stat';

        var label =
            document.createElement(
                'div'
            );

        label.className =
            'wiki-entry-stat-label';

        label.textContent =
            labelText;

        var value =
            document.createElement(
                'div'
            );

        value.className =
            'wiki-entry-stat-value';

        value.textContent =
            valueText;

        stat.appendChild(
            label
        );

        stat.appendChild(
            value
        );

        return stat;

    }

    function createEmptyMessage(
        message
    ) {

        var div =
            document.createElement(
                'div'
            );

        div.className =
            'wiki-entry-empty';

        div.textContent =
            message;

        return div;

    }

    function injectRarityStyles() {

        var old =
            document.getElementById(
                'wiki-dynamic-rarity-styles'
            );

        if (
            old
        ) {
            old.remove();
        }

        var css = '';

        Object.keys(
            rarityEntries
        )
            .forEach(function (key) {

                var rarity =
                    rarityEntries[
                        key
                    ];

                var slug =
                    makeSlug(
                        rarity.name
                    );

                var animation =
                    'wiki-rarity-' +
                    slug;

                css +=
                    '@keyframes ' +
                    animation +
                    '{' +
                    '0%{color:' +
                    rarity.color0 +
                    ';}' +
                    '50%{color:' +
                    rarity.color50 +
                    ';}' +
                    '100%{color:' +
                    rarity.color100 +
                    ';}' +
                    '}';

                css +=
                    '.wiki-dynamic-rarity-' +
                    slug +
                    '{animation:' +
                    animation +
                    ' 3s ease-in-out infinite !important;}';

            });

        var style =
            document.createElement(
                'style'
            );

        style.id =
            'wiki-dynamic-rarity-styles';

        style.textContent =
            css;

        document.head.appendChild(
            style
        );

    }

    function applyRarityClass(
        element,
        rarity
    ) {

        rarity =
            String(
                rarity || ''
            ).trim();

        if (
            !rarity
        ) {
            return;
        }

        var slug =
            makeSlug(
                rarity
            );

        element.classList.add(
            'entry-name-rarity-' +
            slug
        );

        if (
            rarityEntries[
                rarity.toLowerCase()
            ]
        ) {

            element.classList.add(
                'wiki-dynamic-rarity-' +
                slug
            );

        }

    }

    function applyRarityBorderClass(
        element,
        rarity
    ) {

        rarity =
            String(
                rarity || ''
            ).trim();

        if (
            !rarity
        ) {
            return;
        }

        var rarityData =
            rarityEntries[
                rarity.toLowerCase()
            ];

        if (
            !rarityData
        ) {
            return;
        }

        element.classList.add(
            'wiki-rarity-animated-border'
        );

        element.style.setProperty(
            '--rarity-border-color-0',
            rarityData.color0
        );

        element.style.setProperty(
            '--rarity-border-color-50',
            rarityData.color50
        );

    }

    function makeSlug(
        value
    ) {

        return String(
            value || ''
        )
            .toLowerCase()
            .trim()
            .replace(
                /[^a-z0-9]+/g,
                '-'
            )
            .replace(
                /^-+|-+$/g,
                ''
            );

    }

    function normalizeHexColor(
        value
    ) {

        value =
            String(
                value || ''
            )
                .trim()
                .toLowerCase();

        if (
            /^[0-9a-f]{6}$/i.test(
                value
            )
        ) {

            value =
                '#' +
                value;

        }

        if (
            /^#[0-9a-f]{6}$/i.test(
                value
            )
        ) {

            return value;

        }

        return '';

    }

    function getWikiImageUrl(
        filename
    ) {

        filename =
            String(
                filename || ''
            )
                .replace(
                    /^File:/i,
                    ''
                )
                .trim();

        return mw.util.getUrl(
            'Special:Redirect/file/' +
            filename
        );

    }

    function getNameFromPage(
        page
    ) {

        page =
            String(
                page || ''
            );

        var separator =
            page.indexOf(
                ':'
            );

        if (
            separator !==
            -1
        ) {

            return page
                .slice(
                    separator + 1
                )
                .trim();

        }

        return page.trim();

    }

    function sortByName(
        a,
        b
    ) {

        return String(
            a.name || ''
        ).localeCompare(
            String(
                b.name || ''
            ),
            undefined,
            {
                sensitivity:
                    'base'
            }
        );

    }

    function formatChance(
        value
    ) {

        value =
            Number(
                value
            );

        if (
            currentDisplayMode ===
            'percentage'
        ) {

            return formatPercent(
                value
            );

        }

        if (
            !isFinite(
                value
            ) ||
            value <= 0
        ) {

            return '1/∞';

        }


        var denominator =
            100 / value;

        if (
            Math.abs(
                denominator -
                Math.round(
                    denominator
                )
            ) < 0.000001
        ) {

            denominator =
                Math.round(
                    denominator
                );

        } else {

            denominator =
                denominator
                    .toFixed(
                        3
                    )
                    .replace(
                        /\.?0+$/,
                        ''
                    );

        }


        return (
            '1/' +
            denominator
        );

    }

    function formatPercent(
        value
    ) {

        value =
            Number(
                value
            );

        if (
            !isFinite(
                value
            )
        ) {

            return '0%';

        }

        if (
            value >= 10
        ) {

            return (
                value
                    .toFixed(2)
                    .replace(
                        /\.?0+$/,
                        ''
                    ) +
                '%'
            );

        }

        if (
            value >= 1
        ) {

            return (
                value
                    .toFixed(3)
                    .replace(
                        /\.?0+$/,
                        ''
                    ) +
                '%'
            );

        }

        return (
            value
                .toFixed(6)
                .replace(
                    /\.?0+$/,
                    ''
                ) +
            '%'
        );

    }

    function formatNumber(
        value
    ) {

        value =
            Number(
                value
            );

        if (
            !isFinite(
                value
            )
        ) {

            return '0';

        }

        return value.toLocaleString();

    }

    function decodeTemplateValue(
        value
    ) {

        return String(
            value || ''
        )
            .replace(
                /&#124;/g,
                '|'
            )
            .replace(
                /&#123;&#123;/g,
                '{{'
            )
            .replace(
                /&#125;&#125;/g,
                '}}'
            )
            .replace(
                /\}&#125;/g,
                '}}'
            );

    }

    function normalizeApiError(
        code,
        details
    ) {

        var error = {
            code:
                code ||
                'api-error',

            info:
                '',

            details:
                details ||
                null
        };

        if (
            details &&
            details.error
        ) {

            if (
                details.error.code
            ) {

                error.code =
                    details.error.code;

            }

            if (
                details.error.info
            ) {

                error.info =
                    details.error.info;

            }

        }

        if (
            !error.info &&
            details &&
            details.info
        ) {

            error.info =
                details.info;

        }

        if (
            !error.info &&
            typeof details ===
            'string'
        ) {

            error.info =
                details;

        }

        if (
            !error.info
        ) {

            error.info =
                'MediaWiki returned an API error.';

        }

        return error;

    }

    function formatError(
        error
    ) {

        if (
            !error
        ) {

            return 'Unknown error.';

        }

        if (
            typeof error ===
            'string'
        ) {

            return error;

        }

        if (
            error.code &&
            error.info
        ) {

            return (
                error.code +
                ': ' +
                error.info
            );

        }

        return (
            error.info ||
            error.code ||
            error.message ||
            'Unknown error.'
        );

    }

    function escapeHtml(
        value
    ) {

        return String(
            value || ''
        )
            .replace(
                /&/g,
                '&amp;'
            )
            .replace(
                /</g,
                '&lt;'
            )
            .replace(
                />/g,
                '&gt;'
            )
            .replace(
                /"/g,
                '&quot;'
            )
            .replace(
                /'/g,
                '&#039;'
            );

    }

})();

(function () {

    var ENTRIES_PAGE = 'Fish_entries:sandbox';

    var CATEGORIES = {
        Fish: 'Category:Fish Entries',
        Bait: 'Category:Bait Entries',
        Tool: 'Category:Tool Entries',
        Enchant: 'Category:Enchant Entries',
        Location: 'Category:Fish Locations',
        Rarity: 'Category:Rarity Entries'
    };

    var SIDE_ICONS = {
        Items: 'Ball.png',
        Tools: 'Fishing_Rod.png',
        Enchants: 'strength.png'
    };

    var locations = [];
    var fishEntries = [];
    var baitEntries = [];
    var toolEntries = [];
    var enchantEntries = [];
    var rarityEntries = {};

    var currentSection = null;
    var currentItemTab = 'Fish';
    var currentLocation = null;
    var currentDisplayMode ='percentage';
    var ENTRIES_CACHE_VERSION =
    '1';
    var ENTRIES_CACHE_PREFIX =
    'fishEntriesCacheV';
    var ENTRIES_CACHE_KEY =
    ENTRIES_CACHE_PREFIX +
    ENTRIES_CACHE_VERSION;
    var itemsLoaded = false;
    var toolsLoaded = false;
    var enchantsLoaded = false;
    var itemsLoadPromise = null;
    var toolsLoadPromise = null;
    var enchantsLoadPromise = null;
    function clearOldEntriesCaches() {

        try {

            for (
                var i =
                    window.localStorage.length - 1;
                i >= 0;
                i--
            ) {

                var key =
                    window.localStorage.key(
                        i
                    );

                if (
                    key &&
                    key.indexOf(
                        ENTRIES_CACHE_PREFIX
                    ) === 0 &&
                    key !==
                    ENTRIES_CACHE_KEY
                ) {

                    window.localStorage.removeItem(
                        key
                    );

                }

            }

        } catch (error) {

            console.warn(
                'Old Entries Cache Cleanup Error:',
                error
            );

        }

    }

    function loadEntriesCache() {

        try {

            var rawCache =
                window.localStorage.getItem(
                    ENTRIES_CACHE_KEY
                );

            if (
                !rawCache
            ) {
                return false;
            }

            var cache =
                JSON.parse(
                    rawCache
                );
            if (
                !cache ||
                !cache.savedAt ||
                (
                    Date.now() -
                    Number(
                        cache.savedAt
                    )
                ) >
                ENTRIES_CACHE_MAX_AGE
            ) {

                window.localStorage.removeItem(
                    ENTRIES_CACHE_KEY
                );

                return false;

            }

            if (
                !cache ||
                !Array.isArray(
                    cache.locations
                ) ||
                !Array.isArray(
                    cache.fishEntries
                ) ||
                !Array.isArray(
                    cache.baitEntries
                ) ||
                !Array.isArray(
                    cache.toolEntries
                ) ||
                !Array.isArray(
                    cache.enchantEntries
                ) ||
                !cache.rarityEntries
            ) {

                return false;

            }

            locations =
                cache.locations;

            fishEntries =
                cache.fishEntries;

            baitEntries =
                cache.baitEntries;

            toolEntries =
                cache.toolEntries;

            enchantEntries =
                cache.enchantEntries;

            rarityEntries =
                cache.rarityEntries;

            itemsLoaded =
                true;

            toolsLoaded =
                true;

            enchantsLoaded =
                true;

            return true;

        } catch (error) {

            console.warn(
                'Entries Cache Load Error:',
                error
            );

            return false;

        }

    }

    function saveEntriesCache() {

        try {

            window.localStorage.setItem(
                ENTRIES_CACHE_KEY,
                JSON.stringify({
                    savedAt:
                        Date.now(),

                    locations:
                        locations,

                    fishEntries:
                        fishEntries,

                    baitEntries:
                        baitEntries,

                    toolEntries:
                        toolEntries,

                    enchantEntries:
                        enchantEntries,

                    rarityEntries:
                        rarityEntries
                })
            );

        } catch (error) {

            console.warn(
                'Entries Cache Save Error:',
                error
            );

        }

    }

    $(function () {

        if (
            normalizePageName(
                mw.config.get('wgPageName')
            ) !==
            normalizePageName(
                ENTRIES_PAGE
            )
        ) {
            return;
        }

        var container =
            document.getElementById(
                'fish-entries-app'
            );

        if (!container) {
            return;
        }

        if (
            container.dataset.loaded ===
            'true'
        ) {
            return;
        }

        container.dataset.loaded =
            'true';

        clearOldEntriesCaches();

        container.innerHTML =
            '<div class="entries-app-loading">Loading entries...</div>';

        loadMediaWikiModules()
            .then(function () {

                var cacheLoaded =
                    loadEntriesCache();

                if (
                    cacheLoaded
                ) {

                    fishEntries.sort(
                        sortByRarity
                    );

                    baitEntries.sort(
                        sortByRarity
                    );

                    injectRarityStyles();

                    buildEntriesApp(
                        container
                    );

                    return;
                }

                return ensureSectionLoaded(
                    'Tools'
                )
                    .then(function () {

                        buildEntriesApp(
                            container
                        );

                        return preloadEntries();

                    });

            })

            .catch(function (error) {

                console.error(
                    'Fish Entries App Error:',
                    error
                );

                container.innerHTML =
                    '<div class="entries-app-error">' +
                    escapeHtml(
                        formatError(
                            error
                        )
                    ) +
                    '</div>';

            });

    });

    function normalizePageName(value) {

        return String(
            value || ''
        )
            .replace(/_/g, ' ')
            .replace(/\s+/g, ' ')
            .trim()
            .toLowerCase();

    }

    function capitalizeFirst(value) {

        value =
            String(
                value || ''
            ).trim();

        if (!value) {
            return '';
        }

        return (
            value.charAt(0).toUpperCase() +
            value.slice(1).toLowerCase()
        );

    }

    function loadMediaWikiModules() {

        return mw.loader.using([
            'mediawiki.api',
            'mediawiki.util'
        ]);

    }
    function ensureSectionLoaded(
        section
    ) {

        if (
            section ===
            'Items'
        ) {

            if (
                itemsLoaded
            ) {
                return Promise.resolve();
            }

            if (
                itemsLoadPromise
            ) {
                return itemsLoadPromise;
            }

            itemsLoadPromise =
                Promise.all([
                    loadLocations(),
                    loadFish(),
                    loadBaits(),
                    loadRarities()
                ])
                    .then(function () {

                        fishEntries.sort(
                            sortByRarity
                        );

                        baitEntries.sort(
                            sortByRarity
                        );

                        injectRarityStyles();

                        itemsLoaded =
                            true;

                    })
                    .catch(function (
                        error
                    ) {

                        itemsLoadPromise =
                            null;

                        throw error;

                    });

            return itemsLoadPromise;

        }


        if (
            section ===
            'Tools'
        ) {

            if (
                toolsLoaded
            ) {
                return Promise.resolve();
            }

            if (
                toolsLoadPromise
            ) {
                return toolsLoadPromise;
            }

            toolsLoadPromise =
                loadTools()
                    .then(function () {

                        toolsLoaded =
                            true;

                    })
                    .catch(function (
                        error
                    ) {

                        toolsLoadPromise =
                            null;

                        throw error;

                    });

            return toolsLoadPromise;

        }


        if (
            section ===
            'Enchants'
        ) {

            if (
                enchantsLoaded
            ) {
                return Promise.resolve();
            }

            if (
                enchantsLoadPromise
            ) {
                return enchantsLoadPromise;
            }

            enchantsLoadPromise =
                loadEnchants()
                    .then(function () {

                        enchantsLoaded =
                            true;

                    })
                    .catch(function (
                        error
                    ) {

                        enchantsLoadPromise =
                            null;

                        throw error;

                    });

            return enchantsLoadPromise;

        }


        return Promise.resolve();

    }
    function preloadEntries() {

        return Promise.all([
            ensureSectionLoaded(
                'Items'
            ),

            ensureSectionLoaded(
                'Tools'
            ),

            ensureSectionLoaded(
                'Enchants'
            )
        ])
            .then(function () {

                saveEntriesCache();

            })
            .catch(function (
                error
            ) {

                console.warn(
                    'Entries Preload Error:',
                    error
                );

            });

    }

    function loadLocations() {

        var api =
            new mw.Api();

        return getCategoryEntryPages(
            api,
            CATEGORIES.Location,
            'Location'
        )
            .then(function (entries) {

                locations =
                    entries.map(function (entry) {

                        return {
                            page:
                                entry.page,

                            name:
                                entry.data.name ||
                                getNameFromPage(
                                    entry.page
                                ),

                            image:
                                entry.data.image ||
                                ''
                        };

                    });

                locations.sort(
                    sortByName
                );

            });

    }

    function loadFish() {

        var api =
            new mw.Api();

        return getCategoryEntryPages(
            api,
            CATEGORIES.Fish,
            'Fish'
        )
            .then(function (entries) {

                fishEntries =
                    entries.map(function (entry) {

                        return {
                            page:
                                entry.page,

                            name:
                                entry.data.name ||
                                getNameFromPage(
                                    entry.page
                                ),

                            image:
                                entry.data.image ||
                                '',

                            rarity:
                                entry.data.rarity ||
                                '',

                            description:
                                entry.data.description ||
                                '',

                            baseSellPrice:
                                entry.data.base_sell_price ||
                                '',

                            weights:
                                parseLocationWeights(
                                    entry.data.location_weights
                                )
                        };

                    });

            });

    }

    function loadBaits() {

        var api =
            new mw.Api();

        return getCategoryEntryPages(
            api,
            CATEGORIES.Bait,
            'Bait'
        )
            .then(function (entries) {

                baitEntries =
                    entries.map(function (entry) {

                        return {
                            page:
                                entry.page,

                            name:
                                entry.data.name ||
                                getNameFromPage(
                                    entry.page
                                ),

                            image:
                                entry.data.image ||
                                '',

                            rarity:
                                entry.data.rarity ||
                                '',

                            description:
                                entry.data.description ||
                                ''
                        };

                    });

            });

    }

    function loadTools() {

        var api =
            new mw.Api();

        return getCategoryEntryPages(
            api,
            CATEGORIES.Tool,
            'Tool'
        )
            .then(function (entries) {

                toolEntries =
                    entries.map(function (entry) {

                        return {
                            page:
                                entry.page,

                            name:
                                entry.data.name ||
                                getNameFromPage(
                                    entry.page
                                ),

                            image:
                                entry.data.image ||
                                '',

                            description:
                                entry.data.description ||
                                '',

                            baseCost:
                                entry.data.base_cost ||
                                '',
                            rodType:
                                String(
                                    entry.data.rod_type ||
                                    'Unassigned'
                                ).trim() ||
                                'Unassigned',
                            luck:
                                entry.data.luck !==
                                undefined
                                    ? Number(
                                        entry.data.luck
                                    )
                                    : 0
                        };

                    });

                toolEntries.sort(function (
                    a,
                    b
                ) {

                    var aCost =
                        Number(
                            a.baseCost
                        );

                    var bCost =
                        Number(
                            b.baseCost
                        );

                    if (
                        !Number.isFinite(
                            aCost
                        )
                    ) {
                        aCost = Infinity;
                    }

                    if (
                        !Number.isFinite(
                            bCost
                        )
                    ) {
                        bCost = Infinity;
                    }

                    if (
                        aCost !==
                        bCost
                    ) {

                        return (
                            aCost -
                            bCost
                        );

                    }

                    return sortByName(
                        a,
                        b
                    );

                });

            });

    }

    function loadEnchants() {

        var api =
            new mw.Api();

        return getCategoryEntryPages(
            api,
            CATEGORIES.Enchant,
            'Enchant'
        )
            .then(function (entries) {

                enchantEntries =
                    entries.map(function (entry) {

                        return {
                            page:
                                entry.page,

                            name:
                                entry.data.name ||
                                getNameFromPage(
                                    entry.page
                                ),

                            image:
                                entry.data.image ||
                                '',

                            description:
                                entry.data.description ||
                                '',
                            rodType:
                                String(
                                    entry.data.rod_type ||
                                    'Unassigned'
                                ).trim() ||
                                'Unassigned',
                            weight:
                                Number(
                                    entry.data.weight ||
                                    0
                                )
                        };

                    });

                enchantEntries.sort(function (
                    a,
                    b
                ) {

                    if (
                        a.weight !==
                        b.weight
                    ) {

                        return (
                            a.weight -
                            b.weight
                        );

                    }

                    return sortByName(
                        a,
                        b
                    );

                });

            });

    }

    function loadRarities() {

        var api =
            new mw.Api();

        return getCategoryEntryPages(
            api,
            CATEGORIES.Rarity,
            'Rarity'
        )
            .then(function (entries) {

                rarityEntries = {};

                entries.forEach(function (entry) {

                    var name =
                        String(
                            entry.data.name ||
                            getNameFromPage(
                                entry.page
                            )
                        ).trim();

                    if (!name) {
                        return;
                    }

                    var stars =
                        Number(
                            entry.data.stars
                        );

                    if (
                        !Number.isInteger(
                            stars
                        ) ||
                        stars < 0
                    ) {
                        stars = 0;
                    }

                    rarityEntries[
                        name.toLowerCase()
                    ] = {
                        name:
                            name,

                        stars:
                            stars,

                        color0:
                            normalizeHexColor(
                                entry.data.color_0
                            ) ||
                            '#ffffff',

                        color50:
                            normalizeHexColor(
                                entry.data.color_50
                            ) ||
                            '#ffffff',

                        color100:
                            normalizeHexColor(
                                entry.data.color_100
                            ) ||
                            '#ffffff'
                    };

                });

            });

    }

    function getRarityStars(
        rarityName
    ) {

        var rarity =
            rarityEntries[
                String(
                    rarityName || ''
                )
                    .trim()
                    .toLowerCase()
            ];

        if (!rarity) {
            return 999999;
        }

        var stars =
            Number(
                rarity.stars
            );

        if (
            !Number.isFinite(
                stars
            )
        ) {
            return 999999;
        }

        return stars;

    }

    function sortByRarity(
        a,
        b
    ) {

        var aStars =
            getRarityStars(
                a.rarity
            );

        var bStars =
            getRarityStars(
                b.rarity
            );

        if (
            aStars !==
            bStars
        ) {

            return (
                aStars -
                bStars
            );

        }

        return sortByName(
            a,
            b
        );

    }

    function getCategoryEntryPages(
        api,
        category,
        expectedType
    ) {

        return getAllCategoryMembers(
            api,
            category
        )
            .then(function (titles) {

                if (!titles.length) {
                    return [];
                }

                return getPagesContents(
                    api,
                    titles
                );

            })
            .then(function (pages) {

                if (!pages) {
                    return [];
                }

                var result = [];

                pages.forEach(function (page) {

                    var data =
                        parseEntryData(
                            page.text
                        );

                    if (!data) {
                        return;
                    }

                    if (
                        expectedType &&
                        String(
                            data.type || ''
                        ).toLowerCase() !==
                        expectedType.toLowerCase()
                    ) {
                        return;
                    }

                    result.push({
                        page:
                            page.title,

                        data:
                            data
                    });

                });

                return result;

            });

    }

    function getAllCategoryMembers(
        api,
        category,
        cmcontinue
    ) {

        var params = {
            action:
                'query',

            list:
                'categorymembers',

            cmtitle:
                category,

            cmlimit:
                'max',

            cmtype:
                'page',

            format:
                'json',

            formatversion:
                2
        };

        if (
            cmcontinue
        ) {

            params.cmcontinue =
                cmcontinue;

        }

        return apiRequest(
            api,
            params
        )
            .then(function (response) {

                var titles = [];

                if (
                    response.query &&
                    response.query.categorymembers
                ) {

                    titles =
                        response.query
                            .categorymembers
                            .map(function (page) {

                                return page.title;

                            });

                }

                if (
                    response.continue &&
                    response.continue.cmcontinue
                ) {

                    return getAllCategoryMembers(
                        api,
                        category,
                        response.continue.cmcontinue
                    )
                        .then(function (more) {

                            return titles.concat(
                                more
                            );

                        });

                }

                return titles;

            });

    }

    function getPagesContents(
        api,
        titles
    ) {

        var chunks = [];

        for (
            var i = 0;
            i < titles.length;
            i += 50
        ) {

            chunks.push(
                titles.slice(
                    i,
                    i + 50
                )
            );

        }

        return Promise.all(
            chunks.map(function (chunk) {

                return apiRequest(
                    api,
                    {
                        action:
                            'query',

                        prop:
                            'revisions',

                        titles:
                            chunk.join('|'),

                        rvprop:
                            'content',

                        rvslots:
                            'main',

                        redirects:
                            1,

                        format:
                            'json',

                        formatversion:
                            2
                    }
                );

            })
        )
            .then(function (responses) {

                var result = [];

                responses.forEach(function (response) {

                    if (
                        !response.query ||
                        !response.query.pages
                    ) {
                        return;
                    }

                    response.query.pages
                        .forEach(function (page) {

                            if (
                                page.missing ||
                                !page.revisions ||
                                !page.revisions.length
                            ) {
                                return;
                            }

                            var revision =
                                page.revisions[0];

                            var text = '';

                            if (
                                revision.slots &&
                                revision.slots.main
                            ) {

                                text =
                                    revision
                                        .slots
                                        .main
                                        .content ||
                                    revision
                                        .slots
                                        .main['*'] ||
                                    '';

                            } else {

                                text =
                                    revision.content ||
                                    revision['*'] ||
                                    '';

                            }

                            result.push({
                                title:
                                    page.title,

                                text:
                                    text
                            });

                        });

                });

                return result;

            });

    }

    function apiRequest(
        api,
        params
    ) {

        return new Promise(
            function (
                resolve,
                reject
            ) {

                api.get(
                    params
                )
                    .done(
                        resolve
                    )
                    .fail(function (
                        code,
                        details
                    ) {

                        reject(
                            normalizeApiError(
                                code,
                                details
                            )
                        );

                    });

            }
        );

    }

    function parseEntryData(text) {

        var match =
            String(
                text || ''
            ).match(
                /\{\{\s*EntryData\b([\s\S]*?)\n?\}\}/i
            );

        if (!match) {
            return null;
        }

        var data = {};
        var currentKey = null;

        match[1]
            .split(/\r?\n/)
            .forEach(function (line) {

                var parameter =
                    line.match(
                        /^\s*\|\s*([^=]+?)\s*=\s*(.*)$/
                    );

                if (
                    parameter
                ) {

                    currentKey =
                        parameter[1]
                            .trim()
                            .toLowerCase();

                    data[
                        currentKey
                    ] =
                        decodeTemplateValue(
                            parameter[2]
                                .trim()
                        );

                    return;

                }

                if (
                    currentKey &&
                    line.trim()
                ) {

                    data[
                        currentKey
                    ] +=
                        '\n' +
                        line.trim();

                }

            });

        return data;

    }

    function parseLocationWeights(
        value
    ) {

        var result = [];

        String(
            value || ''
        )
            .split(';')
            .forEach(function (part) {

                part =
                    part.trim();

                if (!part) {
                    return;
                }

                var separator =
                    part.lastIndexOf(
                        ':'
                    );

                if (
                    separator ===
                    -1
                ) {
                    return;
                }

                var location =
                    part
                        .slice(
                            0,
                            separator
                        )
                        .trim();

                var weight =
                    Number(
                        part
                            .slice(
                                separator + 1
                            )
                            .trim()
                    );

                if (
                    !location ||
                    !isFinite(
                        weight
                    ) ||
                    weight <= 0
                ) {
                    return;
                }

                result.push({
                    location:
                        location,

                    weight:
                        weight
                });

            });

        return result;

    }

    function getFishWeightForLocation(
        fish,
        locationName
    ) {

        var target =
            String(
                locationName || ''
            )
                .trim()
                .toLowerCase();

        for (
            var i = 0;
            i < fish.weights.length;
            i++
        ) {

            if (
                String(
                    fish.weights[i]
                        .location
                )
                    .trim()
                    .toLowerCase() ===
                target
            ) {

                return Number(
                    fish.weights[i]
                        .weight
                ) || 0;

            }

        }

        return 0;

    }

    function getFishForLocation(
        locationName
    ) {

        var result = [];
        var totalWeight = 0;

        fishEntries.forEach(function (fish) {

            var weight =
                getFishWeightForLocation(
                    fish,
                    locationName
                );

            if (
                weight <= 0
            ) {
                return;
            }

            totalWeight +=
                weight;

            result.push({
                fish:
                    fish,

                weight:
                    weight,

                chance:
                    0
            });

        });

        result.forEach(function (entry) {

            entry.chance =
                totalWeight > 0
                    ? (
                        entry.weight /
                        totalWeight
                    ) * 100
                    : 0;

        });

        result.sort(function (
            a,
            b
        ) {

            var aStars =
                getRarityStars(
                    a.fish.rarity
                );

            var bStars =
                getRarityStars(
                    b.fish.rarity
                );

            if (
                aStars !==
                bStars
            ) {

                return (
                    aStars -
                    bStars
                );

            }

            if (
                b.chance !==
                a.chance
            ) {

                return (
                    b.chance -
                    a.chance
                );

            }

            if (
                b.weight !==
                a.weight
            ) {

                return (
                    b.weight -
                    a.weight
                );

            }

            return String(
                a.fish.name || ''
            ).localeCompare(
                String(
                    b.fish.name || ''
                ),
                undefined,
                {
                    sensitivity:
                        'base'
                }
            );

        });

        return {
            entries:
                result,

            totalWeight:
                totalWeight
        };

    }

    function buildEntriesApp(
