                'div'
            );

        sideMenu.className =
            'wiki-entries-side-menu';

        var displaySetting =
            document.createElement(
                'div'
            );

        displaySetting.className =
            'wiki-side-menu-setting';

        var displayLabel =
            document.createElement(
                'div'
            );

        displayLabel.className =
            'wiki-side-menu-label';

        displayLabel.textContent =
            'Display:';


        var displayToggle =
            document.createElement(
                'button'
            );

        displayToggle.type =
            'button';

        displayToggle.className =
            'wiki-display-toggle';

        displayToggle.textContent =
            'Percentage';


        displayToggle.addEventListener(
            'click',
            function () {

                if (
                    currentDisplayMode ===
                    'percentage'
                ) {

                    currentDisplayMode =
                        'fraction';

                    displayToggle.textContent =
