            );

        tabs.appendChild(
            fishButton
        );

        tabs.appendChild(
            baitButton
        );

        content.appendChild(
            tabs
        );

        var body =
            document.createElement(
                'div'
            );

        body.className =
            'wiki-entry-items-body';

        content.appendChild(
            body
        );

        fishButton.addEventListener(
            'click',
            function () {

                currentItemTab =
                    'Fish';

                currentLocation =
                    null;

                updateItemTabs(
                    fishButton,
                    baitButton
                );

                renderFishLocations(
                    body
                );

            }
        );

        baitButton.addEventListener(
            'click',
            function () {

                currentItemTab =
                    'Baits';

                currentLocation =
                    null;

                updateItemTabs(
                    fishButton,
                    baitButton
                );

                renderBaits(
                    body
                );

            }
        );

        updateItemTabs(
            fishButton,
            baitButton
        );

        if (
            currentItemTab ===
            'Baits'
        ) {

            renderBaits(
                body
            );

        } else {

            renderFishLocations(
                body
            );

        }

    }

