        enchantField.appendChild(
            enchantText
        );

        enchantField.appendChild(
            enchantInput
        );

        luckSetting.appendChild(
            enchantField
        );

        var upgradeField =
            document.createElement(
                'label'
            );

        upgradeField.className =
            'wiki-setting-field';

        var upgradeText =
            document.createElement(
                'span'
            );

        upgradeText.textContent =
            'Fish Upgrade: Fortune';

        var upgradeSelect =
            document.createElement(
                'select'
            );

        upgradeSelect.className =
