        for (
            var upgradeLevel = 0;
            upgradeLevel <= 20;
            upgradeLevel++
        ) {

            var upgradeOption =
                document.createElement(
                    'option'
                );

            upgradeOption.value =
                upgradeLevel;

            upgradeOption.textContent =
                'Level ' + upgradeLevel;

            upgradeSelect.appendChild(
                upgradeOption
            );

        }

        upgradeField.appendChild(
            upgradeText
        );

        upgradeField.appendChild(
            upgradeSelect
        );

        luckSetting.appendChild(
            upgradeField
        );

        var baitField =
            document.createElement(
                'label'
            );

        baitField.className =
            'wiki-setting-field';

        var baitText =
            document.createElement(
                'span'
            );

        baitText.textContent =
            'Bait:';

        var baitSelect =
            document.createElement(
                'select'
            );

        baitSelect.className =
            'wiki-setting-select';

        baitSelect.innerHTML =
            '<option value="parmesan">Parmesan</option>' +
            '<option value="fusion-coil">Fusion Coil</option>';

        baitField.appendChild(
            baitText
        );

        baitField.appendChild(
            baitSelect
        );

        luckSetting.appendChild(
            baitField
        );

        sideMenu.appendChild(
            luckSetting
        );
        function updateToolSettings() {

            if (
                toolSelect.value ===
                'gun'
            ) {

                enchantText.textContent =
                    'Sharpshooter Enchant:';

                baitField.style.display =
                    'none';

            } else {

                enchantText.textContent =
                    'Fortune Enchant:';

                baitField.style.display =
                    'flex';

            }

        }

        toolSelect.addEventListener(
            'change',
