        );

        updateToolSettings();
        shell.appendChild(
            nav
        );

        shell.appendChild(
            content
        );

        var frame =
            document.createElement(
                'div'
        );

        frame.className =
            'wiki-entries-frame';

        frame.appendChild(
            menuBar
        );
        frame.appendChild(
            sideMenu
        );

        frame.appendChild(
            shell
        );

        container.appendChild(
