        );

        menuButton.addEventListener(
            'click',
            function () {

                sideMenu.classList.toggle(
                    'wiki-side-menu-open'
                );

            }
        );

        createNavButton(
            nav,
            'Items',
            SIDE_ICONS.Items
        );

        createNavButton(
            nav,
            'Tools',
            SIDE_ICONS.Tools
        );

        createNavButton(
            nav,
            'Enchants',
            SIDE_ICONS.Enchants
        );

