    function appendDetailBasicInfo(
        detail,
        entry
    ) {

        if (
            entry.image
        ) {

            var image =
                document.createElement(
                    'img'
                );

            image.className =
                'wiki-entry-detail-image';

            image.src =
                getWikiImageUrl(
                    entry.image
                );

            image.alt =
                entry.name;

            detail.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'div'
            );

        name.className =
            'wiki-entry-detail-name';

        name.textContent =
            entry.name;

        if (
            entry.rarity
        ) {

            applyRarityClass(
                name,
                entry.rarity
            );

        }

        detail.appendChild(
            name
        );

        if (
            entry.rarity
        ) {

            var rarity =
                createRarityDisplay(
                    entry.rarity,
                    'wiki-entry-detail-rarity'
                );

            if (
                rarity
            ) {
                detail.appendChild(
                    rarity
                );
            }

        }

        if (
            entry.description
        ) {

            var description =
                document.createElement(
                    'div'
                );

            description.className =
                'wiki-entry-description';

            renderLoreText(
                description,
                entry.description
            );

            detail.appendChild(
                description
            );

        }

    }

    function renderLoreText(
        element,
        text
    ) {

        text =
            String(
                text || ''
            );

        var regex =
            /\[(blue|formula)\]([\s\S]*?)\[\/\1\]/gi;

        var lastIndex = 0;
        var match;

        while (
            (
                match =
                    regex.exec(
                        text
                    )
            ) !==
            null
        ) {

            if (
                match.index >
                lastIndex
            ) {

                element.appendChild(
                    document.createTextNode(
                        text.slice(
                            lastIndex,
                            match.index
                        )
                    )
                );

            }


            var styledText =
                document.createElement(
                    'span'
                );


            if (
                match[1].toLowerCase() ===
                'blue'
            ) {

                styledText.className =
                    'wiki-lore-blue';

            } else if (
                match[1].toLowerCase() ===
                'formula'
            ) {

                styledText.className =
                    'wiki-lore-formula';

            }


            styledText.textContent =
                match[2];


            element.appendChild(
                styledText
            );


            lastIndex =
                regex.lastIndex;

        }


        if (
            lastIndex <
            text.length
        ) {

            element.appendChild(
                document.createTextNode(
                    text.slice(
                        lastIndex
                    )
                )
            );

        }

    }

    function createRarityDisplay(
        rarityName,
        className
    ) {

        rarityName =
            String(
                rarityName || ''
            ).trim();

        if (
            !rarityName
        ) {
            return null;
        }

        var wrapper =
            document.createElement(
                'div'
            );

        wrapper.className =
            className;

        var rarityText =
            document.createElement(
                'span'
            );

        rarityText.textContent =
            capitalizeFirst(
                rarityName
            );

        applyRarityClass(
            rarityText,
            rarityName
        );

        wrapper.appendChild(
            rarityText
        );

        var rarity =
            rarityEntries[
                rarityName.toLowerCase()
            ];

        if (
            rarity &&
            rarity.stars > 0
        ) {

            var stars =
                document.createElement(
                    'span'
                );

            stars.className =
                'wiki-rarity-stars-inline';

            stars.textContent =
                '★'.repeat(
                    rarity.stars
                );

            applyRarityClass(
                stars,
                rarityName
            );

            wrapper.appendChild(
                stars
            );

        }

        return wrapper;

    }

    function createBackButton(
        onClick
    ) {

        var wrapper =
            document.createElement(
                'div'
            );

        wrapper.className =
            'wiki-detail-back-row';

        var button =
            document.createElement(
                'button'
            );

        button.type =
            'button';

        button.className =
            'wiki-entry-back';

        button.textContent =
            'Back';

        button.addEventListener(
            'click',
            onClick
        );

        wrapper.appendChild(
            button
        );

        return wrapper;

    }

    function createStat(
        labelText,
        valueText
    ) {

        var stat =
            document.createElement(
                'div'
            );

        stat.className =
            'wiki-entry-stat';

        var label =
            document.createElement(
                'div'
            );

        label.className =
            'wiki-entry-stat-label';

        label.textContent =
            labelText;

        var value =
            document.createElement(
                'div'
            );

        value.className =
            'wiki-entry-stat-value';

        value.textContent =
            valueText;

        stat.appendChild(
            label
        );

        stat.appendChild(
