                        document.createElement(
                            'span'
                        );

                    name.textContent =
                        bait.name;

                    card.appendChild(
                        name
                    );

                    card.addEventListener(
                        'click',
                        function () {

                            selectedBait =
                                bait;

                            baitButtonName.textContent =
                                bait.name;

                            if (
                                bait.image
                            ) {

                                baitButtonImage.src =
                                    getWikiImageUrl(
                                        bait.image
                                    );

                                baitButtonImage.alt =
                                    bait.name;

                                baitButtonImage.style.display =
                                    'block';

                            } else {

                        baitButtonImage.style.display =
                            'none';

                    }

                    baitPicker.style.display =
                        'none';

                }
            );

            baitPickerGrid.appendChild(
                card
            );

        }
    );

}


baitButton.addEventListener(
    'click',
    function () {

        if (
            baitPicker.style.display ===
            'block'
        ) {

            baitPicker.style.display =
                'none';

            return;

        }

        baitPicker.style.display =
            'block';

        baitPickerGrid.innerHTML =
            '<div class="wiki-bait-picker-loading">Loading...</div>';

        ensureSectionLoaded(
            'Items'
        )
            .then(function () {

                renderBaitPicker();

            });

    }
);

        sideMenu.appendChild(
            luckSetting
        );
        function updateToolSettings() {

            if (
                toolSelect.value ===
                'gun'
            ) {

                enchantText.textContent =
                    'Sharpshooter Enchant:';

                baitField.style.display =
                    'none';

            } else {

                enchantText.textContent =
                    'Fortune Enchant:';

                baitField.style.display =
                    'flex';

            }

        }

        toolSelect.addEventListener(
            'change',
            updateToolSettings
        );

        updateToolSettings();
        shell.appendChild(
            nav
        );

        shell.appendChild(
            content
        );

        var frame =
            document.createElement(
                'div'
        );

        frame.className =
            'wiki-entries-frame';

        frame.appendChild(
            menuBar
        );
        frame.appendChild(
            sideMenu
        );

        frame.appendChild(
            shell
        );

        container.appendChild(
            frame
        );

        menuButton.addEventListener(
            'click',
            function () {

                sideMenu.classList.toggle(
                    'wiki-side-menu-open'
                );

            }
        );

        createNavButton(
            nav,
            'Items',
            SIDE_ICONS.Items
        );

        createNavButton(
            nav,
            'Tools',
            SIDE_ICONS.Tools
        );

        createNavButton(
            nav,
            'Enchants',
            SIDE_ICONS.Enchants
        );

    }

    function createNavButton(
        container,
        section,
        imageName
    ) {

        var button =
            document.createElement(
                'button'
            );

        button.type =
            'button';

        button.className =
            'wiki-entry-nav-pill';

        button.setAttribute(
            'data-entry-section',
            section
        );

        var image =
            document.createElement(
                'img'
            );

        image.src =
            getWikiImageUrl(
                imageName
            );

        image.alt =
            section;

        var label =
            document.createElement(
                'span'
            );

        label.textContent =
            section;

        button.appendChild(
            image
        );

        button.appendChild(
            label
        );

        button.addEventListener(
            'click',
            function () {

                currentSection =
                    section;

                currentLocation =
                    null;

                var shell =
                    document.querySelector(
                        '#fish-entries-app .wiki-entries-shell'
                    );

                var content =
                    document.querySelector(
                        '#fish-entries-app .wiki-entries-content'
                    );

                if (
                    shell
                ) {

                    shell.classList.remove(
                        'wiki-entries-start'
                    );

                    shell.classList.add(
                        'wiki-entries-open'
                    );

                }

                if (
                    content
                ) {

                    content.style.display =
                        'block';

                }

                updateNavButtons();

                if (
                    content
                ) {

                    content.innerHTML =
                        '';

                    content.appendChild(
                        createEmptyMessage(
                            'Loading ' +
                            section +
                            '...'
                        )
                    );

                }

                ensureSectionLoaded(
                    section
                )
                    .then(function () {

                        if (
                            currentSection !==
                            section
                        ) {
                            return;
                        }

                        renderCurrentSection();

                    })
                    .catch(function (
                        error
                    ) {

                        console.error(
                            'Section Load Error:',
                            error
                        );

                        if (
                            currentSection !==
                            section ||
                            !content
                        ) {
                            return;
                        }

                        content.innerHTML =
                            '';

                        content.appendChild(
                            createEmptyMessage(
                                'Could not load ' +
                                section +
                                '.'
                            )
                        );

                    });

            }
        );

        container.appendChild(
            button
        );

    }

    function updateNavButtons() {

        document
            .querySelectorAll(
                '#fish-entries-app .wiki-entry-nav-pill'
            )
            .forEach(function (button) {

                var section =
                    button.getAttribute(
                        'data-entry-section'
                    );

                button.classList.toggle(
                    'entry-active',
                    section ===
                    currentSection
                );

            });

    }

    function renderCurrentSection() {

        updateNavButtons();

        var content =
            document.querySelector(
                '#fish-entries-app .wiki-entries-content'
            );

        if (
            !content
        ) {
            return;
        }

        content.innerHTML =
            '';

        if (
            currentSection ===
            'Items'
        ) {

            renderItemsSection(
                content
            );

            return;

        }

        if (
            currentSection ===
            'Tools'
        ) {

            renderToolsSection(
                content
            );

            return;

        }

        if (
            currentSection ===
            'Enchants'
        ) {

            renderEnchantsSection(
                content
            );

        }

    }

    function createSectionTitle(
        container,
        text
    ) {

        var title =
            document.createElement(
                'div'
            );

        title.className =
            'wiki-entry-content-title';

        title.textContent =
            text;

        container.appendChild(
            title
        );

    }

    function renderItemsSection(
        content
    ) {

        createSectionTitle(
            content,
            'Items'
        );

        var tabs =
            document.createElement(
                'div'
            );

        tabs.className =
            'wiki-entry-subtabs';

        var fishButton =
            createSubtabButton(
                'Fish'
            );

        var baitButton =
            createSubtabButton(
                'Baits'
            );

        tabs.appendChild(
            fishButton
        );

        tabs.appendChild(
            baitButton
        );

        content.appendChild(
            tabs
        );

        var body =
            document.createElement(
                'div'
            );

        body.className =
            'wiki-entry-items-body';

        content.appendChild(
            body
        );

        fishButton.addEventListener(
            'click',
            function () {

                currentItemTab =
                    'Fish';

                currentLocation =
                    null;

                updateItemTabs(
                    fishButton,
                    baitButton
                );

                renderFishLocations(
                    body
                );

            }
        );

        baitButton.addEventListener(
            'click',
            function () {

                currentItemTab =
                    'Baits';

                currentLocation =
                    null;

                updateItemTabs(
                    fishButton,
                    baitButton
                );

                renderBaits(
                    body
                );

            }
        );

        updateItemTabs(
            fishButton,
            baitButton
        );

        if (
            currentItemTab ===
            'Baits'
        ) {

            renderBaits(
                body
            );

        } else {

            renderFishLocations(
                body
            );

        }

    }

    function createSubtabButton(
        text
    ) {

        var button =
            document.createElement(
                'button'
            );

        button.type =
            'button';

        button.className =
            'wiki-entry-subtab';

        button.textContent =
            text;

        return button;

    }

    function updateItemTabs(
        fishButton,
        baitButton
    ) {

        fishButton.classList.toggle(
            'entry-active',
            currentItemTab ===
            'Fish'
        );

        baitButton.classList.toggle(
            'entry-active',
            currentItemTab ===
            'Baits'
        );

    }

    function renderFishLocations(
        body
    ) {

        body.innerHTML = '';

        if (
            currentLocation
        ) {

            renderLocationFish(
                body,
                currentLocation
            );

            return;

        }

        if (
            !locations.length
        ) {

            body.appendChild(
                createEmptyMessage(
                    'No locations have been published yet.'
                )
            );

            return;

        }

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-location-grid';

        locations.forEach(function (location) {

            var button =
                document.createElement(
                    'button'
                );

            button.type =
                'button';

            button.className =
                'wiki-location-pill';

            if (
                location.image
            ) {

                var image =
                    document.createElement(
                        'img'
                    );

                image.src =
                    getWikiImageUrl(
                        location.image
                    );

                image.alt =
                    location.name;

                button.appendChild(
                    image
                );

            }

            var name =
                document.createElement(
                    'div'
                );

            name.className =
                'wiki-location-name';

            name.textContent =
                location.name;

            button.appendChild(
                name
            );

            button.addEventListener(
                'click',
                function () {

                    currentLocation =
                        location;

                    renderFishLocations(
                        body
                    );

                }
            );

            grid.appendChild(
                button
            );

        });

        body.appendChild(
            grid
        );

    }

    function renderLocationFish(
        body,
        location
    ) {

        body.innerHTML =
            '';

        var header =
            document.createElement(
                'div'
            );

        header.className =
            'wiki-location-header';

        var title =
            document.createElement(
                'div'
            );

        title.className =
            'wiki-location-header-title';

        if (
            location.image
        ) {

            var image =
                document.createElement(
                    'img'
                );

            image.src =
                getWikiImageUrl(
                    location.image
                );

            image.alt =
                location.name;

            title.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'span'
            );

        name.textContent =
            location.name;

        title.appendChild(
            name
        );

        var back =
            document.createElement(
                'button'
            );

        back.type =
            'button';

        back.className =
            'wiki-entry-back';

        back.textContent =
            'Back';

        back.addEventListener(
            'click',
            function () {

                currentLocation =
                    null;

                renderFishLocations(
                    body
                );

            }
        );

        header.appendChild(
            title
        );

        header.appendChild(
            back
        );

        body.appendChild(
            header
        );

        var calculated =
            getFishForLocation(
                location.name
            );

        if (
            !calculated.entries.length
        ) {

            body.appendChild(
                createEmptyMessage(
                    'No fish can currently be caught here.'
                )
            );

            return;

        }

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-fish-grid';

        calculated.entries
            .forEach(function (entry) {

                grid.appendChild(
                    createFishCard(
                        entry.fish,
                        location,
                        entry.weight,
                        entry.chance,
                        calculated.totalWeight
                    )
                );

            });

        body.appendChild(
            grid
        );

    }

    function createFishCard(
        fish,
        location,
        weight,
        chance,
        totalWeight
    ) {

        var card =
            document.createElement(
                'button'
            );

        card.type =
            'button';

        card.className =
            'wiki-fish-card';

        applyRarityBorderClass(
            card,
            fish.rarity
        );

        if (
            fish.image
        ) {

            var image =
                document.createElement(
                    'img'
                );

            image.className =
                'wiki-fish-card-image';

            image.src =
                getWikiImageUrl(
                    fish.image
                );

            image.alt =
                fish.name;

            card.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'div'
            );

        name.className =
            'wiki-fish-card-name';

        name.textContent =
            fish.name;

        applyRarityClass(
            name,
            fish.rarity
        );

        card.appendChild(
            name
        );

        if (
            fish.rarity
        ) {

            var rarity =
                createRarityDisplay(
                    fish.rarity,
                    'wiki-fish-card-rarity'
                );

            if (
                rarity
            ) {
                card.appendChild(
                    rarity
                );
            }

        }

        var chanceText =
            document.createElement(
                'div'
            );

        chanceText.className =
            'wiki-fish-card-chance';

        chanceText.textContent =
            formatChance(
                chance
            );

        card.appendChild(
            chanceText
        );

        card.addEventListener(
            'click',
            function () {

                var body =
                    document.querySelector(
                        '#fish-entries-app .wiki-entry-items-body'
                    );

                if (
                    !body
                ) {
                    return;
                }

                renderFishDetail(
                    body,
                    fish,
                    location,
                    weight,
                    chance,
                    totalWeight
                );

            }
        );

        return card;

    }

    function renderFishDetail(
        body,
        fish,
        location,
        weight,
        chance,
        totalWeight
    ) {

        body.innerHTML =
            '';

        var detail =
            document.createElement(
                'div'
            );

        detail.className =
            'wiki-entry-detail';

        detail.appendChild(
            createBackButton(
                function () {

                    renderLocationFish(
                        body,
                        location
                    );

                }
            )
        );

        if (
            fish.image
        ) {

            var image =
                document.createElement(
                    'img'
                );

            image.className =
                'wiki-entry-detail-image';

            image.src =
                getWikiImageUrl(
                    fish.image
                );

            image.alt =
                fish.name;

            detail.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'div'
            );

        name.className =
            'wiki-entry-detail-name';

        name.textContent =
            fish.name;

        applyRarityClass(
            name,
            fish.rarity
        );

        detail.appendChild(
            name
        );

        if (
            fish.rarity
        ) {

            var rarity =
                createRarityDisplay(
                    fish.rarity,
                    'wiki-entry-detail-rarity'
                );

            if (
                rarity
            ) {
                detail.appendChild(
                    rarity
                );
            }

        }

        var stats =
            document.createElement(
                'div'
            );

        stats.className =
            'wiki-entry-stat-grid';

        stats.appendChild(
            createStat(
                'Chance',
                formatChance(
                    chance
                )
            )
        );

        stats.appendChild(
            createStat(
                'Weight',
                formatNumber(
                    weight
                )
            )
        );

        if (
            fish.baseSellPrice !==
            ''
        ) {

            stats.appendChild(
                createStat(
                    'Base Sell',
                    fish.baseSellPrice
                )
            );

        }

        detail.appendChild(
            stats
        );

        if (
            fish.description
        ) {

            var description =
                document.createElement(
                    'div'
                );

            description.className =
                'wiki-entry-description';

            renderLoreText(
                description,
                fish.description
            );

            detail.appendChild(
                description
            );

        }

        body.appendChild(
            detail
        );

    }

    function renderBaits(
        body
    ) {

        body.innerHTML =
            '';

        if (
            !baitEntries.length
        ) {

            body.appendChild(
                createEmptyMessage(
                    'No Bait entries have been published yet.'
                )
            );

            return;

        }

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-standard-entry-grid';

        baitEntries.forEach(function (bait) {

            grid.appendChild(
                createStandardCard(
                    bait,
                    function () {

                        renderStandardDetail(
                            body,
                            bait,
                            'Bait'
                        );

                    }
                )
            );

        });

        body.appendChild(
            grid
        );

    }

    function renderToolsSection(
        content
    ) {

        createSectionTitle(
            content,
            'Tools'
        );

        if (
            !toolEntries.length
        ) {

            content.appendChild(
                createEmptyMessage(
                    'No Tool entries have been published yet.'
                )
            );

            return;

        }

        var toolGroups = {};
        var rodTypeOrder = [];

        toolEntries.forEach(
            function (tool) {

                var rodType =
                    String(
                        tool.rodType ||
                        'Unassigned'
                    ).trim() ||
                    'Unassigned';

                var rodTypeKey =
                    rodType.toLowerCase();

                if (
                    !toolGroups[
                        rodTypeKey
                    ]
                ) {

                    toolGroups[
                        rodTypeKey
                    ] = {
                        name:
                            rodType,

                        tools:
                            []
                    };

                    rodTypeOrder.push(
                        rodTypeKey
                    );

                }

                toolGroups[
                    rodTypeKey
                ]
                    .tools
                    .push(
                        tool
                    );

            }
        );

        rodTypeOrder.forEach(
            function (rodTypeKey) {

                var toolGroup =
                    toolGroups[
                        rodTypeKey
                    ];

                var group =
                    document.createElement(
                        'div'
                    );

                group.className =
                    'wiki-tool-type-group';

                var pill =
                    document.createElement(
                        'div'
                    );

                pill.className =
                    'wiki-tool-type-pill';

                pill.textContent =
                    toolGroup.name;

                group.appendChild(
                    pill
                );

                var grid =
                    document.createElement(
                        'div'
                    );

                grid.className =
                    'wiki-standard-entry-grid';

                toolGroup.tools.forEach(
                    function (tool) {

                        grid.appendChild(
                            createStandardCard(
                                tool,
                                function () {

                                    renderToolDetail(
                                        content,
                                        tool
                                    );

                                }
                            )
                        );

                    }
                );

                group.appendChild(
                    grid
                );

                content.appendChild(
                    group
                );

            }
        );

    }

    function renderEnchantsSection(
        content
    ) {

        createSectionTitle(
            content,
            'Enchants'
        );

        if (
            !enchantEntries.length
        ) {

            content.appendChild(
                createEmptyMessage(
                    'No Enchant entries have been published yet.'
                )
            );

            return;

        }

        var enchantGroups = {};
        var rodTypeOrder = [];

        enchantEntries.forEach(
            function (enchant) {

                var rodType =
                    String(
                        enchant.rodType ||
                        'Unassigned'
                    ).trim() ||
                    'Unassigned';

                var rodTypeKey =
                    rodType.toLowerCase();

                if (
                    !enchantGroups[
                        rodTypeKey
                    ]
                ) {

                    enchantGroups[
                        rodTypeKey
                    ] = {
                        name:
                            rodType,

                        enchants:
                            []
                    };

                    rodTypeOrder.push(
                        rodTypeKey
                    );

                }

                enchantGroups[
                    rodTypeKey
                ]
                    .enchants
                    .push(
                        enchant
                    );

            }
        );

        rodTypeOrder.forEach(
            function (rodTypeKey) {

                var enchantGroup =
                    enchantGroups[
                        rodTypeKey
                    ];

                var totalWeight =
                    enchantGroup.enchants.reduce(
                        function (
                            total,
                            enchant
                        ) {

                            return (
                                total +
                                (
                                    Number(
                                        enchant.weight
                                    ) ||
                                    0
                                )
                            );

                        },
                        0
                    );

                enchantGroup.enchants.sort(
                    function (
                        a,
                        b
                    ) {

                        if (
                            a.weight !==
                            b.weight
                        ) {

                            return (
                                a.weight -
                                b.weight
                            );

                        }

                        return sortByName(
                            a,
                            b
                        );

                    }
                );

                var group =
                    document.createElement(
                        'div'
                    );

                group.className =
                    'wiki-tool-type-group';

                var pill =
                    document.createElement(
                        'div'
                    );

                pill.className =
                    'wiki-tool-type-pill';

                pill.textContent =
                    enchantGroup.name +
                    ' Enchants';

                group.appendChild(
                    pill
                );

                var grid =
                    document.createElement(
                        'div'
                    );

                grid.className =
                    'wiki-standard-entry-grid';

                enchantGroup.enchants.forEach(
                    function (enchant) {

                        var chance =
                            totalWeight > 0
                                ? (
                                    enchant.weight /
                                    totalWeight
                                ) * 100
                                : 0;

                        var card =
                            createStandardCard(
                                enchant,
                                function () {

                                    renderEnchantDetail(
                                        content,
                                        enchant,
                                        chance,
                                        totalWeight
                                    );

                                }
                            );

                        var chanceLabel =
                            document.createElement(
                                'div'
                            );

                        chanceLabel.className =
                            'wiki-standard-card-extra';

                        chanceLabel.textContent =
                            formatChance(
                                chance
                            );

                        card.appendChild(
                            chanceLabel
                        );

                        grid.appendChild(
                            card
                        );

                    }
                );

                group.appendChild(
                    grid
                );

                content.appendChild(
                    group
                );

            }
        );

    }

    function createStandardCard(
        entry,
        onClick
    ) {

        var card =
            document.createElement(
                'button'
            );

        card.type =
            'button';

        card.className =
            'wiki-standard-entry-card';

        if (
            entry.image
        ) {

            var image =
                document.createElement(
                    'img'
                );

            image.src =
                getWikiImageUrl(
                    entry.image
                );

            image.alt =
                entry.name;

            card.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'div'
            );

        name.className =
            'wiki-standard-entry-name';

        name.textContent =
            entry.name;

        if (
            entry.rarity
        ) {

            applyRarityClass(
                name,
                entry.rarity
            );

        }

        card.appendChild(
            name
        );

        if (
            entry.rarity
        ) {

            var rarity =
                createRarityDisplay(
                    entry.rarity,
                    'wiki-standard-entry-rarity'
                );

            if (
                rarity
            ) {
                card.appendChild(
                    rarity
                );
            }

        }

        card.addEventListener(
            'click',
            onClick
        );

        return card;

    }

    function renderStandardDetail(
        body,
        entry,
        type
    ) {

        body.innerHTML =
            '';

        var detail =
            document.createElement(
                'div'
            );

        detail.className =
            'wiki-entry-detail';

        detail.appendChild(
            createBackButton(
                function () {

                    if (
                        type ===
                        'Bait'
                    ) {

                        renderBaits(
                            body
                        );

                    }

                }
            )
        );

        appendDetailBasicInfo(
            detail,
            entry
        );

        body.appendChild(
            detail
        );

    }

    function renderToolDetail(
        content,
        tool
    ) {

        content.innerHTML =
            '';

        createSectionTitle(
            content,
            'Tools'
        );

        var detail =
            document.createElement(
                'div'
            );

        detail.className =
            'wiki-entry-detail wiki-tool-detail';

        detail.appendChild(
            createBackButton(
                function () {

                    renderCurrentSection();

                }
            )
        );

        if (
            tool.image
        ) {

            var image =
                document.createElement(
                    'img'
                );

            image.className =
                'wiki-entry-detail-image';

            image.src =
                getWikiImageUrl(
                    tool.image
                );

            image.alt =
                tool.name;

            detail.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'div'
            );

        name.className =
            'wiki-entry-detail-name';

        name.textContent =
            tool.name;

        detail.appendChild(
            name
        );

        if (
            tool.baseCost !==
            ''
        ) {

            var stats =
                document.createElement(
                    'div'
                );

            stats.className =
                'wiki-entry-stat-grid wiki-tool-base-cost';

            stats.appendChild(
                createStat(
                    'Base Cost',
                    tool.baseCost
                )
            );

            detail.appendChild(
                stats
            );

        }

        if (
            tool.description
        ) {

            var description =
                document.createElement(
                    'div'
                );

            description.className =
                'wiki-entry-description';

            renderLoreText(
                description,
                tool.description
            );

            detail.appendChild(
                description
            );

        }

        content.appendChild(
            detail
        );

    }

    function renderEnchantDetail(
        content,
        enchant,
        chance,
        totalWeight
    ) {

        content.innerHTML =
            '';

        createSectionTitle(
            content,
            'Enchants'
        );

        var detail =
            document.createElement(
                'div'
            );

        detail.className =
            'wiki-entry-detail';

        detail.appendChild(
            createBackButton(
                function () {

                    renderCurrentSection();

                }
            )
        );

        appendDetailBasicInfo(
            detail,
            enchant
        );

        var stats =
            document.createElement(
                'div'
            );

        stats.className =
            'wiki-entry-stat-grid';

        stats.appendChild(
            createStat(
                'Weight',
                formatNumber(
                    enchant.weight
                )
            )
        );

        stats.appendChild(
            createStat(
                'Chance',
                formatChance(
                    chance
                )
            )
        );

        detail.appendChild(
            stats
        );

        content.appendChild(
            detail
        );

    }

    function appendDetailBasicInfo(
        detail,
        entry
    ) {

        if (
            entry.image
        ) {

            var image =
                document.createElement(
                    'img'
                );

            image.className =
                'wiki-entry-detail-image';

            image.src =
                getWikiImageUrl(
                    entry.image
                );

            image.alt =
                entry.name;

            detail.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'div'
            );

        name.className =
            'wiki-entry-detail-name';

        name.textContent =
            entry.name;

        if (
            entry.rarity
        ) {

            applyRarityClass(
                name,
                entry.rarity
            );

        }

        detail.appendChild(
            name
        );

        if (
            entry.rarity
        ) {

            var rarity =
                createRarityDisplay(
                    entry.rarity,
                    'wiki-entry-detail-rarity'
                );

            if (
                rarity
            ) {
                detail.appendChild(
                    rarity
                );
            }

        }

        if (
            entry.description
        ) {

            var description =
                document.createElement(
                    'div'
                );

            description.className =
                'wiki-entry-description';

            renderLoreText(
                description,
                entry.description
            );

            detail.appendChild(
                description
            );

        }

    }

    function renderLoreText(
        element,
        text
    ) {

        text =
            String(
                text || ''
            );

        var regex =
            /\[(blue|formula)\]([\s\S]*?)\[\/\1\]/gi;

        var lastIndex = 0;
        var match;

        while (
            (
                match =
                    regex.exec(
                        text
                    )
            ) !==
            null
        ) {

            if (
                match.index >
                lastIndex
            ) {

                element.appendChild(
                    document.createTextNode(
                        text.slice(
                            lastIndex,
                            match.index
                        )
                    )
                );

            }


            var styledText =
                document.createElement(
                    'span'
                );


            if (
                match[1].toLowerCase() ===
                'blue'
            ) {

                styledText.className =
                    'wiki-lore-blue';

            } else if (
                match[1].toLowerCase() ===
                'formula'
            ) {

                styledText.className =
                    'wiki-lore-formula';

            }


            styledText.textContent =
                match[2];


            element.appendChild(
                styledText
            );


            lastIndex =
                regex.lastIndex;

        }


        if (
            lastIndex <
            text.length
        ) {

            element.appendChild(
                document.createTextNode(
                    text.slice(
                        lastIndex
                    )
                )
            );

        }

    }

    function createRarityDisplay(
        rarityName,
        className
    ) {

        rarityName =
            String(
                rarityName || ''
            ).trim();

        if (
            !rarityName
        ) {
            return null;
        }

        var wrapper =
            document.createElement(
                'div'
            );

        wrapper.className =
            className;

        var rarityText =
            document.createElement(
                'span'
            );

        rarityText.textContent =
            capitalizeFirst(
                rarityName
            );

        applyRarityClass(
            rarityText,
            rarityName
        );

        wrapper.appendChild(
            rarityText
        );

        var rarity =
            rarityEntries[
                rarityName.toLowerCase()
            ];

        if (
            rarity &&
            rarity.stars > 0
        ) {

            var stars =
                document.createElement(
                    'span'
                );

            stars.className =
                'wiki-rarity-stars-inline';

            stars.textContent =
                '★'.repeat(
                    rarity.stars
                );

            applyRarityClass(
                stars,
                rarityName
            );

            wrapper.appendChild(
                stars
            );

        }

        return wrapper;

    }

    function createBackButton(
        onClick
    ) {

        var wrapper =
            document.createElement(
                'div'
            );

        wrapper.className =
            'wiki-detail-back-row';

        var button =
            document.createElement(
                'button'
            );

        button.type =
            'button';

        button.className =
            'wiki-entry-back';

        button.textContent =
            'Back';

        button.addEventListener(
            'click',
            onClick
        );

        wrapper.appendChild(
            button
        );

        return wrapper;

    }

    function createStat(
        labelText,
        valueText
    ) {

        var stat =
            document.createElement(
                'div'
            );

        stat.className =
            'wiki-entry-stat';

        var label =
            document.createElement(
                'div'
            );

        label.className =
            'wiki-entry-stat-label';

        label.textContent =
            labelText;

        var value =
            document.createElement(
                'div'
            );

        value.className =
            'wiki-entry-stat-value';

        value.textContent =
            valueText;

        stat.appendChild(
            label
        );

        stat.appendChild(
            value
        );

        return stat;

    }

    function createEmptyMessage(
        message
    ) {

        var div =
            document.createElement(
                'div'
            );

        div.className =
            'wiki-entry-empty';

        div.textContent =
            message;

        return div;

    }

    function injectRarityStyles() {

        var old =
            document.getElementById(
                'wiki-dynamic-rarity-styles'
            );

        if (
            old
        ) {
            old.remove();
        }

        var css = '';

        Object.keys(
            rarityEntries
        )
            .forEach(function (key) {

                var rarity =
                    rarityEntries[
                        key
                    ];

                var slug =
                    makeSlug(
                        rarity.name
                    );

                var animation =
                    'wiki-rarity-' +
                    slug;

                css +=
                    '@keyframes ' +
                    animation +
                    '{' +
                    '0%{color:' +
                    rarity.color0 +
                    ';}' +
                    '50%{color:' +
                    rarity.color50 +
                    ';}' +
                    '100%{color:' +
                    rarity.color100 +
                    ';}' +
                    '}';

                css +=
                    '.wiki-dynamic-rarity-' +
                    slug +
                    '{animation:' +
                    animation +
                    ' 3s ease-in-out infinite !important;}';

            });

        var style =
            document.createElement(
                'style'
            );

        style.id =
            'wiki-dynamic-rarity-styles';

        style.textContent =
            css;

        document.head.appendChild(
            style
        );

    }

    function applyRarityClass(
        element,
        rarity
    ) {

        rarity =
            String(
                rarity || ''
            ).trim();

        if (
            !rarity
        ) {
            return;
        }

        var slug =
            makeSlug(
                rarity
            );

        element.classList.add(
            'entry-name-rarity-' +
            slug
        );

        if (
            rarityEntries[
                rarity.toLowerCase()
            ]
        ) {

            element.classList.add(
                'wiki-dynamic-rarity-' +
                slug
            );

        }

    }

    function applyRarityBorderClass(
        element,
        rarity
    ) {

        rarity =
            String(
                rarity || ''
            ).trim();

        if (
            !rarity
        ) {
            return;
        }

        var rarityData =
            rarityEntries[
                rarity.toLowerCase()
            ];

        if (
            !rarityData
        ) {
            return;
        }

        element.classList.add(
            'wiki-rarity-animated-border'
        );

        element.style.setProperty(
            '--rarity-border-color-0',
            rarityData.color0
        );

        element.style.setProperty(
            '--rarity-border-color-50',
            rarityData.color50
        );

    }

    function makeSlug(
        value
    ) {

        return String(
            value || ''
        )
            .toLowerCase()
            .trim()
            .replace(
                /[^a-z0-9]+/g,
                '-'
            )
            .replace(
                /^-+|-+$/g,
                ''
            );

    }

    function normalizeHexColor(
        value
    ) {

        value =
            String(
                value || ''
            )
                .trim()
                .toLowerCase();

        if (
            /^[0-9a-f]{6}$/i.test(
                value
            )
        ) {

            value =
                '#' +
                value;

        }

        if (
            /^#[0-9a-f]{6}$/i.test(
                value
            )
        ) {

            return value;

        }

        return '';

    }

    function getWikiImageUrl(
        filename
    ) {

        filename =
            String(
                filename || ''
            )
                .replace(
                    /^File:/i,
                    ''
                )
                .trim();

        return mw.util.getUrl(
            'Special:Redirect/file/' +
            filename
        );

    }

    function getNameFromPage(
        page
    ) {

        page =
            String(
                page || ''
            );

        var separator =
            page.indexOf(
                ':'
            );

        if (
            separator !==
            -1
        ) {

            return page
                .slice(
                    separator + 1
                )
                .trim();

        }

        return page.trim();

    }

    function sortByName(
        a,
        b
    ) {

        return String(
            a.name || ''
        ).localeCompare(
            String(
                b.name || ''
            ),
            undefined,
            {
                sensitivity:
                    'base'
            }
        );

    }

    function formatChance(
        value
    ) {

        value =
            Number(
                value
            );

        if (
            currentDisplayMode ===
            'percentage'
        ) {

            return formatPercent(
                value
            );

        }

        if (
            !isFinite(
                value
            ) ||
            value <= 0
        ) {

            return '1/∞';

        }


        var denominator =
            100 / value;

        if (
            Math.abs(
                denominator -
                Math.round(
                    denominator
                )
            ) < 0.000001
        ) {

            denominator =
                Math.round(
                    denominator
                );

        } else {

            denominator =
                denominator
                    .toFixed(
                        3
                    )
                    .replace(
                        /\.?0+$/,
                        ''
                    );

        }


        return (
            '1/' +
            denominator
        );

    }

    function formatPercent(
        value
    ) {

        value =
            Number(
                value
            );

        if (
            !isFinite(
                value
            )
        ) {

            return '0%';

        }

        if (
            value >= 10
        ) {

            return (
                value
                    .toFixed(2)
                    .replace(
                        /\.?0+$/,
                        ''
                    ) +
                '%'
            );

        }

        if (
            value >= 1
        ) {

            return (
                value
                    .toFixed(3)
                    .replace(
                        /\.?0+$/,
                        ''
                    ) +
                '%'
            );

        }

        return (
            value
                .toFixed(6)
                .replace(
                    /\.?0+$/,
                    ''
                ) +
            '%'
        );

    }

    function formatNumber(
        value
    ) {

        value =
            Number(
                value
            );

        if (
            !isFinite(
                value
            )
        ) {

            return '0';

        }

        return value.toLocaleString();

    }

    function decodeTemplateValue(
        value
    ) {

        return String(
            value || ''
        )
            .replace(
                /&#124;/g,
                '|'
            )
            .replace(
                /&#123;&#123;/g,
                '{{'
            )
            .replace(
                /&#125;&#125;/g,
                '}}'
            )
            .replace(
                /\}&#125;/g,
                '}}'
            );

    }

    function normalizeApiError(
        code,
        details
    ) {

        var error = {
            code:
                code ||
                'api-error',

            info:
                '',

            details:
                details ||
                null
        };

        if (
            details &&
            details.error
        ) {

            if (
                details.error.code
            ) {

                error.code =
                    details.error.code;

            }

            if (
                details.error.info
            ) {

                error.info =
                    details.error.info;

            }

        }

        if (
            !error.info &&
            details &&
            details.info
        ) {

            error.info =
                details.info;

        }

        if (
            !error.info &&
            typeof details ===
            'string'
        ) {

            error.info =
                details;

        }

        if (
            !error.info
        ) {

            error.info =
                'MediaWiki returned an API error.';

        }

        return error;

    }

    function formatError(
        error
    ) {

        if (
            !error
        ) {

            return 'Unknown error.';

        }

        if (
            typeof error ===
            'string'
        ) {

            return error;

        }

        if (
            error.code &&
            error.info
        ) {

            return (
                error.code +
                ': ' +
                error.info
            );

        }

        return (
            error.info ||
            error.code ||
            error.message ||
            'Unknown error.'
        );

    }

    function escapeHtml(
        value
    ) {

        return String(
            value || ''
        )
            .replace(
                /&/g,
                '&amp;'
            )
            .replace(
                /</g,
                '&lt;'
            )
            .replace(
                />/g,
                '&gt;'
            )
            .replace(
                /"/g,
                '&quot;'
            )
            .replace(
                /'/g,
                '&#039;'
            );

    }

})();

(function () {

    var ENTRIES_PAGE = 'Fish_Island';

    var CATEGORIES = {
        Fish: 'Category:Fish Entries',
        Bait: 'Category:Bait Entries',
        Tool: 'Category:Tool Entries',
        Enchant: 'Category:Enchant Entries',
        Location: 'Category:Fish Locations',
        Rarity: 'Category:Rarity Entries'
    };

    var SIDE_ICONS = {
        Items: 'Ball.png',
        Tools: 'Fishing_Rod.png',
        Enchants: 'strength.png'
    };

    var locations = [];
    var fishEntries = [];
    var baitEntries = [];
    var toolEntries = [];
    var enchantEntries = [];
    var rarityEntries = {};

    var currentSection = null;
    var currentItemTab = 'Fish';
    var currentLocation = null;
    var currentDisplayMode ='percentage';

    var ENTRIES_CACHE_VERSION =
    '2'; /* <--- change this version after every publish thx */

    var ENTRIES_CACHE_PREFIX =
    'fishEntriesCacheV';
    var ENTRIES_CACHE_KEY =
    ENTRIES_CACHE_PREFIX +
    ENTRIES_CACHE_VERSION;
    var itemsLoaded = false;
    var toolsLoaded = false;
    var enchantsLoaded = false;
    var itemsLoadPromise = null;
    var toolsLoadPromise = null;
    var enchantsLoadPromise = null;
    function clearOldEntriesCaches() {

        try {

            for (
                var i =
                    window.localStorage.length - 1;
                i >= 0;
                i--
            ) {

                var key =
                    window.localStorage.key(
                        i
                    );

                if (
                    key &&
                    key.indexOf(
                        ENTRIES_CACHE_PREFIX
                    ) === 0 &&
                    key !==
                    ENTRIES_CACHE_KEY
                ) {

                    window.localStorage.removeItem(
                        key
                    );

                }

            }

        } catch (error) {

            console.warn(
                'Old Entries Cache Cleanup Error:',
                error
            );

        }

    }

    function loadEntriesCache() {

        try {

            var rawCache =
                window.localStorage.getItem(
                    ENTRIES_CACHE_KEY
                );

            if (
                !rawCache
            ) {
                return false;
            }

            var cache =
                JSON.parse(
                    rawCache
                );

            if (
                !cache ||
                !Array.isArray(
                    cache.locations
                ) ||
                !Array.isArray(
                    cache.fishEntries
                ) ||
                !Array.isArray(
                    cache.baitEntries
                ) ||
                !Array.isArray(
                    cache.toolEntries
                ) ||
                !Array.isArray(
                    cache.enchantEntries
                ) ||
                !cache.rarityEntries
            ) {

                return false;

            }

            locations =
                cache.locations;

            fishEntries =
                cache.fishEntries;

            baitEntries =
                cache.baitEntries;

            toolEntries =
                cache.toolEntries;

            enchantEntries =
                cache.enchantEntries;

            rarityEntries =
                cache.rarityEntries;

            itemsLoaded =
                true;

            toolsLoaded =
                true;

            enchantsLoaded =
                true;

            return true;

        } catch (error) {

            console.warn(
                'Entries Cache Load Error:',
                error
            );

            return false;

        }

    }

    function saveEntriesCache() {

        try {

            window.localStorage.setItem(
                ENTRIES_CACHE_KEY,
                JSON.stringify({
                    savedAt:
                        Date.now(),

                    locations:
                        locations,

                    fishEntries:
                        fishEntries,

                    baitEntries:
                        baitEntries,

                    toolEntries:
                        toolEntries,

                    enchantEntries:
                        enchantEntries,

                    rarityEntries:
                        rarityEntries
                })
            );

        } catch (error) {

            console.warn(
                'Entries Cache Save Error:',
                error
            );

        }

    }

    $(function () {

        if (
            normalizePageName(
                mw.config.get('wgPageName')
            ) !==
            normalizePageName(
                ENTRIES_PAGE
            )
        ) {
            return;
        }

        var container =
            document.getElementById(
                'fish-entries-app'
            );

        if (!container) {
            return;
        }

        if (
            container.dataset.loaded ===
            'true'
        ) {
            return;
        }

        container.dataset.loaded =
            'true';

        clearOldEntriesCaches();

        container.innerHTML =
            '<div class="entries-app-loading">Loading entries...</div>';

        loadMediaWikiModules()
            .then(function () {

                var cacheLoaded =
                    loadEntriesCache();

                if (
                    cacheLoaded
                ) {

                    fishEntries.sort(
                        sortByRarity
                    );

                    baitEntries.sort(
                        sortByRarity
                    );

                    injectRarityStyles();

                    buildEntriesApp(
                        container
                    );

                    return;
                }

                var itemsPromise =
                    ensureSectionLoaded(
                        'Items'
                    );

                var toolsPromise =
                    ensureSectionLoaded(
                        'Tools'
                    );

                var enchantsPromise =
                    ensureSectionLoaded(
                        'Enchants'
                    );

                var everythingPromise =
                    Promise.all([
                        itemsPromise,
                        toolsPromise,
                        enchantsPromise
                    ]);

                return toolsPromise
                    .then(function () {

                        buildEntriesApp(
                            container
                        );

                        return everythingPromise;

                    })
                    .then(function () {

                        saveEntriesCache();

                    });
            })
            .catch(function (error) {

                console.error(
                    'Fish Entries App Error:',
                    error
                );

                container.innerHTML =
                    '<div class="entries-app-error">' +
                    escapeHtml(
                        formatError(
                            error
                        )
                    ) +
                    '</div>';

            });

    });

    function normalizePageName(value) {

        return String(
            value || ''
        )
            .replace(/_/g, ' ')
            .replace(/\s+/g, ' ')
            .trim()
            .toLowerCase();

    }

    function capitalizeFirst(value) {

        value =
            String(
                value || ''
            ).trim();

        if (!value) {
            return '';
        }

        return (
            value.charAt(0).toUpperCase() +
            value.slice(1).toLowerCase()
        );

    }

    function loadMediaWikiModules() {

        return mw.loader.using([
            'mediawiki.api',
            'mediawiki.util'
        ]);

    }
    function ensureSectionLoaded(
        section
    ) {

        if (
            section ===
            'Items'
        ) {

            if (
                itemsLoaded
            ) {
                return Promise.resolve();
            }

            if (
                itemsLoadPromise
            ) {
                return itemsLoadPromise;
            }

            itemsLoadPromise =
                Promise.all([
                    loadLocations(),
                    loadFish(),
                    loadBaits(),
                    loadRarities()
                ])
                    .then(function () {

                        fishEntries.sort(
                            sortByRarity
                        );

                        baitEntries.sort(
                            sortByRarity
                        );

                        injectRarityStyles();

                        itemsLoaded =
                            true;

                    })
                    .catch(function (
                        error
                    ) {

                        itemsLoadPromise =
                            null;

                        throw error;

                    });

            return itemsLoadPromise;

        }


        if (
            section ===
            'Tools'
        ) {

            if (
                toolsLoaded
            ) {
                return Promise.resolve();
            }

            if (
                toolsLoadPromise
            ) {
                return toolsLoadPromise;
            }

            toolsLoadPromise =
                loadTools()
                    .then(function () {

                        toolsLoaded =
                            true;

                    })
                    .catch(function (
                        error
                    ) {

                        toolsLoadPromise =
                            null;

                        throw error;

                    });

            return toolsLoadPromise;

        }


        if (
            section ===
            'Enchants'
        ) {

            if (
                enchantsLoaded
            ) {
                return Promise.resolve();
            }

            if (
                enchantsLoadPromise
            ) {
                return enchantsLoadPromise;
            }

            enchantsLoadPromise =
                loadEnchants()
                    .then(function () {

                        enchantsLoaded =
                            true;

                    })
                    .catch(function (
                        error
                    ) {

                        enchantsLoadPromise =
                            null;

                        throw error;

                    });

            return enchantsLoadPromise;

        }


        return Promise.resolve();

    }

    function loadLocations() {

        var api =
            new mw.Api();

        return getCategoryEntryPages(
            api,
            CATEGORIES.Location,
            'Location'
        )
            .then(function (entries) {

                locations =
                    entries.map(function (entry) {

                        return {    
                            page:
                                entry.page,

                            name:
                                entry.data.name ||
                                getNameFromPage(
                                    entry.page
                                ),

                            image:
                                entry.data.image ||
                                ''
                        };

                    });

                locations.sort(
                    sortByName
                );

            });

    }

