    function loadRarities() {

        var api =
            new mw.Api();

        return getCategoryEntryPages(
            api,
            CATEGORIES.Rarity,
            'Rarity'
        )
            .then(function (entries) {

                rarityEntries = {};

                entries.forEach(function (entry) {

                    var name =
                        String(
                            entry.data.name ||
                            getNameFromPage(
                                entry.page
                            )
                        ).trim();

                    if (!name) {
                        return;
                    }

                    var stars =
                        Number(
                            entry.data.stars
                        );

                    if (
                        !Number.isInteger(
                            stars
                        ) ||
                        stars < 0
                    ) {
                        stars = 0;
                    }

                    rarityEntries[
                        name.toLowerCase()
                    ] = {
                        name:
                            name,

                        stars:
                            stars,

                        color0:
                            normalizeHexColor(
                                entry.data.color_0
                            ) ||
                            '#ffffff',

                        color50:
                            normalizeHexColor(
                                entry.data.color_50
                            ) ||
                            '#ffffff',

                        color100:
                            normalizeHexColor(
                                entry.data.color_100
                            ) ||
                            '#ffffff'
                    };

                });

            });

    }

    function getRarityStars(
        rarityName
    ) {

        var rarity =
            rarityEntries[
                String(
                    rarityName || ''
                )
                    .trim()
                    .toLowerCase()
            ];

        if (!rarity) {
            return 999999;
        }

        var stars =
            Number(
                rarity.stars
            );

        if (
            !Number.isFinite(
                stars
            )
        ) {
            return 999999;
        }

        return stars;

    }

    function sortByRarity(
        a,
        b
    ) {

        var aStars =
            getRarityStars(
                a.rarity
            );

        var bStars =
            getRarityStars(
                b.rarity
            );

        if (
            aStars !==
            bStars
        ) {

            return (
                aStars -
                bStars
            );

        }

        return sortByName(
            a,
            b
        );

    }

    function getCategoryEntryPages(
        api,
        category,
        expectedType
    ) {

        return getAllCategoryMembers(
            api,
            category
        )
            .then(function (titles) {

                if (!titles.length) {
                    return [];
                }

                return getPagesContents(
                    api,
                    titles
                );

            })
            .then(function (pages) {

                if (!pages) {
                    return [];
                }

                var result = [];

                pages.forEach(function (page) {

                    var data =
                        parseEntryData(
                            page.text
                        );

                    if (!data) {
                        return;
                    }

                    if (
                        expectedType &&
                        String(
                            data.type || ''
                        ).toLowerCase() !==
                        expectedType.toLowerCase()
                    ) {
                        return;
                    }

                    result.push({
                        page:
                            page.title,

                        data:
                            data
                    });

                });

                return result;

            });

    }

    function getAllCategoryMembers(
        api,
        category,
        cmcontinue
    ) {

        var params = {
            action:
                'query',

            list:
                'categorymembers',

            cmtitle:
                category,

            cmlimit:
                'max',

            cmtype:
                'page',

            format:
                'json',

            formatversion:
                2
        };

        if (
            cmcontinue
        ) {

            params.cmcontinue =
                cmcontinue;

        }

        return apiRequest(
            api,
            params
        )
            .then(function (response) {

                var titles = [];

                if (
                    response.query &&
                    response.query.categorymembers
                ) {

                    titles =
                        response.query
                            .categorymembers
                            .map(function (page) {

                                return page.title;

                            });

                }

                if (
                    response.continue &&
                    response.continue.cmcontinue
                ) {

                    return getAllCategoryMembers(
                        api,
                        category,
                        response.continue.cmcontinue
                    )
                        .then(function (more) {

                            return titles.concat(
                                more
                            );

                        });

                }

                return titles;

            });

    }

    function getPagesContents(
        api,
        titles
    ) {

        var chunks = [];

        for (
            var i = 0;
            i < titles.length;
            i += 50
        ) {

            chunks.push(
                titles.slice(
                    i,
                    i + 50
                )
            );

        }

        return Promise.all(
            chunks.map(function (chunk) {

                return apiRequest(
                    api,
                    {
                        action:
                            'query',

                        prop:
                            'revisions',

                        titles:
                            chunk.join('|'),

                        rvprop:
                            'content',

                        rvslots:
                            'main',

                        redirects:
                            1,

                        format:
                            'json',

                        formatversion:
                            2
                    }
                );

            })
        )
            .then(function (responses) {

                var result = [];

                responses.forEach(function (response) {

                    if (
                        !response.query ||
                        !response.query.pages
                    ) {
                        return;
                    }

                    response.query.pages
                        .forEach(function (page) {

                            if (
                                page.missing ||
                                !page.revisions ||
                                !page.revisions.length
                            ) {
                                return;
                            }

                            var revision =
                                page.revisions[0];

                            var text = '';

                            if (
                                revision.slots &&
                                revision.slots.main
                            ) {

                                text =
                                    revision
                                        .slots
                                        .main
                                        .content ||
                                    revision
                                        .slots
                                        .main['*'] ||
                                    '';

                            } else {

                                text =
                                    revision.content ||
                                    revision['*'] ||
                                    '';

                            }

                            result.push({
                                title:
                                    page.title,

                                text:
                                    text
                            });

                        });

                });

                return result;

            });

    }

    function apiRequest(
        api,
        params
    ) {

        return new Promise(
            function (
                resolve,
                reject
            ) {

                api.get(
                    params
                )
                    .done(
                        resolve
                    )
                    .fail(function (
                        code,
                        details
                    ) {

                        reject(
                            normalizeApiError(
                                code,
                                details
                            )
                        );

                    });

            }
        );

    }

    function parseEntryData(text) {

        var match =
            String(
                text || ''
            ).match(
                /\{\{\s*EntryData\b([\s\S]*?)\n?\}\}/i
            );

        if (!match) {
            return null;
        }

        var data = {};
        var currentKey = null;

        match[1]
            .split(/\r?\n/)
            .forEach(function (line) {

                var parameter =
                    line.match(
                        /^\s*\|\s*([^=]+?)\s*=\s*(.*)$/
                    );

                if (
                    parameter
                ) {

                    currentKey =
                        parameter[1]
                            .trim()
                            .toLowerCase();

                    data[
                        currentKey
                    ] =
                        decodeTemplateValue(
                            parameter[2]
                                .trim()
                        );

                    return;

                }

                if (
                    currentKey &&
                    line.trim()
                ) {

                    data[
                        currentKey
                    ] +=
                        '\n' +
                        line.trim();

                }

            });

        return data;

    }

    function parseLocationWeights(
        value
    ) {

        var result = [];

        String(
            value || ''
        )
            .split(';')
            .forEach(function (part) {

                part =
                    part.trim();

                if (!part) {
                    return;
                }

                var separator =
                    part.lastIndexOf(
                        ':'
                    );

                if (
                    separator ===
                    -1
                ) {
                    return;
                }

                var location =
                    part
                        .slice(
                            0,
                            separator
                        )
                        .trim();

                var weight =
                    Number(
                        part
                            .slice(
                                separator + 1
                            )
                            .trim()
                    );

                if (
                    !location ||
                    !isFinite(
                        weight
                    ) ||
                    weight <= 0
                ) {
                    return;
                }

                result.push({
                    location:
                        location,

                    weight:
                        weight
                });

            });

        return result;

    }

    function getFishWeightForLocation(
        fish,
        locationName
    ) {

        var target =
            String(
                locationName || ''
            )
                .trim()
                .toLowerCase();

        for (
            var i = 0;
            i < fish.weights.length;
            i++
        ) {

            if (
                String(
                    fish.weights[i]
                        .location
                )
                    .trim()
                    .toLowerCase() ===
                target
            ) {

                return Number(
                    fish.weights[i]
                        .weight
                ) || 0;

            }

        }

        return 0;

    }

    function getFishForLocation(
        locationName
    ) {

        var result = [];
        var totalWeight = 0;

        fishEntries.forEach(function (fish) {

            var weight =
                getFishWeightForLocation(
                    fish,
                    locationName
                );

            if (
                weight <= 0
            ) {
                return;
            }

            totalWeight +=
                weight;

            result.push({
                fish:
                    fish,

                weight:
                    weight,

                chance:
                    0
            });

        });

        result.forEach(function (entry) {

            entry.chance =
                totalWeight > 0
                    ? (
                        entry.weight /
                        totalWeight
                    ) * 100
                    : 0;

        });

        result.sort(function (
            a,
            b
        ) {

            var aStars =
                getRarityStars(
                    a.fish.rarity
                );

            var bStars =
                getRarityStars(
                    b.fish.rarity
                );

            if (
                aStars !==
                bStars
            ) {

                return (
                    aStars -
                    bStars
                );

            }

            if (
                b.chance !==
                a.chance
            ) {

                return (
                    b.chance -
                    a.chance
                );

            }

            if (
                b.weight !==
                a.weight
            ) {

                return (
                    b.weight -
                    a.weight
                );

            }

            return String(
                a.fish.name || ''
            ).localeCompare(
                String(
                    b.fish.name || ''
                ),
                undefined,
                {
                    sensitivity:
                        'base'
                }
            );

        });

        return {
            entries:
                result,

            totalWeight:
                totalWeight
        };

    }

