    ) {

        body.innerHTML =
            '';

        var detail =
            document.createElement(
                'div'
            );

        detail.className =
            'wiki-entry-detail';

        detail.appendChild(
            createBackButton(
                function () {

                    renderLocationFish(
                        body,
                        location
                    );

                }
            )
        );

        if (
            fish.image
        ) {

            var image =
                document.createElement(
                    'img'
                );

            image.className =
                'wiki-entry-detail-image';

            image.src =
                getWikiImageUrl(
                    fish.image
                );

            image.alt =
                fish.name;

            detail.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'div'
            );

        name.className =
            'wiki-entry-detail-name';

        name.textContent =
            fish.name;

        applyRarityClass(
            name,
            fish.rarity
        );

        detail.appendChild(
            name
        );

        if (
            fish.rarity
        ) {

            var rarity =
                createRarityDisplay(
                    fish.rarity,
                    'wiki-entry-detail-rarity'
                );

            if (
                rarity
            ) {
                detail.appendChild(
                    rarity
                );
            }

        }

        var stats =
