                )
            );

        }

        detail.appendChild(
            stats
        );

        if (
            fish.description
        ) {

            var description =
                document.createElement(
                    'div'
                );

            description.className =
                'wiki-entry-description';

            renderLoreText(
                description,
                fish.description
            );

            detail.appendChild(
                description
            );

        }

        body.appendChild(
            detail
        );

    }

    function renderBaits(
        body
    ) {

        body.innerHTML =
            '';

        if (
            !baitEntries.length
        ) {

            body.appendChild(
                createEmptyMessage(
                    'No Bait entries have been published yet.'
                )
            );

            return;

        }

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-standard-entry-grid';

        baitEntries.forEach(function (bait) {

            grid.appendChild(
                createStandardCard(
                    bait,
                    function () {

                        renderStandardDetail(
                            body,
                            bait,
                            'Bait'
                        );

                    }
                )
            );

        });

        body.appendChild(
            grid
        );

    }

    function renderToolsSection(
        content
    ) {

        createSectionTitle(
            content,
            'Tools'
        );

        if (
            !toolEntries.length
        ) {

            content.appendChild(
                createEmptyMessage(
                    'No Tool entries have been published yet.'
                )
            );

            return;

        }

        var toolGroups = {};
        var rodTypeOrder = [];

        toolEntries.forEach(
            function (tool) {

                var rodType =
                    String(
                        tool.rodType ||
                        'Unassigned'
                    ).trim() ||
                    'Unassigned';

                var rodTypeKey =
                    rodType.toLowerCase();

                if (
                    !toolGroups[
                        rodTypeKey
                    ]
                ) {

                    toolGroups[
                        rodTypeKey
                    ] = {
                        name:
                            rodType,

                        tools:
                            []
                    };

                    rodTypeOrder.push(
                        rodTypeKey
                    );

                }

                toolGroups[
                    rodTypeKey
                ]
                    .tools
                    .push(
                        tool
                    );

            }
        );

        rodTypeOrder.forEach(
            function (rodTypeKey) {

                var toolGroup =
                    toolGroups[
                        rodTypeKey
                    ];

                var group =
                    document.createElement(
                        'div'
                    );

                group.className =
                    'wiki-tool-type-group';

                var pill =
                    document.createElement(
                        'div'
                    );

                pill.className =
                    'wiki-tool-type-pill';

                pill.textContent =
                    toolGroup.name;

                group.appendChild(
                    pill
                );

                var grid =
                    document.createElement(
                        'div'
                    );

                grid.className =
                    'wiki-standard-entry-grid';

                toolGroup.tools.forEach(
                    function (tool) {

                        grid.appendChild(
                            createStandardCard(
                                tool,
                                function () {

                                    renderToolDetail(
                                        content,
                                        tool
                                    );

                                }
                            )
                        );

                    }
                );

                group.appendChild(
                    grid
                );

                content.appendChild(
                    group
                );

            }
        );

    }

    function renderEnchantsSection(
        content
    ) {

        createSectionTitle(
            content,
            'Enchants'
        );

        if (
            !enchantEntries.length
        ) {

            content.appendChild(
                createEmptyMessage(
                    'No Enchant entries have been published yet.'
                )
            );

            return;

        }

        var enchantGroups = {};
        var rodTypeOrder = [];

        enchantEntries.forEach(
            function (enchant) {

                var rodType =
                    String(
                        enchant.rodType ||
                        'Unassigned'
                    ).trim() ||
                    'Unassigned';

                var rodTypeKey =
                    rodType.toLowerCase();

                if (
                    !enchantGroups[
                        rodTypeKey
                    ]
                ) {

                    enchantGroups[
                        rodTypeKey
                    ] = {
                        name:
                            rodType,

                        enchants:
                            []
                    };

                    rodTypeOrder.push(
                        rodTypeKey
                    );

                }

                enchantGroups[
                    rodTypeKey
                ]
                    .enchants
                    .push(
                        enchant
                    );

            }
        );

        rodTypeOrder.forEach(
            function (rodTypeKey) {

                var enchantGroup =
                    enchantGroups[
                        rodTypeKey
                    ];

                var totalWeight =
                    enchantGroup.enchants.reduce(
                        function (
                            total,
                            enchant
                        ) {

                            return (
                                total +
                                (
                                    Number(
                                        enchant.weight
                                    ) ||
                                    0
                                )
                            );

                        },
                        0
                    );

                enchantGroup.enchants.sort(
                    function (
                        a,
                        b
                    ) {

                        if (
                            a.weight !==
                            b.weight
                        ) {

                            return (
                                a.weight -
                                b.weight
                            );

                        }

                        return sortByName(
                            a,
                            b
                        );

                    }
                );

                var group =
                    document.createElement(
                        'div'
                    );

                group.className =
                    'wiki-tool-type-group';

                var pill =
                    document.createElement(
                        'div'
                    );

                pill.className =
                    'wiki-tool-type-pill';

                pill.textContent =
                    enchantGroup.name +
                    ' Enchants';

                group.appendChild(
                    pill
                );

                var grid =
                    document.createElement(
                        'div'
                    );

                grid.className =
                    'wiki-standard-entry-grid';

                enchantGroup.enchants.forEach(
                    function (enchant) {

                        var chance =
                            totalWeight > 0
                                ? (
                                    enchant.weight /
                                    totalWeight
                                ) * 100
                                : 0;

                        var card =
                            createStandardCard(
                                enchant,
                                function () {

                                    renderEnchantDetail(
                                        content,
                                        enchant,
                                        chance,
                                        totalWeight
                                    );

                                }
                            );

                        var chanceLabel =
                            document.createElement(
                                'div'
                            );

                        chanceLabel.className =
                            'wiki-standard-card-extra';

                        chanceLabel.textContent =
                            formatChance(
                                chance
                            );

                        card.appendChild(
                            chanceLabel
                        );

                        grid.appendChild(
                            card
                        );

                    }
                );

                group.appendChild(
                    grid
                );

                content.appendChild(
                    group
                );

            }
        );

    }

    function createStandardCard(
        entry,
        onClick
    ) {

        var card =
            document.createElement(
                'button'
            );

        card.type =
            'button';

        card.className =
            'wiki-standard-entry-card';

        if (
            entry.image
        ) {

            var image =
                document.createElement(
                    'img'
                );

            image.src =
                getWikiImageUrl(
                    entry.image
                );

            image.alt =
                entry.name;

            card.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'div'
            );

        name.className =
            'wiki-standard-entry-name';

        name.textContent =
            entry.name;

        if (
            entry.rarity
        ) {

            applyRarityClass(
                name,
                entry.rarity
            );

        }

        card.appendChild(
            name
        );

        if (
            entry.rarity
        ) {

            var rarity =
                createRarityDisplay(
                    entry.rarity,
                    'wiki-standard-entry-rarity'
                );

            if (
                rarity
            ) {
                card.appendChild(
                    rarity
                );
            }

        }

        card.addEventListener(
            'click',
            onClick
        );

        return card;

    }

    function renderStandardDetail(
