    function renderItemsSection(
        content
    ) {

        createSectionTitle(
            content,
            'Items'
        );

        var tabs =
            document.createElement(
                'div'
            );

        tabs.className =
            'wiki-entry-subtabs';

        var fishButton =
            createSubtabButton(
                'Fish'
            );

        var baitButton =
            createSubtabButton(
                'Baits'
            );

        tabs.appendChild(
            fishButton
        );

        tabs.appendChild(
            baitButton
        );

        content.appendChild(
            tabs
        );

        var body =
            document.createElement(
                'div'
            );

        body.className =
            'wiki-entry-items-body';

        content.appendChild(
            body
        );

        fishButton.addEventListener(
            'click',
            function () {

                currentItemTab =
                    'Fish';

                currentLocation =
                    null;

                updateItemTabs(
                    fishButton,
                    baitButton
                );

                renderFishLocations(
                    body
                );

            }
        );

        baitButton.addEventListener(
            'click',
            function () {

                currentItemTab =
                    'Baits';

                currentLocation =
                    null;

                updateItemTabs(
                    fishButton,
                    baitButton
                );

                renderBaits(
                    body
                );

            }
        );

        updateItemTabs(
            fishButton,
            baitButton
        );

        if (
            currentItemTab ===
            'Baits'
        ) {

            renderBaits(
                body
            );

        } else {

            renderFishLocations(
                body
            );

        }

    }

    function createSubtabButton(
        text
    ) {

        var button =
            document.createElement(
                'button'
            );

        button.type =
            'button';

        button.className =
            'wiki-entry-subtab';

        button.textContent =
            text;

        return button;

    }

    function updateItemTabs(
        fishButton,
        baitButton
    ) {

        fishButton.classList.toggle(
            'entry-active',
            currentItemTab ===
            'Fish'
        );

        baitButton.classList.toggle(
            'entry-active',
            currentItemTab ===
            'Baits'
        );

    }

    function renderFishLocations(
        body
    ) {

        body.innerHTML = '';

        if (
            currentLocation
        ) {

            renderLocationFish(
                body,
                currentLocation
            );

            return;

        }

        if (
            !locations.length
        ) {

            body.appendChild(
                createEmptyMessage(
                    'No locations have been published yet.'
                )
            );

            return;

        }

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-location-grid';

        locations.forEach(function (location) {

            var button =
                document.createElement(
                    'button'
                );

            button.type =
                'button';

            button.className =
                'wiki-location-pill';

            if (
                location.image
            ) {

                var image =
                    document.createElement(
                        'img'
                    );

                image.src =
                    getWikiImageUrl(
                        location.image
                    );

                image.alt =
                    location.name;

                button.appendChild(
                    image
                );

            }

            var name =
                document.createElement(
                    'div'
                );

            name.className =
                'wiki-location-name';

            name.textContent =
                location.name;

            button.appendChild(
                name
            );

            button.addEventListener(
                'click',
                function () {

                    currentLocation =
                        location;

                    renderFishLocations(
                        body
                    );

                }
            );

            grid.appendChild(
                button
            );

        });

        body.appendChild(
            grid
        );

    }

    function renderLocationFish(
        body,
        location
    ) {

        body.innerHTML =
            '';

        var header =
            document.createElement(
                'div'
            );

        header.className =
            'wiki-location-header';

        var title =
            document.createElement(
                'div'
            );

        title.className =
            'wiki-location-header-title';

        if (
            location.image
        ) {

            var image =
                document.createElement(
                    'img'
                );

            image.src =
                getWikiImageUrl(
                    location.image
                );

            image.alt =
                location.name;

            title.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'span'
            );

        name.textContent =
            location.name;

        title.appendChild(
            name
        );

        var back =
            document.createElement(
                'button'
            );

        back.type =
            'button';

        back.className =
            'wiki-entry-back';

        back.textContent =
            'Back';

        back.addEventListener(
            'click',
            function () {

                currentLocation =
                    null;

                renderFishLocations(
                    body
                );

            }
        );

        header.appendChild(
            title
        );

        header.appendChild(
            back
        );

        body.appendChild(
            header
        );

        var calculated =
            getFishForLocation(
                location.name
            );

        if (
            !calculated.entries.length
        ) {

            body.appendChild(
                createEmptyMessage(
                    'No fish can currently be caught here.'
                )
            );

            return;

        }

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-fish-grid';

        calculated.entries
            .forEach(function (entry) {

                grid.appendChild(
                    createFishCard(
                        entry.fish,
                        location,
                        entry.weight,
                        entry.chance,
                        calculated.totalWeight
                    )
                );

            });

        body.appendChild(
            grid
        );

    }

