        function renderBaitPicker() {

            baitPickerGrid.innerHTML =
                '';

            baitEntries.forEach(
                function (bait,index) {

                    var card =
                        document.createElement(
                            'button'
                        );

                    card.type =
                        'button';

                    card.className =
                        'wiki-bait-picker-card';

                    if (
                        bait.image
                    ) {

                        var image =
                            document.createElement(
                                'img'
                            );

                        image.src =
                            getWikiImageUrl(
                                bait.image
                            );

                        image.alt =
                            bait.name;

                        card.appendChild(
                            image
                        );

                    }

                    var name =
                        document.createElement(
                            'span'
                        );

                    name.textContent =
                        bait.name;

                    card.appendChild(
                        name
                    );

                    card.addEventListener(
                        'click',
                        function () {

                            selectedBait =
                                bait;

                            currentFishLuckBaitIndex =
                                index;

                            baitButtonName.textContent =
                                bait.name;

                            refreshCurrentFishLocation();

                            if (
                                bait.image
                            ) {

                                baitButtonImage.src =
                                    getWikiImageUrl(
                                        bait.image
                                    );

                                baitButtonImage.alt =
                                    bait.name;

                                baitButtonImage.style.display =
                                    'block';

                            } else {

                        baitButtonImage.style.display =
                            'none';

                    }

                    baitPicker.style.display =
                        'none';

                }
            );

            baitPickerGrid.appendChild(
                card
            );

        }
    );

}


baitButton.addEventListener(
    'click',
    function () {

        if (
            baitPicker.style.display ===
            'block'
        ) {

            baitPicker.style.display =
                'none';

            return;

        }

        baitPicker.style.display =
            'block';

        baitPickerGrid.innerHTML =
            '<div class="wiki-bait-picker-loading">Loading...</div>';

        ensureSectionLoaded(
            'Items'
        )
            .then(function () {

                renderBaitPicker();

            });

    }
);

        sideMenu.appendChild(
            luckSetting
        );
        function updateToolSettings() {

            var selectedTool =
                toolEntries[
                    Number(
                        toolSelect.value
                    )
                ];

            var rodType =
                selectedTool
                    ? String(
                        selectedTool.rodType ||
                        ''
                    )
                        .trim()
                        .toLowerCase()
                    : '';

            if (
                rodType ===
                'gun'
            ) {

                enchantText.textContent =
                    'Sharpshooter Enchant:';

                baitField.style.display =
                    'none';

            } else {

                enchantText.textContent =
                    'Ultra Enchant:';

                baitField.style.display =
                    'flex';

            }

        }

        toolSelect.addEventListener(
            'change',
            function () {

                currentFishLuckToolIndex =
                    Number(
                        toolSelect.value
                    ) || 0;

                updateToolSettings();

                refreshCurrentFishLocation();

            }
        );

        updateToolSettings();
        shell.appendChild(
            nav
        );

        shell.appendChild(
            content
        );

        var frame =
            document.createElement(
                'div'
        );

        frame.className =
            'wiki-entries-frame';

        frame.appendChild(
            menuBar
        );
        frame.appendChild(
            sideMenu
        );

        frame.appendChild(
            shell
        );

        container.appendChild(
            frame
        );

        menuButton.addEventListener(
            'click',
            function () {

                sideMenu.classList.toggle(
                    'wiki-side-menu-open'
                );

            }
        );

        createNavButton(
            nav,
            'Items',
            SIDE_ICONS.Items
        );

        createNavButton(
            nav,
            'Tools',
            SIDE_ICONS.Tools
        );

        createNavButton(
            nav,
            'Enchants',
            SIDE_ICONS.Enchants
        );

    }

    function createNavButton(
        container,
        section,
        imageName
    ) {

        var button =
            document.createElement(
                'button'
            );

        button.type =
            'button';

        button.className =
            'wiki-entry-nav-pill';

        button.setAttribute(
            'data-entry-section',
            section
        );

        var image =
            document.createElement(
                'img'
            );

        image.src =
            getWikiImageUrl(
                imageName
            );

        image.alt =
            section;

        var label =
            document.createElement(
                'span'
            );

        label.textContent =
            section;

        button.appendChild(
            image
        );

        button.appendChild(
            label
        );

        button.addEventListener(
            'click',
            function () {

                currentSection =
                    section;

                currentLocation =
                    null;

                var shell =
                    document.querySelector(
                        '#fish-entries-app .wiki-entries-shell'
                    );

                var content =
                    document.querySelector(
                        '#fish-entries-app .wiki-entries-content'
                    );

                if (
                    shell
                ) {

                    shell.classList.remove(
                        'wiki-entries-start'
                    );

                    shell.classList.add(
                        'wiki-entries-open'
                    );

                }

                if (
                    content
                ) {

                    content.style.display =
                        'block';

                }

                updateNavButtons();

                if (
                    content
                ) {

                    content.innerHTML =
                        '';

                    content.appendChild(
                        createEmptyMessage(
                            'Loading ' +
                            section +
                            '...'
                        )
                    );

                }

                ensureSectionLoaded(
                    section
                )
                    .then(function () {

                        if (
                            currentSection !==
                            section
                        ) {
                            return;
                        }

                        renderCurrentSection();

                    })
                    .catch(function (
                        error
                    ) {

                        console.error(
                            'Section Load Error:',
                            error
                        );

                        if (
                            currentSection !==
                            section ||
                            !content
                        ) {
                            return;
                        }

                        content.innerHTML =
                            '';

                        content.appendChild(
                            createEmptyMessage(
                                'Could not load ' +
                                section +
                                '.'
                            )
                        );

                    });

            }
        );

        container.appendChild(
            button
        );

    }

    function updateNavButtons() {

        document
            .querySelectorAll(
                '#fish-entries-app .wiki-entry-nav-pill'
            )
            .forEach(function (button) {

                var section =
                    button.getAttribute(
                        'data-entry-section'
                    );

                button.classList.toggle(
                    'entry-active',
                    section ===
                    currentSection
                );

            });

    }

    function renderCurrentSection() {

        updateNavButtons();

        var content =
            document.querySelector(
                '#fish-entries-app .wiki-entries-content'
            );

        if (
            !content
        ) {
            return;
        }

        content.innerHTML =
            '';

        if (
            currentSection ===
            'Items'
        ) {

            renderItemsSection(
                content
            );

            return;

        }

        if (
            currentSection ===
            'Tools'
        ) {

            renderToolsSection(
                content
            );

            return;

        }

        if (
            currentSection ===
            'Enchants'
        ) {

            renderEnchantsSection(
                content
            );

        }

    }

    function createSectionTitle(
        container,
        text
    ) {

        var title =
            document.createElement(
                'div'
            );

        title.className =
            'wiki-entry-content-title';

        title.textContent =
            text;

        container.appendChild(
            title
        );

    }

    function renderItemsSection(
        content
    ) {

        createSectionTitle(
            content,
            'Items'
        );

        var tabs =
            document.createElement(
                'div'
            );

        tabs.className =
            'wiki-entry-subtabs';

        var fishButton =
            createSubtabButton(
                'Fish'
            );

        var baitButton =
            createSubtabButton(
                'Baits'
            );

        tabs.appendChild(
            fishButton
        );

        tabs.appendChild(
            baitButton
        );

        content.appendChild(
            tabs
        );

        var body =
            document.createElement(
                'div'
            );

        body.className =
            'wiki-entry-items-body';

        content.appendChild(
            body
        );

        fishButton.addEventListener(
            'click',
            function () {

                currentItemTab =
                    'Fish';

                currentLocation =
                    null;

                updateItemTabs(
                    fishButton,
                    baitButton
                );

                renderFishLocations(
                    body
                );

            }
        );

        baitButton.addEventListener(
            'click',
            function () {

                currentItemTab =
                    'Baits';

                currentLocation =
                    null;

                updateItemTabs(
                    fishButton,
                    baitButton
                );

                renderBaits(
                    body
                );

            }
        );

        updateItemTabs(
            fishButton,
            baitButton
        );

        if (
            currentItemTab ===
            'Baits'
        ) {

            renderBaits(
                body
            );

        } else {

            renderFishLocations(
                body
            );

        }

    }

    function createSubtabButton(
        text
    ) {

        var button =
            document.createElement(
                'button'
            );

        button.type =
            'button';

        button.className =
            'wiki-entry-subtab';

        button.textContent =
            text;

        return button;

    }

    function updateItemTabs(
        fishButton,
        baitButton
    ) {

        fishButton.classList.toggle(
            'entry-active',
            currentItemTab ===
            'Fish'
        );

        baitButton.classList.toggle(
            'entry-active',
            currentItemTab ===
            'Baits'
        );

    }

    function renderFishLocations(
        body
    ) {

        body.innerHTML = '';

        if (
            currentLocation
        ) {

            renderLocationFish(
                body,
                currentLocation
            );

            return;

        }

        if (
            !locations.length
        ) {

            body.appendChild(
                createEmptyMessage(
                    'No locations have been published yet.'
                )
            );

            return;

        }

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-location-grid';

        locations.forEach(function (location) {

            var button =
                document.createElement(
                    'button'
                );

            button.type =
                'button';

            button.className =
                'wiki-location-pill';

            if (
                location.image
            ) {

                var image =
                    document.createElement(
                        'img'
                    );

                image.src =
                    getWikiImageUrl(
                        location.image
                    );

                image.alt =
                    location.name;

                button.appendChild(
                    image
                );

            }

            var name =
                document.createElement(
                    'div'
                );

            name.className =
                'wiki-location-name';

            name.textContent =
                location.name;

            button.appendChild(
                name
            );

            button.addEventListener(
                'click',
                function () {

                    currentLocation =
                        location;

                    renderFishLocations(
                        body
                    );

                }
            );

            grid.appendChild(
                button
            );

        });

        body.appendChild(
            grid
        );

    }

    function renderLocationFish(
        body,
        location
    ) {

        body.innerHTML =
            '';

        var header =
            document.createElement(
                'div'
            );

        header.className =
            'wiki-location-header';

        var title =
            document.createElement(
                'div'
            );

        title.className =
            'wiki-location-header-title';

        if (
            location.image
        ) {

            var image =
                document.createElement(
                    'img'
                );

            image.src =
                getWikiImageUrl(
                    location.image
                );

            image.alt =
                location.name;

            title.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'span'
            );

        name.textContent =
            location.name;

        title.appendChild(
            name
        );

        var back =
            document.createElement(
                'button'
            );

        back.type =
            'button';

        back.className =
            'wiki-entry-back';

        back.textContent =
            'Back';

        back.addEventListener(
            'click',
            function () {

                currentLocation =
                    null;

                renderFishLocations(
                    body
                );

            }
        );

        header.appendChild(
            title
        );

        header.appendChild(
            back
        );

        body.appendChild(
            header
        );

        var calculated =
            getFishForLocation(
                location.name
            );

        if (
            !calculated.entries.length
        ) {

            body.appendChild(
                createEmptyMessage(
                    'No fish can currently be caught here.'
                )
            );

            return;

        }

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-fish-grid';

        calculated.entries
            .forEach(function (entry) {

                grid.appendChild(
                    createFishCard(
                        entry.fish,
                        location,
                        entry.weight,
                        entry.chance,
                        calculated.totalWeight
                    )
                );

            });

        body.appendChild(
            grid
        );

    }

    function createFishCard(
        fish,
        location,
        weight,
        chance,
        totalWeight
    ) {

        var card =
            document.createElement(
                'button'
            );

        card.type =
            'button';

        card.className =
            'wiki-fish-card';

        applyRarityBorderClass(
            card,
            fish.rarity
        );

        if (
            fish.image
        ) {

            var image =
                document.createElement(
                    'img'
                );

            image.className =
                'wiki-fish-card-image';

            image.src =
                getWikiImageUrl(
                    fish.image
                );

            image.alt =
                fish.name;

            card.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'div'
            );

        name.className =
            'wiki-fish-card-name';

        name.textContent =
            fish.name;

        applyRarityClass(
            name,
            fish.rarity
        );

        card.appendChild(
            name
        );

        if (
            fish.rarity
        ) {

            var rarity =
                createRarityDisplay(
                    fish.rarity,
                    'wiki-fish-card-rarity'
                );

            if (
                rarity
            ) {
                card.appendChild(
                    rarity
                );
            }

        }

        var chanceText =
            document.createElement(
                'div'
            );

        chanceText.className =
            'wiki-fish-card-chance';

        chanceText.textContent =
            formatChance(
                chance
            );

        card.appendChild(
            chanceText
        );

        card.addEventListener(
            'click',
            function () {

                var body =
                    document.querySelector(
                        '#fish-entries-app .wiki-entry-items-body'
                    );

                if (
                    !body
                ) {
                    return;
                }

                renderFishDetail(
                    body,
                    fish,
                    location,
                    weight,
                    chance,
                    totalWeight
                );

            }
        );

        return card;

    }

    function renderFishDetail(
        body,
        fish,
        location,
        weight,
        chance,
        totalWeight
    ) {

        body.innerHTML =
            '';

        var detail =
            document.createElement(
                'div'
            );

        detail.className =
            'wiki-entry-detail';

        detail.appendChild(
            createBackButton(
                function () {

                    renderLocationFish(
                        body,
                        location
                    );

                }
            )
        );

        if (
            fish.image
        ) {

            var image =
                document.createElement(
                    'img'
                );

            image.className =
                'wiki-entry-detail-image';

            image.src =
                getWikiImageUrl(
                    fish.image
                );

            image.alt =
                fish.name;

            detail.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'div'
            );

        name.className =
            'wiki-entry-detail-name';

        name.textContent =
            fish.name;

        applyRarityClass(
            name,
            fish.rarity
        );

        detail.appendChild(
            name
        );

        if (
            fish.rarity
        ) {

            var rarity =
                createRarityDisplay(
                    fish.rarity,
                    'wiki-entry-detail-rarity'
                );

            if (
                rarity
            ) {
                detail.appendChild(
                    rarity
                );
            }

        }

        var stats =
            document.createElement(
                'div'
            );

        stats.className =
            'wiki-entry-stat-grid';

        stats.appendChild(
            createStat(
                'Chance',
                formatChance(
                    chance
                )
            )
        );

        stats.appendChild(
            createStat(
                'Weight',
                formatNumber(
                    weight
                )
            )
        );

        if (
            fish.baseSellPrice !==
            ''
        ) {

            stats.appendChild(
                createStat(
                    'Base Sell',
                    fish.baseSellPrice
                )
            );

        }

        detail.appendChild(
            stats
        );

        if (
            fish.description
        ) {

            var description =
                document.createElement(
                    'div'
                );

            description.className =
                'wiki-entry-description';

            renderLoreText(
                description,
                fish.description
            );

            detail.appendChild(
                description
            );

        }

        body.appendChild(
            detail
        );

    }

    function renderBaits(
        body
    ) {

        body.innerHTML =
            '';

        if (
            !baitEntries.length
        ) {

            body.appendChild(
                createEmptyMessage(
                    'No Bait entries have been published yet.'
                )
            );

            return;

        }

        var grid =
            document.createElement(
                'div'
            );

        grid.className =
            'wiki-standard-entry-grid';

        baitEntries.forEach(function (bait) {

            grid.appendChild(
                createStandardCard(
                    bait,
                    function () {

                        renderStandardDetail(
                            body,
                            bait,
                            'Bait'
                        );

                    }
                )
            );

        });

        body.appendChild(
            grid
        );

    }

    function renderToolsSection(
        content
    ) {

        createSectionTitle(
            content,
            'Tools'
        );

        if (
            !toolEntries.length
        ) {

            content.appendChild(
                createEmptyMessage(
                    'No Tool entries have been published yet.'
                )
            );

            return;

        }

        var toolGroups = {};
        var rodTypeOrder = [];

        toolEntries.forEach(
            function (tool) {

                var rodType =
                    String(
                        tool.rodType ||
                        'Unassigned'
                    ).trim() ||
                    'Unassigned';

                var rodTypeKey =
                    rodType.toLowerCase();

                if (
                    !toolGroups[
                        rodTypeKey
                    ]
                ) {

                    toolGroups[
                        rodTypeKey
                    ] = {
                        name:
                            rodType,

                        tools:
                            []
                    };

                    rodTypeOrder.push(
                        rodTypeKey
                    );

                }

                toolGroups[
                    rodTypeKey
                ]
                    .tools
                    .push(
                        tool
                    );

            }
        );

        rodTypeOrder.forEach(
            function (rodTypeKey) {

                var toolGroup =
                    toolGroups[
                        rodTypeKey
                    ];

                var group =
                    document.createElement(
                        'div'
                    );

                group.className =
                    'wiki-tool-type-group';

                var pill =
                    document.createElement(
                        'div'
                    );

                pill.className =
                    'wiki-tool-type-pill';

                pill.textContent =
                    toolGroup.name;

                group.appendChild(
                    pill
                );

                var grid =
                    document.createElement(
                        'div'
                    );

                grid.className =
                    'wiki-standard-entry-grid';

                toolGroup.tools.forEach(
                    function (tool) {

                        grid.appendChild(
                            createStandardCard(
                                tool,
                                function () {

                                    renderToolDetail(
                                        content,
                                        tool
                                    );

                                }
                            )
                        );

                    }
                );

                group.appendChild(
                    grid
                );

                content.appendChild(
                    group
                );

            }
        );

    }

    function renderEnchantsSection(
        content
    ) {

        createSectionTitle(
            content,
            'Enchants'
        );

        if (
            !enchantEntries.length
        ) {

            content.appendChild(
                createEmptyMessage(
                    'No Enchant entries have been published yet.'
                )
            );

            return;

        }

        var enchantGroups = {};
        var rodTypeOrder = [];

        enchantEntries.forEach(
            function (enchant) {

                var rodType =
                    String(
                        enchant.rodType ||
                        'Unassigned'
                    ).trim() ||
                    'Unassigned';

                var rodTypeKey =
                    rodType.toLowerCase();

                if (
                    !enchantGroups[
                        rodTypeKey
                    ]
                ) {

                    enchantGroups[
                        rodTypeKey
                    ] = {
                        name:
                            rodType,

                        enchants:
                            []
                    };

                    rodTypeOrder.push(
                        rodTypeKey
                    );

                }

                enchantGroups[
                    rodTypeKey
                ]
                    .enchants
                    .push(
                        enchant
                    );

            }
        );

        rodTypeOrder.forEach(
            function (rodTypeKey) {

                var enchantGroup =
                    enchantGroups[
                        rodTypeKey
                    ];

                var totalWeight =
                    enchantGroup.enchants.reduce(
                        function (
                            total,
                            enchant
                        ) {

                            return (
                                total +
                                (
                                    Number(
                                        enchant.weight
                                    ) ||
                                    0
                                )
                            );

                        },
                        0
                    );

                enchantGroup.enchants.sort(
                    function (
                        a,
                        b
                    ) {

                        if (
                            a.weight !==
                            b.weight
                        ) {

                            return (
                                a.weight -
                                b.weight
                            );

                        }

                        return sortByName(
                            a,
                            b
                        );

                    }
                );

                var group =
                    document.createElement(
                        'div'
                    );

                group.className =
                    'wiki-tool-type-group';

                var pill =
                    document.createElement(
                        'div'
                    );

                pill.className =
                    'wiki-tool-type-pill';

                pill.textContent =
                    enchantGroup.name +
                    ' Enchants';

                group.appendChild(
                    pill
                );

                var grid =
                    document.createElement(
                        'div'
                    );

                grid.className =
                    'wiki-standard-entry-grid';

                enchantGroup.enchants.forEach(
                    function (enchant) {

                        var chance =
                            totalWeight > 0
                                ? (
                                    enchant.weight /
                                    totalWeight
                                ) * 100
                                : 0;

                        var card =
                            createStandardCard(
                                enchant,
                                function () {

                                    renderEnchantDetail(
                                        content,
                                        enchant,
                                        chance,
                                        totalWeight
                                    );

                                }
                            );

                        var chanceLabel =
                            document.createElement(
                                'div'
                            );

                        chanceLabel.className =
                            'wiki-standard-card-extra';

                        chanceLabel.textContent =
                            formatChance(
                                chance
                            );

                        card.appendChild(
                            chanceLabel
                        );

                        grid.appendChild(
                            card
                        );

                    }
                );

                group.appendChild(
                    grid
                );

                content.appendChild(
                    group
                );

            }
        );

    }

    function createStandardCard(
        entry,
        onClick
    ) {

        var card =
            document.createElement(
                'button'
            );

        card.type =
            'button';

        card.className =
            'wiki-standard-entry-card';

        if (
            entry.rarity
        ) {

            applyRarityBorderClass(
                card,
                entry.rarity
            );

        }

        if (
            entry.image
        ) {

            var image =
                document.createElement(
                    'img'
                );

            image.src =
                getWikiImageUrl(
                    entry.image
                );

            image.alt =
                entry.name;

            card.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'div'
            );

        name.className =
            'wiki-standard-entry-name';

        name.textContent =
            entry.name;

        if (
            entry.rarity
        ) {

            applyRarityClass(
                name,
                entry.rarity
            );

        }

        card.appendChild(
            name
        );

        if (
            entry.rarity
        ) {

            var rarity =
                createRarityDisplay(
                    entry.rarity,
                    'wiki-standard-entry-rarity'
                );

            if (
                rarity
            ) {
                card.appendChild(
                    rarity
                );
            }

        }

        card.addEventListener(
            'click',
            onClick
        );

        return card;

    }

    function renderStandardDetail(
        body,
        entry,
        type
    ) {

        body.innerHTML =
            '';

        var detail =
            document.createElement(
                'div'
            );

        detail.className =
            'wiki-entry-detail';

        detail.appendChild(
            createBackButton(
                function () {

                    if (
                        type ===
                        'Bait'
                    ) {

                        renderBaits(
                            body
                        );

                    }

                }
            )
        );

        appendDetailBasicInfo(
            detail,
            entry
        );

        body.appendChild(
            detail
        );

    }

    function renderToolDetail(
        content,
        tool
    ) {

        content.innerHTML =
            '';

        createSectionTitle(
            content,
            'Tools'
        );

        var detail =
            document.createElement(
                'div'
            );

        detail.className =
            'wiki-entry-detail wiki-tool-detail';

        detail.appendChild(
            createBackButton(
                function () {

                    renderCurrentSection();

                }
            )
        );

        if (
            tool.image
        ) {

            var image =
