            image.src =
                getWikiImageUrl(
                    tool.image
                );

            image.alt =
                tool.name;

            detail.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'div'
            );

        name.className =
            'wiki-entry-detail-name';

        name.textContent =
            tool.name;

        detail.appendChild(
            name
        );

        if (
            tool.baseCost !==
            ''
        ) {

            var stats =
                document.createElement(
                    'div'
                );

            stats.className =
                'wiki-entry-stat-grid wiki-tool-base-cost';

            stats.appendChild(
                createStat(
                    'Base Cost',
                    tool.baseCost
                )
            );

            detail.appendChild(
                stats
            );

        }

        if (
            tool.description
        ) {

