    function loadTools() {

        var api =
            new mw.Api();

        return getCategoryEntryPages(
            api,
            CATEGORIES.Tool,
            'Tool'
        )
            .then(function (entries) {

                toolEntries =
                    entries.map(function (entry) {

                        return {
                            page:
                                entry.page,

                            name:
                                entry.data.name ||
                                getNameFromPage(
                                    entry.page
                                ),

                            image:
                                entry.data.image ||
                                '',

                            description:
                                entry.data.description ||
                                '',

                            baseCost:
                                entry.data.base_cost ||
                                '',
                            rodType:
                                String(
                                    entry.data.rod_type ||
                                    'Unassigned'
                                ).trim() ||
                                'Unassigned',
                            luck:
                                entry.data.luck !==
                                    undefined &&
                                entry.data.luck !==
                                    ''
                                    ? Number(
                                        entry.data.luck
                                    )
                                    : 1
                        };

                    });

                toolEntries.sort(function (
                    a,
                    b
                ) {

                    var aCost =
                        Number(
                            a.baseCost
                        );

                    var bCost =
                        Number(
                            b.baseCost
                        );

                    if (
                        !Number.isFinite(
                            aCost
                        )
                    ) {
                        aCost = Infinity;
                    }

                    if (
                        !Number.isFinite(
                            bCost
                        )
                    ) {
                        bCost = Infinity;
                    }

                    if (
                        aCost !==
                        bCost
                    ) {

                        return (
                            aCost -
                            bCost
                        );

                    }

                    return sortByName(
                        a,
                        b
                    );

                });

            });

    }

