    function loadRarities() {

        var api =
            new mw.Api();

        return getCategoryEntryPages(
            api,
            CATEGORIES.Rarity,
            'Rarity'
        )
            .then(function (entries) {

                rarityEntries = {};

                entries.forEach(function (entry) {

                    var name =
                        String(
                            entry.data.name ||
                            getNameFromPage(
                                entry.page
                            )
                        ).trim();

                    if (!name) {
                        return;
                    }

                    var stars =
                        Number(
                            entry.data.stars
                        );

                    if (
                        !Number.isInteger(
                            stars
                        ) ||
                        stars < 0
                    ) {
                        stars = 0;
                    }

                    rarityEntries[
                        name.toLowerCase()
                    ] = {
                        name:
                            name,

                        stars:
                            stars,

                        color0:
                            normalizeHexColor(
                                entry.data.color_0
                            ) ||
                            '#ffffff',

                        color50:
                            normalizeHexColor(
                                entry.data.color_50
                            ) ||
                            '#ffffff',

                        color100:
                            normalizeHexColor(
                                entry.data.color_100
                            ) ||
                            '#ffffff'
                    };

                });

            });

    }

    function getRarityStars(
        rarityName
    ) {

        var rarity =
            rarityEntries[
                String(
                    rarityName || ''
                )
                    .trim()
                    .toLowerCase()
            ];

        if (!rarity) {
            return 999999;
        }

        var stars =
            Number(
                rarity.stars
            );

        if (
            !Number.isFinite(
                stars
            )
        ) {
            return 999999;
        }

        return stars;

    }

    function sortByRarity(
        a,
        b
    ) {

        var aStars =
            getRarityStars(
                a.rarity
            );

        var bStars =
            getRarityStars(
                b.rarity
            );

        if (
            aStars !==
            bStars
        ) {

            return (
                aStars -
                bStars
            );

        }

        return sortByName(
            a,
            b
        );

    }

    function getCategoryEntryPages(
        api,
        category,
        expectedType
    ) {

        return getAllCategoryMembers(
            api,
            category
        )
            .then(function (titles) {

                if (!titles.length) {
                    return [];
                }

                return getPagesContents(
                    api,
                    titles
                );

            })
            .then(function (pages) {

                if (!pages) {
                    return [];
                }

                var result = [];

                pages.forEach(function (page) {

                    var data =
                        parseEntryData(
                            page.text
                        );

                    if (!data) {
                        return;
                    }

                    if (
                        expectedType &&
                        String(
                            data.type || ''
                        ).toLowerCase() !==
                        expectedType.toLowerCase()
                    ) {
                        return;
                    }

                    result.push({
                        page:
                            page.title,

                        data:
                            data
                    });

                });

                return result;

            });

    }

    function getAllCategoryMembers(
        api,
        category,
        cmcontinue
    ) {

        var params = {
            action:
                'query',

            list:
                'categorymembers',

            cmtitle:
                category,

            cmlimit:
                'max',

            cmtype:
                'page',

            format:
                'json',

            formatversion:
                2
        };

        if (
            cmcontinue
        ) {

            params.cmcontinue =
                cmcontinue;

        }

        return apiRequest(
            api,
            params
        )
            .then(function (response) {

                var titles = [];

                if (
                    response.query &&
                    response.query.categorymembers
                ) {

                    titles =
                        response.query
                            .categorymembers
                            .map(function (page) {

                                return page.title;

                            });

                }

                if (
                    response.continue &&
                    response.continue.cmcontinue
                ) {

                    return getAllCategoryMembers(
                        api,
                        category,
                        response.continue.cmcontinue
                    )
                        .then(function (more) {

                            return titles.concat(
                                more
                            );

                        });

                }

                return titles;

            });

    }

    function getPagesContents(
        api,
        titles
    ) {

        var chunks = [];

        for (
            var i = 0;
            i < titles.length;
            i += 50
        ) {

            chunks.push(
                titles.slice(
                    i,
                    i + 50
                )
            );

        }

        return Promise.all(
            chunks.map(function (chunk) {

                return apiRequest(
                    api,
                    {
                        action:
                            'query',

                        prop:
                            'revisions',

                        titles:
                            chunk,

                        rvprop:
                            'content',

                        rvslots:
                            'main',

                        redirects:
                            1,

                        format:
                            'json',

                        formatversion:
                            2
                    }
                );

            })
        )
            .then(function (responses) {

                var result = [];

                responses.forEach(function (response) {

                    if (
                        !response.query ||
                        !response.query.pages
                    ) {
                        return;
                    }

                    response.query.pages
                        .forEach(function (page) {

                            if (
                                page.missing ||
                                !page.revisions ||
                                !page.revisions.length
                            ) {
                                return;
                            }

                            var revision =
                                page.revisions[0];

                            var text = '';

                            if (
                                revision.slots &&
                                revision.slots.main
                            ) {

                                text =
                                    revision
                                        .slots
                                        .main
                                        .content ||
                                    revision
                                        .slots
                                        .main['*'] ||
                                    '';

                            } else {

                                text =
                                    revision.content ||
                                    revision['*'] ||
                                    '';

                            }

                            result.push({
                                title:
                                    page.title,

                                text:
                                    text
                            });

                        });

                });

                return result;

            });

    }

    function apiRequest(
        api,
        params
    ) {

        return new Promise(
            function (
                resolve,
                reject
            ) {

                api.get(
                    params
                )
                    .done(
                        resolve
                    )
                    .fail(function (
                        code,
                        details
                    ) {

                        reject(
                            normalizeApiError(
                                code,
                                details
                            )
                        );

                    });

            }
        );

    }

    function parseEntryData(text) {

        var match =
            String(
                text || ''
            ).match(
                /\{\{\s*EntryData\b([\s\S]*?)\n?\}\}/i
            );

        if (!match) {
            return null;
        }

        var data = {};
        var currentKey = null;

        match[1]
            .split(/\r?\n/)
            .forEach(function (line) {

                var parameter =
                    line.match(
                        /^\s*\|\s*([^=]+?)\s*=\s*(.*)$/
                    );

                if (
                    parameter
                ) {

                    currentKey =
                        parameter[1]
                            .trim()
                            .toLowerCase();

                    data[
                        currentKey
                    ] =
                        decodeTemplateValue(
                            parameter[2]
                                .trim()
                        );

                    return;

                }

                if (
                    currentKey &&
                    line.trim()
                ) {

                    data[
                        currentKey
                    ] +=
                        '\n' +
                        line.trim();

                }

            });

        return data;

    }

    function parseLocationWeights(
        value
    ) {

        var result = [];

        String(
            value || ''
        )
            .split(';')
            .forEach(function (part) {

                part =
                    part.trim();

                if (!part) {
                    return;
                }

                var separator =
                    part.lastIndexOf(
                        ':'
                    );

                if (
                    separator ===
                    -1
                ) {
                    return;
                }

                var location =
                    part
                        .slice(
                            0,
                            separator
                        )
                        .trim();

                var weight =
                    Number(
                        part
                            .slice(
                                separator + 1
                            )
                            .trim()
                    );

                if (
                    !location ||
                    !isFinite(
                        weight
                    ) ||
                    weight <= 0
                ) {
                    return;
                }

                result.push({
                    location:
                        location,

                    weight:
                        weight
                });

            });

        return result;

    }

    function getFishWeightForLocation(
        fish,
        locationName
    ) {

        var target =
            String(
                locationName || ''
            )
                .trim()
                .toLowerCase();

        for (
            var i = 0;
            i < fish.weights.length;
            i++
        ) {

            if (
                String(
                    fish.weights[i]
                        .location
                )
                    .trim()
                    .toLowerCase() ===
                target
            ) {

                return Number(
                    fish.weights[i]
                        .weight
                ) || 0;

            }

        }

        return 0;

    }

    function getEntryLuckMultiplier(
        value
    ) {

        var multiplier =
            Number(
                value
            );

        if (
            !Number.isFinite(
                multiplier
            )
        ) {
            return 1;
        }

        return Math.max(
            0,
            multiplier
        );

    }


    function getSelectedFishLuckTool() {

        return (
            toolEntries[
                currentFishLuckToolIndex
            ] ||
            null
        );

    }


    function getCurrentFishLuckMultiplier() {

        var multiplier =
            1;

        var selectedTool =
            getSelectedFishLuckTool();

        if (
            selectedTool
        ) {

            multiplier *=
                getEntryLuckMultiplier(
                    selectedTool.luck
                );

        }

        var enchantLevel =
            Number(
                currentFishLuckEnchantLevel
            );

        if (
            !Number.isFinite(
                enchantLevel
            ) ||
            enchantLevel < 0
        ) {
            enchantLevel = 0;
        }

        multiplier *=
            1 +
            (
                enchantLevel *
                0.1
            );

        var fortuneLevel =
            Number(
                currentFishLuckFortuneLevel
            );

        if (
            !Number.isFinite(
                fortuneLevel
            ) ||
            fortuneLevel < 0
        ) {
            fortuneLevel = 0;
        }

        fortuneLevel =
            Math.min(
                20,
                fortuneLevel
            );

        multiplier *=
            1 +
            (
                fortuneLevel *
                0.05
            );

        var rodType =
            selectedTool
                ? String(
                    selectedTool.rodType ||
                    ''
                )
                    .trim()
                    .toLowerCase()
                : '';

        if (
            rodType !==
                'gun' &&
            currentFishLuckBaitIndex >=
                0
        ) {

            var selectedBait =
                baitEntries[
                    currentFishLuckBaitIndex
                ];

            if (
                selectedBait
            ) {

                multiplier *=
                    getEntryLuckMultiplier(
                        selectedBait.luck
                    );

            }

        }

        return Math.max(
            0,
            multiplier
        );

    }


    function sortByFishLuckSpawnOrder(
        a,
        b
    ) {

        if (
            b.baseWeight !==
            a.baseWeight
        ) {

            return (
                b.baseWeight -
                a.baseWeight
            );

        }

        return String(
            a.fish.name || ''
        ).localeCompare(
            String(
                b.fish.name || ''
            )
        );

    }


    function refreshCurrentFishLocation() {

        if (
            currentSection !==
                'Items' ||
            currentItemTab !==
                'Fish' ||
            !currentLocation
        ) {
            return;
        }

        var body =
            document.querySelector(
                '#fish-entries-app .wiki-entry-items-body'
            );

        if (!body) {
            return;
        }

        renderLocationFish(
            body,
            currentLocation
        );

    }

    function getFishForLocation(
        locationName
    ) {

        var result = [];
        var totalWeight = 0;

        fishEntries.forEach(function (
            fish
        ) {

            var baseWeight =
                getFishWeightForLocation(
                    fish,
                    locationName
                );

            if (
                baseWeight <= 0
            ) {
                return;
            }

            result.push({
                fish:
                    fish,

                baseWeight:
                    baseWeight,

                weight:
                    baseWeight,

                chance:
                    0
            });

        });

        result.sort(
            sortByFishLuckSpawnOrder
        );


        var fishLuckMultiplier =
            getCurrentFishLuckMultiplier();

        if (
            result.length > 1
        ) {

            result.forEach(function (
                entry,
                index
            ) {

                var rarityScale =
                    index /
                    (
                        result.length -
                        1
                    );

                var weightMultiplier =
                    Math.pow(
                        fishLuckMultiplier,
                        rarityScale
                    );

                entry.weight =
                    entry.baseWeight *
                    weightMultiplier;

            });

        }


        result.forEach(function (
            entry
        ) {

            totalWeight +=
                entry.weight;

        });


        result.forEach(function (
            entry
        ) {

            entry.chance =
                totalWeight > 0
                    ? (
                        entry.weight /
                        totalWeight
                    ) * 100
                    : 0;

        });


        result.sort(function (
            a,
            b
        ) {

            var aStars =
                getRarityStars(
                    a.fish.rarity
                );

            var bStars =
                getRarityStars(
                    b.fish.rarity
                );

            if (
                aStars !==
                bStars
            ) {
                return (
                    aStars -
                    bStars
                );
            }

            if (
                b.chance !==
                a.chance
            ) {
                return (
                    b.chance -
                    a.chance
                );
            }

            return String(
                a.fish.name || ''
            ).localeCompare(
                String(
                    b.fish.name || ''
                )
            );

        });


        return {
            entries:
                result,

            totalWeight:
                totalWeight
        };

    }

    function buildEntriesApp(
        container
    ) {

        container.innerHTML = '';

        var shell =
            document.createElement(
                'div'
            );

        shell.className =
            'wiki-entries-shell wiki-entries-start';

        var nav =
            document.createElement(
                'div'
            );

        nav.className =
            'wiki-entries-nav';

        var content =
            document.createElement(
                'div'
            );

        content.className =
            'wiki-entries-content';

        content.style.display =
            'none';

        var menuBar =
            document.createElement(
                'div'
            );

        menuBar.className =
            'wiki-entries-menu-bar';

        var menuButton =
            document.createElement(
                'button'
            );

        menuButton.type =
            'button';

        menuButton.className =
            'wiki-entries-menu-button';

        menuButton.innerHTML =
            '<span></span><span></span><span></span>';

        var displayStatus =
            document.createElement(
                'div'
            );

        displayStatus.className =
            'wiki-display-status';

        displayStatus.textContent =
            currentDisplayMode ===
                'fraction'
                ? 'Displaying: Fraction'
                : 'Displaying: Percentage';

        menuBar.appendChild(
            menuButton
        );

        menuBar.appendChild(
            displayStatus
        );

        var sideMenu =
            document.createElement(
                'div'
            );

        sideMenu.className =
            'wiki-entries-side-menu';

        var displaySetting =
            document.createElement(
                'div'
            );

        displaySetting.className =
            'wiki-side-menu-setting';

        var displayLabel =
            document.createElement(
                'div'
            );

        displayLabel.className =
            'wiki-side-menu-label';

        displayLabel.textContent =
            'Display:';


        var displayToggle =
            document.createElement(
                'button'
            );

        displayToggle.type =
            'button';

        displayToggle.className =
            'wiki-display-toggle';

        displayToggle.textContent =
            currentDisplayMode ===
                'fraction'
                ? 'Fraction'
                : 'Percentage';


        displayToggle.addEventListener(
            'click',
            function () {

                if (
                    currentDisplayMode ===
                    'percentage'
                ) {

                    currentDisplayMode =
                        'fraction';

                    displayToggle.textContent =
                        'Fraction';

                    displayStatus.textContent =
                        'Displaying: Fraction';

                } else {

                    currentDisplayMode =
                        'percentage';

                    displayToggle.textContent =
                        'Percentage';

                    displayStatus.textContent =
                        'Displaying: Percentage';

                }
                saveDisplayModeCache();
                if (
                    currentSection
                ) {

                    renderCurrentSection();

                }

            }
        );


        displaySetting.appendChild(
            displayLabel
        );

        displaySetting.appendChild(
            displayToggle
        );

        sideMenu.appendChild(
            displaySetting
        );

        var luckSetting =
            document.createElement(
                'div'
            );

        luckSetting.className =
            'wiki-side-menu-setting wiki-fish-luck-setting';

        var luckTitle =
            document.createElement(
                'div'
            );

        luckTitle.className =
            'wiki-side-menu-label';

        luckTitle.textContent =
            'Fish Luck Modifier';

        luckSetting.appendChild(
            luckTitle
        );

        var toolField =
            document.createElement(
                'label'
            );

        toolField.className =
            'wiki-setting-field';

        var toolText =
            document.createElement(
                'span'
            );

        toolText.textContent =
            'Select your tool:';

        var toolSelect =
            document.createElement(
                'select'
            );

        toolSelect.className =
            'wiki-setting-select';

        toolSelect.innerHTML =
            '';

        var toolTypeGroups =
            {};

        var toolTypeOrder =
            [];

        toolEntries.forEach(
            function (
                tool,
                index
            ) {

                var rodType =
                    String(
                        tool.rodType ||
                        'Unassigned'
                    ).trim() ||
                    'Unassigned';

                var rodTypeKey =
                    rodType.toLowerCase();

                if (
                    !toolTypeGroups[
                        rodTypeKey
                    ]
                ) {

                    toolTypeGroups[
                        rodTypeKey
                    ] = {
                        name:
                            rodType,

                        tools:
                            []
                    };

                    toolTypeOrder.push(
                        rodTypeKey
                    );

                }

                toolTypeGroups[
                    rodTypeKey
                ].tools.push({
                    tool:
                        tool,

                    index:
                        index
                });

            }
        );

        toolTypeOrder.forEach(
            function (
                rodTypeKey
            ) {

                var group =
                    toolTypeGroups[
                        rodTypeKey
                    ];

                var optgroup =
                    document.createElement(
                        'optgroup'
                    );

                optgroup.label =
                    group.name;

                group.tools.forEach(
                    function (
                        entry
                    ) {

                        var option =
                            document.createElement(
                                'option'
                            );

                        option.value =
                            String(
                                entry.index
                            );

                        option.textContent =
                            entry.tool.name;

                        option.setAttribute(
                            'data-luck',
                            entry.tool.luck
                        );

                        optgroup.appendChild(
                            option
                        );

                    }
                );

                toolSelect.appendChild(
                    optgroup
                );

            }
        );

        toolField.appendChild(
            toolText
        );

        toolField.appendChild(
            toolSelect
        );

        luckSetting.appendChild(
            toolField
        );

        var enchantField =
