        );


        function renderBaitPicker() {

            baitPickerGrid.innerHTML =
                '';

            baitEntries.forEach(
                function (bait,index) {

                    var card =
                        document.createElement(
                            'button'
                        );

                    card.type =
                        'button';

                    card.className =
                        'wiki-bait-picker-card';

                    if (
                        bait.image
                    ) {

                        var image =
                            document.createElement(
                                'img'
                            );

                        image.src =
                            getWikiImageUrl(
                                bait.image
                            );

                        image.alt =
                            bait.name;

                        card.appendChild(
                            image
                        );

                    }

                    var name =
                        document.createElement(
                            'span'
                        );

                    name.textContent =
