            '<div class="wiki-bait-picker-loading">Loading...</div>';

        ensureSectionLoaded(
            'Items'
        )
            .then(function () {

                renderBaitPicker();

            });

    }
);

        sideMenu.appendChild(
            luckSetting
        );
        function updateToolSettings() {

            var selectedTool =
                toolEntries[
                    Number(
                        toolSelect.value
                    )
                ];

            var rodType =
                selectedTool
                    ? String(
                        selectedTool.rodType ||
                        ''
                    )
                        .trim()
                        .toLowerCase()
                    : '';

            if (
                rodType ===
                'gun'
            ) {

                enchantText.textContent =
                    'Sharpshooter Enchant:';

                baitField.style.display =
                    'none';

            } else {

                enchantText.textContent =
                    'Ultra Enchant:';

                baitField.style.display =
                    'flex';

            }

        }

        toolSelect.addEventListener(
            'change',
            function () {

                currentFishLuckToolIndex =
                    Number(
                        toolSelect.value
                    ) || 0;

                updateToolSettings();

                refreshCurrentFishLocation();

            }
        );

        updateToolSettings();
        shell.appendChild(
            nav
        );

