            frame
        );

        menuButton.addEventListener(
            'click',
            function () {

                sideMenu.classList.toggle(
                    'wiki-side-menu-open'
                );

            }
        );

        createNavButton(
            nav,
            'Items',
            SIDE_ICONS.Items
        );

        createNavButton(
