    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    padding: 7px;

    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 14px;

    color: #4f8cff;

    cursor: pointer;

    box-sizing: border-box;

    transition:
        background 0.15s ease,
        border-color 0.15s ease,
        transform 0.15s ease;
}

.wiki-location-pill:hover {
    background: #101a2b;
    border-color: #58aaff;
    transform: translateY(-1px);
}

.wiki-location-pill img {
    width: 55px;
    height: 55px;

    object-fit: contain;

    margin: 0 auto 3px;
}

.wiki-location-name {
    width: 100%;

    color: #4f8cff;

    font-size: 12px;
    font-weight: bold;

    line-height: 1.05;

    text-align: center;

    overflow-wrap: anywhere;
}


/* LOCATION HEADER */

.wiki-location-header {
    display: flex;
    align-items: center;
    justify-content: space-between;

    gap: 8px;

    margin-bottom: 10px;
}

.wiki-location-header-title {
    min-width: 0;

    display: flex;
    align-items: center;

    gap: 7px;

    color: #4f8cff;

    font-size: 17px;
    font-weight: bold;
}

.wiki-location-header-title img {
    width: 30px;
    height: 30px;

    object-fit: contain;
}

.wiki-location-header-title span {
    overflow-wrap: anywhere;
}


/* BACK BUTTON */

.wiki-entry-back {
    flex: 0 0 auto;

    padding: 5px 10px;

    background: #10275a;
    border: 2px solid #58aaff;
    border-radius: 8px;

    color: #ffffff;

    font-size: 11px;
    font-weight: bold;

    cursor: pointer;
}

.wiki-entry-back:hover {
    background: #1d4389;
}


/* FISH / TOOL / BAIT / ENCHANT GRIDS */

.wiki-fish-grid,
.wiki-standard-entry-grid {
    display: grid;

    grid-template-columns:
        repeat(3, minmax(0, 1fr));

    gap: 9px;

    width: 100%;
}

.wiki-fish-card,
.wiki-standard-entry-card {
    min-width: 0;
    min-height: 115px;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-start;

    padding: 7px;

    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 13px;

    color: #ffffff;

    text-align: center;

    cursor: pointer;

    box-sizing: border-box;

    transition:
        background 0.15s ease,
        border-color 0.15s ease,
        transform 0.15s ease;
}

.wiki-fish-card:hover,
.wiki-standard-entry-card:hover {
    background: #101a2b;
    border-color: #58aaff;
    transform: translateY(-1px);
}

.wiki-fish-card-image,
.wiki-standard-entry-card img {
    width: 50px;
    height: 50px;

    object-fit: contain;

    margin: 0 auto 4px;
}

.wiki-fish-card-name,
.wiki-standard-entry-name {
    width: 100%;

    font-size: 12px;
    font-weight: bold;
    line-height: 1.05;

    overflow-wrap: anywhere;
}

.wiki-fish-card-rarity,
.wiki-standard-entry-rarity {
    margin-top: 3px;

    font-size: 9px;
    font-weight: bold;
}

.wiki-fish-card-chance,
.wiki-standard-card-extra {
    margin-top: 4px;

    color: #70b9ff;

    font-size: 11px;
    font-weight: bold;
}


/* ENTRY DETAILS */

.wiki-entry-detail {
    width: 100%;

    text-align: center;

    box-sizing: border-box;
}

.wiki-detail-back-row {
    display: flex;
    justify-content: flex-end;

    margin-bottom: 4px;
}

.wiki-entry-detail-image {
    width: 72px;
    height: 72px;

    object-fit: contain;

    margin: 0 auto 5px;
}

.wiki-entry-detail-name {
    font-size: 20px;
    font-weight: bold;

    line-height: 1.05;

    overflow-wrap: anywhere;
}

.wiki-entry-detail-rarity {
    margin-top: 3px;

    font-size: 11px;
    font-weight: bold;
}


/* STATS */

.wiki-entry-stat-grid {
    display: grid;

    grid-template-columns:
        repeat(3, minmax(0, 1fr));

    gap: 6px;

    margin-top: 9px;
}

.wiki-entry-stat {
    min-width: 0;

    padding: 6px 4px;

    background: #07142e;
    border: 1px solid #263a63;
    border-radius: 8px;

    box-sizing: border-box;
}

.wiki-entry-stat-label {
    color: #70b9ff;

    font-size: 8px;
    font-weight: bold;

    text-transform: uppercase;
}

.wiki-entry-stat-value {
    margin-top: 2px;

    color: #ffffff;

    font-size: 12px;
    font-weight: bold;

    overflow-wrap: anywhere;
}


/* DESCRIPTION */

.wiki-entry-description {
    margin-top: 8px;
    padding: 8px;

    background: #07142e;
    border: 1px solid #252c34;
    border-radius: 8px;

    color: #ffffff;

    font-size: 11px;
    line-height: 1.35;

    text-align: left;

    overflow-wrap: anywhere;
}


/* LOADING / EMPTY / ERROR */

.wiki-entry-empty,
.entries-app-loading,
.entries-app-error {
    width: 100%;

    padding: 18px 8px;

    color: #8d9aae;

    font-size: 12px;

    text-align: center;

    box-sizing: border-box;
}

.entries-app-error {
    color: #ff7272;
}


