.wiki-entries-shell {
    width: 750px;
    max-width: 100%;
    height: 400px;
    padding: 14px;

    background: #07142e;
    border: 4px solid #252c34;
    border-radius: 24px;

    overflow: hidden;
    box-sizing: border-box;
}

.wiki-entries-start {
    display: flex;
    align-items: center;
    justify-content: center;
}

.wiki-entries-start .wiki-entries-nav {
    width: 100%;

    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));

    gap: 18px;
    margin: 0;
}

.wiki-entries-start .wiki-entry-nav-pill {
    width: 100%;
    height: 220px;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    gap: 13px;
    padding: 14px;

    background: #0b1017;
    border: 3px solid #252c34;
    border-radius: 18px;

    color: #4f8cff;

    font-family: inherit;
    font-size: 27px;
    font-weight: 500;
    line-height: 1;

    text-align: center;

    cursor: pointer;

    box-sizing: border-box;
    appearance: none;

    transition:
        background 0.15s ease,
        border-color 0.15s ease,
        transform 0.15s ease;
}

.wiki-entries-start .wiki-entry-nav-pill:hover {
    background: #101722;
    border-color: #58aaff;
    transform: translateY(-2px);
}

.wiki-entries-start .wiki-entry-nav-pill img {
    display: block;

    width: 110px;
    height: 110px;

    object-fit: contain;

    margin: 0;
}

.wiki-entries-start .wiki-entry-nav-pill span {
    display: block;

    margin: 0;

    color: #4f8cff;

    line-height: 1;
}

.wiki-entries-start .wiki-entries-content {
    display: none;
}

.wiki-entries-open {
    display: grid;
    grid-template-columns: 150px minmax(0, 1fr);
    gap: 14px;
}

.wiki-entries-open .wiki-entries-nav {
    display: flex;
    flex-direction: column;

    gap: 10px;

    min-width: 0;
    height: 100%;
}

.wiki-entries-open .wiki-entry-nav-pill {
    width: 100%;

    flex: 1 1 0;
    min-height: 0;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    gap: 7px;
    padding: 8px;

    background: #0b1017;
    border: 3px solid #252c34;
    border-radius: 17px;

    color: #4f8cff;

    font-family: inherit;
    font-size: 16px;
    font-weight: bold;
    line-height: 1;

    text-align: center;

    cursor: pointer;

    box-sizing: border-box;
    appearance: none;

    transition:
        background 0.15s ease,
        border-color 0.15s ease,
        transform 0.15s ease;
}

.wiki-entries-open .wiki-entry-nav-pill:hover {
    background: #101722;
    border-color: #58aaff;
    transform: translateY(-1px);
}

.wiki-entries-open .wiki-entry-nav-pill.entry-active {
    background: #18366f;
    border-color: #58aaff;
}

.wiki-entries-open .wiki-entry-nav-pill img {
    display: block;

    width: 62px;
    height: 62px;

    object-fit: contain;

    margin: 0;
}

.wiki-entries-open .wiki-entry-nav-pill span {
    display: block;

    margin: 0;

    color: #4f8cff;

    line-height: 1;
}

.wiki-entries-content {
    width: 100%;
    height: 100%;

    min-width: 0;
    min-height: 0;

    padding: 15px 16px;

    background: #0b1017;
    border: 3px solid #252c34;
    border-radius: 18px;

    overflow-y: auto;
    overflow-x: hidden;

    box-sizing: border-box;
}

.wiki-entries-content::-webkit-scrollbar {
    width: 6px;
}

.wiki-entries-content::-webkit-scrollbar-track {
    background: transparent;
}

.wiki-entries-content::-webkit-scrollbar-thumb {
    background: #263a63;
    border-radius: 999px;
}

.wiki-entry-content-title {
    margin: 0 0 11px;

    color: #4f8cff;

    font-size: 25px;
    font-weight: bold;
    line-height: 1;
}

.wiki-entry-subtabs {
    display: flex;
    align-items: center;

    gap: 8px;

    margin: 0 0 12px;
}

.wiki-entry-subtab {
    padding: 7px 14px;

    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 999px;

    color: #4f8cff;

    font-family: inherit;
    font-size: 14px;
    font-weight: bold;
    line-height: 1.2;

    cursor: pointer;

    box-sizing: border-box;
    appearance: none;

    transition:
        background 0.15s ease,
        border-color 0.15s ease;
}

.wiki-entry-subtab:hover {
    border-color: #58aaff;
}

.wiki-entry-subtab.entry-active {
    background: #18366f;
    border-color: #58aaff;
}

.wiki-entry-items-body {
    width: 100%;
    min-width: 0;

    box-sizing: border-box;
}

.wiki-location-grid {
    width: 100%;

    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    align-items: flex-start;

    gap: 9px;

    box-sizing: border-box;
}

.wiki-location-pill {
    width: 125px;
    height: 112px;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    gap: 4px;
    padding: 7px;

    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 14px;

    color: #4f8cff;

    font-family: inherit;

    cursor: pointer;

    box-sizing: border-box;
    appearance: none;

    transition:
        background 0.15s ease,
        border-color 0.15s ease,
        transform 0.15s ease;
}

.wiki-location-pill:hover {
    background: #101722;
    border-color: #58aaff;
    transform: translateY(-1px);
}

.wiki-location-pill img {
    display: block;

    width: 58px;
    height: 58px;

    object-fit: contain;

    margin: 0;
}

.wiki-location-name {
    width: 100%;

    color: #4f8cff;

    font-size: 12px;
    font-weight: bold;
    line-height: 1.05;

    text-align: center;

    overflow-wrap: anywhere;
}

.wiki-location-header {
    width: 100%;

    display: flex;
    align-items: center;
    justify-content: space-between;

    gap: 8px;

    margin-bottom: 10px;
}

.wiki-location-header-title {
    min-width: 0;

    display: flex;
    align-items: center;

    gap: 7px;

    color: #4f8cff;

    font-size: 17px;
    font-weight: bold;
    line-height: 1;
}

.wiki-location-header-title img {
    flex: 0 0 auto;

    display: block;

    width: 32px;
    height: 32px;

    object-fit: contain;
}

.wiki-location-header-title span {
    min-width: 0;

    overflow-wrap: anywhere;
}

.wiki-entry-back {
    flex: 0 0 auto;

    padding: 5px 10px;

    background: #10275a;
    border: 2px solid #58aaff;
    border-radius: 8px;

    color: #ffffff;

    font-family: inherit;
    font-size: 11px;
    font-weight: bold;

    cursor: pointer;

    appearance: none;
    box-sizing: border-box;
}

.wiki-entry-back:hover {
    background: #1d4389;
}

.wiki-fish-grid,
.wiki-standard-entry-grid {
    width: 100%;

    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));

    gap: 9px;

    box-sizing: border-box;
}

.wiki-fish-card,
.wiki-standard-entry-card {
    min-width: 0;
    min-height: 125px;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-start;

    padding: 7px;

    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 13px;

    color: #ffffff;

    font-family: inherit;
    text-align: center;

    cursor: pointer;

    box-sizing: border-box;
    appearance: none;

    transition:
        background 0.15s ease,
        border-color 0.15s ease,
        transform 0.15s ease;
}

.wiki-fish-card:hover,
.wiki-standard-entry-card:hover {
    background: #101722;
    border-color: #58aaff;
    transform: translateY(-1px);
}

.wiki-fish-card-image,
.wiki-standard-entry-card img {
    display: block;

    width: 52px;
    height: 52px;

    object-fit: contain;

    margin: 0 auto 4px;
}

.wiki-fish-card-name,
.wiki-standard-entry-name {
    width: 100%;

    font-size: 12px;
    font-weight: bold;
    line-height: 1.05;

    overflow-wrap: anywhere;
}

.wiki-fish-card-rarity,
.wiki-standard-entry-rarity {
    width: 100%;

    display: flex;
    align-items: center;
    justify-content: center;
    flex-wrap: wrap;

    gap: 5px;

    margin-top: 4px;

    font-size: 10px;
    font-weight: bold;
    line-height: 1;

    text-align: center;
}

.wiki-rarity-stars-inline {
    display: inline-block;
    margin-left: 1px;
    font-weight: bold;
    letter-spacing: 1px;
}

.wiki-fish-card-chance,
.wiki-standard-card-extra {
    margin-top: 5px;

    color: #70b9ff;

    font-size: 12px;
    font-weight: bold;
    line-height: 1;
}

.wiki-entry-detail {
    width: 100%;
    min-width: 0;

    text-align: center;

    box-sizing: border-box;
}

.wiki-detail-back-row {
    width: 100%;

    display: flex;
    justify-content: flex-end;

    margin-bottom: 4px;
}

.wiki-entry-detail-image {
    display: block;

    width: 80px;
    height: 80px;

    object-fit: contain;

    margin: 0 auto 5px;
}

.wiki-entry-detail-name {
    width: 100%;

    font-size: 21px;
    font-weight: bold;
    line-height: 1.05;

    overflow-wrap: anywhere;
}

.wiki-entry-detail-rarity {
    width: 100%;

    display: flex;
    align-items: center;
    justify-content: center;
    flex-wrap: wrap;

    gap: 6px;

    margin-top: 5px;

    font-size: 13px;
    font-weight: bold;
    line-height: 1;

    text-align: center;
}

.wiki-entry-detail-rarity .wiki-rarity-stars-inline {
    font-size: 14px;
}

.wiki-entry-stat-grid {
    width: 100%;

    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));

    gap: 6px;

    margin-top: 10px;

    box-sizing: border-box;
}

.wiki-entry-stat {
    min-width: 0;

    padding: 7px 4px;

    background: #07142e;
    border: 1px solid #263a63;
    border-radius: 8px;

    box-sizing: border-box;
}

.wiki-entry-stat-label {
    color: #70b9ff;

    font-size: 8px;
    font-weight: bold;
    line-height: 1.1;

    text-transform: uppercase;
}

.wiki-entry-stat-value {
    margin-top: 3px;

    color: #ffffff;

    font-size: 12px;
    font-weight: bold;
    line-height: 1.1;

    overflow-wrap: anywhere;
}

.wiki-entry-description {
    width: 100%;

    margin-top: 9px;
    padding: 8px;

    background: #07142e;
    border: 1px solid #252c34;
    border-radius: 8px;

    color: #ffffff;

    font-size: 11px;
    line-height: 1.35;

    text-align: left;

    overflow-wrap: anywhere;

    box-sizing: border-box;
}

.wiki-entry-empty,
.entries-app-loading,
.entries-app-error {
    width: 100%;

    padding: 18px 8px;

    color: #8d9aae;

    font-size: 12px;

    text-align: center;

    box-sizing: border-box;
}

.entries-app-loading {
    width: 750px;
    max-width: 100%;

    min-height: 100px;

    margin: 0 auto;
}

.entries-app-error {
    color: #ff7272;
}

@media (max-width: 760px) {

    #fish-entries-app {
        width: 100%;
    }

    .wiki-entries-shell {
        width: 100%;
        height: 400px;
    }

    .wiki-entries-start .wiki-entries-nav {
        gap: 10px;
    }

    .wiki-entries-start .wiki-entry-nav-pill {
        height: 205px;
        font-size: 21px;
    }

    .wiki-entries-start .wiki-entry-nav-pill img {
        width: 90px;
        height: 90px;
    }

    .wiki-entries-open {
        grid-template-columns: 125px minmax(0, 1fr);
        gap: 10px;
    }

    .wiki-entries-open .wiki-entry-nav-pill {
        font-size: 14px;
    }

    .wiki-entries-open .wiki-entry-nav-pill img {
        width: 52px;
        height: 52px;
    }

    .wiki-location-pill {
        width: 115px;
    }

}

@media (max-width: 520px) {

    .wiki-entries-shell {
        height: 400px;

        padding: 9px;

        border-radius: 20px;
    }

    .wiki-entries-start .wiki-entries-nav {
        gap: 6px;
    }

    .wiki-entries-start .wiki-entry-nav-pill {
        height: 160px;

        padding: 8px;

        border-radius: 14px;

        font-size: 15px;
    }

    .wiki-entries-start .wiki-entry-nav-pill img {
        width: 62px;
        height: 62px;
    }

    .wiki-entries-open {
        grid-template-columns: 90px minmax(0, 1fr);

        gap: 7px;
    }

    .wiki-entries-open .wiki-entries-nav {
        gap: 7px;
    }

    .wiki-entries-open .wiki-entry-nav-pill {
        padding: 4px;

        border-radius: 12px;

        font-size: 10px;
    }

    .wiki-entries-open .wiki-entry-nav-pill img {
        width: 36px;
        height: 36px;
    }

    .wiki-entries-content {
        padding: 10px;

        border-radius: 14px;
    }

    .wiki-entry-content-title {
        font-size: 19px;
    }

    .wiki-entry-subtab {
        padding: 5px 10px;

        font-size: 11px;
    }

    .wiki-location-grid {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));

        gap: 7px;
    }

    .wiki-location-pill {
        width: 100%;
        height: 98px;
    }

    .wiki-location-pill img {
        width: 46px;
        height: 46px;
    }

    .wiki-fish-grid,
    .wiki-standard-entry-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));

        gap: 7px;
    }

    .wiki-fish-card,
    .wiki-standard-entry-card {
        min-height: 112px;
    }

    .wiki-fish-card-image,
    .wiki-standard-entry-card img {
        width: 44px;
        height: 44px;
    }

    .wiki-fish-card-rarity,
    .wiki-standard-entry-rarity {
        gap: 3px;

        font-size: 9px;
    }

    .wiki-rarity-stars-inline {
        letter-spacing: 0;
    }

    .wiki-entry-stat-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

}

