    border-radius: 10px;

    z-index: 1;

    pointer-events: none;

    transition:
        background 0.15s ease;
}

.wiki-fish-card.wiki-rarity-animated-border > * {
    position: relative;

    z-index: 2;
}

.wiki-fish-card.wiki-rarity-animated-border:hover::after {
    background: #101722;
}

@keyframes wiki-rarity-border-spin {

    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }

}

@media (max-width: 760px) {

    #fish-entries-app {
        width: 100%;
    }

    .wiki-entries-shell {
        width: 100%;
    }

    .wiki-entries-open {
        grid-template-columns: 125px minmax(0, 1fr);

        gap: 10px;
    }

    .wiki-entries-open .wiki-entries-nav {
        width: 125px;
    }

    .wiki-entries-open .wiki-entry-nav-pill img {
        width: 52px;
        height: 52px;
    }

    .wiki-entries-open .wiki-entry-nav-pill {
        font-size: 14px;
    }

}

@media (max-width: 520px) {

    .wiki-entries-shell {
        height: 400px;

        padding: 8px;

        border-width: 3px;
        border-radius: 18px;
    }

    .wiki-entries-start .wiki-entries-nav {
        gap: 7px;
    }

    .wiki-entries-start .wiki-entry-nav-pill {
        height: 190px;

        padding: 8px;

        font-size: 18px;
    }

    .wiki-entries-start .wiki-entry-nav-pill img {
        width: 70px;
        height: 70px;
    }

    .wiki-entries-open {
        grid-template-columns: 90px minmax(0, 1fr);

        gap: 7px;
    }

    .wiki-entries-open .wiki-entries-nav {
        width: 90px;

        gap: 6px;
    }

    .wiki-entries-open .wiki-entry-nav-pill {
        padding: 5px;

        border-radius: 10px;

        font-size: 11px;
    }

    .wiki-entries-open .wiki-entry-nav-pill img {
        width: 36px;
        height: 36px;
    }

    .wiki-entries-content {
        padding: 10px;

        border-width: 2px;
        border-radius: 13px;
    }

    .wiki-entry-content-title {
        font-size: 20px;
    }

    .wiki-location-grid {
        gap: 6px;
    }

    .wiki-location-pill {
        width: calc(50% - 4px);
        height: 100px;
    }

    .wiki-location-pill img {
        width: 48px;
        height: 48px;
    }

    .wiki-fish-grid,
    .wiki-standard-entry-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));

        gap: 6px;
    }

    .wiki-fish-card,
    .wiki-standard-entry-card {
        min-height: 112px;

        padding: 6px;
    }

    .wiki-fish-card-image,
    .wiki-standard-entry-card img {
        width: 44px;
        height: 44px;
    }

    .wiki-fish-card-name,
    .wiki-standard-entry-name {
        font-size: 12px;
    }

    .wiki-fish-card-rarity,
    .wiki-standard-entry-rarity {
        font-size: 9px;
    }

    .wiki-fish-card-chance,
    .wiki-standard-card-extra {
        font-size: 9px;
    }

    .wiki-entry-detail-image {
        width: 65px;
        height: 65px;
    }

    .wiki-entry-detail-name {
        font-size: 18px;
    }

    .wiki-entry-stat-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .wiki-tool-base-cost {
        grid-template-columns: minmax(130px, 160px);
    }

    .wiki-entry-description {
        font-size: 12px;
    }

}

/* =========================================================
   FISH ISLAND ENTRIES
   FULL CSS
   ========================================================= */


/* =========================================================
   MAIN APP
   ========================================================= */

#fish-entries-app {
    width: 100%;
    max-width: 1075px;

    margin: 0 auto;

    box-sizing: border-box;
}

#fish-entries-app * {
    box-sizing: border-box;
}


/* =========================================================
   LOADING / ERROR
   ========================================================= */

.entries-app-loading,
.entries-app-error {
    width: 100%;
    min-height: 180px;

    display: flex;
    align-items: center;
    justify-content: center;

    padding: 20px;

    background: #07122b;

    border: 4px solid #222831;
    border-radius: 24px;

    color: #ffffff;

    font-size: 20px;
    font-weight: bold;

    text-align: center;
}

.entries-app-error {
    color: #ff7b8c;
}


/* =========================================================
   MAIN SHELL
   ========================================================= */

#fish-entries-app .wiki-entries-shell {
    position: relative;

    width: 100%;
    max-width: 1075px;

    min-height: 500px;

    padding: 24px;

    background: #07122b;

    border: 4px solid #222831;
    border-radius: 24px;

    box-sizing: border-box;

    overflow: visible;
}


/* =========================================================
   START SCREEN
   ========================================================= */

#fish-entries-app .wiki-entries-start {
    display: block;
}

#fish-entries-app .wiki-entries-start .wiki-entries-nav {
    width: 100%;
    min-height: 444px;

    display: flex;

    flex-direction: row;
    flex-wrap: nowrap;

    align-items: center;
    justify-content: center;

    gap: 28px;
}


/* =========================================================
   MAIN CATEGORY BUTTONS
   ========================================================= */

#fish-entries-app .wiki-entry-nav-pill {
    width: 300px;
    height: 280px;

    flex: 0 1 300px;

    display: flex;

    flex-direction: column;

    align-items: center;
    justify-content: center;

    gap: 10px;

    padding: 14px;

    background: #0b0f17;

    border: 4px solid #222831;
    border-radius: 26px;

    color: #4f8cff;

    font-family: inherit;

    font-size: 38px;
    font-weight: bold;

    line-height: 1;

    text-align: center;

    cursor: pointer;

    transition:
        background 0.15s ease,
        border-color 0.15s ease,
        transform 0.15s ease;

    overflow: hidden;
}

#fish-entries-app .wiki-entry-nav-pill:hover {
    background: #10275a;

    border-color: #5aaeff;

    transform: translateY(-2px);
}

#fish-entries-app .wiki-entry-nav-pill.entry-active {
    background: #10275a;

    border-color: #5aaeff;
}

#fish-entries-app .wiki-entry-nav-pill img {
    display: block;

    max-width: 185px;
    max-height: 185px;

    width: auto;
    height: auto;

    margin: 0 auto;
}

#fish-entries-app .wiki-entry-nav-pill span {
    display: block;

    color: #4f8cff;

    font-size: 38px;
    font-weight: bold;

    line-height: 1;

    white-space: nowrap;
}


/* =========================================================
   OPEN LIBRARY LAYOUT
   ========================================================= */

#fish-entries-app .wiki-entries-open {
    display: grid;

    grid-template-columns:
        180px minmax(0, 1fr);

    gap: 24px;

    align-items: stretch;
}

#fish-entries-app .wiki-entries-open .wiki-entries-nav {
    width: 180px;

    display: flex;

    flex-direction: column;

    align-items: center;
    justify-content: flex-start;

    gap: 18px;

    padding: 0;

    min-height: 430px;
}

#fish-entries-app
.wiki-entries-open
.wiki-entry-nav-pill {
    width: 170px;
    height: 135px;

    min-height: 135px;

    flex: 0 0 135px;

    padding: 10px;

    border-radius: 24px;

    font-size: 22px;
}

#fish-entries-app
.wiki-entries-open
.wiki-entry-nav-pill img {
    max-width: 76px;
    max-height: 76px;
}

#fish-entries-app
.wiki-entries-open
.wiki-entry-nav-pill span {
    font-size: 22px;
}


/* =========================================================
   CONTENT BOX
   ========================================================= */

#fish-entries-app .wiki-entries-content {
    position: relative;

    width: 100%;
    min-width: 0;

    min-height: 430px;

    padding: 24px;

    background: #0b0f17;

    border: 4px solid #222831;
    border-radius: 24px;

    box-sizing: border-box;

    overflow: hidden;
}


/* =========================================================
   PAGE TITLE
   ========================================================= */

#fish-entries-app .wiki-entry-content-title {
    margin: 0 0 20px 0;

    color: #4f8cff;

    font-size: 42px;
    font-weight: bold;

    line-height: 1.1;
}


/* =========================================================
   ITEMS SUBTABS
   ========================================================= */

#fish-entries-app .wiki-entry-subtabs {
    display: flex;

    flex-wrap: wrap;

    gap: 12px;

    margin-bottom: 20px;
}

#fish-entries-app .wiki-entry-subtab {
    padding: 8px 18px;

    background: #0b0f17;

    border: 3px solid #222831;
    border-radius: 999px;

    color: #4f8cff;

    font-family: inherit;

    font-size: 22px;
    font-weight: bold;

    cursor: pointer;

    transition:
        background 0.15s ease,
        border-color 0.15s ease;
}

#fish-entries-app .wiki-entry-subtab:hover {
    background: #10275a;

    border-color: #5aaeff;
}

#fish-entries-app
.wiki-entry-subtab.entry-active {
    background: #17346b;

    border-color: #5aaeff;
}


/* =========================================================
   LOCATION SECTION
   ========================================================= */

#fish-entries-app .wiki-location-label {
    margin-bottom: 18px;

    color: #7eb5ff;

    font-size: 25px;
    font-weight: bold;
}


/* =========================================================
   LOCATION GRID
   ========================================================= */

#fish-entries-app .wiki-location-grid {
    display: grid;

    grid-template-columns:
        repeat(3, minmax(0, 1fr));

    gap: 14px;
}


/* =========================================================
   LOCATION BUTTON
   ========================================================= */

#fish-entries-app .wiki-location-pill {
    min-height: 165px;

    display: flex;

    flex-direction: column;

    align-items: center;
    justify-content: center;

    gap: 8px;

    padding: 12px;

    background: #07122b;

    border: 3px solid #263a63;
    border-radius: 18px;

    color: #ffffff;

    font-family: inherit;

    cursor: pointer;

    transition:
        background 0.15s ease,
        border-color 0.15s ease,
        transform 0.15s ease;
}

#fish-entries-app .wiki-location-pill:hover {
    background: #10275a;

    border-color: #5aaeff;

    transform: translateY(-2px);
}

#fish-entries-app .wiki-location-pill img {
    display: block;

    max-width: 105px;
    max-height: 105px;

    width: auto;
    height: auto;

    margin: 0 auto;
}

#fish-entries-app .wiki-location-name {
    color: #4f8cff;

    font-size: 18px;
    font-weight: bold;

    line-height: 1.1;

    text-align: center;

    overflow-wrap: anywhere;
}


/* =========================================================
   LOCATION HEADER
   ========================================================= */

#fish-entries-app .wiki-location-header {
    display: flex;

    align-items: center;
    justify-content: space-between;

    gap: 16px;

    margin-bottom: 20px;
}

#fish-entries-app .wiki-location-header-title {
    display: flex;

    align-items: center;

    gap: 12px;

    min-width: 0;

    color: #4f8cff;

    font-size: 30px;
    font-weight: bold;

    line-height: 1;
}

#fish-entries-app
.wiki-location-header-title img {
    display: block;

    max-width: 58px;
    max-height: 58px;

    width: auto;
    height: auto;
}

#fish-entries-app
.wiki-location-header-title span {
    overflow-wrap: anywhere;
}


/* =========================================================
   BACK BUTTON
   ========================================================= */

#fish-entries-app .wiki-entry-back {
    display: inline-flex;

    align-items: center;
    justify-content: center;

    padding: 8px 15px;

    background: #10275a;

    border: 2px solid #5aaeff;
    border-radius: 12px;

    color: #ffffff;

    font-family: inherit;

    font-size: 15px;
    font-weight: bold;

    cursor: pointer;

    transition:
        background 0.15s ease,
        transform 0.15s ease;
}

#fish-entries-app .wiki-entry-back:hover {
    background: #1f4388;

    transform: translateY(-1px);
}


/* =========================================================
   FISH GRID
   ========================================================= */

#fish-entries-app .wiki-fish-grid {
    display: flex;

    flex-wrap: wrap;

    justify-content: center;

    align-content: flex-start;

    gap: 12px;
}


/* =========================================================
   FISH CARD
   ========================================================= */

#fish-entries-app .wiki-fish-card {
    position: relative;

    width: 140px;
    min-height: 180px;

    display: flex;

    flex-direction: column;

    align-items: center;
    justify-content: flex-start;

    padding: 10px;

    background: #07122b;

    border: 3px solid #263a63;
    border-radius: 18px;

    color: #ffffff;

    font-family: inherit;

    text-align: center;

    cursor: pointer;

    overflow: hidden;

    transition:
        background 0.15s ease,
        border-color 0.15s ease,
        transform 0.15s ease;
}

#fish-entries-app .wiki-fish-card:hover {
    background: #10275a;

    border-color: #5aaeff;

    transform: translateY(-2px);
}


/* =========================================================
   FISH IMAGE
   ========================================================= */

#fish-entries-app .wiki-fish-card-image {
    display: block;

    max-width: 105px;
    max-height: 105px;

    width: auto;
    height: auto;

    margin: 0 auto 6px;
}


/* =========================================================
   FISH NAME
   ========================================================= */

#fish-entries-app .wiki-fish-card-name {
    width: 100%;

    margin-top: auto;

    font-size: 16px;
    font-weight: bold;

    line-height: 1.1;

    overflow-wrap: anywhere;
}


/* =========================================================
   FISH RARITY
   ========================================================= */

#fish-entries-app .wiki-fish-card-rarity {
    width: 100%;

    margin-top: 5px;

    font-size: 13px;
    font-weight: bold;

    line-height: 1;
}


/* =========================================================
   FISH CHANCE
   ========================================================= */

#fish-entries-app .wiki-fish-card-chance {
    width: 100%;

    margin-top: 7px;

    padding-top: 6px;

    border-top: 1px solid #263a63;

    color: #8fc5ff;

    font-size: 14px;
    font-weight: bold;

    line-height: 1;
}


/* =========================================================
   STANDARD ENTRY GRID
   BAITS / TOOLS / ENCHANTS
   ========================================================= */

#fish-entries-app .wiki-standard-entry-grid {
    display: flex;

    flex-wrap: wrap;

    justify-content: center;

    align-content: flex-start;

    gap: 12px;
}


/* =========================================================
   STANDARD CARD
   ========================================================= */

#fish-entries-app .wiki-standard-entry-card {
    position: relative;

    width: 145px;
    min-height: 170px;

    display: flex;

    flex-direction: column;

    align-items: center;
    justify-content: flex-start;

    padding: 11px;

    background: #07122b;

    border: 3px solid #263a63;
    border-radius: 18px;

    color: #ffffff;

    font-family: inherit;

    text-align: center;

    cursor: pointer;

    overflow: hidden;

    transition:
        background 0.15s ease,
        border-color 0.15s ease,
        transform 0.15s ease;
}

#fish-entries-app
.wiki-standard-entry-card:hover {
    background: #10275a;

    border-color: #5aaeff;

    transform: translateY(-2px);
}

#fish-entries-app
.wiki-standard-entry-card img {
    display: block;

    max-width: 105px;
    max-height: 105px;

    width: auto;
    height: auto;

    margin: 0 auto 7px;
}


/* =========================================================
   STANDARD CARD NAME
   ========================================================= */

#fish-entries-app .wiki-standard-entry-name {
    width: 100%;

    margin-top: auto;

    color: #4f8cff;

    font-size: 16px;
    font-weight: bold;

    line-height: 1.1;

    overflow-wrap: anywhere;
}


/* =========================================================
   STANDARD RARITY
   ========================================================= */

#fish-entries-app .wiki-standard-entry-rarity {
    width: 100%;

    margin-top: 5px;

    font-size: 13px;
    font-weight: bold;
}


/* =========================================================
   STANDARD CARD EXTRA
   ENCHANT CHANCE
   ========================================================= */

#fish-entries-app .wiki-standard-card-extra {
    width: 100%;

    margin-top: 7px;

    padding-top: 6px;

    border-top: 1px solid #263a63;

    color: #bba3ff;

    font-size: 14px;
    font-weight: bold;
}


/* =========================================================
   DETAIL PAGE
   ========================================================= */

#fish-entries-app .wiki-entry-detail {
    position: relative;

    width: 100%;

    min-height: 320px;

    padding: 4px;

    color: #ffffff;
}


/* =========================================================
   DETAIL BACK ROW
   ========================================================= */

#fish-entries-app .wiki-detail-back-row {
    width: 100%;

    display: flex;

    justify-content: flex-end;

    margin-bottom: 8px;
}


/* =========================================================
   DETAIL IMAGE
   ========================================================= */

#fish-entries-app
.wiki-entry-detail
> .wiki-entry-detail-image {
    display: block;

    max-width: 150px;
    max-height: 150px;

    width: auto;
    height: auto;

    margin: 0 auto 12px;
}


/* =========================================================
   DETAIL NAME
   ========================================================= */

#fish-entries-app .wiki-entry-detail-name {
    width: 100%;

    color: #4f8cff;

    font-size: 40px;
    font-weight: bold;

    line-height: 1.05;

    text-align: center;

    overflow-wrap: anywhere;
}


/* =========================================================
   DETAIL RARITY
   ========================================================= */

#fish-entries-app .wiki-entry-detail-rarity {
    margin-top: 8px;

    font-size: 18px;
    font-weight: bold;

    text-align: center;
}


/* =========================================================
   DESCRIPTION
   ========================================================= */

#fish-entries-app .wiki-entry-description {
    width: 100%;

    margin-top: 20px;

    padding: 16px;

    background: rgba(
        7,
        18,
        43,
        0.55
    );

    border: 1px solid #263a63;
    border-radius: 14px;

    color: #ffffff;

    font-size: 17px;
    line-height: 1.45;

    white-space: pre-wrap;

    overflow-wrap: anywhere;
}


/* =========================================================
   STAT GRID
   ========================================================= */

#fish-entries-app .wiki-entry-stat-grid {
    width: 100%;

    display: grid;

    grid-template-columns:
        repeat(
            2,
            minmax(0, 1fr)
        );

    gap: 12px;

    margin-top: 20px;
}


/* =========================================================
   STAT
   ========================================================= */

#fish-entries-app .wiki-entry-stat {
    min-width: 0;

    padding: 14px 16px;

    background: #07122b;

    border: 2px solid #263a63;
    border-radius: 14px;
}


/* Tool Base Cost can appear outside a stat grid */

#fish-entries-app
.wiki-entry-detail
> .wiki-entry-stat {
    margin-top: 18px;
}


/* =========================================================
   STAT LABEL
   ========================================================= */

#fish-entries-app .wiki-entry-stat-label {
    margin-bottom: 6px;

    color: #7eb5ff;

    font-size: 13px;
    font-weight: bold;

    letter-spacing: 0.06em;

    line-height: 1;

    text-transform: uppercase;
}


/* =========================================================
   STAT VALUE
   ========================================================= */

#fish-entries-app .wiki-entry-stat-value {
    color: #ffffff;

    font-size: 19px;
    font-weight: bold;

    line-height: 1.25;

    overflow-wrap: anywhere;
}


/* =========================================================
   EMPTY MESSAGE
   ========================================================= */

#fish-entries-app .wiki-entry-empty {
    width: 100%;

    padding: 30px 18px;

    color: #91a4c1;

    font-size: 18px;
    font-weight: bold;

    text-align: center;
}


/* =========================================================
   SETTINGS MENU BUTTON
   IMPORTANT:
   ABSOLUTE POSITION KEEPS IT OUT OF CATEGORY NAV
   ========================================================= */

#fish-entries-app .wiki-entries-menu-button {
    position: absolute !important;

    top: 12px !important;
    left: 12px !important;

    z-index: 2001 !important;

    width: 42px !important;
    min-width: 42px !important;
    max-width: 42px !important;

    height: 42px !important;
    min-height: 42px !important;
    max-height: 42px !important;

    flex: none !important;

    display: flex !important;

    align-items: center !important;
    justify-content: center !important;

    margin: 0 !important;
    padding: 0 !important;

    background: #0b0f17 !important;

    border: 2px solid #5aaeff !important;
    border-radius: 12px !important;

    color: #ffffff !important;

    font-family: inherit !important;

    font-size: 22px !important;
    font-weight: bold !important;

    line-height: 1 !important;

    cursor: pointer !important;

    transform: none !important;

    box-sizing: border-box !important;
}

#fish-entries-app
.wiki-entries-menu-button:hover {
    background: #10275a !important;

    border-color: #7ec2ff !important;
}


/* =========================================================
   SETTINGS POPUP
   ========================================================= */

#fish-entries-app .wiki-entries-settings-menu {
    display: none;

    position: absolute !important;

    top: 62px !important;
    left: 12px !important;

    z-index: 2000 !important;

    width: 280px !important;
    max-width:
        calc(
            100% - 24px
        ) !important;

    padding: 16px !important;

    background:
        rgba(
            7,
            18,
            43,
            0.98
        ) !important;

    border:
        2px solid
        #5aaeff !important;

    border-radius:
        16px !important;

    box-shadow:
        0 10px 30px
        rgba(
            0,
            0,
            0,
            0.45
        ) !important;

    box-sizing:
        border-box !important;
}

#fish-entries-app
.wiki-entries-settings-menu.menu-open {
    display: block !important;
}


/* =========================================================
   SETTINGS TITLE
   ========================================================= */

#fish-entries-app .wiki-entries-settings-title {
    margin-bottom: 16px;

    color: #ffffff;

    font-size: 22px;
    font-weight: bold;

    text-align: center;
}


/* =========================================================
   SETTINGS LABEL
   ========================================================= */

#fish-entries-app .wiki-entries-settings-label {
    margin-bottom: 9px;

    color: #7eb5ff;

    font-size: 13px;
    font-weight: bold;

    letter-spacing: 0.04em;

    text-transform: uppercase;
}


/* =========================================================
   CHANCE DISPLAY OPTIONS
   ========================================================= */

#fish-entries-app .wiki-chance-display-options {
    display: flex;

    flex-direction: column;

    gap: 8px;
}


/* =========================================================
   CHANCE OPTION
   ========================================================= */

#fish-entries-app .wiki-chance-display-option {
    width: 100%;

    padding: 11px 14px;

    display: flex;

    align-items: center;

    background: #0b0f17;

    border: 2px solid #222831;
    border-radius: 10px;

    color: #ffffff;

    font-family: inherit;

    font-size: 16px;
    font-weight: bold;

    text-align: left;

    cursor: pointer;

    transition:
        background 0.15s ease,
        border-color 0.15s ease;
}

#fish-entries-app
.wiki-chance-display-option:hover {
    background: #10275a;

    border-color: #5aaeff;
}

#fish-entries-app
