    margin-bottom: 18px;
    background: #0b0f17;
    border: 3px solid #222831;
    border-radius: 18px;
}

#fish-entries-app .wiki-entries-menu-button {
    width: 40px;
    min-width: 40px;
    height: 40px;
    min-height: 40px;
    flex: 0 0 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0;
    margin: 0;
    background: #0b0f17;
    border: 2px solid #5aaeff;
    border-radius: 11px;
    color: #ffffff;
    font-family: inherit;
    font-size: 21px;
    font-weight: bold;
    line-height: 1;
    cursor: pointer;
    transition:
        background 0.15s ease,
        border-color 0.15s ease,
        transform 0.15s ease;
}

#fish-entries-app .wiki-entries-menu-button:hover {
    background: #10275a;
    border-color: #7ec2ff;
