@property --rarity-border-angle {
    syntax: '<angle>';
    initial-value: 0deg;
    inherits: false;
}

@keyframes wiki-rarity-border-spin {
    from {
        --rarity-border-angle: 0deg;
    }

    to {
        --rarity-border-angle: 360deg;
    }
}

#fish-entries-app {
    width: 100%;
    max-width: 1075px;
    margin: 0 auto;
    box-sizing: border-box;
}

#fish-entries-app * {
    box-sizing: border-box;
}

.entries-app-loading,
.entries-app-error {
    width: 100%;
    min-height: 180px;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px;
    background: #07122b;
    border: 4px solid #222831;
    border-radius: 24px;
    color: #ffffff;
    font-size: 20px;
    font-weight: bold;
    text-align: center;
}

.entries-app-error {
    color: #ff7b8c;
}

#fish-entries-app .wiki-entries-shell {
    position: relative;
    width: 100%;
    max-width: 1075px;
    height: 630px;
    min-height: 630px;
    padding: 18px;
    background: #07122b;
    border: 4px solid #222831;
    border-radius: 24px;
    overflow: hidden;
}

#fish-entries-app .wiki-entries-topbar {
    position: relative;
    width: 100%;
    min-height: 58px;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 12px;
    padding: 8px 10px;
    margin-bottom: 18px;
    background: #0b0f17;
    border: 3px solid #222831;
    border-radius: 18px;
}

#fish-entries-app .wiki-entries-menu-button {
    width: 40px;
    min-width: 40px;
    height: 40px;
    min-height: 40px;
    flex: 0 0 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0;
    margin: 0;
    background: #0b0f17;
    border: 2px solid #5aaeff;
    border-radius: 11px;
    color: #ffffff;
    font-family: inherit;
    font-size: 21px;
    font-weight: bold;
    line-height: 1;
    cursor: pointer;
    transition:
        background 0.15s ease,
        border-color 0.15s ease,
        transform 0.15s ease;
}

#fish-entries-app .wiki-entries-menu-button:hover {
    background: #10275a;
    border-color: #7ec2ff;
    transform: translateY(-1px);
}

#fish-entries-app .wiki-entries-display-status {
    min-height: 40px;
    display: flex;
    align-items: center;
    color: #7eb5ff;
    font-size: 15px;
    font-weight: bold;
    line-height: 1;
    white-space: nowrap;
}

#fish-entries-app .wiki-entries-settings-menu {
    display: none;
    flex: 0 0 100%;
    width: 100%;
    padding: 14px;
    margin-top: 2px;
    background: #07122b;
    border: 2px solid #5aaeff;
    border-radius: 14px;
}

#fish-entries-app .wiki-entries-settings-menu.menu-open {
    display: block;
}

#fish-entries-app .wiki-entries-settings-title {
    margin-bottom: 13px;
    color: #ffffff;
    font-size: 20px;
    font-weight: bold;
}

#fish-entries-app .wiki-entries-settings-label {
    margin-bottom: 8px;
    color: #7eb5ff;
    font-size: 13px;
    font-weight: bold;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

#fish-entries-app .wiki-chance-display-options {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

#fish-entries-app .wiki-chance-display-option {
    min-width: 150px;
    display: flex;
    align-items: center;
    padding: 10px 13px;
    background: #0b0f17;
