#fish-entries-app
.wiki-entries-start
.wiki-entries-nav {
    width: 100%;
    height: calc(100% - 76px);
    min-height: 0;
    display: flex;
    flex-direction: row;
    flex-wrap: nowrap;
    align-items: center;
    justify-content: center;
    gap: 28px;
}

#fish-entries-app .wiki-entry-nav-pill {
    width: 300px;
