        conic-gradient(
            from var(--rarity-border-angle),
            var(--rarity-color-50) 0deg,
            var(--rarity-color-100) 70deg,
            var(--rarity-color-50) 140deg,
            var(--rarity-color-100) 210deg,
            var(--rarity-color-50) 280deg,
            var(--rarity-color-100) 360deg
        ) border-box;
    box-shadow:
        0 0 4px
        var(--rarity-color-50);
    animation:
        wiki-rarity-border-spin
        5.5s
        linear
        infinite;
}

#fish-entries-app
.wiki-fish-card.wiki-dynamic-rarity-border:hover,
#fish-entries-app
.wiki-standard-entry-card.wiki-dynamic-rarity-border:hover {
