#fish-entries-app {
    width: 750px;
    max-width: 100%;
    margin: 0 auto;
    box-sizing: border-box;
}

#fish-entries-app button {
    font-family: inherit;
}

.entries-app-loading,
.entries-app-error {
    width: 100%;
    padding: 18px;

    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 12px;

    color: #ffffff;

    text-align: center;

    box-sizing: border-box;
}

.entries-app-error {
    color: #ff7777;
}

.wiki-entries-shell {
    width: 750px;
    max-width: 100%;
    height: 400px;

    padding: 14px;

    background: #07142e;
    border: 4px solid #252c34;
    border-radius: 24px;

    color: #ffffff;

    overflow: hidden;

    box-sizing: border-box;
}

.wiki-entries-start {
    display: block;
}

.wiki-entries-start .wiki-entries-nav {
    width: 100%;
    height: 100%;

    display: grid;
    grid-template-columns: repeat(3, 1fr);

    gap: 18px;

    align-items: center;
}

.wiki-entries-start .wiki-entry-nav-pill {
    width: 100%;
    height: 220px;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    gap: 12px;

    padding: 16px;

    background: #0b1017;
    border: 3px solid #252c34;
    border-radius: 18px;

    color: #ffffff;

    font-size: 27px;
    font-weight: bold;

    cursor: pointer;

    box-sizing: border-box;

    transition:
        background 0.15s ease,
        border-color 0.15s ease,
        transform 0.15s ease;
}

.wiki-entries-start .wiki-entry-nav-pill:hover {
    background: #101b2b;
    border-color: #58aaff;

    transform: translateY(-2px);
}

.wiki-entries-start .wiki-entry-nav-pill img {
    width: 110px;
    height: 110px;

    object-fit: contain;

    pointer-events: none;
}

.wiki-entries-start .wiki-entry-nav-pill span {
    pointer-events: none;
}

.wiki-entries-open {
    display: grid;
    grid-template-columns: 150px minmax(0, 1fr);

    gap: 14px;
}

.wiki-entries-open .wiki-entries-nav {
    width: 150px;
    height: 100%;

    display: flex;
    flex-direction: column;

    gap: 9px;
}

.wiki-entries-open .wiki-entry-nav-pill {
    width: 100%;

    flex: 1;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    gap: 5px;

    min-height: 0;

    padding: 7px;

    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 13px;

    color: #ffffff;

    font-size: 16px;
    font-weight: bold;

    cursor: pointer;

    box-sizing: border-box;

    transition:
        background 0.15s ease,
        border-color 0.15s ease;
}

.wiki-entries-open .wiki-entry-nav-pill:hover {
    background: #101b2b;
    border-color: #58aaff;
}

.wiki-entries-open .wiki-entry-nav-pill.entry-active {
    background: #18366f;
    border-color: #58aaff;
}

.wiki-entries-open .wiki-entry-nav-pill img {
    width: 62px;
    height: 62px;

    object-fit: contain;

    pointer-events: none;
}

.wiki-entries-open .wiki-entry-nav-pill span {
    pointer-events: none;
}

.wiki-entries-content {
    min-width: 0;
    height: 100%;

    padding: 15px 16px;

    background: #080c12;
    border: 3px solid #252c34;
    border-radius: 18px;

    overflow-y: auto;
    overflow-x: hidden;

    box-sizing: border-box;
}

.wiki-entries-content::-webkit-scrollbar {
    width: 7px;
}

.wiki-entries-content::-webkit-scrollbar-track {
    background: transparent;
}

.wiki-entries-content::-webkit-scrollbar-thumb {
    background: #354052;
    border-radius: 999px;
}

.wiki-entry-content-title {
    margin-bottom: 10px;

    color: #ffffff;

    font-size: 25px;
    font-weight: bold;
    line-height: 1.1;
}

.wiki-entry-subtabs {
    display: flex;
    flex-wrap: wrap;

    gap: 7px;

    margin-bottom: 11px;
}

.wiki-entry-subtab,
.wiki-entry-back {
    padding: 6px 12px;

    background: #101722;
    border: 2px solid #303a48;
    border-radius: 999px;

    color: #ffffff;

    font-size: 13px;
    font-weight: bold;

    cursor: pointer;

    box-sizing: border-box;

    transition:
        background 0.15s ease,
        border-color 0.15s ease;
}

.wiki-entry-subtab:hover,
.wiki-entry-back:hover {
    background: #17243a;
    border-color: #58aaff;
}

.wiki-entry-subtab.entry-active {
    background: #18366f;
    border-color: #58aaff;
}

.wiki-entry-items-body {
    width: 100%;
    min-width: 0;
}

.wiki-location-grid {
    width: 100%;

    display: flex;
    flex-wrap: wrap;
    justify-content: center;

    gap: 9px;

    box-sizing: border-box;
}

.wiki-location-pill {
    width: 125px;
    height: 112px;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    gap: 5px;

    padding: 8px;

    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 12px;

    color: #ffffff;

    cursor: pointer;

    box-sizing: border-box;

    transition:
        background 0.15s ease,
        border-color 0.15s ease,
        transform 0.15s ease;
}

.wiki-location-pill:hover {
    background: #101722;
    border-color: #58aaff;

    transform: translateY(-1px);
}

.wiki-location-pill img {
    width: 58px;
    height: 58px;

    object-fit: contain;

    pointer-events: none;
}

.wiki-location-name {
    width: 100%;

    color: #ffffff;

    font-size: 13px;
    font-weight: bold;
    line-height: 1.15;

    text-align: center;

    overflow: hidden;
    text-overflow: ellipsis;

    pointer-events: none;
}

.wiki-location-header {
    width: 100%;

    display: flex;
    align-items: center;
    justify-content: space-between;

    gap: 10px;

    margin-bottom: 10px;
}

.wiki-location-header-title {
    min-width: 0;

    display: flex;
