    border-color: #58aaff;

    transform: translateY(-1px);
}

.wiki-location-pill img {
    width: 58px;
    height: 58px;

    object-fit: contain;

    pointer-events: none;
}

.wiki-location-name {
    width: 100%;

    color: #ffffff;

    font-size: 13px;
    font-weight: bold;
    line-height: 1.15;

    text-align: center;

    overflow: hidden;
    text-overflow: ellipsis;

    pointer-events: none;
}

.wiki-location-header {
    width: 100%;

    display: flex;
    align-items: center;
    justify-content: space-between;

    gap: 10px;

    margin-bottom: 10px;
}

.wiki-location-header-title {
    min-width: 0;

    display: flex;
    align-items: center;

    gap: 7px;

    color: #ffffff;

    font-size: 18px;
    font-weight: bold;
}

.wiki-location-header-title img {
    width: 38px;
    height: 38px;

    object-fit: contain;
}

.wiki-location-header-title span {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.wiki-fish-grid,
.wiki-standard-entry-grid {
    width: 100%;

    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));

    gap: 9px;

    box-sizing: border-box;
}

.wiki-fish-card,
.wiki-standard-entry-card {
    position: relative;

    min-width: 0;
    min-height: 125px;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    gap: 3px;

    padding: 8px;

    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 12px;

    color: #ffffff;

    cursor: pointer;

    box-sizing: border-box;

    overflow: hidden;

    transition:
        transform 0.15s ease,
        background 0.15s ease,
        border-color 0.15s ease;
}

.wiki-fish-card:hover,
.wiki-standard-entry-card:hover {
    background: #101722;
    border-color: #58aaff;

    transform: translateY(-1px);
}

.wiki-fish-card-image,
.wiki-standard-entry-card img {
    width: 52px;
    height: 52px;

    object-fit: contain;

    flex: 0 0 auto;

    pointer-events: none;
}

.wiki-fish-card-name,
.wiki-standard-entry-name {
    max-width: 100%;

    color: #ffffff;

    font-size: 14px;
    font-weight: bold;
    line-height: 1.15;

    text-align: center;

    overflow-wrap: anywhere;

    pointer-events: none;
}

.wiki-fish-card-rarity,
.wiki-standard-entry-rarity,
.wiki-entry-detail-rarity {
    max-width: 100%;

    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: center;

    gap: 1px;

    font-size: 11px;
    font-weight: bold;
    line-height: 1.15;

    text-align: center;
}

.wiki-rarity-stars-inline {
    margin-left: 0;

    letter-spacing: 1px;
}

.wiki-fish-card-chance,
.wiki-standard-card-extra {
    color: #aab7c7;

    font-size: 11px;
    font-weight: bold;
    line-height: 1.15;

    text-align: center;

    pointer-events: none;
}

.wiki-entry-detail {
    width: 100%;

    display: flex;
    flex-direction: column;
    align-items: center;

    box-sizing: border-box;
}

.wiki-detail-back-row {
    width: 100%;

    display: flex;
    justify-content: flex-start;

    margin-bottom: 7px;
}

.wiki-entry-detail-image {
    width: 80px;
    height: 80px;

    margin-bottom: 5px;

    object-fit: contain;
}

.wiki-entry-detail-name {
    max-width: 100%;

    color: #ffffff;

    font-size: 21px;
    font-weight: bold;
    line-height: 1.15;

    text-align: center;

    overflow-wrap: anywhere;
}

.wiki-entry-detail-rarity {
    margin-top: 2px;

    font-size: 13px;
}

.wiki-entry-detail-rarity .wiki-rarity-stars-inline {
    font-size: 14px;
}

.wiki-entry-stat-grid {
    width: 100%;

    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));

    gap: 7px;

    margin-top: 11px;

    box-sizing: border-box;
}

.wiki-entry-stat {
    min-width: 0;

    padding: 7px 5px;

    background: #0b1017;
    border: 1px solid #252c34;
    border-radius: 9px;

    box-sizing: border-box;

    text-align: center;
}

.wiki-entry-stat-label {
    margin-bottom: 2px;

    color: #8391a4;

    font-size: 10px;
    font-weight: bold;

    text-transform: uppercase;
}

.wiki-entry-stat-value {
    color: #ffffff;

    font-size: 13px;
    font-weight: bold;

    overflow-wrap: anywhere;
}

.wiki-entry-description {
    width: 100%;

    margin-top: 11px;
    padding: 10px 11px;

    background: #0b1017;
    border: 1px solid #252c34;
    border-radius: 10px;

    color: #d8dee8;

    font-size: 13px;
    line-height: 1.45;

    white-space: pre-line;
    overflow-wrap: anywhere;

    box-sizing: border-box;
}

.wiki-lore-blue {
    color: #58aaff;
}

.wiki-entry-empty {
    width: 100%;

    padding: 20px 10px;

    color: #8997aa;

    font-size: 13px;

    text-align: center;

    box-sizing: border-box;
}

.wiki-fish-card.wiki-rarity-animated-border {
    position: relative;

    overflow: hidden;

    border: 2px solid transparent;

    background: transparent;
}

.wiki-fish-card.wiki-rarity-animated-border::before {
    content: "";

    position: absolute;

    width: 300%;
    height: 300%;

    left: -100%;
    top: -100%;

    background:
        conic-gradient(
            from 45deg,
            var(--rarity-border-color-0) 0deg,
            var(--rarity-border-color-50) 90deg,
            var(--rarity-border-color-0) 180deg,
            var(--rarity-border-color-50) 270deg,
            var(--rarity-border-color-0) 360deg
        );

    animation:
        wiki-rarity-border-spin
        6s
        linear
        infinite;

    z-index: 0;

    pointer-events: none;
}

.wiki-fish-card.wiki-rarity-animated-border::after {
    content: "";

    position: absolute;

    top: 2px;
    right: 2px;
    bottom: 2px;
    left: 2px;

    background: #0b1017;

    border-radius: 10px;

    z-index: 1;

    pointer-events: none;

    transition:
        background 0.15s ease;
}

.wiki-fish-card.wiki-rarity-animated-border > * {
    position: relative;

    z-index: 2;
}

.wiki-fish-card.wiki-rarity-animated-border:hover::after {
    background: #101722;
}

@keyframes wiki-rarity-border-spin {

    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }

}

