.wiki-entries-frame {
    width: 750px;
    max-width: 100%;

    margin: 0 auto;

    background: #07142e;

    border: 4px solid #252c34;
    border-radius: 24px;

    overflow: hidden;

    box-sizing: border-box;
}

.wiki-entries-menu-bar {

    width: 100%;
    height: 36px;

    display: flex;
    align-items: center;

    gap: 8px;

    padding: 3px 7px;

    background: #07142e;

    border-bottom: 2px solid #252c34;

    box-sizing: border-box;
}

.wiki-entries-menu-button {
    width: 30px;
    height: 26px;

    display: flex;
    flex-direction: column;
    justify-content: center;

    gap: 4px;

    padding: 4px;

    background: transparent;
    border: none;

    cursor: pointer;
}

.wiki-entries-menu-button span {
    width: 22px;
    height: 3px;

    display: block;

    background: #ffffff;
    border-radius: 3px;
}

.wiki-entries-menu-button:hover span {
    background: #58aaff;
}

.wiki-entries-frame .wiki-entries-shell {
    width: 100%;

    margin: 0;

    border: none;
    border-radius: 0;

    box-sizing: border-box;
}

.wiki-entries-frame {
    position: relative;
}

.wiki-entries-side-menu {
    position: absolute;

    top: 36px;
    left: 0;
    bottom: 0;

    width: 250px;

    padding: 16px;

    background: #0b1017;
    border-right: 3px solid #252c34;

    box-sizing: border-box;

    z-index: 20;

    overflow-y: auto;

    transform: translateX(-100%);

    transition:
        transform 0.25s ease;
}

.wiki-entries-side-menu.wiki-side-menu-open {
    transform: translateX(0);
}

.wiki-side-menu-setting {
    width: 100%;

    padding-bottom: 15px;
    margin-bottom: 15px;

    border-bottom: 1px solid #252c34;

    box-sizing: border-box;
}

.wiki-side-menu-label {
    margin-bottom: 9px;

    color: #ffffff;

    font-size: 15px;
    font-weight: bold;
}

.wiki-fish-luck-setting {
    display: flex;
    flex-direction: column;

    gap: 13px;
}

.wiki-setting-field {
    width: 100%;

    display: flex;
    flex-direction: column;

    gap: 5px;

    color: #d8dee8;

    font-size: 12px;
    font-weight: bold;
}

.wiki-setting-select {
    width: 100%;

    padding: 7px 9px;

    background: #101722;

    border: 2px solid #303a48;
    border-radius: 8px;

    color: #ffffff;

    font-family: inherit;
    font-size: 13px;

    box-sizing: border-box;
}

.wiki-setting-select:hover,
.wiki-setting-select:focus {
    border-color: #58aaff;
}
.wiki-display-toggle {
    width: 100%;

    padding: 8px 10px;

    background: #101722;
    border: 2px solid #303a48;
    border-radius: 8px;

    color: #58aaff;

    font-family: inherit;
    font-size: 13px;
    font-weight: bold;

    cursor: pointer;

    box-sizing: border-box;

    transition:
        background 0.15s ease,
        border-color 0.15s ease;
}

.wiki-display-toggle:hover {
    background: #17243a;
    border-color: #58aaff;
}
.wiki-display-status {
    padding: 4px 10px;

    background: #101722;

    border: 2px solid #303a48;
    border-radius: 999px;

    color: #ffffff;

    font-size: 12px;
    font-weight: bold;

    white-space: nowrap;

    box-sizing: border-box;
}

#fish-entries-app {
    width: 750px;
    max-width: 100%;
    margin: 0 auto;
    box-sizing: border-box;
}

#fish-entries-app button {
    font-family: inherit;
}

.entries-app-loading,
.entries-app-error {
    width: 100%;
    padding: 18px;

    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 12px;

    color: #ffffff;

    text-align: center;

    box-sizing: border-box;
}

.entries-app-error {
    color: #ff7777;
}

.wiki-entries-shell {
    width: 750px;
    max-width: 100%;
    height: 400px;

    padding: 14px;

    background: #07142e;
    border: 4px solid #252c34;
    border-radius: 24px;

    color: #ffffff;

    overflow: hidden;

    box-sizing: border-box;
}

.wiki-entries-start {
    display: block;
}

.wiki-entries-start .wiki-entries-nav {
    width: 100%;
    height: 100%;

    display: grid;
    grid-template-columns: repeat(3, 1fr);

    gap: 18px;

    align-items: center;
}

.wiki-entries-start .wiki-entry-nav-pill {
    width: 100%;
    height: 220px;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    gap: 12px;

    padding: 16px;

    background: #0b1017;
    border: 3px solid #252c34;
    border-radius: 18px;

    color: #ffffff;

    font-size: 27px;
    font-weight: bold;

    cursor: pointer;

    box-sizing: border-box;

    transition:
        background 0.15s ease,
        border-color 0.15s ease,
        transform 0.15s ease;
}

.wiki-entries-start .wiki-entry-nav-pill:hover {
    background: #101b2b;
    border-color: #58aaff;

    transform: translateY(-2px);
}

.wiki-entries-start .wiki-entry-nav-pill img {
    width: 110px;
    height: 110px;

    object-fit: contain;

    pointer-events: none;
}

.wiki-entries-start .wiki-entry-nav-pill span {
    pointer-events: none;
}

.wiki-entries-open {
    display: grid;
    grid-template-columns: 150px minmax(0, 1fr);

    gap: 14px;
}

.wiki-entries-open .wiki-entries-nav {
    width: 150px;
    height: 100%;

    display: flex;
    flex-direction: column;

    gap: 9px;
}

.wiki-entries-open .wiki-entry-nav-pill {
    width: 100%;

    flex: 1;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    gap: 5px;

    min-height: 0;

    padding: 7px;

    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 13px;

    color: #ffffff;

    font-size: 16px;
    font-weight: bold;

    cursor: pointer;

    box-sizing: border-box;

    transition:
        background 0.15s ease,
