    border-color: #58aaff;
}

.wiki-entries-open .wiki-entry-nav-pill img {
    width: 62px;
    height: 62px;

    object-fit: contain;

    pointer-events: none;
}

.wiki-entries-open .wiki-entry-nav-pill span {
    pointer-events: none;
}

.wiki-entries-content {
    min-width: 0;
    height: 100%;

    padding: 15px 16px;

    background: #080c12;
    border: 3px solid #252c34;
    border-radius: 18px;

    overflow-y: auto;
    overflow-x: hidden;

    box-sizing: border-box;
}

.wiki-entries-content::-webkit-scrollbar {
    width: 7px;
}

.wiki-entries-content::-webkit-scrollbar-track {
    background: transparent;
}

.wiki-entries-content::-webkit-scrollbar-thumb {
    background: #354052;
    border-radius: 999px;
}

.wiki-entry-content-title {
    margin-bottom: 10px;

    color: #ffffff;

    font-size: 25px;
    font-weight: bold;
    line-height: 1.1;
}

.wiki-entry-subtabs {
    display: flex;
    flex-wrap: wrap;

    gap: 7px;

    margin-bottom: 11px;
}

.wiki-entry-subtab,
.wiki-entry-back {
    padding: 6px 12px;

    background: #101722;
    border: 2px solid #303a48;
    border-radius: 999px;

    color: #ffffff;

    font-size: 13px;
    font-weight: bold;

    cursor: pointer;

    box-sizing: border-box;

    transition:
        background 0.15s ease,
        border-color 0.15s ease;
}

.wiki-entry-subtab:hover,
.wiki-entry-back:hover {
    background: #17243a;
    border-color: #58aaff;
}

.wiki-entry-subtab.entry-active {
    background: #18366f;
    border-color: #58aaff;
}

.wiki-entry-items-body {
    width: 100%;
    min-width: 0;
}

.wiki-location-grid {
    width: 100%;

    display: flex;
    flex-wrap: wrap;
    justify-content: center;

    gap: 9px;

    box-sizing: border-box;
}

.wiki-location-pill {
    width: 125px;
    height: 112px;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    gap: 5px;

    padding: 8px;

    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 12px;

    color: #ffffff;

    cursor: pointer;

    box-sizing: border-box;

    transition:
        background 0.15s ease,
        border-color 0.15s ease,
        transform 0.15s ease;
}

.wiki-location-pill:hover {
    background: #101722;
    border-color: #58aaff;

    transform: translateY(-1px);
}

.wiki-location-pill img {
    width: 58px;
    height: 58px;

    object-fit: contain;

    pointer-events: none;
}

.wiki-location-name {
    width: 100%;

    color: #ffffff;

    font-size: 13px;
    font-weight: bold;
    line-height: 1.15;

    text-align: center;

    overflow: hidden;
    text-overflow: ellipsis;

    pointer-events: none;
}

.wiki-location-header {
    width: 100%;

    display: flex;
    align-items: center;
    justify-content: space-between;

    gap: 10px;

    margin-bottom: 10px;
}

.wiki-location-header-title {
    min-width: 0;

    display: flex;
    align-items: center;

    gap: 7px;

    color: #ffffff;

    font-size: 18px;
    font-weight: bold;
}

.wiki-location-header-title img {
    width: 38px;
    height: 38px;

    object-fit: contain;
}

.wiki-location-header-title span {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.wiki-fish-grid,
.wiki-standard-entry-grid {
    width: 100%;

    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));

    gap: 9px;

    box-sizing: border-box;
}

.wiki-fish-card,
.wiki-standard-entry-card {
    position: relative;

    min-width: 0;
    min-height: 125px;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    gap: 3px;

    padding: 8px;

    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 12px;

    color: #ffffff;

    cursor: pointer;

    box-sizing: border-box;

    overflow: hidden;

    transition:
        transform 0.15s ease,
        background 0.15s ease,
        border-color 0.15s ease;
}

.wiki-fish-card:hover,
.wiki-standard-entry-card:hover {
    background: #101722;
    border-color: #58aaff;

    transform: translateY(-1px);
}

.wiki-fish-card-image,
