.wiki-fish-card-name,
.wiki-standard-entry-name {
    max-width: 100%;

    color: #ffffff;

    font-size: 14px;
    font-weight: bold;
    line-height: 1.15;

    text-align: center;

    overflow-wrap: anywhere;

    pointer-events: none;
}

.wiki-fish-card-rarity,
