    font-weight: bold;
    line-height: 1.1;
}

.wiki-entry-subtabs {
    display: flex;
    flex-wrap: wrap;

    gap: 7px;

    margin-bottom: 11px;
}

.wiki-entry-subtab,
.wiki-entry-back {
    padding: 6px 12px;

    background: #101722;
    border: 2px solid #303a48;
    border-radius: 999px;

    color: #ffffff;

    font-size: 13px;
    font-weight: bold;

    cursor: pointer;

    box-sizing: border-box;

    transition:
        background 0.15s ease,
        border-color 0.15s ease;
}

.wiki-entry-subtab:hover,
.wiki-entry-back:hover {
    background: #17243a;
    border-color: #58aaff;
}

.wiki-entry-subtab.entry-active {
