    }

    .wiki-entry-description {
        font-size: 12px;
    }

}

.wiki-entries-frame {
    width: 750px;
    max-width: 100%;

    margin: 0 auto;

    background: #07142e;

    border: 4px solid #252c34;
    border-radius: 24px;

    overflow: hidden;

    box-sizing: border-box;
}

.wiki-entries-menu-bar {

    width: 100%;
    height: 36px;

    display: flex;
    align-items: center;

    gap: 8px;

    padding: 3px 7px;

    background: #07142e;

    border-bottom: 2px solid #252c34;

    box-sizing: border-box;
}

.wiki-entries-menu-button {
    width: 30px;
    height: 26px;

    display: flex;
    flex-direction: column;
    justify-content: center;

    gap: 4px;

    padding: 4px;

    background: transparent;
    border: none;

    cursor: pointer;
}

.wiki-entries-menu-button span {
    width: 22px;
    height: 3px;

    display: block;

    background: #ffffff;
    border-radius: 3px;
}

.wiki-entries-menu-button:hover span {
    background: #58aaff;
}

.wiki-entries-frame .wiki-entries-shell {
    width: 100%;

    margin: 0;

    border: none;
    border-radius: 0;

    box-sizing: border-box;
}

.wiki-entries-frame {
    position: relative;
}

.wiki-entries-side-menu {
    position: absolute;

    top: 36px;
    left: 0;
    bottom: 0;

    width: 250px;

    padding: 16px;

    background: #0b1017;
    border-right: 3px solid #252c34;

    box-sizing: border-box;

