}

.wiki-setting-select:hover,
.wiki-setting-select:focus {
    border-color: #58aaff;
}
.wiki-display-toggle {
    width: 100%;

    padding: 8px 10px;

    background: #101722;
    border: 2px solid #303a48;
    border-radius: 8px;

    color: #58aaff;

    font-family: inherit;
    font-size: 13px;
    font-weight: bold;

    cursor: pointer;

    box-sizing: border-box;

    transition:
        background 0.15s ease,
        border-color 0.15s ease;
}

.wiki-display-toggle:hover {
    background: #17243a;
    border-color: #58aaff;
}
.wiki-display-status {
    padding: 4px 10px;

    background: #101722;

    border: 2px solid #303a48;
    border-radius: 999px;

    color: #ffffff;

    font-size: 12px;
    font-weight: bold;

    white-space: nowrap;

    box-sizing: border-box;
}

#fish-entries-app {
    width: 750px;
    max-width: 100%;
    margin: 0 auto;
    box-sizing: border-box;
}

#fish-entries-app button {
    font-family: inherit;
}

.entries-app-loading,
.entries-app-error {
    width: 100%;
    padding: 18px;

    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 12px;

    color: #ffffff;

    text-align: center;

    box-sizing: border-box;
}

.entries-app-error {
    color: #ff7777;
}

.wiki-entries-shell {
    width: 750px;
    max-width: 100%;
    height: 400px;

    padding: 14px;

    background: #07142e;
    border: 4px solid #252c34;
    border-radius: 24px;

    color: #ffffff;

    overflow: hidden;

    box-sizing: border-box;
}

.wiki-entries-start {
    display: block;
}

.wiki-entries-start .wiki-entries-nav {
    width: 100%;
    height: 100%;

    display: grid;
    grid-template-columns: repeat(3, 1fr);

    gap: 18px;

    align-items: center;
}

.wiki-entries-start .wiki-entry-nav-pill {
    width: 100%;
    height: 220px;

    display: flex;
    flex-direction: column;
    align-items: center;
