}

.wiki-location-grid {
    width: 100%;

    display: flex;
    flex-wrap: wrap;
    justify-content: center;

    gap: 9px;

    box-sizing: border-box;
}

.wiki-location-pill {
    width: 125px;
    height: 112px;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    gap: 5px;

    padding: 8px;

    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 12px;

    color: #ffffff;

    cursor: pointer;

