}

.wiki-tool-type-pill {
    width: 100%;

    margin-bottom: 9px;
    padding-bottom: 6px;

    background: transparent;
    border: none;
    border-bottom: 2px solid #303a48;
    border-radius: 0;

    color: #ffffff;

    font-size: 15px;
    font-weight: bold;
    line-height: 1.2;

    text-align: left;

    box-sizing: border-box;
}
.wiki-fish-grid,
.wiki-standard-entry-grid {
    width: 100%;

    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));

    gap: 9px;

    box-sizing: border-box;
}

.wiki-fish-card,
.wiki-standard-entry-card {
    position: relative;

    min-width: 0;
    min-height: 125px;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    gap: 3px;

    padding: 8px;

    background: #0b1017;
    border: none;
    border-radius: 12px;
    box-shadow:
        inset 0 0 0 2px #252c34;

    color: #ffffff;

    cursor: pointer;

    box-sizing: border-box;

    overflow: hidden;

    transition:
        transform 0.15s ease,
        background 0.15s ease,
        border-color 0.15s ease;
}

.wiki-fish-card:hover,
.wiki-standard-entry-card:hover {
    background: #101722;
    box-shadow:
        inset 0 0 0 2px #58aaff;
    transform: translateY(-1px);
}

.wiki-fish-card-image,
.wiki-standard-entry-card img {
    width: 52px;
    height: 52px;

    object-fit: contain;

    flex: 0 0 auto;

    pointer-events: none;
