    letter-spacing: 1px;
}

.wiki-fish-card-chance,
.wiki-standard-card-extra {
    color: #aab7c7;

    font-size: 11px;
    font-weight: bold;
    line-height: 1.15;

    text-align: center;

    pointer-events: none;
}

.wiki-entry-detail {
    width: 100%;

    display: flex;
    flex-direction: column;
    align-items: center;

    box-sizing: border-box;
}

.wiki-detail-back-row {
