}

.wiki-entry-stat-label {
    margin-bottom: 2px;

    color: #8391a4;

    font-size: 10px;
    font-weight: bold;

    text-transform: uppercase;
}

.wiki-entry-stat-value {
    color: #ffffff;

    font-size: 13px;
    font-weight: bold;

    overflow-wrap: break-word;
}

.wiki-entry-description {
    width: 100%;

    margin-top: 11px;
    padding: 10px 11px;

    background: #0b1017;
    border: 1px solid #252c34;
    border-radius: 10px;

    color: #d8dee8;

    font-size: 13px;
    line-height: 1.45;

    white-space: pre-line;
    overflow-wrap: break-word;

    box-sizing: border-box;
}

.wiki-lore-blue {
    color: #58aaff;
}
.wiki-lore-formula {
    color: #8997aa;
    font-style: italic;
}

.wiki-entry-empty {
    width: 100%;

    padding: 20px 10px;

    color: #8997aa;

    font-size: 13px;

    text-align: center;

    box-sizing: border-box;
}

.wiki-fish-card.wiki-rarity-animated-border {
    position: relative;

    overflow: hidden;

    border: none;
    border-radius: 12px;

    background: transparent;

    box-shadow: none;
}


.wiki-fish-card.wiki-rarity-animated-border::before {
    content: "";

    position: absolute;

    width: 300%;
    height: 300%;

    left: -100%;
    top: -100%;

    background:
        conic-gradient(
            from 45deg,
            var(--rarity-border-color-0) 0deg,
            var(--rarity-border-color-50) 90deg,
            var(--rarity-border-color-0) 180deg,
            var(--rarity-border-color-50) 270deg,
            var(--rarity-border-color-0) 360deg
        );

    animation:
        wiki-rarity-border-spin
        6s
        linear
        infinite;

    z-index: 0;

    pointer-events: none;
}


.wiki-fish-card.wiki-rarity-animated-border::after {
    content: "";

    position: absolute;

    top: 3px;
    right: 3px;
    bottom: 3px;
    left: 3px;

    background: #0b1017;

    border-radius: 9px;

    z-index: 1;

    pointer-events: none;
}


.wiki-fish-card.wiki-rarity-animated-border > img,
.wiki-fish-card.wiki-rarity-animated-border > div {
    position: relative;

    z-index: 2;
}


.wiki-fish-card.wiki-rarity-animated-border:hover::after {
    background: #101722;
}


@keyframes wiki-rarity-border-spin {

    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }

}

