    box-sizing: border-box;

    z-index: 20;

    overflow-y: auto;

    transform: translateX(-100%);

    transition:
        transform 0.25s ease;
}

.wiki-entries-side-menu.wiki-side-menu-open {
    transform: translateX(0);
}

.wiki-side-menu-setting {
    width: 100%;

    padding-bottom: 15px;
    margin-bottom: 15px;

    border-bottom: 1px solid #252c34;

    box-sizing: border-box;
}

.wiki-side-menu-label {
    margin-bottom: 9px;

    color: #ffffff;

    font-size: 15px;
    font-weight: bold;
}

.wiki-fish-luck-setting {
    display: flex;
    flex-direction: column;

    gap: 13px;
}

.wiki-setting-field {
    width: 100%;

    display: flex;
    flex-direction: column;

    gap: 5px;

    color: #d8dee8;

    font-size: 12px;
    font-weight: bold;
}

.wiki-setting-select {
    width: 100%;

    padding: 7px 9px;

    background: #101722;

    border: 2px solid #303a48;
    border-radius: 8px;

    color: #ffffff;

    font-family: inherit;
    font-size: 13px;

    box-sizing: border-box;
}

.wiki-setting-select:hover,
.wiki-setting-select:focus {
    border-color: #58aaff;
}
.wiki-display-toggle {
    width: 100%;

    padding: 8px 10px;

    background: #101722;
    border: 2px solid #303a48;
    border-radius: 8px;

    color: #58aaff;

    font-family: inherit;
    font-size: 13px;
    font-weight: bold;

    cursor: pointer;

    box-sizing: border-box;

    transition:
        background 0.15s ease,
        border-color 0.15s ease;
}

.wiki-display-toggle:hover {
    background: #17243a;
    border-color: #58aaff;
}
.wiki-display-status {
    padding: 4px 10px;

    background: #101722;

    border: 2px solid #303a48;
    border-radius: 999px;

    color: #ffffff;

    font-size: 12px;
    font-weight: bold;

    white-space: nowrap;

    box-sizing: border-box;
}

#fish-entries-app {
    width: 750px;
    max-width: 100%;
    margin: 0 auto;
    box-sizing: border-box;
}

#fish-entries-app button {
    font-family: inherit;
}

.entries-app-loading,
.entries-app-error {
    width: 100%;
    padding: 18px;

    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 12px;

    color: #ffffff;

    text-align: center;

    box-sizing: border-box;
}

.entries-app-error {
    color: #ff7777;
}

.wiki-entries-shell {
    width: 750px;
    max-width: 100%;
    height: 400px;

    padding: 14px;

    background: #07142e;
    border: 4px solid #252c34;
    border-radius: 24px;

    color: #ffffff;

    overflow: hidden;

    box-sizing: border-box;
}

.wiki-entries-start {
    display: block;
}

.wiki-entries-start .wiki-entries-nav {
    width: 100%;
    height: 100%;

    display: grid;
    grid-template-columns: repeat(3, 1fr);

    gap: 18px;

    align-items: center;
}

.wiki-entries-start .wiki-entry-nav-pill {
    width: 100%;
    height: 220px;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    gap: 12px;

    padding: 16px;

    background: #0b1017;
    border: 3px solid #252c34;
    border-radius: 18px;

    color: #ffffff;

    font-size: 27px;
    font-weight: bold;

    cursor: pointer;

    box-sizing: border-box;

    transition:
        background 0.15s ease,
        border-color 0.15s ease,
        transform 0.15s ease;
}

.wiki-entries-start .wiki-entry-nav-pill:hover {
    background: #101b2b;
    border-color: #58aaff;

    transform: translateY(-2px);
}

.wiki-entries-start .wiki-entry-nav-pill img {
    width: 110px;
    height: 110px;

    object-fit: contain;

    pointer-events: none;
}

.wiki-entries-start .wiki-entry-nav-pill span {
    pointer-events: none;
}

.wiki-entries-open {
    display: grid;
    grid-template-columns: 150px minmax(0, 1fr);

    gap: 14px;
}

.wiki-entries-open .wiki-entries-nav {
    width: 150px;
    height: 100%;

    display: flex;
    flex-direction: column;

    gap: 9px;
}

.wiki-entries-open .wiki-entry-nav-pill {
    width: 100%;

    flex: 1;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    gap: 5px;

    min-height: 0;

    padding: 7px;

    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 13px;

    color: #ffffff;

    font-size: 16px;
    font-weight: bold;

    cursor: pointer;

    box-sizing: border-box;

    transition:
        background 0.15s ease,
        border-color 0.15s ease;
}

.wiki-entries-open .wiki-entry-nav-pill:hover {
    background: #101b2b;
    border-color: #58aaff;
}

.wiki-entries-open .wiki-entry-nav-pill.entry-active {
    background: #18366f;
    border-color: #58aaff;
}

.wiki-entries-open .wiki-entry-nav-pill img {
    width: 62px;
    height: 62px;

    object-fit: contain;

    pointer-events: none;
}

.wiki-entries-open .wiki-entry-nav-pill span {
    pointer-events: none;
}

.wiki-entries-content {
    min-width: 0;
    height: 100%;

    padding: 15px 16px;

    background: #080c12;
    border: 3px solid #252c34;
    border-radius: 18px;

    overflow-y: auto;
    overflow-x: hidden;

    box-sizing: border-box;
}

.wiki-entries-content::-webkit-scrollbar {
    width: 7px;
}

.wiki-entries-content::-webkit-scrollbar-track {
    background: transparent;
}

.wiki-entries-content::-webkit-scrollbar-thumb {
    background: #354052;
    border-radius: 999px;
}

.wiki-entry-content-title {
    margin-bottom: 10px;

    color: #ffffff;

    font-size: 25px;
    font-weight: bold;
    line-height: 1.1;
}

.wiki-entry-subtabs {
    display: flex;
    flex-wrap: wrap;

    gap: 7px;

    margin-bottom: 11px;
}

.wiki-entry-subtab,
.wiki-entry-back {
    padding: 6px 12px;

    background: #101722;
    border: 2px solid #303a48;
    border-radius: 999px;

    color: #ffffff;

    font-size: 13px;
    font-weight: bold;

    cursor: pointer;

    box-sizing: border-box;

    transition:
        background 0.15s ease,
        border-color 0.15s ease;
}

.wiki-entry-subtab:hover,
.wiki-entry-back:hover {
    background: #17243a;
    border-color: #58aaff;
}

.wiki-entry-subtab.entry-active {
    background: #18366f;
    border-color: #58aaff;
}

.wiki-entry-items-body {
    width: 100%;
    min-width: 0;
}

.wiki-location-grid {
    width: 100%;

    display: flex;
    flex-wrap: wrap;
    justify-content: center;

    gap: 9px;

    box-sizing: border-box;
}

.wiki-location-pill {
    width: 125px;
    height: 112px;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    gap: 5px;

    padding: 8px;

    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 12px;

    color: #ffffff;

    cursor: pointer;

    box-sizing: border-box;

    transition:
        background 0.15s ease,
        border-color 0.15s ease,
        transform 0.15s ease;
}

.wiki-location-pill:hover {
    background: #101722;
    border-color: #58aaff;

    transform: translateY(-1px);
}

.wiki-location-pill img {
    width: 58px;
    height: 58px;

    object-fit: contain;

    pointer-events: none;
}

.wiki-location-name {
    width: 100%;

    color: #ffffff;

    font-size: 13px;
    font-weight: bold;
    line-height: 1.15;

    text-align: center;

    overflow: hidden;
    text-overflow: ellipsis;

    pointer-events: none;
}

.wiki-location-header {
    width: 100%;

    display: flex;
    align-items: center;
    justify-content: space-between;

    gap: 10px;

    margin-bottom: 10px;
}

.wiki-location-header-title {
    min-width: 0;

    display: flex;
    align-items: center;

    gap: 7px;

    color: #ffffff;

    font-size: 18px;
    font-weight: bold;
}

.wiki-location-header-title img {
    width: 38px;
    height: 38px;

    object-fit: contain;
}

.wiki-location-header-title span {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.wiki-tool-type-group {
    width: 100%;

    margin-bottom: 16px;

    box-sizing: border-box;
}

.wiki-tool-type-group:last-child {
    margin-bottom: 0;
}

.wiki-tool-type-pill {
    width: 100%;

    margin-bottom: 9px;
    padding-bottom: 6px;

    background: transparent;
    border: none;
    border-bottom: 2px solid #303a48;
    border-radius: 0;

    color: #ffffff;

    font-size: 15px;
    font-weight: bold;
    line-height: 1.2;

    text-align: left;

    box-sizing: border-box;
}
.wiki-fish-grid,
.wiki-standard-entry-grid {
    width: 100%;

    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));

    gap: 9px;

    box-sizing: border-box;
}

.wiki-fish-card,
.wiki-standard-entry-card {
    position: relative;

    min-width: 0;
    min-height: 125px;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    gap: 3px;

    padding: 8px;

    background: #0b1017;
    border: none;
    border-radius: 12px;
    box-shadow:
        inset 0 0 0 2px #252c34;

    color: #ffffff;

    cursor: pointer;

    box-sizing: border-box;

    overflow: hidden;

    transition:
        transform 0.15s ease,
        background 0.15s ease,
        border-color 0.15s ease;
}

.wiki-fish-card:hover,
.wiki-standard-entry-card:hover {
    background: #101722;
    box-shadow:
        inset 0 0 0 2px #58aaff;
    transform: translateY(-1px);
}

.wiki-fish-card-image,
.wiki-standard-entry-card img {
    width: 52px;
    height: 52px;

    object-fit: contain;

    flex: 0 0 auto;

    pointer-events: none;
}

.wiki-fish-card-name,
.wiki-standard-entry-name {
    max-width: 100%;

    color: #ffffff;

    font-size: 14px;
    font-weight: bold;
    line-height: 1.15;

    text-align: center;

    overflow-wrap: break-word;

    pointer-events: none;
}

.wiki-fish-card-rarity,
.wiki-standard-entry-rarity,
.wiki-entry-detail-rarity {
    max-width: 100%;

    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: center;

    gap: 1px;

    font-size: 11px;
    font-weight: bold;
    line-height: 1.15;

    text-align: center;
}

.wiki-rarity-stars-inline {
    margin-left: 0;

    letter-spacing: 1px;
}

.wiki-fish-card-chance,
.wiki-standard-card-extra {
    color: #aab7c7;

    font-size: 11px;
    font-weight: bold;
    line-height: 1.15;

    text-align: center;

    pointer-events: none;
}

.wiki-entry-detail {
    width: 100%;

    display: flex;
    flex-direction: column;
    align-items: center;

    box-sizing: border-box;
}

.wiki-detail-back-row {
    width: 100%;

    display: flex;
    justify-content: flex-start;

    margin-bottom: 7px;
}

.wiki-entry-detail-image {
    width: 80px;
    height: 80px;

    margin-bottom: 5px;

    object-fit: contain;
}

.wiki-entry-detail-name {
    max-width: 100%;

    color: #ffffff;

    font-size: 21px;
    font-weight: bold;
    line-height: 1.15;

    text-align: center;

    overflow-wrap: break-word;
}

.wiki-entry-detail-rarity {
    margin-top: 2px;

    font-size: 13px;
}

.wiki-entry-detail-rarity .wiki-rarity-stars-inline {
    font-size: 14px;
}

.wiki-entry-stat-grid {
    width: 100%;

    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));

    gap: 7px;

    margin-top: 11px;

    box-sizing: border-box;
}

.wiki-entry-stat {
    min-width: 0;

    padding: 7px 5px;

    background: #0b1017;
    border: 1px solid #252c34;
    border-radius: 9px;

    box-sizing: border-box;

    text-align: center;
}

.wiki-entry-stat-label {
    margin-bottom: 2px;

    color: #8391a4;

    font-size: 10px;
    font-weight: bold;

    text-transform: uppercase;
}

.wiki-entry-stat-value {
    color: #ffffff;

    font-size: 13px;
    font-weight: bold;

    overflow-wrap: break-word;
}

.wiki-entry-description {
    width: 100%;

    margin-top: 11px;
    padding: 10px 11px;

    background: #0b1017;
    border: 1px solid #252c34;
    border-radius: 10px;

    color: #d8dee8;

    font-size: 13px;
    line-height: 1.45;

    white-space: pre-line;
    overflow-wrap: break-word;

    box-sizing: border-box;
}

.wiki-lore-blue {
    color: #58aaff;
}
.wiki-lore-formula {
    color: #8997aa;
    font-style: italic;
}

.wiki-entry-empty {
    width: 100%;

    padding: 20px 10px;

    color: #8997aa;

    font-size: 13px;

    text-align: center;

    box-sizing: border-box;
}

.wiki-fish-card.wiki-rarity-animated-border {
    position: relative;

    overflow: hidden;

    border: none;
    border-radius: 12px;

    background: transparent;

    box-shadow: none;
}


.wiki-fish-card.wiki-rarity-animated-border::before {
    content: "";

    position: absolute;

    width: 300%;
    height: 300%;

    left: -100%;
    top: -100%;

    background:
        conic-gradient(
            from 45deg,
            var(--rarity-border-color-0) 0deg,
            var(--rarity-border-color-50) 90deg,
            var(--rarity-border-color-0) 180deg,
            var(--rarity-border-color-50) 270deg,
            var(--rarity-border-color-0) 360deg
        );

    animation:
        wiki-rarity-border-spin
        6s
        linear
        infinite;

    z-index: 0;

    pointer-events: none;
}


.wiki-fish-card.wiki-rarity-animated-border::after {
    content: "";

    position: absolute;

    top: 3px;
    right: 3px;
    bottom: 3px;
    left: 3px;

    background: #0b1017;

    border-radius: 9px;

    z-index: 1;

    pointer-events: none;
}


.wiki-fish-card.wiki-rarity-animated-border > img,
.wiki-fish-card.wiki-rarity-animated-border > div {
    position: relative;

    z-index: 2;
}


.wiki-fish-card.wiki-rarity-animated-border:hover::after {
    background: #101722;
}


@keyframes wiki-rarity-border-spin {

    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }

}

@media (max-width: 760px) {

    #fish-entries-app {
        width: 100%;
    }

    .wiki-entries-shell {
        width: 100%;
    }

    .wiki-entries-open {
        grid-template-columns: 125px minmax(0, 1fr);

        gap: 10px;
    }

    .wiki-entries-open .wiki-entries-nav {
        width: 125px;
    }

    .wiki-entries-open .wiki-entry-nav-pill img {
        width: 52px;
        height: 52px;
    }

    .wiki-entries-open .wiki-entry-nav-pill {
        font-size: 14px;
    }

}

@media (max-width: 520px) {

    .wiki-entries-shell {
        height: 400px;

        padding: 8px;

        border-width: 3px;
        border-radius: 18px;
    }

    .wiki-entries-start .wiki-entries-nav {
        gap: 7px;
    }

    .wiki-entries-start .wiki-entry-nav-pill {
        height: 190px;

        padding: 8px;

        font-size: 18px;
    }

    .wiki-entries-start .wiki-entry-nav-pill img {
        width: 70px;
        height: 70px;
    }

    .wiki-entries-open {
        grid-template-columns: 90px minmax(0, 1fr);

        gap: 7px;
    }

    .wiki-entries-open .wiki-entries-nav {
        width: 90px;

        gap: 6px;
    }

    .wiki-entries-open .wiki-entry-nav-pill {
        padding: 5px;

        border-radius: 10px;

        font-size: 11px;
    }

    .wiki-entries-open .wiki-entry-nav-pill img {
        width: 36px;
        height: 36px;
    }

    .wiki-entries-content {
        padding: 10px;

        border-width: 2px;
        border-radius: 13px;
    }

    .wiki-entry-content-title {
        font-size: 20px;
    }

    .wiki-location-grid {
        gap: 6px;
    }

    .wiki-location-pill {
        width: calc(50% - 4px);
        height: 100px;
    }

    .wiki-location-pill img {
        width: 48px;
        height: 48px;
    }

    .wiki-fish-grid,
    .wiki-standard-entry-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));

        gap: 6px;
    }

    .wiki-fish-card,
    .wiki-standard-entry-card {
        min-height: 112px;

        padding: 6px;
    }

    .wiki-fish-card-image,
    .wiki-standard-entry-card img {
        width: 44px;
        height: 44px;
    }

    .wiki-fish-card-name,
    .wiki-standard-entry-name {
        font-size: 12px;
    }

    .wiki-fish-card-rarity,
    .wiki-standard-entry-rarity {
        font-size: 9px;
    }

    .wiki-fish-card-chance,
    .wiki-standard-card-extra {
        font-size: 9px;
    }

    .wiki-entry-detail-image {
        width: 65px;
        height: 65px;
    }

    .wiki-entry-detail-name {
        font-size: 18px;
    }

    .wiki-entry-stat-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .wiki-entry-description {
        font-size: 12px;
    }

}

