        repeat(2, minmax(0, 1fr));

    gap: 6px;
}

.wiki-bait-picker-card {
    min-width: 0;

    padding: 7px 4px;

    display: flex;
    flex-direction: column;
    align-items: center;

    gap: 4px;

    background: #101722;

    border: 2px solid #252c34;
    border-radius: 8px;

    color: #ffffff;

