}

.wiki-entries-shell {
    width: 750px;
    max-width: 100%;
    height: 400px;

    padding: 14px;

    background: #07142e;
    border: 4px solid #252c34;
    border-radius: 24px;

    color: #ffffff;

    overflow: hidden;

    box-sizing: border-box;
}

.wiki-entries-start {
