    grid-template-columns: 150px minmax(0, 1fr);

    gap: 14px;
}

.wiki-entries-open .wiki-entries-nav {
    width: 150px;
    height: 100%;

    display: flex;
    flex-direction: column;

    gap: 9px;
}

.wiki-entries-open .wiki-entry-nav-pill {
    width: 100%;

    flex: 1;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    gap: 5px;

    min-height: 0;

    padding: 7px;

    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 13px;

    color: #ffffff;

    font-size: 16px;
    font-weight: bold;

    cursor: pointer;

    box-sizing: border-box;

    transition:
        background 0.15s ease,
        border-color 0.15s ease;
}

.wiki-entries-open .wiki-entry-nav-pill:hover {
    background: #101b2b;
    border-color: #58aaff;
}

.wiki-entries-open .wiki-entry-nav-pill.entry-active {
    background: #18366f;
    border-color: #58aaff;
}

.wiki-entries-open .wiki-entry-nav-pill img {
    width: 62px;
    height: 62px;

    object-fit: contain;

    pointer-events: none;
}

.wiki-entries-open .wiki-entry-nav-pill span {
    pointer-events: none;
}

.wiki-entries-content {
