    height: 100%;

    padding: 15px 16px;

    background: #080c12;
    border: 3px solid #252c34;
    border-radius: 18px;

    overflow-y: auto;
    overflow-x: hidden;

    box-sizing: border-box;
}

.wiki-entries-content::-webkit-scrollbar {
