}

.wiki-entry-subtab,
.wiki-entry-back {
    padding: 6px 12px;

    background: #101722;
    border: 2px solid #303a48;
    border-radius: 999px;

    color: #ffffff;

    font-size: 13px;
    font-weight: bold;

    cursor: pointer;

    box-sizing: border-box;

    transition:
        background 0.15s ease,
        border-color 0.15s ease;
}

.wiki-entry-subtab:hover,
.wiki-entry-back:hover {
    background: #17243a;
    border-color: #58aaff;
}

.wiki-entry-subtab.entry-active {
    background: #18366f;
    border-color: #58aaff;
}

.wiki-entry-items-body {
    width: 100%;
    min-width: 0;
}

.wiki-location-grid {
    width: 100%;

    display: flex;
    flex-wrap: wrap;
    justify-content: center;

    gap: 9px;

    box-sizing: border-box;
}

.wiki-location-pill {
    width: 125px;
    height: 112px;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    gap: 5px;

    padding: 8px;

    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 12px;

    color: #ffffff;

    cursor: pointer;

    box-sizing: border-box;

    transition:
        background 0.15s ease,
        border-color 0.15s ease,
        transform 0.15s ease;
}

.wiki-location-pill:hover {
    background: #101722;
    border-color: #58aaff;

    transform: translateY(-1px);
}

.wiki-location-pill img {
    width: 58px;
    height: 58px;

    object-fit: contain;

    pointer-events: none;
}

.wiki-location-name {
