}

.wiki-tool-type-pill {
    width: 100%;

    margin-bottom: 9px;
    padding-bottom: 6px;

    background: transparent;
    border: none;
    border-bottom: 2px solid #303a48;
    border-radius: 0;

    color: #ffffff;

    font-size: 15px;
    font-weight: bold;
    line-height: 1.2;

    text-align: left;

    box-sizing: border-box;
