.wiki-fish-card-name,
.wiki-standard-entry-name {
    max-width: 100%;

    color: #ffffff;

    font-size: 14px;
    font-weight: bold;
    line-height: 1.15;

    text-align: center;

    overflow-wrap: break-word;

    pointer-events: none;
}

.wiki-fish-card-rarity,
.wiki-standard-entry-rarity,
.wiki-entry-detail-rarity {
    max-width: 100%;

    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: center;

    gap: 1px;

    font-size: 11px;
    font-weight: bold;
    line-height: 1.15;

    text-align: center;
}

.wiki-rarity-stars-inline {
    margin-left: 0;

    letter-spacing: 1px;
}

.wiki-fish-card-chance,
.wiki-standard-card-extra {
    color: #aab7c7;

    font-size: 11px;
    font-weight: bold;
    line-height: 1.15;

    text-align: center;

    pointer-events: none;
}

.wiki-entry-detail {
    width: 100%;

    display: flex;
    flex-direction: column;
    align-items: center;

    box-sizing: border-box;
}

.wiki-detail-back-row {
    width: 100%;

    display: flex;
    justify-content: flex-start;

    margin-bottom: 7px;
}

.wiki-entry-detail-image {
    width: 80px;
    height: 80px;

    margin-bottom: 5px;

    object-fit: contain;
}

.wiki-entry-detail-name {
    max-width: 100%;

    color: #ffffff;

    font-size: 21px;
    font-weight: bold;
    line-height: 1.15;

    text-align: center;

    overflow-wrap: break-word;
}

.wiki-entry-detail-rarity {
    margin-top: 2px;

    font-size: 13px;
}

.wiki-entry-detail-rarity .wiki-rarity-stars-inline {
    font-size: 14px;
}

.wiki-entry-stat-grid {
    width: 100%;

    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));

    gap: 7px;

    margin-top: 11px;

    box-sizing: border-box;
}

.wiki-entry-stat {
    min-width: 0;

    padding: 7px 5px;

    background: #0b1017;
    border: 1px solid #252c34;
    border-radius: 9px;

    box-sizing: border-box;

    text-align: center;
}

.wiki-entry-stat-label {
    margin-bottom: 2px;

    color: #8391a4;

    font-size: 10px;
    font-weight: bold;

    text-transform: uppercase;
}

.wiki-entry-stat-value {
    color: #ffffff;

    font-size: 13px;
    font-weight: bold;

    overflow-wrap: break-word;
}

.wiki-entry-description {
    width: 100%;

    margin-top: 11px;
    padding: 10px 11px;

    background: #0b1017;
    border: 1px solid #252c34;
    border-radius: 10px;

    color: #d8dee8;

    font-size: 13px;
    line-height: 1.45;

    white-space: pre-line;
    overflow-wrap: break-word;

    box-sizing: border-box;
}

.wiki-lore-blue {
    color: #58aaff;
}
.wiki-lore-formula {
    color: #8997aa;
    font-style: italic;
}

.wiki-entry-empty {
    width: 100%;

    padding: 20px 10px;

    color: #8997aa;

    font-size: 13px;

    text-align: center;

    box-sizing: border-box;
}
.wiki-fish-card.wiki-rarity-animated-border,
.wiki-standard-entry-card.wiki-rarity-animated-border {
    position: relative;

    overflow: hidden;

    border: none;
    border-radius: 12px;

    background: transparent;

    box-shadow: none;
}

.wiki-fish-card.wiki-rarity-animated-border::before,
.wiki-standard-entry-card.wiki-rarity-animated-border::before {
    content: "";

    position: absolute;

    width: 300%;
    height: 300%;

    left: -100%;
    top: -100%;

    background:
        conic-gradient(
            from 45deg,
            var(--rarity-border-color-0) 0deg,
            var(--rarity-border-color-50) 90deg,
            var(--rarity-border-color-0) 180deg,
            var(--rarity-border-color-50) 270deg,
            var(--rarity-border-color-0) 360deg
        );

    animation:
        wiki-rarity-border-spin
        6s
        linear
        infinite;

    z-index: 0;

    pointer-events: none;
}

.wiki-fish-card.wiki-rarity-animated-border::after,
.wiki-standard-entry-card.wiki-rarity-animated-border::after {
    content: "";

    position: absolute;

    top: 3px;
    right: 3px;
    bottom: 3px;
    left: 3px;

    background: #0b1017;

    border-radius: 9px;

    z-index: 1;

    pointer-events: none;
}


.wiki-fish-card.wiki-rarity-animated-border > img,
.wiki-fish-card.wiki-rarity-animated-border > div,
.wiki-standard-entry-card.wiki-rarity-animated-border > img,
.wiki-standard-entry-card.wiki-rarity-animated-border > div {
    position: relative;

    z-index: 2;
}

.wiki-fish-card.wiki-rarity-animated-border:hover::after,
.wiki-standard-entry-card.wiki-rarity-animated-border:hover::after {
    background: #101722;
}


@keyframes wiki-rarity-border-spin {

    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }

}

@media (max-width: 760px) {

    #fish-entries-app {
        width: 100%;
    }

    .wiki-entries-shell {
        width: 100%;
    }

    .wiki-entries-open {
        grid-template-columns: 125px minmax(0, 1fr);

        gap: 10px;
    }

    .wiki-entries-open .wiki-entries-nav {
        width: 125px;
    }

    .wiki-entries-open .wiki-entry-nav-pill img {
        width: 52px;
        height: 52px;
    }

    .wiki-entries-open .wiki-entry-nav-pill {
        font-size: 14px;
    }

}

@media (max-width: 520px) {

    .wiki-entries-shell {
        height: 400px;

        padding: 8px;

        border-width: 3px;
        border-radius: 18px;
    }

    .wiki-entries-start .wiki-entries-nav {
        gap: 7px;
    }

    .wiki-entries-start .wiki-entry-nav-pill {
        height: 190px;

        padding: 8px;

        font-size: 18px;
    }

    .wiki-entries-start .wiki-entry-nav-pill img {
        width: 70px;
        height: 70px;
    }

    .wiki-entries-open {
        grid-template-columns: 90px minmax(0, 1fr);

        gap: 7px;
    }

    .wiki-entries-open .wiki-entries-nav {
        width: 90px;

        gap: 6px;
    }

    .wiki-entries-open .wiki-entry-nav-pill {
        padding: 5px;

        border-radius: 10px;

        font-size: 11px;
    }

    .wiki-entries-open .wiki-entry-nav-pill img {
        width: 36px;
        height: 36px;
    }

    .wiki-entries-content {
        padding: 10px;

        border-width: 2px;
        border-radius: 13px;
    }

    .wiki-entry-content-title {
        font-size: 20px;
    }

    .wiki-location-grid {
        gap: 6px;
    }

    .wiki-location-pill {
        width: calc(50% - 4px);
        height: 100px;
    }

    .wiki-location-pill img {
        width: 48px;
        height: 48px;
    }

    .wiki-fish-grid,
    .wiki-standard-entry-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));

        gap: 6px;
    }

    .wiki-fish-card,
    .wiki-standard-entry-card {
        min-height: 112px;

        padding: 6px;
    }

    .wiki-fish-card-image,
    .wiki-standard-entry-card img {
        width: 44px;
        height: 44px;
    }

    .wiki-fish-card-name,
    .wiki-standard-entry-name {
        font-size: 12px;
    }

    .wiki-fish-card-rarity,
    .wiki-standard-entry-rarity {
        font-size: 9px;
    }

    .wiki-fish-card-chance,
    .wiki-standard-card-extra {
        font-size: 9px;
    }

    .wiki-entry-detail-image {
        width: 65px;
        height: 65px;
    }

    .wiki-entry-detail-name {
        font-size: 18px;
    }

    .wiki-entry-stat-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .wiki-entry-description {
        font-size: 12px;
    }

}

.wiki-entries-frame {
