    line-height: 1.2;

    text-align: left;

    box-sizing: border-box;

    transform: none !important;
}

.entry-creator-edit-item:hover {
    background: #202b3a !important;
    border-color: #58aaff !important;
}

.entry-creator-edit-item.entry-active {
