}

.wiki-location-header {
    width: 100%;

    display: flex;
    align-items: center;
    justify-content: space-between;

    gap: 10px;

    margin-bottom: 10px;
}

.wiki-location-header-title {
    min-width: 0;

    display: flex;
    align-items: center;

    gap: 7px;

    color: #ffffff;

    font-size: 18px;
    font-weight: bold;
}

.wiki-location-header-title img {
    width: 38px;
    height: 38px;

    object-fit: contain;
}

.wiki-location-header-title span {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.wiki-tool-type-group {
    width: 100%;

    margin-bottom: 16px;

    box-sizing: border-box;
}

.wiki-tool-type-group:last-child {
    margin-bottom: 0;
}

.wiki-tool-type-pill {
    width: 100%;

    margin-bottom: 9px;
    padding-bottom: 6px;

    background: transparent;
    border: none;
    border-bottom: 2px solid #303a48;
    border-radius: 0;

    color: #ffffff;

    font-size: 15px;
    font-weight: bold;
    line-height: 1.2;

    text-align: left;

    box-sizing: border-box;
}
.wiki-fish-grid,
.wiki-standard-entry-grid {
    width: 100%;

    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));

    gap: 9px;

    box-sizing: border-box;
}

.wiki-fish-card,
.wiki-standard-entry-card {
    position: relative;

    min-width: 0;
    min-height: 125px;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    gap: 3px;

    padding: 8px;

    background: #0b1017;
    border: none;
    border-radius: 12px;
    box-shadow:
        inset 0 0 0 2px #252c34;

    color: #ffffff;

    cursor: pointer;

    box-sizing: border-box;

    overflow: hidden;

    transition:
        transform 0.15s ease,
        background 0.15s ease,
        border-color 0.15s ease;
}

.wiki-fish-card:hover,
.wiki-standard-entry-card:hover {
    background: #101722;
    box-shadow:
        inset 0 0 0 2px #58aaff;
    transform: translateY(-1px);
}

.wiki-fish-card-image,
.wiki-standard-entry-card img {
    width: 52px;
    height: 52px;

    object-fit: contain;

    flex: 0 0 auto;

    pointer-events: none;
}

.wiki-fish-card-name,
.wiki-standard-entry-name {
    max-width: 100%;

    color: #ffffff;

    font-size: 14px;
    font-weight: bold;
    line-height: 1.15;

    text-align: center;

    overflow-wrap: break-word;

    pointer-events: none;
}

.wiki-fish-card-rarity,
.wiki-standard-entry-rarity,
.wiki-entry-detail-rarity {
    max-width: 100%;

    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: center;

    gap: 1px;

    font-size: 11px;
    font-weight: bold;
    line-height: 1.15;

    text-align: center;
}

.wiki-rarity-stars-inline {
    margin-left: 0;

    letter-spacing: 1px;
}

.wiki-fish-card-chance,
.wiki-standard-card-extra {
    color: #aab7c7;

    font-size: 11px;
    font-weight: bold;
    line-height: 1.15;

    text-align: center;

    pointer-events: none;
}

.wiki-entry-detail {
    width: 100%;

    display: flex;
    flex-direction: column;
    align-items: center;

    box-sizing: border-box;
}

.wiki-detail-back-row {
    width: 100%;

    display: flex;
    justify-content: flex-start;

    margin-bottom: 7px;
}

.wiki-entry-detail-image {
