}

.wiki-side-menu-setting {
    width: 100%;

    padding-bottom: 15px;
    margin-bottom: 15px;

    border-bottom: 1px solid #252c34;

    box-sizing: border-box;
}

.wiki-side-menu-label {
    margin-bottom: 9px;

    color: #ffffff;

    font-size: 15px;
    font-weight: bold;
}

.wiki-fish-luck-setting {
    display: flex;
    flex-direction: column;

    gap: 13px;
}

.wiki-setting-field {
    width: 100%;

    display: flex;
    flex-direction: column;

    gap: 5px;

    color: #d8dee8;

    font-size: 12px;
    font-weight: bold;
}

.wiki-setting-select {
    width: 100%;

    padding: 7px 9px;

    background: #101722;

    border: 2px solid #303a48;
    border-radius: 8px;

    color: #ffffff;

    font-family: inherit;
    font-size: 13px;

    box-sizing: border-box;
}

.wiki-setting-select:hover,
.wiki-setting-select:focus {
    border-color: #58aaff;
}
.wiki-display-toggle {
    width: 100%;

    padding: 8px 10px;

    background: #101722;
    border: 2px solid #303a48;
    border-radius: 8px;

    color: #58aaff;

    font-family: inherit;
    font-size: 13px;
    font-weight: bold;

    cursor: pointer;

    box-sizing: border-box;

    transition:
        background 0.15s ease,
        border-color 0.15s ease;
}

.wiki-display-toggle:hover {
    background: #17243a;
    border-color: #58aaff;
}
.wiki-display-status {
    padding: 4px 10px;

    background: #101722;

    border: 2px solid #303a48;
    border-radius: 999px;

    color: #ffffff;

    font-size: 12px;
    font-weight: bold;

    white-space: nowrap;

    box-sizing: border-box;
}
#entry-creator,
#fish-entry-creator {
    width: 100%;
    max-width: 760px;
    margin: 0 auto;
    box-sizing: border-box;
}

.entry-creator {
    width: 100%;
    padding: 16px;

    background: #080c12;
    border: 3px solid #252c34;
    border-radius: 18px;

    color: #ffffff;

    font-family: inherit;

    box-sizing: border-box;
}

.entry-creator-title {
    margin-bottom: 14px;

    color: #ffffff;

    font-size: 24px;
    font-weight: bold;
    line-height: 1.1;
}

.entry-creator-section-title {
    margin: 12px 0 8px;

    color: #4f8cff;

    font-size: 18px;
    font-weight: bold;
    line-height: 1.1;
}

.entry-creator-row {
    width: 100%;

    display: flex;
    flex-direction: column;

    gap: 5px;

    margin-bottom: 12px;

    box-sizing: border-box;
}

.entry-creator-row > label {
    color: #ffffff;

    font-size: 14px;
    font-weight: bold;
}

.entry-creator input[type="text"],
.entry-creator input[type="number"],
.entry-creator input[type="file"],
.entry-creator select,
.entry-creator textarea {
    width: 100%;

    padding: 7px 9px;

    background: #0b1017;
    border: 2px solid #303843;
    border-radius: 7px;

    color: #ffffff;

    font-family: inherit;
    font-size: 14px;

    box-sizing: border-box;

    outline: none;
}

.entry-creator input[type="text"]:focus,
.entry-creator input[type="number"]:focus,
.entry-creator input[type="file"]:focus,
.entry-creator select:focus,
.entry-creator textarea:focus {
    border-color: #58aaff;
}

.entry-creator textarea {
    min-height: 100px;

    resize: vertical;
}

.entry-creator select {
    cursor: pointer;
}

.entry-creator select option {
    background: #0b1017;

    color: #ffffff;
}

.entry-creator button {
    padding: 7px 12px;

    background: #18366f;
    border: 2px solid #58aaff;
    border-radius: 7px;

    color: #ffffff;

    font-family: inherit;
    font-size: 13px;
    font-weight: bold;

    cursor: pointer;

    box-sizing: border-box;
    appearance: none;

    transition:
        background 0.15s ease,
        border-color 0.15s ease,
        transform 0.15s ease;
}

.entry-creator button:hover {
    background: #24509e;

    transform: translateY(-1px);
}

.entry-creator button:disabled {
    opacity: 0.55;

    cursor: default;

    transform: none;
}

.entry-creator-type-section {
    margin-bottom: 14px;
}

.entry-creator-help {
    margin: 4px 0 10px;

    color: #9aa7b8;

    font-size: 12px;
    line-height: 1.35;
}

.entry-creator-file-note {
    margin-top: 4px;

    color: #8f9bad;

    font-size: 11px;
}

.entry-creator-image-options {
    display: flex;
    flex-wrap: wrap;

    gap: 12px;
}

.entry-creator-image-options label {
    display: flex;
    align-items: center;

    gap: 5px;

    color: #ffffff;

    font-size: 12px;

    cursor: pointer;
}

.entry-creator-image-options input[type="radio"] {
    width: auto;
    margin: 0;
}

.entry-creator-preview {
    margin: 8px 0 12px;
}

.entry-creator-preview img {
    display: block;

    width: 90px;
    height: 90px;

    object-fit: contain;

    padding: 5px;

    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 10px;

    box-sizing: border-box;
}

.entry-creator-weights {
    width: 100%;

    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));

    gap: 8px;

    box-sizing: border-box;
}

.entry-creator-weight {
    min-width: 0;

    display: flex;
    flex-direction: column;

    gap: 4px;
}

.entry-creator-weight label {
    color: #ffffff;

    font-size: 12px;
    font-weight: bold;
}

.entry-creator-color-input {
    display: flex;
    align-items: center;

    gap: 7px;
}

.entry-creator-color-input input[type="color"] {
    width: 46px;
    height: 38px;

    flex: 0 0 auto;

    padding: 2px;

    background: #0b1017;
    border: 2px solid #303843;
    border-radius: 7px;

    cursor: pointer;

    box-sizing: border-box;
}

.entry-creator-color-input input[type="text"] {
