    flex: 1;
}

#entryCreatorEditSection {
    padding: 12px;

    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 12px;

    box-sizing: border-box;
}

#entryCreatorEditSection .entry-creator-row {
