    display: flex;
    flex-direction: column;

    gap: 5px;

    color: #d8dee8;

    font-size: 12px;
    font-weight: bold;
}

.wiki-setting-select {
    width: 100%;

    padding: 7px 9px;

    background: #101722;

    border: 2px solid #303a48;
    border-radius: 8px;

    color: #ffffff;

    font-family: inherit;
    font-size: 13px;

    box-sizing: border-box;
}

.wiki-setting-select:hover,
.wiki-setting-select:focus {
    border-color: #58aaff;
}
.wiki-display-toggle {
    width: 100%;

    padding: 8px 10px;

    background: #101722;
    border: 2px solid #303a48;
    border-radius: 8px;

    color: #58aaff;

    font-family: inherit;
    font-size: 13px;
    font-weight: bold;

    cursor: pointer;

    box-sizing: border-box;

    transition:
        background 0.15s ease,
        border-color 0.15s ease;
}

.wiki-display-toggle:hover {
    background: #17243a;
    border-color: #58aaff;
}
.wiki-display-status {
    padding: 4px 10px;

    background: #101722;

    border: 2px solid #303a48;
    border-radius: 999px;

    color: #ffffff;

    font-size: 12px;
    font-weight: bold;

    white-space: nowrap;

    box-sizing: border-box;
}
#entry-creator,
#fish-entry-creator {
    width: 100%;
    max-width: 760px;
    margin: 0 auto;
    box-sizing: border-box;
}

.entry-creator {
    width: 100%;
    padding: 16px;

    background: #080c12;
    border: 3px solid #252c34;
    border-radius: 18px;

    color: #ffffff;

    font-family: inherit;

    box-sizing: border-box;
}

.entry-creator-title {
    margin-bottom: 14px;

    color: #ffffff;

    font-size: 24px;
    font-weight: bold;
    line-height: 1.1;
}

.entry-creator-section-title {
    margin: 12px 0 8px;

    color: #4f8cff;

    font-size: 18px;
    font-weight: bold;
    line-height: 1.1;
}

.entry-creator-row {
    width: 100%;

    display: flex;
    flex-direction: column;

    gap: 5px;

    margin-bottom: 12px;

    box-sizing: border-box;
}

.entry-creator-row > label {
    color: #ffffff;

    font-size: 14px;
    font-weight: bold;
}

.entry-creator input[type="text"],
.entry-creator input[type="number"],
.entry-creator input[type="file"],
.entry-creator select,
.entry-creator textarea {
    width: 100%;

    padding: 7px 9px;

    background: #0b1017;
    border: 2px solid #303843;
    border-radius: 7px;

    color: #ffffff;

    font-family: inherit;
    font-size: 14px;

    box-sizing: border-box;

    outline: none;
}

.entry-creator input[type="text"]:focus,
.entry-creator input[type="number"]:focus,
.entry-creator input[type="file"]:focus,
.entry-creator select:focus,
.entry-creator textarea:focus {
    border-color: #58aaff;
}

.entry-creator textarea {
    min-height: 100px;

    resize: vertical;
}

.entry-creator select {
    cursor: pointer;
}

.entry-creator select option {
    background: #0b1017;

    color: #ffffff;
}

.entry-creator button {
    padding: 7px 12px;

    background: #18366f;
    border: 2px solid #58aaff;
    border-radius: 7px;

    color: #ffffff;

    font-family: inherit;
    font-size: 13px;
    font-weight: bold;

    cursor: pointer;

    box-sizing: border-box;
    appearance: none;

    transition:
        background 0.15s ease,
        border-color 0.15s ease,
        transform 0.15s ease;
}

.entry-creator button:hover {
    background: #24509e;

    transform: translateY(-1px);
}

.entry-creator button:disabled {
    opacity: 0.55;

    cursor: default;

    transform: none;
}

.entry-creator-type-section {
    margin-bottom: 14px;
}

.entry-creator-help {
    margin: 4px 0 10px;

    color: #9aa7b8;

    font-size: 12px;
    line-height: 1.35;
}

.entry-creator-file-note {
    margin-top: 4px;

    color: #8f9bad;

    font-size: 11px;
}

.entry-creator-image-options {
    display: flex;
    flex-wrap: wrap;

    gap: 12px;
}

.entry-creator-image-options label {
    display: flex;
    align-items: center;

    gap: 5px;

    color: #ffffff;

    font-size: 12px;

    cursor: pointer;
}

.entry-creator-image-options input[type="radio"] {
    width: auto;
    margin: 0;
}

.entry-creator-preview {
    margin: 8px 0 12px;
}

.entry-creator-preview img {
    display: block;

    width: 90px;
    height: 90px;

    object-fit: contain;

    padding: 5px;

    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 10px;

    box-sizing: border-box;
}

.entry-creator-weights {
    width: 100%;

    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));

    gap: 8px;

    box-sizing: border-box;
}

.entry-creator-weight {
    min-width: 0;

    display: flex;
    flex-direction: column;

    gap: 4px;
}

.entry-creator-weight label {
    color: #ffffff;

    font-size: 12px;
    font-weight: bold;
}

.entry-creator-color-input {
    display: flex;
    align-items: center;

    gap: 7px;
}

.entry-creator-color-input input[type="color"] {
    width: 46px;
    height: 38px;

    flex: 0 0 auto;

    padding: 2px;

    background: #0b1017;
    border: 2px solid #303843;
    border-radius: 7px;

    cursor: pointer;

    box-sizing: border-box;
}

.entry-creator-color-input input[type="text"] {
    min-width: 0;

    flex: 1;
}

#entryCreatorEditSection {
    padding: 12px;

    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 12px;

    box-sizing: border-box;
}

#entryCreatorEditSection .entry-creator-row {
    max-width: 300px;
}

.entry-creator-edit-list {
    display: flex;
    flex-direction: column;

    gap: 4px;

    width: 250px;
    max-width: 100%;

    max-height: 156px;

    margin: 4px 0 8px;

    overflow-y: auto;
    overflow-x: hidden;

    box-sizing: border-box;
}

.entry-creator-edit-item {
    display: block;

    width: 100%;
    min-height: 28px;

    flex: 0 0 auto;

    padding: 5px 8px !important;

    background: #151b24 !important;
    border: 1px solid #353e4a !important;
    border-radius: 5px !important;

    color: #ffffff !important;

    font-size: 12px !important;
    font-weight: normal !important;

    line-height: 1.2;

    text-align: left;

    box-sizing: border-box;

    transform: none !important;
}

.entry-creator-edit-item:hover {
    background: #202b3a !important;
    border-color: #58aaff !important;
}

.entry-creator-edit-item.entry-active {
    background: #18366f !important;
    border-color: #58aaff !important;
}

.entry-creator-edit-list::-webkit-scrollbar {
    width: 6px;
}

.entry-creator-edit-list::-webkit-scrollbar-track {
    background: #0b1017;

    border-radius: 999px;
}

.entry-creator-edit-list::-webkit-scrollbar-thumb {
    background: #3b4655;

    border-radius: 999px;
}

.entry-creator-edit-list::-webkit-scrollbar-thumb:hover {
    background: #536176;
}

.entry-creator-edit-selected {
    width: 250px;
    max-width: 100%;

    margin: 5px 0 8px;

    color: #70b9ff;

    font-size: 12px;
    font-weight: bold;

    overflow-wrap: anywhere;
}

#entryCreatorLoad {
    width: auto;

    margin-top: 2px;
}

#entryCreatorSubmit {
    min-width: 150px;

    margin-top: 10px;

    padding: 9px 15px;

    font-size: 14px;
}

.entry-creator-status {
    margin-top: 10px;

    font-size: 12px;
    line-height: 1.4;

    overflow-wrap: anywhere;
}

.entry-creator-status-error,
.entry-creator-error {
    color: #ff7070;
}

.entry-creator-status-success {
    color: #70e59b;
}

.entry-creator-status-success a {
    color: #70b9ff;
}

@media (max-width: 600px) {

    .entry-creator {
        padding: 12px;

        border-radius: 14px;
    }

    .entry-creator-title {
        font-size: 20px;
    }

    .entry-creator-section-title {
        font-size: 16px;
    }

    .entry-creator-weights {
        grid-template-columns: 1fr;
    }

    .entry-creator-edit-list {
        width: 220px;
    }

    .entry-creator-edit-selected {
        width: 220px;
    }

}

@media (max-width: 400px) {

    .entry-creator {
        padding: 9px;
    }

    #entryCreatorEditSection {
        padding: 9px;
    }

    .entry-creator-edit-list,
    .entry-creator-edit-selected {
        width: 100%;
    }

    .entry-creator-image-options {
        flex-direction: column;

        gap: 7px;
    }

}
.entry-creator-description-help {
    margin-top: 4px;

    color: #8f9bad;

    font-size: 11px;
    font-style: italic;
}
.wiki-bait-select-button {
    width: 100%;

    display: flex;
    align-items: center;

    gap: 8px;

    padding: 7px 9px;

    background: #101722;

    border: 2px solid #303a48;
    border-radius: 8px;

    color: #ffffff;

    font-family: inherit;
    font-size: 13px;

    cursor: pointer;

    box-sizing: border-box;
}

.wiki-bait-select-button:hover {
    border-color: #58aaff;
}

.wiki-bait-select-image {
    width: 30px;
    height: 30px;

    object-fit: contain;
}

.wiki-bait-picker {
    width: 100%;

    max-height: 220px;

    padding: 7px;

    background: #080c12;

    border: 2px solid #303a48;
    border-radius: 8px;

    overflow-y: auto;

    box-sizing: border-box;
}

.wiki-bait-picker-grid {
    display: grid;

    grid-template-columns:
        repeat(2, minmax(0, 1fr));

    gap: 6px;
}

.wiki-bait-picker-card {
    min-width: 0;

    padding: 7px 4px;

    display: flex;
    flex-direction: column;
    align-items: center;

    gap: 4px;

    background: #101722;

    border: 2px solid #252c34;
    border-radius: 8px;

    color: #ffffff;

    font-family: inherit;
    font-size: 10px;
    font-weight: bold;

    cursor: pointer;

    box-sizing: border-box;
}

.wiki-bait-picker-card:hover {
    background: #17243a;
    border-color: #58aaff;
}

.wiki-bait-picker-card img {
    width: 42px;
    height: 42px;

    object-fit: contain;
}

.wiki-bait-picker-card span {
    max-width: 100%;

    text-align: center;

    overflow-wrap: break-word;
}

.wiki-bait-picker-loading {
