#entry-creator,
#fish-entry-creator {
    width: 100%;
    max-width: 760px;
    margin: 0 auto;
    box-sizing: border-box;
}

.entry-creator {
    width: 100%;
    padding: 16px;

    background: #080c12;
    border: 3px solid #252c34;
    border-radius: 18px;

    color: #ffffff;

    font-family: inherit;

    box-sizing: border-box;
}

.entry-creator-title {
    margin-bottom: 14px;

    color: #ffffff;

    font-size: 24px;
    font-weight: bold;
    line-height: 1.1;
}

.entry-creator-section-title {
    margin: 12px 0 8px;

    color: #4f8cff;

    font-size: 18px;
    font-weight: bold;
    line-height: 1.1;
}

.entry-creator-row {
    width: 100%;

    display: flex;
    flex-direction: column;

    gap: 5px;

    margin-bottom: 12px;

    box-sizing: border-box;
}

.entry-creator-row > label {
    color: #ffffff;

    font-size: 14px;
    font-weight: bold;
}

.entry-creator input[type="text"],
.entry-creator input[type="number"],
.entry-creator input[type="file"],
.entry-creator select,
.entry-creator textarea {
    width: 100%;

    padding: 7px 9px;

    background: #0b1017;
    border: 2px solid #303843;
    border-radius: 7px;

    color: #ffffff;

    font-family: inherit;
    font-size: 14px;

    box-sizing: border-box;

    outline: none;
}

.entry-creator input[type="text"]:focus,
.entry-creator input[type="number"]:focus,
.entry-creator input[type="file"]:focus,
.entry-creator select:focus,
.entry-creator textarea:focus {
    border-color: #58aaff;
}

.entry-creator textarea {
    min-height: 100px;

    resize: vertical;
}

.entry-creator select {
    cursor: pointer;
}

.entry-creator select option {
    background: #0b1017;

    color: #ffffff;
}

.entry-creator button {
    padding: 7px 12px;

    background: #18366f;
    border: 2px solid #58aaff;
    border-radius: 7px;

    color: #ffffff;

    font-family: inherit;
    font-size: 13px;
    font-weight: bold;

    cursor: pointer;

    box-sizing: border-box;
    appearance: none;

    transition:
        background 0.15s ease,
        border-color 0.15s ease,
        transform 0.15s ease;
}

.entry-creator button:hover {
    background: #24509e;

    transform: translateY(-1px);
}

.entry-creator button:disabled {
    opacity: 0.55;

    cursor: default;

    transform: none;
}

.entry-creator-type-section {
    margin-bottom: 14px;
}

.entry-creator-help {
    margin: 4px 0 10px;

    color: #9aa7b8;

    font-size: 12px;
    line-height: 1.35;
}

.entry-creator-file-note {
    margin-top: 4px;

    color: #8f9bad;

    font-size: 11px;
}

.entry-creator-image-options {
    display: flex;
    flex-wrap: wrap;

    gap: 12px;
}

.entry-creator-image-options label {
    display: flex;
    align-items: center;

    gap: 5px;

    color: #ffffff;

    font-size: 12px;

    cursor: pointer;
}

.entry-creator-image-options input[type="radio"] {
    width: auto;
    margin: 0;
}

.entry-creator-preview {
    margin: 8px 0 12px;
}

