var currentPage = mw.config.get('wgPageName');

if (currentPage === 'Fish_page:sandbox') {
    importScript('MediaWiki:EntryCreator.js');
    importStylesheet('MediaWiki:EntryCreator.css');
}

if (currentPage === 'Fish_entries:sandbox') {
    importScript('MediaWiki:FishEntries.js');
    importStylesheet('MediaWiki:FishEntriesSandbox.css');
}

/* --- Cursor card preview area (2x2 image grid) --- */
.citizen-preferences-card__preview--cursors {
	display: grid;
	grid-template-columns: 1fr 1fr;
	grid-template-rows: 1fr 1fr;
	width: 100%;
	aspect-ratio: 1 / 1;
	gap: 2px;
	padding: 4px;
	background: var( --color-surface-2, #eaecf0 );
	border-bottom: var( --border-subtle, 1px solid #c8ccd1 );
}

.citizen-preferences-card__preview--cursors img {
	display: block;
	width: 100%;
	height: 100%;
	object-fit: contain;
	image-rendering: auto;
	border-radius: 3px;
}

/* "None" card – no preview, slightly taller label */
.citizen-preferences-card--none .citizen-preferences-card__label {
	padding-block: var( --space-md, 16px );
	font-size: var( --font-size-base, 16px );
}

/* --- Card selection highlight (already handled by Citizen) --- */
/* Border radius override for cursor cards */
.citizen-preferences-card {
	border-radius: var( --border-radius-large, 12px );
}

/* --- Apply cursors on selection --- */
/* NOTE: replace the image URLs below with your uploaded cursor files */

html.cursor-clientpref-retro {
	cursor: url("/wiki/Special:FilePath/Cursor-retro-arrow.png") 0 0, auto;
}

html.cursor-clientpref-pixel {
	cursor: url("/wiki/Special:FilePath/Cursor-pixel-arrow.png") 0 0, auto;
}

html.cursor-clientpref-modern {
	cursor: url("/wiki/Special:FilePath/Cursor-modern-arrow.png") 0 0, auto;
}

html.cursor-clientpref-sleek {
	cursor: url("/wiki/Special:FilePath/Cursor-sleek-arrow.png") 0 0, auto;
}

/* --- Hover / pointer cursor variations --- */
html.cursor-clientpref-retro a:hover,
html.cursor-clientpref-retro button:hover,
html.cursor-clientpref-retro .cdx-button:hover {
	cursor: url("/wiki/Special:FilePath/Cursor-retro-pointer.png") 2 0, pointer;
}

html.cursor-clientpref-pixel a:hover,
html.cursor-clientpref-pixel button:hover,
html.cursor-clientpref-pixel .cdx-button:hover {
	cursor: url("/wiki/Special:FilePath/Cursor-pixel-pointer.png") 2 0, pointer;
}

