// Cursor preferences
(function () {
	'use strict';

	/* --- CONFIG --- */
	var DEFAULT_CURSOR = 'futura';

	var CURSOR_GROUPS = {
		none: {
			label: 'None',
			images: []
		},
		futura: {
			label: 'Futura',
			images: [
				'https://static.wikitide.net/upgradexwiki/0/0f/Futura_Cursor.webp',
				'https://static.wikitide.net/upgradexwiki/8/8b/Futura_Pointer.webp',
				'https://static.wikitide.net/upgradexwiki/c/c9/Futura_Textline.webp',
				'https://static.wikitide.net/upgradexwiki/b/b7/Futura_Movement.webp'
			]
		}
	};

	if (!CURSOR_GROUPS[DEFAULT_CURSOR]) {
		DEFAULT_CURSOR = 'none';
	}

	/* --- Register --- */
	var cursorKeys = Object.keys(CURSOR_GROUPS);
	var options = cursorKeys.map(function (key) {
		return {
			value: key,
			label: CURSOR_GROUPS[key].label || key
		};
	});

	var columns = options.length > 6 ? 3 : 2;

	mw.hook('citizen.preferences.register').add(function (register) {
		register({
			sections: {
				cursors: { label: 'Cursors' }
			},
			preferences: {
				cursor: {
					section: 'cursors',
					type: 'radio',
					columns: columns,
					options: options,
					default: DEFAULT_CURSOR,
					visibilityCondition: 'always'
				}
			}
		});
	});

	/* --- 2x2 image preview injection --- */
	function injectCursorPreview(cardEl, images) {
		if (cardEl.querySelector('.citizen-preferences-card__preview--cursors')) {
			return;
		}

		var previewEl = document.createElement('span');
		previewEl.className = 'citizen-preferences-card__preview citizen-preferences-card__preview--cursors';

		images.forEach(function (src) {
			var img = document.createElement('img');
			img.src = src;
			img.alt = '';
			img.loading = 'lazy';
			previewEl.appendChild(img);
		});

		cardEl.insertBefore(previewEl, cardEl.firstChild);
	}

	function injectAllCursorPreviews() {
		var contentEl = document.getElementById('citizen-preferences-content');
		if (!contentEl) {
			return;
		}

		var radios = contentEl.querySelectorAll('#skin-client-prefs-cursor .cdx-radio');

		radios.forEach(function (radio) {
			var input = radio.querySelector('input[type="radio"]');
			if (!input) return;

			var cardEl = radio.querySelector('.citizen-preferences-card');
			if (!cardEl) return;

			var value = input.value;
			var group = CURSOR_GROUPS[value];

			if (group && group.images && group.images.length) {
				injectCursorPreview(cardEl, group.images);
			}

			if (value === 'none') {
				cardEl.classList.add('citizen-preferences-card--none');
			}
		});
	}

	/* --- Dynamically apply cursor CSS (no manual CSS rules needed) --- */
	var cursorStyleEl = document.createElement('style');
	cursorStyleEl.id = 'citizen-cursor-style';
	document.head.appendChild(cursorStyleEl);

	function applyCursorCSS(value) {
		if (value === 'none') {
			cursorStyleEl.textContent = '';
			return;
		}

		var group = CURSOR_GROUPS[value];
		if (!group || !group.images || group.images.length < 4) {
			return;
		}

		var arrow  = group.images[0];
		var pointer = group.images[1];
		var text    = group.images[2];
		var move    = group.images[3];

		cursorStyleEl.textContent = [
			'/* ' + (group.label || value) + ' cursors */',
			'html { cursor: url("' + arrow + '") 0 0, auto; }',
			'a:hover, button:hover, [role="button"]:hover, .cdx-button:hover,' +
				'input[type="submit"]:hover, input[type="reset"]:hover' +
				' { cursor: url("' + pointer + '") 2 0, pointer; }',
			'input[type="text"]:not(:read-only), textarea:not(:read-only),' +
				'[contenteditable="true"]' +
				' { cursor: url("' + text + '") 0 0, text; }',
			'.draggable, [draggable="true"]' +
				' { cursor: url("' + move + '") 0 0, move; }'
		].join('\n');
	}

	/* --- Apply on selection change --- */
	mw.hook('citizen.preferences.changed').add(function (featureName, value) {
		if (featureName === 'cursor') {
			applyCursorCSS(value);
		}
	});

	/* --- Apply default on first load --- */
	// Citizen applies 'default' on first visit via the 'default' field,
	// but if no value is stored yet, it won't fire 'changed'. Handle that:
	mw.loader.using('skins.citizen.preferences').then(function () {
		var clientPrefs = require('./clientPrefs.polyfill.js')();
		var stored = clientPrefs.get('cursor');
		applyCursorCSS(stored || DEFAULT_CURSOR);
	});

	/* --- DOM observer (panel is lazy-loaded) --- */
	var injectionObserver = new MutationObserver(function () {
		injectAllCursorPreviews();
	});

	function startObserving() {
		var contentEl = document.getElementById('citizen-preferences-content');
		if (contentEl) {
			injectionObserver.observe(contentEl, { childList: true, subtree: true });
			injectAllCursorPreviews();
			return true;
		}
		return false;
	}

	if (!startObserving()) {
		var bodyObserver = new MutationObserver(function () {
			if (startObserving()) {
				bodyObserver.disconnect();
			}
		});
		bodyObserver.observe(document.body, { childList: true, subtree: true });
	}

})();

