				'https://static.wikitide.net/upgradexwiki/8/8b/Futura_Pointer.webp',
				'https://static.wikitide.net/upgradexwiki/c/c9/Futura_Textline.webp',
				'https://static.wikitide.net/upgradexwiki/b/b7/Futura_Movement.webp'
			]
		}
	};

	if (!CURSOR_GROUPS[DEFAULT_CURSOR]) {
		DEFAULT_CURSOR = 'none';
	}

	var options = Object.keys(CURSOR_GROUPS).map(function (key) {
		return {
			value: key,
			label: CURSOR_GROUPS[key].label
		};
	});

	/* Register the preference */
	mw.hook('citizen.preferences.register').add(function (register) {
		register({
			sections: {
				cursors: {
					label: 'Cursors'
				}
			},
			preferences: {
				cursor: {
					section: 'cursors',
					type: 'radio',
					columns: 2,
					options: options,
					default: DEFAULT_CURSOR
				}
			}
		});
	});

	/* Runtime cursor styles */
	var cursorStyle = document.createElement('style');
	cursorStyle.id = 'citizen-cursor-runtime-style';
	(document.head || document.documentElement).appendChild(cursorStyle);

	function escapeUrl(url) {
		return String(url)
			.replace(/\\/g, '\\\\')
			.replace(/"/g, '\\"');
	}

	function cursorValue(url, fallback) {
		return 'url("' + escapeUrl(url) + '") 0 0, ' + fallback;
	}

	function applyCursor(value) {
		var group = CURSOR_GROUPS[value];

		document.documentElement.style.removeProperty('cursor');

		if (!group || value === 'none' || !group.images.length) {
			cursorStyle.textContent = '';
			return;
		}

		var arrow = cursorValue(group.images[0], 'auto');
		var pointer = cursorValue(group.images[1] || group.images[0], 'pointer');
		var text = cursorValue(group.images[2] || group.images[0], 'text');
		var movement = cursorValue(group.images[3] || group.images[0], 'move');

		cursorStyle.textContent = [
			'html, html * { cursor: ' + arrow + ' !important; }',
			'html a, html button, html summary, html select,',
			'html [role="button"], html .cdx-button,',
			'html input[type="submit"], html input[type="button"],',
			'html #skin-client-prefs-cursor .cdx-radio {',
			'cursor: ' + pointer + ' !important;',
			'}',
			'html input[type="text"], html input[type="search"],',
			'html input[type="email"], html input[type="url"],',
			'html input[type="password"], html textarea,',
			'html [contenteditable="true"] {',
			'cursor: ' + text + ' !important;',
			'}',
			'html [draggable="true"] {',
			'cursor: ' + movement + ' !important;',
			'}'
		].join('\n');
	}

	function setCursor(value) {
		if (!CURSOR_GROUPS[value]) {
			return;
		}

		applyCursor(value);
	}

	/* Apply the selected cursor whenever Citizen changes it */
	mw.hook('citizen.preferences.changed').add(function (featureName, value) {
		if (featureName === 'cursor') {
			setCursor(value);
		}
	});

	/* Backup listener so switching updates immediately */
	document.addEventListener('change', function (event) {
		var input = event.target;

		if (
			input &&
			input.matches &&
			input.matches('#skin-client-prefs-cursor input[type="radio"]')
		) {
			setCursor(input.value);
		}
	});

	/* Add the 2x2 previews and move titles above the image card */
	function injectPreviews() {
		var content = document.getElementById('citizen-preferences-content');

		if (!content) {
			return;
		}

		content.querySelectorAll(
			'#skin-client-prefs-cursor .cdx-radio'
		).forEach(function (radio) {
			var input = radio.querySelector('input[type="radio"]');
			var card = radio.querySelector('.citizen-preferences-card');

			if (!input || !card) {
				return;
			}

			var value = input.value;
			var group = CURSOR_GROUPS[value];

			if (!group) {
				return;
			}

			radio.classList.add('citizen-cursor-option');
			card.classList.add('citizen-preferences-card--cursor');

			if (value === 'none') {
				radio.classList.add('citizen-cursor-option--none');
				card.classList.add('citizen-preferences-card--cursor-none');
				return;
			}

			/* Move the title outside and above the square card */
			var label = card.querySelector('.citizen-preferences-card__label');
			var parent = card.parentElement;

			if (
				label &&
				parent &&
				!parent.querySelector('.citizen-cursor-card-title')
			) {
				label.className = 'citizen-cursor-card-title';
				parent.insertBefore(label, card);
			}

			if (
				card.querySelector(
					'.citizen-preferences-card__preview--cursors'
				)
			) {
				return;
			}

			var preview = document.createElement('span');
			preview.className =
				'citizen-preferences-card__preview ' +
				'citizen-preferences-card__preview--cursors';
			preview.setAttribute('aria-hidden', 'true');

			group.images.slice(0, 4).forEach(function (src) {
				var image = document.createElement('img');
				image.src = src;
				image.alt = '';
				image.draggable = false;
				image.loading = 'lazy';
				preview.appendChild(image);
			});

			card.appendChild(preview);
		});
	}

	var observer = new MutationObserver(injectPreviews);

	function observePreferences() {
		var content = document.getElementById(
			'citizen-preferences-content'
		);

		if (!content) {
			return false;
		}

		observer.observe(content, {
			childList: true,
			subtree: true
		});

		injectPreviews();
		return true;
	}

	if (!observePreferences()) {
		var bodyObserver = new MutationObserver(function () {
			if (observePreferences()) {
				bodyObserver.disconnect();
			}
		});

		bodyObserver.observe(document.body, {
			childList: true,
			subtree: true
		});
	}

	/* Apply the default on the current page */
	applyCursor(DEFAULT_CURSOR);
})();

