			images: []
		},

		futura: {
			label: 'Futura',

			// Preview images
			images: [
				'https://static.wikitide.net/upgradexwiki/0/0f/Futura_Cursor.webp',
				'https://static.wikitide.net/upgradexwiki/8/8b/Futura_Pointer.webp',
				'https://static.wikitide.net/upgradexwiki/c/c9/Futura_Textline.webp',
				'https://static.wikitide.net/upgradexwiki/b/b7/Futura_Movement.webp'
			],

			// Upload these files as 64x64 PNG or CUR files
			cursorImages: [
				'https://static.wikitide.net/upgradexwiki/d/d9/Futura_Cursor_64.png',
				'https://static.wikitide.net/upgradexwiki/7/78/Futura_Pointer_64.png',
				'https://static.wikitide.net/upgradexwiki/1/19/Futura_Textline_64.png',
				'https://static.wikitide.net/upgradexwiki/2/22/Futura_Movement_64.png'
			]
		}
	};

	if (!CURSOR_GROUPS[DEFAULT_CURSOR]) {
		DEFAULT_CURSOR = 'none';
	}

	function validCursor(value) {
		return Object.prototype.hasOwnProperty.call(
			CURSOR_GROUPS,
			value
		);
	}

	function readStoredCursor() {
		var stored = '';
		var match;

		try {
			stored = mw.storage.get('mwclientpreferences') || '';
		} catch (e) {
			stored = '';
		}

		match = /(?:^|,)cursor-clientpref-([A-Za-z0-9]+)(?:,|$)/.exec(
			stored
		);

		if (match && validCursor(match[1])) {
			return match[1];
		}

		match = /(?:^|\s)cursor-clientpref-([A-Za-z0-9]+)(?:\s|$)/.exec(
			document.documentElement.className
		);

		if (match && validCursor(match[1])) {
			return match[1];
		}

		return null;
	}

	function saveCursor(value) {
		var stored = '';
		var entries = [];

		try {
			stored = mw.storage.get('mwclientpreferences') || '';

			stored.split(',').forEach(function (entry) {
				var match = /^([\w-]+)-clientpref-(\w+)$/.exec(entry);

				if (match && match[1] !== 'cursor') {
					entries.push(entry);
				}
			});

			entries.push('cursor-clientpref-' + value);
			mw.storage.set(
				'mwclientpreferences',
				entries.join(',')
			);
		} catch (e) {
			// Citizen will save it when the preference panel is open.
		}
	}

	function setCursorClass(value) {
		Array.prototype.slice
			.call(document.documentElement.classList)
			.forEach(function (className) {
				if (/^cursor-clientpref-[A-Za-z0-9]+$/.test(className)) {
