			subtree: true
		});
	}
})();

(function () {
	'use strict';

	var DEFAULT_CURSOR = 'futura';
	var STORAGE_KEY = 'citizen-cursor-pack';

	var CURSOR_GROUPS = {
		none: {
			label: 'None',
			images: []
		},

		futura: {
			label: 'Futura',

			// Large preview images
			images: [
				'https://static.wikitide.net/upgradexwiki/0/0f/Futura_Cursor.webp',
				'https://static.wikitide.net/upgradexwiki/8/8b/Futura_Pointer.webp',
				'https://static.wikitide.net/upgradexwiki/c/c9/Futura_Textline.webp',
				'https://static.wikitide.net/upgradexwiki/b/b7/Futura_Movement.webp'
			],

			// Small actual cursor images
			cursorImages: [
				'/wiki/Special:FilePath/Futura_Cursor_64.png',
				'/wiki/Special:FilePath/Futura_Pointer_64.png',
				'/wiki/Special:FilePath/Futura_Textline_64.png',
				'/wiki/Special:FilePath/Futura_Movement_64.png'
			]
		}
	};

	if (!CURSOR_GROUPS[DEFAULT_CURSOR]) {
		DEFAULT_CURSOR = 'none';
	}

	function isValidCursor(value) {
		return Object.prototype.hasOwnProperty.call(
			CURSOR_GROUPS,
			value
		);
	}

	function getSavedCursor() {
		var saved = null;
		var match;

		try {
			saved = localStorage.getItem(STORAGE_KEY);
		} catch (e) {
			saved = null;
		}

		if (saved && isValidCursor(saved)) {
			return saved;
		}

		match = /(?:^|\s)cursor-clientpref-([A-Za-z0-9]+)(?:\s|$)/.exec(
			document.documentElement.className
		);

		if (match && isValidCursor(match[1])) {
			return match[1];
		}

		return null;
	}

	function saveCursor(value) {
		try {
			localStorage.setItem(STORAGE_KEY, value);
		} catch (e) {
			// Ignore storage errors.
		}
	}

	function setHtmlCursorClass(value) {
		Array.prototype.slice
			.call(document.documentElement.classList)
			.forEach(function (className) {
				if (/^cursor-clientpref-[A-Za-z0-9]+$/.test(className)) {
					document.documentElement.classList.remove(className);
				}
			});

		document.documentElement.classList.add(
			'cursor-clientpref-' + value
		);
	}

	function clearBodyCursor() {
		if (!document.body) {
			return;
		}

		document.body.classList.remove('citizen-cursor-on');

		Array.prototype.slice
			.call(document.body.classList)
			.forEach(function (className) {
				if (/^citizen-cursor-pack-[A-Za-z0-9]+$/.test(className)) {
					document.body.classList.remove(className);
				}
			});

		[
			'--citizen-cursor-arrow',
			'--citizen-cursor-pointer',
			'--citizen-cursor-text',
			'--citizen-cursor-movement'
		].forEach(function (property) {
			document.body.style.removeProperty(property);
		});
