		return 'url("' + escapeUrl(url) + '") 0 0, ' + fallback;
	}

	function applyCursor(value, shouldSave) {
		var group;
		var cursors;

		if (!isValidCursor(value)) {
			value = 'none';
		}

		group = CURSOR_GROUPS[value];

		setHtmlCursorClass(value);

		if (shouldSave) {
			saveCursor(value);
		}

		clearBodyCursor();

		if (
			!document.body ||
			value === 'none' ||
			!group.cursorImages ||
			!group.cursorImages.length
		) {
			updateSelectedCard(value);
			return;
		}

		cursors = group.cursorImages;

		document.body.classList.add('citizen-cursor-on');
		document.body.classList.add('citizen-cursor-pack-' + value);

		document.body.style.setProperty(
			'--citizen-cursor-arrow',
			cursorValue(cursors[0], 'auto')
		);

		document.body.style.setProperty(
			'--citizen-cursor-pointer',
			cursorValue(cursors[1] || cursors[0], 'pointer')
		);

		document.body.style.setProperty(
			'--citizen-cursor-text',
			cursorValue(cursors[2] || cursors[0], 'text')
		);

		document.body.style.setProperty(
			'--citizen-cursor-movement',
			cursorValue(cursors[3] || cursors[0], 'move')
		);

		updateSelectedCard(value);
	}

	function updateSelectedCard(value) {
