					);

					radio.style.gridColumn = '1 / -1';

					[
						radio,
						radio.querySelector('.cdx-radio__wrapper'),
						radio.querySelector('.cdx-label'),
						radio.querySelector('.cdx-label__label'),
						card
					].forEach(function (element) {
						if (element) {
							element.style.height = '52px';
							element.style.minHeight = '52px';
							element.style.maxHeight = '52px';
						}
					});

					return;
				}

				var label = card.querySelector(
					'.citizen-preferences-card__label'
				);
				var parent = card.parentElement;

				if (
					label &&
					parent &&
					!parent.querySelector(
						'.citizen-cursor-card-title'
					)
				) {
					label.className =
						'citizen-cursor-card-title';
