		try {
			saved = localStorage.getItem(STORAGE_KEY);
		} catch (e) {
			saved = null;
		}

		if (saved && isValidCursor(saved)) {
			return saved;
		}

		match = /(?:^|\s)cursor-clientpref-([A-Za-z0-9]+)(?:\s|$)/.exec(
			document.documentElement.className
		);

		if (match && isValidCursor(match[1])) {
			return match[1];
		}

		return null;
	}

	function saveCursor(value) {
		try {
			localStorage.setItem(STORAGE_KEY, value);
		} catch (e) {
			// Ignore storage errors.
		}
	}

	function setHtmlCursorClass(value) {
		Array.prototype.slice
			.call(document.documentElement.classList)
			.forEach(function (className) {
				if (/^cursor-clientpref-[A-Za-z0-9]+$/.test(className)) {
					document.documentElement.classList.remove(className);
				}
			});

		document.documentElement.classList.add(
			'cursor-clientpref-' + value
		);
	}

	function clearBodyCursor() {
		if (!document.body) {
			return;
		}

		document.body.classList.remove('citizen-cursor-on');

		Array.prototype.slice
			.call(document.body.classList)
			.forEach(function (className) {
				if (/^citizen-cursor-pack-[A-Za-z0-9]+$/.test(className)) {
					document.body.classList.remove(className);
				}
			});

		[
			'--citizen-cursor-arrow',
			'--citizen-cursor-pointer',
			'--citizen-cursor-text',
			'--citizen-cursor-movement'
		].forEach(function (property) {
			document.body.style.removeProperty(property);
		});
	}

	function escapeUrl(url) {
		return String(url)
			.replace(/\\/g, '\\\\')
			.replace(/"/g, '\\"');
	}

	function cursorValue(url, fallback) {
		return 'url("' + escapeUrl(url) + '") 0 0, ' + fallback;
	}

	function resizeCursorImage(url) {
		return new Promise(function (resolve, reject) {
			var image = new Image();
			var canvas;
			var context;

			image.crossOrigin = 'anonymous';

			image.onload = function () {
				try {
					canvas = document.createElement('canvas');
					canvas.width = CURSOR_SIZE;
					canvas.height = CURSOR_SIZE;

					context = canvas.getContext('2d');
					context.clearRect(0, 0, CURSOR_SIZE, CURSOR_SIZE);
					context.drawImage(
						image,
						0,
						0,
						CURSOR_SIZE,
						CURSOR_SIZE
					);

					resolve(canvas.toDataURL('image/png'));
				} catch (error) {
					reject(error);
				}
			};

			image.onerror = reject;
			image.src = url;
		});
	}

	function setCursorVariables(cursors) {
		if (!document.body || !cursors.length) {
			return;
		}

		document.body.style.setProperty(
			'--citizen-cursor-arrow',
			cursorValue(cursors[0], 'auto')
		);

		document.body.style.setProperty(
			'--citizen-cursor-pointer',
			cursorValue(cursors[1] || cursors[0], 'pointer')
		);

		document.body.style.setProperty(
			'--citizen-cursor-text',
			cursorValue(cursors[2] || cursors[0], 'text')
		);

		document.body.style.setProperty(
			'--citizen-cursor-movement',
			cursorValue(cursors[3] || cursors[0], 'move')
		);
	}

	function applyCursor(value, shouldSave) {
		var group;
		var cursors;
		var request;

		if (!isValidCursor(value)) {
			value = 'none';
		}

		group = CURSOR_GROUPS[value];
		request = ++cursorRequest;

		setHtmlCursorClass(value);

		if (shouldSave) {
			saveCursor(value);
		}

		clearBodyCursor();

		if (
			!document.body ||
			value === 'none' ||
			!group.cursorImages ||
			!group.cursorImages.length
		) {
			updateSelectedCard(value);
			return;
		}

		cursors = group.cursorImages;

		document.body.classList.add('citizen-cursor-on');
		document.body.classList.add('citizen-cursor-pack-' + value);

		// Immediate fallback.
		setCursorVariables(cursors);

		// Resize images to a browser-safe cursor size.
		Promise.all(
			cursors.slice(0, 4).map(function (url) {
				return resizeCursorImage(url).catch(function () {
					return url;
				});
			})
		).then(function (resizedCursors) {
			if (request === cursorRequest) {
				setCursorVariables(resizedCursors);
			}
		});

		updateSelectedCard(value);
	}

	function updateSelectedCard(value) {
		var content = document.getElementById(
			'citizen-preferences-content'
		);

		if (!content) {
			return;
		}

		value = value || getSavedCursor() || DEFAULT_CURSOR;

		Array.prototype.slice
			.call(
				content.querySelectorAll(
					'#skin-client-prefs-cursor .citizen-cursor-option'
				)
			)
			.forEach(function (radio) {
				var input = radio.querySelector(
					'input[type="radio"]'
				);

				radio.classList.toggle(
					'citizen-cursor-option--selected',
					!!input && input.value === value
				);
			});
	}

	var options = Object.keys(CURSOR_GROUPS).map(function (key) {
		return {
			value: key,
			label: CURSOR_GROUPS[key].label
		};
	});

	mw.hook('citizen.preferences.register').add(function (register) {
		register({
			sections: {
				cursors: {
					label: 'Cursors'
				}
			},
			preferences: {
				cursor: {
					section: 'cursors',
					type: 'radio',
					columns: 2,
					options: options,
					default: DEFAULT_CURSOR
				}
			}
		});
	});

	mw.hook('citizen.preferences.changed').add(function (
		featureName,
		value
	) {
		if (featureName === 'cursor') {
			applyCursor(value, true);
		}
	});

	document.addEventListener('change', function (event) {
		var input = event.target;

		if (
			input &&
			input.matches &&
			input.matches(
				'#skin-client-prefs-cursor input[type="radio"]'
			)
		) {
			applyCursor(input.value, true);
		}
	});

	function injectPreviews() {
		var content = document.getElementById(
			'citizen-preferences-content'
		);

		if (!content) {
			return;
		}

		Array.prototype.slice
			.call(
				content.querySelectorAll(
					'#skin-client-prefs-cursor .cdx-radio'
				)
			)
			.forEach(function (radio) {
				var input = radio.querySelector(
					'input[type="radio"]'
				);
				var card = radio.querySelector(
					'.citizen-preferences-card'
				);

				if (!input || !card) {
					return;
				}

				var value = input.value;
				var group = CURSOR_GROUPS[value];

				if (!group) {
					return;
				}

				radio.classList.add('citizen-cursor-option');
				card.classList.add(
					'citizen-preferences-card--cursor'
				);

				if (value === 'none') {
					radio.classList.add(
						'citizen-cursor-option--none'
					);
					card.classList.add(
						'citizen-preferences-card--cursor-none'
					);
					radio.style.gridColumn = '1 / -1';
					return;
				}

				var label = card.querySelector(
					'.citizen-preferences-card__label'
				);
				var parent = card.parentElement;

				if (
					label &&
					parent &&
					!parent.querySelector(
						'.citizen-cursor-card-title'
					)
				) {
					label.className =
						'citizen-cursor-card-title';
					parent.insertBefore(label, card);
				}

				if (
					card.querySelector(
						'.citizen-preferences-card__preview--cursors'
					)
				) {
					return;
				}

				var preview = document.createElement('span');

				preview.className =
					'citizen-preferences-card__preview ' +
					'citizen-preferences-card__preview--cursors';

				preview.setAttribute('aria-hidden', 'true');

				group.images.forEach(function (src) {
					var image = document.createElement('img');

					image.src = src;
					image.alt = '';
					image.loading = 'lazy';
					image.draggable = false;

					preview.appendChild(image);
				});

				card.appendChild(preview);
			});

		updateSelectedCard();
	}

	$(function () {
		var initialCursor = getSavedCursor() || DEFAULT_CURSOR;

		applyCursor(initialCursor, false);

		var observer = new MutationObserver(injectPreviews);
		var content = document.getElementById(
			'citizen-preferences-content'
		);

		if (content) {
			observer.observe(content, {
				childList: true,
				subtree: true
			});

			injectPreviews();
		} else {
			var bodyObserver = new MutationObserver(function () {
				var preferences = document.getElementById(
					'citizen-preferences-content'
				);

				if (preferences) {
					observer.observe(preferences, {
						childList: true,
						subtree: true
					});

					injectPreviews();
					bodyObserver.disconnect();
				}
			});

			bodyObserver.observe(document.body, {
				childList: true,
				subtree: true
			});
		}
	});
})();

.sfrac {
	white-space: nowrap;
}

.sfrac.tion,
.sfrac .tion {
	display: inline-block;
	vertical-align: -0.5em;
	font-size: 85%;
	text-align: center;
}

.sfrac .num {
	display: block;
	line-height: 1em;
	margin: 0.0em 0.1em;
	border-bottom: 1px solid;
}

.sfrac .den {
	display: block;
	line-height: 1em;
	margin: 0.1em 0.1em;
}
.sr-only {
	border: 0;
	clip: rect(0, 0, 0, 0); /* removed from CSS */
	clip-path: polygon(0px 0px, 0px 0px, 0px 0px);
	height: 1px;
	margin: -1px;
	overflow: hidden;
	padding: 0;
	position: absolute;
	width: 1px;
	/* white-space: nowrap; /* already have nowrap above */
}

