var currentPage = mw.config.get('wgPageName');

if (currentPage === 'Fish_page:sandbox') {
    importScript('MediaWiki:EntryCreator.js');
    importStylesheet('MediaWiki:EntryCreator.css');
}

if (currentPage === 'Fish_entries:sandbox') {
    importScript('MediaWiki:FishEntries.js');
    importStylesheet('MediaWiki:FishEntriesSandbox.css');
}

(function () {

    var STATISTICS_PAGE =
        'Fish_Statistics';

    var CATEGORIES = {
        Fish:
            'Category:Fish Entries',
        Location:
            'Category:Fish Locations'
    };

    $(function () {

        if (
            normalizePageName(
                mw.config.get('wgPageName')
            ) !==
            normalizePageName(
                STATISTICS_PAGE
            )
        ) {
            return;
        }

        var container =
            document.getElementById(
                'fish-statistics-app'
            );

        if (!container) {
            return;
        }

        container.innerHTML =
            '<div class="fish-stats-loading">Loading fish statistics...</div>';

        mw.loader.using([
            'mediawiki.api',
            'mediawiki.util'
        ])
            .then(function () {

                var api =
                    new mw.Api();

                return Promise.all([
                    loadLocations(api),
                    loadFish(api)
                ]);

            })
            .then(function (results) {

                var locations =
                    results[0];

                var fishEntries =
                    results[1];

                renderStatistics(
                    container,
                    locations,
                    fishEntries
                );

            })
            .catch(function (error) {

                console.error(
                    'Fish Statistics Error:',
                    error
                );

                container.innerHTML =
                    '<div class="fish-stats-error">Could not load fish statistics.</div>';

            });

    });


    function normalizePageName(value) {

        return String(
            value || ''
        )
            .replace(/_/g, ' ')
            .replace(/\s+/g, ' ')
            .trim()
            .toLowerCase();

    }


    function loadLocations(api) {

        return getCategoryEntryPages(
            api,
            CATEGORIES.Location,
            'Location'
        )
            .then(function (entries) {

                var locations =
                    entries.map(function (entry) {

                        return {
                            name:
                                entry.data.name ||
                                getNameFromPage(
                                    entry.page
                                ),

                            image:
                                entry.data.image ||
                                ''
                        };

                    });

                locations.sort(sortByName);

                return locations;

            });

    }


    function loadFish(api) {

        return getCategoryEntryPages(
            api,
            CATEGORIES.Fish,
            'Fish'
        )
            .then(function (entries) {

                return entries.map(function (entry) {

                    var fishPoints =
                        Number(
                            String(
                                entry.data.base_sell_price ||
                                '0'
                            ).replace(/,/g, '')
                        );

                    if (
                        !Number.isFinite(
                            fishPoints
                        )
                    ) {
                        fishPoints = 0;
                    }

                    return {
                        name:
                            entry.data.name ||
                            getNameFromPage(
                                entry.page
                            ),

                        image:
                            entry.data.image ||
                            '',

                        rarity:
                            entry.data.rarity ||
                            '',

                        fishPoints:
                            fishPoints,

                        weights:
                            parseLocationWeights(
                                entry.data.location_weights
                            )
                    };

                });

            });

    }


    function renderStatistics(
        container,
        locations,
        fishEntries
    ) {

        container.innerHTML = '';

        var shell =
            document.createElement(
                'div'
            );

        shell.className =
            'fish-stats-shell';

        var title =
            document.createElement(
                'div'
            );

        title.className =
            'fish-stats-title';

        title.textContent =
            'Fish Statistics';

        shell.appendChild(
            title
        );

        var subtitle =
            document.createElement(
                'div'
            );

        subtitle.className =
            'fish-stats-subtitle';

        subtitle.textContent =
            'Average Fish Points per area, weighted by each fish\'s catch weight.';

        shell.appendChild(
            subtitle
        );

        if (
            !locations.length
        ) {

            shell.appendChild(
                createMessage(
                    'No locations have been published yet.'
                )
            );

            container.appendChild(
                shell
            );

            return;

        }

        locations.forEach(function (
            location
        ) {

            shell.appendChild(
                createLocationSection(
                    location,
                    fishEntries
                )
            );

        });

        container.appendChild(
            shell
        );

    }


    function createLocationSection(
        location,
        fishEntries
    ) {

        var calculated =
            calculateLocationStatistics(
                location.name,
                fishEntries
            );

        var section =
            document.createElement(
                'section'
            );

        section.className =
            'fish-stats-location';

        var header =
            document.createElement(
                'div'
            );

        header.className =
            'fish-stats-location-header';

        var heading =
            document.createElement(
                'div'
            );

        heading.className =
            'fish-stats-location-heading';

        if (
            location.image
        ) {

            var image =
                document.createElement(
                    'img'
                );

            image.src =
                getWikiImageUrl(
                    location.image
                );

            image.alt =
                location.name;

            heading.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'span'
            );

        name.textContent =
            location.name;

        heading.appendChild(
            name
        );

        header.appendChild(
            heading
        );

        var averageBox =
            document.createElement(
                'div'
            );

        averageBox.className =
            'fish-stats-average';

        var averageLabel =
            document.createElement(
                'span'
            );

        averageLabel.textContent =
            'Average Fish Points';

        var averageValue =
            document.createElement(
                'strong'
            );

        averageValue.textContent =
            calculated.totalWeight > 0
                ? formatNumber(
                    calculated.averagePoints
                )
                : 'N/A';

        averageBox.appendChild(
            averageLabel
        );

        averageBox.appendChild(
            averageValue
        );

        header.appendChild(
            averageBox
        );

        section.appendChild(
            header
        );

        if (
            !calculated.entries.length
        ) {

            section.appendChild(
                createMessage(
                    'No fish can currently be caught here.'
                )
            );

            return section;

        }

        var tableWrap =
            document.createElement(
                'div'
            );

        tableWrap.className =
            'fish-stats-table-wrap';

        var table =
            document.createElement(
                'table'
            );

        table.className =
            'fish-stats-table';

        table.innerHTML =
            '<thead>' +
                '<tr>' +
                    '<th>Fish</th>' +
                    '<th>Weight</th>' +
                    '<th>Chance</th>' +
                    '<th>Fish Points</th>' +
                    '<th>Weighted Points</th>' +
                '</tr>' +
            '</thead>';

        var tbody =
            document.createElement(
                'tbody'
            );

        calculated.entries.forEach(
            function (entry) {

                var row =
                    document.createElement(
                        'tr'
                    );

                var fishCell =
                    document.createElement(
                        'td'
                    );

                fishCell.className =
                    'fish-stats-fish-cell';

                if (
                    entry.fish.image
                ) {

                    var fishImage =
                        document.createElement(
                            'img'
                        );

                    fishImage.src =
                        getWikiImageUrl(
                            entry.fish.image
                        );

                    fishImage.alt =
                        entry.fish.name;

                    fishCell.appendChild(
                        fishImage
                    );

                }

                var fishName =
                    document.createElement(
                        'span'
                    );

                fishName.textContent =
                    entry.fish.name;

                fishCell.appendChild(
                    fishName
                );

                row.appendChild(
                    fishCell
                );

                row.appendChild(
                    createNumberCell(
                        entry.weight
                    )
                );

                row.appendChild(
                    createTextCell(
                        formatPercent(
                            entry.chance
                        )
                    )
                );

                row.appendChild(
                    createNumberCell(
                        entry.fish.fishPoints
                    )
                );

                row.appendChild(
                    createNumberCell(
                        entry.weightedPoints
                    )
                );

                tbody.appendChild(
                    row
                );

            }
        );

        var totalRow =
            document.createElement(
                'tr'
            );

        totalRow.className =
            'fish-stats-total-row';

        var totalLabel =
            document.createElement(
                'td'
            );

        totalLabel.textContent =
            'Total';

        totalRow.appendChild(
            totalLabel
        );

        totalRow.appendChild(
            createNumberCell(
                calculated.totalWeight
            )
        );

        totalRow.appendChild(
            createTextCell(
                '100%'
            )
        );

        totalRow.appendChild(
            createTextCell(
                '—'
            )
        );

        totalRow.appendChild(
            createNumberCell(
                calculated.totalWeightedPoints
            )
        );

        tbody.appendChild(
            totalRow
        );

        table.appendChild(
            tbody
        );

        tableWrap.appendChild(
            table
        );

        section.appendChild(
            tableWrap
        );

        var formula =
            document.createElement(
                'div'
            );

        formula.className =
            'fish-stats-formula';

        formula.textContent =
            'Average = Total Weighted Points ÷ Total Weight = ' +
            formatNumber(
                calculated.totalWeightedPoints
            ) +
            ' ÷ ' +
            formatNumber(
                calculated.totalWeight
            ) +
            ' = ' +
            formatNumber(
                calculated.averagePoints
            );

        section.appendChild(
            formula
        );

        return section;

    }


    function calculateLocationStatistics(
        locationName,
        fishEntries
    ) {

        var result = [];
        var totalWeight = 0;
        var totalWeightedPoints = 0;

        fishEntries.forEach(function (fish) {

            var weight =
                getFishWeightForLocation(
                    fish,
                    locationName
                );

            if (
                weight <= 0
            ) {
                return;
            }

            var weightedPoints =
                weight *
                fish.fishPoints;

            totalWeight +=
                weight;

            totalWeightedPoints +=
                weightedPoints;

            result.push({
                fish:
                    fish,

                weight:
                    weight,

                weightedPoints:
                    weightedPoints,

                chance:
                    0
            });

        });

        result.forEach(function (entry) {

            entry.chance =
                totalWeight > 0
                    ? (
                        entry.weight /
                        totalWeight
                    ) * 100
                    : 0;

        });

        result.sort(function (a, b) {

            if (
                b.chance !==
                a.chance
            ) {
                return b.chance - a.chance;
            }

            return String(
                a.fish.name || ''
            ).localeCompare(
                String(
                    b.fish.name || ''
                ),
                undefined,
                {
                    sensitivity:
                        'base'
                }
            );

        });

        return {
            entries:
                result,

            totalWeight:
                totalWeight,

            totalWeightedPoints:
                totalWeightedPoints,

            averagePoints:
                totalWeight > 0
                    ? totalWeightedPoints /
                        totalWeight
                    : 0
        };

    }


    function getFishWeightForLocation(
        fish,
        locationName
    ) {

        var target =
            String(
                locationName || ''
            )
                .trim()
                .toLowerCase();

        for (
            var i = 0;
            i < fish.weights.length;
            i++
        ) {

            if (
                String(
                    fish.weights[i].location
                )
                    .trim()
                    .toLowerCase() ===
                target
            ) {

                return Number(
                    fish.weights[i].weight
                ) || 0;

            }

        }

        return 0;

    }


    function parseLocationWeights(value) {

        var result = [];

        String(
            value || ''
        )
            .split(';')
            .forEach(function (part) {

                part =
                    part.trim();

                if (!part) {
                    return;
                }

                var separator =
                    part.lastIndexOf(':');

                if (
                    separator === -1
                ) {
                    return;
                }

                var location =
                    part
                        .slice(
                            0,
                            separator
                        )
                        .trim();

                var weight =
                    Number(
                        part
                            .slice(
                                separator + 1
                            )
                            .trim()
                    );

                if (
                    !location ||
                    !Number.isFinite(weight) ||
                    weight <= 0
                ) {
                    return;
                }

                result.push({
                    location:
                        location,

                    weight:
                        weight
                });

            });

        return result;

    }


    function getCategoryEntryPages(
        api,
        category,
        expectedType
    ) {

        return getAllCategoryMembers(
            api,
            category
        )
            .then(function (titles) {

                if (!titles.length) {
                    return [];
                }

                return getPagesContents(
                    api,
                    titles
                );

            })
            .then(function (pages) {

                if (!pages) {
                    return [];
                }

                var result = [];

                pages.forEach(function (page) {

                    var data =
                        parseEntryData(
                            page.text
                        );

                    if (!data) {
                        return;
                    }

                    if (
                        expectedType &&
                        String(
                            data.type || ''
                        ).toLowerCase() !==
                        expectedType.toLowerCase()
                    ) {
                        return;
                    }

                    result.push({
                        page:
                            page.title,

                        data:
                            data
                    });

                });

                return result;

            });

    }


    function getAllCategoryMembers(
        api,
        category,
        cmcontinue
    ) {

        var params = {
            action:
                'query',

            list:
                'categorymembers',

            cmtitle:
                category,

            cmlimit:
                'max',

            cmtype:
                'page',

            format:
                'json',

            formatversion:
                2
        };

        if (
            cmcontinue
        ) {
            params.cmcontinue =
                cmcontinue;
        }

        return new Promise(
            function (
                resolve,
                reject
            ) {

                api.get(params)
                    .done(resolve)
                    .fail(reject);

            }
        )
            .then(function (response) {

                var titles = [];

                if (
                    response.query &&
                    response.query.categorymembers
                ) {

                    titles =
                        response.query.categorymembers
                            .map(function (page) {
                                return page.title;
                            });

                }

                if (
                    response.continue &&
                    response.continue.cmcontinue
                ) {

                    return getAllCategoryMembers(
                        api,
                        category,
                        response.continue.cmcontinue
                    )
                        .then(function (more) {

                            return titles.concat(
                                more
                            );

                        });

                }

                return titles;

            });

    }


    function getPagesContents(
        api,
        titles
    ) {

        var chunks = [];

        for (
            var i = 0;
            i < titles.length;
            i += 50
        ) {

            chunks.push(
                titles.slice(
                    i,
                    i + 50
                )
            );

        }

        return Promise.all(
            chunks.map(function (chunk) {

                return new Promise(
                    function (
                        resolve,
                        reject
                    ) {

                        api.get({
                            action:
                                'query',

                            prop:
                                'revisions',

                            titles:
                                chunk.join('|'),

                            rvprop:
                                'content',

                            rvslots:
                                'main',

                            redirects:
                                1,

                            format:
                                'json',

                            formatversion:
                                2
                        })
                            .done(resolve)
                            .fail(reject);

                    }
                );

            })
        )
            .then(function (responses) {

                var result = [];

                responses.forEach(
                    function (response) {

                        if (
                            !response.query ||
                            !response.query.pages
                        ) {
                            return;
                        }

                        response.query.pages
                            .forEach(function (page) {

                                if (
                                    page.missing ||
                                    !page.revisions ||
                                    !page.revisions.length
                                ) {
                                    return;
                                }

                                var revision =
                                    page.revisions[0];

                                var text = '';

                                if (
                                    revision.slots &&
                                    revision.slots.main
                                ) {

                                    text =
                                        revision.slots.main.content ||
                                        revision.slots.main['*'] ||
                                        '';

                                } else {

                                    text =
                                        revision.content ||
                                        revision['*'] ||
                                        '';

                                }

                                result.push({
                                    title:
                                        page.title,

                                    text:
                                        text
                                });

                            });

                    }
                );

                return result;

            });

    }


    function parseEntryData(text) {

        var match =
            String(
                text || ''
            ).match(
                /\{\{\s*EntryData\b([\s\S]*?)\n?\}\}/i
            );

        if (!match) {
            return null;
        }

        var data = {};
        var currentKey = null;

        match[1]
            .split(/\r?\n/)
            .forEach(function (line) {

                var parameter =
                    line.match(
                        /^\s*\|\s*([^=]+?)\s*=\s*(.*)$/
                    );

                if (
                    parameter
                ) {

                    currentKey =
                        parameter[1]
                            .trim()
                            .toLowerCase();

                    data[currentKey] =
                        decodeTemplateValue(
                            parameter[2]
                                .trim()
                        );

                    return;

                }

                if (
                    currentKey &&
                    line.trim()
                ) {

                    data[currentKey] +=
                        '\n' +
                        line.trim();

                }

            });

        return data;

    }


    function decodeTemplateValue(value) {

        return String(
            value || ''
        )
            .replace(
                /&#124;/g,
                '|'
            )
            .replace(
                /&#123;&#123;/g,
                '{{'
            )
            .replace(
                /&#125;&#125;/g,
                '}}'
            )
            .replace(
                /}&#125;/g,
                '}}'
            );

    }


    function getNameFromPage(page) {

        return String(
            page || ''
        )
            .replace(
                /^[^:]+:\s*/,
                ''
            )
            .trim();

    }


    function getWikiImageUrl(filename) {

        filename =
            String(
                filename || ''
            )
                .replace(
                    /^File:/i,
                    ''
                )
                .trim();

        return mw.util.getUrl(
            'Special:Redirect/file/' +
            filename
        );

    }


    function sortByName(a, b) {

        return String(
            a.name || ''
        ).localeCompare(
            String(
                b.name || ''
            ),
            undefined,
            {
                sensitivity:
                    'base'
            }
        );

    }


    function createMessage(text) {

        var message =
            document.createElement(
                'div'
            );

        message.className =
            'fish-stats-message';

        message.textContent =
            text;

        return message;

    }


    function createNumberCell(value) {

        return createTextCell(
            formatNumber(value)
        );

    }


    function createTextCell(value) {

        var cell =
            document.createElement(
                'td'
            );

        cell.textContent =
            value;

        return cell;

    }


    function formatPercent(value) {

        return formatNumber(value) + '%';

    }


    function formatNumber(value) {

        value =
            Number(value);

        if (
            !Number.isFinite(value)
        ) {
            return '0';
        }

        return value.toLocaleString(
            undefined,
            {
                maximumFractionDigits:
                    2
            }
        );

    }

}());

