                    ) {
                        fishPoints = 0;
                    }

                    return {
                        name:
                            entry.data.name ||
                            getNameFromPage(
                                entry.page
                            ),

                        image:
                            entry.data.image ||
                            '',

                        rarity:
                            entry.data.rarity ||
                            '',

                        fishPoints:
                            fishPoints,

                        weights:
                            parseLocationWeights(
                                entry.data.location_weights
                            )
                    };

                });

            });

    }


    function renderStatistics(
        container,
        locations,
        fishEntries
    ) {

        container.innerHTML = '';

        var shell =
            document.createElement(
                'div'
            );

        shell.className =
            'fish-stats-shell';

        var title =
            document.createElement(
                'div'
            );

        title.className =
            'fish-stats-title';

        title.textContent =
            'Fish Statistics';

        shell.appendChild(
            title
        );

        var subtitle =
            document.createElement(
                'div'
            );

        subtitle.className =
            'fish-stats-subtitle';

        subtitle.textContent =
            'Average Fish Points per area, weighted by each fish\'s catch weight.';

        shell.appendChild(
            subtitle
        );

        if (
            !locations.length
        ) {

            shell.appendChild(
                createMessage(
                    'No locations have been published yet.'
                )
            );

            container.appendChild(
                shell
            );

            return;

        }

        shell.appendChild(
            createLeaderboard(
                locations,
                fishEntries
            )
        );

        locations.forEach(function (
            location
        ) {

            shell.appendChild(
                createLocationSection(
                    location,
                    fishEntries
                )
            );

        });

        container.appendChild(
            shell
        );

    }

    function createLeaderboard(
        locations,
        fishEntries
    ) {

        var rankings =
            locations.map(function (
                location
            ) {

                var calculated =
                    calculateLocationStatistics(
                        location.name,
                        fishEntries
                    );

                return {
                    location:
                        location,

                    average:
                        calculated.averagePoints
                };

            });

        rankings.sort(function (
            a,
            b
        ) {

            if (
                b.average !==
                a.average
            ) {

                return (
                    b.average -
                    a.average
                );

            }

            return String(
                a.location.name || ''
            ).localeCompare(
                String(
                    b.location.name || ''
                )
            );

        });

        var leaderboard =
            document.createElement(
                'div'
            );

        leaderboard.className =
            'fish-stats-leaderboard';

        var title =
            document.createElement(
                'div'
            );

        title.className =
            'fish-stats-leaderboard-title';

        title.textContent =
            'Area Rankings';

        leaderboard.appendChild(
            title
        );

        rankings.forEach(function (
            entry,
            index
        ) {

            var row =
                document.createElement(
                    'div'
                );

            row.className =
                'fish-stats-leaderboard-row';

            var rank =
                document.createElement(
                    'div'
                );

            rank.className =
                'fish-stats-leaderboard-rank';

            if (
                index === 0
            ) {

                rank.textContent =
                    '🥇';

            } else if (
                index === 1
            ) {

                rank.textContent =
                    '🥈';

            } else if (
                index === 2
            ) {

                rank.textContent =
                    '🥉';

            } else {

                rank.textContent =
                    String(
                        index + 1
                    );

            }

            var name =
                document.createElement(
                    'div'
                );

            name.className =
                'fish-stats-leaderboard-name';

            name.textContent =
                entry.location.name;

            var average =
                document.createElement(
                    'div'
                );

            average.className =
                'fish-stats-leaderboard-average';

            average.textContent =
                formatNumber(
                    entry.average
                ) +
                ' avg Fish Points';

            row.appendChild(
                rank
            );

            row.appendChild(
                name
            );

            row.appendChild(
                average
            );

            leaderboard.appendChild(
                row
            );

        });

        return leaderboard;

    }

    function createLocationSection(
        location,
        fishEntries
    ) {

        var calculated =
            calculateLocationStatistics(
                location.name,
                fishEntries
            );

        var section =
            document.createElement(
                'section'
            );

        section.className =
            'fish-stats-location';

        var header =
            document.createElement(
                'div'
            );

        header.className =
            'fish-stats-location-header';

        var heading =
            document.createElement(
                'div'
            );

        heading.className =
            'fish-stats-location-heading';

        if (
            location.image
        ) {

            var image =
                document.createElement(
                    'img'
                );

            image.src =
                getWikiImageUrl(
                    location.image
                );

            image.alt =
                location.name;

            heading.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'span'
            );

        name.textContent =
            location.name;

        heading.appendChild(
            name
        );

        header.appendChild(
            heading
        );

        var averageBox =
            document.createElement(
                'div'
            );

        averageBox.className =
            'fish-stats-average';

        var averageLabel =
            document.createElement(
                'span'
            );

        averageLabel.textContent =
            'Average Fish Points';

        var averageValue =
            document.createElement(
                'strong'
            );

        averageValue.textContent =
            calculated.totalWeight > 0
                ? formatNumber(
                    calculated.averagePoints
                )
                : 'N/A';

        averageBox.appendChild(
            averageLabel
        );

        averageBox.appendChild(
            averageValue
        );

        header.appendChild(
            averageBox
        );

        section.appendChild(
            header
        );

        if (
            !calculated.entries.length
        ) {

            section.appendChild(
                createMessage(
                    'No fish can currently be caught here.'
                )
            );

            return section;

        }

        var tableWrap =
            document.createElement(
                'div'
            );

        tableWrap.className =
            'fish-stats-table-wrap';

        var table =
            document.createElement(
                'table'
            );

        table.className =
            'fish-stats-table';

        table.innerHTML =
            '<thead>' +
                '<tr>' +
                    '<th>Fish</th>' +
                    '<th>Weight</th>' +
                    '<th>Chance</th>' +
                    '<th>Fish Points</th>' +
                    '<th>Weighted Points</th>' +
                '</tr>' +
            '</thead>';

        var tbody =
            document.createElement(
                'tbody'
            );

        calculated.entries.forEach(
            function (entry) {

                var row =
                    document.createElement(
                        'tr'
                    );

                var fishCell =
                    document.createElement(
                        'td'
                    );

                fishCell.className =
                    'fish-stats-fish-cell';

                if (
                    entry.fish.image
                ) {

                    var fishImage =
                        document.createElement(
                            'img'
                        );

                    fishImage.src =
                        getWikiImageUrl(
                            entry.fish.image
                        );

                    fishImage.alt =
                        entry.fish.name;

                    fishCell.appendChild(
                        fishImage
                    );

                }

                var fishName =
                    document.createElement(
                        'span'
                    );

                fishName.textContent =
                    entry.fish.name;

                fishCell.appendChild(
                    fishName
                );

                row.appendChild(
                    fishCell
                );

                row.appendChild(
                    createNumberCell(
                        entry.weight
                    )
                );

                row.appendChild(
                    createTextCell(
                        formatPercent(
                            entry.chance
                        )
                    )
                );

                row.appendChild(
                    createNumberCell(
                        entry.fish.fishPoints
                    )
                );

                row.appendChild(
                    createNumberCell(
                        entry.weightedPoints
                    )
                );

                tbody.appendChild(
                    row
                );

            }
        );

        var totalRow =
            document.createElement(
                'tr'
            );

        totalRow.className =
            'fish-stats-total-row';

        var totalLabel =
            document.createElement(
                'td'
            );

        totalLabel.textContent =
            'Total';

        totalRow.appendChild(
            totalLabel
        );

        totalRow.appendChild(
            createNumberCell(
                calculated.totalWeight
            )
        );

        totalRow.appendChild(
            createTextCell(
                '100%'
            )
        );

        totalRow.appendChild(
            createTextCell(
                '—'
            )
        );

        totalRow.appendChild(
            createNumberCell(
                calculated.totalWeightedPoints
            )
        );

        tbody.appendChild(
            totalRow
        );

        table.appendChild(
            tbody
        );

        tableWrap.appendChild(
            table
        );

        section.appendChild(
            tableWrap
        );

        var formula =
            document.createElement(
                'div'
            );

        formula.className =
            'fish-stats-formula';

        formula.textContent =
            'Average = Total Weighted Points ÷ Total Weight = ' +
            formatNumber(
                calculated.totalWeightedPoints
            ) +
            ' ÷ ' +
            formatNumber(
                calculated.totalWeight
            ) +
            ' = ' +
            formatNumber(
                calculated.averagePoints
            );

        section.appendChild(
            formula
        );

        return section;

    }


    function calculateLocationStatistics(
        locationName,
        fishEntries
    ) {

        var result = [];
        var totalWeight = 0;
        var totalWeightedPoints = 0;

        fishEntries.forEach(function (fish) {

            var weight =
                getFishWeightForLocation(
                    fish,
                    locationName
                );

            if (
                weight <= 0
            ) {
                return;
            }

            var weightedPoints =
                weight *
                fish.fishPoints;

            totalWeight +=
                weight;

            totalWeightedPoints +=
                weightedPoints;

            result.push({
                fish:
                    fish,

                weight:
                    weight,

                weightedPoints:
                    weightedPoints,

                chance:
                    0
            });

        });

        result.forEach(function (entry) {

            entry.chance =
                totalWeight > 0
                    ? (
                        entry.weight /
                        totalWeight
                    ) * 100
                    : 0;

        });

        result.sort(function (a, b) {

            if (
                b.chance !==
                a.chance
            ) {
                return b.chance - a.chance;
            }

            return String(
                a.fish.name || ''
            ).localeCompare(
                String(
                    b.fish.name || ''
                ),
                undefined,
                {
                    sensitivity:
                        'base'
                }
            );

        });

        return {
            entries:
                result,

            totalWeight:
                totalWeight,

            totalWeightedPoints:
                totalWeightedPoints,

            averagePoints:
                totalWeight > 0
                    ? totalWeightedPoints /
                        totalWeight
                    : 0
        };

    }


    function getFishWeightForLocation(
        fish,
        locationName
    ) {

        var target =
            String(
                locationName || ''
            )
                .trim()
                .toLowerCase();

        for (
            var i = 0;
            i < fish.weights.length;
            i++
        ) {

            if (
                String(
                    fish.weights[i].location
                )
                    .trim()
                    .toLowerCase() ===
                target
            ) {

                return Number(
                    fish.weights[i].weight
                ) || 0;

            }

        }

        return 0;

    }


    function parseLocationWeights(value) {

        var result = [];

        String(
            value || ''
        )
            .split(';')
            .forEach(function (part) {

                part =
                    part.trim();

                if (!part) {
                    return;
                }

                var separator =
                    part.lastIndexOf(':');

                if (
                    separator === -1
                ) {
                    return;
                }

                var location =
                    part
                        .slice(
                            0,
                            separator
                        )
                        .trim();

                var weight =
                    Number(
                        part
                            .slice(
                                separator + 1
                            )
                            .trim()
                    );

                if (
                    !location ||
                    !Number.isFinite(weight) ||
                    weight <= 0
                ) {
                    return;
                }

                result.push({
                    location:
                        location,

                    weight:
                        weight
                });

            });

        return result;

    }


    function getCategoryEntryPages(
        api,
        category,
        expectedType
    ) {

        return getAllCategoryMembers(
            api,
            category
        )
            .then(function (titles) {

                if (!titles.length) {
                    return [];
                }

                return getPagesContents(
                    api,
                    titles
                );

            })
            .then(function (pages) {

                if (!pages) {
                    return [];
                }

                var result = [];

                pages.forEach(function (page) {

                    var data =
                        parseEntryData(
                            page.text
                        );

                    if (!data) {
                        return;
                    }

                    if (
                        expectedType &&
                        String(
                            data.type || ''
                        ).toLowerCase() !==
                        expectedType.toLowerCase()
                    ) {
                        return;
                    }

                    result.push({
                        page:
                            page.title,

                        data:
                            data
                    });

                });

                return result;

            });

    }


    function getAllCategoryMembers(
        api,
        category,
        cmcontinue
    ) {

        var params = {
            action:
                'query',

            list:
                'categorymembers',

            cmtitle:
                category,

            cmlimit:
                'max',

            cmtype:
                'page',

            format:
                'json',

            formatversion:
                2
        };

        if (
            cmcontinue
        ) {
            params.cmcontinue =
                cmcontinue;
        }

        return new Promise(
            function (
                resolve,
                reject
            ) {

                api.get(params)
                    .done(resolve)
                    .fail(reject);

            }
        )
            .then(function (response) {

                var titles = [];

                if (
                    response.query &&
                    response.query.categorymembers
                ) {

                    titles =
                        response.query.categorymembers
                            .map(function (page) {
                                return page.title;
                            });

                }

                if (
                    response.continue &&
                    response.continue.cmcontinue
                ) {

                    return getAllCategoryMembers(
                        api,
                        category,
                        response.continue.cmcontinue
                    )
                        .then(function (more) {

                            return titles.concat(
                                more
                            );

                        });

                }

                return titles;

            });

    }


    function getPagesContents(
        api,
        titles
    ) {

        var chunks = [];

        for (
            var i = 0;
            i < titles.length;
            i += 50
        ) {

            chunks.push(
                titles.slice(
                    i,
                    i + 50
                )
            );

        }

        return Promise.all(
            chunks.map(function (chunk) {

                return new Promise(
                    function (
                        resolve,
                        reject
                    ) {

                        api.get({
                            action:
                                'query',

                            prop:
                                'revisions',

                            titles:
                                chunk.join('|'),

                            rvprop:
                                'content',

                            rvslots:
                                'main',

                            redirects:
                                1,

                            format:
                                'json',

                            formatversion:
                                2
                        })
                            .done(resolve)
                            .fail(reject);

                    }
                );

            })
        )
            .then(function (responses) {

                var result = [];

                responses.forEach(
                    function (response) {

                        if (
                            !response.query ||
                            !response.query.pages
                        ) {
                            return;
                        }

                        response.query.pages
                            .forEach(function (page) {

                                if (
                                    page.missing ||
                                    !page.revisions ||
                                    !page.revisions.length
                                ) {
                                    return;
                                }

                                var revision =
                                    page.revisions[0];

                                var text = '';

                                if (
                                    revision.slots &&
                                    revision.slots.main
                                ) {

                                    text =
                                        revision.slots.main.content ||
                                        revision.slots.main['*'] ||
                                        '';

                                } else {

                                    text =
                                        revision.content ||
                                        revision['*'] ||
                                        '';

                                }

                                result.push({
                                    title:
                                        page.title,

                                    text:
                                        text
                                });

                            });

                    }
                );

                return result;

            });

    }


    function parseEntryData(text) {

        var match =
            String(
                text || ''
            ).match(
                /\{\{\s*EntryData\b([\s\S]*?)\n?\}\}/i
            );

        if (!match) {
            return null;
        }

        var data = {};
        var currentKey = null;

        match[1]
            .split(/\r?\n/)
            .forEach(function (line) {

                var parameter =
                    line.match(
                        /^\s*\|\s*([^=]+?)\s*=\s*(.*)$/
                    );

                if (
                    parameter
                ) {

                    currentKey =
                        parameter[1]
                            .trim()
                            .toLowerCase();

                    data[currentKey] =
                        decodeTemplateValue(
                            parameter[2]
                                .trim()
                        );

                    return;

                }

                if (
                    currentKey &&
                    line.trim()
                ) {

                    data[currentKey] +=
                        '\n' +
                        line.trim();

                }

            });

        return data;

    }


    function decodeTemplateValue(value) {

        return String(
            value || ''
        )
            .replace(
                /&#124;/g,
                '|'
            )
            .replace(
                /&#123;&#123;/g,
                '{{'
            )
            .replace(
                /&#125;&#125;/g,
                '}}'
            )
            .replace(
                /}&#125;/g,
                '}}'
            );

    }


    function getNameFromPage(page) {

        return String(
            page || ''
        )
            .replace(
                /^[^:]+:\s*/,
                ''
            )
            .trim();

    }


    function getWikiImageUrl(filename) {

        filename =
            String(
                filename || ''
            )
                .replace(
                    /^File:/i,
                    ''
                )
                .trim();

        return mw.util.getUrl(
            'Special:Redirect/file/' +
            filename
        );

    }


    function sortByName(a, b) {

        return String(
            a.name || ''
        ).localeCompare(
            String(
                b.name || ''
            ),
            undefined,
            {
                sensitivity:
                    'base'
            }
        );

    }


    function createMessage(text) {

        var message =
            document.createElement(
                'div'
            );

        message.className =
            'fish-stats-message';

        message.textContent =
            text;

        return message;

    }


    function createNumberCell(value) {

        return createTextCell(
            formatNumber(value)
        );

    }


    function createTextCell(value) {

        var cell =
            document.createElement(
                'td'
            );

        cell.textContent =
            value;

        return cell;

    }


    function formatPercent(value) {

        return formatNumber(value) + '%';

    }


    function formatNumber(value) {

        value =
            Number(value);

        if (
            !Number.isFinite(value)
        ) {
            return '0';
        }

        return value.toLocaleString(
            undefined,
            {
                maximumFractionDigits:
                    2
            }
        );

    }

}());

(function () {

    var STATISTICS_PAGE =
        'Fish_Statistics';

    panel.appendChild(
        title
    );
        $(function () {

            if (
                normalizePageName(
                    mw.config.get('wgPageName')
                ) !==
                normalizePageName(
                    STATISTICS_PAGE
                )
            ) {
                return;
            }

            var container =
                document.getElementById(
                    'fish-statistics-app'
                );

            if (!container) {
                return;
            }

            container.innerHTML =
                '<div class="fish-stats-loading">Loading fish statistics...</div>';

            mw.loader.using([
                'mediawiki.api',
                'mediawiki.util'
            ])
                .then(function () {

                    var api =
                        new mw.Api();

                    return Promise.all([
                        loadLocations(api),
                        loadFish(api),
                        loadTools(api),
                        loadBaits(api)
                    ]);

                })
                .then(function (results) {

                    var locations =
                        results[0];

                    var fishEntries =
                        results[1];

                    renderStatistics(
                        container,
                        locations,
                        fishEntries
                    );

                })
                .catch(function (error) {

                    console.error(
                        'Fish Statistics Error:',
                        error
                    );

                    container.innerHTML =
                        '<div class="fish-stats-error">Could not load fish statistics.</div>';

                });

        });

    function normalizePageName(value) {

        return String(
            value || ''
        )
            .replace(/_/g, ' ')
            .replace(/\s+/g, ' ')
            .trim()
            .toLowerCase();

    }


    function loadLocations(api) {

        return getCategoryEntryPages(
            api,
            CATEGORIES.Location,
            'Location'
        )
            .then(function (entries) {

                var locations =
                    entries.map(function (entry) {

                        return {
                            name:
                                entry.data.name ||
                                getNameFromPage(
                                    entry.page
                                ),

                            image:
                                entry.data.image ||
                                ''
                        };

                    });

                locations.sort(sortByName);

                return locations;

            });

    }

    function loadTools(api) {

        return getCategoryEntryPages(
            api,
            CATEGORIES.Tool,
            'Tool'
        )
            .then(function (entries) {

                toolEntries =
                    entries.map(function (entry) {

                        return {
                            name:
                                entry.data.name ||
                                getNameFromPage(
                                    entry.page
                                ),

                            image:
                                entry.data.image ||
                                '',

                            baseCost:
                                entry.data.base_cost ||
                                '',

                            rodType:
                                String(
                                    entry.data.rod_type ||
                                    'Unassigned'
                                ).trim() ||
                                'Unassigned',

                            luck:
                                entry.data.luck !==
                                undefined
                                    ? Number(
                                        entry.data.luck
                                    )
                                    : 0
                        };

                    });

                toolEntries.sort(function (
                    a,
                    b
                ) {

                    var aCost =
                        Number(
                            a.baseCost
                        );

                    var bCost =
                        Number(
                            b.baseCost
                        );

                    if (
                        !Number.isFinite(
                            aCost
                        )
                    ) {
                        aCost = Infinity;
                    }

                    if (
                        !Number.isFinite(
                            bCost
                        )
                    ) {
                        bCost = Infinity;
                    }

                    if (
                        aCost !==
                        bCost
                    ) {

                        return (
                            aCost -
                            bCost
                        );

                    }

                    return sortByName(
                        a,
                        b
                    );

                });

                return toolEntries;

            });

    }


    function loadBaits(api) {

        return getCategoryEntryPages(
            api,
            CATEGORIES.Bait,
            'Bait'
        )
            .then(function (entries) {

                baitEntries =
                    entries.map(function (entry) {

                        return {
                            name:
                                entry.data.name ||
                                getNameFromPage(
                                    entry.page
                                ),

                            image:
                                entry.data.image ||
                                '',

                            rarity:
                                entry.data.rarity ||
                                ''
                        };

                    });

                baitEntries.sort(
                    sortByName
                );

                return baitEntries;

            });

    }

    function loadFish(api) {

        return getCategoryEntryPages(
            api,
            CATEGORIES.Fish,
            'Fish'
        )
            .then(function (entries) {

                return entries.map(function (entry) {

                    var fishPoints =
                        Number(
                            String(
                                entry.data.base_sell_price ||
                                '0'
                            ).replace(/,/g, '')
                        );

                    if (
                        !Number.isFinite(
                            fishPoints
                        )
                    ) {
                        fishPoints = 0;
                    }

                    return {
                        name:
                            entry.data.name ||
                            getNameFromPage(
                                entry.page
                            ),

                        image:
                            entry.data.image ||
                            '',

                        rarity:
                            entry.data.rarity ||
                            '',

                        fishPoints:
                            fishPoints,

                        weights:
                            parseLocationWeights(
                                entry.data.location_weights
                            )
                    };

                });

            });

    }


    function renderStatistics(
        container,
        locations,
        fishEntries
    ) {

        container.innerHTML = '';

        var shell =
            document.createElement(
                'div'
            );

        shell.className =
            'fish-stats-shell';

        var title =
            document.createElement(
                'div'
            );

        title.className =
            'fish-stats-title';

        title.textContent =
            'Fish Statistics';

        shell.appendChild(
            title
        );

        var subtitle =
            document.createElement(
                'div'
            );

        subtitle.className =
            'fish-stats-subtitle';

        subtitle.textContent =
            'Average Fish Points per area, weighted by each fish\'s catch weight.';

        shell.appendChild(
            subtitle
        );

        shell.appendChild(
            createModifierPanel(
                container,
                locations,
                fishEntries
            )
        );

        if (
            !locations.length
        ) {

            shell.appendChild(
                createMessage(
                    'No locations have been published yet.'
                )
            );

            container.appendChild(
                shell
            );

            return;

        }

        shell.appendChild(
            createLeaderboard(
                locations,
                fishEntries
            )
        );

        locations.forEach(function (
            location
        ) {

            shell.appendChild(
                createLocationSection(
                    location,
                    fishEntries
                )
            );

        });

        container.appendChild(
            shell
        );

    }

    function createModifierPanel(
        container,
        locations,
        fishEntries
    ) {

        var panel =
            document.createElement(
                'div'
            );

        panel.className =
            'fish-stats-modifiers';

        var title =
            document.createElement(
                'div'
            );

        title.className =
            'fish-stats-modifiers-title';

        title.textContent =
            'Modifiers';

        panel.appendChild(
            title
        );

        var luckSection =
            document.createElement(
                'div'
            );

        luckSection.className =
            'fish-stats-modifier-section';


        var luckTitle =
            document.createElement(
                'div'
            );

        luckTitle.className =
            'fish-stats-modifier-section-title';

        luckTitle.textContent =
            'Fish Luck Modifier';

        luckSection.appendChild(
            luckTitle
        );

        var toolField =
            document.createElement(
                'label'
            );

        toolField.className =
            'fish-stats-modifier-field';


        var toolText =
            document.createElement(
                'span'
            );

        toolText.textContent =
            'Select your tool:';


        var toolSelect =
            document.createElement(
                'select'
            );

        toolSelect.className =
            'fish-stats-modifier-input';


        if (
            currentSelectedToolIndex >=
            toolEntries.length
        ) {

            currentSelectedToolIndex =
                0;

        }


        var toolTypeGroups =
            {};

        var toolTypeOrder =
            [];


        toolEntries.forEach(
            function (
                tool,
                index
            ) {

                var rodType =
                    String(
                        tool.rodType ||
                        'Unassigned'
                    ).trim() ||
                    'Unassigned';

                var rodTypeKey =
                    rodType.toLowerCase();


                if (
                    !toolTypeGroups[
                        rodTypeKey
                    ]
                ) {

                    toolTypeGroups[
                        rodTypeKey
                    ] = {
                        name:
                            rodType,

                        tools:
                            []
                    };

                    toolTypeOrder.push(
                        rodTypeKey
                    );

                }


                toolTypeGroups[
                    rodTypeKey
                ].tools.push({
                    tool:
                        tool,

                    index:
                        index
                });

            }
        );


        toolTypeOrder.forEach(
            function (
                rodTypeKey
            ) {

                var group =
                    toolTypeGroups[
                        rodTypeKey
                    ];

                var optgroup =
                    document.createElement(
                        'optgroup'
                    );

                optgroup.label =
                    group.name;


                group.tools.forEach(
                    function (
                        entry
                    ) {

                        var option =
                            document.createElement(
                                'option'
                            );

                        option.value =
                            String(
                                entry.index
                            );

                        option.textContent =
                            entry.tool.name;

                        option.setAttribute(
                            'data-luck',
                            entry.tool.luck
                        );

                        if (
                            entry.index ===
                            currentSelectedToolIndex
                        ) {

                            option.selected =
                                true;

                        }

                        optgroup.appendChild(
                            option
                        );

                    }
                );


                toolSelect.appendChild(
                    optgroup
                );

            }
        );


        if (
            !toolEntries.length
        ) {

            var noToolOption =
                document.createElement(
                    'option'
                );

            noToolOption.textContent =
                'No tools available';

            noToolOption.disabled =
                true;

            noToolOption.selected =
                true;

            toolSelect.appendChild(
                noToolOption
            );

        }


        toolField.appendChild(
            toolText
        );

        toolField.appendChild(
            toolSelect
        );

        luckSection.appendChild(
            toolField
        );

        var enchantField =
            document.createElement(
                'label'
            );

        enchantField.className =
            'fish-stats-modifier-field';


        var enchantText =
            document.createElement(
                'span'
            );

        enchantText.textContent =
            'Ultra Enchant:';


        var enchantInput =
            document.createElement(
                'input'
            );

        enchantInput.type =
            'number';

        enchantInput.min =
            '0';

        enchantInput.step =
            '1';

        enchantInput.value =
            currentEnchantLevel;

        enchantInput.className =
            'fish-stats-modifier-input';


        enchantInput.addEventListener(
            'change',
            function () {

                var value =
                    Number(
                        enchantInput.value
                    );

                if (
                    !Number.isFinite(
                        value
                    ) ||
                    value < 0
                ) {

                    value = 0;

                }

                currentEnchantLevel =
                    value;

                enchantInput.value =
                    value;

            }
        );


        enchantField.appendChild(
            enchantText
        );

        enchantField.appendChild(
            enchantInput
        );

        luckSection.appendChild(
            enchantField
        );

        var upgradeField =
            document.createElement(
                'label'
            );

        upgradeField.className =
            'fish-stats-modifier-field';


        var upgradeText =
            document.createElement(
                'span'
            );

        upgradeText.textContent =
            'Fish Upgrade: Fortune';


        var upgradeSelect =
            document.createElement(
                'select'
            );

        upgradeSelect.className =
            'fish-stats-modifier-input';


        for (
            var upgradeLevel = 0;
            upgradeLevel <= 20;
            upgradeLevel++
        ) {

            var upgradeOption =
                document.createElement(
                    'option'
                );

            upgradeOption.value =
                upgradeLevel;

            upgradeOption.textContent =
                'Level ' +
                upgradeLevel;

            if (
                upgradeLevel ===
                currentFortuneLevel
            ) {

                upgradeOption.selected =
                    true;

            }

            upgradeSelect.appendChild(
                upgradeOption
            );

        }


        upgradeSelect.addEventListener(
            'change',
            function () {

                currentFortuneLevel =
                    Number(
                        upgradeSelect.value
                    ) || 0;

            }
        );


        upgradeField.appendChild(
            upgradeText
        );

        upgradeField.appendChild(
            upgradeSelect
        );

        luckSection.appendChild(
            upgradeField
        );

        var baitField =
            document.createElement(
                'div'
            );

        baitField.className =
            'fish-stats-modifier-field fish-stats-bait-field';


        var baitText =
            document.createElement(
                'span'
            );

        baitText.textContent =
            'Bait:';


        var baitButton =
            document.createElement(
                'button'
            );

        baitButton.type =
            'button';

        baitButton.className =
            'fish-stats-bait-select-button';


        var baitButtonImage =
            document.createElement(
                'img'
            );

        baitButtonImage.className =
            'fish-stats-bait-select-image';


        var baitButtonName =
            document.createElement(
                'span'
            );


        if (
            currentSelectedBaitIndex >= 0 &&
            baitEntries[
                currentSelectedBaitIndex
            ]
        ) {

            var currentBait =
                baitEntries[
                    currentSelectedBaitIndex
                ];

            baitButtonName.textContent =
                currentBait.name;

            if (
                currentBait.image
            ) {

                baitButtonImage.src =
                    getWikiImageUrl(
                        currentBait.image
                    );

                baitButtonImage.alt =
                    currentBait.name;

                baitButtonImage.style.display =
                    'block';

            } else {

                baitButtonImage.style.display =
                    'none';

            }

        } else {

            baitButtonName.textContent =
                'Choose a bait';

            baitButtonImage.style.display =
                'none';

        }


        baitButton.appendChild(
            baitButtonImage
        );

        baitButton.appendChild(
            baitButtonName
        );


        var baitPicker =
            document.createElement(
                'div'
            );

        baitPicker.className =
            'fish-stats-bait-picker';

        baitPicker.style.display =
            'none';


        var baitPickerGrid =
            document.createElement(
                'div'
            );

        baitPickerGrid.className =
            'fish-stats-bait-picker-grid';

        baitPicker.appendChild(
            baitPickerGrid
        );


        function renderBaitPicker() {

            baitPickerGrid.innerHTML =
                '';


            if (
                !baitEntries.length
            ) {

                var empty =
                    document.createElement(
                        'div'
                    );

                empty.className =
                    'fish-stats-bait-empty';

                empty.textContent =
                    'No baits available.';

                baitPickerGrid.appendChild(
                    empty
                );

                return;

            }


            baitEntries.forEach(
                function (
                    bait,
                    index
                ) {

                    var card =
                        document.createElement(
                            'button'
                        );

                    card.type =
                        'button';

                    card.className =
                        'fish-stats-bait-picker-card';


                    if (
                        index ===
                        currentSelectedBaitIndex
                    ) {

                        card.classList.add(
                            'fish-stats-bait-selected'
                        );

                    }


                    if (
                        bait.image
                    ) {

                        var image =
                            document.createElement(
                                'img'
                            );

                        image.src =
                            getWikiImageUrl(
                                bait.image
                            );

                        image.alt =
                            bait.name;

                        card.appendChild(
                            image
                        );

                    }


                    var name =
                        document.createElement(
                            'span'
                        );

                    name.textContent =
                        bait.name;

                    card.appendChild(
                        name
                    );


                    card.addEventListener(
                        'click',
                        function () {

                            currentSelectedBaitIndex =
                                index;

                            baitButtonName.textContent =
                                bait.name;


                            if (
                                bait.image
                            ) {

                                baitButtonImage.src =
                                    getWikiImageUrl(
                                        bait.image
                                    );

                                baitButtonImage.alt =
                                    bait.name;

                                baitButtonImage.style.display =
                                    'block';

                            } else {

                                baitButtonImage.style.display =
                                    'none';

                            }


                            baitPicker.style.display =
                                'none';

                        }
                    );


                    baitPickerGrid.appendChild(
                        card
                    );

                }
            );

        }


        baitButton.addEventListener(
            'click',
            function () {

                if (
                    baitPicker.style.display ===
                    'block'
                ) {

                    baitPicker.style.display =
                        'none';

                    return;

                }

                renderBaitPicker();

                baitPicker.style.display =
                    'block';

            }
        );


        baitField.appendChild(
            baitText
        );

        baitField.appendChild(
            baitButton
        );

        baitField.appendChild(
            baitPicker
        );

        luckSection.appendChild(
            baitField
        );

        var luckNote =
            document.createElement(
                'div'
            );

        luckNote.className =
            'fish-stats-luck-note';

        luckNote.textContent =
            'Fish Luck calculation will be added when the new formula is known.';

        luckSection.appendChild(
            luckNote
        );

        function updateToolSettings() {

            var selectedTool =
                toolEntries[
                    Number(
                        toolSelect.value
                    )
                ];


            var rodType =
                selectedTool
                    ? String(
                        selectedTool.rodType ||
                        ''
                    )
                        .trim()
                        .toLowerCase()
                    : '';


            if (
                rodType ===
                'gun'
            ) {

                enchantText.textContent =
                    'Sharpshooter Enchant:';

                baitField.style.display =
                    'none';

            } else {

                enchantText.textContent =
                    'Ultra Enchant:';

                baitField.style.display =
                    'flex';

            }

        }


        toolSelect.addEventListener(
            'change',
            function () {

                currentSelectedToolIndex =
                    Number(
                        toolSelect.value
                    ) || 0;

                updateToolSettings();

            }
        );


        updateToolSettings();


        panel.appendChild(
            luckSection
        );

        var priceSection =
            document.createElement(
                'div'
            );

        priceSection.className =
            'fish-stats-modifier-section';


        var priceTitle =
            document.createElement(
                'div'
            );

        priceTitle.className =
            'fish-stats-modifier-section-title';

        priceTitle.textContent =
            'Fish Price Modifier';

        priceSection.appendChild(
            priceTitle
        );

        var bargainingField =
            document.createElement(
                'label'
            );

        bargainingField.className =
            'fish-stats-modifier-field';


        var bargainingLabel =
            document.createElement(
                'span'
            );

        bargainingLabel.textContent =
            'Bargaining';


        var bargainingSelect =
            document.createElement(
                'select'
            );

        bargainingSelect.className =
            'fish-stats-modifier-input';


        for (
            var level = 0;
            level <= 20;
            level++
        ) {

            var option =
                document.createElement(
                    'option'
                );

            option.value =
                level;

            option.textContent =
                'Level ' +
                level +
                ' (×' +
                formatMultiplier(
                    1 +
                    (
                        level *
                        0.05
                    )
                ) +
                ')';


            if (
                level ===
                currentBargainingLevel
            ) {

                option.selected =
                    true;

            }


            bargainingSelect.appendChild(
                option
            );

        }


        bargainingSelect.addEventListener(
            'change',
            function () {

                currentBargainingLevel =
                    Number(
                        bargainingSelect.value
                    ) || 0;

                renderStatistics(
                    container,
                    locations,
                    fishEntries
                );

            }
        );


        bargainingField.appendChild(
            bargainingLabel
        );

        bargainingField.appendChild(
            bargainingSelect
        );

        priceSection.appendChild(
            bargainingField
        );

        var entriesField =
            document.createElement(
                'label'
            );

        entriesField.className =
            'fish-stats-modifier-field';


        var entriesLabel =
            document.createElement(
                'span'
            );

        entriesLabel.textContent =
            'Fish Entries';


        var entriesInput =
            document.createElement(
                'input'
            );

        entriesInput.type =
            'number';

        entriesInput.min =
            '1';

        entriesInput.max =
            '1.43';

        entriesInput.step =
            '0.01';

        entriesInput.value =
            currentFishEntriesMultiplier.toFixed(
                2
            );

        entriesInput.className =
            'fish-stats-modifier-input';


        entriesInput.addEventListener(
            'change',
            function () {

                var value =
                    Number(
                        entriesInput.value
                    );


                if (
                    !Number.isFinite(
                        value
                    )
                ) {

                    value = 1;

                }


                value =
                    Math.max(
                        1,
                        Math.min(
                            1.43,
                            value
                        )
                    );


                currentFishEntriesMultiplier =
                    value;


                renderStatistics(
                    container,
                    locations,
                    fishEntries
                );

            }
        );


        var entriesHelp =
            document.createElement(
                'small'
            );

        entriesHelp.textContent =
            '×1.00 to ×1.43';


        entriesField.appendChild(
            entriesLabel
        );

        entriesField.appendChild(
            entriesInput
        );

        entriesField.appendChild(
            entriesHelp
        );

        priceSection.appendChild(
            entriesField
        );

        var total =
            document.createElement(
                'div'
            );

        total.className =
            'fish-stats-total-modifier';

        total.textContent =
            'Total Fish Price Modifier: ×' +
            formatMultiplier(
                getFishPriceMultiplier()
            );

        priceSection.appendChild(
            total
        );


        panel.appendChild(
            priceSection
        );


        return panel;

    }

    function createLeaderboard(
        locations,
        fishEntries
    ) {

        var rankings =
            locations.map(function (
                location
            ) {

                var calculated =
                    calculateLocationStatistics(
                        location.name,
                        fishEntries
                    );

                return {
                    location:
                        location,

                    average:
                        calculated.averagePoints
                };

            });

        rankings.sort(function (
            a,
            b
        ) {

            if (
                b.average !==
                a.average
            ) {

                return (
                    b.average -
                    a.average
                );

            }

            return String(
                a.location.name || ''
            ).localeCompare(
                String(
                    b.location.name || ''
                )
            );

        });

        var leaderboard =
            document.createElement(
                'div'
            );

        leaderboard.className =
            'fish-stats-leaderboard';

        var title =
            document.createElement(
                'div'
            );

        title.className =
            'fish-stats-leaderboard-title';

        title.textContent =
            'Area Rankings';

        leaderboard.appendChild(
            title
        );

        rankings.forEach(function (
            entry,
            index
        ) {

            var row =
                document.createElement(
                    'div'
                );

            row.className =
                'fish-stats-leaderboard-row';

            var rank =
                document.createElement(
                    'div'
                );

            rank.className =
                'fish-stats-leaderboard-rank';

            if (
                index === 0
            ) {

                rank.textContent =
                    '🥇';

            } else if (
                index === 1
            ) {

                rank.textContent =
                    '🥈';

            } else if (
                index === 2
            ) {

                rank.textContent =
                    '🥉';

            } else {

                rank.textContent =
                    String(
                        index + 1
                    );

            }

            var name =
                document.createElement(
                    'div'
                );

            name.className =
                'fish-stats-leaderboard-name';

            name.textContent =
                entry.location.name;

            var average =
                document.createElement(
                    'div'
                );

            average.className =
                'fish-stats-leaderboard-average';

            average.textContent =
                formatNumber(
                    entry.average
                ) +
                ' avg Fish Points';

            row.appendChild(
                rank
            );

            row.appendChild(
                name
            );

            row.appendChild(
                average
            );

            leaderboard.appendChild(
                row
            );

        });

        return leaderboard;

    }

    function createLocationSection(
        location,
        fishEntries
    ) {

        var calculated =
            calculateLocationStatistics(
                location.name,
                fishEntries
            );

        var section =
            document.createElement(
                'section'
            );

        section.className =
            'fish-stats-location';

        var header =
            document.createElement(
                'div'
            );

        header.className =
            'fish-stats-location-header';

        var heading =
            document.createElement(
                'div'
            );

        heading.className =
            'fish-stats-location-heading';

        if (
            location.image
        ) {

            var image =
                document.createElement(
                    'img'
                );

            image.src =
                getWikiImageUrl(
                    location.image
                );

            image.alt =
                location.name;

            heading.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'span'
            );

        name.textContent =
            location.name;

        heading.appendChild(
            name
        );

        header.appendChild(
            heading
        );

        var averageBox =
            document.createElement(
                'div'
            );

        averageBox.className =
            'fish-stats-average';

        var averageLabel =
            document.createElement(
                'span'
            );

        averageLabel.textContent =
            'Average Fish Points';

        var averageValue =
            document.createElement(
                'strong'
            );

        averageValue.textContent =
            calculated.totalWeight > 0
                ? formatNumber(
                    calculated.averagePoints
                )
                : 'N/A';

        averageBox.appendChild(
            averageLabel
        );

        averageBox.appendChild(
            averageValue
        );

        header.appendChild(
            averageBox
        );

        section.appendChild(
            header
        );

        if (
            !calculated.entries.length
        ) {

            section.appendChild(
                createMessage(
                    'No fish can currently be caught here.'
                )
            );

            return section;

        }

        var tableWrap =
            document.createElement(
                'div'
            );

        tableWrap.className =
            'fish-stats-table-wrap';

        var table =
            document.createElement(
                'table'
            );

        table.className =
            'fish-stats-table';

        table.innerHTML =
            '<thead>' +
                '<tr>' +
                    '<th>Fish</th>' +
                    '<th>Weight</th>' +
                    '<th>Chance</th>' +
                    '<th>Fish Points</th>' +
                    '<th>Weighted Points</th>' +
                '</tr>' +
            '</thead>';

        var tbody =
            document.createElement(
                'tbody'
            );

        calculated.entries.forEach(
            function (entry) {

                var row =
                    document.createElement(
                        'tr'
                    );

                var fishCell =
                    document.createElement(
                        'td'
                    );

                fishCell.className =
                    'fish-stats-fish-cell';

                if (
                    entry.fish.image
                ) {

                    var fishImage =
                        document.createElement(
                            'img'
                        );

                    fishImage.src =
                        getWikiImageUrl(
                            entry.fish.image
                        );

                    fishImage.alt =
                        entry.fish.name;

                    fishCell.appendChild(
                        fishImage
                    );

                }

                var fishName =
                    document.createElement(
                        'span'
                    );

                fishName.textContent =
                    entry.fish.name;

                fishCell.appendChild(
                    fishName
                );

                row.appendChild(
                    fishCell
                );

                row.appendChild(
                    createNumberCell(
                        entry.weight
                    )
                );

                row.appendChild(
                    createTextCell(
                        formatPercent(
                            entry.chance
                        )
                    )
                );

                row.appendChild(
                    createNumberCell(
                        entry.modifiedFishPoints
                    )
                );

                row.appendChild(
                    createNumberCell(
                        entry.weightedPoints
                    )
                );

                tbody.appendChild(
                    row
                );

            }
        );

        var totalRow =
            document.createElement(
                'tr'
            );

        totalRow.className =
            'fish-stats-total-row';

        var totalLabel =
            document.createElement(
                'td'
            );

        totalLabel.textContent =
            'Total';

        totalRow.appendChild(
            totalLabel
        );

        totalRow.appendChild(
            createNumberCell(
                calculated.totalWeight
            )
        );

        totalRow.appendChild(
            createTextCell(
                '100%'
            )
        );

        totalRow.appendChild(
            createTextCell(
                '—'
            )
        );

        totalRow.appendChild(
            createNumberCell(
                calculated.totalWeightedPoints
            )
        );

        tbody.appendChild(
            totalRow
        );

        table.appendChild(
            tbody
        );

        tableWrap.appendChild(
            table
        );

        section.appendChild(
            tableWrap
        );

        var formula =
            document.createElement(
                'div'
            );

        formula.className =
            'fish-stats-formula';

        formula.textContent =
            'Average = Total Weighted Points ÷ Total Weight = ' +
            formatNumber(
                calculated.totalWeightedPoints
            ) +
            ' ÷ ' +
            formatNumber(
                calculated.totalWeight
            ) +
            ' = ' +
            formatNumber(
                calculated.averagePoints
            );

        section.appendChild(
            formula
        );

        return section;

    }

    function getFishPriceMultiplier() {

        var bargainingMultiplier =
            1 +
            (
                currentBargainingLevel *
                0.05
            );

        return (
            bargainingMultiplier *
            currentFishEntriesMultiplier
        );

    }


    function formatMultiplier(value) {

        return Number(
            value
        ).toFixed(
            2
        );

    }

    function calculateLocationStatistics(
        locationName,
        fishEntries
    ) {

        var result = [];
        var totalWeight = 0;
        var totalWeightedPoints = 0;

        fishEntries.forEach(function (fish) {

            var weight =
                getFishWeightForLocation(
                    fish,
                    locationName
                );

            if (
                weight <= 0
            ) {
                return;
            }

            var modifiedFishPoints =
                fish.fishPoints *
                getFishPriceMultiplier();

            var weightedPoints =
                weight *
                modifiedFishPoints;

            totalWeight +=
                weight;

            totalWeightedPoints +=
                weightedPoints;

            result.push({
                fish:
                    fish,

                weight:
                    weight,

                modifiedFishPoints:
                    modifiedFishPoints,

                weightedPoints:
                    weightedPoints,

                chance:
                    0
            });

        });

        result.forEach(function (entry) {

            entry.chance =
                totalWeight > 0
                    ? (
                        entry.weight /
                        totalWeight
                    ) * 100
                    : 0;

        });

        result.sort(function (a, b) {

            if (
                b.chance !==
                a.chance
            ) {
                return b.chance - a.chance;
            }

            return String(
                a.fish.name || ''
            ).localeCompare(
                String(
                    b.fish.name || ''
                ),
                undefined,
                {
                    sensitivity:
                        'base'
                }
            );

        });

        return {
            entries:
                result,

            totalWeight:
                totalWeight,

            totalWeightedPoints:
                totalWeightedPoints,

            averagePoints:
                totalWeight > 0
                    ? totalWeightedPoints /
                        totalWeight
                    : 0
        };

    }


    function getFishWeightForLocation(
        fish,
        locationName
    ) {

        var target =
            String(
                locationName || ''
            )
                .trim()
                .toLowerCase();

        for (
            var i = 0;
            i < fish.weights.length;
            i++
        ) {

            if (
                String(
                    fish.weights[i].location
                )
                    .trim()
                    .toLowerCase() ===
                target
            ) {

                return Number(
                    fish.weights[i].weight
                ) || 0;

            }

        }

        return 0;

    }


    function parseLocationWeights(value) {

        var result = [];

        String(
            value || ''
        )
            .split(';')
            .forEach(function (part) {

                part =
                    part.trim();

                if (!part) {
                    return;
                }

                var separator =
                    part.lastIndexOf(':');

                if (
                    separator === -1
                ) {
                    return;
                }

                var location =
                    part
                        .slice(
                            0,
                            separator
                        )
                        .trim();

                var weight =
                    Number(
                        part
                            .slice(
                                separator + 1
                            )
                            .trim()
                    );

                if (
                    !location ||
                    !Number.isFinite(weight) ||
                    weight <= 0
                ) {
                    return;
                }

                result.push({
                    location:
                        location,

                    weight:
                        weight
                });

            });

        return result;

    }


    function getCategoryEntryPages(
        api,
        category,
        expectedType
    ) {

        return getAllCategoryMembers(
            api,
            category
        )
            .then(function (titles) {

                if (!titles.length) {
                    return [];
                }

                return getPagesContents(
                    api,
                    titles
                );

            })
            .then(function (pages) {

                if (!pages) {
                    return [];
                }

                var result = [];

                pages.forEach(function (page) {

                    var data =
                        parseEntryData(
                            page.text
                        );

                    if (!data) {
                        return;
                    }

                    if (
                        expectedType &&
                        String(
                            data.type || ''
                        ).toLowerCase() !==
                        expectedType.toLowerCase()
                    ) {
                        return;
                    }

                    result.push({
                        page:
                            page.title,

                        data:
                            data
                    });

                });

                return result;

            });

    }


    function getAllCategoryMembers(
        api,
        category,
        cmcontinue
    ) {

        var params = {
            action:
                'query',

            list:
                'categorymembers',

            cmtitle:
                category,

            cmlimit:
                'max',

            cmtype:
                'page',

            format:
                'json',

            formatversion:
                2
        };

        if (
            cmcontinue
        ) {
            params.cmcontinue =
                cmcontinue;
        }

        return new Promise(
            function (
                resolve,
                reject
            ) {

                api.get(params)
                    .done(resolve)
                    .fail(reject);

            }
        )
            .then(function (response) {

                var titles = [];

                if (
                    response.query &&
                    response.query.categorymembers
                ) {

                    titles =
                        response.query.categorymembers
                            .map(function (page) {
                                return page.title;
                            });

                }

                if (
                    response.continue &&
                    response.continue.cmcontinue
                ) {

                    return getAllCategoryMembers(
                        api,
                        category,
                        response.continue.cmcontinue
                    )
                        .then(function (more) {

                            return titles.concat(
                                more
                            );

                        });

                }

                return titles;

            });

    }


    function getPagesContents(
        api,
        titles
    ) {

        var chunks = [];

        for (
            var i = 0;
            i < titles.length;
            i += 50
        ) {

            chunks.push(
                titles.slice(
                    i,
                    i + 50
                )
            );

        }

        return Promise.all(
            chunks.map(function (chunk) {

                return new Promise(
                    function (
                        resolve,
                        reject
                    ) {

                        api.get({
                            action:
                                'query',

                            prop:
                                'revisions',

                            titles:
                                chunk.join('|'),

                            rvprop:
                                'content',

                            rvslots:
                                'main',

                            redirects:
                                1,

                            format:
                                'json',

                            formatversion:
                                2
                        })
                            .done(resolve)
                            .fail(reject);

                    }
                );

            })
        )
            .then(function (responses) {

                var result = [];

                responses.forEach(
                    function (response) {

                        if (
                            !response.query ||
                            !response.query.pages
                        ) {
                            return;
                        }

                        response.query.pages
                            .forEach(function (page) {

                                if (
                                    page.missing ||
                                    !page.revisions ||
                                    !page.revisions.length
                                ) {
                                    return;
                                }

                                var revision =
                                    page.revisions[0];

                                var text = '';

                                if (
                                    revision.slots &&
                                    revision.slots.main
                                ) {

                                    text =
                                        revision.slots.main.content ||
                                        revision.slots.main['*'] ||
                                        '';

                                } else {

                                    text =
                                        revision.content ||
                                        revision['*'] ||
                                        '';

                                }

                                result.push({
                                    title:
                                        page.title,

                                    text:
                                        text
                                });

                            });

                    }
                );

                return result;

            });

    }


    function parseEntryData(text) {

        var match =
            String(
                text || ''
            ).match(
                /\{\{\s*EntryData\b([\s\S]*?)\n?\}\}/i
            );

        if (!match) {
            return null;
        }

        var data = {};
        var currentKey = null;

        match[1]
            .split(/\r?\n/)
            .forEach(function (line) {

                var parameter =
                    line.match(
                        /^\s*\|\s*([^=]+?)\s*=\s*(.*)$/
                    );

                if (
                    parameter
                ) {

                    currentKey =
                        parameter[1]
                            .trim()
                            .toLowerCase();

                    data[currentKey] =
                        decodeTemplateValue(
                            parameter[2]
                                .trim()
                        );

                    return;

                }

                if (
                    currentKey &&
                    line.trim()
                ) {

                    data[currentKey] +=
                        '\n' +
                        line.trim();

                }

            });

        return data;

    }


    function decodeTemplateValue(value) {

        return String(
            value || ''
        )
            .replace(
                /&#124;/g,
                '|'
            )
            .replace(
                /&#123;&#123;/g,
                '{{'
            )
            .replace(
                /&#125;&#125;/g,
                '}}'
            )
            .replace(
                /}&#125;/g,
                '}}'
            );

    }


    function getNameFromPage(page) {

        return String(
            page || ''
        )
            .replace(
                /^[^:]+:\s*/,
                ''
            )
            .trim();

    }


    function getWikiImageUrl(filename) {

        filename =
            String(
                filename || ''
            )
                .replace(
                    /^File:/i,
                    ''
                )
                .trim();

        return mw.util.getUrl(
            'Special:Redirect/file/' +
            filename
        );

    }


    function sortByName(a, b) {

        return String(
            a.name || ''
        ).localeCompare(
            String(
                b.name || ''
            ),
            undefined,
            {
                sensitivity:
                    'base'
            }
        );

    }


    function createMessage(text) {

        var message =
            document.createElement(
                'div'
            );

        message.className =
            'fish-stats-message';

        message.textContent =
            text;

        return message;

    }


    function createNumberCell(value) {

        return createTextCell(
            formatNumber(value)
        );

    }


    function createTextCell(value) {

        var cell =
            document.createElement(
                'td'
            );

        cell.textContent =
            value;

        return cell;

    }


    function formatPercent(value) {

        return formatNumber(value) + '%';

    }


    function formatNumber(value) {

        value =
            Number(value);

        if (
            !Number.isFinite(value)
        ) {
            return '0';
        }

        return value.toLocaleString(
            undefined,
            {
                maximumFractionDigits:
                    2
            }
        );

    }

}());

(function () {

    var STATISTICS_PAGE =
        'Fish_Statistics';

    var CATEGORIES = {
        Fish:
            'Category:Fish Entries',

        Bait:
            'Category:Bait Entries',

        Tool:
            'Category:Tool Entries',

        Location:
            'Category:Fish Locations'
    };

    var toolEntries =
        [];

    var baitEntries =
        [];

    var currentSelectedToolIndex =
        0;

    var currentEnchantLevel =
        0;

    var currentFortuneLevel =
        0;

    var currentSelectedBaitIndex =
        -1;

    var currentBargainingLevel =
        0;

    var currentFishEntriesMultiplier =
        1;

        $(function () {

            if (
                normalizePageName(
                    mw.config.get('wgPageName')
                ) !==
                normalizePageName(
                    STATISTICS_PAGE
                )
            ) {
                return;
            }

            var container =
                document.getElementById(
                    'fish-statistics-app'
                );

            if (!container) {
                return;
            }

            container.innerHTML =
                '<div class="fish-stats-loading">Loading fish statistics...</div>';

            mw.loader.using([
                'mediawiki.api',
                'mediawiki.util'
            ])
                .then(function () {

                    var api =
                        new mw.Api();

                    return Promise.all([
                        loadLocations(api),
                        loadFish(api),
                        loadTools(api),
                        loadBaits(api)
                    ]);

                })
                .then(function (results) {

                    var locations =
                        results[0];

                    var fishEntries =
                        results[1];

                    renderStatistics(
                        container,
                        locations,
                        fishEntries
                    );

                })
                .catch(function (error) {

                    console.error(
                        'Fish Statistics Error:',
                        error
                    );

                    container.innerHTML =
                        '<div class="fish-stats-error">Could not load fish statistics.</div>';

                });

        });

    function normalizePageName(value) {

        return String(
            value || ''
        )
            .replace(/_/g, ' ')
            .replace(/\s+/g, ' ')
            .trim()
            .toLowerCase();

    }


    function loadLocations(api) {

        return getCategoryEntryPages(
            api,
            CATEGORIES.Location,
            'Location'
        )
            .then(function (entries) {

                var locations =
                    entries.map(function (entry) {

                        return {
                            name:
                                entry.data.name ||
                                getNameFromPage(
                                    entry.page
                                ),

                            image:
                                entry.data.image ||
                                ''
                        };

                    });

                locations.sort(sortByName);

                return locations;

            });

    }

    function loadTools(api) {

        return getCategoryEntryPages(
            api,
            CATEGORIES.Tool,
            'Tool'
        )
            .then(function (entries) {

                toolEntries =
                    entries.map(function (entry) {

                        return {
                            name:
                                entry.data.name ||
                                getNameFromPage(
                                    entry.page
                                ),

                            image:
                                entry.data.image ||
                                '',

                            baseCost:
                                entry.data.base_cost ||
                                '',

                            rodType:
                                String(
                                    entry.data.rod_type ||
                                    'Unassigned'
                                ).trim() ||
                                'Unassigned',

                            luck:
                                entry.data.luck !==
                                undefined
                                    ? Number(
                                        entry.data.luck
                                    )
                                    : 0
                        };

                    });

                toolEntries.sort(function (
                    a,
                    b
                ) {

                    var aCost =
                        Number(
                            a.baseCost
                        );

                    var bCost =
                        Number(
                            b.baseCost
                        );

                    if (
                        !Number.isFinite(
                            aCost
                        )
                    ) {
                        aCost = Infinity;
                    }

                    if (
                        !Number.isFinite(
                            bCost
                        )
                    ) {
                        bCost = Infinity;
                    }

                    if (
                        aCost !==
                        bCost
                    ) {

                        return (
                            aCost -
                            bCost
                        );

                    }

                    return sortByName(
                        a,
                        b
                    );

                });

                return toolEntries;

            });

    }


    function loadBaits(api) {

        return getCategoryEntryPages(
            api,
            CATEGORIES.Bait,
            'Bait'
        )
            .then(function (entries) {

                baitEntries =
                    entries.map(function (entry) {

                        return {
                            name:
                                entry.data.name ||
                                getNameFromPage(
                                    entry.page
                                ),

                            image:
                                entry.data.image ||
                                '',

                            rarity:
                                entry.data.rarity ||
                                ''
                        };

                    });

                baitEntries.sort(
                    sortByName
                );

                return baitEntries;

            });

    }

    function loadFish(api) {

        return getCategoryEntryPages(
            api,
            CATEGORIES.Fish,
            'Fish'
        )
            .then(function (entries) {

                return entries.map(function (entry) {

                    var fishPoints =
                        Number(
                            String(
                                entry.data.base_sell_price ||
                                '0'
                            ).replace(/,/g, '')
                        );

                    if (
                        !Number.isFinite(
                            fishPoints
                        )
                    ) {
                        fishPoints = 0;
                    }

                    return {
                        name:
                            entry.data.name ||
                            getNameFromPage(
                                entry.page
                            ),

                        image:
                            entry.data.image ||
                            '',

                        rarity:
                            entry.data.rarity ||
                            '',

                        fishPoints:
                            fishPoints,

                        weights:
                            parseLocationWeights(
                                entry.data.location_weights
                            )
                    };

                });

            });

    }


    function renderStatistics(
        container,
        locations,
        fishEntries
    ) {

        container.innerHTML = '';

        var shell =
            document.createElement(
                'div'
            );

        shell.className =
            'fish-stats-shell';

        var title =
            document.createElement(
                'div'
            );

        title.className =
            'fish-stats-title';

        title.textContent =
            'Fish Statistics';

        shell.appendChild(
            title
        );

        var subtitle =
            document.createElement(
                'div'
            );

        subtitle.className =
            'fish-stats-subtitle';

        subtitle.textContent =
            'Average Fish Points per area, weighted by each fish\'s catch weight.';

        shell.appendChild(
            subtitle
        );

        shell.appendChild(
            createModifierPanel(
                container,
                locations,
                fishEntries
            )
        );

        if (
            !locations.length
        ) {

            shell.appendChild(
                createMessage(
                    'No locations have been published yet.'
                )
            );

            container.appendChild(
                shell
            );

            return;

        }

        shell.appendChild(
            createLeaderboard(
                locations,
                fishEntries
            )
        );

        locations.forEach(function (
            location
        ) {

            shell.appendChild(
                createLocationSection(
                    location,
                    fishEntries
                )
            );

        });

        container.appendChild(
            shell
        );

    }

    function createModifierPanel(
