                    ]
                ) {

                    toolTypeGroups[
                        rodTypeKey
                    ] = {
                        name:
                            rodType,

                        tools:
                            []
                    };

                    toolTypeOrder.push(
                        rodTypeKey
                    );

                }


                toolTypeGroups[
                    rodTypeKey
                ].tools.push({
                    tool:
                        tool,

                    index:
                        index
                });

            }
        );


        toolTypeOrder.forEach(
            function (
                rodTypeKey
            ) {

                var group =
                    toolTypeGroups[
                        rodTypeKey
                    ];

                var optgroup =
                    document.createElement(
                        'optgroup'
                    );

                optgroup.label =
                    group.name;


                group.tools.forEach(
