            toolSelect.appendChild(
                noToolOption
            );

        }


        toolField.appendChild(
            toolText
        );

        toolField.appendChild(
            toolSelect
        );

        luckSection.appendChild(
            toolField
        );

        var enchantField =
            document.createElement(
                'label'
            );

        enchantField.className =
            'fish-stats-modifier-field';


        var enchantText =
            document.createElement(
                'span'
            );

        enchantText.textContent =
            'Ultra Enchant:';


        var enchantInput =
