            );

        baitButtonImage.className =
            'fish-stats-bait-select-image';


        var baitButtonName =
            document.createElement(
                'span'
            );


        if (
            currentSelectedBaitIndex >= 0 &&
            baitEntries[
                currentSelectedBaitIndex
            ]
        ) {

            var currentBait =
                baitEntries[
                    currentSelectedBaitIndex
                ];

            baitButtonName.textContent =
                currentBait.name;

            if (
                currentBait.image
            ) {

                baitButtonImage.src =
                    getWikiImageUrl(
                        currentBait.image
                    );

                baitButtonImage.alt =
                    currentBait.name;

                baitButtonImage.style.display =
                    'block';

            } else {

                baitButtonImage.style.display =
                    'none';

            }

        } else {

            baitButtonName.textContent =
                'Choose a bait';

            baitButtonImage.style.display =
                'none';

        }


        baitButton.appendChild(
            baitButtonImage
        );

        baitButton.appendChild(
            baitButtonName
        );


        var baitPicker =
            document.createElement(
                'div'
            );

        baitPicker.className =
            'fish-stats-bait-picker';

        baitPicker.style.display =
            'none';


        var baitPickerGrid =
            document.createElement(
                'div'
            );

        baitPickerGrid.className =
            'fish-stats-bait-picker-grid';

        baitPicker.appendChild(
            baitPickerGrid
        );


        function renderBaitPicker() {

            baitPickerGrid.innerHTML =
                '';


            if (
                !baitEntries.length
            ) {

                var empty =
                    document.createElement(
                        'div'
                    );

                empty.className =
                    'fish-stats-bait-empty';

                empty.textContent =
                    'No baits available.';

                baitPickerGrid.appendChild(
                    empty
                );

                return;

            }


            baitEntries.forEach(
                function (
                    bait,
                    index
                ) {

                    var card =
                        document.createElement(
                            'button'
                        );

                    card.type =
                        'button';

                    card.className =
                        'fish-stats-bait-picker-card';


                    if (
                        index ===
                        currentSelectedBaitIndex
                    ) {

                        card.classList.add(
                            'fish-stats-bait-selected'
                        );

                    }


                    if (
                        bait.image
                    ) {

                        var image =
                            document.createElement(
                                'img'
                            );

                        image.src =
                            getWikiImageUrl(
                                bait.image
                            );

                        image.alt =
                            bait.name;

                        card.appendChild(
                            image
                        );

                    }


                    var name =
                        document.createElement(
                            'span'
                        );

                    name.textContent =
                        bait.name;

                    card.appendChild(
                        name
                    );


                    card.addEventListener(
                        'click',
                        function () {

                            currentSelectedBaitIndex =
                                index;

                            baitButtonName.textContent =
                                bait.name;


                            if (
                                bait.image
                            ) {

                                baitButtonImage.src =
                                    getWikiImageUrl(
                                        bait.image
                                    );

                                baitButtonImage.alt =
                                    bait.name;

                                baitButtonImage.style.display =
                                    'block';

                            } else {

                                baitButtonImage.style.display =
                                    'none';

                            }


                            baitPicker.style.display =
                                'none';

                        }
                    );


                    baitPickerGrid.appendChild(
                        card
                    );

                }
            );

        }


        baitButton.addEventListener(
            'click',
            function () {

                if (
                    baitPicker.style.display ===
                    'block'
                ) {

                    baitPicker.style.display =
                        'none';

                    return;

                }

                renderBaitPicker();

                baitPicker.style.display =
                    'block';

            }
        );


        baitField.appendChild(
            baitText
        );

        baitField.appendChild(
            baitButton
        );

        baitField.appendChild(
            baitPicker
        );

        luckSection.appendChild(
            baitField
        );

        var luckNote =
            document.createElement(
                'div'
            );

        luckNote.className =
            'fish-stats-luck-note';

        luckNote.textContent =
            'Fish Luck calculation will be added when the new formula is known.';

        luckSection.appendChild(
            luckNote
        );

        function updateToolSettings() {

            var selectedTool =
                toolEntries[
                    Number(
                        toolSelect.value
                    )
                ];


            var rodType =
                selectedTool
                    ? String(
                        selectedTool.rodType ||
                        ''
                    )
                        .trim()
                        .toLowerCase()
                    : '';


            if (
                rodType ===
                'gun'
            ) {

                enchantText.textContent =
                    'Sharpshooter Enchant:';

                baitField.style.display =
                    'none';

            } else {

                enchantText.textContent =
                    'Ultra Enchant:';

                baitField.style.display =
                    'flex';

            }

        }


        toolSelect.addEventListener(
            'change',
            function () {

                currentSelectedToolIndex =
                    Number(
                        toolSelect.value
                    ) || 0;

                updateToolSettings();

            }
        );


        updateToolSettings();


        panel.appendChild(
            luckSection
        );

        var priceSection =
            document.createElement(
                'div'
            );

        priceSection.className =
            'fish-stats-modifier-section';


        var priceTitle =
            document.createElement(
                'div'
            );

        priceTitle.className =
            'fish-stats-modifier-section-title';

        priceTitle.textContent =
            'Fish Price Modifier';

        priceSection.appendChild(
            priceTitle
        );

        var bargainingField =
            document.createElement(
                'label'
            );

        bargainingField.className =
            'fish-stats-modifier-field';


        var bargainingLabel =
            document.createElement(
                'span'
            );

        bargainingLabel.textContent =
            'Bargaining';


        var bargainingSelect =
            document.createElement(
                'select'
            );

        bargainingSelect.className =
            'fish-stats-modifier-input';


        for (
            var level = 0;
            level <= 20;
            level++
        ) {

            var option =
                document.createElement(
                    'option'
                );

            option.value =
                level;

            option.textContent =
                'Level ' +
                level +
                ' (×' +
                formatMultiplier(
                    1 +
                    (
                        level *
                        0.05
                    )
                ) +
                ')';


            if (
                level ===
                currentBargainingLevel
            ) {

                option.selected =
                    true;

            }


            bargainingSelect.appendChild(
                option
            );

        }


        bargainingSelect.addEventListener(
            'change',
            function () {

                currentBargainingLevel =
                    Number(
                        bargainingSelect.value
                    ) || 0;

                renderStatistics(
                    container,
                    locations,
                    fishEntries
                );

            }
        );


        bargainingField.appendChild(
            bargainingLabel
        );

        bargainingField.appendChild(
            bargainingSelect
        );

        priceSection.appendChild(
            bargainingField
        );

        var entriesField =
            document.createElement(
                'label'
            );

        entriesField.className =
            'fish-stats-modifier-field';


        var entriesLabel =
            document.createElement(
                'span'
            );

        entriesLabel.textContent =
            'Fish Entries';


        var entriesInput =
            document.createElement(
                'input'
            );

        entriesInput.type =
            'number';

        entriesInput.min =
            '1';

        entriesInput.max =
            '1.43';

        entriesInput.step =
            '0.01';

        entriesInput.value =
            currentFishEntriesMultiplier.toFixed(
                2
            );

        entriesInput.className =
            'fish-stats-modifier-input';


        entriesInput.addEventListener(
            'change',
            function () {

                var value =
                    Number(
                        entriesInput.value
                    );


                if (
                    !Number.isFinite(
                        value
                    )
                ) {

                    value = 1;

                }


                value =
                    Math.max(
                        1,
                        Math.min(
                            1.43,
                            value
                        )
                    );


                currentFishEntriesMultiplier =
                    value;


                renderStatistics(
                    container,
                    locations,
                    fishEntries
                );

            }
        );


        var entriesHelp =
            document.createElement(
                'small'
            );

        entriesHelp.textContent =
            '×1.00 to ×1.43';


        entriesField.appendChild(
            entriesLabel
        );

        entriesField.appendChild(
            entriesInput
        );

        entriesField.appendChild(
            entriesHelp
        );

        priceSection.appendChild(
            entriesField
        );

        var total =
            document.createElement(
                'div'
            );

        total.className =
            'fish-stats-total-modifier';

        total.textContent =
            'Total Fish Price Modifier: ×' +
            formatMultiplier(
                getFishPriceMultiplier()
            );

        priceSection.appendChild(
            total
        );


        panel.appendChild(
            priceSection
        );


        return panel;

    }

    function createLeaderboard(
        locations,
        fishEntries
    ) {

        var rankings =
            locations.map(function (
                location
            ) {

                var calculated =
                    calculateLocationStatistics(
                        location.name,
                        fishEntries
                    );

                return {
                    location:
                        location,

                    average:
                        calculated.averagePoints
                };

            });

        rankings.sort(function (
            a,
            b
        ) {

            if (
                b.average !==
                a.average
            ) {

                return (
                    b.average -
                    a.average
                );

            }

            return String(
                a.location.name || ''
            ).localeCompare(
                String(
                    b.location.name || ''
                )
            );

        });

        var leaderboard =
            document.createElement(
                'div'
            );

        leaderboard.className =
            'fish-stats-leaderboard';

        var title =
            document.createElement(
                'div'
            );

        title.className =
            'fish-stats-leaderboard-title';

        title.textContent =
            'Area Rankings';

        leaderboard.appendChild(
            title
        );

        rankings.forEach(function (
            entry,
            index
        ) {

            var row =
                document.createElement(
                    'div'
                );

            row.className =
                'fish-stats-leaderboard-row';

            var rank =
                document.createElement(
                    'div'
                );

            rank.className =
                'fish-stats-leaderboard-rank';

            if (
                index === 0
            ) {

                rank.textContent =
                    '🥇';

            } else if (
                index === 1
            ) {

                rank.textContent =
                    '🥈';

            } else if (
                index === 2
            ) {

                rank.textContent =
                    '🥉';

            } else {

                rank.textContent =
                    String(
                        index + 1
                    );

            }

            var name =
                document.createElement(
                    'div'
                );

            name.className =
                'fish-stats-leaderboard-name';

            name.textContent =
                entry.location.name;

            var average =
                document.createElement(
                    'div'
                );

            average.className =
                'fish-stats-leaderboard-average';

            average.textContent =
                formatNumber(
                    entry.average
                ) +
                ' avg Fish Points';

            row.appendChild(
                rank
            );

            row.appendChild(
                name
            );

            row.appendChild(
                average
            );

            leaderboard.appendChild(
                row
            );

        });

        return leaderboard;

    }

