                    'No fish can currently be caught here.'
                )
            );

            return section;

        }

        var tableWrap =
            document.createElement(
                'div'
            );

        tableWrap.className =
            'fish-stats-table-wrap';

        var table =
            document.createElement(
                'table'
            );

        table.className =
            'fish-stats-table';

        table.innerHTML =
            '<thead>' +
                '<tr>' +
                    '<th>Fish</th>' +
                    '<th>Weight</th>' +
                    '<th>Chance</th>' +
                    '<th>Fish Points</th>' +
                    '<th>Weighted Points</th>' +
                '</tr>' +
            '</thead>';

        var tbody =
            document.createElement(
                'tbody'
            );

        calculated.entries.forEach(
            function (entry) {

                var row =
                    document.createElement(
                        'tr'
                    );

                var fishCell =
                    document.createElement(
                        'td'
                    );

                fishCell.className =
                    'fish-stats-fish-cell';

                if (
                    entry.fish.image
                ) {

                    var fishImage =
                        document.createElement(
                            'img'
                        );

                    fishImage.src =
                        getWikiImageUrl(
                            entry.fish.image
                        );

                    fishImage.alt =
                        entry.fish.name;

                    fishCell.appendChild(
                        fishImage
                    );

                }

                var fishName =
                    document.createElement(
                        'span'
                    );

                fishName.textContent =
                    entry.fish.name;

                fishCell.appendChild(
                    fishName
                );

                row.appendChild(
                    fishCell
                );

                row.appendChild(
                    createNumberCell(
                        entry.weight
                    )
                );

                row.appendChild(
                    createTextCell(
                        formatPercent(
                            entry.chance
                        )
                    )
                );

                row.appendChild(
                    createNumberCell(
                        entry.modifiedFishPoints
                    )
                );

                row.appendChild(
                    createNumberCell(
                        entry.weightedPoints
                    )
                );

                tbody.appendChild(
                    row
                );

            }
        );

        var totalRow =
            document.createElement(
                'tr'
            );

        totalRow.className =
            'fish-stats-total-row';

        var totalLabel =
            document.createElement(
                'td'
            );

        totalLabel.textContent =
            'Total';

        totalRow.appendChild(
            totalLabel
        );

        totalRow.appendChild(
            createNumberCell(
                calculated.totalWeight
            )
        );

        totalRow.appendChild(
            createTextCell(
                '100%'
            )
        );

        totalRow.appendChild(
            createTextCell(
                '—'
            )
        );

        totalRow.appendChild(
            createNumberCell(
                calculated.totalWeightedPoints
            )
        );

        tbody.appendChild(
            totalRow
        );

        table.appendChild(
