        );

        tableWrap.appendChild(
            table
        );

        section.appendChild(
            tableWrap
        );

        var formula =
            document.createElement(
                'div'
            );

        formula.className =
            'fish-stats-formula';

        formula.textContent =
            'Average = Total Weighted Points ÷ Total Weight = ' +
            formatNumber(
                calculated.totalWeightedPoints
            ) +
            ' ÷ ' +
            formatNumber(
                calculated.totalWeight
            ) +
            ' = ' +
            formatNumber(
                calculated.averagePoints
            );

        section.appendChild(
            formula
        );

        return section;

    }

    function getEntryLuckMultiplier(
        value
    ) {

        var multiplier =
            Number(
                value
            );

        if (
            !Number.isFinite(
                multiplier
            )
        ) {
            return 1;
        }

        return Math.max(
            0,
            multiplier
        );

    }


    function getSelectedFishLuckTool() {

        return (
            toolEntries[
                currentSelectedToolIndex
            ] ||
            null
        );

    }


    function getCurrentFishLuckMultiplier() {

        var multiplier =
            1;

        var selectedTool =
            getSelectedFishLuckTool();

        if (
            selectedTool
        ) {

            multiplier *=
                getEntryLuckMultiplier(
                    selectedTool.luck
                );

        }

        var enchantLevel =
            Number(
                currentEnchantLevel
            );

        if (
            !Number.isFinite(
                enchantLevel
            ) ||
            enchantLevel < 0
        ) {
            enchantLevel = 0;
        }

        multiplier *=
            1 +
            (
                enchantLevel *
                0.1
            );

        var fortuneLevel =
            Number(
                currentFortuneLevel
            );

        if (
            !Number.isFinite(
                fortuneLevel
            ) ||
            fortuneLevel < 0
        ) {
            fortuneLevel = 0;
        }

        fortuneLevel =
            Math.min(
                20,
                fortuneLevel
            );

        multiplier *=
            1 +
            (
                fortuneLevel *
                0.05
            );

        var rodType =
            selectedTool
                ? String(
                    selectedTool.rodType ||
                    ''
                )
                    .trim()
                    .toLowerCase()
                : '';

        if (
            rodType !==
                'gun' &&
            currentSelectedBaitIndex >=
                0
        ) {

            var selectedBait =
                baitEntries[
                    currentSelectedBaitIndex
                ];

            if (
                selectedBait
            ) {

                multiplier *=
                    getEntryLuckMultiplier(
                        selectedBait.luck
                    );

            }

        }

        return Math.max(
            0,
            multiplier
        );

    }


    function sortByFishLuckSpawnOrder(
        a,
        b
    ) {

        if (
            b.baseWeight !==
            a.baseWeight
        ) {

            return (
                b.baseWeight -
                a.baseWeight
            );

        }

        return String(
            a.fish.name || ''
        ).localeCompare(
            String(
                b.fish.name || ''
            )
        );

    }

    function getFishPriceMultiplier() {

        var bargainingMultiplier =
            1 +
            (
                currentBargainingLevel *
                0.05
            );

        return (
            bargainingMultiplier *
            currentFishEntriesMultiplier
        );

    }


    function formatMultiplier(value) {

        return Number(
            value
        ).toFixed(
            2
        );

    }

    function calculateLocationStatistics(
        locationName,
        fishEntries
    ) {

        var result = [];
        var totalWeight = 0;
        var totalWeightedPoints = 0;

        fishEntries.forEach(function (
            fish
        ) {

            var baseWeight =
                getFishWeightForLocation(
                    fish,
                    locationName
                );

            if (
                baseWeight <= 0
            ) {
                return;
            }

            var modifiedFishPoints =
                fish.fishPoints *
                getFishPriceMultiplier();

            result.push({
                fish:
                    fish,

                baseWeight:
                    baseWeight,

                weight:
                    baseWeight,

                modifiedFishPoints:
                    modifiedFishPoints,

                weightedPoints:
                    0,

                chance:
                    0
            });

        });

        result.sort(
            sortByFishLuckSpawnOrder
        );


        var fishLuckMultiplier =
            getCurrentFishLuckMultiplier();

        if (
            result.length > 1
        ) {

            result.forEach(function (
                entry,
                index
            ) {

                var rarityScale =
                    index /
                    (
                        result.length -
                        1
                    );

                var weightMultiplier =
                    Math.pow(
                        fishLuckMultiplier,
                        rarityScale
                    );

                entry.weight =
                    entry.baseWeight *
                    weightMultiplier;

            });

        }


        result.forEach(function (
            entry
        ) {

            entry.weightedPoints =
                entry.weight *
                entry.modifiedFishPoints;

            totalWeight +=
                entry.weight;

            totalWeightedPoints +=
                entry.weightedPoints;

        });


        result.forEach(function (
            entry
        ) {

            entry.chance =
                totalWeight > 0
                    ? (
                        entry.weight /
                        totalWeight
                    ) * 100
                    : 0;

        });


        result.sort(function (
            a,
            b
        ) {

            if (
                b.chance !==
                a.chance
            ) {

                return (
                    b.chance -
                    a.chance
                );

            }

            return String(
                a.fish.name || ''
            ).localeCompare(
                String(
                    b.fish.name || ''
                )
            );

        });


        return {
            entries:
                result,

            totalWeight:
                totalWeight,

            totalWeightedPoints:
                totalWeightedPoints,

            averagePoints:
                totalWeight > 0
                    ? totalWeightedPoints /
                        totalWeight
                    : 0
        };

    }

    function getFishWeightForLocation(
        fish,
        locationName
    ) {

        var target =
            String(
                locationName || ''
            )
                .trim()
                .toLowerCase();

        for (
            var i = 0;
            i < fish.weights.length;
            i++
        ) {

            if (
                String(
                    fish.weights[i].location
                )
                    .trim()
                    .toLowerCase() ===
                target
            ) {

                return Number(
                    fish.weights[i].weight
                ) || 0;

            }

        }

        return 0;

    }


    function parseLocationWeights(value) {

        var result = [];

        String(
            value || ''
        )
            .split(';')
            .forEach(function (part) {

                part =
                    part.trim();

                if (!part) {
                    return;
                }

                var separator =
                    part.lastIndexOf(':');

                if (
                    separator === -1
                ) {
                    return;
                }

                var location =
                    part
                        .slice(
                            0,
                            separator
                        )
                        .trim();

                var weight =
                    Number(
                        part
                            .slice(
                                separator + 1
                            )
                            .trim()
                    );

                if (
                    !location ||
                    !Number.isFinite(weight) ||
                    weight <= 0
                ) {
                    return;
                }

                result.push({
                    location:
                        location,

                    weight:
                        weight
                });

            });

        return result;

    }


    function getCategoryEntryPages(
        api,
        category,
        expectedType
    ) {

        return getAllCategoryMembers(
            api,
            category
        )
            .then(function (titles) {

                if (!titles.length) {
                    return [];
                }

                return getPagesContents(
                    api,
                    titles
                );

            })
            .then(function (pages) {

                if (!pages) {
                    return [];
                }

                var result = [];

                pages.forEach(function (page) {

                    var data =
                        parseEntryData(
                            page.text
                        );

                    if (!data) {
                        return;
                    }

                    if (
                        expectedType &&
                        String(
                            data.type || ''
                        ).toLowerCase() !==
                        expectedType.toLowerCase()
                    ) {
                        return;
                    }

                    result.push({
                        page:
                            page.title,

                        data:
                            data
                    });

                });

                return result;

            });

    }


    function getAllCategoryMembers(
        api,
        category,
        cmcontinue
    ) {

        var params = {
            action:
                'query',

            list:
                'categorymembers',

            cmtitle:
                category,

            cmlimit:
                'max',

            cmtype:
                'page',

            format:
                'json',

            formatversion:
                2
        };

        if (
            cmcontinue
        ) {
            params.cmcontinue =
                cmcontinue;
        }

        return new Promise(
            function (
                resolve,
                reject
            ) {

                api.get(params)
                    .done(resolve)
                    .fail(reject);

            }
        )
            .then(function (response) {

                var titles = [];

                if (
                    response.query &&
                    response.query.categorymembers
                ) {

                    titles =
                        response.query.categorymembers
                            .map(function (page) {
                                return page.title;
                            });

                }

                if (
                    response.continue &&
                    response.continue.cmcontinue
                ) {

                    return getAllCategoryMembers(
                        api,
                        category,
                        response.continue.cmcontinue
                    )
                        .then(function (more) {

                            return titles.concat(
                                more
                            );

                        });

                }

                return titles;

            });

    }


    function getPagesContents(
        api,
        titles
    ) {

        var chunks = [];

        for (
            var i = 0;
            i < titles.length;
            i += 50
        ) {

            chunks.push(
                titles.slice(
                    i,
                    i + 50
                )
            );

        }

        return Promise.all(
            chunks.map(function (chunk) {

                return new Promise(
                    function (
                        resolve,
                        reject
                    ) {

                        api.get({
                            action:
                                'query',

                            prop:
                                'revisions',

                            titles:
                                chunk.join('|'),

                            rvprop:
                                'content',

                            rvslots:
                                'main',

                            redirects:
                                1,

                            format:
                                'json',

                            formatversion:
                                2
                        })
                            .done(resolve)
                            .fail(reject);

                    }
                );

            })
        )
            .then(function (responses) {

                var result = [];

                responses.forEach(
                    function (response) {

                        if (
                            !response.query ||
                            !response.query.pages
                        ) {
                            return;
                        }

                        response.query.pages
                            .forEach(function (page) {

                                if (
                                    page.missing ||
                                    !page.revisions ||
                                    !page.revisions.length
                                ) {
                                    return;
                                }

                                var revision =
                                    page.revisions[0];

                                var text = '';

                                if (
                                    revision.slots &&
                                    revision.slots.main
                                ) {

                                    text =
                                        revision.slots.main.content ||
                                        revision.slots.main['*'] ||
                                        '';

                                } else {

                                    text =
                                        revision.content ||
                                        revision['*'] ||
                                        '';

                                }

                                result.push({
                                    title:
                                        page.title,

                                    text:
                                        text
                                });

                            });

                    }
                );

                return result;

            });

    }


    function parseEntryData(text) {

        var match =
            String(
                text || ''
            ).match(
                /\{\{\s*EntryData\b([\s\S]*?)\n?\}\}/i
            );

        if (!match) {
            return null;
        }

        var data = {};
        var currentKey = null;

        match[1]
            .split(/\r?\n/)
            .forEach(function (line) {

                var parameter =
                    line.match(
                        /^\s*\|\s*([^=]+?)\s*=\s*(.*)$/
                    );

                if (
                    parameter
                ) {

                    currentKey =
                        parameter[1]
                            .trim()
                            .toLowerCase();

                    data[currentKey] =
                        decodeTemplateValue(
                            parameter[2]
                                .trim()
                        );

                    return;

                }

                if (
                    currentKey &&
                    line.trim()
                ) {

                    data[currentKey] +=
                        '\n' +
                        line.trim();

                }

            });

        return data;

    }


    function decodeTemplateValue(value) {

        return String(
            value || ''
        )
            .replace(
                /&#124;/g,
                '|'
            )
            .replace(
                /&#123;&#123;/g,
                '{{'
            )
            .replace(
                /&#125;&#125;/g,
                '}}'
            )
            .replace(
                /}&#125;/g,
                '}}'
            );

    }


    function getNameFromPage(page) {

        return String(
            page || ''
        )
            .replace(
                /^[^:]+:\s*/,
                ''
            )
            .trim();

    }


    function getWikiImageUrl(filename) {

        filename =
            String(
                filename || ''
            )
                .replace(
                    /^File:/i,
                    ''
                )
                .trim();

        return mw.util.getUrl(
            'Special:Redirect/file/' +
            filename
        );

    }


    function sortByName(a, b) {

        return String(
            a.name || ''
        ).localeCompare(
            String(
                b.name || ''
            ),
            undefined,
            {
                sensitivity:
                    'base'
            }
        );

    }


    function createMessage(text) {

        var message =
            document.createElement(
                'div'
            );

        message.className =
            'fish-stats-message';

        message.textContent =
            text;

        return message;

    }


    function createNumberCell(value) {

        return createTextCell(
            formatNumber(value)
        );

    }


    function createTextCell(value) {

        var cell =
            document.createElement(
                'td'
            );

        cell.textContent =
            value;

        return cell;

    }


    function formatPercent(value) {

        return formatNumber(value) + '%';

    }


    function formatNumber(value) {

        value =
            Number(value);

        if (
            !Number.isFinite(value)
        ) {
            return '0';
        }

        return value.toLocaleString(
            undefined,
            {
                maximumFractionDigits:
                    2
            }
        );

    }

}());

(function () {

    var STATISTICS_PAGE =
        'Fish_Statistics';

    var CATEGORIES = {
        Fish:
            'Category:Fish Entries',

        Bait:
            'Category:Bait Entries',

        Tool:
            'Category:Tool Entries',

        Location:
            'Category:Fish Locations'
    };

    var toolEntries =
        [];

    var baitEntries =
        [];

    var currentSelectedToolIndex =
        0;

    var currentEnchantLevel =
        0;

    var currentFortuneLevel =
        0;

    var currentSelectedBaitIndex =
        -1;

    var currentBargainingLevel =
        0;

    var currentFishEntriesMultiplier =
        1;

    var currentFortuneEnchantLevel =
        0;

        $(function () {

            if (
                normalizePageName(
                    mw.config.get('wgPageName')
                ) !==
                normalizePageName(
                    STATISTICS_PAGE
                )
            ) {
                return;
            }

            var container =
                document.getElementById(
                    'fish-statistics-app'
                );

            if (!container) {
                return;
            }

            container.innerHTML =
                '<div class="fish-stats-loading">Loading fish statistics...</div>';

            mw.loader.using([
                'mediawiki.api',
                'mediawiki.util'
            ])
                .then(function () {

                    var api =
                        new mw.Api();

                    return Promise.all([
                        loadLocations(api),
                        loadFish(api),
                        loadTools(api),
                        loadBaits(api)
                    ]);

                })
                .then(function (results) {

                    var locations =
                        results[0];

                    var fishEntries =
                        results[1];

                    renderStatistics(
                        container,
                        locations,
                        fishEntries
                    );

                })
                .catch(function (error) {

                    console.error(
                        'Fish Statistics Error:',
                        error
                    );

                    container.innerHTML =
                        '<div class="fish-stats-error">Could not load fish statistics.</div>';

                });

        });

    function normalizePageName(value) {

        return String(
            value || ''
        )
            .replace(/_/g, ' ')
            .replace(/\s+/g, ' ')
            .trim()
            .toLowerCase();

    }


    function loadLocations(api) {

        return getCategoryEntryPages(
            api,
            CATEGORIES.Location,
            'Location'
        )
            .then(function (entries) {

                var locations =
                    entries.map(function (entry) {

                        return {
                            name:
                                entry.data.name ||
                                getNameFromPage(
                                    entry.page
                                ),

                            image:
                                entry.data.image ||
                                ''
                        };

                    });

                locations.sort(sortByName);

                return locations;

            });

    }

    function loadTools(api) {

        return getCategoryEntryPages(
            api,
            CATEGORIES.Tool,
            'Tool'
        )
            .then(function (entries) {

                toolEntries =
                    entries.map(function (entry) {

                        return {
                            name:
                                entry.data.name ||
                                getNameFromPage(
                                    entry.page
                                ),

                            image:
                                entry.data.image ||
                                '',

                            baseCost:
                                entry.data.base_cost ||
                                '',

                            rodType:
                                String(
                                    entry.data.rod_type ||
                                    'Unassigned'
                                ).trim() ||
                                'Unassigned',

                            luck:
                                entry.data.luck !==
                                    undefined &&
                                entry.data.luck !==
                                    ''
                                    ? Number(
                                        entry.data.luck
                                    )
                                    : 1
                        };

                    });

                toolEntries.sort(function (
                    a,
                    b
                ) {

                    var aCost =
                        Number(
                            a.baseCost
                        );

                    var bCost =
                        Number(
                            b.baseCost
                        );

                    if (
                        !Number.isFinite(
                            aCost
                        )
                    ) {
                        aCost = Infinity;
                    }

                    if (
                        !Number.isFinite(
                            bCost
                        )
                    ) {
                        bCost = Infinity;
                    }

                    if (
                        aCost !==
                        bCost
                    ) {

                        return (
                            aCost -
                            bCost
                        );

                    }

                    return sortByName(
                        a,
                        b
                    );

                });

                return toolEntries;

            });

    }


    function loadBaits(api) {

        return getCategoryEntryPages(
            api,
            CATEGORIES.Bait,
            'Bait'
        )
            .then(function (entries) {

                baitEntries =
                    entries.map(function (entry) {

                        return {
                            name:
                                entry.data.name ||
                                getNameFromPage(
                                    entry.page
                                ),

                            image:
                                entry.data.image ||
                                '',

                            rarity:
                                entry.data.rarity ||
                                '',

                            luck:
                                entry.data.luck !==
                                    undefined &&
                                entry.data.luck !==
                                    ''
                                    ? Number(
                                        entry.data.luck
                                    )
                                    : 1
                        };

                    });

                baitEntries.sort(
                    sortByName
                );

                return baitEntries;

            });

    }

    function loadFish(api) {

        return getCategoryEntryPages(
            api,
            CATEGORIES.Fish,
            'Fish'
        )
            .then(function (entries) {

                return entries.map(function (entry) {

                    var fishPoints =
                        Number(
                            String(
                                entry.data.base_sell_price ||
                                '0'
                            ).replace(/,/g, '')
                        );

                    if (
                        !Number.isFinite(
                            fishPoints
                        )
                    ) {
                        fishPoints = 0;
                    }

                    return {
                        name:
                            entry.data.name ||
                            getNameFromPage(
                                entry.page
                            ),

                        image:
                            entry.data.image ||
                            '',

                        rarity:
                            entry.data.rarity ||
                            '',

                        fishPoints:
                            fishPoints,

                        weights:
                            parseLocationWeights(
                                entry.data.location_weights
                            )
                    };

                });

            });

    }


    function renderStatistics(
        container,
        locations,
        fishEntries
    ) {

        container.innerHTML = '';

        var shell =
            document.createElement(
                'div'
            );

        shell.className =
            'fish-stats-shell';

        var title =
            document.createElement(
                'div'
            );

        title.className =
            'fish-stats-title';

        title.textContent =
            'Fish Statistics';

        shell.appendChild(
            title
        );

        var subtitle =
            document.createElement(
                'div'
            );

        subtitle.className =
            'fish-stats-subtitle';

        subtitle.textContent =
            'Average Fish Points per area, weighted by each fish\'s catch weight.';

        shell.appendChild(
            subtitle
        );

        shell.appendChild(
            createModifierPanel(
                container,
                locations,
                fishEntries
            )
        );

        if (
            !locations.length
        ) {

            shell.appendChild(
                createMessage(
                    'No locations have been published yet.'
                )
            );

            container.appendChild(
                shell
            );

            return;

        }

        shell.appendChild(
            createLeaderboard(
                locations,
                fishEntries
            )
        );

        locations.forEach(function (
            location
        ) {

            shell.appendChild(
                createLocationSection(
                    location,
                    fishEntries
                )
            );

        });

        container.appendChild(
            shell
        );

    }

    function createModifierPanel(
        container,
        locations,
        fishEntries
    ) {

        var panel =
