                'div'
            );

        panel.className =
            'fish-stats-modifiers';

        var title =
            document.createElement(
                'div'
            );

        title.className =
            'fish-stats-modifiers-title';

        title.textContent =
            'Modifiers';

        panel.appendChild(
            title
        );

        var luckSection =
            document.createElement(
                'div'
            );

        luckSection.className =
            'fish-stats-modifier-section';


        var luckTitle =
            document.createElement(
                'div'
            );

        luckTitle.className =
            'fish-stats-modifier-section-title';

        luckTitle.textContent =
            'Fish Luck Modifier';

        luckSection.appendChild(
            luckTitle
        );

        var toolField =
            document.createElement(
                'label'
            );

        toolField.className =
            'fish-stats-modifier-field';


        var toolText =
            document.createElement(
                'span'
            );

        toolText.textContent =
            'Select your tool:';


        var toolSelect =
            document.createElement(
                'select'
            );

        toolSelect.className =
            'fish-stats-modifier-input';


        if (
            currentSelectedToolIndex >=
            toolEntries.length
        ) {

            currentSelectedToolIndex =
                0;

        }


        var toolTypeGroups =
            {};

        var toolTypeOrder =
            [];


        toolEntries.forEach(
            function (
                tool,
                index
            ) {

                var rodType =
                    String(
                        tool.rodType ||
                        'Unassigned'
                    ).trim() ||
                    'Unassigned';

                var rodTypeKey =
                    rodType.toLowerCase();


                if (
                    !toolTypeGroups[
                        rodTypeKey
                    ]
                ) {

                    toolTypeGroups[
                        rodTypeKey
                    ] = {
                        name:
                            rodType,

                        tools:
                            []
                    };

                    toolTypeOrder.push(
                        rodTypeKey
                    );

                }


                toolTypeGroups[
                    rodTypeKey
                ].tools.push({
                    tool:
                        tool,

                    index:
                        index
                });

            }
        );


        toolTypeOrder.forEach(
            function (
                rodTypeKey
            ) {

                var group =
                    toolTypeGroups[
                        rodTypeKey
                    ];

                var optgroup =
                    document.createElement(
                        'optgroup'
                    );

                optgroup.label =
                    group.name;


                group.tools.forEach(
                    function (
                        entry
                    ) {

                        var option =
