                    container,
                    locations,
                    fishEntries
                );
            }
        );


        enchantField.appendChild(
            enchantText
        );

        enchantField.appendChild(
            enchantInput
        );

        luckSection.appendChild(
            enchantField
        );

        var upgradeField =
            document.createElement(
                'label'
            );

        upgradeField.className =
            'fish-stats-modifier-field';


        var upgradeText =
