            document.createElement(
                'div'
            );

        baitPickerGrid.className =
            'fish-stats-bait-picker-grid';

        baitPicker.appendChild(
            baitPickerGrid
        );


        function renderBaitPicker() {

            baitPickerGrid.innerHTML =
                '';


            if (
                !baitEntries.length
            ) {

                var empty =
                    document.createElement(
                        'div'
                    );

                empty.className =
                    'fish-stats-bait-empty';

                empty.textContent =
                    'No baits available.';

                baitPickerGrid.appendChild(
                    empty
                );

                return;

            }


            baitEntries.forEach(
                function (
                    bait,
                    index
                ) {

                    var card =
                        document.createElement(
                            'button'
                        );

                    card.type =
                        'button';

                    card.className =
                        'fish-stats-bait-picker-card';


                    if (
                        index ===
                        currentSelectedBaitIndex
                    ) {

                        card.classList.add(
                            'fish-stats-bait-selected'
                        );

                    }


                    if (
                        bait.image
                    ) {

                        var image =
                            document.createElement(
                                'img'
                            );

                        image.src =
                            getWikiImageUrl(
                                bait.image
                            );

                        image.alt =
                            bait.name;

                        card.appendChild(
                            image
                        );

                    }


                    var name =
                        document.createElement(
                            'span'
                        );

                    name.textContent =
                        bait.name;

                    card.appendChild(
                        name
                    );


                    card.addEventListener(
                        'click',
                        function () {

                            currentSelectedBaitIndex =
                                index;

                            renderStatistics(
                                container,
                                locations,
                                fishEntries
                            );

                            baitButtonName.textContent =
                                bait.name;


                            if (
                                bait.image
                            ) {

                                baitButtonImage.src =
                                    getWikiImageUrl(
                                        bait.image
                                    );

                                baitButtonImage.alt =
                                    bait.name;

                                baitButtonImage.style.display =
                                    'block';

                            } else {

                                baitButtonImage.style.display =
                                    'none';

                            }


                            baitPicker.style.display =
                                'none';

                        }
                    );


                    baitPickerGrid.appendChild(
                        card
                    );

                }
            );

        }


        baitButton.addEventListener(
            'click',
            function () {

                if (
                    baitPicker.style.display ===
                    'block'
                ) {

                    baitPicker.style.display =
                        'none';

                    return;

                }

                renderBaitPicker();

                baitPicker.style.display =
                    'block';

            }
        );


        baitField.appendChild(
            baitText
        );

        baitField.appendChild(
            baitButton
        );

        baitField.appendChild(
