        );

        var luckNote =
            document.createElement(
                'div'
            );

        luckNote.className =
            'fish-stats-luck-note';

        luckNote.textContent =
            'Fish Luck changes each fish chance and the average Fish Points.';

        luckSection.appendChild(
            luckNote
        );

        function updateToolSettings() {

            var selectedTool =
                toolEntries[
                    Number(
                        toolSelect.value
                    )
                ];


            var rodType =
                selectedTool
                    ? String(
                        selectedTool.rodType ||
                        ''
                    )
                        .trim()
                        .toLowerCase()
                    : '';


            if (
                rodType ===
                'gun'
            ) {

                enchantText.textContent =
                    'Sharpshooter Enchant:';

                baitField.style.display =
                    'none';

            } else {

                enchantText.textContent =
                    'Ultra Enchant:';

                baitField.style.display =
                    'flex';

            }

        }


        toolSelect.addEventListener(
            'change',
            function () {

                currentSelectedToolIndex =
                    Number(
                        toolSelect.value
                    ) || 0;

                updateToolSettings();

                renderStatistics(
                    container,
                    locations,
                    fishEntries
                );

            }
        );


        updateToolSettings();


        panel.appendChild(
            luckSection
        );

        var priceSection =
            document.createElement(
                'div'
            );

        priceSection.className =
            'fish-stats-modifier-section';


        var priceTitle =
            document.createElement(
                'div'
            );

        priceTitle.className =
            'fish-stats-modifier-section-title';

        priceTitle.textContent =
            'Fish Price Modifier';

        priceSection.appendChild(
            priceTitle
        );

        var bargainingField =
            document.createElement(
                'label'
            );

        bargainingField.className =
            'fish-stats-modifier-field';


        var bargainingLabel =
            document.createElement(
                'span'
            );

        bargainingLabel.textContent =
            'Bargaining';


        var bargainingSelect =
            document.createElement(
                'select'
            );

        bargainingSelect.className =
            'fish-stats-modifier-input';


        for (
            var level = 0;
            level <= 20;
            level++
        ) {

            var option =
                document.createElement(
                    'option'
                );

            option.value =
                level;

            option.textContent =
                'Level ' +
                level +
                ' (×' +
                formatMultiplier(
                    1 +
                    (
                        level *
                        0.05
                    )
                ) +
                ')';


            if (
                level ===
                currentBargainingLevel
            ) {

                option.selected =
                    true;

            }


            bargainingSelect.appendChild(
                option
            );

        }


        bargainingSelect.addEventListener(
            'change',
            function () {

                currentBargainingLevel =
                    Number(
                        bargainingSelect.value
                    ) || 0;

                renderStatistics(
                    container,
                    locations,
                    fishEntries
                );

            }
        );


        bargainingField.appendChild(
            bargainingLabel
        );

        bargainingField.appendChild(
            bargainingSelect
        );

        priceSection.appendChild(
            bargainingField
        );

        var entriesField =
            document.createElement(
                'label'
            );

        entriesField.className =
            'fish-stats-modifier-field';


        var entriesLabel =
            document.createElement(
                'span'
            );

        entriesLabel.textContent =
            'Fish Entries';


        var entriesInput =
            document.createElement(
                'input'
            );

        entriesInput.type =
            'number';

        entriesInput.min =
            '1';

        entriesInput.max =
            '1.43';

        entriesInput.step =
            '0.01';

        entriesInput.value =
            currentFishEntriesMultiplier.toFixed(
                2
            );

        entriesInput.className =
            'fish-stats-modifier-input';


        entriesInput.addEventListener(
            'change',
            function () {

                var value =
                    Number(
                        entriesInput.value
                    );


                if (
                    !Number.isFinite(
                        value
                    )
                ) {

                    value = 1;

                }


                value =
                    Math.max(
                        1,
                        Math.min(
                            1.43,
                            value
                        )
                    );


                currentFishEntriesMultiplier =
                    value;


                renderStatistics(
                    container,
                    locations,
                    fishEntries
                );

            }
        );


        var entriesHelp =
            document.createElement(
                'small'
            );

        entriesHelp.textContent =
            '×1.00 to ×1.43';


        entriesField.appendChild(
            entriesLabel
        );

        entriesField.appendChild(
            entriesInput
        );

        entriesField.appendChild(
            entriesHelp
        );

        priceSection.appendChild(
            entriesField
        );

        var total =
            document.createElement(
                'div'
            );

        total.className =
            'fish-stats-total-modifier';

        total.textContent =
            'Total Fish Price Modifier: ×' +
            formatMultiplier(
                getFishPriceMultiplier()
            );

        priceSection.appendChild(
            total
        );


        panel.appendChild(
            priceSection
        );


        return panel;

    }

    function createLeaderboard(
        locations,
        fishEntries
    ) {

        var rankings =
            locations.map(function (
                location
            ) {

                var calculated =
                    calculateLocationStatistics(
                        location.name,
                        fishEntries
                    );

                return {
                    location:
                        location,

                    average:
                        calculated.averagePoints
                };

            });

        rankings.sort(function (
            a,
            b
        ) {

            if (
                b.average !==
                a.average
            ) {

                return (
                    b.average -
                    a.average
                );

            }

            return String(
                a.location.name || ''
            ).localeCompare(
                String(
                    b.location.name || ''
                )
            );

        });

        var leaderboard =
            document.createElement(
                'div'
            );

        leaderboard.className =
            'fish-stats-leaderboard';

        var title =
            document.createElement(
                'div'
            );

        title.className =
            'fish-stats-leaderboard-title';

        title.textContent =
            'Area Rankings';

        leaderboard.appendChild(
            title
        );

        rankings.forEach(function (
            entry,
            index
        ) {

            var row =
                document.createElement(
                    'div'
                );

            row.className =
                'fish-stats-leaderboard-row';

            var rank =
                document.createElement(
                    'div'
                );

            rank.className =
                'fish-stats-leaderboard-rank';

            if (
                index === 0
            ) {

                rank.textContent =
                    '🥇';

            } else if (
                index === 1
            ) {

                rank.textContent =
                    '🥈';

            } else if (
                index === 2
            ) {

                rank.textContent =
                    '🥉';

            } else {

                rank.textContent =
                    String(
                        index + 1
                    );

            }

            var name =
                document.createElement(
                    'div'
                );

            name.className =
                'fish-stats-leaderboard-name';

            name.textContent =
                entry.location.name;

            var average =
                document.createElement(
                    'div'
                );

            average.className =
                'fish-stats-leaderboard-average';

            average.textContent =
                formatNumber(
                    entry.average
                ) +
                ' avg Fish Points';

            row.appendChild(
                rank
            );

            row.appendChild(
                name
            );

            row.appendChild(
                average
            );

            leaderboard.appendChild(
                row
            );

        });

        return leaderboard;

    }

    function createLocationSection(
        location,
        fishEntries
    ) {

        var calculated =
            calculateLocationStatistics(
                location.name,
                fishEntries
            );

        var section =
            document.createElement(
                'section'
            );

        section.className =
            'fish-stats-location';

        var header =
            document.createElement(
                'div'
            );

        header.className =
            'fish-stats-location-header';

        var heading =
            document.createElement(
                'div'
            );

        heading.className =
            'fish-stats-location-heading';

        if (
            location.image
        ) {

            var image =
                document.createElement(
                    'img'
                );

            image.src =
                getWikiImageUrl(
                    location.image
                );

            image.alt =
                location.name;

            heading.appendChild(
                image
            );

        }

        var name =
            document.createElement(
                'span'
            );

        name.textContent =
            location.name;

        heading.appendChild(
            name
        );

        header.appendChild(
            heading
        );

        var averageBox =
            document.createElement(
                'div'
            );

        averageBox.className =
            'fish-stats-average';

        var averageLabel =
            document.createElement(
                'span'
            );

        averageLabel.textContent =
            'Average Fish Points';

        var averageValue =
            document.createElement(
                'strong'
            );

        averageValue.textContent =
            calculated.totalWeight > 0
                ? formatNumber(
                    calculated.averagePoints
                )
                : 'N/A';

        averageBox.appendChild(
            averageLabel
        );

        averageBox.appendChild(
            averageValue
        );

        header.appendChild(
            averageBox
        );

        section.appendChild(
            header
        );

        if (
            !calculated.entries.length
        ) {

            section.appendChild(
                createMessage(
                    'No fish can currently be caught here.'
                )
            );

            return section;

        }

        var tableWrap =
            document.createElement(
                'div'
            );

        tableWrap.className =
            'fish-stats-table-wrap';

        var table =
            document.createElement(
                'table'
            );

        table.className =
            'fish-stats-table';

        table.innerHTML =
            '<thead>' +
                '<tr>' +
                    '<th>Fish</th>' +
                    '<th>Weight</th>' +
                    '<th>Chance</th>' +
                    '<th>Fish Points</th>' +
                    '<th>Weighted Points</th>' +
                '</tr>' +
            '</thead>';

        var tbody =
            document.createElement(
                'tbody'
            );

        calculated.entries.forEach(
            function (entry) {

                var row =
                    document.createElement(
                        'tr'
                    );

                var fishCell =
                    document.createElement(
                        'td'
                    );

                fishCell.className =
                    'fish-stats-fish-cell';

                if (
                    entry.fish.image
                ) {

                    var fishImage =
                        document.createElement(
                            'img'
                        );

                    fishImage.src =
                        getWikiImageUrl(
                            entry.fish.image
                        );

                    fishImage.alt =
                        entry.fish.name;

                    fishCell.appendChild(
                        fishImage
                    );

                }

                var fishName =
                    document.createElement(
                        'span'
                    );

                fishName.textContent =
                    entry.fish.name;

                fishCell.appendChild(
                    fishName
                );

                row.appendChild(
                    fishCell
                );

                row.appendChild(
                    createNumberCell(
                        entry.weight
                    )
                );

                row.appendChild(
                    createTextCell(
                        formatPercent(
                            entry.chance
                        )
                    )
                );

                row.appendChild(
                    createNumberCell(
                        entry.modifiedFishPoints
                    )
                );

                row.appendChild(
                    createNumberCell(
                        entry.weightedPoints
                    )
                );

                tbody.appendChild(
                    row
                );

            }
        );

        var totalRow =
            document.createElement(
                'tr'
            );

        totalRow.className =
            'fish-stats-total-row';

        var totalLabel =
            document.createElement(
                'td'
            );

        totalLabel.textContent =
            'Total';

        totalRow.appendChild(
            totalLabel
        );

        totalRow.appendChild(
            createNumberCell(
                calculated.totalWeight
            )
        );

        totalRow.appendChild(
            createTextCell(
                '100%'
            )
        );

        totalRow.appendChild(
            createTextCell(
                '—'
            )
        );

        totalRow.appendChild(
            createNumberCell(
                calculated.totalWeightedPoints
            )
        );

        tbody.appendChild(
            totalRow
        );

        table.appendChild(
            tbody
        );

        tableWrap.appendChild(
            table
        );

        section.appendChild(
            tableWrap
        );

        var formula =
            document.createElement(
                'div'
            );

        formula.className =
            'fish-stats-formula';

        formula.textContent =
            'Average = Total Weighted Points ÷ Total Weight = ' +
            formatNumber(
                calculated.totalWeightedPoints
            ) +
            ' ÷ ' +
            formatNumber(
                calculated.totalWeight
            ) +
            ' = ' +
            formatNumber(
                calculated.averagePoints
            );

        section.appendChild(
            formula
        );

        return section;

    }

    function getEntryLuckMultiplier(
        value
    ) {

        var multiplier =
            Number(
                value
            );

        if (
            !Number.isFinite(
                multiplier
            )
        ) {
            return 1;
        }

        return Math.max(
            0,
            multiplier
        );

    }


    function getSelectedFishLuckTool() {

        return (
            toolEntries[
                currentSelectedToolIndex
            ] ||
            null
        );

    }


    function getCurrentFishLuckMultiplier() {

        var multiplier =
            1;

        var selectedTool =
            getSelectedFishLuckTool();

        if (
            selectedTool
        ) {

            multiplier *=
                getEntryLuckMultiplier(
                    selectedTool.luck
                );

        }

        var enchantLevel =
            Number(
                currentEnchantLevel
            );

        if (
            !Number.isFinite(
                enchantLevel
            ) ||
            enchantLevel < 0
        ) {
            enchantLevel = 0;
        }

        multiplier *=
            1 +
            (
                enchantLevel *
                0.1
            );

        var fortuneLevel =
            Number(
                currentFortuneLevel
            );

        if (
            !Number.isFinite(
                fortuneLevel
            ) ||
            fortuneLevel < 0
        ) {
            fortuneLevel = 0;
        }

        fortuneLevel =
            Math.min(
                20,
                fortuneLevel
            );

        multiplier *=
            1 +
            (
                fortuneLevel *
                0.05
            );

        var rodType =
            selectedTool
                ? String(
                    selectedTool.rodType ||
                    ''
                )
                    .trim()
                    .toLowerCase()
                : '';

        if (
            rodType !==
                'gun' &&
            currentSelectedBaitIndex >=
                0
        ) {

            var selectedBait =
                baitEntries[
                    currentSelectedBaitIndex
                ];

            if (
                selectedBait
            ) {

                multiplier *=
                    getEntryLuckMultiplier(
                        selectedBait.luck
                    );

            }

        }

        return Math.max(
            0,
            multiplier
        );

    }


    function sortByFishLuckSpawnOrder(
        a,
        b
    ) {

        if (
            b.baseWeight !==
            a.baseWeight
        ) {

            return (
                b.baseWeight -
                a.baseWeight
            );

        }

        return String(
            a.fish.name || ''
        ).localeCompare(
            String(
                b.fish.name || ''
            )
        );

    }

    function getFortuneEnchantMultiplier() {

        var level =
            Number(
                currentFortuneEnchantLevel
            );

        if (
            !Number.isFinite(
                level
            ) ||
            level < 0
        ) {

            level = 0;

        }

        level =
            Math.min(
                20,
                level
            );

        return (
            1 +
            (
                level *
                0.15
            )
        );

    }

    function getFishPriceMultiplier() {

        var bargainingMultiplier =
            1 +
            (
                currentBargainingLevel *
                0.05
            );

        return (
            bargainingMultiplier *
            currentFishEntriesMultiplier
        );

    }


    function formatMultiplier(value) {

        return Number(
            value
        ).toFixed(
            2
        );

    }

    function calculateLocationStatistics(
        locationName,
        fishEntries
    ) {

        var result = [];
        var totalWeight = 0;
        var totalWeightedPoints = 0;

        fishEntries.forEach(function (
            fish
        ) {

            var baseWeight =
                getFishWeightForLocation(
                    fish,
                    locationName
                );

            if (
                baseWeight <= 0
            ) {
                return;
            }

            var modifiedFishPoints =
                fish.fishPoints *
                getFishPriceMultiplier();

            var expectedFishGain =
                getFortuneEnchantMultiplier();

            var expectedFishPoints =
                modifiedFishPoints *
                expectedFishGain;

            result.push({
                fish:
                    fish,

                baseWeight:
                    baseWeight,

                weight:
                    baseWeight,

                modifiedFishPoints:
                    modifiedFishPoints,

                expectedFishGain:
                    expectedFishGain,

                expectedFishPoints:
                    expectedFishPoints,

                weightedPoints:
                    0,

                chance:
                    0
            });

        });

        result.sort(
            sortByFishLuckSpawnOrder
        );


        var fishLuckMultiplier =
            getCurrentFishLuckMultiplier();

        if (
            result.length > 1
        ) {

            result.forEach(function (
                entry,
                index
            ) {

                var rarityScale =
                    index /
                    (
                        result.length -
                        1
                    );

                var weightMultiplier =
                    Math.pow(
                        fishLuckMultiplier,
                        rarityScale
                    );

                entry.weight =
                    entry.baseWeight *
                    weightMultiplier;

            });

        }


        result.forEach(function (
            entry
        ) {

            entry.weightedPoints =
                entry.weight *
                entry.expectedFishPoints;

            totalWeight +=
                entry.weight;

            totalWeightedPoints +=
                entry.weightedPoints;

        });


        result.forEach(function (
            entry
        ) {

            entry.chance =
                totalWeight > 0
                    ? (
                        entry.weight /
                        totalWeight
                    ) * 100
                    : 0;

        });


        result.sort(function (
            a,
            b
        ) {

            if (
                b.chance !==
                a.chance
            ) {

                return (
                    b.chance -
                    a.chance
                );

            }

            return String(
                a.fish.name || ''
            ).localeCompare(
                String(
                    b.fish.name || ''
                )
            );

        });


        return {
            entries:
                result,

            totalWeight:
                totalWeight,

            totalWeightedPoints:
                totalWeightedPoints,

            averagePoints:
                totalWeight > 0
                    ? totalWeightedPoints /
                        totalWeight
                    : 0
        };

    }

    function getFishWeightForLocation(
        fish,
        locationName
    ) {

        var target =
            String(
                locationName || ''
            )
                .trim()
                .toLowerCase();

        for (
            var i = 0;
            i < fish.weights.length;
            i++
        ) {

            if (
                String(
                    fish.weights[i].location
                )
                    .trim()
                    .toLowerCase() ===
                target
            ) {

                return Number(
                    fish.weights[i].weight
                ) || 0;

            }

        }

        return 0;

    }


    function parseLocationWeights(value) {

        var result = [];

        String(
            value || ''
        )
            .split(';')
            .forEach(function (part) {

                part =
                    part.trim();

                if (!part) {
                    return;
                }

                var separator =
                    part.lastIndexOf(':');

                if (
                    separator === -1
                ) {
                    return;
                }

                var location =
                    part
                        .slice(
                            0,
                            separator
                        )
                        .trim();

                var weight =
                    Number(
                        part
                            .slice(
                                separator + 1
                            )
                            .trim()
                    );

                if (
                    !location ||
                    !Number.isFinite(weight) ||
                    weight <= 0
                ) {
                    return;
                }

                result.push({
                    location:
                        location,

                    weight:
                        weight
                });

            });

        return result;

    }


    function getCategoryEntryPages(
        api,
        category,
        expectedType
    ) {

        return getAllCategoryMembers(
            api,
            category
        )
            .then(function (titles) {

                if (!titles.length) {
                    return [];
                }

                return getPagesContents(
                    api,
                    titles
                );

            })
            .then(function (pages) {

                if (!pages) {
                    return [];
                }

                var result = [];

                pages.forEach(function (page) {

                    var data =
                        parseEntryData(
                            page.text
                        );

                    if (!data) {
                        return;
                    }

                    if (
                        expectedType &&
                        String(
                            data.type || ''
                        ).toLowerCase() !==
                        expectedType.toLowerCase()
                    ) {
                        return;
                    }

                    result.push({
                        page:
                            page.title,

                        data:
                            data
                    });

                });

                return result;

            });

    }


    function getAllCategoryMembers(
        api,
        category,
        cmcontinue
    ) {

        var params = {
            action:
                'query',

            list:
                'categorymembers',

            cmtitle:
                category,

            cmlimit:
                'max',

            cmtype:
                'page',

            format:
                'json',

            formatversion:
                2
        };

        if (
            cmcontinue
        ) {
            params.cmcontinue =
                cmcontinue;
        }

        return new Promise(
            function (
                resolve,
                reject
            ) {

                api.get(params)
                    .done(resolve)
                    .fail(reject);

            }
        )
            .then(function (response) {

                var titles = [];

                if (
                    response.query &&
                    response.query.categorymembers
                ) {

                    titles =
                        response.query.categorymembers
                            .map(function (page) {
                                return page.title;
                            });

                }

                if (
                    response.continue &&
                    response.continue.cmcontinue
                ) {

                    return getAllCategoryMembers(
                        api,
                        category,
                        response.continue.cmcontinue
                    )
                        .then(function (more) {

                            return titles.concat(
                                more
                            );

                        });

                }

                return titles;

            });

    }


    function getPagesContents(
        api,
        titles
    ) {

        var chunks = [];

        for (
            var i = 0;
            i < titles.length;
            i += 50
        ) {

            chunks.push(
                titles.slice(
                    i,
                    i + 50
                )
            );

        }

        return Promise.all(
            chunks.map(function (chunk) {

                return new Promise(
                    function (
                        resolve,
                        reject
                    ) {

                        api.get({
                            action:
                                'query',

                            prop:
                                'revisions',

                            titles:
                                chunk.join('|'),

                            rvprop:
                                'content',

                            rvslots:
                                'main',

                            redirects:
                                1,

                            format:
                                'json',

                            formatversion:
                                2
                        })
                            .done(resolve)
                            .fail(reject);

                    }
                );

            })
        )
            .then(function (responses) {

                var result = [];

                responses.forEach(
                    function (response) {

                        if (
                            !response.query ||
                            !response.query.pages
                        ) {
                            return;
                        }

                        response.query.pages
                            .forEach(function (page) {

                                if (
                                    page.missing ||
                                    !page.revisions ||
                                    !page.revisions.length
                                ) {
                                    return;
                                }

                                var revision =
                                    page.revisions[0];

                                var text = '';

                                if (
                                    revision.slots &&
                                    revision.slots.main
                                ) {

                                    text =
                                        revision.slots.main.content ||
                                        revision.slots.main['*'] ||
                                        '';

                                } else {

                                    text =
                                        revision.content ||
                                        revision['*'] ||
                                        '';

                                }

                                result.push({
                                    title:
                                        page.title,

                                    text:
                                        text
                                });

                            });

                    }
                );

                return result;

            });

    }


    function parseEntryData(text) {

        var match =
            String(
                text || ''
            ).match(
                /\{\{\s*EntryData\b([\s\S]*?)\n?\}\}/i
            );

        if (!match) {
            return null;
        }

        var data = {};
        var currentKey = null;

        match[1]
            .split(/\r?\n/)
            .forEach(function (line) {

                var parameter =
                    line.match(
                        /^\s*\|\s*([^=]+?)\s*=\s*(.*)$/
                    );

                if (
                    parameter
                ) {

                    currentKey =
                        parameter[1]
                            .trim()
                            .toLowerCase();

                    data[currentKey] =
                        decodeTemplateValue(
                            parameter[2]
                                .trim()
                        );

                    return;

                }

                if (
                    currentKey &&
                    line.trim()
                ) {

                    data[currentKey] +=
                        '\n' +
                        line.trim();

                }

            });

        return data;

    }


    function decodeTemplateValue(value) {

        return String(
            value || ''
        )
            .replace(
                /&#124;/g,
                '|'
            )
            .replace(
                /&#123;&#123;/g,
                '{{'
            )
            .replace(
                /&#125;&#125;/g,
                '}}'
            )
            .replace(
                /}&#125;/g,
                '}}'
            );

    }


    function getNameFromPage(page) {

        return String(
            page || ''
        )
            .replace(
                /^[^:]+:\s*/,
                ''
            )
            .trim();

    }


    function getWikiImageUrl(filename) {

        filename =
            String(
                filename || ''
            )
                .replace(
                    /^File:/i,
                    ''
                )
                .trim();

        return mw.util.getUrl(
            'Special:Redirect/file/' +
            filename
        );

    }


    function sortByName(a, b) {

        return String(
            a.name || ''
        ).localeCompare(
            String(
                b.name || ''
            ),
            undefined,
            {
                sensitivity:
                    'base'
            }
        );

    }


    function createMessage(text) {

        var message =
            document.createElement(
                'div'
            );

        message.className =
            'fish-stats-message';

        message.textContent =
            text;

        return message;

    }


    function createNumberCell(value) {

        return createTextCell(
            formatNumber(value)
        );

    }


    function createTextCell(value) {

        var cell =
            document.createElement(
                'td'
            );

        cell.textContent =
            value;

        return cell;

    }


    function formatPercent(value) {

        return formatNumber(value) + '%';

    }


    function formatNumber(value) {

        value =
            Number(value);

        if (
            !Number.isFinite(value)
        ) {
            return '0';
        }

        return value.toLocaleString(
            undefined,
            {
                maximumFractionDigits:
                    2
            }
        );

    }

}());

#fish-statistics-app {
    width: 100%;
    box-sizing: border-box;
    color: #ffffff;
    font-family: inherit;
}

.fish-stats-shell {
    display: flex;
    flex-direction: column;
    gap: 18px;
}

.fish-stats-title {
    font-size: 30px;
    font-weight: 800;
    line-height: 1.1;
}

.fish-stats-subtitle {
    margin-top: -8px;
    color: #8997aa;
    font-size: 14px;
}

.fish-stats-location {
    overflow: hidden;
    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 12px;
}

.fish-stats-location-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 14px;
    padding: 14px 16px;
    background: #101722;
    border-bottom: 2px solid #252c34;
}

.fish-stats-location-heading {
    min-width: 0;
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 19px;
    font-weight: 800;
}

.fish-stats-location-heading img {
    width: 42px;
    height: 42px;
    object-fit: contain;
    flex: 0 0 auto;
}

.fish-stats-average {
    min-width: 150px;
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 2px;
}

.fish-stats-average span {
    color: #8997aa;
    font-size: 11px;
    font-weight: 700;
}

.fish-stats-average strong {
    font-size: 22px;
    line-height: 1;
}

.fish-stats-table-wrap {
    width: 100%;
    overflow-x: auto;
}

.fish-stats-table {
    width: 100%;
    min-width: 650px;
    border-collapse: collapse;
}

.fish-stats-table th,
.fish-stats-table td {
    padding: 10px 12px;
    border-bottom: 1px solid #252c34;
    text-align: right;
    vertical-align: middle;
    white-space: nowrap;
}

.fish-stats-table th {
    background: #080c12;
    color: #8997aa;
    font-size: 11px;
    font-weight: 800;
    text-transform: uppercase;
}

.fish-stats-table th:first-child,
.fish-stats-table td:first-child {
    text-align: left;
}

.fish-stats-table tbody tr:hover {
    background: #101722;
}

.fish-stats-fish-cell {
    display: flex;
    align-items: center;
    gap: 8px;
    font-weight: 700;
}

.fish-stats-fish-cell img {
    width: 34px;
    height: 34px;
    object-fit: contain;
    flex: 0 0 auto;
}

.fish-stats-total-row {
    background: #101722;
    font-weight: 800;
}

.fish-stats-total-row td {
    border-bottom: none;
}

.fish-stats-formula {
    padding: 10px 14px;
    background: #080c12;
    color: #8997aa;
    font-size: 12px;
    font-style: italic;
    border-top: 1px solid #252c34;
}

.fish-stats-loading,
.fish-stats-error,
.fish-stats-message {
    padding: 16px;
    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 10px;
    color: #8997aa;
}

.fish-stats-error {
    color: #ff9b9b;
}

@media (max-width: 760px) {

    .fish-stats-title {
        font-size: 25px;
    }

    .fish-stats-location-header {
        align-items: flex-start;
        flex-direction: column;
    }

    .fish-stats-average {
        min-width: 0;
        align-items: flex-start;
    }

}

