    color: #8997aa;
    font-size: 11px;
    font-weight: 800;
    text-transform: uppercase;
}

.fish-stats-table th:first-child,
.fish-stats-table td:first-child {
    text-align: left;
}

.fish-stats-table tbody tr:hover {
    background: #101722;
}

.fish-stats-fish-cell {
    display: flex;
    align-items: center;
    gap: 8px;
    font-weight: 700;
}

.fish-stats-fish-cell img {
    width: 34px;
    height: 34px;
    object-fit: contain;
    flex: 0 0 auto;
}

.fish-stats-total-row {
    background: #101722;
    font-weight: 800;
}

.fish-stats-total-row td {
    border-bottom: none;
}

.fish-stats-formula {
    padding: 10px 14px;
    background: #080c12;
    color: #8997aa;
    font-size: 12px;
    font-style: italic;
    border-top: 1px solid #252c34;
}

.fish-stats-loading,
.fish-stats-error,
.fish-stats-message {
    padding: 16px;
    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 10px;
    color: #8997aa;
}

.fish-stats-error {
    color: #ff9b9b;
}
.fish-stats-leaderboard {
    overflow: hidden;
    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 12px;
}

.fish-stats-leaderboard-title {
    padding: 14px 16px;
    background: #101722;
    border-bottom: 2px solid #252c34;
    font-size: 18px;
    font-weight: 800;
}

.fish-stats-leaderboard-row {
    display: grid;
    grid-template-columns: 45px 1fr auto;
    align-items: center;
    gap: 10px;
    padding: 11px 16px;
    border-bottom: 1px solid #252c34;
}

.fish-stats-leaderboard-row:last-child {
    border-bottom: none;
}

.fish-stats-leaderboard-row:hover {
    background: #101722;
}

.fish-stats-leaderboard-rank {
    font-size: 18px;
    font-weight: 800;
    text-align: center;
}

.fish-stats-leaderboard-name {
    font-weight: 700;
}

.fish-stats-leaderboard-average {
    color: #8997aa;
    font-weight: 700;
    text-align: right;
}
@media (max-width: 760px) {

    .fish-stats-title {
        font-size: 25px;
    }

    .fish-stats-location-header {
        align-items: flex-start;
        flex-direction: column;
    }

    .fish-stats-average {
        min-width: 0;
        align-items: flex-start;
    }

}

#fish-statistics-app {
    width: 100%;
    box-sizing: border-box;
    color: #ffffff;
    font-family: inherit;
}

.fish-stats-shell {
    display: flex;
    flex-direction: column;
    gap: 18px;
}

.fish-stats-title {
    font-size: 30px;
    font-weight: 800;
    line-height: 1.1;
}

.fish-stats-subtitle {
    margin-top: -8px;
    color: #8997aa;
    font-size: 14px;
}

.fish-stats-location {
    overflow: hidden;
    background: #0b1017;
    border: 2px solid #252c34;
    border-radius: 12px;
}

.fish-stats-location-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 14px;
    padding: 14px 16px;
    background: #101722;
    border-bottom: 2px solid #252c34;
}

.fish-stats-location-heading {
