.fish-stats-modifier-field {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 5px;
}

.fish-stats-modifier-field > span {
    font-size: 13px;
    font-weight: 700;
}

.fish-stats-modifier-field small {
    color: #8997aa;
    font-size: 10px;
}

.fish-stats-modifier-input {
    width: 100%;
    padding: 8px 9px;
    background: #101722;
    border: 2px solid #303a48;
    border-radius: 8px;
    color: #ffffff;
    font-family: inherit;
    box-sizing: border-box;
}

.fish-stats-modifier-input:focus {
