    color: #8997aa;
    font-size: 11px;
}

.fish-stats-total-modifier {
    grid-column: 1 / -1;
    padding-top: 10px;
    border-top: 1px solid #252c34;
    color: #8997aa;
    font-size: 13px;
    font-weight: 700;
}

.fish-stats-bait-select-button {
    width: 100%;
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 7px 9px;
    background: #101722;
    border: 2px solid #303a48;
    border-radius: 8px;
    color: #ffffff;
    font-family: inherit;
    font-size: 13px;
    cursor: pointer;
    box-sizing: border-box;
}

.fish-stats-bait-select-button:hover {
    border-color: #58aaff;
}

.fish-stats-bait-select-image {
    width: 30px;
    height: 30px;
    object-fit: contain;
}

.fish-stats-bait-picker {
    width: 100%;
    max-height: 220px;
    padding: 7px;
    background: #080c12;
    border: 2px solid #303a48;
    border-radius: 8px;
    overflow-y: auto;
    box-sizing: border-box;
}

.fish-stats-bait-picker-grid {
    display: grid;
    grid-template-columns:
        repeat(2, minmax(0, 1fr));
    gap: 6px;
}

.fish-stats-bait-picker-card {
    min-width: 0;
    padding: 7px 4px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;
    background: #101722;
    border: 2px solid #252c34;
    border-radius: 8px;
    color: #ffffff;
    font-family: inherit;
    font-size: 10px;
    font-weight: bold;
    cursor: pointer;
    box-sizing: border-box;
}

.fish-stats-bait-picker-card:hover,
.fish-stats-bait-picker-card.fish-stats-bait-selected {
    background: #17243a;
    border-color: #58aaff;
}

.fish-stats-bait-picker-card img {
    width: 42px;
    height: 42px;
    object-fit: contain;
}

.fish-stats-bait-picker-card span {
    max-width: 100%;
    text-align: center;
    overflow-wrap: break-word;
}

.fish-stats-bait-empty {
    grid-column: 1 / -1;
    padding: 10px;
    color: #8997aa;
    text-align: center;
}

@media (max-width: 760px) {

    .fish-stats-title {
        font-size: 25px;
    }

    .fish-stats-location-header {
        align-items: flex-start;
        flex-direction: column;
    }

    .fish-stats-average {
        min-width: 0;
        align-items: flex-start;
    }

    .fish-stats-modifier-section {
        grid-template-columns: 1fr;
    }
}

