$(function () {

    function disableSectionCollapse() {

        /* ===== Desktop Citizen ===== */

        document
            .querySelectorAll(
                '.citizen-section-toggle'
            )
            .forEach(function (button) {

                if (
                    button.getAttribute(
                        'aria-expanded'
                    ) === 'false'
                ) {
                    button.click();
                }

                button.remove();

            });


        /* ===== MobileFrontend ===== */

        document
            .querySelectorAll(
                'section.collapsible-block'
            )
            .forEach(function (section) {

                section.removeAttribute(
                    'hidden'
                );

            });


        document
            .querySelectorAll(
                '.mf-icon.indicator'
            )
            .forEach(function (arrow) {

                arrow.remove();

            });


        document
            .querySelectorAll(
                '.collapsible-heading'
            )
            .forEach(function (heading) {

                heading.setAttribute(
                    'aria-expanded',
                    'true'
                );

            });

    }


    disableSectionCollapse();


    /* Catch Citizen/MobileFrontend changing it later */
    var observer =
        new MutationObserver(
            function () {

                disableSectionCollapse();

            }
        );

    var content =
        document.getElementById(
            'mw-content-text'
        );

    if (content) {

        observer.observe(
            content,
            {
                childList: true,
                subtree: true,
                attributes: true,
                attributeFilter: [
                    'hidden',
                    'aria-expanded'
                ]
            }
        );

    }

});

