console.log('StoopidArrow.js loaded1');

$(function () {

    var updateScheduled =
        false;

    function disableSectionCollapse() {

        document
            .querySelectorAll(
                '.citizen-section-toggle'
            )
            .forEach(function (button) {

                var controls =
                    button.getAttribute(
                        'aria-controls'
                    );

                if (controls) {

                    var target =
                        document.getElementById(
                            controls
                        );

                    if (
                        target &&
                        target.hasAttribute(
                            'hidden'
                        )
                    ) {

                        target.removeAttribute(
                            'hidden'
                        );

                    }

                }


                button.remove();

            });

        document
            .querySelectorAll(
                'section.collapsible-block'
            )
            .forEach(function (section) {

                if (
                    section.hasAttribute(
                        'hidden'
                    )
                ) {

                    section.removeAttribute(
                        'hidden'
                    );

                }

            });


        document
            .querySelectorAll(
                '.mf-icon.indicator'
            )
            .forEach(function (arrow) {

                arrow.remove();

            });


        document
            .querySelectorAll(
                '.collapsible-heading'
            )
            .forEach(function (heading) {

                if (
                    heading.getAttribute(
                        'aria-expanded'
                    ) !== 'true'
                ) {

                    heading.setAttribute(
                        'aria-expanded',
                        'true'
                    );

                }

            });

    }


    function scheduleUpdate() {

        if (
            updateScheduled
        ) {
            return;
        }

        updateScheduled =
            true;

        requestAnimationFrame(
            function () {

                updateScheduled =
                    false;

                disableSectionCollapse();

            }
        );

    }

    disableSectionCollapse();

    document.addEventListener(
        'click',
        function (event) {

            var toggle =
                event.target.closest(
                    '.citizen-section-toggle, ' +
                    '.mf-icon.indicator'
                );

            if (!toggle) {
                return;
            }

            event.preventDefault();
            event.stopImmediatePropagation();

        },
        true
    );

    var content =
        document.getElementById(
            'mw-content-text'
        );

    if (content) {

        var observer =
            new MutationObserver(
                function (mutations) {

                    var hasNewContent =
                        mutations.some(
                            function (mutation) {

                                return (
                                    mutation.addedNodes &&
                                    mutation.addedNodes.length > 0
                                );

                            }
                        );

                    if (
                        hasNewContent
                    ) {

                        scheduleUpdate();

                    }

                }
            );

        observer.observe(
            content,
            {
                childList: true,
                subtree: true
            }
        );

    }

    setTimeout(
        disableSectionCollapse,
        250
    );

    setTimeout(
        disableSectionCollapse,
        1000
    );

});

console.log('StoopidArrow.js loaded2');

$(function () {

    var updateScheduled = false;

    function disableSectionCollapse() {

        document
            .querySelectorAll(
                '.citizen-section-toggle'
            )
            .forEach(function (button) {

                var controls =
                    button.getAttribute(
                        'aria-controls'
                    );

                if (controls) {

                    var target =
                        document.getElementById(
                            controls
                        );

                    if (
                        target &&
                        target.hasAttribute('hidden')
                    ) {
                        target.removeAttribute('hidden');
                    }

                }

                button.remove();

            });


        document
            .querySelectorAll(
                'section.collapsible-block'
            )
            .forEach(function (section) {

                if (
                    section.hasAttribute('hidden')
                ) {
                    section.removeAttribute('hidden');
                }

            });

        document
            .querySelectorAll(
                '.mf-icon.indicator'
            )
            .forEach(function (arrow) {

                arrow.remove();

            });

        document
            .querySelectorAll(
                '.collapsible-heading'
            )
            .forEach(function (heading) {

                if (
                    heading.getAttribute(
                        'aria-expanded'
                    ) !== 'true'
                ) {
                    heading.setAttribute(
                        'aria-expanded',
                        'true'
                    );
                }

            });

    }

    function scheduleUpdate() {

        if (updateScheduled) {
            return;
        }

        updateScheduled = true;

        requestAnimationFrame(
            function () {

                updateScheduled = false;
                disableSectionCollapse();

            }
        );

    }

    disableSectionCollapse();

    document.addEventListener(
        'click',
        function (event) {

            var heading =
                event.target.closest(
                    '.collapsible-heading'
                );

            var toggle =
                event.target.closest(
                    '.citizen-section-toggle, ' +
                    '.mf-icon.indicator'
                );

            if (
                !heading &&
                !toggle
            ) {
                return;
            }

            if (
                event.target.closest('a')
            ) {
                return;
            }

            event.preventDefault();
            event.stopPropagation();
            event.stopImmediatePropagation();

            scheduleUpdate();

        },
        true
    );

    var content =
        document.getElementById(
            'mw-content-text'
        );

    if (content) {

        var observer =
            new MutationObserver(
                function (mutations) {

                    var hasNewContent =
                        mutations.some(
                            function (mutation) {

                                return (
                                    mutation.addedNodes &&
                                    mutation.addedNodes.length > 0
                                );

                            }
                        );

                    if (hasNewContent) {
                        scheduleUpdate();
                    }

                }
            );

        observer.observe(
            content,
            {
                childList: true,
                subtree: true
            }
        );

    }

    setTimeout(
        disableSectionCollapse,
        250
    );

    setTimeout(
        disableSectionCollapse,
        1000
    );

});

#fish-upgrades {
    width: 100%;
