(function () {

    var CATEGORY =
        'Category:Fish Upgrade';

    var CONTAINER_ID =
        'fish-upgrades';


    $(function () {

        var container =
            document.getElementById(
                CONTAINER_ID
            );

        if (
            !container ||
            container.dataset.loaded ===
            'true'
        ) {
            return;
        }

        container.dataset.loaded =
            'true';

        container.innerHTML =
            '<div class="fish-upgrades-loading">Loading upgrades...</div>';


        mw.loader.using([
            'mediawiki.api',
            'mediawiki.util'
        ])
            .then(function () {

                var api =
                    new mw.Api();

                return getAllCategoryMembers(
                    api,
                    CATEGORY
                )
                    .then(function (titles) {

                        if (
                            !titles.length
                        ) {
                            return [];
                        }

                        return getPagesContents(
                            api,
                            titles
                        );

                    });

            })
            .then(function (pages) {

                var upgrades = [];

                pages.forEach(function (page) {

                    var data =
                        parseEntryData(
                            page.text
                        );

                    if (
                        !data ||
                        String(
                            data.type || ''
                        ).toLowerCase() !==
                        'fish upgrade'
                    ) {
                        return;
                    }

                    if (
                        data.status &&
                        String(
                            data.status
                        ).toLowerCase() !==
                        'published'
                    ) {
                        return;
                    }


                    var maxLevel =
                        Number(
                            data.max_level
                        );

                    if (
                        !Number.isInteger(
                            maxLevel
                        ) ||
                        maxLevel < 1
                    ) {
                        maxLevel = 1;
                    }


                    var order =
                        Number(
                            data.order
                        );

                    if (
                        !Number.isFinite(
                            order
                        )
                    ) {
                        order = 999999;
                    }


                    var effect =
                        Number(
                            data.effect
                        );

                    if (
                        !Number.isFinite(
                            effect
                        )
                    ) {
                        effect = null;
                    }


                    upgrades.push({

                        name:
                            data.name ||
                            getNameFromTitle(
                                page.title
                            ),

                        image:
                            data.image ||
                            '',

                        description:
                            data.description ||
                            '',

                        effect:
                            effect,

                        maxLevel:
                            maxLevel,

                        order:
                            order

                    });

                });


                upgrades.sort(function (
                    a,
                    b
                ) {

                    if (
                        a.order !==
                        b.order
                    ) {

                        return (
                            a.order -
                            b.order
                        );

                    }

                    return String(
                        a.name || ''
                    ).localeCompare(
                        String(
                            b.name || ''
                        ),
                        undefined,
                        {
                            sensitivity:
                                'base'
                        }
                    );

                });


                renderUpgrades(
                    container,
                    upgrades
                );

            })
            .catch(function (error) {

                console.error(
                    'Fish Upgrades Error:',
                    error
                );

                container.innerHTML =
                    '<div class="fish-upgrades-error">Could not load Fish Upgrades.</div>';

            });

    });


    /* =========================
       RENDER WINDOW
       ========================= */

    function renderUpgrades(
        container,
        upgrades
    ) {

        container.innerHTML =
            '';


        var windowElement =
            document.createElement(
                'div'
            );

        windowElement.className =
            'fish-upgrades-window';


        /* HEADER */

        var header =
            document.createElement(
                'div'
            );

        header.className =
            'fish-upgrades-header';


        var headerIcon =
            document.createElement(
                'span'
            );

        headerIcon.className =
            'fish-upgrades-header-icon';

        headerIcon.textContent =
            '⬆';


        var headerTitle =
            document.createElement(
                'span'
            );

        headerTitle.className =
            'fish-upgrades-header-title';

        headerTitle.textContent =
            'UPGRADES';


        header.appendChild(
            headerIcon
        );

        header.appendChild(
            headerTitle
        );

        windowElement.appendChild(
            header
        );


        /* LIST */

        var list =
            document.createElement(
                'div'
            );

        list.className =
            'fish-upgrades-list';


        if (
            !upgrades.length
        ) {

            var empty =
                document.createElement(
                    'div'
                );

            empty.className =
                'fish-upgrades-empty';

            empty.textContent =
                'No Fish Upgrades have been added yet.';

            list.appendChild(
                empty
            );

        } else {

            upgrades.forEach(function (
                upgrade
            ) {

                list.appendChild(
                    createUpgradeEntry(
                        upgrade
                    )
                );

            });

        }


        windowElement.appendChild(
            list
        );

        container.appendChild(
            windowElement
        );

    }


    /* =========================
       CREATE ONE UPGRADE
       ========================= */

    function createUpgradeEntry(
        upgrade
    ) {

        var entry =
            document.createElement(
                'div'
            );

        entry.className =
            'fish-upgrade-entry is-maxed';


        /* IMAGE */

        var imageBox =
            document.createElement(
                'div'
            );

        imageBox.className =
            'fish-upgrade-image-box';


        if (
            upgrade.image
        ) {

            var image =
                document.createElement(
                    'img'
                );

            image.className =
                'fish-upgrade-image';

            image.alt =
                upgrade.name;

            image.src =
                mw.util.getUrl(
                    'Special:Redirect/file/' +
                    normalizeImageName(
                        upgrade.image
                    )
                );

            imageBox.appendChild(
                image
            );

        }


        /* INFO */

        var info =
            document.createElement(
                'div'
            );

        info.className =
            'fish-upgrade-info';


        var top =
            document.createElement(
                'div'
            );

        top.className =
            'fish-upgrade-top';


        var name =
            document.createElement(
                'div'
            );

        name.className =
            'fish-upgrade-name';

        name.textContent =
            upgrade.name;


        var level =
            document.createElement(
                'div'
            );

        level.className =
            'fish-upgrade-level';

        level.textContent =
            'LEVEL ' +
            upgrade.maxLevel;


        top.appendChild(
            name
        );

        top.appendChild(
            level
        );

        info.appendChild(
            top
        );


        /* LEVEL BAR */

        var levelBar =
            document.createElement(
                'div'
            );

        levelBar.className =
            'fish-upgrade-level-bar';


        var segmentCount =
            Math.min(
                upgrade.maxLevel,
                50
            );


        for (
            var i = 0;
            i < segmentCount;
            i++
        ) {

            var segment =
                document.createElement(
                    'span'
                );

            segment.className =
                'fish-upgrade-level-segment is-filled';

            levelBar.appendChild(
                segment
            );

        }


        info.appendChild(
            levelBar
        );


        /* DESCRIPTION */

        var description =
            document.createElement(
                'div'
            );

        description.className =
            'fish-upgrade-description';


        var processedDescription =
            applyEffectText(
                upgrade.description,
                upgrade
            );


        renderDescription(
            description,
            processedDescription
        );


        info.appendChild(
            description
        );


        entry.appendChild(
            imageBox
        );

        entry.appendChild(
            info
        );


        return entry;

    }


    /* =========================
       EFFECT TEXT
       ========================= */

    function applyEffectText(
        text,
        upgrade
    ) {

        var effectText =
            upgrade.effect ===
            null
                ? ''
                : formatNumber(
                    upgrade.effect
                );


        var totalEffectText =
            upgrade.effect ===
            null
                ? ''
                : formatNumber(
                    upgrade.effect *
                    upgrade.maxLevel
                );


        return String(
            text || ''
        )
            .replace(
                /\[effectxlevel\]/gi,
                totalEffectText
            )
            .replace(
                /\[effect\]/gi,
                effectText
            );

    }


    /* =========================
       FORMULA / BLUE TEXT
       ========================= */

    function renderDescription(
        container,
        text
    ) {

        var tokenRegex =
            /\[(formula|blue)\]([\s\S]*?)\[\/\1\]/gi;

        var lastIndex =
            0;

        var match;


        while (
            (
                match =
                    tokenRegex.exec(
                        text
                    )
            ) !==
            null
        ) {

            appendPlainText(
                container,
                text.slice(
                    lastIndex,
                    match.index
                )
            );


            var span =
                document.createElement(
                    'span'
                );


            if (
                match[1]
                    .toLowerCase() ===
                'formula'
            ) {

                span.className =
                    'fish-upgrade-formula';

            } else {

                span.className =
                    'fish-upgrade-blue';

            }


            span.textContent =
                match[2];


            container.appendChild(
                span
            );


            lastIndex =
                tokenRegex.lastIndex;

        }


        appendPlainText(
            container,
            text.slice(
                lastIndex
            )
        );

    }


    function appendPlainText(
        container,
        text
    ) {

        var parts =
            String(
                text || ''
            ).split(
                /\r?\n/
            );


        parts.forEach(function (
            part,
            index
        ) {

            if (
                index > 0
            ) {

                container.appendChild(
                    document.createElement(
                        'br'
                    )
                );

            }

            if (
                part
            ) {

                container.appendChild(
                    document.createTextNode(
                        part
                    )
                );

            }

        });

    }


    /* =========================
       NUMBER FORMAT
       ========================= */

    function formatNumber(
        value
    ) {

        if (
            !Number.isFinite(
                value
            )
        ) {
            return '';
        }


        var rounded =
            Math.round(
                value *
                1000000000
            ) /
            1000000000;


        return String(
            rounded
        );

    }


    /* =========================
       IMAGE
       ========================= */

    function normalizeImageName(
        value
    ) {

        return String(
            value || ''
        )
            .replace(
                /^File:/i,
                ''
            )
            .trim();

    }


    /* =========================
       PAGE NAME
       ========================= */

    function getNameFromTitle(
        title
    ) {

        return String(
            title || ''
        )
            .replace(
                /^Fish upgrade page:/i,
                ''
            )
            .trim();

    }


    /* =========================
       CATEGORY LOADER
       ========================= */

    function getAllCategoryMembers(
        api,
        category,
        cmcontinue
    ) {

        var params = {

            action:
                'query',

            list:
                'categorymembers',

            cmtitle:
                category,

            cmlimit:
                'max',

            cmtype:
                'page',

            format:
                'json',

            formatversion:
                2

        };


        if (
            cmcontinue
        ) {

            params.cmcontinue =
                cmcontinue;

        }


        return api.get(
            params
        )
            .then(function (
                response
            ) {

                var titles = [];


                if (
                    response.query &&
                    response.query.categorymembers
                ) {

                    titles =
                        response.query
                            .categorymembers
                            .map(function (
                                page
                            ) {

                                return page.title;

                            });

                }


                if (
                    response.continue &&
                    response.continue.cmcontinue
                ) {

                    return getAllCategoryMembers(
                        api,
                        category,
                        response.continue.cmcontinue
                    )
                        .then(function (
                            more
                        ) {

                            return titles.concat(
                                more
                            );

                        });

                }


                return titles;

            });

    }


    /* =========================
       PAGE CONTENT LOADER
       ========================= */

    function getPagesContents(
        api,
        titles
    ) {

        var chunks = [];


        for (
            var i = 0;
            i < titles.length;
            i += 50
        ) {

            chunks.push(
                titles.slice(
                    i,
                    i + 50
                )
            );

        }


        return Promise.all(
            chunks.map(function (
                chunk
            ) {

                return api.get({

                    action:
                        'query',

                    prop:
                        'revisions',

                    titles:
                        chunk.join('|'),

                    rvprop:
                        'content',

                    rvslots:
                        'main',

                    redirects:
                        1,

                    format:
                        'json',

                    formatversion:
                        2

                });

            })
        )
            .then(function (
                responses
            ) {

                var pages =
                    [];


                responses.forEach(function (
                    response
                ) {

                    if (
                        !response.query ||
                        !response.query.pages
                    ) {
                        return;
                    }


                    response.query.pages
                        .forEach(function (
                            page
                        ) {

                            if (
                                page.missing ||
                                !page.revisions ||
                                !page.revisions.length
                            ) {
                                return;
                            }


                            var revision =
                                page.revisions[0];

                            var text =
                                '';


                            if (
                                revision.slots &&
                                revision.slots.main
                            ) {

                                text =
                                    revision
                                        .slots
                                        .main
                                        .content ||
                                    revision
                                        .slots
                                        .main['*'] ||
                                    '';

                            } else {

                                text =
                                    revision.content ||
                                    revision['*'] ||
                                    '';

                            }


                            pages.push({

                                title:
                                    page.title,

                                text:
                                    text

                            });

                        });

                });


                return pages;

            });

    }


    /* =========================
       ENTRYDATA PARSER
       ========================= */

    function parseEntryData(
        text
    ) {

        var match =
            String(
                text || ''
            ).match(
                /\{\{\s*EntryData\b([\s\S]*?)\n?\}\}/i
            );


        if (
            !match
        ) {
            return null;
        }


        var data =
            {};

        var currentKey =
            null;


        match[1]
            .split(
                /\r?\n/
            )
            .forEach(function (
                line
            ) {

                var parameter =
                    line.match(
                        /^\s*\|\s*([^=]+?)\s*=\s*(.*)$/
                    );


                if (
                    parameter
                ) {

                    currentKey =
                        parameter[1]
                            .trim()
                            .toLowerCase();


                    data[
                        currentKey
                    ] =
                        decodeTemplateValue(
                            parameter[2]
                                .trim()
                        );


                    return;

                }


                if (
                    currentKey &&
                    line.trim()
                ) {

                    data[
                        currentKey
                    ] +=
                        '\n' +
                        line.trim();

                }

            });


        return data;

    }


    function decodeTemplateValue(
        value
    ) {

        return String(
            value || ''
        )
            .replace(
                /&#124;/g,
                '|'
            )
            .replace(
                /&#123;&#123;/g,
                '{{'
            )
            .replace(
                /&#125;&#125;/g,
                '}}'
            )
            .replace(
                /\}&#125;/g,
                '}}'
            );

    }

})();

(function () {

    var CATEGORY =
        'Category:Fish Upgrade';

    var CONTAINER_ID =
        'fish-upgrades';


    $(function () {

        var container =
            document.getElementById(
                CONTAINER_ID
            );

        if (
            !container ||
            container.dataset.loaded ===
            'true'
        ) {
            return;
        }

        container.dataset.loaded =
            'true';

        container.innerHTML =
            '<div class="fish-upgrades-loading">Loading upgrades...</div>';


        mw.loader.using([
            'mediawiki.api',
            'mediawiki.util'
        ])
            .then(function () {

                var api =
                    new mw.Api();

                return getAllCategoryMembers(
                    api,
                    CATEGORY
                )
                    .then(function (titles) {

                        if (
                            !titles.length
                        ) {
                            return [];
                        }

                        return getPagesContents(
                            api,
                            titles
                        );

                    });

            })
            .then(function (pages) {

                var upgrades = [];

                pages.forEach(function (page) {

                    var data =
                        parseEntryData(
                            page.text
                        );

                    if (
                        !data ||
                        String(
                            data.type || ''
                        ).toLowerCase() !==
                        'fish upgrade'
                    ) {
                        return;
                    }

                    if (
                        data.status &&
                        String(
                            data.status
                        ).toLowerCase() !==
                        'published'
                    ) {
                        return;
                    }


                    var maxLevel =
                        Number(
                            data.max_level
                        );

                    if (
                        !Number.isInteger(
                            maxLevel
                        ) ||
                        maxLevel < 1
                    ) {
                        maxLevel = 1;
                    }


                    var order =
                        Number(
                            data.order
                        );

                    if (
                        !Number.isFinite(
                            order
                        )
                    ) {
                        order = 999999;
                    }


                    var effect =
                        Number(
                            data.effect
                        );

                    if (
                        !Number.isFinite(
                            effect
                        )
                    ) {
                        effect = null;
                    }


                    upgrades.push({

                        name:
                            data.name ||
                            getNameFromTitle(
                                page.title
                            ),

                        image:
                            data.image ||
                            '',

                        description:
                            data.description ||
                            '',

                        effect:
                            effect,

                        maxLevel:
                            maxLevel,

                        order:
                            order

                    });

                });


                upgrades.sort(function (
                    a,
                    b
                ) {

                    if (
                        a.order !==
                        b.order
                    ) {

                        return (
                            a.order -
                            b.order
                        );

                    }

                    return String(
                        a.name || ''
                    ).localeCompare(
                        String(
                            b.name || ''
                        ),
                        undefined,
                        {
                            sensitivity:
                                'base'
                        }
                    );

                });


                renderUpgrades(
                    container,
                    upgrades
                );

            })
            .catch(function (error) {

                console.error(
                    'Fish Upgrades Error:',
                    error
                );

                container.innerHTML =
                    '<div class="fish-upgrades-error">Could not load Fish Upgrades.</div>';

            });

    });


    /* =========================
       RENDER WINDOW
       ========================= */

    function renderUpgrades(
