    /* =========================
       EFFECT TEXT
       ========================= */

    function applyEffectText(
        text,
        upgrade
    ) {

        var effectText =
            upgrade.effect ===
            null
                ? ''
                : formatNumber(
                    upgrade.effect
                );


        var totalEffectText =
            upgrade.effect ===
            null
                ? ''
                : formatNumber(
                    upgrade.effect *
                    upgrade.maxLevel
                );


        return String(
            text || ''
        )
            .replace(
