       ========================= */

    function renderDescription(
        container,
        text
    ) {

        var tokenRegex =
            /\[(formula|blue)\]([\s\S]*?)\[\/\1\]/gi;

        var lastIndex =
            0;

        var match;


        while (
            (
                match =
                    tokenRegex.exec(
                        text
                    )
            ) !==
            null
        ) {

            appendPlainText(
                container,
                text.slice(
                    lastIndex,
                    match.index
                )
            );


