$(function () {

    var isMainPage =
        mw.config.get('wgIsMainPage');

    var pageName =
        mw.config.get('wgPageName');

    var pageTitle =
        mw.config.get('wgTitle');

    var action =
        mw.config.get('wgAction');

    if (
        !isMainPage &&
        action === 'view' &&
        pageName &&
        pageName.indexOf('Special:') !== 0
    ) {

        try {

            localStorage.setItem(
                'upgradex-last-page',
                JSON.stringify({
                    title: pageTitle || pageName,
                    url: mw.util.getUrl(pageName)
                })
            );

        } catch (error) {

            console.warn(
                'Could not remember the last page.',
                error
            );

        }

        return;
    }

    if (!isMainPage) {
        return;
    }


    var overlay =
        document.getElementById(
            'main-page-return-overlay'
        );

    var returnButton =
        document.getElementById(
            'main-page-return-button'
        );

    var noThanksButton =
        document.getElementById(
            'main-page-return-no'
        );


    if (
        !overlay ||
        !returnButton ||
        !noThanksButton
    ) {
        return;
    }


    function closeReturnPopup() {

        overlay.classList.remove(
            'is-visible'
        );

    }


    try {

        var savedPage =
            JSON.parse(
                localStorage.getItem(
                    'upgradex-last-page'
                )
            );

        if (
            !savedPage ||
            !savedPage.url
        ) {
            return;
        }

        returnButton.href =
            savedPage.url;

        returnButton.title =
            'Return to ' + savedPage.title;

        overlay.classList.add(
            'is-visible'
        );

    } catch (error) {

        console.warn(
            'Could not load the last page.',
            error
        );

        return;
    }

    overlay.addEventListener(
        'click',
        function (event) {

            if (event.target === overlay) {
                closeReturnPopup();
            }

        }
    );

    noThanksButton.addEventListener(
        'click',
        closeReturnPopup
    );

    document.addEventListener(
        'keydown',
        function (event) {

            if (event.key === 'Escape') {
                closeReturnPopup();
            }

        }
    );

});

$(function () {

    var pageName =
    	mw.config.get('wgPageName');

	var isMainPage =
    	pageName === 'Main_Page';

    var pageTitle =
        mw.config.get('wgTitle');

    var action =
        mw.config.get('wgAction');

    if (
        !isMainPage &&
        action === 'view' &&
        pageName &&
        pageName.indexOf('Special:') !== 0
    ) {

        try {

            localStorage.setItem(
                'upgradex-last-page',
                JSON.stringify({
                    title: pageTitle || pageName,
                    url: mw.util.getUrl(pageName)
                })
            );

        } catch (error) {

            console.warn(
                'Could not remember the last page.',
                error
            );

        }

        return;
    }

    if (!isMainPage) {
        return;
    }


    var overlay =
        document.getElementById(
            'main-page-return-overlay'
        );

    var returnButton =
        document.getElementById(
            'main-page-return-button'
        );

    var noThanksButton =
        document.getElementById(
            'main-page-return-no'
        );


    if (
        !overlay ||
        !returnButton ||
        !noThanksButton
    ) {
        return;
    }


    function closeReturnPopup() {

        overlay.classList.remove(
            'is-visible'
        );

    }


    try {

        var savedPage =
            JSON.parse(
                localStorage.getItem(
                    'upgradex-last-page'
                )
            );

        if (
            !savedPage ||
            !savedPage.url
        ) {
            return;
        }

        returnButton.href =
            savedPage.url;

        returnButton.title =
            'Return to ' + savedPage.title;

        overlay.classList.add(
            'is-visible'
        );

    } catch (error) {

        console.warn(
            'Could not load the last page.',
            error
        );

        return;
    }

    overlay.addEventListener(
        'click',
        function (event) {

            if (event.target === overlay) {
                closeReturnPopup();
            }

        }
    );

    noThanksButton.addEventListener(
        'click',
        closeReturnPopup
    );

    document.addEventListener(
        'keydown',
        function (event) {

            if (event.key === 'Escape') {
                closeReturnPopup();
            }

        }
    );

});

