            if (event.key === 'Escape') {
                closeReturnPopup();
            }

        }
    );

});

$(function () {

    var pageName =
        mw.config.get('wgPageName');

    var pageTitle =
        mw.config.get('wgTitle');

    var action =
        mw.config.get('wgAction');

    var isMainPage =
        pageName === 'Main_Page' ||
        mw.config.get('wgIsMainPage') === true ||
        document.body.classList.contains('mw-mainpage');

    if (
        !isMainPage &&
        action === 'view' &&
        pageName &&
        pageName.indexOf('Special:') !== 0
    ) {

        try {

            localStorage.setItem(
                'upgradex-last-page',
                JSON.stringify({
                    title: pageTitle || pageName,
                    url: mw.util.getUrl(pageName)
                })
            );

        } catch (error) {

            console.warn(
                'Could not remember the last page.',
                error
            );

        }

        return;
    }

    if (!isMainPage) {
        return;
    }

    var overlay =
        document.getElementById(
            'main-page-return-overlay'
        );

    var returnButton =
        document.getElementById(
            'main-page-return-button'
        );

    var noThanksButton =
        document.getElementById(
            'main-page-return-no'
        );

    var pageNameDisplay =
        document.getElementById(
            'main-page-return-name'
        );

    if (
        !overlay ||
        !returnButton ||
        !noThanksButton ||
        !pageNameDisplay
    ) {

        console.warn(
            'Main page return popup elements were not found.'
        );

        return;
    }

    var savedPage;

    try {

        savedPage =
            JSON.parse(
                localStorage.getItem(
                    'upgradex-last-page'
                )
            );

    } catch (error) {

        console.warn(
            'Could not load the last page.',
            error
        );

        return;
    }

    if (
        !savedPage ||
        !savedPage.url
    ) {
        return;
    }

    function closeReturnPopup() {

        overlay.classList.remove(
            'is-visible'
        );

    }

    function returnToSavedPage() {

        window.location.href =
            savedPage.url;

    }

    function activateWithKeyboard(
        event,
        actionFunction
    ) {

        if (
            event.key === 'Enter' ||
            event.key === ' '
        ) {

            event.preventDefault();
            actionFunction();

        }

    }

    pageNameDisplay.textContent =
        savedPage.title;

    returnButton.title =
        'Return to ' + savedPage.title;

    overlay.classList.add(
        'is-visible'
    );

    returnButton.addEventListener(
        'click',
        returnToSavedPage
    );

    returnButton.addEventListener(
        'keydown',
        function (event) {

            activateWithKeyboard(
                event,
                returnToSavedPage
            );

        }
    );

    noThanksButton.addEventListener(
        'click',
        closeReturnPopup
    );

    noThanksButton.addEventListener(
        'keydown',
        function (event) {

            activateWithKeyboard(
                event,
                closeReturnPopup
            );

        }
    );

    overlay.addEventListener(
        'click',
        function (event) {

            if (event.target === overlay) {
                closeReturnPopup();
            }

        }
    );

    document.addEventListener(
        'keydown',
        function (event) {

            if (event.key === 'Escape') {
                closeReturnPopup();
            }

        }
    );

});

.container {
	background: #00000060;
	border: 3px solid #252525;
	border-radius:15px;
}

.image {
    transition: opacity 0.1s ease, width 0.2s ease, height 0.2s ease;
	padding: 5px;
}

.image:hover{
	width: 170px;
	height: 170px;
	opacity: 0.9;
}

.link-btn-container {
    transition: opacity 0.1s ease, width 0.3s ease;
    color: white;
	padding: 1em;
	display: flex;
	flex-direction: column;
	justify-content: flex-end;
	align-items: center;
	background: #00000060;
	border: 3px solid #252525;
	border-radius:15px;

}

.links-container:hover .link-btn-container:not(:hover) {
  opacity: 0.7;
}

.links-btn-container:hover{
  width: 33%;
}

.link-btn-logo {
    background-position: center;
    background-repeat: no-repeat;
    background-size: contain;
	width: 85%;
	height: 85%;
}

.guide-logo {
	background-image: url("-14.png")
}

